// ---------------------------------------------------------------------------
// Construction
// ---------------------------------------------------------------------------

static bool isStableStringRef(ASTNode* n);   // defined below; used by string-index materialization
static bool isConstInitExpr(ExpressionNode* e);   // defined below; used by the `comptime` local-decl check

CEmitter::CEmitter(std::ostream& out, const std::string& sourcePath, bool emitLineDirectives)
    : _out(&out)
    , _sourcePath(sourcePath)
    , _lines(emitLineDirectives)
    , _unsupported(0)
{
}

// Analysis-mode construction: no real output stream. `_out` points at an internal throwaway sink so the
// handful of defensive `*_out <<` sites (chiefly `unsupported()`) stay valid while `collectProgram` runs.
// collectProgram itself emits no C, so the sink stays empty in the well-formed case.
CEmitter::CEmitter(const std::string& sourcePath)
    : _out(&_analysisSink)
    , _sourcePath(sourcePath)
    , _lines(false)
    , _unsupported(0)
{
    _analysis = true;   // record body use-sites for the reference index (a `kama build` records none)
}

// Run the FULL front-end pipeline (name resolution, type checking, generic/collection instantiation,
// ownership + serialization fixpoints, contract/export/import validation, AND the per-body walk) over
// `units` into a throwaway sink — so no C is written anywhere, yet EVERY diagnostic is captured and the
// query tables are fully populated. The body walk matters: many diagnostics (use-after-move, raw-pointer-
// outside-`unsafe`, type/escape errors) are only detected while emitting a function body, not during
// collectProgram — so a collectProgram-only pass would silently miss them. Reuses the exact emit path a
// build runs (so `analyze()` diagnostics == `kama build` diagnostics), just aimed at discarded streams.
// Returns the number of nodes the pipeline could not handle (0 == fully understood).
int CEmitter::analyze(const std::vector<SharedCompilationUnit>& units)
{
    if (units.empty()) return _unsupported;
    _units = units;                      // retain for the query facade (URI->unit, outline ownership filter)
    if (units.size() == 1) {
        emit(units[0]);                  // writes to `_analysisSink` (the analysis-mode `_out`)
    } else {
        // Multi-file: the same shared-header + per-module emission a build uses, but every stream is the
        // one throwaway sink.
        //
        // Each unit gets ITS OWN path. `_sourcePath` for every unit is what a discarded `#line` does not
        // care about — and what a DIAGNOSTIC does: `diagFile()` reads the same field, so handing the entry
        // file's path to every module reported every imported module's body against the file being
        // checked. Line right, file wrong, which is `check-diag-file.sh`'s whole subject; it guarded the
        // collect path, where `_collectingUnitPath` already wins, and this is the emit path underneath it.
        // Measured on the corpus before the fix: 1,174 of 1,848 `--strict-numeric` rows named a line past
        // the end of the file they named. `u->name` is the same spelling `collectProgram` scopes
        // `_collectingUnitPath` from, so the two paths now agree by construction rather than by accident.
        std::ostringstream sink;
        std::vector<std::ostream*> moduleStreams(units.size(), &sink);
        std::vector<std::string>   paths;
        paths.reserve(units.size());
        for (auto& u : units) paths.push_back(u && u->name ? *u->name : _sourcePath);
        emitProgram(units, "<analysis>.h", sink, moduleStreams, paths);
        _out = &_analysisSink;           // restore (emitProgram left `_out` at the now-dying local sink)
    }
    // Tables are stable after the analysis walk — build the read-only query index over them (T4/T5).
    buildDefSites();
    buildPositions();
    return _unsupported;
}

void CEmitter::indent(int depth)
{
    for (int i = 0; i < depth; ++i) *_out << "    ";
}

void EmitCapture::put(char c)
{
    _copy.push_back(c);
    if (_keepLines) { _dst.sputc(c); return; }
    static const char kDirective[] = "#line ";
    if (_dropping) {
        if (c == '\n') { _dropping = false; _atLineStart = true; }
        return;
    }
    if (_held > 0 || (_atLineStart && c == '#')) {
        if (c == kDirective[_held]) {
            if (++_held == 6) { _held = 0; _dropping = true; }
            return;
        }
        flushHeld();   // not a directive after all — release what was held, then this char
    }
    _dst.sputc(c);
    _atLineStart = (c == '\n');
}

void EmitCapture::flushHeld()
{
    if (_held > 0) { _dst.sputn("#line ", _held); _held = 0; _atLineStart = false; }
}

void CEmitter::line(int srcLine)
{
    if (srcLine > 0) _curLine = srcLine;   // track for conditional-drop diagnostics
    // Written whether or not the build wants `#line` — the call graph reads a call site's line from it, and
    // `--no-line` is honoured by EmitCapture, which drops the directive on its way to the real stream.
    if (srcLine <= 0) return;
    // `diagFile()`, not `_sourcePath` — a `#line` is a DIAGNOSTIC, routed through the C compiler and the
    // debugger instead of through `unsupported()`, and it wants the same answer: the file that owns the
    // code being written. Reading `_sourcePath` gave it "whatever the emitter was constructed with", so
    // the prelude's static-inline bodies — folded into the header, which no module owns — came out stamped
    // with the ENTRY file in a single-unit build and with "" in a multi-file one. A one-line program
    // emitted 391 `#line` directives, 389 of them past its own end, the highest claiming line 633 of a file
    // with one. That is `check-diag-file.sh`'s "line right, file wrong" one layer down, and it decides
    // where clang reports an error and where a debugger stops.
    //
    // ⚠️ AND IT MUST NOT GUESS. `<prelude>` is a synthetic unit name, not a path — the same `<`-sentinel
    // `checkReach` reads for "compiler-owned" — and there is no file on disk to point at. Emitting nothing
    // is the honest answer: the C compiler then attributes to the GENERATED file, which does exist, which
    // `--keep-c` hands the user, and which is where that code actually lives.
    //
    // In the HEADER pass, `_emitDeclFile` alone. Header content belongs to nobody's module: a generic
    // instance carries the template's file there (that is what `_emitDeclFile` is for), and everything
    // else is the prelude, which carries nothing. Falling through to `_sourcePath` is what produced the
    // lie. This is deliberately NARROWER than `diagFile()` and must not be widened to it: `diagFile()` is
    // right for a DIAGNOSTIC, which should still name the user's file when that is the best it knows,
    // whereas a `#line` that names the wrong file silently relocates every error the C compiler reports.
    const std::string& f = _inHeaderPass ? _emitDeclFile : diagFile();
    if (f.empty() || f[0] == '<') return;
    // The path is a C string literal: escape `\` and `"` so a Windows path (`D:\a\…\tests\foo.kama`)
    // isn't read as escape sequences (`\o`/`\x`/… are errors, not just the file name we meant).
    *_out << "#line " << srcLine << " \"";
    for (char c : f) { if (c == '\\' || c == '"') *_out << '\\'; *_out << c; }
    *_out << "\"\n";
}

// Render an INTERNAL mangled name the way the user spelled it. Declarations are scope-prefixed by
// `qualify()` as `<scope>__<name>`, where the scope is a namespace (`std__collections`) or, for a
// file-private type, `_F<file>` — so a diagnostic that interpolates a resolved name leaks
// `_FplainMod__Plain` or `std__collections__Map` at the user. Applied once here, at the single point where a
// message becomes visible, rather than at the ~30 call sites that interpolate a name (and every future one).
//
// Per identifier token: a REGISTERED file-private scope is stripped, then an INTERIOR `__` becomes `::`. A LEADING
// `__` is left alone — the emitter's own reserved identifiers (`__base`, `__vptr`, `__ret_N`, `__match0`;
// SPEC § Reserved/runtime) must render verbatim.
// A monomorphized instance is additionally mangled as `Tmpl_<arg>_<arg>` — rendered back to the source
// `Tmpl<arg, arg>`, with trailing DEFAULTED args dropped so `Map<int32, int32>` doesn't read as
// `Map<int32, int32, DefaultHasher, GlobalAllocator>`. `depth` bounds the recursion through nested args:
// a diagnostic must never be the thing that hangs the compiler.
std::string CEmitter::demangleForDisplay(const std::string& msg, int depth) const
{
    auto identChar = [](char c) { return std::isalnum((unsigned char)c) || c == '_'; };
    std::string out;
    for (size_t i = 0; i < msg.size(); ) {
        if (!identChar(msg[i])) { out += msg[i++]; continue; }
        size_t start = i;
        while (i < msg.size() && identChar(msg[i])) ++i;
        std::string tok = msg.substr(start, i - start);

        // An OPAQUE TYPE PARAMETER renders as the parameter the user wrote. It is checked first because
        // its mangle contains the template key, which the `__` rewriting below would otherwise turn into
        // a namespace path — `DynamicArray<__opq::F4::neverCalled3_T>` for what the source calls
        // `DynamicArray<T>`. The mistake being reported is in the user's generic; the type there is `T`.
        auto od = _opaqueDisplay.find(tok);
        if (od != _opaqueDisplay.end()) { out += od->second; continue; }

        // The one rename `qualify()` makes that is not a scope prefix, undone here for the same reason
        // every other rewriting in this function happens: the reader is being shown a name to go and look
        // for, and `kama_main` is not in their file. It stayed invisible while nothing reported a chain
        // rooted at `main` — which `--no-heap` now routinely does, since `main` is where a program owns
        // the container whose destructor frees.
        if (tok == "kama_main") { out += "main"; continue; }
        // ...and the funnel's two entries into a `@globalAllocator` pool, which a no-heap chain passes through on its
        // way into the pool's body. The reader declared against the contract, so the chain names its member.
        if (tok == "kama__global_allocate")   { out += "GlobalHeap::allocate"; continue; }
        if (tok == "kama__global_deallocate") { out += "GlobalHeap::deallocate"; continue; }

        // A generic INSTANCE renders as its source spelling before any `__` rewriting, since the mangle
        // splices scope-qualified argument names into the same token.
        auto gi = _genericTypeInsts.find(tok);
        if (depth < 4 && gi != _genericTypeInsts.end()) {
            const auto& args = gi->second.typeArgs;
            auto df = _genericTypeDefaults.find(gi->second.templateKey);
            // A template's default is written UNQUALIFIED in the template's own scope (`DefaultHasher`)
            // while the recorded arg is resolved and qualified (`std::collections::DefaultHasher`), so an
            // unqualified default matches on its leaf. A default that IS qualified must match exactly —
            // two same-leaf types in different namespaces are different types, and hiding one would lie.
            auto sameType = [](const std::string& arg, const std::string& dflt) {
                if (arg == dflt) return true;
                if (dflt.find("::") != std::string::npos) return false;
                size_t p = arg.rfind("::");
                return p != std::string::npos && arg.compare(p + 2, std::string::npos, dflt) == 0;
            };
            size_t n = args.size();
            if (df != _genericTypeDefaults.end())                       // drop trailing args left at default
                while (n > 0 && n <= df->second.size() && df->second[n - 1] && args[n - 1]
                       && args[n - 1]->value && df->second[n - 1]->value
                       && sameType(demangleForDisplay(*args[n - 1]->value, depth + 1),
                                   demangleForDisplay(*df->second[n - 1]->value, depth + 1)))
                    --n;
            // ⚠️ A type ARGUMENT may itself be a generic instance, and a type NODE carries its arguments in
            // `genericArgs` rather than in `value` — so rendering `value` alone printed `Shared` for what
            // the source calls `Shared<Leaf>`, and a diagnostic naming `Pair2<Shared<Leaf>>` read
            // `Pair2<std::memory::Shared>`. Render the node, not just its head.
            std::function<std::string(const SharedIdentifier&, int)> renderArg =
                [&](const SharedIdentifier& a, int d) -> std::string {
                    if (!a || !a->value) return "?";
                    std::string r = demangleForDisplay(*a->value, d);
                    if (d < 4 && a->genericArgs && !a->genericArgs->empty()) {
                        r += "<";
                        for (size_t k = 0; k < a->genericArgs->size(); ++k)
                            r += (k ? ", " : "") + renderArg(a->genericArgs->at(k), d + 1);
                        r += ">";
                    }
                    return r;
                };
            std::string s = demangleForDisplay(gi->second.templateKey, depth + 1);
            if (n) {
                s += "<";
                for (size_t a = 0; a < n; ++a) s += (a ? ", " : "") + renderArg(args[a], depth + 1);
                s += ">";
            }
            out += s;
            continue;
        }

        // A FILE-PRIVATE scope names no namespace a user could write, so it is stripped rather than
        // rendered. Since §2e.26 the spelling is derived from the file's name (`_Fmain`) instead of its
        // position (`_F4`), so there is no pattern to match on — the registry the emitter filled while
        // assigning contexts is the only thing that knows. Longest match wins, because a file whose name
        // itself contains `__` mints a scope that does too (`b__c.kama` -> `_Fb__c`).
        // A module file's private scope renders as its MODULE: the file segment is the only part no user
        // can spell (`nhflag___Fapp__grow` -> `nhflag::grow`). Before the loose-file strip below, which
        // would otherwise take the whole prefix and leave a bare name.
        {
            bool fileScoped = false;
            for (const auto& fs : _privateFileScopes)
                if (tok.size() > fs.first.size() + 2 && tok.compare(0, fs.first.size(), fs.first) == 0
                    && tok.compare(fs.first.size(), 2, "__") == 0) {
                    out += demangleForDisplay(fs.second + "__" + tok.substr(fs.first.size() + 2), depth + 1);
                    fileScoped = true; break;
                }
            if (fileScoped) continue;
        }
        const std::string* priv = nullptr;
        for (const auto& s : _privateScopes)
            if (tok.size() > s.size() + 2 && tok.compare(0, s.size(), s) == 0
                && tok.compare(s.size(), 2, "__") == 0 && (!priv || s.size() > priv->size()))
                priv = &s;
        if (priv) { out += demangleForDisplay(tok.substr(priv->size() + 2), depth + 1); continue; }

        // Leading underscores are reserved-identifier territory — measure the token's real start.
        size_t lead = tok.find_first_not_of('_');
        if (lead == std::string::npos) { out += tok; continue; }
        std::string body = tok.substr(lead);
        for (size_t p = body.find("__"); p != std::string::npos; p = body.find("__", p + 2))
            body.replace(p, 2, "::");
        out += tok.substr(0, lead) + body;
    }
    return out;
}

// Which file a diagnostic belongs to. `_sourcePath` is the module currently being WRITTEN, which is right
// during body emission and empty everywhere else in a multi-file build — the driver constructs that emitter
// with no path and the real ones only arrive per module, inside emitProgram's loop. So every diagnostic
// raised by collectProgram (the whole front end) reported an empty file, in stderr AND in the structured
// `Diagnostic.file` an editor places it by. `_collectingUnitPath` is the unit a collect pass is walking;
// a late whole-program check scopes it from the ClassInfo's `declFile`.
//
// `_collectingUnitPath` WINS when it is set, and that ordering is the whole point: it names the unit whose
// declarations are being walked RIGHT NOW, which is strictly more specific than "the module being written".
// It used to lose to a non-empty `_sourcePath`, so a single-file `kama check user.kama` — where
// `_sourcePath` is set from the start — reported every imported module's declaration against `user.kama`.
// The LINE was right and the FILE was wrong, which is the worst shape a diagnostic can take: it points a
// reader (or an editor's go-to) confidently at an innocent line of the wrong file. `ScopedStr` restores the
// previous value at the end of each collect pass, so body emission is unaffected.
//
// `_emitDeclFile` sits between them, for the one body the per-module loop does not own: a GENERIC INSTANCE
// is emitted from the HEADER pass, before any module's path is current, so `_sourcePath` there is whatever
// the emitter was constructed with — the entry file. It names the TEMPLATE's file, which is what owns the
// line. Ordered under `_collectingUnitPath` and over `_sourcePath` for the same reason: most specific wins.
// Set a string member for a dynamic extent and restore it on exit (survives early returns and `continue`).
// Defined here, beside `diagFile()`, because that comment is about it and because `checkDeclaredTypes`
// — far above its old home — needs it to name the unit its diagnostics are about.
namespace { struct ScopedStr { std::string& s; std::string prev;
    ScopedStr(std::string& s_, const std::string& v) : s(s_), prev(s_) { s = v; }
    ~ScopedStr() { s = prev; } };
// Its boolean sibling, for a flag that must be restored on every exit from a pass.
struct ScopedFlag { bool& b; bool prev;
    ScopedFlag(bool& b_) : b(b_), prev(b_) { b = true; }
    ~ScopedFlag() { b = prev; } };
// ScopedFlag's conditional twin: raise the flag only when `on`, and restore on EVERY exit. The
// restore-on-exit is what makes it safe in a function with early returns, where the hand-written
// save/set/restore pair it replaces would leak the flag into whatever is emitted next.
// Install a CONTRACT's own name-resolution scope, for rendering its member signatures under its imports
// rather than the implementing unit's. Three sites did this by hand and all three moved the same THREE
// fields of `NsCtx` while leaving the fourth — `unitPath` — pointing at the implementer. That is not a
// harmless omission: `checkReach` decides the import rung by comparing `_nsCtx.unitPath` against the file
// being walked, precisely so it can tell "these imports belong to a different file" — and a stale path
// made the two agree, so a contract member returning a type declared BESIDE the contract was judged
// against the contract's own imports. A file does not import what it declares, so the implementer was
// told to import a name its line 1 already imported. One helper, so a fourth site cannot get it wrong.
//
// It carries the DIAGNOSTIC file too. A defect found while rendering the contract's signature is at the
// contract, and reporting it against the implementer paired one file's path with another's line number —
// the half that made this cost bisection time rather than fix time.
struct ScopedContractNs {
    NsCtx& ns; NsCtx savedNs; std::string& diag; std::string savedDiag;
    ScopedContractNs(NsCtx& ns_, std::string& diag_, const InterfaceInfo& ii)
        : ns(ns_), savedNs(ns_), diag(diag_), savedDiag(diag_)
    {
        if (ii.isGenericInst) return;   // a generic instance gets its scope from ContractSubst instead
        ns.scope = ii.scope; ns.usings = ii.usings; ns.symbolAliases = ii.symbolAliases;
        ns.privScope = ii.privScope; ns.exportedHere = ii.exportedHere;
        ns.unitPath = ii.declFile;
        if (!ii.declFile.empty()) diag = ii.declFile;
    }
    ~ScopedContractNs() { ns = savedNs; diag = savedDiag; }
};

struct ScopedNoHeap { bool& b; bool prev;
    ScopedNoHeap(bool& b_, bool on) : b(b_), prev(b_) { if (on) b = true; }
    ~ScopedNoHeap() { b = prev; } }; }

// Where a compiler-owned unit's source lives, keyed BOTH ways: by unit pointer for the query layer's
// DefSites, and by the unit's synthetic name for reportPath, which is what a diagnostic carries.
void CEmitter::noteBuiltinFile(const CompilationUnit* u, const std::string& srcPath)
{
    if (!u) return;
    _builtinUnitFile[u] = srcPath;
    if (u->name) _builtinFileByName[*u->name] = srcPath;
}

const std::string& CEmitter::diagFile() const
{
    if (!_collectingUnitPath.empty()) return _collectingUnitPath;
    if (!_emitDeclFile.empty())       return _emitDeclFile;
    return _sourcePath;
}

// `@compileFor` on a member: one sentence, raised at collection (collectClasses) and again where emission reaches the
// attribute (emitAttributes) — identical text, so the diagnostic dedup reports it once.
const char* const CEmitter::kCompileForOnMember =
    "`@compileFor` gates a whole top-level declaration, and a member is not one — the gate would be silently "
    "ignored here. Gate the enclosing `type` instead (which drops every member with it), or split the member "
    "into two types";

// Source the author cannot edit: a compiler-owned `<…>` unit, or a file under the stdlib or package-store roots.
bool CEmitter::isForeignFile(const std::string& path) const
{
    if (path.empty()) return false;
    if (path[0] == '<') return true;
    for (auto& r : _foreignRoots)
        if (!r.empty() && path.size() > r.size() && path.compare(0, r.size(), r) == 0 && path[r.size()] == '/') return true;
    return false;
}

// The site that instantiated `mangled`, recorded once, when it is registered: the use site's file and line —
// or, when it is registered from inside another foreign instance's body, THAT instance's user site, so a chain
// of stdlib instances still leads back to the line the author wrote.
void CEmitter::recordInstSite(const std::string& mangled, const std::string& templateKey,
                              const std::vector<SharedIdentifier>& args, int line)
{
    if (_instSites.count(mangled)) return;
    if (!_attrSite.file.empty()) { _instSites[mangled] = _attrSite; return; }
    const std::string f = !_nsCtx.unitPath.empty() ? _nsCtx.unitPath : diagFile();
    if (f.empty() || isForeignFile(f) || line <= 0) return;
    // The label spells the instance as source would — `Fixed<int8>#(16)`, `deserializeJsonBuffer<Shared<Pt>>` —
    // rather than demangling its C name, which cannot tell a namespace separator from a type-argument boundary.
    std::string types, values;
    for (auto& a : args) {
        int64_t v;
        if (a && a->constArgValue && constArgN(a, v)) values += (values.empty() ? "" : ", ") + std::to_string(v);
        else types += (types.empty() ? "" : ", ") + (a ? demangleForDisplay(mangleElem(a)) : std::string("?"));
    }
    std::string label = demangleForDisplay(templateKey);
    const size_t cut = label.rfind("::");
    if (cut != std::string::npos) label = label.substr(cut + 2);
    label += (types.empty() ? "" : "<" + types + ">") + (values.empty() ? "" : "#(" + values + ")");
    _instSites[mangled] = { f, line, label };
}

// KR-38: a diagnostic raised INSIDE a foreign template's instance — at a stdlib line the author never wrote —
// is reported at the instantiation site, with the stdlib location kept as a note. The mistake is the type
// argument (or the call) the author chose, and some of these facts are settled only after collection, so the
// refusal cannot move to a bound; what can move is where it is reported. `rawFile` is the unrendered file.
void CEmitter::attributeToInstSite(std::string& file, int& line, std::string& message) const
{
    if (_attrSite.file.empty() || !isForeignFile(diagFile())) return;
    message += " (in `" + _attrSite.label + "`, instantiated here; raised at " + file + ":" + std::to_string(line) + ")";
    file = reportPath(_attrSite.file);
    line = _attrSite.line;
}

void CEmitter::unsupported(const char* rawWhat, int srcLine)
{
    unsupported(rawWhat, srcLine, std::string());
}

// The same channel, plus the NAME the defect is about — see Diagnostic::subject for why a tool must be
// handed the name rather than left to find it in the prose. Only the sites a TOOL can act on pass one;
// everything else keeps the two-argument form, so an empty subject means "nothing to act on" rather
// than "nobody got round to it".
void CEmitter::unsupported(const char* rawWhat, int srcLine, const std::string& subject)
{
    std::string display = demangleForDisplay(rawWhat);
    std::string dfile = reportPath(diagFile());
    attributeToInstSite(dfile, srcLine, display);
    const char* what = display.c_str();
    // ONE mistake, ONE diagnostic. A generic type's member body is emitted once per instantiation, so a
    // rule that fires inside one fired once per instantiation: `Box<int32>` and `Box<bool>` turned a
    // single bad initializer into "FAILED (2 errors)", both on the same line of the same file. Keyed on
    // (file, line, message) because `unsupported` is given a LINE, not a node — two different mistakes
    // that agree on all three are indistinguishable to the reader anyway.
    //
    // The `/* TODO(kama): unsupported … */` marker below is deliberately NOT deduped: it is a property of
    // the emission site, one per body actually emitted, and it keeps `--keep-c` honest.
    if (!_reportedDiags.insert(dfile + ":" + std::to_string(srcLine) + ":" + display).second) {
        *_out << "/* TODO(kama): unsupported " << what << " */";
        return;
    }
    ++_unsupported;
    // The ONE record of this defect. It is NOT printed here: `unsupported` is a hard error at the driver
    // (unsupported > 0 fails the build), and a stderr line printed from inside the walk could only ever be
    // a second, differently-worded rendering of what this struct already says — which is exactly what it
    // was. See `renderDiagnostic` (kama.diagnostic.h) for the shape that replaced it; the driver renders
    // this list for `build` and `check` alike, so the two cannot disagree about a defect they both found.
    // We only know the line here (call sites pass `node->line`); precise column/end come with spans (T3).
    Diagnostic d;
    d.line = srcLine;
    d.severity = DiagSeverity::Error;
    d.code = "unsupported";
    d.message = what;
    // reportPath, not diagFile: a diagnostic owned by the prelude names the prelude's FILE when the
    // install has it (and the driver has verified it is still what this binary compiled), and its
    // synthetic `<prelude>` name when it does not. The unit keeps its name either way.
    d.file = dfile;
    d.subject = subject;
    _diagnostics.push_back(d);
    *_out << "/* TODO(kama): unsupported " << what << " */";
}

// (A soft `warning()` stood here, whose header promised it could land a breaking rule in two steps —
// warn while the corpus is swept, then flip to `unsupported`. It never had a caller, and the promise
// was false: `run_tests.sh` fails any fixture whose stderr matches /warning/i, deliberately, because a
// warning is the compiler saying it does not believe its own output. Breaking rules land the other way
// round — migrate the corpus and the rule in one commit. `DiagSeverity::Warning` itself stays; its one
// producer is the LSP-only `undeclared-import` in the driver, which never reaches stderr.)

// ---------------------------------------------------------------------------
// Namespaces: scope prefixes + name resolution
// ---------------------------------------------------------------------------

// "a.b.c" — the dotted source name from an identifier's qualifier + value.
std::string CEmitter::qualifiedName(SharedIdentifier id)
{
    std::string s;
    if (id->qualifier)
        for (auto& seg : *id->qualifier) s += *seg + ".";
    s += id->value ? *id->value : "";
    return s;
}

std::string CEmitter::mangleNs(const std::string& ns)
{
    std::string r = ns;
    for (size_t p; (p = r.find('.')) != std::string::npos; ) r.replace(p, 1, "__");
    return r;
}

// A module name is written `a::b`; every manglable path in this file is dotted before `mangleNs` folds it
// to `a__b` (see the import paths below, and `qualifiedName` above). One spelling in, one mangler.
// The two arguments every allocation and release takes — a block's size and alignment — for C type `cty`.
// Every `kama_alloc`/`kama_free`/`A__allocate`/`A__deallocate` the emitter writes spells a layout through here.
static std::string layoutOf(const std::string& cty) { return "sizeof(" + cty + "), _Alignof(" + cty + ")"; }

static std::string dottedModule(const std::string& mod)
{
    std::string r = mod;
    for (size_t p; (p = r.find("::")) != std::string::npos; ) r.replace(p, 2, ".");
    return r;
}

// The file-private scope for a unit no module owns, derived from the unit's NAME rather than its position
// in the compilation (§2e.26). It used to be `_F<index>`, which made every file-private symbol move when
// the operands were permuted: the same program emitted `_F4__priv` one way and `_F6__priv` the other, so
// `--keep-c` was not reproducible. The index also counted prelude units, so it moved for reasons that had
// nothing to do with the user's own file list.
//
// `_F` is kept as the marker (leading `_` + uppercase is reserved to the implementation by C11 §7.1.3, and
// that is what these are), but it is no longer followed by digits — so `demangleForDisplay` can no longer
// recognise one by PATTERN and reads a registry of minted scopes instead.
static std::string privateScopeFor(const std::string& unitPath)
{
    size_t slash = unitPath.find_last_of("/\\");
    std::string stem = (slash == std::string::npos) ? unitPath : unitPath.substr(slash + 1);
    size_t dot = stem.find_last_of('.');
    if (dot != std::string::npos) stem.erase(dot);
    std::string r = "_F";
    for (char c : stem) r += (std::isalnum((unsigned char)c) || c == '_') ? c : '_';
    return r;
}

// Build a file's namespace context: the module its PATH puts it in, or private (`_F<file>`); collect its
// `using`s and aliases.
//
// A file's identity is where it sits — its path under its project's `source` root, resolved against the
// `modules` map in that project's `kama.json` (SPEC.md § Modules). The driver answers that
// through `_moduleResolver`, because it is filesystem work. A loose file — nothing with a `kama.json`
// above it — has no module to be in, and takes the file-private scope above; §2e.27 is what makes its
// symbols unimportable, which is why deriving that scope from the file's own name is enough.
//
// There are TWO rungs, not three. A middle one read the file's own `namespace` declaration; phase 2e
// deleted that declaration from the language along with all 91 of its uses, so a file's identity now comes
// from where it sits or from nowhere at all.
NsCtx CEmitter::ctxOf(SharedCompilationUnit unit)
{
    NsCtx ctx;
    ctx.unitPath = unit->name ? *unit->name : std::string();
    // Every rejection below is about an `import` line written in THIS unit, and this runs before any
    // module is current — `_sourcePath` is "" in a multi-file build — so they named no file at all.
    ScopedStr _cu(_collectingUnitPath, ctx.unitPath);   // see diagFile()
    const std::string module = (_moduleResolver && unit->name) ? _moduleResolver(*unit->name) : std::string();
    ctx.module = module;
    if (!module.empty()) {
        ctx.scope = mangleNs(dottedModule(module));           // `std::collections` -> `std__collections`
        ctx.isPublic = true;
        // The file rung's key material (see NsCtx): the private scope this file's unexported names take,
        // and the export list that decides which names do not. Read here, before any key is minted.
        ctx.privScope = ctx.scope + "__" + privateScopeFor(ctx.unitPath);
        if (unit->exportList)
            for (auto& name : *unit->exportList) if (name) ctx.exportedHere.insert(*name);
    } else {
        ctx.scope = privateScopeFor(ctx.unitPath);
        ctx.isPublic = false;
    }
    // Imports (`::`-path already resolved to source by the driver). Populate scope bindings:
    //   import a::b;            -- nothing (qualified-only, a::b::X)
    //   import a::b as m;       -- module alias  -> aliases[m] = a__b, so m::X resolves
    //   import a::b::{X,Y as Z} -- per-symbol    -> symbolAliases[X]=a__b__X, [Z]=a__b__Y (unqualified)
    //
    // An `as` alias may NOT claim a PROJECT root reachable from this file (§2f.29). It used to be able
    // to, and `global::a::b::X` was the escape hatch — name a module absolutely, past the file's own
    // aliases. That escape is gone with the `namespace` declaration, so the shadowing it worked around is
    // refused where it is written instead. The set is exactly what this file can name: the three reserved
    // roots, its own project, and the root of every module it imports — which is the right scope, because
    // an alias binds in one file and nowhere else.
    std::set<std::string> projectRoots = { "std", "core", "global" };
    if (!module.empty()) projectRoots.insert(module.substr(0, module.find("::")));
    if (unit->importDeclarationList)
        for (auto& imp : *unit->importDeclarationList)
            if (imp && imp->modulePath && !imp->modulePath->empty())
                projectRoots.insert(*(*imp->modulePath)[0]);

    if (unit->importDeclarationList)
        for (auto& imp : *unit->importDeclarationList) {
            if (!imp || !imp->modulePath) continue;
            std::string path;                                  // dotted, for mangleNs
            for (auto& s : *imp->modulePath) path += (path.empty() ? "" : ".") + *s;
            // `import { X };` — an EMPTY modulePath is the SAME-MODULE form, not a malformed one. It
            // needs no path because there is exactly one candidate, so it targets this file's own scope
            // and the symbols bind bare, just as a foreign per-symbol import does. (A file in no module
            // has scope `_F<file>` and no siblings, so the form is inert rather than special-cased.)
            std::string mod = imp->modulePath->empty() ? ctx.scope : mangleNs(path);
            if (imp->symbols)
                for (auto& sym : *imp->symbols) {
                    if (!sym || !sym->identifier || !sym->identifier->value) continue;
                    std::string local = (sym->alias && sym->alias->value) ? *sym->alias->value
                                                                          : *sym->identifier->value;
                    // ⚠️ §2f.29 NOW RIDES ON THE SYMBOL ALIAS, because that is the only alias left. The
                    // rule is unchanged — an `as` may not claim a name that already roots a project this
                    // file can reach — but it used to be checked on the MODULE alias, and dropping the
                    // whole-module import would have retired the rule silently along with the form.
                    // The harm is the same either way: `… as std` leaves `std::…` unspellable in this file.
                    if (sym->alias && sym->alias->value && projectRoots.count(local))
                        unsupported(("`as " + local + "` claims `" + local + "`, which already names a "
                                     "project this file can reach — the alias would shadow it with no way "
                                     "left to spell the original. Pick another name").c_str(), imp->line);
                    std::string target = mod + "__" + *sym->identifier->value;
                    auto it = ctx.symbolAliases.find(local);
                    if (it != ctx.symbolAliases.end() && it->second != target)
                        unsupported(("import of `" + local + "` collides with another import — disambiguate with `as`").c_str(), imp->line);
                    ctx.symbolAliases[local] = target;
                }
        }
    // The smart-pointer triad is a built-in module (std::memory), always in scope — add an implicit
    // `using` so bare `Owned`/`Shared`/`Weak` resolve everywhere with no `import std::memory`. Consulted
    // AFTER an explicit import's symbolAliases and the unit's own scope (see resolveUserName/resolveFunc),
    // so it never shadows a user's own name and a redundant explicit import stays a harmless no-op.
    ctx.usings.push_back("std__memory");
    return ctx;
}

// Scope-prefix a declared name (registration). `main` stays the global entry.
std::string CEmitter::qualify(const std::string& name) const
{
    if (name == "main") return "kama_main";
    if (_nsCtx.scope.empty()) return name;   // the prelude's global namespace -> bare names
    // A name this file does not `export` is private to the FILE, and its key says so. Before 0.9.207 the
    // key carried only the module, so two files each declaring a private `helper` collided ("duplicate
    // function"), and a private `type T`/`static n` in one file silently replaced the other's — the
    // tables were per module while the visibility rule was per file (ROADMAP row 1, found by the first
    // package's tests). Decided HERE, once, because every declaration key and every same-file lookup
    // comes through this function; the cross-file lookups add the module key as their second try.
    if (!_nsCtx.privScope.empty() && !_nsCtx.exportedHere.count(name)) return _nsCtx.privScope + "__" + name;
    return _nsCtx.scope + "__" + name;
}

void CEmitter::restoreFileRung(NsCtx& ns, const std::string& declFile) const
{
    ns.privScope.clear(); ns.exportedHere.clear();
    if (declFile.empty() || declFile[0] == '<') return;          // compiler-owned, or unknown
    for (auto& kv : _unitCtx)
        if (kv.second.unitPath == declFile) { ns.privScope = kv.second.privScope; ns.exportedHere = kv.second.exportedHere; return; }
}

std::string CEmitter::siblingPrivateKey(const std::string& name,
                                        const std::function<bool(const std::string&)>& known,
                                        const std::string& scope) const
{
    // A QUALIFIED spelling (`a::b::X`) names a module by path and reaches its private names the same way a
    // sibling does: found, then refused by checkReach as "not exported by <file>" — the message every
    // qualified-reference fixture asserts, and the one that names the file to edit.
    const std::string& want = scope.empty() ? _nsCtx.scope : scope;
    if (want.empty()) return "";
    // Only from a REAL file context. A context rebuilt for a header pass (scope, no file rung) has no
    // reference site for checkReach to judge, so a private key handed back there is not refused — it is
    // EMITTED, and b's ctor prototype came out returning a's private `T`. Everything a header pass
    // resolves was validated under a real context at collect time; a miss here is a miss.
    if (_nsCtx.isPublic && _nsCtx.privScope.empty()) return "";
    for (auto& kv : _unitCtx) {
        const NsCtx& other = kv.second;
        if (other.scope != want || other.privScope.empty() || other.privScope == _nsCtx.privScope) continue;
        std::string cand = other.privScope + "__" + name;
        if (known(cand)) return cand;
    }
    return "";
}

bool CEmitter::isNamespace(const std::string& name) const
{
    if (_nsCtx.aliases.count(name)) return true;
    return _namespaces.count(mangleNs(name)) != 0;
}

// Resolve a class/enum/interface reference (bare or qualified) to its registered
// mangled name. Bare names search the file's own scope, then its `using`s — never
// another file's private symbols. Returns the bare name if unresolved.
std::string CEmitter::resolveUserName(const std::string& value, SharedStringList qualifier,
                                      const IdentifierNode* site)
{
    if (rejectRootedPath(qualifier, site)) return value;
    std::string key = resolveUserNameImpl(value, qualifier);
    // THE CHOKEPOINT. Every qualified/unqualified type spelling in expression position resolves through
    // here — a static call's receiver, a variant construction's union, a dot-on-type ctor — so the file
    // rung is enforced once instead of at each emission site. The `…Impl` above stays pure, which is what
    // keeps completion from diagnosing a half-typed `secret::`.
    // `!synthesized` mirrors recordRef's gate, for the same reason: a substituted or emitter-built node
    // names no source text, so it cannot be attributed to a file — and a per-FILE rule must not judge it.
    // It is how `DynamicArray<Rec>` stops blaming the template's file for the caller's type argument.
    if (site && !site->synthesized)
        checkReach(key, value, "this reference", site->line, refFilePath(), qualifier && !qualifier->empty());
    recordRef(key, site);
    return key;
}

std::string CEmitter::resolveUserNameImpl(const std::string& value, SharedStringList qualifier)
{
    auto known = [&](const std::string& n) {
        return _classes.count(n) || _enums.count(n) || _interfaces.count(n) || _sigs.count(n)
            || _genericTypes.count(n)       // a generic-type template resolves to its scoped name too
            || _genericContracts.count(n);  // as does a generic-contract template (`Iterator<T>`)
    };
    // FFI: extern struct/handle names are global literal C names.
    if ((!qualifier || qualifier->empty()) && _externNames.count(value)) return value;
    // A per-symbol import binds a bare local name to a fully-mangled global (`import a::b::{X as Y}`).
    if (!qualifier || qualifier->empty()) {
        auto sa = _nsCtx.symbolAliases.find(value);
        if (sa != _nsCtx.symbolAliases.end() && known(sa->second)) return sa->second;
        if (sa != _nsCtx.symbolAliases.end()) { std::string ext = importedExtern(sa->second); if (!ext.empty()) return ext; }
    }
    // `global::X` — resolve from the ROOT, ignoring the file's own scope, its `using`s and its aliases:
    // the same symbol as bare `X`, nameable even where a local declaration shadows the spelling. `global`
    // is therefore a reserved PROJECT name (§2f.29). A longer path under it is refused by
    // rejectRootedPath before this runs, so `q` is empty here whenever `rooted`. (docs/SPEC.md § Modules —
    // deferred until an LSP existed to give it a completion payoff; precedent is C#'s `global::`.)
    SharedStringList q = qualifier;
    bool rooted = q && !q->empty() && *(*q)[0] == "global";
    if (rooted) {
        auto rest = std::make_shared<StringList>();
        for (size_t i = 1; i < q->size(); ++i) rest->push_back((*q)[i]);
        q = rest;
        if (q->empty()) return value;                    // `global::X` == the bare/floor spelling
    }
    if (q && !q->empty()) {
        // Qualified `A.B...value` — a namespace path (alias-expand a 1-segment head, but never under
        // `global::`, whose whole meaning is "not through this file's aliases").
        std::string nsMangled;
        if (!rooted && q->size() == 1 && _nsCtx.aliases.count(*(*q)[0]))
            nsMangled = _nsCtx.aliases[*(*q)[0]];
        else {
            std::string path;
            for (auto& seg : *q) path += (path.empty() ? "" : ".") + *seg;
            nsMangled = mangleNs(path);
        }
        std::string cand = nsMangled + "__" + value;
        if (known(cand)) return cand;
        // An extern keeps its literal key, so a qualified spelling reaches it only if THAT module exports
        // it; anything else stays unresolved rather than falling to the literal name some other file declares.
        if (_externDeclSites.count(value)) return externExportedFrom(value, nsMangled) ? value : cand;
        std::string priv = siblingPrivateKey(value, known, nsMangled);   // that module's file-private name -> checkReach refuses it
        return priv.empty() ? value : priv;
    }
    // This file's own name first — the file-private key for one it does not export, the module key for
    // one it does — then the module key regardless (a sibling's EXPORTED name, reachable without an
    // import; checkReach's inbound arm is what judges that), then the imported namespaces.
    std::string own = qualify(value);
    if (known(own)) return own;
    own = _nsCtx.scope + "__" + value;
    if (known(own)) return own;
    for (auto& u : _nsCtx.usings) {                    // imported public namespaces
        std::string cand = u + "__" + value;
        if (known(cand)) return cand;
    }
    // A sibling file's PRIVATE name: resolve to it so checkReach can say "not exported by a.kama" — the
    // one diagnostic that tells the reader which file to edit — rather than "unknown type".
    { std::string sib = siblingPrivateKey(value, known); if (!sib.empty()) return sib; }
    // `Base` names the enclosing type's base, as `This` names the enclosing type — so a derived author
    // never spells the concrete base name and `this.base = Base.make(…)` survives a rename of it.
    // Resolved HERE rather than in `cType` because `This` is only ever a TYPE, while `Base.make(…)` is
    // also an expression receiver; `resolveUserName` is the one funnel both go through (and it
    // `recordRef`s, so the query index gets the reference for free).
    //
    // LAST, deliberately: a real type named `Base` wins. `This` can afford to shadow unconditionally
    // because nobody names a type `This`, but `Base` is an ordinary name — four fixtures in this repo
    // declare one, and stealing it would be a language-wide tax to save a derived author one identifier.
    // Where the two would disagree, `checkBaseInstall` catches it as a type mismatch.
    if ((!qualifier || qualifier->empty()) && value == "Base" && !_thisType.empty()) {
        auto it = _classes.find(_thisType);
        if (it != _classes.end() && !it->second.baseName.empty()) return it->second.baseName;
    }
    return value;   // builtin/forward/unresolved — caller handles
}

// A name no scope of this file binds, reported by what ANOTHER file declares under it: "not imported — add
// this import" when a module exports one, "not exported by that file" when only a private one exists.
// Returns false, reporting nothing, when no module file declares it — the caller's "unknown" is then the
// right message. `known` says which table the name belongs in (types, or module constants).
//
// Asked of each file's own scope, never by splitting table keys on `__`. That split used to be the whole
// answer, and it matched a generic INSTANCE's key too (`Result_geo__Shown_geo__ShownErr` ends in
// `ShownErr`), so the hint said `add import { Result_geo::Shown_geo::ShownErr };`; it also named a PRIVATE
// declaration's module as the import to add, which no import can satisfy.
bool CEmitter::reportDeclaredElsewhere(const std::string& noun, const std::string& name,
                                       const std::function<bool(const std::string&)>& known,
                                       const char* what, int line)
{
    auto userDecl = [&](const std::string& k) {
        if (!known(k)) return false;
        const std::string f = declFileOf(k);
        return !f.empty() && f[0] != '<';                 // not an FFI spelling, not compiler-owned
    };
    std::set<std::string> exportedBy, privateIn;
    for (auto& kv : _unitCtx) {
        const NsCtx& c = kv.second;
        if (!c.isPublic) continue;                        // a loose file's names are unimportable (§2e.27)
        if (userDecl(c.scope + "__" + name)) exportedBy.insert(c.module);
        const std::string pk = c.privScope + "__" + name;
        if (userDecl(pk)) privateIn.insert(declFileOf(pk));
    }
    // ⚠️ The spelling this names has to be one that PARSES. It said `import ns::{Name}` — the module form
    // the module campaign deleted — so the one message whose whole job is to hand the reader a line to
    // paste handed them a syntax error (`unexpected IDENTIFIER, expecting {`). There is one import form
    // now, `import { … };`.
    if (!exportedBy.empty()) {
        // Two modules may export the same name (`DecodeError` in base64 and hex); each import is offered,
        // since only the reader knows which one they meant.
        std::string where, fix;
        for (auto& m : exportedBy) {
            where += (where.empty() ? "`" : " and `") + m + "`";
            fix += (fix.empty() ? "add `import { " : ", or add `import { ") + m + "::" + name + " };`";
        }
        unsupported((noun + " `" + name + "` is not imported — it lives in " + where + "; " + fix).c_str(),
                    line, name);
        return true;
    }
    if (privateIn.empty()) return false;
    // Only a PRIVATE declaration exists, so no import can reach it — naming one would send the reader to add
    // a line that fails. The same words `checkReach` uses for a qualified spelling of it.
    std::string files;
    for (auto& f : privateIn) files += (files.empty() ? "`" : " or `") + f + "`";
    unsupported(("`" + name + "` is not exported by " + files + ", so " + what
                 + " cannot name it — visibility is per FILE, and a name leaves its file only through that "
                   "file's `export { … };`. Add it there if it is meant to be reachable").c_str(), line);
    return true;
}

// Is `n` a generic TYPE-PARAM name rather than a real type? Type params flow through the type resolver
// unresolved by design (a template body mentions `T` long before any instantiation binds it — they are by
// far the commonest unresolved name), so every "this type doesn't exist" diagnostic must skip them.
// Checks the active substitution first (inside an instantiation), then every template's declared params —
// deliberately permissive: missing a typo that happens to collide with some template's param letter is a
// far better failure than rejecting valid generic code.
bool CEmitter::isTypeParamName(const std::string& n) const
{
    if (_typeSubst.count(n)) return true;
    if (_probeTypeParams.count(n)) return true;   // the template being probed — see checkUninstantiatedTemplates
    for (auto& kv : _genericTypeParams)
        for (auto& p : kv.second) if (p == n) return true;
    return false;
}

// The type a `null` is being measured against, when that type can never BE null — "" when `null` is
// legitimate there. Both null rules key on this.
//
// A bare local resolves through `_localTypeNodes`, its DECLARED type node, and only then falls back to
// `exprClass`. That order is the whole point: `exprClass` is **empty for a primitive**, so an `int32`
// looks exactly like an `UnsafePtr` to it — which is why `int32 a; if (a == null)` slipped the `== null`
// rule for as long as that rule has existed.
std::string CEmitter::neverNullType(SharedExpression e)
{
    if (auto* id = dynamic_cast<IdentifierNode*>(e.get()))
        if (id->value && (!id->qualifier || id->qualifier->empty())) {
            auto it = _localTypeNodes.find(*id->value);
            if (it != _localTypeNodes.end() && it->second && it->second->value) {
                const SharedIdentifier& t = it->second;
                const std::string ct = cType(t);
                if (t->builtInVal != 0 || isClass(ct) || isInterface(ct) || isEnum(ct)) return *t->value;
                return std::string();          // an UnsafePtr / FFI slot — `null` belongs here
            }
        }
    return exprClass(e);
}

// `null` STORED into a declared slot. The `== null` / `!= null` rule (see the BinaryExpressionNode arm)
// has always said that a safe type is never null; nothing said the same about putting one there, so
// `int32 x = null;`, `Thing t = null;` and `string s = null;` all passed `kama check` clean and exit 0, and
// failed later in the C compiler as an incompatible-pointer conversion against generated code.
//
// Deliberately keyed on the DECLARED type, not on inference: `null`'s legality is a property of the slot,
// which makes this checkable without an expression type checker. Deliberately conservative about what
// counts as safe — a class, contract, enum or builtin primitive. An unresolved or FFI name is left alone,
// because a C typedef for a pointer (`CompareFn cb = null;`) is a legitimate FFI spelling and this pass
// cannot tell one from a typo.
void CEmitter::rejectNullInit(SharedIdentifier declType, SharedExpression init, const char* what, int line)
{
    if (!init || !dynamic_cast<NullNode*>(init.get())) return;
    if (!declType || !declType->value) return;
    const std::string ty = cType(declType);
    const bool safe = declType->builtInVal != 0 || isClass(ty) || isInterface(ty) || isEnum(ty);
    if (!safe) return;
    unsupported(("`" + *declType->value + "` is never null in safe code, so " + what
                 + " cannot be `null` — `null` is only for `UnsafePtr<T>` at the FFI boundary. Use a "
                 "zero value, or `Optional<T>` to model absence").c_str(), line);
}

// ---------------------------------------------------------------------------------------------------
// KINDS — the first expression type checking kama has ever done.
//
// `int32 x = "not an int";` passed `kama check` clean and failed at CLANG, against generated C the
// author never wrote, naming C types (`kama_string`) the author never spelled. `kama check` saying OK
// is the worse half: the editor shows a broken file as clean.
//
// This is deliberately NOT a type checker. It answers one question — which of four FAMILIES does a
// value belong to — and rejects only a crossing between two of them. Width is not consulted: every
// integral/float/char combination is allowed, because narrowing is milestone 6's decision (D2) and
// carries a corpus migration this rule must not smuggle in.
//
// `Unknown` is the entire design. `exprClass` returns "" for a primitive AND for "unknown", and ~40
// callers depend on that conflation, so a checker built on it either says nothing about primitives (the
// exact bug) or fires on every unresolved name (unlandable). Here the two are distinct, and `Unknown`
// NEVER diagnoses. Everything the classifier is not certain about — array literals, bare variant
// constructors, a value-producing `match` at check time, `extern fn` results, an unresolved name —
// becomes `Unknown` and is left alone. (`borrow` aliases, `foreach` bindings and primitive `match`
// payload bindings were on this list; the classifier answers for all three now.)
const char* CEmitter::kindName(TKind k)
{
    switch (k) {
        case TKind::Num:       return "a number";
        case TKind::Bool:      return "a `bool`";
        case TKind::Str:       return "a `string`";
        case TKind::Aggregate: return "a type value";
        default:               return "unknown";
    }
}

// Keyed on the LOWERED C type, so one function serves both sides of the comparison. `cType` is not
// injective (`char` and `uint32` share `uint32_t`), which costs nothing here: both are `Num`, and
// char/integral crossings are allowed anyway.
CEmitter::TKind CEmitter::kindOfCType(const std::string& ct)
{
    if (ct.empty()) return TKind::Unknown;
    // PRIMITIVES FIRST, and this order is load-bearing: `kama_string` is itself a registered class (it
    // carries methods), so asking `isClass` first classified every `string` in the prelude as an aggregate
    // and rejected `string val = "";` on line 432 of it. The primitive C names are a closed set that no
    // user type can collide with — a user type is namespace-mangled — so testing them first is safe.
    if (ct == "kama_string")                            return TKind::Str;
    if (ct == "bool")                                   return TKind::Bool;
    if (ct == "int8_t"  || ct == "int16_t"  || ct == "int32_t"  || ct == "int64_t"
     || ct == "uint8_t" || ct == "uint16_t" || ct == "uint32_t" || ct == "uint64_t"
     || ct == "float"   || ct == "double"   || ct == "kama_char"
     || ct == "size_t"  || ct == "ptrdiff_t"
     || ct == "long"    || ct == "unsigned long")       return TKind::Num;   // `clong`/`culong` (0.9.232)
    // A CONTRACT or a `sig` is deliberately Unknown, not an aggregate. A contract value accepts a class,
    // another contract, AND a widened primitive — `Hashable h = n;` over an `int32` is a shipped feature
    // (tests/intrinsic_widen.kama), and calling that an aggregate rejected three fixtures that are right.
    // A destination that admits every kind cannot discriminate on kind.
    if (isInterface(ct) || isSigType(ct))               return TKind::Unknown;
    // A payload/generic `enum` is backed by a ClassInfo (`isVariant`), so `isClass` already covers it;
    // `_enums` holds ONLY the payload-less kind, which this compiler calls "a bare integer, not a struct"
    // in its own `@generate` diagnostic — and emits as one (`typedef uint8_t Tag;` for `: IntType`, a C
    // enum otherwise). So a plain enum is `Num`.
    //
    // ⚠️ This used to end "…and `Tag t = 0` keeps compiling", stated as a deliberate allowance. It is not
    // one any more, and it never should have been: an integer names no variant until it has been checked
    // against them, which is why `cast<Tag>(n)` is refused. `rejectTypeIdentityMismatch` owns that now.
    // The KIND answer here is still `Num` and still correct — a plain enum is not an aggregate — which is
    // exactly why identity had to become a separate rule rather than a sixth bucket.
    if (isClass(ct)) {
        // …and the same exemption follows the contract into a smart-pointer handle. `Owned<Hashable> b = 20;`
        // is the OWNING form of that widening (tests/intrinsic_widen_box.kama) — the one that can outlive its
        // scope — so a box over a contract absorbs a primitive exactly as the bare contract does.
        if (isSmartPtrClass(ct)) {
            const std::string& el = _classes[ct].collElemClass;
            if (el.empty() || isInterface(el)) return TKind::Unknown;
        }
        return TKind::Aggregate;
    }
    if (isEnum(ct))                                     return TKind::Num;
    // Everything else — `void`, `void*`/`T*` (UnsafePtr), an FFI typedef, an unresolved name, a bare
    // type parameter in a signature this pass sees before any binding. All of it is deliberately silent.
    return TKind::Unknown;
}

CEmitter::TKind CEmitter::declTypeKind(SharedIdentifier type)
{
    if (!type || !type->value) return TKind::Unknown;
    // `This`/`Base` resolve against an enclosing type that is NOT on the stack during `checkDeclaredTypes`
    // — the same reason that pass's own `check` skips them. Asking `cType` here would make it diagnose,
    // and this classifier must never be the thing that reports.
    if (*type->value == "This" || *type->value == "Base") return TKind::Unknown;
    return kindOfCType(cType(type));
}

// `cType` for a type node that a CLASSIFIER is asking about: "" wherever cType would DIAGNOSE. `This`
// and `Base` are the only two names it errors on, and both are legitimate in a signature this pass may
// see before the context that resolves them exists — `checkDeclaredTypes` skips them for the same
// reason. A classifier that reports is a classifier that fires on correct code.
std::string CEmitter::classifierCType(SharedIdentifier type)
{
    if (!type || !type->value) return "";
    if (*type->value == "This" && !type->genericArg && _thisType.empty()) return "";
    if (*type->value == "Base" && !type->genericArg
        && (!_basesLinked || !_currentClass || _currentClass->baseName.empty())) return "";
    return cType(type);
}

// The numeric-classification primitives the width rules are built on. Placed AHEAD of `typeOfExpr`
// because that classifier now uses them: under D-arith it must ask "is this a numeric C type" to
// decide whether `T op T` yields `T`, and a shift must ask the same of its LEFT operand alone.
namespace {
// Width in bits of a numeric C type, 0 if it is not one. `size_t`/`ptrdiff_t` are TARGET-width by
// definition — reported as their own bucket rather than assigned a number this compiler cannot know.
int cNumBits(const std::string& ct)
{
    if (ct == "int8_t"  || ct == "uint8_t")  return 8;
    if (ct == "int16_t" || ct == "uint16_t") return 16;
    if (ct == "int32_t" || ct == "uint32_t" || ct == "float" || ct == "kama_char") return 32;
    if (ct == "int64_t" || ct == "uint64_t" || ct == "double") return 64;
    return 0;
}
bool cNumSigned(const std::string& ct)
{
    return ct == "int8_t" || ct == "int16_t" || ct == "int32_t" || ct == "int64_t"
        || ct == "float"  || ct == "double"  || ct == "ptrdiff_t" || ct == "long";
}
bool cNumFloat(const std::string& ct) { return ct == "float" || ct == "double"; }

// The C type a primitive `lhs op rhs` computes in, when the EMITTER can say so without asking C: both
// operands one wide numeric type, or an `int32` literal beside one (C's usual conversions then yield the
// other side's type — which is also what `KAMA_ADD`'s `_Generic` would have selected). "" otherwise, and
// the caller keeps the `_Generic` form. This exists because that form spells every operand twice, so a
// nested chain doubles its C at each level (see `KAMA_ADD_T` in kama_runtime.h); knowing the type lets
// the caller name the helper itself and write each operand once.
std::string arithCType(const std::string& lt, bool lLit32, const std::string& rt, bool rLit32)
{
    auto wide = [](const std::string& t) {
        return t == "int32_t" || t == "int64_t" || t == "uint32_t" || t == "uint64_t" || cNumFloat(t);
    };
    if (wide(lt) && (lt == rt || rLit32)) return lt;
    if (wide(rt) && lLit32) return rt;
    return "";
}
// The fixed-width helper suffix of a type `arithCType` answered (`kama_div_i32`, `KAMA_ADD_T(i64, …)`).
const char* arithSuffix(const std::string& ct)
{
    return ct == "int32_t" ? "i32" : ct == "int64_t" ? "i64" : ct == "uint32_t" ? "u32"
         : ct == "uint64_t" ? "u64" : ct == "float" ? "f32" : "f64";
}
bool cNumTargetWidth(const std::string& ct) { return ct == "size_t" || ct == "ptrdiff_t" || ct == "long" || ct == "unsigned long"; }

// A numeric target's range as C TEXT, for the runtime narrowing check. Deliberately not numbers:
// `size_t`/`ptrdiff_t` have no width this compiler can know, and `<stdint.h>`'s macros are exactly the
// right answer on every target. `lo` is a `long long` expression, `hi` an `unsigned long long` one —
// the two argument types `kama_narrow_chk_s`/`_u` take.
//
// Distinct from `primIntRangeC`, which answers for the CONSTANT-fold rule and stops where an `int64_t`
// stops holding every fold. This one has to cover the 64-bit and target-width targets too, because a
// RUNTIME uint64 -> int64 can fail where no constant can.
bool cNumRangeText(const std::string& ct, std::string& lo, std::string& hi)
{
    if (ct == "int8_t")    { lo = "INT8_MIN";    hi = "INT8_MAX";    return true; }
    if (ct == "int16_t")   { lo = "INT16_MIN";   hi = "INT16_MAX";   return true; }
    if (ct == "int32_t")   { lo = "INT32_MIN";   hi = "INT32_MAX";   return true; }
    if (ct == "int64_t")   { lo = "INT64_MIN";   hi = "INT64_MAX";   return true; }
    if (ct == "uint8_t")   { lo = "0";           hi = "UINT8_MAX";   return true; }
    if (ct == "uint16_t")  { lo = "0";           hi = "UINT16_MAX";  return true; }
    if (ct == "uint32_t")  { lo = "0";           hi = "UINT32_MAX";  return true; }
    if (ct == "kama_char") { lo = "0";           hi = "UINT32_MAX";  return true; }   // ranged by WIDTH
    if (ct == "uint64_t")  { lo = "0";           hi = "UINT64_MAX";  return true; }
    if (ct == "ptrdiff_t") { lo = "PTRDIFF_MIN"; hi = "PTRDIFF_MAX"; return true; }
    if (ct == "size_t")    { lo = "0";           hi = "SIZE_MAX";    return true; }
    if (ct == "long")          { lo = "LONG_MIN";    hi = "LONG_MAX";    return true; }   // `clong` (0.9.232)
    if (ct == "unsigned long") { lo = "0";           hi = "ULONG_MAX";   return true; }   // `culong`
    return false;   // float/double (see below) and everything that is not a number
}

// Is every value of the integer type `src` representable in the integer type `dst`? The predicate that
// decides whether a cast needs a check at all — both sides are integers, the caller having already
// answered for floats. Conservative by construction: a target-width type (`size_t`/`ptrdiff_t`) reports
// width 0, so it is only ever "contained" in itself, and the check that survives costs nothing —
// `lo`/`hi` are compile-time constants, so a comparison that cannot fail folds away at `-O2`.
bool cNumContains(const std::string& dst, const std::string& src)
{
    if (dst == src) return true;
    const int ds = cNumBits(dst), ss = cNumBits(src);
    if (!ds || !ss) return false;                       // a target-width type on either side
    if (cNumSigned(dst) == cNumSigned(src)) return ds >= ss;
    if (cNumSigned(dst)) return ds > ss;                // unsigned -> signed needs a strictly wider dst
    return false;                                       // signed -> unsigned: the negatives have nowhere to go
}

// Is this expression a NUMERIC LITERAL the author wrote — including one behind a sign? That bucket is
// the whole point of the measurement: contextual literal typing (row 2) absorbs it for free, so the
// row-3 migration is what is LEFT once it is subtracted.
bool isNumericLiteral(const ASTNode* n)
{
    if (!n) return false;
    if (auto* u = dynamic_cast<const SimpleUnaryExpressionNode*>(n))
        return isNumericLiteral(u->expression.get());
    return dynamic_cast<const Int8Node*>(n)   || dynamic_cast<const Int16Node*>(n)
        || dynamic_cast<const Int32Node*>(n)  || dynamic_cast<const Int64Node*>(n)
        || dynamic_cast<const UInt8Node*>(n)  || dynamic_cast<const UInt16Node*>(n)
        || dynamic_cast<const UInt32Node*>(n) || dynamic_cast<const UInt64Node*>(n)
        || dynamic_cast<const Float32Node*>(n)|| dynamic_cast<const Float64Node*>(n)
        || dynamic_cast<const CharNode*>(n);
}
// A LITERAL EXPRESSION: a numeric literal, or arithmetic built only out of them. D2a types a literal by
// its destination, and const arithmetic over literals is still the literal — `int8 a = 2 + 3;` is the
// author writing 5 where an `int8` goes, and `tests/int_literal_wide.kama:57` already pins governance
// reaching through such a fold.
//
// ⚠️ A NAMED constant is deliberately NOT one, and the distinction is the whole reason this cannot just
// ask `constValue`: the folder happily evaluates `comptime int32 N = 5;` to 5, but `N` STATES a type, so
// `int8 x = N;` is a conversion — as it is in Rust, where `const N: i32` cannot initialize an `i8`.
// Folding is about the value; this is about whether the author wrote a type.
// ⚠️ A SHIFT is not one either, however literal both its sides are. Its result type comes from the LEFT
// operand — that is D-arith, the same rule the classifier and the emitter follow — so context does not
// get to choose it. `1i32 << 31` is an `int32` whose value is INT32_MIN, which SPEC guarantees and
// `tests/num_cast.kama:21` asserts; reading it as a literal instead made the fold's 2147483648 look like
// a constant that does not fit an `int32`, and rejected the fixture.
bool isLiteralExpr(const ASTNode* n)
{
    if (!n) return false;
    if (auto* u = dynamic_cast<const SimpleUnaryExpressionNode*>(n)) return isLiteralExpr(u->expression.get());
    if (auto* b = dynamic_cast<const BinaryExpressionNode*>(n)) {
        if (b->token == LTLT || b->token == GTGT) return false;
        return isLiteralExpr(b->LHS.get()) && isLiteralExpr(b->RHS.get());
    }
    // A ternary whose BOTH arms are literals is itself a literal for typing purposes — every value it can
    // produce is one, so the destination types the whole expression, exactly as it does for `2 + 3`. Only
    // the condition varies, and that is a `bool`. Without this, `isize from = neg ? 1 : 0;` was rejected:
    // the arms defaulted to `int32` and the D2a exemption never fired because the node is not a literal.
    if (auto* t = dynamic_cast<const TernaryExpressionNode*>(n))
        return isLiteralExpr(t->LHS.get()) && isLiteralExpr(t->RHS.get());
    return isNumericLiteral(n);
}

// An UNSUFFIXED numeric literal, possibly negated — the one argument generic inference defers, so the typed
// siblings bind `T` first and the literal is then retyped to what they chose (ASTNode::unsuffixed). A
// suffixed `5i32` is the author's explicit width and binds eagerly, exactly as before.
static bool isDeferrableLiteral(const ASTNode* n)
{
    if (!n) return false;
    if (auto* u = dynamic_cast<const SimpleUnaryExpressionNode*>(n)) return isDeferrableLiteral(u->expression.get());
    return n->unsuffixed && isNumericLiteral(n);
}

// A value-producing expression that carries NO type of its own and must be HANDED its destination —
// a `match`, an array literal, or a ternary that yields one.
//
// The two gates that thread a destination (the call-argument path and the assignment path) each used to
// test `dynamic_cast<MatchNode*>` on the argument/RHS node ITSELF. So the identical `match`, wrapped in a
// ternary, slipped past both — and because a position that does not thread leaves `_matchTargetCType`
// alone rather than clearing it, the match silently adopted whatever target an ENCLOSING position had
// left behind. Probed 2026-08-18: `fn int64 f(int8 p)` called as
// `f(p: c ? match (e) {…int64 arms…} : match (e) {…})` inherited the `int64` of the surrounding
// `int64 y = …`, passed the arm check, built with no diagnostic and TRUNCATED 300 to 44. The kind rule
// went the same way — the same call with a `bool p` was accepted.
//
// Recursing through the ternary is what makes the gate see the shape; clearing at the non-threading
// positions is what makes the miss FAIL CLOSED (the existing "must appear in a typed position" error)
// rather than silently wrong.
static bool needsTargetType(const ASTNode* n)
{
    if (!n) return false;
    if (dynamic_cast<const MatchNode*>(n))        return true;
    if (dynamic_cast<const ArrayLiteralNode*>(n)) return true;
    if (auto* t = dynamic_cast<const TernaryExpressionNode*>(n))
        return needsTargetType(t->LHS.get()) || needsTargetType(t->RHS.get());
    return false;
}
}  // namespace

// `try cast<T>(x)` — the fallible conversion. Three verbs share `CastNode`, and only this one is a
// STATEMENT form (it needs a destination type to read `Some`'s payload from, and a slot to evaluate the
// operand once), so the positions that hoist it must be able to pick it out of the other two.
static bool isTryCast(const ASTNode* n)
{
    auto* c = dynamic_cast<const CastNode*>(n);
    return c && c->isTry;
}

CEmitter::SavedLocalType CEmitter::saveLocalBinding(const std::string& name)
{
    SavedLocalType sv; sv.name = name;
    auto t = _localTypes.find(name);     if (t != _localTypes.end())     { sv.had = true;         sv.prev = t->second; }
    auto c = _localCTypes.find(name);    if (c != _localCTypes.end())    { sv.hadC = true;        sv.prevC = c->second; }
    auto n = _localTypeNodes.find(name); if (n != _localTypeNodes.end()) { sv.hadNode = true;     sv.prevNode = n->second; }
    auto v = _constLocalVals.find(name); if (v != _constLocalVals.end()) { sv.hadConstVal = true; sv.prevConstVal = v->second; }
    auto m = _moveState.find(name);      if (m != _moveState.end())      { sv.hadMove = true;     sv.prevMove = m->second; }
    sv.hadConst    = _constLocals.count(name);
    sv.hadSlot     = _slotLocals.count(name);
    sv.hadSlotDecl = _slotDeclared.count(name);
    sv.hadRef      = _refParams.count(name);
    return sv;
}

// Reverse order, so a name bound twice in one scope (the re-declaration diagnostic keeps emitting)
// unwinds to what the FIRST binding displaced.
void CEmitter::restoreLocalBindings(const std::vector<SavedLocalType>& saved)
{
    for (auto it = saved.rbegin(); it != saved.rend(); ++it) {
        const SavedLocalType& sv = *it;
        if (sv.had)         _localTypes[sv.name]     = sv.prev;         else _localTypes.erase(sv.name);
        if (sv.hadC)        _localCTypes[sv.name]    = sv.prevC;        else _localCTypes.erase(sv.name);
        if (sv.hadNode)     _localTypeNodes[sv.name] = sv.prevNode;     else _localTypeNodes.erase(sv.name);
        if (sv.hadConstVal) _constLocalVals[sv.name] = sv.prevConstVal; else _constLocalVals.erase(sv.name);
        if (sv.hadMove)     _moveState[sv.name]      = sv.prevMove;     else _moveState.erase(sv.name);
        if (sv.hadConst)    _constLocals.insert(sv.name);    else _constLocals.erase(sv.name);
        if (sv.hadSlot)     _slotLocals.insert(sv.name);     else _slotLocals.erase(sv.name);
        if (sv.hadSlotDecl) _slotDeclared.insert(sv.name);   else _slotDeclared.erase(sv.name);
        if (sv.hadRef)      _refParams.insert(sv.name);      else _refParams.erase(sv.name);
    }
}

// With no scope open the binding is function-wide (a parameter, the `parallel_for` worker's captures) and
// the per-body reset at the next function entry is what retires it — exactly as before.
void CEmitter::noteScopedBinding(const std::string& name)
{
    if (!_scopes.empty()) _scopes.back().bindings.push_back(saveLocalBinding(name));
}

// A binder that shadows a live name is now REJECTED (`checkBinderShadow`), so on a valid program there is
// nothing here to hide — every erase below is a no-op. It earns its keep on an INVALID one: `unsupported`
// records the diagnostic and emission continues, and without this the doomed body would go on resolving
// the binder through the outer entry and pile cascade errors on top of the one true message. One binder,
// one diagnostic, which is what makes the `xfail` fixtures for this rule assert exactly one error.
//
// `_localCTypes` is deliberately never WRITTEN for these binders (see bindArmPayloadTypes: a
// `foreach (string s …)` binding is a borrow on the indexed path and an owned value on the iterator path,
// and an entry perturbs `ownsByValue` LHS detection). Erasing is not writing.
void CEmitter::hideShadowedLocal(const std::string& name, bool refBinder)
{
    _localCTypes.erase(name);
    _constLocals.erase(name); _constLocalVals.erase(name);
    _slotLocals.erase(name);  _slotDeclared.erase(name);
    _moveState.erase(name);
    if (!refBinder) _refParams.erase(name);
}

std::string CEmitter::matchSubjectClassQuiet(MatchNode* m, bool* inlineSubj, std::string* handleCls)
{
    if (inlineSubj) *inlineSubj = false;
    if (handleCls) handleCls->clear();
    if (!m) return "";
    std::string subjCls = exprClass(m->subject);
    // `match (give x)` — the consuming form resolves through the hand-off to x's class.
    if (subjCls.empty()) if (auto* h = dynamic_cast<HandoffNode*>(m->subject.get())) subjCls = exprClass(h->value);
    // THROUGH A HEAP HANDLE (KR-42): `match (g)` on an `Owned<Geo>`/`Shared<Geo>` matches the enum it points at,
    // as a method call on the same handle auto-derefs. The subject's class is the POINTEE; the handle is
    // reported so the emitter borrows through it. A `Weak` is not seen through — it must be upgraded first.
    {
        std::string pointee = heapOwnerTarget(subjCls);
        if (pointee.empty() && isSmartPtrClass(subjCls) && smartKind(subjCls) != CollKind::Weak)
            pointee = _classes[subjCls].collElemClass;
        auto pc = pointee.empty() ? _classes.end() : _classes.find(pointee);
        if (pc != _classes.end() && pc->second.isVariant) {
            if (handleCls) *handleCls = subjCls;
            return pointee;
        }
    }
    // A value-producing variant ctor as the SUBJECT: the concrete instance was inferred + registered at
    // discovery and its mangled name stashed, because it cannot be re-inferred here.
    if (subjCls.empty()) {
        auto it = _matchSubjInst.find(m);
        if (it != _matchSubjInst.end() && _classes.count(it->second)) {
            subjCls = it->second;
            if (inlineSubj) *inlineSubj = true;
        }
    }
    // A NON-generic user enum built inline (`match (Shape::Circle(r: 3))`) has no instance to infer, so it
    // never reached `_matchSubjInst`; its enum is recoverable straight from the qualified variant name.
    if (subjCls.empty()) {
        std::string vt = variantExprEnumCType(m->subject);
        if (!vt.empty() && _classes.count(vt)) {
            subjCls = vt;
            if (inlineSubj) *inlineSubj = true;
        }
    }
    return subjCls;
}

// The classifier's half of the arm-payload binding. `emitMatchSwitch` does the same lookup, but it also
// emits, indexes for the LSP, checks containment and tracks moves — and it may DIAGNOSE, which a total
// classifier may not. So the two share the lookup shape and the save/restore, not the install: everything
// unresolvable here is skipped silently and simply leaves the arm unanswered.
//
// ⚠️ `_localTypes` + `_localTypeNodes` ONLY, never `_localCTypes` — that map is read by `lvalueCType`, the
// compound-assignment path and the ownership/RAII paths, where a `foreach (string s in …)` binding is a
// BORROW on the indexed path and an OWNED value on the iterator path, so a binding in it perturbs
// `ownsByValue` LHS detection (the binding milestone broke 19 fixtures that way, and 6 this way).
std::vector<CEmitter::SavedLocalType> CEmitter::bindArmPayloadTypes(const ClassInfo& ci, const SharedMatchArm& a)
{
    std::vector<SavedLocalType> saved;
    if (!a || a->isWildcard() || !a->variantName || !a->bindings || !a->labels) return saved;
    const VariantCase* vc = nullptr;
    for (auto& v : ci.variants) if (v.name == *a->variantName) { vc = &v; break; }
    if (!vc) return saved;
    for (size_t i = 0; i < a->bindings->size() && i < a->labels->size(); ++i) {
        const std::string& lbl = *(*a->labels)[i];
        const FieldInfo* pf = nullptr;
        for (auto& f : vc->payload) if (f.name == lbl) { pf = &f; break; }
        if (!pf) continue;                       // an unknown label is emitMatchSwitch's to report
        const std::string bn = *(*a->bindings)[i];
        saved.push_back(saveLocalBinding(bn));
        hideShadowedLocal(bn, /*refBinder=*/false);
        // SUBSTITUTED — a generic instance stores its payload in the TEMPLATE's `T`, so the raw node
        // would classify as nothing. The binding is scoped to THIS RESOLUTION (`deepSubstInInstance`),
        // not held open by the caller: the arm body that follows belongs to the ENCLOSING generic scope,
        // whose own `T` a whole-match binding would have replaced.
        SharedIdentifier ty = deepSubstInInstance(ci.name, pf->type);
        const std::string bcty = classifierCType(ty);   // classifier-safe: "" where cType would diagnose
        _localTypes[bn]     = (isClass(bcty) || isInterface(bcty) || isSigType(bcty)) ? bcty : "";
        _localTypeNodes[bn] = ty;
    }
    return saved;
}

// ---------------------------------------------------------------------------------------------------
// `typeOfExpr` — the total expression classifier.
//
// The twelve partial resolvers that grew up inside this emitter each answer for one node shape, and each
// returns "" for BOTH "this is a primitive" and "I have no idea". That conflation is why none of them
// could ever be the basis of a type rule: built on `exprClass`, a checker is either silent on every
// primitive or firing on every unresolved name. Here the two are separated — a primitive answers with
// its C spelling, and "" means only "not certain", exactly as `TKind::Unknown` does one level up.
//
// It COMPOSES those resolvers rather than re-deriving them. Each already carries the hard parts —
// generic-instance binding, `This` under `_thisType`, auto-deref through a smart pointer or a user
// `Deref<T>`, contract receivers, `_typeSubst` save/restore — and a second implementation of any of
// that is free to drift from the one the emitter actually lowers through.
//
// The answer is a LOWERED C type name, not a new type representation, because every destination in the
// compiler already holds one (`_localCTypes`, `_currentReturnCType`, `_matchTargetCType`,
// `ParamSig::className`, `FuncSig::retCType`) and `primKeyOfCType` recovers the kama width from it.
std::string CEmitter::typeOfExpr(SharedExpression e)
{
    if (!e) return "";
    ASTNode* n = e.get();

    // --- literals: the one place a type is known outright -------------------------------------------
    if (dynamic_cast<StringNode*>(n))   return "kama_string";
    if (dynamic_cast<BooleanNode*>(n))  return "bool";
    if (dynamic_cast<CharNode*>(n))     return "kama_char";  // a codepoint, and its own type since 0.9.104
    if (dynamic_cast<Int8Node*>(n))     return "int8_t";
    if (dynamic_cast<Int16Node*>(n))    return "int16_t";
    if (dynamic_cast<Int32Node*>(n))    return "int32_t";
    if (dynamic_cast<Int64Node*>(n))    return "int64_t";
    if (dynamic_cast<UInt8Node*>(n))    return "uint8_t";
    if (dynamic_cast<UInt16Node*>(n))   return "uint16_t";
    if (dynamic_cast<UInt32Node*>(n))   return "uint32_t";
    if (dynamic_cast<UInt64Node*>(n))   return "uint64_t";
    if (dynamic_cast<Float32Node*>(n))  return "float";
    if (dynamic_cast<Float64Node*>(n))  return "double";
    // An interpolation lowers to a `string` — UNLESS it carries a tag, whose function decides the type.
    if (auto* is = dynamic_cast<InterpolatedStringNode*>(n)) {
        if (!is->tag) return "kama_string";
        std::string key = resolveFunc(*is->tag, nullptr);
        auto f = _funcs.find(key);
        return f != _funcs.end() ? f->second.retCType : "";
    }
    // `null` is deliberately typeless here: `rejectNullInit` owns it and says something better.
    if (dynamic_cast<NullNode*>(n)) return "";

    // --- places -------------------------------------------------------------------------------------
    if (dynamic_cast<ThisAccessNode*>(n)) return _currentClass ? _currentClass->name : "";
    if (dynamic_cast<IdentifierNode*>(n) || dynamic_cast<MemberAccessNode*>(n)) {
        // `lvalueCType` answers a local/param and a field of the current class; `receiverScalarCType`
        // reaches a PRIMITIVE field through an arbitrary receiver, which lvalueCType's own path already
        // covers but a const-generic binding does not; `exprClass` reaches a module `static` and resolves
        // a field under its OWNER INSTANCE's type args. First non-empty wins — they do not disagree,
        // they cover different shapes.
        std::string ct = lvalueCType(e);
        if (ct.empty()) ct = receiverScalarCType(e);
        if (ct.empty()) ct = moduleStaticCTypeRaw(e);
        if (ct.empty()) ct = exprClass(e);
        // A BINDING — a `foreach` element or a `match`-arm payload. None of the four resolvers above
        // reaches one: they answer for a declared local, a param, a field or a module static, and a
        // binding is none of those. So the rule the author can see two tokens away (`foreach (int64 x in
        // xs)`, `case Some(value: c)`) did not hold through it, and `int8 n = x;` truncated in silence.
        //
        // `_localTypeNodes` is the map that HAS held the answer all along, and it is deliberately the one
        // consulted rather than `_localCTypes`: that map is read by `lvalueCType`, the compound-assignment
        // path and the ownership/RAII paths, where a `foreach (string s in …)` binding is a BORROW on the
        // indexed path and an OWNED value on the iterator path — teaching it about bindings perturbs
        // `ownsByValue` LHS detection. This one is read only by `neverNullType` and the numeric rules,
        // which is exactly the blast radius this answer should have.
        if (ct.empty())
            if (auto* id = dynamic_cast<IdentifierNode*>(n))
                if (id->value && (!id->qualifier || id->qualifier->empty())) {
                    auto it = _localTypeNodes.find(*id->value);
                    if (it != _localTypeNodes.end()) ct = classifierCType(it->second);
                }
        // An ENUM MEMBER — `[Ns::]Enum::Member`. None of the resolvers above reaches one either: it is a
        // QUALIFIED name, so the binding fallback just above excludes it by construction, and the four
        // before it answer for a place rather than a constant. So `A::A2` classified as "" — meaning
        // `uint8 n = A::A2;` was invisible to every rule that reads this classifier, while `uint8 n = a;`
        // through a local was not. Half of each enum shape was unexaminable purely by spelling.
        //
        // Same resolution the emitter does at `emitExpression`'s IdentifierNode arm: the enum name is the
        // LAST qualifier segment, resolved through the file's scope with the segments before it. Quiet —
        // `resolveUserName` on a non-enum qualifier just fails to match `_enums` and leaves "".
        if (ct.empty())
            if (auto* id = dynamic_cast<IdentifierNode*>(n))
                if (id->value && id->qualifier && !id->qualifier->empty()) {
                    auto enumQual = std::make_shared<StringList>();
                    for (size_t i = 0; i + 1 < id->qualifier->size(); ++i)
                        enumQual->push_back((*id->qualifier)[i]);
                    std::string en = resolveUserName(*id->qualifier->back(), enumQual);
                    // …in EVERY spelling an enum has. `_enums` is a payload-less enum (members or not, and a
                    // generic one's instance, pinned by the target type); a tagged enum was never in it.
                    // Answering "" for a tagged one left every rule that asks this question unable to see
                    // that `E::B` is an `E` at all: the comparison lowering fell through to a raw C
                    // operator, reported as "no operator '==' — define `operator==`", which kama does not
                    // have. The member NAME
                    // is checked, so `Color::NotAVariant` still resolves to nothing and reaches the
                    // unresolved-name diagnostic that names the enum.
                    //
                    // A GENERIC enum's variant (`Optional::None`) deliberately misses: its template is in
                    // `_genericTypes`, never `_classes`, and the instance a literal belongs to comes from
                    // the target-type context, which this function does not have.
                    if (isEnum(scalarEnumInstanceOf(en))) ct = scalarEnumInstanceOf(en);
                    else {
                        auto cit = _classes.find(en);
                        if (cit != _classes.end() && cit->second.isVariant)
                            for (auto& vc : cit->second.variants)
                                if (vc.name == *id->value) { ct = en; break; }
                    }
                }
        return ct;
    }

    // --- calls --------------------------------------------------------------------------------------
    // `callReturnTypeRaw` is UNFILTERED by design — it was extracted out of `exprClass` precisely so a
    // non-class return (a plain enum, a primitive) survives, which is what makes it usable here.
    if (auto* inv = dynamic_cast<InvocationNode*>(n)) return callReturnTypeRaw(inv);

    // --- indexing -----------------------------------------------------------------------------------
    if (dynamic_cast<ElementAccessNode*>(n)) {
        std::string ct = indexElemTypeRaw(e);
        // `receiverScalarCType` resolves the container through `_localCTypes` where `exprClass` (which
        // `indexElemTypeRaw` asks first) resolves it through `_localTypes` — different maps, so it
        // answers for a container shape the other misses rather than duplicating it.
        return !ct.empty() ? ct : receiverScalarCType(e);
    }

    // --- conversions --------------------------------------------------------------------------------
    // `try cast<T>(x)` is the one cast whose type is NOT its type argument: it yields `Optional<T>`, the
    // same shape `.as<T>()` has, so it gets the same answer. Without this every rule downstream reads it
    // as a bare `T` — and the kind rule then rejects `Optional<int8> r = try cast<int8>(v);` as a number
    // initializing a type.
    if (auto* c  = dynamic_cast<CastNode*>(n))
        return c->isTry ? classifierCType(optionalTypeNode(c->type)) : classifierCType(c->type);
    if (auto* bc = dynamic_cast<BitcastNode*>(n)) return classifierCType(bc->type);
    if (auto* ad = dynamic_cast<AsDowncastNode*>(n)) return classifierCType(optionalTypeNode(ad->type));
    if (dynamic_cast<SizeofNode*>(n)) return "size_t";   // `sizeof`/`alignof` are a `usize`
    if (auto* inv = dynamic_cast<InvocationNode*>(n))    // `sizeof(ptr: p)`, the intrinsic call form
        if (inv->identifier && inv->identifier->value
            && (*inv->identifier->value == "sizeof" || *inv->identifier->value == "alignof")) return "size_t";

    // --- operators ----------------------------------------------------------------------------------
    // A comparison or a logical connective yields `bool` WHATEVER its operands are, so this arm is
    // certain where the arithmetic one is not.
    if (dynamic_cast<LogicalAndOrNode*>(n)) return "bool";
    if (auto* be = dynamic_cast<BinaryExpressionNode*>(n)) {
        switch (be->token) {
            case EQEQ: case NOTEQ: case LT: case GT: case LEQ: case GEQ: return "bool";
            default: break;
        }
        std::string oc = operatorResultClass(be->token, /*binary*/1, be->LHS, be->RHS);
        if (!oc.empty()) return oc;
        // `string + string` is the one built-in binary operator over a non-numeric type.
        if (be->token == PLUS && (exprIsString(be->LHS) || exprIsString(be->RHS))) return "kama_string";
        // A SHIFT takes its type from the LEFT operand alone. The right one is a COUNT, not a co-operand
        // — Rust implements `Shl<Rhs>` for every integer pair and C promotes each side independently — so
        // requiring the two to agree would be a rule about nothing. `lib/std/num/fixed.kama` shifts an
        // `int64` by a `const F: int32` eight times over, and `json.kama` writes `(c >> 4ui8)`.
        if (be->token == LTLT || be->token == GTGT) {
            const std::string lt = typeOfExpr(be->LHS);
            return (cNumBits(lt) || cNumTargetWidth(lt)) ? lt : "";
        }
        // ARITHMETIC over two operands of the SAME numeric type yields THAT type — kama's own rule
        // (D-arith), not C's. C would promote anything narrower than `int` to `int` here, and that answer
        // used to be reported: `uint8 + uint8` was an `int32_t`, so `fn uint8 hexDigit(uint8 v) { return
        // 48ui8 + v; }` read as a narrowing return in code that has nothing wrong with it. Inheriting C's
        // promotion table also makes it part of kama's surface — a reader would have to know it to predict
        // which lines need a cast — which is the opposite of what this campaign is for. Rust, Swift and Go
        // all answer `T`, and `emitBinaryOperator` now emits the cast that makes C agree.
        //
        // MIXED operand types stay "". Under full D2 they are an ERROR (milestone 6's operand rule), so
        // there is no conversion for this classifier to describe and no answer it should invent.
        {
            const std::string lt = typeOfExpr(be->LHS), rt = typeOfExpr(be->RHS);
            if (!lt.empty() && lt == rt && (cNumBits(lt) || cNumTargetWidth(lt))) return lt;
            // ONE operand a literal is NOT a mixed expression. A literal takes its type from the other
            // operand (the D2a exemption the operand rule already carves out), so `cap * 2` on an `isize`
            // is an `isize` — answering "" here made it merely SILENT rather than typed, which is why
            // `isize nc = cap == 0 ? 4 : cap * 2;` was rejected while `isize d = cap * 2;` passed.
            const bool lLit = isLiteralExpr(be->LHS.get()), rLit = isLiteralExpr(be->RHS.get());
            if (lLit != rLit) {
                const std::string& ot = lLit ? rt : lt;
                if (!ot.empty() && (cNumBits(ot) || cNumTargetWidth(ot))) return ot;
            }
        }
        return "";
    }
    if (auto* su = dynamic_cast<SimpleUnaryExpressionNode*>(n)) {
        // `!x` is a `bool` regardless; `-x`/`+x`/`~x` carry the operand's type through, and a user
        // operator carries its own return type.
        if (su->token == EXCLAMATION) return "bool";
        std::string oc = operatorResultClass(su->token, /*unary*/0, su->expression, nullptr);
        return !oc.empty() ? oc : typeOfExpr(su->expression);
    }
    if (auto* pr = dynamic_cast<PreIncrDecrNode*>(n)) {
        std::string oc = operatorResultClass(pr->token, 0, pr->expression, nullptr);
        return !oc.empty() ? oc : typeOfExpr(pr->expression);
    }
    if (auto* po = dynamic_cast<PostIncrDecrNode*>(n)) {
        std::string oc = operatorResultClass(po->token, 0, po->expression, nullptr);
        return !oc.empty() ? oc : typeOfExpr(po->expression);
    }

    // --- value-producing branches -------------------------------------------------------------------
    // Every arm shares a type, so the first that resolves is representative — the same walk `exprClass`
    // makes, including a block arm's terminal `:= expr;`.
    if (auto* tx = dynamic_cast<TernaryExpressionNode*>(n)) {
        // A branch that is a bare LITERAL is not representative of the ternary's type. A literal takes its
        // type from its DESTINATION (D2a, the same exemption `numericHandoff` and the operand rule apply),
        // so `cap == 0 ? 4 : cap * 2` is an `isize` expression with a literal in one arm — not an `int32`
        // one. Taking the first arm that resolved made the literal win by position, which rejected
        // `isize nc = this.cap == 0 ? 4 : this.cap * 2;` in every collection that grows a buffer.
        const bool lLit = isLiteralExpr(tx->LHS.get()), rLit = isLiteralExpr(tx->RHS.get());
        if (lLit != rLit) {                                  // exactly one arm is a literal — ask the other
            std::string oc = typeOfExpr(lLit ? tx->RHS : tx->LHS);
            if (!oc.empty()) return oc;
        }
        std::string lc = typeOfExpr(tx->LHS);
        return !lc.empty() ? lc : typeOfExpr(tx->RHS);
    }
    if (auto* mx = dynamic_cast<MatchNode*>(n)) {
        // Two passes, for the same reason the ternary above takes one: an arm that is a bare LITERAL is
        // contextually typed (D2a), so it is not representative of the match. `isize got = match (rr) {
        // case Ok(value: c): c; case Err(error: e): 0 - 1; }` is an `isize` match with a literal in its
        // error arm — taking the first arm that RESOLVED made `0 - 1` win whenever the payload arm was
        // unknown, and typed the whole match `int32`.
        auto armValue = [](const SharedMatchArm& a) -> SharedExpression {
            SharedExpression v = a->body;
            if (!v && a->block && a->block->statements)
                for (auto& st : *a->block->statements)
                    if (auto* av = dynamic_cast<ArmValueNode*>(st.get())) v = av->value;
            return v;
        };
        if (mx->arms) {
            // An arm's payload binding is bound by `emitMatchSwitch` during EMISSION, which is too late for
            // every rule that asks this classifier — so `case Some(value: x): x;` answered "" and the whole
            // match with it. Bind the payload types HERE too, for exactly as long as it takes to classify
            // one arm's value. The payload's type is the variant's declared field type, statically
            // available, so this is not a guess (which is why the removed literal fallback below must stay
            // removed — see the pass-2 comment).
            std::string subjCls = matchSubjectClassQuiet(mx);
            auto scit = _classes.find(subjCls);
            const ClassInfo* mci = (scit != _classes.end() && scit->second.isVariant) ? &scit->second : nullptr;
            // NOTE the subject's type args are NOT bound around the loop below. `bindArmPayloadTypes`
            // binds them for its own resolution and gives them straight back, so `typeOfExpr(v)` below
            // classifies the arm VALUE under the enclosing scope's substitution — which is the one the
            // arm body was written in. Holding the subject's binding open here answered `this.item`
            // inside a generic type's method with the subject enum's `T`.

            bool anyValueArm = false;                            // a non-literal arm EXISTS, answered or not
            std::string answer;
            for (auto& a : *mx->arms) {                          // a NON-literal arm speaks first
                SharedExpression v = armValue(a);
                if (!v || isLiteralExpr(v.get())) continue;      // diverging, or contextually typed
                anyValueArm = true;
                std::vector<SavedLocalType> bound;
                if (mci) bound = bindArmPayloadTypes(*mci, a);
                std::string ac = typeOfExpr(v);
                restoreLocalBindings(bound);
                if (!ac.empty()) { answer = ac; break; }
            }
            if (!answer.empty()) return answer;
            // Pass 2 belongs to "EVERY arm is a literal", which is what its comment always claimed — but it
            // used to run whenever pass 1 produced no ANSWER, which is not the same test. A payload arm the
            // classifier cannot type is still a value arm, and letting the error arm's `0` speak for the
            // match typed `isize written = match (wr) { case Ok(value: w): w; case Err(error: e): 0; }` as
            // an `int32` and rejected the initializer. Unknown is the honest answer there.
            if (!anyValueArm)
                for (auto& a : *mx->arms) {                      // every arm literal — they type the match
                    SharedExpression v = armValue(a);
                    if (!v) continue;
                    std::string ac = typeOfExpr(v);
                    if (!ac.empty()) return ac;
                }
        }
        return "";
    }

    // Everything else is deliberately silent: an array literal and a bare variant constructor take their
    // type from context, and an `extern fn` result is opaque. (A `borrow` alias used to be listed here and
    // is NOT one — the borrow site records both its C type and its type node, so indexing through one
    // types correctly. Probed 2026-08-18; the claim had outlived the code.)
    return "";
}

// The kind of an expression is the kind of its type. Before `typeOfExpr` this switched on the node
// itself and reached literals and simple places only, so a call result, an element, a cast, a comparison
// and a value-producing `match` all crossed a hand-off unexamined.
CEmitter::TKind CEmitter::exprKind(SharedExpression e)
{
    return kindOfCType(typeOfExpr(e));
}

// The same rule where the destination is already a LOWERED C type rather than a declared type node — a
// return value, a `match` arm, a call argument. Those sites never hold the kama type; they hold the C
// type they are about to assign through, which is exactly what `kindOfCType` wants.
// ---------------------------------------------------------------------------------------------------
// M5a — the MEASURING instrument for strict numeric conversion (ROADMAP row 3).
//
// That rule is source-breaking, so its size has to be known before it is scoped, and the size is not
// grep-able: two naive regexes over 31k lines find 126 sites and miss assignments, arguments, returns,
// field initializers and compound operators entirely. This rides the five hand-off positions the kind
// rule already visits, which is every place a value crosses into a destination of a stated type.
//
// It REJECTS NOTHING and it must not print `warning:` — the soft warning channel was deliberately
// deleted, because a warning is the compiler saying it does not believe its own output, and
// `run_tests.sh` fails any fixture whose stderr matches /warning/i. So this is a TSV on STDOUT,
// emitted only under the hidden flag, aggregated with `sort | uniq -c`.
//
// The taxonomy is the brief's four buckets plus two the brief folded together and should not have:
// a signedness flip at equal width changes the value without changing the width, and an int/float
// crossing is a conversion in a category of its own. Both would otherwise be counted as "widening".

void CEmitter::noteNumericHandoff(const std::string& dstCType, SharedExpression value,
                                  const char* what, int line)
{
    if (!_strictNumericScan || !value || dstCType.empty()) return;
    const bool dstNum = cNumBits(dstCType) || cNumTargetWidth(dstCType);
    if (!dstNum) return;
    const std::string src = typeOfExpr(value);
    // A NUMERIC destination the classifier cannot answer the source of. Reported as its own bucket
    // rather than dropped, because it is the instrument's own blind spot and a measurement that hides
    // its blind spot is worse than no measurement: arithmetic is deliberately uncertain (C's usual
    // conversions decide `a + b`'s width, which is the strict rule's own problem to model), and an
    // intrinsic with a NULL `returnType` — `s.length()` and its `usize` siblings — records no type at
    // all. This count is the upper bound on what a later pass could still find.
    if (src.empty()) {
        std::string u = "kama-strictnum\t" + reportPath(diagFile()) + "\t" + std::to_string(line)
                      + "\t?\t" + dstCType + "\tunknown-src\t" + (what ? what : "");
        size_t t = u.find('`'); if (t != std::string::npos) u = u.substr(0, t);
        if (_strictNumericSeen.insert(u).second) std::fprintf(stdout, "%s\n", u.c_str());
        return;
    }
    if (src == dstCType) return;
    if (!cNumBits(src) && !cNumTargetWidth(src)) return;   // a kind crossing, which is already an ERROR

    // CONTEXTUAL LITERAL TYPING (D2a), which is what 5b MEANS: a literal takes its type from its
    // destination, so a literal that FITS there is already of that type and no conversion happens. Only
    // one that does not fit is a hand-off at all — and that one is now an ERROR (rejectConstOutOfRange),
    // not a row to migrate. This is what empties the `literal` bucket and leaves row 2's real size.
    // A literal that does not fold (a float) is contextually typed too, and drops for the same reason.
    if (isNumericLiteral(value.get())) {
        int64_t v;
        if (!constValue(value, v)) return;
        if (!constOutOfRange(dstCType, v, src)) return;
    }

    const char* cat;
    if (isNumericLiteral(value.get()))                            cat = "literal";
    else if (cNumTargetWidth(src) || cNumTargetWidth(dstCType))   cat = "target-width";
    else if (cNumFloat(src) != cNumFloat(dstCType))               cat = "int-float";
    else if (cNumBits(dstCType) <  cNumBits(src))                 cat = "narrowing";
    else if (cNumSigned(src)   != cNumSigned(dstCType))           cat = "signedness";
    else                                                          cat = "widening";

    // The POSITION, normalized: the callers spell a name into it (``argument `x` ``), and a per-name
    // bucket would not aggregate.
    std::string pos(what ? what : "");
    size_t tick = pos.find('`');
    if (tick != std::string::npos) pos = pos.substr(0, tick);
    while (!pos.empty() && pos.back() == ' ') pos.pop_back();

    std::string row = "kama-strictnum\t" + reportPath(diagFile()) + "\t" + std::to_string(line) + "\t"
                    + src + "\t" + dstCType + "\t" + cat + "\t" + pos;
    // A generic body is emitted once per instantiation and the prelude is analyzed once per unit, so
    // the same site arrives many times. Same dedupe key as `unsupported`, for the same reason.
    if (!_strictNumericSeen.insert(row).second) return;
    std::fprintf(stdout, "%s\n", row.c_str());
}

// The SEVENTH position, and the one the hand-off instrument above cannot see: an operator's two OPERANDS.
// D2 read literally — "no implicit numeric conversion" — makes `int32 + uint8` a conversion as surely as
// `int8 a = big` is, and that is the rule Rust/Swift/Go have (`i32 + u8` does not compile; `Add<u8>` is not
// implemented for `i32`). Nothing anywhere measures it today, so this sizes it before the rule exists.
//
// Same row shape as `noteNumericHandoff`, deliberately: column 4 carries the LEFT operand where a hand-off
// row carries the source, column 5 the RIGHT where it carries the destination, so one `cut -f6 | sort |
// uniq -c` still answers the whole histogram. Every bucket is prefixed `op-` so the six hand-off buckets
// stay separable in it. Column 7 is the OPERATOR rather than a position name, because which operators drive
// the migration is exactly what decides the exemption list.
//
// ⚠️ `op-unknown` is REPORTED, not dropped. 5a's first draft dropped every hand-off whose source it could
// not type and reported 219 rows, reading as "the strict rule has no migration" while hiding 29,282. A
// measurement that hides its blind spot is worse than no measurement, and this instrument's blind spot is
// larger than that one's: a type-parameter operand, a const-generic parameter, an intrinsic with no
// recorded return type, and (until milestone 6's own D-arith change) every mixed-width arithmetic
// subexpression all answer "".
void CEmitter::noteNumericOperands(int opToken, SharedExpression lhs, SharedExpression rhs,
                                   const char* posWhat, int line)
{
    if (!_strictNumericScan || !lhs || !rhs) return;
    const std::string lt = typeOfExpr(lhs), rt = typeOfExpr(rhs);
    const bool lNum = !lt.empty() && (cNumBits(lt) || cNumTargetWidth(lt));
    const bool rNum = !rt.empty() && (cNumBits(rt) || cNumTargetWidth(rt));

    // Not a numeric operator pair at all: `string + string`, `bool && bool`, a user type, an enum (which
    // lowers to its own typedef, never to a C numeric name). Silent — those are other rules' subjects.
    if ((!lt.empty() && !lNum) || (!rt.empty() && !rNum)) return;
    if (lt.empty() && rt.empty()) return;         // both unknown says nothing about anything

    const char* cat;
    if (!lNum || !rNum)                                        cat = "op-unknown";
    else if (opToken == LTLT || opToken == GTGT)               cat = lt == rt ? nullptr : "op-shift";
    else if (lt == rt) {
        // Same type on both sides is no conversion — but the four sub-`int` types are where C's integer
        // promotion makes the RESULT wider than either operand, which is what D-arith (`T op T -> T`)
        // changes and what the emitter then has to truncate. Counting them here says whether that
        // emission change is twenty sites or two thousand, before a line of it is written.
        //
        // ⚠️ A COMPARISON is counted separately and is NOT part of that change: it yields `bool`, so
        // promotion cannot leak into its result and it needs no cast. Lumping the two together answered
        // 11,701 when the number D-arith actually has to touch was 39 — a measurement off by 300x, in the
        // direction that would have killed the design.
        if (!cNumBits(lt) || cNumBits(lt) >= 32 || cNumFloat(lt)) cat = nullptr;
        else cat = isComparisonToken(opToken) ? "cmp-subint" : "arith-subint";
    }
    else if (isNumericLiteral(lhs.get()) && isNumericLiteral(rhs.get())) {
        // BOTH sides literals (`4294967295 + 1`). Neither one is a destination for the other, so there is
        // nothing to convert: the whole expression is contextually typed by the hand-off it feeds, which
        // is where 5b-A range-checks it and 5b-B governs its width — `tests/int_literal_wide.kama:57`
        // pins exactly that ("governance reaches THROUGH const arithmetic"). Counted rather than dropped
        // so the exemption stays visible; reading it as a migration site is how this instrument first
        // reported the operand rule as costing one site when it costs none.
        cat = "op-both-literal";
    }
    else if (isNumericLiteral(lhs.get()) != isNumericLiteral(rhs.get())) {
        // Exactly one side is a literal, so D2a applies at operand position too: the literal takes the
        // OTHER operand's type, and no conversion happens — unless it does not fit there, which is the
        // one case that becomes an error rather than an exemption.
        const bool lLit = isNumericLiteral(lhs.get());
        const std::string& litT  = lLit ? lt : rt;
        const std::string& destT = lLit ? rt : lt;
        int64_t v;
        if (!constValue(lLit ? lhs : rhs, v)) cat = "op-literal";        // a float literal: no fold, no check
        else cat = constOutOfRange(destT, v, litT) ? "op-literal-oob" : "op-literal";
    }
    else if (cNumTargetWidth(lt) || cNumTargetWidth(rt))       cat = "op-target-width";
    else if (cNumFloat(lt) != cNumFloat(rt))                   cat = "op-int-float";
    else if (cNumBits(lt) != cNumBits(rt))
        cat = cNumSigned(lt) != cNumSigned(rt) ? "op-mixed-both" : "op-mixed-width";
    else                                                       cat = "op-mixed-sign";

    if (!cat) return;                              // same type, nothing to migrate and nothing to note

    std::string row = "kama-strictnum\t" + reportPath(diagFile()) + "\t" + std::to_string(line) + "\t"
                    + (lt.empty() ? "?" : lt) + "\t" + (rt.empty() ? "?" : rt) + "\t" + cat + "\t"
                    + (posWhat ? posWhat : "");
    if (!_strictNumericSeen.insert(row).second) return;
    std::fprintf(stdout, "%s\n", row.c_str());
}

// ---------------------------------------------------------------------------------------------------
// TYPE IDENTITY — the measuring instrument, and the classifier the rule will be built on.
//
// The kind rule sorts every type into five buckets, so two DISTINCT kama types that land in the same
// bucket cross every hand-off unexamined. The numeric rules cannot catch them either: each one bails on
// a C spelling it does not recognize as a number, and `rejectMixedOperands`' bail names the escapee
// outright — "`string + string`, a bool, AN ENUM". Neither rule is wrong on its own terms. Nothing owns
// identity.
//
// A FAMILY is a set of types that are (a) mutually non-interchangeable and (b) recognizable from an
// already-lowered C type — which is all the hand-off funnels hold. Two members of one family, or of two
// families, may never cross. `None` is silent, exactly as `TKind::Unknown` is, and it is what keeps the
// rule off everything the rest of the campaign made legal: a contract destination (which admits every
// kind by design), a smart-pointer or `Optional` promotion, an inheritance upcast, a type parameter.
//
// `Num` is EVERY numeric primitive taken together, not one family member per width. The widths are
// already held apart by `rejectNumericConversion` — each has its own C spelling — so splitting them here
// would only duplicate it. What this family is for is naming the enum<->number boundary, and it must
// include the target-width pair (`size_t`/`ptrdiff_t`) and the floats: leaving them out reported
// `isize == int32` as an identity crossing, which is the numeric rule's subject and not this one's.
CEmitter::IdFamily CEmitter::idFamilyOf(const std::string& ct)
{
    if (ct.empty()) return IdFamily::None;
    // A payload-less `enum` — `_enums` holds only that kind; a payload/generic one is a ClassInfo, which
    // C refuses to assign across anyway. Pinned (`: IntType`) it is a typedef NAME, unpinned a C `enum`;
    // both are why every numeric rule reads it as "not a number I know" and takes its silent path.
    if (isEnum(ct))                            return IdFamily::Enum;
    if (isSigType(ct))                         return IdFamily::Sig;
    // `char` is a codepoint, not a number that happens to be 32 bits wide, and it is the third family for
    // the same reason as the other two. It is ALSO numeric (`cNumBits("kama_char")` is 32) — deliberately,
    // so it keeps range checking and mixed-operand checking — which is why this test comes first and why
    // `rejectTypeIdentityMismatch` hands the non-literal crossings back to `rejectNumericConversion`.
    if (ct == "kama_char")                     return IdFamily::Char;
    if (cNumBits(ct) || cNumTargetWidth(ct))   return IdFamily::Num;
    return IdFamily::None;
}

const char* CEmitter::idFamilyName(IdFamily f)
{
    switch (f) {
        case IdFamily::Enum: return "enum";
        case IdFamily::Sig:  return "sig";
        case IdFamily::Num:  return "num";
        case IdFamily::Char: return "char";
        default:             return "none";
    }
}

// The hand-off half of the measurement. Rides the same two funnels and the same hidden flag as M5a, and
// keeps its row shape so one `cut -f6 | sort | uniq -c` still answers the histogram.
//
// ⚠️ The exemptions are where this rule's size lives, not the check — so this instrument REPORTS them
// rather than dropping them. `x-none` is every crossing where one side is a family and the other is not
// (a contract, a class, a smart pointer, an unresolved type parameter): all legal, all silent under the
// rule, and all invisible unless counted. M5a's first draft dropped its blind spot and reported 219 rows
// while hiding 29,282; this is that lesson applied before the fact.
void CEmitter::noteTypeIdentity(const std::string& dstCType, SharedExpression value,
                                const char* what, int line)
{
    if (!_strictNumericScan || !value || dstCType.empty()) return;
    const IdFamily dstF = idFamilyOf(dstCType);
    if (dstF == IdFamily::None) return;                 // the destination owns no identity to violate
    const std::string src = typeOfExpr(value);
    const IdFamily srcF = idFamilyOf(src);

    const char* cat;
    if (src.empty())                                    cat = "id-unknown-src";
    else if (srcF == IdFamily::None)                    cat = "id-x-none";
    else if (src == dstCType)                           return;        // the same type: nothing crossed
    else if (srcF == IdFamily::Num && dstF == IdFamily::Num) return;   // rejectNumericConversion's subject
    else if (isLiteralExpr(value.get()))                cat = srcF == IdFamily::Num ? "id-lit-into-enum"
                                                                                    : "id-lit-cross";
    else if (srcF == IdFamily::Enum && dstF == IdFamily::Enum) cat = "id-enum-enum";
    else if (srcF == IdFamily::Enum && dstF == IdFamily::Num)  cat = "id-enum-num";
    else if (srcF == IdFamily::Num  && dstF == IdFamily::Enum) cat = "id-num-enum";
    else if (srcF == IdFamily::Sig  && dstF == IdFamily::Sig)  cat = "id-sig-sig";
    else                                                       cat = "id-cross-family";

    std::string pos(what ? what : "");
    size_t tick = pos.find('`');
    if (tick != std::string::npos) pos = pos.substr(0, tick);
    while (!pos.empty() && pos.back() == ' ') pos.pop_back();

    std::string row = "kama-typeid\t" + reportPath(diagFile()) + "\t" + std::to_string(line) + "\t"
                    + (src.empty() ? "?" : src) + "\t" + dstCType + "\t" + cat + "\t" + pos;
    if (!_strictNumericSeen.insert(row).second) return;
    std::fprintf(stdout, "%s\n", row.c_str());
}

// The operand half. Two shapes are counted and they are NOT the same defect:
//   - two operands of DIFFERENT identity (`a == w` across two enums, which compares equal and takes the
//     wrong branch) — the identity rule's own subject;
//   - an arithmetic, bitwise or ordering operator over operands of the SAME enum (`a + A::A1`), which
//     yields a value of that enum that is no declared variant. Equality is exempt: `a == a` is the one
//     operator whose result over an enum is meaningful, and `==` is a contract in this language.
void CEmitter::noteTypeIdentityOperands(int opToken, SharedExpression lhs, SharedExpression rhs,
                                        const char* opName, int line)
{
    if (!_strictNumericScan || !lhs || !rhs) return;
    if (opToken == LTLT || opToken == GTGT) return;      // a shift count is not a co-operand
    const std::string lt = typeOfExpr(lhs), rt = typeOfExpr(rhs);
    const IdFamily lf = idFamilyOf(lt), rf = idFamilyOf(rt);
    if (lf == IdFamily::None && rf == IdFamily::None) return;
    if (lf == IdFamily::Num  && rf == IdFamily::Num)  return;   // rejectMixedOperands' subject

    const char* cat;
    if (lt.empty() || rt.empty())                       cat = "id-op-unknown";
    else if (lf == IdFamily::None || rf == IdFamily::None) cat = "id-op-x-none";
    else if (lt != rt)                                  cat = "id-op-cross";
    else if (lf != IdFamily::Enum)                      return;   // same sig on both sides: nothing to say
    else if (isComparisonToken(opToken))
        cat = (opToken == EQEQ || opToken == NOTEQ) ? nullptr : "id-op-enum-order";
    else                                                cat = "id-op-enum-arith";
    if (!cat) return;

    std::string row = "kama-typeid\t" + reportPath(diagFile()) + "\t" + std::to_string(line) + "\t"
                    + (lt.empty() ? "?" : lt) + "\t" + (rt.empty() ? "?" : rt) + "\t" + cat + "\t"
                    + (opName ? opName : "");
    if (!_strictNumericSeen.insert(row).second) return;
    std::fprintf(stdout, "%s\n", row.c_str());
}

// ---------------------------------------------------------------------------------------------------
// 5b-A — CONTEXTUAL LITERAL TYPING (D2a). A literal takes its type from its DESTINATION, and the
// fits-check runs against that type.
//
// The rule is milestone 2's constant-cast check at a different site, and it reaches every site for free
// because all six hand-off positions funnel through the two functions below — nowhere else holds a
// destination type. Its reach is whatever `constValue` folds, not written literals only, which is the
// same reach the `cast` rule already has: two answers for `int8 x = cast<int8>(300)` and `int8 x = 300`
// would be exactly the split this campaign exists to remove.
//
// Measured before it was built: ZERO corpus sites change. Of 5a's 219 `literal` rows only 21 have a
// range-checkable destination and none is out of range, and none of the 105 rows into `size_t`/`uint64_t`
// passes a negative. Both boundary guards (check-agents.sh, check-query.sh) keep passing too, because the
// width mismatch they pin is `int8 a = big` — a VARIABLE, which `constValue` does not fold.
bool CEmitter::constOutOfRange(const std::string& dstCType, int64_t v, const std::string& srcCType)
{
    // `constValue` folds into an int64, so a NEGATIVE fold means one of three things and only two are
    // answerable: the value really is negative (a signed source), or it is a magnitude above INT64_MAX
    // reinterpreted (a 64-bit unsigned source), or WE CANNOT TELL. "Cannot tell" must be silent — the
    // constraint this whole campaign is built on — and the first cut of this rule broke it by reading
    // "the classifier did not say uint64_t" as "signed". `_moduleConsts` and `_constLocalVals` record a
    // const's VALUE with no type, so `typeOfExpr` answers "" for a module-level `comptime`, and
    // `uint64 x = M;` for `comptime uint64 M = 18446744073709551615ui64;` was rejected as "-1".
    const bool srcSigned = srcCType == "int8_t"  || srcCType == "int16_t" || srcCType == "int32_t"
                        || srcCType == "int64_t" || srcCType == "ptrdiff_t";
    const bool srcU64    = srcCType == "uint64_t" || srcCType == "size_t";
    if (v < 0 && !srcSigned) {
        if (!srcU64) return false;                  // unknown source — a value and a reinterpretation look alike
        // Above INT64_MAX, so it fits a 64-bit unsigned destination and no other INTEGER — but only a
        // destination this compiler can name is a judgement. An unsubstituted type parameter reaches
        // here spelled `T` (a generic call is range-checked before instantiation), and the first cut
        // read "not uint64_t" as "too narrow": `id(x: 18446744073709551615ui64)` into `fn T id<T>(T x)`
        // was refused as holding "no negative value". Same constraint as the unknown-source arm above.
        if (dstCType == "uint64_t" || dstCType == "size_t") return false;
        int64_t lo, hi;
        return primIntRangeC(dstCType, lo, hi) || dstCType == "int64_t" || dstCType == "ptrdiff_t";
    }
    int64_t lo, hi;
    if (primIntRangeC(dstCType, lo, hi)) return v < lo || v > hi;
    // The two target-width types, answered by SIGN alone rather than by a width this compiler was not
    // told: `usize n = -1;` is a bug on every target without knowing which one. `int64_t`/`ptrdiff_t`
    // hold every fold that reaches here.
    if (dstCType == "uint64_t" || dstCType == "size_t") return v < 0;
    return false;                       // not an integer destination — a float, a class, an enum
}

// A module-level `static` / `comptime`, UNFILTERED. `exprClass` already reaches one, but runs it through
// `isClass` — so a static of PRIMITIVE type answers "", which is the same filtering that hid a container's
// element type from the spine (see `indexElemTypeRaw`, extracted for exactly this reason). It matters here
// because `_moduleConsts` folds such a constant's VALUE while nothing could state its TYPE, and a rule
// that must tell a real negative from `constValue`'s int64 reinterpretation is blind without one:
// `comptime int32 N = -1;` at module scope let `uint8 u = N;` through, and the C it emitted said 255.
// A local of the same name shadows it, which the two lookups ahead of this one already handle.
std::string CEmitter::moduleStaticCTypeRaw(SharedExpression e)
{
    auto* id = dynamic_cast<IdentifierNode*>(e.get());
    if (!id || !id->value) return "";
    auto ms = _moduleStatics.find(qualify(*id->value));
    if (ms != _moduleStatics.end()) return classifierCType(ms->second);
    const std::string xk = resolveExternConst(*id->value, id->qualifier);
    return xk.empty() ? "" : classifierCType(_externConsts[xk].type);
}

// Recurses through exactly the shapes `constValue` folds through, plus the ternary — everywhere a literal
// can sit and still be governed by the destination of the expression around it. It does NOT require the
// expression to fold: `int64 a = 4294967295 + v;` claims the literal even though `v` is a runtime value,
// because the destination is just as much the literal's type there.
void CEmitter::governWideLiterals(SharedExpression e)
{
    if (!e) return;
    ASTNode* n = e.get();
    if (e->wideUnsuffixed) _litGoverned.insert(n);
    if (auto* u = dynamic_cast<SimpleUnaryExpressionNode*>(n)) { governWideLiterals(u->expression); return; }
    if (auto* c = dynamic_cast<CastNode*>(n))                  { governWideLiterals(c->unaryExpression); return; }
    if (auto* b = dynamic_cast<BinaryExpressionNode*>(n))  { governWideLiterals(b->LHS); governWideLiterals(b->RHS); }
    if (auto* t = dynamic_cast<TernaryExpressionNode*>(n)) { governWideLiterals(t->LHS); governWideLiterals(t->RHS); }
}

void CEmitter::rejectConstOutOfRange(const std::string& dstCType, SharedExpression value,
                                     const char* what, bool isInit, int line)
{
    int64_t v;
    if (dstCType.empty() || !value || !constValue(value, v)) return;
    const std::string srcCType = typeOfExpr(value);
    if (!constOutOfRange(dstCType, v, srcCType)) return;
    // A negative fold from a 64-bit unsigned source is a magnitude above INT64_MAX, so the diagnostic
    // must print the magnitude rather than the reinterpretation.
    const bool srcUnsignedWide = v < 0 && (srcCType == "uint64_t" || srcCType == "size_t");

    const std::string name = primKeyOfCType(dstCType);
    const std::string shown = srcUnsignedWide ? std::to_string((unsigned long long)v) : std::to_string(v);
    int64_t lo, hi;
    std::string head, tail;
    if (primIntRangeC(dstCType, lo, hi)) {
        head = "` (" + std::to_string(lo) + " to " + std::to_string(hi) + ")";
        tail = " — that is not a conversion but a different number. Write a value in range, or mask first "
               "if the truncation is what you mean (`cast<" + name + ">(x & 0xFF)`)";
    } else {
        head = "`";
        tail = " — `" + name + "` holds no negative value, and its width belongs to the target rather than "
               "to this compiler, so there is no conversion this could mean";
    }
    // Phrased like the kind-mismatch neighbour at the same position: an initializer is "declared T, so it
    // cannot be initialized with", a value hand-off is "expects T, so it cannot be given".
    unsupported((std::string(what) + (isInit ? " is declared `" : " expects `") + name + head
                 + (isInit ? ", so it cannot be initialized with " : ", so it cannot be given ")
                 + shown + tail).c_str(), line);
}

// Milestone 6, the hand-off half: a value must ALREADY have its destination's type. No implicit numeric
// conversion — not narrowing, not widening, not a signedness flip, not int/float. The Rust/Swift/Go rule
// (D2), and the reason it is a 1.0 gate: it is source-breaking, so it lands before the API-stability tag
// or waits for 2.0.
//
// This is `noteNumericHandoff`'s classification turned into a judgement, at the same two funnels, because
// those are the only places that hold a destination type. What it must NOT do is fire on anything the
// rest of the campaign made legal:
//
//   - an UNKNOWN source is silent. `typeOfExpr` returns "" for a type parameter, a const-generic
//     parameter, an intrinsic with no recorded return type, an `extern fn` result, a mixed-arithmetic
//     subexpression, and a value-producing `match` whose arm binding is not yet bound at CHECK time.
//     A `foreach` binding, a `match`-arm payload binding and a `borrow` alias were on this list and are
//     not any more — the classifier answers for all three. Every survivor must still compile, and this
//     is the single most important constraint in the campaign — a rule built on a classifier that
//     conflates "primitive" with "no idea" is either silent on every primitive or unlandable.
//   - a LITERAL is contextually typed (D2a), so it is already of its destination's type and there is no
//     conversion to reject. `constOutOfRange` is the predicate for the one that does not fit, and
//     `rejectConstOutOfRange` — which ran just above — owns that case, so this rule stays out of it
//     entirely rather than risking a second diagnostic for one mistake.
//   - a non-numeric destination or source belongs to the KIND rule below, which says it better.
void CEmitter::rejectNumericConversion(const std::string& dstCType, SharedExpression value,
                                       const char* what, bool isInit, int line)
{
    if (!value || dstCType.empty()) return;
    const bool dstNum = cNumBits(dstCType) || cNumTargetWidth(dstCType);
    if (!dstNum) return;
    const std::string src = typeOfExpr(value);
    if (src.empty() || src == dstCType) return;
    if (!cNumBits(src) && !cNumTargetWidth(src)) return;   // a kind crossing — the rule below names it

    // The D2a exemption: a literal takes its type from its destination, so there is no conversion to
    // reject. `rejectConstOutOfRange` ran just above and owns the one that does not FIT, so this rule
    // stays out of the literal case entirely rather than risk a second diagnostic for one mistake.
    //
    // One crossing survives it, and the line is REPRESENTABILITY, not family. `float32 f = 3;` is the
    // literal written at the destination's type and 5b decided it deliberately —
    // `tests/lit_in_range.kama:32` pins it, "an int literal into a float destination is contextual too" —
    // which is a step past Rust, where `let f: f64 = 3;` is an error. But `int32 x = 1.5;` cannot be the
    // same thing in reverse: no reading of `1.5` is an `int32`, so context is not typing the literal, it
    // is silently truncating it. That one is a real conversion and is rejected.
    if (isLiteralExpr(value.get()) && !(cNumFloat(src) && !cNumFloat(dstCType))) return;

    const std::string dstName = primKeyOfCType(dstCType);
    const std::string srcName = primKeyOfCType(src);
    unsupported((std::string(what) + (isInit ? " is declared `" : " expects `") + dstName
                 + "`, so it cannot be " + (isInit ? "initialized with " : "given ") + "a `" + srcName
                 + "` — kama has no implicit numeric conversion. Convert it explicitly: `cast<" + dstName
                 + ">(…)`").c_str(), line);
}

// The name a diagnostic uses for a type that owns identity. A PRIMITIVE wants its kama spelling — `usize`
// not `size_t`, `char` not `kama_char`, and that second one is not cosmetic: `kama_char` is a name no
// author ever typed, so a message carrying it would send the reader looking for a type that does not
// exist in their source. An enum or a sig is a USER name, and `unsupported` runs every message through
// `demangleForDisplay`, so the mangled key is already the right thing to hand it.
std::string CEmitter::idTypeName(const std::string& ct)
{
    const IdFamily f = idFamilyOf(ct);
    if (f == IdFamily::Num || f == IdFamily::Char) return primKeyOfCType(ct);
    return ct;
}

// Two signature types always differ in NAME; when they also differ in SHAPE the mismatch is not a
// nominal-typing nicety but a miscompile, and the message has to say which. `H hp = fp;` between
// `fnptr int32 F(int32)` and `fnptr int32 H(int32, int32)` compiles today with only a clang warning, and
// the call through it passes two arguments to a one-parameter function — an indirect call through a
// mismatched function pointer, which is exactly the UB class UBSan's `function` check would catch and
// which is disabled suite-wide for an unrelated, permanent reason (run_tests.sh).
std::string CEmitter::sigShapeNote(const std::string& srcCType, const std::string& dstCType)
{
    auto s = _sigs.find(srcCType), d = _sigs.find(dstCType);
    if (s == _sigs.end() || d == _sigs.end()) return "";
    if (s->second.params.size() != d->second.params.size())
        return " taking " + std::to_string(s->second.params.size()) + " and "
             + std::to_string(d->second.params.size()) + " parameters — calling one through the other "
               "would pass the wrong number of arguments";
    if (s->second.retCType != d->second.retCType)
        return " returning `" + idTypeName(s->second.retCType) + "` and `"
             + idTypeName(d->second.retCType) + "`";
    return "";
}

// TYPE IDENTITY — the rule the five kinds cannot express, for the families the numeric rules skip.
//
// The kind rule sorts every type into five buckets and passes when both sides land in one, so two
// DISTINCT kama types in the same bucket cross unexamined. The numeric rules cannot catch them either:
// each bails on a C spelling it does not recognize as a number, and `rejectMixedOperands`' bail names
// the escapee outright — "`string + string`, a bool, AN ENUM". A pinned enum lowers to a typedef NAME
// (`typedef uint8_t _Fu__A;`), so every numeric rule reads it as "not a number I know" and takes its
// documented silent path while the kind rule reads both sides as `Num` and passes. Neither rule is wrong
// on its own terms. Nothing owned identity, so this does.
//
// Measured over the whole corpus before it was written: ZERO sites change (see the `--strict-numeric`
// identity buckets). The exemptions are why — and they are the CLASSIFIER's, not a list here:
// `idFamilyOf` answers `None` for a contract, a class, a smart-pointer or `Optional` handle, an
// inheritance upcast and a type parameter, and `None` is silent on both sides. What survives is only the
// pairs that genuinely share a C representation.
//
// Two exemptions do need spelling out, because they are the ones a reader will reach for:
//
//   NUM -> NUM is not ours. Every width has its own C spelling and `rejectNumericConversion` already
//     holds them apart, with a better message. Returning here rather than shadowing it is what keeps one
//     mistake to one diagnostic.
//   A LITERAL is NOT exempt here, which is the one place this rule departs from its neighbours. D2a says
//     a literal takes its type from its destination — but that is a statement about WIDTH, and it holds
//     because every integer literal is a legitimate value of every integer type wide enough for it. It
//     does not survive a destination whose values are NAMED VARIANTS: `A a = 0;` is not "the literal
//     written at `A`'s type", it is an integer standing in for a variant, which is the exact thing
//     `cast<A>(n)` has been refused for since 0.9.94. `kindOfCType` used to promise the opposite in a
//     comment ("`Tag t = 0` keeps compiling"); no corpus site ever took it up, and it is corrected there.
//     `rejectConstOutOfRange` cannot double-diagnose here — it fires only on numeric destinations.
void CEmitter::rejectTypeIdentityMismatch(const std::string& dstCType, SharedExpression value,
                                          const char* what, bool isInit, int line)
{
    if (!value || dstCType.empty()) return;
    const IdFamily dstF = idFamilyOf(dstCType);
    if (dstF == IdFamily::None) return;                        // the destination owns no identity
    const std::string src = typeOfExpr(value);
    if (src.empty() || src == dstCType) return;                // unknown is silent; same type is fine
    const IdFamily srcF = idFamilyOf(src);
    if (srcF == IdFamily::None) return;
    if (srcF == IdFamily::Num && dstF == IdFamily::Num) return;      // rejectNumericConversion said it

    // `char` <-> number is REAL and is rejected — but by `rejectNumericConversion`, not here. Since
    // `char` lowers to its own C name while still answering `cNumBits` (32), that rule already sees two
    // different numeric spellings and says the right thing, pointing at `cast<uint32>` / `cast<char>`,
    // which genuinely are the sanctioned doors. Firing here too would be two diagnostics for one mistake.
    //
    // ONE case it cannot own, and it is the case the whole codepoint distinction dies in: a LITERAL.
    // D2a exempts it there — correctly, for widths — but `char d = 65;` is not a literal written at
    // `char`'s type, it is an integer standing in for a codepoint, and `uint32 n = 'a';` is the same
    // trade in reverse. Same reasoning as the int-literal-into-an-enum case, and the same answer.
    if (srcF == IdFamily::Char || dstF == IdFamily::Char)
        if (!isLiteralExpr(value.get())) return;

    const std::string dstName = idTypeName(dstCType), srcName = idTypeName(src);
    const std::string head = std::string(what) + (isInit ? " is declared `" : " expects `") + dstName
                           + "`, so it cannot be " + (isInit ? "initialized with " : "given ");

    // Each crossing names the door OUT, because each has a different one — and getting that wrong is how
    // `cast<A>(n)` came to be refused with a careful diagnostic while `A a = n;` sailed past. The enum
    // directions are NOT symmetric: enum -> int is total (`cast<int32>(Code::Bad)` folds, and
    // tests/try_cast_enum.kama says so), while int -> enum is fallible by construction, which is the
    // whole reason `try cast` exists.
    if (srcF == IdFamily::Enum && dstF == IdFamily::Enum)
        unsupported((head + "a `" + srcName + "` — these are two distinct enums, and sharing a tag width "
                     "does not make a value of one name a variant of the other. `match` on it, or write "
                     "the `" + dstName + "` variant you mean").c_str(), line);
    else if (srcF == IdFamily::Enum && dstF == IdFamily::Num)
        unsupported((head + "a `" + srcName + "` — an enum is not its underlying integer. That direction "
                     "is total, so convert it explicitly: `cast<" + dstName + ">(…)`").c_str(), line);
    else if (srcF == IdFamily::Num && dstF == IdFamily::Enum)
        unsupported((head + "a `" + srcName + "` — an integer names no variant of `" + dstName + "` until "
                     "it has been checked against them. Write the variant (`" + dstName + "::…`), or "
                     "`try cast<" + dstName + ">(…)` for a value from outside").c_str(), line);
    else if (srcF == IdFamily::Sig && dstF == IdFamily::Sig)
        unsupported((head + "a `" + srcName + "` — these are two distinct signature types" + sigShapeNote(src, dstCType)
                     + ". A function pointer is not converted; declare the value at the signature it is "
                       "called through").c_str(), line);
    // Only literals reach here (the non-literal crossings went back to `rejectNumericConversion` above),
    // so the message is about what the literal MEANS rather than about a conversion. `char` is a
    // codepoint: `'A'` is how one is written, and an integer is one only after somebody decides it is.
    else if (dstF == IdFamily::Char)
        unsupported((head + "a `" + srcName + "` — a `char` is one Unicode codepoint, not a number. Write "
                     "the character (`'A'`), or `cast<char>(…)` if the integer really is a scalar "
                     "value").c_str(), line);
    else if (srcF == IdFamily::Char)
        unsupported((head + "a `" + srcName + "` — a `char` is one Unicode codepoint, not a number. "
                     "Convert it explicitly: `cast<" + dstName + ">(…)`").c_str(), line);
    else
        unsupported((head + "a `" + srcName + "`").c_str(), line);
}

// Milestone 6, the OPERAND half — the seventh position. D2 read literally: mixing two numeric types in
// one expression is an implicit conversion just as surely as `int8 a = big` is, so it is an error.
// `i32 + u8` does not compile in Rust (`Add<u8>` is not implemented for `i32`), nor in Swift, nor in Go.
//
// The exemptions are the rule's whole content, and each is a decision:
//
//   SHIFT — exempt. The right operand is a COUNT, not a co-operand; Rust implements `Shl<Rhs>` for every
//     integer pair and C promotes each side independently. Requiring agreement would be a rule about
//     nothing, and it would break `lib/std/num/fixed.kama` (an `int64` shifted by a `const F: int32`,
//     eight times over) and `json.kama`'s `(c >> 4ui8)`. The result type still comes from the left.
//   COMPARISON — INCLUDED. Rust rejects `1i32 == 1u8`, and this is the rule's highest safety payoff:
//     C's `-1 < 1u32` is FALSE, which is the whole reason `-Wsign-compare` exists.
//   LITERAL — exempt, and typed by the OTHER OPERAND. That is D2a extended from a hand-off to an
//     operand, and without it the corpus would drown in suffixes: `v < 10` on a `uint8` would need
//     `10ui8`. A wide unsuffixed literal is claimed here too, which is the third caller
//     `governWideLiterals` needed — `int64 x; x > 4294967295` was a parse error whose own message said
//     "give it a destination whose type it can take", and under this rule the other operand is one.
//   BOTH literals — exempt. Neither is the other's destination; the hand-off types the whole expression.
//   UNKNOWN — silent, as everywhere else in this campaign.
void CEmitter::rejectMixedOperands(int opToken, SharedExpression lhs, SharedExpression rhs,
                                   const std::string& opName, int line)
{
    if (!lhs || !rhs) return;
    if (opToken == LTLT || opToken == GTGT) return;          // a shift count is not a co-operand

    const bool lLit = isLiteralExpr(lhs.get()), rLit = isLiteralExpr(rhs.get());
    if (lLit && rLit) return;                                // the hand-off types the whole expression

    std::string lt = typeOfExpr(lhs), rt = typeOfExpr(rhs);

    // ENUM OPERANDS, ahead of everything below — including the literal branch, which would otherwise
    // return silently on `a + 1` (it bails when the non-literal side is not a C numeric spelling, and an
    // enum never is).
    //
    // An enum's values are NAMED VARIANTS, not numbers that happen to have names, so arithmetic over them
    // is not a narrower version of integer arithmetic — it has no meaning at all. `a + A::A1` compiled and
    // yielded an `A` that is no declared variant: a value of an enum type that `match` cannot handle, in
    // a language where `match` is the one construct that reads an enum. ORDERING goes the same way for a
    // second, independent reason — comparison in kama is a contract (`<` lowers to `Comparable.compareTo`)
    // — so an enum with an order says so by implementing it.
    //
    // `==`/`!=` between two values of the SAME enum is the one operator that survives, and it must: it is
    // how every `match`-free variant test is written. Across two DIFFERENT enums it is the sharpest form
    // of the identity hole, so it falls through to the crossing message below.
    if (idFamilyOf(lt) == IdFamily::Enum || idFamilyOf(rt) == IdFamily::Enum) {
        const bool isEq = (opToken == EQEQ || opToken == NOTEQ);
        if (isEq && lt == rt) return;                        // the one meaningful operator over an enum
        if (!isEq) {
            const std::string& et = idFamilyOf(lt) == IdFamily::Enum ? lt : rt;
            const std::string  en = idTypeName(et);
            if (isComparisonToken(opToken))
                unsupported(("`" + opName + "` has no meaning over enum `" + en + "` — comparison in kama "
                             "is a contract, so an enum with an order implements `Comparable`. To order "
                             "by the underlying value, `match` it to a number first").c_str(), line);
            else
                unsupported(("`" + opName + "` has no meaning over enum `" + en + "` — its values are "
                             "named variants, not numbers, and the result would be an `" + en + "` that is "
                             "no declared variant. `match` it to a number first, or `cast<…>` it").c_str(),
                            line);
            return;
        }
    }

    // A literal takes the other operand's type. Claim any wide unsuffixed literal against it first —
    // otherwise `governWideLiterals`' end-of-emit report fires on a literal this rule just legitimized —
    // then range-check it there, which is the same predicate the hand-off uses.
    if (lLit != rLit) {
        SharedExpression lit = lLit ? lhs : rhs;
        const std::string& otherT = lLit ? rt : lt;
        if (otherT.empty() || !(cNumBits(otherT) || cNumTargetWidth(otherT))) return;
        governWideLiterals(lit);
        rejectConstOutOfRange(otherT, lit, ("an operand of `" + opName + "`").c_str(), false, line);
        return;
    }

    if (lt.empty() || rt.empty() || lt == rt) return;

    // IDENTITY, ahead of the numeric bail below — which is exactly where `a == b` across two enums used
    // to escape. Its own comment names the escapee ("`string + string`, a bool, AN ENUM"), and for `==`
    // that silence is not a missing niggle: two enums of DIFFERENT widths compare equal through it and
    // the program takes the wrong branch, in a language whose comparison model is otherwise a contract.
    {
        const IdFamily lf = idFamilyOf(lt), rf = idFamilyOf(rt);
        if (lf != IdFamily::None && rf != IdFamily::None
            && !(lf == IdFamily::Num && rf == IdFamily::Num)) {   // Num/Num is the numeric rule's
            unsupported(("`" + opName + "` needs both operands to have the same type, and the left is `"
                         + idTypeName(lt) + "` while the right is `" + idTypeName(rt)
                         + "` — these are two distinct types that happen to share a representation, so "
                           "the comparison C performs is not the one written here").c_str(), line);
            return;
        }
    }

    if (!(cNumBits(lt) || cNumTargetWidth(lt))) return;      // `string + string`, a bool, an enum
    if (!(cNumBits(rt) || cNumTargetWidth(rt))) return;

    unsupported(("`" + opName + "` needs both operands to have the same type, and the left is `"
                 + primKeyOfCType(lt) + "` while the right is `"
                 + primKeyOfCType(rt) + "` — kama has no implicit numeric conversion. "
                 "Convert one side (`cast<" + primKeyOfCType(lt) + ">(…)` or `cast<"
                 + primKeyOfCType(rt) + ">(…)`)").c_str(), line);
}

// A user class handed to a destination of a DIFFERENT user class. The `ref T` argument path has always
// checked this ("cannot borrow a `X` as `ref Y`"); the BY-VALUE path never did, and neither did an
// assignment, a local initializer or a return. So `Mat4 m = someVec4;` and `takesMat(m: someVec4)` passed
// `kama check` and failed in the C COMPILER, naming mangled struct types at a line in the generated file.
// C's name equivalence means it was always caught eventually — this is a check/build divergence and a
// diagnostic-quality defect, not a soundness hole — but `kama check` promising a clean build and not
// delivering one is the thing the suite's own analysis-agreement phase exists to prevent.
//
// Deliberately narrow: PLAIN user classes only. A smart pointer, an intrinsic collection and a contract
// destination all admit values of other types by design (promotion, `Owned<T>` from `new T`, a contract
// taking every kind), and a generic instance's argument list is how `Optional<Mat4> o = m;` is spelled.
// Each of those is a legal widening, so the rule stops where the widenings start.
bool CEmitter::plainUserClass(const std::string& ct) const
{
    if (ct.empty() || !isClass(ct) || isInterface(ct)) return false;
    if (isSmartPtrClass(ct) || isBindableClass(ct)) return false;
    auto it = _classes.find(ct);
    if (it == _classes.end() || it->second.isIntrinsicColl || it->second.isExternStruct) return false;
    return true;
}

void CEmitter::rejectClassIdentityMismatch(const std::string& dstCType, SharedExpression value,
                                           const char* what, int line)
{
    if (!value) return;
    // Runs inside a generic instantiation too. It was gated on `_typeSubst.empty()` from `0.9.148` to
    // `0.9.184` because it fired on `Owned<T, A>.adoptIn`; that was `lvalueCType` auto-dereferencing
    // `this.alloc` onto the pointee (fixed in its member arm), not a substitution defect.
    const std::string src = exprClass(value);
    // The two stdlib windows. `View<X>` NARROWS to `ConstView<X>` at every sink (the sink spells it —
    // narrowViewValue), the direction kama already takes for `const ref` parameters and `UnsafePtr<T>` →
    // `UnsafeConstPtr<T>`; the reverse would make a read-only window writable, and "unrelated types"
    // would name the wrong problem — the remedy is the writable half, taken where the view was made.
    if (!src.empty() && !dstCType.empty()) {
        if (constViewOf(dstCType, src)) return;
        if (constViewOf(src, dstCType)) {
            unsupported((std::string(what) + " expects a `" + demangleForDisplay(dstCType) + "` — the writable "
                         "window — and a `" + demangleForDisplay(src) + "` is read-only; it does not widen. "
                         "Take the mutable form where the view was made (`viewMut()` / `sliceMut()`)").c_str(), line);
            return;
        }
    }
    // A HEAP OWNER given the very value it would own (`Shared<Pt> p = Pt.make(x: 1)`, `Owned<Geo> g =
    // Geo::Point`). The exemptions below exist for a wrapper that HOLDS a value (`Optional<Pt> o = p`), and
    // they let this through too — into clang, which refused assigning a `Pt` to a handle in every position.
    // A handle is not its pointee and nothing converts one into the other: heap construction says `new`.
    // (A value into a CONTRACT handle — `Owned<Error>`, `Owned<Hashable>` — is a box, and never reaches
    // here: its element is the contract, not the value's own type.)
    {
        const std::string owned = heapOwnerTarget(dstCType);
        const std::string vc = src.empty() ? typeOfExpr(value) : src;
        if (!owned.empty() && !vc.empty() && !isInterface(owned) && (vc == owned || isBaseOf(owned, vc))) {
            const bool isEnum = (_classes.count(vc) && _classes[vc].isVariant) || _enums.count(vc);
            unsupported((std::string(what) + " expects a `" + demangleForDisplay(dstCType) + "`, a heap handle, "
                         "and a `" + demangleForDisplay(vc) + "` value is not one — build it on the heap with `new` ("
                         + (isEnum ? "`new " + demangleForDisplay(vc) + "::Variant(…)`"
                                   : "`new " + demangleForDisplay(vc) + ".make(…)`") + ")").c_str(), line);
            return;
        }
    }
    if (!plainUserClass(dstCType)) return;
    if (src.empty() || src == dstCType || !plainUserClass(src)) return;
    if (isBaseOf(dstCType, src)) return;                       // an inheritance UPCAST is the point of one
    if (!_classes[dstCType].collElemClass.empty()
        && _classes[dstCType].collElemClass == src) return;    // a container/handle over exactly this type
    auto gi = _genericTypeInsts.find(dstCType);                // `Optional<Mat4> o = m;` and its siblings
    auto si = _genericTypeInsts.find(src);
    if (gi != _genericTypeInsts.end()) {
        for (const auto& a : gi->second.typeArgs) if (a && cType(a) == src) return;
        // Two instances of the SAME template. `Shared<Square>` into a `Shared<Shape>` is the smart-pointer
        // upcast, and judging argument variance properly is a separate rule from "these are unrelated
        // types" — so the shared template is where this one stops.
        if (si != _genericTypeInsts.end() && si->second.templateKey == gi->second.templateKey) return;
    }
    // The library heap owners are ordinary generic types, not the intrinsic smart pointers, so
    // `isSmartPtrClass` does not see them: an `Owned<Counter>` handed to a `Counter` parameter borrows its
    // pointee through `Deref`, which is a widening and not a mismatch. Read off the ARGUMENT list so it
    // covers `Owned<Square>` into a `Shape` too, rather than naming the three owner types.
    if (si != _genericTypeInsts.end())
        for (const auto& a : si->second.typeArgs) {
            if (!a) continue;
            const std::string ac = cType(a);
            if (ac == dstCType || isBaseOf(dstCType, ac)) return;
        }
    unsupported((std::string(what) + " expects a `" + demangleForDisplay(dstCType) + "`, so it cannot be "
                 "given a `" + demangleForDisplay(src) + "` — these are unrelated types. Convert it "
                 "explicitly, or take a contract both implement").c_str(), line);
}

void CEmitter::rejectValueKindMismatch(const std::string& dstCType, SharedExpression value,
                                       const char* what, int line)
{
    noteNumericHandoff(dstCType, value, what, line);   // M5a: measure first, then judge
    noteTypeIdentity(dstCType, value, what, line);     // the identity measurement, same discipline
    // Independent of the kind rule below, and ahead of it so its early returns cannot shadow this one.
    // They cannot both fire: a folded integer constant is `Num`, so its kind never mismatches.
    if (!dstCType.empty()) governWideLiterals(value);   // 5b-B, and BEFORE the value is emitted
    rejectConstOutOfRange(dstCType, value, what, false, line);
    rejectNumericConversion(dstCType, value, what, /*isInit*/false, line);   // milestone 6
    rejectTypeIdentityMismatch(dstCType, value, what, /*isInit*/false, line);
    // Binding a FUNCTION NAME to a `fnptr` destination. The identity rule above cannot see this one:
    // `typeOfExpr` has no arm for a bare function name, so it answers "" and the rule takes its
    // documented silent path — which is exactly why every bind position but a local initializer went
    // unchecked. This is the funnel they all share, and it already has the destination type.
    checkFnPtrValueBind(dstCType, value, line);
    rejectClassIdentityMismatch(dstCType, value, what, line);
    const TKind vk = exprKind(value);
    if (vk == TKind::Unknown) return;
    const TKind dk = kindOfCType(dstCType);
    if (dk == TKind::Unknown || dk == vk) return;
    unsupported((std::string(what) + " expects " + kindName(dk) + ", so it cannot be given "
                 + kindName(vk)).c_str(), line);
}

void CEmitter::rejectInitKindMismatch(SharedIdentifier declType, SharedExpression init,
                                      const char* what, int line)
{
    if (_strictNumericScan) {
        noteNumericHandoff(classifierCType(declType), init, what, line);
        noteTypeIdentity(classifierCType(declType), init, what, line);
    }
    // 5b-A, ahead of the kind rule for the reason given at `rejectValueKindMismatch`, and gated on the
    // initializer folding FIRST: this site runs inside `checkDeclaredTypes`, where a type is deliberately
    // half-resolved and the rule below is careful not to lower one unless it must. `constValue` fails in
    // a few dynamic_casts for anything that is not a constant, which is almost every initializer.
    governWideLiterals(init);                           // 5b-B — a declared type is always a destination
    int64_t folded;
    if (init && constValue(init, folded))
        rejectConstOutOfRange(classifierCType(declType), init, what, true, line);
    // Milestone 6. Unlike the range check above this is NOT gated on the initializer folding — a
    // conversion needs no constant, and `int8 a = big;` is the shape the whole rule is named for.
    //
    // The source test is spelled out HERE rather than left to the rule, because an argument is evaluated
    // before the call it is passed to: writing `rejectNumericConversion(classifierCType(declType), …)`
    // would lower the declared type on every initializer in the program, which is exactly what the
    // comment above says this site must not do inside `checkDeclaredTypes`.
    //
    // The identity rule rides the same gate for the same reason, and reads the same `srcT`: a source that
    // owns no identity can never make it fire, so there is no destination worth lowering for it. That
    // covers most initializers in the program.
    if (init) {
        const std::string srcT = typeOfExpr(init);
        if (!srcT.empty() && (cNumBits(srcT) || cNumTargetWidth(srcT)))
            rejectNumericConversion(classifierCType(declType), init, what, /*isInit*/true, line);
        if (idFamilyOf(srcT) != IdFamily::None)
            rejectTypeIdentityMismatch(classifierCType(declType), init, what, /*isInit*/true, line);
        // ...and the CLASS identity rule, which reads `exprClass` rather than `typeOfExpr` and so cannot
        // ride the `srcT` gate above: a user class answers "" from `typeOfExpr` and would never reach it.
        if (plainUserClass(exprClass(init)))
            rejectClassIdentityMismatch(classifierCType(declType), init, what, line);
    }
    // Ask the CHEAP, certain side first. Most initializers are `Unknown`, and returning here keeps this
    // rule from calling `cType` on a declared type at all — which matters in `checkDeclaredTypes`, where
    // a type is deliberately half-resolved.
    const TKind ik = exprKind(init);
    if (ik == TKind::Unknown) return;
    const TKind dk = declTypeKind(declType);
    if (dk == TKind::Unknown || dk == ik) return;

    unsupported((std::string(what) + " is declared `" + *declType->value + "`, so it cannot be initialized "
                 "with " + kindName(ik) + " — " + kindName(dk) + " was expected").c_str(), line);
}

// A type name in a DECLARATION that resolved to nothing. `cType` hands an unresolved name straight back
// (see resolveUserName's "caller handles" tail), and until now no caller did — so a misspelled or
// unimported type sailed through analysis and only failed later in the C compiler, as a confusing
// 'undeclared identifier' against generated code. `kama check` (and the LSP, which shares that path) said
// OK. Two cases, both reported here:
//   - the name IS a real type in another namespace  -> missing import, name the namespace;
//   - the name is nowhere at all                    -> unknown type.
// Only for a BARE, non-builtin name. The caller passes what `cType` produced, and anything cType mapped to
// a different spelling is by definition known — that covers primitives, `UnsafePtr`/`usize`/`isize`, `This`,
// generic instances and defaulted-generic bare names WITHOUT re-deriving cType's special cases here (the
// first cut did re-derive them and promptly flagged `UnsafePtr`). Type params / FFI extern names are excluded
// explicitly (see isTypeParamName / _externNames).
//
// A GENERIC head reaches here too. It used to bail outright on `genericArg`, which meant
// `Nonexistent<int32> a;` passed `kama check` clean while the bare `Nonexistent a;` was reported — the
// spelling with the *more* type information got the *less* checking. That same hole is what let the old
// `Ptr<T>` spelling survive `check` after the rename. No re-derivation is needed to close it: `cType` maps a
// resolved generic to its mangled instance, so the `cTypeResult != name` guard below already lets every
// known one through, and only an unresolved head comes back as its own bare spelling. So this judges ONE
// node: each caller walks the type arguments under it (`forEachTypeArg`) and calls this per node.
void CEmitter::checkTypeResolves(SharedIdentifier type, const std::string& cTypeResult,
                                 const char* what, int line, const char* noun)
{
    if (!type || !type->value || type->builtInVal != 0) return;
    const std::string& name = *type->value;
    if (cTypeResult != name) return;                  // cType mapped it somewhere -> known
    const std::string& ty = name;
    if (isClass(ty) || isInterface(ty) || isEnum(ty) || isSigType(ty)) return;
    if (_genericTypes.count(ty) || _genericContracts.count(ty) || _externNames.count(ty)) return;
    if (isTypeParamName(ty)) return;
    // RETIRED SPELLING. `uint` never existed in kama, but a C/Go reader will try it, and "unknown type"
    // would send them looking for a missing import instead of a different spelling — so the replacement is
    // named rather than the absence reported.
    //
    // ⚠️ `uint` IS THE ONLY ONE LEFT HERE, and the asymmetry is deliberate. `int`, `double` and `float`
    // used to share this arm; they are C KEYWORDS, so since §2e.28 the lexer refuses them one step earlier
    // — kama reserves the whole C set, because a kama name that is a C keyword emits C that does not
    // compile. Their width guidance moved into that message rather than dying with the arm (`cReservedWhy`,
    // kama.l). `uint` is not a C keyword, is not reserved, and so still arrives here.
    // tools/check-c-keywords.sh asserts both halves so this cannot be tidied into "consistency" by mistake.
    if (ty == "uint") {
        unsupported((std::string("`uint` is not a kama type in ") + what + " — write `uint32` for a fixed "
                     "32-bit integer, or `usize` for a platform-width size crossing into C (`sizeof`, an "
                     "allocation, an `extern fn`)").c_str(), line);
        return;
    }
    const bool reported = reportDeclaredElsewhere(noun, name, [&](const std::string& k) { return isTypeKey(k); },
                                                  what, line);
    if (!reported)
        unsupported((std::string("unknown ") + noun + " `" + name + "` in " + what
                     + " — no such " + noun + " is declared or imported").c_str(), line, name);
}

bool CEmitter::isTypeKey(const std::string& k) const
{
    return _classes.count(k) || _enums.count(k) || _interfaces.count(k) || _genericTypes.count(k)
        || _genericContracts.count(k);
}

// A type written in a BODY — a cast target, a `sizeof` operand, a turbofish argument, a local's type —
// held to the rules a declared type meets in `checkDeclaredTypes`, over the whole spelling: every name
// resolves (or is reported with the import that fixes it), every name is in reach of this file, and a
// `#(K)` constant is too.
//
// Judged HERE, where the emitter resolves the type, rather than by a second walk over bodies: in this
// compiler analysis IS emission, every other body rule lives in this walk, and an uncalled generic's body
// is re-emitted by the template probe, so it is judged as well (KR-46, decided 2026-09-14). A declaration
// that `@compileFor` drops is judged by neither walk — its own open question, not this one.
void CEmitter::checkBodyType(const SharedIdentifier& t, const char* what, int line)
{
    if (!t || !t->value) return;
    // A C spelling this file's own `extern fn` introduced (see `_externCSpellings`) is the header's to judge.
    if (!t->qualifier || t->qualifier->empty()) {
        auto cs = _externCSpellings.find(refFilePath());
        if (cs != _externCSpellings.end() && cs->second.count(*t->value)) return;
    }
    checkTypeResolves(t, cType(t), what, line);
    // A substituted node names no source text, so no file wrote it (see `resolveUserName`).
    if (!t->synthesized)
        checkReach(resolveUserNameImpl(*t->value, t->qualifier), *t->value, what, line, refFilePath(),
                   t->qualifier && !t->qualifier->empty());
    forEachTypeArg(t, [&](const SharedIdentifier& a) { checkBodyType(a, what, line); });
    forEachConstArgName(t, [&](const SharedIdentifier& k) { constArgReaches(k, what, refFilePath()); });
}

// The TYPE arguments a spelling writes — its `<…>` entries and a qualifier's `::<…>` — never a `#(…)` value,
// which the parser appends to the same vector after `nTypeArgs`.
void CEmitter::forEachTypeArg(const SharedIdentifier& t, const std::function<void(const SharedIdentifier&)>& f)
{
    if (!t) return;
    if (t->genericArgs) {
        for (size_t i = 0; i < t->genericArgs->size(); ++i) {
            const SharedIdentifier& a = (*t->genericArgs)[i];
            if (a && !a->constArgValue && (t->nTypeArgs < 0 || (int)i < t->nTypeArgs)) f(a);
        }
    } else if (t->genericArg) f(t->genericArg);
    if (t->qualifierGenericArgs) for (auto& a : *t->qualifierGenericArgs) if (a) f(a);
}

// The `#(…)` values a spelling writes that are NAMES (`#(K)`, `#(geo::CAP)`) — a literal or an expression
// needs no resolution.
void CEmitter::forEachConstArgName(const SharedIdentifier& t, const std::function<void(const SharedIdentifier&)>& f)
{
    if (!t || !t->genericArgs || t->nTypeArgs < 0) return;
    for (size_t i = (size_t)t->nTypeArgs; i < t->genericArgs->size(); ++i) {
        const SharedIdentifier& k = (*t->genericArgs)[i];
        if (k && k->value && !k->constArgValue && !k->genericArg) f(k);
    }
}

// A `#(K)` naming a module constant, judged for reach from `refFile` like any other name. False when `K`
// names no module constant — a comptime parameter, a type constant, or nothing — which the caller answers.
bool CEmitter::constArgReaches(const SharedIdentifier& k, const char* what, const std::string& refFile)
{
    const std::string key = resolveModuleVar(*k->value, k->qualifier);
    if (key.empty()) return false;
    checkReach(key, *k->value, what, k->line, refFile, k->qualifier && !k->qualifier->empty());
    return true;
}

bool CEmitter::isComptimeParamHere(const std::string& nm) const
{
    // Function half of the probe: every param of the template is in _probeTypeParams, and only the TYPE
    // params receive an opaque binding in _typeSubst (buildOpaqueParams) — so "probed and unbound" is
    // exactly "const".
    if (_probingTemplate && _probeTypeParams.count(nm) && !_typeSubst.count(nm)) return true;
    // An instantiated generic function: its template says which of its params are const.
    auto gi = _genericInsts.find(_currentFunc);
    if (gi != _genericInsts.end()) {
        auto t = _generics.find(gi->second.templateKey);
        if (t != _generics.end() && t->second && t->second->comptimeParams)
            for (auto& p : *t->second->comptimeParams) if (p && *p == nm) return true;
    }
    // A generic TYPE's method — instantiated, or the probe's opaque instance (whose `N` slot holds the
    // valueless probeConstArg placeholder): the template's const slots say which names are values.
    if (_currentClass && _currentClass->isGenericInst) {
        auto of = _genericTypeInstOf.find(_currentClass->name);
        if (of != _genericTypeInstOf.end()) {
            auto ps = _genericTypeParams.find(of->second);
            auto ct = _genericTypeConstTypes.find(of->second);
            if (ps != _genericTypeParams.end() && ct != _genericTypeConstTypes.end())
                for (size_t i = 0; i < ps->second.size() && i < ct->second.size(); ++i)
                    if (ps->second[i] == nm && ct->second[i]) return true;
        }
    }
    return false;
}

void CEmitter::rejectUnresolvedName(IdentifierNode* v, const std::string& nm)
{
    const int line = v->line;
    if (v->qualifier && !v->qualifier->empty()) {
        const std::string& head = *(*v->qualifier)[0];
        const std::string& last = *v->qualifier->back();
        std::string path = head;
        for (size_t i = 1; i < v->qualifier->size(); ++i) path += "::" + *(*v->qualifier)[i];
        path += "::" + nm;
        // A value-headed `::` was already refused (it names the `.` spelling); one sentence per line.
        if (isValueName(head, nullptr)) return;
        auto rest = std::make_shared<StringList>();
        for (size_t i = 0; i + 1 < v->qualifier->size(); ++i) rest->push_back((*v->qualifier)[i]);
        const std::string t = resolveUserName(last, rest);
        ClassInfo* ci = nullptr;
        if (_classes.count(t))            ci = &_classes[t];
        else if (_genericTypes.count(t))  ci = &_genericTypes[t];
        if (_enums.count(t) || (ci && ci->isVariant)) {
            unsupported(("`" + last + "` has no variant `" + nm + "`").c_str(), line, nm);
            return;
        }
        if (ci) {
            ClassInfo* owner = nullptr;
            MethodInfo* mi = nullptr;
            if (findFieldOwner(ci, nm))
                unsupported(("`" + path + "` — " + dotOnTypeAdvice(DotMemberKind::Field, last, t, nm)).c_str(), line);
            else if ((mi = findMethod(ci, nm, &owner)))
                unsupported(("`" + path + "` — " + dotOnTypeAdvice(mi->isCtor ? DotMemberKind::Ctor
                                                                  : mi->isStatic ? DotMemberKind::Static
                                                                  : DotMemberKind::Method, last, t, nm)).c_str(), line);
            else if (!rejectUnprovenBound(t, nm, line))
                unsupported(("`" + last + "` has no member `" + nm + "`").c_str(), line, nm);
            return;
        }
        // `Natural<T>::compare` under a probe names an instance that does not exist yet — the existing
        // bucket for that shape.
        if (_probeTypeParams.count(head) || _probeTypeParams.count(last)) { deferUnknownWhileProbing(DK_ScopeQual); return; }
        if (v->qualifier->size() == 1
            && reportDeclaredElsewhere("type", head, [&](const std::string& k) { return isTypeKey(k); },
                                       "this reference", line))
            return;
        unsupported(("cannot resolve `" + path + "` — `" + head + "` is not a type or module in reach here").c_str(),
                    line, head);
        return;
    }
    // Bare. A TYPE where a value is expected says which kind of type, and what a value of it looks like.
    const std::string t = resolveUserName(nm, nullptr);
    auto ei = _enums.find(t);
    if (ei != _enums.end()) {
        const std::string ex = ei->second.members.empty() ? "…" : ei->second.members.front().name;
        unsupported(("`" + nm + "` is an enum type, not a value — name one of its variants (`" + nm + "::" + ex + "`)").c_str(), line);
        return;
    }
    if (_classes.count(t) || _genericTypes.count(t)) {
        unsupported(("`" + nm + "` is a type, not a value — construct one (`" + nm + ".<ctor>(...)`) or name an "
                     "associated item (`" + nm + "::NAME`)").c_str(), line);
        return;
    }
    if (_interfaces.count(t)) { unsupported(("`" + nm + "` is a contract, not a value").c_str(), line); return; }
    if (_sigs.count(t))       { unsupported(("`" + nm + "` is a function signature, not a value").c_str(), line); return; }
    if (_typeSubst.count(nm) || _probeTypeParams.count(nm)) {
        unsupported(("`" + nm + "` is a type parameter, not a value — a type has no value of its own; construct one "
                     "through a bound (`" + nm + ".<ctor>(...)`) or take a `" + nm + "` parameter").c_str(), line);
        return;
    }
    // Not a type either. The two likeliest misspellings of something that DOES exist come first.
    if (_currentClass && _typeConsts.count(_currentClass->name + "::" + nm)) {
        unsupported(("`" + nm + "` is a `comptime` constant of `" + _currentClass->name + "` — read it as `"
                     + _currentClass->name + "::" + nm + "`").c_str(), line);
        return;
    }
    for (auto& kv : _enums)
        for (auto& m : kv.second.members)
            if (m.name == nm) {
                unsupported(("`" + nm + "` is a variant of `" + kv.first + "` — write `" + kv.first + "::" + nm
                             + "`").c_str(), line);
                return;
            }
    if (reportDeclaredElsewhere("constant", nm, [&](const std::string& k) { return _moduleStatics.count(k) > 0; },
                                "this reference", line))
        return;
    unsupported(("cannot resolve `" + nm + "` — no local, parameter, field, function, module `static`/`comptime` "
                 "or type of that name is in reach here").c_str(), line, nm);
}

// A type node the emitter invents. Lazily creates the shared synth context on first use (several call
// sites used to do that inline). See ASTNode::synthesized for what the flag buys.
SharedIdentifier CEmitter::synthId(const std::string& name, int builtInVal)
{
    if (!_synthCtx) _synthCtx = std::make_shared<CodeGenContext>(std::make_shared<std::string>("<generic>"));
    auto n = std::make_shared<IdentifierNode>(*_synthCtx, std::make_shared<std::string>(name), builtInVal);
    n->synthesized = true;
    return n;
}

// A copy of a parsed node, re-tagged: the ORIGINAL is source text and stays indexable, but this copy is an
// emitter artifact (a substituted or absolutized type) and is frequently a temporary.
SharedIdentifier CEmitter::synthClone(const IdentifierNode& src)
{
    auto n = std::make_shared<IdentifierNode>(src);
    n->synthesized = true;
    return n;
}

// Does this statement DEFINITELY leave the enclosing function — by returning, or by diverging?
//
// Deliberately one-sided: it answers "yes, provably" and otherwise "no". Every construct it does not model
// contributes `false`, which is safe because a BLOCK is satisfied by ANY statement that returns (anything
// after one is unreachable) — so an unmodeled statement can only fail to help, never wrongly satisfy. The
// cost of the other bias would be rejecting valid code, which is far worse than the status quo of letting
// the C compiler catch it.
bool CEmitter::alwaysExits(const SharedStatement& s) const
{
    if (!s) return false;
    ASTNode* n = s.get();
    if (dynamic_cast<ReturnNode*>(n)) return true;
    if (auto* b = dynamic_cast<BlockNode*>(n)) {
        if (b->statements) for (auto& st : *b->statements) if (alwaysExits(st)) return true;
        return false;
    }
    if (auto* sc = dynamic_cast<ScopeNode*>(n)) return alwaysExits(sc->body);  // `scope { … }` always runs
    if (auto* bn = dynamic_cast<BorrowNode*>(n)) return alwaysExits(bn->body); // `borrow … { … }` always runs
    // An `if` only guarantees an exit when BOTH arms do — a bare `if` may fall through by design.
    if (auto* f = dynamic_cast<IfNode*>(n))
        return f->elseStatement && alwaysExits(f->ifStatement) && alwaysExits(f->elseStatement);
    // A `match` is exhaustive by construction (the emitter rejects a non-exhaustive one), so it exits when
    // every arm does. An arm is either a single expression or a block.
    if (auto* m = dynamic_cast<MatchNode*>(n)) {
        if (!m->arms || m->arms->empty()) return false;
        for (auto& a : *m->arms) {
            if (!a) return false;
            if (a->block) { if (!alwaysExits(a->block)) return false; }
            else if (a->body) { if (!exprDiverges(a->body.get())) return false; }
            else return false;
        }
        return true;
    }
    // A loop with no exit condition never falls out of the bottom — `while (true)` / `for (;;)` is how a
    // scheduler or an embedded main is written. A `break` targeting it would escape, so only a
    // break-free body counts.
    if (auto* w = dynamic_cast<WhileNode*>(n))
        return isLiteralTrue(w->booleanExpression) && !hasLoopBreak(w->whileStatement);
    if (auto* fo = dynamic_cast<ForNode*>(n))
        return !fo->booleanExpression && !hasLoopBreak(fo->body);
    // A bare `panic(…)` never returns. An invocation IS an ExpressionStatementNode, so a call in statement
    // position arrives here directly.
    return exprDiverges(n);
}

// `panic(...)` — the one call the language knows never returns.
bool CEmitter::exprDiverges(const ASTNode* n) const
{
    auto* inv = dynamic_cast<const InvocationNode*>(n);
    // A BARE call keeps its name in `identifier`; `expression` is the RECEIVER and is null for one.
    if (!inv || inv->expression || !inv->identifier || !inv->identifier->value) return false;
    if (*inv->identifier->value != "panic") return false;
    const SharedStringList& q = inv->identifier->qualifier;
    return !q || q->empty() || (q->size() == 1 && *(*q)[0] == "global");   // `panic` or `global::panic`
}

// Is there a `break` that would escape THIS loop? Nested loops swallow their own, and a `break` inside a
// `match` arm belongs to the match, not the loop — but counting those merely makes the answer "cannot
// prove it diverges", which is the safe direction.
bool CEmitter::hasLoopBreak(const SharedStatement& s) const
{
    if (!s) return false;
    ASTNode* n = s.get();
    if (dynamic_cast<BreakNode*>(n)) return true;
    if (dynamic_cast<WhileNode*>(n) || dynamic_cast<ForNode*>(n) ||
        dynamic_cast<DoWhileNode*>(n) || dynamic_cast<ForEachNode*>(n)) return false;   // its own break
    if (auto* b = dynamic_cast<BlockNode*>(n)) {
        if (b->statements) for (auto& st : *b->statements) if (hasLoopBreak(st)) return true;
        return false;
    }
    if (auto* sc = dynamic_cast<ScopeNode*>(n)) return hasLoopBreak(sc->body);
    if (auto* bn = dynamic_cast<BorrowNode*>(n)) return hasLoopBreak(bn->body);
    if (auto* f = dynamic_cast<IfNode*>(n)) return hasLoopBreak(f->ifStatement) || hasLoopBreak(f->elseStatement);
    if (auto* m = dynamic_cast<MatchNode*>(n)) {
        if (m->arms) for (auto& a : *m->arms) if (a && a->block && hasLoopBreak(a->block)) return true;
        return false;
    }
    return false;
}

// A `while (true)` condition — a literal `true`, nothing cleverer.
bool CEmitter::isLiteralTrue(const SharedExpression& e) const
{
    auto* b = dynamic_cast<const BooleanNode*>(e.get());
    return b && b->value;
}

// A non-void function whose body can reach the closing brace without returning. Until this existed the
// only thing catching it was CLANG (`-Werror=return-type`), so the diagnostic named generated C and
// `kama check` — the path the language server runs — reported the file clean. A language server calling a
// broken file clean is the one failure mode it must not have.
void CEmitter::checkReturns(FunctionDeclarationNode* fn, ClassMethodDeclarationNode* md, const char* what)
{
    SharedIdentifier rt = fn ? fn->returnType : md->returnType;
    SharedBlock body    = fn ? fn->block      : md->body;
    if (!rt || !body) return;                                   // a ctor / prototype / extern — nothing to check
    if (rt->builtInVal == IDENTIFIER_VOID_VAL) return;          // void may fall off the end
    if (md && md->isCtor) return;                               // a named ctor has its own completeness check
    if (alwaysExits(body)) return;
    const std::string& nm = fn ? (fn->name && fn->name->value ? *fn->name->value : "")
                               : (md->name && md->name->value ? *md->name->value : "");
    unsupported((std::string(what) + " `" + nm + "` can reach the end of its body without returning a value "
                 "— every path out of a non-`void` function must `return` (or diverge: `panic`, or a loop "
                 "with no exit)").c_str(), body->line);
}

// The file that DECLARED a resolved symbol, or "" when the key names nothing this emitter collected.
// "" is the safe answer in both directions: an unresolved name is someone else's diagnostic, and a
// synthesized key (a generic INSTANCE, an FFI spelling) has no source file to be judged against.
// ⚠️ An FFI name is deliberately "" — and it is not a nicety, it is required. An `extern fn` / `extern
// class` keeps its LITERAL C spelling, so it is never scope-prefixed and every file that declares one
// collapses onto a single table entry whose `declFile` is whichever file happened to be collected last.
// Repeating `extern fn memset` in three files is the idiom SPEC prescribes ("a name a file declares
// itself is satisfied there and pulls in no sibling"), so judging that entry by file would reject the
// two losers of a race. An external C symbol is not a module symbol and has no export to check.
std::string CEmitter::declFileOf(const std::string& key) const
{
    auto c  = _classes.find(key);
    if (c  != _classes.end())           return c->second.isExternStruct ? std::string() : c->second.declFile;
    auto e  = _enums.find(key);             if (e  != _enums.end())             return e->second.declFile;
    auto i  = _interfaces.find(key);        if (i  != _interfaces.end())        return i->second.declFile;
    auto gt = _genericTypes.find(key);      if (gt != _genericTypes.end())      return gt->second.declFile;
    auto gc = _genericContracts.find(key);  if (gc != _genericContracts.end())  return gc->second.declFile;
    auto s  = _sigs.find(key);              if (s  != _sigs.end())              return s->second.declFile;
    auto f  = _funcs.find(key);
    if (f  != _funcs.end())             return isExtern(f->second.node) ? std::string() : f->second.declFile;
    auto mv = _moduleVarFile.find(key);     if (mv != _moduleVarFile.end())     return mv->second;
    return std::string();
}

// THE FILE RUNG. A file may name only what it declares or imports; `export { … };` is the outbound half.
// So a reference from file R to a symbol declared in file D != R requires that D exported it — in EVERY
// position, which is what this being one predicate rather than a list of emission-site checks buys.
//
// This replaces a per-MODULE rule. Privacy used to stop at the module: a directory module's files shared
// one namespace and saw each other's private names, so `export` gated only the way out of the module.
// Under the decided model (SPEC.md § Modules) the file is the unit of privacy — which is the
// rung Go never had and the reason a large Go package becomes a soup where any file reaches any
// unexported identifier. The `visibility` key governs reach BEYOND the module and nothing else.
//
// ⚠️ `refFile` is THE FILE THE REFERENCE IS WRITTEN IN, and it is not always the file whose NsCtx is
// installed. Generic instantiation restores the TEMPLATE's context to resolve the template body, while
// the type ARGUMENTS being substituted were written at the instantiation site — so judging by `_nsCtx`
// rejected `View<Transform>` in a single-file fixture, blaming that fixture for not exporting its own
// type. Expression positions therefore pass `_refUnit` (the recorder's notion, already save/restored
// around nested generic emission), and the declaration walk passes `_nsCtx.unitPath`, which is right
// there because that loop installs one unit's context at a time.
//
// Deliberately blind in four directions, each load-bearing:
//   * only a resolved USER declaration (`declFileOf` non-empty) — an unresolved name and an `extern`
//     C spelling are not module symbols;
//   * a declaring file starting with `<` is compiler-owned (the prelude floor, the embedded
//     `std::memory` triad). Those are built-in intrinsics: always in scope, never imported, exempt;
//   * an EMPTY `refFile` means nobody could say where the reference was written (a header pass, a
//     synthesized node). Silence beats a wrong file in a diagnostic that names one;
//   * before `_exported` is populated it cannot answer, so `_exportedReady` gates it. Collection
//     resolves names too, and judging them against an empty export set would reject everything.
void CEmitter::checkReach(const std::string& key, const std::string& spelled, const char* what,
                          int line, const std::string& refFile, bool qualified)
{
    if (!_exportedReady || refFile.empty()) return;
    // THE FFI ARM, and it runs BEFORE the `declFile.empty()` return because that return is exactly the
    // hole: `declFileOf` reports "" for an extern on purpose (one table entry, many declaring files), so
    // every extern name used to walk straight out of this predicate. A file could call `malloc` having
    // neither declared nor imported it — measured at 0.9.84, and it built, linked and ran.
    //
    // An extern is an ordinary FILE-PRIVATE declaration: the file that declares it may name it, and another
    // file reaches it the way it reaches any name — the declaring file `export`s it and this file `import`s
    // it (or spells it qualified, which the resolver only resolves through a module that exports it).
    // Repeating the declaration stays legal: two declarations are two bindings of one C symbol, and the
    // agreement checks in collectSignatures/collectClasses hold them identical. (Until 0.9.329 the rule was
    // DECLARE-only — "an extern is not a module symbol". Its reason was the C symbol having no module
    // surface; a declaration does have one, and calling an extern already requires `unsafe`, so exporting
    // one widens nothing safe code can do.)
    //
    // No `<`-prefixed exemption here, deliberately. The prelude declares `malloc`/`free` for
    // `GlobalAllocator`, and letting a compiler-owned declaration satisfy every file would leave the same
    // leak with a shorter reach — a user program would still get libc's allocator for free, unwritten.
    {
        auto ext = _externDeclSites.find(key);
        if (ext != _externDeclSites.end()) {
            if (ext->second.count(refFile)) return;                        // declared right here — always
            if (qualified) return;                                         // resolved only through an exporting module
            const NsCtx* rc = nullptr;
            if (_nsCtx.unitPath == refFile) rc = &_nsCtx;
            else for (auto& kv : _unitCtx) if (kv.second.unitPath == refFile) { rc = &kv.second; break; }
            if (rc) for (auto& sa : rc->symbolAliases) if (importedExtern(sa.second) == key) return;   // imported
            std::string other;   // a USER file that declares it, when there is one — the prelude's is not importable
            for (auto& f : ext->second) if (!f.empty() && f[0] != '<') { other = f; break; }
            const bool offered = _externExportedBy.count(key) != 0;
            unsupported(("`" + spelled + "` is an `extern` "
                         + (other.empty() ? std::string("this file neither declares nor imports") + " — " + what
                                            + " cannot name it (the prelude's own declaration is not offered to "
                                              "user code). Declare it in this file"
                                          : "declared in `" + other + "`, and this file neither declares nor "
                                            "imports it — " + what + " cannot name it. "
                                            + (offered ? "Import it (`import { … };`) from the file that exports it"
                                                       : "Export it from the file that declares it and import it here")
                                            + ", or repeat the declaration in this file")).c_str(), line);
            return;
        }
    }
    const std::string declFile = declFileOf(key);
    if (declFile.empty() || declFile[0] == '<') return;      // unresolved, synthesized, or compiler-owned
    if (declFile == refFile) return;                         // its own file — always
    // ...and its own file AGAIN, when a generic instantiation has installed the TEMPLATE's context under a
    // caller's `refFile`. `sorted_map.kama:31` spells `BTreeNode` inside `BTreeNode` — the template's own
    // internal self-reference — and re-walking it for a user's `BTreeNode<int32,int32>` judged that line
    // against the USER's file: `tests/xfail/export_qualified_ref_local.kama:31`, in a 19-line file. The
    // inbound clause below already defends itself this way ("_nsCtx ... is NOT always the file being
    // judged"); the outbound one did not, so the same instantiation produced a third, impossible copy of a
    // diagnostic it had already reported correctly twice.
    if (!_nsCtx.unitPath.empty() && _nsCtx.unitPath != refFile && declFile == _nsCtx.unitPath) return;
    // §2c FOR A QUALIFIED REFERENCE. The import site above covers what a file imports; a qualified
    // spelling reaches a module WITHOUT importing it (that is deliberate — see the inbound clause below),
    // so the same rung has to be asked here or the manifest key is enforced in one position and not the
    // other, which is the shape of §1a claim 3 all over again.
    if (_moduleVisible) {
        const size_t cut = key.rfind("__");
        auto mn = cut == std::string::npos ? _moduleNames.end() : _moduleNames.find(key.substr(0, cut));
        if (mn != _moduleNames.end() && !_moduleVisible(_nsCtx.module, mn->second)) {
            unsupported(("module `" + mn->second + "` is not visible from "
                         + (_nsCtx.module.empty() ? std::string("a file in no module")
                                                  : "`" + _nsCtx.module + "`")
                         + " — its `visibility` in `kama.json` does not name this module, and a qualified "
                           "spelling reaches no further than an `import` would").c_str(), line);
            return;
        }
    }
    if (!_exported.count(key)) {                             // OUTBOUND: it never left its file
        unsupported(("`" + spelled + "` is not exported by `" + declFile + "`, so " + what
                     + " cannot name it — visibility is per FILE, and a name leaves its file only through "
                       "that file's `export { … };`. Add it there if it is meant to be reachable").c_str(),
                    line);
        return;
    }
    // INBOUND: a file names only what it declares or imports, so an `export` is an offer and an `import`
    // is the acceptance. Restricted to UNQUALIFIED spellings on purpose: a qualified `geo::area()` names
    // its module at the use site, so the provenance this rung protects is already written down — it is
    // the bare name whose origin was ambient. (A bare `import a::b;` records nothing in NsCtx, so a
    // qualified foreign reference could not be judged here anyway without a second channel.)
    //
    // `_nsCtx` is the file whose imports we are about to consult, and it is NOT always the file being
    // judged — generic instantiation installs the template's context. Only decide when the two agree.
    if (qualified || _nsCtx.unitPath != refFile) return;
    for (auto& sa : _nsCtx.symbolAliases) if (sa.second == key) return;   // per-symbol import (either form)
    unsupported(("`" + spelled + "` is declared in `" + declFile + "` and this file does not import it — "
                 "add `import { " + spelled + " };`. A module's files share a name space but not a scope: "
                 "`export` offers a name and `import` accepts it, so every name a file uses is written "
                 "down at its top").c_str(), line, spelled);
}

// Does a file whose module scope is `modScope` export the extern `name`? An extern keeps its literal key, so
// the module half of an import (`a::b::{name}`) is matched against the exporting file's scope instead.
bool CEmitter::externExportedFrom(const std::string& name, const std::string& modScope) const
{
    auto ex = _externExportedBy.find(name);
    if (ex == _externExportedBy.end()) return false;
    for (auto& kv : _unitCtx)
        if (ex->second.count(kv.second.unitPath) && kv.second.scope == modScope) return true;
    return false;
}

// The extern an import's alias target (`<module>__<name>`) names, or "" when it names none.
std::string CEmitter::importedExtern(const std::string& target) const
{
    const size_t cut = target.rfind("__");
    if (cut == std::string::npos) return "";
    const std::string name = target.substr(cut + 2);
    return externExportedFrom(name, target.substr(0, cut)) ? name : std::string();
}

// The file a reference is being written in, for `checkReach`. Empty outside a body walk.
std::string CEmitter::refFilePath() const
{
    return (_refUnit && _refUnit->name) ? *_refUnit->name : std::string();
}

// The DECLARATION-walk entry point: a type spelled in a signature, a field, a variant payload or a local.
// It reaches names the emitter never emits — an uninstantiated generic's parameter types — so it stays a
// separate caller of the same predicate rather than folding into the resolve wrappers.
//
// Its own member rather than a lambda because two callers need it at different strengths: a DECLARED type
// gets it as one clause of the full `check`, and a LOCAL declaration gets it alone (see `checkBodyLocals`).
// Callers own the namespace context — `_nsCtx` must already be the declaring unit's.
void CEmitter::checkQualifiedExport(const SharedIdentifier& t, const char* what)
{
    if (!t || !t->value) return;
    checkReach(resolveUserNameImpl(*t->value, t->qualifier), *t->value, what, t->line, _nsCtx.unitPath,
               t->qualifier && !t->qualifier->empty());
}

// The same check as `checkTypeResolves`, applied to every type a DECLARATION spells: parameter types,
// return types, field types and enum-variant payload types. Those positions used to be silent — only a
// local's type was checked (the single call site in `emitStatement`) — so a misspelled or unimported type
// in a signature passed `kama check` AND the language server and failed later in the C compiler, against
// generated code.
//
// A single-visit walk, deliberately NOT a check bolted onto the emission sites. Those positions are walked
// at 8+ places (prototype, definition, vtable slot, contract slot, once per generic instance), and a
// generic that is never instantiated is never emitted at all — so an emission-site check would both
// duplicate diagnostics and stay blind to exactly the templates that need it most. This visits each
// declaration's own AST node once, whether or not it is ever instantiated. The walk mirrors
// `buildPositions` step (2) in kama.query.cpp, which already covers this same structure for the position
// index; keep the two in sync when the language gains a declaration form.
//
// Runs from the tail of `collectProgram` — see the call site for why that point, and not earlier, is the
// only sound one.
// A struct crossing into C BY VALUE needs a layout both sides agree on, and only a C header can be that
// agreement: an `extern fn`'s prototype IS the header's, so a kama-emitted struct there is a second C type
// (clang: "incompatible type") — and an `expose fn`'s host has nothing to match but a layout kama never
// promised. So a composite crossing by value is a `type extern value`, whose layout the header owns and both
// sides include (KR-45). What is not a kama composite passes: a primitive, a pointer, a `fnptr`, a
// payload-less enum (a C integer), and a name the header itself declares. kama's own intrinsics pass too —
// `string` is the runtime header's `kama_string`, `InlineArray`/`Simd` are compiler-emitted value arrays,
// and `View`/`ConstView` are the stdlib's `{ptr, len}` borrow — their layout is kama's ABI, not a guess.
// Owning types keep the `expose` refusal in emitFunction (RAII cannot cross); `string` by value is the
// runtime's own convention on an `extern fn`, so only the `expose` side refuses it.
void CEmitter::rejectPlainCrossing(const SharedIdentifier& t, const char* where, const std::string& fname,
                                   bool isExternFn, int line)
{
    if (!t || !t->value) return;
    rejectPlainCrossingC(cType(t), where, fname, isExternFn, line);
}

void CEmitter::rejectPlainCrossingC(const std::string& cty, const char* where, const std::string& fname,
                                   bool isExternFn, int line)
{
    if (cty.empty() || cty.back() == '*' || isSigType(cty)) return;
    auto en = _enums.find(cty);
    if (en != _enums.end()) {
        // KR-55 — an enum's values cross exactly as a struct's layout does: someone must own them.
        const EnumInfo& ei = en->second;
        const std::string fn = std::string(isExternFn ? "extern fn " : "expose fn ") + fname;
        if (ei.isExtern) return;
        if (ei.isExpose && !isExternFn) return;
        if (ei.isExpose)
            unsupported(("`" + demangleForDisplay(cty) + "` crosses into C as " + where + " of `" + fn + "`, but it is "
                         "a `type expose enum` — values KAMA owns, and an `extern fn`'s prototype comes from a C header "
                         "that defines its own enum. A C-owned enum is a `type extern enum`").c_str(), line);
        else
            unsupported(("`" + demangleForDisplay(cty) + "` crosses into C as " + where + " of `" + fn + "`, but it is a "
                         "plain enum, whose values nothing promises to C — inserting a variant would renumber the rest "
                         "silently. Bind the header's enum with `type extern enum`, or publish kama's with `type expose "
                         "enum` (every value spelled)").c_str(), line);
        return;
    }
    auto it = _classes.find(cty);
    if (it == _classes.end()) return;                     // a primitive, a C enum, or the header's own name
    const ClassInfo& ci = it->second;
    if (ci.isExternStruct) return;
    if (ci.isExposeStruct) {
        if (!isExternFn) return;   // kama states the layout and the host header publishes it
        unsupported(("`" + demangleForDisplay(cty) + "` crosses into C by value as " + where + " of `extern fn "
                     + fname + "`, but it is a `type expose value` — a layout KAMA owns, and an `extern fn`'s "
                     "prototype comes from a C header that declares its own struct, so kama's would be a second, "
                     "incompatible type. A C-owned layout is a `type extern value`").c_str(), line);
        return;
    }
    if (ci.isIntrinsicColl) {
        if (ci.collKind == CollKind::Fixed || isValueVectorKind(ci.collKind)) {
            // An intrinsic array's own layout is kama's ABI, but its ELEMENTS are laid out inline: an
            // `InlineArray<Vec2>` publishes `Vec2`'s layout exactly as a bare `Vec2` would, so the element
            // answers the same question.
            auto co = _collections.find(cty);
            if (co != _collections.end())
                rejectPlainCrossingC(co->second.elemCType, where, fname, isExternFn, line);
            return;
        }
        if (ci.collKind == CollKind::String || !isExternFn) return;   // expose: emitFunction's owning refusal
    }
    auto gi = _genericTypeInsts.find(cty);
    if (gi != _genericTypeInsts.end()
        && (gi->second.templateKey == "std__collections__View" || gi->second.templateKey == "std__collections__ConstView"))
        return;
    if (!isExternFn && (isSmartPtrClass(cty) || ownsByValue(cty))) return;   // emitFunction says it
    const std::string shown = demangleForDisplay(cty);
    const std::string fn = std::string(isExternFn ? "extern fn " : "expose fn ") + fname;
    std::string kind = ci.enumNode ? "an `enum` with payloads" : ci.isGenericInst ? "a generic instance"
                     : ci.kind == TypeKind::Resource ? "a `resource`" : "a plain `type value`";
    unsupported(("`" + shown + "` crosses into C by value as " + where + " of `" + fn + "`, but it is " + kind
                 + ", and kama promises no C layout for it" + (isExternFn
                     ? " — the C header's prototype declares its own struct, so kama's would be a second, "
                       "incompatible type. Bind the header's struct with `type extern value`"
                     : " — the host would be matching a layout nothing states. Declare it `type expose value` "
                       "(kama states the layout and the generated host header publishes it), bind a C header's "
                       "struct with `type extern value`, or pass an `UnsafePtr`")).c_str(),
                line);
}

void CEmitter::checkDeclaredTypes(const std::vector<SharedCompilationUnit>& units)
{
    // The prelude and the built-in modules are compiler-owned sources: they are collect-only, they are not
    // user code, and `analyze()` excludes them from `_units` for the same reason.
    std::set<const CompilationUnit*> builtIn;
    if (_preludeUnit) builtIn.insert(_preludeUnit.get());
    for (auto& p : _preludeModuleUnits) if (p) builtIn.insert(p.get());

    // The declaring node's OWN type params. `isTypeParamName` only knows generic classes/enums
    // (`_genericTypeParams`); a generic FUNCTION keeps its params on the AST node alone, and `_typeSubst`
    // is empty here, so without this every `T` in every generic signature would be reported as unknown.
    std::set<std::string> tp;
    // The comptime params of that same declaration (`comptimeParams` is a SUBSET of `typeParams`, so
    // `tp` holds these names too — this says which of them bind a VALUE rather than a type).
    //
    // A const param is resolved by `emitExpression` ahead of every runtime name (see the identifier
    // branch), so a parameter, field or local of the same name is not a second binding — it is a
    // silently discarded one. Before this rule, `fn int32 f<const F: int32>(int32 F) { return F; }`
    // compiled clean and `f::<16>(F: 3)` returned 16. The name is therefore reserved for the whole
    // declaration, which is the answer kama already gives for every other shadowing (`emitDeclarator`)
    // and which makes the precedence question moot.
    std::set<std::string> cp;
    // NO SIGNATURE LEAK. A project's API is DERIVED, never written down: it is the `public` modules of
    // `kama.json` crossed with the `export` blocks of their files. That derivation is only coherent if an
    // exported symbol cannot name an unexported type of its own file — otherwise the enumeration lists a
    // `makeThing` whose result a consumer can hold and cannot spell. Rust calls this family
    // `private_interfaces`; it is NOT what `checkQualifiedExport` covers, which judges the REFERENCING
    // file rather than a declaration leaking its own file's private type.
    //
    // Same file only. A type from ANOTHER file already had to be exported to be named here at all, so the
    // file rung has answered for it — this is exclusively about the surface a file offers.
    //
    // `ownerExported` is set per top-level declaration and applies to publicly reachable positions only:
    // a `private` member's type is not part of what the export offers, so it leaks nothing.
    bool ownerExported = false;
    auto checkNoLeak = [&](const SharedIdentifier& t, const char* what) {
        if (!ownerExported || !t || !t->value) return;
        const std::string key = resolveUserNameImpl(*t->value, t->qualifier);
        // An extern type this file declares is file-private like any other, under its literal key.
        auto ds = _externDeclSites.find(key);
        if (ds != _externDeclSites.end()) {
            if (_nsCtx.unitPath.empty() || !ds->second.count(_nsCtx.unitPath)) return;
            auto ex = _externExportedBy.find(key);
            if (ex != _externExportedBy.end() && ex->second.count(_nsCtx.unitPath)) return;
        } else {
            if (declFileOf(key) != _nsCtx.unitPath || _nsCtx.unitPath.empty()) return;
            if (_exported.count(key)) return;
        }
        unsupported(("`" + *t->value + "` is not exported by this file, but " + what
                     + " of an exported declaration names it — a consumer could reach the declaration and "
                       "not the type. Export it too, or take it out of the exported surface").c_str(),
                    t->line);
    };
    auto constParamShadow = [&](const char* kind, const SharedIdentifier& id) {
        if (!id || !id->value || !cp.count(*id->value)) return;
        unsupported((std::string(kind) + " `" + *id->value + "` shadows the comptime parameter of "
                     "the same name, which binds a compile-time value for this whole declaration and "
                     "outranks every runtime name — rename it").c_str(), id->line);
    };
    // One type spelling, judged at its head AND at every type argument under it, to any depth. The rules
    // used to stop at the head, and `cType` maps any generic instance to SOME mangled name, so a bad name
    // nested as an argument — `Result<Uuid, UuidError>` without importing `UuidError` — passed and failed in
    // clang. A name is judged by the same rules wherever in the spelling it sits.
    //
    // `noun` is "contract" for an `implements` clause or a bound, whose HEAD names a contract rather than a
    // value's type — so the mint-protocol rule, which is about values, does not apply to it. Its type
    // arguments are types again.
    std::function<void(const SharedIdentifier&, const char*, const char*)> checkTypeNode =
        [&](const SharedIdentifier& t, const char* what, const char* noun) {
        if (!t || !t->value) return;
        // `This` is resolved against the enclosing type, which is not on the stack during this pass —
        // cType would reject it here for the wrong reason. It is always valid where the grammar allows it.
        // `Base` is resolved against that type's BASE, so it is not on the stack here either; a `Base` in
        // a type that has none is still caught, just later, where the enclosing type is known.
        if (*t->value == "This" || *t->value == "Base") return;
        // A const param names a value, so a TYPE position naming one is a mistake, not a binding —
        // `fn int32 f<const N: int32>(N x)` used to emit a bare `N` into C and die there. The legitimate
        // position, a `#(N)` argument, is skipped below and never reaches here.
        if (cp.count(*t->value)) {
            unsupported(("`" + *t->value + "` is a comptime parameter — a value, not a type — so "
                         + what + " cannot name it").c_str(), t->line);
            return;
        }
        if (tp.count(*t->value)) return;
        checkQualifiedExport(t, what);
        checkNoLeak(t, what);
        checkTypeResolves(t, cType(t), what, t->line, noun);
        if (std::string(noun) == "type") rejectMintProtocolValue(t, what, t->line);
        else {
            // A contract position naming something that RESOLVES but is not a contract — a type. The late
            // checks only ever said "unknown contract", and only when something was instantiated or emitted.
            const std::string k = resolveUserNameImpl(*t->value, t->qualifier);
            if ((_classes.count(k) || _enums.count(k) || _genericTypes.count(k)) && !_interfaces.count(k))
                unsupported(("`" + *t->value + "` is a type, not a contract, so " + what
                             + " cannot name it").c_str(), t->line);
        }
        forEachTypeArg(t, [&](const SharedIdentifier& a) { checkTypeNode(a, what, "type"); });
        // A `#(K)` argument names a VALUE, so it is judged as one: a module constant must be in reach of this
        // file like any other name. It was never looked at, so an unimported, private or unknown `K` emitted
        // a bare `K` into the instance's C name and failed in clang. A literal needs nothing; the declaration's
        // own comptime parameter is bound, not referenced.
        forEachConstArgName(t, [&](const SharedIdentifier& k) {
            if (tp.count(*k->value) || constArgReaches(k, what, _nsCtx.unitPath)) return;
            const bool qualified = k->qualifier && !k->qualifier->empty();
            if (qualified) {
                // `Type::NAME`, a type-associated constant — how `constArgN` reads a qualified size.
                auto tq = std::make_shared<StringList>(k->qualifier->begin(), k->qualifier->end() - 1);
                if (_typeConsts.count(resolveUserNameImpl(*k->qualifier->back(), tq) + "::" + *k->value)) return;
            }
            if (!qualified && reportDeclaredElsewhere("constant", *k->value, [&](const std::string& mk) {
                    return _moduleStatics.count(mk) > 0; }, what, k->line))
                return;
            unsupported(("unknown constant `" + *k->value + "` in " + what
                         + " — no such constant is declared or imported").c_str(), k->line, *k->value);
        });
    };
    auto check = [&](const SharedIdentifier& t, const char* what) {
        if (!t || !t->value) return;
        if (rejectBareCChar(t, what, t->line)) return;   // a C `char` element outside a raw pointer (scans the whole spelling)
        checkTypeNode(t, what, "type");
    };
    // Every contract a declaration names: its `implements` list and its type parameters' bounds. Judged
    // here, before any instantiation, because a bound or a conformance is not EMITTED as a name — a bound on
    // an uncalled generic and a private qualified contract were never judged at all, and a type argument of
    // `implements Holds<X>` was never resolved.
    auto checkContracts = [&](const SharedClassBaseDeclaration& bases, const SharedBoundsList& bounds) {
        if (bases && bases->interfaces)
            for (auto& itf : *bases->interfaces) checkTypeNode(itf, "an `implements` clause", "contract");
        if (bounds) for (auto& list : *bounds) if (list)
            for (auto& b : *list) checkTypeNode(b, "a bound", "contract");
    };
    // Every LOCAL declared type in a body, checked for module privacy ONLY. `collectBindings` is the
    // statement walker (kama.query.cpp) the position index already uses; `stmtOnly` drops its `match`-arm
    // half, whose payload bindings carry a DERIVED type rather than a source spelling and whose resolution
    // replay has no business running in a check pass.
    //
    // Deliberately NOT the full `check` lambda: `checkTypeResolves`/`cType` have never seen a function
    // body, and a generic METHOD's own type params are never bound here (`bindTypeParams` runs per
    // top-level declaration), so every `T` in a generic method's locals would report as unknown. The
    // export gate is immune — it returns at once unless the spelling is qualified, and a type parameter
    // never is.
    auto checkBodyLocals = [&](const SharedBlock& body) {
        if (!body) return;
        std::vector<QueryBinding> binds;
        collectBindings(std::static_pointer_cast<StatementNode>(body), binds, /*stmtOnly=*/true);
        for (auto& b : binds)
            if (!b.isParam) checkQualifiedExport(b.type, "a local variable");
    };
    auto checkParams = [&](const SharedParameterList& params, const char* what) {
        if (!params) return;
        for (auto& p : *params) if (p) { check(p->type, what); constParamShadow("parameter", p->identifier); }
    };
    // `self` is the C name of the receiver pointer, so a parameter of that name inside a type body
    // redeclares it. Checked here rather than in the emitter so an uninstantiated generic type is covered
    // too, and so free `fn`/`fnptr` — which this pass never reaches with a type body — stay untouched.
    auto checkNoSelfParam = [&](const SharedParameterList& params) {
        if (!params) return;
        for (auto& p : *params)
            if (p && p->identifier && p->identifier->value && *p->identifier->value == "self")
                unsupported("`self` names the receiver inside a type body — the kama spelling is `this`; "
                            "rename this parameter", p->identifier->line);
    };
    // A type parameter is a BINDER, so `fn f<Point>(Point p)` legally declares a fresh `Point` that
    // shadows the type — Rust and C++ do the same. What was wrong is that nothing said so: inside the
    // body `Point` silently meant the parameter, `f(p: 5)` bound it to `int32`, and the mistake surfaced
    // as a clang error about `int32_t` not being a structure. The shadowing is the whole reason a
    // specialization cannot be spelled `fn f<Concrete>`, so it is worth naming rather than tolerating.
    //
    // Resolved through the emitter's own resolver, at the DECLARATION's namespace, so an import, a
    // per-symbol alias and a `using` all count as visible — and via the Impl form, because recording a
    // reference from a name that is not a type reference would pollute the LSP index.
    //
    // A comptime parameter arrives here too — `comptimeParams` is a subset of `typeParams` — and it
    // binds its name just as firmly, so it keeps the same rule and only the noun changes.
    auto bindTypeParams = [&](const SharedStringList& names, const SharedStringList& constNames,
                              int line, const char* what) {
        tp.clear();
        cp.clear();
        if (constNames) for (auto& n : *constNames) if (n) cp.insert(*n);
        if (!names) return;
        for (auto& n : *names) if (n) {
            tp.insert(*n);
            std::string k = resolveUserNameImpl(*n, SharedStringList());
            if (_classes.count(k) || _enums.count(k) || _interfaces.count(k)
                || _genericTypes.count(k) || _genericContracts.count(k))
                unsupported(((cp.count(*n) ? "comptime parameter `" : "type parameter `") + *n
                             + "` of " + what + " shadows the type of the same "
                             "name, which is then unreachable in this declaration — rename the parameter")
                                .c_str(), line);
        }
    };

    NsCtx saved = _nsCtx;
    for (auto& u : units) {
        if (!u || !u->codeDeclarationList || builtIn.count(u.get())) continue;
        _nsCtx = _unitCtx[u.get()];
        // Every diagnostic this walk raises is ABOUT a declaration in `u`, and this runs from the tail of
        // collectProgram where `_collectingUnitPath` has already been unwound and `_sourcePath` is still ""
        // in a multi-file build — so without this the whole pass reported `at :17`, naming no file at all.
        ScopedStr _cu(_collectingUnitPath, u->name ? *u->name : std::string());
        for (auto& decl : *u->codeDeclarationList) {
            if (auto* fn = dynamic_cast<FunctionDeclarationNode*>(decl.get())) {
                // An `extern fn` signature names C types owned by the `extern "header.h"` it binds — a
                // `CompareFn` typedef the header declares is deliberately NOT a kama type, and `cType`
                // passes such a name through verbatim as the literal C spelling. That is the FFI seam
                // working as designed (tests/callback_qsort.d), so the check stops at it.
                if (isExtern(fn) || isExposed(fn)) {
                    const bool ext = isExtern(fn);
                    const std::string fname = fn->name && fn->name->value ? *fn->name->value : std::string();
                    // ...except the one rule that IS about the C spelling: a bare `cchar` in an extern signature.
                    if (ext) rejectBareCChar(fn->returnType, "a return type", fn->line);
                    if (fn->returnType)
                        rejectPlainCrossing(fn->returnType, "the return", fname, ext, fn->line);
                    if (fn->parameters)
                        for (auto& p : *fn->parameters) {
                            if (!p) continue;
                            if (ext) rejectBareCChar(p->type, "a parameter", p->line);
                            if (!paramByRef(p.get()))
                                rejectPlainCrossing(p->type, "a parameter", fname, ext, p->line ? p->line : fn->line);
                        }
                    if (ext) {
                        // ...and a QUALIFIED name, which is never a C spelling: `geo::HidVal` names a kama
                        // declaration, so it is held to the same rules as anywhere else. The bare-name skip
                        // above stays — `UnsafePtr<CFoo>` is the header's `CFoo`.
                        tp.clear(); cp.clear(); ownerExported = false;
                        std::function<void(const SharedIdentifier&, const char*)> qualifiedOnly =
                            [&](const SharedIdentifier& t, const char* what) {
                            if (!t || !t->value) return;
                            if (t->qualifier && !t->qualifier->empty()) checkTypeNode(t, what, "type");
                            else forEachTypeArg(t, [&](const SharedIdentifier& a) { qualifiedOnly(a, what); });
                        };
                        qualifiedOnly(fn->returnType, "a return type");
                        if (fn->parameters) for (auto& p : *fn->parameters) if (p) qualifiedOnly(p->type, "a parameter");
                        continue;
                    }
                }
                ownerExported = fn->name && fn->name->value && _exported.count(qualify(*fn->name->value));
                bindTypeParams(fn->typeParams, fn->comptimeParams,
                               fn->name ? fn->name->line : fn->line, "a function");
                checkContracts(nullptr, fn->typeBounds);
                check(fn->returnType, "a return type");
                checkParams(fn->parameters, "a parameter");
                checkReturns(fn, nullptr, "function");
                checkBodyLocals(fn->block);
            } else if (auto* cd = dynamic_cast<ClassDeclarationNode*>(decl.get())) {
                const bool typeExported =
                    cd->name && cd->name->value && _exported.count(qualify(*cd->name->value));
                ownerExported = false;
                bindTypeParams(cd->typeParams, cd->comptimeParams,
                               cd->name ? cd->name->line : cd->line, "a type");
                checkContracts(cd->baseTypes, cd->typeBounds);
                if (cd->baseTypes) check(cd->baseTypes->base, "a base type");
                if (cd->members) for (auto& m : *cd->members) {
                    if (auto* fld = dynamic_cast<ClassFieldDeclarationNode*>(m.get())) {
                        // A `private` field's type is not part of what the export offers, so it is not a
                        // leak. `fieldVisibility` owns the rule, including `value` forcing Public.
                        auto ciIt = _classes.find(qualify(*cd->name->value));
                        ownerExported = typeExported && ciIt != _classes.end()
                            && fieldVisibility(ciIt->second, fld->modifiers, fld->line) == Visibility::Public;
                        check(fld->type, "a field");
                        // A field of the const param's name would make `exprClass`'s bare-field path and
                        // the const arm in `emitExpression` disagree about what `F` means.
                        if (fld->declarators) for (auto& d : *fld->declarators)
                            if (d) { constParamShadow("field", d->name);
                                     rejectNullInit(fld->type, d->initializer, "a field", fld->line);
                                     rejectInitKindMismatch(fld->type, d->initializer, "a field", fld->line); }
                    } else if (auto* md = dynamic_cast<ClassMethodDeclarationNode*>(m.get())) {
                        ownerExported = typeExported
                            && visibilityOf(md->modifiers, Visibility::Private, md->line) == Visibility::Public;
                        check(md->returnType, "a return type");
                        checkParams(md->params, "a parameter");
                        checkNoSelfParam(md->params);
                        checkReturns(nullptr, md, "method");
                        checkBodyLocals(md->body);
                    } else if (auto* ct = dynamic_cast<ClassConstructorDeclarationNode*>(m.get())) {
                        // A ctor IS the construction API of an exported type, so its parameters are surface.
                        ownerExported = typeExported;
                        if (ct->declarator) { checkParams(ct->declarator->params, "a parameter");
                                              checkNoSelfParam(ct->declarator->params); }
                        checkBodyLocals(ct->body);
                    } else if (auto* op = dynamic_cast<ClassOperatorDeclarationNode*>(m.get())) {
                        if (auto* od = op->operatorDeclarator.get()) {
                            check(od->returnType, "a return type");
                            check(od->param1Type, "a parameter");
                            check(od->param2Type, "a parameter");
                            constParamShadow("parameter", od->param1Name);
                            constParamShadow("parameter", od->param2Name);
                            checkBodyLocals(op->body);
                        }
                    }
                }
            } else if (auto* ed = dynamic_cast<EnumDeclarationNode*>(decl.get())) {
                ownerExported = ed->identifier && ed->identifier->value
                             && _exported.count(qualify(*ed->identifier->value));
                bindTypeParams(ed->typeParams, ed->comptimeParams,
                               ed->identifier ? ed->identifier->line : ed->line, "an enum");
                checkContracts(ed->baseTypes, ed->typeBounds);
                if (ed->body) for (auto& mem : *ed->body)
                    if (mem) checkParams(mem->payload, "an enum variant payload");
            } else if (auto* ii = dynamic_cast<IntrinsicImplNode*>(decl.get())) {
                ownerExported = false;    // a conformance block exports nothing of its own
                tp.clear(); cp.clear();   // a `type intrinsic` block declares no type params of its own
                checkContracts(ii->baseTypes, nullptr);
                if (ii->targets) for (auto& tgt : *ii->targets) if (tgt) rejectBareCChar(tgt, "a `type intrinsic` target", tgt->line);
                if (ii->members) for (auto& m : *ii->members)
                    if (auto* md = dynamic_cast<ClassMethodDeclarationNode*>(m.get())) {
                        check(md->returnType, "a return type");
                        checkParams(md->params, "a parameter");
                        checkNoSelfParam(md->params);
                    }
                if (ii->sections) for (auto& sec : *ii->sections)
                    if (sec && sec->members) for (auto& m : *sec->members)
                        if (auto* md = dynamic_cast<ClassMethodDeclarationNode*>(m.get())) {
                            check(md->returnType, "a return type");
                            checkParams(md->params, "a parameter");
                            checkNoSelfParam(md->params);
                        }
            } else if (auto* mv = dynamic_cast<ModuleVariableDeclaration*>(decl.get())) {
                // A module `static` / `comptime`: its type is a declared type like a field's. It was never in
                // this walk, so `static Optional<Zork> gs;` reached clang as `Optional_Zork`.
                ownerExported = false;
                if (mv->variables) for (auto& d : *mv->variables)
                    if (d && d->name && d->name->value && _exported.count(qualify(*d->name->value))) ownerExported = true;
                tp.clear(); cp.clear();
                check(mv->type, mv->isComptime ? "a constant" : "a static");
            }
        }
    }
    _nsCtx = saved;
}

// `global::` has ONE job now: reach the floor past a local declaration that shadows the spelling
// (`global::envOr`). It used to have a second — `global::a::b::X`, naming a namespace absolutely, through
// neither the file's `using`s nor its aliases — and the module model (SPEC.md § Modules) removed it,
// because `global` is an ordinary reserved PROJECT name now and `global::a::b::X` would have to mean
// module `a/b` OF a project called `global`. Two spellings for one path is exactly what this campaign
// exists to remove.
//
// The job it did is real, and it is fixed at the source instead: the only way a module path needed an
// absolute escape was an `import … as N` alias shadowing a project name, and that alias is now refused
// where it is written (`kama.driver.cpp`, the import-alias check).
bool CEmitter::rejectRootedPath(SharedStringList qualifier, const IdentifierNode* site)
{
    if (!qualifier || qualifier->size() < 2 || *(*qualifier)[0] != "global") return false;
    std::string rest;
    for (size_t i = 1; i < qualifier->size(); ++i) rest += (rest.empty() ? "" : "::") + *(*qualifier)[i];
    // Name resolution runs from passes with no current module, so this named no file. `_nsCtx` is the
    // context of the file doing the naming, which is the file that wrote the `global::` path. See diagFile().
    ScopedStr _cu(_collectingUnitPath, _nsCtx.unitPath.empty() ? _collectingUnitPath : _nsCtx.unitPath);
    // REJECT ALWAYS, REPORT ONLY FROM THE SITE. `site` is defaulted to null at ~75 of this predicate's call
    // sites — name resolution asks the same question from positions that carry no identifier node — and
    // those calls reported the violation wherever the emitter happened to be: at line 0 before the walk,
    // and at the enclosing function's line inside it. Because `unsupported` dedupes on (file, line,
    // message), neither merged with the correctly-positioned firing, so ONE mistake was reported TWICE —
    // `global_absolute_path.kama` said line 10, which is right, and then line 9, which is the `fn` above it.
    // A second copy at an approximate line teaches a reader that the compiler is guessing. The sited call
    // is the one that knows, so it is the only one that speaks; `return true` is unchanged, so the path is
    // still refused. That the build still FAILS is not an assumption — it is the xfail leg's first assertion.
    if (site)
        unsupported(("`global::" + rest + "::…` names a module absolutely, which `global::` no longer does — "
                     "it reaches the always-in-scope floor and nothing else. Write `" + rest + "::…`, and if "
                     "an `import … as` alias is shadowing that name, rename the alias").c_str(), site->line);
    return true;
}

// Resolve a function reference to its mangled cName (same search as types).
std::string CEmitter::resolveFunc(const std::string& name, SharedStringList qualifier,
                                  const IdentifierNode* site)
{
    if (rejectRootedPath(qualifier, site)) return name;
    std::string key = resolveFuncImpl(name, qualifier);
    // §2f.31: `main` is the ENTRY POINT, not a symbol. C++ forbids calling it; Rust and Go make it
    // uncallable. Here it is reached BELOW the visibility system — `qualify` maps it to `kama_main` before
    // any scope prefix, and the emitter synthesizes a real C `main` that calls it directly — so no
    // `export`, no `import` and no `visibility` could ever gate it. Say it where it is written instead.
    if (site && !site->synthesized && name == "main")
        unsupported("`main` is the program's entry point, not a callable function — the runtime calls it "
                    "once. Move the body you want to share into a function of its own and call that",
                    site->line);
    if (site && !site->synthesized)                                        // chokepoint: see resolveUserName
        checkReach(key, name, "a call", site->line, refFilePath(), qualifier && !qualifier->empty());
    recordRef(key, site);
    return key;
}

std::string CEmitter::resolveFuncImpl(const std::string& name, SharedStringList qualifier)
{
    if (name == "main") return "kama_main";
    if (!qualifier || qualifier->empty()) {
        auto sa = _nsCtx.symbolAliases.find(name);   // per-symbol `import a::b::{fn as g}`
        if (sa != _nsCtx.symbolAliases.end() && _funcs.count(sa->second)) return sa->second;
        if (sa != _nsCtx.symbolAliases.end()) { std::string ext = importedExtern(sa->second); if (!ext.empty()) return ext; }
    }
    SharedStringList q = qualifier;                      // `global::…` — see resolveUserNameImpl
    bool rooted = q && !q->empty() && *(*q)[0] == "global";
    if (rooted) {
        auto rest = std::make_shared<StringList>();
        for (size_t i = 1; i < q->size(); ++i) rest->push_back((*q)[i]);
        q = rest;
        if (q->empty()) return name;                     // `global::f` == the bare/floor spelling
    }
    if (q && !q->empty()) {
        std::string nsMangled;
        if (!rooted && q->size() == 1 && _nsCtx.aliases.count(*(*q)[0]))
            nsMangled = _nsCtx.aliases[*(*q)[0]];
        else {
            std::string path;
            for (auto& seg : *q) path += (path.empty() ? "" : ".") + *seg;
            nsMangled = mangleNs(path);
        }
        std::string cand = nsMangled + "__" + name;
        if (_funcs.count(cand)) return cand;
        if (_externDeclSites.count(name)) return externExportedFrom(name, nsMangled) ? name : cand;   // see resolveUserNameImpl
        std::string priv = siblingPrivateKey(name, [&](const std::string& k) { return _funcs.count(k) > 0; }, nsMangled);
        return priv.empty() ? name : priv;
    }
    // Own name (private or module-scoped), then the module key, then usings, then a sibling's private key
    // for the diagnostic — the same ladder resolveUserNameImpl climbs, for the same reasons.
    std::string own = qualify(name);
    if (_funcs.count(own)) return own;
    own = _nsCtx.scope + "__" + name;
    if (_funcs.count(own)) return own;
    for (auto& u : _nsCtx.usings) {
        std::string cand = u + "__" + name;
        if (_funcs.count(cand)) return cand;
    }
    { std::string sib = siblingPrivateKey(name, [&](const std::string& k) { return _funcs.count(k) > 0; });
      if (!sib.empty()) return sib; }
    return name;
}

// Does this module-variable declaration publish any of its names? One declaration may bind several
// (`comptime int32 A = 1, B = 2;`), and the two emission sites need a single yes/no, so any exported
// name carries the whole declaration into the header. Over-inclusion is harmless: an unexported name
// sitting there is still refused at the file rung, which is where visibility is decided.
bool CEmitter::moduleVarExported(ModuleVariableDeclaration* mv)
{
    if (!mv || !mv->variables) return false;
    for (auto& d : *mv->variables)
        if (d && d->name && d->name->value && _exported.count(qualify(*d->name->value))) return true;
    return false;
}

// A module-scope `static`/`comptime` name -> its qualified C symbol, or "" if nothing of that name is
// in reach. The same three lookups `resolveFuncImpl` does — a per-symbol import alias, an explicit
// qualifier (or namespace alias), then this file's own scope and its `using`s — because a module
// constant is reached exactly the way a module function is. It used to be a bare `qualify(name)`, which
// consulted neither the qualifier nor the import aliases: an imported or qualified constant resolved to
// the *importing* file's scope, emitted an unqualified name, and failed in the C compiler.
std::string CEmitter::resolveModuleVar(const std::string& name, SharedStringList qualifier)
{
    if (!qualifier || qualifier->empty()) {
        auto sa = _nsCtx.symbolAliases.find(name);   // per-symbol `import a::b::{CAP}` (or `as`)
        if (sa != _nsCtx.symbolAliases.end() && _moduleStatics.count(sa->second)) return sa->second;
    }
    SharedStringList q = qualifier;                  // `global::…` — see resolveUserNameImpl
    bool rooted = q && !q->empty() && *(*q)[0] == "global";
    if (rooted) {
        auto rest = std::make_shared<StringList>();
        for (size_t i = 1; i < q->size(); ++i) rest->push_back((*q)[i]);
        q = rest;                                    // empty => `global::CAP`, the bare spelling below
    }
    if (q && !q->empty()) {
        std::string nsMangled;
        if (!rooted && q->size() == 1 && _nsCtx.aliases.count(*(*q)[0]))
            nsMangled = _nsCtx.aliases[*(*q)[0]];
        else {
            std::string path;
            for (auto& seg : *q) path += (path.empty() ? "" : ".") + *seg;
            nsMangled = mangleNs(path);
        }
        std::string cand = nsMangled + "__" + name;
        if (_moduleStatics.count(cand)) return cand;
        return siblingPrivateKey(name, [&](const std::string& k) { return _moduleStatics.count(k) > 0; }, nsMangled);
    }
    std::string own = qualify(name);                 // this file's own (a `static` is always file-private)
    if (_moduleStatics.count(own)) return own;
    own = _nsCtx.scope + "__" + name;                // a sibling's exported `comptime`
    if (_moduleStatics.count(own)) return own;
    for (auto& u : _nsCtx.usings) {
        std::string cand = u + "__" + name;
        if (_moduleStatics.count(cand)) return cand;
    }
    return std::string();
}

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

std::string CEmitter::cType(SharedIdentifier type)
{
    if (!type) return "void";
    // inside a generic instantiation, a bare type-param name (`T`, no <...> of its own)
    // resolves to the concrete type it was bound to. Guarded on !genericArg so a real `List<T>`
    // still flows to the collection arm (whose element then hits this same substitution).
    if (!_typeSubst.empty() && type->value && !type->genericArg) {
        auto s = _typeSubst.find(*type->value);
        if (s != _typeSubst.end()) return cType(s->second);
    }
    // `This` (the self-type) resolves to the enclosing type — the concrete class while emitting a
    // class body/prototype/struct (_thisType), or the interface type inside its vtbl slot. In a bounded
    // generic the receiver's concrete class carries `This` (resolved when that class was emitted), so no
    // binding is needed at the call site. `This` outside a type/contract is a clean error.
    if (type->value && *type->value == "This" && !type->genericArg) {
        if (!_thisType.empty()) return _thisType;
        if (_currentClass)      return _currentClass->name;
        unsupported("`This` (the self-type) is only valid inside a `type` or `contract`", type->line);
        return "void";
    }
    // `Base` is `This`'s companion — the enclosing type's BASE. resolveUserNameImpl does the resolving;
    // this arm exists only to answer the two ways it can have nothing to resolve to. Without it the
    // name would flow on as the literal "Base" and be diagnosed as an unknown type, or (since the
    // signature pre-pass has to skip it) not at all.
    if (type->value && *type->value == "Base" && !type->genericArg) {
        // Ask the resolver, which tries a REAL type named `Base` first and falls back to the alias.
        std::string r = resolveUserNameImpl("Base", type->qualifier);
        if (_classes.count(r) || _enums.count(r) || _interfaces.count(r)) return r;
        // Nothing to resolve to. `baseName` is populated by linkBases(), which runs AFTER signatures are
        // collected — so before that, "nothing" means "not linked yet" and diagnosing would reject every
        // legal `Base` in a signature. After linking it means what it says.
        if (_basesLinked) {
            ClassInfo* encl = !_thisType.empty() && _classes.count(_thisType) ? &_classes[_thisType]
                                                                              : _currentClass;
            if (!encl)
                unsupported("`Base` (the base type) is only valid inside a `type` that declares "
                            "`extends …`", type->line);
            else
                unsupported(("'" + encl->name + "' has no base class, so `Base` names nothing "
                             "(only a type declared `extends …` has one)").c_str(), type->line);
            return "void";
        }
    }
    // FFI: a raw C pointer carrier (opaque). Bare `UnsafePtr` -> void* (the
    // universal handle / opaque pointer); `UnsafePtr<T>` -> T*. This is the explicit, extern-marked
    // unsafe boundary.
    // ⚠️ This arm RETURNS before the resolver runs, which is why it also has to index itself.
    // Every other built-in is a reserved WORD carrying a `builtInVal`, and its spelling reaches the
    // reference index through the ordinary resolve path; `UnsafePtr` is a plain identifier that this
    // function short-circuits, so nothing recorded it and a body-local annotation naming it was one the
    // editor could see nothing at — no hover, no jump, while `bool` and `float32` on the lines around it
    // both answered. `usize`/`isize` sat in this same arm until 0.9.136 for the same reason; they are
    // reserved words now, so they take the ordinary path and the switch below spells them.
    //
    // `UnsafeConstPtr<T>` -> `T const*`, EAST-const on purpose: `UnsafeConstPtr<UnsafePtr<uint8>>` is then
    // `uint8_t* const*` (a pointer to a const pointer — what it says), where a left `const` would spell
    // `const uint8_t**` (a pointer to a pointer to const — something else). It also makes "is this C type a
    // const raw pointer" an exact suffix test (isConstRawCType), which every resolved-type site relies on.
    if (type->value && isRawPtrName(*type->value)) {
        recordBuiltinRef(*type->value, type.get());
        const std::string base = type->genericArg ? cType(type->genericArg) : std::string("void");
        return isConstRawPtrName(*type->value) ? base + " const*" : base + "*";
    }

    // `InlineArray<T,N>` spells `InlineArray_<mangleT>_<N>`, and `Simd<T,N>` spells `Simd_<mangleT>_<N>` —
    // the same two-argument shape (the comptime size mangles to its value), so one arm serves both.
    if (type->genericArg && type->value && type->genericArgs
        && (*type->value == "InlineArray" || *type->value == "Simd" || *type->value == "Mask")) {
        std::string m = *type->value;
        for (auto& a : *type->genericArgs) m += "_" + mangleElem(a);
        return m;
    }
    // `BindableFunctionPtr<Sig>` spells its mangled struct name. (DynamicArray AND FixedArray are library
    // generic types now — std::collections — and smart pointers likewise; they flow through the generic-type
    // arm below.)
    if (type->genericArg && type->value && *type->value == "BindableFunctionPtr")
        return *type->value + "_" + mangleElem(type->genericArg);
    // a user generic TYPE (`Box<int32>`) spells its specialized struct name (`Box_int32`).
    // Reached only for a non-reserved name with a type arg; under _typeSubst the arg's `T` resolves.
    if (type->genericArg && type->value) {   // genericArg mirrors genericArgs[0] (non-null iff there are args)
        std::string tmpl = resolveUserName(*type->value, type->qualifier, type.get());
        // a generic TYPE (`Box<int32>`) or a generic CONTRACT (`Iterator<int32>`) both spell their
        // specialized name; the contract instance lives in _interfaces after discovery.
        if (_genericTypes.count(tmpl) || _genericContracts.count(tmpl))
            return genericTypeMangle(tmpl, type->genericArgs);
    }
    // A generic TYPE named BARE (no type args) whose params are ALL defaulted (`BitSet` ==
    // `BitSet<GlobalAllocator>`): spell the defaulted instance name — NOT under _typeSubst, where a bare
    // param name is substituted above. (A bare type-param isn't in _genericTypes, so this never fires for one.)
    if (type->value && !type->genericArg) {
        std::string tmpl = resolveUserName(*type->value, type->qualifier, type.get());
        if (_genericTypes.count(tmpl) && allTypeParamsDefaulted(tmpl))
            return genericTypeMangle(tmpl, nullptr);
    }
    switch (type->builtInVal) {
        case IDENTIFIER_INT8_VAL:    return "int8_t";
        case IDENTIFIER_INT16_VAL:   return "int16_t";
        case IDENTIFIER_INT32_VAL:   return "int32_t";
        case IDENTIFIER_INT64_VAL:   return "int64_t";
        case IDENTIFIER_UINT8_VAL:   return "uint8_t";
        case IDENTIFIER_UINT16_VAL:  return "uint16_t";
        case IDENTIFIER_UINT32_VAL:  return "uint32_t";
        case IDENTIFIER_UINT64_VAL:  return "uint64_t";
        case IDENTIFIER_BOOL_VAL:    return "bool";
        case IDENTIFIER_FLOAT32_VAL: return "float";
        case IDENTIFIER_FLOAT64_VAL: return "double";
        case IDENTIFIER_STRING_VAL:  return "kama_string";
        case IDENTIFIER_VOID_VAL:    return "void";
        // `char` is one Unicode scalar value (codepoint), and it is its OWN C type — `typedef uint32_t
        // kama_char;` in kama_runtime.h. It used to lower straight to `uint32_t`, which cost the language
        // the whole codepoint/integer distinction: every rule decides identity by comparing lowered
        // spellings, so with nothing left to compare `uint32 n = c;` and `char d = u;` both crossed in
        // silence. Representation is unchanged — this is a typedef, not a wrapper.
        case IDENTIFIER_CHAR_VAL:    return "kama_char";
        // The two platform-varying types. This lowering IS the variance — C's own `ptrdiff_t`/`size_t`
        // are 8 bytes on x86_64/arm64 and 4 on wasm32/thumbv6m, and kama inherits that rather than
        // restating it. Nothing here changed when they became reserved words in 0.9.136; what changed is
        // that they now arrive as a `builtInVal` instead of being string-compared ahead of this switch.
        case IDENTIFIER_ISIZE_VAL:   return "ptrdiff_t";
        case IDENTIFIER_USIZE_VAL:   return "size_t";
        // The C ABI elements (0.9.232). `cchar` gets its OWN C name for the reason `kama_char` has one: every
        // identity rule compares lowered spellings, and a bare `char` would collide with the codepoint key in
        // `primKeyOfCType`. A typedef is the same C type, so `kama_cchar const*` reaches `puts(const char*)`
        // with no warning. `long`/`unsigned long` collide with nothing and lower to themselves.
        case IDENTIFIER_CCHAR_VAL:   return "kama_cchar";
        case IDENTIFIER_CLONG_VAL:   return "long";
        case IDENTIFIER_CULONG_VAL:  return "unsigned long";
        default:
            // User-defined type (class/enum/interface) — resolve through the
            // current file's namespace scope + usings to its mangled C name.
            if (!type->value) return "void";
            return resolveUserName(*type->value, type->qualifier, type.get());
    }
}

// The key a type's contract conformances are filed under: the KAMA spelling for a scalar primitive, the C
// name for everything else (`string` -> `kama_string`, a user type -> its mangle). The distinction exists
// because `cType` is not injective — `char` and `uint32` both emit `uint32_t`, so a cType-keyed registry
// could hold a `Formattable` for one of them and not the other. Nothing else in the compiler collides.
//
// The `_typeSubst` hop comes FIRST, exactly as in `cType` and `mangleElem`: inside a monomorph a parameter's
// recorded type node is still the unsubstituted `T`, and reading `builtInVal` off that would fall through to
// the C type and quietly file `char` under `uint32`.
std::string CEmitter::primKey(SharedIdentifier type)
{
    if (!type) return "void";
    if (!_typeSubst.empty() && type->value && !type->genericArg) {
        auto s = _typeSubst.find(*type->value);
        if (s != _typeSubst.end()) return primKey(s->second);
    }
    if (!type->genericArg) switch (type->builtInVal) {
        case IDENTIFIER_INT8_VAL:    return "int8";
        case IDENTIFIER_INT16_VAL:   return "int16";
        case IDENTIFIER_INT32_VAL:   return "int32";
        case IDENTIFIER_INT64_VAL:   return "int64";
        case IDENTIFIER_UINT8_VAL:   return "uint8";
        case IDENTIFIER_UINT16_VAL:  return "uint16";
        case IDENTIFIER_UINT32_VAL:  return "uint32";
        case IDENTIFIER_UINT64_VAL:  return "uint64";
        case IDENTIFIER_BOOL_VAL:    return "bool";
        case IDENTIFIER_FLOAT32_VAL: return "float32";
        case IDENTIFIER_FLOAT64_VAL: return "float64";
        case IDENTIFIER_CHAR_VAL:    return "char";
        // ⚠️ These two are why this switch and `cType` must stay separate maps. Until 0.9.136 they had no
        // arm here, so they fell through to `return cType(type)` and their conformance key became the C
        // name — `ptrdiff_t`/`size_t`. Nothing chose that; it was the fall-through. It leaked into
        // diagnostics ("`ptrdiff_t` has no method `format`") and, worse, it disagreed with `mangleElem`,
        // which DID spell them `isize`/`usize`: `@generate(Serializable)` over an `isize` field emitted a
        // call to `ptrdiff_t__serialize` beside a `Result_isize_…` declaration, which is two names for
        // one type in a single translation unit.
        case IDENTIFIER_ISIZE_VAL:   return "isize";
        case IDENTIFIER_USIZE_VAL:   return "usize";
        case IDENTIFIER_CLONG_VAL:   return "clong";     // same reason: the key must agree with mangleElem
        case IDENTIFIER_CULONG_VAL:  return "culong";
        // `cchar` has NO arm on purpose: it never names a value, so nothing conforms on it and no diagnostic
        // should key on it — rejectBareCChar fires before any conformance lookup could.
        default: break;
    }
    return cType(type);
}

// True for the sixteen keys the switch above can produce — i.e. "this key names a scalar primitive", as
// opposed to the C name `primKey` hands back for everything else. A caller that resolved a key from a kama
// type node uses this to decide whether that key is authoritative or whether to fall back to the C type.
bool CEmitter::isScalarPrimKey(const std::string& k)
{
    static const std::set<std::string> kScalars = {
        "int8", "int16", "int32", "int64", "uint8", "uint16", "uint32", "uint64",
        "bool", "float32", "float64", "char", "isize", "usize", "clong", "culong" };
    return kScalars.count(k) != 0;
}

// The same key recovered from a C type, for the places that have already lost the kama type node (an
// element of a collection, a field of a generic instance).
//
// This used to carry a caveat — "`uint32_t` is the one ambiguous input; it answers `uint32`, so a `char`
// that reaches a contract only through such a place still rides `uint32`'s conformance" — and it is gone
// as of 0.9.104, because `char` now lowers to `kama_char` rather than to `uint32_t`. There is no longer
// an ambiguous input: every scalar's C spelling names exactly one kama type, which is the property the
// whole type-identity rule rests on. Callers that CAN produce the type node should still prefer
// `primKey`, since it answers without lowering anything.
//
// `ptrdiff_t`/`size_t` used to fall out of the bottom unchanged, which is the same fall-through `primKey`
// had, and it is what made a diagnostic name the C type. They map back now, so this stays the exact
// inverse of `cType` over every scalar.
std::string CEmitter::primKeyOfCType(const std::string& ct)
{
    if (ct == "ptrdiff_t") return "isize";
    if (ct == "size_t")    return "usize";
    if (ct == "long")          return "clong";
    if (ct == "unsigned long") return "culong";
    if (ct == "int8_t")   return "int8";
    if (ct == "int16_t")  return "int16";
    if (ct == "int32_t")  return "int32";
    if (ct == "int64_t")  return "int64";
    if (ct == "uint8_t")  return "uint8";
    if (ct == "uint16_t") return "uint16";
    if (ct == "uint32_t") return "uint32";
    if (ct == "kama_char") return "char";
    if (ct == "uint64_t") return "uint64";
    if (ct == "bool")     return "bool";
    if (ct == "float")    return "float32";
    if (ct == "double")   return "float64";
    return ct;
}

// ---------------------------------------------------------------------------
// Operators
// ---------------------------------------------------------------------------

std::string CEmitter::binaryOperator(int token)
{
    switch (token) {
        case PLUS:    return "+";
        case MINUS:   return "-";
        case STAR:    return "*";
        case SLASH:   return "/";
        case PERCENT: return "%";
        case LTLT:    return "<<";
        case GTGT:    return ">>";
        case LT:      return "<";
        case GT:      return ">";
        case LEQ:     return "<=";
        case GEQ:     return ">=";
        case EQEQ:    return "==";
        case NOTEQ:   return "!=";
        case AMP:     return "&";
        case CARET:   return "^";
        case BAR:     return "|";
        default:      return "/*?op*/";
    }
}

// The six operators that a user type gets from a CONTRACT (`Equatable` -> `==`/`!=`, `Comparable` ->
// `<`/`>`/`<=`/`>=`) rather than by declaring an `operator` member. Every other operator (`*`, `[]`, …)
// stays an ordinary per-type operator method: those are concrete-type ergonomics, while these two are
// the operators a GENERIC BOUND has to be able to name.
bool CEmitter::isComparisonToken(int token)
{
    return token == EQEQ || token == NOTEQ || token == LT || token == GT || token == LEQ || token == GEQ;
}

// Render an expression back to readable KAMA text for a diagnostic message (the auto-stringified
// `assert` condition). Pure and self-contained: it never calls emitExpression (so no emitter side
// effects / no C leak like `this->x`), and returns "" for any form it doesn't handle so the caller
// falls back to a bare "assertion failed". Covers what actually appears in conditions.
std::string CEmitter::unparseExpr(SharedExpression expr)
{
    if (!expr) return "";
    ASTNode* n = expr.get();

    if (auto* v = dynamic_cast<IdentifierNode*>(n)) {
        std::string s;
        if (v->qualifier) for (auto& q : *v->qualifier) if (q) s += *q + ".";
        return s + (v->value ? *v->value : "");
    }
    if (dynamic_cast<ThisAccessNode*>(n)) return "this";
    if (auto* v = dynamic_cast<BooleanNode*>(n)) return v->value ? "true" : "false";
    if (dynamic_cast<NullNode*>(n))              return "null";
    if (auto* v = dynamic_cast<Int8Node*>(n))    return std::to_string((int)v->value);
    if (auto* v = dynamic_cast<Int16Node*>(n))   return std::to_string((int)v->value);
    if (auto* v = dynamic_cast<Int32Node*>(n))   return std::to_string(v->value);
    if (auto* v = dynamic_cast<Int64Node*>(n))   return std::to_string((long long)v->value);
    if (auto* v = dynamic_cast<UInt8Node*>(n))   return std::to_string((unsigned)v->value);
    if (auto* v = dynamic_cast<UInt16Node*>(n))  return std::to_string((unsigned)v->value);
    if (auto* v = dynamic_cast<UInt32Node*>(n))  return std::to_string(v->value);
    if (auto* v = dynamic_cast<UInt64Node*>(n))  return std::to_string((unsigned long long)v->value);
    if (auto* v = dynamic_cast<CharNode*>(n))    return std::to_string(v->value);
    if (auto* v = dynamic_cast<Float64Node*>(n)) { char b[64]; std::snprintf(b, sizeof b, "%g", v->value); return b; }
    if (auto* v = dynamic_cast<Float32Node*>(n)) { char b[64]; std::snprintf(b, sizeof b, "%g", (double)v->value); return b; }
    if (auto* v = dynamic_cast<StringNode*>(n))  return "\"" + (v->value ? *v->value : std::string()) + "\"";

    // `sizeof(T)` / `alignof(T)` — the operand is a TYPE, not an expression, so nothing else here reaches
    // it. A layout condition is almost entirely made of these (M7's `comptime assert`), and without this
    // arm the auto-stringified condition came out as " == 16".
    if (auto* v = dynamic_cast<SizeofNode*>(n)) {
        std::string t;
        if (v->type) {
            if (v->type->qualifier) for (auto& q : *v->type->qualifier) if (q) t += *q + "::";
            if (v->type->value) t += *v->type->value;
        }
        if (t.empty()) return "";
        return (v->isAlign ? "alignof(" : "sizeof(") + t + ")";
    }

    // `cast<T>(e)` — a const-generic bound's width check reads `F < cast<int32>(sizeof(B)) * 8`, so a
    // conversion sits in the middle of exactly the conditions this function exists to render.
    if (auto* v = dynamic_cast<CastNode*>(n)) {
        std::string t, e = unparseExpr(v->unaryExpression);
        if (v->type) {
            if (v->type->qualifier) for (auto& q : *v->type->qualifier) if (q) t += *q + "::";
            if (v->type->value) t += *v->type->value;
        }
        if (t.empty() || e.empty()) return "";
        return "cast<" + t + ">(" + e + ")";
    }

    // The composite arms below propagate emptiness rather than splicing it: an unrendered child used to
    // leave a HOLE in the middle of the text (`F <  * 8`), which reads as a compiler bug rather than as
    // the documented degrade-to-"assertion failed". The access/invocation arms already did this.
    if (auto* v = dynamic_cast<BinaryExpressionNode*>(n)) {
        std::string l = unparseExpr(v->LHS), r = unparseExpr(v->RHS);
        if (l.empty() || r.empty()) return "";
        return l + " " + binaryOperator(v->token) + " " + r;
    }
    if (auto* v = dynamic_cast<LogicalAndOrNode*>(n)) {
        std::string l = unparseExpr(v->LHS), r = unparseExpr(v->RHS);
        if (l.empty() || r.empty()) return "";
        return l + (v->token == ANDAND ? " && " : " || ") + r;
    }
    if (auto* v = dynamic_cast<SimpleUnaryExpressionNode*>(n)) {
        const char* op = v->token == EXCLAMATION ? "!" : v->token == TILDE ? "~"
                       : v->token == MINUS ? "-" : v->token == PLUS ? "+" : "";
        std::string e = unparseExpr(v->expression);
        if (!*op || e.empty()) return "";
        return op + e;
    }
    if (auto* v = dynamic_cast<MemberAccessNode*>(n)) {
        std::string base = v->expression ? unparseExpr(v->expression)
                         : (v->classType && v->classType->value ? *v->classType->value : "");
        std::string mem = v->identifier && v->identifier->value ? *v->identifier->value : "";
        if (base.empty() || mem.empty()) return "";
        return base + "." + mem;
    }
    if (auto* v = dynamic_cast<ElementAccessNode*>(n)) {
        std::string base = v->expression ? unparseExpr(v->expression)
                         : (v->identifier && v->identifier->value ? *v->identifier->value : "");
        std::string idx;
        if (v->expressionlist) for (auto& e : *v->expressionlist) {
            std::string s = unparseExpr(e);
            if (s.empty()) return "";
            if (!idx.empty()) idx += ", ";
            idx += s;
        }
        if (base.empty()) return "";
        return base + "[" + idx + "]";
    }
    if (auto* v = dynamic_cast<InvocationNode*>(n)) {
        std::string callee = v->identifier ? unparseExpr(v->identifier) : unparseExpr(v->expression);
        std::string args;
        if (v->args) for (auto& a : *v->args) {
            if (!a) continue;
            std::string an = a->name && a->name->value ? *a->name->value : "";
            std::string av = unparseExpr(a->expression);
            if (av.empty()) return "";
            if (!args.empty()) args += ", ";
            args += an.empty() ? av : (an + ": " + av);
        }
        if (callee.empty()) return "";
        return callee + "(" + args + ")";
    }
    return "";   // unhandled form → caller degrades to a bare "assertion failed"
}

// The PLACE operator (kama_runtime.h) a compound assignment lowers to — `x += y` is `KAMA_ADDEQ(&(x), y)`,
// the place taken by ADDRESS so `a[idx()] += 1` evaluates its index once and a sub-`int` place gets the
// range check C's `+=` never had. "" for the bitwise forms, which stay C's own operator (no fault to check).
static const char* placeOpMacro(int token)
{
    switch (token) {
        case PLUSEQ:  return "KAMA_ADDEQ";
        case MINUSEQ: return "KAMA_SUBEQ";
        case STAREQ:  return "KAMA_MULEQ";
        case DIVEQ:   return "KAMA_DIVEQ";
        case MODEQ:   return "KAMA_MODEQ";
        case LTLTEQ:  return "KAMA_SHLEQ";
        case GTGTEQ:  return "KAMA_SHREQ";
        default:      return "";
    }
}

std::string CEmitter::assignmentOperator(int token)
{
    switch (token) {
        case EQ:      return "=";
        case PLUSEQ:  return "+=";
        case MINUSEQ: return "-=";
        case STAREQ:  return "*=";
        case DIVEQ:   return "/=";
        case MODEQ:   return "%=";
        case XOREQ:   return "^=";
        case ANDEQ:   return "&=";
        case OREQ:    return "|=";
        case GTGTEQ:  return ">>=";
        case LTLTEQ:  return "<<=";
        default:      return "/*?assign*/=";
    }
}

// map an overloadable operator token + arity-class to a stable C-safe method name.
// arity 0 => a UNARY operator on `this`; arity >= 1 => a BINARY operator (method or free form,
// same name). Returns "" when the operator has no form for that arity (e.g. unary `*`, binary `!`).
std::string CEmitter::operatorMangle(int opToken, int arity)
{
    bool unary = (arity == 0);
    switch (opToken) {
        case PLUS:        return unary ? "op_pos"  : "op_add";
        case MINUS:       return unary ? "op_neg"  : "op_sub";
        case STAR:        return unary ? ""        : "op_mul";
        case SLASH:       return unary ? ""        : "op_div";
        case PERCENT:     return unary ? ""        : "op_mod";
        case EQEQ:        return unary ? ""        : "op_eq";
        case NOTEQ:       return unary ? ""        : "op_ne";
        case LT:          return unary ? ""        : "op_lt";
        case GT:          return unary ? ""        : "op_gt";
        case LEQ:         return unary ? ""        : "op_le";
        case GEQ:         return unary ? ""        : "op_ge";
        case AMP:         return unary ? ""        : "op_band";
        case BAR:         return unary ? ""        : "op_bor";
        case CARET:       return unary ? ""        : "op_bxor";
        case LTLT:        return unary ? ""        : "op_shl";
        case GTGT:        return unary ? ""        : "op_shr";
        case EXCLAMATION: return unary ? "op_not"  : "";
        case TILDE:       return unary ? "op_bnot" : "";
        case PLUSPLUS:    return unary ? "op_inc"  : "";   // pre/post both map here (mutating in place)
        case MINUSMINUS:  return unary ? "op_dec"  : "";
        case LEFT_BRACKET: return unary ? ""       : "op_index";   // `a[i]` — method form (self + index)
        default:          return "";
    }
}

// Type-based dispatch — the full operator name = the base mangle + an operand-type suffix, so a
// type can carry several `operator*` distinguished by operand type (mat*vec vs mat*mat). Rule:
//   arity 2 (free/static form)              -> `op_<sym>__free`
//   arity 1 (method form), DIFFERENT user rhs -> `op_<sym>__<RhsClass>`
//   arity 1, same-type rhs (incl. `This`), primitive rhs, or a unary op -> bare `op_<sym>`
// The same-type/`This` case keeping the bare name is what lets a `contract` bound (`This operator+(This)`)
// match a concrete `operator+(Vec2)` structurally, with no `This`-in-name special-casing.
std::string CEmitter::operatorName(int opToken, int arity, SharedIdentifier paramType, const std::string& owner)
{
    std::string base = operatorMangle(opToken, arity);
    if (base.empty()) return "";
    if (arity == 2) return base + "__free";
    if (arity == 1 && paramType) {
        std::string pk = (paramType->value && *paramType->value == "This") ? owner : cType(paramType);
        if (!pk.empty() && pk != owner && isClass(pk)) return base + "__" + pk;   // different user type
    }
    return base;
}

// synthesize a ParameterList from an operator declarator's param1/param2 (0/1/2 params) so all
// normal method machinery (paramListC, paramSigsOf, emitMethodOrCtorBody's binding) is reused verbatim.
SharedParameterList CEmitter::operatorParamList(ClassOperatorDeclaratorNode* d)
{
    if (!_synthCtx) _synthCtx = std::make_shared<CodeGenContext>(std::make_shared<std::string>("<operator>"));
    auto list = std::make_shared<ParameterList>();
    if (d->param1Type)
        list->push_back(std::make_shared<FunctionParameterNode>(*_synthCtx, SharedModifier(), d->param1Type, d->param1Name));
    if (d->param2Type)
        list->push_back(std::make_shared<FunctionParameterNode>(*_synthCtx, SharedModifier(), d->param2Type, d->param2Name));
    return list;
}

// is `cls` a user type that may carry operator overloads (a `value`/`resource`/class, not a
// collection/smart-pointer, whose arithmetic is a real C `struct` with no built-in `+`)?
static inline bool userOperandType(const std::string& cls, std::map<std::string, ClassInfo>& classes)
{
    if (cls.empty()) return false;
    auto it = classes.find(cls);
    return it != classes.end() && !it->second.isIntrinsicColl;
}

// `&<operand>` for a method-form/unary operator's `self`. A simple lvalue (a local, a field/
// member access, `this`) is addressed directly; an rvalue (a nested operator result, a call, `a[i]`)
// is first materialized into a hoisted temp — ISO C, no statement-expressions — so `&` is legal and
// chained `a + b + c` works. In a non-hoistable slot (a raw `if`/`while` condition) a chained operand
// is a clean error rather than bad C.
// produce the `self` pointer for a method-form/unary operator. A simple lvalue (a local, a
// field/member access, `this`) is addressed directly. An rvalue (a nested operator result, a call —
// `a + b + c`, `-(a + b)`) can't be `&`'d, so it is wrapped in a C99 compound-literal array: `(V[]){e}`
// decays to `V*` and the temporary lives to the end of the enclosing block. This is ISO C11 (the same
// construct used for variants), needs no statement slot, and so works in ANY position — including
// a raw `if`/`while` condition — with no hoisting.
// the class `e` constructs if it is a bare inline constructor (`Vec3(x: …)` — not a method call
// or a `Type::variant`), else "".
std::string CEmitter::bareCtorClass(SharedExpression e)
{
    auto* iv = dynamic_cast<InvocationNode*>(e.get());
    if (!iv || iv->expression || !iv->identifier || !iv->identifier->value) return "";
    if (iv->identifier->qualifier && !iv->identifier->qualifier->empty()) return "";   // Type::variant, not a ctor
    std::string rn = resolveUserName(*iv->identifier->value, iv->identifier->qualifier);
    return (isClass(rn) && _classes.count(rn) && !_classes[rn].isIntrinsicColl) ? rn : "";
}

// The concrete type constructed by a DOT-ON-TYPE ctor call `Point.make(…)` (infallible, concrete receiver),
// else "". Distinct from bareCtorClass (nameless inline ctor) because a factory result materializes by MOVE,
// and only the call-ARGUMENT path wants this — the operator-operand path already handles it via exprClass +
// the compound-literal fallback, and must NOT be routed through inline-ctor hoisting. #M8d.2
std::string CEmitter::dotCtorFactoryClass(SharedExpression e)
{
    auto* iv = dynamic_cast<InvocationNode*>(e.get());
    if (!iv) return "";
    auto* ma = dynamic_cast<MemberAccessNode*>(iv->expression.get());
    if (!ma) return "";
    std::string dt, m = (ma->identifier && ma->identifier->value) ? *ma->identifier->value : "";
    if (m.empty() || !isTypeReceiver(ma, dt) || !_classes.count(dt) || _classes[dt].isIntrinsicColl) return "";
    auto cit = _classes[dt].ctors.find(m);
    return (cit != _classes[dt].ctors.end() && !cit->second.isFallible) ? dt : "";
}

// an inline constructor operand, hoisted into a temp (needs a statement slot); "" otherwise.
std::string CEmitter::hoistCtorIfInline(SharedExpression e)
{
    std::string rn = bareCtorClass(e);
    return rn.empty() ? "" : tryHoistInlineCtor(e, rn, e->line);   // "" when !_hoistOK (e.g. a raw condition)
}

// a clean diagnostic for a bare inline ctor operand that has no statement slot to hoist into
// (e.g. inside a raw `if`/`while` condition) — the same boundary an inline `match`/ctor hits elsewhere.
void CEmitter::rejectUnhoistableCtor(SharedExpression e)
{
    if (!bareCtorClass(e).empty())
        unsupported("an inline constructor as an operator operand here has no statement slot — bind it to a local first", e->line);
}

// emit an operator operand by value, materializing an inline constructor into a hoisted temp.
std::string CEmitter::emitOperandByValue(SharedExpression e)
{
    std::string t = hoistCtorIfInline(e);
    if (!t.empty()) return t;
    rejectUnhoistableCtor(e);
    return emitExpression(e);
}

// An identifier that names a CONSTANT rather than a place — an enum member (`Color::Red`) or an `extern const`,
// which may be a `#define` — so a borrow of it needs a temporary. Answers that temporary's C type, or "".
std::string CEmitter::constantTempCType(SharedExpression e)
{
    auto* id = dynamic_cast<IdentifierNode*>(e.get());
    if (!id || !id->value) return "";
    if (id->qualifier && !id->qualifier->empty()) {
        const std::string en = exprEnumType(e);
        if (!en.empty()) return en;
    }
    if (_localTypes.count(*id->value) || _paramNames.count(*id->value)) return "";
    const std::string xk = resolveExternConst(*id->value, id->qualifier);
    return xk.empty() ? "" : cType(_externConsts[xk].type);
}

std::string CEmitter::addrOfOperand(SharedExpression e, const std::string& cls, int line)
{
    ASTNode* n = e.get();
    if (dynamic_cast<ThisAccessNode*>(n))   // `this` is already `self` — a pointer, except on a scalar receiver
        return (_currentClass && _currentClass->isScalarRecv) ? "&(" + emitExpression(e) + ")" : emitExpression(e);
    std::string ct = hoistCtorIfInline(e);
    if (!ct.empty()) return "&" + ct;   // inline ctor operand → a hoisted, addressable temp
    rejectUnhoistableCtor(e);
    // A place-returning call (`fn ref T` — `getRef(k)`, a user `at(i)`) emits as `(*call)`, an lvalue whose
    // address folds back to the returned `T*`. Treating it as a place (not a compound-literal copy) is what
    // lets a chained mutation `m.getRef(k).bump()` / `m.getRef(k) = x` write THROUGH the borrow, like `a[i]`.
    bool lvalue = dynamic_cast<IdentifierNode*>(n) || dynamic_cast<MemberAccessNode*>(n)
                  || invocationReturnsPlace(dynamic_cast<InvocationNode*>(n));
    const std::string constTy = constantTempCType(e);
    std::string em = emitExpression(e);
    if (!constTy.empty()) return "(" + constTy + "[]){ " + em + " }";
    if (lvalue || cls.empty()) {
        // A READ-ONLY place (a `const ref T` call, `cv[i]` through a const `operator[]`) is a `T const*` in
        // C, and every runtime helper takes `T*`: `const fn` is ABI-neutral, so the front end has already
        // refused every write and the cast only restates that. Same cast method dispatch applies to its
        // receiver; this is the operator/intrinsic-operand half of it.
        if (!cls.empty() && chainThroughConstPlace(e)) return "(" + cls + "*)&(" + em + ")";
        return "&(" + em + ")";
    }
    return "(" + cls + "[]){ " + em + " }";   // rvalue → addressable compound-literal temporary
}

// resolve `a OP b` to an operator method by OPERAND TYPES. Priority: the method form (arity 1) on
// the LHS type — a different-user-type rhs (`op_<sym>__<Rc>`) before the same-type/scalar form
// (`op_<sym>`) — then the free form (`op_<sym>__free`) on either operand's type. Returns null if none.
MethodInfo* CEmitter::findBinaryOperator(int token, const std::string& lc, const std::string& rc, ClassInfo** ownerOut)
{
    std::string opBase = operatorMangle(token, 1);
    if (opBase.empty()) return nullptr;
    if (userOperandType(lc, _classes)) {
        std::vector<std::string> names;
        if (userOperandType(rc, _classes) && rc != lc) names.push_back(opBase + "__" + rc);   // mat * vec
        names.push_back(opBase);                                                               // same-type / scalar
        for (auto& nm : names) {
            ClassInfo* owner = nullptr;
            MethodInfo* mi = findMethod(&_classes[lc], nm, &owner);
            if (mi && mi->isOperator && mi->arity == 1) { if (ownerOut) *ownerOut = owner; return mi; }
        }
    }
    for (const std::string& cls : { lc, rc }) {   // free/static form (scalar-on-the-left, etc.)
        if (!userOperandType(cls, _classes)) continue;
        ClassInfo* owner = nullptr;
        MethodInfo* mi = findMethod(&_classes[cls], opBase + "__free", &owner);
        if (mi && mi->isOperator && mi->arity == 2) { if (ownerOut) *ownerOut = owner; return mi; }
    }
    return nullptr;
}

// a binary expression with a user-typed operand dispatches to an operator overload; a purely
// primitive expression keeps the raw-C path (so the whole numeric fixture suite is untouched). The
// method form passes `self` by pointer (an rvalue is wrapped by addrOfOperand); the free form passes
// both operands by value.
std::string CEmitter::emitBinaryOperator(int token, SharedExpression lhs, SharedExpression rhs, int line)
{
    std::string lc = exprClass(lhs);
    std::string rc = exprClass(rhs);
    // An enum VALUE (`Color::Red`, `WsOpcode::Text`) is not a class expression, so `exprClass` — which
    // answers for class-typed operands only — leaves it blank. For a payload-less enum without members that
    // is right: it is a bare C integer and the all-primitive path below gives it the raw operator. Two
    // spellings need the enum's class instead:
    //
    //   - a payload-less enum WITH members must reach its hand-written `equals`, when it declares one;
    //   - a TAGGED enum that declares `Equatable<This>` — the hand-written conformance, which is the
    //     sanctioned answer until the derive ships — compared fine against a named local and was refused
    //     against a variant literal, with a message naming `operator==`, a thing kama does not have and
    //     rejects if written. The first consumer's report (KB-17) is exactly this line.
    //
    // `typeOfExpr` answers for an enum value in every spelling, so both are one rule. Accepting only a
    // variant class from it widens the classifier for nothing else.
    // `s == Side::R` on a GENERIC integer enum: the bare member names only the template, and the other
    // operand's instance is what pins it — the same target-type context a declaration supplies.
    auto enumOperandClass = [&](SharedExpression e, const std::string& other) {
        ScopedStr _vt(_variantTargetType, other.empty() ? _variantTargetType : other);
        std::string t = typeOfExpr(e);
        auto it = _classes.find(t);
        return (it != _classes.end() && (it->second.isVariant || it->second.isScalarEnum())) ? t : std::string();
    };
    if (lc.empty()) lc = enumOperandClass(lhs, rc);
    if (rc.empty()) rc = enumOperandClass(rhs, lc);
    bool lUser = userOperandType(lc, _classes);
    bool rUser = userOperandType(rc, _classes);
    // `string` is a primitive (kama_string), not a user-operator type, so `+`/`==`/`!=` are compiler
    // special-cases lowered to the runtime intrinsics — not overloads. Both operands must be `string`
    // (no implicit conversion; `string + number` would need a Display/to-string substrate — a later
    // roadmap item). `self` goes by pointer (an rvalue literal / nested `a+b` wraps in a compound-literal
    // temp via addrOfOperand), the other operand by value, exactly like the user-operator lowering.
    bool lStr = exprIsString(lhs), rStr = exprIsString(rhs);
    if (lStr || rStr) {
        if (!(lStr && rStr)) {
            unsupported("operator on `string` requires both operands to be `string` "
                        "(no implicit conversion — build the other side into a string first)", line);
            return "0";
        }
        // An owned-string rvalue operand is hoisted into a scope-dtor'd temp so it isn't leaked; a
        // literal/lvalue keeps the leak-free addrOfOperand/by-value path.
        auto ptrOf = [&](SharedExpression e) {
            std::string t = hoistStringTemp(e);
            return t.empty() ? addrOfOperand(e, "kama_string", line) : ("&" + t);
        };
        auto valOf = [&](SharedExpression e) {
            std::string t = hoistStringTemp(e);
            return t.empty() ? emitOperandByValue(e) : t;
        };
        // `a + b` on strings is `concat` written as an operator, and it allocates the same new buffer.
        // It needs its own gate because it never reaches emitDispatch: the operator is lowered straight to
        // the runtime call here, so the intrinsic gate there cannot see it. Without this, `"${a}${b}"` was
        // rejected inside a `@noheap` region and `a + b` was not — one allocation, two answers.
        if (token == PLUS) {
            rejectIfNoHeap("`string + string` builds a NEW owned string", line);
            return "kama_string__concat(" + ptrOf(lhs) + ", " + valOf(rhs) + ")";
        }
        if (token == EQEQ)  return "kama_string__equals(" + ptrOf(lhs) + ", " + valOf(rhs) + ")";
        if (token == NOTEQ) return "(!kama_string__equals(" + ptrOf(lhs) + ", " + valOf(rhs) + "))";
        unsupported(("operator '" + binaryOperator(token) + "' is not defined for `string` "
                     "(only `+`, `==`, `!=`)").c_str(), line);
        return "0";
    }
    if (!lUser && !rUser) {
        // A `Mask<T>#(N)` carries NO operators. Its lanes are all-ones/all-zeros bit patterns rather than
        // numbers, so `m * n` and `m + n` are nonsense that C would nevertheless compute — a mask is a
        // raw vector type, so without this it lands on the primitive path below and compiles silently.
        // Keeping arithmetic off a mask is half the reason it is a separate type from `Simd` at all (the
        // other half being that `select` cannot then be handed a data vector), so the rule has to be
        // enforced rather than merely documented.
        if (isSimdColl(lc) || isSimdColl(rc)) {
            // A DATA vector — elementwise operators are the point. But a SIGNED INTEGER lane obeys
            // kama's overflow rule the same way a scalar of that type does: trap in debug, wrap in
            // release. Nothing in the toolchain supplies that — `-fsanitize=signed-integer-overflow`
            // does NOT instrument vector arithmetic (measured: the scalar add trapped and the lane add
            // wrapped, same build, same flags) — so the emitted C carries the check.
            const std::string& sc = isSimdColl(lc) ? lc : rc;
            const CollectionInfo& ci2 = _collections[sc];
            const bool signedInt = cNumSigned(ci2.elemCType) && !cNumFloat(ci2.elemCType);
            const char* op = token == PLUS ? "KAMA_SIMD_ADD" : token == MINUS ? "KAMA_SIMD_SUB"
                           : token == STAR ? "KAMA_SIMD_MUL" : nullptr;
            if (signedInt && op && lc == rc)
                return std::string(op) + "(" + sc + ", " + emitOperandByValue(lhs) + ", "
                     + emitOperandByValue(rhs) + ")";
            // ⚠️ A signed `<<` must NOT reach `KAMA_SHL` below: that shim dispatches with `_Generic`,
            // which cannot see a vector type — so a `Simd` operand is a hard C error, not a fallback. The
            // per-lane `__shl` is the same rule (shift in the unsigned peer, so shifting into the sign bit
            // stays defined) written where a vector can use it.
            if (signedInt && token == LTLT && lc == rc)
                return sc + "__shl(" + emitOperandByValue(lhs) + ", " + emitOperandByValue(rhs) + ")";
        }
        else if (isMaskColl(lc) || isMaskColl(rc)) {
            unsupported(("`" + binaryOperator(token) + "` is not defined on a `Mask<T>#(N)` — its lanes are "
                         "all-ones/all-zeros bit patterns, not numbers. Combine masks with `and(rhs:)`, "
                         "`or(rhs:)` and `not()`, test them with `anyTrue()`/`allTrue()`, and use "
                         "`select(ifTrue:, ifFalse:)` to pick lanes").c_str(), line);
            return "0";
        }
        // The operand measurement (C2) goes HERE and nowhere else: this branch is entered only when
        // neither side is a user type, so a user `operator+`, an `Equatable`/`Comparable` lowering, a
        // contract value, a `sig` and `string + string` are all structurally out of reach — they return
        // above. The guard is the control flow, not a classifier test, which is what keeps it out of the
        // three traps `exprClass`'s `isClass` filter has already sprung on this campaign.
        noteNumericOperands(token, lhs, rhs, binaryOperator(token).c_str(), line);
        noteTypeIdentityOperands(token, lhs, rhs, binaryOperator(token).c_str(), line);
        rejectMixedOperands(token, lhs, rhs, binaryOperator(token), line);   // milestone 6, the operands

        // D-arith, the emission half: `T op T` IS a `T`, so where C would hand back a promoted `int` the
        // result is narrowed to `T` right here. Only the four sub-`int` types can differ — everything
        // from `int32` up is already its own type in C — and only a value-producing operator; a
        // comparison yields `bool`, so promotion cannot reach its result. A shift takes its type from the
        // LEFT operand alone, matching `typeOfExpr`.
        //
        // Without this the classifier and the emitter disagree wherever the promoted value is READ before
        // something narrows it: `cast<int32>(a + b)` said 300 where kama's rule says 44, and so did
        // `(a + b) > c`, `(a + b) / c` and `arr[a + b]`. The corpus never noticed because a hand-off into
        // a `T` destination truncates on the way in, which is the one path where both answers agree.
        // Measured at 39 sites before the change (`--strict-numeric`'s `arith-subint` bucket); the 11,662
        // sub-`int` COMPARISONS are untouched, which is why the bucket had to be split to size this.
        std::string resT;
        if (!isComparisonToken(token)) {
            const std::string lt = typeOfExpr(lhs);
            if (token == LTLT || token == GTGT) resT = lt;
            else if (!lt.empty() && lt == typeOfExpr(rhs)) resT = lt;
            if (!(cNumBits(resT) && cNumBits(resT) < 32 && !cNumFloat(resT))) resT.clear();
        }
        const std::string open  = resT.empty() ? "(" : "(" + resT + ")(";
        // Every shift and every integer division takes kama's own checked path (kama_runtime.h): a shift
        // amount outside the promoted width, a zero divisor and `TYPE_MIN / -1` are faults the program can
        // NAME — a message, the panic hook, recovery inside an `@onPanic` region — where they used to be a
        // bare `-fsanitize-trap` `ud2`. A signed left shift into the sign bit stays DEFINED (the helper
        // shifts in the unsigned peer). Dispatch is `_Generic` on the promoted type, inside a function per
        // width, so no "shift count >= width" false positive fires against an unselected arm (the old
        // `kama_lshift` macro shifted inline in every arm and fired 72 of them across `std::num`).
        // A `Simd` operand keeps C's own vector operator: `_Generic` cannot see a vector type, and a
        // float lane division is IEEE (an unsigned lane shift is defined; the signed cases return above).
        const bool vec = isSimdColl(lc) || isSimdColl(rc);
        // Known operand type -> the helper is named here and each operand written once (`arithCType`).
        // A shift's type is its LEFT operand's alone; the amount is widened to `long long` either way.
        auto lit32 = [](const SharedExpression& e) { return dynamic_cast<Int32Node*>(e.get()) != nullptr; };
        const std::string known = vec ? std::string()
            : (token == LTLT || token == GTGT) ? arithCType(typeOfExpr(lhs), false, typeOfExpr(lhs), false)
            : arithCType(typeOfExpr(lhs), lit32(lhs), typeOfExpr(rhs), lit32(rhs));
        const bool knownInt = !known.empty() && !cNumFloat(known);
        if (!vec && (token == LTLT || token == GTGT)) {
            const std::string l = emitExpression(lhs), r = emitExpression(rhs);
            if (knownInt)
                return open + "kama_" + (token == LTLT ? "shl_" : "shr_") + arithSuffix(known) + "(" + l
                     + ", (long long)(" + r + ")))";
            return open + (token == LTLT ? "KAMA_SHL(" : "KAMA_SHR(") + l + ", " + r + "))";
        }
        const std::string l = emitExpression(lhs), r = emitExpression(rhs);
        const std::string body = (!vec && token == SLASH && !known.empty())
                                   ? std::string("kama_div_") + arithSuffix(known) + "(" + l + ", " + r + ")"
                               : (!vec && token == PERCENT && knownInt)
                                   ? std::string("kama_mod_") + arithSuffix(known) + "(" + l + ", " + r + ")"
                               : (!vec && token == SLASH)   ? "KAMA_DIV(" + l + ", " + r + ")"
                               : (!vec && token == PERCENT) ? "KAMA_MOD(" + l + ", " + r + ")"
                               : l + " " + binaryOperator(token) + " " + r;
        // D-arith, the CHECK half. `resT` non-empty means a sub-`int` result, which is exactly where the
        // language's own overflow rule had a hole: C promotes `int8`/`int16` operands to `int`, so
        // `100 + 100` is computed as 200 where `-fsanitize=signed-integer-overflow` sees nothing, and the
        // narrowing above is a CONVERSION, which that check does not watch either. So `int8` silently
        // produced -56 where `int32 MAX + 1` trapped, and SPEC recorded the split as a ⚠️ rather than the
        // rule being wrong. It is the rule being wrong — 200 is not representable in the type kama says
        // the expression has — and this is the missing half.
        //
        // `+ - *` follow the WIDE rule exactly: trap in debug, wrap in release. `KAMA_ARITH_NARROW` is
        // that two-tier split (its release arm is a plain truncation, which IS the defined wrap, so
        // release codegen is unchanged). `/` traps in EVERY build instead, because the only division that
        // can overflow is `TYPE_MIN / -1` and SPEC promises that one unconditionally.
        //
        // UNSIGNED is untouched: `uint8`/`uint16` wrapping is defined and the language says so. Shifts are
        // untouched: a signed left shift into the sign bit is DEFINED here (`kama_lshift` above), and a
        // shift's result type comes from the left operand alone, so `resT` being set does not mean an
        // overflow happened.
        const bool arithTok = token == PLUS || token == MINUS || token == STAR;
        std::string lo, hi;
        if (!resT.empty() && cNumSigned(resT) && (arithTok || token == SLASH)
            && cNumRangeText(resT, lo, hi)) {
            return arithTok
                 ? "KAMA_ARITH_NARROW(" + resT + ", " + lo + ", " + hi + ", " + body + ")"
                 : "((" + resT + ")kama_arith_chk((long long)(" + body + "), " + lo + ", " + hi + "))";
        }
        // The WIDE half of the division rule — `TYPE_MIN / -1` at 32 and 64 bits, where nothing narrows —
        // is inside `KAMA_DIV` (kama_div_i32/_i64 check the OPERANDS: `INT64_MIN / -1` overflows the very
        // `long long` a result check would compute it in), promised in EVERY build since the release tier
        // dropped the signed-overflow sanitizer (see the driver's note).
        //
        // ...and the WIDE half of the overflow rule: `+ - *` on `int32`/`int64` (nothing narrows, so the
        // arm above cannot see them) trap in debug and wrap in release through `KAMA_ADD`/`SUB`/`MUL` —
        // the plain operator under NDEBUG, `__builtin_*_overflow` otherwise. It used to be
        // `-fsanitize=signed-integer-overflow`, the last sanitizer flag the driver passed.
        // (`resT` non-empty here is an UNSIGNED sub-`int` — the signed one returned above — whose wrap is
        // defined and whose result `open` truncates; it stays the plain operator.)
        // With the type known, the helper `_Generic` would have selected is named here instead.
        if (arithTok && !vec && resT.empty() && !known.empty())
            return std::string(token == PLUS ? "KAMA_ADD_T(" : token == MINUS ? "KAMA_SUB_T(" : "KAMA_MUL_T(")
                 + arithSuffix(known) + ", " + l + ", " + r + ")";
        if (arithTok && !vec && resT.empty())
            return std::string(token == PLUS ? "KAMA_ADD(" : token == MINUS ? "KAMA_SUB(" : "KAMA_MUL(")
                 + l + ", " + r + ")";
        return open + body + ")";   // primitives — `open` narrows a sub-`int` result
    }

    // Comparison is CONTRACT-driven, not operator-driven. `Equatable` and `Comparable` are the single
    // opt-in for the six comparison operators, and `a == b` / `a < b` on a user type LOWER to that
    // contract's `equals` / `compareTo` — declaring `operator==` & co. directly is rejected at
    // registration (collectClasses). That is what keeps `a == b` and a `<K: Equatable>` bound from ever
    // disagreeing, and it makes `Equatable` the sibling of `Comparable` it always should have been.
    // Both operands must be the SAME user type — `equals(ref This)` / `compareTo(ref This)` say so.
    // Primitives never reach here (the all-primitive path above keeps the raw C operator), so float
    // `<` keeps exact IEEE semantics and never routes through `Comparable`'s total order.
    if (isComparisonToken(token) && lUser && rUser && lc == rc) {
        bool eq = (token == EQEQ || token == NOTEQ);
        std::string need = eq ? "Equatable" : "Comparable";
        std::string meth = eq ? "equals"    : "compareTo";
        auto ci = _classes.find(lc);
        MethodInfo* cm = nullptr;
        if (satisfiesBound(lc, need) && ci != _classes.end()) {
            auto m = ci->second.methods.find(meth);
            if (m != ci->second.methods.end()) cm = &m->second;
        }
        // `==`/`!=` between two values of the SAME payload-less enum is the one comparison an enum keeps
        // without declaring anything (SPEC § *Enums*: everything else goes through `match`). One without
        // members never reaches here — the all-primitive path above already answered it with the raw
        // operator — and one WITH members is the same integer, so it must not lose the operator merely for
        // having declared them. Ordering is NOT included: `<` on an enum needs `Comparable`, which the
        // message below still says.
        // ...and the same shortcut when the `equals` in hand is the SYNTHESIZED one: a derived
        // `Color__equals` on a payload-less enum is `self == *other` wearing a function call, so
        // taking the call would make `@generate(Equatable)` cost something that `implements Equatable`
        // does not. A HAND-WRITTEN `equals` still wins — the author meant it — and the derived body is
        // still emitted and still used wherever the conformance is (a `Map` key, a `<T: Equatable>` bound).
        if ((!cm || cm->isSynthCmp) && eq && ci != _classes.end() && ci->second.isScalarEnum()) {
            ScopedStr _vt(_variantTargetType, lc);   // pins a generic enum's bare member (see enumOperandClass)
            const std::string l = emitExpression(lhs), r = emitExpression(rhs);
            return "(" + l + (token == EQEQ ? " == " : " != ") + r + ")";
        }
        if (!cm) {
            const std::string dnote = derivedUnmetNote(lc, need);
            unsupported((dnote.empty()
                         ? ("`" + binaryOperator(token) + "` on `" + lc + "` needs `implements " + need
                            + "` — declare `implements " + need + " for " + lc + " { … }`"
                            + (eq ? " (or `@generate(Equatable)`)" : "")
                            + "; `" + binaryOperator(token) + "` calls its `" + meth + "`")
                         : ("`" + binaryOperator(token) + "` on `" + lc + "` needs `implements " + need
                            + "`" + dnote)).c_str(), line);
            return "0";
        }
        canAccess(&ci->second, cm->visibility, cm->cName, line);
        std::string call = cm->cName + "(" + (ci->second.isScalarEnum() ? emitExpression(lhs) : addrOfOperand(lhs, lc, line))
                                     + ", " + addrOfOperand(rhs, rc, line) + ")";
        switch (token) {
            case EQEQ:  return call;
            case NOTEQ: return "(!" + call + ")";
            case LT:    return "(" + call + " == Ordering_Less)";
            case GT:    return "(" + call + " == Ordering_Greater)";
            case LEQ:   return "(" + call + " != Ordering_Greater)";
            default:    return "(" + call + " != Ordering_Less)";     // GEQ
        }
    }

    ClassInfo* owner = nullptr;
    MethodInfo* mi = findBinaryOperator(token, lc, rc, &owner);
    if (!mi) {
        unsupported(("no operator '" + binaryOperator(token) + "' for operand type '"
                     + (lUser ? lc : rc) + "' — define `operator" + binaryOperator(token) + "` on the type").c_str(), line);
        return "0";
    }
    canAccess(owner, mi->visibility, mi->cName, line);
    // An operator's operands are ARGUMENTS, and they were the one argument position nothing checked.
    // `findBinaryOperator` falls back from the mixed-type form (`op_mul__Vec4`) to the same-type form
    // (`op_mul`) whenever the mixed one is absent, and nothing then confirmed the operand actually IS the
    // declared parameter type — so `Mat4 * Vec4` against `Mat4 operator*(Mat4)` resolved, emitted, and
    // failed in the C compiler. The consumer filed this as ergonomic friction; it is a check/build
    // divergence, and the same hole reached every by-value hand-off (see rejectClassIdentityMismatch).
    if (mi->arity == 1) {   // method form: `A__op(&lhs, rhs)` (rvalue lhs -> compound-literal temporary)
        if (!mi->params.empty())
            rejectClassIdentityMismatch(mi->params[0].className, rhs, "the right-hand operand", line);
        return mi->cName + "(" + addrOfOperand(lhs, lc, line) + ", " + emitOperandByValue(rhs) + ")";
    }
    if (mi->params.size() >= 2) {   // free form: both by value
        rejectClassIdentityMismatch(mi->params[0].className, lhs, "the left-hand operand", line);
        rejectClassIdentityMismatch(mi->params[1].className, rhs, "the right-hand operand", line);
    }
    return mi->cName + "(" + emitOperandByValue(lhs) + ", " + emitOperandByValue(rhs) + ")";
}

// a compound-assignment token maps to its binary operator (`a += b` == `a = a + b`) for a
// user type. Returns 0 (not a valid token) for a plain `=` or an unmapped token.
int CEmitter::compoundToBinary(int token)
{
    switch (token) {
        case PLUSEQ:  return PLUS;
        case MINUSEQ: return MINUS;
        case STAREQ:  return STAR;
        case DIVEQ:   return SLASH;
        case MODEQ:   return PERCENT;
        case ANDEQ:   return AMP;
        case OREQ:    return BAR;
        case XOREQ:   return CARET;
        case LTLTEQ:  return LTLT;
        case GTGTEQ:  return GTGT;
        default:      return 0;
    }
}

// a unary / increment / decrement on a user type dispatches to a 0-param (on-`this`) operator.
// Returns "" when the operand is NOT a user type (caller keeps its raw-C path).
std::string CEmitter::emitUnaryUserOp(int opToken, SharedExpression operand, int line)
{
    std::string oc = exprClass(operand);
    if (!userOperandType(oc, _classes)) return "";
    std::string opName = operatorMangle(opToken, 0);   // op_neg / op_not / op_bnot / op_pos / op_inc / op_dec
    MethodInfo* mi = opName.empty() ? nullptr : findMethod(&_classes[oc], opName, nullptr);
    if (!mi || !mi->isOperator) {
        unsupported(("no unary operator for type '" + oc + "' — define the matching `operator` on the type").c_str(), line);
        return "0";
    }
    canAccess(&_classes[oc], mi->visibility, opName, line);
    return mi->cName + "(" + addrOfOperand(operand, oc, line) + ")";   // rvalue operand → hoisted temp
}

// ---------------------------------------------------------------------------
// Expressions
// ---------------------------------------------------------------------------

// String interpolation `"a ${x} b"` lowers to a Formatter build, hoisted into the enclosing statement (ISO
// C — no statement-expressions): a `Formatter` temp, a `writeStr` per literal part + a `<hole>.format(ref f)`
// per hole (synthesized method-call ASTs, so EVERY hole type goes through the real Formattable dispatch), then a
// `finish()` whose owned-string temp is the expression's value (scope-dropped like any string rvalue). The
// whole nested value materializes in ONE growing buffer — no O(n²) concat.
std::string CEmitter::emitInterpolation(InterpolatedStringNode* is)
{
    if (!is) return "\"\"";
    if (!_hoistOK) {
        unsupported("string interpolation must appear where a statement can be hoisted (an initializer, "
                    "argument, or return) — not a raw `if`/`while` condition; bind a `let` first", is->line);
        return "\"\"";
    }
    if (!_synthCtx) _synthCtx = std::make_shared<CodeGenContext>(std::make_shared<std::string>("<interp>"));
    CodeGenContext& ctx = *_synthCtx;

    // A TAGGED string `html"…${x}…"` routes literal parts + rendered holes to a tag function (Campaign 2),
    // which treats them differently (escape holes, dedent parts, bind holes as params). Handled separately
    // from the default Formatter lowering below.
    if (is->tag) return emitTaggedInterpolation(is);

    rejectIfNoHeap("string interpolation builds a heap `Formatter` buffer", is->line);   // no-heap gate
    std::string fv = "__fmt" + std::to_string(_tempCounter++);
    _hoisted.push_back("Formatter " + fv + " = Formatter__make();");
    recordDestructibleLocal(fv, "Formatter");

    size_t nh = is->holes.size();
    for (size_t i = 0; i < is->parts.size(); ++i) {
        const std::string& part = is->parts[i] ? *is->parts[i] : std::string();
        if (!part.empty()) {   // skip empty chunks (adjacent holes / empty head or tail)
            // A literal part appends directly (a borrowed literal temp -> writeStr's `ref string`); reuse the
            // StringNode emitter for correct C-escaping. No synthesized method call — the receiver `fv` is a
            // fresh C temp the method-dispatch wouldn't resolve as a class.
            std::string litExpr = emitExpression(std::make_shared<StringNode>(ctx, std::make_shared<std::string>(part)));
            std::string pv = "__ip" + std::to_string(_tempCounter++);
            _hoisted.push_back("kama_string " + pv + " = " + litExpr + ";");
            _hoisted.push_back("Formatter__writeStr(&" + fv + ", &" + pv + ");");
        }
        if (i < nh && is->holes[i])
            emitHoleInto(fv, is->holes[i], (i < is->specs.size()) ? is->specs[i] : nullptr);
    }

    // Return the `finish()` call itself (a fresh owned-string rvalue, like `a + b`), NOT a recorded temp —
    // so the enclosing assignment/return/arg takes sole ownership with no double-drop. `fv` (scope-dropped)
    // frees its now-empty buffer harmlessly after the zero-copy take.
    return "Formatter__finish(&" + fv + ")";
}

// Render ONE interpolation hole into the Formatter named `fv` (a hoisted C temp): a `${x:spec}` applies its
// specifier via a Formatter fast-path; a `char` renders its CHARACTER (char has no Formattable conformance — it
// shares uint32's cType); everything else dispatches through the real `Formattable` contract on the hole's static
// type. Shared by the plain lowering above and the per-hole render in emitTaggedInterpolation.
void CEmitter::emitHoleInto(const std::string& fv, SharedExpression hole, SharedString spec)
{
    if (!_synthCtx) _synthCtx = std::make_shared<CodeGenContext>(std::make_shared<std::string>("<interp>"));
    CodeGenContext& ctx = *_synthCtx;
    auto ident = [&](const std::string& s) { return synthId(s); };
    if (spec) { emitHoleSpec(fv, hole, *spec); return; }
    if (exprIsChar(hole)) { _hoisted.push_back("Formatter__writeChar(&" + fv + ", " + emitExpression(hole) + ");"); return; }
    // `${x}` renders through the `Formattable` contract. Check that BEFORE synthesizing the call: the
    // synthesized node carries the synth context's line (1), so letting it fail inside emitDispatch
    // reported `unknown method` against line 1 of the user's file and never named `Formattable`, the type, or
    // even the method — the one error a reader could act on, missing all four.
    {
        std::string hc = exprClass(hole);
        if (!hc.empty() && _classes.count(hc) && !satisfiesBound(hc, "Formattable")) {
            const std::string dnote = derivedUnmetNote(hc, "Formattable");
            unsupported(("`" + hc + "` cannot be interpolated — `${…}` renders a value through the "
                         "`Formattable` contract"
                         + (dnote.empty() ? std::string("; add `implements Formattable` (or "
                                                        "`@generate(Formattable)`), or call a method that "
                                                        "returns a string")
                                          : dnote)).c_str(), hole->line);
            return;   // reported; synthesizing the call would add a second error against the synth line
        }
        // The same question for a PRIMITIVE hole, which took a very different road to a much worse
        // answer: no class, so the check above did not apply, and the synthesized `format` call fell all
        // the way through method dispatch to an unresolved-receiver error naming neither the value nor
        // the interpolation. `isize`/`usize` were the ones that hit it — they were absent from every
        // `type intrinsic <…> implements …` list in the prelude until 0.9.136, and they are exactly the
        // types a `length()` or an index has, so the recommended type for every length was the one that
        // could not be logged. They implement `Formattable` now; this check stays because it is not about
        // them — any primitive reaching a hole without a conformance takes the same road.
        if (hc.empty()) {
            SharedIdentifier htn = receiverTypeNode(hole);
            const std::string hk = htn ? kamaTypeText(htn) : std::string();
            const std::string ck = receiverScalarCType(hole);
            if (!hk.empty() && !ck.empty() && !primConformance(primKeyOfCType(ck)))
                unsupported(("`" + hk + "` cannot be interpolated — `${…}` renders a value through the "
                             "`Formattable` contract, and no `Formattable` is implemented for `" + hk
                             + "`. Widen it at the hole (`cast<int64>(…)`) or render it another way").c_str(),
                            hole->line);
        }
    }
    // synthesize `<hole>.format(f: ref fv)` so the hole's static type picks the right `format`.
    auto args = std::make_shared<ArgumentList>();
    args->push_back(std::make_shared<ArgumentNode>(ctx, ident("f"),
                      std::make_shared<ModifierNode>(ctx, std::make_shared<std::string>("ref")), ident(fv)));
    auto call = std::make_shared<InvocationNode>(ctx,
                  std::make_shared<MemberAccessNode>(ctx, ident("format"), hole), args);
    // Carry the HOLE's line onto the synthesized call. Without it every diagnostic raised while lowering
    // `${x}` was reported at line 1 column 0 — a synthesized node has no position — so a mistake five
    // lines down pointed at the top of the file and named neither the hole nor the interpolation.
    call->line = hole->line;
    // This call is the COMPILER's lowering of `${x}`, not something the author wrote, so the
    // contract-scope gate does not apply to it: the rule is about what a primitive's API looks like in
    // SOURCE, and interpolation is how the language itself reaches `Formattable`.
    bool prevSynth = _inSynthDispatch; _inSynthDispatch = true;
    _hoisted.push_back(emitExpression(call) + ";");
    _inSynthDispatch = prevSynth;
}

// A tagged string `<tag>"lit ${hole} lit"` lowers to: render each part + hole to an owned `kama_string`, pack
// them into two C arrays, wrap a prelude `Template` (borrowed `UnsafePtr<string>` + counts) over them, and call the
// tag function `fn R <tag>(ref Template)`. The tag decides how literals (trusted) and holes (values) combine —
// escaping, dedenting, or `?`-parameter binding (holes stay out-of-band → injection-safe by construction).
// Holes render via the SAME per-hole path as plain interpolation (spec/char/Formattable), so specs compose for free.
std::string CEmitter::emitTaggedInterpolation(InterpolatedStringNode* is)
{
    CodeGenContext& ctx = *_synthCtx;

    std::string tagKey = resolveFunc(*is->tag, nullptr);
    if (!_funcs.count(tagKey)) {
        unsupported(("unknown string tag '" + *is->tag + "' — expected an imported `fn R " + *is->tag +
                    "(ref Template t)` (e.g. `html`, `sql`, `stripIndent` from std::fmt)").c_str(), is->line);
        return "\"\"";
    }

    // 1. Render each hole into its own owned `kama_string` temp; record it destructible so RAII frees it once
    //    at scope end (the C arrays below hold borrowed fat-pointer copies — never separately freed).
    std::vector<std::string> holeVars;
    for (size_t i = 0; i < is->holes.size(); ++i) {
        if (!is->holes[i]) continue;
        std::string hf = "__thf" + std::to_string(_tempCounter++);
        _hoisted.push_back("Formatter " + hf + " = Formatter__make();");
        recordDestructibleLocal(hf, "Formatter");
        emitHoleInto(hf, is->holes[i], (i < is->specs.size()) ? is->specs[i] : nullptr);
        std::string hv = "__thv" + std::to_string(_tempCounter++);
        _hoisted.push_back("kama_string " + hv + " = Formatter__finish(&" + hf + ");");
        recordDestructibleLocal(hv, "kama_string");
        holeVars.push_back(hv);
    }

    // 2. Materialize each literal part into a `kama_string` temp (string literals are non-owning — no drop).
    std::vector<std::string> partVars;
    for (size_t i = 0; i < is->parts.size(); ++i) {
        const std::string& part = is->parts[i] ? *is->parts[i] : std::string();
        std::string litExpr = emitExpression(std::make_shared<StringNode>(ctx, std::make_shared<std::string>(part)));
        std::string pv = "__tp" + std::to_string(_tempCounter++);
        _hoisted.push_back("kama_string " + pv + " = " + litExpr + ";");
        partVars.push_back(pv);
    }

    // 3. Pack into C arrays (a zero-length array is illegal C → use NULL when there are no holes).
    std::string pa = "__tpa" + std::to_string(_tempCounter++);
    { std::string s = "kama_string " + pa + "[" + std::to_string(partVars.size()) + "] = {";
      for (size_t i = 0; i < partVars.size(); ++i) s += (i ? ", " : " ") + partVars[i];
      s += " };"; _hoisted.push_back(s); }
    std::string holesPtr = "NULL";
    if (!holeVars.empty()) {
        std::string ha = "__tha" + std::to_string(_tempCounter++);
        std::string s = "kama_string " + ha + "[" + std::to_string(holeVars.size()) + "] = {";
        for (size_t i = 0; i < holeVars.size(); ++i) s += (i ? ", " : " ") + holeVars[i];
        s += " };"; _hoisted.push_back(s);
        holesPtr = ha;
    }

    // 4. Wrap a `Template` over the borrowed arrays (designated init — robust to field layout).
    std::string tv = "__tmpl" + std::to_string(_tempCounter++);
    _hoisted.push_back("Template " + tv + " = { ._parts = " + pa + ", ._nparts = " + std::to_string(partVars.size()) +
                       ", ._holes = " + holesPtr + ", ._nholes = " + std::to_string(holeVars.size()) + " };");

    // 5. Call the tag: `<tag>(&__tmpl)` returns a fresh owned R (like Formatter__finish), which the enclosing
    //    assignment/return/arg takes ownership of. Hand-emitted via the resolved cName (bypasses named-arg
    //    matching, so the tag's Template parameter may have any name).
    return _funcs[tagKey].cName + "(&" + tv + ")";
}

// Escape a decoded string's bytes into the body of a C `"..."` literal (no surrounding quotes). Shared by
// `StringNode` lowering and inline-asm lowering — the asm path in particular relies on `\n`/quote/backslash
// escaping so a multi-instruction `asm("cpsid i\n\tdsb")` produces a well-formed C string.
std::string CEmitter::cEscapeStringBody(const std::string& s)
{
    std::string out;
    out.reserve(s.size());
    for (char c : s) {
        switch (c) {
            case '\\': out += "\\\\"; break;
            case '"':  out += "\\\""; break;
            case '\n': out += "\\n";  break;
            case '\t': out += "\\t";  break;
            case '\r': out += "\\r";  break;
            default:   out += c;      break;
        }
    }
    return out;
}

std::string CEmitter::emitExpression(SharedExpression expr)
{
    if (!expr) return "";
    ASTNode* n = expr.get();

    if (auto* mm = dynamic_cast<MatchNode*>(n)) return emitMatch(mm);   // value-producing match (lifted)
    if (auto* al = dynamic_cast<ArrayLiteralNode*>(n)) return emitArrayLiteral(al);   // `[…]` -> a Fixed value
    if (auto* iso = dynamic_cast<IsolateNode*>(n)) return emitIsolateExpr(iso);   // `= isolate worker(...)` handle

    // 5b-B. A wide unsuffixed literal that reached emission without a destination claiming it. Contextual
    // literal typing gives a literal its destination's type and `int32` when nothing constrains it — this
    // one constrains nothing and does not fit `int32`, so there is no type to give it. Reported HERE
    // rather than at the parse, because only here is it known whether a destination spoke for it.
    if (expr->wideUnsuffixed && !_litGoverned.count(n)) {
        std::string mag;
        if (auto* s = dynamic_cast<Int64Node*>(n))       mag = std::to_string((long long)s->value);
        else if (auto* u = dynamic_cast<UInt64Node*>(n)) mag = std::to_string((unsigned long long)u->value);
        unsupported(("integer literal `" + mag + "` does not fit `int32`, the width of an unsuffixed "
                     "literal, and nothing here says which width to use — write it (`" + mag + "i64`, `"
                     + mag + "ui64`), or give it a destination whose type it can take").c_str(), expr->line);
    }
    if (auto* v = dynamic_cast<Int8Node*>(n))   return std::to_string((int)v->value);
    if (auto* v = dynamic_cast<Int16Node*>(n))  return std::to_string((int)v->value);
    if (auto* v = dynamic_cast<Int32Node*>(n))  return std::to_string(v->value);
    // INT64_MIN has no C literal: `-9223372036854775808LL` is the unary minus applied to a magnitude one
    // past LLONG_MAX, which no signed type holds, so C gives it an unsigned type (and clang warns). The
    // idiomatic spelling — what <stdint.h> itself uses for INT64_MIN — is one less, minus one. Reachable
    // since 5b-C gave INT64_MIN a suffixed spelling (`-9223372036854775808i64`).
    if (auto* v = dynamic_cast<Int64Node*>(n)) {
        if ((int64_t)v->value == INT64_MIN) return "(-9223372036854775807LL - 1)";
        return std::to_string((long long)v->value) + "LL";
    }
    if (auto* v = dynamic_cast<UInt8Node*>(n))  return std::to_string((unsigned)v->value) + "U";
    if (auto* v = dynamic_cast<UInt16Node*>(n)) return std::to_string((unsigned)v->value) + "U";
    if (auto* v = dynamic_cast<UInt32Node*>(n)) return std::to_string(v->value) + "U";
    if (auto* v = dynamic_cast<CharNode*>(n))   return std::to_string(v->value) + "U";   // codepoint literal
    if (auto* v = dynamic_cast<UInt64Node*>(n)) return std::to_string((unsigned long long)v->value) + "ULL";

    if (auto* v = dynamic_cast<Float64Node*>(n)) {
        char buf[64];
        std::snprintf(buf, sizeof(buf), "%.17g", v->value);
        std::string s(buf);
        // A whole-number %g (`100`) emits a C *integer* literal, so `100.0f64 / 8.0f64` would become the
        // integer division `100 / 8` (== 12, not 12.5). Force a decimal point to keep it a double literal.
        if (s.find('.') == std::string::npos && s.find('e') == std::string::npos
            && s.find('E') == std::string::npos && s.find_first_of("0123456789") != std::string::npos)
            s += ".0";
        return s;
    }
    if (auto* v = dynamic_cast<Float32Node*>(n)) {
        char buf[64];
        std::snprintf(buf, sizeof(buf), "%.9g", (double)v->value);
        std::string s(buf);
        // A whole-number %g (`16`) needs a decimal point before the `f` suffix — `16f` is an INVALID C
        // literal (integer with a float suffix). Make it `16.0f`. (`2.5`/`1e9` already have `.`/`e`.)
        if (s.find('.') == std::string::npos && s.find('e') == std::string::npos
            && s.find('E') == std::string::npos && s.find_first_of("0123456789") != std::string::npos)
            s += ".0";
        return s + "f";
    }
    if (auto* v = dynamic_cast<BooleanNode*>(n)) return v->value ? "true" : "false";
    if (dynamic_cast<NullNode*>(n))              return "NULL";

    if (auto* h = dynamic_cast<HandoffNode*>(n)) {
        // `give x` / `copy x`. The move (invalidate source) / retain side effects
        // need a statement context — handled where a value is HANDED OFF: an initializer,
        // assignment, argument, or return (emitDeclarator / the assignment arm / emitReorderedCall
        // / the return arm all unwrap the marker). Reaching here means the marker rides a bare
        // sub-expression (e.g. `give x` used as a statement or inside a larger expression), which
        // isn't a hand-off position — only a plain-value `copy` (a value copy) would be complete.
        std::string ic = exprClass(h->value);
        // A marker on an OWNED value (smart-ptr / collection / any destructible resource) in a bare
        // sub-expression is a position error. On a plain value it's harmless — `give`/`copy` of a value
        // is just that value (a copy), so yield it.
        bool owned = isSmartPtrClass(ic)
                   || (!ic.empty() && _classes.count(ic) && (_classes[ic].isIntrinsicColl || _classes[ic].destructible));
        if (owned)
            unsupported("`give`/`copy` mark a value being handed off — an initializer, assignment, argument, "
                        "or return — not a bare sub-expression", h->line);
        return emitExpression(h->value);
    }

    if (auto* v = dynamic_cast<StringNode*>(n)) {
        // Lower to a borrowed runtime string. The lexer already produced the raw bytes; emit them as a
        // C string-literal body (shared with inline-asm lowering via cEscapeStringBody).
        const std::string& s = v->value ? *v->value : std::string();
        return "kama_string_lit(\"" + cEscapeStringBody(s) + "\", " + std::to_string(s.size()) + ")";
    }

    if (auto* is = dynamic_cast<InterpolatedStringNode*>(n)) return emitInterpolation(is);

    if (auto* v = dynamic_cast<IdentifierNode*>(n)) {
        // Variable/parameter reference. Qualified/member resolution is later.
        std::string nm = v->value ? *v->value : "";
        // Enum member `[Ns.]Enum.Member` (value=Member, qualifier=[…,Enum]) —
        // resolve the enum name (last qualifier segment) through the file's scope.
        if (v->qualifier && !v->qualifier->empty()) {
            auto enumQual = std::make_shared<StringList>();
            for (size_t i = 0; i + 1 < v->qualifier->size(); ++i) enumQual->push_back((*v->qualifier)[i]);
            std::string en = resolveUserName(*v->qualifier->back(), enumQual);
            // The enum is a name this file spells, so it is judged for reach like any other — without a site
            // above, `geo::HidErr::Bad` named a PRIVATE enum and compiled (KR-46). Directly, not by passing
            // `v` as the site: that would also record the reference on the MEMBER's span.
            if (!v->synthesized)
                checkReach(en, *v->qualifier->back(), "this reference", v->line, refFilePath(), !enumQual->empty());
            // `v`'s span is just the MEMBER name (qualified_identifier reuses the basic_identifier node),
            // so recording the use here points find-references/rename at `Member`, not at `Enum::Member`.
            // Only a MEMBER of the enum resolves here; `K::ZZZ` used to be emitted as `K_ZZZ` for the C
            // compiler to refuse. A miss falls through (an enum can carry `Type::NAME` constants and
            // contract methods, resolved below) and ends in rejectUnresolvedName, which names the enum.
            // A generic payload-less enum names its TEMPLATE (`Side::R`); the instance is the target's.
            const std::string een = scalarEnumInstanceOf(en);
            if (_enums.count(een))
                for (auto& m : _enums[een].members)
                    if (m.name == nm) { recordRef(enumMemberKey(een, nm), v); return een + "_" + nm; }
            // `Union::Variant` with no payload -> `(Union){ .tag = Union_Variant }`
            // (`Optional<int32>::None` resolves the instance via the target-type context).
            if (ClassInfo* vt = resolveVariantType(en))
                for (auto& vc : vt->variants)
                    if (vc.name == nm) {
                        recordRef(enumMemberKey(vt->name, nm), v);
                        return emitVariantConstruction(*vt, nm, SharedArgumentList(), v->line);
                    }
            // 6b-2: `Type::NAME` -> a type-associated `comptime` constant. Access-checked (public/private,
            // same as a field), then read through its real `static const` symbol.
            {
                auto tc = _typeConsts.find(en + "::" + nm);
                if (tc != _typeConsts.end()) {
                    auto oc = _classes.find(tc->second.owner);
                    canAccess(oc != _classes.end() ? &oc->second : nullptr, tc->second.visibility, nm, v->line);
                    return tc->second.cName;
                }
            }
            // `::` resolves MODULES and TYPES; `.` is instance/value access (SPEC "Scope resolution
            // uses `::`"). So a `::` head that is a local, a parameter or a field is a spelling error for
            // `.`, not a second way to reach a member — accepting it would give the language two ways to
            // write field access, one of them undocumented. Every static form keeps a TYPE or MODULE
            // head (`Vec2::dot`, `Type::NAME`, `Color::Blue`, `mod::counter`) and is resolved above, so
            // this rejects only the value-headed spelling.
            const std::string& head = *(*v->qualifier)[0];
            if (_localTypes.count(head) || (_currentClass && findFieldOwner(_currentClass, head))) {
                std::string dotted = head;   // the whole path respelled, not just the two ends
                for (size_t i = 1; i < v->qualifier->size(); ++i) dotted += "." + *(*v->qualifier)[i];
                unsupported(("`" + head + "` is a value — reach its members with `.` (`" + dotted + "."
                             + nm + "`); `::` resolves modules and types").c_str(), v->line);
            }
        }
        // A comptime parameter (`const F: int32`) read as a VALUE — the bound integer, spelled
        // with its declared width. A compile-time binder outranks every runtime name, so this arm sits
        // ahead of the ref-param, field and local paths — and nothing else may bind the name, which is
        // what makes that outranking safe rather than silent. The three rejections that hold it up:
        // a parameter or field of the same name at `checkDeclaredTypes` (`constParamShadow`, which
        // reaches an uninstantiated generic too), a local at `emitDeclarator`'s shadowing block, and a
        // write at `checkConstWrite`. Each is pinned by a `tests/xfail/constparam_*` fixture.
        if (!v->qualifier || v->qualifier->empty()) {
            std::string cpv = constParamCValue(nm);
            if (!cpv.empty()) return cpv;
        }
        // A QUALIFIED name resolves through its qualifier and nothing else. The two arms below used to
        // ignore it, so `S::x` inside a method of a class with a field `x` resolved to `self->x` — and
        // built, and ran (tests/xfail/scope_op_field_leak).
        const bool qualified = v->qualifier && !v->qualifier->empty();
        // A ref/out parameter is a pointer in C; reads dereference it.
        if (!qualified && _refParams.count(nm)) { recordRef(bindingKeyOf(nm), v); return "(*" + nm + ")"; }
        // An unqualified name that is a field of the enclosing class (or an
        // ancestor) and not a local/param resolves to self->[__base.]…field.
        if (!qualified && _currentClass && !_localTypes.count(nm)) {
            ClassInfo* owner = findFieldOwner(_currentClass, nm);
            if (owner) {
                if (_inStaticMethod) unsupported("a `static` method has no `this` — access the field through an instance", v->line);
                // In a `ctor` the value under construction is named `this` and its fields are reached only
                // through it. A bare name is therefore always a local or a param — which is what lets a
                // ctor write `int32 fd = openRaw(…); this.fd = fd;` without the two `fd`s colliding. Say so
                // rather than silently resolving to the field, which would make the two spellings differ.
                if (_inNamedCtorBody)
                    unsupported(("'" + nm + "' is a field of '" + owner->name + "' — inside a constructor, "
                                 "reach it through the value being built: `this." + nm + "`").c_str(), v->line);
                _ctorSelfUsed = true;           // in a ctor: the implicit `this` storage is needed
                checkFieldAccess(owner, nm, v->line);
                recordFieldRef(owner, nm, v);   // implicit `this.` field read
                return "self->" + basePathTo(_currentClass, owner) + nm;
            }
        }
        // A bare **function name** used as a value (not a call) → its C function
        // pointer — enables binding/passing a free function to a FunctionPtr.
        if (!_localTypes.count(nm)) {
            auto fit = _funcs.find(resolveFunc(nm, v->qualifier));
            if (fit != _funcs.end()) return symbolOf(fit->second);
            // A bare name that is a module-level `static` (MCU step 1) → its qualified C symbol.
            // The file rung applies here exactly as it does to a type or a call: a module-scope name
            // reaches another file only through that file's `export { … };`. Without this the reference
            // resolved silently and failed in the C compiler instead — see _moduleVarFile.
            const std::string key = resolveModuleVar(nm, v->qualifier);
            if (!key.empty()) {
                if (!v->synthesized)
                    checkReach(key, nm, "this reference", v->line, refFilePath(),
                               v->qualifier && !v->qualifier->empty());
                recordStaticRead(key, nm, v->line);   // the foreign-entry walk's read fact — this is the one funnel
                return key;
            }
            // `extern const T NAME;` (KR-56) → the C constant's own spelling; the header owns the value.
            const std::string xk = resolveExternConst(nm, v->qualifier);
            if (!xk.empty()) {
                if (!v->synthesized)
                    checkReach(xk, nm, "this reference", v->line, refFilePath(), v->qualifier && !v->qualifier->empty());
                recordRef(xk, v);
                return "(" + _externConsts[xk].symbol + ")";
            }
        }
        // Nothing above bound the name, and it is not a local, a parameter or a ref-param either: it
        // resolves to NOTHING. This is the arm that was missing — the spelling used to be written into the
        // C for the C compiler to refuse ("use of undeclared identifier"), on the right line and in the
        // wrong language, while `kama check` said OK. The one name allowed through is a `comptime` param
        // a probe left unbound (deferred and counted, like every probe residual).
        const bool bound = !qualified && (_localTypes.count(nm) || _paramNames.count(nm) || _refParams.count(nm));
        if (!v->synthesized && v->builtInVal == 0 && !bound) {
            if (isComptimeParamHere(nm)) { deferUnknownWhileProbing(DK_ConstParam); return nm; }
            rejectUnresolvedName(v, nm);
            return "0";
        }
        checkNotMoved(nm, v->line);   // reject reading a moved-from `resource` value
        recordRef(bindingKeyOf(nm), v);   // a local, a param, or an unindexed name (empty key => dropped)
        return nm;
    }

    if (auto* tn = dynamic_cast<ThisAccessNode*>(n)) {
        if (_inStaticMethod) unsupported("a `static` method has no `this`", tn->line);
        _ctorSelfUsed = true;               // in a ctor: the implicit `this` storage is needed
        return "self";
    }

    if (auto* v = dynamic_cast<MemberAccessNode*>(n)) {
        return emitMemberAccess(v);
    }

#if KAMA_INHERITANCE
    if (auto* ba = dynamic_cast<BaseAccessNode*>(n)) {
        // base.field (bare; base.method(...) is handled in emitInvocation).
        std::string name = (ba->identifier && ba->identifier->value) ? *ba->identifier->value : "";
        if (_currentClass && _currentClass->base) {
            ClassInfo* owner = findFieldOwner(_currentClass->base, name);
            if (owner) { checkFieldAccess(owner, name, ba->line);
                         recordFieldRef(owner, name, ba->identifier.get());
                         return "self->__base." + basePathTo(_currentClass->base, owner) + name; }
        }
        // Say what actually happened. This used to report the bare fragment "base access", naming
        // neither the member nor the type — the two failures below are quite different problems.
        if (!_currentClass)
            unsupported("`base` is only meaningful inside a method of a derived type", ba->line);
        else if (!_currentClass->base)
            unsupported(("'" + _currentClass->name + "' has no base class, so `base` names nothing "
                         "(only a type declared `extends …` has one)").c_str(), ba->line);
        else
            unsupported(("'" + name + "' is not a field of the base class '" + _currentClass->base->name
                         + "'").c_str(), ba->line);
        return name;
    }
#endif

    if (auto* v = dynamic_cast<ObjectCreationNode*>(n)) {
        // `new T(...)` is supported only as a local-variable initializer
        // (handled in LocalVariableDeclaration). Bare expression position needs
        // a temp/statement context that arrives with RAII.
        unsupported("`new` outside a local-variable initializer", v->line);
        return "0";
    }

    if (auto* v = dynamic_cast<BinaryExpressionNode*>(n)) {
        // GOALS §3b: `== null` / `!= null` on a safe type is a compile error — a value,
        // smart pointer, or contract is never null (the C habit checks the wrong thing here).
        // `null` is only for `UnsafePtr<T>` at the FFI boundary (exprClass is empty for those).
        if (v->token == EQEQ || v->token == NOTEQ) {
            bool lNull = dynamic_cast<NullNode*>(v->LHS.get()) != nullptr;
            bool rNull = dynamic_cast<NullNode*>(v->RHS.get()) != nullptr;
            if (lNull != rNull) {
                std::string oc = neverNullType(lNull ? v->RHS : v->LHS);
                if (!oc.empty())
                    unsupported(("`" + oc + "` is never null in safe code — don't null-check it "
                                 "(a `Weak` uses `tryUpgrade`; `null` is only for `UnsafePtr<T>` at the FFI boundary)").c_str(),
                                v->line);
            }
        }
        return emitBinaryOperator(v->token, v->LHS, v->RHS, v->line);   // user operand → dispatch, else raw C
    }

    if (auto* v = dynamic_cast<LogicalAndOrNode*>(n)) {
        std::string op = (v->token == ANDAND) ? "&&" : "||";
        return "(" + emitExpression(v->LHS) + " " + op + " " + emitExpression(v->RHS) + ")";
    }

    if (auto* v = dynamic_cast<TernaryExpressionNode*>(n)) {
        return "(" + emitExpression(v->condition) + " ? " + emitExpression(v->LHS)
                   + " : " + emitExpression(v->RHS) + ")";
    }

    if (auto* v = dynamic_cast<InvocationNode*>(n)) {
        return emitInvocation(v);
    }

    if (auto* v = dynamic_cast<AssignmentNode*>(n)) {
        checkConstWrite(v->unaryExpression, v->line);   // no write to/through const
        if (v->token == EQ) rejectConstPtrWiden(lvalueCType(v->unaryExpression), v->expression, "this assignment", v->line);
        // A plain `=` STORES to its target: the LHS mention that follows is a write, not a read, and the
        // foreign-entry walk must not count it (writing a static inside the region is per-thread scratch).
        // A compound `+=` reads first, so it keeps the read; `recordStaticRead` consumes this once.
        if (v->token == EQ && v->unaryExpression) {
            const std::string root = rootBinding(v->unaryExpression);
            if (!root.empty() && root != "this" && !_localTypes.count(root) && !_paramNames.count(root)
                && !(_currentClass && findFieldOwner(_currentClass, root)))
                _staticWriteLhs = resolveModuleVar(root, nullptr);
        }
        // The window defeated from the INSIDE. An alias names one window over one place for the extent of
        // one block; reseating it to some other container's view keeps the name and drops the bound, so
        // the rest of the block reads a view nothing froze. A reseat is the BARE alias on the left — a write
        // THROUGH it (`v[0] = x`, `v.f = x`) is what a mutate-through window is for. This used to test the
        // root binding, which collapses `v[0]` to `v`, and so refused every element write inside a
        // `borrow d.viewMut() as v { … }` as a reseat.
        if (auto* lid = dynamic_cast<IdentifierNode*>(v->unaryExpression.get()))
            if (lid->value && (!lid->qualifier || lid->qualifier->empty()))
                if (const std::vector<std::string>* r = frozenAliasRoot(*lid->value))
                    unsupported(("`" + *lid->value + "` is a `borrow` alias — it names the "
                                 "window over `" + placeText(*r) + "` and cannot be reseated, or the rest of "
                                 "the block would hold a view of storage this window never froze. Open another "
                                 "`borrow`, or derive with `.slice(…)`").c_str(), v->line);
        // The STORE direction of the `== null` rule, for an assignment rather than a declaration (where
        // `rejectNullInit` handles it): a safe type is never null, so writing one there is the same
        // mistake. Keyed on the LHS's class exactly as the comparison arm is — empty means an
        // `UnsafePtr`/FFI slot, which is the one place `null` belongs.
        if (v->token == EQ && dynamic_cast<NullNode*>(v->expression.get())) {
            std::string lc = neverNullType(v->unaryExpression);
            if (!lc.empty())
                unsupported(("`" + lc + "` is never null in safe code, so it cannot be assigned `null` "
                             "— `null` is only for `UnsafePtr<T>` at the FFI boundary. Use a zero value, "
                             "or `Optional<T>` to model absence").c_str(), v->line);
        }
        // Indexed assignment to a collection lowers to __set, not `lhs = rhs`.
        if (auto* ea = dynamic_cast<ElementAccessNode*>(v->unaryExpression.get())) {
            std::string coll, recvExpr, idx;
            if (collectionElemAccess(ea, coll, recvExpr, idx)) {
                std::string rhs = emitExpression(v->expression);
                if (v->token == EQ)
                    return coll + "__set(&(" + recvExpr + "), " + idx + ", " + rhs + ")";
                // Compound (a[i] += x): mutate the element in place through the bounds-checked `*__at`
                // place — the index is evaluated ONCE (no double `__get`+`__set`), and a nested
                // `a[i][j] += x` works because `recvExpr` is itself a place.
                // An arithmetic compound goes through the place operator with the `__at` POINTER — the
                // index is evaluated once, the sub-`int` result is range-checked, `/=` checks its divisor.
                if (*placeOpMacro(v->token))
                    return std::string(placeOpMacro(v->token)) + "(" + coll + "__at((" + coll + "*)&(" + recvExpr + "), " + idx
                         + "), (" + rhs + "))";
                return "((*" + coll + "__at((" + coll + "*)&(" + recvExpr + "), " + idx + ")) "
                            + assignmentOperator(v->token) + " (" + rhs + "))";
            }
            // A user place-returning `operator[]`: assign/compound-assign THROUGH the place.
            if (indexesUserOp(ea)) {
                std::string place = emitPlace(v->unaryExpression);
                std::string rhs = emitExpression(v->expression);
                if (*placeOpMacro(v->token))
                    return std::string(placeOpMacro(v->token)) + "(&(" + place + "), (" + rhs + "))";
                return "(" + place + " " + assignmentOperator(v->token) + " (" + rhs + "))";
            }
            // Raw pointer store `p[i] = v` — only inside an `unsafe fn`.
            SharedExpression recv = ea->expression ? ea->expression
                                  : std::static_pointer_cast<ExpressionNode>(ea->identifier);
            std::string ridx = (ea->expressionlist && !ea->expressionlist->empty())
                             ? emitExpression((*ea->expressionlist)[0]) : "0";
            if (!_inUnsafe) {
                unsupported("raw pointer access requires an `unsafe fn`", ea->line);
                return "0";
            }
            // (not during a poisoned instance's re-walk — the user's spelling was reported already)
            if (_typeSubst.empty() && rawElemIsCChar(v->unaryExpression)) { rejectBareCChar(synthId("cchar", IDENTIFIER_CCHAR_VAL), "an element written through the pointer", ea->line); return "0"; }
            if (*placeOpMacro(v->token))
                return std::string(placeOpMacro(v->token)) + "(&((" + emitExpression(recv) + ")[" + ridx + "]), ("
                     + emitExpression(v->expression) + "))";
            return "((" + emitExpression(recv) + ")[" + ridx + "] "
                       + assignmentOperator(v->token) + " " + emitExpression(v->expression) + ")";
        }
        // compound assignment on a user type (`a += b`) lowers to `a = a <op> b` via the
        // operator, since a struct has no built-in `+=`. Plain `=` and primitives keep the raw path.
        int binTok = compoundToBinary(v->token);
        if (binTok && userOperandType(exprClass(v->unaryExpression), _classes))
            return "(" + emitExpression(v->unaryExpression) + " = "
                       + emitBinaryOperator(binTok, v->unaryExpression, v->expression, v->line) + ")";
        // A COMPOUND assignment on primitives is an operand pair — `x += y` is `x = x <op> y` — and it is
        // the one shape the assignment hand-off at `emitStatement` deliberately excludes (it is not a
        // hand-off: the destination's type is already the result's). So the operand rule is what covers
        // it, and this is where it is measured. Plain `=` is excluded here because it IS that hand-off.
        if (binTok) {
            noteNumericOperands(binTok, v->unaryExpression, v->expression,
                                assignmentOperator(v->token).c_str(), v->line);
            noteTypeIdentityOperands(binTok, v->unaryExpression, v->expression,
                                     assignmentOperator(v->token).c_str(), v->line);
            rejectMixedOperands(binTok, v->unaryExpression, v->expression,
                                assignmentOperator(v->token), v->line);
        }
        // Arithmetic and shift compounds on a primitive place: `KAMA_ADDEQ(&(x), y)` — see placeOpMacro.
        // A `hardware` (volatile) static and a `ref` parameter (already a pointer, so `&(*p)`) both work.
        if (*placeOpMacro(v->token))
            return std::string(placeOpMacro(v->token)) + "(&(" + emitExpression(v->unaryExpression) + "), ("
                 + emitExpression(v->expression) + "))";
        std::string lhs = emitExpression(v->unaryExpression);
        std::string rhs = emitExpression(v->expression);
        if (v->token == EQ) rhs = narrowViewValue(lvalueCType(v->unaryExpression), v->expression, rhs, v->line);
        return "(" + lhs + " " + assignmentOperator(v->token) + " " + rhs + ")";
    }

    if (auto* ea = dynamic_cast<ElementAccessNode*>(n)) {
        std::string coll, recvExpr, idx;
        if (collectionElemAccess(ea, coll, recvExpr, idx)) {
            // `__get` borrows its receiver by address (`&recv`). A string RVALUE receiver — a literal
            // (`"abc"[0]`, emitted as a `kama_string_lit(…)` call) or a computed piece (`s.concat(x)[0]`) —
            // has no address, so materialize it into a temp first (single-eval: reuse the already-emitted
            // `recvExpr`, don't re-emit). A named var / field / `this` stays a direct borrow. A computed
            // temp that owns a heap buffer is RAII-dropped at scope end.
            // The receiver is `ea->expression`, or `ea->identifier` for a bare-name receiver (`s[i]`).
            ASTNode* recvNode = ea->expression ? ea->expression.get()
                              : (ea->identifier ? (ASTNode*)ea->identifier.get() : nullptr);
            bool addressable = isStableStringRef(recvNode) && !dynamic_cast<StringNode*>(recvNode);
            if (coll == "kama_string" && _hoistOK && !addressable) {
                std::string t = "__stridx" + std::to_string(_tempCounter++);
                _hoisted.push_back("kama_string " + t + " = " + recvExpr + ";");
                recordDestructibleLocal(t, "kama_string");
                return coll + "__get(&" + t + ", " + idx + ")";
            }
            return coll + "__get((" + coll + "*)&(" + recvExpr + "), " + idx + ")";
        }
        // A user place-returning `operator[]`: read the value out of the place.
        if (indexesUserOp(ea)) return emitPlace(expr);
        // Raw pointer read `p[i]` — only inside an `unsafe fn`.
        SharedExpression recv = ea->expression ? ea->expression
                              : std::static_pointer_cast<ExpressionNode>(ea->identifier);
        std::string ridx = (ea->expressionlist && !ea->expressionlist->empty())
                         ? emitExpression((*ea->expressionlist)[0]) : "0";
        if (!_inUnsafe) {
            unsupported("raw pointer access requires an `unsafe fn`", ea->line);
            return "0";
        }
        if (_typeSubst.empty() && rawElemIsCChar(expr)) { rejectBareCChar(synthId("cchar", IDENTIFIER_CCHAR_VAL), "an element read through the pointer", ea->line); return "0"; }
        return "(" + emitExpression(recv) + ")[" + ridx + "]";
    }

    if (auto* v = dynamic_cast<PreIncrDecrNode*>(n)) {
        checkConstWrite(v->expression, v->line);
        std::string uop = emitUnaryUserOp(v->token, v->expression, v->line);   // op_inc/op_dec on a user type
        if (!uop.empty()) return uop;
        // `++x` is `x += 1` — the place operator, by address: checked at every width, evaluated once.
        return std::string(v->token == PLUSPLUS ? "KAMA_ADDEQ(&(" : "KAMA_SUBEQ(&(")
             + emitExpression(v->expression) + "), 1)";
    }

    if (auto* v = dynamic_cast<PostIncrDecrNode*>(n)) {
        checkConstWrite(v->expression, v->line);
        std::string uop = emitUnaryUserOp(v->token, v->expression, v->line);   //  (mutating in place — pre/post alike)
        if (!uop.empty()) return uop;
        // `x++` hands back the OLD value (tests/post_increment_expr) through the post variant.
        return std::string(v->token == PLUSPLUS ? "KAMA_POSTADD(&(" : "KAMA_POSTSUB(&(")
             + emitExpression(v->expression) + "), 1)";
    }

    if (auto* v = dynamic_cast<SimpleUnaryExpressionNode*>(n)) {
        std::string uop = emitUnaryUserOp(v->token, v->expression, v->line);   // op_neg/op_not/op_bnot/op_pos
        if (!uop.empty()) return uop;
        std::string op;
        switch (v->token) {
            case EXCLAMATION: op = "!"; break;
            case TILDE:       op = "~"; break;
            case PLUS:        op = "+"; break;
            case MINUS:       op = "-"; break;
            default:          op = "/*?unary*/"; break;
        }
        // The unary half of D-arith. `~` and `-` and `+` carry the operand's type through — `typeOfExpr`
        // has always said so — but C promotes a sub-`int` operand first, so `~u` on a `uint8` came back
        // with the high bits set and `cast<int32>(~15ui8)` answered -16 instead of 240. `!` is excluded:
        // it yields `bool` and its operand is not a number. Same four types, same reasoning, as the
        // binary half above.
        if (v->token != EXCLAMATION) {
            const std::string t = typeOfExpr(v->expression);
            if (cNumBits(t) && cNumBits(t) < 32 && !cNumFloat(t)) {
                // `-x` on a signed sub-`int` is the one unary overflow (`-(-128i8)` is 128): range-checked
                // like the binary half, trapping in debug and truncating in release.
                std::string lo, hi;
                if (v->token == MINUS && cNumSigned(t) && cNumRangeText(t, lo, hi))
                    return "KAMA_ARITH_NARROW(" + t + ", " + lo + ", " + hi + ", -(long long)("
                         + emitExpression(v->expression) + "))";
                return "(" + t + ")(" + op + emitExpression(v->expression) + ")";
            }
            // ...and at 32/64 bits `-TYPE_MIN` overflows too: KAMA_NEG traps in debug, wraps in release.
            if (v->token == MINUS && (t == "int32_t" || t == "int64_t"))   // operand written once — see KAMA_NEG_T
                return std::string("KAMA_NEG_T(") + arithSuffix(t) + ", " + emitExpression(v->expression) + ")";
            if (v->token == MINUS && (t.empty() || (cNumBits(t) && !cNumFloat(t)) || cNumFloat(t)))
                return "KAMA_NEG(" + emitExpression(v->expression) + ")";
        }
        return "(" + op + emitExpression(v->expression) + ")";
    }

    if (auto* v = dynamic_cast<CastNode*>(n)) {
        std::string target = cType(v->type);
        if (rejectBareCChar(v->type, "a cast target", v->line)) return "0";
        checkBodyType(v->type, "a cast target", v->line);
        std::string nm = (v->type && v->type->value) ? *v->type->value : target;
        // `try cast` is a STATEMENT form (see emitTryCast) — the declaration path and the value-position
        // hoist (tryHoistInlineValue) intercept it before the expression walk. Arriving here means it was
        // written somewhere with no `Optional<T>` destination to read at all (nested inside another
        // expression, say), which is `try new`'s rule and its diagnostic's shape.
        if (v->isTry) {
            unsupported(("`try cast<" + nm + ">(…)` needs a declared `Optional<" + nm
                         + ">` destination — a local, an argument, or the function's return type — that is "
                           "where its result type comes from. For a value that must "
                           "not fail use `cast<" + nm + ">(…)`, and to keep the low bits use `truncate<"
                         + nm + ">(…)`").c_str(), v->line);
            return "0";
        }
        // Containment: `cast<UnsafePtr<T>>(…)` MAKES a raw pointer out of an integer or another pointer —
        // one of the two production sites (the other is `addr(of:)`). It stays possible, which is what
        // keeps MMIO writable; it just cannot happen in a function carrying no marker.
        if (namesUnsafePtr(v->type)) rejectRawOutsideUnsafe("`cast<UnsafePtr<…>>(…)`", v->line);
        // A cast lowers to a C cast, and C casts only between SCALARS and POINTERS. Anything that lowers to
        // an aggregate produces `((Pair)(x))`, which the C compiler rejects — and used to reject with no
        // kama diagnostic at all, naming a mangled type the user never wrote.
        //
        // The test is "is this a kama type with a struct body", i.e. anything in `_classes` (a value/resource/
        // view, a collection, a smart pointer, `string` -> kama_string, a tagged enum) or a contract. It is
        // deliberately NOT a whitelist of scalars: an FFI type is opaque to kama (`cast<CompareFn>(c)` in
        // tests/callback_qsort.d, a C function-pointer typedef reached through `extern`), which must stay
        // legal and is not something kama can prove scalar. A plain enum reaches its own rule below —
        // it lowers to a C scalar, so this test cannot catch it, and it needs a different answer anyway.
        // Three verbs share this node, so a diagnostic must name the one that was WRITTEN. Reporting
        // `truncate<string>(…)` as `cast<string>(…)` sends the reader to a line that does not say `cast`.
        const std::string verb = v->isTruncate ? "truncate" : (v->isTry ? "try cast" : "cast");
        if (isInterface(target)) {
            // A contract value is a fat pointer that BORROWS its object; a cast has no object to borrow.
            unsupported(("`" + verb + "<" + nm + ">(…)` — a contract is not a conversion target: a contract "
                         "value borrows its object, so you get one by binding it (`" + nm + " x = obj;`) or "
                         "by passing the object where a `" + nm + "` is expected").c_str(), v->line);
            return "0";
        }
        // An enum with members has a `_classes` entry too, but it is an integer, not an aggregate: it takes
        // the enum message one rule down (an integer becomes an enum only through `try cast`), not `bitcast`.
        if (_classes.count(target) && !isEnum(target)) {
            if (opaqueScalarUnknown(target)) return "0";   // an opaque param — see the header
            unsupported(("`" + verb + "<" + nm + ">(…)` — a conversion works between scalars and pointers, "
                         "and `" + nm + "` is neither. To reinterpret a scalar's bits use `bitcast`; to "
                         "narrow a contract value to a concrete type use `expr.as<T>()`").c_str(), v->line);
            return "0";
        }
        // A plain enum is a SET of named constants, not a range, so an integer arriving from outside has
        // no reason to name one — and the infallible verb has no honest use at either end: when the value
        // is known the variant already HAS a name (`Color::Green`), and when it is not the conversion is
        // fallible by construction. `cast<Color>(200)` used to compile and hand back a `Color` that is
        // none of its variants: the one narrowing conversion in the language that went unchecked, while
        // `cast<int8>(300)` has trapped since 0.9.30. Rust refuses this direction outright (`200u8 as
        // Color` is E0605, and so is `0u8 as Color` — validity does not enter into it); enum -> INT stays
        // legal here as it does there, because it is total. `try cast<Color>(x)` is the door, and the
        // `Optional` it yields is consumed by `match` — the one construct that reads an enum.
        //
        // `truncate` is excluded so its own message wins below: it keeps low bits, and pointing its
        // reader at `try cast` would answer a question they did not ask.
        if (!v->isTruncate && isEnum(target)) {
            unsupported(("`" + verb + "<" + nm + ">(…)` — an integer is not a `" + nm + "` until it has "
                         "been checked against the variants. Name the variant when you know it "
                         "(`" + nm + "::…`), or use `try cast<" + nm + ">(…)` for a value from outside, "
                         "which yields `Optional<" + nm + ">`").c_str(), v->line);
            return "0";
        }
        // A CONSTANT that provably does not fit the target. `cast<int8>(300)` silently produced 44, and
        // nothing in the language said so — the value is knowable here, the compiler already has the
        // folder, and truncating a number the author wrote in full is not a conversion, it is a
        // different number. Precedent: xfail/constgen_oob rejects a constant out-of-range array index
        // while a dynamic one traps at runtime.
        //
        int64_t lo, hi, cv;
        if (primIntRange(v->type, lo, hi) && constValue(v->unaryExpression, cv) && (cv < lo || cv > hi)) {
            rejectConstCastOverflow(v->type, cv, lo, hi, v->line);
            return "0";
        }
        // `truncate<T>` keeps the LOW BITS, so a widening target is a contradiction: there are no bits to
        // drop, and the two verbs would mean the same thing. Zig rejects a widening `@truncate` for the
        // same reason. Only a PROVABLE widening is rejected — an unknown source stays silent, like every
        // other rule in this campaign.
        if (v->isTruncate) {
            std::string tlo, thi;
            const std::string src = typeOfExpr(v->unaryExpression);
            if (!cNumRangeText(target, tlo, thi))
                unsupported(("`truncate<" + nm + ">(…)` keeps the low bits of an integer, and `" + nm
                             + "` is not one. To reinterpret a scalar's bits use `bitcast`, and to convert "
                               "a value use `cast`").c_str(), v->line);
            else if (!src.empty() && (cNumBits(src) || cNumTargetWidth(src)) && !cNumFloat(src)
                     && cNumContains(target, src) && target != src)
                unsupported(("`truncate<" + nm + ">(…)` drops the high bits, but every `"
                             + primKeyOfCType(src) + "` already fits `" + nm
                             + "` — write `cast<" + nm + ">(…)`").c_str(), v->line);
        }
        // And the RUNTIME half, which the sentence above used to defer. `cast<T>` preserves the VALUE, so
        // a value that does not fit `T` is not a conversion but a different number — the same reasoning,
        // now applied where the number is only knowable at runtime. `truncate<T>` keeps the low bits and
        // `try cast<T>` yields `Optional<T>`; both skip this.
        if (!v->isTruncate && !v->isTry) {
            const std::string checked = narrowCheck(target, v->unaryExpression);
            if (!checked.empty()) return checked;   // (declines for an enum source — a kind crossing, not a narrowing)
        }
        // Enum -> integer is TOTAL and stays legal (SPEC § *Enums*): every payload-less enum is its integer.
        return "((" + target + ")(" + emitExpression(v->unaryExpression) + "))";
    }

    if (auto* v = dynamic_cast<BitcastNode*>(n)) return emitBitcast(v);

    if (auto* ad = dynamic_cast<AsDowncastNode*>(n)) return emitAsDowncast(ad);

    // `sizeof(T)`/`alignof(T)` -> C `sizeof(<cType>)`/`_Alignof(<cType>)` (a compile-time `size_t`/
    // `usize`). `cType` resolves a generic `T` under substitution, so `n * sizeof(T)` inside a
    // `Vec<T>` monomorphizes to the concrete size. `_Alignof` is C11 (kama emits strict ISO C11).
    if (auto* v = dynamic_cast<SizeofNode*>(n)) {
        if (rejectBareCChar(v->type, v->isAlign ? "an `alignof` operand" : "a `sizeof` operand", v->line)) return "0";
        checkBodyType(v->type, v->isAlign ? "an `alignof` operand" : "a `sizeof` operand", v->line);
        return std::string(v->isAlign ? "_Alignof(" : "sizeof(") + cType(v->type) + ")";
    }

    // Compiler-internal zero-init (`(T){0}`), spliced into a synthesized `deserialize` for bypass-ctor
    // construction (no user grammar). `cType` resolves a generic `T` under substitution.
    if (auto* v = dynamic_cast<ZeroValueNode*>(n)) {
        return "(" + cType(v->type) + "){0}";
    }

    unsupported("expression", n->line);
    return "0";
}

// ---------------------------------------------------------------------------
// Statements
// ---------------------------------------------------------------------------

// --- RAII cleanup helpers ---------------------------------------------

bool CEmitter::stmtIsJump(SharedStatement s)
{
    ASTNode* n = s.get();
    return dynamic_cast<ReturnNode*>(n) || dynamic_cast<BreakNode*>(n) || dynamic_cast<ContinueNode*>(n);
}

// does this body end in a jump (so control doesn't fall through to a branch join)?
bool CEmitter::bodyDiverges(SharedStatement s)
{
    if (!s) return false;
    if (auto* b = dynamic_cast<BlockNode*>(s.get())) {
        if (b->statements && !b->statements->empty()) return stmtIsJump(b->statements->back());
        return false;
    }
    return stmtIsJump(s);
}

void CEmitter::emitScopeCleanup(const Scope& s, int depth)
{
    // M4 barrier: JOIN every child `spawn`ed in this task scope BEFORE dropping any local. This runs
    // from every exit path — fall-through here, and the return/break/continue unwinds (emitUnwindAll /
    // emitUnwindToLoop both call this) — so a borrowed scope-local is guaranteed to outlive its child on
    // ALL paths (join-before-drop). Join order among siblings is irrelevant: the joins are independent.
    // A `parallel_spawn` group joins over the count it actually spawned, not over the array's extent:
    // the two differ if the container was empty, and joining an unwritten handle is undefined.
    for (auto& c : s.taskChildren) {
        indent(depth);
        if (c.count.empty()) { *_out << "kama_isolate_join(" << c.handle << ");\n"; }
        else {
            std::string j = "__kama_pj" + std::to_string(_tempCounter++);
            *_out << "for (int " << j << " = 0; " << j << " < " << c.count << "; ++" << j << ") "
                  << "kama_isolate_join(" << c.handle << "[" << j << "]);\n";
        }
    }
    for (auto it = s.locals.rbegin(); it != s.locals.rend(); ++it) {
        auto ms = _moveState.find(it->cVar);
        if (ms != _moveState.end()) {
            if (ms->second == MoveState::Moved) continue;   // moved out — skip its drop
            if (ms->second == MoveState::MaybeMoved) {      // moved on some paths, live here — undecidable drop
                // For an ordinary value this is unanswerable, so it is an error. For a SLOT it is not: the
                // declaration's field-default fill already left the storage in a valid, drop-safe state,
                // so "filled on some paths" just means DROP IT — the drop is correct when it was filled and
                // a no-op on the zero value when it was not. Only a slot untouched on EVERY path keeps its
                // drop elided, which is the case that retires the runtime liveness guards.
                if (!_slotDeclared.count(it->cVar))
                    unsupported(("`" + it->cVar + "` is moved on some paths but not others and is still live at "
                                 "scope exit — move it on all paths or none, or use Optional<T>").c_str(), _curLine);
            }
        }
        // A move-only value that owns nothing (an empty `resource`/token) is tracked for move
        // analysis but has no destructor — skip the drop.
        auto ci = _classes.find(it->className);
        if (ci != _classes.end() && !ci->second.destructible) continue;
        indent(depth);
        *_out << it->className << "__dtor(&" << it->cVar << ");\n";
    }
    // A `@onPanic` region DISARMS on every exit path: this helper is on all of them (fall-through, and
    // the return/break/continue unwinds), and the root scope is the region's frame.
    if (s.isFunctionRoot && _onPanicArmed) {
        indent(depth);
        *_out << "kama_recover_top = __kama_rec.prev;\n";
    }
}

// The landing pad of a `@onPanic` region, first thing inside the root block: arm the per-thread recovery
// slot, and on a longjmp back here restore the previous slot and return the region's declared value.
// `__kama_rec` is not modified between setjmp and longjmp, so no `volatile` is needed for `prev`.
void CEmitter::emitOnPanicPrologue(int depth)
{
    if (!_onPanicArmed) return;
    indent(depth); *_out << "kama_recover_t __kama_rec; __kama_rec.prev = kama_recover_top;\n";
    indent(depth); *_out << "if (setjmp(__kama_rec.jb)) { kama_recover_top = __kama_rec.prev; return"
                         << (_onPanicRecover.empty() ? "" : " " + _onPanicRecover) << "; }\n";
    indent(depth); *_out << "kama_recover_top = &__kama_rec;\n";
}

// A destructible local (or owning by-value parameter) the body being emitted OWNS — the fact the
// `@onPanic` walk needs, recorded where the local is registered so it cannot drift from the dtor emission.
void CEmitter::recordDestructibleOwner(const std::string& cVar, const std::string& className)
{
    if (_probingTemplate || _currentFunc.empty()) return;
    auto ci = _classes.find(className);
    if (ci == _classes.end() || !ci->second.destructible) return;   // owns nothing: no dtor to skip
    if (!_destructibleOwners.count(_currentFunc))
        _destructibleOwners[_currentFunc] = DestructibleSite{ cVar, className, _curLine, diagFile() };
    // Where the call graph should POINT for this owner's drop. The edge itself comes from the C, but the C
    // runs the destructor at scope exit, and `return n;` is not the line an author changes — the declaration
    // that takes ownership is. First owner of each type wins, like every other first-site record.
    _dropSiteLines[_currentFunc].emplace(className + "__dtor", _curLine);
}

// Pop the innermost scope, first erasing move-state for the locals it owned. A name going out of
// scope is lexically dead, so a sibling scope that later reuses the name must start NotMoved rather
// than inherit a stale Moved (the sibling-scope false use-after-move bug). Erasing an untracked name
// is a harmless no-op, so the pass is uniform. Only true scope-pops call this; the early-exit dtor
// walks for return/break/continue leave enclosing scopes live and must NOT clear their move-state.
//
// Then the scope's bindings unwind — every per-name table entry a binder here displaced comes back (see
// `SavedLocalType`). AFTER the move-state erase, on purpose: a `match`/`foreach` binding may shadow an
// enclosing move-tracked local of the same name, and the erase above would otherwise be the last word on
// the OUTER local's state. The `_scopes.clear()` resets at body entry/exit skip this, and may: every one
// sits beside (or right before) the per-body table reset that retires the whole function's entries.
void CEmitter::popScope()
{
    for (auto& l : _scopes.back().locals) _moveState.erase(l.cVar);
    restoreLocalBindings(_scopes.back().bindings);
    _scopes.pop_back();
}

// Drop the destructible temps a condition hoisted into the current scope since `preLoc`, then
// unregister them. Used by `if`/`while`/`for` after a value-producing condition: the temps were
// declared in the condition's wrapper block (or the loop's `while(1){…}` body), so their dtor must
// name them there, not at the outer scope where recordDestructibleLocal parked them. Mirrors
// emitScopeCleanup's guards (skip Moved / a temp of a non-destructible class) — a condition temp is
// only ever borrowed, so this is a no-op filter for strings, but the guards keep it sound now that
// arbitrary `ref`-arg class temps can hoist here. The full [preLoc,end) range is ALWAYS erased, even
// when a dtor was skipped, so a skipped temp isn't double-visited at real scope exit.
void CEmitter::dropCondTemps(size_t preLoc, int depth)
{
    if (_scopes.empty()) return;
    auto& locs = _scopes.back().locals;
    for (size_t i = locs.size(); i-- > preLoc; ) {
        auto ms = _moveState.find(locs[i].cVar);
        if (ms != _moveState.end() && ms->second != MoveState::NotMoved) continue;   // moved / maybe-moved: no drop
        auto ci = _classes.find(locs[i].className);
        if (ci != _classes.end() && !ci->second.destructible) continue;              // owns nothing
        indent(depth); *_out << locs[i].className << "__dtor(&" << locs[i].cVar << ");\n";
    }
    if (locs.size() > preLoc) locs.erase(locs.begin() + preLoc, locs.end());
}

// Destroy scopes from innermost up to & including the nearest loop boundary.
void CEmitter::emitUnwindToLoop(int depth)
{
    for (size_t i = _scopes.size(); i-- > 0; ) {
        emitScopeCleanup(_scopes[i], depth);
        if (_scopes[i].isLoopBoundary) break;
    }
}

// Destroy all scopes from innermost down to the function root (for return).
void CEmitter::emitUnwindAll(int depth)
{
    for (size_t i = _scopes.size(); i-- > 0; )
        emitScopeCleanup(_scopes[i], depth);
}

void CEmitter::recordDestructibleLocal(const std::string& cVar, const std::string& className)
{
    recordDestructibleOwner(cVar, className);   // the `@onPanic` walk's fact, at the one registration point
    if (!_scopes.empty())
        _scopes.back().locals.push_back({cVar, className});
    // Track for move analysis: move-only resources AND heap-owning collections/strings (so `give s`
    // suppresses the source's scope-drop, and a use-after-move is caught). A never-`give`n collection/
    // string stays NotMoved → drops normally, exactly as before.
    if (ownsByValue(className)) _moveState[cVar] = MoveState::NotMoved;
    // (The no-heap DESTRUCTOR edge is not recorded here: the emitted `T__dtor(&x)` is in the C, and the call
    // graph is read from the C — see buildCallGraph.)
}

// --- Blocks ----------------------------------------------------------------

void CEmitter::emitBlock(BlockNode* block, int depth)
{
    emitBlockScoped(block, depth, /*loopBoundary=*/false, /*functionRoot=*/false);
}

void CEmitter::emitBlockScoped(BlockNode* block, int depth, bool loopBoundary, bool functionRoot)
{
    Scope sc; sc.isLoopBoundary = loopBoundary; sc.isFunctionRoot = functionRoot;
    _scopes.push_back(sc);
    // by-value smart-ptr params the callee owns drop at fn-end. Recorded FIRST in
    // the root scope, so they're destroyed LAST (after every local), at function exit.
    if (functionRoot && !_pendingParamDtors.empty()) {
        for (auto& l : _pendingParamDtors) {
            _scopes.back().locals.push_back(l);
            recordDestructibleOwner(l.cVar, l.className);   // ...and a `@onPanic` region may not (the parameter hole)
        }
        _pendingParamDtors.clear();
    }

    *_out << "{\n";
    if (functionRoot) emitOnPanicPrologue(depth + 1);   // a `@onPanic` region arms itself before anything else
    SharedStatement last;
    if (block && block->statements) {
        for (auto& stmt : *block->statements) { emitStatement(stmt, depth + 1); last = stmt; }
    }
    // Fall-through cleanup, unless the block already exited via a jump (which
    // ran its own cleanup) — the double-destruction guard.
    if (!(last && stmtIsJump(last)))
        emitScopeCleanup(_scopes.back(), depth + 1);

    indent(depth);
    *_out << "}";
    popScope();
}

// The nearest enclosing `scope { }` on the scope stack, or null. A bare `spawn` registers its join
// handle into this; a `ref` borrow (M4.2) is checked against the locals it owns.
CEmitter::Scope* CEmitter::innermostTaskScope()
{
    for (size_t i = _scopes.size(); i-- > 0; )
        if (_scopes[i].isTaskScope) return &_scopes[i];
    return nullptr;
}

int CEmitter::innermostTaskScopeIndex()
{
    for (int i = (int)_scopes.size() - 1; i >= 0; --i)
        if (_scopes[i].isTaskScope) return i;
    return -1;
}

// The _scopes index whose `declaredNames` lists `name`, searching innermost-out. Returns -1 when no
// scope declares it — meaning it is a PARAMETER (params live for the whole fn, outliving any scope) or
// unknown. `declaredNames` records EVERY local (primitives included), so this is exact for locals.
int CEmitter::findScopeDeclaring(const std::string& name)
{
    for (int i = (int)_scopes.size() - 1; i >= 0; --i)
        for (auto& dn : _scopes[i].declaredNames)
            if (dn == name) return i;
    return -1;
}

// `scope { ... }` — structured concurrency (M4). Lowered like emitBlockScoped, but the scope is a TASK
// scope: bare `spawn`s inside register their `kama_isolate_t` handles here, and emitScopeCleanup joins
// them ALL before dropping any local (the join-before-drop barrier). A `scope` introduces exactly one
// lexical C block, like a plain `{ }`, so child handles declared in it are in scope at the closing brace.
void CEmitter::emitScope(ScopeNode* sc, int depth)
{
    line(sc->line);
    indent(depth);
    Scope s; s.isTaskScope = true;
    _scopes.push_back(s);

    *_out << "{\n";
    SharedStatement last;
    auto* block = dynamic_cast<BlockNode*>(sc->body.get());
    if (block && block->statements) {
        for (auto& stmt : *block->statements) { emitStatement(stmt, depth + 1); last = stmt; }
    }
    // Fall-through: join every child, then drop locals. On a jump exit the unwind path already ran the
    // full cleanup (child joins included) via emitScopeCleanup — the double-destruction guard.
    if (!(last && stmtIsJump(last)))
        emitScopeCleanup(_scopes.back(), depth + 1);
    indent(depth); *_out << "}\n";
    popScope();
}

// `borrow xf as v, ys as w { ... }` — the lexical window a view is minted into (the view model).
//
// The window is the whole mechanism. kama answers "how long is this view valid?" with lexical scope
// rather than a lifetime (GOALS §3e declines the machinery) or a programmer promise (what `View<T>` had
// before), so a mint has to name the extent it is valid for, and that extent is this block.
//
// Purely lexical: one C block plus one initializer per binding, no runtime cost. `.view()` resolves
// STRUCTURALLY, the way emitForeachIterator already resolves `iterator()`/`iterMut()` — going through
// contract dispatch would box the view and cost the zero-dispatch property the ECS path depends on.
void CEmitter::emitBorrow(BorrowNode* bn, int depth)
{
    line(bn->line);
    indent(depth);
    _scopes.push_back(Scope());

    *_out << "{\n";
    // The bindings of ONE `borrow` are checked against each other by the same prefix test the rest of the
    // model uses. `borrow a as x, a as y` would hand out two mutable views of one buffer — `View<T>` is a
    // mutate-through window, so this is precisely the aliasing the window exists to prevent, just spelled
    // in one statement instead of two. `borrow w.bodies as b, w.springs as s` stays legal: distinct fields
    // cannot overlap. A non-place host has an empty path and is skipped here — it is rejected on its own.
    std::vector<std::pair<std::vector<std::string>, std::string>> bound;   // place -> the alias holding it
    std::vector<Scope::FrozenPlace> frozenNow;   // staged; registered after the loop (see below)
    if (bn->bindings) {
        for (auto& b : *bn->bindings) {
            if (!b || !b->host || !b->alias || !b->alias->value) continue;
            const std::string alias = *b->alias->value;
            // The host is a MINT CALL — `<place>.<mint>()` — and the window is over the mint's RECEIVER.
            // Naming the container alone would not say WHICH view to open: a type may carry several grants
            // (`DynamicArray` has `view`, `iterator` and `iterMut`), and a `Map` has no `view()` at all, so
            // the old hardcoded name left every iterator with no spelling. The grant already names its
            // member; this reads it instead of guessing.
            auto* inv = dynamic_cast<InvocationNode*>(b->host.get());
            MemberAccessNode* ma = (inv && inv->expression)
                                 ? dynamic_cast<MemberAccessNode*>(inv->expression.get()) : nullptr;
            if (!ma || !ma->expression || !ma->identifier || !ma->identifier->value) {
                unsupported(("`borrow` binds a mint call, so `" + alias + "` must name one — write "
                             "`borrow <container>.<mint>() as " + alias + "` (e.g. `borrow d.view() as "
                             + alias + "`, `borrow m.values() as " + alias + "`). A container alone does "
                             "not say which view to open, and a type may grant several").c_str(), bn->line);
                continue;
            }
            const std::string mint = *ma->identifier->value;
            SharedExpression recvExpr = ma->expression;
            if (inv->args && !inv->args->empty()) {
                unsupported(("a mint takes no arguments, so `" + mint + "(…)` cannot open a window — "
                             "borrow the whole thing and narrow inside it with `.slice(…)` on `" + alias
                             + "`, which is free").c_str(), bn->line);
                continue;
            }
            std::vector<std::string> hp = placePath(recvExpr);
            if (!hp.empty()) {
                // An ENCLOSING window already froze this storage. Two windows over one buffer are the
                // same two mutable views the sibling rule below rejects, merely spelled across statements.
                if (const Scope::FrozenPlace* outer = frozenConflict(hp)) {
                    unsupported(("`" + placeText(hp) + "` is already borrowed by an enclosing `borrow` "
                                 "(opened at line " + std::to_string(outer->line) + " as `" + outer->alias
                                 + "`) — that would be two mutable views of one buffer; derive from `"
                                 + outer->alias + "` with `.slice(…)` instead, which is free").c_str(),
                                bn->line);
                    continue;
                }
                bool clash = false;
                for (auto& pr : bound)
                    if (placesConflict(pr.first, hp)) {
                        unsupported(("`" + placeText(hp) + "` is borrowed twice by one `borrow` (as `"
                                     + pr.second + "` and as `" + alias + "`) — that is two mutable views "
                                     "of the same storage, which is what the window exists to prevent; "
                                     "borrow it once and derive with `.slice(…)`, which is free")
                                        .c_str(), bn->line);
                        clash = true;
                        break;
                    }
                if (clash) continue;
                bound.push_back({ hp, alias });
            }
            const std::string hostCls = exprClass(recvExpr);
            if (hostCls.empty() || !_classes.count(hostCls)) {
                unsupported(("`borrow` needs a container that can mint a view; `" + alias
                             + "`'s host is not one").c_str(), bn->line);
                continue;
            }
            // Resolve the mint structurally — this is a gate, never a dispatch, which is what keeps the
            // emitted call direct.
            MethodInfo* vmi = findMethod(&_classes[hostCls], mint, nullptr);
            if (!vmi || !vmi->params.empty()) {
                // Same fixable cause as at the method-dispatch site: an intrinsic collection's `view()`
                // exists only when the program has a `std::collections::View` to mint.
                if ((mint == "view" || mint == "viewMut") && viewTemplateKey().empty() && _classes[hostCls].isIntrinsicColl)
                    unsupported(("`" + hostCls + "` can open a window, but this program has no `View<T>` "
                                 "to mint — add `import { std::collections::View };`").c_str(), bn->line);
                else
                    unsupported(("`" + hostCls + "` has no nullary `." + mint + "()`, so it cannot open a "
                                 "window — a `borrow` host must be a container that can hand out a view")
                                    .c_str(), bn->line);
                continue;
            }
            // A mint is a CALL on its receiver, so it answers to deep const like any other: the writable
            // window (`viewMut()`, not `const fn`) cannot be opened over a `const` place. Said here because
            // this gate emits the call directly and never passes through the dispatch site's receiver check.
            if (!vmi->isConst && isConstReceiver(recvExpr)) {
                unsupported(("cannot call non-const method `" + mint + "` on a const receiver — a window over "
                             "a `const` place is the read-only one; open it with `view()` (a `const fn`, "
                             "yielding a `ConstView<T>`)").c_str(), bn->line);
                continue;
            }
            if (!grantedMint(_classes[hostCls], mint)) {
                unsupported(("`" + hostCls + "` has a `." + mint + "()` but never granted it as a mint — "
                             "`borrow` opens the window a view lives in, so the host must declare that its "
                             "storage is what that view views. Implement a `@viewable` contract carrying `"
                             + mint + "()` (the prelude's `Viewable<V>`, `Iterable<T>` and "
                             "`ValuesIterable<I>` are such contracts)").c_str(), bn->line);
                continue;
            }
            const std::string viewCType = cTypeInInstance(hostCls, vmi->returnType);
            if (!isViewCType(viewCType)) {
                unsupported(("`" + hostCls + "." + mint + "()` does not return a `type view` — a window "
                             "bounds the life of a BORROW, and this hands back a value that owns itself, "
                             "so there is nothing here for a window to bound; call it normally").c_str(),
                            bn->line);
                continue;
            }
            indent(depth + 1);
            *_out << viewCType << " " << alias << " = " << vmi->cName
                  << "(&(" << emitExpression(recvExpr) << "));\n";
            noteScopedBinding(alias);   // the window's scope owns the alias — popScope retires all three entries
            _localTypes[alias] = viewCType;
            // An alias is an ordinary local in every way a later statement can ask about, and generic
            // INFERENCE asks through `_localCTypes` — without this, `sort(items: v)` on an alias could not
            // infer `T` and demanded a turbofish. No fixture caught it because the only `borrow` fixture
            // passed its alias to a non-generic `sum` and to an explicitly-turbofished call.
            _localCTypes[alias] = viewCType;
            _localTypeNodes[alias] = vmi->returnType;
            _scopes.back().declaredNames.push_back(alias);
            frozenNow.push_back({ hp, alias, bn->line });
        }
        // Registered only AFTER every binding is resolved. Eagerly, the second binding of
        // `borrow a.view() as x, a.view() as y` would trip the freeze rule instead of the sibling rule
        // above, which says the same thing far better — and `xfail/borrow_two_bindings_overlap` would go
        // red against a message that is not wrong, merely worse.
        for (auto& f : frozenNow) if (!f.place.empty()) _scopes.back().frozen.push_back(f);
    }

    SharedStatement last;
    auto* block = dynamic_cast<BlockNode*>(bn->body.get());
    if (block && block->statements)
        for (auto& stmt : *block->statements) { emitStatement(stmt, depth + 1); last = stmt; }
    // Same double-destruction guard as `scope`: a jump exit already ran the full cleanup on its way out.
    if (!(last && stmtIsJump(last)))
        emitScopeCleanup(_scopes.back(), depth + 1);
    indent(depth); *_out << "}\n";
    popScope();   // retires the aliases
}

// Synthesize the `View<elem>` type node the loop iterates, so the scan passes register that instance
// (a parallel_for always iterates a View — directly, or one we auto-`.view()` from a container). (M6.3)
SharedIdentifier CEmitter::parforViewType(SharedIdentifier elem)
{
    auto view = synthId("View");
    auto args = std::make_shared<IdentifierList>();
    args->push_back(elem);
    view->genericArgs = args;
    view->genericArg  = elem;
    return view;
}

// `parallel_for (ref T e in coll) { body }` — disjoint-slice data-parallel loop (M6.3), the third and
// final safe-sharing primitive. Splits `coll` into K non-overlapping sub-Views (one per worker isolate),
// runs the body over each in place, and joins them ALL at the closing brace (self-joining barrier — the
// parallel_for owns its own DYNAMIC fan-out, unlike a `scope`'s static child list). Safe by disjointness:
// two workers never touch the same element, so no lock and no data race, with no borrow checker.
//
// Lowering (reuses the M4.2 borrow-trampoline pattern + the foreach `ref` lowering):
//   (a) resolve the operand to a `View<T>` (directly, or auto-`.view()` a contiguous container);
//   (b) free-variable analysis of the body -> the captured enclosing locals (the one new pass);
//   (c) write-through-capture gate: a written non-atomic capture is shared -> race -> rejected;
//   (d) synthesize a worker fn `__kama_pf_bodyN(View slice, cap0*, ...)` whose body is
//       `foreach (ref T e in slice) { <body> }` — captures thread in as `ref` params (deref via _refParams);
//   (e) a per-site arg struct + trampoline to cross the isolate ABI's single void*;
//   (f) at the call site: split into K disjoint slices, spawn K, join all at the brace.
void CEmitter::emitParallelFor(ParallelForNode* pf, int depth)
{
    // One function serves both constructs; `deferJoin` is the whole difference. Diagnostics name the
    // spelling the user actually wrote, or every `parallel_spawn` error would talk about `parallel_for`.
    const std::string KW = pf->deferJoin ? "parallel_spawn" : "parallel_for";

    line(pf->line);
    rejectIfNoHeap((KW + " heaps a per-worker argument bundle").c_str(), pf->line);   // no-heap gate

    // The isolate count. `parallel_for` REQUIRES it and `parallel_spawn` FORBIDS it, and both halves are
    // the same rule seen from two sides: **the number of isolates is always the number of jobs you hand
    // the construct.** A bare `spawn` is one job. `parallel_spawn`'s jobs are the container's elements, so
    // its count is already stated — `workers:` there would be a second, conflicting answer. `parallel_for`'s
    // jobs are SLICES of one buffer, and how finely to slice is the one thing the data cannot say, so it
    // has to be written.
    //
    // There is deliberately NO DEFAULT. kama has no optional parameters — a user `fn` cannot have one
    // (`int32 b = 5` is a parse error), so a built-in must not either, or the language grants itself a
    // privilege user code cannot have. The old implicit `min(cores, length)` is now written `cpuCount()`,
    // which only became expressible when cpuCount() shipped; before that a mandatory clause would have
    // needed a magic sentinel (`workers: 0`), which is the implicit-over-explicit trade GOALS refuses.
    // The payoff is that `grep 'workers:'` finds every parallelism-width decision in a codebase — those
    // decisions used to be invisible, which is precisely what made a chunked `parallel_for` surprising.
    if (pf->deferJoin && pf->workers) {
        unsupported("`parallel_spawn` takes no `workers:` — its isolate count IS the container's length, "
                    "one per element. Size the container to say how many you want (`cpuCount()` for one "
                    "per core); a second count here could only contradict it", pf->line);
        return;
    }
    if (!pf->deferJoin && !pf->workers) {
        unsupported("`parallel_for` requires an explicit `workers:` count — write "
                    "`parallel_for (ref T e in c, workers: cpuCount())` for one slice per core (the old "
                    "implicit behaviour), or any other count. It is stated rather than defaulted because "
                    "how finely to slice is the one thing the data cannot say, and a silent count is what "
                    "makes a chunked loop surprising", pf->line);
        return;
    }
    // A count that is provably nonsense is a compile error rather than a clamp — the point of the clause is
    // that you get what you asked for. A RUNTIME value is floored at 1 below instead, since the compiler
    // cannot know it and refusing to build would be worse than running one worker.
    if (pf->workers) {
        long long litVal = 0; bool isLit = false;
        if (auto* i32 = dynamic_cast<Int32Node*>(pf->workers.get())) { litVal = i32->value; isLit = true; }
        else if (auto* i64 = dynamic_cast<Int64Node*>(pf->workers.get())) { litVal = i64->value; isLit = true; }
        if (isLit && litVal <= 0) {
            unsupported(("`workers: " + std::to_string(litVal) + "` asks for no workers at all — the "
                         "count must be at least 1").c_str(), pf->line);
            return;
        }
    }

    // `parallel_spawn` hands its join to the enclosing `scope { }`, so there has to be one — and it has
    // to be a DIRECT statement of it, for exactly the reason a bare `spawn` does (the handle array is
    // declared at the scope's own depth so the barrier can name it; one declared in a nested block is
    // out of scope at the join, which is invalid C). `parallel_for` owns its join and needs neither.
    if (pf->deferJoin) {
        if (!innermostTaskScope()) {
            unsupported("`parallel_spawn` must appear inside a `scope { }` (which owns the join) — it "
                        "starts long-lived workers that run ALONGSIDE the statements after it, so "
                        "something else has to join them. For work that finishes on its own, that is "
                        "`parallel_for`, which joins at its own brace", pf->line);
            return;
        }
        if (innermostTaskScopeIndex() != (int)_scopes.size() - 1) {
            unsupported("`parallel_spawn` must be a direct statement of its `scope { }` — this one is "
                        "inside a nested block, whose handle array the scope's join cannot name. Put "
                        "the `if` outside the `scope`", pf->line);
            return;
        }
    }

    // The isolate seam header (and its `-lpthread` link) flows in via
    // `import std::concurrent;`; without it the spawn/join calls would not compile.
    if (!externsHeader("kama_isolate.h"))
        unsupported(("`" + KW + "` requires `import std::concurrent;` (the isolate seam)").c_str(), pf->line);

    const std::string loopVar = (pf->name && pf->name->value) ? *pf->name->value : "__e";
    std::string elemTy = cType(pf->type);
    // Each worker borrows its slice's elements by `ref`, which is the borrow form of a `spawn` bundle —
    // so the element faces the same sendability gate a bundle does (a worker may `copy` a handle out of
    // an element, and the parent's drop then races that copy's release). Recorded like a bundle, checked
    // after emission by checkSpawnBundleSendability. A primitive element passes: its conformance is
    // declared in the prelude.
    if (!_probingTemplate && !elemTy.empty())
        _spawnBundles.push_back(SpawnBundle{ elemTy, pf->line, diagFile(), "as a `" + KW + "` element" });

    // ── (a) Resolve the iterable to a View<T> (direct, or auto-`.view()` a contiguous container). ─────
    std::string itCls = exprClass(pf->expression);
    if (itCls.empty() || !_classes.count(itCls))
        unsupported((KW + " needs a `View<T>` or a contiguous container with `.viewMut()` "
                    "(DynamicArray/FixedArray) — the operand is not a collection").c_str(), pf->line);
    std::string viewCType, viewExpr;
    if (isViewCType(itCls)) {
        // `ref` is mandatory here — every worker WRITES its slice — so the read-only window cannot serve.
        // Said here, or the foreach lowering below would report a missing `iterMut()` and leave the reader
        // to work out that a `ConstView` never has one.
        if (isConstViewCType(itCls)) {
            unsupported((KW + " binds each element `ref` — every worker writes its slice — and a "
                         "`ConstView<T>` is read-only. Pass the writable window: `viewMut()` where the "
                         "view was made").c_str(), pf->line);
            return;
        }
        viewCType = itCls;
        viewExpr  = emitExpression(pf->expression);
    } else {
        MethodInfo* viewMi = findMethod(&_classes[itCls], "viewMut", nullptr);
        if (!viewMi || !viewMi->params.empty()
            || !isViewCType(cTypeInInstance(itCls, viewMi->returnType))) {
            unsupported((KW + " needs a `View<T>` or a contiguous container with a nullary `.viewMut()` "
                         "(DynamicArray/FixedArray); `" + itCls + "` is not contiguous — a non-contiguous "
                         "collection cannot be split into disjoint slices").c_str(), pf->line);
            return;   // `viewMi` may be the null this guard rejected — never fall through and deref it
        }
        if (!declaresViewable(_classes[itCls])) {
            unsupported((KW + " splits a container into disjoint slices, so the container must "
                         "declare that its storage is what those slices view; `" + itCls + "` has a "
                         "`.viewMut()` but implements no `@viewable` contract (the prelude's `ViewableMut<V>`)")
                            .c_str(), pf->line);
            return;
        }
        viewCType = cTypeInInstance(itCls, viewMi->returnType);
        viewExpr  = viewMi->cName + "(&(" + emitExpression(pf->expression) + "))";
    }
    ClassInfo* viewCI = &_classes[viewCType];
    MethodInfo* lenMi   = findMethod(viewCI, "length", nullptr);
    MethodInfo* sliceMi = findMethod(viewCI, "slice", nullptr);
    if (!lenMi || !sliceMi)
        unsupported((KW + ": the view type `" + viewCType + "` needs `.length()` and `.slice()`").c_str(), pf->line);

    // ── (b) Free-variable capture analysis — the one genuinely new pass. ──────────────────────────────
    // Collect enclosing locals/params the body references (skip the loop var + body-local decls). A
    // `this`/field access is rejected (a worker runs with no receiver — shared-nothing). Reuses the
    // enclosing emitter state (`findScopeDeclaring`/_paramNames/_localCTypes), intact at this point.
    std::vector<std::string> capOrder;
    std::set<std::string> capSeen;
    std::map<std::string, bool> capWrites;   // name -> is written (assignment / incr-decr LHS root)
    std::set<std::string> bodyLocal;

    auto noteUse = [&](const std::string& nm, bool isWrite) {
        if (nm.empty() || nm == loopVar || bodyLocal.count(nm)) return;
        bool isLocal = (findScopeDeclaring(nm) >= 0) || _paramNames.count(nm);
        if (!isLocal) {
            if (_currentClass && findFieldOwner(_currentClass, nm))
                unsupported((KW + " body may not access field `" + nm + "` — a worker runs with no "
                             "receiver (shared-nothing); pass the data in as a local").c_str(), pf->line);
            return;   // a top-level fn / type / enum name — not a capture
        }
        if (!capSeen.count(nm)) { capSeen.insert(nm); capOrder.push_back(nm); capWrites[nm] = false; }
        if (isWrite) capWrites[nm] = true;
    };

    std::function<void(SharedExpression)> scanE;
    std::function<void(SharedStatement)>  scanS;
    scanE = [&](SharedExpression e) {
        if (!e) return;
        ASTNode* n = e.get();
        if (auto* as = dynamic_cast<AssignmentNode*>(n)) {
            std::string r = rootBinding(as->unaryExpression);
            if (!r.empty()) noteUse(r, true);        // the LHS root is written
            scanE(as->unaryExpression); scanE(as->expression);   // LHS sub-exprs (indices) + RHS are reads
        } else if (auto* id = dynamic_cast<IdentifierNode*>(n)) {
            if (id->value) noteUse(*id->value, false);
        } else if (dynamic_cast<ThisAccessNode*>(n)) {
            unsupported((KW + " body may not access `this`/fields — a worker runs with no receiver "
                        "(shared-nothing); pass the data in as a local").c_str(), pf->line);
        } else if (auto* ma = dynamic_cast<MemberAccessNode*>(n)) {
            scanE(ma->expression);                   // the member/method name is not a capture
        } else if (auto* inv = dynamic_cast<InvocationNode*>(n)) {
            if (auto* ma = dynamic_cast<MemberAccessNode*>(inv->expression.get())) {
                scanE(inv->expression);              // recurse the receiver (reads)
                // A NON-const method mutates its receiver; if the receiver root is a capture, that is a
                // shared write across all workers -> the gate rejects it unless the capture is an Atomic.
                std::string recvCls = exprClass(ma->expression);
                std::string mname = (ma->identifier && ma->identifier->value) ? *ma->identifier->value : "";
                if (!recvCls.empty() && _classes.count(recvCls) && !mname.empty()) {
                    MethodInfo* mi = findMethod(&_classes[recvCls], mname, nullptr);
                    if (mi && !mi->isConst) { std::string r = rootBinding(ma->expression); if (!r.empty()) noteUse(r, true); }
                }
            }
            // else: a bare free-fn call target is a global symbol, not a capture — skip the callee name.
            if (inv->args) for (auto& a : *inv->args) if (a) {
                // A capture passed by `ref`/`out` may be mutated by the callee -> treat as a write.
                bool byRef = a->modifier && a->modifier->value
                             && (*a->modifier->value == "ref" || *a->modifier->value == "out");
                if (byRef) { std::string r = rootBinding(a->expression); if (!r.empty()) noteUse(r, true); }
                scanE(a->expression);
            }
        } else if (auto* ea = dynamic_cast<ElementAccessNode*>(n)) {
            scanE(ea->expression);
            if (ea->expressionlist) for (auto& x : *ea->expressionlist) scanE(x);
        } else if (auto* b = dynamic_cast<BinaryExpressionNode*>(n)) {
            scanE(b->LHS); scanE(b->RHS);
        } else if (auto* l = dynamic_cast<LogicalAndOrNode*>(n)) {
            scanE(l->LHS); scanE(l->RHS);
        } else if (auto* t = dynamic_cast<TernaryExpressionNode*>(n)) {
            scanE(t->condition); scanE(t->LHS); scanE(t->RHS);
        } else if (auto* c = dynamic_cast<CastNode*>(n)) {
            scanE(c->unaryExpression);
        } else if (auto* su = dynamic_cast<SimpleUnaryExpressionNode*>(n)) {
            scanE(su->expression);
        } else if (auto* pre = dynamic_cast<PreIncrDecrNode*>(n)) {
            std::string r = rootBinding(pre->expression); if (!r.empty()) noteUse(r, true);
            scanE(pre->expression);
        } else if (auto* po = dynamic_cast<PostIncrDecrNode*>(n)) {
            std::string r = rootBinding(po->expression); if (!r.empty()) noteUse(r, true);
            scanE(po->expression);
        } else if (auto* oc = dynamic_cast<ObjectCreationNode*>(n)) {
            if (oc->args) for (auto& a : *oc->args) if (a) scanE(a->expression);
        }
        // literals / other leaves: nothing to capture.
    };
    scanS = [&](SharedStatement s) {
        if (!s) return;
        ASTNode* n = s.get();
        if (auto* blk = dynamic_cast<BlockNode*>(n)) {
            if (blk->statements) for (auto& st : *blk->statements) scanS(st);
        } else if (auto* d = dynamic_cast<LocalVariableDeclaration*>(n)) {
            if (d->variables) for (auto& v : *d->variables) if (v) {
                scanE(v->initializer);
                if (v->name && v->name->value) bodyLocal.insert(*v->name->value);
            }
        } else if (auto* cd = dynamic_cast<ConstLocalVariableDeclaration*>(n)) {
            if (cd->variables) for (auto& v : *cd->variables) if (v) {
                scanE(v->initializer);
                if (v->name && v->name->value) bodyLocal.insert(*v->name->value);
            }
        } else if (dynamic_cast<ExpressionStatementNode*>(n)) {
            scanE(std::dynamic_pointer_cast<ExpressionNode>(s));
        } else if (auto* f = dynamic_cast<IfNode*>(n)) {
            scanE(f->booleanExpression); scanS(f->ifStatement); scanS(f->elseStatement);
        } else if (auto* w = dynamic_cast<WhileNode*>(n)) {
            scanE(w->booleanExpression); scanS(w->whileStatement);
        } else if (auto* dw = dynamic_cast<DoWhileNode*>(n)) {
            scanE(dw->booleanExpression); scanS(dw->doWhileStatement);
        } else if (auto* fr = dynamic_cast<ForNode*>(n)) {
            if (fr->initializerStatements) for (auto& st : *fr->initializerStatements) scanS(st);
            scanE(fr->booleanExpression);
            if (fr->iteratorStatements) for (auto& st : *fr->iteratorStatements) scanS(st);
            scanS(fr->body);
        } else if (auto* fe = dynamic_cast<ForEachNode*>(n)) {
            scanE(fe->expression);
            if (fe->name && fe->name->value) bodyLocal.insert(*fe->name->value);
            scanS(fe->body);
        } else if (auto* r = dynamic_cast<ReturnNode*>(n)) {
            scanE(r->expression);
        }
        // ponytail: this recognizes the statement/expression node kinds a parallel_for body contains
        // today. A newly-added node kind that can name or write a local must be handled here, or its
        // capture is missed — a loud failure (the worker fn won't compile), never a silent race.
    };
    scanS(pf->body);

    // Snapshot each capture's C type / class / address expression from the ENCLOSING context (intact
    // here), and apply the write-through-capture gate (c).
    struct Cap { std::string name, cType, className, addr; };
    std::vector<Cap> caps;
    for (auto& nm : capOrder) {
        Cap c;
        c.name      = nm;
        c.className = _localTypes.count(nm)  ? _localTypes[nm]  : "";
        c.cType     = _localCTypes.count(nm) ? _localCTypes[nm] : c.className;
        if (capWrites[nm] && !isAtomicClass(c.className))
            unsupported((KW + " body writes to captured `" + nm + "` — a non-atomic capture is shared "
                         "across all workers and would race; make it an `Atomic<T>`, or write only through the "
                         "loop element `" + loopVar + "`").c_str(), pf->line);
        c.addr = _refParams.count(nm) ? nm : ("&(" + nm + ")");   // a ref-param capture IS already a pointer
        // A capture reaches every worker by `ref` — the same crossing as a borrowed bundle, so the same
        // sendability gate (see the element record above).
        if (!_probingTemplate && !c.cType.empty())
            _spawnBundles.push_back(SpawnBundle{ c.cType, pf->line, diagFile(),
                                                 "as the captured local `" + nm + "` of a `" + KW + "`" });
        caps.push_back(c);
    }

    int seq = _parforSeq++;
    std::string bodyFn  = "__kama_pf_body"  + std::to_string(seq);
    std::string trampFn = "__kama_pf_tramp" + std::to_string(seq);
    std::string argTy   = "__kama_pf_arg"   + std::to_string(seq);

    // ── (d) Synthesize the worker fn into a buffer: iterate the disjoint sub-View over `ref T e`. ─────
    // A worker is a fresh function context, so save/reset/restore ALL enclosing per-function state.
    std::ostringstream body;
    {
        std::ostream* savedOut        = _out;
        auto savedRefParams           = _refParams;
        auto savedParamNames          = _paramNames;
        auto savedLocalTypes          = _localTypes;
        auto savedLocalCTypes         = _localCTypes;
        auto savedLocalTypeNodes      = _localTypeNodes;
        auto savedConstLocals         = _constLocals;
        auto savedSlotLocals          = _slotLocals;
        auto savedSlotDeclared        = _slotDeclared;
        auto savedMoveState           = _moveState;
        auto savedScopes              = _scopes;
        auto savedHoisted             = _hoisted;
        ClassInfo* savedClass         = _currentClass;
        std::string savedRetC         = _currentReturnCType;
        int savedTemp                 = _tempCounter;

        _out = &body;
        _refParams.clear(); _paramNames.clear();
        _localTypes.clear(); _localCTypes.clear(); _localTypeNodes.clear();
        _constLocals.clear(); _moveState.clear(); _slotLocals.clear(); _slotDeclared.clear(); _scopes.clear(); _hoisted.clear();
        _currentClass = nullptr;
        _currentReturnCType = "void";
        _tempCounter = 0;

        body << "static void " << bodyFn << "(" << viewCType << " __slice";
        for (auto& c : caps) body << ", " << c.cType << "* " << c.name;
        body << ") {\n";

        _paramNames.insert("__slice");
        _localTypes["__slice"] = viewCType; _localCTypes["__slice"] = viewCType;
        for (auto& c : caps) {
            _paramNames.insert(c.name);
            _refParams.insert(c.name);                 // a `ref` param: reads/writes deref via _refParams
            _localTypes[c.name]  = c.className;         // "" if primitive
            _localCTypes[c.name] = c.cType;
        }

        Scope root; root.isFunctionRoot = true;
        _scopes.push_back(root);

        // Reuse the foreach `ref` lowering: `foreach (ref elemTy loopVar in __slice) { <body> }`.
        auto sliceId = synthId("__slice");
        auto fe = std::make_shared<ForEachNode>(*_synthCtx, pf->type, pf->name, sliceId, pf->body);
        fe->isRef = true;
        emitForeachIterator(fe.get(), viewCType, 1);
        emitScopeCleanup(_scopes.back(), 1);   // function-root scope (no owned locals expected)
        body << "}\n";

        _out = savedOut;
        _refParams       = savedRefParams;   _paramNames      = savedParamNames;
        _localTypes      = savedLocalTypes;  _localCTypes     = savedLocalCTypes;
        _localTypeNodes  = savedLocalTypeNodes; _constLocals  = savedConstLocals;
        _slotLocals      = savedSlotLocals;  _slotDeclared    = savedSlotDeclared;
        _moveState       = savedMoveState;   _scopes          = savedScopes;
        _hoisted         = savedHoisted;     _currentClass    = savedClass;
        _currentReturnCType = savedRetC;     _tempCounter     = savedTemp;
    }

    // ── (e) Arg struct + trampoline (crosses the isolate ABI's single void*). ─────────────────────────
    std::ostringstream helper;
    helper << "typedef struct { " << viewCType << " slice;";
    for (size_t i = 0; i < caps.size(); ++i) helper << " " << caps[i].cType << "* c" << i << ";";
    helper << " } " << argTy << ";\n";
    helper << body.str();
    helper << "static void* " << trampFn << "(void* __p) {\n";
    helper << "    " << argTy << "* __a = (" << argTy << "*)__p;\n";
    helper << "    " << bodyFn << "(__a->slice";
    for (size_t i = 0; i < caps.size(); ++i) helper << ", __a->c" << i;
    helper << ");\n    kama_free(__p, " << layoutOf(argTy) << ");\n    return (void*)0;\n}\n";
    _fileScopeHelpers.push_back(helper.str());

    // ── (f) Call site: split into K disjoint slices, spawn K workers, join ALL at the brace. ──────────
    flushHoisted(depth);
    std::string sfx = std::to_string(seq);
    std::string V = "__pfv"+sfx, LEN = "__pflen"+sfx, K = "__pfk"+sfx, CH = "__pfch"+sfx,
                H = "__pfh"+sfx, SP = "__pfs"+sfx, W = "__pfw"+sfx, F = "__pff"+sfx,
                C = "__pfc"+sfx, A = "__pfa"+sfx, J = "__pfj"+sfx;

    // `parallel_spawn` declares its state at the SCOPE's own depth — no wrapper block — because the
    // scope-barrier join has to be able to name the handle array. `parallel_for` owns its join, so it
    // wraps everything and keeps its temporaries out of the enclosing scope.
    const int d = pf->deferJoin ? depth : depth + 1;
    if (!pf->deferJoin) { indent(depth); *_out << "{\n"; }

    indent(d); *_out << viewCType << " " << V << " = " << viewExpr << ";\n";
    indent(d); *_out << "int32_t " << LEN << " = " << lenMi->cName << "(&" << V << ");\n";
    if (pf->deferJoin) {
        // ⚠️ K IS `length()` EXACTLY — one long-lived isolate per element, and capping it at the core
        // count would be a BUG, not a safeguard. A cap does not skip the extras; it gives one isolate
        // several elements to run SEQUENTIALLY (the chunk arithmetic below). A pool worker blocks — it
        // sits on a channel until the far end closes — so a chunked worker never starts, and the failure
        // is silent rather than a hang: the running workers drain the queue, the producer closes, they
        // exit, and only then do the rest start and immediately see the closed end. The construct
        // promises "these K run concurrently"; a cap breaks that promise invisibly. That different
        // guarantee is exactly what makes this a second construct instead of a knob on `parallel_for`,
        // whose own cap is right because its work is finite and independent.
        indent(d); *_out << "int " << K << " = (int)" << LEN << ";   /* one isolate per element — NOT capped at core count */\n";
        // A zero-length VLA is undefined, and an empty container is a legitimate pool of nobody: floor
        // the ARRAY at 1 while leaving K at 0, so the spawn loop runs zero times and the barrier — which
        // joins over the spawned COUNT, not the array extent — joins nothing.
        indent(d); *_out << "kama_isolate_t " << H << "[" << K << " > 0 ? " << K << " : 1];\n";
        indent(d); *_out << "int " << SP << " = 0;\n";
        indent(d); *_out << "for (int " << W << " = 0; " << W << " < " << K << "; ++" << W << ") {\n";
        indent(d+1); *_out << argTy << "* " << A << " = (" << argTy << "*)kama_alloc(" << layoutOf(argTy) << ");\n";
        indent(d+1); *_out << "if (!" << A << ") kama_panic(kama_string_lit(\"out of memory\", 13));\n";
        // A one-element slice, so the synthesized worker body — a `foreach` over its slice — runs the
        // body exactly once, for this element. Identical machinery to parallel_for, chunk size 1.
        indent(d+1); *_out << A << "->slice = " << sliceMi->cName << "(&" << V << ", " << W << ", 1);\n";
        for (size_t i = 0; i < caps.size(); ++i) {
            indent(d+1); *_out << A << "->c" << i << " = " << caps[i].addr << ";\n";
        }
        noteThreadSpawn();
        indent(d+1); *_out << H << "[" << SP << "++] = kama_isolate_spawn(&" << trampFn << ", " << A << ");\n";
        indent(d); *_out << "}\n";
        // Hand the join to the enclosing `scope`, which runs it on EVERY exit path (fall-through and the
        // return/break/continue unwinds) before dropping any local — the same join-before-drop guarantee
        // a bare `spawn` gets, which is what lets a child borrow a scope-local.
        innermostTaskScope()->taskChildren.push_back({ H, SP });
        return;
    }

    // K is exactly what `workers:` asked for — NOT min'd with the core count. You said a number; silently
    // substituting a different one is the invisible-K surprise this clause exists to remove, and it is what
    // every neighbour does too (OpenMP's `num_threads`, .NET's MaxDegreeOfParallelism: neither clamps to
    // cores). Oversubscription is a mild inefficiency for CPU-bound work and the RIGHT answer for anything
    // that blocks, so it is the caller's call. Two bounds remain and both are meaningless to exceed:
    // more workers than elements would leave workers with no slice, and fewer than one is not a loop.
    indent(d); *_out << "int " << K << " = (int)(" << emitExpression(pf->workers) << ");\n";
    indent(d); *_out << "if (" << K << " > " << LEN << ") " << K << " = " << LEN << ";\n";
    indent(d); *_out << "if (" << K << " < 1) " << K << " = 1;\n";
    indent(d); *_out << "int32_t " << CH << " = (" << LEN << " + " << K << " - 1) / " << K << ";\n";
    indent(d); *_out << "kama_isolate_t " << H << "[" << K << "];   /* VLA: K = core count, small */\n";
    indent(d); *_out << "int " << SP << " = 0;\n";
    indent(d); *_out << "for (int " << W << " = 0; " << W << " < " << K << "; ++" << W << ") {\n";
    indent(d+1); *_out << "int32_t " << F << " = " << W << " * " << CH << ";\n";
    indent(d+1); *_out << "if (" << F << " >= " << LEN << ") break;\n";
    indent(d+1); *_out << "int32_t " << C << " = " << LEN << " - " << F << "; if (" << C << " > " << CH
                       << ") " << C << " = " << CH << ";\n";
    indent(d+1); *_out << argTy << "* " << A << " = (" << argTy << "*)kama_alloc(" << layoutOf(argTy) << ");\n";
    indent(d+1); *_out << "if (!" << A << ") kama_panic(kama_string_lit(\"out of memory\", 13));\n";
    indent(d+1); *_out << A << "->slice = " << sliceMi->cName << "(&" << V << ", " << F << ", " << C << ");\n";
    for (size_t i = 0; i < caps.size(); ++i) {
        indent(d+1); *_out << A << "->c" << i << " = " << caps[i].addr << ";\n";
    }
    noteThreadSpawn();
    indent(d+1); *_out << H << "[" << SP << "++] = kama_isolate_spawn(&" << trampFn << ", " << A << ");\n";
    indent(d); *_out << "}\n";
    indent(d); *_out << "for (int " << J << " = 0; " << J << " < " << SP << "; ++" << J << ") "
                     << "kama_isolate_join(" << H << "[" << J << "]);\n";
    indent(depth);   *_out << "}\n";
}

// write hoisted temp statements (inline-ctor-in-arg materialization) at `depth`, then clear.
// A leaf statement sets _hoistOK, builds its expression string (which may push here), then calls
// this BEFORE writing its own line — so the temps appear first. Pure ISO C, no `({ … })`.
void CEmitter::flushHoisted(int depth)
{
    if (_hoisted.empty()) return;
    for (auto& s : _hoisted) { indent(depth); *_out << s << "\n"; }
    _hoisted.clear();
    // RE-STAMP. `#line` is written once per statement and clang counts FORWARD from it, so every C line a
    // lowering emits after its first is attributed to "the statement's line plus the offset". A hoisted
    // block is the long shape — a `match` lowering runs ~18 C lines — so without this the REST of the
    // statement it was hoisted for is reported many lines below itself, and on a short file below the end
    // of the file: `#line 4` + 15 reported as vm.kama:18 in a 10-line file.
    //
    // ⚠️ check-diag-line.sh cannot see this and is not the guard for it: every directive here is correct,
    // and it is clang's arithmetic BETWEEN them that leaves the file. tools/check-diag-drift.sh compiles a
    // probe and reads what the C compiler says instead.
    line(_curLine);
}

// emit a condition with hoisting enabled so an inline ctor / `match` works in `if`/`while`/`for`.
// An inline ctor knows its own type; a value-producing `match` needs a result type, and a condition is
// boolean — so a DIRECTLY-`match` condition is typed `bool`. A `match` nested in a larger condition keeps
// no target type and stays the clean "must appear in a typed position" error (bind it to a local).
// Strip ONE redundant outer paren pair when the whole expression is already wrapped. emitExpression
// parenthesizes every binary op, so a bare condition comes back as `(x == y)`; the enclosing
// `if (...)`/`while (...)` then double-wraps it into `if ((x == y))`, which clang flags under
// -Wparentheses-equality (it reads like a mistaken `if ((x = y))`). The keyword already groups, so drop
// the outer pair — cleaner generated C, warning gone. Literal-aware: a `(` inside a string/char literal
// never miscounts. Only strips when the FIRST `(` matches the LAST `)` (so `(a) && (b)` is left alone).
static std::string stripRedundantOuterParens(const std::string& s)
{
    if (s.size() < 2 || s.front() != '(' || s.back() != ')') return s;
    int depth = 0; bool inStr = false, inChr = false;
    for (size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        if (inStr) { if (c == '\\') ++i; else if (c == '"')  inStr = false; continue; }
        if (inChr) { if (c == '\\') ++i; else if (c == '\'') inChr = false; continue; }
        if      (c == '"')  inStr = true;
        else if (c == '\'') inChr = true;
        else if (c == '(')  ++depth;
        else if (c == ')' && --depth == 0 && i != s.size() - 1) return s;   // outer pair closes early
    }
    return s.substr(1, s.size() - 2);
}

std::string CEmitter::emitCondition(SharedExpression cond)
{
    if (!cond) return "";
    bool ph = _hoistOK; _hoistOK = true;
    std::string pmt = _matchTargetCType;
    if (dynamic_cast<MatchNode*>(cond.get())) _matchTargetCType = "bool";
    std::string s = emitExpression(cond);
    _matchTargetCType = pmt;
    _hoistOK = ph;
    return stripRedundantOuterParens(s);
}

// `asm("...")` (MCU 6a) — lower to `__asm__ __volatile__("<text>" : : : "memory")`. Always volatile (never
// elided/reordered) and always a full memory clobber (so `cpsid i`/`dsb`/`dmb` order memory correctly by
// default). Requires an enclosing `unsafe fn` — the same `_inUnsafe` gate as raw pointer index/store.
void CEmitter::emitAsm(AsmNode* a, int depth)
{
    if (!_inUnsafe) {
        unsupported("inline `asm(...)` must be inside an `unsafe fn`", a->line);
        return;
    }
    const std::string& s = a->code ? *a->code : std::string();
    line(a->line);
    indent(depth);
    *_out << "__asm__ __volatile__(\"" << cEscapeStringBody(s) << "\" : : : \"memory\");\n";
}

// std::log v2 (M7) — the recognized-facade lowering. --------------------------------------------------------
// A `logError/Warn/Info/Debug/Trace(tag:, msg:)` call returns void, so it can only appear as an
// ExpressionStatement — recognizing it there covers every call site. `logFacadeLevel` matches the resolved
// callee (both the bare-imported and `std::log::`-qualified spellings resolve to the same `_funcs` key) and
// yields the level ordinal.
static SharedExpression logArgByName(InvocationNode* iv, const char* want)
{
    if (iv && iv->args) for (auto& a : *iv->args)
        if (a && a->name && a->name->value && *a->name->value == want) return a->expression;
    return nullptr;
}

bool CEmitter::logFacadeLevel(InvocationNode* iv, int& level)
{
    if (!iv || !iv->identifier || iv->expression || !iv->identifier->value) return false;  // a free-fn call
    if (!externsHeader("kama_log.h")) return false;                                         // program uses std::log?
    static const std::map<std::string,int> kFacade = {
        {"std__log__logError", 0}, {"std__log__logWarn", 1}, {"std__log__logInfo", 2},
        {"std__log__logDebug", 3}, {"std__log__logTrace", 4} };
    auto it = kFacade.find(resolveFunc(*iv->identifier->value, iv->identifier->qualifier));
    if (it == kFacade.end()) return false;
    if (!logArgByName(iv, "tag") || !logArgByName(iv, "msg")) return false;   // else let the normal path diagnose
    level = it->second;
    return true;
}

// Bind a facade string arg to a stable `kama_string` lvalue and return its name — an addressable temp usable
// both as a span (`.data`/`.len`, for the inline filter check) and by address (`&t`, for the `ref string`
// dispatch). Setup is flushed into `_hoisted` at the caller's chosen depth. An owned rvalue (interpolation/
// concat) rides hoistStringTemp — a scope-dtor'd temp dropped via dropCondTemps where it was hoisted; a
// literal/lvalue is bound to a borrow temp (cap==0, nothing to free), so the value is evaluated exactly once.
std::string CEmitter::logSpanOf(SharedExpression e, int /*depth*/)
{
    if (auto* h = dynamic_cast<HandoffNode*>(e.get())) e = h->value;   // `give`/`copy` marker: log borrows the value
    std::string t = hoistStringTemp(e);                               // owned rvalue -> registered scope-dtor'd temp
    if (t.empty()) {                                                  // literal / lvalue -> a borrow temp
        t = "__logspan" + std::to_string(_tempCounter++);
        _hoisted.push_back("kama_string " + t + " = " + emitExpression(e) + ";");
    }
    return t;
}

void CEmitter::emitLogFacade(InvocationNode* iv, int level, int depth)
{
    // Compile-time strip: below the floor in a --release build the whole statement (message build included)
    // is physically absent — like `debugAssert`. Works at any -O; args are not evaluated (log calls must be
    // side-effect-free, the same contract as a stripped `debugAssert`).
    if (_release && level >= _logCompileMin) return;

    line(iv->line);
    bool ph = _hoistOK; _hoistOK = true;
    size_t tagPre = _scopes.empty() ? 0 : _scopes.back().locals.size();

    // Wrapper block: the tag span binds here (the filter needs it); a hoisted owned tag temp drops before it
    // closes, where it is in scope.
    indent(depth); *_out << "{\n";
    int bd = depth + 1;
    std::string tagVar = logSpanOf(logArgByName(iv, "tag"), bd);
    flushHoisted(bd);

    // Runtime filter — inlined here in the CALLER's TU (it reads the process-global env config, so it is
    // multi-TU-safe). The message is built INSIDE, so a filtered-out call skips the interpolation entirely.
    indent(bd); *_out << "if (kama_log_enabled(" << level << ", " << tagVar << ".data, " << tagVar << ".len)) {\n";
    int gd = bd + 1;
    size_t msgPre = _scopes.empty() ? 0 : _scopes.back().locals.size();
    std::string msgVar = logSpanOf(logArgByName(iv, "msg"), gd);
    flushHoisted(gd);
    // Dispatch straight to the extern seam: the sink slot is external-linkage (one definition), so the
    // borrowed spans reach the right slot from any TU. Read by borrow (`.data`/`.len`) — no ownership transfer.
    indent(gd); *_out << "kama_log_dispatch(" << level << ", " << tagVar << ".data, " << tagVar << ".len, "
                      << msgVar << ".data, " << msgVar << ".len);\n";
    dropCondTemps(msgPre, gd);                 // drop the message's Formatter/owned temps inside the guard
    indent(bd); *_out << "}\n";

    dropCondTemps(tagPre, bd);                 // drop an owned tag temp inside the wrapper
    indent(depth); *_out << "}\n";
    _hoistOK = ph;
}

// Bring zero-inited storage of class `ty`, named `nm` in C, up to a valid empty state: apply each field's
// inline initializer, call each field's `default` ctor, and set the vtable pointer. Shared by the bare
// class-local declaration path and by a `ctor`'s implicit `this` storage — the two places a value of a
// class type comes into being without an initializer, and they must agree exactly.
//
// Construction-model M8d.1: `= {0}` alone is valid only for a PROVABLY-ZERO default (a primitive, a raw
// `UnsafePtr`, an intrinsic collection). A field whose `default` ALLOCATES (a `SortedMap` building a B-tree root)
// would otherwise zero-init to a broken null-root value; this is what makes `isDefaultFillable` actually
// FILL correctly. A gated-away default (a custom-`A` collection) has no `isDefaultCtor` method and is not
// filled — it is `mustAssign`, so the completeness gate already forces an explicit assignment.
// `this` inside a `ctor` lowers to `self`, a `T*` pointing at the storage the ctor is filling. Wherever the
// destination is a `T` BY VALUE — the return temp, a variant payload such as `Result::Ok(value: this)` — it
// has to be dereferenced. True for exactly that case. (As an ARGUMENT to an ordinary call, `this` already
// has its own by-value handling at each argument site.)
bool CEmitter::ctorThisAsValue(SharedExpression e, const std::string& dstCType) const
{
    return _inNamedCtorBody && _currentClass && dstCType == _currentClass->name
           && dynamic_cast<ThisAccessNode*>(e.get()) != nullptr;
}

void CEmitter::emitAggregateFill(const std::string& nm, const std::string& ty, int lineNo, int depth,
                                 const std::string& moveKey, SharedExpression baseInit)
{
    // Move-state keys are spelled the way the SOURCE names the value, which is not always the C name:
    // a ctor's storage is `__self` in C but `this` in kama, and `lvalueMoveKey` keys off the source.
    const std::string& mk = moveKey.empty() ? nm : moveKey;
#if KAMA_INHERITANCE
    // `this.base = Base.<ctor>(…)` — the base part is built by the BASE'S OWN constructor and installed
    // whole. It goes FIRST, and that ordering is the entire answer to the vtable pointer: `__base` sits at
    // offset 0 and the vptr lives at the chain ROOT, i.e. INSIDE `__base` for a derived type, so a
    // whole-struct store would clobber it. The vptr store at the end of this function then re-stamps the
    // most-derived vtable over whatever the base wrote (or, for an `abstract` base, over the zero it left).
    //
    // The storage is fresh `{0}`, so there is no old value to drop — which is why this is emitted here
    // rather than routed through the general assignment path, whose first act would be a `Base__dtor` on
    // zeroed memory.
    if (baseInit && _classes[ty].base) {
        _inBaseInstall = true;                  // lets an `abstract` base's ctor be called HERE and nowhere else
        std::string rhs = emitExpression(baseInit);
        _inBaseInstall = false;
        flushHoisted(depth);                    // emitReorderedCall may have hoisted argument temps
        line(lineNo); indent(depth);
        *_out << nm << ".__base = " << rhs << ";\n";
    }
#endif
    for (auto& f : _classes[ty].fields) {
        // An inline field initializer (`const int32 kind = 7;`) applies here too, exactly as the
        // instance-ctor path applies it — else a factory-built value loses it (zero instead of 7). #M8d.2
        if (f.initializer) {
            // Through the hand-off funnel, with the FIELD's type as the destination — the same one a return
            // value and a `match` arm take — so a destination-typed construction (`DynamicArray<T> items =
            // DynamicArray.empty();`) resolves as it does in a local initializer, instead of refusing with
            // "give the type arguments" when they are already on the field (KR-21 b).
            emitOwnedValueInto(nm + "." + f.name, fieldCType(ty, f), f.initializer, lineNo, depth, "a field initializer",
                               /*kindChecked=*/true);
            continue;
        }
        // The BAKED type — this class may be declared in another module, and resolving its field types
        // here resolved them in the READER's scope: across a module boundary the prefix differs, the
        // lookup below missed, and the `continue` skipped a fill that the same source one module over
        // emitted. The field then kept its `{0}` instead of its `default` ctor. See bakeFieldCTypes.
        std::string fcls = fieldCType(ty, f);
        auto cit = _classes.find(fcls);
        if (cit == _classes.end()) continue;
        bool filled = false;
        for (auto& kv : cit->second.methods)
            if (kv.second.isDefaultCtor) {
                line(lineNo); indent(depth);
                *_out << nm << "." << f.name << " = " << kv.second.cName << "();\n";
                filled = true;
                break;
            }
        // Drop-only-if-live (A): a move-only-value field left `{0}` by the fill (no inline initializer, no
        // `default` ctor — e.g. a raw-handle `resource` field) is NOT yet live. Seed its `local.field`
        // move-state Moved so the first `f.field = give …` does NOT drop the zeroed slot (which for a raw
        // handle would e.g. close(0)).
        if (!filled && isMoveOnlyValue(fcls))
            _moveState[mk + "." + f.name] = MoveState::Moved;
    }
    // Construction-model M8 Phase E: a polymorphic (vtable-carrying) value sets its `__vptr` directly — the
    // value (`.`) mirror of a method body's `self->…__vptr` store. With `synthCtor` removed, a factory-built
    // value of a polymorphic class would otherwise dispatch through a NULL vptr. Most-derived vtable at the
    // root slot.
    if (_classes[ty].hasVtable && !_classes[ty].isAbstractClass) {
        line(lineNo); indent(depth);
        *_out << nm << "." << vptrPrefix(&_classes[ty]) << "__vptr = &"
              << _classes[ty].name << "__vtable;\n";
    }
}

void CEmitter::emitStatement(SharedStatement stmt, int depth)
{
    if (!stmt) return;
    ASTNode* n = stmt.get();

    // `:= expr;` is the value of a value-producing `match` arm — the match emitter consumes it as the
    // arm's final statement. Reaching it here means it is misplaced (not last, or in a match used as a
    // statement, or outside any match).
    if (dynamic_cast<ArmValueNode*>(n)) {
        unsupported("`:=` produces a match arm's value — it is only valid as the final statement of a "
                    "value-producing `match` arm", n->line);
        return;
    }

    if (auto* block = dynamic_cast<BlockNode*>(n)) {
        line(n->line);
        indent(depth);
        emitBlock(block, depth);
        *_out << "\n";
        return;
    }

    // `scope { ... }` — structured concurrency (M4): a task scope that joins every child `spawn`ed
    // inside it at the closing brace, before any local dtor (join-before-drop).
    if (auto* sc = dynamic_cast<ScopeNode*>(n)) {
        emitScope(sc, depth);
        return;
    }

    // `borrow h as v { ... }` — the lexical window a view is minted into (the view model).
    if (auto* bn = dynamic_cast<BorrowNode*>(n)) {
        emitBorrow(bn, depth);
        return;
    }

    // `parallel_for (ref T e in coll) { ... }` — disjoint-slice data-parallel loop (M6.3): split `coll`
    // into K non-overlapping sub-Views, run the body on each in a worker isolate, join all at the brace.
    if (auto* pf = dynamic_cast<ParallelForNode*>(n)) {
        emitParallelFor(pf, depth);
        return;
    }

    // `spawn worker(p: give x);` — a bare `spawn` statement: a deferred-join child of the enclosing
    // `scope { }` (M4). Scope-only; shared-nothing by construction (bare top-level entry + moved arg).
    if (auto* iso = dynamic_cast<IsolateNode*>(n)) {
        emitIsolate(iso, depth);
        return;
    }

    // `asm("...")` — inline assembly (MCU 6a). Requires an `unsafe fn` (same greppable seam as raw pointer
    // ops); lowers to the volatile + memory-clobber form so it is never elided/reordered.
    if (auto* a = dynamic_cast<AsmNode*>(n)) {
        emitAsm(a, depth);
        return;
    }

    // `comptime assert(cond:, msg:)` (M7) — checked here, emits no runtime code. Inside a generic body this
    // runs once per instantiation, with `_comptimeSubst`/`_typeSubst` already bound by emitGenericInst.
    if (auto* ca = dynamic_cast<ComptimeAssertNode*>(n)) {
        emitComptimeAssert(ca);
        return;
    }

    {
        // Local declaration — plain or `const`. The two declarator node types
        // are structurally identical (name + initializer), so one generic body serves
        // both; a const decl additionally records each name as immutable (no
        // reassignment, and — deep const — no writes THROUGH the binding either).
        LocalVariableDeclaration* lvd = dynamic_cast<LocalVariableDeclaration*>(n);
        ConstLocalVariableDeclaration* cvd = lvd ? nullptr
                                            : dynamic_cast<ConstLocalVariableDeclaration*>(n);
        SharedIdentifier declType = lvd ? lvd->type : (cvd ? cvd->type : SharedIdentifier());
        bool isConstDecl = (cvd != nullptr);
        if (declType) {
            // a bare generic type without a type argument (`Box b` instead of `Box<int32> b`)
            // is not a usable type — the template is not a concrete class. EXCEPTION: an all-defaulted
            // generic (`BitSet` == `BitSet<GlobalAllocator>`) is a complete type spelled bare.
            if (declType->value && !declType->genericArg
                && _genericTypes.count(resolveUserName(*declType->value, declType->qualifier))
                && !allTypeParamsDefaulted(resolveUserName(*declType->value, declType->qualifier)))
                unsupported(("generic type `" + *declType->value + "` needs a type argument, e.g. `"
                             + *declType->value + "<int32>`").c_str(), n->line);
            // Not in the template probe: there `N` is a comptime PARAMETER with no binding, which is not a fault.
            SharedExpression init0 = lvd && lvd->variables && !lvd->variables->empty() ? (*lvd->variables)[0]->initializer
                                   : cvd && cvd->variables && !cvd->variables->empty() ? (*cvd->variables)[0]->initializer
                                   : SharedExpression();
            auto* lit0 = dynamic_cast<ArrayLiteralNode*>(init0.get());
            int64_t litN = lit0 && lit0->elements && !lit0->elements->empty() ? (int64_t)lit0->elements->size() : 1;
            if (!_probingTemplate)
                if (SharedIdentifier ph = unsizedFixedPlaceholder(declType, "a local's `InlineArray`", n->line, litN)) {
                    declType = ph;   // this walk only — the AST node stays: the query index holds raw pointers into it
                }
            std::string ty = cType(declType);
            // Every name in the spelling — the head alone waves `Optional<Zork>` through, because the instance
            // mangles to some name regardless — and a `#(K)` constant's reach (`constArgN` folds a qualified
            // private one, so `#(geo::HIDK)` compiled). An unresolved `K` is left to the fold's diagnostic.
            checkBodyType(declType, "a local declaration", n->line);
            if (_typeSubst.empty()) rejectBareCChar(declType, "a local", n->line);   // not during a poisoned instance's re-walk
            rejectMintProtocolValue(declType, "a local", n->line);
            // Containment: a local BINDING of raw-pointer type. Declaring an `UnsafePtr` FIELD stays legal
            // (every container depends on it), but naming one as a local is holding raw memory in a body,
            // which is what the marker exists to make greppable.
            if (namesUnsafePtr(declType))
                rejectRawOutsideUnsafe(("local `" + (lvd && lvd->variables && !lvd->variables->empty()
                                                     && (*lvd->variables)[0]->name
                                                     && (*lvd->variables)[0]->name->value
                                                        ? *(*lvd->variables)[0]->name->value
                                                        : std::string("?")) + "`").c_str(), n->line);
            if (lvd && lvd->variables)
                for (auto& d : *lvd->variables)
                    if (d) { rejectNullInit(declType, d->initializer, "a local", n->line);
                             rejectInitKindMismatch(declType, d->initializer, "a local", n->line);
                             rejectConstPtrWiden(ty, d->initializer, "a local's initializer", n->line); }
            bool cls = isClass(ty);
            bool iface = isInterface(ty);
            auto emitDeclarator = [&](auto& d) {
                std::string nm = (d->name && d->name->value) ? *d->name->value : "";
                // `slot` means "no value yet", so spelling one WITH a value is a contradiction — and it
                // would quietly disable the drop of a live object. One way to say each thing.
                if (lvd && lvd->isSlot && d->initializer)
                    unsupported(("`slot " + nm + "` declares a hole, so it cannot have an initializer — "
                                 "drop the `slot` to declare an ordinary local").c_str(), n->line);
                // A local with NO initializer and no `slot` is the unstated hole this campaign closes: it
                // zero-inits, it is live, and its destructor runs — which is the only reason a raw-handle
                // resource ever needed a runtime drop guard. Warn while the corpus is swept; M3 flips this
                // to a hard error and drops the implicit default-ctor call below with it.
                // A ctor's value is `this`, so declaring uninitialized storage OF THE TYPE BEING BUILT is
                // a second name for the same thing — and there is no way to hand two of them back. `this`
                // is the only spelling. An INITIALIZED local of the same type is untouched: it is a
                // finished value like any other, not a second thing under construction.
                //
                // Checked BEFORE the missing-initializer rule, and instead of it: here `slot` is not the
                // answer the general rule would offer, so reporting both would give one declaration two
                // messages, the first of them pointing the wrong way.
                bool ctorOwnType = _inNamedCtorBody && !d->initializer
                                && _currentClass && ty == _currentClass->name;
                if (ctorOwnType)
                    unsupported(("a constructor builds `" + ty + "`, and that value is `this` — assign its "
                                 "fields directly (`this.<field> = …`) instead of declaring `" + nm
                                 + "`").c_str(), n->line);
                else if (lvd && !lvd->isSlot && !d->initializer)
                    unsupported(("local `" + nm + "` has no initializer — prefix it with `slot` (declaring "
                                 "a hole that must be assigned before it is used) or give it a value").c_str(),
                                n->line);
                // Ban shadowing (enforces the flat-name-map assumption above; C#-aligned, "one way"). A
                // local may not shadow a parameter, an enclosing-scope local, or an in-scope field. (A
                // param sharing a FIELD name — the `this.x = x` idiom — is allowed and handled elsewhere.)
                if (!nm.empty()) {
                    // `self` is the C name of the receiver pointer inside a type body, so a local of that
                    // name collides with it and the author gets clang's "redefinition of 'self'" rather
                    // than anything kama said. Reserve it across the whole type body — a `static fn` has
                    // no receiver to collide with today, but one rule is worth more than one exemption,
                    // and a free fn is not a type body at all (tests/fnptr_method.kama names a `fnptr`
                    // parameter `self` deliberately, and keeps doing so).
                    if (nm == "self" && _currentClass)
                        unsupported("`self` names the receiver inside a type body — the kama spelling is "
                                    "`this`; rename this local", n->line);
                    checkConstParamBinder(nm, "local", n->line);
                    if (_paramNames.count(nm))
                        unsupported(("local `" + nm + "` shadows a parameter — rename it").c_str(), n->line);
                    else {
                        bool enc = false;
                        for (auto& sc : _scopes) { for (auto& dn : sc.declaredNames) if (dn == nm) { enc = true; break; } if (enc) break; }
                        if (enc)
                            unsupported(("local `" + nm + "` shadows an enclosing-scope local — rename it").c_str(), n->line);
                        else if (_currentClass && !_inStaticMethod && !_inNamedCtorBody
                                 && _currentClass->fieldNames.count(nm))
                            // A static method has no `this` → no bare field access → nothing to shadow.
                            // Neither does a `ctor`: a bare name there is ALWAYS a local or a param, because
                            // the value under construction is reached only through `this` (below). So
                            // `int32 fd = openRaw(…); this.fd = fd;` shadows nothing — it is the clearest
                            // spelling there is, and it is what the stdlib's raw-handle ctors already write.
                            unsupported(("local `" + nm + "` shadows a field — rename it").c_str(), n->line);
                    }
                    if (!_scopes.empty()) _scopes.back().declaredNames.push_back(nm);
                    registerBinding(d->name.get(), SymKind::Local);   // LSP index (analysis mode only)
                }
                // The WINDOW RULE. A view local outlives the statement that made it, so its root has to
                // outlive it too — and a container still in scope does not, since the next line may grow
                // it. `borrow` is the spelling that bounds one, and after the mint generalization every
                // `@viewable` grant can open a window, so a rejection here always has one.
                if (isViewCType(ty) && d->initializer) {
                    if (viewLocalBounded(d->initializer)) _scopes.back().boundedViews.insert(nm);
                    else
                        unsupported(("`" + nm + "` is a view of storage that nothing bounds — a view "
                                     "borrows a buffer it does not own, so it may only live where that "
                                     "buffer is held still. Open a window: `borrow <container>.<mint>() as "
                                     + nm + " { … }`, and derive inside it with `.slice(…)`. A view already "
                                     "rooted in a window, or in a by-value view parameter, needs no "
                                     "window of its own").c_str(), n->line);
                }
                noteScopedBinding(nm);                        // the block owns it: popScope retires every entry below
                _localTypes[nm] = (cls || iface) ? ty : "";   // record all names (shadow fields)
                _localCTypes[nm] = ty;                        // full C type (incl. primitives) for assignment-RHS lowering
                _localTypeNodes[nm] = declType;               // kama type node (keeps char vs uint32 for interpolation)
                if (isConstDecl) {
                    if (!d->initializer)
                        unsupported("a const must be initialized (it is immutable)", n->line);
                    _constLocals.insert(nm);
                    // 6b-2: bind the folded value so a later local `InlineArray<T,(CAP)>` / `[v;(CAP)]`
                    // resolves at emit time (cType/emitArrayLiteral call constValue). Declared-before-use.
                    // Plain `const` folds opportunistically (works as a size when it can); `comptime` is the
                    // explicit form — if it can't fold to a compile-time constant, that's an error AT the decl.
                    { int64_t cv; if (constValue(d->initializer, cv)) _constLocalVals[nm] = cv; }
                    if (cvd && cvd->isComptime && d->initializer) {
                        int64_t cv;
                        if (!constValue(d->initializer, cv) && !isConstInitExpr(d->initializer.get()))
                            unsupported(("a `comptime` local must have a compile-time-constant initializer "
                                         "(a literal, `sizeof`, `alignof`, or const arithmetic) — `" + nm
                                         + "`; use `const` for a runtime-initialized immutable").c_str(), n->line);
                    }
                }

                // Interface-typed local: `I s = concrete;` -> a fat pointer borrowing
                // the concrete object (which must be an lvalue that outlives `s`).
                if (iface) {
                    line(n->line); indent(depth);
                    *_out << ty << " " << nm;
                    if (d->initializer) {
                        std::string c = exprClass(d->initializer);
                        // Conformance, ahead of the cascade. The `else` at the bottom used to be the only
                        // thing standing here, and it fires only when `exprClass` answers NOTHING — so it
                        // caught a plain enum and let every non-conforming CLASS through to the
                        // `isClass(c)` branch, which cheerfully emitted `Plain__as_Hashable` for clang to
                        // discover did not exist.
                        rejectContractNonConformance(ty, d->initializer, "a local", n->line);
                        if (!c.empty() && isClass(c) && dynamic_cast<ThisAccessNode*>(d->initializer.get()))
                            // `this` is ALREADY a pointer to the concrete object; fatPointer's `&(lvalue)` would
                            // wrongly take the address OF the `this` pointer. Bind the pointer directly.
                            *_out << " = (" << ty << "){ (void*)(" << emitExpression(d->initializer)
                                  << "), &" << contractVtblOf(c, ty) << " }";
                        else if (!c.empty() && isClass(c))
                            *_out << " = " << fatPointer(ty, c, emitExpression(d->initializer));
                        else if (!c.empty() && isInterface(c))
                            *_out << " = " << emitExpression(d->initializer);  // already an interface value
                        else if (!primWidenKey(d->initializer, ty).empty()) {
                            // A PRIMITIVE widened to a contract value. `&(int32_t){ n }` takes the address
                            // of a C99 COMPOUND LITERAL, which has the enclosing block's storage duration —
                            // exactly the lifetime a borrow wants, and no hoisted temp. The existing escape
                            // check still forbids storing the fat pointer.
                            std::string pk = primWidenKey(d->initializer, ty);
                            *_out << " = (" << ty << "){ (void*)&(" << primConformance(pk)->name << "){ "
                                  << emitExpression(d->initializer) << " }, &" << intrinsicContractVtbl(pk, ty) << " }";
                        }
                        else
                            unsupported(("cannot bind this to the contract `" + ty + "` — a contract value "
                                         "borrows a concrete object, so it needs a named value, or a "
                                         "primitive that declares the conformance").c_str(), n->line);
                    }
                    *_out << ";\n";
                    return;
                }

                // FunctionPtr<Sig> binding: a signature-typed local — track the
                // sig (drives invoke), bind a free function (resolve + signature-check)
                // or another FunctionPtr; must be initialized (non-null).
                if (isSigType(ty)) {
                    _localTypes[nm] = ty;
                    line(n->line); indent(depth);
                    *_out << ty << " " << nm;
                    if (!d->initializer)
                        unsupported("a FunctionPtr must be initialized (it is non-null)", n->line);
                    else
                        *_out << " = " << emitFnPtrBind(ty, d->initializer, n->line);
                    *_out << ";\n";
                    return;
                }

                if (!cls) {
                    line(n->line);
                    std::string initStr;
                    if (d->initializer) {
                        bool ph = _hoistOK; _hoistOK = true;               // inline-ctor hoisting
                        std::string pmt = _matchTargetCType; _matchTargetCType = ty;   // value-producing match result type
                        initStr = " = " + emitExpression(d->initializer);
                        _matchTargetCType = pmt;
                        _hoistOK = ph;
                    }
                    flushHoisted(depth);                                   // temp decls first…
                    indent(depth);
                    *_out << ty << " " << nm << initStr << ";\n";          // …then this declaration
                    return;
                }

                // Class-typed local: declare the value, then construct in place.
                // Collections zero-init so an unconstructed one frees safely; extern
                // structs zero-init so unset descriptor fields are well-defined.
                line(n->line); indent(depth);
                // A bare (uninitialized) local must be brought to a valid state so its scope-exit dtor — and
                // any `f = …` that first RELEASES the old field — don't free stack garbage. Collections /
                // extern structs zero-init (no kama ctor); a destructible `resource` WITHOUT a zero-arg ctor
                // (e.g. a factory-built one) MUST zero-init too — else its `Owned`/`Shared` field is garbage
                // and the first assignment's "drop old" frees a wild pointer (glibc tolerates it, macOS
                // aborts). A type WITH a default ctor is brought up by that ctor (below) instead.
                // Construction-model M8b: a bare aggregate local with no default ctor + no initializer (a
                // factory building a value field-by-field) also zero-inits — so any DEFAULT-FILLABLE field
                // left unassigned reaches its zero default (`ZERO COUNTS`) rather than stack garbage. The
                // non-zero default fill (calling the field type's `default` ctor) lands with M8c.
                // An initializer-less local is now always a `slot` — a HOLE — so it zero-inits and takes
                // the field-default fill below. It no longer silently runs the type's `default` ctor: that
                // was a second piece of implicit construction, and a hole that quietly constructs itself is
                // a contradiction. Spell `T x = T.empty();` to get the default.
                bool zeroInit = _classes[ty].isIntrinsicColl || _classes[ty].isExternStruct
                    || !d->initializer;
                *_out << ty << " " << nm << (zeroInit ? " = {0}" : "") << ";\n";
                // Track for RAII cleanup at scope exit (assumes init-at-decl).
                if (_classes[ty].destructible || isMoveOnlyValue(ty)) recordDestructibleLocal(nm, ty);  // track empty resources for move analysis
                // `slot T x;` — a HOLE, so it is not live and must NOT be dropped. Seed the state the
                // move analysis already uses for "this local owns nothing right now": scope cleanup skips
                // a Moved local, and an assignment's drop-the-old-value step is suppressed the same way.
                // Every assignment handler already clears it back to NotMoved, and the if/else + match
                // move merges already handle the flow — so drop-elision needs no machinery of its own.
                // (Seeded AFTER recordDestructibleLocal, which sets NotMoved for an ownsByValue type.)
                if (lvd && lvd->isSlot) { _slotLocals.insert(nm); _slotDeclared.insert(nm); _moveState[nm] = MoveState::Moved; }
                if (!d->initializer) {
                    // No initializer: this is a `slot`. Its drop is elided while it stays unassigned, but
                    // the storage must still be well-defined, because filling it field-by-field reads and
                    // releases what is already there. The `= {0}` above plus the field-default fill below
                    // is that valid state.
                    if (zeroInit && !_classes[ty].isIntrinsicColl && !_classes[ty].isExternStruct)
                        emitAggregateFill(nm, ty, n->line, depth);
                    return;   // otherwise declared-only (zero-inited empty, or a non-destructible value)
                }

                // unwrap a give/copy hand-off marker — the inner NAMED value drives
                // move (give) vs duplicate (copy). A fresh rvalue never takes a marker.
                SharedExpression init = d->initializer;
                int handoff = 0;   // 0 none, 1 give, 2 copy
                if (auto* h = dynamic_cast<HandoffNode*>(d->initializer.get())) { handoff = h->isGive ? 1 : 2; init = h->value; }
                if (handoff && !isNamedValue(init.get()))
                    unsupported("`give`/`copy` apply to a named value — a fresh `new`/constructor/call result needs no marker", n->line);

                // `T(...)` with no `new` (an InvocationNode whose callee names the
                // declared class) is STACK construction; `new` is reserved for the heap.
                InvocationNode* stackCtor = nullptr;
                if (auto* iv = dynamic_cast<InvocationNode*>(init.get()))
                    if (iv->identifier && iv->identifier->value && isClass(ty)) {
                        std::string rn = resolveUserName(*iv->identifier->value, iv->identifier->qualifier);
                        // `Box<int32> b = Box(v: 7)` — the ctor names the bare template `Box`, but
                        // the declared type is the instance `Box_int32`; accept the template→instance match.
                        auto g = _genericTypeInstOf.find(ty);
                        if (rn == ty || (g != _genericTypeInstOf.end() && g->second == rn))
                            stackCtor = iv;
                    }

                // `Optional<T> r = try cast<T>(x);` — the fallible conversion, handled here for the same
                // reason `try new` is: the `Some` payload type comes from the DECLARED destination, and
                // the operand needs a statement slot so it is evaluated once.
                if (auto* cst = dynamic_cast<CastNode*>(init.get())) {
                    if (cst->isTry) {
                        line(n->line);
                        bool ph = _hoistOK; _hoistOK = true;
                        std::string s = emitTryCast(ty, nm, cst, n->line);
                        _hoistOK = ph; flushHoisted(depth);
                        if (!s.empty()) { indent(depth); *_out << s << "\n"; }
                        return;
                    }
                }

                if (auto* oc = dynamic_cast<ObjectCreationNode*>(init.get())) {
                    checkNamelessNewBanned(oc, n->line);   // M8 Phase E: no nameless `new Type(...)`
                    // no-heap gate (covers try/fallible new below) — a placement `new` into an allocator
                    // the program owns is judged by what that allocator reaches, see newDrawsFromHeap.
                    if (newDrawsFromHeap(oc)) rejectIfNoHeap(oc->isTry ? "try new" : "new", n->line);
                    // `new` is the HEAP operator — it boxes a value into a smart
                    // pointer (Owned/Shared/Weak), naming the element type directly:
                    // `Owned<Box> p = new Box(...)`. (BindableFunctionPtr keeps `new` for
                    // its bind.) `new` into a plain value type is an error — drop `new`.
                    // NOTE: the intrinsic-iface + library-adopt boxing below is mirrored (as a
                    // hoisted-temp string) in tryHoistInlineValue for return/arg/payload positions —
                    // keep the two in sync (esp. the Shared ctrl asymmetry: iface path emits
                    // kama_ctrl_new(), the library-adopt path lets `adopt` allocate it).
                    std::string octy = cType(oc->type);
                    { std::string ve = newVariantEnum(oc, !heapOwnerTarget(ty).empty() ? heapOwnerTarget(ty) : std::string());
                      if (!ve.empty()) octy = ve; }
                    // `try new T(...)` (M-step5): the non-panic entry — build `Optional<Owned<T>>`, `None` on
                    // OOM instead of `kama_panic`. `nm` is assigned by both branches (declared/RAII-tracked
                    // above). Mirrors the `ctorIsFallible` shape just below (wrap-a-box-in-a-sum-type).
                    if (oc->isTry) {
                        line(n->line);
                        bool ph = _hoistOK; _hoistOK = true;               // hoist arg hand-offs
                        std::string s = emitTryNewBox(ty, nm, oc, n->line);
                        _hoistOK = ph; flushHoisted(depth);
                        if (!s.empty()) { indent(depth); *_out << s << "\n"; }
                        return;
                    }
                    // M4b: a fallible (`Result`-returning) named ctor via `new` builds `Result<Owned<T>,E>` —
                    // box the `Ok` payload, propagate `Err` with no allocation. `nm` (already declared +
                    // RAII-tracked at the top of this declarator) is assigned by both branches.
                    if (ctorIsFallible(oc)) {
                        line(n->line);
                        bool ph = _hoistOK; _hoistOK = true;               // hoist arg hand-offs
                        std::string s = emitFallibleNewBox(ty, nm, oc, n->line);
                        _hoistOK = ph; flushHoisted(depth);
                        if (!s.empty()) { indent(depth); *_out << s << "\n"; }
                        return;
                    }
                    // Allocator-aware `new(allocator: …)` threads a stateful allocator through BOTH the
                    // concrete-element library boxes (`Owned<T, A>` via `adoptIn`) AND the type-erased
                    // INTERFACE-element intrinsic path (`isSmartPtrClass`, M11d — each fat handle carries its
                    // own `A alloc` value + `objsize`, drawing the pointee/ctrl from `A`); handled inline below.
                    if (isBindableClass(ty)) {
                        // `new` is the HEAP operator and a bindable is a value (its object is already on the
                        // heap, behind the `Owned`/`Shared` it takes) — so it is built like any other value.
                        unsupported("a `BindableFunctionPtr` is built by its constructor, not `new` — write "
                                    "`BindableFunctionPtr.bind(obj: …, method: Type::method)`", n->line);
                    } else if (isSmartPtrClass(ty)) {
                        std::string T = _classes[ty].collElemClass;
                        if (isSmartPtrClass(octy) || isBindableClass(octy))
                            unsupported(("`new` now names the element type — write `new " + T
                                         + "(...)`, not the wrapper").c_str(), n->line);
                        else if (isInterface(T)) {
                            // box a concrete class that implements interface T into an owned
                            // interface handle — malloc the concrete, ctor it, set {obj, vtbl}.
                            auto cit = _classes.find(octy);
                            bool implementsT = false;
                            if (cit != _classes.end())
                                for (auto& i : cit->second.interfaces) if (i == T) { implementsT = true; break; }
                            if (!implementsT)
                                unsupported(("`new " + octy + "` does not implement `" + T + "` — `" + ty
                                             + "` owns a class that satisfies the contract").c_str(), n->line);
                            else if (_classes[octy].isAbstractClass)
                                unsupported(("cannot instantiate abstract class '" + octy + "'").c_str(), n->line);
                            else {
                                // Placement `new(allocator: a)` (M11d): draw the pointee AND (Shared) the ctrl
                                // from `a`, and store `a`+`objsize` in the fat handle so its dtor frees through it.
                                // A default GlobalAllocator box keeps the libc malloc + kama_ctrl_new() path.
                                bool useAlloc = ifaceNewAllocator(ty, oc, n->line);
                                std::string ap;
                                line(n->line); indent(depth);
                                if (useAlloc) {
                                    auto pa = placementAllocator(oc, n->line, /*emit=*/true);
                                    ap = "__alloc" + std::to_string(_tempCounter++);
                                    *_out << pa.second << " " << ap << " = " << pa.first << ";\n"; indent(depth);
                                    *_out << nm << ".obj = (void*)unwrapPtr(" << pa.second << "__allocate(&" << ap << ", " << layoutOf(octy) << "));\n";
                                } else {
                                    *_out << nm << ".obj = kama_alloc(" << layoutOf(octy) << ");\n";
                                }
                                indent(depth); *_out << "if (!" << nm << ".obj) kama_panic(kama_string_lit(\"out of memory\", 13));\n";
                                if (newBuildsValue(octy, oc))
                                    emitNewFactoryMove(octy, "(" + octy + "*)" + nm + ".obj", oc, n->line, depth);
                                indent(depth); *_out << nm << ".vtbl = &" << octy << "__as_" << T << ";\n";
                                if (useAlloc) {
                                    indent(depth); *_out << nm << ".alloc = " << ap << ";\n";
                                }
                                if (smartKind(ty) == CollKind::Shared) {   // ref-counted owned interface
                                    indent(depth);
                                    if (useAlloc)   // ctrl drawn from the SAME allocator (validated == the box's A)
                                        *_out << nm << ".ctrl = (kama_ctrl*)unwrapPtr(" << _collections[ty].allocType
                                              << "__allocate(&" << ap << ", " << layoutOf("kama_ctrl") << ")); "
                                              << nm << ".ctrl->strong = 1; " << nm << ".ctrl->weak = 0;\n";
                                    else
                                        *_out << nm << ".ctrl = kama_ctrl_new();\n";
                                }
                            }
                        }
                        // (No concrete-element arm: a smart-pointer class is only ever registered over a
                        // CONTRACT element — registerGenericTypeInst — so `Owned<T>` is the library type.)
                    } else if (!heapOwnerTarget(ty).empty()) {
                        // a LIBRARY heap owner (`Box<T> implements HeapOwner<T>`): `new T(args)`
                        // placement-constructs T on the heap and adopts the raw ptr — ZERO copies, same
                        // as the intrinsic. `new` stays valid ONLY into an RAII owner, so it can't leak.
                        std::string T = heapOwnerTarget(ty);
                        // `new Derived` into a `Shared`/`Owned<Base>` widens (upcast): build the DERIVED,
                        // then adopt its base subobject (offset-0 `__base` chain) — destruction stays
                        // virtual (Base__vdrop), so no slicing. `octy == T` is the plain same-element case.
                        bool upcastNew = (octy != T) && isClass(octy) && isBaseOf(T, octy);
                        std::string C = upcastNew ? octy : T;              // the concrete actually built
                        if (octy != T && !upcastNew)
                            unsupported(("`" + ty + "` owns `" + T + "`, but got `new " + octy
                                         + "(...)` — name the element type or a derived of it, not the owner").c_str(), n->line);
                        else if (isClass(C) && _classes[C].isAbstractClass)
                            unsupported(("cannot instantiate abstract class '" + C + "'").c_str(), n->line);
                        else {
                            // Placement `new(allocator: a)`: draw the block from `a` (via its `allocate`) and
                            // adopt through `adoptIn` so the box stores the handle for its dtor's `deallocate`.
                            // A bare `new` keeps the libc malloc + `adopt` path (byte-for-byte as before).
                            auto pa = placementAllocator(oc, n->line, /*emit=*/true);
                            bool placed = !pa.second.empty();
                            // A bare `new` default-constructs the box's allocator — safe only for a STATELESS
                            // one (no fields, e.g. GlobalAllocator). A stateful `Owned<T, A>` needs the handle,
                            // so require the placement form (else the block would leak on a no-op deallocate).
                            if (!placed) {
                                const std::string why = bareNewRefusal(boxAllocatorArg(ty), "new", "T");
                                if (!why.empty()) unsupported(why.c_str(), n->line);
                            } else {
                                // The box's declared allocator type must match the `new(allocator: …)` handle —
                                // there is no inference axis; spell it (e.g. `Shared<T, BumpAllocator>`).
                                std::string boxA = boxAllocatorArg(ty);
                                if (!boxA.empty() && boxA != pa.second)
                                    unsupported(("the box's allocator type `" + boxA + "` does not match the `new(allocator: …)` "
                                                 "handle `" + pa.second + "` — spell the box's allocator explicitly").c_str(), n->line);
                            }
                            const char* adoptName = placed ? "adoptIn" : "adopt";
                            ClassInfo* ao = nullptr;
                            MethodInfo* adoptM = findMethod(&_classes[ty], adoptName, &ao);
                            if (placed && !adoptM)
                                unsupported(("allocator-aware `new(allocator: …)` needs an `adoptIn(raw, allocator)` on `"
                                             + ty + "`").c_str(), n->line);
                            else if (!adoptM) { unsupported(("`" + ty + "` implements HeapOwner but has no `adopt` method").c_str(), n->line); }
                            else {
                                std::string hp = "__heap" + std::to_string(_tempCounter++);
                                std::string ap;
                                if (placed) {   // materialize the allocator handle once, then allocate through it
                                    ap = "__alloc" + std::to_string(_tempCounter++);
                                    line(n->line); indent(depth);
                                    *_out << pa.second << " " << ap << " = " << pa.first << ";\n";
                                }
                                line(n->line); indent(depth);
                                if (placed)
                                    *_out << C << "* " << hp << " = (" << C << "*)unwrapPtr(" << pa.second << "__allocate(&" << ap << ", " << layoutOf(C) << "));\n";
                                else
                                    *_out << C << "* " << hp << " = (" << C << "*)kama_alloc(" << layoutOf(C) << ");\n";
                                indent(depth); *_out << "if (!" << hp << ") kama_panic(kama_string_lit(\"out of memory\", 13));\n";
                                if (newBuildsValue(C, oc))
                                    emitNewFactoryMove(C, hp, oc, n->line, depth);
                                // adopt the T* — the base subobject when widening (offset-0), else the ptr itself.
                                std::string adoptArg = hp;
                                if (upcastNew) {
                                    std::string bp = basePathTo(&_classes[C], &_classes[T]);
                                    if (!bp.empty()) bp.pop_back();
                                    adoptArg = "(" + T + "*)&(" + hp + "->" + bp + ")";
                                }
                                indent(depth); *_out << nm << " = " << adoptM->cName << "(" << adoptArg
                                                     << (ap.empty() ? "" : ", " + ap) << ");\n";
                            }
                        }
                    } else if (_classes.count(ty) && _classes[ty].isIntrinsicColl) {
                        // An intrinsic collection (`string`, `BindableFunctionPtr<Sig>`) declares its own
                        // storage — `new` is accepted and the declaration above already emitted it. Nothing
                        // further to construct; the branch exists so this does NOT fall to the `else` gate.
                    } else {
                        unsupported(("`new` allocates on the heap — wrap it in `Owned<" + octy
                                     + ">`/`Shared<" + octy + ">`, or drop `new` for a stack value "
                                     "(`" + ty + " v = " + octy + "(...)`)").c_str(), n->line);
                    }
                } else if (stackCtor) {
                    // STACK value, constructed in place (`Box b = Box(id: 5)`).
                    if (_classes[ty].isAbstractClass)
                        unsupported(("cannot instantiate abstract class '" + ty + "'").c_str(), n->line);
                    {
                        // A bare `Type(args)` has no ctor to call — it would SILENTLY drop the args and leave
                        // the value uninitialized. Reject and point at the named form. This fires for a type
                        // with NO ctor too: that case used to fall through to a bare `T v;` reading
                        // uninitialized stack, which is exactly what `slot` exists to make impossible.
                        std::string disp = (stackCtor->identifier && stackCtor->identifier->value)
                                         ? *stackCtor->identifier->value : ty;
                        rejectNamelessConstruction(_classes[ty], disp, /*viaNew=*/false, n->line);
                    }
                } else if (isSmartPtrClass(ty) && smartKind(ty) == CollKind::Weak
                           && isSmartPtrLValue(init) && exprClass(init) != ty) {
                    // Shared->Weak conversion (different C structs, same layout):
                    // field-copy + weak retain. The source Shared stays valid. A fat
                    // contract Weak copies {obj, vtbl}; a thin Weak copies {ptr}.
                    line(n->line); indent(depth);
                    std::string src = emitExpression(init);
                    if (isInterface(_classes[ty].collElemClass)) {
                        *_out << nm << ".obj = (" << src << ").obj; " << nm << ".vtbl = (" << src << ").vtbl; "
                             << nm << ".ctrl = (" << src << ").ctrl;\n";
                        // stateful-A iface Weak (M11d): carry the allocator so it frees the ctrl through the
                        // right A even after its Shared is gone.
                        std::string wa = _collections.count(ty) ? _collections[ty].allocType : "";
                        if (!wa.empty() && wa != "GlobalAllocator") {
                            indent(depth); *_out << nm << ".alloc = (" << src << ").alloc;\n";
                        }
                    }
                    else
                        *_out << nm << ".ptr = (" << src << ").ptr; " << nm << ".ctrl = (" << src << ").ctrl;\n";
                    indent(depth); *_out << "if (" << nm << ".ctrl) " << nm << ".ctrl->weak++;\n";
                } else if (isSmartPtrUpcast(ty, init)) {
                    // Cross-element upcast: widen a concrete-element `Shared`/`Owned` into this
                    // contract-element (intrinsic fat) handle. The pointee is shared/moved; `nm`
                    // was already zero-declared above.
                    line(n->line);
                    emitSmartPtrUpcast(nm, ty, init, handoff, depth, n->line);
                } else if (isSmartPtrBaseUpcast(ty, init)) {
                    // Base-class upcast: widen a derived-class handle into this base-class handle.
                    line(n->line);
                    emitSmartPtrBaseUpcast(nm, ty, init, handoff, depth, n->line);
                } else if (isSmartPtrHandoffMismatch(ty, init)) {
                    // Both sides own, but the widening isn't valid — a clear diagnostic instead of
                    // the misleading "collection hand-off" message below.
                    std::string k = declType->value ? *declType->value : "handle";
                    std::string e = (declType->genericArg && declType->genericArg->value)
                                        ? *declType->genericArg->value : "T";
                    unsupported(("cannot widen this handle into `" + k + "<" + e + ">` — an owning-handle "
                                 "upcast needs the same ownership kind and an `is a` element (a concrete that "
                                 "implements the contract `" + e + "`, or a derived of the base `" + e + "`)").c_str(),
                                n->line);
                } else if (isSmartPtrClass(ty) && !primWidenKey(init, _classes[ty].collElemClass).empty()) {
                    // `Owned<Hashable> h = 42;` — a PRIMITIVE boxed into an owning contract handle. The
                    // borrow form cannot serve this: its fat pointer borrows a block-scoped compound
                    // literal, so the escape check forbids storing or returning it. An owned box is the
                    // form that outlives its scope — a field, a collection element, a return.
                    line(n->line);
                    std::string pk = primWidenKey(init, _classes[ty].collElemClass);
                    std::string t = emitPrimBoxIntoContract(ty, pk, emitExpression(init), n->line);
                    flushHoisted(depth);
                    indent(depth); *_out << nm << " = " << t << ";\n";
                } else if (isSmartPtrClass(ty) && isInterface(_classes[ty].collElemClass)
                           && exprClass(init) == "kama_string"
                           && classDeclaresContract("kama_string", _classes[ty].collElemClass)) {
                    // `Owned<Show> o = give s;` — a `string` boxed into an owning contract handle: the same box,
                    // with the string MOVED (or deep-copied) into the heap cell; the vtbl's `__dtor` frees it.
                    // A named string needs the marker like any owning hand-off; a fresh one moves in bare.
                    line(n->line);
                    std::string v = emitExpression(init);
                    bool moveOut = false;
                    if (isNamedValue(init.get())) {
                        if (handoff == 0)
                            unsupported("a `string` hand-off must say `give` (move) or `copy` (deep)", n->line);
                        else if (handoff == 2) v = copyCall("kama_string", v);
                        else moveOut = true;
                    }
                    std::string t = emitPrimBoxIntoContract(ty, "kama_string", v, n->line);
                    if (moveOut) {
                        _hoisted.push_back(moveNullStmt("kama_string", v));
                        std::string mv = moveOnlySource(init, n->line); if (!mv.empty()) markMoved(mv);
                    }
                    flushHoisted(depth);
                    indent(depth); *_out << nm << " = " << t << ";\n";
                } else if (isBindableClass(ty)) {
                    // BindableFunctionPtr <- free function (promote) or another bindable (move).
                    line(n->line);
                    emitBindablePromote(nm, ty, init, depth);
                } else {
                    // Copy-initialize from another named value. The give/copy marker
                    // (or the type's default) decides move vs duplicate.
                    line(n->line);
                    bool ph = _hoistOK; _hoistOK = true;               // inline-ctor hoisting
                    std::string pvt = _variantTargetType; _variantTargetType = ty;   // `Optional<int32> o = Optional::Some(…)`
                    std::string pmt = _matchTargetCType; _matchTargetCType = ty;      // `string s = match(…)` / `List l = match(…)`
                    // A LOCAL IS NOT LIVE UNTIL ITS INITIALIZER COMPLETES — and a value-producing `match`
                    // is the one initializer that can leave without completing, because an arm may
                    // `return`. The declaration above emits `T x;` and the assignment lands only AFTER the
                    // lifted switch, so an arm's early return ran the full scope-drop list over a local
                    // that had never been assigned: `T__dtor(&x)` on uninitialized stack. It is the idiom
                    // every fallible read uses (`T x = match (give r) { … case Err: { return 251; } }`),
                    // latent only because an Err arm rarely fires in a passing test, and it presents as a
                    // crash inside a destructor — which sends the reader hunting in the callee.
                    //
                    // The machinery already existed: `slot` marks a hole `Moved` to mean "owns nothing
                    // right now", and scope cleanup skips a `Moved` local. A local mid-initializer is in
                    // exactly that state, so it is spelled exactly that way. (The comment three screens up
                    // says the RAII registration "assumes init-at-decl" — this is the case where that
                    // assumption is false.)
                    const bool lateInit = needsTargetType(init.get());
                    if (lateInit) _moveState[nm] = MoveState::Moved;
                    std::string iv = narrowViewValue(ty, init, emitExpression(init), n->line);   // `ConstView<T> cv = v;`
                    if (lateInit) _moveState[nm] = MoveState::NotMoved;   // the assignment below makes it live
                    _matchTargetCType = pmt;
                    _variantTargetType = pvt;
                    _hoistOK = ph;
                    flushHoisted(depth);
                    indent(depth);
                    *_out << nm << " = " << iv << ";\n";
                    if (isSmartPtrClass(ty) && isSmartPtrLValue(init)) {
                        CollKind k = smartKind(ty);
                        // Default: Owned -> give(move), Shared/Weak -> copy(retain). A marker overrides.
                        bool doGive = (handoff == 1) || (handoff == 0 && k == CollKind::Owned);
                        if (handoff == 2 && k == CollKind::Owned)
                            unsupported("an `Owned` is unique — it can't be `copy`'d; use `give` to move it", n->line);
                        indent(depth);
                        if (doGive) *_out << smartPtrInvalidate(emitExpression(init), k, isInterface(_classes[ty].collElemClass)) << "\n";
                        else        *_out << nm << ".ctrl->" << (k == CollKind::Weak ? "weak" : "strong") << "++;\n";
                    } else if (_classes.count(ty) && _classes[ty].isIntrinsicColl
                               && !isFixedColl(ty) && !isValueVectorKind(_classes[ty].collKind)
                               && isNamedValue(init.get())) {
                        // a collection move/deep-copy isn't a plain `=` — require a marker. (A
                        // `Fixed` is a value: the plain `=` above already copied it — no marker. A
                        // `Simd` likewise, and even more plainly: it is a `vector_size` typedef over a
                        // primitive, so `=` is a register move and there is nothing that could be
                        // aliased, moved from, or deep-copied.)
                        if (handoff == 0)
                            unsupported(("a collection hand-off must say `give` (move) or `copy` (deep) — write "
                                         "`" + ty + " v = give …`").c_str(), n->line);
                        else if (handoff == 2) {
                            // `copy` = a real deep copy (fresh buffer), element-wise. Valid iff
                            // each element is copyable — bitwise-copyable (owns nothing), OR a resource that
                            // opted into `Copyable` (`__copy` calls the element's `copy()`). A
                            // resource element WITHOUT the contract is rejected. Overwrites the blit above.
                            auto ci = _collections.find(ty);
                            if (ci != _collections.end() && ci->second.elemDestructible && !ci->second.elemCopyable)
                                unsupported(("`copy` of a `" + ty + "` needs copyable elements — its elements own "
                                             "resources but aren't `Copyable` (add a `copy` method to the element, "
                                             "or use `give` to move)").c_str(), n->line);
                            else { indent(depth); *_out << nm << " = " << copyCall(ty, emitExpression(init)) << ";\n"; }
                        }
                        // give: the plain `=` already transferred the struct; null the source's buffer.
                        else { indent(depth); *_out << moveNullStmt(ty, emitExpression(init)) << "\n"; }
                    } else if (isMoveOnlyValue(ty) && isNamedValue(init.get())) {
                        // A destructible `resource` value. Movable is universal: `give` MOVES (relocate —
                        // the `=` blit already transferred the bytes; move-tracking suppresses the source
                        // dtor). Copyable is opt-in: `copy` duplicates via copy() (overwriting the blit;
                        // source stays valid). A BARE hand-off follows the type's declared `bare:` default
                        // (give→move, copy→copy()/retain). A non-Copyable resource has no copy() → move.
                        bool cpy = isCopyable(ty);
                        bool doCopy;
                        if (handoff == 2) {                              // explicit `copy`
                            if (!cpy) unsupported(("`" + ty + "` has no `copy` method — add `implements "
                                                   "Copyable(bare: …)`, or use `give` to move it").c_str(), n->line);
                            doCopy = cpy;
                        } else if (handoff == 1) doCopy = false;         // explicit `give` = move (always allowed)
                        else doCopy = cpy && _classes[ty].bareDefault == COPY;   // bare — the declared default
                        if (doCopy) { indent(depth); *_out << nm << " = " << copyCall(ty, emitExpression(init)) << ";\n"; }
                        else { std::string mv = moveOnlySource(init, n->line); if (!mv.empty()) markMoved(mv); }
                    }
                    // A value/primitive: the plain `=` above IS the hand-off — `copy` and `give` are both
                    // just that copy (a value's "move" is a copy; the source stays valid, so no marker error).
                }
            };
            if (lvd && lvd->variables)
                for (auto& d : *lvd->variables) { if (d) emitDeclarator(d); }
            else if (cvd && cvd->variables)
                for (auto& d : *cvd->variables) { if (d) emitDeclarator(d); }
            return;
        }
    }

    if (auto* ret = dynamic_cast<ReturnNode*>(n)) {
        line(n->line);
        // Unwrap a give/copy marker for the place-return check below; the value path passes the original
        // `ret->expression` (marker and all) to emitOwnedValueInto, which re-unwraps + applies the matrix.
        SharedExpression retExpr = ret->expression;
        if (retExpr)
            if (auto* h = dynamic_cast<HandoffNode*>(retExpr.get())) retExpr = h->value;
        rejectConstPtrWiden(_currentReturnCType, retExpr, "this `return`", n->line);
        // A `ref T operator[]` returns a PLACE: address the lvalue directly (`return &(place)`) — no
        // by-value return-temp (you can't copy a place). The place borrows `self`, which outlives the
        // call, so it's valid for the caller's enclosing statement (used transiently, never stored).
        if (_returnIsPlace) {
            // A returned place must borrow something that OUTLIVES the call — `this` (the caller owns
            // the receiver) or a `ref` parameter (a borrow the caller holds). A place rooted at a
            // LOCAL would dangle the moment the callee returns. Targeted rule, no lifetimes.
            //
            // Chained ref-return: when the place is itself a place-returning method call
            // (`recv.getRef(...)`), its result borrows the RECEIVER — exactly as `operator[]` /`.`/`[]`
            // already do (the place "borrows self, which outlives the call", above). The callee is itself
            // subject to THIS same check, so it can only hand back a borrow of its own `this` (= recv) or a
            // ref-param — never one of its locals. So trace the root through the call to the receiver: a
            // `this`-rooted receiver is accepted, a local receiver is still (correctly) rejected. This is
            // the structural root-tracing stepped one level through the call — no lifetime analysis added.
            std::string root;
            if (retExpr) {
                if (auto* inv = dynamic_cast<InvocationNode*>(retExpr.get())) {
                    if (inv->expression)
                        if (auto* ma = dynamic_cast<MemberAccessNode*>(inv->expression.get()))
                            if (ma->expression) root = rootBinding(ma->expression);   // receiver's root
                }
                if (root.empty()) root = rootBinding(retExpr);   // non-call place (field/element/this)
            }
            if (root != "this" && !_refParams.count(root))
                unsupported("a `ref T` result must borrow `this` or a `ref` parameter — returning a "
                            "place into a local would dangle", n->line);
            // The mirror of checkConstPlaceReturn, one step later: a WRITABLE place may not be minted from
            // a read-only one. `fn ref T f(const ref X x) { return x.n; }` would hand the caller a
            // writable alias into a const parameter, and `return this.m.getRef(k)` one into a `const ref`
            // place — the C backstop (`T const*` → `T*`) would catch the second; the first lowers to a
            // plain pointer and would not. `const ref T` is the return type both want.
            if (!_returnIsConstPlace && retExpr && (rootIsConst(root) || chainThroughConstPlace(retExpr)))
                unsupported("a `ref T` result is a writable place, and this one is read-only — it roots in a "
                            "`const` binding or passes through a `const ref` place. Return `const ref T` "
                            "instead, or take the mutable form (`…Mut`) where the place was made", n->line);
            // Every place is an lvalue we address with `&` — a structural one (`this.f[i]`) directly, and a
            // place-returning CALL (`return this.at(i: 0)`) through the `(*call)` placeWrap gives every
            // place call, which `&` folds back to the callee's pointer. This used to special-case the call
            // as "already a pointer, return it directly" and emit `return (*call)`: a chained place return
            // through a DIRECT method call never compiled (the stdlib's one chain, `SortedMap.getRef`, goes
            // through an `Owned` auto-deref and took another path), and the first `const ref` fixture found it.
            bool ph = _hoistOK; _hoistOK = true;
            std::string p = retExpr ? emitPlace(retExpr) : std::string("0");
            _hoistOK = ph;
            flushHoisted(depth);
            emitUnwindAll(depth);
            indent(depth);
            *_out << "return &(" << p << ");\n";
            return;
        }
        // View-return escape check (B4): a `type view` return borrows its buffer, so allow it only when
        // the returned view roots at `this` or a `ref`/by-value view parameter — the borrow then
        // outlives the call. The by-value sibling of the `ref T` place-return rule above; structural
        // root-tracing, no lifetime analysis (north star 3e). A view over a LOCAL is (correctly) rejected.
        // A named `ctor` factory RETURNS the view it builds (borrowing from its by-value `UnsafePtr`/view params,
        // which the caller owns); that provenance is validated structurally by checkViewCtorEscape instead,
        // so skip the fn-shaped check here for a ctor body.
        if (retExpr && !_inNamedCtorBody && isViewCType(_currentReturnCType)) {
            std::string root = viewReturnRoot(retExpr);
            if (!isSafeViewRoot(root))
                unsupported("a view borrows its buffer, so it can only be returned when it borrows `this` "
                            "or a `ref` parameter — returning a view over a local would dangle; return an "
                            "owning `DynamicArray` to hand back data", n->line);
            // fall through to the normal by-value return emission below (a view is a value, not a place)
        }
        // Capture the return value BEFORE running any destructors (it may
        // reference locals about to be destroyed), then unwind, then return.
        if (retExpr && _currentReturnCType != "void") {
            // Capture the return value into a temp BEFORE any destructors run (it may reference locals
            // about to be destroyed), handling an owned hand-off (give/copy, an inline ctor/`new`, or a
            // bare generic ctor) uniformly with a value-producing `match` arm, then unwind, then return.
            std::string tmp = "__ret_" + std::to_string(_tempCounter++);
            indent(depth); *_out << _currentReturnCType << " " << tmp << ";\n";
            emitOwnedValueInto(tmp, _currentReturnCType, ret->expression, n->line, depth, "a return value");
            emitUnwindAll(depth);
            indent(depth); *_out << "return " << tmp << ";\n";
        } else {
            if (retExpr) { indent(depth); *_out << emitExpression(retExpr) << ";\n"; }
            emitUnwindAll(depth);
            indent(depth); *_out << "return;\n";
        }
        return;
    }

    if (auto* f = dynamic_cast<IfNode*>(n)) {
        line(n->line);
        // A value-producing construct in the condition (an inline ctor / `match`) hoists a temp; a raw
        // condition has no statement slot, so wrap the whole `if` in a block and flush the temps first.
        // An owned-string temp hoisted here (`if (s.trim() == "x")`) is registered destructible in the
        // current scope but *declared* in this wrapper block, so we dtor+unregister it before the wrapper
        // closes (below) rather than at the outer scope — else its drop would name an out-of-scope temp.
        size_t preLoc = _scopes.empty() ? 0 : _scopes.back().locals.size();
        std::string cond = emitCondition(f->booleanExpression);
        bool hoist = !_hoisted.empty();
        int bd = depth;
        if (hoist) { indent(depth); *_out << "{\n"; flushHoisted(depth + 1); bd = depth + 1; }
        indent(bd);
        *_out << "if (" << cond << ") ";
        // walk each branch from the SAME pre-if move-state, then merge at the join.
        // A branch that diverges (ends in return/break/continue) doesn't reach the join.
        auto before = _moveState;
        emitBody(f->ifStatement, bd, /*loopBoundary=*/false);
        auto thenState = _moveState;
        bool thenDiv = bodyDiverges(f->ifStatement);
        _moveState = before;
        bool elseDiv = false;
        if (f->elseStatement) {
            *_out << " else ";
            emitBody(f->elseStatement, bd, false);
            elseDiv = bodyDiverges(f->elseStatement);
        }
        auto elseState = _moveState;   // no else -> == before (the fall-through arm)
        for (auto& kv : before) {
            MoveState t = thenState.count(kv.first) ? thenState[kv.first] : kv.second;
            MoveState e = elseState.count(kv.first) ? elseState[kv.first] : kv.second;
            MoveState merged;
            if (thenDiv && elseDiv) merged = kv.second;   // join unreachable
            else if (thenDiv)       merged = e;
            else if (elseDiv)       merged = t;
            else if (t == e)        merged = t;
            else                    merged = MoveState::MaybeMoved;   // moved on one arm only
            _moveState[kv.first] = merged;
        }
        *_out << "\n";
        if (hoist) {
            // dtor + unregister the destructible temps hoisted for the condition (declared in this wrapper
            // block). A diverging arm already dropped them via emitUnwindAll, so on that path this line is
            // simply not reached — each temp is dropped exactly once.
            dropCondTemps(preLoc, bd);
            indent(depth); *_out << "}\n";
        }
        return;
    }

    if (auto* w = dynamic_cast<WhileNode*>(n)) {
        line(n->line);
        size_t preLoc = _scopes.empty() ? 0 : _scopes.back().locals.size();
        std::string cond = emitCondition(w->booleanExpression);
        if (_hoisted.empty()) {                                   // fast path — unchanged
            indent(depth);
            *_out << "while (" << cond << ") ";
            emitBody(w->whileStatement, depth, /*loopBoundary=*/true);
            *_out << "\n";
        } else {                                                  // loop-and-a-half: recompute cond each pass
            bool drop = !_scopes.empty() && _scopes.back().locals.size() > preLoc;
            indent(depth); *_out << "while (1) {\n";
            flushHoisted(depth + 1);                              // condition temps — re-run each iteration
            if (drop) {                                           // owned condition temp: eval, drop, then break
                std::string lc = "__loopcond" + std::to_string(_tempCounter++);
                indent(depth + 1); *_out << "bool " << lc << " = (" << cond << ");\n";
                dropCondTemps(preLoc, depth + 1);                // drop before the body — cond doesn't bind into it
                indent(depth + 1); *_out << "if (!" << lc << ") break;\n";
            } else {
                indent(depth + 1); *_out << "if (!(" << cond << ")) break;\n";
            }
            emitBody(w->whileStatement, depth + 1, /*loopBoundary=*/true);
            *_out << "\n";
            indent(depth); *_out << "}\n";
        }
        return;
    }

    if (auto* d = dynamic_cast<DoWhileNode*>(n)) {
        line(n->line); indent(depth);
        // `do`/`while` condition sits at the bottom and its `continue` must skip TO it, which a naive
        // while(1) rewrite breaks — so a hoisting construct here stays a clean error (bind to a local).
        *_out << "do ";
        emitBody(d->doWhileStatement, depth, /*loopBoundary=*/true);
        *_out << " while (" << emitExpression(d->booleanExpression) << ");\n";
        return;
    }

    if (auto* f = dynamic_cast<ForNode*>(n)) {
        line(n->line);
        // The counter the init declares lives exactly as long as the loop — in C, and in kama's binding
        // tables through this wrapper Scope, which owns the init's bindings and nothing else: it emits no
        // block and is NOT a loop boundary (the body scope is; break/continue unwind to that one). Any
        // init/condition temp recorded into it is handed back to the enclosing scope below, so dtor
        // emission is exactly what it was when the enclosing scope held them directly. Without it the
        // counter stayed typed to the end of the enclosing block — `for (int32 i …) {}` followed by
        // `foreach (E i in xs)` handed the second `i` the first one's `int32_t`.
        _scopes.push_back(Scope());
        std::string init = emitForClause(f->initializerStatements);
        size_t preLoc = _scopes.empty() ? 0 : _scopes.back().locals.size();
        std::string cond = emitCondition(f->booleanExpression);
        std::string iter = emitForClause(f->iteratorStatements);
        if (_hoisted.empty()) {                                   // fast path — unchanged
            indent(depth);
            *_out << "for (" << init << "; " << cond << "; " << iter << ") ";
            emitBody(f->body, depth, /*loopBoundary=*/true);
            *_out << "\n";
        } else {                                                  // loop-and-a-half; iter stays in the C header
            bool drop = !_scopes.empty() && _scopes.back().locals.size() > preLoc;
            indent(depth); *_out << "for (" << init << "; ; " << iter << ") {\n";
            flushHoisted(depth + 1);                              // condition temps — re-run each iteration
            if (drop) {                                           // owned condition temp: eval, drop, then break
                std::string lc = "__loopcond" + std::to_string(_tempCounter++);
                indent(depth + 1); *_out << "bool " << lc << " = (" << cond << ");\n";
                dropCondTemps(preLoc, depth + 1);                // drop before the body — cond doesn't bind into it
                indent(depth + 1); *_out << "if (!" << lc << ") break;\n";
            } else {
                indent(depth + 1); *_out << "if (!(" << cond << ")) break;\n";
            }
            emitBody(f->body, depth + 1, /*loopBoundary=*/true);
            *_out << "\n";
            indent(depth); *_out << "}\n";
        }
        {   // hand any temps the wrapper collected back to the enclosing scope, then retire the counter
            Scope& wrap = _scopes.back();
            if (_scopes.size() >= 2 && !wrap.locals.empty()) {
                auto& outer = _scopes[_scopes.size() - 2].locals;
                outer.insert(outer.end(), wrap.locals.begin(), wrap.locals.end());
                wrap.locals.clear();
            }
        }
        popScope();
        return;
    }

    if (dynamic_cast<BreakNode*>(n)) {
        line(n->line);
        emitUnwindToLoop(depth);   // dtors must run before the break keyword
        indent(depth); *_out << "break;\n";
        return;
    }
    if (dynamic_cast<ContinueNode*>(n)) {
        line(n->line);
        emitUnwindToLoop(depth);
        indent(depth); *_out << "continue;\n";
        return;
    }

    if (auto* fe = dynamic_cast<ForEachNode*>(n)) {
        // Ahead of the iterator/collection split below, so BOTH shapes are covered by the one check.
        if (fe->name && fe->name->value) {
            checkConstParamBinder(*fe->name->value, "`foreach` variable", fe->name->line);
            checkBinderShadow(*fe->name->value, "`foreach` variable", fe->name->line);
        }
        line(n->line); indent(depth);
        std::string itCls = exprClass(fe->expression);
        // A user type (not a built-in collection) iterates via the iterator protocol (structural).
        if (!itCls.empty() && _classes.count(itCls) && !_classes[itCls].isIntrinsicColl) {
            emitForeachIterator(fe, itCls, depth); return;
        }
        if (itCls.empty() || !_classes.count(itCls) || !_classes[itCls].isIntrinsicColl) {
            unsupported("foreach over a non-collection (a user type needs `iterator()`/`next()` or `iterMut()`)", n->line); *_out << "\n"; return;
        }
        const std::string& coll = _classes[itCls].name;
        std::string elemTy   = cType(fe->type);
        std::string elemClass = _classes[itCls].collElemClass;   // "" if primitive element

        // The DECLARED element type must be the collection's ACTUAL element type. Without this the
        // binding's type was taken on trust and the element assigned straight into it, so
        // `foreach (char c in s)` — which SPEC calls a type error, because the byte/codepoint
        // distinction is the whole point of `string` being UTF-8 bytes — compiled and yielded one
        // bogus `char` PER BYTE: iterating "é" gave codepoints 195 and 169 (the raw C3 A9) instead of
        // 233. Mojibake from a type system that had promised `char` "can't silently mix with ints".
        // The hole was general, not a string quirk: `foreach (bool v in someInt32Array)` was accepted
        // just as happily. Both `elemCType` and `elemTy` come from cType(), so this compares like with
        // like; an empty elemCType means a shape that does not record one, and is left alone.
        auto collIt = _collections.find(coll);
        if (collIt != _collections.end() && !collIt->second.elemCType.empty()
            && elemTy != collIt->second.elemCType) {
            const std::string& want = collIt->second.elemCType;
            // The string case gets the spelling that works, because it is the one people reach for and
            // the two right answers are not guessable from the error alone.
            std::string hint = (_classes[itCls].collKind == CollKind::String && want == "uint8_t")
                ? " — a `string` is UTF-8 BYTES: use `foreach (uint8 b in s)` for bytes, or "
                  "`foreach (char c in s.chars())` for codepoints"
                : "";
            std::string msg = "foreach element type does not match the collection's (binding is `"
                            + elemTy + "`, elements are `" + want + "`)" + hint;
            unsupported(msg.c_str(), n->line);
            *_out << "\n";
            return;
        }
        std::string nm = (fe->name && fe->name->value) ? *fe->name->value : "__x";
        int id = _tempCounter++;
        std::string fp = "__fe" + std::to_string(id);
        std::string ix = "__i"  + std::to_string(id);
        std::string recvExpr = emitExpression(fe->expression);

        // Is the subject a `comptime` constant? Those emit as C `static const`, so taking a plain `T*` to
        // one discards the qualifier — a real warning on every `foreach` over a baked lookup table, and
        // `-Werror` away from breaking the build. The loop only READS on the by-value path, so the honest
        // fix is a const receiver pointer (and const-correct `__length`/`__get`), not a cast.
        bool constRecv = false;
        if (auto* rid = dynamic_cast<IdentifierNode*>(fe->expression.get()))
            if (rid->value) constRecv = _constStatics.count(resolveUserNameImpl(*rid->value, rid->qualifier)) != 0
                                     || _constStatics.count(qualify(*rid->value)) != 0;
        // `foreach (ref T e in K)` would hand out a mutable `T*` into a constant. Reject it here rather
        // than emitting code the C compiler has to catch: the `ref` binding exists to write back, and
        // there is nothing writable to bind to.
        if (constRecv && fe->isRef) {
            unsupported("`foreach (ref …)` over a `comptime` constant — a constant has no writable element "
                        "to borrow (drop the `ref` to iterate by value)", n->line);
            *_out << "\n";
            return;
        }
        std::string cq = constRecv ? "const " : "";

        // Outer wrapper holds the receiver pointer (evaluate the receiver once).
        *_out << "{\n";
        indent(depth + 1); *_out << cq << coll << "* " << fp << " = &(" << recvExpr << ");\n";
        indent(depth + 1);
        *_out << "for (size_t " << ix << " = 0; " << ix << " < " << coll << "__length(" << fp
             << "); ++" << ix << ") {\n";

        // Loop-body scope (a loop boundary so break/continue unwind correctly).
        Scope sc; sc.isLoopBoundary = true;
        _scopes.push_back(sc);
        registerBinding(fe->name.get(), SymKind::Local);   // LSP index (the loop variable)
        // The loop scope owns the binding: the type entries below (and `_refParams` for the `ref` form)
        // must not outlive the loop, and popScope puts back whatever `nm` named outside it.
        noteScopedBinding(nm);
        hideShadowedLocal(nm, fe->isRef);
        _localTypes[nm] = elemClass;   // element binding's class (for x.method() resolution)
        if (fe->type) _localTypeNodes[nm] = fe->type;   // element kama type node (char vs uint32 for interpolation)

        // `foreach (ref T e …)` binds each element by PLACE (a bounds-checked `T*` via `__at`), so
        // mutation persists; `e` joins `_refParams` so reads/writes in the body deref it (`(*e)`),
        // exactly like a `ref` parameter. Plain `foreach` binds a borrowed COPY (`__get`). Neither
        // is recorded destructible (the collection owns the element).
        indent(depth + 2);
        if (fe->isRef) {
            *_out << elemTy << "* " << nm << " = " << coll << "__at(" << fp << ", " << ix << ");\n";
            _refParams.insert(nm);
        } else {
            *_out << elemTy << " " << nm << " = " << coll << "__get(" << fp << ", " << ix << ");\n";
        }

        SharedStatement last;
        if (auto* b = dynamic_cast<BlockNode*>(fe->body.get())) {
            if (b->statements) for (auto& st : *b->statements) { emitStatement(st, depth + 2); last = st; }
        } else if (fe->body) {
            emitStatement(fe->body, depth + 2); last = fe->body;
        }
        if (!(last && stmtIsJump(last))) emitScopeCleanup(_scopes.back(), depth + 2);
        popScope();   // retires the binding — see noteScopedBinding above

        indent(depth + 1); *_out << "}\n";   // close for
        indent(depth);     *_out << "}\n";   // close wrapper
        return;
    }

    // Smart-pointer assignment `b = a;` — release b's current pointee first (no
    // leak), copy, then either invalidate the source (give: move) or retain
    // (copy: refcount++). The null/retain is a statement, so it can't live in
    // an expression. a give/copy marker on the RHS overrides the default,
    // uniformly with init / argument / return.
    if (auto* as = dynamic_cast<AssignmentNode*>(n)) {
#if KAMA_INHERITANCE
        // A base install that reached here is a MISPLACED one — the well-formed one is lifted into the
        // ctor prologue and never becomes a statement. `checkBaseInstall` has already said what is wrong
        // with it, so emit nothing: otherwise `this.base` would also trip the read guard and the fixture
        // pinning the placement rule would report two errors, one of them beside the point.
        if (isThisBase(as->unaryExpression)) return;
#endif
        // The kind rule in ASSIGNMENT position — the SIXTH hand-off, and the one the spine missed. It
        // wired the five that hand a value into a *declared* destination (initializer, return, `match`
        // arm, argument, variant payload) and left the plainest one open: `int32 x = 0; x = "oops";`
        // passed `kama check` clean and failed at clang, which is the exact defect this whole campaign
        // exists to close, one statement later than the fixture that pinned it.
        //
        // `EQ` only. A compound operator (`+=`, `<<=`) is an arithmetic rule, not a hand-off, and
        // `string += string` is a shipped concatenation. `typeOfExpr` on the LHS place answers through
        // the same map the ownership branch below already trusts.
        if (as->token == EQ) {
            SharedExpression rhs = as->expression;
            if (auto* h = dynamic_cast<HandoffNode*>(rhs.get())) rhs = h->value;   // judge on the value
            rejectValueKindMismatch(typeOfExpr(as->unaryExpression), rhs, "an assignment", n->line);
        }
        // Writing to a slot — whole (`x = …`) or to one of its fields (`x.f = …`, which is how a factory
        // builds a value) — FILLS the hole: it is a live value from here on, so its destructor comes back
        // and ordinary move tracking takes over. Done once here rather than in each of the assignment
        // sub-paths below, and BEFORE any of them emit, because emitting the target reads its move state.
        if (!_slotLocals.empty()) {
            std::string sn;
            SharedExpression lhs = as->unaryExpression;
            if (auto* id = dynamic_cast<IdentifierNode*>(lhs.get())) {
                if (id->value && (!id->qualifier || id->qualifier->empty())) sn = *id->value;
            } else if (auto* ma = dynamic_cast<MemberAccessNode*>(lhs.get())) {
                if (auto* bid = dynamic_cast<IdentifierNode*>(ma->expression.get()))
                    if (bid->value && (!bid->qualifier || bid->qualifier->empty())) sn = *bid->value;
            }
            if (!sn.empty() && _slotLocals.count(sn)) {
                _slotLocals.erase(sn);                        // no longer a hole — normal rules apply
                _moveState[sn] = MoveState::NotMoved;
            }
        }
        // Base-class upcast reseat: `b = [give] d` where `b: Shared<Base>` and `d: Shared<Derived>`
        // (both thin library handles — the LHS isn't an intrinsic smart ptr, so this precedes the
        // smart-ptr path below). Release the handle's old pointee, then widen the derived handle in.
        if (as->token == EQ) {
            SharedExpression rhs0 = as->expression;
            int handoff0 = 0;   // 0 none, 1 give, 2 copy
            if (auto* h = dynamic_cast<HandoffNode*>(rhs0.get())) { handoff0 = h->isGive ? 1 : 2; rhs0 = h->value; }
            std::string lty0 = exprClass(as->unaryExpression);
            if (isSmartPtrBaseUpcast(lty0, rhs0)) {
                checkConstWrite(as->unaryExpression, n->line);
                std::string b = emitExpression(as->unaryExpression);
                line(n->line);
                indent(depth); *_out << lty0 << "__dtor(&" << b << ");\n";
                emitSmartPtrBaseUpcast(b, lty0, rhs0, handoff0, depth, n->line);
                return;
            }
        }
        // Bare in-place ctor assigned to a class-typed lvalue (`this.m = Map()`, `x = Point(v: 1)`): a bare
        // stack ctor has no rvalue form — it constructs into a place — so build it DIRECTLY into the lvalue,
        // exactly like the local-init `stackCtor` path, after releasing the old value. Fires only for a fresh
        // ctor whose callee names the lvalue's (possibly generic) class; a `give`/`copy`-marked or named RHS
        // never matches (not an InvocationNode), so the ownership paths below are untouched.
        if (as->token == EQ) {
            std::string lty = exprClass(as->unaryExpression);
            if (auto* iv = dynamic_cast<InvocationNode*>(as->expression.get()))
                if (iv->identifier && iv->identifier->value && isClass(lty)
                    && !isSmartPtrClass(lty)) {
                    std::string rn = resolveUserName(*iv->identifier->value, iv->identifier->qualifier);
                    auto g = _genericTypeInstOf.find(lty);
                    if (rn == lty || (g != _genericTypeInstOf.end() && g->second == rn)) {
                        checkConstWrite(as->unaryExpression, n->line);
                        // Nameless reassignment (`b = Box(id: 5)`) — no ctor to bind. Reject with the
                        // context-aware advice; an exempt type (intrinsic collection) falls through to the
                        // ordinary assignment path below rather than being silently dropped.
                        if (rejectNamelessConstruction(_classes[lty], *iv->identifier->value,
                                                       /*viaNew=*/false, n->line))
                            return;
                    }
                }
        }
        // Owned value into an `operator[]` PLACE: `a[i] = [give/copy] <owned>` where the element OWNS
        // something (string/collection/resource/smart-ptr). Release the old element, then move/copy the new
        // one THROUGH the place — an `ElementAccessNode` LHS isn't a named lvalue, so the branches below miss
        // it, and the RHS `give`/`copy` marker would otherwise hit the "bare sub-expression" reject. A
        // primitive element keeps the plain store path; a raw `UnsafePtr<T>` slot is handled just below.
        //
        // This used to read `if (as->token == EQ && !_inUnsafe)`, to keep a RAW slot store out of the
        // collection-release path. `_inUnsafe` was always the wrong discriminator for that — the raw path
        // below tests the actual question, `ptrElemType`/`ptrLocalElemType`, i.e. "is the LHS a raw pointer
        // element" — and it became actively wrong once `unsafe` grew from a BLOCK to the whole FUNCTION:
        // an `unsafe fn` doing an ordinary `xs[0] = give s` on a COLLECTION skipped the release entirely,
        // and the `give` then fell through to the generic "bare sub-expression" reject. Probed. The two
        // paths are disjoint by their own tests, so the guard was redundant as well as harmful.
        if (as->token == EQ) {
            if (auto* ea = dynamic_cast<ElementAccessNode*>(as->unaryExpression.get())) {
                std::string dcoll, drecv, didx, et;
                if (collectionElemAccess(ea, dcoll, drecv, didx) && _collections.count(dcoll))
                    et = _collections[dcoll].elemClass;            // "" for a primitive element
                else if (indexesUserOp(ea))
                    et = exprClass(as->unaryExpression);            // user `ref T operator[]` element
                if (!et.empty() && _classes.count(et) && _classes[et].destructible) {
                    SharedExpression rhs = as->expression;
                    int handoff = 0;
                    if (auto* h = dynamic_cast<HandoffNode*>(rhs.get())) { handoff = h->isGive ? 1 : 2; rhs = h->value; }
                    checkConstWrite(as->unaryExpression, n->line);
                    bool named  = isNamedValue(rhs.get());
                    bool isColl = _classes[et].isIntrinsicColl && !isSmartPtrClass(et);   // List/Array/string element
                    bool copyable = isColl || isCopyable(et);
                    bool doCopy;
                    if (handoff == 2) {
                        if (!copyable) unsupported(("`copy` of a `" + et + "` element needs a `Copyable` element "
                                                    "— use `give` to move it").c_str(), n->line);
                        doCopy = true;
                    } else if (handoff == 1) {
                        doCopy = false;                                                 // give = move
                    } else {
                        // bare: a NAMED owning source needs a marker; a FRESH owned rvalue (`"…"`, `List()`,
                        // a call result) moves in with no marker.
                        if (named) unsupported("an owned element hand-off must say `give` (move) or `copy` "
                                               "(deep) — write `a[i] = give …` or `a[i] = copy …`", n->line);
                        doCopy = false;
                    }
                    // Evaluate the RHS into a temp FIRST (it may read the old `a[i]`, e.g. `a[i] = a[i].concat`),
                    // then take the place ONCE (a `__at`/`operator[]` call — bounds-checked), release the old
                    // element, and move/copy the new one in. An inline ctor/`new` RHS (`a[i] = Tag(…)`)
                    // materializes into a hoisted temp from the element type.
                    bool ph = _hoistOK; _hoistOK = true;
                    std::string src = tryHoistInlineCtor(rhs, et, n->line);
                    if (src.empty()) src = tryHoistInlineValue(rhs, et, n->line);
                    if (src.empty()) src = emitExpression(rhs);
                    _hoistOK = ph;
                    std::string tv = "__elv" + std::to_string(_tempCounter++);
                    std::string sp = "__esl" + std::to_string(_tempCounter++);
                    line(n->line);
                    flushHoisted(depth);
                    indent(depth); *_out << et << " " << tv << " = "
                                         << (doCopy ? copyCall(et, src) : src) << ";\n";
                    std::string place = emitPlace(as->unaryExpression);
                    indent(depth); *_out << et << "* " << sp << " = &(" << place << ");\n";
                    indent(depth); *_out << et << "__dtor(" << sp << ");\n";           // release the old element
                    indent(depth); *_out << "*" << sp << " = " << tv << ";\n";         // move/copy the new one in
                    if (!doCopy && named) {   // consume the moved source (a copy leaves it valid; a fresh rvalue has none)
                        if (isColl) { indent(depth); *_out << moveNullStmt(et, src) << "\n"; }
                        else { std::string mv = moveOnlySource(rhs, n->line); if (!mv.empty()) markMoved(mv); }
                    }
                    return;
                }
            }
        }
        // A RAW pointer-slot store `ptr[i] = give x` / `ptr[i] = x` in unsafe manual-memory code: the
        // exprClass of an `UnsafePtr<T>` index is unknown (not a collection / user `operator[]`), so it's a raw
        // C store. Blit the value in, DON'T release the (uninitialized) old slot, and consume a moved
        // resource source (mark it moved so its scope dtor is skipped). This is how a library container
        // relocates an element into its buffer. Only intercepted for an owned RHS (marker or resource) —
        // a plain `ptr[i] = value` or a value-producing RHS keeps the generic path below.
        // A bare-LOCAL `UnsafePtr<T>` slot (`buf[i]`, not `this.field[i]`) is the UNTRACKED raw-relocate escape
        // hatch collections rely on (`nd[i] = od[j]`), so there an UNMARKED store stays a plain C store —
        // only an explicit `give`/`copy` is a tracked move. A FIELD slot keeps the implicit-owned guard.
        std::string pfield = ptrElemType(as->unaryExpression);                              // `this.data[i]` FIELD slot
        std::string plocal = pfield.empty() ? ptrLocalElemType(as->unaryExpression) : "";   // bare-LOCAL `buf[i]` slot
        if (as->token == EQ && (!pfield.empty() || !plocal.empty())) {
            SharedExpression rhs = as->expression;
            bool give = false, marked = false;
            if (auto* h = dynamic_cast<HandoffNode*>(rhs.get())) { give = h->isGive; rhs = h->value; marked = true; }
            bool tgtField = !pfield.empty();
            std::string rc = exprClass(rhs);
            // A FIELD slot keeps the implicit-owned guard (an unmarked resource/smart RHS is a move); a
            // bare-LOCAL slot moves ONLY on an explicit `give`/`copy` — an unmarked local store stays the
            // untracked raw-relocate (`nd[i] = od[j]`) and falls through to the generic C store below.
            bool ownedRhs = marked || (tgtField && !rc.empty() && (isMoveOnlyValue(rc) || isSmartPtrClass(rc)));
            if (ownedRhs) {
                std::string b = emitExpression(as->unaryExpression), src = emitExpression(rhs);
                line(n->line);
                // `copy` of an owning collection/`string` into the raw slot deep-copies (`__copy`), so the
                // slot and the source own separate buffers (the source survives). Otherwise blit.
                if (marked && !give && ownsByValue(rc) && !isMoveOnlyValue(rc)) {
                    indent(depth); *_out << b << " = " << copyCall(rc, src) << ";\n";
                    return;
                }
                indent(depth); *_out << b << " = " << src << ";\n";
                if (give || !marked) {
                    // consume the moved source so it isn't dropped again: an IFACE smart pointer is nulled
                    // at runtime (its callee-drop then no-ops); a resource OR collection/`string` is
                    // move-tracked (its scope-drop is skipped — the raw slot now owns the buffer).
                    if (isSmartPtrClass(rc)) { indent(depth); *_out << smartPtrInvalidate(src, smartKind(rc), isInterface(_classes[rc].collElemClass)) << "\n"; }
                    else if (ownsByValue(rc)) { std::string mv = moveOnlySource(rhs, n->line); if (!mv.empty()) markMoved(mv); }
                }
                return;
            }
        }
        if (as->token == EQ && isSmartPtrExpr(as->unaryExpression)) {
            checkConstWrite(as->unaryExpression, n->line);   // no reseating a const smart ptr
            std::string b   = emitExpression(as->unaryExpression);
            std::string ty  = exprClass(as->unaryExpression);      // Owned_T / Shared_T / Weak_T
            CollKind    knd = smartKind(ty);
            SharedExpression rhs = as->expression;
            int handoff = 0;   // 0 none, 1 give, 2 copy
            if (auto* h = dynamic_cast<HandoffNode*>(rhs.get())) { handoff = h->isGive ? 1 : 2; rhs = h->value; }
            if (isSmartPtrUpcast(ty, rhs)) {
                // Cross-element upcast reseat: release the handle's old pointee, then widen a
                // concrete-element `Shared`/`Owned` into this contract-element intrinsic handle.
                line(n->line);
                indent(depth); *_out << ty << "__dtor(&" << b << ");\n";
                emitSmartPtrUpcast(b, ty, rhs, handoff, depth, n->line);
                return;
            }
            bool rhsLval = isSmartPtrLValue(rhs);
            if (handoff && !rhsLval)
                unsupported("`give`/`copy` apply to a named value — a fresh `new`/constructor/call result needs no marker", n->line);
            std::string src = emitExpression(rhs);                  // evaluate the RHS once
            line(n->line);
            // Step 4: self-assignment (`a = a`) would release a's pointee, then "copy" it
            // back onto the freed memory -> use-after-free. When the RHS is an lvalue, guard
            // the whole release-and-reseat with an address check (a no-op for `a = a`).
            int d2 = depth;
            if (rhsLval) { indent(depth); *_out << "if (&" << b << " != &(" << src << ")) {\n"; d2 = depth + 1; }
            indent(d2); *_out << ty << "__dtor(&" << b << ");\n";   // release b's old
            if (knd == CollKind::Weak && rhsLval && exprClass(rhs) != ty) {
                // Shared->Weak reseat: field-copy + weak retain. A fat contract Weak
                // copies {obj, vtbl}; a thin Weak copies {ptr}.
                indent(d2);
                if (isInterface(_classes[ty].collElemClass)) {
                    *_out << b << ".obj = (" << src << ").obj; " << b << ".vtbl = (" << src << ").vtbl; "
                         << b << ".ctrl = (" << src << ").ctrl;\n";
                    std::string wa = _collections.count(ty) ? _collections[ty].allocType : "";
                    if (!wa.empty() && wa != "GlobalAllocator") {   // stateful-A iface Weak reseat (M11d)
                        indent(d2); *_out << b << ".alloc = (" << src << ").alloc;\n";
                    }
                }
                else
                    *_out << b << ".ptr = (" << src << ").ptr; " << b << ".ctrl = (" << src << ").ctrl;\n";
                indent(d2); *_out << "if (" << b << ".ctrl) " << b << ".ctrl->weak++;\n";
            } else {
                indent(d2); *_out << b << " = " << src << ";\n";
                if (rhsLval) {                                       // reseat from a named smart ptr
                    // Default the natural op (Owned -> give, Shared/Weak -> copy); a marker overrides.
                    bool doGive = (handoff == 1) || (handoff == 0 && knd == CollKind::Owned);
                    if (handoff == 2 && knd == CollKind::Owned)
                        unsupported("an `Owned` is unique — it can't be `copy`'d; use `give` to move it", n->line);
                    indent(d2);
                    if (doGive) *_out << smartPtrInvalidate(src, knd, isInterface(_classes[ty].collElemClass)) << "\n";
                    else *_out << b << ".ctrl->" << (knd == CollKind::Weak ? "weak" : "strong") << "++;\n";
                }
            }
            if (rhsLval) { indent(depth); *_out << "}\n"; }
            return;
        }
        // Reassigning a destructible `resource` VALUE from a NAMED source: release the target's old
        // value, then move or copy the new one in. `give` MOVES (relocate; mark source moved); `copy`
        // deep-copies via copy() (source survives); a BARE assign follows the type's `bare:` default. A
        // self-COPY (`s = s`) is a guarded no-op; a self-MOVE is rejected. A fresh rvalue keeps the
        // generic path below.
        if (as->token == EQ && isMoveOnlyValue(exprClass(as->unaryExpression))) {
            SharedExpression rhs = as->expression;
            int handoff = 0;
            if (auto* h = dynamic_cast<HandoffNode*>(rhs.get())) { handoff = h->isGive ? 1 : 2; rhs = h->value; }
            if (isNamedValue(rhs.get())) {
                std::string lty = exprClass(as->unaryExpression);
                checkConstWrite(as->unaryExpression, n->line);
                std::string lname = lvalueMoveKey(as->unaryExpression);   // bare local OR `local.field` slot
                bool cpy = isCopyable(lty);
                bool doCopy;
                if (handoff == 2) {
                    if (!cpy) unsupported(("`" + lty + "` has no `copy` method — add `implements "
                                           "Copyable(bare: …)`, or use `give` to move it").c_str(), n->line);
                    doCopy = cpy;
                } else if (handoff == 1) doCopy = false;
                else doCopy = cpy && _classes[lty].bareDefault == COPY;
                // A move needs a movable local (reject moving out of a field/element); a copy reads any lvalue.
                std::string mv = doCopy ? std::string() : moveOnlySource(rhs, n->line);
                std::string rname;
                if (auto* rid = dynamic_cast<IdentifierNode*>(rhs.get()))
                    if (rid->value && (!rid->qualifier || rid->qualifier->empty())) rname = *rid->value;
                if (!lname.empty() && doCopy && rname == lname) return;   // self-copy (retain onto self): no-op
                if (!lname.empty() && !mv.empty() && mv == lname)
                    unsupported("handing a value onto itself would use it after it was dropped", n->line);
                bool bMoved = (!lname.empty() && _moveState.count(lname) && _moveState[lname] == MoveState::Moved);
                if (!lname.empty()) _moveState[lname] = MoveState::NotMoved;   // write target: clear before emit
                std::string b   = emitExpression(as->unaryExpression);
                std::string src = emitExpression(rhs);
                line(n->line);
                if (!bMoved && _classes.count(lty) && _classes[lty].destructible)             // free the old value (if it owns anything)
                    { indent(depth); *_out << lty << "__dtor(&" << b << ");\n"; }
                indent(depth); *_out << b << " = " << (doCopy ? copyCall(lty, src) : src) << ";\n";
                if (!mv.empty()) markMoved(mv);
                return;
            }
            // A FRESH owned rvalue — a ctor/fn CALL returning this resource by value (`this.inPipe =
            // File.make(0)`, `this.buf = Buffer.make(…)`) — reassigned to a `resource` lvalue. The NAMED
            // path above releases the old value; a fresh-rvalue reassignment MUST too, else the old resource
            // LEAKS (a reassigned fd/handle stays open, a heap buffer leaks). Drop-only-if-live keeps the
            // ctor field-first-write correct: a fresh `{0}` slot is marked Moved, so its non-live dtor is
            // skipped — the fd-`close(0)` invariant is untouched. Restricted to (a) a real `resource` kind
            // (a tagged-union Optional/Result reassignment threads the LHS type via the value-producing path
            // below — don't preempt it), (b) a call RHS with no give/copy marker (bare `Type(args)`/generic
            // ctors already returned via the in-place path at ~2806; match/variant/array RHS aren't
            // InvocationNodes). Hoist the RHS into a temp FIRST (it may read the old lvalue), then drop, then
            // assign — mirroring the collection fresh-rvalue path.
            if (handoff == 0 && dynamic_cast<InvocationNode*>(rhs.get())) {
                std::string lty = exprClass(as->unaryExpression);
                auto ci = _classes.find(lty);
                // A dot-ctor on a generic TEMPLATE (`b = Box.make(…)`, `this.m = SortedMap.withAllocator(…)`)
                // must resolve its callee from the LHS instance — the value-producing path further down
                // threads that type and drops the old value; don't preempt it. Every OTHER call returning a
                // resource by value is emitted here, generic instance or not: this gate used to exclude any
                // generic instance (`_genericTypeInstOf`) on the claim that the path below would drop, but
                // that path fires for exactly the dot-ctor shape, so `b = fresh()` on a `Box<int32>` or an
                // `Owned<Probe>` fell through both into a plain store and LEAKED the old value — 503 MB over
                // 2,000 iterations in safe kama, against 1.8 MB for the non-generic twin. The `__dtor` below
                // is right for an instance too: `lty` IS its mangled name. tests/generic_reassign_drop.kama.
                if (ci != _classes.end() && ci->second.kind == TypeKind::Resource
                    && !isGenericDotCtorCall(rhs.get())) {
                    checkConstWrite(as->unaryExpression, n->line);
                    std::string lname = lvalueMoveKey(as->unaryExpression);
                    bool bMoved = (!lname.empty() && _moveState.count(lname) && _moveState[lname] == MoveState::Moved);
                    std::string b = emitExpression(as->unaryExpression);
                    bool ph = _hoistOK; _hoistOK = true;
                    std::string rv = emitExpression(rhs);
                    _hoistOK = ph;
                    std::string t = "__asgn" + std::to_string(_tempCounter++);
                    line(n->line);
                    flushHoisted(depth);
                    indent(depth); *_out << lty << " " << t << " = " << rv << ";\n";
                    if (!bMoved && ci->second.destructible)                 // release the old value (only if live)
                        { indent(depth); *_out << lty << "__dtor(&" << b << ");\n"; }
                    indent(depth); *_out << b << " = " << t << ";\n";
                    if (!lname.empty()) _moveState[lname] = MoveState::NotMoved;
                    return;
                }
            }
        }

        // Reassigning a collection/`string` lvalue (`s = …`, `this.a = …`). exprClass() is "" for a
        // collection/string, so resolve via lvalueCType. Release the target's old buffer, then: from a
        // NAMED source require a marker (bare→error, like the decl handler) — `give` moves (relocate struct
        // + null source + markMoved), `copy` deep-copies (`__copy`); a FRESH owned rvalue moves in bare.
        // Without this branch a named RHS aliases (double-free) and a fresh-rvalue RHS leaks the old buffer.
        if (as->token == EQ) {
            std::string lty = lvalueCType(as->unaryExpression);
            if (ownsByValue(lty) && _classes.count(lty) && _classes[lty].isIntrinsicColl) {
                SharedExpression rhs = as->expression;
                int handoff = 0;
                if (auto* h = dynamic_cast<HandoffNode*>(rhs.get())) { handoff = h->isGive ? 1 : 2; rhs = h->value; }
                checkConstWrite(as->unaryExpression, n->line);
                std::string lname;
                if (auto* lid = dynamic_cast<IdentifierNode*>(as->unaryExpression.get()))
                    if (lid->value && (!lid->qualifier || lid->qualifier->empty())) lname = *lid->value;

                if (isNamedValue(rhs.get())) {
                    if (handoff == 0)
                        unsupported("a collection/`string` hand-off must say `give` (move) or `copy` (deep) "
                                    "— write `… = give …` or `… = copy …`, or pass by `ref` to borrow", n->line);
                    std::string rname;
                    if (auto* rid = dynamic_cast<IdentifierNode*>(rhs.get()))
                        if (rid->value && (!rid->qualifier || rid->qualifier->empty())) rname = *rid->value;
                    if (handoff == 2) {                                   // copy = deep copy via __copy
                        auto ci = _collections.find(lty);
                        if (ci != _collections.end() && ci->second.elemDestructible && !ci->second.elemCopyable)
                            unsupported(("`copy` of a `" + lty + "` needs copyable elements — its elements own "
                                         "resources but aren't `Copyable`; use `give` to move").c_str(), n->line);
                        if (!lname.empty() && rname == lname) return;     // self-copy: no-op
                        std::string b = emitExpression(as->unaryExpression), src = emitExpression(rhs);
                        line(n->line);
                        indent(depth); *_out << lty << "__dtor(&" << b << ");\n";
                        indent(depth); *_out << b << " = " << copyCall(lty, src) << ";\n";
                        return;
                    }
                    // give = move: relocate the struct, then null the source so its scope-drop is a no-op.
                    std::string mv = moveOnlySource(rhs, n->line);
                    if (!lname.empty() && !mv.empty() && mv == lname)
                        unsupported("handing a value onto itself would use it after it was dropped", n->line);
                    if (!lname.empty()) _moveState[lname] = MoveState::NotMoved;   // target live again
                    std::string b = emitExpression(as->unaryExpression), src = emitExpression(rhs);
                    line(n->line);
                    indent(depth); *_out << lty << "__dtor(&" << b << ");\n";
                    indent(depth); *_out << b << " = " << src << ";\n";
                    indent(depth); *_out << moveNullStmt(lty, src) << "\n";
                    if (!mv.empty()) markMoved(mv);
                    return;
                }
                // Fresh owned rvalue (concat/substring/literal): the RHS may READ the old LHS
                // (`s = s.concat(…)`), so hoist it into a temp BEFORE releasing the old buffer, then assign.
                // Enable hoisting for the RHS emit so an interpolation operand (`acc = acc + "${x}"`) can
                // lift its Formatter build — the only owning-string sink that otherwise forgot to.
                std::string b = emitExpression(as->unaryExpression);
                bool ph = _hoistOK; _hoistOK = true;
                std::string rv = emitExpression(as->expression);
                _hoistOK = ph;
                std::string t = "__asgn" + std::to_string(_tempCounter++);
                line(n->line);
                flushHoisted(depth);                                   // Formatter build + operand temps first…
                indent(depth); *_out << lty << " " << t << " = " << rv << ";\n";
                indent(depth); *_out << lty << "__dtor(&" << b << ");\n";
                indent(depth); *_out << b << " = " << t << ";\n";
                return;
            }
        }
    }

    // `lhs = match(…)` / `lhs = Optional::Some(…)` — a value-producing RHS (a value-producing
    // `match`, or a generic-variant construction that needs its instance from context) needs the LHS's
    // C type threaded. The assignment paths above don't handle these RHS kinds; this fires ONLY for
    // them (a match or a `Union::Variant` construction), so ordinary assignments are untouched.
    if (auto* as = dynamic_cast<AssignmentNode*>(n)) {
        if (as->token == EQ) {
            ASTNode* r = as->expression.get();
            bool isMatch = needsTargetType(r);   // a `match`, or a ternary yielding one — see needsTargetType
            // an array literal RHS (`v = [1,2,3]`) is value-producing too — it needs the LHS Fixed
            // type threaded so the compound literal / `__fill` names the right struct.
            bool isArrayLit = dynamic_cast<ArrayLiteralNode*>(r) != nullptr;
            bool isVariantCtor = false;
            // A dot-on-type ctor call on a GENERIC template (`x = Map.empty()`) is value-producing and needs
            // the LHS instance threaded so emitDotOnTypeCtorCall can resolve `Map` -> `Map_int32_int32` by LHS
            // inference — the same channel a local-decl uses. (A concrete-type ctor needs no threading.) #M8d.2
            bool isDotCtor = false;
            if (!isMatch && !isArrayLit) {
                SharedStringList qual;
                if (auto* iv = dynamic_cast<InvocationNode*>(r)) {
                    if (iv->identifier) qual = iv->identifier->qualifier;
                    isDotCtor = isGenericDotCtorCall(r);
                }
                else if (auto* id = dynamic_cast<IdentifierNode*>(r)) qual = id->qualifier;
                if (qual && !qual->empty()) {
                    auto q = std::make_shared<StringList>();
                    for (size_t i = 0; i + 1 < qual->size(); ++i) q->push_back((*qual)[i]);
                    std::string en = resolveUserName(*qual->back(), q);
                    isVariantCtor = (_classes.count(en) && _classes[en].isVariant) || _genericTypeParams.count(en);
                }
            }
            if (isMatch || isVariantCtor || isArrayLit || isDotCtor) {
                std::string lhsCType = exprClass(as->unaryExpression);      // class/union name
                std::string lname;
                if (auto* lid = dynamic_cast<IdentifierNode*>(as->unaryExpression.get()))
                    if (lid->value && (!lid->qualifier || lid->qualifier->empty())) {
                        lname = *lid->value;
                        if (lhsCType.empty() && _localCTypes.count(lname)) lhsCType = _localCTypes[lname];   // primitive/Fixed LHS
                    }
                // …and an ELEMENT LHS learns its type from the collection, which is the only place it is
                // written down: `exprClass` of an element access answers "" for a primitive element, and the
                // `_localCTypes` fallback above only fires for a bare local, so `xs[2] = match (…) {…}` on an
                // `InlineArray<int32>` used to be refused as "needs a typed assignment target" — with a
                // plain local as the only way to spell it. The owning-element store one branch up already
                // reads the element type off `_collections` exactly this way.
                if (lhsCType.empty())
                    if (auto* lea = dynamic_cast<ElementAccessNode*>(as->unaryExpression.get())) {
                        SharedExpression recv = lea->expression
                                                    ? lea->expression
                                                    : std::static_pointer_cast<ExpressionNode>(lea->identifier);
                        const std::string rc = recv ? exprClass(recv) : std::string();
                        if (!rc.empty() && _classes.count(rc) && _classes[rc].isIntrinsicColl
                            && _collections.count(rc))
                            lhsCType = _collections[rc].elemCType;
                    }
                if (lhsCType.empty()) {
                    unsupported("a value-producing `match` / variant construction here needs a typed "
                                "assignment target — assign to a plain local", n->line);
                    *_out << "\n"; return;
                }
                checkConstWrite(as->unaryExpression, n->line);
                std::string mkey = lvalueMoveKey(as->unaryExpression);   // bare local OR `local.field` slot
                bool destructible = _classes.count(lhsCType) && _classes[lhsCType].destructible;
                bool bMoved = (!mkey.empty() && _moveState.count(mkey) && _moveState[mkey] == MoveState::Moved);
                // A PLACE, not an expression. An assignment target is an lvalue by definition, and for an
                // intrinsic-collection element the two spellings differ: `emitExpression` gives the by-value
                // `Coll__get(…)` and `emitExpression(lhs) = rhs` is then not assignable C — it failed at the
                // C compiler for a generic-instance ctor, a qualified variant construction, an array literal
                // and a value-producing `match` alike. `emitPlace` gives `(*Coll__at(…))`, and it falls
                // through to `emitExpression` for every other LHS shape, so this is exactly equivalent
                // elsewhere. (It is used twice below — the RAII dtor takes `&lhs` — and `&(*__at(…))` folds
                // back to the same `T*`.)
                std::string lhs = emitPlace(as->unaryExpression);
                line(n->line);
                bool ph = _hoistOK; _hoistOK = true;
                std::string pm = _matchTargetCType, pv = _variantTargetType;
                _matchTargetCType = _variantTargetType = lhsCType;
                std::string rv = emitExpression(as->expression);
                _matchTargetCType = pm; _variantTargetType = pv;
                _hoistOK = ph;
                flushHoisted(depth);
                // RAII: drop a live destructible LHS before the blit (its owned resource would leak).
                if (destructible && !bMoved) { indent(depth); *_out << lhsCType << "__dtor(&" << lhs << ");\n"; }
                if (!mkey.empty()) _moveState[mkey] = MoveState::NotMoved;   // target is live again
                indent(depth); *_out << lhs << " = " << rv << ";\n";
                return;
            }
        }
    }

    // Bare expression statement (e.g. an assignment or call used as a statement).
    // a statement-position `match` (value discarded) — emit the switch directly, not as an
    // expression (which would try to lift a result temp). Must precede the generic expr-statement path.
    if (auto* mm = dynamic_cast<MatchNode*>(n)) { emitMatchStatement(mm, depth); return; }

    // std::log v2 (M7): a recognized `logError/Warn/Info/Debug/Trace(tag:, msg:)` facade call lowers to a
    // compile-strip + runtime-guard with the message built inside (zero cost when off). Intercept before the
    // generic expression-statement path; an unrecognized call falls straight through unchanged.
    if (auto* iv = dynamic_cast<InvocationNode*>(n)) {
        int lvl;
        if (logFacadeLevel(iv, lvl)) { emitLogFacade(iv, lvl, depth); return; }
    }

    if (dynamic_cast<ExpressionStatementNode*>(n)) {
        line(n->line);
        bool ph = _hoistOK; _hoistOK = true;                       // allow inline-ctor hoisting
        std::string s = emitExpression(std::dynamic_pointer_cast<ExpressionNode>(stmt));
        _hoistOK = ph;
        flushHoisted(depth);                                       // temp decls first…
        indent(depth);
        *_out << s << ";\n";                                       // …then the statement using them
        return;
    }

    line(n->line);
    indent(depth);
    unsupported("statement", n->line);
    *_out << "\n";
}

// A brace-wrapped body for if/while/for/do. Reuses an existing block as-is.
// Always introduces a scope (even for a single-statement body) so RAII cleanup
// and the loop boundary are tracked correctly.
void CEmitter::emitBody(SharedStatement stmt, int depth, bool loopBoundary)
{
    if (auto* b = dynamic_cast<BlockNode*>(stmt.get())) {
        emitBlockScoped(b, depth, loopBoundary, /*functionRoot=*/false);
    } else {
        Scope sc; sc.isLoopBoundary = loopBoundary;
        _scopes.push_back(sc);
        *_out << "{\n";
        emitStatement(stmt, depth + 1);
        if (!stmtIsJump(stmt))
            emitScopeCleanup(_scopes.back(), depth + 1);
        indent(depth);
        *_out << "}";
        popScope();
    }
}

// A statement rendered for a for-clause: no trailing semicolon or newline.
std::string CEmitter::inlineStatement(SharedStatement stmt)
{
    if (!stmt) return "";
    ASTNode* n = stmt.get();

    if (auto* decl = dynamic_cast<LocalVariableDeclaration*>(n)) {
        const std::string ty = cType(decl->type);
        std::string s = ty + " ";
        bool first = true;
        if (decl->variables) {
            for (auto& d : *decl->variables) {
                if (!first) s += ", ";
                first = false;
                const std::string nm = (d->name && d->name->value) ? *d->name->value : "";
                s += nm;
                // A `for` init declares a LOCAL. Record it in the binding tables exactly as emitDeclarator
                // does — it used to be invisible to all of them, so the counter of every `for` loop in the
                // corpus reached the identifier arm as a name nothing bound. Not pushed onto the scope's
                // Owned by the `for`'s wrapper scope (emitStatement's ForNode arm), so it dies with the loop.
                // It IS pushed onto `declaredNames` — the counter is a binding like any other, and the ban
                // applies to it (a `for (int32 i …)` over a live `i` is the same hazard as `int32 i = …`).
                // The comment here used to say it must not be, so that two sequential loops over `i` would
                // not read as shadowing; that was true when the counter had no scope of its own and is not
                // now — the wrapper scope pops between them, so sequential loops never coexist while a
                // NESTED one is caught, which is the distinction the ban is actually about.
                if (!nm.empty()) {
                    checkConstParamBinder(nm, "`for` counter", decl->line);
                    checkBinderShadow(nm, "`for` counter", decl->line);
                    noteScopedBinding(nm);
                    if (!_scopes.empty()) _scopes.back().declaredNames.push_back(nm);
                    _localTypes[nm]     = (isClass(ty) || isInterface(ty)) ? ty : "";
                    _localCTypes[nm]    = ty;
                    _localTypeNodes[nm] = decl->type;
                    registerBinding(d->name.get(), SymKind::Local);
                }
                if (d->initializer) s += " = " + emitExpression(d->initializer);
            }
        }
        return s;
    }

    if (dynamic_cast<ExpressionStatementNode*>(n))
        return emitExpression(std::dynamic_pointer_cast<ExpressionNode>(stmt));

    unsupported("for-clause statement", n->line);
    return "";
}

std::string CEmitter::emitForClause(SharedStatementList list)
{
    if (!list || list->empty()) return "";
    std::string s;
    bool first = true;
    for (auto& st : *list) {
        if (!first) s += ", ";
        first = false;
        s += inlineStatement(st);
    }
    return s;
}

// ---------------------------------------------------------------------------
// Functions
// ---------------------------------------------------------------------------

std::string CEmitter::cFunctionName(const std::string& kamaName)
{
    // The user `main` becomes `kama_main`; a real C `main` wrapper is synthesized.
    return (kamaName == "main") ? "kama_main" : kamaName;
}

std::string CEmitter::mangledFunctionName(FunctionDeclarationNode* fn, bool& isEntryPoint)
{
    std::string name = (fn->name && fn->name->value) ? *fn->name->value : "anon";
    isEntryPoint = (name == "main");
    if (isExposed(fn)) {   // kama→host boundary: the qualified host symbol, or the `@linkName` (collectSignatures)
        auto it = _funcs.find(qualify(name));
        if (it != _funcs.end()) return symbolOf(it->second);
    }
    return qualify(name);   // scope-prefixed (main -> kama_main); _nsCtx set per file
}

// A `ParamSig::className` is mangled when the signature is REGISTERED, which is during unit collection —
// and a `comptime` module constant only the INTERPRETER can fold (a `comptime fn` call) is not folded yet, so
// `InlineArray<isize>#(MAX_CREW)` mangles to `InlineArray_isize_MAX_CREW`, the constant's NAME. The
// function's own prototype is fine, because `paramListC` re-`cType`s the AST node at EMIT time, by which
// point the constant is known — so one instantiation ends up spelled two ways, and the CALL SITE's cast
// (which reads `className`) names a type nothing declares. Reported by a consumer as KB-22, against a
// tree where the constant's file sorted after the callee's; it reproduces only in that order, which is why
// four hand-built probes missed it. ⚠️ Since collectModuleVars/foldModuleConsts, a constant the plain folder
// can reach is known before ANY signature registers, in any file order (KB-23); what is left for this pass
// is the interpreter-folded constant, and removing it breaks exactly that (measured).
//
// The refresh is deliberately SELF-CHECKING: a stale name resolves to nothing, so it only ever replaces a
// className that names no known type with one that does. Re-mangling in a context that cannot see the
// constant produces another unknown name and changes nothing.
void CEmitter::refreshStaleParamTypes()
{
    auto stale = [&](const std::string& c) {
        return !c.empty() && !_classes.count(c) && !_collections.count(c);
    };
    // ONLY a type carrying `#(…)` comptime VALUE arguments can be stale this way, and restricting to that
    // shape is what keeps the re-resolution safe: a parameter type may be spelled with something only its
    // own declaration site can resolve (`Base`, inside a type that `extends`), and re-`cType`ing one of
    // those from a whole-program pass is an error rather than a better answer. `nTypeArgs` is how many
    // leading args came from `<…>`; anything past that came from `#(…)`.
    auto hasComptimeArgs = [](const SharedIdentifier& ty) {
        return ty && ty->genericArgs && ty->nTypeArgs >= 0
            && (int)ty->genericArgs->size() > ty->nTypeArgs;
    };
    auto refresh = [&](std::vector<ParamSig>& sigs, SharedParameterList decl, const std::string& declFile,
                       const ClassInfo* owner) {
        if (!decl) return;
        size_t i = 0;
        for (auto& p : *decl) {
            if (i >= sigs.size()) break;
            if (p && p->type && hasComptimeArgs(p->type) && stale(sigs[i].className)) {
                NsCtx saved = _nsCtx;
                // The DECLARING file's whole context, not a rebuilt one: the type spells the constant the
                // way that file imports it (bare, after `import { m::MAX_CREW }`), so the usings and
                // aliases are what make it resolve. `_unitCtx` carries each file's, keyed by its path.
                bool found = false;
                for (auto& uk : _unitCtx)
                    if (uk.second.unitPath == declFile) { _nsCtx = uk.second; found = true; break; }
                if (!found && owner) {
                    _nsCtx = NsCtx{};
                    _nsCtx.scope = owner->scope; _nsCtx.usings = owner->usings;
                    _nsCtx.symbolAliases = owner->symbolAliases;
                    restoreFileRung(_nsCtx, declFile);
                }
                const std::string fresh = (found || owner) ? cType(p->type) : std::string();
                _nsCtx = saved;
                if (!fresh.empty() && !stale(fresh)) sigs[i].className = fresh;
            }
            ++i;
        }
    };
    for (auto& kv : _funcs)
        if (kv.second.node) refresh(kv.second.params, kv.second.node->parameters, kv.second.declFile, nullptr);
    for (auto& ck : _classes) {
        ClassInfo& ci = ck.second;
        for (auto& mk : ci.methods)
            if (mk.second.node) refresh(mk.second.params, mk.second.node->params, ci.declFile, &ci);
        for (auto& ctk : ci.ctors)
            if (ctk.second.node && ctk.second.node->declarator)
                refresh(ctk.second.params, ctk.second.node->declarator->params, ci.declFile, &ci);
    }
}

std::vector<ParamSig> CEmitter::paramSigsOf(SharedParameterList params)
{
    std::vector<ParamSig> out;
    if (params) {
        for (auto& p : *params) {
            ParamSig ps;
            ps.name  = (p->identifier && p->identifier->value) ? *p->identifier->value : "";
            ps.byRef = paramByRef(p.get());
            ps.isOut = paramIsOut(p.get());
            ps.isConst = p->isConst;
            ps.isHardware = p->isHardware;
            ps.declSite = p->identifier.get();   // M6 A2: what a call-site label is a reference TO
            // Store the C type spelling; whether it's a class is checked at the
            // call site (paramSigsOf may run before the class table is built).
            ps.className = p->type ? cType(p->type) : "";
            out.push_back(ps);
        }
    }
    return out;
}

// A generic call used to reorder its arguments off the TEMPLATE's signature, whose `className`s are the
// symbolic spellings (`std__collections__ConstView_T`). Every per-argument rule in emitReorderedCall keys on
// that C type — the kind rule, the identity rule, and the `View<X>` → `ConstView<X>` narrowing, which is
// what found this: `isSorted(items: v)` narrowed nowhere because `ConstView_T` names no instance. Bind the
// instantiation's arguments exactly as emitGenericInst does, and the call site sees what the callee's
// prototype says. Saved and restored around the binding: the caller may itself be an instantiation mid-walk.
const std::vector<ParamSig>& CEmitter::instParamSigs(const GenericInst& gi)
{
    auto cached = _instParamSigs.find(gi.mangledName);
    if (cached != _instParamSigs.end()) return cached->second;
    auto tit = _generics.find(gi.templateKey);
    if (tit == _generics.end()) return _instParamSigs[gi.mangledName] = _funcs[gi.templateKey].params;
    FunctionDeclarationNode* tmpl = tit->second;
    std::map<std::string, SharedIdentifier> savedSubst = _typeSubst;
    auto savedComptime = _comptimeSubst;
    NsCtx savedCtx = _nsCtx;
    auto cit = _genericCtx.find(gi.templateKey);
    if (cit != _genericCtx.end()) _nsCtx = cit->second;
    bindInstParams(tmpl->typeParams, tmpl->constTypes, gi.typeArgs);
    std::vector<ParamSig> sigs = paramSigsOf(tmpl->parameters);
    _typeSubst = savedSubst; _comptimeSubst = savedComptime; _nsCtx = savedCtx;
    return _instParamSigs[gi.mangledName] = sigs;
}

// Module-level `static T name …` (MCU step 1) and `comptime NAME = …`: register each name's qualified C symbol
// so references in any body of this module resolve to it. Legality is checked at emission. Its own pass, run
// over EVERY unit before any other collection, so no reader of a constant depends on FILE ORDER: a
// `comptime isize DERIVED = PROBE_N;` aliasing a constant from a file that sorts later used to fold after
// `collectCollections` had already asked for it, and an `InlineArray<Leaf>#(DERIVED)` field degraded to a raw
// pointer with no diagnostic naming the declaration (consumer KB-23). foldModuleConsts finishes the job.
void CEmitter::collectModuleVars(SharedCompilationUnit unit)
{
    if (!unit || !unit->codeDeclarationList) return;
    for (auto& decl : *unit->codeDeclarationList) {
        if (auto* mv = dynamic_cast<ModuleVariableDeclaration*>(decl.get())) {
            if (mv->variables)
                for (auto& d : *mv->variables)
                    if (d && d->name && d->name->value) {
                        _moduleStatics[qualify(*d->name->value)] = mv->type;
                        _moduleVarFile[qualify(*d->name->value)] = _collectingUnitPath;   // the file rung's key
                        // A `comptime` static emits as C `static const`, so anything that takes its ADDRESS
                        // must take a `const` one — see the const-correct foreach lowering. Recorded for
                        // every comptime static, not just the foldable ones, since constness is a property
                        // of the declaration and not of whether the folder happened to succeed.
                        if (mv->isComptime) _constStatics.insert(qualify(*d->name->value));
                        // 6b-2: a `comptime NAME` with a foldable integer initializer is a named
                        // compile-time constant — record its value (qualified key) so const-generic sizes
                        // and later `comptime` initializers resolve it. Declaration-order fold: an
                        // earlier const is already recorded, so `B = A + 1` folds here (constValue -> _moduleConsts).
                        if (mv->isComptime && d->initializer) {
                            int64_t cv;
                            if (constValue(d->initializer, cv)) _moduleConsts[qualify(*d->name->value)] = cv;
                            // A fold miss is deferred: to foldModuleConsts when it names a constant from a
                            // unit not yet seen, and past that to the interpreter pass (evalComptimeConsts)
                            // for a `comptime fn` call, a `Type::NAME`, or anything else the folder can't do.
                            else _ctDeferredConsts.push_back({ qualify(*d->name->value), mv->type, d->initializer, _nsCtx, mv->line });
                        }
                    }
        }
    }
}

// Fold every deferred module constant the plain folder can now reach, to a fixpoint — every unit's constants
// are registered, so an alias chain of any depth across files resolves regardless of which file sorts first.
// What still misses (a `comptime fn` call, a `Type::NAME` before collectClasses) stays deferred for
// evalComptimeConsts, exactly as before.
void CEmitter::foldModuleConsts()
{
    NsCtx saved = _nsCtx;
    for (bool progress = true; progress; ) {
        progress = false;
        for (auto it = _ctDeferredConsts.begin(); it != _ctDeferredConsts.end(); ) {
            _nsCtx = it->ctx;
            int64_t cv;
            if (constValue(it->init, cv)) {
                _moduleConsts[it->cName] = cv;
                it = _ctDeferredConsts.erase(it);
                progress = true;
            } else {
                ++it;
            }
        }
    }
    _nsCtx = saved;
}

// Build the function signature table so call sites can reorder named arguments
// into C's positional order.
void CEmitter::collectSignatures(SharedCompilationUnit unit)
{
    if (!unit || !unit->codeDeclarationList) return;
    for (auto& decl : *unit->codeDeclarationList) {
        if (dynamic_cast<ModuleVariableDeclaration*>(decl.get())) continue;   // collectModuleVars, every unit first
        if (auto* xc = dynamic_cast<ExternConstNode*>(decl.get())) { collectExternConst(xc); continue; }
        auto* fn = dynamic_cast<FunctionDeclarationNode*>(decl.get());
        if (!fn || !fn->name || !fn->name->value) continue;
        rejectPinOutsideContract(fn->typePins, fn->typeParams, "a function", fn->line);

        // const-eval 6b-3: a `comptime fn` is a compile-time-only function. Register it for the
        // interpreter (NOT in _funcs — it is never emitted as a C symbol) and reject an impure body
        // now. It is monomorphic in v1 (the grammar admits no type/const params or `expose`).
        if (fn->isComptime) {
            _comptimeFns[qualify(*fn->name->value)] = fn;
            continue;
        }

        // The boundary symbol: the kama name, unless `@linkName("…")` says otherwise (extern/expose only).
        const std::string link = (isExtern(fn) || isExposed(fn)) ? linkNameOf(fn) : std::string();
        if (isExposed(fn)) {
            // The kama→host boundary needs ONE concrete, C-ABI-callable symbol. A generic
            // template has none (its `T` is unbound), and a `fn ref T` place-return has no
            // clean C ABI. The by-value signature (ownership-crossing) check needs `_classes`,
            // so it lives in emitFunction (this pass runs before collectClasses).
            if (fn->typeParams && !fn->typeParams->empty())
                unsupported("`expose` cannot mark a generic function — a host needs a concrete "
                            "C-ABI symbol; expose a concrete wrapper instead", fn->line);
            if (fn->isRef)
                unsupported("`expose` cannot mark a `fn ref T` place-returning function — its "
                            "return has no C-ABI form; return a value or an `UnsafePtr<T>`", fn->line);
            const std::string exported = link.empty() ? exposedSymbol(*fn->name->value) : link;
            const std::string who = (_nsCtx.module.empty() ? std::string() : _nsCtx.module + "::") + *fn->name->value;
            auto prev = _exposedNames.emplace(exported, who + " (" + _collectingUnitPath + ":" + std::to_string(fn->line) + ")");
            if (!prev.second)
                unsupported(("`expose fn " + who + "` exports the C symbol `" + exported + "`, which `"
                             + prev.first->second + "` already exports — a host links against one symbol "
                             "per name; rename one, or give it `@linkName(\"…\")`").c_str(), fn->line);
        }

        // A bodiless top-level `fn ret Name(params);` (no body, not extern) is a
        // function-pointer SIGNATURE type, not a callable — register in _sigs.
        if (!fn->block && !isExtern(fn)) {
            SigInfo si;
            si.cName    = qualify(*fn->name->value);
            si.retCType = cType(fn->returnType);
            si.params   = paramSigsOf(fn->parameters);
            si.declFile = _collectingUnitPath;
            si.noHeap   = hasNoHeapAttr(fn->attributes);   // the declared half of the no-heap proof
            si.foreignEntry = hasAttr(fn->attributes, "foreignEntry");   // ...and of the threading one
            si.callerThread = hasAttr(fn->attributes, "callerThread");
            if (si.foreignEntry && si.callerThread)
                unsupported(("`" + *fn->name->value + "` is both `@foreignEntry` and `@callerThread` — a "
                             "callback runs on the calling isolate or it does not; pick the one the C API "
                             "documents").c_str(), fn->line);
            _sigs[si.cName] = si;
            continue;
        }

        FuncSig sig;
        // An extern (host->kama FFI) keeps its literal C name: the symbol belongs to C. Everything else is
        // scope-prefixed (main -> kama_main) — an `expose fn` included, because its kama identity is its
        // module's like any function's; only its SYMBOL is the host's, and that lives in `linkName`.
        sig.cName   = isExtern(fn) ? *fn->name->value : qualify(*fn->name->value);
        sig.linkName = isExposed(fn) && link.empty() ? exposedSymbol(*fn->name->value) : link;   // see FuncSig
        sig.retCType = cType(fn->returnType);
        sig.params  = paramSigsOf(fn->parameters);
        sig.isPlaceReturn = fn->isRef;   // `fn ref T …` — the call site derefs the returned place
        sig.isConstPlace  = fn->isConstRef;   // `fn const ref T …` — and may only read through it
        sig.isUnsafe = fn->isUnsafe;     // `unsafe fn …` — the body may touch raw memory
        sig.node = fn;                   // decl site for the LSP def-site table (unused by emission)
        // `@heap extern fn`: C that touches the heap, by the SYMBOL — every declaration of it names the same C,
        // so one marked declaration marks every call, including one through an unmarked redeclaration.
        if (isExtern(fn) && hasAttr(fn->attributes, "heap")) _heapSymbols.insert(symbolOf(sig));

        // kama has no overloading, so a name is declared once per namespace — but this was a bare
        // assignment, so a second declaration silently REPLACED the first. For a plain function clang
        // caught it downstream as a C redefinition (a C-level diagnostic for a kama-level error); for a
        // generic template nothing caught it at all — the LAST body won and the program built clean.
        // Same shape as the duplicate-operator rejection: the key carries the discriminator, so a
        // collision on the exact key IS the error.
        //
        // `extern` is exempt on BOTH sides. Re-declaring a C entry point in each module that calls it is
        // idiomatic and pervasive here (`malloc` in 3 files, `kama_last_error` in 5), and it is what an
        // extern IS — a reference to a symbol someone else defines, not a definition. A genuinely
        // conflicting pair still fails, in the C compiler, on the two disagreeing prototypes.
        //
        // Both lines come off `fn->name`, not `fn`: a declaration node is built with the lexer counter at
        // reduce time, which lags by one lookahead token, while the NAME is STAMP_LOC'd from `@4` — the
        // arm's own comment says so ("an unmodified fn's @$ starts at the previous token"). A duplicate
        // must point at the duplicate, so the accurate span is the one worth reading.
        if (!isExtern(fn)) {
            auto prev = _funcs.find(sig.cName);
            if (prev != _funcs.end() && !(prev->second.node && isExtern(prev->second.node))) {
                FunctionDeclarationNode* first = prev->second.node;
                // The first declaration's location, WITH ITS FILE. It read "(first declared at line 2)"
                // and named no file, which was merely unhelpful while both were in one file and is wrong
                // now that a module spans a directory and `main` is scoped by nothing at all — the two
                // sites are routinely in different folders. `FuncSig::declFile` carries it.
                std::string where;
                if (first && first->name) {
                    where = " (first declared at ";
                    if (!prev->second.declFile.empty()) where += prev->second.declFile + ":";
                    where += std::to_string(first->name->line) + ")";
                }
                // ⚠️ TWO RULES, TWO MESSAGES. `main` is not scoped — `qualify` maps every one of them to
                // `kama_main` before any scope prefix — so two `main`s collide where `a::helper` and
                // `b::helper` do not. The generic message cannot describe both, and describing the wrong
                // one is worse than terse: it sent the reader looking for a module clash that is not there.
                //
                // ⚠️ The generic arm must keep the literal prefix `duplicate function '<name>'` —
                // tests/xfail/dup_fn.msg and dup_generic_fn.msg assert exactly that substring.
                if (sig.cName == "kama_main")
                    unsupported(("a project has ONE entry point, and this is the second `main`" + where
                                 + ". `main` is scoped by nothing — it is not in any module's surface and "
                                   "every one of them emits as the same C symbol — so two collide where "
                                   "`a::helper` and `b::helper` would not").c_str(),
                                fn->name->line);
                else
                    unsupported(("duplicate function '" + *fn->name->value + "' — kama has no overloading, "
                                 "so a name may be declared only once in its module" + where).c_str(),
                                fn->name->line);
            }
        }

        // AGREEMENT. Re-declaring an extern in each file that calls it is the idiom SPEC prescribes, and
        // the duplicate rule above is exempt for exactly that reason — but "exempt" used to mean the LAST
        // declaration collected silently replaced every earlier one, and every call site in the program
        // then lowered through the winner. That is a silent miscompile, not a nicety:
        //
        //   a.kama  extern fn UnsafePtr memcpy(UnsafePtr dst, UnsafePtr src, usize n);   // the true order
        //   b.kama  extern fn UnsafePtr memcpy(UnsafePtr src, UnsafePtr dst, usize n);   // names swapped
        //
        // Both files write `memcpy(dst: d, src: s, n: 4)`; named arguments are REORDERED off the winning
        // FuncSig, so a.kama's correct call emitted `memcpy(s, d, 4)` — source and destination reversed —
        // and it built, linked and ran. Measured, not reasoned: that is `tests/xfail/extern_disagree.d`.
        //
        // And the winner can be the USER: a program declaring `extern fn int32 malloc(int32)` replaced the
        // prelude's own, so `GlobalAllocator.allocate` stopped compiling with a diagnostic that named no
        // file at all (`at :531`) and blamed the standard library for the user's line.
        //
        // kama never emits a prototype for an extern (SPEC: the prototype comes from the header), so C
        // cannot catch the disagreement either — there is no second declaration for clang to compare.
        // This is the only place that can. Agreement stays silent; that is still the idiom.
        if (isExtern(fn)) {
            auto prev = _funcs.find(sig.cName);
            if (prev != _funcs.end() && prev->second.node && isExtern(prev->second.node)) {
                const FuncSig& was = prev->second;
                std::string diff;
                if (was.retCType != sig.retCType)
                    diff = "it returns `" + sig.retCType + "` here and `" + was.retCType + "` there";
                else if (was.params.size() != sig.params.size())
                    diff = "it takes " + std::to_string(sig.params.size()) + " parameter(s) here and "
                         + std::to_string(was.params.size()) + " there";
                else for (size_t i = 0; i < sig.params.size() && diff.empty(); ++i) {
                    const ParamSig& a = sig.params[i];
                    const ParamSig& b = was.params[i];
                    // The NAME is part of the signature here in a way it is not in C: kama calls are
                    // named-argument and reorder off this list, so two declarations that differ only in
                    // parameter order are the memcpy case above.
                    if (a.name != b.name)
                        diff = "parameter " + std::to_string(i + 1) + " is named `" + a.name
                             + "` here and `" + b.name + "` there";
                    else if (a.className != b.className)
                        diff = "parameter `" + a.name + "` is `" + a.className + "` here and `"
                             + b.className + "` there";
                    else if (a.byRef != b.byRef || a.isOut != b.isOut || a.isConst != b.isConst)
                        diff = "parameter `" + a.name + "` disagrees on `ref`/`out`/`const`";
                }
                if (!diff.empty()) {
                    std::string where = was.declFile.empty() ? std::string("another file")
                                                             : "`" + was.declFile + "`";
                    if (was.node && was.node->name)
                        where += ":" + std::to_string(was.node->name->line);
                    unsupported(("this `extern fn " + *fn->name->value + "` disagrees with the one in "
                                 + where + " — " + diff + ". `" + sig.cName + "` is ONE C symbol, so every "
                                 "declaration of it in a program must match: kama emits no prototype for an "
                                 "extern, so nothing downstream can catch a mismatch, and call sites in "
                                 "BOTH files lower through whichever was collected last").c_str(),
                                fn->name->line);
                }
            }
        }

        // The signature half of the containment rule, free-function side. `extern` is exempt for the same
        // reason a contract member is: it is BODILESS, so there is nothing in it to be unsafe — CALLING one
        // is the unsafe act, gated at the call. A bodiless `fn` is a function-pointer signature TYPE and
        // never reaches here (it went to `_sigs` above).
        if (!isExtern(fn))
            checkSignatureRawPtr(fn->isUnsafe, fn->returnType, fn->parameters,
                                 *fn->name->value, fn->name->line);

        sig.declFile = _collectingUnitPath;   // the file rung's key, and the duplicate diagnostic's
        // An extern's `declFile` is whichever file was collected LAST, so it cannot answer the rung on its
        // own — the set can. Recorded before the table write, which overwrites the previous declaration.
        if (isExtern(fn) && !_collectingUnitPath.empty()) {
            _externDeclSites[sig.cName].insert(_collectingUnitPath);
            // Every BARE name the signature spells, as a C spelling this file introduced: `CompareFn` in
            // `extern fn void qsort(…, CompareFn compar)` is the header's typedef, and the file bridges to
            // it with `cast<CompareFn>(…)`. `checkBodyType` admits exactly these, and only in this file.
            std::function<void(const SharedIdentifier&)> spell = [&](const SharedIdentifier& t) {
                if (!t || !t->value) return;
                if (!t->qualifier || t->qualifier->empty()) _externCSpellings[_collectingUnitPath].insert(*t->value);
                forEachTypeArg(t, spell);
            };
            spell(fn->returnType);
            if (fn->parameters) for (auto& p : *fn->parameters) if (p) spell(p->type);
        }
        // ONE C SYMBOL, ONE KAMA BINDING. `@linkName` lets two kama names reach one symbol, and the
        // agreement rule above is keyed on the kama name, so `extern fn add` in one file and
        // `@linkName("add") extern fn plus` in another would never be compared — the silent last-wins
        // that rule exists to prevent, back through another door. Comparing signatures across kama names
        // is machinery for a program that has two names for one thing; refuse it and name the binding
        // that already exists.
        if (isExtern(fn)) {
            const std::string& sym = symbolOf(sig);
            auto own = _externSymbolOwner.find(sym);
            if (own != _externSymbolOwner.end() && own->second != sig.cName) {
                std::string where;
                auto prev = _funcs.find(own->second);
                if (prev != _funcs.end()) {
                    where = " (declared in " + (prev->second.declFile.empty() ? std::string("another file")
                                                                              : "`" + prev->second.declFile + "`");
                    if (prev->second.node && prev->second.node->name)
                        where += ":" + std::to_string(prev->second.node->name->line);
                    where += ")";
                }
                unsupported(("the C symbol `" + sym + "` is already bound as `" + own->second + "`" + where
                             + " — one C symbol has one kama binding in a program; declare `extern fn "
                             + own->second + "` here and call that").c_str(), fn->name->line);
            } else {
                _externSymbolOwner[sym] = sig.cName;
            }
        }
        _funcs[sig.cName] = sig;

        // a generic template (`fn max<T>(…)`) is registered for monomorphization and is
        // NOT emitted as-is (its `T` is unbound). Its FuncSig stays in _funcs so call sites reorder
        // named args off it; call emission redirects to the concrete instantiation instead.
        if (fn->typeParams && !fn->typeParams->empty()) {
            _generics[sig.cName]   = fn;
            _genericCtx[sig.cName] = _nsCtx;   // resolve the body's type refs in its home scope
            // The template's own file, for a diagnostic raised while re-walking this body per
            // instantiation — that happens in the HEADER pass, where `_sourcePath` names the entry file.
            // Same record `ClassInfo::declFile` keeps for a generic type.
            _genericDeclFile[sig.cName] = _collectingUnitPath;
        }
    }
}

// `extern const T NAME;` — a C constant, bound by name the way an `extern fn` is: repeated only identically, one kama
// binding per C symbol, and a PRIMITIVE, since a pointer/struct/string constant has no by-value kind to check (a
// string macro is a `char[N]`, a braced `*_INIT` macro is not an expression at all).
void CEmitter::collectExternConst(ExternConstNode* xc)
{
    if (!xc->name || !xc->name->value || !xc->type) return;
    const std::string& nm = *xc->name->value;
    const int ln = xc->name->line;
    std::string ct = cType(xc->type);
    const std::string key = primKeyOfCType(ct);
    if (!isScalarPrimKey(key) || key == "char" || xc->type->genericArg) {
        unsupported(("`extern const " + nm + "` must be a number or `bool` — a C constant crosses by value, and only "
                     "a primitive has a size and kind the build can hold to the header's; bind a pointer or a "
                     "struct constant through a C function that returns it").c_str(), ln);
        return;
    }
    ExternConst ec;
    ec.type = xc->type; ec.cType = ct; ec.declFile = _collectingUnitPath; ec.line = ln; ec.node = xc;
    const std::string link = linkNameOf(xc->attributes, xc->line);
    ec.symbol = link.empty() ? nm : link;
    auto prev = _externConsts.find(nm);
    if (prev != _externConsts.end() && (prev->second.cType != ct || prev->second.symbol != ec.symbol)) {
        unsupported(("this `extern const " + nm + "` disagrees with the one in `" + prev->second.declFile + "`:"
                     + std::to_string(prev->second.line) + " — `" + nm + "` is ONE C constant, so every declaration of "
                       "it must state the same type and bind the same symbol").c_str(), ln);
        return;
    }
    if (_funcs.count(nm)) {
        unsupported(("`" + nm + "` is already an `extern fn` — one C name is one kind of thing").c_str(), ln);
        return;
    }
    auto own = _externSymbolOwner.find(ec.symbol);
    if (own != _externSymbolOwner.end() && own->second != nm) {
        unsupported(("the C symbol `" + ec.symbol + "` is already bound as `" + own->second + "` — one C symbol has "
                     "one kama binding in a program; name that one here").c_str(), ln);
        return;
    }
    _externSymbolOwner[ec.symbol] = nm;
    if (!_collectingUnitPath.empty()) _externDeclSites[nm].insert(_collectingUnitPath);
    _externConsts[nm] = ec;
}

// `<T is This>` outside a `type contract` — see the header for why this is semantic and not a parse error.
void CEmitter::rejectPinOutsideContract(SharedIdentifierList pins, SharedStringList params,
                                        const char* what, int line)
{
    if (!pins) return;
    for (size_t i = 0; i < pins->size(); ++i) {
        if (!(*pins)[i]) continue;
        SharedString nm = (params && i < params->size()) ? (*params)[i] : SharedString();
        unsupported(("`" + (nm ? *nm : std::string("?")) + " is …` pins a type parameter to the implementing "
                     "type, and " + what + " has no implementer — the pin is valid only on a `type contract`")
                    .c_str(), line);
    }
}

// Collect interface declarations (method prototype lists).
void CEmitter::collectInterfaces(SharedCompilationUnit unit)
{
    if (!unit || !unit->codeDeclarationList) return;
    for (auto& decl : *unit->codeDeclarationList) {
        // `type contract C { … }` — a ClassDeclarationNode whose kind word is "contract".
        // Its methods parse as (bodiless) class methods; register them as a contract's slots.
        auto* cd = dynamic_cast<ClassDeclarationNode*>(decl.get());
        if (!cd || !cd->typeKind || *cd->typeKind != "contract" || !cd->name || !cd->name->value) continue;
        InterfaceInfo ii;
        ii.name = qualify(*cd->name->value); ii.scope = _nsCtx.scope; ii.usings = _nsCtx.usings;
        ii.privScope = _nsCtx.privScope; ii.exportedHere = _nsCtx.exportedHere;
        ii.symbolAliases = _nsCtx.symbolAliases;   // so contract sigs can name imported/library-generic types
        ii.node = cd;                              // decl site for the LSP def-site table (unused by emission)
        ii.declFile = unit && unit->name ? *unit->name : std::string();   // for a late whole-program check
        // `@viewable` — the mint grant (see InterfaceInfo::isViewable). Read here rather than in
        // collectClasses because that pass `continue`s on a contract, and read at all rather than being
        // inferred from the member signatures because the grant is a DECLARATION: `Iterable<T>.iterator()`
        // returns the `Iterator<T>` CONTRACT, not a view, so no signature in a marked contract has to name
        // one. What returns a view is the IMPLEMENTATION, and that is where the grant is spent.
        if (cd->attributes)
            for (auto& at : *cd->attributes) {
                if (!at || !at->name) continue;
                if (*at->name == "viewable") {
                    if (at->args && !at->args->empty())
                        unsupported("`@viewable` takes no arguments — it marks the whole contract, and the "
                                    "return type of each member self-selects which ones may mint", cd->line);
                    ii.isViewable = true;
                } else {
                    unsupported(("unknown contract attribute `@" + *at->name
                                 + "` (expected `@viewable`)").c_str(), cd->line);
                }
            }
        // Kind gate: `for <kinds>` is MANDATORY on a contract — the designer must state which kinds may
        // implement it. The clause is a COMMA LIST meaning "any of these" (`for value, view`); there is
        // no `|` alternative in the grammar (kama.y kind_name_list), whatever older messages implied.
        if (cd->forKinds) for (auto& k : *cd->forKinds) {
            if (!k) continue;
            if (unsigned bit = kamaImplKindBit(*k)) { ii.implKinds |= bit; continue; }
            // `both` named an arbitrary pair the moment there were more than two kinds, and 96 uses
            // showed it was being reached for as a default rather than chosen. Its own message, because
            // "not a kind word" would be true but useless to someone migrating.
            if (*k == "both")
                unsupported(("`for both` is retired — a contract names its kinds: `type contract "
                             + *cd->name->value + " for value, resource`, plus `view`, `enum` or "
                             "`intrinsic` if those implement it too").c_str(), cd->line);
            else
                unsupported(("a contract's `for` clause takes `value`, `resource`, `view`, `enum` or "
                             "`intrinsic` — not `" + *k + "`").c_str(), cd->line);
        }
        // Keyed on the CLAUSE being absent, not on the mask being empty. A clause that was written and
        // then rejected word-by-word has already been told what is wrong; a second "you didn't declare
        // any" stacked on top of that points the reader away from the actual mistake.
        if (!cd->forKinds || cd->forKinds->empty())
            unsupported(("contract `" + *cd->name->value + "` must declare which kinds may implement it: "
                         "`type contract " + *cd->name->value + " for value, resource { … }` — any of "
                         "`value`, `resource`, `view`, `enum`, `intrinsic`").c_str(), cd->line);
        // A contract signature may not name `This` — see the method arm below for why. Shared by the
        // method and operator arms, since `This operator+(This rhs)` is the same shape as a method.
        auto namesThis = [](SharedIdentifier t) {
            return t && t->value && *t->value == "This" && !t->genericArg;
        };
        auto rejectThis = [&](const std::string& what, int line) {
            unsupported(("contract `" + ii.name + "` names `This` in `" + what + "` — a contract value "
                         "erases the self-type, so declare it as a pinned parameter instead: `type contract "
                         + *cd->name->value + "<T is This>` and write `T` in the signature").c_str(), line);
        };
        if (cd->members)
            for (auto& m : *cd->members) {
                // a `contract` is a public guarantee: signatures only, no bodies, no fields, no
                // dtor (it holds no state and destroys nothing). A `ctor` IS allowed — it is what lets a
                // bound construct (`T.fromStr(s: …)`), and it registers as an `isCtor` slot below.
                if (auto* md = dynamic_cast<ClassMethodDeclarationNode*>(m.get())) {
                    if (md->body)
                        unsupported(("a `contract` method (`" + (md->name && md->name->value ? *md->name->value : std::string())
                                     + "`) has no body — it is a guarantee, not an implementation").c_str(), md->line);
                    // …and having no body, it has nothing to be `unsafe`. A contract member is a CONDUIT:
                    // both ends are already closed by the member's own types — an implementation whose
                    // signature names `UnsafePtr` must be an `unsafe fn`, and a caller cannot invoke one
                    // without holding an `UnsafePtr`. That is what keeps `A: Allocator` a safe bound while
                    // `allocate`/`deallocate` stay uninvocable outside an `unsafe fn`.
                    if (md->whenParams && !md->whenParams->empty())
                        unsupported(("a `contract` member (`" + (md->name && md->name->value ? *md->name->value : std::string())
                                     + "`) cannot be conditional — a contract is one guarantee for every "
                                       "implementer; put the `when` on the implementing type's method").c_str(), md->line);
                    if (modHas(md->modifiers, "unsafe"))
                        unsupported(("`unsafe` marks a function BODY, and the `contract` member `"
                                     + (md->name && md->name->value ? *md->name->value : std::string())
                                     + "` has none — the implementation carries the marker, not the "
                                       "declaration").c_str(), md->line);
                    // A contract signature may not name `This`. It is the erasure hazard in one line: a
                    // vtbl slot has to give `This` ONE type, so it binds the contract, while the concrete
                    // function behind the slot bound the implementing type — two bindings for one function
                    // pointer, and the cast between them is a lie the C compiler cannot see. Declaring the
                    // self-type as a pinned parameter makes it a real type argument that resolves the same
                    // way on both sides. `This` stays legal in a type's OWN body, where it is not erased.
                    if (md->name && md->name->value) {
                        bool bad = namesThis(md->returnType);
                        if (md->params) for (auto& pp : *md->params) if (pp && namesThis(pp->type)) bad = true;
                        if (bad) rejectThis(*md->name->value, md->line);
                        ii.methods.push_back({*md->name->value, md->returnType, md->params, md->isRef, md->isCtor, md->isConst,
                                              modHas(md->modifiers, "static"), md->name});
                        ii.methods.back().isConstPlace = md->isConstRef;   // `const ref T` member — see InterfaceMethod
                        // `@noheap` on a contract member. It parsed and was silently DISCARDED before this
                        // — the attribute reached `ClassMemberDeclarationNode::attributes` and nothing ever
                        // read it here, so a contract could promise a real-time guarantee that no
                        // implementation was ever checked against.
                        ii.methods.back().noHeap = hasNoHeapAttr(md->attributes);
                    }
                } else if (auto* od = dynamic_cast<ClassOperatorDeclarationNode*>(m.get())) {
                    // an operator in a `contract` is a bound for generic math: `IArithmetic`
                    // declares `This operator+(This rhs)`. Register it under the SAME synthetic name
                    // (`op_add`) the concrete class's `operator+` uses, so classSatisfiesBound matches
                    // it structurally and the monomorphized `a + b` lowers to `Concrete__op_add(&a, b)`.
                    if (od->body)
                        unsupported("a `contract` operator has no body — it is a guarantee, not an implementation", od->line);
                    auto* d = od->operatorDeclarator.get();
                    int arity = (d->param1Type ? 1 : 0) + (d->param2Type ? 1 : 0);
                    // owner="" — a `This` param is same-type → the bare name `op_add`, matching the concrete
                    // class's same-type operator; a different-type contract operand keeps its `__<Type>` suffix.
                    std::string opName = operatorName(d->opToken, arity, d->param1Type, "");
                    if (opName.empty())
                        unsupported((std::string("operator '") + binaryOperator(d->opToken)
                                     + "' has no " + (arity == 0 ? "unary" : "binary") + " form").c_str(), od->line);
                    if (namesThis(d->returnType) || namesThis(d->param1Type) || namesThis(d->param2Type))
                        rejectThis(std::string("operator") + binaryOperator(d->opToken), od->line);
                    ii.methods.push_back({opName, d->returnType, operatorParamList(d)});
                } else if (dynamic_cast<ClassFieldDeclarationNode*>(m.get()) || dynamic_cast<ClassConstDeclarationNode*>(m.get())) {
                    unsupported(("a `contract` holds no state — remove the field from `" + ii.name + "`").c_str(), m->line);
                } else if (dynamic_cast<ClassConstructorDeclarationNode*>(m.get()) || dynamic_cast<ClassDestructorDeclarationNode*>(m.get())) {
                    unsupported(("a `contract` has no constructor/destructor — `" + ii.name + "` is a guarantee").c_str(), m->line);
                } else if (dynamic_cast<FriendGrantNode*>(m.get())) {
                    // A `friend` grant opens a PRIVATE member to a named accessor, and a contract has no
                    // private members: every method satisfying one must be `public` (see the conformance
                    // check in emitClassInterfaceVtables). So the grant had nothing to widen.
                    //
                    // It parsed and was then silently dropped — `collectClasses` reads `friendGrantsRaw`,
                    // `collectInterfaces` never did — so a non-granted caller still reached the member and
                    // `friend nameThatDoesNotExist[m]` was accepted, while the same typo on a TYPE is caught
                    // (tests/xfail/friend_unknown). Accepted-and-inert surface that reads as protection is
                    // worse than no surface: refuse it and say where the mechanism does live.
                    unsupported(("`friend` on `contract " + ii.name + "` grants nothing — a contract is a "
                                 "PUBLIC interface, so it has no private member to open. For a hidden "
                                 "member with named access, put it on a `type` (a `virtual`/`abstract` one "
                                 "if it needs `protected`) and grant there").c_str(), m->line);
                }
            }
        // a generic CONTRACT template (`type contract Iterator<T>`) is kept OUT of _interfaces — its
        // method sigs name the raw `T`, so an eager vtable would be bogus. Its shape is parked in
        // _genericContracts and specialized per concrete `Iterator<Arg>` at discovery (mirrors the
        // generic-TYPE divert in collectClasses).
        // the prelude `Deref<T>` gates auto-deref — remember its resolved name (by source name, so a
        // user's own `Deref` in a namespace still matches). Empty if no `Deref` is in scope → inert.
        if (cd->name && cd->name->value && *cd->name->value == "Deref") _derefContract = ii.name;
        if (cd->name && cd->name->value && *cd->name->value == "DerefMut") _derefMutContract = ii.name;
        // the prelude `HeapOwner<T>` — a type implementing it is a `new` placement target (via `adopt`).
        if (cd->name && cd->name->value && *cd->name->value == "HeapOwner") _heapOwnerContract = ii.name;
        // the prelude ownership markers — `Movable` (implicit on resources; `!Movable` subtracts it) and
        // `Copyable` (duplicable). Recognized by source name so the give/copy discipline can consult them.
        if (cd->name && cd->name->value && *cd->name->value == "Movable")  _movableContract  = ii.name;
        if (cd->name && cd->name->value && *cd->name->value == "Copyable") _copyableContract = ii.name;
        // the prelude `Sendable` marker — DECLARED by a type and VERIFIED by the compiler over its fields
        // (checkSendableDeclarations); required at every isolate crossing. Recognized by source name so
        // the refinement below and the gates can consult it.
        if (cd->name && cd->name->value && *cd->name->value == "Sendable") _sendableContract = ii.name;
        // Refinement: `type contract Animated implements Drawable` — record the parent contract names
        // (resolved in this contract's scope); linkContracts() merges their methods in transitively.
        if (cd->baseTypes && cd->baseTypes->interfaces)
            for (auto& p : *cd->baseTypes->interfaces)
                if (p && p->value) {
                    const std::string pn = resolveUserName(*p->value, p->qualifier);
                    // `type contract Job implements Sendable` — a REQUIREMENT on implementors, not a
                    // parent with members to merge: every `implements Job` must also declare `Sendable`
                    // (and is verified), which is what lets a boxed `Owned<Job>` cross an isolate.
                    if (!_sendableContract.empty() && pn == _sendableContract) ii.requiresSendable = true;
                    else ii.refines.push_back(pn);
                }
        // `<T is This>` — the identity pin. Validated here, at the declaration, because every rejection
        // below is a property of the contract alone; a use site would report it too late and too often.
        if (cd->typePins)
            for (size_t i = 0; i < cd->typePins->size(); ++i) {
                SharedIdentifier pin = (*cd->typePins)[i];
                if (!pin) continue;
                std::string pname = (i < cd->typeParams->size() && (*cd->typeParams)[i])
                                  ? *(*cd->typeParams)[i] : std::string("?");
                // `is` names an IDENTITY, and the only identity a contract can name is its implementer.
                // A concrete type here (`<T is Widget>`) would be a subtype bound — a different feature,
                // and one that makes inheritance the extension seam for generic code. Not this slot.
                if (!pin->value || *pin->value != "This")
                    unsupported(("`is` constrains a type parameter to the implementing type, so its "
                                 "operand must be `This` — `" + pname + " is "
                                 + (pin->value ? *pin->value : std::string("?")) + "`").c_str(), cd->line);
                else if (!pin->bounds || pin->bounds->empty()) {
                    if (ii.pinnedParam >= 0) {
                        // Both would be forced equal to the implementer, so the second says nothing.
                        SharedString first = (*cd->typeParams)[ii.pinnedParam];
                        unsupported(("a contract pins at most one type parameter to `This` — `" + ii.name
                                     + "` already pins `" + (first ? *first : std::string("?")) + "`, so `"
                                     + pname + "` is redundant").c_str(), cd->line);
                    }
                    else if (i != 0)
                        // The pinned parameter IS the contract's subject, so it reads first — and that
                        // keeps `implements C<This, …>` uniform at every conformance site.
                        unsupported(("the `This`-pinned type parameter must come first — move `" + pname
                                     + " is This` to the front of `" + ii.name + "`'s parameter list").c_str(),
                                    cd->line);
                    else ii.pinnedParam = (int)i;
                }
            }
        if (cd->typeParams && !cd->typeParams->empty()) {
            std::vector<std::string> ps;
            for (auto& p : *cd->typeParams) if (p) ps.push_back(*p);
            _genericContractParams[ii.name] = ps;
            if (cd->typeDefaults) _genericContractDefaults[ii.name] = *cd->typeDefaults;
            _genericContractCtx[ii.name]    = _nsCtx;
            _genericContracts[ii.name]      = ii;
        } else {
            _interfaces[ii.name] = ii;
        }
    }
}

// Collect enum declarations.
// an `enum` is a tagged union (discriminated union) if any variant carries a payload, or it
// is generic (parameterized, so it can't be a bare C `enum`). A plain, non-generic, payloadless enum
// stays a C integer.
static bool enumIsTagged(EnumDeclarationNode* ed)
{
    if (ed->typeParams && !ed->typeParams->empty()) return true;
    if (ed->body)
        for (auto& m : *ed->body)
            if (m->payload && !m->payload->empty()) return true;
    return false;
}

// Build the ClassInfo backing a payload/generic enum — a discriminant tag + a union of the
// per-variant payloads. Reuses ClassInfo so monomorphization, RAII, and move analysis all apply.
// A variant is flagged `isVariant`; its move-only-ness follows destructibility (owns a resource →
// moves), not the `kind` (which stays the neutral `Intrinsic`).
// The line of whichever declaration produced this ClassInfo. An enum's ClassInfo has an `enumNode` and a NULL
// `node` (that one is a ClassDeclarationNode), so anything reporting a diagnostic against a type must come
// through here rather than dereferencing `node`.
int ClassInfo::declLine() const { return node ? node->line : (enumNode ? enumNode->line : 0); }
ClassBaseDeclarationNode* ClassInfo::baseTypesDecl() const
{
    return node ? node->baseTypes.get() : (enumNode ? enumNode->baseTypes.get() : nullptr);
}

ClassInfo CEmitter::buildVariantClassInfo(EnumDeclarationNode* ed, const std::string& name)
{
    ClassInfo ci;
    ci.name      = name;
    ci.kind      = TypeKind::Neutral;   // move-only-ness is driven by isVariant + destructible
    ci.enumNode  = ed;                  // its decl site; `ci.node` stays null (that is a ClassDeclarationNode)
    ci.scope     = _nsCtx.scope;
    ci.usings    = _nsCtx.usings;
    ci.symbolAliases = _nsCtx.symbolAliases;
    ci.isVariant = true;
    ci.tagCType  = ed->underlyingType ? cType(ed->underlyingType) : "";
    if (ed->body)
        for (auto& m : *ed->body) {
            if (!m->identifier || !m->identifier->value) continue;
            VariantCase vc;
            vc.name = *m->identifier->value;
            if (m->payload)
                for (auto& p : *m->payload)
                    if (p && p->identifier && p->identifier->value) {
                        FieldInfo fi;
                        fi.name = *p->identifier->value;
                        fi.nameId = p->identifier;
                        fi.type = p->type;
                        vc.payload.push_back(fi);
                    }
            ci.variants.push_back(vc);
        }
    return ci;
}

// An enum's key in `_enums`/`_classes`: its module-qualified name, except a `type extern enum`, which keeps its
// literal C name.
std::string CEmitter::enumKey(EnumDeclarationNode* ed)
{
    const std::string& bare = *ed->identifier->value;
    return enumHasModifier(ed, "extern") ? bare : qualify(bare);
}

// The integer form of a payload-less enum, under the current name-resolution context: its members in
// declaration order (values folded later, by foldEnumMembers) and its `: IntType` width.
EnumInfo CEmitter::scalarEnumInfo(EnumDeclarationNode* ed, const std::string& name, const std::string& declFile)
{
    EnumInfo ei;
    ei.name  = name;
    ei.line = ed->line;
    ei.scope = _nsCtx.scope;
    ei.usings = _nsCtx.usings;
    ei.symbolAliases = _nsCtx.symbolAliases;
    ei.underlyingCType = ed->underlyingType ? cType(ed->underlyingType) : "";   // `: IntType`
    if (ed->body)
        for (auto& m : *ed->body)
            if (m->identifier && m->identifier->value) {
                EnumMember em;
                em.name  = *m->identifier->value;
                em.value = m->constantExpression;   // folded later, by foldEnumMembers
                em.line  = m->line;
                ei.members.push_back(em);
            }
    ei.declFile = declFile;
    return ei;
}

void CEmitter::collectEnums(SharedCompilationUnit unit)
{
    if (!unit || !unit->codeDeclarationList) return;
    for (auto& decl : *unit->codeDeclarationList) {
        auto* ed = dynamic_cast<EnumDeclarationNode*>(decl.get());
        if (!ed || !ed->identifier || !ed->identifier->value) continue;
        rejectPinOutsideContract(ed->typePins, ed->typeParams, "an enum", ed->line);
        const bool isExtern = enumHasModifier(ed, "extern"), isExpose = enumHasModifier(ed, "expose");
        const std::string& bare = *ed->identifier->value;
        // KR-55: who owns an enum's values at the C boundary — a C header (`extern`) or kama (`expose`).
        if (isExtern || isExpose) {
            const char* mk = isExtern ? "extern" : "expose";
            bool shapeOk = false;
            if (isExtern && isExpose)
                unsupported(("`" + bare + "` is both `extern` and `expose` — `extern` binds an enum a C header "
                             "defines, `expose` publishes one kama defines, and one side owns its values").c_str(), ed->line);
            else if (enumIsTagged(ed))
                unsupported(("`type " + std::string(mk) + " enum " + bare + "` cannot be generic or carry payloads — "
                             "a C enum is a set of integer constants; a tagged union has no C spelling").c_str(), ed->line);
            else if (!ed->underlyingType)
                unsupported(("`type " + std::string(mk) + " enum " + bare + "` must state its width (`: int32`, "
                             "`: uint32`, …) — C leaves an enum's size to the compiler, so the crossing states "
                             "it and the build checks it").c_str(), ed->line);
            else shapeOk = true;
            if (shapeOk && ed->body)
                for (auto& m : *ed->body) {
                    if (!m || !m->identifier || !m->identifier->value) continue;
                    if (isExtern && m->constantExpression)
                        unsupported(("`" + bare + "::" + *m->identifier->value + "` writes a value, but `" + bare
                                     + "` is a `type extern enum` — its values are the C header's. Name the "
                                       "constant and leave the number to C").c_str(), m->line);
                    if (isExpose && !m->constantExpression)
                        unsupported(("`" + bare + "::" + *m->identifier->value + "` has no value, but `" + bare
                                     + "` is a `type expose enum` — the host header publishes every value, so each "
                                       "is written out: inserting a variant must not renumber one a host compiled "
                                       "against").c_str(), m->line);
                }
        }
        std::string name = enumKey(ed);
        _enumDeclNodes[name] = ed;   // the LSP def-site table's only source for enums
        if (unit == _preludeUnit) _preludeEnums.insert(name);

        // Layout control is not offered on an enum, and saying so is the point: the `@generate` loops
        // below `continue` past every name they do not recognize, so `@packed type enum` compiled clean
        // with the attribute silently DROPPED. A payload-less enum has no struct to attach one to, and a
        // tagged one has a per-variant payload struct plus a union that a `packed` on the outer struct
        // would not reach — so one rejection is the honest answer, not an attribute that half works.
        // Placed before the tagged/plain fork so it covers both, which the `@generate` loops do not.
        if (ed->attributes)
            for (auto& at : *ed->attributes)
                if (at && at->name && (*at->name == "align" || *at->name == "packed"))
                    unsupported(("`@" + *at->name + "` controls the layout of a struct, and an `enum` has "
                                 "none to control: a payload-less one lowers to an integer, and a tagged "
                                 "one to a tag plus a per-variant union. To fix an enum's tag width write "
                                 "`type enum E : IntType`").c_str(), ed->line);
        // ...and every OTHER name is refused too, for the same reason: the `@generate` loops skip what they do not
        // recognize, so `@linkName` on a plain enum (or a typo'd `@genrate`) compiled clean and did nothing.
        if (ed->attributes)
            for (auto& at : *ed->attributes) {
                if (!at || !at->name || *at->name == "align" || *at->name == "packed" || *at->name == "generate") continue;
                if (*at->name == "linkName") {
                    if (!enumHasModifier(ed, "expose"))
                        unsupported("`@linkName` names what a host sees, and only a `type expose enum` has a host-visible "
                                    "name to fix — a `type extern enum` is the header's own name already", ed->line);
                    continue;
                }
                unsupported(("unknown enum attribute `@" + *at->name + "` (expected `@generate`, or `@linkName` on a "
                             "`type expose enum`)").c_str(), ed->line);
            }

        if (enumIsTagged(ed)) {
            // a payload/generic enum is a discriminated union backed by a ClassInfo.
            ClassInfo ci = buildVariantClassInfo(ed, name);
            ci.declFile = unit && unit->name ? *unit->name : std::string();
            // The `@generate` flags are read ABOVE the template/concrete fork, because a generic enum
            // needs them on its TEMPLATE. Reading them inside the concrete branch is why `@generate` on
            // a generic enum was not refused but SILENTLY IGNORED: the attribute parsed nowhere, the
            // program built, and the missing conformance surfaced much later as `==` complaining that
            // `Msg<int32>` "needs `implements Equatable`". The flags come off the ONE accept-list; what
            // they MEAN is decided by registerDerives, below for a concrete enum and per instance for a
            // generic one.
            if (ed->attributes)
                for (auto& at : *ed->attributes)
                    if (at && at->name && *at->name == "generate") parseGenerateAttr(at, ci, ed->line);
            const bool anyDerive = ci.genSerialize || ci.genDeserialize || ci.genFormat
                                || ci.genEquatable || ci.genHashable || ci.genOf || ci.genZero;
            if (ed->typeParams && !ed->typeParams->empty()) {
                // Generic enum (Optional<T>): a monomorphization TEMPLATE, kept OUT of _classes —
                // each `Optional<Arg>` becomes a specialized ClassInfo at discovery (registerGenericTypeInst).
                // ⚠️ The FLAGS ride along on the template and nothing else does: registerDerives is never
                // called here. The instance is a whole-struct copy of the template, so a conformance
                // minted at the template would be inherited — identically, and identically wrong — by
                // every instance, when the whole point is that each instance answers for its own payload.
                std::vector<std::string> ps;
                for (auto& p : *ed->typeParams) if (p) ps.push_back(*p);
                _genericTypeParams[name] = ps;
                _genericTypeBounds[name] = ed->typeBounds;
                if (ed->constTypes) _genericTypeConstTypes[name] = *ed->constTypes;
                if (ed->typeDefaults) _genericTypeDefaults[name] = *ed->typeDefaults;
                _genericTypeCtx[name]    = _nsCtx;
                _genericTypes[name]      = ci;
            } else {
                if (anyDerive) registerDerives(ci, ed->identifier, ed->line);
                // A TAGGED prelude enum's bodies are emitted `static inline` by the `_preludeEnums` loop in
                // the end pass, so its prototypes must carry the same linkage. collectEnumConformances sets
                // `preludeStatic` too, but only for an enum that declares members, `implements` or
                // `@generate` — it returns early otherwise. A prelude enum that declares NONE of those and
                // still owns a payload (`FieldKey { Name(string), Id(uint32) }`) reached the end pass with a
                // static-inline dtor definition and non-static prototypes, which clang refuses outright
                // ("static declaration of 'FieldKey__dtor' follows non-static declaration"). Nothing hit it
                // before because no prelude enum was both payload-carrying and destructible.
                if (unit == _preludeUnit) ci.preludeStatic = true;
                _classes[name] = ci;
            }
            continue;
        }

        // A payload-less enum carrying `@generate` is NOT derived here: collectEnumConformances gives it the
        // member ClassInfo a conformance and a method live on — as it does for one that declares
        // `implements` — and reads the attribute itself. The enum stays this bare C integer either way.
        // Plain C-style enum — the existing lightweight path (bare integer, zero regression).
        EnumInfo ei = scalarEnumInfo(ed, name, _collectingUnitPath);
        ei.isExtern = isExtern;
        ei.isExpose = isExpose;
        if (isExpose) ei.hostName = linkNameOf(ed->attributes, ed->line);
        if (isExtern) {
            if (!ei.declFile.empty()) _externDeclSites[name].insert(ei.declFile);
            // ONE C enum, so every declaration of it in a program must agree — the rule a repeated
            // `type extern value` and `extern fn` already follow. A declaration may be repeated where it is
            // used; a different width or constant list would decide how BOTH files read the type.
            auto prev = _enums.find(name);
            if (prev != _enums.end() && prev->second.isExtern && !prev->second.declFile.empty()
                && prev->second.declFile != ei.declFile) {
                std::string names, prevNames;
                for (auto& m : ei.members) names += " " + m.name;
                for (auto& m : prev->second.members) prevNames += " " + m.name;
                if (prev->second.underlyingCType != ei.underlyingCType || names != prevNames)
                    unsupported(("this `type extern enum " + name + "` disagrees with the one in `" + prev->second.declFile
                                 + "` — `" + name + "` is ONE C enum, so every declaration of it in a program must "
                                   "declare the same width and the same constants, in the same order").c_str(), ed->line);
            }
        }
        _enums[ei.name] = ei;
    }
}

bool CEmitter::enumHasModifier(const EnumDeclarationNode* ed, const char* mod)
{
    if (ed && ed->modifiers)
        for (auto& m : *ed->modifiers)
            if (m && m->value && *m->value == mod) return true;
    return false;
}

// Validate one `@align(N)` / `@packed` and fold it into a type's layout state.
//
// `N` must be a power of two: that is C's own rule for `__attribute__((aligned(N)))`, and a value that is
// not one is silently rounded UP by gcc/clang rather than rejected — so `@align(3)` would compile and
// quietly mean 4. Refusing it here is the difference between kama stating a layout and kama appearing to.
// The 4096 ceiling is a page; nothing an aggregate needs goes past it, and an absurd value is far more
// likely a typo than an intent.
void CEmitter::readLayoutAttr(const AttributeNode& at, int& alignN, bool& packed, int line)
{
    const bool isAlign = at.name && *at.name == "align";
    const size_t nargs = at.args ? at.args->size() : 0;
    if (!isAlign) {
        if (nargs) { unsupported("`@packed` takes no arguments — it removes padding, it does not set a "
                                 "width. To set an alignment use `@align(N)`", line); return; }
        packed = true;
        return;
    }
    // A bare NUMBER, which is the only attribute-argument form that carries one (see attr_arg in kama.y).
    int64_t n = 0;
    SharedExpression arg = (nargs == 1 && at.args->front()) ? at.args->front()->expression : SharedExpression();
    const bool bare = arg && (!at.args->front()->name);
    if (!bare || !constValue(arg, n)) {
        unsupported("`@align(N)` needs one literal number — the alignment in bytes, e.g. `@align(16)`", line);
        return;
    }
    if (n < 1 || n > 4096 || (n & (n - 1)) != 0) {
        unsupported(("`@align(" + std::to_string(n) + ")` — an alignment must be a power of two from 1 to "
                     "4096. A C compiler rounds a non-power-of-two UP rather than refusing it, so this "
                     "would quietly mean something else").c_str(), line);
        return;
    }
    alignN = (int)n;
}

// enum Name { Name_M0, Name_M1 = <expr>, … }
void CEmitter::emitEnum(EnumInfo& ei)
{
    // A C enum: nothing is declared — the header already did — and kama's own constant spelling
    // (`<Enum>_<Member>`, which every use site, `match` arm and `try cast` emits) is an ALIAS for the C constant
    // of that exact name. So the values are the header's by construction, a constant the header does not define
    // fails to compile naming it, and the declared width is held to the C type's size.
    if (ei.isExtern) {
        const std::string at = ei.declFile + ":" + std::to_string(ei.line);
        *_out << "_Static_assert(sizeof(" << ei.name << ") == sizeof(" << ei.underlyingCType << "), \"kama: `type extern enum "
              << ei.name << " : " << primKeyOfCType(ei.underlyingCType) << "` (" << cEscapeStringBody(at)
              << ") — the C enum is not that size; state the width the header's type has\");\n";
        for (auto& m : ei.members) *_out << "#define " << ei.name << "_" << m.name << " (" << m.name << ")\n";
        *_out << "\n";
        return;
    }
    // `enum Name : IntType` pins the value to a fixed-width integer. ISO C can't set an enum's
    // underlying type, so emit `typedef <ctype> Name;` + an anonymous enum carrying the constants.
    if (!ei.underlyingCType.empty()) {
        *_out << "typedef " << ei.underlyingCType << " " << ei.name << ";\n";
        *_out << "enum {\n";
        for (auto& m : ei.members) {
            indent(1);
            *_out << ei.name << "_" << m.name;
            if (m.value && m.hasFolded) *_out << " = " << m.folded;   // the FOLDED value — see EnumMember
            *_out << ",\n";
        }
        *_out << "};\n\n";
        return;
    }
    *_out << "typedef enum " << ei.name << " {\n";
    for (auto& m : ei.members) {
        indent(1);
        *_out << ei.name << "_" << m.name;
        if (m.value && m.hasFolded) *_out << " = " << m.folded;
        *_out << ",\n";
    }
    *_out << "} " << ei.name << ";\n\n";
}

// bind `_thisType` (what `This` resolves to) for a scope, restoring on exit (survives early
// returns / loop `continue`s). Used across signature collection and class/interface emission.
namespace {
// Bind `This` as an ordinary entry in `_typeSubst` for a scope. That is the whole claim this campaign
// rests on: `This` IS a type parameter, so binding it where a conformance is resolved makes every existing
// substitution path — cType, mangleElem, deepSubstType — resolve it with no new special case. Needed
// because a pinned conformance writes its argument as `This` (`implements C<This>`), and the instance it
// mints has to record the IMPLEMENTING type; recording the literal word files the vtable under
// `C__as_C_This` while every use site asks for `C__as_C_<Type>`.
struct ScopedThis { std::map<std::string, SharedIdentifier>& m; bool had; SharedIdentifier prev;
    ScopedThis(std::map<std::string, SharedIdentifier>& m_, SharedIdentifier v) : m(m_) {
        auto it = m.find("This"); had = it != m.end(); if (had) prev = it->second;
        if (v) m["This"] = v; else if (had) m.erase("This");
    }
    ~ScopedThis() { if (had) m["This"] = prev; else m.erase("This"); } }; }

// Build the class table: ordered fields, methods, and the (single) constructor.
// Register the conformances and synthesized methods a type's `@generate(...)` asks for.
//
// One function for every subject that can carry the attribute, because the attribute means the same
// thing on each: a plain type (from collectClasses, where this always lived) and a generic INSTANCE
// (from registerGenericTypeInst, once its fields are substituted concrete). The four "not a generic"
// refusals that used to stand where the call now is are gone — a generic type derives per
// instantiation, which is the only place its fields have types to walk.
//
// `selfNode` is the type node this type is spelled by — the declaration's name for a plain type, a
// synthesized identifier naming the instance for a generic one. It is what the fallible `deserialize`
// builds its `Result<This, Owned<Error>>` from and what a bag ctor returns, so passing it in is what
// lets one function serve both callers.
//
// ⚠️ CONDITIONAL BY FIELD, for an instance. `@generate(Equatable)` on `Box<T>` cannot hold for every
// `T` — `Box<Handle>` has no `equals` to walk into — so an instance registers a derive only when every
// substituted field satisfies it, which is Rust's `impl<T: PartialEq> PartialEq for Box<T>` and
// Haskell's `instance Eq a => Eq (Box a)`. The condition is not written by the author because it is not
// the author's choice: it is a mechanical consequence of the fields, and kama's own `when [T: Bound]`
// exists for the case where a type says something a field walk cannot derive. A use on an instance that
// does not qualify is refused at the USE site, naming the field that disqualified it (`derivedUnmet`).
//
// A plain type keeps the stricter rule it always had — an unmet field is an error at the DECLARATION,
// because there is exactly one subject and the author can see it. The body emitters carry those checks
// (eqFieldTest, emitFmtFieldWrite, serdeRejectsField), so nothing here duplicates them.
std::string CEmitter::derivedUnmetNote(const std::string& cty, const std::string& bound)
{
    auto it = _classes.find(cty);
    if (it == _classes.end()) return "";
    // The serde bounds have two answers of their own. A graph node is never a by-value `Serializable`
    // (it can alias, cycle, or hold a `Weak` back-edge — none survive a by-value return), and `Shared<T>`
    // is not the spelling of a root: both name the type that is, so the author is not left to hunt.
    // `Shared<X>` IS how a graph comes back — the root arrives behind a handle because a cycle cannot be
    // returned by value — but only when `X` is a node. Name the half that is missing rather than the
    // spelling, which is already right.
    if (bound == "Deserializable" && it->second.graphDeserialize)
        return " — `" + demangleForDisplay(cty) + "` reaches a `Shared`/`Weak` field, so it is a graph and "
               "cannot be read by value: a cycle has nowhere to point if the root is a stack value. Read it "
               "as `Shared<" + demangleForDisplay(cty) + ">`";
    if (bound == "Serializable" || bound == "Deserializable") {
        auto g = _genericTypeInstOf.find(cty);
        bool shared = (g != _genericTypeInstOf.end() && g->second == _sharedTmpl)
                   || (isSmartPtrClass(cty) && smartKind(cty) == CollKind::Shared);
        if (shared) {
            const std::string x = sharedPointeeClass(cty);
            return " — a graph is read back as `Shared<T>`, and "
                 + (x.empty() ? std::string("its pointee") : "`" + demangleForDisplay(x) + "`")
                 + " is not a graph node: a node is `@generate(Deserializable)` and reaches a `Shared`/`Weak` "
                   "field. A pointer-free type is read by value, with no handle";
        }
    }
    auto u = it->second.derivedUnmet.find(bound);
    if (u == it->second.derivedUnmet.end()) return "";
    // Name the TEMPLATE, not the instance: the attribute is written once, on `Box<T>`, and that is the
    // line the author will go to.
    std::string tmpl = cty;
    auto of = _genericTypeInstOf.find(cty);
    if (of != _genericTypeInstOf.end()) tmpl = of->second;
    return " — `@generate(" + bound + ")` on `" + demangleForDisplay(tmpl) + "` holds for an instance "
           "whose every field conforms, and " + u->second + " does not implement `" + bound + "`. Derive "
           "or implement `" + bound + "` for that field, or write the conformance on this instance by hand";
}

// One `@generate(...)` attribute, read onto `ci`'s derive flags. THE accept-list — there is exactly one,
// which is the point: the enum path used to carry its own two-name copy (`Serializable, Deserializable`),
// so the four newer derives were not "unsupported on an enum", they were unknown to a second parser that
// nobody remembered to grow. What each flag then means is decided in registerDerives, once, for every
// subject. The caller decides WHERE the flags land — for a generic they land on the TEMPLATE, and the
// instance is what registers a conformance.
void CEmitter::parseGenerateAttr(const SharedAttribute& at, ClassInfo& ci, int line)
{
    static const char* kNames = "Serializable, Deserializable, Formattable, Equatable, Hashable, of, zero";
    if (!at || !at->name || *at->name != "generate") return;
    if (!at->args || at->args->empty()) {
        unsupported((std::string("`@generate(...)` needs at least one of ") + kNames).c_str(), line);
        return;
    }
    for (auto& a : *at->args) {
        // bare identifier args only (Serializable/Deserializable/of/zero); a `key: value` form is invalid here
        std::string which = (a && a->name && a->name->value && !a->expression) ? *a->name->value : "";
        if      (which == "Serializable")   ci.genSerialize = true;
        else if (which == "Deserializable") ci.genDeserialize = true;
        else if (which == "of")   ci.genOf = true;     // bag ctor — validated + registered after fields
        else if (which == "zero") ci.genZero = true;
        else if (which == "Formattable") ci.genFormat = true;   // field-dump Formattable impl
        // Memberwise `equals` / field-walked `hash` + the nominal conformance — so a data bag
        // becomes comparable (and a `Map` key) without hand-rolling an FNV loop. Rust's
        // `#[derive(PartialEq, Hash)]`. Registered + validated once the fields are known.
        else if (which == "Equatable") ci.genEquatable = true;
        else if (which == "Hashable")  ci.genHashable = true;
        else unsupported((std::string("`@generate(...)` accepts only ") + kNames).c_str(), line);
    }
}

// True when this declaration carries a `@generate(...)` at all — asked by collectEnumConformances, which
// has to decide whether a payload-less enum needs a member ClassInfo BEFORE anything has parsed its attributes.
bool CEmitter::hasGenerateAttr(const SharedAttributeList& attrs)
{
    if (attrs)
        for (auto& at : *attrs)
            if (at && at->name && *at->name == "generate") return true;
    return false;
}

void CEmitter::registerDerives(ClassInfo& ci, SharedIdentifier selfNode, int line)
{
    // Every derive this type asked for that its FIELDS cannot support, for an instance whose conformance
    // is therefore conditional. Empty for a plain type, which errors instead.
    if (ci.isGenericInst) {
        auto unmet = [&](const char* bound) -> std::string {
            auto bad = [&](const FieldInfo& f) -> bool {
                if (f.serSkip) return false;              // `@skip` is out of the walk entirely
                if (!f.type) return false;
                // ⚠️ `primKey`, NOT `cType`. It hops `_typeSubst` (so the template's `T` answers as the
                // instance's argument) and it returns the KAMA name for a scalar, which is the key a
                // primitive's conformance is filed under — `_intrinsicConformances["int32"]`, never
                // `"int32_t"`. Asking with the C spelling reports every primitive as non-conforming, so
                // the first draft of this rule disqualified `Box<int32>` from every derive it asked for.
                // For a user type primKey falls through to `cType`, which is that key.
                const std::string k = primKey(f.type);
                if (k.empty() || opaqueScalarUnknown(k)) return false;   // nothing known — do not guess
                return !satisfiesBound(k, bound);
            };
            for (auto& f : ci.fields)
                if (bad(f)) return "field `" + f.name + "` (`" + demangleForDisplay(primKey(f.type)) + "`)";
            for (auto& v : ci.variants)
                for (auto& f : v.payload)
                    if (bad(f)) return "`" + v.name + "`'s field `" + f.name
                                     + "` (`" + demangleForDisplay(primKey(f.type)) + "`)";
            return "";
        };
        auto drop = [&](bool& flag, const char* bound) {
            if (!flag) return;
            std::string why = unmet(bound);
            if (why.empty()) return;
            flag = false;
            ci.derivedUnmet[bound] = why;
        };
        drop(ci.genEquatable,   "Equatable");
        drop(ci.genHashable,    "Hashable");
        drop(ci.genFormat,      "Formattable");
        drop(ci.genSerialize,   "Serializable");
        drop(ci.genDeserialize, "Deserializable");
    }
    // Register the nominal conformance whenever `@generate` opts in — INDEPENDENT of whether the
    // body is synthesized. A hand-written `serialize`/`deserialize` (e.g. a user `ctor deserialize`)
    // still lands the type in `ci.methods`, so the `!count` guard below skips only the BODY synth;
    // the type must still satisfy the `Serializable`/`Deserializable` bound (`decode::<T>` checks it).
    // ⚠️ A derived conformance is a WHOLE conformance, on an enum exactly as on a `value` — it does NOT
    // go into `staticOnlyInterfaces`. The enum path used to put it there, reasoning that "an enum cannot
    // carry a fat-pointer method", and that reasoning is simply false: `emitClassInterfaceVtables` runs
    // for an enum (that is how `type enum E implements Error` gets dynamic dispatch), and the emitter
    // will happily box one into a contract existential. What static-only did was suppress the
    // `<Enum>__as_<C>` vtbl the boxing then referenced — so `encode(v: msg)`, whose parameter IS the
    // `Serializable` existential, emitted a call naming a symbol nothing defined and failed in CLANG.
    // Consumer bug KB-18: the one obvious thing to do with a derived message type was the one thing that
    // did not work, while the same value as a FIELD (reached statically through a `when [T: Serializable]`
    // clause) round-tripped fine. A derive registers what the derive needs.
    auto hasItf = [&](const std::string& n) { for (auto& i : ci.interfaces) if (i == n) return true; return false; };
    auto addItf = [&](const std::string& n) { if (!hasItf(n)) ci.interfaces.push_back(n); };
    // Wire keys must be unique before anything is emitted from them. Here rather than in the attribute
    // loop because that loop runs per DECLARATION and cannot see a sibling's key; here rather than at the
    // one call site because this is the funnel every path reaches — a plain type, a generic INSTANCE
    // (registerGenericTypeInst), and an enum with members. A no-op for a type that serializes nothing.
    if (ci.genSerialize || ci.genDeserialize) validateSerFieldKeys(ci, line);
    if (ci.genSerialize) {
        addItf("Serializable");
        if (!ci.methods.count("serialize")) {
            MethodInfo mi; mi.cName = ci.name + "__serialize"; mi.visibility = Visibility::Public;
            mi.isSynthSer = true; mi.isConst = true;   // writes to `w`, reads `this`
            mi.returnType = resultUnitOwnedErrorTypeNode();   // P4: fallible `Result<Unit, Owned<Error>>`
            scanTypeForCollections(mi.returnType);   // monomorphize Result<Unit, Owned<Error>>
            ParamSig w; w.name = "w"; w.byRef = true; w.className = "Serializer"; mi.params.push_back(w);
            ci.methods["serialize"] = mi;   // `fn Result<Unit, Owned<Error>> serialize(ref Serializer w)`
        }
    }
    if (ci.genDeserialize) {
        addItf(synthConformanceName("Deserializable", ci.name));
        if (!ci.methods.count("deserialize")) {
            MethodInfo mi; mi.cName = ci.name + "__deserialize"; mi.visibility = Visibility::Public;
            // P4: the synth deserialize is a FALLIBLE ctor `Result<This, Owned<Error>>` — reading crosses
            // a trust boundary. (The graph two-pass returns `Result<Shared<This>, Owned<Error>>`; its
            // return node is rebuilt in computeGraphNodeTypes.)
            mi.isStatic = true; mi.isSynthDe = true; mi.isCtor = true;
            mi.returnType = resultOwnedErrorTypeNode(selfNode);
            scanTypeForCollections(mi.returnType);   // monomorphize Result<This, Owned<Error>>
            ParamSig r; r.name = "r"; r.byRef = false; r.className = "Deserializer"; mi.params.push_back(r);
            ci.methods["deserialize"] = mi;   // `ctor Result<This, Owned<Error>> deserialize(Deserializer r)`
            ci.ctors["deserialize"] = CtorInfo{ nullptr, mi.params, Visibility::Public, true, mi.returnType };
        }
    }
    // Nothing graph-specific is registered here. A graph node keeps exactly the pair declared above —
    // `serialize`/`deserialize`, the same two members and the same two conformances a by-value type has —
    // and computeGraphNodeTypes later retargets `deserialize`'s RESULT to `Result<Shared<This>, …>`, because
    // a graph root comes back as a handle. The walk itself is emitted as internal C helpers keyed off
    // `isGraphNode`, so a node type carries no extra public surface at all.
    // `@generate(Formattable)` — a synthesized infallible field-dump `fn void format(ref Formatter f)`
    // (`Type { f1: v1, … }`). The display analog of Serializable: register the nominal `Formattable`
    // conformance + the synth method; a hand-written `format` wins via the `!count` guard (body only).
    // returnType stays null -> cType(null) == "void".
    if (ci.genFormat) {
        addItf("Formattable");
        if (!ci.methods.count("format")) {
            MethodInfo mi; mi.cName = ci.name + "__format"; mi.visibility = Visibility::Public;
            mi.isSynthFormat = true; mi.isConst = true;   // the dump writes to `f`, never to `this`
            if (!_synthCtx) _synthCtx = std::make_shared<CodeGenContext>(std::make_shared<std::string>("<synth>"));
            mi.returnType = synthId("void", IDENTIFIER_VOID_VAL);
            ParamSig f; f.name = "f"; f.byRef = true; f.className = "Formatter"; mi.params.push_back(f);
            ci.methods["format"] = mi;   // `fn void format(ref Formatter f)`
        }
    }
    // `@generate(of|zero)` bag ctors (M6) — BAG-ONLY: a transparent `value` (all public fields). `of`
    // = a synthesized memberwise ctor `V.of(f1: …, …)`; `zero` = a zero-init ctor `V.zero()`. Both are
    // infallible named ctors (returnType = the enclosing type), registered in `ctors`/`methods` and
    // emitted by emitBagCtorBody. A hand-written `of`/`zero` wins via the `!methods.count` guard.
    if (ci.genOf || ci.genZero) {
        // On an enum this is a NON-GOAL, not a gap, and the message says which: a variant already IS its
        // own memberwise constructor (`Shape::Circle(r: 2)` names the tag and takes the payload), so `of`
        // would be a second spelling of the one that exists — and `zero` names no variant at all, since
        // an enum has no "all fields zeroed" state, only a choice between tags.
        if (ci.isVariant || ci.isScalarEnum())
            unsupported("`@generate(of, zero)` is not offered on an `enum`: a variant is already its own "
                        "memberwise constructor (`E::Variant(field: …)`), and `zero` names no variant. "
                        "Construct the one you mean", line);
        else if (ci.kind != TypeKind::Value)
            unsupported("`@generate(of, zero)` applies only to a `value` whose fields are all public "
                        "(a data bag) — not a `resource`, `view`, or `enum`", line);
        else if (!isTransparentValue(ci)) {
            std::string bad;
            for (auto& f : ci.fields) if (f.visibility != Visibility::Public) { bad = f.name; break; }
            unsupported(("`@generate(of, zero)` needs an all-public `value` (a data bag); field '"
                         + bad + "' is not public").c_str(), line);
        } else {
            if (ci.genOf && !ci.methods.count("of")) {
                MethodInfo mi; mi.cName = ci.name + "__of"; mi.visibility = Visibility::Public;
                mi.isStatic = true; mi.isCtor = true; mi.isSynthBag = true; mi.returnType = selfNode;
                for (auto& f : ci.fields) {
                    ParamSig ps; ps.name = f.name; ps.byRef = false; ps.className = cType(f.type);
                    mi.params.push_back(ps);
                }
                ci.methods["of"] = mi;
                ci.ctors["of"] = CtorInfo{ nullptr, mi.params, Visibility::Public, false, selfNode };
            }
            if (ci.genZero && !ci.methods.count("zero")) {
                // A `value` owns nothing (the "a value owns nothing" rule rejects an `Owned`/`Shared`
                // field before we get here), so zero-init is always a valid, never-null state.
                MethodInfo mi; mi.cName = ci.name + "__zero"; mi.visibility = Visibility::Public;
                mi.isStatic = true; mi.isCtor = true; mi.isSynthBag = true; mi.returnType = selfNode;
                ci.methods["zero"] = mi;
                ci.ctors["zero"] = CtorInfo{ nullptr, {}, Visibility::Public, false, selfNode };
            }
        }
    }
    // `@generate(Equatable|Hashable)` — memberwise `equals` / field-walked `hash`, plus the nominal
    // conformance. Since comparison is contract-driven, deriving `Equatable` is also what gives the
    // type its `==`/`!=`; deriving `Hashable` alongside it makes the type a `Map`/`Set` key without
    // hand-rolling an FNV loop. Structural equality remains OPT-IN — that is the whole stance; the
    // attribute is where you ask for it. A hand-written `equals`/`hash` wins via the `!count` guard
    // (body only — the conformance is still registered). Per-field conformance is checked at emit,
    // like `@generate(Formattable)`, because impl blocks are not all collected yet at this point.
    if (ci.genEquatable) {
        // `Equatable` PINS its parameter, so the conformance is recorded as `Equatable_<Type>`.
        // There is no source node here to carry `<This>` — the attribute is the whole declaration —
        // so the instance is named AND MINTED here, by synthConformanceName. Naming it without minting
        // is what "unknown contract in implements" means: the vtable emit resolves the name and finds
        // nothing. A plain type used to be rescued by a separate mint in the collect sweep, which walks
        // ClassDeclarationNodes and so could never reach a generic INSTANCE; one call covers both, and
        // the sweep's special case is gone.
        std::string eqName = synthConformanceName(resolveUserName("Equatable", nullptr), ci.name);
        addItf(eqName);
        if (!ci.methods.count("equals")) {
            MethodInfo mi; mi.cName = ci.name + "__equals"; mi.visibility = Visibility::Public;
            mi.isSynthCmp = true; mi.isConst = true;   // a derived comparison reads `this` and nothing else
            if (!_synthCtx) _synthCtx = std::make_shared<CodeGenContext>(std::make_shared<std::string>("<synth>"));
            mi.returnType = synthId("bool", IDENTIFIER_BOOL_VAL);
            ParamSig o; o.name = "other"; o.byRef = true; o.isConst = true;   // `Equatable` borrows
            o.className = ci.name; mi.params.push_back(o);                   // the operand read-only
            ci.methods["equals"] = mi;   // `fn bool equals(ref This other)`
        }
    }
    if (ci.genHashable) {
        addItf("Hashable");
        if (!ci.methods.count("hash")) {
            MethodInfo mi; mi.cName = ci.name + "__hash"; mi.visibility = Visibility::Public;
            mi.isSynthCmp = true; mi.isConst = true;   // ditto — a hash is a pure read of the fields
            if (!_synthCtx) _synthCtx = std::make_shared<CodeGenContext>(std::make_shared<std::string>("<synth>"));
            mi.returnType = synthId("uint64", IDENTIFIER_UINT64_VAL);
            ci.methods["hash"] = mi;     // `fn uint64 hash()`
        }
    }
}

void CEmitter::collectClasses(SharedCompilationUnit unit)
{
    if (!unit || !unit->codeDeclarationList) return;
    for (auto& decl : *unit->codeDeclarationList) {
        auto* cd = dynamic_cast<ClassDeclarationNode*>(decl.get());
        if (!cd || !cd->name || !cd->name->value) continue;
        // A `contract`'s pin is legal and is validated in collectInterfaces; every other kind has no
        // implementer for it to name.
        if (!cd->typeKind || *cd->typeKind != "contract")
            rejectPinOutsideContract(cd->typePins, cd->typeParams,
                                     ("a `type " + (cd->typeKind ? *cd->typeKind : std::string("?")) + "`").c_str(),
                                     cd->line);

        // `type <kind> Name` — map the kind word. `contract` is registered as an interface
        // (collectInterfaces), so skip it here; a bad kind word is a clear error.
        TypeKind kind = TypeKind::Neutral;
        if (cd->typeKind) {
            if      (*cd->typeKind == "value")    kind = TypeKind::Value;
            else if (*cd->typeKind == "resource") kind = TypeKind::Resource;
            // `type view` — a non-escaping borrow. It codegens exactly like a `value` (inline struct,
            // owns nothing, no dtor); the `isBorrow` flag below drives the escape check. Registering it
            // as Value means every `== TypeKind::Value` path (layout, bitwise-copy, sealed-ness) already
            // does the right thing — only the escape sites and the integrity guards branch on isBorrow.
            else if (*cd->typeKind == "view")     kind = TypeKind::Value;
            else if (*cd->typeKind == "contract") continue;   // handled as an interface
            else unsupported(("unknown type kind `" + *cd->typeKind
                              + "` — expected `value`, `resource`, `view`, or `contract`").c_str(), cd->line);
        }
        // A `for <kinds>` clause gates a CONTRACT's implementers — meaningless on a value/resource.
        if (cd->forKinds && !cd->forKinds->empty())
            unsupported("a `for` clause applies only to a `type contract` — it names the kinds that may "
                        "implement it, and a value/resource implements rather than being implemented", cd->line);

        // FFI: an `extern class`/`extern value` is an external C struct — keep its literal
        // C name (not namespace-mangled) and don't emit/own it.
        bool isExt = false, isExpose = false;
        if (cd->modifiers)
            for (auto& mod : *cd->modifiers) {
                if (mod->value && *mod->value == "extern") isExt = true;
                if (mod->value && *mod->value == "expose") isExpose = true;
            }

        ClassInfo ci;
        ci.name  = isExt ? *cd->name->value : qualify(*cd->name->value);   // scope-mangle / FFI literal name
        ci.kind  = kind;
        ci.isBorrow = cd->typeKind && *cd->typeKind == "view";   // non-escaping borrow (see escape sites)
        if (ci.isBorrow && cd->name && cd->name->value)
            _viewTypeNames.insert(*cd->name->value);   // bare name — recognizes `View(...)` in the return check
        // A non-generic prelude type (e.g. `Chars`, the codepoint iterator) has method bodies but no
        // owning module to emit them — flag it so the header emits them static-inline.
        if (unit == _preludeUnit && (!cd->typeParams || cd->typeParams->empty())) ci.preludeStatic = true;
        ci.scope = _nsCtx.scope;
        ci.usings = _nsCtx.usings;
        ci.symbolAliases = _nsCtx.symbolAliases;
        ci.declFile = unit && unit->name ? *unit->name : std::string();   // for a late whole-program check
        ci.isExternStruct = isExt;
        ci.isExposeStruct = isExpose;
        if (isExpose) {
            // WHO OWNS THE LAYOUT, answered once: a C header (`extern`) or kama (`expose`), never both.
            if (isExt)
                unsupported(("`" + *cd->name->value + "` is both `extern` and `expose` — `extern` binds a layout a "
                             "C header states, `expose` publishes one kama states, and one side owns a layout"
                             ).c_str(), cd->line);
            else if (kind != TypeKind::Value || ci.isBorrow)
                unsupported(("`expose` on a type publishes its C layout to a host, and only a `type value` has "
                             "one to publish — a `" + (cd->typeKind ? *cd->typeKind : std::string("?"))
                             + "` owns, borrows or dispatches, which C cannot honor; pass it by `UnsafePtr`, "
                               "where the host header names it opaquely").c_str(), cd->line);
            else if (cd->typeParams && !cd->typeParams->empty())
                unsupported(("`type expose value " + *cd->name->value + "` cannot be generic — a host needs one "
                             "concrete C struct; expose a concrete value instead").c_str(), cd->line);
            ci.hostName = linkNameOf(cd->attributes, cd->line);
        }
        if (isExt) {
            _externNames.insert(ci.name);
            if (!ci.declFile.empty()) _externDeclSites[ci.name].insert(ci.declFile);   // rung, FFI side
        }
        ci.node = cd;

        // `@generate(Serializable, Deserializable)` — opt this type into serialization codegen (pay-for-what-you-
        // use: only a marked type gets the reflective helpers). Only the type-level `@generate` is valid
        // here; per-field attributes are read in the member loop below.
        if (cd->attributes)
            for (auto& at : *cd->attributes) {
                if (!at || !at->name) continue;
                if (*at->name == "generate") {
                    parseGenerateAttr(at, ci, cd->line);
                } else if (*at->name == "viewable") {
                    // `@viewable` is a grant a contract carries, never a property of one type. Marking the
                    // type itself would say "I may be minted anywhere", which is the forge the private ctor
                    // exists to close — and it could not be written generically, since a bound names
                    // contracts (kama.y type_param) and has no way to name a marked type.
                    unsupported(("`@viewable` marks a `type contract`, not a `type "
                                 + (cd->typeKind ? *cd->typeKind : std::string("?")) + "` — minting is a "
                                 "capability the VIEWED type declares by implementing a marked contract, "
                                 "so put the mark on that contract").c_str(), cd->line);
                } else if (*at->name == "linkName" && isExpose) {
                    // The host header's name for the struct (validated in linkNameOf above) — the same one
                    // override an `expose fn`'s symbol has, for a name someone else chose.
                } else if (*at->name == "align" || *at->name == "packed") {
                    // LAYOUT CONTROL — passthrough, the shape `@section` already has for functions and
                    // statics. kama can KNOW a layout (`sizeof`/`alignof` fold, `comptime assert` hands the
                    // rest to the C compiler) but could not CONTROL one, which is what an engine's vertex
                    // buffer / std140 block and an MCU's packed register block both need. It stays
                    // passthrough on purpose: kama emits C, the C compiler lays the struct out, and a
                    // second source of truth in kama could only disagree with it per target.
                    readLayoutAttr(*at, ci.alignN, ci.packed, cd->line);
                } else if (*at->name == "globalAllocator") {
                    // The program's heap (SPEC *Global allocator*). Marked here, known before any body is
                    // emitted — the no-heap facts recorded during emission depend on it — and judged against
                    // the rest of its rules in checkGlobalAllocator, once fields and conformances exist.
                    if (at->args && !at->args->empty())
                        unsupported("`@globalAllocator` takes no arguments", cd->line);
                    else if (cd->typeParams && !cd->typeParams->empty())
                        unsupported(("`@globalAllocator` marks `" + *cd->name->value + "`, which is generic — the "
                                     "program's heap is ONE instance, so it names one concrete type").c_str(), cd->line);
                    else {
                        ci.globalAllocator = true;
                        if (_globalAllocator.empty()) _globalAllocator = ci.name;
                    }
                } else {
                    unsupported(("unknown type attribute `@" + *at->name
                                 + (*at->name == "linkName" ? "` here — `@linkName` names a C symbol, and only a "
                                    "`type expose value` has a host-visible name to fix"
                                    : "` (expected `@generate`, `@align(N)`, `@packed` or `@globalAllocator`)")).c_str(), cd->line);
                }
            }

        ScopedStr _ts(_thisType, ci.name);   // `This` -> this class in its collected method sigs

        // Single inheritance (extends). Base/interface names are RESOLVED in
        // linkBases() once every file's declarations are registered.
        if (cd->baseTypes) {
            if (cd->baseTypes->base && cd->baseTypes->base->value)
                ci.baseName = *cd->baseTypes->base->value;   // bare; resolved in linkBases
            if (cd->baseTypes->interfaces)
                for (auto& itf : *cd->baseTypes->interfaces) {
                    if (!itf || !itf->value) continue;
                    checkWhenParams(itf->whenParams, cd->typeParams, ci.name, ci.declLine());
                    ci.interfaces.push_back(*itf->value);  // bare; resolved in linkBases
                    // Copyable is NOMINAL: `implements Copyable(bare: give|copy)` is the opt-in (a lone
                    // `copy()` no longer implies it). Recognized by name — the capability markers are
                    // compiler-owned. The `(bare: …)` parameter is the mandatory bare-hand-off default;
                    // its presence + the `copy()` method are validated after the member loop below.
                    // Derived-only: the qualifier is where immutability is stated, and it is VERIFIED.
                    // A nominal `implements Immutable` would be a promise nothing checks — on a marker
                    // contract with no members, any type at all would satisfy it structurally.
                    if (*itf->value == "Immutable")
                        unsupported(("`" + ci.name + "` may not declare `implements Immutable` — deep "
                                     "immutability is stated with the `immutable` qualifier on the type "
                                     "(`type immutable value …`), which the compiler verifies over every "
                                     "field, base and variant payload; the contract exists only so a bound "
                                     "can name it").c_str(), ci.declLine());
                    if (*itf->value == "Copyable") {
                        ci.copyable = true; ci.bareDefault = itf->bareDefault;
                        if (itf->whenParams)   // conditional: `… when [P: B, …]` — record each gated param+bound
                            for (size_t c = 0; c < itf->whenParams->size(); ++c) {
                                auto& p = (*itf->whenParams)[c];
                                auto& b = itf->whenBounds ? (*itf->whenBounds)[c] : p;
                                ci.copyableWhenParams.push_back(p && p->value ? *p->value : "");
                                ci.copyableWhenBounds.push_back(resolveWhenBound(b));
                                ci.copyableWhenBoundNodes.push_back(b);
                            }
                    }
                }
        }
        // Class-level extensibility modifier: virtual | abstract | final.
        if (cd->modifiers)
            for (auto& mod : *cd->modifiers) {
                if (!mod->value) continue;
                const std::string& mv = *mod->value;
                if (mv == "abstract") ci.isAbstractClass = true;
                else if (mv == "virtual")  ci.isVirtualClass = true;
                else if (mv == "final")    ci.isFinalClass = true;
                if ((mv == "abstract" || mv == "virtual") && mod->args) ci.maxDepth = readMaxDepth(mod, cd->line);
                else if (mv == "immutable") ci.isImmutableQualified = true;   // M6.2: deep-immutability verified in computeDeeplyImmutable
                else if (mv == "unsafe")
                    unsupported("`unsafe` marks a function BODY, and a type has none — mark the members that "
                                "touch raw memory instead", cd->line);
            }
#if !KAMA_INHERITANCE
        // A `virtual class` goes too, not just `extends` — it carries a vtable with or without a subclass,
        // so rejecting only `extends` would leave the machinery this build exists to remove.
        if (!ci.baseName.empty())   rejectInheritance("`extends`", cd->line);
        if (ci.isAbstractClass)     rejectInheritance("an `abstract class`", cd->line);
        else if (ci.isVirtualClass) rejectInheritance("a `virtual class`", cd->line);
#endif
        // A plain `value`/`resource` type is sealed: only virtual/abstract/final classes may extend a base.
        // (The base must itself be extensible — checked in linkBases once names resolve.)
        if (!ci.baseName.empty() && !(ci.isVirtualClass || ci.isAbstractClass || ci.isFinalClass))
            unsupported(("class '" + ci.name + "' extends '" + ci.baseName
                         + "'; only a `virtual`/`abstract`/`final class` may extend").c_str(), cd->line);
        // `virtual`/`abstract`/`final` are qualifiers on a `resource` (extensible owned
        // hierarchy). A `value` is sealed — for polymorphism use a `contract`.
        if (ci.kind == TypeKind::Value && (ci.isVirtualClass || ci.isAbstractClass || ci.isFinalClass))
            unsupported("a `value` is sealed — `virtual`/`abstract`/`final` apply to a `resource`; "
                        "for polymorphism declare a `contract`", cd->line);

        // A `type extern value` may declare ctors, methods, operators and statics (KR-53): the STRUCT is the
        // header's and is never emitted, but a member is an ordinary kama function, emitted like any other —
        // from the one declaration that carries the members (see the merge below and `classOf` in
        // emitModuleContent). Until KR-53 they were refused on the premise that nothing would emit the body.
        if (cd->members) {
            for (auto& m : *cd->members) {
                ASTNode* mn = m.get();
                if (auto* fd = dynamic_cast<ClassFieldDeclarationNode*>(mn)) {
                    if (fd->modifiers)
                        for (auto& mod : *fd->modifiers) {
                            if (!mod->value) continue;
                            if (*mod->value == "expose")
                                unsupported("`expose` applies only to a free function (the kama->host C-ABI boundary), not a type, field, or method", fd->line);
                            if (*mod->value == "unsafe")
                                unsupported("`unsafe` marks a function BODY, and a field has none — declaring "
                                            "an `UnsafePtr<T>` field is safe; it is reading and writing one "
                                            "that requires an `unsafe fn`", fd->line);
                            // `immutable` is a WHOLE-TYPE qualifier and cannot mean anything per field:
                            // the guarantee it asserts is what licenses cross-isolate sharing, and one
                            // mutable field anywhere breaks it — so a per-field spelling would promise
                            // exactly nothing. It parses only because the modifier list is shared with
                            // the type declaration (kama.y `modifier`), and it used to be SILENTLY
                            // DROPPED here, which is the worst answer available: the author wrote a
                            // guarantee, the compiler agreed, and nothing was checked.
                            if (*mod->value == "immutable")
                                unsupported("`immutable` is a TYPE qualifier (`type immutable value T`) "
                                            "asserting DEEP immutability of the whole type — a single field "
                                            "cannot carry it, because one mutable field anywhere would break "
                                            "the guarantee. For a field written once in the constructor and "
                                            "never again, use `const`", fd->line);
                        }
                    // A `value` picks field visibility PER FIELD (default private, `public` allowed;
                    // `protected` belongs to an extensible `resource`). A `resource` field is always
                    // private (ownership encapsulated). An extern struct's fields are public — the
                    // FFI struct owns its layout.
                    Visibility fvis = fieldVisibility(ci, fd->modifiers, fd->line);

                    // Serialization field metadata (`@field` / `@field(name: "…", id: N)` / `@skip` /
                    // `@deprecated`). On a `@generate`d type EVERY field must be marked `@field` or `@skip` —
                    // an unmarked field is a compile error, so adding a field always forces an explicit
                    // in/out decision.
                    bool serGen = ci.genSerialize || ci.genDeserialize;
                    bool fMarked = false, fSkip = false, fDeprecated = false; std::string fName;
                    int64_t fId = -1; bool fIdSet = false;
                    if (fd->attributes)
                        for (auto& at : *fd->attributes) {
                            if (!at || !at->name) continue;
                            const std::string& an = *at->name;
                            if (an == "skip") { fSkip = true; fMarked = true; }
                            // `@deprecated` REFINES `@field` rather than standing in for it: it does not set
                            // `fMarked`, so a field carrying it alone still fails the mandatory-mark gate
                            // below. That is deliberate — the mark says whether a field is on the wire at
                            // all, and "read but never written" is a property of a field that IS on it.
                            else if (an == "deprecated") { fDeprecated = true; }
                            else if (an == "field") {
                                fMarked = true;
                                if (at->args)
                                    for (auto& a : *at->args) {
                                        const bool named = a && a->name && a->name->value && a->expression;
                                        if (named && *a->name->value == "name") {
                                            if (auto* sn = dynamic_cast<StringNode*>(a->expression.get()))
                                                fName = sn->value ? *sn->value : "";
                                            else unsupported("`@field(name: …)` needs a string literal", fd->line);
                                        } else if (named && *a->name->value == "id") {
                                            int64_t n = 0;
                                            if (!constValue(a->expression, n))
                                                unsupported("`@field(id: N)` needs one literal number — the field's "
                                                            "wire id, e.g. `@field(id: 3)`", fd->line);
                                            else if (n < 0 || n > 4294967295LL)
                                                unsupported(("`@field(id: " + std::to_string(n) + ")` — a wire id is a "
                                                             "uint32, so it must be from 0 to 4294967295").c_str(), fd->line);
                                            else { fId = n; fIdSet = true; }
                                        } else {
                                            unsupported("`@field(...)` accepts only `name: \"…\"` and `id: N`", fd->line);
                                        }
                                    }
                            }
                            else unsupported(("unknown field attribute `@" + an + "`").c_str(), fd->line);
                        }
                    // `@skip` is absent from every backend; `@deprecated` means "still read, no longer
                    // written". A field cannot be both, and silently letting `@skip` win would drop a field
                    // an author explicitly asked to keep reading.
                    if (fDeprecated && fSkip)
                        unsupported("`@deprecated` and `@skip` on one field — `@skip` is absent from every "
                                    "backend, while `@deprecated` is still READ. Drop one", fd->line);
                    // An id names ONE field, so it cannot be shared by a declaration's sibling declarators.
                    // Refused by name rather than left to the duplicate-id diagnostic, which would point at
                    // this same line twice and read as a mystery.
                    if (fIdSet && fd->declarators && fd->declarators->size() > 1) {
                        unsupported("`@field(id: N)` on a declaration that declares several fields — an id "
                                    "names one field. Give each its own `@field` declaration", fd->line);
                        fIdSet = false;   // else every declarator takes the id and the duplicate check piles on
                    }
                    if (!serGen && !ci.genFormat && fd->attributes && !fd->attributes->empty())
                        unsupported("field attributes (`@field`/`@skip`/`@deprecated`) require `@generate(...)` "
                                    "on the type", fd->line);
                    // `@generate(Formattable)` honors `@skip` (omit a field from the dump) but does NOT require every
                    // field marked — a field dump needs no wire names, so marking would be pointless ceremony.
                    if (serGen && !fMarked)
                        unsupported("every field of a `@generate`d type must be marked `@field` or `@skip`", fd->line);
                    // Smart-pointer fields = object-graph mode: `Shared`/`Weak`/`Owned` serialize as integer ids
                    // into the `{root,objects}` id table and deserialize via the two-pass graph intrinsic (Phase
                    // D). `Bindable` (a bound callback) is never serializable.
                    if (serGen && !fSkip && fd->type && fd->type->value) {
                        const std::string& tn = *fd->type->value;
                        if (tn == "Bindable")
                            unsupported("a `Bindable<…>` field can't be serialized — `@skip` it and rebind it "
                                        "after decoding", fd->line);
                    }

                    // BAKE a named compile-time SIZE into the field's type, HERE, where the declaring
                    // file's scope is still installed. `InlineArray<isize>#(N)` resolves `N` through the
                    // reading file's imports wherever the field is later read, so a consumer that imported
                    // the TYPE but not the CONSTANT could not index it — across a package boundary the
                    // constant is not even in scope to import by accident. And the failure was a SILENT
                    // SKIP: `registerFixed` returns when the size will not fold, so the field stopped being
                    // a container and the access fell through to the raw-pointer path, reported as "raw
                    // pointer access requires an `unsafe fn`" — naming neither the constant nor the import,
                    // and pointing the reader at `unsafe`, the one direction this should never send anyone.
                    //
                    // Baked rather than resolved-at-read because the size is part of the type's LAYOUT, not
                    // of its API: a consumer has no reason to know the name, and making them import it
                    // leaks a private constant into every consumer's import block. Doing it at the read
                    // site instead means swapping `_nsCtx` on every member-type resolution, which is the
                    // five-site partial-swap hazard and measured at 30 corpus failures when tried.
                    if (fd->type) bakeConstSizes(fd->type, cd->comptimeParams);
                    if (fd->declarators) {
                        for (auto& d : *fd->declarators) {
                            FieldInfo fi;
                            fi.name        = (d->name && d->name->value) ? *d->name->value : "";
                            fi.nameId      = d->name;
                            fi.type        = fd->type;
                            fi.initializer = d->initializer;
                            fi.visibility  = fvis;
                            fi.serSkip     = fSkip;
                            fi.serName     = fName;
                            fi.serId       = fIdSet ? (int)fId : -1;
                            fi.serDeprecated = fDeprecated;
                            // A member name is declared once (consumer KB-21). A duplicate FIELD used to
                            // reach clang as `duplicate member` in a generated file; the METHOD twin below
                            // was accepted outright and the last body won.
                            if (ci.fieldNames.count(fi.name))
                                unsupported(("duplicate field '" + fi.name + "' in '" + ci.name
                                             + "' — a member name may be declared only once in its type").c_str(),
                                            d->name ? d->name->line : mn->line);
                            ci.fields.push_back(fi);
                            ci.fieldNames.insert(fi.name);
                        }
                    }
                } else if (auto* md = dynamic_cast<ClassMethodDeclarationNode*>(mn)) {
                    // const-eval 6b-3: a type-associated `comptime fn` is compile-time-only — register it for
                    // the interpreter (`Type::name`, with its visibility; default private = access-restricted)
                    // and keep it OUT of the class method table so it is never emitted as C nor runtime-callable.
                    if (md->isComptime) {
                        if (md->name && md->name->value)
                            _comptimeMethods[ci.name + "::" + *md->name->value] =
                                { md, visibilityOf(md->modifiers, Visibility::Private, md->line), ci.name };
                        continue;
                    }
                    if (md->name && md->name->value) {
                        MethodInfo mi;
                        mi.cName      = ci.name + "__" + *md->name->value;
                        mi.returnType = md->returnType;
                        mi.params     = paramSigsOf(md->params);
                        mi.node       = md;
                        mi.isConst    = md->isConst;   // `const fn …`
                        checkConstPlaceReturn(md->isConst, md->isRef, md->isConstRef, *md->name->value, md->line);
                        checkWhenParams(md->whenParams, cd->typeParams, ci.name, md->line);
                        if (md->whenParams)   // `fn … when [P: B, …]` — conditional method (AND of all)
                            for (size_t c = 0; c < md->whenParams->size(); ++c) {
                                auto& p = (*md->whenParams)[c];
                                auto& b = md->whenBounds ? (*md->whenBounds)[c] : p;
                                mi.whenParams.push_back(p && p->value ? *p->value : "");
                                mi.whenBounds.push_back(resolveWhenBound(b));
                                mi.whenBoundNodes.push_back(b);
                            }
                        mi.isPlaceReturn = md->isRef;  // `fn ref T …` — returns a place (T*), like `operator[]`
                        mi.isConstPlace  = md->isConstRef;   // `fn const ref T …` — a read-only place (T const*)
                        mi.noHeap = hasNoHeapAttr(md->attributes);   // the declared half of the no-heap proof
                        mi.serdeGraphEdges = hasAttr(md->attributes, "serializedGraphEdges");
                        mi.visibility = visibilityOf(md->modifiers, Visibility::Private, md->line);
                        // A `view`'s CONSTRUCTOR is always private — the mint rule. A view is a
                        // bidirectional relationship: it does not exist without a type to view, so it may
                        // be born only inside the view itself or inside the type it views, the latter
                        // declared by implementing a member of a `@viewable` contract. `public` here would
                        // be a standing offer to build a borrow over any memory the caller can name, which
                        // is the forge this closes. Rejected rather than silently downgraded, exactly as
                        // fieldVisibility rejects a written visibility on a `view` field: the default is
                        // already `Private`, so a downgrade would leave 16 stdlib declarations reading
                        // `public` while meaning the opposite.
                        if (ci.isBorrow && md->isCtor
                            && (modHas(md->modifiers, "public") || modHas(md->modifiers, "protected")))
                            unsupported(("a `view` constructor is always private — `" + ci.name + "` borrows "
                                         "memory it does not own, so it may only be minted by the type that "
                                         "owns that memory. Drop the visibility and let the viewed type "
                                         "declare the capability, by implementing a `@viewable` contract "
                                         "whose member returns this view").c_str(), md->line);
                        // `protected` belongs to a `resource` in an extensibility hierarchy
                        // (`virtual`/`abstract` declares protected members for subclasses; a `final`
                        // override still uses `protected` by NVI). It's meaningless on a `value`, a
                        // plain sealed `resource`, or a `contract` — those members are private/public.
                        if (mi.visibility == Visibility::Protected
                            && !(ci.isVirtualClass || ci.isAbstractClass || ci.isFinalClass))
                            unsupported(("`protected` belongs to a `virtual`/`abstract`/`final resource` — `" + ci.name
                                         + "` is a plain `value`/`resource`, so its members are `private` or `public`").c_str(), md->line);
                        mi.isFinal    = modHas(md->modifiers, "final");
                        mi.isUnsafe   = modHas(md->modifiers, "unsafe");
                        // `unsafe` describes a BODY. A contract member and an `abstract` method are
                        // bodiless, so there is nothing in them to be unsafe — and a contract could not
                        // usefully specify one anyway: everything it might force is already forced by the
                        // member's own types (an implementation whose signature names `UnsafePtr` must be
                        // an `unsafe fn`; a caller must hold an `UnsafePtr` to invoke it). This is what
                        // keeps `A: Allocator` a perfectly safe bound.
                        if (mi.isUnsafe && !md->body)
                            unsupported(("`unsafe` marks a function BODY, and `" + *md->name->value
                                         + "` has none — the implementation carries the marker, not the "
                                           "declaration").c_str(), md->line);
                        // The signature half of the containment rule. A member that NAMES a raw pointer —
                        // in its return type or any parameter — must be `unsafe`, so the marker sits at
                        // the declaration a reader greps for rather than inside a body they must open.
                        // Only where a body exists: an `abstract` member is a guarantee, and a `contract`
                        // member (collected in collectInterfaces) is a conduit — see the rejection above.
                        if (md->body) checkSignatureRawPtr(mi.isUnsafe, md->returnType, md->params,
                                                           *md->name->value, md->line);
                        if (md->modifiers)
                            for (auto& mod : *md->modifiers) {
                                if (!mod->value) continue;
                                if (*mod->value == "virtual")  mi.isVirtual = true;
                                if (*mod->value == "override") { mi.isVirtual = true; mi.isOverride = true; }
                                if (*mod->value == "abstract") { mi.isVirtual = true; mi.isAbstract = true; }
                                if (*mod->value == "static")   mi.isStatic = true;   // no implicit `self`
                                if (*mod->value == "expose")
                                    unsupported("`expose` applies only to a free function (the kama->host C-ABI boundary), not a type, field, or method", md->line);
                                // See the field arm above: a whole-type qualifier, silently dropped here
                                // until 0.9.144. `const fn` is the per-method promise it gets mistaken for.
                                if (*mod->value == "immutable")
                                    unsupported("`immutable` is a TYPE qualifier (`type immutable value T`) "
                                                "asserting DEEP immutability of the whole type — a method "
                                                "cannot carry it. For a method that does not mutate its "
                                                "receiver, use `const fn`", md->line);
                            }
                        // Construction-model: a named constructor (`ctor name(…)`) is a static factory
                        // returning the enclosing type (infallible — no return type written) or `Result<This,E>`
                        // (fallible). Reuses the static-method pipeline; the ctors map records it for the
                        // dot-on-type dispatch / completeness / enforcement of later milestones.
                        if (md->isCtor) {
                            mi.isStatic = true;
                            mi.isCtor   = true;
                            // Guarantee #1 (return-type correctness): an INFALLIBLE ctor omits the return type
                            // (`ctor make(…)`) — it returns the enclosing type; a FALLIBLE ctor writes exactly
                            // `Result<This, E>` (never `Optional`, never a bare type — a failure carries *why*).
                            bool fallible = (bool)mi.returnType;   // a written return type => fallible
                            if (fallible) {
                                const std::string rt = (mi.returnType->value) ? *mi.returnType->value : "";
                                if (rt != "Result")
                                    unsupported(("a `ctor` with a return type must be `Result<…, E>` (fallible) — "
                                                 "omit it for an infallible ctor; got `" + rt + "`").c_str(), md->line);
                            } else if (cd->typeParams && !cd->typeParams->empty()) {
                                // infallible ctor on a GENERIC type: the return type must carry the type
                                // parameters (`Pair<T>`, not the bare template `_F<file>__Pair`) so per-instance
                                // emission substitutes them — exactly as a `static fn Pair<T> make` return type
                                // would. Without this the ctor's return type + return-slot stay unspecialized
                                // (clang: `unknown type name '_F<file>__Pair'`). #M7-E1
                                if (!_synthCtx) _synthCtx = std::make_shared<CodeGenContext>(std::make_shared<std::string>("<generic-ctor>"));
                                auto rt = synthClone(*cd->name);   // copy name + qualifier
                                rt->genericArgs = std::make_shared<IdentifierList>();
                                for (auto& p : *cd->typeParams)
                                    if (p) rt->genericArgs->push_back(
                                        synthId(*p));
                                if (!rt->genericArgs->empty()) rt->genericArg = (*rt->genericArgs)[0];
                                mi.returnType = rt;
                            } else {
                                mi.returnType = cd->name;          // infallible => the enclosing type
                            }
                            // `default ctor …()` (M8b): explicitly designate the ONE canonical zero-arg ctor
                            // (Kama allows N zero-arg ctors — `empty`/`zero`/… — so "the default" needs a marker).
                            // Never inferred: `@generate(zero)` yields a callable `zero()` but does NOT elect it.
                            bool isDefaultCtor = modHas(md->modifiers, "default");
                            if (isDefaultCtor) {
                                if (!mi.params.empty())
                                    unsupported("`default` marks a zero-arg ctor — remove its parameters", md->line);
                                for (auto& kv : ci.ctors)
                                    if (kv.second.isDefaultCtor)
                                        unsupported(("a type may mark at most one `default` ctor — `"
                                                     + kv.first + "` is already the default").c_str(), md->line);
                            }
                            mi.isDefaultCtor = isDefaultCtor;
                            ci.ctors[*md->name->value] = CtorInfo{ nullptr, mi.params, mi.visibility, fallible, mi.returnType, isDefaultCtor };
                        }
                        // `default` is a ctor-only modifier — reject it silently no-op'ing on a plain method.
                        if (!md->isCtor && modHas(md->modifiers, "default"))
                            unsupported("`default` applies only to a zero-arg `ctor`", md->line);
                        // a `static` method has no `this`: no vtable slot, must have a body.
                        if (mi.isStatic) {
                            if (mi.isVirtual)
                                unsupported("a `static` method has no `this` — it can't be `virtual`/`override`/`abstract`", md->line);
                            if (!md->body)
                                unsupported("a `static` method needs a body", md->line);
                            // Construction-model M8e: a SELF-RETURNING `static fn` (returns the enclosing type,
                            // or `Result<EnclosingType, E>`) IS a constructor — the whole factory role now lives
                            // in `ctor`. Reject it so there is exactly one way to construct. A static fn returning
                            // any OTHER type (`Vec3::dot -> float`, `Buffer::create -> Result<Owned<Buffer>, E>`)
                            // stays a legitimate utility.
                            if (!md->isCtor && cd->name && cd->name->value && md->returnType && md->returnType->value) {
                                const std::string& encl = *cd->name->value;
                                const std::string& rt = *md->returnType->value;
                                bool selfRet = (rt == encl || rt == "This");
                                if (rt == "Result" && md->returnType->genericArg && md->returnType->genericArg->value) {
                                    const std::string& okTy = *md->returnType->genericArg->value;
                                    selfRet = selfRet || okTy == encl || okTy == "This";
                                }
                                if (selfRet)
                                    unsupported(("a self-returning `static fn " + *md->name->value + "` is a constructor — "
                                                 "declare it `ctor " + *md->name->value + "(...)` and call it dot-on-type (`"
                                                 + encl + "." + *md->name->value + "(...)`)").c_str(), md->line);
                            }
                        }
                        if (!md->body) mi.isAbstract = mi.isVirtual = true;   // null body => pure
                        // polymorphism rules.
                        if (mi.isVirtual) {
                            const std::string& mname = *md->name->value;
                            const char* kw = mi.isAbstract ? "abstract" : mi.isOverride ? "override" : "virtual";
#if !KAMA_INHERITANCE
                            // An overridable method is a vtable slot, so it goes too.
                            rejectInheritance((std::string(mi.isVirtual && !mi.isAbstract && !mi.isOverride ? "a `" : "an `")
                                               + kw + "` method").c_str(), md->line);
#endif
                            // (3) an overridable method is written `protected` (never public/private):
                            //     a private virtual can't be overridden, a public one is the interface's job.
                            if (mi.visibility != Visibility::Protected)
                                unsupported(("overridable method '" + mname + "' must be declared `protected` (write `protected "
                                    + kw + "`); public polymorphism belongs on a contract").c_str(), md->line);
                            // (4a) the class kind must opt in to the method's polymorphism.
                            if (mi.isAbstract && !ci.isAbstractClass)
                                unsupported(("class '" + ci.name + "' declares an abstract method; declare it `abstract class`").c_str(), md->line);
                            else if (mi.isOverride && !(ci.isVirtualClass || ci.isAbstractClass || ci.isFinalClass))
                                unsupported(("class '" + ci.name + "' overrides a method; declare it `virtual`/`abstract`/`final class`").c_str(), md->line);
                            else if (!mi.isAbstract && !mi.isOverride && !ci.isVirtualClass && !ci.isAbstractClass)
                                unsupported(("class '" + ci.name + "' declares a virtual method; declare it `virtual class`").c_str(), md->line);
                        }
                        // `final` seals a virtual slot; reject the meaningless/contradictory cases.
                        if (mi.isFinal && mi.isAbstract)
                            unsupported(("`final abstract` on '" + *md->name->value + "' is a contradiction (an abstract method must be overridden)").c_str(), md->line);
                        else if (mi.isFinal && !mi.isVirtual)
                            unsupported(("`final` on '" + *md->name->value + "' applies only to an overridable (virtual/override) method").c_str(), md->line);
                        // KB-21's silent half: two bodies under one name compiled, and the LAST one
                        // answered every call. Same rule as `duplicate function` at file scope — kama has
                        // no overloading — so a member name is declared once. (`redeclares … inherits` is
                        // the base-class case and lives with the inheritance checks.)
                        // A member `@compileFor` is refused here, at COLLECTION, and not only where emission
                        // reaches the attribute: two same-named members each gated for a different platform are
                        // exactly what someone writes when they believe the gate works, and the duplicate rule
                        // below used to answer first — "duplicate method" — about code whose real mistake is the
                        // gate. The text is the emitter's, so the second report dedups onto this one (KR-21 d).
                        const bool gated = hasAttr(md->attributes, "compileFor");
                        if (gated) unsupported(kCompileForOnMember, md->line);
                        auto dupIt = ci.methods.find(*md->name->value);
                        const bool prevGated = dupIt != ci.methods.end() && dupIt->second.node
                                            && hasAttr(dupIt->second.node->attributes, "compileFor");
                        if (dupIt != ci.methods.end() && !gated && !prevGated)
                            unsupported(("duplicate method '" + *md->name->value + "' in '" + ci.name
                                         + "' — kama has no overloading, so a member name may be declared "
                                           "only once in its type; the second body would silently replace the first").c_str(),
                                        md->line);
                        ci.methods[*md->name->value] = mi;
                    }
                } else if (auto* cc = dynamic_cast<ClassConstructorDeclarationNode*>(mn)) {
                    // Construction-model M8 (Phase E + M8e): the legacy class-named constructor is no longer
                    // allowed — all construction is a named factory `ctor` called dot-on-type. The Phase-E
                    // serde exemption is gone (M8e removed the `onConstruction` hook).
                    {
                        std::string tnm = (cd->name && cd->name->value) ? *cd->name->value : "T";
                        // `: base(...)` deserves its own answer. The production exists ONLY so that a
                        // class-named ctor still PARSES — which is what lets the guided message below be
                        // reported instead of a raw parse error — and no emitter code ever read
                        // ClassConstructorInitializerNode, so its arguments were parsed and silently
                        // discarded even when the enclosing form was legal. Saying "base delegation is not
                        // supported" is a far better answer than a general "no class-named ctors" for
                        // someone who wrote it because they wanted base delegation specifically.
                        if (cc->declarator && cc->declarator->initializer)
                            unsupported(("base-constructor delegation (`: base(...)`) is not supported — a "
                                         "named `ctor` is a factory with no `self` to chain into. Install the "
                                         "base VALUE instead: `this.base = Base.<ctor>(...);` as the first "
                                         "statement of a named constructor `ctor make(...)` on `"
                                         + tnm + "`").c_str(),
                                        cc->line);
                        else
                            unsupported(("class-named constructor `" + tnm + "(...)` is no longer allowed — declare a "
                                         "named constructor `ctor make(...)` and call it dot-on-type (`" + tnm
                                         + ".make(...)`)").c_str(), cc->line);
                    }
                    // Nothing is recorded: the form is rejected above, so no later pass may act on it.
                } else if (auto* dd = dynamic_cast<ClassDestructorDeclarationNode*>(mn)) {
                    // `~dtor` ⟺ `resource`. A `value` owns nothing, so a destructor makes it
                    // a resource; that disagreement is the lesson in the message. A `view` borrows and
                    // owns nothing either — a `~dtor` would try to free memory it doesn't own.
                    if (ci.isBorrow)
                        unsupported("a `view` borrows and owns nothing — it may not declare a `~dtor` "
                                    "(it would free memory it doesn't own)", dd->line);
                    if (ci.kind == TypeKind::Value)
                        unsupported("a `value` owns nothing — a `~dtor` makes it a `resource`; "
                                    "declare it `type resource`", dd->line);
                    ci.hasDtor  = true;
                    ci.dtorNode = dd;
                } else if (auto* kd = dynamic_cast<ClassConstDeclarationNode*>(mn)) {
                    // a `const` data member — a normal struct field, written
                    // ONCE in the constructor (inline init or `this.f = …`), then
                    // immutable. Enforcement is at the kama level; the C field is plain.
                    // visibility follows the same per-field rule (see fieldVisibility).
                    Visibility kvis = fieldVisibility(ci, kd->modifiers, kd->line);
                    if (kd->declarators)
                        for (auto& d : *kd->declarators) {
                            std::string fn = (d->name && d->name->value) ? *d->name->value : "";
                            // 6b-2: a `comptime` member is a type-ASSOCIATED compile-time constant (`Type::NAME`),
                            // NOT a per-instance field. Fold it (declaration order, so a later `B = A+1` resolves
                            // an earlier one via _typeConsts) and register it for `Type::NAME` reads / sizes.
                            if (kd->isComptime) {
                                TypeConstInfo tc;
                                tc.hasValue = d->initializer && constValue(d->initializer, tc.value);
                                tc.visibility = kvis; tc.owner = ci.name; tc.cName = ci.name + "__" + fn;
                                tc.type = kd->type; tc.initializer = d->initializer; tc.line = kd->line;
                                _typeConsts[ci.name + "::" + fn] = tc;
                                continue;
                            }
                            FieldInfo fi;
                            fi.name        = fn;
                            fi.nameId      = d->name;
                            fi.type        = kd->type;
                            fi.initializer = d->initializer;
                            fi.visibility  = kvis;
                            if (ci.fieldNames.count(fi.name))   // KB-21, the `const` field spelling
                                unsupported(("duplicate field '" + fi.name + "' in '" + ci.name
                                             + "' — a member name may be declared only once in its type").c_str(),
                                            d->name ? d->name->line : mn->line);
                            ci.fields.push_back(fi);
                            ci.fieldNames.insert(fi.name);
                            ci.constFields.insert(fi.name);
                        }
                } else if (auto* od = dynamic_cast<ClassOperatorDeclarationNode*>(mn)) {
                    // an operator overload registers as a method under a synthetic name
                    // (`op_add`/`op_neg`/…), disambiguated by arity: 0 params = unary-on-`this`,
                    // 1 = binary method (`this`+rhs), 2 = binary free form (both operands explicit).
                    auto* d = od->operatorDeclarator.get();
                    int arity = (d->param1Type ? 1 : 0) + (d->param2Type ? 1 : 0);
                    // The six comparison operators are CONTRACT-driven and may not be declared directly:
                    // `Equatable`/`Comparable` are the one opt-in, and `==`/`<`/… lower to their
                    // `equals`/`compareTo` (emitBinaryOperator). Two spellings of one concept is how C#
                    // ended up with `operator==`, `Equals`, `IEquatable<T>` and `EqualityComparer` able to
                    // disagree; kama has one. Every other operator stays an ordinary operator member.
                    if (isComparisonToken(d->opToken)) {
                        bool eq = (d->opToken == EQEQ || d->opToken == NOTEQ);
                        std::string need = eq ? "Equatable" : "Comparable";
                        std::string meth = eq ? "fn bool equals(ref This other)"
                                              : "fn Ordering compareTo(ref This other)";
                        unsupported((std::string("`operator") + binaryOperator(d->opToken) + "` is not declared "
                                     "directly — comparison comes from a contract: `implements " + need + " for "
                                     + ci.name + " { public " + meth + " { … } }`, and `"
                                     + binaryOperator(d->opToken) + "` calls it"
                                     + (eq ? " (a data bag can `@generate(Equatable)` instead)" : "")).c_str(), od->line);
                        continue;
                    }
                    std::string opName = operatorName(d->opToken, arity, d->param1Type, ci.name);   // type-suffixed
                    if (opName.empty())
                        unsupported((std::string("operator '") + binaryOperator(d->opToken)
                                     + "' has no " + (arity == 0 ? "unary" : "binary") + " form").c_str(), od->line);
                    if (!od->body)
                        unsupported("an operator needs a body", od->line);
                    // No overloading BY ARITY (a stated non-goal). Operators MAY distinguish operand types
                    // (`mat*vec` vs `mat*mat` — the sanctioned exception, since `a*b` can't take named args),
                    // so a duplicate is only two operators with the same symbol AND operand type (same name).
                    if (ci.methods.count(opName))
                        unsupported((std::string("duplicate operator '") + binaryOperator(d->opToken)
                                     + "' on '" + ci.name + "' for the same operand type").c_str(), od->line);
                    MethodInfo mi;
                    mi.cName      = ci.name + "__" + opName;
                    mi.returnType = d->returnType;
                    mi.params     = paramSigsOf(operatorParamList(d));
                    mi.node       = nullptr;                 // an operator is NOT a ClassMethodDeclarationNode
                    mi.opDecl     = od;
                    mi.isOperator = true;
                    mi.arity      = arity;
                    mi.isStatic   = (arity == 2);            // the free form takes no `this`
                    mi.isPlaceReturn = d->refReturn;         // `ref T operator[]` — the result is a place (T*)
                    mi.isConstPlace  = d->constRefReturn;    // `const ref T operator[]` — a read-only place (T const*)
                    mi.isUnsafe   = modHas(od->modifiers, "unsafe");   // `unsafe ref T operator[]` — View indexes raw memory
                    mi.visibility = visibilityOf(od->modifiers, Visibility::Public, od->line);   // operators are public by nature
                    ci.methods[opName] = mi;
                } else if (auto* fg = dynamic_cast<FriendGrantNode*>(mn)) {
                    // capture the grant raw; the accessor is resolved (against the
                    // full function/class tables) in resolveFriends() once all units load.
                    RawFriendGrant rg; rg.accessor = fg->accessor; rg.line = fg->line;
                    if (fg->members)                                  // null => `[...]` (all privates)
                        for (auto& m : *fg->members)
                            if (m && m->value) rg.members.insert(*m->value);
                    ci.friendGrantsRaw.push_back(rg);
                }
            }
        }
        // a `virtual`/`abstract class` must actually declare an overridable method
        // (else the qualifier is a lie); the reverse of rule 4a.
        if (ci.isVirtualClass || ci.isAbstractClass) {
            bool hasOverridable = false;
            for (auto& kv : ci.methods) if (kv.second.isVirtual) { hasOverridable = true; break; }
            // Only a ROOT must declare one. A middle layer's extensibility is justified by the seams it
            // INHERITS — it may exist purely to add state between a root and its leaves, and demanding it
            // invent a new hook would be asking for a seam nobody wanted. (Before the depth budget every
            // extensible class was a root, so this distinction could not arise.)
            if (!hasOverridable && ci.baseName.empty())
                unsupported(("`" + std::string(ci.isAbstractClass ? "abstract" : "virtual") + " class` '"
                             + ci.name + "' declares no overridable (virtual/abstract) method").c_str(), cd->line);
            // ...and it must declare a CONSTRUCTOR, for the same reason: without one it can be neither
            // instantiated nor installed as a base (`this.base = Base.<ctor>(…)` has nothing to call), so
            // it is unconstructible and every type below it is too. Said HERE rather than at each derived
            // ctor because the fix belongs to the base — and because a designer should learn it when
            // writing the base, not from a subclass three files away. A generator cannot substitute:
            // `@generate(zero)`/`of` need a transparent `value`, and a `value` is sealed.
            if (ci.ctors.empty())
                unsupported(("`" + std::string(ci.isAbstractClass ? "abstract" : "virtual") + " class` '"
                             + ci.name + "' declares no `ctor`, so nothing can ever be built from it — "
                             "neither the class itself nor a type that extends it (which must install its "
                             "base with `this.base = Base.<ctor>(…);`)").c_str(), cd->line);
        }
        // `implements Copyable(bare: give|copy)` is the nominal opt-in. It obliges a resource to supply
        // BOTH the `copy` CTOR (`ctor copy(ref This source)`) AND the `bare:` contract parameter (the
        // bare-hand-off default). A value is copyable implicitly (bitwise) — it needs neither, and its
        // bare-default is a copy. `copy` is a ctor because a copy IS a new object: it was the last
        // self-returning member that wasn't one, and M8e had already ruled that shape out for `static fn`.
        if (ci.copyable && ci.kind != TypeKind::Value) {
            auto cm = ci.methods.find("copy");
            if (cm == ci.methods.end() || cm->second.visibility != Visibility::Public
                || !cm->second.isCtor || cm->second.params.size() != 1)
                unsupported(("`" + ci.name + "` implements `Copyable` but has no public `copy` constructor "
                             "(the contract is `ctor copy(ref This source)`)").c_str(), cd->line);
            if (ci.bareDefault == 0)
                unsupported(("`" + ci.name + "` implements `Copyable` but doesn't declare its bare-hand-off default "
                             "— write `implements Copyable(bare: give)` or `Copyable(bare: copy)`").c_str(), cd->line);
        }
        // What `@generate(...)` asks for — see registerDerives. A generic TEMPLATE is skipped here and
        // derived PER INSTANCE instead (registerGenericTypeInst), which is the only place its fields have
        // concrete types to walk; the template's flags ride into `_genericTypes` with the rest of its shape.
        if (!(cd->typeParams && !cd->typeParams->empty())) registerDerives(ci, cd->name, cd->line);
        // a generic TYPE template (`type value Box<T>`) is kept OUT of _classes — it is
        // specialized per concrete `Box<Arg>` at discovery. Its ClassInfo shape (T-typed fields/
        // methods) is parked in _genericTypes; the specialized instances are the real classes.
        if (cd->typeParams && !cd->typeParams->empty()) {
            std::vector<std::string> ps;
            for (auto& p : *cd->typeParams) if (p) ps.push_back(*p);   // [A, B, …]
            _genericTypeParams[ci.name] = ps;
            _genericTypeBounds[ci.name] = cd->typeBounds;   // per-param contract bounds
            if (cd->constTypes) _genericTypeConstTypes[ci.name] = *cd->constTypes;   // per-param `const N: int32` width
            if (cd->typeDefaults) _genericTypeDefaults[ci.name] = *cd->typeDefaults;   // per-param `= Default` (null entry = required)
            _genericTypeCtx[ci.name]    = _nsCtx;
            _genericTypes[ci.name]      = ci;
            if (cd->name && cd->name->value) {              // capture the prelude triad's template keys (Phase D)
                const std::string& sn = *cd->name->value;
                if      (sn == "Shared") _sharedTmpl = ci.name;
                else if (sn == "Owned")  _ownedTmpl  = ci.name;
                else if (sn == "Weak")   _weakTmpl   = ci.name;
                else if (sn == "Channel"  && ci.scope == "std__concurrent") _channelTmpl  = ci.name;
                else if (sn == "Sender"   && ci.scope == "std__concurrent") _senderTmpl   = ci.name;
                else if (sn == "Receiver" && ci.scope == "std__concurrent") _receiverTmpl = ci.name;
                else if (sn == "Atomic"   && ci.scope == "std__concurrent") _atomicTmpl   = ci.name;
            }
        } else {
            // AGREEMENT, extern-struct side — the same rule the FuncSig builder applies to an `extern fn`,
            // and for the same reason: `type extern value div_t { … }` keeps its literal C name, so every
            // file declaring it writes to ONE table entry and the last one collected wins. A FIELD READ is
            // safe on its own (it emits the literal member name, so a reordering is harmless and the real
            // C header supplies the layout) — what is not safe is a differing field TYPE, which decides how
            // kama types every expression reading that member, in every file. Before this, the loser's
            // correct code was rejected by a downstream numeric error naming the innocent file.
            //
            // A field this declaration does not mention is a disagreement too: `_classes` is replaced
            // wholesale, so the other file's reads of the missing member stop resolving.
            if (ci.isExternStruct) {
                auto prev = _classes.find(ci.name);
                if (prev != _classes.end() && prev->second.isExternStruct
                    && !prev->second.declFile.empty() && prev->second.declFile != ci.declFile) {
                    const ClassInfo& was = prev->second;
                    std::string diff;
                    if (was.fields.size() != ci.fields.size())
                        diff = "it has " + std::to_string(ci.fields.size()) + " field(s) here and "
                             + std::to_string(was.fields.size()) + " there";
                    else for (size_t i = 0; i < ci.fields.size() && diff.empty(); ++i) {
                        const std::string an = ci.fields[i].name,  bn = was.fields[i].name;
                        const std::string at = ci.fields[i].type  ? *ci.fields[i].type->value  : std::string();
                        const std::string bt = was.fields[i].type ? *was.fields[i].type->value : std::string();
                        if (an != bn)      diff = "field " + std::to_string(i + 1) + " is named `" + an
                                                + "` here and `" + bn + "` there";
                        else if (at != bt) diff = "field `" + an + "` is `" + at + "` here and `" + bt
                                                + "` there";
                    }
                    if (!diff.empty())
                        unsupported(("this `type extern value " + *cd->name->value + "` disagrees with the "
                                     "one in `" + was.declFile + "` — " + diff + ". `" + ci.name + "` is ONE "
                                     "C struct, so every declaration of it in a program must match: kama "
                                     "does not emit it (the real layout comes from the header), and the "
                                     "last declaration collected decides how BOTH files type every read of "
                                     "its members").c_str(), cd->line);
                    // MEMBERS belong to ONE declaration. The fields are the header's and every copy repeats
                    // them; a ctor or method is kama code with one body, so a second declaration carrying
                    // members would define it twice. Share the type by exporting it from the declaring file.
                    const bool mine = !ci.methods.empty(), theirs = !was.methods.empty();
                    if (mine && theirs)
                        unsupported(("`type extern value " + *cd->name->value + "` declares members here and in `"
                                     + was.declFile + "` — its fields may be repeated, but its ctors and methods "
                                     "have one body each. Declare them once and `export` the type from that "
                                     "file").c_str(), cd->line);
                    if (theirs) {   // this copy is fields only (or a refused second set): keep the first declaration's members
                        ci.methods = was.methods; ci.ctors = was.ctors;
                        ci.node = was.node; ci.declFile = was.declFile;
                    }
                }
            }
            _classes[ci.name] = ci;
        }
    }
}

// ---- Collections -----------------------------------------------------

// ---- Const generics --------------------------------------------------
// M6: `sizeof(T)` in BYTES for a fixed-width scalar T — the compiler's only type-size knowledge, and
// deliberately the smallest set it can justify. kama does not own struct layout (it emits C; the C
// compiler lays out the aggregates), so it may fold only what the LANGUAGE fixes, never what the ABI
// decides:
//   int8..int64 / uint8..uint64 / char  ISO C11 §7.20.1.1 pins the exact-width types at N bits with no
//                                       padding; sizeof counts chars, so this also needs CHAR_BIT == 8
//   float32 / float64                   `float`/`double` at 4/8 — an ABI convention (ISO C's Annex F is
//                                       optional), already relied on by emitBitcast and kama_f32_bits
// All three premises are `_Static_assert`ed in kama_runtime.h and checked by the C compiler for the real
// target on every build, so the fold is verified rather than assumed.
//
// Everything else stays a C `sizeof` passthrough: `bool` (implementation-defined size), `string`/`void`/
// user aggregates (layout is the C compiler's), and — the one that looks like it belongs — `usize`/
// `isize`, which map to `size_t` and are genuinely target-dependent (4 on wasm32/thumbv6m, 8 on x86_64).
// `alignof` never folds at all: alignment is an ABI CHOICE with no premise to assert (1 on AVR, and
// _Alignof(double) is 4 on i386), which is why the caller checks isAlign before reaching here.
bool CEmitter::scalarByteSize(SharedIdentifier type, int64_t& out)
{
    if (!type) return false;
    // The _typeSubst hop comes FIRST, exactly as in cType/mangleElem: inside a monomorph a parameter's
    // type node is still the unsubstituted `T`, so `sizeof(B)` in a generic instance needs resolving
    // before the token is read. This is what makes M9's `sizeof(B) * 8` fold.
    SharedIdentifier t = deepSubstType(type);
    if (!t || t->genericArg) return false;   // a generic instance is an aggregate — not ours to size
    switch (t->builtInVal) {
        case IDENTIFIER_INT8_VAL:  case IDENTIFIER_UINT8_VAL:                             out = 1; return true;
        case IDENTIFIER_INT16_VAL: case IDENTIFIER_UINT16_VAL:                            out = 2; return true;
        case IDENTIFIER_INT32_VAL: case IDENTIFIER_UINT32_VAL: case IDENTIFIER_CHAR_VAL:
        case IDENTIFIER_FLOAT32_VAL:                                                      out = 4; return true;
        case IDENTIFIER_INT64_VAL: case IDENTIFIER_UINT64_VAL: case IDENTIFIER_FLOAT64_VAL: out = 8; return true;
        // ⚠️ REFUSED ON PURPOSE, and named rather than left to `default:`. `isize`/`usize` are
        // platform-varying types (`ptrdiff_t`/`size_t` — 8 bytes on x86_64/arm64, 4 on wasm32/thumbv6m),
        // so there is no one number to fold and `sizeof(usize)` stays a runtime `sizeof`. They reached
        // this switch for the first time in 0.9.136, when they became reserved words; before that they
        // fell out here anyway, invisibly. A silent `default:` is how `char` slipped past strict numeric
        // checking, so the refusal is spelled out. Guarded by tests/xfail/sizeof_usize_not_foldable.
        case IDENTIFIER_ISIZE_VAL: case IDENTIFIER_USIZE_VAL:                             return false;
        // ...and C's `long`/`unsigned long` (4 bytes on Windows, 8 elsewhere) — the same refusal, guarded by
        // tests/xfail/sizeof_clong_not_foldable. `cchar` is refused as a VALUE position at the sizeof site.
        case IDENTIFIER_CLONG_VAL: case IDENTIFIER_CULONG_VAL: case IDENTIFIER_CCHAR_VAL: return false;
        default: return false;
    }
}

// The compile-time integer value of a comptime argument expression: an integer literal (any
// width), or a const-param identifier bound to a value in the current instantiation (`N` -> 4). This
// is the value half of the monomorphization — the parallel of resolving a bound type-param.
// The inclusive range of a fixed-width integral type, in the int64 the const folder works in.
//
// `usize`/`isize` are deliberately absent, for the same reason `scalarByteSize` refuses them: their
// width belongs to the target, not to this compiler, and kama accepts arbitrary triples. Asserting a
// range for `cast<usize>(4096)` would be asserting a target we were not told about. `uint64`'s upper
// half is absent for a different reason — `constValue` folds in int64, so there is no value above
// INT64_MAX for it to hand us, and claiming the range is [0, INT64_MAX] would be a lie about the type
// rather than about the fold. Both cases answer "not checkable", which is the safe answer.
// One message for both paths that can see an out-of-range constant cast — the emit walk, and the const
// folder (which is where a `comptime` constant is resolved, and it never reaches the emit walk).
void CEmitter::rejectConstCastOverflow(SharedIdentifier target, int64_t v, int64_t lo, int64_t hi, int line)
{
    const std::string nm = (target && target->value) ? *target->value : std::string("?");
    unsupported(("`cast<" + nm + ">(" + std::to_string(v) + ")` — " + std::to_string(v)
                 + " does not fit `" + nm + "` (" + std::to_string(lo) + " to " + std::to_string(hi)
                 + "), so this is not a conversion but a different number. Write a value in range, "
                   "or mask first if the truncation is what you mean (`cast<" + nm + ">(x & 0xFF)`)")
                .c_str(), line);
}

// The RUNTIME narrowing check for one `cast<T>(x)`. Returns the checked C expression, or "" when the
// conversion provably cannot fail and must stay a bare cast.
//
// The gate is the TARGET being a number, which is what keeps the ~200 `cast<UnsafePtr<T>>` sites — a
// pointer conversion, and the unsafe seam's one production site — out of this entirely, along with an FFI
// typedef and a plain enum. `cNumRangeText` answering false IS that gate.
std::string CEmitter::narrowCheck(const std::string& dstCType, SharedExpression value)
{
    std::string lo, hi;
    if (!value || !cNumRangeText(dstCType, lo, hi)) return "";
    // A CONSTANT into a target whose width this compiler knows has already been judged, one arm up:
    // `primIntRange` + `constValue` rejected it if it did not fit, so anything still here fits. Same
    // admitted set as `primIntRangeC`, which is why that call is the test.
    //
    // A constant into `usize`/`isize` keeps its check on purpose: their width is the TARGET's, so
    // `cast<usize>(70000)` fits on a 64-bit host and does not on a 16-bit one, and the constant rule
    // declines to answer for exactly that reason. `lo`/`hi` are compile-time constants there too, so the
    // check that survives folds away at `-O2`.
    int64_t clo, chi, cv;
    if (primIntRangeC(dstCType, clo, chi) && constValue(value, cv)) return "";
    // A `foreach` element or a `match`-arm payload binding used to need its own `_localTypeNodes` lookup
    // right here, because the classifier could not answer for one. It answers now, so this reads the same
    // map through the same call every other rule uses.
    //
    // ⚠️ The payoff is CODE, not release speed, and the difference was measured 2026-08-18 rather than
    // assumed. A widening `cast<int64>(v)` out of an `int32` binding emits `KAMA_NARROW` when the source
    // is unknown — a real call to `kama_narrow_chk_s` — but at `-O2`/`-O3` clang inlines it, proves an
    // int32 always fits an int64, and deletes it: the same loop compiled with and without the check timed
    // identically (0.11s both, same clang, same flags, one-token diff in the emitted C). It costs in a
    // DEBUG build, and it costs readability and `--keep-c` output in every build. Do not repeat the
    // "~19% of a 2M-iteration loop" figure for this shape — that number does not reproduce at -O3.
    std::string src = typeOfExpr(value);
    if (!src.empty()) {
        // A kind crossing (a `bool`, a `string`, an enum) is a different rule's error, not a narrowing.
        if (!cNumBits(src) && !cNumTargetWidth(src)) return "";
        // float -> int: a range test on the double (out of range or NaN is a fault the program can name —
        // it was `-fsanitize-trap=float-cast-overflow`), then the cast itself still truncates toward zero.
        if (cNumFloat(src))
            return "((" + dstCType + ")kama_f2i_chk((double)(" + emitExpression(value) + "), " + lo + ", " + hi + "))";
        if (cNumContains(dstCType, src)) return "";
        const bool sgn = cNumSigned(src);
        return "((" + dstCType + ")kama_narrow_chk_"
             + (sgn ? "s((long long)(" : "u((unsigned long long)(")
             + emitExpression(value) + "), " + lo + ", " + hi + "))";
    }
    // An UNKNOWN source — a type parameter, a const-generic parameter, an intrinsic with no recorded
    // return type, an `extern fn` result, mixed arithmetic. ⚠️ NEVER a guess and never a skip: `_Generic`
    // asks C the question this classifier could not answer, and evaluates the operand exactly once. Each
    // one that stays unanswered is a check that cannot be proved away, which is why it is worth answering:
    // `tools/check-binding-widen.sh` pins the two binding forms that no longer land here.
    return "((" + dstCType + ")KAMA_NARROW(" + emitExpression(value) + ", " + lo + ", " + hi + "))";
}

bool CEmitter::primIntRangeC(const std::string& ct, int64_t& lo, int64_t& hi)
{
    if (ct == "int8_t")   { lo = -128;            hi = 127;            return true; }
    if (ct == "int16_t")  { lo = -32768;          hi = 32767;          return true; }
    if (ct == "int32_t")  { lo = -2147483648LL;   hi = 2147483647LL;   return true; }
    if (ct == "uint8_t")  { lo = 0;               hi = 255;            return true; }
    if (ct == "uint16_t") { lo = 0;               hi = 65535;          return true; }
    if (ct == "uint32_t") { lo = 0;               hi = 4294967295LL;   return true; }
    // `char` is ranged by its WIDTH rather than by 0x10FFFF: "that is not a codepoint" is a different
    // rule from "that does not fit", and this campaign is only about the second.
    if (ct == "kama_char"){ lo = 0;               hi = 4294967295LL;   return true; }
    return false;             // int64_t (holds every fold), uint64_t, floats, size_t/ptrdiff_t, long/unsigned long, classes
}

bool CEmitter::primIntRange(SharedIdentifier type, int64_t& lo, int64_t& hi)
{
    if (!type) return false;
    SharedIdentifier t = deepSubstType(type);
    if (!t || t->genericArg) return false;
    // Which types are admitted is decided HERE, on the builtin tag, so this stays exact for a declared
    // type node (and never calls `cType`, which diagnoses on `This`/`Base`). Only the NUMBERS are
    // delegated, so the value positions — which hold no type node — cannot drift from these.
    switch (t->builtInVal) {
        case IDENTIFIER_INT8_VAL:   return primIntRangeC("int8_t",   lo, hi);
        case IDENTIFIER_INT16_VAL:  return primIntRangeC("int16_t",  lo, hi);
        case IDENTIFIER_INT32_VAL:  return primIntRangeC("int32_t",  lo, hi);
        case IDENTIFIER_UINT8_VAL:  return primIntRangeC("uint8_t",  lo, hi);
        case IDENTIFIER_UINT16_VAL: return primIntRangeC("uint16_t", lo, hi);
        case IDENTIFIER_UINT32_VAL: return primIntRangeC("uint32_t", lo, hi);
        case IDENTIFIER_CHAR_VAL:   return primIntRangeC("kama_char", lo, hi);
        // ⚠️ REFUSED ON PURPOSE, for the same reason `scalarByteSize` refuses them: a platform-varying
        // width has no one range to check against, so "does this literal fit" cannot be answered here
        // without knowing the target. Named rather than left to `default:` — see the note there.
        case IDENTIFIER_ISIZE_VAL: case IDENTIFIER_USIZE_VAL: return false;
        case IDENTIFIER_CLONG_VAL: case IDENTIFIER_CULONG_VAL: return false;   // target-width too (0.9.232)
        default: return false;    // int64 (always fits), uint64, floats, everything else
    }
}

bool CEmitter::constValue(SharedExpression e, int64_t& out)
{
    if (!e) return false;
    ASTNode* n = e.get();
    if (auto* v = dynamic_cast<Int8Node*>(n))   { out = v->value; return true; }
    if (auto* v = dynamic_cast<Int16Node*>(n))  { out = v->value; return true; }
    if (auto* v = dynamic_cast<Int32Node*>(n))  { out = v->value; return true; }
    if (auto* v = dynamic_cast<Int64Node*>(n))  { out = (int64_t)v->value; return true; }
    if (auto* v = dynamic_cast<UInt8Node*>(n))  { out = v->value; return true; }
    if (auto* v = dynamic_cast<UInt16Node*>(n)) { out = v->value; return true; }
    if (auto* v = dynamic_cast<UInt32Node*>(n)) { out = v->value; return true; }
    if (auto* v = dynamic_cast<UInt64Node*>(n)) { out = (int64_t)v->value; return true; }
    // `bool` and `char` are admissible comptime VALUE types alongside the eight integers, and they fold
    // to their integer form: a `bool` param mangles as 0/1 and a `char` as its codepoint. No collision
    // follows from sharing the integer space, because a slot's declared type is fixed by its
    // declaration — `#(true)` and `#(1)` can never occupy the same one.
    if (auto* v = dynamic_cast<BooleanNode*>(n)) { out = v->value ? 1 : 0; return true; }
    if (auto* v = dynamic_cast<CharNode*>(n))    { out = (int64_t)v->value; return true; }
    if (dynamic_cast<IdentifierNode*>(n)) return constArgN(std::static_pointer_cast<IdentifierNode>(e), out);

    // MCU 6b-1: fold const arithmetic when every operand resolves, so a const-generic param can drive a
    // computed size (`Fixed<T, N+1>`, `2*N`). Recurses through the same shape `isConstInitExpr` permits.
    // A cast is NOT value-preserving, which this arm used to assume. `InlineArray<T, cast<int8>(300)>`
    // therefore sized at 300 while the runtime cast gave 44 — the fold and the machine disagreed about
    // the same expression. Narrow the folded value the way the emitted C cast will, so they agree.
    // (The emit path rejects a provably out-of-range constant cast outright; this keeps the fold honest
    // on every path that never reaches it.)
    if (auto* c = dynamic_cast<CastNode*>(n)) {
        if (!constValue(c->unaryExpression, out)) return false;
        int64_t lo, hi;
        if (primIntRange(c->type, lo, hi) && (out < lo || out > hi)) {
            // The SAME rejection the emit path gives, because a `comptime` constant never reaches that
            // path — it is folded here and nowhere else, so `comptime int32 N = cast<int8>(300);` was
            // accepted while the identical `int8 v = cast<int8>(300);` was rejected. Two answers for one
            // expression is the thing this campaign exists to remove. Safe to report from a query
            // function only because duplicate diagnostics are now deduped on (file, line, message).
            rejectConstCastOverflow(c->type, out, lo, hi, c->line);
            const uint64_t span = (uint64_t)(hi - lo) + 1;             // 2^width, exactly
            out = lo + (int64_t)(((uint64_t)(out - lo)) % span);       // wrap, as C does
        }
        return true;
    }
    // M6: `sizeof(T)` for a fixed-width scalar. One arm serves every consumer, because they all route
    // here — module/type/local `comptime`, a const-generic argument (via constArgN), an InlineArray size,
    // a `[v; N]` fill count — and the binary recursion below gives `sizeof(int32) * 8` for free.
    if (auto* s = dynamic_cast<SizeofNode*>(n)) {
        if (s->isAlign) return false;   // alignment is an ABI choice kama has no premise to fold — see scalarByteSize
        return scalarByteSize(s->type, out);
    }
    if (auto* u = dynamic_cast<SimpleUnaryExpressionNode*>(n)) {
        int64_t v;
        if (!constValue(u->expression, v)) return false;
        switch (u->token) {
            case PLUS:  out = v;   return true;
            case MINUS: out = -v;  return true;
            case TILDE: out = ~v;  return true;
            default:    return false;   // `!` etc. — not an integer fold
        }
    }
    if (auto* b = dynamic_cast<BinaryExpressionNode*>(n)) {
        int64_t l, r;
        if (!constValue(b->LHS, l) || !constValue(b->RHS, r)) return false;
        // The folder is an ESCAPE HATCH from the emit walk, and this measures how wide it is. A module
        // `comptime`/`static` initializer is baked from this fold and never reaches `emitBinaryOperator`,
        // so an operand rule that lives only there would be silent on `comptime int32 A = 1i8 + 2i32;`.
        // Milestone 2 found the same asymmetry with `cast` and closed it by diagnosing from the folder;
        // whether this one is worth a second home is what the `const-fold` count decides.
        noteNumericOperands(b->token, b->LHS, b->RHS, ("const-fold " + binaryOperator(b->token)).c_str(),
                            b->line);
        switch (b->token) {
            case PLUS:    out = l + r; return true;
            case MINUS:   out = l - r; return true;
            case STAR:    out = l * r; return true;
            case SLASH:   if (r == 0 || (l == INT64_MIN && r == -1)) return false; out = l / r; return true;
            case PERCENT: if (r == 0 || (l == INT64_MIN && r == -1)) return false; out = l % r; return true;
            case LTLT:    if (r < 0 || r >= 64) return false; out = (int64_t)((uint64_t)l << r); return true;
            case GTGT:    if (r < 0 || r >= 64) return false; out = l >> r; return true;
            case AMP:     out = l & r; return true;
            case BAR:     out = l | r; return true;
            case CARET:   out = l ^ r; return true;
            default:      return false;   // comparisons/logical — not an integer size fold
        }
    }
    return false;
}

// The const value carried by a generic ARGUMENT node: a literal wrapped by the grammar
// (`constArgValue`, as in `Fixed<T,4>`), or a bare const-param identifier bound in this
// instantiation (`Fixed<T,N>`). Returns false for a type argument (no const value).
// Rewrite a compile-time size written as a NAME into its literal value, in place. Called while COLLECTING
// a declaration, which is the one moment the declaring file's scope is installed — see the call site for
// why a member's size must not be left to the reader's imports.
//
// A size that does not fold here is left exactly as written: inside a generic template `N` is a comptime
// PARAMETER and must stay symbolic until an instantiation binds it, and `shadowed` keeps a parameter that
// happens to share a name with a module constant from being baked to the constant's value.
void CEmitter::bakeConstSizes(SharedIdentifier t, const SharedStringList& shadowed)
{
    if (!t) return;
    if (t->genericArgs) for (auto& a : *t->genericArgs) bakeConstSizes(a, shadowed);
    else if (t->genericArg) bakeConstSizes(t->genericArg, shadowed);
    if (!t->genericArgs || t->genericArgs->size() != 2) return;
    SharedIdentifier n = (*t->genericArgs)[1];
    if (!n || !n->value || n->constArgValue || n->genericArg) return;   // already literal, or not a name
    if (shadowed) for (auto& sp : *shadowed) if (sp && *sp == *n->value) return;
    int64_t v;
    if (!constArgN(n, v)) return;                                       // still symbolic: leave it alone
    if (!_synthCtx) _synthCtx = std::make_shared<CodeGenContext>(std::make_shared<std::string>("<synth>"));
    auto id = std::make_shared<IdentifierNode>(*_synthCtx, SharedString());
    id->synthesized   = true;
    id->constArgValue = std::make_shared<Int64Node>(*_synthCtx, v);
    (*t->genericArgs)[1] = id;
}

bool CEmitter::constArgN(SharedIdentifier arg, int64_t& out)
{
    if (!arg) return false;
    if (arg->constArgValue) return constValue(arg->constArgValue, out);
    // 6b-2: `Type::NAME` -> a type-associated `comptime` constant. Resolve the type name (last qualifier
    // segment, through the file's scope) and look up its folded value. Access control is checked at the
    // read site (emitPrimary), not here — a size position is always within the same compile.
    if (arg->value && arg->qualifier && !arg->qualifier->empty()) {
        auto tq = std::make_shared<StringList>();
        for (size_t i = 0; i + 1 < arg->qualifier->size(); ++i) tq->push_back((*arg->qualifier)[i]);
        std::string en = resolveUserName(*arg->qualifier->back(), tq);
        auto tc = _typeConsts.find(en + "::" + *arg->value);
        if (tc != _typeConsts.end() && tc->second.hasValue) { out = tc->second.value; return true; }
        // ...or `module::NAME`, a module `comptime` spelled qualified. This branch used to return here, so
        // `#(geo::CAP)` never reached the module lookup below and a legal size failed to fold.
        const std::string mk = resolveModuleVar(*arg->value, arg->qualifier);
        auto mc = mk.empty() ? _moduleConsts.end() : _moduleConsts.find(mk);
        if (mc != _moduleConsts.end()) { out = mc->second; return true; }
        return false;
    }
    if (arg->value && !arg->genericArg) {
        auto it = _comptimeSubst.find(*arg->value);
        if (it != _comptimeSubst.end()) { out = it->second.value; return true; }
        // 6b-2: a function-local `const` bound to a folded integer (`const int32 CAP = 8;` then
        // `InlineArray<T,(CAP)>` / `[v;(CAP)]`). Consulted after the generic-param binding.
        auto lv = _constLocalVals.find(*arg->value);
        if (lv != _constLocalVals.end()) { out = lv->second; return true; }
        // 6b-2: a module `comptime NAME`. Through `resolveModuleVar`, not a bare `qualify`, so an
        // IMPORTED constant can size an `InlineArray` too — publishing a constant is only useful if a
        // consumer can then use it where a constant is required. (A QUALIFIED one is the branch above.)
        const std::string mk = resolveModuleVar(*arg->value, arg->qualifier);
        if (!mk.empty()) {
            auto mc = _moduleConsts.find(mk);
            if (mc != _moduleConsts.end()) { out = mc->second; return true; }
        }
    }
    return false;
}

// The `sizeof`/`alignof` inside a const-argument expression, if any — so the diagnostic below can name the
// reason the fold failed instead of stating a generic rule. Walks the shape constValue itself recurses.
static SizeofNode* findSizeof(ExpressionNode* e)
{
    if (!e) return nullptr;
    if (auto* s = dynamic_cast<SizeofNode*>(e)) return s;
    if (auto* u = dynamic_cast<SimpleUnaryExpressionNode*>(e)) return findSizeof(u->expression.get());
    if (auto* c = dynamic_cast<CastNode*>(e))                  return findSizeof(c->unaryExpression.get());
    if (auto* b = dynamic_cast<BinaryExpressionNode*>(e)) {
        if (auto* l = findSizeof(b->LHS.get())) return l;
        return findSizeof(b->RHS.get());
    }
    return nullptr;
}

// M6: a const-generic argument the author wrote as a VALUE which does not fold to a compile-time integer.
// Before M6 this fell through to the `_typeSubst` arm below and bound the const param as a TYPE, so the
// param's name reached the emitted C undeclared — clang reported it and kama said nothing at all
// (`idN::<(sizeof(Blk))>()`). Gated on `constArgValue`, which the grammar sets exactly on the `literal` and
// `( expression )` arms (kama.y:607-608): a value argument can never be a type substitution, so failing to
// fold is unambiguously an error. A BARE identifier argument is deliberately left alone — it is a type name
// until proven otherwise, and that path is what every existing generic relies on.
void CEmitter::rejectUnfoldableConstArg(const std::string& param, SharedIdentifier arg)
{
    if (!arg || !arg->constArgValue) return;
    // Report each offending argument ONCE. An instantiation's params are re-bound on every discovery pass
    // (bindInstParams has three call sites), so without this the same line prints three times.
    if (!_badConstArgs.insert(arg->constArgValue.get()).second) return;
    SizeofNode* sz = findSizeof(arg->constArgValue.get());
    std::string why =
        (sz && sz->isAlign) ? "`alignof` does not fold — alignment is a target ABI property, not a language "
                              "guarantee (1 on AVR, and `_Alignof(double)` is 4 on i386)"
      : (sz)               ? "`sizeof` folds only for fixed-width scalars (`int8`..`int64`, `uint8`..`uint64`, "
                             "`char`, `float32`, `float64`) — `usize`/`isize`, `bool`, `string` and user types "
                             "have target- or layout-dependent size"
                           : "it must be an integer literal, a comptime parameter, or "
                             "arithmetic over those";
    // Phrased to read after the "unsupported " prefix `unsupported()` prints.
    unsupported(("comptime argument for `" + param + "` — it does not fold to a compile-time integer; "
                 + why).c_str(), arg->constArgValue->line);
}

// --- `comptime assert(cond:, msg:)` — const-generics M7 --------------------------------------------------
//
// One surface, TWO lowerings, and the rule below is what picks between them. The split exists because M6
// drew `sizeof`'s fold boundary at fixed-width scalars: kama owns what the LANGUAGE fixes and never what
// the ABI decides, since clang — not kama — lays out aggregates. So a predicate kama can answer, kama
// answers (a real diagnostic, visible to `kama check` and the LSP); a predicate that turns on a layout fact
// kama deliberately does not model is handed to the C compiler as a C11 `_Static_assert`. That is what
// makes M6's narrow fold cost nothing: the cases it refuses are exactly the cases clang is the authority on.

// Does this predicate turn on a `sizeof`/`alignof` that kama cannot fold? If so it must go to C — asking
// the interpreter first would only produce M6's "does not fold" diagnostic for a question that HAS a right
// answer on the target. Every `alignof`, `sizeof` of an aggregate, and `sizeof(usize)` lands here.
bool CEmitter::ctaNeedsCLowering(SharedExpression e)
{
    if (!e) return false;
    ASTNode* n = e.get();
    if (auto* s = dynamic_cast<SizeofNode*>(n)) {
        int64_t sz;
        return s->isAlign || !scalarByteSize(s->type, sz);
    }
    if (auto* u = dynamic_cast<SimpleUnaryExpressionNode*>(n)) return ctaNeedsCLowering(u->expression);
    if (auto* c = dynamic_cast<CastNode*>(n))                  return ctaNeedsCLowering(c->unaryExpression);
    if (auto* b = dynamic_cast<BinaryExpressionNode*>(n))      return ctaNeedsCLowering(b->LHS) || ctaNeedsCLowering(b->RHS);
    if (auto* l = dynamic_cast<LogicalAndOrNode*>(n))          return ctaNeedsCLowering(l->LHS) || ctaNeedsCLowering(l->RHS);
    return false;
}

// Render a layout predicate as a C constant expression. Returns false for any leaf that is not a pure
// layout/constant fact — a runtime value, a call, a field read — which is what keeps this from silently
// emitting a `_Static_assert` over something clang would reject for a different reason entirely.
bool CEmitter::ctaRenderC(SharedExpression e, std::string& out)
{
    if (!e) return false;
    ASTNode* n = e.get();
    // Anything that folds in kama renders as its VALUE — an integer literal, a `comptime` constant, a const
    // generic parameter, `sizeof` of a fixed-width scalar, arithmetic over those. One arm covers them all
    // because they all route through constValue, and baking the value keeps the emitted C independent of
    // whether the name is even visible at that point in the generated file.
    int64_t v;
    if (constValue(e, v)) { out = std::to_string(v); return true; }
    if (auto* s = dynamic_cast<SizeofNode*>(n)) {
        SharedIdentifier t = deepSubstType(s->type);   // so `sizeof(T)` works inside a generic instance
        if (!t) return false;
        std::string ct = cType(t);
        if (ct.empty()) return false;
        out = (s->isAlign ? "_Alignof(" : "sizeof(") + ct + ")";
        return true;
    }
    if (auto* c = dynamic_cast<CastNode*>(n)) return ctaRenderC(c->unaryExpression, out);
    if (auto* u = dynamic_cast<SimpleUnaryExpressionNode*>(n)) {
        std::string s;
        if (!ctaRenderC(u->expression, s)) return false;
        const char* op = u->token == PLUS  ? "+" : u->token == MINUS       ? "-"
                       : u->token == TILDE ? "~" : u->token == EXCLAMATION ? "!" : nullptr;
        if (!op) return false;
        out = std::string(op) + "(" + s + ")";
        return true;
    }
    if (auto* b = dynamic_cast<BinaryExpressionNode*>(n)) {
        std::string l, r;
        if (!ctaRenderC(b->LHS, l) || !ctaRenderC(b->RHS, r)) return false;
        std::string op = binaryOperator(b->token);
        if (op == "/*?op*/") return false;
        out = "(" + l + ") " + op + " (" + r + ")";
        return true;
    }
    if (auto* l = dynamic_cast<LogicalAndOrNode*>(n)) {
        std::string a, b;
        if (!ctaRenderC(l->LHS, a) || !ctaRenderC(l->RHS, b)) return false;
        out = "(" + a + ") " + (l->token == ANDAND ? "&&" : "||") + " (" + b + ")";
        return true;
    }
    return false;
}

// The whole statement, at every scope it is legal in. Called from emitStatement (function bodies), from
// emitModuleContent (module scope) and from the per-class walks (type-member scope) — including the
// per-instantiation one, which is why a failure inside a generic names the instance that failed.
void CEmitter::emitComptimeAssert(ComptimeAssertNode* a)
{
    if (!a) return;
    if (a->modifiers && !a->modifiers->empty()) {
        unsupported("visibility on a `comptime assert` — an assertion is not a member anything can reach",
                    a->line);
        return;
    }
    // The grammar accepts any callee here on purpose: the trailing `(` is what keeps the production
    // LALR(1)-clean against `comptime <type> <name>`, so the name is checked where a real diagnostic can
    // be written rather than as a parse error that could only say "syntax error".
    const std::string name = (a->callee && a->callee->value) ? *a->callee->value : std::string();
    const bool bare = (!a->callee || !a->callee->qualifier || a->callee->qualifier->empty());
    if (!bare || name != "assert") {
        unsupported(("compile-time statement `comptime " + (name.empty() ? std::string("?") : name)
                     + "(...)` — the only one is `comptime assert(cond: …, msg: \"…\")`").c_str(), a->line);
        return;
    }
    SharedExpression cond, msg;
    if (a->args) for (auto& ar : *a->args) {
        if (!ar || !ar->name || !ar->name->value) continue;
        if      (*ar->name->value == "cond") cond = ar->expression;
        else if (*ar->name->value == "msg")  msg  = ar->expression;
    }
    if (!cond) { unsupported("`comptime assert` requires `cond:`", a->line); return; }
    if (!msg)  { unsupported("`comptime assert` requires `msg:` (use `msg: \"\"` for none)", a->line); return; }
    // A LITERAL, not any string expression — the runtime `assert` accepts the latter, but C11
    // `_Static_assert` needs a literal, and one rule across both lowerings beats a rule that changes
    // depending on which one the predicate happens to take.
    auto* lit = dynamic_cast<StringNode*>(msg.get());
    if (!lit || !lit->value) {
        unsupported("`msg:` on a `comptime assert` — it must be a plain string LITERAL (no interpolation): "
                    "the aggregate form lowers to a C11 `_Static_assert`, whose message is a literal",
                    a->line);
        return;
    }
    const std::string condText = unparseExpr(cond);
    const std::string message  = *lit->value;

    // --- lowering 2: a layout fact only the target knows -> let the C compiler answer it ---
    if (ctaNeedsCLowering(cond)) {
        std::string c;
        if (!ctaRenderC(cond, c)) {
            unsupported(("`comptime assert` predicate `" + condText + "` mixes a layout fact "
                         "(`sizeof`/`alignof` of an aggregate) with something that is not a compile-time "
                         "constant — a layout assertion may only combine `sizeof`/`alignof`, literals and "
                         "`comptime` constants").c_str(), a->line);
            return;
        }
        // Both halves are optional: `msg: ""` is allowed, and unparseExpr returns "" for a form it does
        // not render. Joining unconditionally produced a dangling "— " in the C compiler's own output.
        std::string note = message.empty() ? condText
                         : condText.empty() ? message
                                            : (message + " — " + condText);
        std::string s = "_Static_assert(" + c + ", \"kama: " + cEscapeStringBody(note) + " ("
                      + cEscapeStringBody(_sourcePath) + ":" + std::to_string(a->line) + ")\");\n";
        // One instantiation's worth is enough: a generic type's members are re-walked per instance, and a
        // monomorph reached twice would otherwise repeat its assert verbatim. Keyed on the emitted text, so
        // two DIFFERENT instances (`Fixed<16>` / `Fixed<24>`) still each get theirs.
        if (_staticAsserts.insert(s).second) _fileScopeHelpers.push_back(s);
        return;
    }

    // --- lowering 1: kama can answer it, so kama answers it ---
    // Through the comptime interpreter, not constValue: `constValue` is deliberately an integer-SIZE fold
    // whose `default: return false` arms drop every comparison and logical operator, while ctEvalExpr
    // already produces a CTValue::Bool for all of them.
    _ctSteps = 0; _ctDepth = 0; _ctFailed = false; _ctCurrentOwner.clear();
    CTEnv env;
    CTValue v;
    if (!ctEvalExpr(cond, env, v)) return;    // ctEvalExpr has already reported precisely why
    if (v.kind != CTValue::Bool) {
        ctFail(("`comptime assert` condition `" + condText + "` is not a boolean").c_str(), a->line);
        return;
    }
    if (v.i == 0) {
        // Name the instantiation. The assert's own line is the same for every instance of a generic, so
        // without the bindings a failure says WHAT broke but not WHICH use site broke it — and finding
        // that by hand is the whole cost this milestone exists to remove.
        // TYPE bindings first, then const ones. A width check reads `F < sizeof(B) * 8`, so naming only
        // the const half says `[with F = 16]` and leaves the reader to work out which `B` it was paired
        // with — which is the half of a bad pairing that is actually hard to see from the use site.
        // A generic TYPE keeps every parameter in _typeSubst, const ones included (bindInstParams), so a
        // const name has to be skipped here or it prints twice — once with no type to render.
        std::string binds;
        for (auto& kv : _typeSubst) {
            if (_comptimeSubst.count(kv.first) || !kv.second) continue;
            std::string t = qualifiedName(kv.second);
            if (!t.empty()) binds += (binds.empty() ? "" : ", ") + kv.first + " = " + t;
        }
        for (auto& kv : _comptimeSubst)
            binds += (binds.empty() ? "" : ", ") + kv.first + " = " + std::to_string(kv.second.value);
        ctFail(("assertion failed: " + (condText.empty() ? std::string("<condition>") : condText)
                + (message.empty() ? std::string() : " — " + message)
                + (binds.empty()   ? std::string() : " [with " + binds + "]")).c_str(), a->line);
    }
}

// Every `comptime assert` declared directly in a type body, under whatever substitution is bound now. For a
// generic that is one call per instantiation (see emitGenericTypeInst), which is the entire point: the
// predicate is checked against the arguments the use site actually passed.
void CEmitter::emitComptimeAssertsIn(ClassDeclarationNode* cd)
{
    if (!cd || !cd->members) return;
    for (auto& m : *cd->members)
        if (auto* a = dynamic_cast<ComptimeAssertNode*>(m.get())) emitComptimeAssert(a);
}

// Bind one instantiation's parameters. A const param binds a VALUE plus the width it was declared with;
// every other param binds a type. One loop, so the two maps can never disagree about which is which.
void CEmitter::bindInstParams(const SharedStringList& params, const SharedIdentifierList& constTypes,
                              const std::vector<SharedIdentifier>& args)
{
    _typeSubst.clear();
    _comptimeSubst.clear();
    if (!params) return;
    for (size_t i = 0; i < params->size() && i < args.size(); ++i) {
        if (!(*params)[i]) continue;
        const std::string& pn = *(*params)[i];
        // `constTypes` is parallel to `params` and non-null exactly on a const param — the same fact
        // `comptimeParams` carries as a name subset, but positional, so the declared width comes with it.
        SharedIdentifier ct = (constTypes && i < constTypes->size()) ? (*constTypes)[i] : SharedIdentifier();
        int64_t v;
        if (ct && constArgN(args[i], v)) { ConstBinding b; b.value = v; b.kind = ct->builtInVal; _comptimeSubst[pn] = b; }
        else { if (ct) rejectUnfoldableConstArg(pn, args[i]);   // a const param whose VALUE arg won't fold
               _typeSubst[pn] = args[i]; }
    }
}

void CEmitter::bindInstConstParams(const std::string& tmplKey, const std::vector<SharedIdentifier>& args)
{
    auto cti = _genericTypeConstTypes.find(tmplKey);
    if (cti == _genericTypeConstTypes.end()) return;
    const std::vector<SharedIdentifier>& cts = cti->second;
    const std::vector<std::string>& ps = _genericTypeParams[tmplKey];
    // While PROBING the argument is a placeholder (see probeConstArg), so binding it would fold every
    // expression that reads `N` against a number nobody wrote. Leave it unbound: the function half has
    // always walked a `const` parameter that way, and a type error in the body is caught either way.
    if (_probingTemplate) return;
    for (size_t i = 0; i < ps.size() && i < args.size() && i < cts.size(); ++i) {
        if (!cts[i]) continue;                       // a type param — already bound in _typeSubst
        int64_t v;
        if (constArgN(args[i], v)) { ConstBinding b; b.value = v; b.kind = cts[i]->builtInVal; _comptimeSubst[ps[i]] = b; }
        else rejectUnfoldableConstArg(ps[i], args[i]);
    }
}

// A bound const param as a C value: the integer, cast to the type it was declared with. Without the cast
// a bare `8` is a C `int`, so `const F: uint32` would compare signed and `const F: int8` would not wrap
// where a real `int8` local does — the value has to behave as the declared type under every promotion.
std::string CEmitter::constParamCValue(const std::string& name)
{
    auto it = _comptimeSubst.find(name);
    if (it == _comptimeSubst.end()) return "";
    const ConstBinding& b = it->second;
    std::string lit = std::to_string(b.value);
    // The literal has to be REPRESENTABLE before the cast can apply, so the 64-bit kinds keep a suffix.
    if (b.kind == IDENTIFIER_INT64_VAL)  lit += "LL";
    if (b.kind == IDENTIFIER_UINT64_VAL) lit = std::to_string((uint64_t)b.value) + "ULL";
    return "((" + cType(primTypeNode(b.kind)) + ")" + lit + ")";
}

bool CEmitter::isFixedColl(const std::string& cls) const
{
    auto it = _classes.find(cls);
    return it != _classes.end() && it->second.isIntrinsicColl && it->second.collKind == CollKind::Fixed;
}

bool CEmitter::isSimdColl(const std::string& cls) const
{
    auto it = _classes.find(cls);
    return it != _classes.end() && it->second.isIntrinsicColl && it->second.collKind == CollKind::Simd;
}

bool CEmitter::isMaskColl(const std::string& cls) const
{
    auto it = _classes.find(cls);
    return it != _classes.end() && it->second.isIntrinsicColl && it->second.collKind == CollKind::Mask;
}

// The mangling suffix for an element type: primitives use a short stable
// spelling; a class/enum uses its own name. Array<int32> -> "int32".
std::string CEmitter::mangleElem(SharedIdentifier elem)
{
    if (!elem) return "void";
    // comptime ARGUMENT: a literal value (`Fixed<T,4>`) or a const-param identifier bound in
    // this instantiation (`Fixed<T,N>` with N=4) mangles to the integer itself (`_4`), symmetric to
    // a type arg's name. Consulted before the type-param path since a const arg has no `value`.
    // A NEGATIVE value spells its sign as `n`: `-` is not a C identifier character, so `f::<(-1)>()`
    // otherwise mangled to `_F<file>__neg8__-1` and died in the C compiler with no kama diagnostic.
    { int64_t v; if (constArgN(elem, v))
        return v < 0 ? "n" + std::to_string(-(uint64_t)v) : std::to_string(v); }
    // substitute a bound type-param before mangling (mirrors cType).
    if (!_typeSubst.empty() && elem->value && !elem->genericArg) {
        auto s = _typeSubst.find(*elem->value);
        if (s != _typeSubst.end()) return mangleElem(s->second);
    }
    switch (elem->builtInVal) {
        case IDENTIFIER_STRING_VAL:  return "string";
        case IDENTIFIER_INT8_VAL:    return "int8";
        case IDENTIFIER_INT16_VAL:   return "int16";
        case IDENTIFIER_INT32_VAL:   return "int32";
        case IDENTIFIER_INT64_VAL:   return "int64";
        case IDENTIFIER_UINT8_VAL:   return "uint8";
        case IDENTIFIER_UINT16_VAL:  return "uint16";
        case IDENTIFIER_UINT32_VAL:  return "uint32";
        case IDENTIFIER_UINT64_VAL:  return "uint64";
        case IDENTIFIER_BOOL_VAL:    return "bool";
        case IDENTIFIER_FLOAT32_VAL: return "float32";
        case IDENTIFIER_FLOAT64_VAL: return "float64";
        // The size types mangle by their KAMA spelling, not their C one — a container instance is
        // `DynamicArray_isize`, never `DynamicArray_ptrdiff_t`. These were a string test ahead of this
        // switch until 0.9.136, because they carried no `builtInVal` and `default:` handed them to
        // `resolveUserName`, which does not answer for a primitive: the suffix came back empty and the
        // call site emitted an UNMANGLED `std__ptr__relocate(...)`, which C rejects as an implicit
        // declaration. Latent until something instantiated a container at `isize` — `DynamicArray<isize>`
        // never compiled.
        case IDENTIFIER_ISIZE_VAL:   return "isize";
        case IDENTIFIER_USIZE_VAL:   return "usize";
        // The C ABI elements mangle by their kama spelling too — `cchar` included, because a raw-pointer generic
        // argument (`DynamicArray<UnsafeConstPtr<cchar>>`) reaches this switch, and `default:` would hand
        // `resolveUserName("cchar")` back empty: the unmangled-call defect the size types had.
        case IDENTIFIER_CCHAR_VAL:   return "cchar";
        case IDENTIFIER_CLONG_VAL:   return "clong";
        case IDENTIFIER_CULONG_VAL:  return "culong";
        // A source-spelled `char` used to survive on the `default:` arm (resolveUserName("char") finds no
        // user type and hands the spelling back), but a char LITERAL argument synthesizes its type node
        // (primTypeNode) with an empty `value` — which mangled to "" and gave one type two monomorphs.
        case IDENTIFIER_CHAR_VAL:    return "char";
        default: {  // class / generic element — resolve to its mangled name (the suffix)
            if (!elem->value) return "void";
            // M6 B3h: pass the SITE. A generic ARGUMENT (`Sp` in `Owned<Sp>`, `Circle` in
            // `List<Shared<Circle>>`) resolves here and nowhere else, so without this it was indexed
            // nowhere and renaming the argument type left every such spelling behind — B3a's silent
            // under-apply again. buildPositions dedups by identifier node, so the re-walks are free.
            std::string base = resolveUserName(*elem->value, elem->qualifier, elem.get());
            // A generic INSTANCE (`Shared<C>`, `DynamicArray<int32>`) mangles through genericTypeMangle so
            // its DEFAULT type params + named overrides fill EXACTLY as in cType — a partially-applied
            // `Shared<C>` becomes `Shared_C_GlobalAllocator` (not `Shared_C`), matching the class struct
            // name. Else a nested `Optional<Shared<C>>` name (built here in registerGenericTypeInst) would
            // diverge from its filled body → two incompatible C structs. (M8 default-fill; latent until a
            // smart pointer with a defaulted param was nested in a generic.)
            if (elem->genericArgs && (_genericTypes.count(base) || _genericContracts.count(base)))
                return genericTypeMangle(base, elem->genericArgs);
            // recurse into a nested generic arg so `Shared<Circle>` mangles to
            // `Shared_Circle` (not just `Shared`) — fixes the `List<Shared<Circle>>` collision.
            if (elem->genericArgs) for (auto& a : *elem->genericArgs) base += "_" + mangleElem(a);
            else if (elem->genericArg) base += "_" + mangleElem(elem->genericArg);
            // A bare all-defaulted generic (`BitSet` == `BitSet<GlobalAllocator>`) mangles to its
            // defaulted instance name, matching cType (so a `DynamicArray<BitSet>` element mangles right).
            else if (_genericTypes.count(base) && allTypeParamsDefaulted(base)) return genericTypeMangle(base, nullptr);
            return base;
        }
    }
}

// the mangled struct name for `Pair<A, B, …>` — the template's scoped name + one "_<mangle>"
// suffix per type arg. `mangleElem` resolves a bound `T` under _typeSubst, so this is used identically
// at discovery (concrete args), at cType (field/decl args under subst), and to name the specialized ClassInfo.
void CEmitter::positionalizeGenericArgs(const std::vector<std::string>& params,
                                        const std::vector<SharedIdentifier>& defaults,
                                        SharedIdentifierList args,
                                        std::vector<SharedIdentifier>& full,
                                        std::vector<bool>& isDefault)
{
    full.assign(params.size(), SharedIdentifier());
    isDefault.assign(params.size(), false);
    size_t pos = 0;
    if (args) for (auto& a : *args) {
        if (a && a->argName) {                                   // named override -> place by param name
            for (size_t i = 0; i < params.size(); ++i)
                if (params[i] == *a->argName) { full[i] = a; break; }
        } else if (pos < params.size()) {                        // positional -> next free leading slot
            full[pos++] = a;
        }
        // overflow / unknown-name are ignored here; the registration path reports them precisely.
    }
    for (size_t i = 0; i < params.size(); ++i)                   // fill trailing gaps from defaults
        if (!full[i] && i < defaults.size()) { full[i] = defaults[i]; isDefault[i] = true; }
}

// Report a precise error for a bad use-site type-arg list (unknown named param, positional-after-named,
// too many args, or a required param left unbound). `bound` is positionalizeGenericArgs's output. Returns
// false (after emitting the error) on any problem, true when the binding is well-formed. `kind` is
// "type"/"contract" for the message.
bool CEmitter::validateGenericArgs(const std::string& tmpl, const char* kind,
                                   const std::vector<std::string>& params, SharedIdentifierList args,
                                   const std::vector<SharedIdentifier>& bound, int line)
{
    // The template's slots split into a TYPE group and a compile-time VALUE group (types first — see
    // splitFnParams / makeTypeDeclaration). Every count and every noun below has to name the group the
    // reader actually wrote, or the diagnostic sends them to the wrong pair of brackets: an omitted
    // `#(4)` used to report "wrong number of TYPE arguments", pointing at `<…>`, which is correct about
    // nothing except the arity.
    auto ctIt = _genericTypeConstTypes.find(tmpl);
    const std::vector<SharedIdentifier>* cts = ctIt != _genericTypeConstTypes.end() ? &ctIt->second : nullptr;
    auto isValueSlot = [&](size_t i) { return cts && i < cts->size() && (*cts)[i]; };
    size_t nTypes = 0;
    for (size_t i = 0; i < params.size(); ++i) if (!isValueSlot(i)) ++nTypes;

    size_t pos = 0; bool sawNamed = false;
    if (args) for (auto& a : *args) {
        if (a && a->argName) {
            sawNamed = true;
            bool found = false;
            for (auto& p : params) if (p == *a->argName) { found = true; break; }
            if (!found) {
                unsupported(("unknown type parameter `" + *a->argName + "` for generic " + kind + " `" + tmpl + "`").c_str(), a->line);
                return false;
            }
        } else {
            if (sawNamed) { unsupported("positional type argument after a named one", a ? a->line : line); return false; }
            if (pos >= params.size()) {
                unsupported(("wrong number of type arguments for generic " + std::string(kind) + " `" + tmpl + "` (expected "
                             + std::to_string(params.size()) + ", got more)").c_str(), line);
                return false;
            }
            pos++;
        }
    }
    for (size_t i = 0; i < params.size(); ++i)
        if (!bound[i]) {
            if (isValueSlot(i))
                unsupported(("generic " + std::string(kind) + " `" + tmpl + "` is missing its compile-time argument `"
                             + params[i] + "` — a compile-time VALUE goes in its own group, `#(…)`, "
                             "never in `<…>`").c_str(), line);
            else
                unsupported(("wrong number of type arguments for generic " + std::string(kind) + " `" + tmpl + "` (expected "
                             + std::to_string(nTypes) + ", missing `" + params[i] + "`)").c_str(), line);
            return false;
        }
    return true;
}

// Split a mangled template key (`std__collections__View`) back into a qualified type node — value `View`,
// qualifier ["std", "collections"]. Named separately because the split is the non-obvious half: the key is
// the only handle registerFixedViews has on the stdlib's View, and the two consumers want opposite halves
// of it (cType wants the mangle, inference wants the bare name).
SharedIdentifier CEmitter::viewQualifiedNode(const std::string& tmplKey)
{
    std::vector<std::string> segs;
    size_t start = 0;
    for (size_t i = 0; (i = tmplKey.find("__", start)) != std::string::npos; start = i + 2)
        segs.push_back(tmplKey.substr(start, i - start));
    segs.push_back(tmplKey.substr(start));
    auto n = synthId(segs.back());
    if (segs.size() > 1) {
        auto q = std::make_shared<StringList>();
        for (size_t i = 0; i + 1 < segs.size(); ++i) q->push_back(std::make_shared<std::string>(segs[i]));
        n->setQualifier(q);
    }
    return n;
}

// Give every registered `InlineArray<T,N>` its `view()` and the `Viewable<View<T>>` grant that makes the
// mint legitimate. A PASS rather than a line in registerFixed, and the reason is ordering: registerFixed
// runs while units are still being collected, so whether `std::collections::View` existed yet depended on
// the user's unrelated imports — `FixedArray` drags View in through its own module, a prelude builtin
// drags in nothing. `a.view()` therefore resolved or not according to which other containers the file
// happened to mention. Running once, after every unit is collected, makes View's availability a settled
// fact instead of a race.
//
// If the program has no `View` at all, `view()` is simply not registered and `a.view()` is an ordinary
// "no such method" — deterministic, and the honest answer: `View<T>` is a stdlib type, so a program that
// never imports it does not have one. `dataPtr()` is unaffected and always present.
void CEmitter::registerFixedViews()
{
    const std::string viewTmpl  = viewTemplateKey();
    const std::string constTmpl = constViewTemplateKey();
    if (viewTmpl.empty() || constTmpl.empty()) return;   // one module declares both; neither, or both
    // Collect first: registerGenericTypeInst can register further collections, and mutating
    // `_collections` while iterating it would invalidate the iterator.
    std::vector<std::string> fixed;
    for (auto& kv : _collections)
        if (kv.second.kind == CollKind::Fixed && kv.second.elem
            && _classes.count(kv.first) && !_classes[kv.first].methods.count("view"))
            fixed.push_back(kv.first);

    for (auto& name : fixed) {
        SharedIdentifier elem = _collections[name].elem;
        // One mint per half, exactly as the stdlib containers spell them: `view()` is the READ-ONLY window
        // (`ConstView<T>`, a `const fn`, so a `const` InlineArray can open one) and `viewMut()` the
        // mutate-through one (`View<T>`). Each carries its own grant.
        auto mint = [&](const char* member, const char* contract, const std::string& tmpl, bool isConst) {
            auto viewArgs = std::make_shared<IdentifierList>();
            viewArgs->push_back(elem);
            registerGenericTypeInst(tmpl, viewArgs);
            // The return node is spelled as a QUALIFIED reference — `std::collections::View<T>` — not as the
            // pre-mangled key. Both resolve to the same C type, but only this one carries the bare name
            // `View` in `value`, and generic-argument INFERENCE matches a `View<T>` parameter by that name:
            // with the mangled spelling, `sortUnstable(items: v)` could not infer `T` from a view an
            // InlineArray minted, while the identical call over a FixedArray's view inferred it fine.
            // Qualifying also makes the reference independent of the calling file's imports, which a bare
            // `View` would not be.
            auto viewRet = viewQualifiedNode(tmpl);
            viewRet->genericArg  = elem;
            viewRet->genericArgs = std::make_shared<IdentifierList>();
            viewRet->genericArgs->push_back(elem);

            ClassInfo& ci = _classes[name];   // after the instantiation above, which may grow `_classes`
            MethodInfo mi; mi.cName = name + "__" + member;
            mi.returnType = viewRet; mi.isIntrinsic = true; mi.isConst = isConst;
            ci.methods[member] = mi;

            // The grant. `Viewable<V>` is a generic contract, so its instance must be registered before it
            // can be named — the same two-step `synthConformanceName` does for `Deserializable<T>` — and the
            // instance name is the one registerGenericContractInst computes: template + mangled args.
            // `borrow` and `parallel_for` read this to prove the host IS the thing being viewed rather than a
            // type forwarding somebody else's view, and here it states a fact: an `InlineArray` is
            // `struct { T v[N]; }`, so a view minted from it views that struct's own bytes.
            if (_genericContractParams.count(contract)) {
                auto vwArgs = std::make_shared<IdentifierList>();
                vwArgs->push_back(viewRet);
                registerGenericContractInst(contract, vwArgs);
                ci.interfaces.push_back(std::string(contract) + "_" + mangleElem(viewRet));
            }
        };
        mint("view",    "Viewable",    constTmpl, /*isConst=*/true);
        mint("viewMut", "ViewableMut", viewTmpl,  /*isConst=*/false);
    }
}

// The template key of the stdlib's `type view View<T>` — `std__collections__View`, not the bare `View`.
//
// It cannot be resolved by name from registerFixed, which is the caller that needs it: resolveUserName
// answers under the ctx of whatever unit is being collected, and a program that never imports `View`
// (the common case — `InlineArray` is a prelude builtin) would resolve it to nothing. Nor is the path
// hardcoded: the stdlib may move it. It is IDENTIFIED instead, by the two facts that define it — a
// single-parameter generic whose bare tail is `View` and whose template shape is a `type view`
// (`isBorrow`). Cached because it is asked once per `InlineArray<T,N>` instantiation. The same
// identification, by bare tail, serves the read-only twin `ConstView<T>` — the tail test is exact
// (`__ConstView` is not `__View`), so each answers for its own type.
const std::string& CEmitter::viewTemplateKeyFor(const std::string& tail)
{
    auto cached = _viewTmplKeys.find(tail);
    if (cached != _viewTmplKeys.end()) return cached->second;
    std::string& key = _viewTmplKeys[tail];   // "" until found — and "" for good if the stdlib has no such view
    const std::string suffix = "__" + tail;
    for (auto& kv : _genericTypeParams) {
        const std::string& k = kv.first;
        bool tailMatches = (k == tail)
            || (k.size() > suffix.size() && k.compare(k.size() - suffix.size(), suffix.size(), suffix) == 0);
        if (!tailMatches || kv.second.size() != 1) continue;
        auto gt = _genericTypes.find(k);
        if (gt != _genericTypes.end() && gt->second.isBorrow) { key = k; break; }
    }
    return key;
}
const std::string& CEmitter::viewTemplateKey()      { return viewTemplateKeyFor("View"); }
const std::string& CEmitter::constViewTemplateKey() { return viewTemplateKeyFor("ConstView"); }

bool CEmitter::allTypeParamsDefaulted(const std::string& tmpl) const
{
    auto p = _genericTypeParams.find(tmpl);
    if (p == _genericTypeParams.end() || p->second.empty()) return false;
    auto d = _genericTypeDefaults.find(tmpl);
    if (d == _genericTypeDefaults.end() || d->second.size() != p->second.size()) return false;
    for (auto& def : d->second) if (!def) return false;        // a null entry = a required param
    return true;
}

std::string CEmitter::genericTypeMangle(const std::string& tmpl, SharedIdentifierList args)
{
    // Default type params + named overrides: expand the use-site args into the full positional list so
    // `Wrap<bool>`, `Wrap<bool, int32>`, and `Wrap<bool, U: int32>` all mangle to the SAME instance name.
    // A DEFAULT names a type visible where the template was DECLARED, so mangle it under that home ctx —
    // matching registerGeneric*Inst, which resolves defaults under the home ctx too.
    const std::vector<std::string>* params = nullptr;
    const std::vector<SharedIdentifier>* defs = nullptr;
    const NsCtx* homeCtx = nullptr;
    auto tp = _genericTypeParams.find(tmpl);
    if (tp != _genericTypeParams.end()) {
        params = &tp->second;
        auto d = _genericTypeDefaults.find(tmpl);  if (d != _genericTypeDefaults.end()) defs = &d->second;
        auto c = _genericTypeCtx.find(tmpl);        if (c != _genericTypeCtx.end())      homeCtx = &c->second;
    } else {
        auto cp = _genericContractParams.find(tmpl);
        if (cp != _genericContractParams.end()) {
            params = &cp->second;
            auto d = _genericContractDefaults.find(tmpl);  if (d != _genericContractDefaults.end()) defs = &d->second;
            auto c = _genericContractCtx.find(tmpl);        if (c != _genericContractCtx.end())      homeCtx = &c->second;
        }
    }

    std::string m = tmpl;
    static const std::vector<SharedIdentifier> noDefs;
    if (params && !params->empty()) {
        std::vector<SharedIdentifier> full; std::vector<bool> isDefault;
        positionalizeGenericArgs(*params, defs ? *defs : noDefs, args, full, isDefault);
        for (size_t i = 0; i < full.size(); ++i) {
            if (!full[i]) continue;                              // unbound required param — invalid; registration reports
            if (isDefault[i] && homeCtx) {                       // mangle the default under its home ctx
                NsCtx saved = _nsCtx; _nsCtx = *homeCtx;
                m += "_" + mangleElem(full[i]);
                _nsCtx = saved;
            } else {
                m += "_" + mangleElem(full[i]);
            }
        }
        return m;
    }
    if (args) for (auto& a : *args) m += "_" + mangleElem(a);   // fallback: params unknown — raw args
    return m;
}

bool CEmitter::isCollectionType(SharedIdentifier t) const
{
    if (!t) return false;
    if (t->builtInVal == IDENTIFIER_STRING_VAL) return true;          // string
    // DynamicArray, FixedArray, and the smart pointers are library generic types (std::collections /
    // std::memory), not intrinsic collections; they route through registerGenericTypeInst. `InlineArray<T,N>`
    // (the const-generic value array) stays intrinsic.
    return t->genericArg && t->value &&
           (*t->value == "BindableFunctionPtr" || *t->value == "InlineArray" || *t->value == "Simd" || *t->value == "Mask");
}

// Discover a used Coll<T> instantiation: register a CollectionInfo (drives the
// macro emission) and a synthetic ClassInfo (so dispatch/RAII/decl reuse works).
void CEmitter::registerCollection(SharedIdentifier collType)
{
    if (!isCollectionType(collType)) return;

    // Smart pointers (Owned/Shared/Weak) are library generic types now; they never reach here — only
    // their polymorphic `<Contract>` instances become smart-ptr collections, registered directly via
    // registerSmartPtr from registerGenericTypeInst's interface-owner divert.
    bool isStr = collType->builtInVal == IDENTIFIER_STRING_VAL;
    // A string's element is a raw byte (`s[i]` -> uint8), so byte iteration/indexing routes through the
    // collection machinery; codepoints come from `.chars()` (a separate iterator).
    SharedIdentifier elem = isStr ? primTypeNode(IDENTIFIER_UINT8_VAL) : collType->genericArg;
    std::string elemCType  = isStr ? "uint8_t" : cType(elem);
    std::string elemMangle = isStr ? "" : mangleElem(elem);
    std::string elemClass  = (!isStr && isClass(elemCType)) ? elemCType : "";

    // BindableFunctionPtr<Sig> — element is a function SIGNATURE, not a class.
    if (!isStr && collType->value && *collType->value == "BindableFunctionPtr") {
        registerBindable(elem);
        return;
    }

    // InlineArray<T, N> — the const-generic value array (a distinct shape: two args, value semantics).
    if (!isStr && collType->value && *collType->value == "InlineArray") {
        registerFixed(collType);
        return;
    }

    // Simd<T, N> — the lane batch. A sibling shape (two args, value semantics) with a different C
    // lowering: a `vector_size` typedef rather than a struct. See registerSimd.
    //
    // `Mask<T>#(N)` routes here TOO, and deliberately: a mask only ever arises from a comparison on its
    // data vector, so registerSimd registers the pair together. Spelling `Mask<float32,4>` in a type
    // annotation without ever mentioning `Simd<float32,4>` is legal and lands in the same place.
    if (!isStr && collType->value && (*collType->value == "Simd" || *collType->value == "Mask")) {
        if (*collType->value == "Mask") {
            SharedIdentifier sTy = std::make_shared<IdentifierNode>(*collType);
            sTy->value = std::make_shared<std::string>("Simd");
            registerSimd(sTy);
        } else {
            registerSimd(collType);
        }
        return;
    }

    // a non-escaping borrow — a contract (fat pointer) or a `type view` (borrowed `UnsafePtr<T>`) — can't be
    // a BARE collection element (a `DynamicArray` of them would dangle). Own the referent instead:
    // a contract → store `Shared<I>` (`DynamicArray<Shared<I>>`); a view → copy into an owning collection.
    if (isNonEscapingBorrow(elemCType)) {
        std::string nm = (elem && elem->value) ? *elem->value : elemCType;
        if (isInterface(elemCType))
            unsupported(("a contract (`" + nm + "`) borrows its object, so it can't be a collection "
                         "element — it would dangle; store an owning `Shared<" + nm + ">` instead").c_str(),
                        collType->line);
        else
            unsupported(("a view (`" + nm + "`) borrows its buffer, so it can't be a collection "
                         "element — it would dangle; copy into an owning collection instead").c_str(),
                        collType->line);
        return;
    }

    // Everything else diverted above (`InlineArray` -> registerFixed, `BindableFunctionPtr` ->
    // registerBindable), so `string` is the only intrinsic collection this registers.
    std::string cName = "kama_string";

    if (_collections.count(cName)) return;    // dedup

    CollectionInfo info;
    info.kind = CollKind::String; info.cName = cName;
    info.elemCType = elemCType; info.elemMangle = elemMangle; info.elemClass = elemClass;
    info.elemDestructible = !elemClass.empty() && _classes.count(elemClass) && _classes[elemClass].destructible;
    _collections[cName] = info;
    _collectionOrder.push_back(cName);

    // Synthetic ClassInfo: a struct with a dtor, and (collections only) intrinsic methods.
    ClassInfo ci;
    ci.name = cName;
    ci.isIntrinsicColl = true;
    ci.collKind = CollKind::String;
    ci.collElemClass = elemClass;
    ci.destructible = true;                    // owns heap -> RAII frees
    ci.copyable = isStr;                        // `string` is deep-copyable (kama_string__copy) -> satisfies
                                               // `Copyable` as a type arg, so `List<string>` gets its
                                               // `when T: Copyable` methods (copy / by-value foreach).
    // `string`'s `Equatable` used to be recorded HERE, nominally, because an intrinsic had no way to say
    // `implements` — the one conformance in the language that the compiler asserted on a type's behalf.
    // It is now declared like every other, by `type intrinsic <string> implements Equatable { }` in the
    // prelude; the empty body is not a stub, it is the point — the completeness check reads the type's
    // method map, and `string`'s NATIVE `equals` (registered just below) is already in it.
    auto addMethod =[&](const std::string& mname, std::vector<ParamSig> params, SharedIdentifier ret) {
        MethodInfo mi;
        mi.cName = cName + "__" + mname;
        mi.params = std::move(params);
        mi.returnType = ret;
        mi.isIntrinsic = true;
        mi.isConst = true;                    // `string` is immutable: every one of its intrinsics reads.
                                              // The ones that "change" a string (`concat`/`trim`/`substring`
                                              // /case) return a NEW owned string and leave the receiver alone.
        mi.visibility = Visibility::Public;   // an intrinsic (a string op) IS that type's public API —
                                              // string's `equals` is real, so its nominal Equatable (recorded
                                              // in `interfaces`) resolves to it for a `<K: Equatable>` bound
        ci.methods[mname] = mi;
    };
    {   // `string`'s intrinsic method set — the only one left (everything else diverted above)
        // The argument kind rule was silent on every intrinsic, because these synthesized signatures
        // name no parameter type at all — `s.substring(start: "x", end: 3)` compiled. The type goes in
        // `kindCType`, NOT `className`: that field also drives `ownsByValue`, and the read-only
        // `kama_string__*` intrinsics BORROW their string argument, so naming it there would demand a
        // `give`/`copy` marker on `s.contains(substring: t)`. `include/kama_runtime.h` is the authority
        // for each spelling — an offset is a `size_t`, a needle or piece is a `kama_string`.
        // An offset into a string is an `isize` — kama's size type — so `SZ` is `ptrdiff_t`, not `size_t`.
        auto SZ = [](const char* n) { ParamSig p; p.name = n; p.byRef = false; p.kindCType = "ptrdiff_t"; return p; };
        auto ST = [](const char* n) { ParamSig p; p.name = n; p.byRef = false; p.kindCType = "kama_string"; return p; };
        if (!_synthCtx) _synthCtx = std::make_shared<CodeGenContext>(std::make_shared<std::string>("<generic>"));
        // `length` names its return type instead of passing NULL and letting the C type govern. A NULL
        // returnType makes `typeOfExpr` answer "" — "I have no idea" — and every numeric rule is silent on
        // an unknown source by design, so `int8 n = s.length();` COMPILED and silently truncated. Naming it
        // closes that (milestone 6's rule never reached an intrinsic) and is what lets a caller write
        // `isize n = s.length();` with no cast at all.
        addMethod("length", {}, synthId("isize", IDENTIFIER_ISIZE_VAL));
        addMethod("equals", { ST("other") }, SharedIdentifier());
        addMethod("concat", { ST("other") }, collType);   // returns a string
        // `cstr()` returns the READ-ONLY pointer — C's `const char*`, which is what the comment always
        // said and what `kama_string__cstr` now returns. It was registered with a NULL return type, so
        // the acquisition gate never saw it and the pointer that came back was a writable `char*`:
        // `p = s.cstr(); p[0] = 'x'` on a `const ref string` built, ran, and died with SIGBUS writing
        // into a literal (measured 2026-09-06). Naming the type closes both.
        {
            auto cstrRet = synthId("UnsafeConstPtr");
            auto ch = synthId("cchar", IDENTIFIER_CCHAR_VAL);   // C's `char`, not the codepoint (0.9.232)
            cstrRet->genericArg  = ch;
            cstrRet->genericArgs = std::make_shared<IdentifierList>();
            cstrRet->genericArgs->push_back(ch);
            addMethod("cstr", {}, cstrRet);
        }
        addMethod("get",    { SZ("index") }, elem);        // `s[i]` -> the i-th byte (uint8)
        addMethod("chars",  {}, synthId("Chars"));   // codepoint iterator
        // Phase 3 ergonomics. Bool-returning methods pass a NULL returnType (the `equals` pattern — the
        // emitter emits the raw C call and the C `bool` return governs). `substring`/`trim`/`replace`/case
        // return `collType` (a `string`), so their owned result is RAII-freed exactly like `.concat()`.
        addMethod("substring", { SZ("start"), SZ("end") }, collType);
        // `substring` traps on an offset that splits a character, so the safe path has to be reachable:
        // `floorCharBoundary` snaps an arbitrary offset DOWN to a boundary (total, O(1)) and `truncate`
        // names the budget case on top of it. It returns an OFFSET, so it names `isize` for the same
        // reason `length` does — a NULL returnType would leave it invisible to every numeric rule.
        addMethod("floorCharBoundary", { SZ("at") }, synthId("isize", IDENTIFIER_ISIZE_VAL));
        addMethod("truncate", { SZ("maxBytes") }, collType);   // owned result, like trim
        addMethod("contains",   { ST("substring") }, SharedIdentifier());
        addMethod("startsWith", { ST("prefix") },    SharedIdentifier());
        addMethod("endsWith",   { ST("suffix") },    SharedIdentifier());
        addMethod("isEmpty",    {}, SharedIdentifier());
        addMethod("trim",       {}, collType);
        addMethod("trimStart",  {}, collType);
        addMethod("trimEnd",    {}, collType);
        addMethod("replace",    { ST("old"), ST("with") }, collType);  // `with:` (`new` is reserved)
        addMethod("toLower",    {}, collType);
        addMethod("toUpper",    {}, collType);
        // `find` -> Optional<usize> (null-safe byte offset). Register the Optional<usize> instance so its C
        // struct + Some/None variants exist, and give `find` that return type; the emitter emits a wrapper
        // (emitStringFind) that builds the Optional. Mirrors Weak.tryUpgrade / registerOptionalOfShared.
        if (_genericTypeParams.count("Optional")) {
            auto usizeArg = synthId("usize", IDENTIFIER_USIZE_VAL);
            auto optArgs = std::make_shared<IdentifierList>();
            optArgs->push_back(usizeArg);
            registerGenericTypeInst("Optional", optArgs);
            auto optRet = synthId("Optional");
            optRet->genericArg  = usizeArg;
            optRet->genericArgs = std::make_shared<IdentifierList>();
            optRet->genericArgs->push_back(usizeArg);
            addMethod("find", { ST("substring") }, optRet);
        }
        // `split(separator:)` -> a lazy `Split` iterator (prelude value type; see the `.split()`
        // special-case in emitMethodCall). No collections import: pieces come out one at a time.
        addMethod("split", { ST("separator") },
                  synthId("Split"));
    }

    _classes[cName] = ci;
}

// Register a `Fixed<T, N>` instance — the const-generic safe array. Unlike the heap collections it
// is a VALUE type (`struct { T v[N]; }`): it owns no heap, copies by value, and has no destructor,
// so it is a `CollKind::Fixed` carved out of the ownership machinery. It reuses the collection path
// only for bounds-checked indexing + `foreach`. The element must be a `value` (own nothing) and N a
// positive compile-time integer (a literal, or a bound `const N: int` param).
void CEmitter::registerFixed(SharedIdentifier fixedType)
{
    SharedIdentifierList args = fixedType->genericArgs;
    if (!args || args->size() != 2) {
        unsupported("`InlineArray<T>#(N)` takes one type argument and one compile-time size, in separate "
                    "groups -- `InlineArray<float32>#(4)`", fixedType->line);
        return;
    }
    SharedIdentifier elem = (*args)[0];
    SharedIdentifier nArg = (*args)[1];
    int64_t n;
    // An unbound `N` (a `const N: int` param referenced inside a generic template, no binding yet)
    // isn't a concrete type — skip it silently; the concrete `Fixed<T, 4>` instance registers at the
    // use site (a caller's typed local / a bound instantiation). A concrete non-const size resolves here.
    if (!constArgN(nArg, n)) return;
    if (n <= 0) {
        unsupported("the size of an `InlineArray<T>#(N)` must be a positive integer", fixedType->line);
        return;
    }

    std::string elemCType  = cType(elem);
    std::string elemMangle = mangleElem(elem);
    std::string elemClass  = isClass(elemCType) ? elemCType : "";

    // The element must OWN NOTHING (a `value` or primitive): an `InlineArray` is a plain value with no
    // per-element dtor, so a `resource`/interface/destructible element would leak or dangle.
    if (isInterface(elemCType) || (!elemClass.empty() && isMoveOnlyValue(elemClass))) {
        std::string nm = (elem && elem->value) ? *elem->value : elemCType;
        unsupported(("an `InlineArray<T>#(N)` element must be a `value` (it owns nothing) — `" + nm +
                     "` is a `resource`/contract, which would leak; wrap it in an owning `FixedArray`/"
                     "`DynamicArray` instead").c_str(), fixedType->line);
        return;
    }

    std::string cName = "InlineArray_" + elemMangle + "_" + std::to_string(n);
    if (_collections.count(cName)) return;    // dedup

    CollectionInfo info;
    info.kind = CollKind::Fixed; info.cName = cName;
    info.elemCType = elemCType; info.elemMangle = elemMangle; info.elemClass = elemClass;
    info.constValue = n;
    _collections[cName] = info;
    _collectionOrder.push_back(cName);

    // Synthetic ClassInfo: a value struct (NOT destructible, no ctor) with intrinsic get/set/length.
    // Indexing (`v[i]`) and `foreach` go through collectionElemAccess/the foreach path directly;
    // `length` is the one method resolved by name (`v.length()`).
    ClassInfo ci;
    ci.name = cName;
    ci.isIntrinsicColl = true;
    ci.collKind = CollKind::Fixed;
    ci.collElemClass = elemClass;
    ci.destructible = false;                   // a value — owns no heap
    auto addMethod = [&](const std::string& mname, std::vector<ParamSig> params, SharedIdentifier ret,
                         bool isConst) {
        MethodInfo mi; mi.cName = cName + "__" + mname;
        mi.params = std::move(params); mi.returnType = ret; mi.isIntrinsic = true; mi.isConst = isConst;
        ci.methods[mname] = mi;
    };
    // Same split as the string intrinsics above: `className` keeps its ownership/upcast meaning
    // (`elemClass`, empty for a primitive element) and the kind rule reads `kindCType`, which is the
    // element's real C type. `KAMA_FIXED_FUNCS` in include/kama_runtime.h is the authority for both.
    // An index is an `isize` (`ptrdiff_t`), matching every other container — see the string block above.
    ParamSig ixGet; ixGet.name = "index"; ixGet.byRef = false; ixGet.kindCType = "ptrdiff_t";
    ParamSig ixSet = ixGet;
    ParamSig val;   val.name = "value"; val.byRef = false; val.className = elemClass; val.kindCType = elemCType;
    if (!_synthCtx) _synthCtx = std::make_shared<CodeGenContext>(std::make_shared<std::string>("<generic>"));
    addMethod("get",    { ixGet }, elem, true);
    addMethod("set",    { ixSet, val },
              SharedIdentifier(), false);   // the one intrinsic here that writes
    addMethod("length", {}, synthId("isize", IDENTIFIER_ISIZE_VAL), true);   // named, not NULL — see the string `length` above

    // `dataPtr()` -> `UnsafePtr<T>`, the same safe-to-obtain / unsafe-to-deref bridge FixedArray and
    // DynamicArray carry. It needs no rule of its own: the raw-pointer containment check reads the
    // `*`-suffixed return C TYPE at the acquisition-by-call site, so a caller outside an `unsafe fn` is
    // rejected exactly as it is for `FixedArray.dataPtr()`.
    //
    // Two halves, as on FixedArray/DynamicArray: `dataPtr()` is `const fn` and returns the read-only
    // `UnsafeConstPtr<T>` (what a const receiver may hand to a `const T*` C API); `dataPtrMut()` needs a
    // mutable receiver and returns the writable pointer.
    auto ptrRet = synthId("UnsafeConstPtr");
    ptrRet->genericArg  = elem;
    ptrRet->genericArgs = std::make_shared<IdentifierList>();
    ptrRet->genericArgs->push_back(elem);
    addMethod("dataPtr", {}, ptrRet, true);
    auto ptrMutRet = synthId("UnsafePtr");
    ptrMutRet->genericArg  = elem;
    ptrMutRet->genericArgs = std::make_shared<IdentifierList>();
    ptrMutRet->genericArgs->push_back(elem);
    addMethod("dataPtrMut", {}, ptrMutRet, false);

    // `view()` -> `View<T>`, mirroring `string.find` -> `Optional<usize>` above: force-register the
    // generic instance so its C struct exists, give the method that return type, and emit the tiny
    // wrapper (emitFixedView) — a runtime macro cannot name the program-specific `View_<T>`.
    //
    // Without this, InlineArray was the ONE container locked out of `borrow`, `parallel_for` and every
    // View-taking algorithm in the stdlib (`sortUnstable` and friends) — while being the only container
    // a `@noheap` region is allowed to use. `Viewable<View<T>>` goes on `interfaces` below because
    // `borrow`/`parallel_for` read that grant to prove the host is the thing being viewed, and here it
    // states a fact: an InlineArray is `struct { T v[N]; }`, so it genuinely owns the bytes handed out.
    // `view()` is NOT registered here — see registerFixedViews, which runs once every unit is collected.
    // Doing it from this function made the method's existence depend on whether `std::collections::View`
    // happened to be collected before the first `InlineArray<T,N>` in the program, which is an ordering
    // race: `FixedArray` pulls View in transitively through its own module, a prelude builtin pulls in
    // nothing, so `a.view()` resolved or not according to the user's unrelated imports.
    _classes[cName] = ci;
    // For registerFixedViews, below — resolved HERE, under the declaring file's context. That pass runs once
    // every unit is collected, under whatever context the LAST unit left (a stdlib module), where a user
    // file's private `Point` resolves to nothing: the view it minted was over a bare, unregistered `Point`,
    // so `a.viewMut()` did not return a view at all, and an element that is itself a generic instance
    // (`Frame<int32>`) walked `View.swap` with a `T` no inference could bind. KR-11.
    _collections[cName].elem = absolutizeType(elem);
}

// Register a `Simd<T>#(N)` instance — the LANE BATCH. Structurally a sibling of registerFixed above and
// deliberately not a variant of it, because the two differ in the one place that matters: an InlineArray
// is a `struct { T v[N]; }` and a Simd is a `vector_size` typedef over a primitive. That makes a Simd
// have NO by-value struct dependency and NO forward declaration, so its `_TYPE` goes out in the early
// types pass where a Fixed's cannot (see emitCollectionDefs / emitHeaderContent).
//
// The element restriction is much tighter than a Fixed's, and both halves are load-bearing:
//   * the element must be a NUMERIC PRIMITIVE — `vector_size` is a C-level construct over scalars, and a
//     struct element is not merely unsupported but silently misapplied by some compilers.
//   * `sizeof(T) * N` must be exactly 16. 128 bits is the only width EVERY kama target has (SSE2 on the
//     x86-64 baseline, NEON on aarch64, wasm128 since -msimd128), and a wider one needs `-march`, which
//     is the CPU-tuning knob in ROADMAP_DETAIL §9. This is a `unsupported(...)` here rather than a
//     `comptime assert` in the prelude declaration, which is what the design first specified: an
//     intrinsic's prelude declaration has an EMPTY body, so an assert written there would never run.
void CEmitter::registerSimd(SharedIdentifier simdType)
{
    SharedIdentifierList args = simdType->genericArgs;
    if (!args || args->size() != 2) {
        unsupported("`Simd<T>#(N)` takes one numeric element type and one compile-time lane count, in "
                    "separate groups -- `Simd<float32>#(4)`", simdType->line);
        return;
    }
    SharedIdentifier elem = (*args)[0];
    SharedIdentifier nArg = (*args)[1];
    int64_t n;
    // An unbound `N` inside a generic template is not a concrete instance — skip it silently, exactly as
    // registerFixed does; the concrete instantiation registers at the use site that chose the arguments.
    if (!constArgN(nArg, n)) return;
    if (n <= 0) {
        unsupported("the lane count of a `Simd<T>#(N)` must be a positive integer", simdType->line);
        return;
    }

    std::string elemCType  = cType(elem);
    std::string elemMangle = mangleElem(elem);

    // A numeric primitive, and nothing else. `isClass` catches a user type/contract; the width table
    // catches everything else that reached here without one (`bool`, `char`, `string`, a view).
    const int bits = cNumBits(elemCType);
    if (isClass(elemCType) || !bits || elemCType == "bool") {
        std::string nm = (elem && elem->value) ? *elem->value : elemCType;
        unsupported(("a `Simd<T>#(N)` lane must be a numeric primitive — `" + nm + "` is not; a lane batch "
                     "is a machine vector, so its element is a machine number").c_str(), simdType->line);
        return;
    }
    if ((int64_t)(bits / 8) * n != 16) {
        unsupported(("a `Simd<T>#(N)` must be exactly 128 bits — `" + elemMangle + "` x " + std::to_string(n)
                     + " is " + std::to_string((bits / 8) * n) + " bytes. 128 is the only width every kama "
                     "target has; wider needs a CPU-tuning flag that does not exist yet").c_str(),
                    simdType->line);
        return;
    }

    std::string cName = "Simd_" + elemMangle + "_" + std::to_string(n);
    if (_collections.count(cName)) return;    // dedup

    CollectionInfo info;
    info.kind = CollKind::Simd; info.cName = cName;
    info.elemCType = elemCType; info.elemMangle = elemMangle; info.elemClass = "";
    info.constValue = n;
    _collections[cName] = info;
    _collectionOrder.push_back(cName);

    // Synthetic ClassInfo. A value, never destructible, with NO `get`/`set`/`length`: those are the
    // container surface, and a lane batch is one value rather than a row of them. `lane` is the single
    // read, and it is a method rather than `v[i]` on purpose — indexing would invite the scalar loop the
    // type exists to replace.
    ClassInfo ci;
    ci.name = cName;
    ci.isIntrinsicColl = true;
    ci.collKind = CollKind::Simd;
    ci.collElemClass = "";
    ci.destructible = false;
    auto addMethod = [&](const std::string& mname, std::vector<ParamSig> params, SharedIdentifier ret,
                         bool isConst) {
        MethodInfo mi; mi.cName = cName + "__" + mname;
        mi.params = std::move(params); mi.returnType = ret; mi.isIntrinsic = true; mi.isConst = isConst;
        ci.methods[mname] = mi;
    };
    if (!_synthCtx) _synthCtx = std::make_shared<CodeGenContext>(std::make_shared<std::string>("<generic>"));
    ParamSig ix; ix.name = "index"; ix.byRef = false; ix.kindCType = "ptrdiff_t";
    addMethod("lane", { ix }, elem, true);
    // `toArray` is the way back out to addressable memory, and it is what makes the type usable at all:
    // lanes go in through a literal and come out through an `InlineArray<T>#(N)`, which every other part
    // of the language already knows how to index, iterate and store. Registering the array instance HERE
    // is what guarantees its `KAMA_FIXED_TYPE` exists — a Simd's `_FUNCS` names it, and the FUNCS pass
    // runs after the struct bodies, so the ordering holds.
    SharedIdentifierList arrArgs = std::make_shared<IdentifierList>();
    arrArgs->push_back(elem);
    arrArgs->push_back(nArg);
    SharedIdentifier arrTy = synthId("InlineArray");
    arrTy->genericArg = elem; arrTy->genericArgs = arrArgs; arrTy->line = simdType->line;
    registerFixed(arrTy);
    addMethod("toArray", {}, arrTy, true);
    // The elementwise ops that need no libm, so this header stays freestanding — see KAMA_SIMD_FUNCS.
    // `className` as well as `kindCType`: the argument path threads a target type from `className`, and
    // that is what lets an array literal be written directly as an operand — `a.greaterThan(rhs: [2; 4])`
    // rather than forcing a named local first. Without it the literal has no context and is refused.
    ParamSig rhs; rhs.name = "rhs"; rhs.byRef = false; rhs.kindCType = cName; rhs.className = cName;
    addMethod("abs", {}, simdType, true);
    addMethod("min", { rhs }, simdType, true);
    addMethod("max", { rhs }, simdType, true);
    // The libm trio, on FLOAT lanes only — the first methods here whose existence depends on `T`, so an
    // integer batch gets "no method `sqrt`" rather than a per-lane `sqrtf(int)`. Their bodies come from
    // `kama_math.h` (KAMA_SIMD_MATH, emitted beside the `_FUNCS` instance), not from the freestanding
    // runtime header, because they need libm; see emitCollectionDefs for the include and the `-lm` hint.
    if (cNumFloat(elemCType)) {
        addMethod("sqrt",  {}, simdType, true);
        addMethod("floor", {}, simdType, true);
        addMethod("ceil",  {}, simdType, true);
    }
    // The lane permutations — the operations that have NO scalar spelling, and the reason this type
    // exists at all. Registered here so dispatch resolves them; the CALL is intercepted in emitDispatch
    // and folded to `__builtin_shufflevector`, because the lane indices must be literals.
    ParamSig pat; pat.name = "pattern"; pat.byRef = false;
    pat.kindCType = "InlineArray_int32_" + std::to_string(n);
    addMethod("shuffle", { pat }, simdType, true);
    addMethod("blend",   { rhs, pat }, simdType, true);
    // ⚠️ The pattern's `InlineArray<int32, N>` is deliberately NOT registered. The literal is folded to
    // lane indices at the call and never reaches runtime, so registering it would emit an
    // `InlineArray_int32_N` struct plus its five bounds-checked accessors into every program that uses a
    // `Simd` and reference none of them. The ParamSig above names the type for arity/kind matching, which
    // is all the dispatch path needs before emitSimdShuffle takes over.

    // The MASK partner. Registered here rather than on first use of `Mask<T,N>` because the comparisons
    // that produce one live on this type, so the pair is always needed together — and because a mask's C
    // lane width is derived from T, which is known here and nowhere cheaper.
    const std::string mName = "Mask_" + elemMangle + "_" + std::to_string(n);
    SharedIdentifier mTy = synthId("Mask");
    {
        SharedIdentifierList mArgs = std::make_shared<IdentifierList>();
        mArgs->push_back(elem); mArgs->push_back(nArg);
        mTy->genericArg = elem; mTy->genericArgs = mArgs; mTy->line = simdType->line;
    }
    if (!_collections.count(mName)) {
        // A mask's lane is the SIGNED INTEGER of the element's own width — which is exactly what a vector
        // comparison on that element produces (measured; see KAMA_MASK_TYPE). This is the whole reason a
        // mask carries `T` rather than just `N`.
        const char* mElemC = bits == 8 ? "int8_t" : bits == 16 ? "int16_t"
                           : bits == 32 ? "int32_t" : "int64_t";
        CollectionInfo mi2;
        mi2.kind = CollKind::Mask; mi2.cName = mName;
        mi2.elemCType = mElemC; mi2.elemMangle = elemMangle; mi2.elemClass = "";
        mi2.constValue = n; mi2.ifacePartner = cName;   // the data vector `select` hands back
        _collections[mName] = mi2;
        _collectionOrder.push_back(mName);

        ClassInfo mc;
        mc.name = mName; mc.isIntrinsicColl = true; mc.collKind = CollKind::Mask;
        mc.collElemClass = ""; mc.destructible = false;
        auto addM = [&](const std::string& nm, std::vector<ParamSig> ps, SharedIdentifier ret) {
            MethodInfo m; m.cName = mName + "__" + nm;
            m.params = std::move(ps); m.returnType = ret; m.isIntrinsic = true; m.isConst = true;
            mc.methods[nm] = m;
        };
        ParamSig t; t.name = "ifTrue";  t.byRef = false; t.kindCType = cName; t.className = cName;
        ParamSig f; f.name = "ifFalse"; f.byRef = false; f.kindCType = cName; f.className = cName;
        ParamSig o; o.name = "rhs";     o.byRef = false; o.kindCType = mName; o.className = mName;
        addM("select",  { t, f }, simdType);
        addM("and",     { o }, mTy);
        addM("or",      { o }, mTy);
        addM("not",     {},    mTy);
        addM("anyTrue", {},    synthId("bool"));
        addM("allTrue", {},    synthId("bool"));
        _classes[mName] = mc;
    }

    // The comparisons produce a mask, so they belong to the DATA vector but name the mask type. These
    // are the second operation with no scalar spelling: a lane mask as a first-class value.
    addMethod("greaterThan", { rhs }, mTy, true);
    addMethod("lessThan",    { rhs }, mTy, true);
    addMethod("atLeast",     { rhs }, mTy, true);
    addMethod("atMost",      { rhs }, mTy, true);
    addMethod("equals",      { rhs }, mTy, true);
    addMethod("notEquals",   { rhs }, mTy, true);
    // Horizontal reductions — the deliberate collapse to a scalar.
    addMethod("reduceAdd", {}, elem, true);
    addMethod("reduceMul", {}, elem, true);
    addMethod("reduceMin", {}, elem, true);
    addMethod("reduceMax", {}, elem, true);
    _classes[cName] = ci;
}

// `v.shuffle(pattern: [3,2,1,0])` and `a.blend(rhs: b, pattern: [0,5,2,7])` -> `__builtin_shufflevector`.
//
// The pattern must be a COMPILE-TIME CONSTANT, and that is a hardware fact rather than an implementation
// shortcut: the lane selection is encoded in the instruction, so a constant `wzyx` becomes two register
// ops while a runtime pattern spills to the stack and rebuilds the vector one scalar load at a time. Both
// gcc and clang accept `__builtin_shufflevector` (measured — only the TYPE spelling needed a per-compiler
// seam, and `vector_size` removed even that), so there is one emission here and no `#if`.
//
// Why a value argument rather than `shuffle::<3,2,1,0>()`, which is what the design first specified: a
// method turbofish does not exist in kama (kama.cemit.cpp — "a method takes no type arguments"), a method
// cannot take type or comptime parameters at all, and the index COUNT varies with N, which a fixed
// parameter list cannot express and kama has no variadic generics for. Zig's `@shuffle` and C#'s
// `Vector128.Shuffle` both take the mask as a value for the same reason.
std::string CEmitter::emitSimdShuffle(const std::string& cls, const std::string& method,
                                      const std::string& recvPtr, SharedArgumentList args, int srcLine)
{
    const CollectionInfo& info = _collections[cls];
    const int64_t n = info.constValue;
    const bool isBlend = (method == "blend");

    SharedExpression patternExpr, rhsExpr;
    if (args) for (auto& a : *args) {
        auto* an = dynamic_cast<ArgumentNode*>(a.get());
        if (!an || !an->name || !an->name->value) continue;
        if (*an->name->value == "pattern") patternExpr = an->expression;
        else if (*an->name->value == "rhs")     rhsExpr = an->expression;
    }
    if (!patternExpr || (isBlend && !rhsExpr)) {
        unsupported((isBlend ? "`blend` takes `rhs:` and `pattern:`" : "`shuffle` takes `pattern:`"),
                    srcLine);
        return "0";
    }

    // The pattern is an `InlineArray<int32, N>`, and its elements have to be readable HERE. A literal is
    // the spelling that always works; a `comptime` constant would need the interpreter's baked value,
    // which is a separate seam. Anything else is refused by name rather than mis-lowered.
    auto* lit = dynamic_cast<ArrayLiteralNode*>(patternExpr.get());
    if (!lit || !lit->elements) {
        unsupported(("the `pattern:` of `" + method + "` must be a literal list of lane indices — "
                     "`[3, 2, 1, 0]`. The lane selection is encoded in the machine instruction, so it "
                     "cannot come from a runtime value").c_str(), srcLine);
        return "0";
    }
    if ((int64_t)lit->elements->size() != n) {
        unsupported(("this pattern has " + std::to_string(lit->elements->size()) + " lane index(es) but `"
                     + cls + "` has " + std::to_string(n)).c_str(), srcLine);
        return "0";
    }
    // `blend` draws from TWO vectors, so its index space is 0..2N-1: the low half selects a lane of the
    // receiver, the high half a lane of `rhs`. `shuffle` passes the receiver twice, so 0..N-1 is all it
    // may name — an index in the upper half would silently read the same vector again.
    const int64_t hi = isBlend ? (2 * n) : n;
    std::string idx;
    for (auto& e : *lit->elements) {
        int64_t v;
        if (!constValue(e, v)) {
            unsupported(("every lane index in a `" + method + "` pattern must be an integer constant")
                        .c_str(), srcLine);
            return "0";
        }
        if (v < 0 || v >= hi) {
            unsupported(("lane index " + std::to_string(v) + " is out of range for `" + method
                         + "` on `" + cls + "` — valid indices are 0.." + std::to_string(hi - 1)
                         + (isBlend ? " (0.." + std::to_string(n - 1) + " select this vector, "
                                      + std::to_string(n) + ".." + std::to_string(2 * n - 1)
                                      + " select `rhs`)" : "")).c_str(), srcLine);
            return "0";
        }
        idx += ", " + std::to_string(v);
    }
    const std::string self  = "(*(" + cls + "*)" + recvPtr + ")";
    const std::string other = isBlend ? emitOperandByValue(rhsExpr) : self;
    return "__builtin_shufflevector(" + self + ", " + other + idx + ")";
}

// Register a smart pointer (Owned/Shared/Weak) as a synthetic ClassInfo backed by
// a runtime macro. Smart pointers expose a T* `ptr` (auto-deref) and have no real
// ctor (construction is inline). Shared/Weak carry a few intrinsic methods.
void CEmitter::registerSmartPtr(CollKind kind, SharedIdentifier elem, const std::string& customName)
{
    std::string elemCType  = cType(elem);
    std::string elemMangle = mangleElem(elem);
    bool elemIface = isInterface(elemCType);                          // fat-element variant
    std::string elemClass  = (isClass(elemCType) || elemIface) ? elemCType : "";
    if (elemClass.empty()) return;              // caller diagnosed
    // a library `Box<Contract>` is routed here under its own mangled name (Rust's `Box<dyn Trait>`);
    // otherwise the built-in Owned/Shared/Weak prefix.
    std::string cName = !customName.empty() ? customName
                      : (kind == CollKind::Owned  ? "Owned_"
                       : kind == CollKind::Shared ? "Shared_" : "Weak_") + elemMangle;
    if (_collections.count(cName)) return;      // dedup

    CollectionInfo info;
    info.kind = kind; info.cName = cName;
    info.elemCType = elemCType; info.elemMangle = elemMangle; info.elemClass = elemClass;
    info.elemIsInterface = elemIface;
    // An interface element's concrete object is dropped via its vtable's __dtor slot, not the
    // collection's ELEM_DTOR machinery, so elemDestructible stays false here.
    info.elemDestructible = !elemIface && _classes.count(elemClass) && _classes[elemClass].destructible;
    // The paired instance across Shared<->Weak (conventional prefix by default; a library `Rc`/`RcWeak`
    // pair overrides this after registration). A Weak upgrades to `Shared_<elem>`; a Shared downgrades to
    // `Weak_<elem>`.
    if (kind == CollKind::Weak)        info.ifacePartner = "Shared_" + elemMangle;
    else if (kind == CollKind::Shared) info.ifacePartner = "Weak_" + elemMangle;
    _collections[cName] = info;
    _collectionOrder.push_back(cName);

    ClassInfo ci;
    ci.name = cName; ci.isIntrinsicColl = true; ci.collKind = kind;
    ci.collElemClass = elemClass; ci.destructible = true;
    auto addM = [&](const std::string& m, std::vector<ParamSig> p) {
        MethodInfo mi; mi.cName = cName + "__" + m; mi.params = std::move(p);
        // `valid`/`expired`/`tryUpgrade`/`downgrade` all read the handle and hand back a fresh one; none
        // reseats the receiver, so all are callable on a const smart pointer.
        mi.isIntrinsic = true; mi.isConst = true; ci.methods[m] = mi;
    };
    // Intrinsics (not auto-deref forwarded): Owned has none; Shared has valid();
    // Weak has tryUpgrade() (-> Optional<Shared<T>>) and expired().
    if (kind == CollKind::Shared) addM("valid", {});
    if (kind == CollKind::Weak) {
        addM("tryUpgrade", {}); addM("expired", {});
        // record that tryUpgrade returns Optional<Shared<elem>> so exprClass can class a
        // `w.tryUpgrade()` call result — enabling `match(w.tryUpgrade())` without a local binding.
        if (_genericTypeParams.count("Optional")) {
            if (!_synthCtx) _synthCtx = std::make_shared<CodeGenContext>(std::make_shared<std::string>("<synth>"));
            auto mk = [&](const char* nm, SharedIdentifier arg) {
                auto n = synthId(nm);
                n->genericArg = arg; n->genericArgs = std::make_shared<IdentifierList>(); n->genericArgs->push_back(arg);
                return n;
            };
            ci.methods["tryUpgrade"].returnType = mk("Optional", mk("Shared", elem));
        }
    }
    _classes[cName] = ci;
}

// register `Optional<Shared<elem>>` for a `Weak<elem>` — the type `tryUpgrade()` returns.
// Synthesizes the `Shared<elem>` argument node and drives the normal generic-type monomorphization.
void CEmitter::registerOptionalOfShared(SharedIdentifier elem)
{
    if (!elem || !_genericTypeParams.count("Optional")) return;   // no prelude Optional -> skip
    if (!_synthCtx) _synthCtx = std::make_shared<CodeGenContext>(std::make_shared<std::string>("<synth>"));
    auto sh = synthId("Shared");
    sh->genericArg  = elem;
    sh->genericArgs = std::make_shared<IdentifierList>();
    sh->genericArgs->push_back(elem);
    auto optArgs = std::make_shared<IdentifierList>();
    optArgs->push_back(sh);
    registerGenericTypeInst("Optional", optArgs);
}

// register `Optional<sharedName>` where `sharedName` is an already-registered smart-ptr INSTANCE (a
// library `Rc_<elem>`) — a bare type node naming it drives the monomorphization. For `RcWeak.tryUpgrade`.
void CEmitter::registerOptionalOfName(const std::string& sharedName)
{
    if (sharedName.empty() || !_genericTypeParams.count("Optional")) return;
    if (!_synthCtx) _synthCtx = std::make_shared<CodeGenContext>(std::make_shared<std::string>("<synth>"));
    auto sh = synthId(sharedName);
    auto optArgs = std::make_shared<IdentifierList>();
    optArgs->push_back(sh);
    registerGenericTypeInst("Optional", optArgs);
}

// Register a BindableFunctionPtr<Sig> — a callable that may own a bound
// receiver. Element is a signature type (from `fnptr`), not a class. Backed by the
// fully type-erased KAMA_BINDABLE_DEFINE struct; the sig drives only the invoke.
void CEmitter::registerBindable(SharedIdentifier elem)
{
    std::string sigCName = cType(elem);
    if (!isSigType(sigCName)) {
        unsupported("BindableFunctionPtr<Sig> requires a function-signature type (declared with `fnptr`)",
                    elem ? elem->line : 0);
        return;
    }
    std::string cName = "BindableFunctionPtr_" + mangleElem(elem);
    if (_collections.count(cName)) return;            // dedup

    CollectionInfo info;
    info.kind = CollKind::Bindable; info.cName = cName;
    info.elemCType = sigCName; info.elemMangle = mangleElem(elem); info.elemClass = "";
    info.elemDestructible = false;
    _collections[cName] = info;
    _collectionOrder.push_back(cName);

    ClassInfo ci;
    ci.name = cName; ci.isIntrinsicColl = true; ci.collKind = CollKind::Bindable;
    ci.collElemClass = sigCName;       // reused at invoke: the bound signature's cName
    ci.destructible = true;            // owns heap (when bound) -> RAII drop
    _classes[cName] = ci;
}

bool CEmitter::isBindableClass(const std::string& cls) const
{
    auto it = _classes.find(cls);
    return it != _classes.end() && it->second.isIntrinsicColl && it->second.collKind == CollKind::Bindable;
}

void CEmitter::scanTypeForCollections(SharedIdentifier t)
{
    if (!t) return;
    // Inner-first: register the element's collections / generic instances BEFORE the enclosing
    // type, so the outer's elemClass/elemDestructible resolve against an already-registered inner
    // (`List<Shared<IShape>>` must see `Shared_IShape` in _classes to drop each element; likewise
    // `List<List<T>>`, `List<Box<T>>`). Recurse ALL type args so a collection/generic in
    // a 2nd+ position (`Pair<int, List<int>>`) is discovered — not just the first arg.
    if (t->genericArgs) for (auto& a : *t->genericArgs) scanTypeForCollections(a);
    else if (t->genericArg) scanTypeForCollections(t->genericArg);
    scanTypeForGenericTypes(t);                                 // also discover Pair<A,B> here
    scanTypeForGenericContracts(t);                             // and Iterator<int32> (value-position use)
    if (isCollectionType(t)) registerCollection(t);
}

// register the specialized instance for a user generic-type reference `Pair<A, B>`. The
// recursion into the args is driven by scanTypeForCollections (which calls this at each type node).
void CEmitter::scanTypeForGenericTypes(SharedIdentifier t)
{
    if (!t || !t->value) return;
    std::string tmpl = resolveUserName(*t->value, t->qualifier);
    if (!_genericTypes.count(tmpl)) return;
    // Explicit args (`Pair<A,B>`), OR a BARE all-defaulted generic (`BitSet` == `BitSet<GlobalAllocator>`) —
    // the latter drives the instance from its defaults (registerGenericTypeInst fills them from empty args).
    if (t->genericArg) registerGenericTypeInst(tmpl, t->genericArgs);
    else if (allTypeParamsDefaulted(tmpl)) registerGenericTypeInst(tmpl, nullptr);
}

// Deep-substitute a type node under the active _typeSubst (see the header). A bare param -> its
// (already-concrete) binding; a nested generic clones with each arg substituted; anything else is
// returned unchanged. Bindings are kept fully concrete, so recursion terminates.
SharedIdentifier CEmitter::deepSubstType(SharedIdentifier t)
{
    if (!t) return t;
    if (!_typeSubst.empty() && t->value && !t->genericArg) {   // a bare type-param
        auto s = _typeSubst.find(*t->value);
        if (s != _typeSubst.end()) return s->second;           // its binding is already deep
    }
    if (t->genericArgs && !t->genericArgs->empty()) {          // a generic type — substitute its args
        auto clone = synthClone(*t);     // shallow copy (context + scalar fields)
        clone->genericArgs = std::make_shared<IdentifierList>();
        for (auto& a : *t->genericArgs) clone->genericArgs->push_back(deepSubstType(a));
        clone->genericArg = clone->genericArgs->empty() ? SharedIdentifier() : (*clone->genericArgs)[0];
        return clone;
    }
    return t;
}

// Rebind a type node to its use-site-resolved absolute name so it mangles identically in any ctx.
// Called on a generic instance's concrete args (under the use-site _nsCtx) so that when the template's
// own ctx later drives interface/member scanning, a cross-module arg (`Counter` from another file)
// keeps its home mangle instead of being resolved to a bare name against the template's scope.
SharedIdentifier CEmitter::absolutizeType(SharedIdentifier t)
{
    if (!t || !t->value) return t;
    auto clone = synthClone(*t);
    // A user class/enum/contract NAME is rebound to its use-site mangle (qualifier dropped); primitives
    // (`isize`/`usize` among them since 0.9.136), `UnsafePtr` and `This` keep their spelling — they resolve
    // context-free. Generic args recurse either way (`UnsafePtr<Counter>`, `List<Counter>`, `Owned<Counter>`).
    bool contextFree = (t->builtInVal != 0) || isRawPtrName(*t->value) || *t->value == "This";
    if (!contextFree) {
        clone->value = std::make_shared<std::string>(resolveUserName(*t->value, t->qualifier));
        clone->qualifier = SharedStringList();                   // now an absolute name — no qualifier
    }
    if (t->genericArgs) {
        clone->genericArgs = std::make_shared<IdentifierList>();
        for (auto& a : *t->genericArgs) clone->genericArgs->push_back(absolutizeType(a));
        clone->genericArg = clone->genericArgs->empty() ? SharedIdentifier() : (*clone->genericArgs)[0];
    } else if (t->genericArg) {
        clone->genericArg = absolutizeType(t->genericArg);
    }
    return clone;
}

// True iff `a` (already run through deepSubstType/absolutizeType) still names an UNBOUND type-parameter:
// a bare identifier that resolves to no known type and isn't a primitive / reserved name. Recurses into a
// generic's args so `Result<List<V>, …>` is caught via its inner `List<V>`.
bool CEmitter::argCarriesUnboundParam(const SharedIdentifier& a)
{
    if (!a || !a->value) return false;
    if (a->genericArgs && !a->genericArgs->empty()) {          // a generic type — check its args
        for (auto& sub : *a->genericArgs) if (argCarriesUnboundParam(sub)) return true;
        return false;
    }
    if (a->builtInVal != 0) return false;                       // a primitive
    const std::string& v = *a->value;
    if (v == "This" || isRawPtrName(v)) return false;
    std::string r = resolveUserName(v, a->qualifier);
    return !_classes.count(r) && !_enums.count(r) && !_genericTypes.count(r)
        && !_interfaces.count(r) && !_genericContracts.count(r);
}

// Build one synthetic specialized ClassInfo per `Box<Arg>` (mirrors registerCollection): copy the
// template shape, rewrite identity (struct name + method cNames), re-derive param signatures under
// _typeSubst, register in _classes, and transitively scan its substituted member types so a
// `Box<T>` holding `List<T>` registers `List_int32`. Deduped by the mangled name.
void CEmitter::registerGenericTypeInst(const std::string& tmpl, SharedIdentifierList args)
{
    // Empty args is valid ONLY for a bare all-defaulted generic (`BitSet` == `BitSet<GlobalAllocator>`);
    // otherwise there is nothing to instantiate. Below, `args` may be null/empty (defaults fill every slot).
    if ((!args || args->empty()) && !allTypeParamsDefaulted(tmpl)) return;
    // Every rejection here is about the USE SITE — the line below is the first type argument's — and
    // `_nsCtx` at registration IS the use-site context (that is exactly what `_genericTypeInstCtx` records
    // further down). Instantiation is discovered from passes that leave `_collectingUnitPath` empty, so
    // without this a bad type argument named no file at all. Keeps the current value when there is nothing
    // better to say. See diagFile().
    ScopedStr _cu(_collectingUnitPath, _nsCtx.unitPath.empty() ? _collectingUnitPath : _nsCtx.unitPath);
    const std::vector<std::string>& params = _genericTypeParams[tmpl];

    // Resolve each arg to its concrete binding — DEEPLY (a nested `Rc<T>` -> `Rc<Counter>`), so a
    // generic arg carrying a type-param is never stored raw in _typeSubst (which would self-reference
    // and loop mangleElem for a mutually-recursive generic type).
    // Bind the use-site args to the template's params: leading POSITIONAL, then NAMED overrides
    // (`A: Arena` skips an earlier default), then fill trailing unbound params from their `= Default`.
    int line = (args && !args->empty() && args->front()) ? args->front()->line : 0;
    auto dit = _genericTypeDefaults.find(tmpl);
    const std::vector<SharedIdentifier> emptyDefs;
    const std::vector<SharedIdentifier>& defs = dit != _genericTypeDefaults.end() ? dit->second : emptyDefs;
    std::vector<SharedIdentifier> bound; std::vector<bool> isDefault;
    positionalizeGenericArgs(params, defs, args, bound, isDefault);
    if (!validateGenericArgs(tmpl, "type", params, args, bound, line)) return;

    // Resolve each binding to its concrete type — use-site args under the current ctx, DEFAULTS under the
    // template's home ctx (a default names a type visible where the template was declared, not at the use site).
    std::vector<SharedIdentifier> concrete;
    for (size_t i = 0; i < bound.size(); ++i) {
        if (isDefault[i]) {
            NsCtx savedDefCtx = _nsCtx;
            auto hit = _genericTypeCtx.find(tmpl);
            if (hit != _genericTypeCtx.end()) _nsCtx = hit->second;
            concrete.push_back(absolutizeType(deepSubstType(bound[i])));
            _nsCtx = savedDefCtx;
        } else {
            concrete.push_back(absolutizeType(deepSubstType(bound[i])));
        }
    }

    // Defer if a substituted arg still carries an unbound type-param — this only happens when scanning a
    // generic FUNCTION's signature before instantiation (its `V` isn't in _typeSubst yet, so deepSubstType
    // left it raw). The real instance registers at monomorphization (with concrete args). Registering now
    // would emit a struct with a raw `V` field (invalid C), or self-loop mangleElem/cType if the param name
    // clashes with the template's. (Inside a generic-TYPE instantiation the args are already substituted to
    // concrete, so nothing is skipped there — `ListIter<int32>` etc. are unaffected. Mirrors `Fixed<T,N>`'s
    // unbound-`N` skip.)
    for (auto& c : concrete) if (argCarriesUnboundParam(c)) return;
    // An OPAQUE type argument stands for "any `T` an instantiation might bind", so the two use-site
    // rejections below cannot be decided here: an opaque is neither provably a lock-free machine word
    // nor provably a view, and rejecting it would fail every probe of a template that names `Atomic<T>`
    // or buffers a `T`. The real instantiation runs both checks with the real argument, which is where
    // the answer exists and where the user wants the diagnostic pointed.
    bool opaqueArg = false;
    if (_probingTemplate)
        for (auto& c : concrete) {
            auto oi = c ? _classes.find(cType(c)) : _classes.end();
            if (oi != _classes.end() && oi->second.isOpaqueParam) { opaqueArg = true; break; }
        }
    // `Atomic<T>` (M6): the element must be a lock-free machine word — an integer primitive, `usize`/`isize`,
    // or `UnsafePtr`. A struct/`resource`/contract element can't be one atomic cell (atomicity is a hardware
    // property of a word), so reject it here at the user's use-site with a clear message.
    if (!opaqueArg && !_atomicTmpl.empty() && tmpl == _atomicTmpl && !concrete.empty() && concrete[0]) {
        SharedIdentifier el = concrete[0];
        bool isInt  = el->builtInVal >= IDENTIFIER_INT8_VAL && el->builtInVal <= IDENTIFIER_UINT64_VAL;
        // NOT part of the INT8..UINT64 span above — that span is the FIXED widths, and these two are the
        // platform-varying pair, deliberately appended after it in kama.ast.h. They are still lock-free
        // machine words, so they are named here on purpose rather than by widening the span.
        bool isSize = el->builtInVal == IDENTIFIER_ISIZE_VAL || el->builtInVal == IDENTIFIER_USIZE_VAL
                   || el->builtInVal == IDENTIFIER_CLONG_VAL || el->builtInVal == IDENTIFIER_CULONG_VAL;   // C `long`: a word too
        bool isPtr  = isRawPtrName(el);
        // `bool` is a lock-free byte too — the done-flag the docs advertise. What it cannot do is
        // `fetchAdd`/`fetchSub`: the shim adds the raw bytes, and `true + 1` is the byte 2, which is not a
        // `_Bool`. Those two are refused at the CALL on a `bool` cell (emitDispatch), where `swap`/
        // `compareExchange` are the flip. A float is the same story at width 4/8: load/store/swap/
        // compareExchange are bit movement the width switch already does (compareExchange compares BITS,
        // which is C++20 `atomic<float>`), and only `fetchAdd`/`fetchSub` are refused at the call — no
        // hardware has a lock-free float add; the idiom is a compareExchange loop. It used to stay out
        // "with no use", which the consumer-driven audit ruled is not a reason (0.9.228).
        bool isBool  = el->builtInVal == IDENTIFIER_BOOL_VAL;
        bool isFloat = el->builtInVal == IDENTIFIER_FLOAT32_VAL || el->builtInVal == IDENTIFIER_FLOAT64_VAL;
        if (!isInt && !isSize && !isPtr && !isBool && !isFloat) {
            unsupported(("`Atomic<T>` requires an integer primitive, `bool`, a float or `UnsafePtr` element (a lock-free "
                         "machine word) — `" + cType(el) + "` is not one; use one `Atomic` field per shared word").c_str(), line);
            return;
        }
    }

    // A `type view` as a generic type ARGUMENT (a collection's buffered element, a user generic's field)
    // stores a borrow that dangles. A collection buffers behind `UnsafePtr<View>` — NOT a bare `View` field — so
    // emitClassStruct's field-reject misses it, and today the only signal is the indirect escape check on an
    // element-returning library method (a diagnostic pointing at a library line, not the user's decl). Reject
    // here at the instantiation, at the user's use-site line. Skip variant/enum templates (`Optional<View>`) —
    // the payload guard at the tail of this function owns those with its own message.
    if (!opaqueArg && _genericTypes.count(tmpl) && _genericTypes[tmpl].variants.empty())
        for (auto& c : concrete) {
            std::string base = (c && c->value) ? resolveUserName(*c->value, c->qualifier) : "";
            bool viewArg = (!base.empty() && _genericTypes.count(base) && _genericTypes[base].isBorrow)
                        || (c && isViewCType(cType(c)));
            if (viewArg) {
                unsupported(("a view (`" + cType(c) + "`) borrows its buffer, so it can't be a collection "
                             "element — it would dangle; copy into an owning collection instead").c_str(), line);
                return;
            }
        }

    // A CONTRACT as a generic type ARGUMENT, for the same reason as a view: a contract value borrows its object
    // (a fat pointer to someone else's storage), so a collection buffering it or a type holding it dangles. Only
    // a heap handle takes one — anything implementing `HeapOwner` (`Owned`, `Shared`, a user `Box<T>`), which
    // BOXES it, routed below through the interface-owner path — and `Weak`, its partner. Refused here, once, at
    // the argument — the instance's bodies used to refuse it instead, a dozen times over at stdlib lines the
    // author never wrote (`DynamicArray<Shape>`: 12 diagnostics across dynamic_array.kama and view.kama).
    //
    // Decided from the TEMPLATES, not from what is registered yet: a program may name `RcWeak<Shape>` in a
    // signature before its `Rc<Shape>` exists, so "is this a weak partner" is the routing's own rule below — some
    // `HeapOwner` template has a method returning this template — asked of the declarations directly.
    bool boxesContract = tmpl == _weakTmpl;
    if (!boxesContract && !_heapOwnerContract.empty()) {
        auto ownsHeap = [&](const ClassInfo& t) {
            for (auto& ifn : t.interfaces) if (resolveUserName(ifn, nullptr) == _heapOwnerContract) return true;
            return false;
        };
        auto ti = _genericTypes.find(tmpl);
        if (ti != _genericTypes.end() && ownsHeap(ti->second)) boxesContract = true;
        for (auto& kv : _genericTypes) {
            if (boxesContract) break;
            if (kv.first == tmpl || !kv.second.copyable || !ownsHeap(kv.second)) continue;
            for (auto& mk : kv.second.methods) {
                const SharedIdentifier& rt = mk.second.returnType;
                if (rt && rt->value && rt->genericArg && resolveUserName(*rt->value, rt->qualifier) == tmpl) {
                    boxesContract = true; break;
                }
            }
        }
    }
    if (!opaqueArg && !boxesContract)
        for (auto& c : concrete) {
            const std::string base = (c && c->value && !c->genericArg) ? resolveUserName(*c->value, c->qualifier) : "";
            if (!base.empty() && (isInterface(base) || _genericContracts.count(base))) {
                const std::string shown = demangleForDisplay(base);
                unsupported(("a contract (`" + shown + "`) borrows its object, so it can't be a type argument of `"
                             + demangleForDisplay(tmpl) + "` — it would dangle; own the object instead (`Owned<"
                             + shown + ">` or `Shared<" + shown + ">`)").c_str(), line);
                _refusedTypeArgSites.insert(reportPath(diagFile()) + ":" + std::to_string(line));
                return;
            }
        }

    std::string mangled = tmpl;
    for (auto& c : concrete) mangled += "_" + mangleElem(c);
    if (_genericTypeInsts.count(mangled)) return;               // dedup
    // ...and a name already registered as a built-in SMART POINTER. A `Shared<Contract>` registers its `Weak`
    // partner that way (below), over the same concrete args, and never as a generic instance — so a later
    // `Weak<Shape>` missed the dedup above and overwrote the type-erased partner with the library class, whose
    // body then could not construct its `Shared`. Only a program that named `Weak<Shape>` in a signature FIRST
    // (the library class registered, then overwritten by the partner) built; `tests/shared_iface` is one (KR-15).
    if (_collections.count(mangled) && isSmartPtrClass(mangled)) return;

    // A library heap owner (`… implements HeapOwner<T>`) over a CONTRACT element is Rust's
    // `Box<dyn Trait>`: the type-erased `{obj,vtbl}` fat pointer + vtable dispatch/drop can't be safe
    // library code, so route this instance through the intrinsic interface-owner path (a smart pointer
    // under the specialized name) — every downstream `isSmartPtrClass` path then applies. A concrete
    // element falls through to the normal library-class instantiation below.
    // Kind: a **Copyable** heap owner retains-on-copy = reference-counted (`Shared` IFACE, with a ctrl
    // block); a move-only one is unique (`Owned` IFACE). (`Rc<T>` has `copy()`; `Box<T>` does not.)
    if (!_heapOwnerContract.empty() && !concrete.empty() && concrete[0] && isInterface(cType(concrete[0]))) {
        bool implementsHeapOwner = false;
        auto ti = _genericTypes.find(tmpl);
        if (ti != _genericTypes.end())
            for (auto& ifn : ti->second.interfaces)
                if (resolveUserName(ifn, nullptr) == _heapOwnerContract) { implementsHeapOwner = true; break; }
        if (implementsHeapOwner) {
            CollKind k = ti->second.copyable ? CollKind::Shared : CollKind::Owned;   // Copyable => refcounted
            // The box's allocator type arg (the concrete arg that `implements Allocator`) — GlobalAllocator/""
            // stays the default libc path; a stateful one routes the intrinsic macros through it (M11d).
            std::string allocTy;
            for (auto& c : concrete) {
                std::string ct = cType(c);
                auto aci = _classes.find(ct);
                if (aci != _classes.end() && implementsContractTemplate(&aci->second, "Allocator")) { allocTy = ct; break; }
            }
            registerSmartPtr(k, concrete[0], mangled);
            _collections[mangled].allocType = allocTy;
            // A refcounted (Shared) owner may have a WEAK partner: a method (`downgrade`) returning a
            // DIFFERENT generic resource `RcWeak<T>` (not the owner itself). Route the weak to the Weak
            // IFACE + wire `downgrade`/`tryUpgrade` so the library API works on the type-erased pair.
            if (k == CollKind::Shared) {
                std::string downName, weakTmpl;
                for (auto& kv : ti->second.methods) {   // find the downgrade: returns a non-self generic type
                    SharedIdentifier rt = kv.second.returnType;
                    if (!rt || !rt->value || !rt->genericArg) continue;
                    std::string rn = resolveUserName(*rt->value, rt->qualifier);
                    if (rn == "Result" || rn == "Optional") continue;   // a sum-type return (fallible `deserialize`, etc.) is never the Weak partner
                    if (rn != tmpl && _genericTypes.count(rn)) { downName = kv.first; weakTmpl = rn; break; }
                }
                if (!weakTmpl.empty()) {
                    // Name the Weak partner over the SAME concrete args as the Shared (element +
                    // allocator/…), so it matches `mangleElem(Weak<…>)` — which fills default type params
                    // (e.g. `Weak<Shape>` → `Weak_Shape_GlobalAllocator`). Using only the element would
                    // diverge from every downstream `Weak<…>` reference.
                    std::string weakMangled = weakTmpl;
                    for (auto& c : concrete) weakMangled += "_" + mangleElem(c);
                    registerSmartPtr(CollKind::Weak, concrete[0], weakMangled);
                    _collections[weakMangled].allocType   = allocTy;       // the Weak frees the ctrl through its own A copy
                    _collections[mangled].ifacePartner    = weakMangled;   // Rc_Shape downgrades to RcWeak_Shape
                    _collections[mangled].downgradeName   = downName;
                    _collections[weakMangled].ifacePartner = mangled;      // RcWeak_Shape upgrades to Rc_Shape
                    registerOptionalOfName(mangled);                       // Optional<Rc_Shape> for tryUpgrade
                    if (!_synthCtx) _synthCtx = std::make_shared<CodeGenContext>(std::make_shared<std::string>("<synth>"));
                    auto bare = [&](const std::string& n){ return synthId(n); };
                    // downgrade intrinsic on Rc_Shape (-> RcWeak_Shape); dispatched via _classes[cls].methods
                    MethodInfo dm; dm.cName = mangled + "__" + downName; dm.isIntrinsic = true;
                    dm.isConst = true;   // hands back a fresh Weak; the Shared it reads is untouched
                    dm.returnType = bare(weakMangled);
                    _classes[mangled].methods[downName] = dm;
                    // RcWeak_Shape.tryUpgrade returns Optional<Rc_Shape> (not the default Optional<Shared<elem>>)
                    auto opt = bare("Optional");
                    opt->genericArg = bare(mangled); opt->genericArgs = std::make_shared<IdentifierList>();
                    opt->genericArgs->push_back(opt->genericArg);
                    if (_classes[weakMangled].methods.count("tryUpgrade"))
                        _classes[weakMangled].methods["tryUpgrade"].returnType = opt;
                }
            }
            return;
        }
    }

    // each concrete type argument must satisfy its parameter's contract bounds. Runs once per
    // unique instance (after dedup); with _typeSubst still at the caller's binding so a nested arg is
    // already the resolved `concrete[i]`. A bound NAMES a contract visible where the TEMPLATE was
    // declared (like a default type arg — see the M8 default-slot ctx handling), NOT at the use site: a
    // prelude-global bound (`Hashable`) resolves from anywhere via the global fallback, but a
    // stdlib-namespaced bound (`std::collections::Hasher` on `Map`) is invisible at a use site that
    // imported only `Map`.
    //
    // ⚠️ That ctx move belongs to `checkBounds`, which does it NARROWLY (BoundCtxScope, around the
    // contract-NAME lookup alone) off the same `_genericTypeCtx[tmpl]` this used to read. A second, wider
    // swap here was redundant for resolution and actively wrong for attribution: `checkBounds` scopes its
    // diagnostic's FILE from `_nsCtx`, so moving the whole call under the template's ctx handed the
    // template's file to a mistake the use site made. `Map<NotHashable, int32>` in a four-line user
    // program reported `lib/std/collections/map.kama:4` — the user's line, the library's name, and line 4
    // of map.kama is a comment. The generic FUNCTION path never had the swap and always named the right
    // file, which is what identified this one. Guarded by tools/check-diag-file.sh case 8.
    SharedBoundsList bounds = _genericTypeBounds.count(tmpl) ? _genericTypeBounds[tmpl] : SharedBoundsList();
    std::map<std::string, SharedIdentifier> boundBind;
    for (size_t i = 0; i < params.size() && i < concrete.size(); ++i) boundBind[params[i]] = concrete[i];
    bool boundsOk = true;
    if (bounds)
        for (size_t i = 0; i < params.size() && i < bounds->size(); ++i)
            if (!checkBounds(params[i], concrete[i], (*bounds)[i], line, tmpl, boundBind))   // `line` is null-args-safe (bare all-defaulted use)
                boundsOk = false;
    // A `T = cchar` instance is POISONED like a failed bound, silently: the declared-type hooks already report
    // the user's spelling, and every nested instantiation the poisoned body forces would otherwise report
    // again from a library line (nine errors for one `DynamicArray<cchar>`). The turbofish path reports.
    for (auto& c : concrete) if (containsBareCChar(c)) boundsOk = false;
    // A type argument the bound REFUSED must not be carried into the template's body. Registration
    // continues — the instance's shape has to exist or every later reference to it becomes a second,
    // unrelated cascade ("unknown type") — but `emitGenericTypeInst` skips its member BODIES, so the
    // template cannot go on to report the consequences of an argument it already rejected. This is
    // Rust's `ty::Error` / Swift's `ErrorType` poisoning, and C++20's "constraint not satisfied, do not
    // instantiate"; walking the body anyway is the pre-concepts C++ behaviour, which is what this was.
    if (!boundsOk) _boundFailedInsts.insert(mangled);
    // ...and while THIS refused instance's shape is registered below, a nested instantiation its member
    // signatures force (`Channel<Quiet>` mentions `Receiver<T>`, so `Receiver<Quiet>` registers here, under
    // the template's own file and line) fails the same bound again — a consequence of the argument already
    // refused, reported against the LIBRARY. Guard case 8b: a failed bound is reported ONCE, at the use
    // site. So bound failures are silent for the duration of a refused instance's registration.
    struct SilentBounds { int& n; bool on; SilentBounds(int& c, bool o) : n(c), on(o) { if (on) ++n; } ~SilentBounds() { if (on) --n; } };
    SilentBounds _sb(_silentBounds, !boundsOk);

    // Register the KEY first so the transitive scan below can't recurse into this same instance.
    _genericTypeInsts[mangled] = { tmpl, mangled, concrete };
    recordInstSite(mangled, tmpl, concrete, line);
    _genericTypeInstOf[mangled] = tmpl;
    _genericTypeInstOrder.push_back(mangled);
    // Emit the instance's members under the TEMPLATE's ctx, so a name the template body references in
    // its own scope (a sibling generic `Weak<T>`, a module-local helper `Ctrl`) resolves. The concrete
    // args were `absolutizeType`d to their use-site mangle, so they resolve context-free here too — no
    // need to fall back to the use-site ctx. For a same-scope user generic the two ctxs coincide.
    _genericTypeInstCtx[mangled] = _genericTypeCtx[tmpl];

    NsCtx savedCtx = _nsCtx;
    std::map<std::string, SharedIdentifier> savedSubst = _typeSubst;
    _nsCtx = _genericTypeCtx[tmpl];
    _typeSubst.clear();
    for (size_t i = 0; i < params.size(); ++i) _typeSubst[params[i]] = concrete[i];   // zip params -> args

    ClassInfo ci = _genericTypes[tmpl];                         // copy the template shape
    ci.name = mangled;
    ci.isGenericInst = true;
    // A PAYLOAD-LESS generic enum's instance is its integer, exactly as a non-generic one is (KR-59): the
    // type parameter can reach only its members, never its layout. `_enums` carries the constants; the
    // ClassInfo is the scalar receiver its members hang on.
    if (ci.enumNode && ci.isVariant && !ci.variants.empty()
        && std::all_of(ci.variants.begin(), ci.variants.end(), [](const VariantCase& v) { return v.payload.empty(); })) {
        ci.isVariant = false;
        ci.tagCType.clear();
        ci.kind = TypeKind::Value;
        ci.isScalarRecv = true;
        _enums[mangled] = scalarEnumInfo(ci.enumNode, mangled, ci.declFile);
    }
    // Conditional Copyable (`implements Copyable(bare: …) when T: Bound`): this instance is Copyable
    // only when its gated type-param satisfies the bound. If not, drop the capability AND its `copy()`
    // method so it is never emitted for this instance — this is what lets `List<Owned>` compile even
    // though its element isn't copyable, while `copy list<int32>` still works.
    bool copyableActive = ci.copyable;
    if (!ci.copyableWhenParams.empty()) {
        copyableActive = whenConditionsHold(ci.copyableWhenParams, ci.copyableWhenBounds, ci.copyableWhenBoundNodes, params, concrete);
        if (!copyableActive) { ci.copyable = false; ci.methods.erase("copy"); ci.ctors.erase("copy"); }
    }
    // Conditional METHODS (`fn … when T: Bound`): drop any whose bound fails for this instance, so it's
    // never emitted (the value `iterator()` needs a Copyable element — a `List<Owned>` simply lacks it).
    for (auto it = ci.methods.begin(); it != ci.methods.end(); ) {
        const MethodInfo& mi = it->second;
        bool drop = !mi.whenParams.empty()
                 && !whenConditionsHold(mi.whenParams, mi.whenBounds, mi.whenBoundNodes, params, concrete);
        if (drop) it = ci.methods.erase(it); else ++it;
    }
    for (auto& kv : ci.methods) kv.second.cName = mangled + "__" + kv.first;
    // Re-derive ParamSig under substitution so call-site arg typing is concrete (not a stale "T").
    // A `This` PARAMETER (`This operator+(This rhs)`) is this instance, so `_thisType` has to be bound
    // here too — the conformance block below binds it for the same reason, but only after this loop.
    {
        ScopedStr _ts(_thisType, mangled);
        for (auto& kv : ci.methods) {
            if (kv.second.node) kv.second.params = paramSigsOf(kv.second.node->params);
            else if (kv.second.isOperator && kv.second.opDecl)   // an operator has no `node`
                kv.second.params = paramSigsOf(operatorParamList(kv.second.opDecl->operatorDeclarator.get()));
        }
    }
    // Resolve the `implements` list under THIS instance's subst (linkBases skips generic instances).
    if (ci.baseTypesDecl() && ci.baseTypesDecl()->interfaces && (!ci.enumNode || _filledEnumTemplates.count(tmpl)))
        ci.interfaces = instanceInterfaces(ci, mangled, params, concrete);
    _classes[mangled] = ci;
    if (ci.enumNode && _filledEnumTemplates.count(tmpl)) checkEnumInstanceConformances(_classes[mangled], tmpl);

    // Transitive close: register any collection / generic type the substituted members use.
    for (auto& f : ci.fields) scanTypeForCollections(f.type);
    for (auto& kv : ci.methods) {
        scanTypeForCollections(kv.second.returnType);
        if (kv.second.node) for (auto& p : *kv.second.node->params) if (p) scanTypeForCollections(p->type);
    }
    // a generic tagged union (Optional<Shared<T>>) — scan each variant's substituted payload so
    // the inner `Shared_int32` etc. registers (inner-first) before this instance's dtor references it.
    for (auto& v : ci.variants) for (auto& f : v.payload) scanTypeForCollections(f.type);
    // A view in a tagged-union PAYLOAD (`Optional<View>`) would let the borrow be stored or returned via
    // the wrapper — the plain-field reject (emitClassStruct) doesn't see a union payload, so catch it here
    // where the payload type is substituted concrete (`View_int32`, now registered by the scan above). A
    // view is local/parameter-only; it can't be wrapped-and-stored.
    for (auto& v : ci.variants)
        for (auto& f : v.payload)
            if (f.type && isViewCType(cType(f.type)))
                // `line`, not `f.type->line`: the payload field belongs to the TEMPLATE — `Optional`'s
                // payload is declared in the prelude — so its line is a line of a file this diagnostic
                // does not name. The mistake is the type argument, at the use site, which is what `line` is.
                unsupported(("a view (`" + cType(f.type) + "`) can't be an `enum` payload (`" + ci.name
                             + "`) — it borrows and would escape via the enum; a view is local/parameter-only").c_str(),
                            line);

    // `@generate(...)` on the TEMPLATE, applied here — this is the only place a generic type's fields
    // have concrete types to walk, which is why the four "not a generic" refusals this replaces existed.
    //
    // ⚠️ ORDER, three ways, and each was a defect in an earlier draft:
    //   - AFTER `_classes[mangled] = ci` (11165), because the synthesized `deserialize` builds a
    //     `Result<This, …>` from `synthId(mangled)` and a name resolves only once its key is in `_classes`.
    //   - AFTER the transitive scans just above, because the conditional rule asks each field type
    //     whether it conforms — and for `Box<Box<int32>>` the inner instance does not EXIST until that
    //     scan registers it, so the outer would decide against a type that was about to qualify.
    //   - and on `_classes[mangled]`, not the local `ci`: the map holds the copy every later pass reads.
    // The `_genericTypeInsts` guard at the top of this function is what stops a self-referential template
    // recursing here.
    if (_classes[mangled].genSerialize || _classes[mangled].genDeserialize || _classes[mangled].genFormat
        || _classes[mangled].genEquatable || _classes[mangled].genHashable
        || _classes[mangled].genOf || _classes[mangled].genZero)
        registerDerives(_classes[mangled], synthId(mangled), line);

    _typeSubst = savedSubst;
    _nsCtx = savedCtx;
}

// A `when [P: B]` gate conditions a member or a conformance on one of the declaring type's OWN parameters. A
// name that is not one was accepted and then judged "conservatively": on a generic type the member silently
// vanished from every instance, and on a concrete type — which has no parameters at all — the gate was
// never read, so the member was always there. Both look like working code, so both are refused.
void CEmitter::checkWhenParams(const SharedIdentifierList& whenParams, const SharedStringList& typeParams,
                               const std::string& owner, int line)
{
    if (!whenParams) return;
    for (auto& p : *whenParams) {
        if (!p || !p->value) continue;
        bool known = false;
        if (typeParams) for (auto& t : *typeParams) if (t && *t == *p->value) known = true;
        if (known) continue;
        const int at = p->line ? p->line : line;
        if (!typeParams || typeParams->empty())
            unsupported(("`when [" + *p->value + ": …]` conditions on a type parameter, and `" + owner
                         + "` has none — a gate on a concrete type would hold always or never; remove it").c_str(), at);
        else
            unsupported(("`when [" + *p->value + ": …]` names `" + *p->value + "`, which is not a type parameter "
                         "of `" + owner + "` — a gate conditions on the type's own parameters").c_str(), at);
    }
}

// Why a generic instance lacks a method its TEMPLATE declares: the method's `when [...]` gate failed for this
// instance's arguments. Returns the clause to append to "has no method" — naming the gate and the first
// argument that fails it — or "" when the template has no such gated method. Without it the message read as
// if the method were never declared, while a gated CONSTRUCTOR in the same position already said why (KR-43).
std::string CEmitter::whenGateReason(const std::string& inst, const std::string& method)
{
    auto gi = _genericTypeInsts.find(inst);
    if (gi == _genericTypeInsts.end()) return "";
    auto tt = _genericTypes.find(gi->second.templateKey);
    if (tt == _genericTypes.end()) return "";
    auto mit = tt->second.methods.find(method);
    if (mit == tt->second.methods.end() || mit->second.whenParams.empty()) return "";
    const MethodInfo& tm = mit->second;
    const std::vector<std::string>& params = _genericTypeParams[gi->second.templateKey];
    std::string cond;
    for (size_t i = 0; i < tm.whenParams.size(); ++i)
        cond += (i ? ", " : "") + tm.whenParams[i] + ": " + demangleForDisplay(tm.whenBounds[i]);
    std::string why;
    for (size_t c = 0; c < tm.whenParams.size() && why.empty(); ++c)
        for (size_t i = 0; i < params.size() && i < gi->second.typeArgs.size(); ++i) {
            if (params[i] != tm.whenParams[c]) continue;
            // whenConditionsHold treats a serde gate as unmet in a program that serializes nothing — say that,
            // rather than blame an argument that may well be Serializable.
            if (!_usesSerde && (tm.whenBounds[c] == "Serializable" || tm.whenBounds[c] == "Deserializable")) {
                why = ", and this program uses no serialization, so a `" + tm.whenBounds[c] + "` gate is off";
                break;
            }
            std::vector<std::string> wp{tm.whenParams[c]}, wb{tm.whenBounds[c]};
            std::vector<SharedIdentifier> wn{c < tm.whenBoundNodes.size() ? tm.whenBoundNodes[c] : SharedIdentifier()};
            if (!whenConditionsHold(wp, wb, wn, params, gi->second.typeArgs))
                why = ", and `" + demangleForDisplay(cType(gi->second.typeArgs[i])) + "` (for `" + params[i]
                    + "`) does not satisfy `" + demangleForDisplay(tm.whenBounds[c]) + "`";
            break;
        }
    return " — it is declared `when [" + cond + "]`" + why;
}

// A generic instance's `implements` list, resolved under THIS instance's subst (which the caller has bound).
// A generic contract implemented with the type's own param (`Box<T> implements Deref<T>`) mangles to the
// concrete instance (`Deref_Point`) and that instance is registered; plain contracts just resolve.
std::vector<std::string> CEmitter::instanceInterfaces(const ClassInfo& ci, const std::string& mangled,
                                                      const std::vector<std::string>& params,
                                                      const std::vector<SharedIdentifier>& concrete)
{
    std::vector<std::string> out;
    // `This` is bound to THIS instance, not the template: a pinned conformance on a generic type
    // (`DynamicArray<T,A> implements Copyable<This>`) has to name `Copyable_DynamicArray_int32...`,
    // one per instance. linkBases skips generic instances, so this is the only place it can happen —
    // without it every instance registers the literal `Copyable_This` and they all collide.
    ScopedStr  _ts(_thisType, mangled);
    ScopedThis _tt(_typeSubst, synthId(mangled));
    for (auto& itf : *ci.baseTypesDecl()->interfaces) {
        if (!itf || !itf->value) continue;
        // A conditional interface (`Copyable(bare:) when […]`, `Iterable<T> when […]`) is present only
        // when its when-conditions hold for this instance — drop it otherwise (generalizes the old
        // Copyable-only gate; the methods it fronts are dropped by the method gate).
        if (itf->whenParams && !itf->whenParams->empty()) {
            std::vector<std::string> wp, wb;
            std::vector<SharedIdentifier> wn;
            for (size_t c = 0; c < itf->whenParams->size(); ++c) {
                auto& p = (*itf->whenParams)[c];
                auto& b = itf->whenBounds ? (*itf->whenBounds)[c] : p;
                wp.push_back(p && p->value ? *p->value : "");
                wb.push_back(resolveWhenBound(b));
                wn.push_back(b);
            }
            if (!whenConditionsHold(wp, wb, wn, params, concrete)) continue;
        }
        std::string base = resolveUserName(*itf->value, itf->qualifier);
        if (itf->genericArg && _genericContracts.count(base)) {
            scanTypeForGenericContracts(itf);                     // register `Deref_Point` under subst
            base = genericTypeMangle(base, itf->genericArgs);     // mangleElem resolves the class param
        }
        out.push_back(base);
    }
    return out;
}

// A generic ENUM instance's conformances are checked here, per instance, because an enum has no
// `ClassDeclarationNode` and so never reaches the class conformance sweep — the concrete-enum path
// (collectEnumConformances) checks its own the same way. Reported against the template's declaration, in
// the template's FILE, so N instances missing the same method are one diagnostic, not N.
void CEmitter::checkEnumInstanceConformances(ClassInfo& inst, const std::string& tmpl)
{
    ScopedStr _cu(_collectingUnitPath, inst.declFile);
    const std::string bare = inst.enumNode && inst.enumNode->identifier ? *inst.enumNode->identifier->value : tmpl;
    for (auto& c : inst.interfaces) {
        _polyDispatchContracts.insert(c);   // dynamic dispatch through a fat pointer + boxing into `Owned<C>`
        checkImplCompleteness(inst, c, bare, inst.declLine());
    }
}

// Bring an instance cut BEFORE its generic enum's template was filled (collectEnumConformances) up to date:
// a prelude derive or a signature scan registers `Result<…>`/`Optional<…>` instances long before contracts
// exist. The template's methods and `implements` list are applied exactly as registerGenericTypeInst would
// have applied them, and ADDED to what the instance already holds — its derived members stay.
void CEmitter::instantiateEnumMembers(const GenericTypeInst& gi)
{
    auto ci = _classes.find(gi.mangledName);
    auto ti = _genericTypes.find(gi.templateKey);
    if (ci == _classes.end() || ti == _genericTypes.end()) return;
    const std::vector<std::string>& params = _genericTypeParams[gi.templateKey];
    NsCtx savedCtx = _nsCtx;
    std::map<std::string, SharedIdentifier> savedSubst = _typeSubst;
    _nsCtx = _genericTypeCtx[gi.templateKey];
    _typeSubst.clear();
    for (size_t i = 0; i < params.size() && i < gi.typeArgs.size(); ++i) _typeSubst[params[i]] = gi.typeArgs[i];
    ClassInfo& inst = ci->second;
    {
        ScopedStr _ts(_thisType, gi.mangledName);
        for (auto& kv : ti->second.methods) {
            if (inst.methods.count(kv.first)) continue;
            const MethodInfo& tm = kv.second;
            if (!tm.whenParams.empty()
                && !whenConditionsHold(tm.whenParams, tm.whenBounds, tm.whenBoundNodes, params, gi.typeArgs))
                continue;
            MethodInfo mi = tm;
            mi.cName  = gi.mangledName + "__" + kv.first;
            mi.params = paramSigsOf(tm.node->params);
            inst.methods[kv.first] = mi;
        }
    }
    if (inst.baseTypesDecl() && inst.baseTypesDecl()->interfaces)
        for (auto& c : instanceInterfaces(inst, gi.mangledName, params, gi.typeArgs))
            if (std::find(inst.interfaces.begin(), inst.interfaces.end(), c) == inst.interfaces.end())
                inst.interfaces.push_back(c);
    for (auto& kv : inst.methods) {
        scanTypeForCollections(kv.second.returnType);
        if (kv.second.node) for (auto& p : *kv.second.node->params) if (p) scanTypeForCollections(p->type);
    }
    _typeSubst = savedSubst;
    _nsCtx = savedCtx;
    checkEnumInstanceConformances(_classes[gi.mangledName], gi.templateKey);
}

// A contract's method-prototype list — from _interfaces (a concrete contract or a specialized
// generic-contract instance) or _genericContracts (a template). Bound-checking matches by method
// NAME (type-parameter-independent), so it reads either table through this one accessor.
const std::vector<InterfaceMethod>* CEmitter::contractMethods(const std::string& name)
{
    auto it = _interfaces.find(name);
    if (it != _interfaces.end()) return &it->second.methods;
    auto gt = _genericContracts.find(name);
    if (gt != _genericContracts.end()) return &gt->second.methods;
    return nullptr;
}

// A resolved contract's `for`-clause mask — the two-table lookup contractMethods() above does, plus the
// template hint. The hint is not belt-and-braces: resolveInterfaceNames only MANGLES a pinned generic
// contract (`Real<This>` on `float64` -> `Real_double`); minting the instance into _interfaces happens
// at the scanTypeForGenericContracts call sites, none of which walk an IntrinsicImplNode. So a bare
// find("Real_double") from applyIntrinsicImpl misses, and a gate that misses passes silently.
unsigned CEmitter::implKindsOf(const std::string& contract, const std::string& tmplHint)
{
    auto it = _interfaces.find(contract);
    if (it != _interfaces.end()) return it->second.implKinds;
    auto gt = _genericContracts.find(contract);
    if (gt != _genericContracts.end()) return gt->second.implKinds;
    if (!tmplHint.empty()) {
        auto ht = _genericContracts.find(tmplHint);
        if (ht != _genericContracts.end()) return ht->second.implKinds;
        auto hi = _interfaces.find(tmplHint);
        if (hi != _interfaces.end()) return hi->second.implKinds;
    }
    return 0;   // a base class, an unresolved name, or a contract whose clause was already diagnosed
}

// register the specialized instance for a generic-contract reference `Iterator<Arg>` (mirrors
// scanTypeForGenericTypes). Driven by scanTypeForCollections at each type node.
void CEmitter::scanTypeForGenericContracts(SharedIdentifier t)
{
    if (!t || !t->value || !t->genericArg) return;
    std::string tmpl = resolveUserName(*t->value, t->qualifier);
    if (_genericContracts.count(tmpl)) registerGenericContractInst(tmpl, t->genericArgs);
}

// Build one specialized InterfaceInfo per `Iterator<Arg>` (the exact parallel of
// registerGenericTypeInst, minus fields/ctor/dtor): resolve each arg through the active _typeSubst
// (the nested/transitive case), mangle, dedup, copy the template shape into _interfaces under the
// specialized name, then transitively scan the substituted method sigs so an inner `Optional<T>`
// registers `Optional_int32` before this instance's vtable references it.
void CEmitter::registerGenericContractInst(const std::string& tmpl, SharedIdentifierList args)
{
    if (!args || args->empty()) return;
    const std::vector<std::string>& params = _genericContractParams[tmpl];

    // Substitute each arg through the active _typeSubst, then absolutize (both under the caller's ctx, BEFORE
    // the switch to the contract's own ctx below). `deepSubstType` handles a bare type-param (`T` -> binding)
    // AND a nested generic arg (`Iterator<Entry<K,V>>` -> `Iterator<Entry<int32,int32>>`); `absolutizeType`
    // pins each name to its home mangle, so a cross-namespace arg (`std::collections::Entry`) keeps its
    // qualified name when the transitive `Optional<T>` scan below runs under the contract's (global) ctx —
    // without it that scan would register a phantom bare `Optional_Entry_int32_int32` (unqualified, undefined
    // payload). A shallow "bare-param only" substitution would instead leave `Entry<K,V>` un-monomorphized
    // (a dangling `Optional_Entry_K_V`). Mirrors registerGenericTypeInst exactly.
    // Bind positional + named args, then fill trailing defaults (mirror of registerGenericTypeInst).
    int line = args->front() ? args->front()->line : 0;
    ScopedStr _cu(_collectingUnitPath, _nsCtx.unitPath.empty() ? _collectingUnitPath : _nsCtx.unitPath);
    auto dit = _genericContractDefaults.find(tmpl);
    const std::vector<SharedIdentifier> emptyDefs;
    const std::vector<SharedIdentifier>& defs = dit != _genericContractDefaults.end() ? dit->second : emptyDefs;
    std::vector<SharedIdentifier> bound; std::vector<bool> isDefault;
    positionalizeGenericArgs(params, defs, args, bound, isDefault);
    if (!validateGenericArgs(tmpl, "contract", params, args, bound, line)) return;

    std::vector<SharedIdentifier> concrete;
    for (size_t i = 0; i < bound.size(); ++i) {
        if (isDefault[i]) {
            NsCtx savedDefCtx = _nsCtx;
            auto hit = _genericContractCtx.find(tmpl);
            if (hit != _genericContractCtx.end()) _nsCtx = hit->second;
            concrete.push_back(absolutizeType(deepSubstType(bound[i])));
            _nsCtx = savedDefCtx;
        } else {
            concrete.push_back(absolutizeType(deepSubstType(bound[i])));
        }
    }

    std::string mangled = tmpl;
    for (auto& c : concrete) mangled += "_" + mangleElem(c);
    if (!_genericContractInsts.insert(mangled).second) return;    // dedup (also stops self-recursion)

    NsCtx savedCtx = _nsCtx;
    _genericContractInstCtx[mangled] = savedCtx;                  // use-site ctx: a user-type arg resolves here
    std::map<std::string, SharedIdentifier> savedSubst = _typeSubst;
    _nsCtx = _genericContractCtx[tmpl];
    _typeSubst.clear();
    for (size_t i = 0; i < params.size(); ++i) _typeSubst[params[i]] = concrete[i];   // zip params -> args

    InterfaceInfo ii = _genericContracts[tmpl];                   // copy the template (methods keep `T`)
    ii.name = mangled;
    ii.isGenericInst = true;
    ii.templateKey = tmpl;
    ii.typeArgs = concrete;
    _interfaces[mangled] = ii;                                    // the emit loops pick it up from here

    // transitive close: register any collection / generic type the substituted method sigs use, so
    // `Optional<T>` -> `Optional_int32` exists (as a complete typedef) before this vtable slot names it.
    for (auto& m : ii.methods) {
        scanTypeForCollections(m.returnType);
        if (m.params) for (auto& p : *m.params) if (p) scanTypeForCollections(p->type);
    }

    _typeSubst = savedSubst;
    _nsCtx = savedCtx;
}

// The conformance key of a primitive LITERAL, "" for anything else. Shared by the scan (which sees only
// literals and recorded locals) and the emit site (where a literal is not a "receiver", so the type-node
// and scalar-cType routes both answer nothing for it).
static std::string primKeyOfLiteral(ASTNode* n)
{
    if (dynamic_cast<Int8Node*>(n))    return "int8";
    if (dynamic_cast<Int16Node*>(n))   return "int16";
    if (dynamic_cast<Int32Node*>(n))   return "int32";
    if (dynamic_cast<Int64Node*>(n))   return "int64";
    if (dynamic_cast<UInt8Node*>(n))   return "uint8";
    if (dynamic_cast<UInt16Node*>(n))  return "uint16";
    if (dynamic_cast<UInt32Node*>(n))  return "uint32";
    if (dynamic_cast<UInt64Node*>(n))  return "uint64";
    if (dynamic_cast<CharNode*>(n))    return "char";
    return "";
}

// The conformance key of a primitive bound to contract `ct`, read at the emit site, where the expression's
// type is known exactly. "" when `e` is not a primitive that declares `ct`.
std::string CEmitter::primWidenKey(SharedExpression e, const std::string& ct)
{
    if (!e || !isInterface(ct)) return "";
    std::string k = primKeyOfLiteral(e.get());          // a literal is not a receiver; ask it directly
    if (k.empty()) {
        SharedIdentifier tn = receiverTypeNode(e);
        k = tn ? primKey(tn) : std::string();
        if (!isScalarPrimKey(k)) k = primKeyOfCType(receiverScalarCType(e));
    }
    // ...and anything else the emitter can type: a call or method result, a cast, arithmetic, a `bool` or
    // float literal. Without it each of those was refused as "does not implement it" (KR-37).
    if (!isScalarPrimKey(k)) k = primKeyOfCType(typeOfExpr(e));
    if (!isScalarPrimKey(k)) return "";
    ClassInfo* pci = primConformance(k);
    if (!pci) return "";
    for (auto& itf : pci->interfaces) if (itf == ct) return k;
    return "";
}

// The `<key>__as_<C>` vtbl for a type-intrinsic target (a primitive, or `string`) bound to a contract,
// returned as its symbol and DEFINED AHEAD of the C that names it. A target has no class declaration, so
// this cannot ride emitClassInterfaceVtables' per-unit sweep.
//
// Demand-driven, from the emit site that names the symbol — the one place the value's type is known
// exactly. It used to be recorded by a pre-pass that could see only a literal or a typed local, so a call
// result, a field, a cast, a `bool` literal and every `string` all reached clang as an undeclared vtbl, or
// were refused as "does not implement it" about a primitive that does (KR-37). In a module body the
// definition is queued as a file-scope helper, flushed before the module's buffered bodies; in the header
// it is collected and written ahead of the header's buffered body region (emitHeaderContent). Either way
// it is `static`, so a module's copy and the header's never collide — and a module never repeats one the
// header already has.
std::string CEmitter::intrinsicContractVtbl(const std::string& key, const std::string& cn)
{
    std::string sym = key + "__as_" + cn;
    if (_intrinsicVtblsHeader.count(sym)) return sym;
    if (_inHeaderPass) {
        _intrinsicVtblsHeader.insert(sym);
        _intrinsicVtblsHeaderText += renderIntrinsicContractVtbl(key, cn);
    } else if (_intrinsicVtblsModule.insert(sym).second)
        _fileScopeHelpers.push_back(renderIntrinsicContractVtbl(key, cn));
    return sym;
}

// A scalar receiver (a primitive, a payload-less enum) takes `self` BY VALUE, while a contract slot passes
// `void* self` — so each slot points at a thunk that loads the scalar and calls the method. Named per
// (target, contract, method), since two contracts may each require a method of the same name.
std::string CEmitter::scalarSlotThunk(const std::string& key, const std::string& cn, const std::string& m)
{
    return key + "__as_" + cn + "__" + m + "__thunk";
}

void CEmitter::emitScalarSlotThunks(ClassInfo& ci, InterfaceInfo& ii, const std::string& key)
{
    for (auto& m : ii.methods) {
        if (m.isCtor) continue;           // a contract-required ctor has no slot
        MethodInfo* mi = findMethod(&ci, m.name, nullptr);
        if (!mi) continue;
        std::string ret = cType(m.returnType) + placeRetSuffix(m.isPlaceReturn, m.isConstPlace);
        *_out << "static inline " << ret << " " << scalarSlotThunk(key, ii.name, m.name)
              << ifaceSlotSig(m.params) << " {\n";
        indent(1);
        if (ret != "void") *_out << "return ";
        *_out << mi->cName << "(*(" << ci.name << "*)self";
        if (m.params) for (auto& p : *m.params) if (p && p->identifier && p->identifier->value)
            *_out << ", " << *p->identifier->value;
        *_out << ");\n}\n";
    }
}

// The definition itself. A PRIMITIVE's methods take `self` BY VALUE (`isScalarRecv`) while a slot passes
// `void* self` — hence a thunk per slot. A `string`'s take a pointer, exactly as a class's do, so its slots
// are the class cast and its `__dtor` is the string's own.
std::string CEmitter::renderIntrinsicContractVtbl(const std::string& key, const std::string& cn)
{
    ClassInfo* pci = implTargetInfo(key);
    auto ii = _interfaces.find(cn);
    if (!pci || ii == _interfaces.end()) return "";   // the emit site already judged the conformance
    std::ostringstream os;
    std::ostream* saved = _out; _out = &os;
    // Render the slot signatures under the CONTRACT's own scope, with a generic-contract instance's
    // type args bound — the same treatment emitInterfaceTypes gives them. Every pinned contract is such
    // an instance, so without this a thunk's parameter comes out as the raw `T`.
    {
        ScopedContractNs _cns(_nsCtx, _collectingUnitPath, ii->second);
        ContractSubst _cs(*this, ii->second);
        if (pci->isScalarRecv) emitScalarSlotThunks(*pci, ii->second, key);
        *_out << "static const " << cn << "_vtbl " << key << "__as_" << cn << " = {\n";
        for (auto& m : ii->second.methods) {
            if (m.isCtor) continue;
            MethodInfo* mi = findMethod(pci, m.name, nullptr);
            if (!mi) continue;
            indent(1);
            if (pci->isScalarRecv)
                *_out << "." << m.name << " = &" << scalarSlotThunk(key, cn, m.name) << ",\n";
            else
                *_out << "." << m.name << " = (" << cType(m.returnType)
                      << placeRetSuffix(m.isPlaceReturn, m.isConstPlace) << "(*)" << ifaceSlotSig(m.params)
                      << ")&" << mi->cName << ",\n";
        }
        indent(1);
        if (pci->isScalarRecv) *_out << ".__dtor = (void(*)(void*))0,\n";   // a primitive owns nothing
        else                   *_out << ".__dtor = (void(*)(void*))&" << pci->name << "__dtor,\n";
        indent(1); *_out << ".__size = sizeof(" << pci->name << "), .__align = _Alignof(" << pci->name << "),\n";
        if (isPolyDispatchContract(cn)) { indent(1); *_out << ".__type = \"" << pci->name << "\",\n"; }
        *_out << "};\n\n";
    }
    _out = saved;
    return os.str();
}

void CEmitter::scanExprForCollections(SharedExpression e)
{
    if (!e) return;
    ASTNode* n = e.get();
    if (auto* oc = dynamic_cast<ObjectCreationNode*>(n)) {
        scanTypeForCollections(oc->type);
        if (oc->args) for (auto& a : *oc->args) if (a) scanExprForCollections(a->expression);
    } else if (auto* c = dynamic_cast<CastNode*>(n)) {
        scanTypeForCollections(c->type);
        scanExprForCollections(c->unaryExpression);
    } else if (auto* ad = dynamic_cast<AsDowncastNode*>(n)) {
        // Model C `.as<T>()` yields `Optional<T>` — register that instance so its struct + Some/None exist
        // for the result / enclosing match (mirrors string.find's Optional<usize> registration).
        scanExprForCollections(ad->operand);
        scanTypeForCollections(optionalTypeNode(ad->type));
    } else if (auto* b = dynamic_cast<BinaryExpressionNode*>(n)) {
        scanExprForCollections(b->LHS); scanExprForCollections(b->RHS);
    } else if (auto* l = dynamic_cast<LogicalAndOrNode*>(n)) {
        scanExprForCollections(l->LHS); scanExprForCollections(l->RHS);
    } else if (auto* tn = dynamic_cast<TernaryExpressionNode*>(n)) {
        scanExprForCollections(tn->condition); scanExprForCollections(tn->LHS); scanExprForCollections(tn->RHS);
    } else if (auto* as = dynamic_cast<AssignmentNode*>(n)) {
        scanExprForCollections(as->unaryExpression); scanExprForCollections(as->expression);
    } else if (auto* inv = dynamic_cast<InvocationNode*>(n)) {
        scanExprForCollections(inv->expression);
        if (inv->args) for (auto& a : *inv->args) if (a) scanExprForCollections(a->expression);
    } else if (auto* ea = dynamic_cast<ElementAccessNode*>(n)) {
        scanExprForCollections(ea->expression);
        if (ea->expressionlist) for (auto& x : *ea->expressionlist) scanExprForCollections(x);
    } else if (auto* ma = dynamic_cast<MemberAccessNode*>(n)) {
        scanExprForCollections(ma->expression);
    } else if (auto* pe = dynamic_cast<PreIncrDecrNode*>(n)) {
        scanExprForCollections(pe->expression);
    } else if (auto* po = dynamic_cast<PostIncrDecrNode*>(n)) {
        scanExprForCollections(po->expression);
    } else if (auto* su = dynamic_cast<SimpleUnaryExpressionNode*>(n)) {
        scanExprForCollections(su->expression);
    } else if (auto* al = dynamic_cast<ArrayLiteralNode*>(n)) {
        if (al->elements) for (auto& x : *al->elements) scanExprForCollections(x);
        scanExprForCollections(al->fillValue);
    } else if (auto* mm = dynamic_cast<MatchNode*>(n)) {
        // recurse into a `match` — the subject and each arm (a single expression OR a block),
        // so a type used ONLY inside an arm (e.g. a block-local `Shared<T>`) is still registered.
        scanExprForCollections(mm->subject);
        // A1: a value-producing variant ctor as the SUBJECT (`match (Optional::Some(x))`), or a
        // variant-producing ternary / nested `match` over such ctors — infer + register the instance HERE
        // (discovery has the local types via `_scanLocalTys`) and stash the mangled name for emitMatchSwitch
        // (which has no way to re-infer it).
        { std::string inst = inferMatchSubjInst(mm->subject); if (!inst.empty()) _matchSubjInst[mm] = inst; }
        if (mm->arms) for (auto& a : *mm->arms) if (a) {
            // An arm's payload bindings shadow whatever their names meant outside; this pass does not
            // resolve their types, so it hides the outer entries for the arm rather than mistyping them.
            auto savedTys = _scanLocalTys;
            if (a->bindings) for (auto& bn : *a->bindings) if (bn) _scanLocalTys.erase(*bn);
            scanExprForCollections(a->body);
            scanStmtForCollections(a->block);
            _scanLocalTys = savedTys;
        }
    }
}

void CEmitter::scanStmtForCollections(SharedStatement s)
{
    if (!s) return;
    ASTNode* n = s.get();
    if (auto* b = dynamic_cast<BlockNode*>(n)) {
        // A block's declarations end with the block. Both maps are flat and this pass has no scope stack,
        // so the block is the scope: restore what it inherited when it closes. Without this a sibling
        // block's `string m` typed a later `match (Optional::Some(value: m))` whose `m` was something else
        // entirely — the subject inferred `Optional<string>` and the arms were typed off the wrong instance.
        auto savedTys = _scanLocalTys; auto savedConsts = _constLocalVals;
        if (b->statements) for (auto& st : *b->statements) scanStmtForCollections(st);
        _scanLocalTys = savedTys; _constLocalVals = savedConsts;
    } else if (auto* d = dynamic_cast<LocalVariableDeclaration*>(n)) {
        scanTypeForCollections(d->type);
        // A1: record each local's declared type (name->type node) so an inline variant-ctor `match` subject
        // later in this body can infer its instance from a locally-typed payload (`match (Some(x))`).
        if (d->type && d->variables)
            for (auto& v : *d->variables) if (v && v->name && v->name->value)
                _scanLocalTys[*v->name->value] = d->type;
        if (d->variables) for (auto& v : *d->variables) if (v) scanExprForCollections(v->initializer);
    } else if (auto* cd = dynamic_cast<ConstLocalVariableDeclaration*>(n)) {
        scanTypeForCollections(cd->type);
        // 6b-2: gather a foldable integer const so a LATER const-generic size in this body resolves it
        // (`InlineArray<T,(CAP)>`). Statement-order walk = declared-before-use; runs in both the
        // no-binding pre-pass and registerInstColls (where `_comptimeSubst` lets `const CAP = N+1;` fold).
        if (cd->variables) for (auto& v : *cd->variables)
            if (v && v->name && v->name->value && v->initializer) {
                int64_t cv; if (constValue(v->initializer, cv)) _constLocalVals[*v->name->value] = cv;
            }
    } else if (auto* r = dynamic_cast<ReturnNode*>(n)) {
        scanExprForCollections(r->expression);
    } else if (auto* av = dynamic_cast<ArmValueNode*>(n)) {
        scanExprForCollections(av->value);
    } else if (auto* f = dynamic_cast<IfNode*>(n)) {
        scanExprForCollections(f->booleanExpression);
        scanStmtForCollections(f->ifStatement); scanStmtForCollections(f->elseStatement);
    } else if (auto* w = dynamic_cast<WhileNode*>(n)) {
        scanExprForCollections(w->booleanExpression); scanStmtForCollections(w->whileStatement);
    } else if (auto* dw = dynamic_cast<DoWhileNode*>(n)) {
        scanExprForCollections(dw->booleanExpression); scanStmtForCollections(dw->doWhileStatement);
    } else if (auto* fr = dynamic_cast<ForNode*>(n)) {
        if (fr->initializerStatements) for (auto& st : *fr->initializerStatements) scanStmtForCollections(st);
        scanExprForCollections(fr->booleanExpression);
        if (fr->iteratorStatements) for (auto& st : *fr->iteratorStatements) scanStmtForCollections(st);
        scanStmtForCollections(fr->body);
    } else if (auto* fe = dynamic_cast<ForEachNode*>(n)) {
        scanTypeForCollections(fe->type);
        scanExprForCollections(fe->expression);
        // The binding is a locally-typed value for the body, like a declaration — and like the generics
        // scan already records it. So `match (Optional::Some(value: m))` over a loop variable infers, and
        // an enclosing `m` of another type cannot answer for it. Restored after the body.
        {
            auto savedTys = _scanLocalTys;
            if (fe->name && fe->name->value) {
                if (fe->type) _scanLocalTys[*fe->name->value] = fe->type;
                else          _scanLocalTys.erase(*fe->name->value);
            }
            scanStmtForCollections(fe->body);
            _scanLocalTys = savedTys;
        }
    } else if (auto* pf = dynamic_cast<ParallelForNode*>(n)) {
        scanTypeForCollections(pf->type);
        scanTypeForCollections(parforViewType(pf->type));   // M6.3: the synthesized View<T> the loop iterates
        scanExprForCollections(pf->expression);
        scanStmtForCollections(pf->body);
    } else if (auto* bn = dynamic_cast<BorrowNode*>(n)) {
        if (bn->bindings) for (auto& b : *bn->bindings) if (b) scanExprForCollections(b->host);
        scanStmtForCollections(bn->body);
    } else if (dynamic_cast<ExpressionStatementNode*>(n)) {
        scanExprForCollections(std::dynamic_pointer_cast<ExpressionNode>(s));
    }
}

// Pre-pass: scan the whole program for Coll<T> instantiations.
void CEmitter::collectCollections(SharedCompilationUnit unit)
{
    if (!unit || !unit->codeDeclarationList) return;
    // A1: reset the discovery-time local-type map and seed it with a body's parameters before scanning it,
    // so an inline variant-ctor `match` subject (`match (Some(x))`) can infer its instance from `x`'s type.
    auto seedParams = [&](SharedParameterList params) {
        _scanLocalTys.clear();
        _constLocalVals.clear();   // 6b-2: local const values are per-body
        if (params) for (auto& p : *params)
            if (p && p->type && p->identifier && p->identifier->value) _scanLocalTys[*p->identifier->value] = p->type;
    };
    for (auto& decl : *unit->codeDeclarationList) {
        if (auto* mv = dynamic_cast<ModuleVariableDeclaration*>(decl.get())) {
            scanTypeForCollections(mv->type);   // register e.g. `InlineArray<uint8,256>` used only by a static
        } else if (auto* fn = dynamic_cast<FunctionDeclarationNode*>(decl.get())) {
            scanTypeForCollections(fn->returnType);
            if (fn->parameters) for (auto& p : *fn->parameters) if (p) scanTypeForCollections(p->type);
            seedParams(fn->parameters);
            scanStmtForCollections(fn->block);
        } else if (auto* cd = dynamic_cast<ClassDeclarationNode*>(decl.get())) {
            // skip a generic TYPE template's members — their types name the raw type params
            // (`List<T>` would register a bogus `List_T`). Each concrete `Wrap<int32>` reference in
            // the program drives registerGenericTypeInst, which re-scans the specialized members
            // under _typeSubst (so `List<T>` -> `List_int32`).
            if (cd->typeParams && !cd->typeParams->empty()) continue;
            // `class C implements Iterator<int32>` — register the specialized contract instance so its
            // vtable emits (a value/dynamic use of C needs `C__as_Iterator_int32`).
            // `This` is bound to the declaring type first: a PINNED contract writes its argument as `This`
            // (`implements Comparable<This>`), and this is where that instance is MINTED. Registering it
            // unbound files it under the literal word, so the vtable is defined as `C__as_Comparable_This`
            // while every use site asks for `C__as_Comparable_C` — a link error, not a diagnostic.
            if (cd->baseTypes && cd->baseTypes->interfaces) {
                ScopedStr  _ts(_thisType, qualify(*cd->name->value));
                ScopedThis _tt(_typeSubst, synthId(qualify(*cd->name->value)));
                for (auto& itf : *cd->baseTypes->interfaces) scanTypeForGenericContracts(itf);
            }
            // (`@generate(Equatable)`'s pinned instance is minted by registerDerives itself, which is
            // the only site a generic INSTANCE also passes through — this sweep skips generic templates.)
            if (cd->members) for (auto& m : *cd->members) {
                ASTNode* mn = m.get();
                if (auto* fd = dynamic_cast<ClassFieldDeclarationNode*>(mn)) {
                    scanTypeForCollections(fd->type);
                } else if (auto* kd = dynamic_cast<ClassConstDeclarationNode*>(mn)) {
                    scanTypeForCollections(kd->type);   // const field of a collection type
                } else if (auto* md = dynamic_cast<ClassMethodDeclarationNode*>(mn)) {
                    scanTypeForCollections(md->returnType);
                    if (md->params) for (auto& p : *md->params) if (p) scanTypeForCollections(p->type);
                    seedParams(md->params);
                    scanStmtForCollections(md->body);
                } else if (auto* cc = dynamic_cast<ClassConstructorDeclarationNode*>(mn)) {
                    if (cc->declarator && cc->declarator->params)
                        for (auto& p : *cc->declarator->params) if (p) scanTypeForCollections(p->type);
                    seedParams(cc->declarator ? cc->declarator->params : SharedParameterList());
                    scanStmtForCollections(cc->body);
                } else if (auto* dd = dynamic_cast<ClassDestructorDeclarationNode*>(mn)) {
                    _scanLocalTys.clear();
                    scanStmtForCollections(dd->body);
                }
            }
        } else if (auto* ed = dynamic_cast<EnumDeclarationNode*>(decl.get())) {
            // A tagged enum's variant PAYLOAD is a declared type just like a class field, and until this
            // arm existed nothing scanned it: a payload type reached registration only if some OTHER part
            // of the program happened to name it. So `enum E { A, B(Shared<Probe>) }` whose `B` is never
            // constructed emitted a C union naming `std__memory__Shared__F<file>__Probe_GlobalAllocator`, a type
            // that was never declared. The union has storage for every variant whether or not one is built,
            // so the payload must register unconditionally.
            //
            // Generic enums are skipped for the same reason generic classes are: their payloads name raw
            // type params (`Optional<T>` would register a bogus `Shared_T`). Each concrete instance
            // re-scans its substituted payloads in registerGenericTypeInst.
            if (ed->typeParams && !ed->typeParams->empty()) continue;
            // An enum's `implements` list needs the same treatment as a class's: a generic-contract
            // conformance has to mint its instance. Nothing scanned it before because no enum had one —
            // an enum could not carry a generic contract until `type enum E implements C` (M1) and could
            // not carry a PINNED one until now, where `implements Equatable<This>` is the ordinary form.
            if (ed->baseTypes && ed->baseTypes->interfaces && ed->identifier && ed->identifier->value) {
                ScopedStr  _ts(_thisType, enumKey(ed));
                ScopedThis _tt(_typeSubst, synthId(enumKey(ed)));
                for (auto& itf : *ed->baseTypes->interfaces) scanTypeForGenericContracts(itf);
            }
            if (ed->body) for (auto& m : *ed->body)
                if (m && m->payload)
                    for (auto& p : *m->payload) if (p) scanTypeForCollections(p->type);
        }
    }
}

// ---- Generics ------------------------------------------------------
// Monomorphization. A `fn name<T,...>(…)` template is specialized once per concrete
// type-argument tuple reachable from a call site. Discovery infers the tuple from the
// call's arguments (literals + locally-typed values), registers a deduped instantiation,
// and records the target per call node. Emission clones nothing — it re-emits the template
// body with `_typeSubst` set, so cType/mangleElem resolve each `T` to its concrete type.

// A cached, synthesized type node for a primitive kind — inference needs a SharedIdentifier
// to feed _typeSubst / mangleElem, but a literal argument has no type node of its own.
SharedIdentifier CEmitter::primTypeNode(int builtInVal)
{
    auto it = _primTypeCache.find(builtInVal);
    if (it != _primTypeCache.end()) return it->second;
    if (!_synthCtx) _synthCtx = std::make_shared<CodeGenContext>(std::make_shared<std::string>("<generic>"));
    auto node = std::make_shared<IdentifierNode>(*_synthCtx, std::make_shared<std::string>(""), builtInVal);
    node->synthesized = true;   // emitter-built: not source text (see ASTNode::synthesized)
    _primTypeCache[builtInVal] = node;
    return node;
}

// The concrete type node of an argument expression (null if undeterminable). Inputs:
// literals -> their builtin kind; a bare identifier -> its declared type via `localTys`; an
// explicit new/cast -> its own type; an arithmetic expr -> an operand's type.
SharedIdentifier CEmitter::exprTypeNode(SharedExpression e, std::map<std::string, SharedIdentifier>& localTys)
{
    if (!e) return nullptr;
    ASTNode* n = e.get();
    if (dynamic_cast<Int8Node*>(n))    return primTypeNode(IDENTIFIER_INT8_VAL);
    if (dynamic_cast<Int16Node*>(n))   return primTypeNode(IDENTIFIER_INT16_VAL);
    if (dynamic_cast<Int32Node*>(n))   return primTypeNode(IDENTIFIER_INT32_VAL);
    if (dynamic_cast<Int64Node*>(n))   return primTypeNode(IDENTIFIER_INT64_VAL);
    if (dynamic_cast<UInt8Node*>(n))   return primTypeNode(IDENTIFIER_UINT8_VAL);
    if (dynamic_cast<UInt16Node*>(n))  return primTypeNode(IDENTIFIER_UINT16_VAL);
    if (dynamic_cast<UInt32Node*>(n))  return primTypeNode(IDENTIFIER_UINT32_VAL);
    if (dynamic_cast<UInt64Node*>(n))  return primTypeNode(IDENTIFIER_UINT64_VAL);
    if (dynamic_cast<Float32Node*>(n)) return primTypeNode(IDENTIFIER_FLOAT32_VAL);
    if (dynamic_cast<Float64Node*>(n)) return primTypeNode(IDENTIFIER_FLOAT64_VAL);
    if (dynamic_cast<BooleanNode*>(n)) return primTypeNode(IDENTIFIER_BOOL_VAL);
    if (dynamic_cast<CharNode*>(n))    return primTypeNode(IDENTIFIER_CHAR_VAL);
    if (dynamic_cast<StringNode*>(n))  return primTypeNode(IDENTIFIER_STRING_VAL);
    if (auto* id = dynamic_cast<IdentifierNode*>(n)) {
        if (!id->value) return nullptr;
        auto it = localTys.find(*id->value);
        if (it != localTys.end()) return it->second;
        // A bound comptime param is a value of its DECLARED integral type. Answered with a
        // synthesized node (not the declaration's own), so the reference index stays clean.
        auto cs = _comptimeSubst.find(*id->value);
        return cs != _comptimeSubst.end() ? primTypeNode(cs->second.kind) : nullptr;
    }
    if (auto* oc = dynamic_cast<ObjectCreationNode*>(n)) return oc->type;
    if (auto* c  = dynamic_cast<CastNode*>(n))           return c->type;
    if (auto* b  = dynamic_cast<BinaryExpressionNode*>(n)) {
        SharedIdentifier l = exprTypeNode(b->LHS, localTys);
        return l ? l : exprTypeNode(b->RHS, localTys);
    }
    // `-5.0` is a unary minus over a literal, not a literal, so without this a NEGATED constant could not
    // bind a type parameter — `abs(x: -5.0)` failed to infer while `abs(x: 5.0)` succeeded. The operand
    // carries the type for every prefix operator kama has (`-`, `+`, `!`, `~`).
    if (auto* u  = dynamic_cast<SimpleUnaryExpressionNode*>(n)) return exprTypeNode(u->expression, localTys);
    // `give x` / `copy x` is the VALUE of `x` with an ownership marker on it, and a `string`/collection by
    // value MUST carry one — so without this arm an owning argument to a by-value generic parameter was
    // uninferable (`ident(x: copy m)`: "not a literal or a locally-typed value") while the turbofish worked.
    if (auto* h  = dynamic_cast<HandoffNode*>(n)) return exprTypeNode(h->value, localTys);
    // A call's type is its callee's declared return type, which makes a NESTED call inferable
    // (`log(x: exp(x: 1.0))`). Only for a non-generic callee: a generic one returns its own `T`, which is
    // exactly the thing not yet known here, so it is left to the "bind it to a local" rule.
    if (auto* iv = dynamic_cast<InvocationNode*>(n)) {
        // A DOT-ON-TYPE ctor call (`StringWriter.make()`) types as the type it constructs — or as the
        // ctor's declared `Result<…>` when it is fallible. Checked before the method-call arm because the
        // receiver here is a TYPE, not a value, so `mintReturnTypeNode` finds no receiver type and gives
        // up: `f(to: StringWriter.make())` reported "not a literal or a locally-typed value" and demanded
        // `StringWriter w = StringWriter.make(); f(to: give w);` — a named local for a value used once.
        // Construction is the ONLY way a type is made in kama, so this is the shape a generic sink
        // parameter meets constantly (`serializeKbinPositionalStream<W: Writer>(v:, to:)`).
        if (auto* ma = dynamic_cast<MemberAccessNode*>(iv->expression.get())) {
            std::string dt;
            if (ma->identifier && ma->identifier->value && isTypeReceiver(ma, dt) && _classes.count(dt)) {
                if (CtorInfo* ct = _classes[dt].ctorByName(*ma->identifier->value))
                    return ct->returnType ? ct->returnType : synthId(dt);
            }
            // ...and on a generic TEMPLATE, the instance its own arguments pin (`Box.of(v: x)` is a
            // `Box<int32>`), so a generic callee can infer from it: `take(b: Box.of(v: x))`.
            if (SharedIdentifier inst = inferDotCtorInstance(iv, localTys)) return inst;
        }
        // A METHOD call on a typed receiver: the method's declared return type, with the host's generic
        // arguments substituted — `xs.length()` on a `DynamicArray<int32>` is an `isize`. mintReturnTypeNode
        // already answers this for a `borrow` alias; a generic call's argument is the same question
        // (`pick(a: 0, b: xs.length())` used to be "not a literal or a locally-typed value").
        if (iv->expression) return mintReturnTypeNode(e, localTys);
        if (iv->identifier && iv->identifier->value && !iv->expression) {
            std::string k = resolveFunc(*iv->identifier->value, iv->identifier->qualifier);
            if (!_generics.count(k)) {
                auto fit = _funcs.find(k);
                if (fit != _funcs.end() && fit->second.node && fit->second.node->returnType)
                    return fit->second.node->returnType;
            }
        }
        return nullptr;
    }
    return nullptr;
}

// One intrinsic instance's method return type, or null. Split out only so mintReturnTypeNode's intrinsic
// fallback stays a single line next to the two lookups it parallels.
SharedIdentifier CEmitter::findMethodReturn(ClassInfo& ci, const std::string& member)
{
    MethodInfo* mi = findMethod(&ci, member, nullptr);
    return (mi && mi->returnType) ? mi->returnType : SharedIdentifier();
}

// The type a `borrow` alias names: the mint's declared return type, with the HOST's generic arguments
// substituted in (`DynamicArray<int32>.view()` -> `View<int32>`).
//
// An alias is the one local in the language with no written type, so it is the one local `localTys` cannot
// learn from the declaration — and `localTys` is the table generic inference reads. Without this,
// `sort(items: v)` on an alias could not infer `T` and demanded a turbofish, while the identical call on a
// plain view local did not. Exactly the `foreach`-binding gap recorded one arm below in
// `scanStmtForGenerics`, and invisible for the same reason: the only `borrow` fixture passed its alias to a
// non-generic function and to an explicitly-turbofished one.
SharedIdentifier CEmitter::mintReturnTypeNode(SharedExpression host,
                                              std::map<std::string, SharedIdentifier>& localTys)
{
    auto* inv = dynamic_cast<InvocationNode*>(host.get());
    if (!inv || !inv->expression) return nullptr;
    auto* ma = dynamic_cast<MemberAccessNode*>(inv->expression.get());
    if (!ma || !ma->identifier || !ma->identifier->value || !ma->expression) return nullptr;
    SharedIdentifier recvTy = exprTypeNode(ma->expression, localTys);
    if (!recvTy || !recvTy->value) return nullptr;
    const std::string& mint = *ma->identifier->value;

    // The template shape carries the mint's declared return type; the concrete class does too, when the
    // host is not generic (a user's `Buf.span()`).
    // `resolveUserName`, not `qualify` — the host is usually an IMPORTED type, and `qualify` answers with
    // this file's private mangle (`_F<file>__DynamicArray`), which matches nothing.
    const std::string base = resolveUserName(*recvTy->value, recvTy->qualifier, nullptr);
    ClassInfo* shape = nullptr;
    const std::vector<std::string>* tps = nullptr;
    auto g = _genericTypes.find(base);
    if (g != _genericTypes.end()) {
        shape = &g->second;
        auto tp = _genericTypeParams.find(base);
        if (tp != _genericTypeParams.end()) tps = &tp->second;
    } else {
        auto c = _classes.find(base);
        if (c != _classes.end()) shape = &c->second;
    }
    // An INTRINSIC collection resolves by neither route: `InlineArray<int32,4>` has no template in
    // `_genericTypes` and no `_classes` entry under the bare name — only the monomorphized instance
    // `InlineArray_int32_4` exists, because registerFixed synthesizes the instance directly. Its C type IS
    // that instance name, so ask for it. Without this an `InlineArray` alias came out of `borrow` untyped
    // and `sortUnstable(items: v)` could not infer `T`, while the same call on a `FixedArray` alias could.
    if (!shape) {
        auto c = _classes.find(cType(recvTy));
        if (c != _classes.end() && c->second.isIntrinsicColl) return findMethodReturn(c->second, mint);
    }
    if (!shape) return nullptr;
    MethodInfo* mi = findMethod(shape, mint, nullptr);
    if (!mi || !mi->returnType) return nullptr;
    if (!tps || !recvTy->genericArgs) return mi->returnType;   // non-generic host — nothing to substitute

    std::map<std::string, SharedIdentifier> saved = _typeSubst;
    _typeSubst.clear();
    for (size_t i = 0; i < tps->size() && i < recvTy->genericArgs->size(); ++i)
        _typeSubst[(*tps)[i]] = (*recvTy->genericArgs)[i];
    SharedIdentifier out = deepSubstType(mi->returnType);
    _typeSubst = saved;
    // The return type is spelled as the HOST's file spells it — `ConstView<T>` in dynamic_array.kama — and
    // the node goes back to a CALLER that may never have imported that name: `id(x: xs.view().length())`
    // in a file importing only `View` resolved `ConstView` to nothing and could not infer `T`. Re-spell
    // it absolutely under the host's own context (the same independence from the calling file's imports
    // registerFixedViews buys with viewQualifiedNode), so the next lookup needs no import.
    if (out && out->value) {
        NsCtx savedCtx = _nsCtx;
        auto cx = _genericTypeCtx.find(base);
        if (cx != _genericTypeCtx.end()) _nsCtx = cx->second;
        const std::string rk = resolveUserName(*out->value, out->qualifier, nullptr);
        _nsCtx = savedCtx;
        if (!rk.empty() && (_genericTypes.count(rk) || _classes.count(rk))) {
            SharedIdentifier q = viewQualifiedNode(rk);
            q->genericArgs = out->genericArgs;
            q->genericArg  = out->genericArg;
            out = q;
        }
    }
    return out;
}

// A1: infer the concrete generic-variant instance of a value-producing variant constructor used as a `match`
// SUBJECT — `match (Optional::Some(x))` -> the `Optional<int32>` instance node. The subject parses as an
// InvocationNode whose callee is a `Type::Variant` qualified identifier (no receiver). Each BARE-type-param
// payload field is bound by name from its argument's inferred type (via `exprTypeNode(arg, localTys)`); ALL
// template params must bind (so `Result::Ok(42)` — E unbound — returns null and falls back to the "requires an
// enum subject" error). `reg=true` (discovery) registers the instance so its C struct emits; `reg=false`
// (emit) just rebuilds the node to recover the mangled name. Returns null for anything that isn't inferable.
// Resolve the tagged-union class of a value-producing `match` SUBJECT (discovery time). An inline variant
// ctor resolves directly; a variant-producing ternary or a nested `match` resolves from its first branch/arm
// whose value is (recursively) an inline variant ctor — both branches/arms share the type. Instances are
// registered as a side effect (via inferInlineVariantInstance's reg=true). "" if the subject isn't this shape.
std::string CEmitter::inferMatchSubjInst(SharedExpression subj)
{
    if (!subj) return "";
    if (auto* iv = dynamic_cast<InvocationNode*>(subj.get())) {
        SharedIdentifier inst = inferInlineVariantInstance(iv, _scanLocalTys, /*reg=*/true);
        return inst ? cType(inst) : "";
    }
    if (auto* tx = dynamic_cast<TernaryExpressionNode*>(subj.get())) {
        std::string l = inferMatchSubjInst(tx->LHS);
        return !l.empty() ? l : inferMatchSubjInst(tx->RHS);
    }
    if (auto* mx = dynamic_cast<MatchNode*>(subj.get())) {
        if (mx->arms)
            for (auto& a : *mx->arms) if (a) {
                SharedExpression v = a->body;                          // single-expression arm
                if (!v && a->block && a->block->statements)            // block arm: its terminal `:= expr;`
                    for (auto& st : *a->block->statements)
                        if (auto* av = dynamic_cast<ArmValueNode*>(st.get())) v = av->value;
                std::string r = inferMatchSubjInst(v);
                if (!r.empty()) return r;
            }
    }
    return "";
}

SharedIdentifier CEmitter::inferInlineVariantInstance(InvocationNode* inv,
                                                      std::map<std::string, SharedIdentifier>& localTys, bool reg)
{
    if (!inv || !inv->identifier || inv->expression) return nullptr;   // a `recv.method(...)` is not this
    SharedStringList qual = inv->identifier->qualifier;
    if (!qual || qual->empty() || !inv->identifier->value) return nullptr;   // must be `Type::Variant(...)`
    std::string variantName = *inv->identifier->value;

    // The qualifier's last segment is the TYPE; earlier segments are its namespace.
    auto tq = std::make_shared<StringList>();
    for (size_t i = 0; i + 1 < qual->size(); ++i) tq->push_back((*qual)[i]);
    std::string tmpl = resolveUserName(*qual->back(), tq);
    if (!_genericTypes.count(tmpl) || !_genericTypes[tmpl].isVariant) return nullptr;   // (the template lives here, NOT _classes)
    const std::vector<std::string>& params = _genericTypeParams[tmpl];
    if (params.empty()) return nullptr;

    const VariantCase* vc = nullptr;
    for (auto& v : _genericTypes[tmpl].variants) if (v.name == variantName) { vc = &v; break; }
    if (!vc) return nullptr;

    std::map<std::string, SharedExpression> byName;
    if (inv->args) for (auto& a : *inv->args) if (a && a->name && a->name->value) byName[*a->name->value] = a->expression;

    std::map<std::string, SharedIdentifier> bind;
    for (auto& f : vc->payload) {
        if (!f.type || !f.type->value || f.type->genericArg) continue;   // only a BARE type-param field infers
        bool isParam = false;
        for (auto& p : params) if (p == *f.type->value) { isParam = true; break; }
        if (!isParam) continue;
        auto ai = byName.find(f.name);
        if (ai == byName.end()) return nullptr;
        SharedIdentifier at = exprTypeNode(ai->second, localTys);
        if (!isConcreteTypeArg(at)) return nullptr;                      // a variable with no discovery-time type, etc.
        bind[*f.type->value] = at;
    }
    // Require EVERY template param bound — a return-only param (Result's E from an Ok(...)) can't be inferred.
    SharedIdentifierList argList = std::make_shared<IdentifierList>();
    for (auto& p : params) {
        auto b = bind.find(p);
        if (b == bind.end()) return nullptr;
        argList->push_back(b->second);
    }

    if (reg) registerGenericTypeInst(tmpl, argList);   // ONLY at discovery — creates _classes[mangled] so the struct emits

    // Build the instance node — BOTH genericArg (singular; mangling reads it) AND genericArgs (list).
    if (!_synthCtx) _synthCtx = std::make_shared<CodeGenContext>(std::make_shared<std::string>("<a1>"));
    auto inst = synthId(*qual->back());
    if (!tq->empty()) inst->qualifier = tq;
    inst->genericArg  = argList->front();
    inst->genericArgs = argList;
    return inst;
}

// The instance a dot-on-type ctor call on a generic TEMPLATE constructs, pinned by the ctor's OWN arguments:
// `Box.of(v: 3)` binds `T` from `v`, exactly as a generic function binds from its arguments. Each ctor
// parameter declared as a bare type parameter binds from its argument's type; an unbound trailing parameter
// takes its default, and any other unbound one means the call cannot be inferred (null) — the caller then
// says so ("give the type arguments"). The instance is REGISTERED on the way out, which is a dedup no-op for
// every call after the discovery pass that first reaches it (KR-15).
SharedIdentifier CEmitter::inferDotCtorInstance(InvocationNode* inv, std::map<std::string, SharedIdentifier>& localTys)
{
    auto* ma = inv ? dynamic_cast<MemberAccessNode*>(inv->expression.get()) : nullptr;
    auto* rid = ma ? dynamic_cast<IdentifierNode*>(ma->expression.get()) : nullptr;
    if (!rid || !rid->value || rid->genericArgs || !ma->identifier || !ma->identifier->value
        || ma->identifier->genericArgs || localTys.count(*rid->value)) return nullptr;
    const std::string tmpl = resolveUserName(*rid->value, rid->qualifier);
    auto gt = _genericTypes.find(tmpl);
    if (gt == _genericTypes.end() || gt->second.isVariant || _classes.count(tmpl)) return nullptr;
    auto mit = gt->second.methods.find(*ma->identifier->value);
    if (mit == gt->second.methods.end() || !mit->second.isCtor || !mit->second.node) return nullptr;
    auto* md = dynamic_cast<ClassMethodDeclarationNode*>(mit->second.node);
    if (!md || !md->params) return nullptr;
    const std::vector<std::string>& params = _genericTypeParams[tmpl];
    if (params.empty()) return nullptr;

    std::map<std::string, SharedExpression> byName;
    if (inv->args) for (auto& a : *inv->args) if (a && a->name && a->name->value) byName[*a->name->value] = a->expression;
    std::map<std::string, SharedIdentifier> bind;
    for (auto& p : *md->params) {
        if (!p || !p->type || !p->type->value || p->type->genericArgs || !p->identifier || !p->identifier->value) continue;
        if (std::find(params.begin(), params.end(), *p->type->value) == params.end()) continue;
        auto ai = byName.find(*p->identifier->value);
        if (ai == byName.end()) return nullptr;
        SharedIdentifier at = exprTypeNode(ai->second, localTys);
        if (!isConcreteTypeArg(at)) return nullptr;
        auto prev = bind.find(*p->type->value);
        if (prev != bind.end() && cType(prev->second) != cType(at)) return nullptr;   // two arguments disagree
        bind[*p->type->value] = at;
    }
    auto dit = _genericTypeDefaults.find(tmpl);
    SharedIdentifierList argList = std::make_shared<IdentifierList>();
    for (size_t i = 0; i < params.size(); ++i) {
        auto b = bind.find(params[i]);
        if (b != bind.end()) { argList->push_back(b->second); continue; }
        bool defaulted = dit != _genericTypeDefaults.end() && i < dit->second.size() && dit->second[i];
        if (!defaulted) return nullptr;
        break;   // a defaulted parameter and everything after it: registration fills the defaults
    }
    if (argList->empty()) return nullptr;
    if (!_discoveryClosed) registerGenericTypeInst(tmpl, argList);
    else if (!_classes.count(genericTypeMangle(tmpl, argList))) return nullptr;   // never discovered: say so, not clang
    if (!_synthCtx) _synthCtx = std::make_shared<CodeGenContext>(std::make_shared<std::string>("<a1>"));
    auto inst = synthId(*rid->value);
    if (rid->qualifier && !rid->qualifier->empty()) inst->qualifier = rid->qualifier;
    inst->genericArg  = argList->front();
    inst->genericArgs = argList;
    return inst;
}

// A type node usable as a generic type argument: a primitive, or a known
// class/enum/contract. A bare type-parameter (its name resolves to none of these) and a
// collection/smart-pointer type argument (a `List<…>` etc.) are NOT concrete here.
bool CEmitter::isConcreteTypeArg(SharedIdentifier t)
{
    if (!t) return false;
    if (t->builtInVal != IDENTIFIER_NONE_VAL) return true;   // primitive
    // A RAW POINTER is concrete, and it is neither a primitive nor a registered type — it is one machine
    // word whatever it points at, which is why nothing ever registers a class for it. Without this,
    // `T = UnsafePtr` failed EVERY generic inference over a pointer element: declaring an
    // `InlineArray<UnsafePtr>#(1)` was enough to fail the build, because `InlineArray` materialises its
    // `view()` for every instantiation and `View<T>.swap` calls the generic `relocate<T>`. The typed form
    // is concrete exactly when its ELEMENT is, so `UnsafePtr<T>` inside a template stays parameterized.
    if (isRawPtrName(t))
        return !t->genericArg || isConcreteTypeArg(t->genericArg);
    // A generic type argument (`DynamicArray<int32>`, `Shared<Node>`) is concrete exactly when it has
    // already been REGISTERED as an instance — then it names a real struct and can be mangled into an
    // instantiation key. An unregistered one is either still parameterized (an argument that is itself a
    // bare type-param) or a type this program never builds, and neither can be specialized against.
    if (t->genericArg) {
        std::string m = mangleElem(t);
        return _classes.count(m) || _genericTypeInsts.count(m) || _collections.count(m);
    }
    if (!t->value) return false;
    std::string m = resolveUserName(*t->value, t->qualifier);
    return _classes.count(m) || _enums.count(m) || _interfaces.count(m);
}

// Unify a generic call's arguments against the template's parameters -> a deduped instantiation.
// Each parameter whose declared type is a bare type-param binds it to the argument's concrete
// type; a second, conflicting binding, an unresolvable argument, or a return-only (unbound)
// type parameter each produce a clean diagnostic. Runs with _typeSubst empty (concrete mangles).
// One argument's contribution to a generic call's binding: its (substituted) type must be concrete, and
// must agree with what `T` is already bound to. Split out of inferGenericInst so the same rule serves both
// passes — the typed arguments first, the deferred literals after.
bool CEmitter::bindGenericArg(const std::string& pty, const std::string& pname, SharedExpression arg,
                              std::map<std::string, SharedIdentifier>& localTys,
                              std::map<std::string, SharedIdentifier>& bind, int line)
{
    // `_typeSubst` is bound when this runs from registerInstGenerics — i.e. the call sits inside a
    // generic TYPE's member, being re-walked for one instantiation. Substituting first is what lets
    // an argument declared with the ENCLOSING template's parameter (`V`) read as the concrete type.
    SharedIdentifier at = deepSubstType(exprTypeNode(arg, localTys));
    // An argument typed by the ENCLOSING template's own parameter (`idA(x: x)` inside `fn T idB<T>(T x)`) is
    // not a failed inference: this is the template's own walk, where `T` is still open, and each
    // instantiation re-walks the body with `T` bound (registerInstGenerics) and infers there. Refusing here
    // is what made a generic calling a generic need a turbofish the argument already implied (KR-21 a).
    if (!isConcreteTypeArg(at) && at && argCarriesUnboundParam(at)) { _inferSawOpenArg = true; return false; }
    if (!isConcreteTypeArg(at)) {
        unsupported(("cannot infer generic type parameter '" + pty + "' — argument '" + pname +
                     "' is not a literal or a locally-typed value").c_str(), line);
        return false;
    }
    auto b = bind.find(pty);
    if (b != bind.end() && mangleElem(b->second) != mangleElem(at)) {
        unsupported(("cannot unify type parameter '" + pty + "' (" + mangleElem(b->second) +
                     " vs " + mangleElem(at) + ")").c_str(), line);
        return false;
    }
    bind[pty] = at;
    return true;
}

bool CEmitter::inferGenericInst(FunctionDeclarationNode* tmpl, const std::string& key, SharedArgumentList args,
                                std::map<std::string, SharedIdentifier>& localTys, int line, GenericInst& out,
                                const std::map<std::string, SharedIdentifier>* seed)
{
    std::map<std::string, SharedExpression> byName;
    if (args) for (auto& a : *args) if (a && a->name && a->name->value) byName[*a->name->value] = a->expression;

    std::set<std::string> tps;
    for (auto& tp : *tmpl->typeParams) if (tp) tps.insert(*tp);
    std::set<std::string> cps;
    if (tmpl->comptimeParams) for (auto& cp : *tmpl->comptimeParams) if (cp) cps.insert(*cp);

    // synthesize a comptime ARGUMENT node carrying an integer value (so a bound const param
    // travels through mangleElem / GenericInst::typeArgs uniformly with a type argument).
    auto constArgNode = [&](int64_t v) -> SharedIdentifier {
        if (!_synthCtx) _synthCtx = std::make_shared<CodeGenContext>(std::make_shared<std::string>("<synth>"));
        auto id = std::make_shared<IdentifierNode>(*_synthCtx, SharedString());
        id->synthesized = true;   // emitter-built: not source text (see ASTNode::synthesized)
        id->constArgValue = std::make_shared<Int64Node>(*_synthCtx, v);
        return id;
    };

    // Pre-bound from what the use site wrote — `headOf::<int32>(a: v)` fixes `T` here and leaves `N` to
    // the unification below. A seeded parameter is simply already in `bind`, so every later step (the
    // conflict check, the "cannot infer" sweep, bounds, mangling) treats it exactly like an inferred one.
    std::map<std::string, SharedIdentifier> bind;
    struct DeferredLit { std::string pty, pname; SharedExpression expr; };
    std::vector<DeferredLit> deferred;   // unsuffixed literals, bound after every typed argument
    if (seed) bind = *seed;
    _inferSawOpenArg = false;

    // Structurally unify a parameter's declared type against the argument's concrete type, binding
    // every type parameter that appears anywhere inside it — `View<T>`, `DynamicArray<T>`,
    // `Optional<T>`, `Pair<K, V>`, and nestings of those. Without this only a BARE `T x` parameter
    // was inferable, so every call that passed a container had to carry a turbofish.
    // BEST-EFFORT by design: a shape that doesn't line up (different type, different arity) binds
    // nothing and falls through to the "pass it explicitly with turbofish" diagnostic below, so this
    // only ever WIDENS what compiles — it never invents a new hard error. The one thing it does
    // reject is a genuine conflict: one parameter unified against two different types.
    std::function<bool(const SharedIdentifier&, const SharedIdentifier&)> unify =
        [&](const SharedIdentifier& pt, const SharedIdentifier& at) -> bool {
        if (!pt || !pt->value || !at || !at->value) return true;
        if (!pt->genericArg && tps.count(*pt->value)) {          // a bare type-param position — bind it
            if (!isConcreteTypeArg(at)) { if (argCarriesUnboundParam(at)) _inferSawOpenArg = true; return true; }
            auto b = bind.find(*pt->value);
            if (b != bind.end() && mangleElem(b->second) != mangleElem(at)) {
                unsupported(("cannot unify type parameter '" + *pt->value + "' (" + mangleElem(b->second) +
                             " vs " + mangleElem(at) + ")").c_str(), line);
                return false;
            }
            bind[*pt->value] = at;
            return true;
        }
        // `ConstView<T>` parameter, `View<T>` argument: the argument sink narrows implicitly, so the shapes DO
        // line up — bind `T` through the pair, or every read-only algorithm (`binarySearch`, `isSorted`)
        // would demand a turbofish from exactly the caller it was written for. The REVERSE pair binds too:
        // a `ConstView<T>` handed to `sortUnstable(View<T>)` is wrong, and it is the identity rule at the
        // sink that says why ("read-only; it does not widen") — "cannot infer T" would point away from it.
        const bool viewPair = ((*pt->value == "ConstView" && *at->value == "View")
                            || (*pt->value == "View" && *at->value == "ConstView"))
                          && !constViewTemplateKey().empty() && !viewTemplateKey().empty();
        if ((*pt->value != *at->value && !viewPair) || !pt->genericArgs || !at->genericArgs
            || pt->genericArgs->size() != at->genericArgs->size()) return true;   // shapes differ — bind nothing
        for (size_t i = 0; i < pt->genericArgs->size(); ++i)
            if (!unify((*pt->genericArgs)[i], (*at->genericArgs)[i])) return false;
        return true;
    };

    if (tmpl->parameters) for (auto& p : *tmpl->parameters) {
        if (!p || !p->type || !p->type->value) continue;
        const std::string& pty = *p->type->value;
        // An `InlineArray<ElemT, K>` or `Simd<ElemT, K>` parameter — infer any type-param element AND the
        // comptime size K from the argument's concrete type. This is the comptime half of inference, and
        // the two intrinsics share it because they share the shape: two arguments, the second a value.
        // Without this a generic function over either one cannot be called at all — the size parameter has
        // nowhere else to come from, since it appears only inside the argument's type.
        if ((pty == "InlineArray" || pty == "Simd") && p->type->genericArgs && p->type->genericArgs->size() == 2) {
            std::string pname = (p->identifier && p->identifier->value) ? *p->identifier->value : "";
            auto ai = byName.find(pname);
            if (ai == byName.end()) continue;   // missing arg — emitReorderedCall reports it precisely
            SharedIdentifier at = deepSubstType(exprTypeNode(ai->second, localTys));
            if (!at || !at->value || *at->value != pty || !at->genericArgs || at->genericArgs->size() != 2) {
                unsupported(("cannot infer the generic parameters of `" + pty + "<…>` — argument '" + pname +
                             "' is not a `" + pty + "<…>` value").c_str(), line);
                return false;
            }
            SharedIdentifier pElem = (*p->type->genericArgs)[0], pN = (*p->type->genericArgs)[1];
            SharedIdentifier aElem = (*at->genericArgs)[0],       aN = (*at->genericArgs)[1];
            // element type parameter (`Fixed<T, N>` — bind T), if it is a bare type-param
            if (pElem && pElem->value && !pElem->genericArg && tps.count(*pElem->value)) {
                if (!isConcreteTypeArg(aElem)) {
                    unsupported(("cannot infer type parameter '" + *pElem->value + "' from argument '" + pname + "'").c_str(), line);
                    return false;
                }
                auto b = bind.find(*pElem->value);
                if (b != bind.end() && mangleElem(b->second) != mangleElem(aElem)) {
                    unsupported(("cannot unify type parameter '" + *pElem->value + "'").c_str(), line);
                    return false;
                }
                bind[*pElem->value] = aElem;
            }
            // const size parameter (`Fixed<T, N>` — bind N to the argument's size)
            if (pN && pN->value && cps.count(*pN->value)) {
                int64_t v;
                if (!constArgN(aN, v)) {
                    unsupported(("cannot infer comptime parameter '" + *pN->value + "' — argument '" + pname +
                                 "' has no statically-known size").c_str(), line);
                    return false;
                }
                auto b = bind.find(*pN->value);
                if (b != bind.end()) { int64_t pv; if (constArgN(b->second, pv) && pv != v) {
                    unsupported(("cannot unify comptime parameter '" + *pN->value + "' (" + std::to_string(pv) +
                                 " vs " + std::to_string(v) + ")").c_str(), line);
                    return false; } }
                bind[*pN->value] = constArgNode(v);
            }
            continue;
        }
        // `View<T>` / `DynamicArray<T>` / … — a generic type whose ARGUMENTS mention a type param.
        // (`InlineArray<T>#(N)` never reaches here; its branch above binds the const size too.)
        if (p->type->genericArg) {
            std::string pname = (p->identifier && p->identifier->value) ? *p->identifier->value : "";
            auto ai = byName.find(pname);
            if (ai == byName.end()) continue;   // missing arg — emitReorderedCall reports it precisely
            if (!unify(p->type, deepSubstType(exprTypeNode(ai->second, localTys)))) return false;
            continue;
        }
        if (!tps.count(pty)) continue;                          // a concrete type — nothing to bind
        std::string pname = (p->identifier && p->identifier->value) ? *p->identifier->value : "";
        auto ai = byName.find(pname);
        if (ai == byName.end()) continue;   // missing arg — emitReorderedCall reports it precisely
        // An unsuffixed literal is DEFERRED: `range(rng: g, lo: 0, hi: n)` with `isize n` used to fail
        // with "cannot unify T (int32 vs isize)" because the literal, first in parameter order, bound `T`
        // as int32 before the typed sibling was seen. The typed arguments bind first; the literal is
        // then retyped to what they chose (the "literal is typed by its destination" rule the isize
        // campaign taught ternary arms, mixed binaries and `match` arms), and range-checked against it.
        if (isDeferrableLiteral(ai->second.get())) { deferred.push_back({ pty, pname, ai->second }); continue; }
        if (!bindGenericArg(pty, pname, ai->second, localTys, bind, line)) return false;
    }
    for (const DeferredLit& d : deferred) {
        auto b = bind.find(d.pty);
        if (b != bind.end()) {
            // `T` is bound by a typed sibling: retype the literal to it when that is a numeric widening
            // the hand-off rule admits (an integer literal into any numeric type, a float literal into a
            // float type — rejectNumericConversion's D2a exemption), with the fits check the same
            // hand-off would run. Anything else — `string` bound and a literal `3` — is the ordinary
            // conflict, reported exactly as before.
            const std::string dst = cType(b->second);
            const bool dstFloat = cNumFloat(dst);
            int64_t lo, hi;
            // primIntRangeC answers only the widths a fold can overflow; the 64-bit pair and the
            // target-width pair are integers too, just ones every fold fits.
            const bool dstInt = primIntRangeC(dst, lo, hi) || cNumTargetWidth(dst)
                             || dst == "int64_t" || dst == "uint64_t";
            const bool litFloat = cNumFloat(typeOfExpr(d.expr));
            if (dstFloat || (dstInt && !litFloat)) {
                if (dstInt) {
                    int64_t v;
                    if (constValue(d.expr, v) && constOutOfRange(dst, v, typeOfExpr(d.expr))) {
                        rejectConstOutOfRange(dst, d.expr, ("argument `" + d.pname + "`").c_str(), false, line);
                        return false;
                    }
                }
                continue;
            }
        }
        if (!bindGenericArg(d.pty, d.pname, d.expr, localTys, bind, line)) return false;
    }

    for (auto& tp : *tmpl->typeParams) {
        if (tp && !bind.count(*tp)) {
            if (_inferSawOpenArg) return false;   // the template's own walk — see bindGenericArg
            // A comptime parameter is a VALUE, and values are written in their own group — pointing the
            // reader at a turbofish would name brackets that can no longer hold one.
            const bool isValue = cps.count(*tp) != 0;
            unsupported(((isValue ? "cannot infer compile-time parameter '" : "cannot infer type parameter '")
                         + *tp + "' from the call arguments — pass it explicitly"
                         + (isValue ? ", e.g. `f(...)#(4)`" : " with turbofish, e.g. `f::<T>(...)`")).c_str(), line);
            return false;
        }
    }

    // each inferred concrete type must satisfy its parameter's contract bounds (points at this call).
    bool boundsOk = true;
    if (tmpl->typeBounds)
        for (size_t i = 0; i < tmpl->typeParams->size() && i < tmpl->typeBounds->size(); ++i)
            if ((*tmpl->typeParams)[i])
                if (!checkBounds(*(*tmpl->typeParams)[i], bind[*(*tmpl->typeParams)[i]], (*tmpl->typeBounds)[i], line, key, bind))
                    boundsOk = false;

    out.templateKey = key;
    out.typeArgs.clear();
    std::string mangled = key;
    for (auto& tp : *tmpl->typeParams) {
        SharedIdentifier a = absolutizeType(bind[*tp]);   // use-site mangle — see explicitGenericInst
        out.typeArgs.push_back(a);
        mangled += "__" + mangleElem(a);
    }
    out.mangledName = mangled;
    if (!boundsOk) _boundFailedInsts.insert(mangled);   // prototype only — see emitGenericInst
    return true;
}

// Turbofish `f::<A, B>(…)` and/or compile-time arguments `f(…)#(4)` — bind each parameter from what the
// use site wrote, in order (no inference). The concrete args are already resolved nodes from the grammar;
// arity is checked PER GROUP and contract bounds after.
//
// The two groups are independent, and either may be omitted when it is inferable — that is the whole
// point of separating them (`headOf::<int32>(a: v)` writes the type and lets `N` come from the argument;
// `sumN(a: w)#(2)` does the reverse). An omitted group is NOT an arity error: this seeds what was written
// and hands the rest to inferGenericInst. `typeParams` is types-then-values (splitFnParams guarantees the
// order), so a group maps onto a contiguous run of slots and no index bookkeeping is needed beyond the
// split point. `nTypeArgs < 0` marks a node the emitter synthesized, which has no groups and is complete
// by construction.
bool CEmitter::explicitGenericInst(FunctionDeclarationNode* tmpl, const std::string& key,
                                   SharedIdentifierList typeArgs, int nTypeArgs, SharedArgumentList callArgs,
                                   std::map<std::string, SharedIdentifier>* localTys, int line, GenericInst& out)
{
    size_t np = tmpl->typeParams ? tmpl->typeParams->size() : 0;
    size_t na = typeArgs ? typeArgs->size() : 0;
    size_t nVals = 0;
    if (tmpl->constTypes) for (auto& ct : *tmpl->constTypes) if (ct) ++nVals;
    const size_t nTypes = np - nVals;

    if (nTypeArgs >= 0 && na != np) {
        const size_t written  = (size_t)nTypeArgs;
        const size_t writtenV = na - written;
        if (written != 0 && written != nTypes) {
            unsupported(("generic function '" + key + "' takes " + std::to_string(nTypes) +
                         " type argument(s), but " + std::to_string(written) + " were given in `::<…>`").c_str(), line);
            return false;
        }
        if (writtenV != 0 && writtenV != nVals) {
            unsupported(("generic function '" + key + "' takes " + std::to_string(nVals) +
                         " compile-time argument(s), but " + std::to_string(writtenV) +
                         " were given in `#(…)`").c_str(), line);
            return false;
        }
        // One group is missing and inferable. Seed the written slots and let inference finish.
        std::map<std::string, SharedIdentifier> seed;
        for (size_t i = 0; i < written && i < nTypes; ++i)
            if ((*tmpl->typeParams)[i]) seed[*(*tmpl->typeParams)[i]] = absolutizeType(deepSubstType((*typeArgs)[i]));
        for (size_t j = 0; j < writtenV && nTypes + j < np; ++j)
            if ((*tmpl->typeParams)[nTypes + j])
                seed[*(*tmpl->typeParams)[nTypes + j]] = absolutizeType(deepSubstType((*typeArgs)[written + j]));
        // Same deferral as the complete path below: an argument still carrying an unbound parameter means
        // this is the pre-instantiation scan of a template body, not a real call.
        for (auto& s : seed) if (argCarriesUnboundParam(s.second)) return false;
        std::map<std::string, SharedIdentifier> noLocals;
        return inferGenericInst(tmpl, key, callArgs, localTys ? *localTys : noLocals, line, out, &seed);
    }
    if (na != np) {
        unsupported(("generic function '" + key + "' takes " + std::to_string(np) + " type argument(s), but "
                     + std::to_string(na) + " were given in `::<…>`").c_str(), line);
        return false;
    }
    // Resolve each arg through the ACTIVE substitution first, then absolutize it to its use-site mangled
    // name so it resolves context-free when the instance is later emitted under the TEMPLATE's home
    // namespace (a `tryParse::<Point>` in module A must carry `Point`'s home mangle, not resolve `Point`
    // against json's scope). `_callInst` + `_genericInsts` both key off that name.
    //
    // The deepSubstType is what registerGenericTypeInst has always done and this path was missing. A
    // turbofish written INSIDE another generic — `lessAt::<T, Natural<T>>` in a `<T>` function — stored
    // the raw `T` as the instance's type argument; zipping that back into `_typeSubst` bound `T` to
    // itself, and `mangleElem` then recursed on its own result until the stack died. A compiler crash,
    // not a diagnostic.
    std::vector<SharedIdentifier> concrete;
    for (size_t i = 0; i < np; ++i) concrete.push_back(absolutizeType(deepSubstType((*typeArgs)[i])));

    // Defer while any argument still carries an unbound parameter: that means this is the scan of a
    // generic function's body BEFORE instantiation, where the enclosing `T` has no binding yet. The real
    // instance registers at monomorphization, with concrete args. Both callers treat `false` as "nothing
    // to register" rather than an error, which is exactly the intent. Mirrors the same skip in
    // registerGenericTypeInst.
    for (auto& c : concrete) if (argCarriesUnboundParam(c)) return false;

    // Bounds are checked against the SUBSTITUTED argument, so the diagnostic names the real type.
    bool boundsOk = true;
    std::map<std::string, SharedIdentifier> boundBind;
    for (size_t i = 0; i < np && i < concrete.size(); ++i)
        if ((*tmpl->typeParams)[i]) boundBind[*(*tmpl->typeParams)[i]] = concrete[i];
    if (tmpl->typeBounds)
        for (size_t i = 0; i < np && i < tmpl->typeBounds->size(); ++i)
            if ((*tmpl->typeParams)[i])
                if (!checkBounds(*(*tmpl->typeParams)[i], concrete[i], (*tmpl->typeBounds)[i], line, key, boundBind))
                    boundsOk = false;
    // A user-spelled turbofish (`pick::<cchar>()`) has no declared-type site, so it reports here; the same
    // call reached while a poisoned instance's body is re-walked under substitution (`relocate::<T>` with
    // `T` bound to `cchar`) only poisons — the user's spelling was reported already, and reporting again
    // would name a library line.
    for (auto& c : concrete)
        if (containsBareCChar(c)) { boundsOk = false; if (_typeSubst.empty()) rejectBareCChar(c, "a type argument", line); }

    out.templateKey = key;
    out.typeArgs.clear();
    std::string mangled = key;
    for (size_t i = 0; i < np; ++i) {
        out.typeArgs.push_back(concrete[i]);
        mangled += "__" + mangleElem(concrete[i]);
    }
    out.mangledName = mangled;
    if (!boundsOk) _boundFailedInsts.insert(mangled);   // prototype only — see emitGenericInst
    return true;
}

void CEmitter::scanExprForGenerics(SharedExpression e, std::map<std::string, SharedIdentifier>& localTys)
{
    if (!e) return;
    ASTNode* n = e.get();
    if (auto* oc = dynamic_cast<ObjectCreationNode*>(n)) {
        if (oc->args) for (auto& a : *oc->args) if (a) scanExprForGenerics(a->expression, localTys);
    } else if (auto* c = dynamic_cast<CastNode*>(n)) {
        scanExprForGenerics(c->unaryExpression, localTys);
    } else if (auto* b = dynamic_cast<BinaryExpressionNode*>(n)) {
        scanExprForGenerics(b->LHS, localTys); scanExprForGenerics(b->RHS, localTys);
    } else if (auto* l = dynamic_cast<LogicalAndOrNode*>(n)) {
        scanExprForGenerics(l->LHS, localTys); scanExprForGenerics(l->RHS, localTys);
    } else if (auto* tn = dynamic_cast<TernaryExpressionNode*>(n)) {
        scanExprForGenerics(tn->condition, localTys); scanExprForGenerics(tn->LHS, localTys); scanExprForGenerics(tn->RHS, localTys);
    } else if (auto* as = dynamic_cast<AssignmentNode*>(n)) {
        scanExprForGenerics(as->unaryExpression, localTys); scanExprForGenerics(as->expression, localTys);
    } else if (auto* inv = dynamic_cast<InvocationNode*>(n)) {
        scanExprForGenerics(inv->expression, localTys);
        if (inv->args) for (auto& a : *inv->args) if (a) scanExprForGenerics(a->expression, localTys);
        if (inv->identifier && inv->identifier->value) {
            std::string k = resolveFunc(*inv->identifier->value, inv->identifier->qualifier);
            auto git = _generics.find(k);
            if (git != _generics.end()) {
                GenericInst gi;
                SharedIdentifierList tfArgs = inv->identifier->genericArgs;   // turbofish `f::<…>` type args
                if (tfArgs) for (auto& ta : *tfArgs) scanTypeForCollections(ta);   // register List<…>/etc. args
                bool ok = tfArgs ? explicitGenericInst(git->second, k, tfArgs, inv->identifier->nTypeArgs,
                                                       inv->args, &localTys, inv->line, gi)
                                 : inferGenericInst(git->second, k, inv->args, localTys, inv->line, gi);
                if (ok) {
                    if (!_genericInsts.count(gi.mangledName)) _genericInsts[gi.mangledName] = gi;
                    recordInstSite(gi.mangledName, gi.templateKey, gi.typeArgs, inv->line);
                    _callInst[inv][substSig()] = gi.mangledName;   // per call node, per enclosing substitution
                } else {
                    _genericInferFailed.insert(inv);   // already diagnosed here — see the emit-side rule
                }
            }
            // Turbofish on a non-generic function is rejected at emit (emitInvocation), where it is a
            // hard build error — a bare `::<…>` that resolves to no generic template.
            //
            // `Box::<int32>::tag()` — a STATIC on a generic type. Here the turbofish rides the QUALIFIER
            // (the owning type), not the callee, so register the concrete instance: without this a call
            // that is the unit's ONLY mention of `Box<int32>` never reaches `_classes` and the static
            // cannot resolve. Sibling of the two dot-on-type ctor arms below.
            SharedIdentifierList qArgs = inv->identifier->qualifierGenericArgs;
            if (qArgs && !qArgs->empty() && inv->identifier->qualifier && !inv->identifier->qualifier->empty()) {
                auto tq = std::make_shared<StringList>();
                for (size_t i = 0; i + 1 < inv->identifier->qualifier->size(); ++i)
                    tq->push_back((*inv->identifier->qualifier)[i]);
                std::string tn = resolveUserName(*inv->identifier->qualifier->back(), tq);
                if (_genericTypeParams.count(tn)) {
                    for (auto& ta : *qArgs) scanTypeForCollections(ta);
                    registerGenericTypeInst(tn, qArgs);
                }
            }
        } else if (auto* ma = dynamic_cast<MemberAccessNode*>(inv->expression.get())) {
            // Dot-on-type ctor turbofish `Type.ctor::<T>(...)` on a GENERIC type — register the concrete
            // instance so its specialized struct + ctor body get emitted (the inferred form rides the LHS
            // annotation's scan instead; the turbofish is for sites where inference can't supply the args). #M7-E3
            if (ma->identifier && ma->identifier->genericArgs) {
                if (auto* rid = dynamic_cast<IdentifierNode*>(ma->expression.get())) {
                    if (rid->value) {
                        std::string tn = resolveUserName(*rid->value, rid->qualifier);
                        if (_genericTypeParams.count(tn)) {
                            for (auto& ta : *ma->identifier->genericArgs) scanTypeForCollections(ta);
                            registerGenericTypeInst(tn, ma->identifier->genericArgs);
                        }
                    }
                }
            }
            // Dot-on-type ctor RECEIVER turbofish `Type::<T>.ctor(...)` — the CANONICAL generic-constructor
            // spelling: the enclosing type's args ride the RECEIVER type identifier (`ma->expression`), not
            // the method. Register the concrete instance so its specialized struct + ctor body emit (mirrors
            // the method-turbofish form above; the two are mutually exclusive — grammar puts genericArgs on
            // exactly one). #M8-PhaseE
            if (auto* rid = dynamic_cast<IdentifierNode*>(ma->expression.get())) {
                if (rid->value && rid->genericArgs) {
                    std::string tn = resolveUserName(*rid->value, rid->qualifier);
                    if (_genericTypeParams.count(tn)) {
                        for (auto& ta : *rid->genericArgs) scanTypeForCollections(ta);
                        registerGenericTypeInst(tn, rid->genericArgs);
                    }
                }
            }
        }
    } else if (auto* ea = dynamic_cast<ElementAccessNode*>(n)) {
        scanExprForGenerics(ea->expression, localTys);
        if (ea->expressionlist) for (auto& x : *ea->expressionlist) scanExprForGenerics(x, localTys);
    } else if (auto* ma = dynamic_cast<MemberAccessNode*>(n)) {
        scanExprForGenerics(ma->expression, localTys);
    } else if (auto* pe = dynamic_cast<PreIncrDecrNode*>(n)) {
        scanExprForGenerics(pe->expression, localTys);
    } else if (auto* po = dynamic_cast<PostIncrDecrNode*>(n)) {
        scanExprForGenerics(po->expression, localTys);
    } else if (auto* su = dynamic_cast<SimpleUnaryExpressionNode*>(n)) {
        scanExprForGenerics(su->expression, localTys);
    } else if (auto* al = dynamic_cast<ArrayLiteralNode*>(n)) {
        // The three arms below (array literal, `.as<T>()`, `match`) are the ones this walk was MISSING
        // while its sibling `scanExprForCollections` had them all along. The two functions answer the same
        // question — what must be registered before emission — over the same tree, so a shape one enters
        // and the other does not is a hole by construction, and every one of these three was: a generic
        // call written inside an array literal, inside a `.as<T>()` operand, or anywhere in a `match` was
        // never discovered. `tools/check-scan-parity.sh` now holds the two at parity.
        if (al->elements) for (auto& x : *al->elements) scanExprForGenerics(x, localTys);
        scanExprForGenerics(al->fillValue, localTys);
    } else if (auto* ad = dynamic_cast<AsDowncastNode*>(n)) {
        scanExprForGenerics(ad->operand, localTys);
    } else if (auto* mm = dynamic_cast<MatchNode*>(n)) {
        scanExprForGenerics(mm->subject, localTys);
        // A payload BINDING is a locally-typed value exactly like a declaration or a `foreach` element, and
        // this is the table `inferGenericInst` reads (through `exprTypeNode`, which consults `localTys` and
        // nothing else — never `_localTypeNodes`, which is emit-time state and must stay untouched here).
        // Without it, `case Some(value: x): f(x: x)` could not infer and the call reached emission with no
        // instantiation. The subject's class is resolved through the type node, not `exprClass`, because
        // `exprClass` reads the emit-time `_localTypes` — empty at discovery.
        //
        // Resolved IN THE SUBJECT'S INSTANCE: `Optional<int64>` stores its payload in the template's `T`,
        // so the declared field type is the bare `T` and only `deepSubstInInstance` answers `int64`. That
        // is the same resolution `emitMatchSwitch` does for `_localTypeNodes`.
        const ClassInfo* subjCi = nullptr;
        std::string subjCls;
        if (SharedIdentifier subjTy = exprTypeNode(mm->subject, localTys)) {
            subjCls = cType(subjTy);
            auto cit = _classes.find(subjCls);
            if (cit != _classes.end() && cit->second.isVariant) subjCi = &cit->second;
        }
        if (mm->arms) for (auto& a : *mm->arms) if (a) {
            // Per-arm COPY: two arms bind different names for the same slot, and an arm's bindings and
            // block locals must not leak sideways into the next arm or outward past the match.
            std::map<std::string, SharedIdentifier> armTys = localTys;
            const VariantCase* vc = nullptr;
            if (subjCi && !a->isWildcard() && a->variantName)
                for (auto& v : subjCi->variants) if (v.name == *a->variantName) { vc = &v; break; }
            if (vc && a->bindings && a->labels)
                for (size_t i = 0; i < a->bindings->size() && i < a->labels->size(); ++i) {
                    if (!(*a->bindings)[i] || !(*a->labels)[i]) continue;
                    for (auto& pf : vc->payload)
                        if (pf.name == *(*a->labels)[i]) {
                            armTys[*(*a->bindings)[i]] = deepSubstInInstance(subjCls, pf.type);
                            break;      // an unknown/duplicate label is emitMatchSwitch's to report
                        }
                }
            scanExprForGenerics(a->body, armTys);
            scanStmtForGenerics(a->block, armTys);
        }
    }
}

void CEmitter::scanStmtForGenerics(SharedStatement s, std::map<std::string, SharedIdentifier>& localTys)
{
    if (!s) return;
    ASTNode* n = s.get();
    if (auto* b = dynamic_cast<BlockNode*>(n)) {
        // Per-block COPY, the way the match arms below already do it: a block's declarations end with
        // the block, so they must not type a same-named binding in a later sibling block.
        std::map<std::string, SharedIdentifier> blockTys = localTys;
        if (b->statements) for (auto& st : *b->statements) scanStmtForGenerics(st, blockTys);
    } else if (auto* d = dynamic_cast<LocalVariableDeclaration*>(n)) {
        if (d->variables) for (auto& v : *d->variables) if (v) {
            scanExprForGenerics(v->initializer, localTys);
            // Flat name->type map; scoping is the CALLER's (a block, a loop, an arm) — each recurses on a
            // copy, so a name declared inside ends with its scope. Declarations do not shadow (a compile
            // error), but `foreach`/`match` bindings do, and those binders scope their own copy too.
            if (v->name && v->name->value && d->type) localTys[*v->name->value] = d->type;
        }
    } else if (auto* cd = dynamic_cast<ConstLocalVariableDeclaration*>(n)) {
        if (cd->variables) for (auto& v : *cd->variables) if (v) {
            scanExprForGenerics(v->initializer, localTys);
            if (v->name && v->name->value && cd->type) localTys[*v->name->value] = cd->type;
        }
    } else if (auto* r = dynamic_cast<ReturnNode*>(n)) {
        scanExprForGenerics(r->expression, localTys);
    } else if (auto* av = dynamic_cast<ArmValueNode*>(n)) {
        scanExprForGenerics(av->value, localTys);
    } else if (auto* f = dynamic_cast<IfNode*>(n)) {
        scanExprForGenerics(f->booleanExpression, localTys);
        scanStmtForGenerics(f->ifStatement, localTys); scanStmtForGenerics(f->elseStatement, localTys);
    } else if (auto* w = dynamic_cast<WhileNode*>(n)) {
        scanExprForGenerics(w->booleanExpression, localTys); scanStmtForGenerics(w->whileStatement, localTys);
    } else if (auto* dw = dynamic_cast<DoWhileNode*>(n)) {
        scanExprForGenerics(dw->booleanExpression, localTys); scanStmtForGenerics(dw->doWhileStatement, localTys);
    } else if (auto* fr = dynamic_cast<ForNode*>(n)) {
        // The counter the init declares is the loop's, not the enclosing block's — a copy for the loop.
        std::map<std::string, SharedIdentifier> loopTys = localTys;
        if (fr->initializerStatements) for (auto& st : *fr->initializerStatements) scanStmtForGenerics(st, loopTys);
        scanExprForGenerics(fr->booleanExpression, loopTys);
        if (fr->iteratorStatements) for (auto& st : *fr->iteratorStatements) scanStmtForGenerics(st, loopTys);
        scanStmtForGenerics(fr->body, loopTys);
    } else if (auto* fe = dynamic_cast<ForEachNode*>(n)) {
        scanExprForGenerics(fe->expression, localTys);
        // A foreach BINDING is a locally-typed value exactly like the declaration arm above, and this is
        // the table generic inference reads. Without it, passing a loop variable to ANY generic function
        // fails to infer — `toString(x: v)` inside a `foreach` demanded an explicit `::<int32>`, while the
        // identical call one line outside the loop did not.
        // Bound in a COPY for the body: the binding may shadow an enclosing local, and it ends with the
        // loop. Bound in the shared map, `string m; foreach (int32 m in xs) {…} ident(x: m)` inferred
        // `T = int32` for a `string` argument after the loop.
        std::map<std::string, SharedIdentifier> bodyTys = localTys;
        if (fe->type && fe->name && fe->name->value) bodyTys[*fe->name->value] = fe->type;
        scanStmtForGenerics(fe->body, bodyTys);
    } else if (auto* pf = dynamic_cast<ParallelForNode*>(n)) {
        scanExprForGenerics(pf->expression, localTys);
        scanStmtForGenerics(pf->body, localTys);
    } else if (auto* bn = dynamic_cast<BorrowNode*>(n)) {
        std::map<std::string, SharedIdentifier> bodyTys = localTys;   // the aliases live in the window only
        if (bn->bindings) for (auto& b : *bn->bindings) if (b) {
            scanExprForGenerics(b->host, localTys);
            // A `borrow` ALIAS is a locally-typed value like the declaration and `foreach` arms above —
            // and the only one whose type is never written, so it has to be resolved from the mint.
            if (b->alias && b->alias->value)
                if (SharedIdentifier at = mintReturnTypeNode(b->host, localTys))
                    bodyTys[*b->alias->value] = at;
        }
        scanStmtForGenerics(bn->body, bodyTys);
    } else if (dynamic_cast<ExpressionStatementNode*>(n)) {
        scanExprForGenerics(std::dynamic_pointer_cast<ExpressionNode>(s), localTys);
    }
}

// Pre-pass: discover every reachable generic-function instantiation (call sites in free
// functions + class members). Seeds `localTys` with the enclosing signature's params.
void CEmitter::collectGenericInsts(SharedCompilationUnit unit)
{
    if (!unit || !unit->codeDeclarationList) return;
    // Generic FUNCTIONS and generic TYPES both — this pass registers a `Pair::<int32,int32>::arity()`
    // instance as well as a `f::<T>()` one, and `_generics` holds only the functions. The prelude used to
    // carry `toString`/`__kamaDeserialize`, so `_generics` was never empty and this guard never fired;
    // removing them exposed it, and a program with generic types but no generic functions skipped the
    // whole pass — its type instances never reached the emitter.
    if (_generics.empty() && _genericTypes.empty()) return;   // nothing generic in the program
    auto seed = [&](SharedParameterList params, std::map<std::string, SharedIdentifier>& lt) {
        if (params) for (auto& p : *params)
            if (p && p->identifier && p->identifier->value && p->type) lt[*p->identifier->value] = p->type;
    };
    for (auto& decl : *unit->codeDeclarationList) {
        if (auto* fn = dynamic_cast<FunctionDeclarationNode*>(decl.get())) {
            if (!fn->block) continue;
            std::map<std::string, SharedIdentifier> lt; seed(fn->parameters, lt);
            scanStmtForGenerics(fn->block, lt);
        } else if (auto* cd = dynamic_cast<ClassDeclarationNode*>(decl.get())) {
            // A GENERIC type's members belong to registerInstGenerics, which re-walks them once per
            // instantiation with `_typeSubst` bound. Walking them here — with the type parameters still
            // bare — is what used to reject a generic call whose argument is typed by the enclosing
            // template, and a template with no instantiation has no code to discover anyway.
            if (cd->typeParams && !cd->typeParams->empty()) continue;
            if (cd->members) for (auto& m : *cd->members) {
                ASTNode* mn = m.get();
                // A field's DEFAULT INITIALIZER is code too — it runs in every ctor — so a generic call in one
                // (`int32 n = pick(x: 7);`) must be discovered like one in a body (KR-21 b). Neither discovery
                // pass walked it, so the call reached the emitter with no instantiation registered.
                if (auto* fd = dynamic_cast<ClassFieldDeclarationNode*>(mn)) {
                    if (fd->declarators)
                        for (auto& d : *fd->declarators)
                            if (d && d->initializer) { std::map<std::string, SharedIdentifier> lt; scanExprForGenerics(d->initializer, lt); }
                } else if (auto* md = dynamic_cast<ClassMethodDeclarationNode*>(mn)) {
                    std::map<std::string, SharedIdentifier> lt; seed(md->params, lt);
                    scanStmtForGenerics(md->body, lt);
                } else if (auto* cc = dynamic_cast<ClassConstructorDeclarationNode*>(mn)) {
                    std::map<std::string, SharedIdentifier> lt;
                    if (cc->declarator) seed(cc->declarator->params, lt);
                    scanStmtForGenerics(cc->body, lt);
                } else if (auto* dd = dynamic_cast<ClassDestructorDeclarationNode*>(mn)) {
                    std::map<std::string, SharedIdentifier> lt;
                    scanStmtForGenerics(dd->body, lt);
                }
            }
        }
    }
}

// Emit one specialized `static` C function for an instantiation: a forward prototype
// (prototypeOnly) so instantiations may call one another / recurse, else the body. The
// template body is re-emitted with _typeSubst bound to this tuple, in the template's home
// namespace scope, under the instantiation's mangled name.
void CEmitter::emitGenericInst(const GenericInst& gi, bool prototypeOnly)
{
    // The generic-FUNCTION half of the same rule emitGenericTypeInst states: a refused type argument gets
    // a prototype (so the call site still resolves) but no body (so the template cannot report the
    // consequences of an argument its own bound rejected).
    if (!prototypeOnly && _boundFailedInsts.count(gi.mangledName)) return;
    auto tit = _generics.find(gi.templateKey);
    if (tit == _generics.end()) return;
    FunctionDeclarationNode* tmpl = tit->second;

    // M6 B3: this body is the TEMPLATE's source, re-walked once per instantiation, so every use-site it
    // records belongs to the template's unit — never the instantiation's use site, which would scatter one
    // declaration's references across every caller's file at the template's own coordinates. A prelude/std
    // template yields nullptr, which correctly disables recording for a body the user cannot edit.
    RefUnitScope refScope(this, unitOfDecl(tmpl));
    // …but a DIAGNOSTIC still belongs to that file even when recording is off, so it reads the file
    // directly rather than through `unitOfDecl`, which answers nothing for a prelude/std template.
    auto dfIt = _genericDeclFile.find(gi.templateKey);
    ScopedStr _edf(_emitDeclFile, dfIt == _genericDeclFile.end() ? std::string() : dfIt->second);
    ScopedAttrSite _as(*this, gi.mangledName, dfIt == _genericDeclFile.end() ? std::string() : dfIt->second);

    NsCtx savedCtx = _nsCtx;
    auto cit = _genericCtx.find(gi.templateKey);
    if (cit != _genericCtx.end()) _nsCtx = cit->second;

    // Bind each parameter to its argument: a const param (`const N: int`) binds a VALUE in
    // _comptimeSubst (so a `Fixed<T,N>` param type resolves to `Fixed_T_4`, and the body can READ `N`);
    // a type param binds a type in _typeSubst. Both are cleared identically at the end.
    bindInstParams(tmpl->typeParams, tmpl->constTypes, gi.typeArgs);

    if (prototypeOnly) emitFunctionPrototype(tmpl, &gi.mangledName);   // emits `static` via nameOverride
    else               emitFunction(tmpl, &gi.mangledName);

    _typeSubst.clear();
    _comptimeSubst.clear();
    _nsCtx = savedCtx;
}

const char* CEmitter::deferKindName(int k)
{
    switch (k) {
        case DK_RecvGeneric: return "recv-generic";
        case DK_RecvBound:   return "recv-param-bounded";
        case DK_RecvUnbound: return "recv-param-unbound";
        case DK_RecvUnknown: return "recv-unknown";
        case DK_Turbofish:   return "turbofish";
        case DK_ScopeQual:   return "scope-qual";
        case DK_DotCtor:     return "dot-ctor";
        case DK_OpaqueScalar: return "opaque-scalar";
        case DK_ConstParam:  return "const-param";
    }
    return "?";
}

// Does `t` name — at any depth — one of the params of the template being probed? `View<T>` and
// `Optional<Pair<K, V>>` both do; `View<int32>` does not. Deliberately narrower than `isTypeParamName`,
// which answers for EVERY template's params: here the question is whether THIS body's own parameter is
// what makes the type unresolvable, and a name that merely collides with some other template's `T` is not.
bool CEmitter::typeMentionsProbedParam(const SharedIdentifier& t) const
{
    if (!t || !t->value) return false;
    if (!t->genericArg && _probeTypeParams.count(*t->value)) return true;
    if (t->genericArgs) for (auto& a : *t->genericArgs) if (typeMentionsProbedParam(a)) return true;
    return false;
}

CEmitter::DeferKind CEmitter::classifyDeferredReceiver(SharedExpression recv)
{
    // The receiver may be the PARAMETER ITSELF rather than a value of it — `T.fromStr(s: s)`,
    // `T.deserialize(r: r)`: a static reached through the type parameter, which is how every bounded
    // static in the stdlib is called. `receiverTypeNode` answers nothing for a type receiver (it looks up
    // locals and fields), so ask the spelling directly, or these land in the "cannot tell" bucket and
    // overstate the residual. Same bounded/unbound split — a bound is what carries the static too.
    if (auto* id = dynamic_cast<IdentifierNode*>(recv.get()))
        if (id->value && _probeTypeParams.count(*id->value)) {
            auto b = _probeParamBounds.find(*id->value);
            return (b != _probeParamBounds.end() && !b->second.empty()) ? DK_RecvBound : DK_RecvUnbound;
        }
    SharedIdentifier tn = receiverTypeNode(recv);
    if (!tn || !tn->value) return DK_RecvUnknown;
    // A BARE parameter (`T x` — no generic args): the split that decides who can close the site. With a
    // bound, a synthetic type standing for `T` answers the call from the contract; without one there is
    // nothing to answer FROM, and the fix is a bound added at the declaration.
    if (!tn->genericArg && _probeTypeParams.count(*tn->value)) {
        auto b = _probeParamBounds.find(*tn->value);
        return (b != _probeParamBounds.end() && !b->second.empty()) ? DK_RecvBound : DK_RecvUnbound;
    }
    if (typeMentionsProbedParam(tn)) return DK_RecvGeneric;   // `View<T>`, `DynamicArray<T>`
    return DK_RecvUnknown;
}

// ---- The probe sandbox --------------------------------------------------------------------------
// A probe registers real instances (`View<__opq_f_T>` goes through registerGenericTypeInst like any
// other) and those registrations are the point — they are what makes `items.length()` resolvable. But
// they describe a body nobody instantiated, so nothing downstream may see them. Snapshot the keys, erase
// what appeared. Keyed rather than instrumented at each insertion site because the registration paths are
// deep and transitive: a missed site would leak silently, and "silently" is the failure mode this whole
// campaign is about.
template <class M, class S> static void snapKeys(const M& m, S& out)
{ out.clear(); for (auto& kv : m) out.insert(kv.first); }
template <class M, class S> static void eraseNew(M& m, const S& snap)
{ for (auto it = m.begin(); it != m.end(); ) { if (snap.count(it->first)) ++it; else it = m.erase(it); } }

void CEmitter::probeSandboxBegin()
{
    snapKeys(_classes,               _probeSnap.classes);
    snapKeys(_interfaces,            _probeSnap.interfaces);
    snapKeys(_genericTypeInsts,      _probeSnap.typeInsts);
    snapKeys(_genericTypeInstOf,     _probeSnap.typeInstOf);
    snapKeys(_genericTypeInstCtx,    _probeSnap.typeInstCtx);
    snapKeys(_collections,           _probeSnap.collections);
    snapKeys(_genericContractInstCtx,_probeSnap.contractInstCtx);
    snapKeys(_primConformances,      _probeSnap.primConf);
    snapKeys(_genericInsts,          _probeSnap.fnInsts);      // a turbofish resolved mid-walk registers one
    snapKeys(_callInst,              _probeSnap.callInsts);
    _probeSnap.contractInsts = _genericContractInsts;             // already a set of names
    _probeSnap.typeInstOrder   = _genericTypeInstOrder.size();
    _probeSnap.collectionOrder = _collectionOrder.size();
}

void CEmitter::probeSandboxEnd()
{
    eraseNew(_classes,                _probeSnap.classes);
    eraseNew(_interfaces,             _probeSnap.interfaces);
    eraseNew(_genericTypeInsts,       _probeSnap.typeInsts);
    eraseNew(_genericTypeInstOf,      _probeSnap.typeInstOf);
    eraseNew(_genericTypeInstCtx,     _probeSnap.typeInstCtx);
    eraseNew(_collections,            _probeSnap.collections);
    eraseNew(_genericContractInstCtx, _probeSnap.contractInstCtx);
    eraseNew(_primConformances,       _probeSnap.primConf);
    eraseNew(_genericInsts,           _probeSnap.fnInsts);
    eraseNew(_callInst,               _probeSnap.callInsts);
    _genericContractInsts = _probeSnap.contractInsts;
    _opaqueDisplay.clear();          // diagnostics render eagerly, so nothing needs this past the walk
    // The two ORDER vectors are append-only registration logs; a probe can only have pushed onto the end.
    if (_genericTypeInstOrder.size() > _probeSnap.typeInstOrder)
        _genericTypeInstOrder.resize(_probeSnap.typeInstOrder);
    if (_collectionOrder.size() > _probeSnap.collectionOrder)
        _collectionOrder.resize(_probeSnap.collectionOrder);
}

// Bounded quantification, said out loud. SPEC has always claimed it — "a bound lets the body call the
// contract's methods on a type-param value" — and nothing enforced it, so a generic could call whatever it
// liked and find out at each consumer's use site. The message names the fix, because the fix is not the one
// a "no such method" would suggest: nothing is missing from `T`, the promise is.
bool CEmitter::rejectUnprovenBound(const std::string& cls, const std::string& member, int line)
{
    if (!_probingTemplate) return false;
    auto it = _classes.find(cls);
    if (it == _classes.end() || !it->second.isOpaqueParam) return false;

    auto dn = _opaqueDisplay.find(cls);
    const std::string p = (dn == _opaqueDisplay.end()) ? cls : dn->second;
    // Show a bound as the contract the user WROTE (`Comparable`), not the instance minted over the
    // opaque (`Comparable___opq_f_T`) — `templateKey` is the specialization's own record of it.
    std::string bounds;
    for (auto& itf : it->second.interfaces) {
        auto ii = _interfaces.find(itf);
        const std::string shown = (ii != _interfaces.end() && !ii->second.templateKey.empty())
                                ? ii->second.templateKey : itf;
        if (!bounds.empty()) bounds += "`, `";
        bounds += shown;
    }
    const bool many = it->second.interfaces.size() > 1;
    unsupported((bounds.empty()
        ? "`" + p + "` has no bound providing `" + member + "` — an unbounded type parameter promises "
          "nothing, so bound it with a contract that declares `" + member + "`: `<" + p + ": …>`"
        : "`" + p + "` has no bound providing `" + member + "` — its bound" + (many ? "s (`" : " (`")
          + bounds + "`) declare" + (many ? "" : "s") + " no such member; add one that does").c_str(), line);
    return true;
}

// The stand-in a probe puts in a `const N: int32` slot. Its VALUE is deliberately never read — see the
// call site — so it exists only to be a well-formed argument for mangling and arity checking. `1` rather
// than `0` because a zero is the value most likely to be meaningful if it ever did leak into a fold.
SharedIdentifier CEmitter::probeConstArg()
{
    if (!_synthCtx) _synthCtx = std::make_shared<CodeGenContext>(std::make_shared<std::string>("<synth>"));
    auto id = std::make_shared<IdentifierNode>(*_synthCtx, SharedString());
    id->synthesized = true;
    id->constArgValue = std::make_shared<Int64Node>(*_synthCtx, 1);
    return id;
}

std::vector<std::string> CEmitter::buildOpaqueParams(const std::string& templateKey,
                                                     SharedStringList typeParams,
                                                     SharedBoundsList typeBounds,
                                                     SharedIdentifierList constTypes)
{
    std::vector<std::string> names;
    if (!typeParams) return names;

    // PASS 1 — every parameter becomes a bare type first. A bound may name a SIBLING parameter
    // (`<T, C: Order<T>>`), and `Order<T>` cannot mangle to an instance until `T` is something to mangle.
    for (size_t i = 0; i < typeParams->size(); ++i) {
        SharedString p = (*typeParams)[i];
        bool isComptimeParam = constTypes && i < constTypes->size() && (*constTypes)[i];
        if (!p || isComptimeParam) { names.push_back(std::string()); continue; }   // a const param stands for a VALUE
        std::string on = "__opq_" + templateKey + "_" + *p;
        ClassInfo ci;
        ci.name          = on;
        ci.isOpaqueParam = true;
        // A RESOURCE that has not opted into Copyable — the conservative reading, and the honest one: an
        // instantiation may bind `T` to a move-only type, so a `when [T: Copyable<T>]` member legitimately
        // does not exist here. Treating an unbounded `T` as a `value` would make the probe pass bodies a
        // move-only argument rejects, which is a blind spot HIDDEN rather than counted.
        ci.kind      = TypeKind::Resource;
        ci.copyable  = false;
        _classes[on] = ci;
        _typeSubst[*p] = synthId(on);
        _opaqueDisplay[on] = *p;      // every diagnostic reads `T` back, never the mangle
        names.push_back(on);
    }

    // PASS 2 — project each bound's promises onto the parameter that declared it. This is the whole of
    // bounded quantification: what the bound names is what the body may call.
    if (!typeBounds) return names;
    for (size_t i = 0; i < typeParams->size() && i < typeBounds->size(); ++i) {
        if (names[i].empty()) continue;
        SharedIdentifierList bl = (*typeBounds)[i];
        if (!bl) continue;
        // A bound's `for` clause says which KINDS may satisfy it, and that is information about the
        // parameter, not just about its implementers: `A: Allocator` where `Allocator` is declared
        // `for value` can only ever be bound to a value, and a value is bitwise-copyable. Intersecting the
        // clauses is what keeps the move-only default from being wrong — without it `Shared<T, A>.copy`
        // reads `source.alloc` as a move out of a field, which is true for a resource `A` and impossible
        // for the `A` its own bound permits. 0 means the clause was missing or already diagnosed, so it
        // narrows nothing.
        unsigned allowedKinds = ~0u;
        bool sawKinds = false;
        for (auto& b : *bl) {
            if (!b || !b->value) continue;
            // A bound names a contract in the scope where the TEMPLATE was written, not where it is
            // probed — the same rule checkBounds follows, and for the same reason.
            std::string contract;
            { BoundCtxScope bc(this, templateKey); contract = resolveUserName(*b->value, b->qualifier); }
            // `Copyable` is the one bound whose meaning is a CAPABILITY rather than a method set, and it
            // is declared `for resource`, so the kind intersection below would read it as "resource, so
            // assume move-only" — the exact opposite of what the bound says. Read it directly.
            if (contract == "Copyable") _classes[names[i]].copyable = true;
            // `T: Comparable<T>` — a GENERIC contract. Mint its instance over the (now bound) arguments,
            // so its method signatures are substituted rather than still spelling the contract's own `T`.
            if (b->genericArg && _genericContracts.count(contract)) {
                registerGenericContractInst(contract, b->genericArgs);
                contract = genericTypeMangle(contract, b->genericArgs);
            }
            const std::vector<InterfaceMethod>* ms = contractMethods(contract);
            if (!ms) continue;      // unknown contract — checkBounds owns that diagnostic, not this
            if (unsigned k = implKindsOf(contract, *b->value)) { allowedKinds &= k; sawKinds = true; }
            _classes[names[i]].interfaces.push_back(contract);
            // A refinement (`type contract Animated implements Drawable`) has already had its parent's
            // slots merged into `methods` by linkContracts, so one pass over `ms` is the full promise.
            for (auto& m : *ms) {
                if (m.name.empty() || _classes[names[i]].methods.count(m.name)) continue;
                MethodInfo mi;
                mi.cName        = names[i] + "__" + m.name;   // never emitted; a probe body is discarded
                mi.returnType   = m.returnType;
                mi.params       = paramSigsOf(m.params);
                mi.isConst      = m.isConst;
                mi.isStatic     = m.isStatic;
                mi.isCtor       = m.isCtor;
                mi.isPlaceReturn = m.isPlaceReturn;
                mi.isConstPlace  = m.isConstPlace;
                mi.visibility   = Visibility::Public;         // a contract's methods are public
                mi.fromContract = contract;
                mi.isAbstract   = true;                       // a promise, not a body — never emit one
                // An operator reaches the contract's method list under the SAME synthetic name a concrete
                // class uses (`op_add`), and `nameId` is null only for that arm. Operator dispatch gates
                // on `isOperator` + `arity`, so both have to be set or `a + b` on a bounded `T` — the
                // whole point of generic math — silently reports "no operator for type".
                if (!m.nameId && m.name.compare(0, 3, "op_") == 0) {
                    mi.isOperator = true;
                    mi.arity      = m.params ? (int)m.params->size() : 0;
                }
                _classes[names[i]].methods[m.name] = mi;
                // A contract may REQUIRE a ctor (`Parseable` requires `fromStr`, `HeapOwner` requires
                // `adopt`), and construction resolves through `ctors`, not `methods` — the two are
                // populated together everywhere else, and populating only one here made `T.fromStr(s: s)`
                // report "`T` cannot be constructed — it has no `ctor`" against a bound that supplies
                // exactly that. A written return type means fallible, the same rule the class path uses.
                if (m.isCtor)
                    _classes[names[i]].ctors[m.name] =
                        CtorInfo{ nullptr, mi.params, Visibility::Public, (bool)m.returnType, m.returnType, false };
            }
        }
        // No bound admits a `resource` => the parameter is a value at every instantiation, so it is
        // bitwise-copyable and `when [P: Copyable<P>]` members are present. This is READ off the
        // declaration, never assumed: an unbounded parameter, or one whose bounds admit a resource, keeps
        // the move-only default it was minted with.
        if (sawKinds && !(allowedKinds & IK_Resource) && allowedKinds != 0) {
            _classes[names[i]].kind     = TypeKind::Value;
            _classes[names[i]].copyable = true;
        }
    }
    return names;
}

// Walk every generic template NOBODY instantiates, for its diagnostics alone. See the header for why this
// exists at all (short version: `analyze()` IS `emit()`, and the emit walk skips a template body, so every
// rule in this file was invisible inside an uninstantiated generic by construction).
//
// This is `emitGenericInst` aimed at a throwaway sink: same ref-unit scope, same declaring-file scope, same
// home namespace, so a diagnostic lands on the template's own file and line and a reference recorded from
// the body belongs to the template's unit. The one thing an instantiation has that a probe does not is a
// real type argument — so the probe invents one, an OPAQUE PARAMETER standing for `T` and promising exactly
// what `T`'s bounds promise. That is the whole difference from `emitGenericInst`, and it is what makes the
// walk answer `x.compareTo(…)` and `d.length()` instead of stepping around them.
void CEmitter::checkUninstantiatedTemplates()
{
    // BOTH tables, or a file with generic types and no generic functions is walked by neither — which is
    // precisely a library shipping a generic container, the case this whole pass exists for.
    if (_generics.empty() && _genericTypes.empty()) return;

    // Which templates a real instantiation already covered. Built once — `_genericInsts` is keyed by
    // MANGLED name, so the template key is in the value, and asking per template would be quadratic.
    std::set<std::string> instantiated;
    for (auto& kv : _genericInsts) instantiated.insert(kv.second.templateKey);

    std::ostringstream sink;
    std::ostream* savedOut = _out;
    NsCtx savedCtx = _nsCtx;
    std::map<std::string, SharedIdentifier> savedSubst = _typeSubst;
    _out = &sink;
    _probingTemplate = true;   // unknown-type diagnostics defer from here on — see deferUnknownWhileProbing
    probeSandboxBegin();       // …and every instance the walk registers is erased on the way out

    // `_generics` is a std::map, so this order is the sorted template key — a diagnostic's position in the
    // output must not depend on hash iteration order.
    for (auto& kv : _generics) {
        const std::string& key = kv.first;
        FunctionDeclarationNode* tmpl = kv.second;
        if (!tmpl || !tmpl->block || !tmpl->typeParams || tmpl->typeParams->empty()) continue;
        if (instantiated.count(key)) continue;      // already walked, with real types — do not diagnose twice

        RefUnitScope refScope(this, unitOfDecl(tmpl));
        auto dfIt = _genericDeclFile.find(key);
        ScopedStr _edf(_emitDeclFile, dfIt == _genericDeclFile.end() ? std::string() : dfIt->second);

        auto cit = _genericCtx.find(key);
        _nsCtx = (cit != _genericCtx.end()) ? cit->second : savedCtx;

        // The template's own params, so `isTypeParamName` answers for them. Restored per template rather
        // than accumulated: two templates' `T`s are different types, and a name that is a param HERE must
        // not stay one for the next body walked.
        std::set<std::string> savedProbe = _probeTypeParams;
        auto savedBounds = _probeParamBounds;
        _probeTypeParams.clear();
        _probeParamBounds.clear();
        for (auto& tp : *tmpl->typeParams) if (tp) _probeTypeParams.insert(*tp);
        // The bounds are index-parallel to the params (an empty entry = unbounded). Stored by their
        // SPELLED name, not resolved: the classifier only asks "is there a bound at all", and resolving
        // would need the template's home ctx for a benefit no column reads.
        if (tmpl->typeBounds)
            for (size_t i = 0; i < tmpl->typeParams->size() && i < tmpl->typeBounds->size(); ++i) {
                SharedIdentifierList bl = (*tmpl->typeBounds)[i];
                if (!bl || !(*tmpl->typeParams)[i]) continue;
                auto& slot = _probeParamBounds[*(*tmpl->typeParams)[i]];
                for (auto& b : *bl) if (b && b->value) slot.push_back(*b->value);
            }

        // One opaque type per parameter, bound into `_typeSubst` — cleared per template, because two
        // templates' `T`s are different types and a binding that outlived its body would silently retype
        // the next one.
        _typeSubst.clear();
        buildOpaqueParams(key, tmpl->typeParams, tmpl->typeBounds, tmpl->constTypes);

        // Then register every generic instance the body names, over those opaque arguments: `View<T>`
        // becomes `View<__opq_f_T>`, an ORDINARY instance with an ordinary `operator[]` and `length()`.
        // Without this the receiver stays unresolved and index lowering falls back to raw C `p[i]` — which
        // the unsafe seam then rejects, a false positive against a body that only ever indexes a view.
        // Mirrors registerInstColls: seed the parameter types, then walk the block.
        _scanLocalTys.clear();
        _constLocalVals.clear();
        if (tmpl->parameters)
            for (auto& p : *tmpl->parameters) {
                if (!p || !p->type) continue;
                if (p->identifier && p->identifier->value) _scanLocalTys[*p->identifier->value] = p->type;
                scanTypeForCollections(p->type);
            }
        scanTypeForCollections(tmpl->returnType);
        scanStmtForCollections(tmpl->block);

        const int  errsBefore = _unsupported;
        const long defBefore = _probeDeferred;
        const long resBefore = _probeResolved;
        long byBefore[DK_Count];
        for (int i = 0; i < DK_Count; ++i) byBefore[i] = _probeDeferBy[i];
        const std::string probeName = key + "__probe";
        emitFunction(tmpl, &probeName);   // nameOverride => `static` linkage, and no entry-point mangling

        // `--probe-templates`: key, file, line, #type-params, errors raised, diagnostics deferred,
        // diagnostics resolved, then ONE COLUMN PER DEFERRAL BUCKET (see DeferKind). The deferred total is
        // the blind spot and `resolved` is its denominator; the buckets say who can close it — a compiler
        // change (recv-generic, recv-param-bounded, turbofish, scope-qual, dot-ctor) or a SOURCE change in
        // every generic that calls through an unbounded parameter (recv-param-unbound). See setProbeReport.
        if (_probeReport) {
            std::fprintf(stdout, "probe\t%s\t%s\t%d\t%zu\t%ld\t%ld\t%ld",
                         key.c_str(), _emitDeclFile.empty() ? "<prelude>" : _emitDeclFile.c_str(),
                         tmpl->line, tmpl->typeParams->size(),
                         (long)(_unsupported - errsBefore), _probeDeferred - defBefore,
                         _probeResolved - resBefore);
            for (int i = 0; i < DK_Count; ++i) std::fprintf(stdout, "\t%ld", _probeDeferBy[i] - byBefore[i]);
            std::fprintf(stdout, "\n");
        }

        _probeTypeParams = savedProbe;
        _probeParamBounds = savedBounds;
        sink.str(std::string());          // one body's worth of C at a time, not the whole corpus
    }

    checkUninstantiatedTypeTemplates();   // the other table, same walk — see the header

    _probingTemplate = false;
    probeSandboxEnd();         // every opaque type and every instance built over one goes here
    _out = savedOut;
    _nsCtx = savedCtx;
    _typeSubst = savedSubst;
    _probeTypeParams.clear();
    _probeParamBounds.clear();
}

// Runs inside checkUninstantiatedTemplates' sink, probe flag and sandbox — so a diagnostic defers the
// same way, and every instance registered here is erased the same way.
void CEmitter::checkUninstantiatedTypeTemplates()
{
    if (_genericTypes.empty()) return;

    std::set<std::string> instantiated;
    for (auto& kv : _genericTypeInsts) instantiated.insert(kv.second.templateKey);

    // Snapshot the keys: registering a probe instance walks the template's members transitively, and a
    // sibling template reached that way must not be visited mid-iteration.
    std::vector<std::string> tmpls;
    for (auto& kv : _genericTypes) tmpls.push_back(kv.first);

    NsCtx savedCtx = _nsCtx;
    for (const std::string& tmpl : tmpls) {
        if (instantiated.count(tmpl)) continue;         // a real instantiation already walked it
        auto pit = _genericTypeParams.find(tmpl);
        if (pit == _genericTypeParams.end() || pit->second.empty()) continue;
        const std::vector<std::string> params = pit->second;

        // A `const N: int32` parameter stands for a VALUE, not a type, so the instance still needs an
        // argument in that slot for `registerGenericTypeInst` to mangle and validate. It gets a
        // placeholder — and the placeholder is NOT then bound as `N`'s value: `bindInstConstParams` skips
        // it while probing, so the body walks with `N` unbound, exactly as the FUNCTION half already does
        // (`fn f<const S: int32>` has always been walked that way, and catches every type error in its
        // body). That is what keeps the walk from deciding anything the number would have decided —
        // notably the template's own `comptime assert`, which is per-instantiation by definition.
        auto ctit = _genericTypeConstTypes.find(tmpl);
        std::vector<bool> isConstSlot(params.size(), false);
        if (ctit != _genericTypeConstTypes.end())
            for (size_t i = 0; i < params.size() && i < ctit->second.size(); ++i)
                isConstSlot[i] = (bool)ctit->second[i];

        auto sp = std::make_shared<StringList>();
        for (auto& p : params) sp->push_back(std::make_shared<std::string>(p));
        SharedBoundsList bounds = _genericTypeBounds.count(tmpl) ? _genericTypeBounds[tmpl]
                                                                 : SharedBoundsList();

        // Bound names resolve in the scope the TEMPLATE was written in, exactly as `checkBounds` reads
        // them — a stdlib-namespaced bound is invisible from anywhere else.
        auto gtc = _genericTypeCtx.find(tmpl);
        _nsCtx = (gtc != _genericTypeCtx.end()) ? gtc->second : savedCtx;

        std::map<std::string, SharedIdentifier> savedSubst = _typeSubst;
        _typeSubst.clear();
        std::vector<std::string> opq = buildOpaqueParams(tmpl, sp, bounds, SharedIdentifierList());

        auto args = std::make_shared<IdentifierList>();
        bool ok = true;
        for (size_t i = 0; i < opq.size(); ++i) {
            if (isConstSlot[i]) { args->push_back(probeConstArg()); continue; }
            if (opq[i].empty()) { ok = false; break; }
            args->push_back(synthId(opq[i]));
        }
        if (ok) {
            const size_t before   = _genericTypeInstOrder.size();
            const int  errsBefore = _unsupported;
            const long defBefore  = _probeDeferred;
            const long resBefore  = _probeResolved;
            long byBefore[DK_Count];
            for (int i = 0; i < DK_Count; ++i) byBefore[i] = _probeDeferBy[i];
            registerGenericTypeInst(tmpl, args);
            // The instance this template just got — the transitive scan appends others behind it, so
            // match on the template rather than taking the last entry.
            for (size_t i = before; i < _genericTypeInstOrder.size(); ++i) {
                auto oit = _genericTypeInstOf.find(_genericTypeInstOrder[i]);
                if (oit == _genericTypeInstOf.end() || oit->second != tmpl) continue;
                auto git = _genericTypeInsts.find(_genericTypeInstOrder[i]);
                if (git == _genericTypeInsts.end()) continue;
                ++_probeTypesWalked;
                emitGenericTypeInst(git->second, 2);   // phase 2 = vtables + member BODIES, the rules
                break;
            }
            // Same columns as a function row, under a `probe-type` tag so the two halves can be told
            // apart in one run — they close different halves of the same gap and are sized separately.
            if (_probeReport) {
                const ClassInfo& tci = _genericTypes[tmpl];
                std::fprintf(stdout, "probe-type\t%s\t%s\t%d\t%zu\t%ld\t%ld\t%ld",
                             tmpl.c_str(), tci.declFile.empty() ? "<prelude>" : tci.declFile.c_str(),
                             tci.declLine(), params.size(),
                             (long)(_unsupported - errsBefore), _probeDeferred - defBefore,
                             _probeResolved - resBefore);
                for (int i = 0; i < DK_Count; ++i) std::fprintf(stdout, "\t%ld", _probeDeferBy[i] - byBefore[i]);
                std::fprintf(stdout, "\n");
            }
        }
        _typeSubst = savedSubst;
    }
    _nsCtx = savedCtx;
}

// MCU 6b-1: after generic instantiations are discovered, register any collection whose size DERIVES from a
// const param (`InlineArray<T, (N+1)>`) by binding each instantiation's const args so `constValue` folds
// the size. The whole-program pre-pass (collectCollections) ran with NO bindings, so it could only register
// sizes reachable from literals; a const-param-derived size registers only here. Must run BEFORE
// emitCollectionDefs so the concrete instance gets its C typedef. Mirrors emitGenericInst's binding.
void CEmitter::registerInstColls()
{
    NsCtx savedCtx = _nsCtx;
    for (auto& kv : _genericInsts) {
        const GenericInst& gi = kv.second;
        auto tit = _generics.find(gi.templateKey);
        if (tit == _generics.end()) continue;
        FunctionDeclarationNode* tmpl = tit->second;
        if (!tmpl || !tmpl->block || !tmpl->typeParams) continue;
        auto cit = _genericCtx.find(gi.templateKey);
        _nsCtx = (cit != _genericCtx.end()) ? cit->second : savedCtx;
        bindInstParams(tmpl->typeParams, tmpl->constTypes, gi.typeArgs);
        _scanLocalTys.clear();
        _constLocalVals.clear();   // 6b-2: local const values are per-body
        if (tmpl->parameters) for (auto& p : *tmpl->parameters)
            if (p && p->type && p->identifier && p->identifier->value) _scanLocalTys[*p->identifier->value] = p->type;
        scanStmtForCollections(tmpl->block);
    }
    _typeSubst.clear();
    _comptimeSubst.clear();
    _nsCtx = savedCtx;
}

// A generic FREE FUNCTION called from inside a generic TYPE's member could not bind its type parameter:
// collectGenericInsts walks a class body ONCE, verbatim, with `_typeSubst` empty, so an argument whose
// declared type is the enclosing template's own parameter (`V`) reads as a bare name and inferGenericInst
// rejects it ("not a literal or a locally-typed value"). That is the same problem registerInstColls
// already answers for const-generic sizes, so it gets the same answer: re-walk each generic type's member
// bodies ONCE PER INSTANTIATION with `_typeSubst` bound, after every type instantiation is known.
//
// Runs to a fixpoint — scanning a member body can itself register a new type instantiation (a nested
// `Optional<V>`, a `Shared<V>`), which then has its own members to walk. Iterating a SNAPSHOT rather than
// the live map is load-bearing: `scanExprForGenerics` calls `registerGenericTypeInst`, so the map grows
// underneath us.
// The active type substitution as a stable key. `_typeSubst` is a std::map, so the order is deterministic.
std::string CEmitter::substSig()
{
    std::string s;
    for (auto& kv : _typeSubst) { s += kv.first; s += '='; s += mangleElem(kv.second); s += ';'; }
    return s;
}

// Which instantiation `call` routes to from HERE. An exact substitution match first (a call inside a
// generic type's member, discovered once per instantiation); then the unsubstituted entry, which is where
// every ordinary call lands; then a lone entry, for a call discovered outside a substitution and emitted
// inside one (a generic FUNCTION template's body, whose own params bind at emit time).
std::string CEmitter::callInstOf(const InvocationNode* call)
{
    auto ci = _callInst.find(call);
    if (ci == _callInst.end() || ci->second.empty()) return "";
    auto si = ci->second.find(substSig());
    if (si == ci->second.end()) si = ci->second.find("");
    if (si == ci->second.end() && ci->second.size() == 1) si = ci->second.begin();
    return si == ci->second.end() ? "" : si->second;
}

void CEmitter::registerInstGenerics()
{
    if (_generics.empty()) return;          // no generic functions in the program — nothing to infer
    NsCtx savedCtx = _nsCtx;
    auto seed = [&](SharedParameterList params, std::map<std::string, SharedIdentifier>& lt) {
        if (params) for (auto& p : *params)
            if (p && p->identifier && p->identifier->value && p->type) lt[*p->identifier->value] = p->type;
    };
    std::set<std::string> done;
    std::set<std::string> doneFns;
    for (;;) {
        std::vector<std::string> todo;
        for (auto& kv : _genericTypeInsts) if (!done.count(kv.first)) todo.push_back(kv.first);
        std::vector<std::string> todoFns;
        for (auto& kv : _genericInsts) if (!doneFns.count(kv.first)) todoFns.push_back(kv.first);
        if (todo.empty() && todoFns.empty()) break;

        // A generic FREE FUNCTION calling ANOTHER one with a forwarded type parameter — `sort<T>` calling
        // `sortWith::<T, Natural<T>>`, or plain `outer<T>` calling `inner::<T>`. The template body is walked
        // once with `_typeSubst` empty, so that turbofish names the enclosing `T` and no concrete instance is
        // ever registered; the call then had nothing to route to. (Before `explicitGenericInst` learned to
        // defer an unbound argument, it registered `T` bound to itself instead, and `mangleElem` recursed on
        // its own result until the compiler died — this pass is the other half of that fix.) The answer is
        // the one the generic-TYPE case above already uses: re-walk the body ONCE PER INSTANTIATION with the
        // substitution bound. Both kinds share this fixpoint because either can discover the other.
        for (auto& mangled : todoFns) {
            doneFns.insert(mangled);
            auto iit = _genericInsts.find(mangled);
            if (iit == _genericInsts.end()) continue;
            const GenericInst gi = iit->second;      // COPY — the scan below may rehash the map
            auto tit = _generics.find(gi.templateKey);
            if (tit == _generics.end() || !tit->second) continue;
            FunctionDeclarationNode* tmpl = tit->second;
            if (!tmpl->block || !tmpl->typeParams) continue;
            auto cit = _genericCtx.find(gi.templateKey);
            _nsCtx = (cit != _genericCtx.end()) ? cit->second : savedCtx;
            // A const param binds a VALUE, not a type — but it still has to bind, or a generic call in
            // this body that passes one (`ident(x: F)`) cannot infer the callee's type parameter from it.
            bindInstParams(tmpl->typeParams, tmpl->constTypes, gi.typeArgs);
            std::map<std::string, SharedIdentifier> lt; seed(tmpl->parameters, lt);
            scanStmtForGenerics(tmpl->block, lt);
        }

        for (auto& mangled : todo) {
            done.insert(mangled);
            auto iit = _genericTypeInsts.find(mangled);
            if (iit == _genericTypeInsts.end()) continue;
            const GenericTypeInst gi = iit->second;      // COPY — the scan below may rehash the map
            auto tit = _genericTypes.find(gi.templateKey);
            auto pit = _genericTypeParams.find(gi.templateKey);
            if (tit == _genericTypes.end() || !tit->second.node || pit == _genericTypeParams.end()) continue;
            // Walk the SPECIALIZED method set, not the template's raw AST members. `registerGenericTypeInst`
            // has already dropped every `when [V: Copyable]`-gated member that does not hold for this
            // instantiation, and walking those would pull in code the program never uses — a `Map<int32, C>`
            // for a move-only `C` would register `MapValueIter<C>` off the gated `values()`, whose
            // `return copy v;` then fails to lower.
            auto sit = _classes.find(mangled);
            if (sit == _classes.end()) continue;
            auto cit = _genericTypeCtx.find(gi.templateKey);
            _nsCtx = (cit != _genericTypeCtx.end()) ? cit->second : savedCtx;
            // Skip an instance whose own arguments are not concrete. `_genericTypeInsts` can hold a
            // partially-resolved registration whose argument is still a bare type-parameter name
            // (`DynamicArray_K`, seen from inside `SortedMap<K,V>`); binding `T -> K` would substitute one
            // unresolvable name for another and report the inference failure this pass exists to prevent.
            // Such an instance is never emitted, so there is nothing in it to discover. A nested generic
            // (`List<int32>`) and a const argument are both concrete for this purpose.
            bool bogus = false;
            for (size_t i = 0; i < pit->second.size() && i < gi.typeArgs.size(); ++i) {
                SharedIdentifier a = gi.typeArgs[i];
                if (a && a->value && !a->genericArg && !a->constArgValue && !isConcreteTypeArg(a)) bogus = true;
            }
            if (bogus) continue;
            _typeSubst.clear();
            for (size_t i = 0; i < pit->second.size() && i < gi.typeArgs.size(); ++i)
                if (gi.typeArgs[i]) _typeSubst[pit->second[i]] = gi.typeArgs[i];
            for (auto& f : sit->second.fields)   // field default initializers — see collectGenericInsts
                if (f.initializer) { std::map<std::string, SharedIdentifier> lt; scanExprForGenerics(f.initializer, lt); }
            for (auto& kv : sit->second.methods) {
                ClassMethodDeclarationNode* md = kv.second.node;
                if (!md || !md->body) continue;                       // intrinsic / synthesized — no body
                std::map<std::string, SharedIdentifier> lt; seed(md->params, lt);
                scanStmtForGenerics(md->body, lt);
            }
            if (tit->second.node->members)                            // the dtor is never gated
              for (auto& m : *tit->second.node->members)
                if (auto* dd = dynamic_cast<ClassDestructorDeclarationNode*>(m.get())) {
                    std::map<std::string, SharedIdentifier> lt;
                    scanStmtForGenerics(dd->body, lt);
                }
        }
    }
    _typeSubst.clear();
    _nsCtx = savedCtx;
}

// `Weak<T>.tryUpgrade() -> Optional<Shared<T>>` — the type-safe replacement for the empty-
// Shared sentinel. Wraps the runtime macro's internal `__upgrade` (which does the strong++/empty):
// a live Shared (ctrl != NULL) becomes `Some`, a dead one `None`. Emitted after the Weak macro,
// where both the Shared and the Optional<Shared<T>> instance structs are already complete.
// A library `Rc<Shape>`'s `downgrade()` (Shared IFACE -> its Weak partner): field-copy the fat pointer +
// bump `weak`. Mirrors the intrinsic Shared->Weak assignment, as a named `static inline` method so
// `rc.downgrade()` dispatches to it (registered as an intrinsic on the Shared instance).
void CEmitter::emitSharedToWeakDowngrade(const CollectionInfo& info)
{
    const std::string& wk = info.ifacePartner;           // the Weak partner (RcWeak_<elem>)
    bool ifaceAlloc = info.elemIsInterface && !info.allocType.empty() && info.allocType != "GlobalAllocator";
    *_out << "static inline " << wk << " " << info.cName << "__" << info.downgradeName
          << "(" << info.cName << "* self) {\n"
          << "    " << wk << " w;\n"
          << "    w.obj = self->obj; w.vtbl = self->vtbl; w.ctrl = self->ctrl;\n";
    if (ifaceAlloc)   // carry the allocator so the Weak frees the ctrl through the right A
        *_out << "    w.alloc = self->alloc;\n";
    *_out << "    if (w.ctrl) w.ctrl->weak++;\n"
          << "    return w;\n"
          << "}\n";
}

void CEmitter::emitWeakTryUpgrade(const CollectionInfo& info)
{
    std::string sh  = info.ifacePartner;                 // the Shared it upgrades to (Shared_<elem> or a library `Rc_<elem>`)
    std::string opt = "Optional_" + sh;                 // Optional_<shared>
    if (!_genericTypeInsts.count(opt)) return;          // prelude Optional unavailable -> skip (upgrade stays)
    *_out << "static inline " << opt << " " << info.cName << "__tryUpgrade(" << info.cName << "* self) {\n"
          << "    " << sh << " s = " << info.cName << "__upgrade(self);\n"
          << "    if (s.ctrl) return (" << opt << "){ .tag = " << opt << "_Some, .u.Some = { .value = s } };\n"
          << "    return (" << opt << "){ .tag = " << opt << "_None };\n"
          << "}\n";
}

// `.find(substring:)` -> Optional<usize>: wrap the raw byte-scan helper so an absent match is `None`,
// never a sentinel. Mirrors emitWeakTryUpgrade — pure ISO C compound literals (no statement-expression),
// emitted in the collection FUNCS phase where the Optional<usize> instance struct is already complete.
void CEmitter::emitStringFind(const CollectionInfo& info)
{
    const std::string opt = "Optional_usize";
    if (!_genericTypeInsts.count(opt)) return;   // Optional<usize> unavailable -> skip (find unregistered)
    *_out << "static inline " << opt << " " << info.cName << "__find(" << info.cName
          << "* self, kama_string needle) {\n"
          << "    size_t off;\n"
          << "    if (kama_string__find_raw(self, needle, &off))\n"
          << "        return (" << opt << "){ .tag = " << opt << "_Some, .u.Some = { .value = off } };\n"
          << "    return (" << opt << "){ .tag = " << opt << "_None };\n"
          << "}\n";
}

// `InlineArray<T,N>.view()` -> `View<T>`, the wrapper KAMA_FIXED_FUNCS cannot supply: a runtime macro has
// no way to name the program-specific `View_<T>` struct. Sibling of emitStringFind, and the same shape —
// a static inline that builds the generic instance's struct literal directly.
//
// It mints the view WITHOUT going through `View.over`, deliberately: that ctor is private (the mint rule),
// and the privacy check is a SOURCE-level rule about which kama type may call it. An intrinsic has no
// source to check, and its ClassInfo carries the `Viewable<View<T>>` grant that makes the mint legitimate
// — so the two-field literal here IS the grant, discharged in C.
void CEmitter::emitFixedView(const CollectionInfo& info)
{
    // Both halves (registerFixedViews): `__view` builds the `ConstView<T>` literal — `self->v` decays to
    // `T*` and C narrows it to the struct's `T const*` field — and `__viewMut` the `View<T>` one.
    for (const char* member : { "view", "viewMut" }) {
        auto mi = _classes[info.cName].methods.find(member);
        if (mi == _classes[info.cName].methods.end()) continue;   // no stdlib View -> unregistered
        const std::string vt = cType(mi->second.returnType);
        if (!isViewCType(vt)) continue;                            // registration failed; nothing to emit
        *_out << "static inline " << vt << " " << info.cName << "__" << member << "(" << info.cName << "* self) {\n"
              << "    return (" << vt << "){ .data = self->v, .len = (ptrdiff_t)(" << info.constValue << ") };\n"
              << "}\n";
    }
}

// Emit the KAMA_*_{TYPE,FUNCS}(...) macro line per registered instantiation.
// An allocator-aware INTERFACE smart ptr (M11d) whose fat handle embeds `A alloc` BY VALUE — so, like
// `Fixed<T,N>`, its TYPE typedef must be laid out AFTER the allocator struct (in unifiedStructOrder),
// not in the early collection-TYPE phase where the allocator is still an incomplete forward decl.
bool CEmitter::isIfaceAllocColl(const CollectionInfo& info) const
{
    return info.elemIsInterface && !info.allocType.empty() && info.allocType != "GlobalAllocator"
        && (info.kind == CollKind::Owned || info.kind == CollKind::Shared || info.kind == CollKind::Weak);
}

// Emit just the `_IFACE_ALLOC_TYPE` typedef for one such collection (called from the ordered struct-body
// pass, once the `A` struct is complete). The FUNCS half is emitted by emitIfaceAllocFuncs.
void CEmitter::emitIfaceAllocType(const CollectionInfo& info)
{
    const char* k = info.kind == CollKind::Owned ? "OWNED" : info.kind == CollKind::Shared ? "SHARED" : "WEAK";
    *_out << "KAMA_" << k << "_IFACE_ALLOC_TYPE(" << info.cName << ", " << info.elemClass << "_vtbl, "
          << info.allocType << ")\n";
}

// Can anything a `NAME` handle drops have a destructor? Only a kind that OWNS something can, and the
// contract's `for` clause says which kinds may implement it: a `for value` contract admits only values,
// which own nothing (`type value` cannot declare a `~dtor` at all), so its vtable's `__dtor` slot is NULL
// in every implementation and the drop has nothing to dispatch. The call is then omitted outright rather
// than marked proven — the most honest form of "the compiler can see through this slot" is C that does not
// contain the call. Any wider clause (`for resource`, `for value, resource`) keeps the dispatch, and with
// it the allocation fact that makes a no-heap region refuse the drop.
bool CEmitter::ifaceDropCanDispatch(const std::string& iface) const
{
    auto it = _interfaces.find(iface);
    if (it == _interfaces.end()) return true;              // unknown: assume it can
    const unsigned k = it->second.implKinds;
    return k == 0 || (k & ~(unsigned)IK_Value) != 0;       // 0 is "already diagnosed" — say nothing new
}

// The drop (and the handle ops beside it) for a smart pointer over a CONTRACT — `Owned<I>`, `Shared<I>`,
// `Weak<I>`, and their allocator-aware twins. `alloc` picks the twin: it frees through the handle's own
// `A` copy instead of `kama_free`.
//
// WRITTEN HERE RATHER THAN BY A RUNTIME MACRO, which is what `KAMA_OWNED_IFACE_FUNCS` and its five
// siblings used to do. The no-heap call graph is read back out of the emitted C (buildCallGraph), and a
// macro's body is not in it: the C says `KAMA_OWNED_IFACE_FUNCS(Owned_Shape)`, one token, with no `free`
// to see and no `vtbl->__dtor` to see. So dropping a polymorphic box in a `@noheap` region was provably
// safe according to an analysis that could not read the drop — `~Circle` freed a `DynamicArray` behind the
// slot and the build passed (tests/xfail/noheap_drop_contract_box*.kama, found planning KR-39). Emitting
// the same C makes the calls visible to the analysis by construction, which is the same reason the graph
// stopped being recorded per call site in 0.9.347. The macros are deleted; the runtime keeps the `_TYPE`
// halves, which declare structs and call nothing.
void CEmitter::emitIfaceHandleFuncs(CollectionInfo& info, bool alloc)
{
    const std::string& N = info.cName;
    const std::string A = info.allocType;
    // A block goes back with the layout it was allocated with — through the allocator the handle carries, or
    // the funnel. The object's layout comes from its vtable, and is read BEFORE the destructor ends its life.
    auto release = [&](const std::string& what, const std::string& size, const std::string& align) {
        return alloc ? (A + "__deallocate(&self->alloc, (void*)self->" + what + ", " + size + ", " + align + ")")
                     : ("kama_free(self->" + what + ", " + size + ", " + align + ")");
    };
    const bool dispatches = ifaceDropCanDispatch(info.elemClass);
    auto dropObj = [&](int d) {
        // `__vsize`/`__valign` are PROVEN slots: every one the compiler installs is a class's own `__vsize`/`__valign`,
        // which reads a field of the object's vtable and calls nothing — so they carry the marker the call graph reads.
        indent(d); *_out << "size_t __n = self->vtbl->__vsize ? KAMA_NOHEAP_SLOT(self->vtbl->__vsize)(self->obj) : self->vtbl->__size;\n";
        indent(d); *_out << "size_t __a = self->vtbl->__valign ? KAMA_NOHEAP_SLOT(self->vtbl->__valign)(self->obj) : self->vtbl->__align;\n";
        if (dispatches) {
            indent(d); *_out << "if (self->vtbl->__dtor) self->vtbl->__dtor(self->obj);\n";
        }
        indent(d); *_out << release("obj", "__n", "__a") << ";\n";
    };
    const std::string ctrlSize = "sizeof(kama_ctrl)", ctrlAlign = "_Alignof(kama_ctrl)";

    if (info.kind == CollKind::Owned) {
        *_out << "static inline void " << N << "__dtor(" << N << "* self) {\n";
        indent(1); *_out << "if (self->obj) {\n";
        dropObj(2);
        indent(2); *_out << "self->obj = NULL;\n";
        indent(1); *_out << "}\n}\n";
        return;
    }
    if (info.kind == CollKind::Shared) {
        // The last strong drop keeps `strong` at 1 while the pointee dtor runs, then releases it: dropping
        // the pointee can free a `Weak` back-edge into THIS same ctrl (a cycle), which would free the ctrl
        // early and leave the `weak == 0` test reading freed memory. See prelude shared.kama.
        *_out << "static inline void " << N << "__dtor(" << N << "* self) {\n";
        indent(1); *_out << "if (self->ctrl) {\n";
        indent(2); *_out << "if (self->ctrl->strong == 1) {\n";
        dropObj(3);
        indent(3); *_out << "self->ctrl->strong = 0;\n";
        indent(3); *_out << "if (self->ctrl->weak == 0) " << release("ctrl", ctrlSize, ctrlAlign) << ";\n";
        indent(2); *_out << "} else { self->ctrl->strong--; }\n";
        indent(2); *_out << "self->obj = NULL; self->ctrl = NULL;\n";
        indent(1); *_out << "}\n}\n";
        *_out << "static inline bool " << N << "__valid(" << N << "* self) { return self->obj != NULL; }\n";
        // `copy h` — a retained duplicate (strong++). The emitter spells every deep copy `NAME__copy(&x)`;
        // a fat handle's copy is a retain, exactly what the library `Shared<T>::copy` does for a thin one.
        *_out << "static inline " << N << " " << N << "__copy(" << N << "* self) { if (self->ctrl) "
              << "self->ctrl->strong++; return *self; }\n";
        if (!info.downgradeName.empty()) emitSharedToWeakDowngrade(info);
        return;
    }
    // Weak<I> — counts `weak`, never touches the concrete object. `__upgrade` must propagate `alloc`
    // into the Shared it returns, so the upgraded strong handle frees through the right
    // allocator (the `= {0}` init leaves them zeroed on the expired path).
    *_out << "static inline void " << N << "__dtor(" << N << "* self) {\n";
    indent(1); *_out << "if (self->ctrl) {\n";
    indent(2); *_out << "if (--self->ctrl->weak == 0 && self->ctrl->strong == 0) "
                     << release("ctrl", ctrlSize, ctrlAlign) << ";\n";
    indent(2); *_out << "self->obj = NULL; self->ctrl = NULL;\n";
    indent(1); *_out << "}\n}\n";
    *_out << "static inline bool " << N << "__expired(" << N << "* self) {\n";
    indent(1); *_out << "return self->ctrl == NULL || self->ctrl->strong == 0;\n}\n";
    const std::string& S = info.ifacePartner;
    *_out << "static inline " << S << " " << N << "__upgrade(" << N << "* self) {\n";
    indent(1); *_out << S << " s = {0};\n";
    indent(1); *_out << "if (self->ctrl && self->ctrl->strong > 0) {\n";
    indent(2); *_out << "self->ctrl->strong++; s.obj = self->obj; s.vtbl = self->vtbl; s.ctrl = self->ctrl;\n";
    if (alloc) { indent(2); *_out << "s.alloc = self->alloc;\n"; }
    indent(1); *_out << "} else { s.obj = NULL; s.vtbl = NULL; s.ctrl = NULL; }\n";
    indent(1); *_out << "return s;\n}\n";
    *_out << "static inline " << N << " " << N << "__copy(" << N << "* self) { if (self->ctrl) "
          << "self->ctrl->weak++; return *self; }\n";
    emitWeakTryUpgrade(info);
}

// Emit the allocator-aware half. Deferred until AFTER class prototypes (unlike the plain collection
// FUNCS at emitCollectionDefs) because the dtor calls `A__deallocate` — the allocator's method prototype
// isn't emitted until the prelude/class-prototype pass. (A library collection holding one of these frees
// its elements from a real function in the late body pass, so no ordering hazard there.)
void CEmitter::emitIfaceAllocFuncs(CollectionInfo& info)
{
    emitIfaceHandleFuncs(info, /*alloc=*/true);
}

// `typesOnly` picks the struct-typedef half (emitted before class struct bodies so a
// class may hold a collection/smart-ptr BY VALUE) vs the funcs half (after class
// prototypes, where element dtors are declared).
void CEmitter::emitCollectionDefs(bool typesOnly)
{
    // Iterate in registration (inner-first) order, not the map's alphabetical order: a collection's
    // dtor calls its element's dtor (`List<Shared<I>>` -> `Shared_I__dtor`), so the element's FUNCS
    // must be emitted first. Alphabetical order breaks e.g. `List_...` (emitted before `Shared_...`).
    for (const std::string& cName : _collectionOrder) {
        CollectionInfo& info = _collections[cName];
        // The iface-ALLOC variant embeds `A` by value + frees through `A__deallocate` -> both halves are
        // deferred: the TYPE to unifiedStructOrder (after A's struct), the FUNCS to after class prototypes
        // (after A's method protos). See emitIfaceAllocType / emitIfaceAllocFuncs.
        if (isIfaceAllocColl(info)) continue;
        // (A stateful allocator on an interface box — the fat handle carrying `A alloc`+`objsize` and
        // freeing through `A` — never reaches here: `isIfaceAllocColl` skipped it above, so its halves can
        // be ordered after the allocator's struct and prototypes. See emitIfaceAllocType/Funcs.)
        if (info.kind == CollKind::Owned && info.elemIsInterface) {
            // fat-element `Owned<I>` — the TYPE is the runtime's struct; the FUNCS half is written out
            // here so the drop's `vtbl->__dtor` and its free are C the call graph can read.
            if (typesOnly) *_out << "KAMA_OWNED_IFACE_TYPE(" << info.cName << ", " << info.elemClass << "_vtbl)\n";
            else           emitIfaceHandleFuncs(info, /*alloc=*/false);
        }
        else if (info.kind == CollKind::Shared && info.elemIsInterface) {
            // (a library `Rc<Shape>` — a Shared IFACE with a weak partner — also gets its `downgrade()`,
            // emitted by emitIfaceHandleFuncs beside the drop.)
            if (typesOnly) *_out << "KAMA_SHARED_IFACE_TYPE(" << info.cName << ", " << info.elemClass << "_vtbl)\n";
            else           emitIfaceHandleFuncs(info, /*alloc=*/false);
        }
        else if (info.kind == CollKind::Weak && info.elemIsInterface) {
            // The C `__upgrade` (-> the Shared partner) stays an internal helper; `tryUpgrade` wraps it.
            if (typesOnly) *_out << "KAMA_WEAK_IFACE_TYPE(" << info.cName << ", " << info.elemClass << "_vtbl)\n";
            else           emitIfaceHandleFuncs(info, /*alloc=*/false);
        }
        else if (info.kind == CollKind::Bindable) {
            // Fully type-erased — the signature drives only the invoke, not the layout. The drop is
            // written out (not a macro) for the reason emitIfaceHandleFuncs gives: it calls through the
            // `release` pointer, which the call graph must see. `release` rebuilds the SOURCE handle the
            // object was bound from and runs that handle's own destructor (emitBindableBind), so the
            // refcount, the virtual drop, the allocator and the block's size are each decided in exactly
            // one place — the owner — instead of being re-derived here, which is how this used to `free`
            // an arena block and hand a base-sized drop to a derived object.
            if (typesOnly) *_out << "KAMA_BINDABLE_TYPE(" << info.cName << ")\n";
            else {
                const std::string& N = info.cName;
                *_out << "static inline void " << N << "__dtor(" << N << "* self) {\n";
                indent(1); *_out << "if (self->release) self->release(self->obj, self->ctrl);   /* free fn: NULL, nothing to drop */\n";
                indent(1); *_out << "self->obj = NULL; self->ctrl = NULL; self->fn = NULL; self->release = NULL;\n";
                *_out << "}\n";
            }
        }
        else if (info.kind == CollKind::Fixed) {
            // Value array: `struct { T v[N]; }` + bounds-checked get/set/at/length/fill. It embeds T
            // by value, so its `_TYPE` is emitted in the by-value struct-body order (emitHeaderContent),
            // NOT in this early types pass — only the `_FUNCS` half comes from here.
            if (!typesOnly) {
                *_out << "KAMA_FIXED_FUNCS(" << info.elemCType << ", " << info.constValue
                     << ", " << info.cName << ")\n";
                emitFixedView(info);   // ...and the `View<T>` mint the macro cannot name
            }
        }
        else if (info.kind == CollKind::Simd) {
            // Lane batch: a `vector_size` typedef over a PRIMITIVE. Unlike a Fixed it embeds no struct,
            // so BOTH halves come from here — the `_TYPE` in the early pass (nothing can depend on it
            // being ordered after a struct body, because it never names one) and the `_FUNCS` after.
            if (typesOnly)
                *_out << "KAMA_SIMD_TYPE(" << info.elemCType << ", " << info.constValue
                     << ", " << info.cName << ")\n";
            else {
                *_out << "KAMA_SIMD_FUNCS(" << info.elemCType << ", " << info.constValue
                     << ", " << info.cName
                     << ", InlineArray_" << info.elemMangle << "_" << info.constValue << ")\n";
                *_out << "KAMA_SIMD_REDUCE(" << info.elemCType << ", " << info.constValue
                     << ", " << info.cName << ")\n";
                *_out << "KAMA_SIMD_CMP(" << info.elemCType << ", " << info.constValue
                     << ", " << info.cName
                     << ", Mask_" << info.elemMangle << "_" << info.constValue << ")\n";
                // Only a SIGNED INTEGER lane needs the overflow checkers. A float lane has no overflow
                // rule to obey (IEEE gives infinities, not a trap) and an unsigned one wraps by
                // definition at every width, so emitting them there would be dead code in every program.
                if (cNumSigned(info.elemCType) && !cNumFloat(info.elemCType))
                    *_out << "KAMA_SIMD_ICHK(" << info.elemCType << ", u" << info.elemCType
                         << ", " << info.constValue << ", " << info.cName << ")\n";
                // A FLOAT lane also gets `sqrt`/`floor`/`ceil`, from `kama_math.h` rather than the
                // freestanding runtime header: they need libm. The include is guarded and the functions
                // are static inline, so a program that never calls them pays only the `#include`; the
                // `<math.h>` record is what makes the driver append `-lm` on native (wasm bundles libm).
                // Emitted here, after emitIncludes, so it lands below `kama_runtime.h` in every TU.
                if (cNumFloat(info.elemCType)) {
                    const bool f32 = info.elemCType == "float";
                    *_out << "#include \"kama_math.h\"\n"
                          << "KAMA_SIMD_MATH(" << info.elemCType << ", " << info.constValue << ", " << info.cName
                          << ", " << (f32 ? "kama_sqrtf" : "kama_sqrt") << ", " << (f32 ? "kama_floorf" : "kama_floor")
                          << ", " << (f32 ? "kama_ceilf" : "kama_ceil") << ")\n";
                    _externedHeaders.insert("<math.h>");
                }
            }
        }
        else if (info.kind == CollKind::Mask) {
            // Same shape as a Simd — a bare vector typedef, both halves from here. Its `_FUNCS` names the
            // partner DATA vector (`select` hands one back), which `ifacePartner` carries.
            if (typesOnly)
                *_out << "KAMA_MASK_TYPE(" << info.elemCType << ", " << info.constValue
                     << ", " << info.cName << ")\n";
            else
                *_out << "KAMA_MASK_FUNCS(" << info.constValue << ", " << info.ifacePartner
                     << ", " << info.cName << ")\n";
        }
        else if (info.kind == CollKind::String) {
            // kama_string itself is predefined in the runtime header; only the `.find()` Optional wrapper
            // (which needs the program-specific Optional_usize struct) is emitted here, in the FUNCS phase.
            if (!typesOnly) emitStringFind(info);
        }
    }
    if (!_collections.empty()) *_out << "\n";
}

// If `ea` indexes a collection, fill coll (cName), recvExpr, idx; return true.
bool CEmitter::collectionElemAccess(ElementAccessNode* ea, std::string& coll,
                                    std::string& recvExpr, std::string& idx)
{
    if (!ea) return false;
    SharedExpression recv = ea->expression ? ea->expression
                                           : std::static_pointer_cast<ExpressionNode>(ea->identifier);
    if (!recv) return false;
    std::string cls = exprClass(recv);
    if (cls.empty() || !_classes.count(cls) || !_classes[cls].isIntrinsicColl) return false;
    coll     = _classes[cls].name;
    // A `Fixed<T,N>` knows its size at compile time, so a CONSTANT out-of-range index is a
    // compile-time error, not just a runtime trap (the safe-array payoff).
    SharedExpression idxExpr = (ea->expressionlist && !ea->expressionlist->empty())
                                   ? (*ea->expressionlist)[0] : SharedExpression();
    if (isFixedColl(cls) && idxExpr) {
        int64_t iv;
        if (constValue(idxExpr, iv) && (iv < 0 || iv >= _collections[cls].constValue))
            unsupported(("index " + std::to_string(iv) + " is out of bounds for `" + cls + "` (length "
                         + std::to_string(_collections[cls].constValue) + ")").c_str(), ea->line);
    }
    // The receiver is emitted as a PLACE (an lvalue): a plain name stays itself, but a nested index
    // (`m[i]` in `m[i][j]`) becomes `(*Outer__at(&m, i))` so `&recvExpr` is a real `T*`, not the
    // address of a by-value `__get` rvalue. This is what makes chained/field-write indexing valid C.
    recvExpr = emitPlace(recv);
    // `this` inside a `type intrinsic <collection>` impl body is `self` — ALREADY a pointer, not a
    // by-value lvalue. Every caller takes `&(recvExpr)`, so hand back the place `(*self)` → `&(*self)` == self
    // (without this, `this[i]` emits `__get(&self, i)`, indexing the pointer's own address — a string-key
    // `hash`/`equals` would read struct bytes, not content, and Map lookups would miss).
    if (dynamic_cast<ThisAccessNode*>(recv.get()))
        recvExpr = "(*" + recvExpr + ")";
    idx      = idxExpr ? emitExpression(idxExpr) : "0";
    return true;
}

// A C lvalue (place) for `e`: an indexed element lowers to `(*NAME__at(&recv, i))` via the
// bounds-checked place intrinsic (recursing through the receiver so nested `a[i][j]` chains stay
// valid — `&(*__at(...))` folds back to the `T*`). Everything else is already an lvalue.
std::string CEmitter::emitPlace(SharedExpression e)
{
    if (auto* ea = dynamic_cast<ElementAccessNode*>(e.get())) {
        std::string coll, recvExpr, idx;
        if (collectionElemAccess(ea, coll, recvExpr, idx))   // recvExpr is itself a place (recursive)
            return "(*" + coll + "__at((" + coll + "*)&(" + recvExpr + "), " + idx + "))";
        // A user place-returning `operator[]`: `a[i]` -> `(*Class__op_index(&(place of a), i))`.
        // The receiver is emitted as a place too, so a nested `m[i][j]` chains cleanly.
        SharedExpression recv = ea->expression ? ea->expression
                                               : std::static_pointer_cast<ExpressionNode>(ea->identifier);
        if (recv) if (MethodInfo* op = userIndexOp(exprClass(recv))) {
            std::string idxE = (ea->expressionlist && !ea->expressionlist->empty())
                                   ? emitExpression((*ea->expressionlist)[0]) : "0";
            // `this` is already `self` (a pointer) — pass it directly; any other lvalue's address is `&place`.
            // A receiver that is itself a READ-ONLY place (`o.stdout()[i]`) is a `T const*` in C; the
            // operator takes `T*` (the ABI-neutral rule — every write was already refused), so cast, as
            // method dispatch does for its receiver.
            const std::string ownerCls = exprClass(recv);
            std::string recvAddr = dynamic_cast<ThisAccessNode*>(recv.get())
                                       ? emitExpression(recv)
                                       : ((chainThroughConstPlace(recv) ? "(" + ownerCls + "*)" : std::string())
                                          + "&(" + emitPlace(recv) + ")");
            return "(*" + op->cName + "(" + recvAddr + ", " + idxE + "))";
        }
    }
    return emitExpression(e);
}

// The place-returning `operator[]` on `cls` or an ancestor (else null). `op_index` is registered with
// `isPlaceReturn` only for `ref T operator[]`.
MethodInfo* CEmitter::userIndexOp(const std::string& cls)
{
    if (cls.empty() || !_classes.count(cls)) return nullptr;
    ClassInfo* owner = nullptr;
    MethodInfo* mi = findMethod(&_classes[cls], "op_index", &owner);
    return (mi && mi->isOperator && mi->isPlaceReturn) ? mi : nullptr;
}

bool CEmitter::indexesUserOp(ElementAccessNode* ea)
{
    if (!ea) return false;
    SharedExpression recv = ea->expression ? ea->expression
                                           : std::static_pointer_cast<ExpressionNode>(ea->identifier);
    return recv && userIndexOp(exprClass(recv)) != nullptr;
}

// cType(typeNode) resolved in the type-substitution context of a generic-instance class `inCls` — so a
// method's `T`-typed return (e.g. `iterator()` -> `VecIter<T>`, `next()` -> `Optional<T>`) resolves to
// the concrete instance (`VecIter_int32` / `Optional_int32`). Mirrors computeDestructible's binding.
//
// A NON-generic class still has a home: its member signatures were written in its declaring file and
// name what THAT file imports. Rendering them under the caller's `_nsCtx` made `Uuid.parse(…)`'s
// `Result<Uuid, UuidError>` mangle against the consumer's imports, so a consumer that imported `Uuid` but
// not `UuidError` got an unknown `Result_…` and "`match` subject's type could not be resolved".
// (tests/ctor_result_foreign_err.d). Scope-less infos (prelude, intrinsic collections) keep the plain path.
std::string CEmitter::cTypeInInstance(const std::string& inCls, SharedIdentifier typeNode)
{
    if (!_genericTypeInsts.count(inCls)) {
        auto ci = _classes.find(inCls);
        if (ci == _classes.end() || ci->second.isIntrinsicColl) return cType(typeNode);
        // The declaring file's WHOLE context — names, unit path, private scope, export list — exactly as
        // its own bodies were judged. `enterClassCtx` rebuilds only the name half and leaves `unitPath`
        // empty, and the visibility check then judged every reference as coming from nowhere: a generic
        // `json::deserializeJsonBuffer::<Point>` reached a test file's own unexported `Point` and was
        // refused under `kama check`. No such file (the prelude, a synthesized type) keeps the plain path.
        const NsCtx* home = nullptr;
        for (auto& kv : _unitCtx) if (kv.second.unitPath == ci->second.declFile) { home = &kv.second; break; }
        if (!home || ci->second.declFile.empty()) return cType(typeNode);
        NsCtx savedCtx = _nsCtx;
        _nsCtx = *home;
        ScopedStr _cu(_collectingUnitPath, ci->second.declFile);
        std::string r = cType(typeNode);
        _nsCtx = savedCtx;
        return r;
    }
    auto savedSubst = _typeSubst; NsCtx savedCtx = _nsCtx;
    const GenericTypeInst& gi = _genericTypeInsts[inCls];
    _nsCtx = _genericTypeInstCtx.count(inCls) ? _genericTypeInstCtx[inCls] : _genericTypeCtx[gi.templateKey];
    _typeSubst.clear();
    const std::vector<std::string>& ps = _genericTypeParams[gi.templateKey];
    for (size_t i = 0; i < ps.size() && i < gi.typeArgs.size(); ++i) _typeSubst[ps[i]] = gi.typeArgs[i];
    std::string r = cType(typeNode);
    _typeSubst = savedSubst; _nsCtx = savedCtx;
    return r;
}

// `deepSubstType(typeNode)` in the type-substitution context of a generic-instance class `inCls` — the
// NODE-returning twin of cTypeInInstance, for the callers that need the substituted type node rather
// than its C spelling (a `match` payload's declared type, which is then classified and containment-checked).
//
// It exists so the binding can be SCOPED TO THE RESOLUTION instead of held open across a whole
// construct. `emitMatchSwitch` used to bind the subject enum's args for the entire switch, on the stated
// grounds that "arm bodies contain no `T`" — which is false the moment the `match` sits inside a generic
// type's method or a generic free function, where the arm body's `T` is the ENCLOSING scope's and the
// binding had replaced it. Three payload resolutions needed it; the arm bodies never did.
SharedIdentifier CEmitter::deepSubstInInstance(const std::string& inCls, SharedIdentifier typeNode)
{
    if (!_genericTypeInsts.count(inCls)) return deepSubstType(typeNode);   // non-generic: plain
    auto savedSubst = _typeSubst; NsCtx savedCtx = _nsCtx;
    const GenericTypeInst& gi = _genericTypeInsts[inCls];
    _nsCtx = _genericTypeInstCtx.count(inCls) ? _genericTypeInstCtx[inCls] : _genericTypeCtx[gi.templateKey];
    _typeSubst.clear();
    const std::vector<std::string>& ps = _genericTypeParams[gi.templateKey];
    for (size_t i = 0; i < ps.size() && i < gi.typeArgs.size(); ++i) _typeSubst[ps[i]] = gi.typeArgs[i];
    SharedIdentifier r = deepSubstType(typeNode);
    _typeSubst = savedSubst; _nsCtx = savedCtx;
    return r;
}

// `foreach` over a user type via the ITERATOR PROTOCOL (structural, zero-cost — direct monomorphized
// calls, no vtable). VALUE (`foreach (T x in v)`): `v.iterator()` yields an iterator with
// `next() -> Optional<T>` (or `v` itself is the iterator); loop while `next()` returns `Some`. MUTABLE
// (`foreach (ref T x in v)`): `v.iterMut()` yields an iterator with `hasNext()` + a place-returning
// `next()`; loop while `hasNext()`, binding `x` to the place. A borrowing iterator holds an `UnsafePtr` cursor
// (its own unsafe internals); the `foreach` surface stays safe.
void CEmitter::emitForeachIterator(ForEachNode* fe, const std::string& container, int depth)
{
    ClassInfo* cc = &_classes[container];
    std::string nm = (fe->name && fe->name->value) ? *fe->name->value : "__x";
    std::string elemTy = cType(fe->type);
    std::string elemClass = isClass(elemTy) ? elemTy : "";   // for `x.method()` resolution
    int id = _tempCounter++;
    std::string it = "__it" + std::to_string(id);
    std::string ot = "__o"  + std::to_string(id);
    // Emit the iterable expression WITH a hoist slot: an owned rvalue operand of a compiler iterator (the
    // receiver of `s.trim().chars()`, the separator of `x.split(a + b)`) materializes into a scope-dtor'd
    // temp that must live for the whole loop. `outerPre` marks the enclosing scope's locals before that
    // materialization so we can relocate those temps into the loop wrapper (declared before the iterator,
    // dropped after the loop) below — the A4 receiver-materialize pattern.
    size_t outerPre = _scopes.empty() ? 0 : _scopes.back().locals.size();
    auto emitIterable = [&]() -> std::string {
        bool ph = _hoistOK; _hoistOK = true;
        std::string r = emitExpression(fe->expression);
        _hoistOK = ph;
        return r;
    };

    // Resolve the iterator + method C-names (structural). `iterCall`/`nextCall`/`hasNextCall` are the
    // full direct calls; `iterCType`/`optC` the concrete types.
    // Calling `iterator()`/`iterMut()` on the operand takes its ADDRESS, so the operand has to BE
    // somewhere. An rvalue is not: `foreach (x in d.view())` emitted `&(std__collections__View_int32){…}`
    // and clang rejected generated C the author never wrote — a build error where `kama check` said the
    // file was clean, which is the one disagreement run_tests.sh guards against most sharply.
    //
    // Only this branch is affected. An operand that IS its own iterator (`"ab".chars()`, `m.valuesMut()`)
    // is copied into `__it` by value and stays legal, which is why the check cannot live at the top.
    auto requirePlaceOperand = [&]() -> bool {
        if (!placePath(fe->expression).empty()) return true;
        const bool isView = isViewCType(container);
        unsupported((isView
            ? "a `foreach` over a view needs a named window — a view minted straight into the loop header "
              "has nowhere to live and nothing holding its buffer still. Write `borrow "
              "<container>.<mint>() as v { foreach (… in v) { … } }`"
            : ("`foreach` needs somewhere to iterate FROM, and `" + container + "` here is a temporary "
               "with no home — bind it to a local first (`" + container + " xs = …;`), then iterate that")
                  .c_str()), fe->line);
        *_out << "\n";
        return false;
    };

    std::string iterCType, iterInit, nextCall, hasNextCall, optC;
    // What the iterator ACTUALLY yields, as opposed to what the loop binding claims. Both branches fill
    // it; the mismatch check below is the same rule the intrinsic-collection path enforces.
    std::string actualElem;
    if (fe->isRef) {
        // Mirror the by-value branch: a container hands out a mutable iterator via `iterMut()`, OR the operand
        // IS its own mutable iterator (implements `IteratorMut` directly) and is iterated by value — the latter
        // lets an rvalue operand (`m.valuesMut()`) work, exactly as `s.chars()` does for the by-value form.
        // The read-only window has no writable iteration to offer, and "must `implements IterableMut<T>`"
        // would be true and useless — the remedy is the other half of the pair, not a conformance.
        if (isConstViewCType(container)) {
            unsupported("a `ConstView<T>` is read-only, so it has no `foreach (ref …)` — a `ref` binding is a "
                        "writable place. Iterate it by value, or take the writable window (`viewMut()`) "
                        "where the view was made", fe->line); *_out << "\n"; return;
        }
        MethodInfo* iterMi = findMethod(cc, "iterMut", nullptr);
        if (iterMi && !iterMi->params.empty()) iterMi = nullptr;
        ClassInfo* ic = nullptr;
        if (iterMi) {
            if (!implementsContractTemplate(cc, "IterableMut")) {   // nominal: the container must declare it
                unsupported(("`" + container + "` must `implements IterableMut<T>` to be used in a "
                             "`foreach (ref …)`").c_str(), fe->line); *_out << "\n"; return;
            }
            if (!requirePlaceOperand()) return;
            iterCType = cTypeInInstance(container, iterMi->returnType);
            ic = _classes.count(iterCType) ? &_classes[iterCType] : nullptr;
            iterInit = iterMi->cName + "(&(" + emitIterable() + "))";
        } else {   // the operand IS the mutable iterator (used by value — an rvalue materializes into `__it`)
            iterCType = container; ic = cc;
            iterInit = emitIterable();
        }
        MethodInfo* hasNextMi = ic ? findMethod(ic, "hasNext", nullptr) : nullptr;
        MethodInfo* nextMi    = ic ? findMethod(ic, "next", nullptr) : nullptr;
        if (!hasNextMi || !nextMi || !nextMi->isPlaceReturn) {
            unsupported(("a mutable iterator (`" + iterCType + "`) needs `hasNext()` and a "
                         "place-returning `ref T next()`").c_str(), fe->line); *_out << "\n"; return;
        }
        if (!implementsContractTemplate(ic, "IteratorMut")) {   // nominal: it must declare the protocol
            unsupported(("the mutable iterator `" + iterCType + "` must `implements IteratorMut<T>` "
                         "to be used in a `foreach (ref …)`").c_str(), fe->line); *_out << "\n"; return;
        }
        hasNextCall = hasNextMi->cName + "(&" + it + ")";
        nextCall    = nextMi->cName + "(&" + it + ")";
        actualElem  = cTypeInInstance(iterCType, nextMi->returnType);   // `ref T next()` -> T
    } else {
        MethodInfo* iterMi = findMethod(cc, "iterator", nullptr);
        if (iterMi && !iterMi->params.empty()) iterMi = nullptr;
        ClassInfo* ic = nullptr;
        if (iterMi) { if (!requirePlaceOperand()) return;
                      iterCType = cTypeInInstance(container, iterMi->returnType);
                      ic = _classes.count(iterCType) ? &_classes[iterCType] : nullptr;
                      iterInit = iterMi->cName + "(&(" + emitIterable() + "))";
                      if (!implementsContractTemplate(cc, "Iterable")) {   // nominal: the container declares it
                          unsupported(("`" + container + "` must `implements Iterable<T>` to be used in a "
                                       "`foreach`").c_str(), fe->line); *_out << "\n"; return;
                      } }
        else        { iterCType = container; ic = cc;                       // the container IS the iterator
                      iterInit = emitIterable(); }                          // (needs only Iterator<T>, below)
        MethodInfo* nextMi = ic ? findMethod(ic, "next", nullptr) : nullptr;
        if (!nextMi || !nextMi->params.empty()) {
            unsupported(("`foreach` over `" + container + "` needs a nullary `iterator()`, or a nullary "
                         "`next()` returning `Optional<T>`").c_str(), fe->line); *_out << "\n"; return;
        }
        if (!implementsContractTemplate(ic, "Iterator")) {   // nominal: it must declare the protocol
            unsupported(("the iterator `" + iterCType + "` must `implements Iterator<T>` to be used "
                         "in a `foreach`").c_str(), fe->line); *_out << "\n"; return;
        }
        optC     = cTypeInInstance(iterCType, nextMi->returnType);
        nextCall = nextMi->cName + "(&" + it + ")";
        // `Optional<T> next()` -> T, read off the monomorphized Optional's `Some` payload rather than
        // re-deriving it from the return type's generic argument: this is the very field the binding is
        // initialized from two lines down (`__o.u.Some.value`), so it cannot disagree with what is emitted.
        if (_classes.count(optC))
            for (const auto& vc : _classes[optC].variants)
                if (vc.name == "Some" && vc.payload.size() == 1)
                    actualElem = cTypeInInstance(optC, vc.payload[0].type);
    }

    // Same rule as the intrinsic-collection path: the DECLARED element type must be what the iterator
    // yields. Without it the payload was assigned straight into the binding and C's implicit conversions
    // did the rest — `foreach (bool v in someInt32Array)` compiled to `bool v = __o.u.Some.value;`, so
    // every non-zero element silently became `true`. Skipped when actualElem could not be determined, so
    // an iterator shape this does not understand keeps working rather than becoming an error.
    if (!actualElem.empty() && actualElem != elemTy) {
        std::string msg = "foreach element type does not match what the iterator yields (binding is `"
                        + elemTy + "`, elements are `" + actualElem + "`)";
        unsupported(msg.c_str(), fe->line);
        *_out << "\n";
        return;
    }

    // Outer wrapper: the iterator, then the loop. All calls are direct (monomorphized), no vtable.
    *_out << "{\n";
    // Relocate any owned-iterable operand temps materialized by emitIterable (e.g. `s.trim()` for
    // `.chars()`) into a WRAPPER scope: declared before the iterator (they back its borrowed bytes) and
    // dropped AFTER the loop (the iterator borrows them for every iteration). Recorded in the enclosing
    // scope by hoistStringTemp; move the delta here so declaration + drop share the wrapper block.
    Scope wrap;
    if (!_scopes.empty() && _scopes.back().locals.size() > outerPre) {
        wrap.locals.assign(_scopes.back().locals.begin() + outerPre, _scopes.back().locals.end());
        _scopes.back().locals.resize(outerPre);
    }
    _scopes.push_back(wrap);
    flushHoisted(depth + 1);   // declare the relocated iterable temps before the iterator line
    indent(depth + 1); *_out << iterCType << " " << it << " = " << iterInit << ";\n";
    indent(depth + 1); *_out << "while (" << (fe->isRef ? hasNextCall : std::string("1")) << ") {\n";

    Scope sc; sc.isLoopBoundary = true;
    // A `foreach` IS a window: it holds a borrowing iterator over its operand for the extent of the body,
    // which is exactly what `borrow` does — it just names the ELEMENTS instead of the view. So the operand
    // is frozen for the body, and `foreach (x in d) { d.add(…) }` becomes a compile error rather than the
    // runtime panic the mods counter raises. The counter stays as depth, but the mistake is now unnameable
    // rather than merely trapped, which is the whole point of the window.
    //
    // The operand's PLACE, so a disjoint sibling stays mutable — `foreach (x in this.buf) { this.hits = … }`
    // is legal for the same reason it is legal inside a `borrow`.
    {
        std::vector<std::string> op = viewRootPlace(fe->expression);   // roots `m.values()` at `m`, not at nothing
        if (!op.empty()) sc.frozen.push_back({ op, nm, fe->line, /*fromBorrow=*/false });
    }
    _scopes.push_back(sc);
    registerBinding(fe->name.get(), SymKind::Local);   // LSP index (the loop variable)
    noteScopedBinding(nm);   // the loop scope owns the binding — see the indexed path
    hideShadowedLocal(nm, fe->isRef);
    _localTypes[nm] = elemClass;
    if (fe->type) _localTypeNodes[nm] = fe->type;   // element kama type node (char vs uint32 for interpolation)
    if (fe->isRef) {
        _refParams.insert(nm);   // reads/writes deref the place, like a `ref` param / built-in `foreach ref`
        indent(depth + 2); *_out << elemTy << "* " << nm << " = " << nextCall << ";\n";
    } else {
        indent(depth + 2); *_out << optC << " " << ot << " = " << nextCall << ";\n";
        indent(depth + 2); *_out << "if (" << ot << ".tag == " << optC << "_None) break;\n";
        indent(depth + 2); *_out << elemTy << " " << nm << " = " << ot << ".u.Some.value;\n";
        // A destructible by-value element that the binding OWNS must RAII-drop each iteration, else it
        // leaks — but only if `next()` yields a FRESH owned value. The compiler-provided `Split` iterator
        // does. `Iterator<T>` yields BY VALUE (a copy — SPEC), so the binding OWNS a destructible element
        // and must drop it each iteration. This is sound because a `next()` returning an owning value into
        // its `Optional<T>` must hand it off with `give`/`copy` (a bare named payload is rejected at variant
        // construction), so the yield is always a fresh/owned value, never an alias the iterator still owns.
        if (_classes.count(elemTy) && _classes[elemTy].destructible)
            recordDestructibleLocal(nm, elemTy);
    }
    SharedStatement last;
    if (auto* b = dynamic_cast<BlockNode*>(fe->body.get())) {
        if (b->statements) for (auto& st : *b->statements) { emitStatement(st, depth + 2); last = st; }
    } else if (fe->body) {
        emitStatement(fe->body, depth + 2); last = fe->body;
    }
    if (!(last && stmtIsJump(last))) emitScopeCleanup(_scopes.back(), depth + 2);
    popScope();   // retires the binding

    indent(depth + 1); *_out << "}\n";   // close while
    emitScopeCleanup(_scopes.back(), depth + 1);   // drop relocated iterable temps (e.g. `s.trim()`) after the loop
    popScope();                                    // wrapper scope
    indent(depth);     *_out << "}\n";   // close wrapper
}

// A fixed-array value literal (`[a, b, c]` or `[v; N]`) initializing a `Fixed<T,N>`. Its type comes
// from the enclosing typed position (a Fixed local, return, or assignment, threaded via the same
// target-type context as `match`/variant construction). List form -> a C99 compound literal over the
// backing array (`(NAME){ .v = { … } }`, count checked == N); fill form -> the runtime `NAME__fill(v)`.
std::string CEmitter::emitArrayLiteral(ArrayLiteralNode* al)
{
    if (!al) return "0";
    // An array literal builds either shape of 16-byte value aggregate — an `InlineArray<T,N>` or a
    // `Simd<T,N>`. One spelling for "N values of T, written out", which is what GOALS asks for; the
    // difference is only in what C the two lower to, at the two `isSimd` branches below.
    auto isAggr = [&](const std::string& t) { return isFixedColl(t) || isSimdColl(t); };
    std::string ty = _variantTargetType;
    if (!isAggr(ty)) ty = _matchTargetCType;
    if (!isAggr(ty)) {
        unsupported("an array literal `[…]` initializes an `InlineArray<T>#(N)` or a `Simd<T>#(N)` — its "
                    "type must be known from context (a typed local, return, or assignment)", al->line);
        return "0";
    }
    const bool isSimd = isSimdColl(ty);
    int64_t n = _collections[ty].constValue;
    // Each element's target type is the Fixed's element type — so a NESTED array literal
    // (`Fixed<Fixed<int32,2>,2> = [[1,2],[3,4]]`) resolves each inner `[…]` to the element Fixed.
    std::string elemCType = _collections[ty].elemCType;
    ScopedStr _tm(_matchTargetCType, elemCType), _tv(_variantTargetType, elemCType);
    if (al->elements) {
        size_t count = al->elements->size();
        if ((int64_t)count != n) {
            unsupported(("this array literal has " + std::to_string(count) + " element(s) but `" + ty
                         + "` holds " + std::to_string(n)).c_str(), al->line);
            return "0";
        }
        // A Fixed is `struct { T v[N]; }`, so its compound literal designates `.v`; a Simd is a bare
        // vector typedef with no member to designate. Same braces either side of that.
        std::string s = isSimd ? ("(" + ty + "){") : ("(" + ty + "){ .v = {");
        // Each element by value — an inline constructor element (`[Point(x:1,y:2), …]`) is
        // materialized into a hoisted temp (ISO C, no statement-expression), like an operator operand.
        for (size_t i = 0; i < al->elements->size(); ++i)
            s += (i ? ", " : " ") + emitOperandByValue((*al->elements)[i]);
        s += isSimd ? " }" : " } }";
        return s;
    }
    // fill form `[v; count]` — the count must be a constant equal to N.
    int64_t fc;
    if (!constValue(al->fillCount, fc)) {
        unsupported("the count in a fill literal `[v; N]` must be an integer constant", al->line);
        return "0";
    }
    if (fc != n) {
        unsupported(("this fill literal repeats " + std::to_string(fc) + " time(s) but `" + ty
                     + "` holds " + std::to_string(n)).c_str(), al->line);
        return "0";
    }
    // `[v; N]` on a lane batch IS a splat — the same literal, and the operation every SIMD API names
    // separately. One spelling covers both because they mean the same thing: N copies of one value.
    return ty + (isSimd ? "__splat(" : "__fill(") + emitOperandByValue(al->fillValue) + ")";
}

// ---- Smart pointers (Owned, Shared) ---------------------------------------

bool CEmitter::isSmartPtrClass(const std::string& cls) const
{
    auto it = _classes.find(cls);
    return it != _classes.end() && it->second.isIntrinsicColl &&
           (it->second.collKind == CollKind::Owned || it->second.collKind == CollKind::Shared ||
            it->second.collKind == CollKind::Weak);
}

CollKind CEmitter::smartKind(const std::string& cls) const
{
    return _classes.at(cls).collKind;   // precondition: isSmartPtrClass(cls)
}

// The pointee's C class for a `Shared<X>` — the LIBRARY generic instance (whose element rides its type
// args) or the interface-erased intrinsic (whose element is recorded on the ClassInfo). "" for anything
// else. Both shapes exist and only one of them carries `collElemClass`, which is why asking the ClassInfo
// alone answered "" for every concrete `Shared<Node>`.
// The pointee's C class for an `Owned<X>` — a library generic instance over a concrete pointee, "" for
// anything else. An `Owned` is a unique subtree, so on the wire it IS its pointee; this is what lets a
// CONTAINER of them satisfy its own `when [T: Serializable]` gate with no library change.
std::string CEmitter::ownedPointeeClass(const std::string& cls)
{
    auto g = _genericTypeInstOf.find(cls);
    if (g == _genericTypeInstOf.end() || g->second != _ownedTmpl) return "";
    auto gi = _genericTypeInsts.find(cls);
    if (gi != _genericTypeInsts.end() && !gi->second.typeArgs.empty()) return cType(gi->second.typeArgs[0]);
    return "";
}

std::string CEmitter::sharedPointeeClass(const std::string& cls)
{
    auto g = _genericTypeInstOf.find(cls);
    if (g != _genericTypeInstOf.end() && g->second == _sharedTmpl) {
        auto gi = _genericTypeInsts.find(cls);
        if (gi != _genericTypeInsts.end() && !gi->second.typeArgs.empty()) return cType(gi->second.typeArgs[0]);
        return "";
    }
    if (isSmartPtrClass(cls) && smartKind(cls) == CollKind::Shared) {
        auto it = _classes.find(cls);
        return it == _classes.end() ? std::string() : it->second.collElemClass;
    }
    return "";
}

bool CEmitter::derefSmartPtr(std::string& cls, std::string& recvExpr)
{
    if (!isSmartPtrClass(cls)) return false;
    recvExpr = "(" + recvExpr + ").ptr";        // both Owned & Shared expose a T*
    cls      = _classes[cls].collElemClass;     // effective class = pointee T
    return true;
}

bool CEmitter::isSmartPtrExpr(SharedExpression e)
{
    return e && isSmartPtrClass(exprClass(e));
}

// A "named value" is an existing binding you can hand off (a variable / field /
// element / base member) — as opposed to a FRESH rvalue (a `new`/constructor, a
// call result, a literal), which is consumed in place and never needs a marker.
bool CEmitter::isNamedValue(ASTNode* e)
{
    if (dynamic_cast<MemberAccessNode*>(e) || dynamic_cast<ElementAccessNode*>(e)
        || dynamic_cast<BaseAccessNode*>(e)) return true;
    // A place-returning call (`m.getRef(k)`, `b.at(i: 0)`, `pick(d: d, i: 0)`) NAMES storage the callee
    // still owns — it is an element reached through a method, not a fresh result — so `addr(of:)` may take
    // its address and `give`/`copy` reach the same rules an element does (a `const ref` place refuses the
    // move; a writable one is "out of a field/element").
    if (auto* inv = dynamic_cast<InvocationNode*>(e)) return invocationReturnsPlace(inv);
    // `this` inside a ctor names the value under construction — real storage the ctor owns and hands
    // out, so `give this` is a move like any other. (In a METHOD `this` is a borrowed receiver, and
    // moving out of it is exactly what the caller must not be able to do.)
    if (_inNamedCtorBody && dynamic_cast<ThisAccessNode*>(e)) return true;
    if (auto* id = dynamic_cast<IdentifierNode*>(e)) {
        // a `::`-scope-resolved enum member / variant construction (`Color::Blue`, `Box::Empty`)
        // is a FRESH rvalue, not a movable named lvalue. Distinguish it from an object access
        // `obj.field` (also a qualified IdentifierNode) by the qualifier head: a local/current-class
        // field head is an object; a type/namespace head is scope resolution.
        if (id->qualifier && !id->qualifier->empty()) {
            const std::string& head = *(*id->qualifier)[0];
            if (_localTypes.count(head)) return true;                        // obj.field…
            if (_currentClass && findFieldOwner(_currentClass, head)) return true;
            auto q = std::make_shared<StringList>();
            for (size_t i = 0; i + 1 < id->qualifier->size(); ++i) q->push_back((*id->qualifier)[i]);
            std::string en = resolveUserName(*id->qualifier->back(), q);
            if (_enums.count(en)) return false;                              // enum member
            auto c = _classes.find(en);
            if (c != _classes.end() && c->second.isVariant) return false;    // variant construction
            if (_genericTypeParams.count(en) || _genericTypes.count(en))     // generic union: Optional::None
                return false;
        }
        return true;
    }
    return false;
}

// an interface value borrows its object, so it's a second-class view — it may
// be a parameter or local, but it can't be STORED beyond the call that produced it
// (a field, a return, a collection element) without dangling. Reject the bare-interface
// case with guidance toward owning the object (`Shared<I>` — enables that).
void CEmitter::rejectStoredInterface(SharedIdentifier ty, const char* whereClause, int line, bool alsoView)
{
    if (!ty) return;
    rejectMintProtocolValue(ty, whereClause, line);
    std::string ct = cType(ty);
    bool iface = isInterface(ct);
    // A `type view` is also a non-escaping borrow — reject it as a FIELD (alsoView), but NOT as a
    // return (a view MAY be returned when it borrows `this`/a `ref` param; that's checked per-ReturnNode).
    bool view  = false;
    if (alsoView && !iface) { auto it = _classes.find(ct); view = it != _classes.end() && it->second.isBorrow; }
    if (!iface && !view) return;
    std::string nm = (ty->value && !ty->value->empty()) ? *ty->value : ct;
    if (iface)
        unsupported(("a contract (`" + nm + "`) borrows its object, so it can't be " + whereClause
                     + " — it would dangle; own the object instead (e.g. `Shared<" + nm + ">`)").c_str(), line);
    else
        unsupported(("a view (`" + nm + "`) borrows its buffer, so it can't be " + whereClause
                     + " — it would dangle; copy the elements into an owning `DynamicArray` instead").c_str(), line);
}

// A plain transferable lvalue: a bare identifier naming a smart-pointer local/
// param. A `new ...<T>(...)` initializer is NOT an lvalue (no source to touch).
bool CEmitter::isSmartPtrLValue(SharedExpression e)
{
    auto* id = dynamic_cast<IdentifierNode*>(e.get());
    return id && id->value && isSmartPtrExpr(e);
}

// Is `src` a concrete-element owning handle being widened into the contract-element
// intrinsic `dstTy`? True iff dst is an intrinsic smart-ptr over an INTERFACE, src is a
// named library heap-owner (`Shared`/`Owned`) whose concrete pointee nominally implements
// that interface, and the ownership KIND matches (library `Shared`(copyable)↔intrinsic
// `Shared`; library `Owned`↔intrinsic `Owned`). A `Weak` or a contract→contract source
// (not a library heap-owner) is not handled here.
bool CEmitter::isSmartPtrUpcast(const std::string& dstTy, SharedExpression src)
{
    if (!isSmartPtrClass(dstTy) || !isInterface(_classes[dstTy].collElemClass)) return false;
    if (!src || !isNamedValue(src.get())) return false;
    std::string libT = heapOwnerTarget(exprClass(src));         // concrete pointee ("" if not a library owner)
    if (libT.empty()) return false;
    auto it = _classes.find(libT);
    if (it == _classes.end()) return false;
    const std::string& dstElem = _classes[dstTy].collElemClass; // interface C name
    bool implementsIt = false;
    for (auto& i : it->second.interfaces) if (i == dstElem) { implementsIt = true; break; }
    if (!implementsIt) return false;
    // kind must agree: a copyable library owner is a `Shared`, a move-only one an `Owned`.
    CollKind dk = smartKind(dstTy);
    return isCopyable(exprClass(src)) ? (dk == CollKind::Shared) : (dk == CollKind::Owned);
}

// Emit the upcast field-bridge into the already-declared intrinsic handle `nm`. Mirrors the
// library→intrinsic bridge in emitBindableBind: the pointee via `deref()`, the concrete's
// `__as_<Contract>` vtable, and (Shared/Weak) the shared `kama_ctrl` block. Retains a
// `Shared` (strong++) or moves an `Owned` (suppress the library source's dtor). Precondition:
// isSmartPtrUpcast(dstTy, src).
void CEmitter::emitSmartPtrUpcast(const std::string& nm, const std::string& dstTy,
                                  SharedExpression src, int handoff, int depth, int line)
{
    std::string srcCls  = exprClass(src);
    std::string libT    = heapOwnerTarget(srcCls);              // concrete pointee C name
    const std::string& dstElem = _classes[dstTy].collElemClass; // interface C name
    CollKind dk = smartKind(dstTy);
    // give/copy on an upcast follows the same matrix as a same-type hand-off: `give` MOVES the
    // handle (every kind is movable), `copy` RETAINS (an `Owned` can't be copied — it's unique),
    // bare defaults to the source's nature (a `Shared`/`Weak` retains, an `Owned` moves).
    bool copyable = isCopyable(srcCls);
    bool retain = (handoff == 1) ? false : (handoff == 2 ? true : copyable);
    if (handoff == 2 && !copyable)
        unsupported("an `Owned` is unique — it can't be `copy`'d; use `give` to move it", line);
    std::string srcE = emitExpression(src);
    // pointee: a library owner exposes it via `deref()` (T*); the concrete's per-contract vtable
    // fattens it. The refcount block is the library `.c` (kama_ctrl-compatible), shared with the source.
    indent(depth); *_out << nm << ".obj = (void*)" << derefFnName(srcCls, true) << "(&(" << srcE << "));\n";
    indent(depth); *_out << nm << ".vtbl = &" << libT << "__as_" << dstElem << ";\n";
    if (dk != CollKind::Owned) {                                // intrinsic Owned<I> is {obj, vtbl} — no ctrl
        indent(depth); *_out << nm << ".ctrl = (kama_ctrl*)(" << srcE << ").c;\n";
        if (retain) { indent(depth); *_out << "if (" << nm << ".ctrl) " << nm << ".ctrl->"
                                            << (dk == CollKind::Weak ? "weak" : "strong") << "++;\n"; }
    }
    // A stateful-allocator dst (M11d): carry the concrete source's own `alloc` value into the fat handle, so
    // the iface box frees obj/ctrl through the SAME allocator the source used. (The object's layout needs no
    // carrying: the vtable reports it, a derived object's included.)
    std::string dstAlloc = _collections.count(dstTy) ? _collections[dstTy].allocType : "";
    if (!dstAlloc.empty() && dstAlloc != "GlobalAllocator") {
        indent(depth); *_out << nm << ".alloc = (" << srcE << ").alloc;\n";
    }
    // move (bare `Owned`, or `give`): consume the source at compile time so its dtor is skipped —
    // the destination handle now owns the ref (it shares the same ctrl without an increment).
    if (!retain) { std::string mv = moveOnlySource(src, line); if (!mv.empty()) markMoved(mv); }
}

// Is `src` a derived-class handle being widened into the base-class handle `dstTy`? Both are
// thin library `Shared`/`Owned` structs; the pointee is a `virtual class` (so it has a virtual
// destructor). True iff both are library owners of the same kind and dst's pointee is a base of
// src's pointee.
bool CEmitter::isSmartPtrBaseUpcast(const std::string& dstTy, SharedExpression src)
{
    if (!src || !isNamedValue(src.get())) return false;
    std::string baseT = heapOwnerTarget(dstTy);                // dst pointee ("" if not a library owner)
    if (baseT.empty()) return false;
    std::string derivedT = heapOwnerTarget(exprClass(src));    // src pointee
    if (derivedT.empty() || baseT == derivedT) return false;
    if (!isBaseOf(baseT, derivedT)) return false;
    return isCopyable(dstTy) == isCopyable(exprClass(src));     // both Shared, or both Owned
}

// Emit the base upcast into the already-declared handle `nm`. Builds it through the library's own
// ctor/`adopt` (so the dest fields aren't poked directly), with the pointer adjusted to the base
// subobject via the `__base` chain (offset 0 in Kama's single-vptr model). A `Shared` retains
// (shares the ctrl, strong++); an `Owned` moves (source consumed). Precondition: isSmartPtrBaseUpcast.
void CEmitter::emitSmartPtrBaseUpcast(const std::string& nm, const std::string& dstTy,
                                      SharedExpression src, int handoff, int depth, int line)
{
    std::string srcCls   = exprClass(src);
    std::string baseT    = heapOwnerTarget(dstTy);
    std::string derivedT = heapOwnerTarget(srcCls);
    // Same give/copy matrix as a same-type hand-off: `give` MOVES, `copy` RETAINS (`Owned` can't
    // be copied), bare defaults to the source's nature (`Shared`/`Weak` retain, `Owned` move).
    bool copyable = isCopyable(srcCls);
    bool retain = (handoff == 1) ? false : (handoff == 2 ? true : copyable);
    if (handoff == 2 && !copyable)
        unsupported("an `Owned` is unique — it can't be `copy`'d; use `give` to move it", line);
    std::string srcE = emitExpression(src);
    // base-subobject pointer: the derived pointee (via deref()) walked down the `__base` chain.
    std::string bp = basePathTo(&_classes[derivedT], &_classes[baseT]);
    if (!bp.empty()) bp.pop_back();                            // drop trailing '.'
    std::string basePtr = "&((" + derefFnName(srcCls, true) + "(&(" + srcE + ")))->" + bp + ")";
    if (copyable) {
        // Shared/Weak: build the base handle sharing the source's ctrl; retain bumps the count,
        // a move transfers the ref (no bump — the source's dtor is suppressed below). Carry the
        // source's allocator handle so the base handle releases the shared ctrl through the SAME
        // allocator (a zero-init default would `free` an arena-owned ctrl → double-free on reset).
        std::string allocArg = boxAllocatorArg(dstTy).empty() ? "" : (", (" + srcE + ").alloc");
        // The library ctor is the named factory `make(p, c, alloc)` (M8d.2 F7 renamed the nameless primary),
        // so it returns the base handle BY VALUE — assign it into the already-declared `nm` (not the old
        // in-place `__ctor(&nm, …)`, which no longer exists).
        indent(depth); *_out << nm << " = " << dstTy << "__make(" << basePtr << ", (" << srcE << ").c" << allocArg << ");\n";
        if (retain) { indent(depth); *_out << "(" << srcE << ").c->strong++;\n"; }
    } else {
        // Owned: adopt the base subobject (no ctrl); always a move.
        indent(depth); *_out << nm << " = " << dstTy << "__adopt(" << basePtr << ");\n";
    }
    if (!retain) { std::string mv = moveOnlySource(src, line); if (!mv.empty()) markMoved(mv); }
}

std::string CEmitter::ownerElem(const std::string& cls)
{
    std::string t = heapOwnerTarget(cls);                      // library Shared/Owned
    if (!t.empty()) return t;
    if (isSmartPtrClass(cls)) return _classes[cls].collElemClass;   // intrinsic (contract handle, Weak)
    return "";
}

bool CEmitter::isSmartPtrHandoffMismatch(const std::string& dstTy, SharedExpression src)
{
    if (!src || !isNamedValue(src.get())) return false;
    std::string de = ownerElem(dstTy), se = ownerElem(exprClass(src));
    if (de.empty() || se.empty() || de == se) return false;    // both must own; a same-element conv is handled elsewhere
    return !isSmartPtrUpcast(dstTy, src) && !isSmartPtrBaseUpcast(dstTy, src);
}

// Invalidate a moved-from smart pointer: null the field its dtor guards on, so
// the source's drop becomes a no-op (the ref/ownership transfers to the dest).
std::string CEmitter::smartPtrInvalidate(const std::string& expr, CollKind kind, bool ifaceElem)
{
    // an owned INTERFACE handle's value field is the fat pointer `.obj`, not `.ptr`.
    if (kind == CollKind::Owned) return expr + (ifaceElem ? ".obj = NULL;" : ".ptr = NULL;");
    return expr + ".ctrl = NULL; " + expr + (ifaceElem ? ".obj = NULL;" : ".ptr = NULL;");  // Shared/Weak guard on ctrl
}

// After `give` relocates an intrinsic collection's struct, the SOURCE must read as empty so its scope-drop
// is a no-op. The reset is the struct's own shape, and there are two: a `string`/buffer is `{data, len}`,
// a `BindableFunctionPtr` is `{obj, ctrl, fn, release}` (kama_runtime.h, KAMA_BINDABLE_TYPE). Every
// hand-off site spelled the first shape inline, so `give`-ing a named bindable into a field or a by-value
// parameter emitted `.data = NULL` against a struct that has no `data` and died in clang — a bindable
// could be built and called, and never stored anywhere. One helper, five sites, dispatched on the class.
std::string CEmitter::moveNullStmt(const std::string& cls, const std::string& expr) const
{
    if (isBindableClass(cls))
        return "(" + expr + ").obj = NULL; (" + expr + ").ctrl = NULL; (" + expr + ").fn = NULL; ("
             + expr + ").release = NULL;";
    return "(" + expr + ").data = NULL; (" + expr + ").len = 0;";
}

// ---- Resource-value move analysis -----------------------------------------

// A move-only VALUE: a destructible class value that isn't a smart-ptr / collection / extern
// struct. It moves on hand-off (its dtor is suppressed) and is never silently copied. (Trigger
// = destructibility — the proxy for a `resource`.)
bool CEmitter::isMoveOnlyValue(const std::string& cls) const
{
    auto it = _classes.find(cls);
    if (it == _classes.end() || it->second.isIntrinsicColl || it->second.isExternStruct || isSmartPtrClass(cls))
        return false;
    const ClassInfo& ci = it->second;
    // Move-only-ness is the declared kind: a `resource` moves even if it owns nothing (an empty
    // resource is a move-only identity/token); a `value` copies. An `Intrinsic` (a tagged-union enum;
    // collections/smart-ptrs already returned above) moves iff it owns a resource (is destructible).
    if (ci.kind == TypeKind::Resource) return true;
    if (ci.kind == TypeKind::Value)    return false;
    // ...or holds a move-only payload that owns nothing (`moveOnly`, from computeDestructible's
    // fixpoint) — a `Result<Token, E>` over a dtor-less resource moves because the token does.
    return ci.destructible || ci.moveOnly;
}

// A by-value class value the SLOT/CALLEE OWNS: a move-only `resource`, or a heap-owning collection/string
// (List/Array/string — NOT a `Fixed<T,N>`, a bitwise value; NOT a smart pointer, which has its own
// give/copy-with-refcount path). The gate for "a NAMED hand-off here needs `give` (move) / `copy` (deep)".
// Disjoint from isMoveOnlyValue (which excludes collections), so every existing isMoveOnlyValue(x) store
// site reads ownsByValue(x) with no change for a non-collection type.
bool CEmitter::ownsByValue(const std::string& cls) const
{
    if (cls.empty() || isSmartPtrClass(cls)) return false;
    if (isMoveOnlyValue(cls)) return true;
    auto it = _classes.find(cls);
    // ⚠️ `Fixed`, `Simd` and `Mask` are the intrinsics that own NOTHING — a value array and two bare
    // `vector_size` typedefs. Passing one by value is a register or struct copy, not a transfer, so it
    // needs no `give`/`copy` marker. This is the most central of the several places the question "is this
    // an intrinsic that owns something" is asked, and asking it as `!isFixedColl` alone made every
    // `Simd`/`Mask` argument demand an ownership marker it has no meaning for.
    return it != _classes.end() && it->second.isIntrinsicColl
        && !isFixedColl(cls) && !isValueVectorKind(it->second.collKind);
}


// has this type opted into the `Copyable` contract? (Detected structurally at collection
// time — a public nullary `copy` returning the own type; see collectClasses.) Only ever consulted
// for a move-only value, where it flips the marker from "silent move" to "mandatory give/copy".
bool CEmitter::isCopyable(const std::string& cls) const
{
    auto it = _classes.find(cls);
    return it != _classes.end() && it->second.copyable;
}

// Does concrete C-type `t` satisfy the contract `bound`? For `Copyable` (the conditional-implements
// container case): a primitive or a `value` is copyable (bitwise), a `resource` only if it implements
// Copyable. For any other contract: the concrete class must nominally implement it.
// The name a bare contract is RECORDED under for type `t` once that contract pins its parameter:
// `Equatable` on `Duration` is `Equatable_Duration`. The compiler names these contracts bare in
// several places that have no source AST to hang a `<This>` on — operator lowering (`==` -> `equals`),
// `@generate(Equatable, Hashable)`, the `when [T: Equatable]` gate — and after the pin a bare name
// matches no recorded conformance. Unpinned contracts (`Hashable`, `Formattable`, `Iterator`) come back
// unchanged, so every caller can ask unconditionally.
std::string CEmitter::pinnedInstanceName(const std::string& bare, const std::string& t) const
{
    auto g = _genericContracts.find(bare);
    // Single-parameter only: a multi-parameter pinned contract has arguments the compiler cannot invent,
    // and nothing names one bare.
    if (g == _genericContracts.end() || g->second.pinnedParam != 0) return bare;
    auto ps = _genericContractParams.find(bare);
    if (ps == _genericContractParams.end() || ps->second.size() != 1) return bare;
    return bare + "_" + t;
}

// Record a compiler-synthesized conformance to a contract that may be PINNED. `@generate(Deserializable)`
// pushes the contract's name straight into `ci.interfaces` — there is no `implements` clause for
// resolveInterfaceNames to mangle — so a bare name is right only while the contract has no parameters.
// Once `Deserializable` declared its factory it had to become `Deserializable<T is This>` (a contract may not
// name `This` in a signature), and a bare `"Deserializable"` would then match nothing `satisfiesBound` looks
// for: every `when [T: Deserializable<T>]` gate would silently read as unsatisfied, which is a whole
// subsystem quietly not emitted rather than a diagnostic. Mint the instance and hand back its name.
std::string CEmitter::synthConformanceName(const std::string& bare, const std::string& typeName)
{
    std::string inst = pinnedInstanceName(bare, typeName);
    if (inst == bare) return bare;                    // not pinned (Serializable) — the bare name IS the name
    auto args = std::make_shared<IdentifierList>();
    args->push_back(synthId(typeName));
    registerGenericContractInst(bare, args);
    return inst;
}

bool CEmitter::satisfiesBound(const std::string& t, const std::string& bound_) const
{
    const std::string bound = pinnedInstanceName(bound_, t);
    auto it = _classes.find(t);
    // `Immutable` is DERIVED, not declared: the compiler answers it for exactly the types the
    // `immutable` qualifier verifies deeply (computeDeeplyImmutable). It exists so deep immutability can
    // be NAMED in a bound — `when [T: Immutable]` is what lets `Shared<T>` say it is sendable exactly
    // when its payload cannot change — since the qualifier itself is not spellable in a bound.
    // A PRIMITIVE has no `_classes` entry and is immutable by nature (a scalar has no interior), which
    // matches the `Copyable` arm directly below.
    if (bound_ == "Immutable")
        return it == _classes.end() ? true : isImmutableType(it->second);
    // `Sendable` is declared and verified, and this is where the by-NATURE cases join the nominal ones:
    // a `when [V: Sendable]` gate on `Map<K, Unit>` must see the payload-less enum, `DynamicArray<UnsafePtr>`
    // the raw pointer, `Channel<InlineArray<int32>#(4)>` the comptime array — none of which has a
    // declaration site. One predicate answers all of it (unsendableReason); it saves and restores every
    // context it touches, which is why asking it from a const method is honest.
    if (!_sendableContract.empty() && bound_ == _sendableContract)
        return const_cast<CEmitter*>(this)->unsendableReason(t).empty();
    if (bound_ == "Copyable") {
        if (it == _classes.end()) return true;                 // primitive C type → bitwise-copyable
        if (it->second.kind == TypeKind::Value) return true;   // a value → bitwise-copyable
        return it->second.copyable;                            // a resource → only if `implements Copyable`
    }
    // A graph is read back as `Shared<X>`: the root arrives behind a handle because a cycle cannot be
    // returned by value, so `deserializeJsonBuffer::<Shared<Node>>` is the spelling. That makes
    // `Shared<X>: Deserializable` true exactly when `X` is a node — and it is DERIVED here, beside
    // `Immutable`/`Sendable`/`Copyable`, rather than declared as a `deserialize` on `Shared`. A method on a
    // handle would SHADOW the pointee's (the triad auto-derefs), which is the whole reason the triad is
    // method-free; a bound has no such hazard, because nothing calls it by name.
    // A graph is read back as `Shared<X>` — the root arrives behind a handle because a cycle cannot be
    // returned by value — so `deserializeJsonBuffer::<Shared<Node>>` is the spelling and the bound has to
    // hold for the handle. DERIVED here, beside `Immutable`/`Sendable`/`Copyable`, and deliberately not
    // declared as a `deserialize` on `Shared`: a method on a handle SHADOWS the pointee's, since the triad
    // auto-derefs, which is exactly why the triad is method-free. A bound has no such hazard — nothing
    // calls it by name.
    //
    // ⚠️ It answers off the POINTEE's own bound, not off `graphDeserialize`: bounds are judged during
    // collection, when a generic instance is registered, and the graph passes have not run yet. That is
    // the same question the old `Shared<T> … when [T: Deserializable<T>]` clause asked, so the reach is
    // unchanged — and as then, naming `Shared<X>` for a pointer-free `X` is a type error later, when the
    // handle turns out to have no `deserialize` to forward to.
    if (bound_ == "Serializable") {
        CEmitter* me = const_cast<CEmitter*>(this);
        std::string x = me->sharedPointeeClass(t);
        if (x.empty()) x = me->ownedPointeeClass(t);
        if (!x.empty() && satisfiesBound(x, "Serializable")) return true;
    }
    if (bound_ == "Deserializable" || (!bound.empty() && bound.compare(0, 15, "Deserializable_") == 0)) {
        CEmitter* me = const_cast<CEmitter*>(this);
        std::string x = me->sharedPointeeClass(t);
        if (x.empty()) x = me->ownedPointeeClass(t);
        if (!x.empty() && satisfiesBound(x, "Deserializable")) return true;
    }
    // A `type intrinsic <t> implements <bound>` block also satisfies it — including a PRIMITIVE target
    // (`int32`), whose conformance lives in _primConformances (NOT _classes). Consult the pre-scan so a
    // `when [T: Equatable]` gate on `List<int32>` sees int32's `Equatable` (matched on the raw source name).
    auto rc = _intrinsicConformances.find(t);
    if (rc != _intrinsicConformances.end() && (rc->second.count(bound) || rc->second.count(bound_))) return true;
    if (it == _classes.end()) return false;
    for (auto& itf : it->second.interfaces) if (itf == bound) return true;
    return false;
}


void CEmitter::markMoved(const std::string& cVar)
{
    // `give`ing the host out of the window is as fatal as growing it — the storage leaves with the value
    // and the alias is left watching nothing. The single choke point for every move, so one check covers
    // `a = give b`, `f(d: give a)` and the ctor/return forms alike.
    if (const Scope::FrozenPlace* f = frozenConflict({ cVar }))
        unsupported(("cannot `give` `" + cVar + "` — it is frozen by the enclosing `borrow` (opened at "
                     "line " + std::to_string(f->line) + " as `" + f->alias + "`), and moving it would "
                     "take the storage `" + f->alias + "` views with it; move it after the window closes")
                        .c_str(), _curLine);
    //  (Increment 3): moving a local declared OUTSIDE the nearest enclosing loop would move
    // it again on the next iteration (double-move). Reject — conservative, no loop fixpoint. A value
    // declared INSIDE the loop body is fresh each iteration, so moving it is fine.
    int lb = -1;
    for (int i = (int)_scopes.size() - 1; i >= 0; --i) if (_scopes[i].isLoopBoundary) { lb = i; break; }
    if (lb >= 0) {
        int li = -1;
        for (int i = (int)_scopes.size() - 1; i >= 0 && li < 0; --i)
            for (auto& l : _scopes[i].locals) if (l.cVar == cVar) { li = i; break; }
        if (li >= 0 && li < lb)
            unsupported(("cannot `give` `" + cVar + "` inside a loop — it would be moved again on the next "
                         "iteration; move it after the loop, or move a value declared in the loop body").c_str(), _curLine);
    }
    _moveState[cVar] = MoveState::Moved;
}

void CEmitter::checkNotMoved(const std::string& cVar, int line)
{
    // A still-unassigned `slot` is seeded Moved to suppress its drop, but it was never moved FROM — so
    // "use after move" would be the wrong story. checkDefiniteAssignment is the authority for holes and
    // reports them first (it runs before any emission), with a message that says what actually went
    // wrong. Once the slot is assigned it leaves _slotLocals and ordinary move tracking resumes.
    if (_slotLocals.count(cVar)) return;
    auto it = _moveState.find(cVar);
    // MaybeMoved on a slot means "filled on some paths" (a branch merge against its seeded state), not
    // "moved" — the storage is valid either way, so using it is fine. A real `give` still sets Moved, so
    // use-after-move on a filled slot is still caught.
    if (it != _moveState.end() && it->second == MoveState::MaybeMoved && _slotDeclared.count(cVar)) return;
    if (it != _moveState.end() && it->second != MoveState::NotMoved)
        unsupported(("use of `" + cVar + "` after it was moved (a `give` consumed it)").c_str(), line);
}

// The source of a move hand-off. A bare move-only local -> its name (caller marks it moved).
// A field / element / base member -> reject: moving out would leave the owner holding a
// moved-from value (use Optional<T> for the field-move case).
// An owning payload binding of a BORROWING `match (x)` arm only aliases the box the subject still owns —
// `give`ing it out moves the alias while the subject keeps ownership → both drop it → double free in safe
// code. Reject it (hard error); the consuming `match (give x)` is the way to move a payload out.
bool CEmitter::giveOfBorrowedBinding(SharedExpression e, int line)
{
    auto* id = dynamic_cast<IdentifierNode*>(e.get());
    if (!id || !id->value || (id->qualifier && !id->qualifier->empty())) return false;
    if (!_borrowedMatchBindings.count(*id->value)) return false;
    unsupported("cannot `give` a borrowed `match` payload out of `match (x)` — it aliases the still-owned "
                "subject; consume the subject with `match (give x)` instead", line);
    return true;
}

std::string CEmitter::moveOnlySource(SharedExpression e, int line)
{
    if (giveOfBorrowedBinding(e, line)) return "";
    // A move MUTATES its source — it leaves it holding a moved-from value — so a const binding may not be
    // one. Every other write through a const root is caught by `checkConstWrite` on an assignment LHS; a
    // hand-off writes through the RHS instead, which is why it needed its own guard. This is the single
    // choke point: every real move reaches here (a `copy`/retain does not, and correctly so).
    if (rootIsConst(rootBinding(e)))
        unsupported(("cannot `give` out of `const " + rootBinding(e) + "` — a move leaves its source "
                     "holding a moved-from value, which a const binding may not become; `copy` it, or "
                     "drop the `const`").c_str(), line);
    else if (chainThroughConstPlace(e))
        unsupported("cannot `give` out of a `const ref` place — a move leaves its source holding a "
                    "moved-from value, and the place only reads; `copy` it, or take the mutable form "
                    "(`…Mut`) where the place was made", line);
    if (auto* id = dynamic_cast<IdentifierNode*>(e.get())) {
        std::string nm = id->value ? *id->value : "";
        if ((!id->qualifier || id->qualifier->empty()) && _moveState.count(nm)) return nm;
        // While PROBING an uninstantiated template, a local whose type depends on the unbound parameter
        // has no resolved C type, so it was never registered as owning and `_moveState` does not know it.
        // It is still a LOCAL — the diagnostic below is about a field or an element, and would be a
        // false one here. Measured: `Lines<R>` in std::io does `Result<…> rl = this.inner.readLine();
        // match (give rl) …` on a `BufReader<R>` field, and every program that merely imported std::io
        // was refused for it. Every instantiation re-walks this body with the type bound and judges the
        // move for real, so deferring here loses nothing.
        if (_probingTemplate && (!id->qualifier || id->qualifier->empty()) && _localTypeNodes.count(nm)) return "";
    }
    // `give this` inside a ctor: `this` is not a field of some other owner, it IS the value the ctor
    // is handing back, and its storage dies at the return. Nothing is left holding a moved-from value.
    // (There is no move state to key on — the storage is the function's own — so report no source.)
    if (_inNamedCtorBody && dynamic_cast<ThisAccessNode*>(e.get())) return "";
    // A LOCAL that is not move-tracked is a plain value — copied on assignment, nothing to move — and
    // the story below (a field, an element) would be the wrong one for it. Measured: `match (give r)`
    // over a `Result<Nonce, E>` with a `value` payload was reported as giving "out of a field/element".
    // Only when the local's TYPE is one that copies: a `ref` foreach binding over a resource is a local
    // too, but an alias of an element the collection still owns, and for it the field/element story
    // below is the right one (tests/xfail/foreach_ref_give).
    if (auto* id = dynamic_cast<IdentifierNode*>(e.get()))
        if (id->value && (!id->qualifier || id->qualifier->empty())
            && (_localTypeNodes.count(*id->value) || _localTypes.count(*id->value))
            && !(_localTypes.count(*id->value)
                 && (ownsByValue(_localTypes[*id->value]) || isSmartPtrClass(_localTypes[*id->value]))))
        {
            unsupported(("cannot `give` `" + *id->value + "` — it is a plain value, copied on assignment, "
                         "and `give` moves a move-only value; drop the `give`").c_str(), line);
            return "";
        }
    unsupported("cannot `give` out of a field/element — it would leave the owner holding a "
                "moved-from value; move a local instead, or use Optional<T>", line);
    return "";
}

// Move-state key for a drop-before-assign LHS. Superset of the inline `lname` extraction the
// assignment handlers do: an unqualified local -> its name; a single-level `local.field` member
// access whose receiver is an unqualified local -> "local.field" (mirrors checkNamedCtorComplete's
// localFieldRef key format). Anything else (this.*, element access, nested, qualified) -> "".
std::string CEmitter::lvalueMoveKey(SharedExpression lhs) const
{
    if (auto* id = dynamic_cast<IdentifierNode*>(lhs.get()))
        if (id->value && (!id->qualifier || id->qualifier->empty())) return *id->value;
    if (auto* ma = dynamic_cast<MemberAccessNode*>(lhs.get()))
        if (ma->identifier && ma->identifier->value) {
            // `this.field` — in a ctor this is THE construction target, and its move state is what stops
            // the first `this.f = give …` from dropping the zeroed field. Without a key here that
            // suppression cannot fire, and for a raw-handle field whose zero is `fd = 0` the drop is a
            // `close(0)`: it shuts the process's own stdin. `Process.make` is exactly that shape.
            if (dynamic_cast<ThisAccessNode*>(ma->expression.get()))
                return "this." + *ma->identifier->value;
            if (auto* id = dynamic_cast<IdentifierNode*>(ma->expression.get()))
                if (id->value && (!id->qualifier || id->qualifier->empty()))
                    return *id->value + "." + *ma->identifier->value;
        }
    return "";
}

// Shared front half of both `isolate` forms (the fused statement and the `Isolate` handle expression):
// validate the `isolate worker(p: give x)` call, queue the per-entry trampoline, emit the moved argument
// expression, and mark its source moved. Returns the entry's mangled cName; sets `cls` (the bundle C type)
// and `val` (the emitted, already-move-marked argument expression). Shared-nothing by construction: the
// entry is a BARE top-level fn (no env capture) and its one argument is MOVED (the source is marked moved
// via the existing `give` seam, so any post-spawn use is the standard use-after-move error).
std::string CEmitter::isolatePrep(IsolateNode* iso, std::string& cls, std::string& val,
                                  bool& isBorrow, bool borrowOK)
{
    // The seam header (and its `-lpthread` link) flows in via `import std::concurrent;`. Without it the
    // generated spawn call would not compile — give a clear error instead.
    if (!externsHeader("kama_isolate.h"))
        unsupported("`spawn` requires `import std::concurrent;` (the native isolate seam)", iso->line);

    auto* inv = dynamic_cast<InvocationNode*>(iso->call.get());
    // Must be a BARE top-level fn call: `spawn worker(...)`. A receiver call (`spawn obj.m(...)`) or an
    // indirect callee would capture/alias enclosing state — reject to keep the entry shared-nothing.
    if (!inv || !inv->identifier || !inv->identifier->value || inv->expression) {
        unsupported("`spawn` entry must be a bare top-level function call, e.g. `spawn worker(p: give x)`", iso->line);
        return "";   // `inv`/`identifier` may be the null this guard rejected — never fall through and deref it
    }

    const std::string fname = *inv->identifier->value;
    auto it = _funcs.find(resolveFunc(fname, inv->identifier->qualifier));
    if (it == _funcs.end())
        unsupported(("`spawn` entry `" + fname + "` names no known top-level function").c_str(), iso->line);
    const FuncSig& sig = it->second;

    // A `void` entry taking exactly one argument (the bundle) — `void` because there is no channel to
    // hand a result back over (use an M3 channel, or a `ref` borrow's fields, for results). The single
    // param's SHAPE selects the mode: a by-value move-only `resource` (M2/M4.1, `give`) or a `ref T`
    // borrow of a caller-owned bundle (M4.2), sound because the scope joins before the local drops.
    if (sig.retCType != "void")
        unsupported(("`spawn` entry `" + fname + "` must return void — there is no channel to return a result over").c_str(), iso->line);
    if (sig.params.size() != 1)
        unsupported(("`spawn` entry `" + fname + "` must take exactly one argument (the bundle)").c_str(), iso->line);
    if (!inv->args || inv->args->size() != 1)
        unsupported(("`spawn` call to `" + fname + "` needs exactly one argument").c_str(), iso->line);

    const ParamSig& p = sig.params[0];
    cls = p.className;
    if (cls.empty())
        // ⚠️ NOT "not a primitive": `className` is empty only when the parameter names no resolvable type
        // at all. A `ref int32` bundle IS legal and `tests/parfor_in_scope.kama` relies on it — the borrow
        // mode restricts the LIFETIME (scope-bounded, join-proven) and is free in the type, while the move
        // mode restricts the TYPE (`isMoveOnlyValue` below) and is free in lifetime. The old wording named
        // a rule neither mode has.
        unsupported("`spawn` entry's parameter names no known type — the bundle must be a type this "
                    "unit can see", iso->line);
    isBorrow = p.byRef;   // a `ref T` param = borrow (M4.2); a by-value param = the moved bundle (M2/M4.1)
    // The bundle crosses into another isolate exactly as a channel element does, so it faces the same
    // sendability gate — see checkSpawnBundleSendability for why the fact is recorded rather than tested
    // here. Recorded for BOTH modes: a moved handle is released by the child, and a borrowed one can be
    // `copy`'d inside it.
    if (!_probingTemplate && !cls.empty())
        _spawnBundles.push_back(SpawnBundle{ cls, iso->line, diagFile() });

    auto* argNode = dynamic_cast<ArgumentNode*>((*inv->args)[0].get());

    if (isBorrow) {
        // ── M4.2: a `ref T` borrow of a caller-owned scope local ────────────────────────────────────
        if (!borrowOK || !innermostTaskScope())
            unsupported("only a bare `spawn` inside a `scope { }` may `ref`-borrow (the scope joins the "
                        "child before the local drops); the handle form must take a moved `give` bundle", iso->line);
        // The argument must be `ref <place>`. A `give`/`copy` (HandoffNode) or a bare value would not
        // match the `ref T` parameter.
        //
        // A PLACE, not just a bare local: `ref w.bodies` and `ref w.springs` hand two children two
        // disjoint fields of one world, which is the shape the ECS/engine work wants and which the
        // bare-local rule refused outright. It reads as a lifetime question — "how long does that field
        // live?" — and it is not one, because a field's storage is INSIDE its root's storage. Containment
        // answers both halves with no inference at all: `w.bodies` is created and destroyed exactly with
        // `w`, so the escape check below is exactly as strong applied to the root; and two places neither
        // of which is a prefix of the other cannot overlap, which is `placesConflict` — the same predicate
        // the view model already ships on. One rule replaces two.
        //
        // What `placePath` refuses is refused for free, on its own "not a statically-nameable place"
        // signal (the empty vector): an ELEMENT (`w.bodies[i]`) has a runtime index no static rule pins
        // (splitting one buffer by index is `parallel_for`'s job), and a CALL or temporary designates no
        // place at all.
        bool isRef = argNode && argNode->modifier && argNode->modifier->value && *argNode->modifier->value == "ref";
        std::vector<std::string> place = (isRef && argNode) ? placePath(argNode->expression)
                                                           : std::vector<std::string>();
        if (!isRef || place.empty()) {
            unsupported(("`spawn` to `" + fname + "` borrows — pass a local or one of its fields by `ref` "
                         "(e.g. `spawn " + fname + "(b: ref myBundle)` or `ref myWorld.bodies`). An element "
                         "(`a[i]`) or a call result names no place a static disjointness rule can pin — "
                         "split a buffer with `parallel_for` instead").c_str(), iso->line);
            return "";   // the place is empty — never fall through and index it
        }
        const std::string root = place[0];

        // ⚠️ The one thing containment does NOT give: a projection through an indirection leaves the
        // root's own storage. If `w` is a handle another handle can copy, `a.bodies` and `b.bodies` are
        // non-prefix places naming ONE cell, and both the lifetime and the disjointness arguments break —
        // a silent data race in safe kama. (Probed: `ref Shared<T>` as a PARAMETER is already refused
        // language-wide, so this hazard is created by the relaxation rather than inherited.)
        //
        // The ownership model draws the line, and `copyable` is the exact question — can a second handle
        // name this object? An `Owned<T>` is unique (`copy` on one is refused), so distinct roots ARE
        // distinct pointees and containment still holds; a `Shared`/`Weak` says outright that someone else
        // may hold it, which is the premise disjointness has to deny. Keying on copyability rather than on
        // a list of type names also covers the intrinsic and the library heap-owner families at once.
        for (ASTNode* n = argNode->expression.get(); ; ) {
            auto* ma = dynamic_cast<MemberAccessNode*>(n);
            if (!ma || !ma->expression) break;
            std::string bc = exprClass(ma->expression);
            if ((isSmartPtrClass(bc) || !heapOwnerTarget(bc).empty()) && isCopyable(bc)) {
                unsupported(("`spawn` borrows `" + placeText(place) + "`, a place inside `" + root
                             + "`'s own storage — but `" + root + "` is a shared handle, and another handle "
                             "can name the same object, so two children are not provably disjoint. Own it "
                             "uniquely (`Owned<T>`), or move the bundle in with `give`").c_str(), iso->line);
                return "";
            }
            n = ma->expression.get();
        }

        // Escape check: the borrowed root must OUTLIVE the scope's join barrier — i.e. be declared in
        // the task scope itself or an OUTER scope (or be a parameter). A local declared in a block
        // NESTED inside the scope drops before the barrier → it would dangle. Structural, no lifetimes.
        //
        // ⚠️ CURRENTLY UNREACHABLE, and deliberately kept. emitIsolate now requires a bare `spawn` to be a
        // DIRECT statement of its task scope, so `ti` is `_scopes.size() - 1` by the time we get here and
        // `findScopeDeclaring` cannot return anything greater — a visible name is necessarily declared at
        // scope level or outer. (The handle form never reaches this arm at all: borrowOK is false there.)
        // It stays because that direct-statement rule is a 1.0-gate simplification, not a permanent one:
        // the deferred handle-group work would readmit a nested `spawn` and make this check live again on
        // the same day. Deleting it would mean reinventing it then.
        int di = findScopeDeclaring(root);
        int ti = innermostTaskScopeIndex();
        if (di >= 0 && di > ti)
            unsupported(("`spawn` may not borrow `" + root + "` — it is declared inside a block nested in "
                         "the `scope`, so it is destroyed before the scope joins this child; declare it in "
                         "the `scope` itself or an outer scope").c_str(), iso->line);
        // Can't borrow something already moved into (or given away by) an earlier statement. Both keys
        // matter for a place: moving the ROOT away takes the field with it, and the field can also have
        // been given away on its own — `_moveState` keys those as "w.bodies", the same shape
        // `moveOnlySource` builds.
        for (size_t k = 1; k <= place.size(); ++k) {
            std::string key = placeText(std::vector<std::string>(place.begin(), place.begin() + k));
            auto ms = _moveState.find(key);
            if (ms != _moveState.end() && ms->second != MoveState::NotMoved) {
                unsupported(("cannot borrow `" + placeText(place) + "` — `" + key
                             + "` was moved (given) away").c_str(), iso->line);
                break;
            }
        }
        // ...nor something an enclosing `borrow` froze. A `ref` handed to a task is a mutable borrow like
        // any other — the direct call `grow(d: ref a)` is rejected inside a window, and routing the same
        // call through `spawn` must not launder it. This path never reaches `checkConstWrite`, which is
        // where every other `ref` argument is caught.
        rejectFrozenWrite(argNode->expression, iso->line);
        // Disjointness: no two children of one scope may borrow OVERLAPPING places (they would race on the
        // shared storage). Two places overlap iff one is a prefix of the other — which is the exact
        // statement, not an approximation, so `w.bodies` and `w.springs` are admitted while `w` beside
        // either is still caught. Overlapping index-ranges of one buffer remain M6/`parallel_for`.
        // EXEMPTION (M6): an `Atomic<T>` is the sanctioned shared-mutable cell — its ops are race-free, so
        // several children borrowing the SAME atomic place is exactly the intended use, not a data race.
        if (!isAtomicClass(cls)) {
            Scope* ts = innermostTaskScope();
            for (auto& prev : ts->borrowedPlaces)
                if (placesConflict(prev, place)) {
                    unsupported(("two children in this `scope` borrow overlapping places (`"
                                 + placeText(prev) + "` and `" + placeText(place) + "`) — a shared mutable "
                                 "borrow across tasks would race; borrow disjoint fields or distinct locals, "
                                 "or use an `Atomic<T>` (M6)").c_str(), iso->line);
                    break;
                }
            ts->borrowedPlaces.push_back(place);
        }

        // Borrow trampoline: `__p` IS `&local` — pass it straight through as the `ref T` (`T*`) param.
        // No heap box, no free, no move (the caller keeps the local and drops it after the join).
        if (_moduleHelperKeys.insert("iso:" + symbolOf(sig)).second) {
            std::ostringstream tr;
            tr << "static void* __kama_iso_" << symbolOf(sig) << "(void* __p) {\n"
               << "    " << symbolOf(sig) << "((" << cls << "*)__p);   /* borrow: __p IS &local — no box, no free, no move */\n"
               << "    return (void*)0;\n"
               << "}\n";
            _fileScopeHelpers.push_back(tr.str());
        }
        val = "(void*)&(" + emitExpression(argNode->expression) + ")";
        return symbolOf(sig);
    }

    // ── M2/M4.1: a by-value MOVED `resource` bundle ─────────────────────────────────────────────────
    // A move-only `resource` VALUE owned by the callee: ownership actually transfers across the thread
    // (a plain `value` would only be copied; a collection would need source-nulling — both deferred).
    if (!isMoveOnlyValue(cls))
        unsupported("`spawn` argument must be a moved `resource` value — the entry's parameter type is not one", iso->line);
    // The argument must be `give`n: a shared borrow would alias state across the thread boundary. Unwrap
    // the HandoffNode ourselves (we emit no call — just the move + spawn).
    SharedExpression argExpr = argNode ? argNode->expression : (*inv->args)[0]->expression;
    auto* h = dynamic_cast<HandoffNode*>(argExpr.get());
    if (!h || !h->isGive) {
        unsupported("`spawn` argument must be `give`n (moved) — a borrow would alias state across the thread", iso->line);
        return "";   // `h` may be the null this guard rejected — never fall through and deref it
    }
    SharedExpression src = h->value;

    // Emit the per-entry trampoline once (the same worker may be spawned from several sites / both forms).
    if (_moduleHelperKeys.insert("iso:" + symbolOf(sig)).second) {
        std::ostringstream tr;
        tr << "static void* __kama_iso_" << symbolOf(sig) << "(void* __p) {\n"
           << "    " << cls << " __v = *(" << cls << "*)__p;   /* relocate the bundle out of the heap box */\n"
           << "    kama_free(__p, " << layoutOf(cls) << ");\n"
           << "    " << symbolOf(sig) << "(__v);                   /* callee owns __v and drops it at fn-end */\n"
           << "    return (void*)0;\n"
           << "}\n";
        _fileScopeHelpers.push_back(tr.str());
    }

    // Read the source, then mark it moved (post-spawn use → use-after-move via the normal `give` seam).
    // moveOnlySource rejects a field/element move, matching every other `give` site.
    val = emitExpression(src);
    std::string mv = moveOnlySource(src, iso->line); if (!mv.empty()) markMoved(mv);
    return symbolOf(sig);
}

// `spawn worker(p: give x);` — a bare `spawn` STATEMENT, which is a **deferred-join child of the
// enclosing `scope { }`** (M4). It is legal ONLY as a DIRECT statement of a scope (which owns the join);
// outside a scope use the handle form `Isolate h = spawn worker(...)`. Generated C: heap the moved bundle
// and spawn now, declaring the `kama_isolate_t` handle at the scope's block level; the join is emitted by
// the scope's closing-brace barrier (emitScopeCleanup), which runs before any local dtor.
void CEmitter::emitIsolate(IsolateNode* iso, int depth)
{
    if (!innermostTaskScope()) {
        unsupported("a bare `spawn` must appear inside a `scope { }` (which owns the join) — outside a "
                    "scope use the handle form `Isolate h = spawn worker(...)`", iso->line);
        return;   // there is no scope to register the handle into; the tail would deref that same null
    }
    // ...and it must be a DIRECT statement of that scope, not buried in a nested block. The handle is
    // declared at the spawn's own depth while `emitScopeCleanup` joins at the scope's brace, so a handle
    // declared inside a sub-block is out of scope at the join — invalid C, which is what a `while`/`if`
    // body produced. Hoisting the declaration would not save it either: one variable holds one handle
    // while a loop starts N, so the barrier would join only the last child and orphan the rest. A scope's
    // children are the `spawn`s written directly in it — which is also what makes them countable by
    // reading the block, and matches the coarse-isolate model (SPEC: roughly one per core, not one per
    // work item). Conditional spawning puts the `if` OUTSIDE the `scope`; per-item work is `parallel_for`.
    if (innermostTaskScopeIndex() != (int)_scopes.size() - 1) {
        unsupported("a bare `spawn` must be a direct statement of its `scope { }` — this one is inside a "
                    "nested block, whose handle the scope's join cannot name. Put the `if` outside the "
                    "`scope`, or use `parallel_for` for per-item work", iso->line);
        return;   // registering it would emit a join naming a handle declared in the sub-block
    }

    std::string cls, val;
    bool isBorrow = false;
    std::string cName = isolatePrep(iso, cls, val, isBorrow, /*borrowOK=*/true);
    if (cName.empty()) return;   // prep already reported; its `cls`/`val` outputs are unset
    std::string hnd = "__kama_iso" + std::to_string(_tempCounter++);

    line(iso->line);
    // The handle is declared at THIS depth (the scope's own block), NOT inside any sub-block, so the
    // scope-barrier join can name it.
    indent(depth); *_out << "kama_isolate_t " << hnd << ";\n";
    if (isBorrow) {
        // M4.2 borrow: `val` is already `(void*)&(local)` — spawn with it directly. No box, no free.
        noteThreadSpawn();
        indent(depth); *_out << hnd << " = kama_isolate_spawn(&__kama_iso_" << cName << ", " << val << ");\n";
    } else {
        // M2/M4.1 move: heap the moved bundle, spawn with the box (the trampoline frees it). The malloc
        // temp stays scoped to its sub-block.
        rejectIfNoHeap("spawn heaps the moved argument bundle", iso->line);   // no-heap gate
        std::string arg = "__kama_iso_arg" + std::to_string(_tempCounter++);
        indent(depth);     *_out << "{\n";
        indent(depth + 1); *_out << cls << "* " << arg << " = (" << cls << "*)kama_alloc(" << layoutOf(cls) << ");\n";
        indent(depth + 1); *_out << "if (!" << arg << ") kama_panic(kama_string_lit(\"out of memory\", 13));\n";
        indent(depth + 1); *_out << "*" << arg << " = (" << val << ");\n";
        noteThreadSpawn();
        indent(depth + 1); *_out << hnd << " = kama_isolate_spawn(&__kama_iso_" << cName << ", " << arg << ");\n";
        indent(depth);     *_out << "}\n";
    }
    // Register into the innermost scope AFTER emission (re-fetch: isolatePrep may have grown _scopes and
    // invalidated an earlier pointer). The scope joins this handle at its closing brace.
    innermostTaskScope()->taskChildren.push_back({ hnd, "" });
}

// `Isolate h = isolate worker(p: give x);` — the HANDLE form: spawn now and wrap the (heap-boxed) thread
// handle in an RAII `std::concurrent::Isolate` whose drop = join. Generated C is a statement-expression:
// heap the moved bundle, spawn (boxed), and hand the box to the `Isolate::fromRaw` ctor.
std::string CEmitter::emitIsolateExpr(IsolateNode* iso)
{
    std::string cls, val;
    bool isBorrow = false;   // the handle form may outlive the scope, so borrowing is rejected in isolatePrep
    std::string cName = isolatePrep(iso, cls, val, isBorrow, /*borrowOK=*/false);
    if (cName.empty()) return "0";   // prep already reported; its `cls`/`val` outputs are unset
    std::string iso_t = resolveUserName("Isolate", SharedStringList());
    if (!_classes.count(iso_t))
        unsupported("the `isolate` handle form needs `std::concurrent::Isolate` in scope — add `import std::concurrent;`", iso->line);
    std::string arg = "__kama_iso_arg" + std::to_string(_tempCounter++);
    std::ostringstream e;
    noteThreadSpawn();
    e << "({ " << cls << "* " << arg << " = (" << cls << "*)kama_alloc(" << layoutOf(cls) << "); "
      << "if (!" << arg << ") kama_panic(kama_string_lit(\"out of memory\", 13)); "
      << "*" << arg << " = (" << val << "); "
      << iso_t << "__fromRaw(kama_isolate_spawn_boxed(&__kama_iso_" << cName << ", " << arg << ")); })";
    return e.str();
}

std::string CEmitter::emitSmartPtrCall(const std::string& cls, const std::string& recvExpr,
                                       const std::string& method, SharedArgumentList args, int srcLine,
                                       const IdentifierNode* site)
{
    // An intrinsic on the pointer itself (lock/expired/valid)?
    if (_classes[cls].methods.count(method))
        return emitDispatch(cls, "&(" + recvExpr + ")", method, args, srcLine, site);
    // an owned INTERFACE handle dispatches polymorphically through its own {obj, vtbl}.
    if (isInterface(_classes[cls].collElemClass) && smartKind(cls) != CollKind::Weak)
        return emitInterfaceDispatch(recvExpr, _classes[cls].collElemClass, method, args, srcLine, cls, site);
    // Otherwise auto-deref to the pointee T (Owned/Shared expose a T* ptr).
    if (smartKind(cls) != CollKind::Weak)
        return emitDispatch(_classes[cls].collElemClass, "(" + recvExpr + ").ptr", method, args, srcLine, site);
    unsupported(("Weak<T> has no member '" + method + "'; call .tryUpgrade()").c_str(), srcLine);
    return "0";
}

// Resolve `extends` names to ClassInfo pointers; error on unknown/cycle.
// Merge each contract's refined-parent methods into its own `methods`, transitively (a refined parent may
// itself refine), so a refining contract's vtable struct, conformance table, and dispatch all see the full
// slot set — parent slots first, then own (a same-named own method wins). Cycle-safe via a visited set.
void CEmitter::linkContracts()
{
    std::set<std::string> done;
    std::function<void(const std::string&)> merge = [&](const std::string& name) {
        if (!done.insert(name).second) return;                 // already merged
        auto it = _interfaces.find(name);
        if (it == _interfaces.end() || it->second.refines.empty()) return;
        InterfaceInfo& ii = it->second;
        std::vector<InterfaceMethod> merged;
        std::set<std::string> seen;
        for (auto& own : ii.methods) seen.insert(own.name);    // own methods take precedence over inherited
        for (auto& parent : ii.refines) {
            merge(parent);                                     // fully merge the parent first (transitive)
            auto pit = _interfaces.find(parent);
            if (pit == _interfaces.end()) {
                unsupported(("contract `" + name + "` refines unknown contract `" + parent + "`").c_str(), 0);
                continue;
            }
            // An inherited slot's SIGNATURE was written in the PARENT's file and resolves there. Merging
            // the method node as-is left its type names to be re-resolved later under the CHILD's
            // namespace, where an import the parent had may not exist — so a parent method taking a
            // `View<uint8>` emitted a vtable slot naming a bare, undeclared `View` unless the child's file
            // happened to import it too. Rebind each type to its absolute, parent-resolved spelling at
            // merge time, so the slot mangles identically no matter which file emits it.
            InterfaceInfo& pi = pit->second;
            NsCtx savedNs = _nsCtx;
            _nsCtx = NsCtx{};
            _nsCtx.scope = pi.scope; _nsCtx.usings = pi.usings; _nsCtx.symbolAliases = pi.symbolAliases;
            _nsCtx.privScope = pi.privScope; _nsCtx.exportedHere = pi.exportedHere;
            for (auto& pm : pit->second.methods) {
                if (!seen.insert(pm.name).second) continue;              // inherited (dedup)
                InterfaceMethod im = pm;
                im.returnType = absolutizeType(im.returnType);
                if (im.params) {
                    auto ps = std::make_shared<ParameterList>();
                    for (auto& p : *im.params) {
                        if (!p) { ps->push_back(p); continue; }
                        auto np = std::make_shared<FunctionParameterNode>(*p);
                        np->synthesized = true;                          // an emitter-built copy, not source
                        np->type = absolutizeType(p->type);
                        ps->push_back(np);
                    }
                    im.params = ps;
                }
                merged.push_back(im);
            }
            _nsCtx = savedNs;
        }
        for (auto& own : ii.methods) merged.push_back(own);    // then own, after the inherited slots
        ii.methods = std::move(merged);
    };
    for (auto& kv : _interfaces) merge(kv.first);
}

// Resolve a parallel (names, nodes) interface list IN PLACE. `names` is the plain string list a ClassInfo
// keeps; `nodes` is the AST list it was built from, which is the only place the generic args survive — a
// `implements Iterator<int32>` has to become `Iterator_int32`, and `names` alone dropped the `<int32>`.
// `nodes` may be null or shorter than `names` (a conformance recorded without a declaration site).
void CEmitter::resolveInterfaceNames(std::vector<std::string>& names, SharedIdentifierList nodes)
{
    std::vector<std::string> kept;
    for (size_t i = 0; i < names.size(); ++i) {
        SharedIdentifier itfNode = (nodes && i < nodes->size()) ? (*nodes)[i] : nullptr;
        // Through the node's QUALIFIER when there is one: `names` holds bare strings, so `implements
        // geo::ShownC` resolved as a bare `ShownC` and was refused unless that was imported too.
        std::string base = resolveUserName(names[i], itfNode ? itfNode->qualifier : SharedStringList());
        // A PINNED contract's argument is DETERMINED — it can only be the implementing type — so there is
        // exactly one always-correct spelling, `This`, and it is also the only one the intrinsic SET form
        // can write (`<int8, …, uint64>` is eight types sharing one block). Naming the type concretely is
        // rejected rather than accepted-when-equal, so a conformance reads the same everywhere.
        auto gc = _genericContracts.find(base);
        if (itfNode && gc != _genericContracts.end() && gc->second.pinnedParam >= 0) {
            size_t p = (size_t)gc->second.pinnedParam;
            SharedIdentifier arg = (itfNode->genericArgs && p < itfNode->genericArgs->size())
                                 ? (*itfNode->genericArgs)[p] : SharedIdentifier();
            if (!arg || !arg->value || *arg->value != "This")
                unsupported(("`" + base + "` pins its type parameter to the implementing type, so the "
                             "conformance names it `This` — write `implements " + base + "<This"
                             + (itfNode->genericArgs && itfNode->genericArgs->size() > 1 ? ", …" : "")
                             + ">`").c_str(), itfNode->line);
        }
        // A source-spelled name that is not a contract was reported where it is written, by
        // `checkDeclaredTypes`. Recording it anyway filed a conformance to nothing, which the vtable emit then
        // reported a second time as "unknown contract in implements", naming no name.
        // `nodes` is the AST's own list and stays whole; only the resolved names drop the entry.
        if (itfNode && !_interfaces.count(base) && !_genericContracts.count(base)) continue;
        if (itfNode && itfNode->genericArg && _genericContracts.count(base))
            base = genericTypeMangle(base, itfNode->genericArgs);   // Iterator -> Iterator_int32
        kept.push_back(base);
    }
    names = std::move(kept);
}

void CEmitter::linkBases()
{
    _basesLinked = true;   // from here on, an empty `baseName` means "no base", not "not resolved yet"

    // Now every file's declarations are registered: resolve each class's base +
    // interface references (bare/qualified) to their mangled names, in the
    // class's own namespace context.
    for (auto& kv : _classes) {
        ClassInfo& ci = kv.second;
        if (ci.isIntrinsicColl) continue;
        // a generic INSTANCE resolved its base/interfaces under its own subst in registerGenericTypeInst
        // (its `node` is the template's, whose refs still name the raw param `T`) — don't re-resolve here.
        if (ci.isGenericInst) continue;
        _nsCtx = NsCtx{}; _nsCtx.scope = ci.scope; _nsCtx.usings = ci.usings; _nsCtx.symbolAliases = ci.symbolAliases; restoreFileRung(_nsCtx, ci.declFile);
#if KAMA_INHERITANCE
        if (ci.node && ci.node->baseTypes && ci.node->baseTypes->base && ci.node->baseTypes->base->value)
            ci.baseName = resolveUserName(*ci.node->baseTypes->base->value, ci.node->baseTypes->base->qualifier);
#endif
        // resolve each interface name; a generic-contract `implements Iterator<int32>` resolves to the
        // specialized instance name (`Iterator_int32`) — its genericArgs live on the AST node, which
        // ci.interfaces (a plain name list) dropped, so read them back in parallel.
        SharedIdentifierList ifaceNodes = (ci.node && ci.node->baseTypes) ? ci.node->baseTypes->interfaces
                                                                          : SharedIdentifierList();
        // A PINNED contract's argument is `This`, and it has to mangle to THIS class — `Comparable<This>`
        // on `Duration` names `Comparable_Duration`. Without the binding it mangles the literal word
        // and the conformance is filed under a key nothing can ever look up.
        ScopedStr  _ts(_thisType, ci.name);
        ScopedThis _tt(_typeSubst, synthId(ci.name));
        resolveInterfaceNames(ci.interfaces, ifaceNodes);
        // Coherence, the class arm: one claim per (type, contract). The enum and `type intrinsic` paths
        // have always checked this; a class's `implements` list never did, so `implements C, C` was
        // accepted and recorded twice. Checked HERE rather than at collect time because the duplicate can
        // be spelled two ways (`C` and `ns::C`), and only the resolved names can tell.
        //
        // A generic INSTANCE is skipped above, so a duplicate on a generic template is reported once,
        // from the template, instead of once per instantiation.
        for (size_t i = 0; i < ci.interfaces.size(); ++i)
            for (size_t j = 0; j < i; ++j)
                if (ci.interfaces[i] == ci.interfaces[j]) {
                    unsupported(("`" + ci.name + "` already implements `" + ci.interfaces[i] + "`").c_str(),
                                ci.declLine());
                    break;
                }
        // Mint each generic-contract instance HERE, not only in collectCollections. A bound check
        // (`SortedSet<Duration>` needing `K: Comparable`) matches a conformance through the instance's
        // `templateKey`, so the instance must exist in `_interfaces` before ANY unit is scanned — and
        // collectCollections walks units in order, so a type declared in a later-scanned unit would not
        // satisfy a bound checked in an earlier one. Registration dedups, so the later scan is free.
        if (ifaceNodes) for (auto& itf : *ifaceNodes) scanTypeForGenericContracts(itf);
    }
#if KAMA_INHERITANCE
    for (auto& kv : _classes) {
        ClassInfo& ci = kv.second;
        if (ci.baseName.empty()) continue;
        auto it = _classes.find(ci.baseName);
        if (it == _classes.end()) {
            unsupported("unknown base class", ci.declLine());
            ci.baseName.clear();
        } else {
            ci.base = &it->second;
            // The base must be extensible: a `virtual`/`abstract class`, never a
            // plain/`final` (sealed) class.
            int bl = ci.declLine();
            if (ci.base->isFinalClass)
                unsupported(("cannot extend '" + ci.base->name + "': it is a `final class` (a sealed leaf)").c_str(), bl);
            else if (!(ci.base->isVirtualClass || ci.base->isAbstractClass))
                unsupported(("cannot extend '" + ci.base->name
                             + "': only a `virtual`/`abstract class` may be extended").c_str(), bl);
        }
    }
    // Break cycles defensively (A extends B extends A): cut the back-edge.
    for (auto& kv : _classes) {
        int hops = 0;
        for (ClassInfo* b = kv.second.base; b; b = b->base) {
            if (b == &kv.second || ++hops > 1000) { kv.second.base = nullptr; kv.second.baseName.clear(); break; }
        }
    }
    // THE DEPTH BUDGET. A `virtual`/`abstract class` must state how many levels may still be added below
    // it — `virtual(maxDepth: 2)` — and a deriving type must state its own, which may be AT MOST one less,
    // or be `final` (which IS a budget of 0). Chain length is therefore bounded by the root's budget by
    // construction, so no hop-count arithmetic is needed: one rule, checked where it is written.
    //
    // The point is that the limit is visible at the moment a designer OPTS IN to extensibility, instead of
    // arriving as a surprise when a third level is refused — by which time the design has been built
    // around an assumption the language was never going to honour. Inheritance is deliberately nerfed
    // here (it is a footgun more often than a tool, and mainstream hierarchies rarely exceed three
    // levels); a budget that must be written down is how that nerf announces itself.
    //
    // "At most one less" rather than "exactly one less" so the number carries information: a middle layer
    // may shorten a chain its root left open. `final` is the only spelling for 0.
    {
        for (auto& kv : _classes) {
            ClassInfo& ci = kv.second;
            if (ci.isGenericInst) continue;
            int line = ci.declLine();
            bool extensible = ci.isVirtualClass || ci.isAbstractClass;

            // Opting in without stating the budget.
            if (extensible && ci.maxDepth == 0)   // 0 = never annotated; -1 = annotated badly, already reported
                unsupported(("`" + std::string(ci.isAbstractClass ? "abstract" : "virtual") + " class` '"
                             + ci.name + "' must state how deep it may be extended — write `"
                             + (ci.isAbstractClass ? "abstract" : "virtual") + "(maxDepth: "
                             + std::to_string(KAMA_INHERIT_DEPTH) + ") resource " + ci.name
                             + "`. The limit is part of the design, so it is written where the design "
                               "opts in rather than discovered later.").c_str(), line);

            if (!ci.base) continue;

            // The base must have had room to spare.
            int budget = ci.base->maxDepth;
            if (budget <= 0) continue;                  // the base is already being diagnosed
            int mine = ci.isFinalClass ? 0 : ci.maxDepth;
            if (mine < 0) continue;                     // its own annotation is already being diagnosed
            if (mine > budget - 1)
                unsupported(("'" + ci.name + "' extends '" + ci.base->name + "', which allows "
                             + std::to_string(budget) + " more level(s) — so '" + ci.name
                             + "' may allow at most " + std::to_string(budget - 1)
                             + (budget - 1 == 0 ? ", i.e. it must be `final`"
                                                : ", not " + std::to_string(mine))).c_str(), line);
        }
    }
#endif   // KAMA_INHERITANCE
}

// A derived type may NOT widen the hierarchy's public interface (decision A, docs/design/inheritance.md).
//
// It may add FIELDS, add PRIVATE helpers, and override the protected seams the base sanctioned
// (`virtual` = may, `abstract` = must). It may not add a public method, and it may not declare
// `implements`. The public surface is therefore fixed at the ROOT, which makes substitutability total
// rather than aspirational: every handle to a base sees the whole of what any subclass can do.
//
// This is what closes the `Exposer` leak — a subclass re-publishing a protected seam under a new public
// name, which compiles today and hands the world a hook the base deliberately kept internal.
//
// Runs after linkBases (bases + interfaces resolved) and before buildVtables.
#if KAMA_INHERITANCE
void CEmitter::checkDerivedPublicSurface()
{
    for (auto& kv : _classes) {
        ClassInfo& ci = kv.second;
        if (ci.isGenericInst || !ci.base) continue;
        int line = ci.declLine();

        // A contract's methods are public and need not exist on the base, so allowing `implements` here
        // would be a hole straight through the rule. If a hierarchy conforms to a contract, its ROOT says
        // so and every leaf inherits the conformance.
        if (!ci.interfaces.empty())
            unsupported(("a deriving type may not declare `implements` — '" + ci.name + "' extends '"
                         + ci.base->name + "', whose public surface is fixed at the root. Declare the "
                         "contract on '" + ci.base->name + "', or compose instead of extend.").c_str(), line);

        for (auto& mkv : ci.methods) {
            MethodInfo& mi = mkv.second;
            if (mi.visibility != Visibility::Public) continue;
            // ⚠️ Constructors are EXEMPT. A derived type needs its own public `ctor` (`RawChannel.open(…)`),
            // and construction is not part of the substitutable surface — you build a concrete type, then
            // hand it out as its base. Letting the rule swallow ctors would make derived types
            // unconstructible.
            if (mi.isCtor) continue;
            if (findMethod(ci.base, mkv.first, nullptr)) continue;   // redeclaring is a separate question
            unsupported(("'" + ci.name + "' adds a public method '" + mkv.first + "' that '"
                         + ci.base->name + "' does not have — a derived type may not widen the public "
                         "interface. Declare it on '" + ci.base->name + "' (as public, calling a "
                         "`protected virtual` hook), or make it private.").c_str(),
                        mi.node ? mi.node->line : line);
        }
    }
}
#else
void CEmitter::checkDerivedPublicSurface() {}
#endif

// Classes in base-before-derived order.
std::vector<ClassInfo*> CEmitter::topoOrderClasses()
{
    std::vector<ClassInfo*> out;
    std::set<ClassInfo*> done;
    std::function<void(ClassInfo*)> visit = [&](ClassInfo* ci) {
        if (!ci || done.count(ci)) return;
        if (ci->base) visit(ci->base);
        done.insert(ci);
        out.push_back(ci);
    };
    // specialized generic-type instances are emitted by a dedicated pass under _typeSubst,
    // not the normal class loops — exclude them here (their only consumer, header emission).
    for (auto& kv : _classes) if (!kv.second.isGenericInst) visit(&kv.second);
    return out;
}

// order EVERY laid-out struct (normal classes + generic instances + tagged unions) so a
// by-value dependency is always emitted first — base-before-derived AND held-value-before-holder.
// Unlike topoOrderClasses this INCLUDES generic instances and adds by-value field/payload edges, so
// `Box<Rock>`/`class Holder{Rock r;}`/`enum Event{Resize(Vec2)}` lay out correctly. A collection /
// smart-ptr field stores `T*` (a forward decl suffices) — not an edge; a by-value user struct is.
// A back-edge (self / mutual by-value) is a genuine infinite-size type and is reported.
std::vector<ClassInfo*> CEmitter::unifiedStructOrder()
{
    std::vector<ClassInfo*> out;
    std::set<ClassInfo*> done;        // fully ordered
    std::set<ClassInfo*> visiting;    // on the current DFS stack — a re-entry is an infinite-size cycle
    NsCtx savedCtxOuter = _nsCtx;
    std::map<std::string, SharedIdentifier> savedSubstOuter = _typeSubst;

    std::function<void(ClassInfo*)> visit = [&](ClassInfo* ci) {
        if (!ci || done.count(ci) || ci->isScalarRecv) return;   // a payload-less enum is its integer, not a struct
        if (visiting.count(ci)) {
            // This runs from a whole-program pass, where `_collectingUnitPath` is unwound and `_sourcePath`
            // is "" in a multi-file build — so the cycle used to be reported against no file at all. The
            // type that closes the cycle owns the mistake, and `declFile` is where it was written.
            ScopedStr _cu(_collectingUnitPath, ci->declFile);
            unsupported(("type '" + ci->name + "' contains itself by value (infinite size) — hold a "
                         "member behind Owned<...>, Shared<...>, or List<...>").c_str(),
                        ci->declLine());
            return;   // stop unwinding this cycle; the driver aborts on the recorded error
        }
        visiting.insert(ci);

        // Resolve this node's field types concretely: a generic instance binds its type args +
        // use-site scope (Box<Rock> -> Rock is an edge; Box<int32> -> none). Mirrors computeDestructible.
        bool inst = ci->isGenericInst && _genericTypeInsts.count(ci->name);
        if (inst) {
            const GenericTypeInst& gi = _genericTypeInsts[ci->name];
            _nsCtx = _genericTypeInstCtx.count(ci->name) ? _genericTypeInstCtx[ci->name]
                                                         : _genericTypeCtx[gi.templateKey];
            _typeSubst.clear();
            const std::vector<std::string>& ps = _genericTypeParams[gi.templateKey];
            for (size_t i = 0; i < ps.size() && i < gi.typeArgs.size(); ++i) _typeSubst[ps[i]] = gi.typeArgs[i];
        } else {
            _nsCtx = NsCtx{}; _nsCtx.scope = ci->scope; _nsCtx.usings = ci->usings; _nsCtx.symbolAliases = ci->symbolAliases; restoreFileRung(_nsCtx, ci->declFile);
            _typeSubst = savedSubstOuter;   // (typically empty here)
        }

        // A by-value dependency: a field/payload whose C type is a laid-out struct (not a T*-holding
        // collection, not an extern header struct). A `Fixed<T,N>` DOES embed its element by value,
        // so it is a real dependency — both as a field's type and as the Fixed struct's own element.
        auto dep = [&](SharedIdentifier ty) -> ClassInfo* {
            auto it = _classes.find(cType(ty));
            if (it == _classes.end() || it->second.isExternStruct) return nullptr;
            // Pointer-storing collections aren't a by-value dep — EXCEPT `Fixed<T,N>` (inline array) and an
            // allocator-aware iface smart ptr (M11d), whose fat handle embeds `A alloc` by value.
            if (it->second.isIntrinsicColl && it->second.collKind != CollKind::Fixed
                && !(_collections.count(it->second.name) && isIfaceAllocColl(_collections[it->second.name])))
                return nullptr;
            return &it->second;
        };
        std::vector<ClassInfo*> deps;
        if (ci->base) deps.push_back(ci->base);
        for (auto& f : ci->fields) if (ClassInfo* d = dep(f.type)) deps.push_back(d);
        for (auto& v : ci->variants) for (auto& f : v.payload) if (ClassInfo* d = dep(f.type)) deps.push_back(d);
        // a `Fixed<T,N>` struct (`{ T v[N]; }`) embeds T by value -> its layout needs T's.
        if (ci->isIntrinsicColl && ci->collKind == CollKind::Fixed && !ci->collElemClass.empty()) {
            auto it = _classes.find(ci->collElemClass);
            if (it != _classes.end() && !it->second.isExternStruct &&
                !(it->second.isIntrinsicColl && it->second.collKind != CollKind::Fixed))
                deps.push_back(&it->second);
        }
        // an allocator-aware iface smart ptr (M11d) embeds `A alloc` by value -> its layout needs A's struct.
        if (ci->isIntrinsicColl && _collections.count(ci->name) && isIfaceAllocColl(_collections[ci->name])) {
            auto it = _classes.find(_collections[ci->name].allocType);
            if (it != _classes.end() && !it->second.isExternStruct) deps.push_back(&it->second);
        }

        // restore the outer context BEFORE recursing, so each recursed node sets up its own binding.
        _nsCtx = savedCtxOuter; _typeSubst = savedSubstOuter;
        for (ClassInfo* d : deps) visit(d);

        visiting.erase(ci);
        done.insert(ci);
        out.push_back(ci);
    };

    for (auto& kv : _classes)
        if ((!kv.second.isIntrinsicColl && !kv.second.isExternStruct) ||
            (kv.second.isIntrinsicColl && kv.second.collKind == CollKind::Fixed) ||   // Fixed lays out by value
            (kv.second.isIntrinsicColl && _collections.count(kv.second.name)          // iface-ALLOC embeds `A`
                 && isIfaceAllocColl(_collections[kv.second.name])))
            visit(&kv.second);
    _nsCtx = savedCtxOuter; _typeSubst = savedSubstOuter;
    return out;
}

// Build the per-class virtual slot tables and the per-root vtable union.
#if KAMA_INHERITANCE
void CEmitter::buildVtables()
{
    for (ClassInfo* ci : topoOrderClasses()) {
        // Inherit base's vtable model.
        if (ci->base && ci->base->hasVtable) {
            ci->hasVtable  = true;
            ci->vtableRoot = ci->base->vtableRoot;
            ci->slotImpl   = ci->base->slotImpl;   // inherited impls
        }
        auto baseHasVirtual = [](ClassInfo* c, const std::string& m) {
            for (ClassInfo* b = c->base; b; b = b->base) {
                auto it = b->methods.find(m);
                if (it != b->methods.end() && it->second.isVirtual) return true;
            }
            return false;
        };
        // SHADOWING IS AN ERROR. Redeclaring a non-virtual base method with no `override` used to be
        // silently legal at any visibility, and which body ran was decided by the STATIC type — `d.h()`
        // yielding 2 while `base.h()` yielded 1. kama already rejects `public virtual` precisely because
        // a public override is a footgun; this is the same footgun with no keyword marking it at all
        // (C# at least demands `new`). The only way to redefine an inherited method is `override` on a
        // `protected virtual` (may) or `protected abstract` (must) — the type designer decides what is
        // overridable, which is what `protected` + `virtual`/`abstract` is for.
        //
        // ⚠️ Reusing a name that is PRIVATE in the base stays legal, and must: that is not shadowing at
        // all. The base's member is invisible to the derived type, so the two names are unrelated and
        // each type sees its own.
        //
        // ⚠️⚠️ The test below asks the base member's VISIBILITY DIRECTLY, and must NOT be "tidied up" into
        // a `canAccess` call, which is the obvious-looking refactor. `canAccess` answers "may this
        // context REACH that member", and a `friend` grant makes it true — so a base that befriended its
        // subclass would turn the subclass's own same-named private helper into a shadowing error.
        // Friendship grants ACCESS; it does not merge namespaces. The question here is narrower: is the
        // base's member part of the derived type's inherited surface at all? Only visibility answers that.
        // Pinned by tests/inherit_private_name_reuse, which includes the `friend` case.
        for (auto& kv : ci->methods) {
            MethodInfo& mi = kv.second;
            const std::string& mname = kv.first;
            if (!mi.isVirtual && !mi.isCtor && !mi.isStatic && mi.fromContract.empty() && ci->base) {
                ClassInfo* bowner = nullptr;
                MethodInfo* bmi = findMethod(ci->base, mname, &bowner);
                if (bmi && bowner && bmi->visibility != Visibility::Private)
                    unsupported(("'" + ci->name + "' redeclares '" + mname + "', which it inherits from '"
                                 + bowner->name + "' — shadowing is not allowed, because which body runs "
                                 "would be decided by the static type. To redefine it, '" + bowner->name
                                 + "' must declare it `protected virtual`/`protected abstract` and this "
                                 "must say `override`; otherwise rename it.").c_str(),
                                mi.node ? mi.node->line : 0);
            }
            if (!mi.isVirtual) continue;
            // Step 3: `override` must override an actual virtual method in a base class —
            // otherwise there is no vtable slot to re-seat and the emitted C is malformed.
            if (mi.isOverride && !baseHasVirtual(ci, mname))
                unsupported(("'override fn " + mname + "' overrides no virtual method in any base class "
                             "(the base method must be `virtual`/`abstract`)").c_str(),
                            mi.node ? mi.node->line : 0);
            // a `final` slot may not be re-overridden by any subclass, and an override may not drop
            // `const`: the caller sees the BASE declaration, so a const receiver that is legal there must
            // stay legal for every subclass that could be behind the slot. (Adding `const` in an override
            // is fine — it only narrows what the override itself may do.)
            if (mi.isOverride)
                for (ClassInfo* b = ci->base; b; b = b->base) {
                    auto it = b->methods.find(mname);
                    if (it != b->methods.end() && it->second.isVirtual) {
                        if (it->second.isFinal)
                            unsupported(("cannot override '" + mname + "': it is `final` in '" + b->name + "'").c_str(),
                                        mi.node ? mi.node->line : 0);
                        if (it->second.isConst && !mi.isConst)
                            unsupported(("'override fn " + mname + "' drops `const`: it is `const fn` in '"
                                         + b->name + "', so a caller may invoke it on a const receiver — "
                                         "declare the override `const fn` too").c_str(),
                                        mi.node ? mi.node->line : 0);
                        break;   // nearest declaring base wins
                    }
                }
            if (mi.isOverride || ci->slotImpl.count(mname)) {
                // Re-slot an inherited virtual with this class's implementation.
                if (!mi.isAbstract) ci->slotImpl[mname] = mi.cName;
            } else {
                // New virtual slot (abstract slots have no impl until overridden).
                if (!ci->hasVtable) { ci->hasVtable = true; ci->vtableRoot = ci->name; }
                if (!mi.isAbstract) ci->slotImpl[mname] = mi.cName;
                VSlot vs; vs.name = mname; vs.owner = ci->name; vs.node = mi.node;
                _rootVtables[ci->vtableRoot].push_back(vs);
            }
        }
        // A class is abstract if marked OR any virtual slot still has no implementation
        // (an inherited pure method left un-overridden). Either way it cannot be `new`ed —
        // instantiating it would leave a NULL vtable slot and crash on the first call.
        if (ci->hasVtable && !ci->isAbstractClass) {
            for (auto& vs : _rootVtables[ci->vtableRoot])
                if (!ci->slotImpl.count(vs.name)) { ci->isAbstractClass = true; break; }
        }

        // Construction-model M8 Phase E: NO synthesized default ctor. A polymorphic class is constructed
        // only by its named `ctor`s; a factory-built bare local sets its own `__vptr` directly (see the
        // vtable-typed bare-local store in emitLocalVariableDeclaration). "Nothing is constructible by
        // default" (design §5) — a ctor-less polymorphic type is simply not constructible.
    }
    // Whole-program override index for devirtualization: a virtual slot must stay an indirect call
    // iff some class overrides it. A never-overridden slot (and every method of a `final` class /
    // any `final` method) has a unique target, so emitDispatch can lower it to a direct call.
    for (auto& kv : _classes)
        for (auto& mkv : kv.second.methods)
            if (mkv.second.isOverride)
                _overriddenSlots.insert(std::make_pair(kv.second.vtableRoot, mkv.first));
}
#else
void CEmitter::buildVtables() {}
#endif

// An `InlineArray<T>#(N)` whose size never folded registers no collection, so the declaration silently became a
// raw pointer and every diagnostic after it was about something else — "`s` is never assigned" of a ctor that
// assigns it, "raw pointer access requires an `unsafe fn`", "an array literal … its type must be known"
// (consumer KB-23). Called once every module constant, enum member and type constant is settled, so a size
// that still does not fold is the author's to fix: say so at the declaration, naming the size. Returns a
// placeholder for the caller to install (sized to agree with an array-literal initializer, if any), so nothing after this reports the raw pointer instead —
// the build is already refused, so it never reaches C. Null when the type is not an unfolded InlineArray.
SharedIdentifier CEmitter::unsizedFixedPlaceholder(const SharedIdentifier& t, const std::string& what, int line,
                                                   int64_t placeholderSize)
{
    if (!t || !t->value || *t->value != "InlineArray" || !t->genericArgs || t->genericArgs->size() != 2)
        return nullptr;
    SharedIdentifier nArg = (*t->genericArgs)[1];
    int64_t n;
    if (!nArg || constArgN(nArg, n)) return nullptr;
    std::string why = "it must be an integer literal or a `comptime` constant";
    bool reported = false;   // the constant's own initializer already failed, and said why
    if (nArg->value && !nArg->constArgValue) {
        const std::string mk = resolveModuleVar(*nArg->value, nArg->qualifier);
        if (_ctErroredConsts.count(mk)) reported = true;
        else if (!mk.empty() && !_constStatics.count(mk))
            why = "`" + *nArg->value + "` is a runtime `static` — declare it `comptime`";
        else if (mk.empty() && !resolveExternConst(*nArg->value, nArg->qualifier).empty())
            why = "`" + *nArg->value + "` is an `extern const`, whose value the C header defines — kama cannot fold one";
        else if (mk.empty())
            why = "`" + *nArg->value + "` names no `comptime` constant";
    }
    if (!reported)
        unsupported(("the size of " + what + " does not fold to a compile-time integer — " + why).c_str(),
                    line ? line : t->line);
    if (!_synthCtx) _synthCtx = std::make_shared<CodeGenContext>(std::make_shared<std::string>("<synth>"));
    auto one = std::make_shared<IdentifierNode>(*_synthCtx, SharedString());
    one->synthesized   = true;
    one->constArgValue = std::make_shared<Int64Node>(*_synthCtx, placeholderSize);
    auto placeholder = synthClone(*t);
    placeholder->genericArgs = std::make_shared<IdentifierList>(*t->genericArgs);
    (*placeholder->genericArgs)[1] = one;
    registerFixed(placeholder);
    return placeholder;
}

// Resolve every field's declared type in ITS OWN class's scope, once, and remember the answer.
//
// A member's declared type used to be re-resolved wherever it was READ, which put the DECLARING file's
// identifier node in front of the resolver while the CONSUMER's file was installed — so the consumer was
// judged for a name it never spells. Measured on 0.9.175, two sibling files of one module: a 3-line
// `use.kama` holding a `Holder` whose field is a `Kind` was told "`Kind` is declared in `decl.kama` and
// this file does not import it", positioned at line 5 — `decl.kama`'s field line, wearing `use.kama`'s
// name. And the import it demanded was pure ceremony: importing `Kind` and never spelling it built.
//
// ⚠️ The message was the SMALL half. Across a module boundary the consumer's scope prefix differs, so the
// same resolution MISSED instead of firing: `_classes.find` came up empty and the field was silently
// dropped from the analysis. Measured, same program in two places: a `slot Box b;` written INSIDE `Box`'s
// module emits the field-default fill `b.c = Counter__start();`, and written one module over emits
// nothing — identical source, different C, decided by the reader's imports.
//
// So the answer is baked HERE, where the declaring class's scope is installed (the same install
// computeDestructible does below, which already resolves every field of every class this way) and where
// `_refUnit` is null — so `checkReach` returns at its first line and `recordRef` files nothing, for a
// checked reason rather than a hopeful one. This is the `InlineArray`-size fix's shape exactly
// (bakeConstSizes, and see the field-collection site that calls it for the full argument).
//
// ⚠️ TWO fixes that look right and are not:
//   • The read-site scope swap — installing the owner's NsCtx in cTypeInInstance — is MEASURED WRONG:
//     30 corpus fixtures and 17 analysis-agreement pairs, the five-site partial-swap hazard. Do not retry it.
//   • Suppressing checkReach around the read sites fixes the message and leaves the cross-module silent
//     skip, the missing fill, and the cross-file xref entry exactly where they are.
// Nor is this baked into the AST node the way bakeConstSizes bakes a size: a generic template's field
// nodes are SHARED by every instance's ClassInfo, so a node rewrite would freeze one instance's answer
// for all of them. The string lives on FieldInfo, which is per-ClassInfo and cannot alias.
void CEmitter::bakeFieldCTypes()
{
    NsCtx savedNs = _nsCtx;
    auto bake = [&](std::vector<FieldInfo>& fields) {
        for (auto& f : fields) {
            if (!f.type) continue;
            std::string t = cType(f.type);
            // An unbound type param resolves to itself — a template's own `T`, which has no answer until
            // an instance binds it. Leave it unbaked so the read site resolves it under the substitution.
            if (t.empty() || isTypeParamName(t)) continue;
            f.cTypeBaked = t;
        }
    };
    for (auto& kv : _classes) {
        ClassInfo& ci = kv.second;
        // The context install is computeDestructible's, verbatim: a specialized instance's fields are
        // typed in `T`, so resolve them under its binding and the template's scope.
        bool inst = ci.isGenericInst && _genericTypeInsts.count(ci.name);
        if (inst) {
            const GenericTypeInst& gi = _genericTypeInsts[ci.name];
            _nsCtx = _genericTypeInstCtx.count(ci.name) ? _genericTypeInstCtx[ci.name]
                                                        : _genericTypeCtx[gi.templateKey];
            _typeSubst.clear();
            const std::vector<std::string>& ps = _genericTypeParams[gi.templateKey];
            for (size_t i = 0; i < ps.size() && i < gi.typeArgs.size(); ++i) _typeSubst[ps[i]] = gi.typeArgs[i];
        } else {
            _nsCtx = NsCtx{}; _nsCtx.scope = ci.scope; _nsCtx.usings = ci.usings; _nsCtx.symbolAliases = ci.symbolAliases; restoreFileRung(_nsCtx, ci.declFile);
        }
        bake(ci.fields);
        for (auto& v : ci.variants) bake(v.payload);
        if (!inst && !ci.isIntrinsicColl)
            for (auto& f : ci.fields)
                if (SharedIdentifier ph = unsizedFixedPlaceholder(f.type, "field `" + f.name + "`",
                                                                  f.nameId ? f.nameId->line : 0)) {
                    f.type = ph;
                    f.cTypeBaked = cType(ph);
                }
        if (inst) _typeSubst.clear();
    }
    _nsCtx = savedNs;
}

// A field's C type. The baked answer when there is one; otherwise resolve it now, under the owner's type
// arguments — an instance minted after bakeFieldCTypes ran has no baked field, and cTypeInInstance is the
// stronger fallback (bare `cType` would lose the substitution).
//
// ⚠️ THIS IS THE ONLY WAY TO READ A FIELD'S TYPE. `cTypeInInstance(owner, f.type)` at a read site is the
// defect, not a shortcut around it: it hands the DECLARING file's identifier node to the resolver while
// the READER's file is installed. 0.9.176 landed the bake with two callers and left eleven sites on the
// old spelling, so the same bug survived one release in a narrower shape — a field merely PASSED ALONG
// (`takesOther(o: h.k)`) was still judged in the reader's scope. That is worse than the message it
// produced: cross-module the resolution MISSES rather than fires, so the enum-identity rule went silent
// and a `Kind` reached an `Other` parameter with no diagnostic from kama and none from clang either
// (both lower to the same C integer). Every field-type read now comes through here — lvalueCType,
// exprClass, receiverScalarCType, exprEnumType, the fnptr-field invoke and the variant-payload paths —
// and they had to move TOGETHER: typeOfExpr takes the first non-empty of four resolvers, so converting
// some of them would only have made them disagree. tools/check-module-emit-parity.sh case 2 holds it.
std::string CEmitter::fieldCType(const std::string& ownerCls, const FieldInfo& f)
{
    return f.cTypeBaked.empty() ? cTypeInInstance(ownerCls, f.type) : f.cTypeBaked;
}

// A class is destructible if it declares a dtor, has a destructible field, OR
// its base is destructible (transitive). Fixed-point — cycle-safe.
void CEmitter::computeDestructible()
{
    // Seed: an explicit `~dtor` OR a collection/smart-ptr (always owns heap → RAII-dropped; its
    // ClassInfo carries destructible=true, which this reset must preserve — collections are
    // registered before this pass now).
    // A `Fixed<T,N>` is a value (owns no heap), so — unlike the heap collections — it is NOT
    // destructible; its element is a `value`, so there is nothing to drop. ⚠️ A `Simd<T,N>` is the same
    // and for a stronger reason: its element is a numeric PRIMITIVE and its C type is a bare
    // `vector_size` typedef, so there is not even a struct to drop. Both must be excluded here — the
    // test used to read `!= CollKind::Fixed`, which would have made every lane batch RAII-dropped.
    for (auto& kv : _classes)
        kv.second.destructible = kv.second.hasDtor ||
            (kv.second.isIntrinsicColl && kv.second.collKind != CollKind::Fixed
                                       && !isValueVectorKind(kv.second.collKind));
    bool changed = true;
    while (changed) {
        changed = false;
        for (auto& kv : _classes) {
            ClassInfo& ci = kv.second;
            if (ci.destructible || ci.isExternStruct) continue;   // kama doesn't own external structs
            // a specialized instance's fields are typed in `T` — resolve them under its binding
            // (and the template's scope) so `Box<Resource>` correctly sees the owned resource.
            bool inst = ci.isGenericInst && _genericTypeInsts.count(ci.name);
            if (inst) {
                const GenericTypeInst& gi = _genericTypeInsts[ci.name];
                _nsCtx = _genericTypeInstCtx.count(ci.name) ? _genericTypeInstCtx[ci.name]   // use-site ctx
                                                            : _genericTypeCtx[gi.templateKey];
                _typeSubst.clear();
                const std::vector<std::string>& ps = _genericTypeParams[gi.templateKey];
                for (size_t i = 0; i < ps.size() && i < gi.typeArgs.size(); ++i) _typeSubst[ps[i]] = gi.typeArgs[i];
            } else {
                _nsCtx = NsCtx{}; _nsCtx.scope = ci.scope; _nsCtx.usings = ci.usings; _nsCtx.symbolAliases = ci.symbolAliases; restoreFileRung(_nsCtx, ci.declFile);   // resolve field types in ci's scope
            }
            bool d = (ci.base && ci.base->destructible);
            if (!d)
                for (auto& f : ci.fields) {
                    auto it = _classes.find(cType(f.type));
                    if (it != _classes.end() && it->second.destructible) { d = true; break; }
                }
            // a tagged union is destructible if any variant's payload owns a resource.
            if (!d)
                for (auto& v : ci.variants) {
                    for (auto& f : v.payload) {
                        auto it = _classes.find(cType(f.type));
                        if (it != _classes.end() && it->second.destructible) { d = true; break; }
                    }
                    if (d) break;
                }
            // MOVE-ONLY is the sibling question, and it is not the same one: a `resource` that owns
            // nothing (no dtor, no owning field — a token, an identity) is not destructible, but it
            // still moves by declared kind. An intrinsic that holds one — `Result<Token, E>`,
            // `Optional<Token>` — must move too, or a local of that type is never move-tracked and
            // `match (give r)` on it is refused as if `r` were a field. Measured on the first external
            // package: every `Result<K, E>` whose `K` had a dtor worked, and the one whose payload was
            // a bare resource did not. Same fixpoint, same scope setup, read through isMoveOnlyValue
            // so a nested intrinsic (`Optional<Result<Token, E>>`) propagates. A `value` is computed too:
            // isMoveOnlyValue answers by its declared kind and never reads the flag, so for a value it only
            // feeds the refusal below (KR-63).
            bool m = ci.moveOnly || (ci.base && ci.base->moveOnly);
            if (!m && !ci.isIntrinsicColl)
                for (auto& f : ci.fields) {
                    if (isMoveOnlyValue(cType(f.type))) { m = true; break; }
                }
            if (!m && !ci.isIntrinsicColl)
                for (auto& v : ci.variants) {
                    for (auto& f : v.payload) {
                        if (isMoveOnlyValue(cType(f.type))) { m = true; break; }
                    }
                    if (m) break;
                }
            if (inst) _typeSubst.clear();
            if (d) { ci.destructible = true; changed = true; }
            if (m && !ci.moveOnly) { ci.moveOnly = true; changed = true; }
        }
    }
    // Re-derive each collection's elemDestructible from the FINAL class destructibility — a
    // collection registered before the fixpoint saw only `~dtor`-based destructibility, so a
    // transitively-destructible element class would have been missed (element drops skipped → leak).
    for (auto& kv : _collections) {
        CollectionInfo& info = kv.second;
        if (info.kind == CollKind::Bindable) continue;   // fully type-erased; no element dtor
        auto it = _classes.find(info.elemClass);
        bool known = !info.elemClass.empty() && it != _classes.end();
        info.elemDestructible = known && it->second.destructible;
        info.elemCopyable     = known && it->second.copyable;   // deep-copy each element
    }
    // A `value` owns nothing. `destructible` (computed above, transitively over base + owned fields +
    // collections + smart-ptrs) is exactly "owns something to drop", so a destructible `value` is a
    // design/field disagreement: declare it a `resource`. (A raw `UnsafePtr`/borrowed contract confers no
    // ownership → not destructible → correctly still a value.) Only user `Value` types are checked —
    // compiler-built `Intrinsic` types (collections/smart-ptrs/variants) own by their own machinery.
    for (auto& kv : _classes) {
        ClassInfo& ci = kv.second;
        if (ci.kind == TypeKind::Value && ci.destructible && !ci.isExternStruct) {
            ScopedStr _cu(_collectingUnitPath, ci.declFile);   // whole-program pass: see diagFile()
            unsupported(("a `value` owns nothing, but `" + ci.name + "` transitively owns a resource "
                         "— declare it `type resource`").c_str(), ci.declLine());
        }
        // ...and a `value` is COPIED, so it may not hold a move-only field either: a resource that owns
        // nothing (an `Atomic`, a token) still has identity, and copying the holder would make two of it
        // (KR-63 — `Holder k = h; k.a.store(5)` left `h.a` untouched). SPEC: a resource "owns something,
        // or has identity"; `destructible` answers the first half, `moveOnly` the second.
        else if (ci.kind == TypeKind::Value && ci.moveOnly && !ci.isExternStruct) {
            ScopedStr _cu(_collectingUnitPath, ci.declFile);
            unsupported(("a `value` is copied, but `" + ci.name + "` holds a move-only resource, which has "
                         "identity and must not be copied — declare it `type resource`").c_str(), ci.declLine());
        }
    }
}

// Serialization mode gate: does T transitively REACH a Shared/Weak pointer? The tighter sibling of
// computeDestructible — same cycle-safe fixpoint (base + fields + variant payloads, generic instances
// resolved under their binding), with two differences: it STOPS at a Shared/Weak (such a field makes the
// owner graph-mode; it does NOT recurse through the pointee), and a plain heap collection (List/Array/
// string) or a Fixed<T,N> contributes nothing unless its ELEMENT reaches a pointer (whereas every heap
// collection is destructible). false => by-value/tree serialization; true => object-graph.
// `Owned<X>` is NOT a pointer here: a unique subtree serializes inline, byte-identical to an `X` field
// (the conformance is the triad's own, lib/std/memory/owned.kama), so an `Owned` reaches exactly when
// its POINTEE does — it is walked THROUGH, the way a by-value field is.
// Consumed by the serialization lowering (Phase C+); inert until then.
void CEmitter::computeReachesPointer()
{
    // Seed: only the SHARED smart pointers ARE pointers. Everything else (scalars, strings, enums, other
    // collections, user types, `Owned`) starts false and earns `true` only by transitively holding one.
    for (auto& kv : _classes) {
        bool intrinsicPtr = kv.second.isIntrinsicColl &&
            (kv.second.collKind == CollKind::Shared || kv.second.collKind == CollKind::Weak);
        // A concrete-element triad instance (`Shared<Leaf>`) is a library generic instance, not intrinsic —
        // recognize it by its template key.
        bool triadPtr = false;
        auto g = _genericTypeInstOf.find(kv.first);
        if (g != _genericTypeInstOf.end())
            triadPtr = (g->second == _sharedTmpl || g->second == _weakTmpl);
        kv.second.reachesPointer = intrinsicPtr || triadPtr;
    }
    bool changed = true;
    while (changed) {
        changed = false;
        for (auto& kv : _classes) {
            ClassInfo& ci = kv.second;
            if (ci.reachesPointer || ci.isExternStruct) continue;
            // a specialized instance's fields are typed in `T` — resolve them under its binding
            // (and the template's scope), mirroring computeDestructible.
            bool inst = ci.isGenericInst && _genericTypeInsts.count(ci.name);
            if (inst) {
                const GenericTypeInst& gi = _genericTypeInsts[ci.name];
                _nsCtx = _genericTypeInstCtx.count(ci.name) ? _genericTypeInstCtx[ci.name]   // use-site ctx
                                                            : _genericTypeCtx[gi.templateKey];
                _typeSubst.clear();
                const std::vector<std::string>& ps = _genericTypeParams[gi.templateKey];
                for (size_t i = 0; i < ps.size() && i < gi.typeArgs.size(); ++i) _typeSubst[ps[i]] = gi.typeArgs[i];
            } else {
                _nsCtx = NsCtx{}; _nsCtx.scope = ci.scope; _nsCtx.usings = ci.usings; _nsCtx.symbolAliases = ci.symbolAliases; restoreFileRung(_nsCtx, ci.declFile);
            }
            bool r = (ci.base && ci.base->reachesPointer);
            if (!r)
                for (auto& f : ci.fields) {
                    auto it = _classes.find(cType(f.type));
                    if (it != _classes.end() && it->second.reachesPointer) { r = true; break; }
                }
            if (!r)
                for (auto& v : ci.variants) {
                    for (auto& f : v.payload) {
                        auto it = _classes.find(cType(f.type));
                        if (it != _classes.end() && it->second.reachesPointer) { r = true; break; }
                    }
                    if (r) break;
                }
            // An intrinsic collection (List/Array/string/Fixed) reaches a pointer iff its ELEMENT does —
            // the element type isn't a walkable field, so consult the collection's elemClass directly.
            // The interface-erased `Owned<Contract>` is walked through the same way, and its element is a
            // contract: it reaches iff ANY nominal implementor does (the closed world the tagged inline form
            // dispatches over).
            if (!r && ci.isIntrinsicColl) {
                auto cit = _collections.find(ci.name);
                if (cit != _collections.end()) {
                    const std::string& elem = cit->second.elemClass;
                    auto e = _classes.find(elem);
                    if (e != _classes.end() && e->second.reachesPointer) r = true;
                    else if (ci.collKind == CollKind::Owned && isInterface(elem))
                        for (auto& kv2 : _classes) {
                            const ClassInfo& c2 = kv2.second;
                            if (!c2.reachesPointer) continue;
                            if (std::find(c2.interfaces.begin(), c2.interfaces.end(), elem) != c2.interfaces.end()) { r = true; break; }
                        }
                }
            }
            // A LIBRARY generic instance reaches iff one of its TYPE ARGUMENTS does. Its own fields are an
            // `UnsafePtr<T>` and bookkeeping — never a walkable class — so the field loop above sees
            // nothing, which is why this has to be asked separately.
            //
            // ⚠️ This used to ask only about `Owned<X>`, so a LIBRARY COLLECTION's element was never
            // walked: an owner holding `DynamicArray<Shared<X>>` did not reach a pointer, was never a graph
            // node, and the failure surfaced as "`DynamicArray` … has none. Give it `@generate(Serializable)`"
            // — advice that cannot be followed, blaming the container for what the element caused.
            // SPEC.md claimed the walk covered collection elements; it did not.
            if (!r && inst) {
                const GenericTypeInst& gi = _genericTypeInsts[ci.name];
                for (auto& a : gi.typeArgs) {
                    auto e = _classes.find(cType(a));
                    if (e != _classes.end() && e->second.reachesPointer) { r = true; break; }
                }
            }
            if (inst) _typeSubst.clear();
            if (r) { ci.reachesPointer = true; changed = true; }
        }
    }
}

// An intrinsic `Shared`/`Weak` collection OR a concrete-element triad instance of one (`Shared<Leaf>`) —
// a NON-ATOMIC shared refcount. `Owned` is deliberately excluded: it is unique, so a move transfers it
// whole with no shared counter to race.
bool CEmitter::isSharedOrWeakClass(const std::string& cls) const
{
    auto it = _classes.find(cls);
    if (it != _classes.end() && it->second.isIntrinsicColl &&
        (it->second.collKind == CollKind::Shared || it->second.collKind == CollKind::Weak))
        return true;
    auto g = _genericTypeInstOf.find(cls);
    return g != _genericTypeInstOf.end() && (g->second == _sharedTmpl || g->second == _weakTmpl);
}

// An `Atomic<T>` instance (std::concurrent, M6) — the one sanctioned cross-isolate shared-mutable cell.
// Used to exempt it from the disjoint-borrow rule (several children may borrow the SAME atomic cell).
bool CEmitter::isAtomicClass(const std::string& cls) const
{
    if (_atomicTmpl.empty()) return false;
    auto g = _genericTypeInstOf.find(cls);
    return g != _genericTypeInstOf.end() && g->second == _atomicTmpl;
}

// The refcount FLAVOR of a `Shared<T>`/`Weak<T>` instance (M6.2): over a deeply-immutable `T` the control
// block uses the atomic ops, so any number of isolates may hold the handle; over a mutable `T` it keeps
// the cheap non-atomic `Rc` ops. Selected at emit time by the kama_ctrl.h seam (`__kama_ctrl_atomic()`),
// so it must be settled here in collectProgram, before any body emits. It used to be a side effect of
// seeding the sendability fixpoint; the fixpoint is gone (sendability is DECLARED and verified now — see
// checkSendableDeclarations) and the flavor decision, which selects emitted code, stays where it was.
void CEmitter::computeAtomicRefcount()
{
    for (auto& kv : _classes) {
        if (!isSharedOrWeakClass(kv.first)) continue;
        std::string elem;
        auto gi = _genericTypeInsts.find(kv.first);
        if (gi != _genericTypeInsts.end() && !gi->second.typeArgs.empty()) elem = cType(gi->second.typeArgs[0]);
        else { auto ci = _collections.find(kv.first); if (ci != _collections.end()) elem = ci->second.elemClass; }
        if (elem.empty() || !deeplyImmutable(elem)) continue;
        kv.second.useAtomicRefcount = true;
        auto ci = _collections.find(kv.first);
        if (ci != _collections.end()) ci->second.useAtomicRefcount = true;
    }
}

// Resolve names the way `ci`'s own body does — its namespace, and for a generic instance its parameter
// binding. The caller SAVES `_nsCtx`/`_typeSubst` before and RESTORES them after: the whole-program passes
// that use this run after emission too, and a partial swap left behind on an emission path is the
// five-site hazard that broke 30 fixtures once already.
void CEmitter::enterClassCtx(const ClassInfo& ci)
{
    bool inst = ci.isGenericInst && _genericTypeInsts.count(ci.name);
    if (inst) {
        const GenericTypeInst& gi = _genericTypeInsts[ci.name];
        _nsCtx = _genericTypeInstCtx.count(ci.name) ? _genericTypeInstCtx[ci.name] : _genericTypeCtx[gi.templateKey];
        _typeSubst.clear();
        const std::vector<std::string>& ps = _genericTypeParams[gi.templateKey];
        for (size_t i = 0; i < ps.size() && i < gi.typeArgs.size(); ++i) _typeSubst[ps[i]] = gi.typeArgs[i];
    } else {
        _nsCtx = NsCtx{}; _nsCtx.scope = ci.scope; _nsCtx.usings = ci.usings; _nsCtx.symbolAliases = ci.symbolAliases; restoreFileRung(_nsCtx, ci.declFile);
    }
}

// Does contract `name` require `Sendable` of every implementor — `type contract Job implements Sendable`?
// Answered for a plain contract, a generic-contract template, and a specialized instance (via its template).
bool CEmitter::contractRequiresSendable(const std::string& name) const
{
    auto it = _interfaces.find(name);
    if (it != _interfaces.end()) {
        if (it->second.requiresSendable) return true;
        if (!it->second.templateKey.empty()) {
            auto gt = _genericContracts.find(it->second.templateKey);
            return gt != _genericContracts.end() && gt->second.requiresSendable;
        }
        return false;
    }
    auto gt = _genericContracts.find(name);
    return gt != _genericContracts.end() && gt->second.requiresSendable;
}

// Is `cls` (a class key / C type) Sendable — may a value of it cross an isolate boundary?
//
// DECLARED, not computed. A user type says `implements Sendable` and the compiler VERIFIES the claim over
// every field, base and variant payload (checkSendableDeclarations); a crossing — a `spawn` bundle, a
// `Channel<T: Sendable>` element — requires the declaration. The `immutable` model: you write it, the
// compiler double-checks it, and a type nobody annotated does not cross. What answers WITHOUT a
// declaration is exactly what cannot carry one:
//   - a primitive and `string`: conformances the prelude declares (`type intrinsic <…> implements Sendable`)
//   - a payload-less `enum`, a bare `fnptr` value: scalars with no interior
//   - `UnsafePtr<T>` and an extern struct: the C seam, stated here rather than hidden
//   - `InlineArray<T>`/`Simd<T>`: iff `T` is (a comptime-sized value with no declaration site of its own)
//   - a boxed contract (`Owned<C>`, the type-erased fat handle): iff `C` refines `Sendable`
//     (`type contract C implements Sendable`), which makes every implementor declare it and be verified
// and what never answers yes: a `BindableFunctionPtr`, whose type names a signature and cannot show
// whether it retains a `Shared` receiver — the erasure hole the old structural walk could not see.
// A library generic instance (`DynamicArray<T, A>`, `Shared<T, A>`) is judged NOMINALLY like a user type:
// the stdlib writes `Sendable when [T: Sendable, A: Sendable]` on the container and `when [T: Immutable]`
// on the shared pointer, the `when` gate is decided per instance at registration, and `interfaces` holds
// the verdict. That is the rule "a `Shared<T>` may cross iff `T` cannot change", written in kama.
//
// `unsendableReason` is the same walk asked "why not": "" for Sendable, else one clause for a diagnostic.
bool CEmitter::isSendableClass(const std::string& cls)
{
    return unsendableReason(cls).empty();
}

std::string CEmitter::unsendableReason(const std::string& cls)
{
    const std::string& S = _sendableContract;
    if (S.empty()) return "";                       // no `Sendable` contract in this program: nothing to judge by
    auto declaredOn = [&](const std::string& key) {
        auto rc = _intrinsicConformances.find(key);
        return rc != _intrinsicConformances.end() && rc->second.count(S) != 0;
    };
    auto it = _classes.find(cls);
    if (it == _classes.end()) {
        if (cls.empty()) return "";
        if (cls.back() == '*') return "";                              // `UnsafePtr<T>` — the C seam
        if (isSigType(cls)) return "";                                 // a bare `fnptr` value: code, no receiver
        if (isEnum(cls)) return "";                                    // a payload-less enum: a scalar
        const std::string pk = primKeyOfCType(cls);
        if (isScalarPrimKey(pk))
            return declaredOn(pk) ? "" : "`" + pk + "` does not declare `implements Sendable`";
        return "";                                                     // a C typedef from an extern header: the seam
    }
    const ClassInfo& ci = it->second;
    if (ci.isExternStruct) return "";                                  // C data: the seam
    if (isBindableClass(cls))
        return "a `BindableFunctionPtr` may retain a `Shared` receiver its type cannot show";
    if (ci.isIntrinsicColl) {
        switch (ci.collKind) {
            case CollKind::String:   // keyed by its C name in the pre-scan (`primKey` of a `string` target falls through to cType)
                return (declaredOn(cls) || declaredOn("string")) ? "" : "`string` does not declare `implements Sendable`";
            case CollKind::Fixed: case CollKind::Simd: case CollKind::Mask: {   // `InlineArray<T>`/`Simd<T>`: iff T
                auto co = _collections.find(cls);
                const std::string elem = co != _collections.end() ? co->second.elemCType : "";
                const std::string r = elem.empty() ? "" : unsendableReason(elem);
                return r.empty() ? "" : "its element `" + elem + "` is not Sendable (" + r + ")";
            }
            case CollKind::Owned: case CollKind::Shared: case CollKind::Weak: {
                // The intrinsic smart-pointer path is the CONTRACT-element box (`Owned<C>`, routed here by
                // registerGenericTypeInst); a concrete element is an ordinary library instance, judged below.
                const std::string& elem = ci.collElemClass;
                if (isInterface(elem) || _genericContracts.count(elem)) {
                    if (contractRequiresSendable(elem)) return "";
                    return "it boxes contract `" + elem + "`, which does not require `Sendable` of its "
                           "implementors (`type contract " + elem + " implements Sendable`)";
                }
                if (ci.collKind == CollKind::Owned) {
                    const std::string r = unsendableReason(elem);
                    return r.empty() ? "" : "its pointee `" + elem + "` is not Sendable (" + r + ")";
                }
                return deeplyImmutable(elem) ? "" : "`" + elem + "` is not `immutable`, so the shared refcount is not atomic";
            }
            default: break;
        }
    }
    for (auto& itf : ci.interfaces) if (itf == S) return "";           // NOMINAL: declared (and `when`-gated)
    // A generic instance whose TEMPLATE declares it: say which `when` condition failed for which argument,
    // so an arena-backed container names its allocator rather than "does not declare".
    if (ci.isGenericInst && _genericTypeInsts.count(cls)) {
        const GenericTypeInst& gi = _genericTypeInsts[cls];
        auto ti = _genericTypes.find(gi.templateKey);
        ClassBaseDeclarationNode* tb = ti != _genericTypes.end() ? ti->second.baseTypesDecl() : nullptr;
        if (tb && tb->interfaces) {
            const NsCtx savedCtx = _nsCtx;
            const std::map<std::string, SharedIdentifier> savedSubst = _typeSubst;
            enterClassCtx(ci);
            std::string out;
            const std::vector<std::string>& ps = _genericTypeParams[gi.templateKey];
            for (auto& itf : *tb->interfaces) {
                if (!itf || !itf->value || resolveUserName(*itf->value, itf->qualifier) != S) continue;
                if (!itf->whenParams) break;
                for (size_t c = 0; c < itf->whenParams->size() && out.empty(); ++c) {
                    auto& p = (*itf->whenParams)[c];
                    auto& b = itf->whenBounds ? (*itf->whenBounds)[c] : p;
                    const std::string pn = p && p->value ? *p->value : "";
                    std::map<std::string, SharedIdentifier> bind;
                    for (size_t i = 0; i < ps.size() && i < gi.typeArgs.size(); ++i) bind[ps[i]] = gi.typeArgs[i];
                    const std::string bn = exactBoundName(resolveWhenBound(b), b, bind);
                    for (size_t i = 0; i < ps.size() && i < gi.typeArgs.size(); ++i) {
                        if (ps[i] != pn) continue;
                        if (satisfiesBound(primKey(gi.typeArgs[i]), bn)) break;
                        const std::string ac = cType(gi.typeArgs[i]);
                        const std::string why = bn == S ? unsendableReason(ac) : "";
                        out = "its type argument `" + ac + "` (for `" + pn + "`) is not `" + bn + "`"
                            + (why.empty() ? "" : " (" + why + ")");
                        break;
                    }
                }
                break;
            }
            _nsCtx = savedCtx; _typeSubst = savedSubst;
            if (!out.empty()) return out;
        }
    }
    return "`" + cls + "` does not declare `implements Sendable`";
}

// M6.2 predicate: is `cls` a deeply-immutable class? (Primitives/enums aren't in `_classes`, so a non-class
// name — a scalar, `UnsafePtr`, etc. — is not deeply immutable here; that's handled by fieldTypeDeeplyImmutable.)
bool CEmitter::deeplyImmutable(const std::string& cls) const
{
    auto it = _classes.find(cls);
    return it != _classes.end() && it->second.deeplyImmutable;
}
// Is a FIELD/variant-payload type deeply immutable — admissible inside an `immutable` type? A primitive
// scalar (incl. `bool`/`float`/`char`) or the immutable `string` is an immutable leaf; an `enum` is an
// immutable value; a named user type is immutable iff its class is `deeplyImmutable`. Everything else — a raw
// `UnsafePtr`, an `Owned`/`Shared`/`Weak`, a mutable collection, a `contract` box — is NOT (a mutable alias exists).
// Resolves `type` under the caller's current `_typeSubst`/`_nsCtx` (set by computeDeeplyImmutable per class).
bool CEmitter::fieldTypeDeeplyImmutable(const SharedIdentifier& type) const
{
    if (!type) return false;
    // Primitive leaves: INT8..CHAR (1..14) EXCEPT void (13). `string` (12) is deeply immutable.
    if (type->builtInVal >= IDENTIFIER_INT8_VAL && type->builtInVal <= IDENTIFIER_CHAR_VAL
        && type->builtInVal != IDENTIFIER_VOID_VAL)
        return true;
    // ⚠️ NOT in that span — `isize`/`usize` are APPENDED after it in kama.ast.h so the existing ranges
    // keep meaning what they meant, which puts the burden on each site that should also cover a size
    // type to name them (the `Atomic<T>` element check does exactly this). THIS site did not, so
    // `type immutable value P { isize n; }` was rejected as holding "a mutable member of type
    // `ptrdiff_t`" — a scalar with no interior mutability, described by the error's own list of what IS
    // allowed ("a primitive"). It read as a compiler fault because it is one.
    //
    // It was never right: before 0.9.136 these two were primitives WITHOUT a builtInVal, so they fell
    // through to `deeplyImmutable(cType)`, found no class named `ptrdiff_t`, and returned false the same
    // way. That campaign converted ~13 such sites and this one was missed, which is what makes the span
    // comment in kama.ast.h worth obeying literally rather than trusting a sweep to have been complete.
    if (type->builtInVal == IDENTIFIER_ISIZE_VAL || type->builtInVal == IDENTIFIER_USIZE_VAL
        || type->builtInVal == IDENTIFIER_CLONG_VAL || type->builtInVal == IDENTIFIER_CULONG_VAL)   // (0.9.232) named, per the span rule
        return true;
    std::string ct = const_cast<CEmitter*>(this)->cType(type);
    if (isEnum(ct)) return true;
    return deeplyImmutable(ct);   // a user class -> its computed flag; an UnsafePtr/Owned/Shared/collection -> false
}

// M6.2: the GREATEST-fixpoint dual of computeReachesPointer(). Seed every `immutable`-qualified type true,
// then FALSIFY any whose base/field/variant-payload is not deeply immutable, to a fixpoint (so a cycle of
// purely-immutable types stays true). Finally, a type that CARRIES `immutable` but failed is a compile error
// naming the first mutable part — the qualifier is a verified guarantee, never a silent downgrade.
void CEmitter::computeDeeplyImmutable()
{
    for (auto& kv : _classes)
        kv.second.deeplyImmutable = kv.second.isImmutableQualified;

    // Set the field-resolution context for class `ci` exactly as enterClassCtx does.
    auto enterCtx = [&](ClassInfo& ci) -> bool {
        bool inst = ci.isGenericInst && _genericTypeInsts.count(ci.name);
        if (inst) {
            const GenericTypeInst& gi = _genericTypeInsts[ci.name];
            _nsCtx = _genericTypeInstCtx.count(ci.name) ? _genericTypeInstCtx[ci.name]
                                                        : _genericTypeCtx[gi.templateKey];
            _typeSubst.clear();
            const std::vector<std::string>& ps = _genericTypeParams[gi.templateKey];
            for (size_t i = 0; i < ps.size() && i < gi.typeArgs.size(); ++i) _typeSubst[ps[i]] = gi.typeArgs[i];
        } else {
            _nsCtx = NsCtx{}; _nsCtx.scope = ci.scope; _nsCtx.usings = ci.usings; _nsCtx.symbolAliases = ci.symbolAliases; restoreFileRung(_nsCtx, ci.declFile);
        }
        return inst;
    };

    bool changed = true;
    while (changed) {
        changed = false;
        for (auto& kv : _classes) {
            ClassInfo& ci = kv.second;
            if (!ci.deeplyImmutable) continue;   // only a qualified candidate can lose the property
            bool inst = enterCtx(ci);
            bool ok = !(ci.base && !ci.base->deeplyImmutable);
            if (ok)
                for (auto& f : ci.fields)
                    if (!fieldTypeDeeplyImmutable(f.type)) { ok = false; break; }
            if (ok)
                for (auto& v : ci.variants) {
                    for (auto& f : v.payload) if (!fieldTypeDeeplyImmutable(f.type)) { ok = false; break; }
                    if (!ok) break;
                }
            if (inst) _typeSubst.clear();
            if (!ok) { ci.deeplyImmutable = false; changed = true; }
        }
    }

    // Diagnostic: a qualified type that did NOT survive has a mutable part — name the first offender.
    for (auto& kv : _classes) {
        ClassInfo& ci = kv.second;
        if (!ci.isImmutableQualified || ci.deeplyImmutable) continue;
        bool inst = enterCtx(ci);
        std::string field, ty;
        if (ci.base && !ci.base->deeplyImmutable) { field = "(base)"; ty = ci.baseName; }
        if (field.empty())
            for (auto& f : ci.fields)
                if (!fieldTypeDeeplyImmutable(f.type)) { field = f.name; ty = cType(f.type); break; }
        if (field.empty())
            for (auto& v : ci.variants) {
                for (auto& f : v.payload) if (!fieldTypeDeeplyImmutable(f.type)) { field = f.name; ty = cType(f.type); break; }
                if (!field.empty()) break;
            }
        if (inst) _typeSubst.clear();
        unsupported(("`immutable` type `" + ci.name + "` has a mutable member `" + field + "` of type `" + ty
                     + "` — every part of an `immutable` type must itself be deeply immutable (a primitive, "
                       "`string`, `enum`, or another `immutable` type); it may not hold an `UnsafePtr`, an "
                       "`Owned`/`Shared`/`Weak`, or a mutable collection").c_str(),
                    ci.declLine());
    }
}

// Does `p` name memory that OUTLIVES the call, so a view constructed from it can borrow it? A `ref`/`out`
// parameter IS the caller's storage; a raw `UnsafePtr<T>` and a view both already point into memory someone else
// owns. Everything else — an `int64`, a `string`, a by-value value type — is the callee's own frame, and a
// view over it dangles the moment the constructor returns.
//
// Matches the SOURCE spelling on purpose: this runs with `_typeSubst` empty, so cType() on an
// unsubstituted contract type parameter resolves nothing useful. `_viewTypeNames` holds bare source names
// for exactly this kind of check.
// The `UnsafePtr` containment rule. TRUE when `type` is `UnsafePtr` or carries one in a generic argument.
// The recursion is the whole point: `Optional<UnsafePtr>` (what `Allocator.allocate` returns) never spells
// the word at the binding site — `match (a.allocate(…)) { case Some(value: p): … }` — so a rule that
// matched the spelled token would let the raw pointer out through a function carrying no marker at all.
bool CEmitter::namesUnsafePtr(SharedIdentifier type)
{
    if (!type || !type->value) return false;
    if (isRawPtrName(*type->value)) return true;
    if (type->genericArgs) {
        for (auto& a : *type->genericArgs) if (namesUnsafePtr(a)) return true;
    } else if (namesUnsafePtr(type->genericArg)) return true;
    return false;
}

// `cchar` is C's `char`: an FFI ELEMENT, legal only as what a raw pointer points at — `UnsafePtr<cchar>`,
// `UnsafeConstPtr<cchar>`, nested (`UnsafePtr<UnsafeConstPtr<cchar>>`), in an extern signature, a `type
// extern value` field, a local holding such a pointer. It never names a value: kama's `char` is a 32-bit
// codepoint and C's is a byte that is a third type beside `int8`/`uint8`, so a `cchar` VALUE would be a
// number with no width story and a codepoint with no encoding. Reading the bytes is a cast to
// `UnsafePtr<uint8>`. This predicate reads the SOURCE spelling, never `cType`, so it is safe on an extern
// signature, on `This`/`Base` and on an unbound `T` (the shape of `namesUnsafePtr` above).
bool CEmitter::containsBareCChar(SharedIdentifier type, bool underRawPtr)
{
    if (!type) return false;
    if (type->builtInVal == IDENTIFIER_CCHAR_VAL) return !underRawPtr;
    const bool raw = type->value && isRawPtrName(*type->value);
    if (type->genericArgs) {
        for (auto& a : *type->genericArgs) if (containsBareCChar(a, raw)) return true;
    } else if (containsBareCChar(type->genericArg, raw)) return true;
    return false;
}
bool CEmitter::rejectBareCChar(const SharedIdentifier& type, const char* what, int line)
{
    if (!containsBareCChar(type)) return false;
    unsupported((std::string("`cchar` is C's `char`, an FFI element only — it may appear only inside "
                 "`UnsafePtr<…>`/`UnsafeConstPtr<…>`, not as ") + what
                 + "; cast to `UnsafePtr<uint8>` to read bytes").c_str(), line);
    return true;
}

// One diagnostic for every raw-pointer position, so the seam reads the same wherever it is hit.
// Does `ci` DECLARE that it hands out a view — a `@viewable` contract carrying a nullary `view()`?
//
// `borrow` and `parallel_for` are the two constructs that reach into a container for one, and both were
// duck-typed on the NAME `view`. Nominal is what `foreach` already is, and what the mint rule makes almost
// free: a type whose `view()` MINTS one must implement such a contract already, or the mint itself would
// be rejected. What this adds is the delegating case — a `view()` that forwards someone else's view — and
// the reason to close it is that `borrow` opens the window a view lives in, so the host had better be the
// thing being viewed.
//
// Resolution stays STRUCTURAL: this is a gate, never a dispatch, which is what keeps the emitted call
// direct and the ECS path free of vtables.
// Is `member` a mint GRANTED to `ci` — a nullary, non-ctor member of a `@viewable` contract it
// implements? The grant has always named its own member (`Viewable<V>.view`, `Iterable<T>.iterator`,
// `ValuesIterable<I>.values`, a user's `Spanned<S>.span`); `borrow` used to ignore that and hardcode the
// name `view`, which left every iterator — and every `Map`, which has no `view()` — with no window it
// could open. Reading the grant is what makes the rule cover all `type view` kinds, not just `View<T>`.
bool CEmitter::grantedMint(const ClassInfo& ci, const std::string& member) const
{
    for (auto& ifn : ci.interfaces) {
        auto it = _interfaces.find(ifn);
        if (it == _interfaces.end() || !it->second.isViewable) continue;
        for (auto& m : it->second.methods)
            if (!m.isCtor && m.name == member && (!m.params || m.params->empty())) return true;
    }
    return false;
}

// `parallel_for` needs CONTIGUOUS storage it can WRITE (its binding is `ref`), so unlike `borrow` it wants
// one specific grant: `viewMut()`, the writable half.
bool CEmitter::declaresViewable(const ClassInfo& ci) const { return grantedMint(ci, "viewMut"); }

bool CEmitter::rejectRawOutsideUnsafe(const char* what, int line)
{
    if (_inUnsafe) return false;
    unsupported((std::string(what) + " is a raw pointer, so it requires an `unsafe fn` — mark the "
                 "enclosing function `unsafe`").c_str(), line);
    return true;
}

// A `@viewable` contract is a MINT PROTOCOL, not a value. It exists so the type being VIEWED can declare
// that it is — and boxing one into a fat pointer would erase exactly the identity the grant is about,
// leaving a `Viewable<View<T>>` that says "somebody hands out a view" and can no longer say who. It is also
// what a boxed `Iterable<T>` would mean, and kama has never boxed an iterator: `foreach` resolves
// structurally and emits direct monomorphized calls, which is the whole reason a view-kind iterator costs
// nothing.
//
// So these contracts emit no C type at all (see emitInterfaceTypes), and this is the diagnostic that keeps
// that an intentional rule rather than a clang error about a missing struct. A `@viewable` contract stays
// perfectly usable where a contract belongs: an `implements` clause, and a generic BOUND.
void CEmitter::rejectMintProtocolValue(SharedIdentifier ty, const char* what, int line)
{
    if (!ty || !ty->value) return;
    auto viewable = [&](const std::string& k) {
        auto i = _interfaces.find(k);
        if (i != _interfaces.end()) return i->second.isViewable;
        auto g = _genericContracts.find(k);
        return g != _genericContracts.end() && g->second.isViewable;
    };
    if (!viewable(cType(ty)) && !viewable(*ty->value) && !viewable(qualify(*ty->value))) return;
    unsupported(("`" + *ty->value + "` is a mint protocol — it declares WHO may hand out a view, so there "
                 "is no value of it to be " + what + ". Use it in an `implements` clause, or as a generic "
                 "bound (`<T: " + *ty->value + ">`)").c_str(), line);
}

// Does this type name a `type view`? Answered from the SOURCE spelling, like `namesUnsafePtr` — the rule
// is about what the author wrote, and it has to work on a bodiless contract member where there is no C
// type to ask about.
bool CEmitter::namesViewType(SharedIdentifier t) const
{
    if (!t || !t->value) return false;
    return _viewTypeNames.count(*t->value) > 0 || _viewTypeNames.count(qualify(*t->value)) > 0;
}

// A view IS a borrow, so `ref`/`out View<T>` is a borrow of a borrow — and the only thing the extra
// indirection buys is the power to RESEAT the caller's view, at storage the caller never named. That is
// finding ④. Zero of these existed in the corpus, so the ban costs nothing and removes the whole
// cross-function half of the problem: a view can then only be aimed at something within one frame.
void CEmitter::rejectViewByRef(FunctionParameterNode* p, const std::string& owner, int line)
{
    if (!p || !paramByRef(p) || !namesViewType(p->type)) return;
    const std::string nm = (p->identifier && p->identifier->value) ? *p->identifier->value : "a parameter";
    unsupported(("`" + owner + "` takes `" + nm + "` by `" + (paramIsOut(p) ? "out" : "ref")
                 + "` — a view is already a borrow, so it cannot be passed by `ref`/`out`; that would let "
                 "the callee reseat it at storage the caller never named. Pass it by value (a view is two "
                 "words), or return one, which the view-return rule already checks").c_str(), line);
}

void CEmitter::checkSignatureRawPtr(bool isUnsafe, SharedIdentifier ret, SharedParameterList params,
                                    const std::string& name, int line)
{
    // Rides along here because this is the one hook both the free-function and the method arm already call
    // with a whole signature in hand — and unlike the raw-pointer half it has no `unsafe` escape, so it is
    // checked before the early return below.
    rejectMintProtocolValue(ret, "returned", line);
    if (params) for (auto& p : *params) if (p) rejectMintProtocolValue(p->type, "a parameter", line);
    // STAGED, not decided: `_viewTypeNames` is filled by `collectClasses`, which runs after this pass,
    // so whether a parameter names a view is not knowable yet. Capture the unit path with it — a late
    // check has no unit context of its own, and misattributing the FILE of a non-local declaration is
    // a mistake this repo has already made once (tools/check-diag-file.sh).
    if (params) for (auto& p : *params)
        if (p && paramByRef(p.get()) && p->type && p->type->value)
            _pendingViewByRef.push_back({ p.get(), name, line, _collectingUnitPath });
    if (isUnsafe) return;
    const char* where = nullptr;
    if (namesUnsafePtr(ret)) where = "returns";
    else if (params) for (auto& p : *params) if (p && namesUnsafePtr(p->type)) { where = "takes"; break; }
    if (!where) return;
    unsupported(("`" + name + "` " + where + " a raw pointer, so it must be declared `unsafe` — the "
                 "marker belongs at the declaration, where it is greppable, not inside the body")
                    .c_str(), line);
}

// Calling an `extern fn` requires an enclosing `unsafe fn`. The DECLARATION carries no marker — it is
// bodiless, so there is nothing in it to be unsafe, exactly as with a contract member — which makes the
// CALL the only place the boundary can be drawn.
//
// NO SCALAR EXEMPTION, deliberately. `extern fn int32 kama_close_socket(isize fd)` names no pointer and is
// a double-free primitive by effect; so are `kama_app_exit` and `kama_ws_close`. 87 of the 188
// `lib/`+`prelude/` extern declarations name no pointer at all, so a type-based carve-out would leave
// finding 1 — a double free with zero `unsafe` tokens in the program — open in its handle-closing shape
// while looking like it had been closed. Danger here is a property of the callee's EFFECT, which kama
// cannot see, not of its signature, which it can.
void CEmitter::gateExternCall(const FuncSig& sig, const std::string& name, int line)
{
    if (_inUnsafe || !sig.node || !isExtern(sig.node)) return;
    unsupported(("calling the `extern fn` `" + name + "` requires an `unsafe fn` — C is outside kama's "
                 "guarantees, so the call is the boundary (the declaration carries no marker: it has no "
                 "body to be unsafe)").c_str(), line);
}

bool CEmitter::paramCanCarryBorrow(FunctionParameterNode* p, const std::string& selfParam) const
{
    if (!p || !p->type || !p->type->value) return false;
    if (p->modifier && p->modifier->value
        && (*p->modifier->value == "ref" || *p->modifier->value == "out")) return true;   // cf. paramByRef
    const std::string& t = *p->type->value;
    if (isRawPtrName(t)) return true;                      // a raw non-owning pointer into caller memory
    if (t == selfParam) return true;                 // the pinned self-type — another view of this kind
    return _viewTypeNames.count(t) > 0;              // any other `type view`
}

// A `type view` may only ever point at memory it was HANDED. A contract slot that CONSTRUCTS the
// implementer (`ctor B fromWide(int64 v)` on `FixedBacking<B is This>`) fixes that parameter list at the
// CONTRACT, where the author has no idea a view might implement it — and if no parameter carries a borrow,
// then every view such a constructor could return borrows one of its own locals and dangles. No body can
// satisfy the conformance, so reject it at the `implements` instead of at whichever body is eventually
// written.
//
// This closes a real hole rather than restating one. checkViewCtorEscape's `safeRoot` is merely "is it a
// parameter?", so a view ctor borrowing a BY-VALUE parameter is accepted today even though that storage
// dies at return:
//     public ctor fromWide(int64 v) { this.p = addr(of: v); this.n = 1; }   // accepted before this rule
// Tightening `safeRoot` instead would report at a body line and tell the author to "borrow a parameter"
// when they already did; the declaration-site rule names the actual cause.
//
// Deliberately NARROW — the neighbouring shapes are already rejected, and duplicating them here would be
// dead code (each verified by probe, not by reading):
//   * an INSTANCE method returning the self-type (`fn T sqrt()` on `Real<T is This>`, `View.slice()`)
//     borrows its receiver and is always legal;
//   * `Owned<Self>`/`Shared<Self>` in any slot -> registerGenericTypeInst's view-as-generic-argument guard,
//     reached through registerGenericContractInst's transitive scanTypeForCollections ("can't be a
//     collection element");
//   * `Result<Self, E>` -> the same function's enum-payload guard ("can't be an `enum` payload").
//
// KNOWN GAPS, both narrower than they look. linkContracts merges only into `_interfaces`, so a pinned
// (hence generic) contract's REFINED parent slots never reach `ii.methods` and are not seen here. And a
// `static fn` slot returning the self-type is not seen either (InterfaceMethod records no `isStatic`) — but
// no class can DEFINE a self-returning `static fn` (collectClasses calls that a constructor), so such a
// slot is unsatisfiable by every type, not just by a view.
void CEmitter::checkViewContractCtors()
{
    for (auto& kv : _classes) {
        ClassInfo& ci = kv.second;
        if (!ci.isBorrow) continue;                                    // views only
        for (auto& base : ci.interfaces) {
            auto it = _interfaces.find(base);
            if (it == _interfaces.end()) continue;                     // a base class / unresolved
            InterfaceInfo& ii = it->second;
            // Only a PINNED parameter can name the implementer: a contract signature may not say `This`
            // (see collectInterfaces), so an unpinned contract can never require a self-returning slot.
            if (ii.pinnedParam < 0 || ii.templateKey.empty()) continue;
            auto pp = _genericContractParams.find(ii.templateKey);
            if (pp == _genericContractParams.end()) continue;
            size_t p = (size_t)ii.pinnedParam;
            if (p >= pp->second.size() || p >= ii.typeArgs.size()) continue;
            // A generic contract INSTANCE copies the template's methods verbatim, so their signatures still
            // spell the raw parameter name (`B`), never the substituted argument.
            const std::string& selfParam = pp->second[p];
            // ...and the pin must actually be bound to THIS class. A generic view's `implements` is resolved
            // by registerGenericTypeInst, which never runs resolveInterfaceNames' "the pinned argument must
            // be `This`" rule — so `implements FixedBacking<int8>` on a view is reachable, and its slots
            // produce an int8 rather than a view. Nothing to reject there.
            SharedIdentifier selfArg = ii.typeArgs[p];
            if (!selfArg || !selfArg->value || *selfArg->value != ci.name) continue;

            for (auto& m : ii.methods) {
                if (!m.isCtor) continue;                               // an instance method borrows `this`
                // A `ctor` slot ALWAYS produces the implementer, whether it spells that return type
                // (`ctor B fromWide(…)`) or omits it, which is how an infallible one is written
                // (`ctor copy(ref T source)`). Both construct a self, so both are in scope; only a slot
                // naming some OTHER type is not. A wrapped return (`Owned<B>`, `Result<B, E>`) is already
                // rejected upstream — see the comment above.
                if (m.returnType && m.returnType->value) {
                    if (m.returnType->genericArg) continue;
                    if (*m.returnType->value != selfParam) continue;
                }

                bool borrowable = false;
                if (m.params)
                    for (auto& mp : *m.params)
                        if (paramCanCarryBorrow(mp.get(), selfParam)) { borrowable = true; break; }
                if (borrowable) continue;

                // Name the TEMPLATE, not the mangled instance — `FromWide`, not `FromWide_F<file>_Span`, which
                // is what the author wrote and is stable across instantiations.
                unsupported(("a `view` (`" + ci.name + "`) borrows memory it is handed, but contract `"
                             + ii.templateKey + "` requires `ctor " + m.name + "` to construct one from parameters "
                             "that carry no borrow (no `UnsafePtr<T>`, no `ref`, no view) — the view it returned "
                             "could only borrow a constructor local, so it would dangle; put this "
                             "conformance on an owning `value` type instead").c_str(),
                            ci.declLine());
            }
        }
    }
}

// Render a type node back in KAMA spelling (`Result<isize, IoError>`), resolving a bound parameter
// through `_typeSubst` so a generic contract's `T` prints as the argument the conformance bound it to.
// The C spelling is what a signature MISMATCH is detected on — it is what clang would eventually
// object to — but it is not what a diagnostic may say: `Result_isize_std__io__IoError` names a type
// the author never wrote, which is precisely what made the original failure unreadable.
//
// Bare, unqualified names only. That is the spelling a conformance is written in, and a qualifier
// reconstructed from `qualifier` would print `std::io::IoError` where the source says `IoError`.
std::string CEmitter::kamaTypeText(SharedIdentifier t)
{
    if (!t || !t->value) return "";
    auto s = _typeSubst.find(*t->value);
    if (s != _typeSubst.end() && s->second && s->second.get() != t.get() && s->second->value)
        return kamaTypeText(s->second);
    std::string out = *t->value;
    if (t->genericArgs && !t->genericArgs->empty()) {
        out += "<";
        for (size_t i = 0; i < t->genericArgs->size(); ++i) {
            if (i) out += ", ";
            out += kamaTypeText((*t->genericArgs)[i]);
        }
        out += ">";
    } else if (t->genericArg) {
        out += "<" + kamaTypeText(t->genericArg) + ">";
    }
    return out;
}

// One member's signature, rendered for comparison: the C spelling (what the mismatch is DETECTED on)
// beside the kama spelling (what the diagnostic may say).
struct CEmitter::ConfSig {
    std::string cRet, kamaRet;
    std::vector<std::string> cParam, kamaParam, label;
    std::vector<bool> byRef, isOut;
    std::vector<bool> isConst;   // `const ref` / `const out` — signature on a PLACE parameter, see reportSigMismatch
};

// The signature of a contract member, rendered under the CONTRACT's own name-resolution scope — its
// imports, not the implementing unit's — with a generic-contract instance's `T` bound to its argument.
// The same two-part dance `emitClassInterfaceVtables` does before it casts a function into a slot; a
// generic instance copies the template's methods verbatim, so their signatures still spell the raw
// parameter name (`B`), never the argument.
CEmitter::ConfSig CEmitter::contractSigOf(InterfaceInfo& ii, const InterfaceMethod& m)
{
    ConfSig s;
    ScopedContractNs _cns(_nsCtx, _collectingUnitPath, ii);
    {
        ContractSubst _cs(*this, ii);
        if (m.returnType) {
            s.cRet    = cType(m.returnType) + placeRetSuffix(m.isPlaceReturn, m.isConstPlace);
            s.kamaRet = placeKamaPrefix(m.isPlaceReturn, m.isConstPlace) + kamaTypeText(m.returnType);
        }
        if (m.params)
            for (auto& p : *m.params) {
                s.cParam.push_back(p && p->type ? cType(p->type) : "");
                s.kamaParam.push_back(p && p->type ? kamaTypeText(p->type) : "");
                s.label.push_back(p && p->identifier && p->identifier->value ? *p->identifier->value : "");
                s.byRef.push_back(p ? paramByRef(p.get()) : false);
                s.isOut.push_back(p ? paramIsOut(p.get()) : false);
                s.isConst.push_back(p ? p->isConst : false);
            }
    }
    return s;
}

// The signature of the method that answers for it, rendered under the DECLARING type's scope with
// `This` bound — and, for a generic instance, with the instance's type arguments bound, so a `T`-typed
// return resolves to the concrete monomorph (`cTypeInInstance`) rather than to the bare parameter.
//
// The type NODES are re-rendered here rather than read back off `mi->params[i].className`, which was
// computed at collection — possibly, as `paramSigsOf` says of itself, before the class table existed.
// Two spellings produced at two different times are exactly the thing a comparison must not rest on.
//
// A COMPILER-BUILT entry (a primitive's synthetic conformance ClassInfo, a collection) records no scope
// of its own, and reseating from it would resolve every bare name in an empty namespace: `type intrinsic
// <int32> implements Boxer { … Wrapped … }` inside `namespace M` rendered the contract's `M::Wrapped`
// against the implementation's unqualified `Wrapped` and called them different (probed, and it was a
// false positive on a correct conformance). Those arrive here from checkImplCompleteness, mid-collection,
// where the DECLARING unit's context is already live and is the right one — so leave it alone.
CEmitter::ConfSig CEmitter::implSigOf(ClassInfo& tci, ClassInfo* owner, MethodInfo* mi)
{
    ConfSig s;
    ClassInfo& src = owner ? *owner : tci;
    NsCtx saved = _nsCtx;
    if (!src.scope.empty()) { _nsCtx.scope = src.scope; _nsCtx.usings = src.usings; _nsCtx.symbolAliases = src.symbolAliases; }
    {
        ScopedStr  _ts(_thisType, tci.name);
        ScopedThis _tt(_typeSubst, synthId(tci.name));
        if (mi->returnType) {
            s.cRet    = cTypeInInstance(tci.name, mi->returnType) + placeRetSuffix(mi->isPlaceReturn, mi->isConstPlace);
            s.kamaRet = placeKamaPrefix(mi->isPlaceReturn, mi->isConstPlace) + kamaTypeText(mi->returnType);
        }
        // The declaration's own parameter nodes when there are any; an intrinsic/synthesized method has
        // no node, and its recorded `className` IS the C spelling — the only answer available there.
        // An OPERATOR is neither: it is not a ClassMethodDeclarationNode, so `node` is null, but its
        // declarator carries real type nodes — and the contract side built its own list from exactly
        // this call (`collectInterfaces`), so the two are rendered the same way rather than one from
        // nodes and one from a C spelling recorded at collection.
        SharedParameterList ps = mi->node ? mi->node->params
                               : mi->isOperator && mi->opDecl && mi->opDecl->operatorDeclarator
                                   ? operatorParamList(mi->opDecl->operatorDeclarator.get())
                                   : SharedParameterList();
        if (ps) {
            for (auto& p : *ps) {
                s.cParam.push_back(p && p->type ? cTypeInInstance(tci.name, p->type) : "");
                s.kamaParam.push_back(p && p->type ? kamaTypeText(p->type) : "");
                s.label.push_back(p && p->identifier && p->identifier->value ? *p->identifier->value : "");
                s.byRef.push_back(p ? paramByRef(p.get()) : false);
                s.isOut.push_back(p ? paramIsOut(p.get()) : false);
                s.isConst.push_back(p ? p->isConst : false);
            }
        } else {
            for (auto& p : mi->params) {
                s.cParam.push_back(p.className);
                s.label.push_back(p.name);
                s.kamaParam.push_back("");      // no node to render: the message falls back to the C name
                s.byRef.push_back(p.byRef);
                s.isOut.push_back(p.isOut);
                s.isConst.push_back(p.isConst);
            }
        }
    }
    _nsCtx = saved;
    return s;
}

// An `implements` clause is a promise about SIGNATURES, and it was the one thing not being checked.
// `type resource File implements Reader, Writer` returned `Result<usize, IoError>` from `read` and
// `write` where both contracts declare `Result<isize, IoError>`; so did `TcpStream` and `WsConnection`.
// Nothing objected — a vtable slot is filled with a CAST to the erased signature, which is exactly what
// silences the C compiler at the declaration and defers the complaint to the use sites, where it names
// mangled types the author never wrote. `examples/httpd` became un-buildable while `kama check` called
// the stdlib clean.
//
// The direct call is worse than un-diagnosed, it is wrong: dispatching `fn int64 count()` through an
// `fn int32 count()` slot compiled, ran, and silently returned the low 32 bits (probed 2026-08-18).
//
// Detection is on the C spelling — that is the ground truth about whether two signatures are the same
// after aliases, imports and substitution — while the message says the kama one.
void CEmitter::checkConformanceSignature(ClassInfo& tci, const std::string& contract,
                                         const std::string& tkey, int line)
{
    auto ifIt = _interfaces.find(contract);
    if (ifIt == _interfaces.end()) return;   // a base class, or unresolved — already diagnosed
    InterfaceInfo& ii = ifIt->second;
    // A `@viewable` contract emits NO vtable and no fat-pointer type (see emitInterfaceTypes), so its
    // members are nominal markers rather than slots — nothing lowers through them, and exact match is the
    // wrong rule. Probed by removing this line: `Iterable<T>` declares `fn Iterator<T> iterator()` while
    // every container returns its own concrete `DynamicArrayIter<T>`, which is how the mint protocol is
    // meant to read; the corpus lit up with eight such "mismatches", all of them correct code.
    if (ii.isViewable) return;

    // A generic type's conformance is checked on its INSTANCES (the template's `implements` is resolved
    // per instance), so a template-level mismatch would otherwise report once per instantiation.
    auto gi = _genericTypeInsts.find(tci.name);
    const std::string subject = gi != _genericTypeInsts.end() ? gi->second.templateKey : tci.name;
    const std::string shown = !ii.templateKey.empty() ? ii.templateKey : contract;

    for (auto& m : ii.methods) {
        ClassInfo* owner = nullptr;
        MethodInfo* mi = findMethod(&tci, m.name, &owner);
        if (!mi) continue;                   // presence is checkImplCompleteness'/the vtable's job
        if (!_conformanceSigChecked.insert(subject + "|" + contract + "|" + m.name).second) continue;
        // A GRAPH NODE's `deserialize` is the compiler's two-pass driver and returns `Result<Shared<This>,
        // …>`, not `Result<This, …>` — rebuilding a cyclic object graph cannot hand back a value, so the
        // root arrives behind a handle. BOTH sides here are compiler-written: `@generate(Deserializable)`
        // synthesizes the method and records the conformance, and there is no `implements` clause anyone
        // authored. This check exists to catch a DECLARED promise that drifted from its contract; there is
        // no such promise to hold. (Surfaced the moment `Deserializable` stopped being an empty marker and
        // started declaring its factory — the mismatch was always there, with nothing to compare against.)
        if (mi->isSynthDe && tci.graphDeserialize) continue;
        const int at = mi->node ? mi->node->line : mi->opDecl ? mi->opDecl->line : line;
        // An operator is registered under a SYNTHETIC name (`op_add`); say what the author wrote.
        const std::string member = mi->isOperator && mi->opDecl && mi->opDecl->operatorDeclarator
                                 ? "operator" + binaryOperator(mi->opDecl->operatorDeclarator->opToken)
                                 : m.name;
        // The receiver is part of the signature too, and it is the parameter no one writes. A contract
        // CAN require a `static fn` (`Hasher::finish` is zero-state, so `H::finish(raw)` monomorphizes to
        // a direct call) — so this is a MATCH, not a ban. Probed both ways before it was written: a
        // `static fn` satisfying an instance member built clean and returned the receiver read as its
        // first argument. A required `ctor` is exempt — one is static by construction, with no `self`.
        if (!m.isCtor && m.isStatic != mi->isStatic) {
            unsupported(("`" + tkey + "` implements `" + shown + "`, but its `" + member + "` is "
                         + (mi->isStatic ? "`static fn` where the contract declares an instance method, "
                                           "which is called on a receiver"
                                         : "an instance method where the contract declares `static fn`, "
                                           "which is called on the type")
                         + "; a conformance must match the signature the contract declares").c_str(), at);
            continue;
        }
        reportSigMismatch(contractSigOf(ii, m), implSigOf(tci, owner, mi),
                          "`" + tkey + "` implements `" + shown + "`, but its `" + member + "` ",
                          "the contract", "a conformance must match the signature the contract declares", at);
    }
}

// The comparison itself, shared by the two promises in the language that have a signature to keep: a
// contract conformance, and an `override`. Both are the same claim — "this callable stands in for that
// one" — and both were being made without anyone checking, so they get one comparison rather than two
// that can drift apart. `lead` names the pair, `authority` is what the other side is called in the
// message ("the contract" / "the base"), `tail` states the rule.
void CEmitter::reportSigMismatch(const ConfSig& want, const ConfSig& have, const std::string& lead,
                                 const std::string& authority, const std::string& rule, int at)
{
    const std::string tail = "; " + rule;
    // Prefer the kama spelling; an intrinsic/synthesized side has no node to render one from.
    auto shownType = [](const std::string& kama, const std::string& c) { return kama.empty() ? c : kama; };

    // Arity first, and alone: a count mismatch makes every positional comparison below meaningless,
    // and reporting both would name one cause twice.
    if (want.cParam.size() != have.cParam.size()) {
        unsupported((lead + "takes " + std::to_string(have.cParam.size()) + " parameter(s) — " + authority
                     + " declares " + std::to_string(want.cParam.size()) + tail).c_str(), at);
        return;
    }
    if (!want.cRet.empty() && !have.cRet.empty() && want.cRet != have.cRet)
        unsupported((lead + "returns `" + shownType(have.kamaRet, have.cRet) + "` — " + authority
                     + " declares `" + shownType(want.kamaRet, want.cRet) + "`" + tail).c_str(), at);
    for (size_t i = 0; i < want.cParam.size(); ++i) {
        if (want.cParam[i].empty() || have.cParam[i].empty()) continue;   // nothing to compare against
        const std::string pos = "parameter " + std::to_string(i + 1);
        // The LABEL is part of the call surface, not decoration: kama call sites are label-based, so a
        // divergence gives one operation two spellings depending on how the receiver is held — and a
        // generic body written against the contract (`w.write(bytes: b)`) fails to compile for the
        // implementer that renamed it, reported in the GENERIC's file, naming a label its author wrote
        // correctly. Measured at zero divergences corpus-wide before this was turned on.
        if (i < want.label.size() && i < have.label.size()
            && !want.label[i].empty() && !have.label[i].empty() && want.label[i] != have.label[i])
            unsupported((lead + "names " + pos + " `" + have.label[i] + "` — " + authority + " calls it `"
                         + want.label[i] + "`, and a caller writes the label" + tail).c_str(), at);
        if (want.cParam[i] != have.cParam[i])
            unsupported((lead + "takes `" + shownType(have.kamaParam[i], have.cParam[i]) + "` as "
                         + pos + " — " + authority + " declares `"
                         + shownType(want.kamaParam[i], want.cParam[i]) + "`" + tail).c_str(), at);
        // `ref`/`out` is not decoration: it is what makes the parameter a pointer in the lowered
        // slot, so a disagreement here is the same class of mismatch as a disagreeing type.
        else if (want.byRef[i] != have.byRef[i] || want.isOut[i] != have.isOut[i])
            unsupported((lead + "passes " + pos + " " + (have.isOut[i] ? "`out`" : have.byRef[i] ? "`ref`" : "by value")
                         + " — " + authority + " declares it "
                         + (want.isOut[i] ? "`out`" : want.byRef[i] ? "`ref`" : "by value") + tail).c_str(), at);
        // Constness of a PLACE parameter is signature too, in both directions — the same rule the
        // place-RETURN already obeys (`placeRetSuffix` folds it into `cRet`). The unsound direction is an
        // implementation or override that DROPS `const`: dispatch goes through a slot whose declaration
        // said `const ref`, so a caller holding a const place hands it over and the body writes through
        // it — measured on an `override` before this clause existed. The other direction (adding `const`
        // where the contract said `ref`) breaks no caller, but a conformance is a promise to match the
        // declared signature, not to be compatible with it: one spelling per member, so a reader knows
        // where const is without consulting the implementation. A by-VALUE `const T x` is the callee's own
        // copy — invisible to every caller and absent from the C spelling — so it is not compared.
        else if (want.byRef[i] && want.isConst[i] != have.isConst[i]) {
            auto spell = [](bool isOut, bool isConst) {
                return std::string(isConst ? "`const " : "`") + (isOut ? "out`" : "ref`");
            };
            unsupported((lead + "declares " + pos + " " + spell(have.isOut[i], have.isConst[i]) + " — " + authority
                         + " declares it " + spell(want.isOut[i], want.isConst[i]) + tail).c_str(), at);
        }
    }
}

// The sweep. Mirrors checkViewContractCtors' shape: every `_classes` entry against every contract it
// declares, late enough that bases, interfaces and generic instances are all resolved.
//
// This reaches conformances the vtable path cannot. `emitClassInterfaceVtables` skips a static-only
// (impl-block, monomorphized) conformance entirely — no fat pointer is emitted for one — so the only
// place its signatures could ever be compared is here.
void CEmitter::checkConformanceSignatures()
{
    for (auto& kv : _classes) {
        ClassInfo& ci = kv.second;
        // A compiler-built entry — a collection, a smart pointer — carries no namespace context to
        // resolve its own signatures in, and this pass is far too late to recover one. Its conformances
        // are declared by `type intrinsic` blocks and reach the same comparator through
        // checkImplCompleteness, while the declaring unit's context is still live. See implSigOf.
        if (ci.scope.empty()) continue;
        // A whole-program check has no unit context of its own, so borrow the declaring file's —
        // otherwise every rejection here reports an empty file in a multi-file build. See diagFile().
        ScopedStr _cu(_collectingUnitPath, ci.declFile);
        for (auto& c : ci.interfaces) checkConformanceSignature(ci, c, ci.name, ci.declLine());
    }
}

// `override` is the same promise one axis over, and it was kept no better. A derived method that
// changes the signature it overrides is reached through the BASE's slot, so the arguments the caller
// passed and the ones the callee reads are two different lists — probed: an override taking a parameter
// the base's slot never passes read a garbage argument register and returned it, deterministically, out
// of safe kama with no `unsafe` anywhere. The return-type and parameter-type variants happened to
// survive on this target, which is worse, not better: nothing about that is guaranteed.
//
// Deliberately NOT covariance-aware. A derived return type would be a real language feature — with its
// own rules about what may narrow and a lowering that can carry it — and inventing one here by
// accepting "any subtype" would let a hierarchy make a promise the vtable cannot keep. Exact match.
void CEmitter::checkOverrideSignatures()
{
    for (auto& kv : _classes) {
        ClassInfo& ci = kv.second;
        if (!ci.base) continue;
        ScopedStr _cu(_collectingUnitPath, ci.declFile);
        for (auto& mkv : ci.methods) {
            MethodInfo& mi = mkv.second;
            if (!mi.isOverride) continue;
            ClassInfo* baseOwner = nullptr;
            MethodInfo* bmi = findMethod(ci.base, mkv.first, &baseOwner);
            // Nothing to compare against: "overrides no virtual method" is its own diagnostic, raised
            // where the `override` marker is validated, and saying it twice helps no one.
            if (!bmi || !baseOwner) continue;
            const int at = mi.node ? mi.node->line : mi.opDecl ? mi.opDecl->line : ci.declLine();
            // `@noheap` travels down a hierarchy for the same reason it travels across a contract: a
            // virtual call is dispatched through a slot, so the base's promise is only worth what the most
            // derived override honours. Checked here rather than folded into the signature comparison
            // because it is not a signature — `reportSigMismatch` renders a type mismatch, and an override
            // that merely dropped an attribute would be described as having the wrong shape.
            if (bmi->noHeap && !mi.noHeap)
                unsupported(("`" + ci.name + "." + mkv.first + "` overrides `" + baseOwner->name + "."
                             + mkv.first + "`, which is `@noheap` — mark this override `@noheap` too, or a "
                               "no-heap caller dispatching through the base loses the guarantee").c_str(), at);
            reportSigMismatch(implSigOf(*baseOwner, baseOwner, bmi), implSigOf(ci, &ci, &mi),
                              "`" + ci.name + "` overrides `" + baseOwner->name + "." + mkv.first
                                  + "`, but its `" + mkv.first + "` ",
                              "the base", "an override must match the signature it overrides", at);
        }
        // THE DESTRUCTOR IS A SLOT LIKE ANY OTHER, and the rule above was never applied to it: dropping a
        // `Owned<Base>` runs the most-derived `~T` through the vtable, so `@noheap ~Base()` is a promise
        // about every object the handle can hold. A subclass that frees in its own teardown — or merely
        // owns a field that does, which needs no `~Square()` in the source at all — broke that promise
        // silently (tests/xfail/noheap_dtor_override.kama, found planning KR-39). A class that drops
        // NOTHING needs no mark: there is no teardown to prove.
        for (ClassInfo* a = ci.base; a; a = a->base) {
            if (!(a->dtorNode && hasNoHeapAttr(a->dtorNode->attributes))) continue;
            if (!ci.destructible) break;
            if (ci.dtorNode && hasNoHeapAttr(ci.dtorNode->attributes)) break;
            unsupported(("`~" + ci.name + "` runs in place of `~" + a->name + "`, which is `@noheap` — mark "
                         "it `@noheap` too (`@noheap ~" + ci.name + "() { }`), or a no-heap caller dropping "
                         "through the base loses the guarantee").c_str(),
                        ci.dtorNode ? ci.dtorNode->line : ci.declLine());
            break;
        }
    }
}

// A `@viewable` contract must be able to grant something. The mark is spent by an IMPLEMENTATION whose
// return type is a `type view`, so a member can only ever mint if its declared return type is a view
// (`fn Span span()`) or a contract a view may implement (`fn Iterator<T> iterator()` — the shape every
// prelude iteration contract has, and the reason this cannot be checked at collectInterfaces, where
// neither `_classes` nor `_viewTypeNames` is populated yet).
//
// ONE such member is enough, deliberately: `Windowed` pairs `fn S rest()` with `fn int32 length()`, and a
// per-member rule would reject the second for the crime of being ordinary. What is worth rejecting is a
// contract where NO member could ever mint — there the mark is inert, and inert is exactly how a grant
// fails silently. (`ctor` slots are excluded: a contract ctor is not a grant, since a call to one from
// outside is neither inside the view nor inside the type it views.)
// The contract-member arm of the `ref`/`out` view ban. A bodiless signature never reaches `paramListC`
// or `checkSignatureRawPtr`, so without this the spelling stayed legal exactly where it is most
// contagious — every implementer of the contract has to repeat it. Late, because `_viewTypeNames` is
// filled by `collectClasses`, which runs AFTER contracts are collected.
void CEmitter::checkViewRefParams()
{
    auto check = [&](const InterfaceInfo& ii) {
        const std::string& shown = ii.templateKey.empty() ? ii.name : ii.templateKey;
        for (auto& m : ii.methods) {
            if (!m.params) continue;
            ScopedStr _cu(_collectingUnitPath, ii.declFile);   // the file that DECLARED it
            for (auto& p : *m.params)
                if (p) rejectViewByRef(p.get(), shown + "." + m.name, ii.node ? ii.node->line : 0);
        }
    };
    for (auto& kv : _genericContracts) check(kv.second);
    for (auto& kv : _interfaces) if (kv.second.templateKey.empty()) check(kv.second);
    // Free functions and methods, staged by `checkSignatureRawPtr` while their file was still current.
    for (auto& pv : _pendingViewByRef) {
        ScopedStr _cu(_collectingUnitPath, pv.file);
        rejectViewByRef(pv.param, pv.owner, pv.line);
    }
}

void CEmitter::checkViewableContracts()
{
    auto couldMint = [&](const InterfaceInfo& ii) {
        // The contract's OWN type parameters. `Viewable<V> { fn V view(); }` names the view through a
        // parameter bound at the conformance site (`implements Viewable<View<T>>`), so `V` is the most
        // direct mintable shape there is — and the one that reads as a non-view here if it is missed.
        const std::string& key = ii.templateKey.empty() ? ii.name : ii.templateKey;
        auto pp = _genericContractParams.find(key);
        for (auto& m : ii.methods) {
            if (m.isCtor || !m.returnType || !m.returnType->value) continue;
            const std::string& r = *m.returnType->value;
            if (_viewTypeNames.count(r)) return true;              // a `type view` by source name
            if (_interfaces.count(r) || _genericContracts.count(r)) return true;   // a contract a view may implement
            if (_interfaces.count(qualify(r)) || _genericContracts.count(qualify(r))) return true;
            if (pp != _genericContractParams.end()
                && std::find(pp->second.begin(), pp->second.end(), r) != pp->second.end()) return true;
        }
        return false;
    };
    auto check = [&](const InterfaceInfo& ii) {
        if (!ii.isViewable || couldMint(ii)) return;
        const std::string& shown = ii.templateKey.empty() ? ii.name : ii.templateKey;
        ScopedStr _cu(_collectingUnitPath, ii.declFile);   // name the file that DECLARED it, not the one being checked
        unsupported(("`@viewable` grants nothing on contract `" + shown + "` — no member returns a `type "
                     "view`, a contract one could implement, or one of this contract's own type "
                     "parameters, so no implementation of it could ever mint. Mark the contract that "
                     "hands the view out").c_str(),
                    ii.node ? ii.node->line : 0);
    };
    for (auto& kv : _genericContracts) check(kv.second);            // the template — its instances copy it
    for (auto& kv : _interfaces) if (kv.second.templateKey.empty()) check(kv.second);   // non-generic only
}

// Every `implements Sendable` is a CLAIM, and this is what makes it one the compiler stands behind: for
// each declaring type, every field, base and variant payload must itself be Sendable (unsendableReason),
// and the first that is not is named, with the reason. This is the `immutable` model applied to the
// isolate boundary — the declaration is where the author says it, this pass is its verification, and a
// crossing may read the declaration. A lie is caught here; an omission is caught at the crossing
// (checkSpawnBundleSendability, and the `Channel<T: Sendable>` bound in std::concurrent).
//
// Post-emission, from BOTH entry points (see checkNoHeapTransitive on why both): a generic instance
// minted inside a body is registered during emission, and its `when [T: Sendable]` verdict is only in
// `interfaces` by then. An intrinsic collection cannot declare anything and is skipped; an extern struct
// is the C seam and answers yes without a declaration.
// ⚠️ Resolves fields under the class's OWN binding — `_nsCtx`/`_typeSubst` swapped and RESTORED.
void CEmitter::checkSendableDeclarations()
{
    const std::string& S = _sendableContract;
    if (S.empty()) return;
    for (auto& kv : _classes) {
        ClassInfo& ci = kv.second;
        if (ci.isExternStruct || ci.isIntrinsicColl) continue;
        bool declares = false;
        for (auto& itf : ci.interfaces) if (itf == S) { declares = true; break; }
        if (!declares) continue;
        const NsCtx savedCtx = _nsCtx;
        const std::map<std::string, SharedIdentifier> savedSubst = _typeSubst;
        enterClassCtx(ci);
        std::string what, why;
        if (ci.base) {
            why = unsendableReason(ci.base->name);
            if (!why.empty()) what = "its base `" + ci.base->name + "`";
        }
        if (what.empty())
            for (auto& f : ci.fields) {
                const std::string fc = cType(f.type);
                why = unsendableReason(fc);
                if (!why.empty()) { what = "its field `" + f.name + "` (of type `" + fc + "`)"; break; }
            }
        if (what.empty())
            for (auto& v : ci.variants) {
                for (auto& f : v.payload) {
                    const std::string fc = cType(f.type);
                    why = unsendableReason(fc);
                    if (!why.empty()) { what = "its variant `" + v.name + "` payload `" + f.name + "` (of type `" + fc + "`)"; break; }
                }
                if (!what.empty()) break;
            }
        _nsCtx = savedCtx; _typeSubst = savedSubst;
        if (what.empty()) continue;
        ScopedStr _cu(_collectingUnitPath, ci.declFile);   // whole-program pass: see diagFile()
        unsupported(("`" + ci.name + "` declares `implements Sendable`, but " + what + " is not Sendable — "
                     + why).c_str(), ci.declLine());
    }
}

// The `spawn` BUNDLE is a crossing, and it requires the declaration exactly as a channel element does
// (there the requirement is the `T: Sendable` bound on `Channel`/`Sender`/`Receiver`; a bundle has no
// type parameter to carry one, so it is asked here). Until 0.9.153 the bundle — the PRIMARY way data
// enters an isolate — faced no gate at all, while the channel half did.
//
// Recorded during emission and checked after it: a `spawn` lives inside a BODY, and unsendableReason
// resolves other types' fields under their own binding, which must not happen mid-emission.
//
// Both modes are checked. A moved bundle carries a second live handle into the child, which then drops it;
// a `ref`-borrowed one is not copied at the seam, but the child may `copy` a handle out of it, and the
// parent's own drop then races that copy's release. A `ref int32` bundle passes: a primitive's conformance
// is declared in the prelude.
void CEmitter::checkSpawnBundleSendability()
{
    for (const SpawnBundle& sb : _spawnBundles) {
        const std::string why = unsendableReason(sb.cls);
        if (why.empty()) continue;
        ScopedStr _f(_emitDeclFile, sb.file);
        unsupported(("cannot spawn with `" + sb.cls + "` " + sb.what + " — " + why + "; a type crosses an "
                     "isolate boundary only by declaring `implements Sendable`, which the compiler verifies "
                     "over every field").c_str(), sb.line);
    }
}
// The class in ci's ancestry that declares `field` (or nullptr).
ClassInfo* CEmitter::findFieldOwner(ClassInfo* ci, const std::string& field)
{
    for (; ci; ci = ci->base)
        if (ci->fieldNames.count(field)) return ci;
    return nullptr;
}

// The nearest method `name` in ci's ancestry; sets *owner to the declaring class.
MethodInfo* CEmitter::findMethod(ClassInfo* ci, const std::string& name, ClassInfo** owner)
{
    for (; ci; ci = ci->base) {
        auto it = ci->methods.find(name);
        if (it != ci->methods.end()) { if (owner) *owner = ci; return &it->second; }
    }
    return nullptr;
}

// Inject a contract-impl block's methods into the target's ClassInfo and record the conformance. The
// caller has already resolved `tci` and rejected a duplicate impl of `contract` on it.
//
// A recorded conformance is STATIC-dispatch-only (it lands in `staticOnlyInterfaces`, so no fat-pointer
// vtable is emitted for it). `isPrimitive` gates the serde-return scan: a primitive's
// `Result<scalar, Owned<Error>>` monomorph only matters when the program actually uses serde.
// The MethodInfo for a method declared in a `type enum`'s own body or a `type intrinsic` block — both
// always public, and neither has a `ClassDeclarationNode` to come through collectClasses. A `when [...]`
// gate is recorded for a GENERIC enum's template, where each instance judges it.
MethodInfo CEmitter::enumMethodInfo(ClassMethodDeclarationNode* md, const std::string& tkey,
                                    const std::string& contract)
{
    const std::string mname = *md->name->value;
    MethodInfo mi;
    mi.cName        = tkey + "__" + mname;
    mi.returnType   = md->returnType;
    mi.params       = paramSigsOf(md->params);
    mi.node         = md;
    mi.isConst      = md->isConst;
    checkConstPlaceReturn(md->isConst, md->isRef, md->isConstRef, mname, md->line);
    mi.isUnsafe     = modHas(md->modifiers, "unsafe");
    mi.isPlaceReturn = md->isRef;
    mi.isConstPlace  = md->isConstRef;
    // a static factory (no `self`) — e.g. `deserialize`; a `ctor` (construction-model M8e:
    // `deserialize` is a fallible ctor) is ALWAYS static, like the in-class ctor path.
    mi.isStatic     = modHas(md->modifiers, "static") || md->isCtor;
    mi.isCtor       = md->isCtor;
    // The rule collectClasses holds a type's ctors to: an infallible ctor writes no return type, a fallible
    // one writes `Result<…, E>` and never `Optional` — a failure carries WHY. An enum's ctor went unchecked,
    // so `ctor Optional<E> parse(…)` was accepted here and refused on a `type value`. ENUMS only: this also
    // serves `type intrinsic` blocks, whose ctor spells the primitive it returns (`ctor int8 fromWide`).
    const bool isEnumOwner = _enumDeclNodes.count(tkey) != 0;
    if (isEnumOwner && md->isCtor && md->returnType) {
        const std::string rt = md->returnType->value ? *md->returnType->value : "";
        if (rt != "Result")
            unsupported(("a `ctor` with a return type must be `Result<…, E>` (fallible) — "
                         "omit it for an infallible ctor; got `" + rt + "`").c_str(), md->line);
    }
    // ...and an INFALLIBLE one returns the enum itself, as a type's does. With no return type written it
    // lowered to a `void` function and its `return` value was dropped, which clang then refused at the caller.
    // A generic enum's carries its own parameters (`Box<T>`), so each instance substitutes them.
    if (isEnumOwner && md->isCtor && !md->returnType && contract.empty()) {
        auto ed = _enumDeclNodes.find(tkey);
        if (ed != _enumDeclNodes.end() && ed->second->identifier) {
            EnumDeclarationNode* e = ed->second;
            auto rt = synthClone(*e->identifier);
            if (e->typeParams && !e->typeParams->empty()) {
                if (!_synthCtx) _synthCtx = std::make_shared<CodeGenContext>(std::make_shared<std::string>("<generic-ctor>"));
                rt->genericArgs = std::make_shared<IdentifierList>();
                for (auto& tp : *e->typeParams) if (tp) rt->genericArgs->push_back(synthId(*tp));
                if (!rt->genericArgs->empty()) rt->genericArg = (*rt->genericArgs)[0];
            }
            mi.returnType = rt;
        }
    }
    mi.fromContract = contract;             // an injected method, not part of the type's own API
    // A `type intrinsic` block's methods belong to its contract, so they are public. An enum's OWN members
    // follow the member rule every other kind follows — private unless written `public` — which they did
    // not: this was `Public` for both, so an enum method with no modifier was callable from any module.
    mi.visibility   = contract.empty() ? visibilityOf(md->modifiers, Visibility::Private, md->line)
                                       : Visibility::Public;
    if (mi.visibility == Visibility::Protected)
        unsupported(("`protected` belongs to a `virtual`/`abstract`/`final resource` — `" + tkey
                     + "` is an `enum`, so its members are `private` or `public`").c_str(), md->line);
    if (md->whenParams)
        for (size_t c = 0; c < md->whenParams->size(); ++c) {
            auto& p = (*md->whenParams)[c];
            auto& b = md->whenBounds ? (*md->whenBounds)[c] : p;
            mi.whenParams.push_back(p && p->value ? *p->value : "");
            mi.whenBounds.push_back(resolveWhenBound(b));
            mi.whenBoundNodes.push_back(b);
        }
    return mi;
}

void CEmitter::injectImplMethods(ClassInfo& tci, SharedClassMemberDeclarationList members,
                                 const std::string& contract, const std::string& tkey,
                                 bool isPrimitive)
{
    if (members)
        for (auto& m : *members) {
            auto* md = dynamic_cast<ClassMethodDeclarationNode*>(m.get());
            if (!md || !md->name || !md->name->value) continue;
            std::string mname = *md->name->value;
            if (tci.methods.count(mname)) {
                unsupported(("`" + tkey + "` implements `" + contract + "`: method `" + mname
                             + "` conflicts with an existing method on the type").c_str(), md->line);
                continue;
            }
            MethodInfo mi = enumMethodInfo(md, tkey, contract);
            // A PRIMITIVE serde conformance's `Result<scalar, Owned<Error>>` return (the ~12 monomorphs)
            // only matters when the program uses serde — skip registering it otherwise (the impl itself
            // is likewise gated off in emitHeaderContent). Every other return scans normally.
            if (!((contract == "Serializable" || contract == "Deserializable") && isPrimitive && !_usesSerde))
                scanTypeForCollections(mi.returnType);  // a monomorph named only in an impl sig
            tci.methods[mname] = mi;
        }
    // An EMPTY contract name means "these are the type's OWN methods, declared in its own body" — the
    // `type enum E implements C { A, B; …methods… }` path, where the members belong to E's API and the
    // conformance is recorded separately, once per declared contract. Nothing to record here.
    if (contract.empty()) return;
    // First claim wins the record; a second one is a duplicate, and this is what lets its message name the
    // package the first came from. `emplace` so a re-claim never overwrites the original claimant.
    _conformanceOrigin.emplace(std::make_pair(tkey, contract), _collectingUnitPath);
    tci.interfaces.push_back(contract);
    tci.staticOnlyInterfaces.push_back(contract);   // static dispatch only — no fat-pointer vtable
}

// `type enum E : U implements C, D { A, B; …members… }` — an enum declares conformance inline, like every
// other kind. Runs AFTER linkContracts() (so `contractMethods` is populated and completeness is checkable)
// and BEFORE buildVtables(), which is what lets the `<E>__as_<C>` vtbl be emitted from the declaration
// instead of retrofitted afterwards.
//
// A payload-less enum stays its C integer whatever it declares (KR-59). Its members, contracts and derives
// live on a ClassInfo that is a SCALAR receiver — `isScalarEnum`: `this` is the value, as a primitive's is
// under `type intrinsic`, and each contract slot reaches a method through a thunk.
void CEmitter::collectEnumConformances(const std::vector<SharedCompilationUnit>& units)
{
    for (auto& u : units) {
        if (!u || !u->codeDeclarationList) continue;
        _nsCtx = _unitCtx[u.get()];
        // Whose code this is. Every diagnostic raised below is ABOUT a declaration in `u`, and in a
        // multi-file build `_sourcePath` is still "" here — so without this they report no file at all,
        // exactly as the four collectors in the main sweep say. It started mattering when registerDerives
        // began firing from here (`@generate(of)` on an enum reports against the enum's own line).
        ScopedStr _cu(_collectingUnitPath, u->name ? *u->name : std::string());
        for (auto& decl : *u->codeDeclarationList) {
            auto* ed = dynamic_cast<EnumDeclarationNode*>(decl.get());
            if (!ed || !ed->identifier || !ed->identifier->value) continue;
            bool hasMembers = ed->members && !ed->members->empty();
            SharedIdentifierList ifaceNodes = ed->baseTypes ? ed->baseTypes->interfaces : SharedIdentifierList();
            bool hasIfaces = ifaceNodes && !ifaceNodes->empty();
            // `@generate` is a third reason for a member ClassInfo, and the same reason as the other two: a
            // conformance and a method need somewhere to live, and an EnumInfo has nowhere. An enum
            // that spells the conformance out (`implements Hashable` + a hand-written `hash`) has always
            // come through here; one that asks for the derived version is asking for the same thing.
            bool hasGen = hasGenerateAttr(ed->attributes);
            if (!hasMembers && !hasIfaces && !hasGen) continue;   // an ordinary enum — the lightweight path, untouched

            const std::string& bare = *ed->identifier->value;
            if (ed->baseTypes && ed->baseTypes->base)
                unsupported(("`type enum " + bare + "` cannot `extends` — an enum has no base type; "
                             "a contract is declared with `implements`").c_str(), ed->line);
            std::string name = enumKey(ed);
            // A C enum may be declared again where it is used, but it is ONE type: its members belong to one of
            // those declarations, or two files could each hang methods on it and neither would see the other's.
            {
                auto prior = _classes.find(name);
                const std::string here = u && u->name ? *u->name : std::string();
                if (enumHasModifier(ed, "extern") && prior != _classes.end() && prior->second.declFile != here) {
                    unsupported(("`type extern enum " + bare + "` declares members, `implements` or `@generate` in `"
                                 + prior->second.declFile + "` too — a C enum is one type, so declare them on one of "
                                   "its declarations and import it where it is used").c_str(), ed->line);
                    continue;
                }
            }

            // An enum's layout is its tag plus its variant payloads — there is no struct to add a field
            // to, and nothing else it could own, so a field or a destructor is a mistake worth naming
            // rather than dropping silently (the method loops only look at methods). Generic or not.
            if (ed->members)
                for (auto& m : *ed->members) {
                    if (dynamic_cast<ClassFieldDeclarationNode*>(m.get()))
                        unsupported(("`type enum " + bare + "` cannot declare a field — an enum's layout is "
                                     "its tag and its variant payloads; put the data in a variant payload")
                                    .c_str(), m->line);
                    else if (dynamic_cast<ClassDestructorDeclarationNode*>(m.get()))
                        unsupported(("`type enum " + bare + "` cannot declare a destructor — an enum owns "
                                     "nothing beyond its payloads, which drop themselves").c_str(), m->line);
                    else if (auto* md = dynamic_cast<ClassMethodDeclarationNode*>(m.get()))
                        checkWhenParams(md->whenParams, ed->typeParams, bare, md->line);
                }
            // `friend` grants, captured raw as collectClasses captures a class's, for resolveFriends to resolve
            // (it walks `_classes` and `_genericTypes`, where an enum's ClassInfo lives). They parsed and were
            // then DROPPED — this loop looked at fields, destructors and methods — so a grant on an enum was
            // silently inert: its private member stayed refused to the very accessor it named, and a typo'd
            // accessor was accepted. Found building `std::net` (KR-6), whose `IpAddr` grants its sockets.
            std::vector<RawFriendGrant> enumGrants;
            if (ed->members)
                for (auto& m : *ed->members)
                    if (auto* fg = dynamic_cast<FriendGrantNode*>(m.get())) {
                        RawFriendGrant rg; rg.accessor = fg->accessor; rg.line = fg->line;
                        if (fg->members)                                  // null => `[...]` (all privates)
                            for (auto& fm : *fg->members)
                                if (fm && fm->value) rg.members.insert(*fm->value);
                        enumGrants.push_back(rg);
                    }
            if (hasIfaces)
                for (auto& i : *ifaceNodes) if (i) checkWhenParams(i->whenParams, ed->typeParams, bare, ed->line);

            if (ed->typeParams && !ed->typeParams->empty()) {
                // A generic enum is a monomorphization TEMPLATE: its members and `implements` list land on
                // the template here, and each instance takes them per instance — a `when [...]` gate judged
                // against that instance's arguments, exactly as a generic class's are. `@generate` never
                // needs this path (collectEnums applies it per instance). The template is filled HERE and
                // not in collectEnums because a `when` bound names a contract, and contracts are collected
                // after enums; an instance cut before now is refreshed below.
                auto tt = _genericTypes.find(name);
                if (tt == _genericTypes.end()) continue;   // errored earlier — already diagnosed
                ClassInfo& tmpl = tt->second;
                for (auto& rg : enumGrants) tmpl.friendGrantsRaw.push_back(rg);
                if (ed->members)
                    for (auto& m : *ed->members) {
                        auto* md = dynamic_cast<ClassMethodDeclarationNode*>(m.get());
                        if (!md || !md->name || !md->name->value) continue;
                        const std::string mname = *md->name->value;
                        if (tmpl.methods.count(mname)) {
                            unsupported(("duplicate method '" + mname + "' in '" + bare + "'").c_str(), md->line);
                            continue;
                        }
                        tmpl.methods[mname] = enumMethodInfo(md, name, /*contract=*/"");
                    }
                // From here on a new instance takes its `implements` list at registration; the ones cut
                // earlier are refreshed. Copied first: a refresh scans member types, which can register more.
                _filledEnumTemplates.insert(name);
                std::vector<GenericTypeInst> earlier;
                for (auto& kv : _genericTypeInsts)
                    if (kv.second.templateKey == name) earlier.push_back(kv.second);
                for (auto& gi : earlier) instantiateEnumMembers(gi);
                continue;
            }

            // Resolve the declared contracts under the ENUM's own ns context (already active), with
            // `This` bound so a PINNED contract mangles to this enum (`Comparable<This>` -> `Comparable_Color`).
            std::vector<std::string> ifaces;
            if (hasIfaces) for (auto& i : *ifaceNodes) if (i && i->value) ifaces.push_back(*i->value);
            { ScopedStr _ts(_thisType, name); ScopedThis _tt(_typeSubst, synthId(name));
              resolveInterfaceNames(ifaces, ifaceNodes); }

            // A payload-less enum gets its member ClassInfo here; a tagged one already has its `_classes` entry.
            auto ci = _classes.find(name);
            if (ci == _classes.end()) {
                if (!_enums.count(name)) continue;   // unknown/errored earlier — already diagnosed
                ClassInfo sci = buildVariantClassInfo(ed, name);
                sci.isVariant = false;          // its variants stay listed (names only) for the derives
                sci.tagCType.clear();
                sci.kind = TypeKind::Value;
                sci.isScalarRecv = true;
                sci.declFile = u && u->name ? *u->name : std::string();
                _classes[name] = sci;
                ci = _classes.find(name);
            }
            ClassInfo& eci = ci->second;
            for (auto& rg : enumGrants) eci.friendGrantsRaw.push_back(rg);
            // A prelude enum has no home module, so its method bodies are emitted `static inline` into the
            // header — which means its PROTOTYPES must be static too, or the C compiler sees a static
            // declaration following a non-static one. `preludeStatic` is what drives that linkage.
            if (_preludeEnums.count(name)) eci.preludeStatic = true;

            // The members are the enum's OWN API (empty `contract` — they are declared in its own body),
            // unlike a `type intrinsic` block's, which belong to the contract that carried them in.
            injectImplMethods(eci, ed->members, /*contract=*/"", name, /*isPrimitive=*/false);
            for (auto& c : ifaces) {
                bool dup = false;
                for (auto& ex : eci.interfaces) if (ex == c) { dup = true; break; }
                if (dup) { unsupported(("`" + bare + "` already implements `" + c + "`").c_str(), ed->line); continue; }
                eci.interfaces.push_back(c);
                // Dynamic dispatch through a fat pointer + (P2) boxing into `Owned<C>`.
                _polyDispatchContracts.insert(c);
                checkImplCompleteness(eci, c, bare, ed->line);
            }

            // ...and LAST, the derives. After injectImplMethods and the `implements` loop, both because a
            // hand-written `equals`/`hash`/`format` must win registerDerives' `!methods.count` guard, and
            // because checkImplCompleteness above must not be asked about a method that has not been
            // synthesized yet. A tagged enum has already been through this in collectEnums, so only a
            // payload-less one reaches it here — `hasGen` is what brought it.
            if (hasGen && !eci.genSerialize && !eci.genDeserialize && !eci.genFormat
                && !eci.genEquatable && !eci.genHashable && !eci.genOf && !eci.genZero) {
                for (auto& at : *ed->attributes)
                    if (at && at->name && *at->name == "generate") parseGenerateAttr(at, eci, ed->line);
                registerDerives(eci, ed->identifier, ed->line);
            }
        }
    }
}

// The BODIES of the methods a `type enum` declares in its own body. `emitClassDefinitions` is driven by a
// `ClassDeclarationNode` and an enum has none (classOf skips enums), so its bodies are emitted here — from
// the enum's own declaration site, alongside its dtor and vtbls. Prototypes come from `emitClassPrototypes`
// the ordinary way, because these methods carry no `fromContract` (a non-empty one routes a method to the
// separate impl passes instead).
void CEmitter::emitEnumMemberBodies(ClassInfo& eci, EnumDeclarationNode* ed)
{
    if (!ed || !ed->members) return;
    ScopedStr _ts(_thisType, eci.name);
    for (auto& m : *ed->members) {
        auto* md = dynamic_cast<ClassMethodDeclarationNode*>(m.get());
        if (!md || !md->name || !md->name->value || !md->body) continue;
        // The return type off the method table, not the node: an infallible ctor's is synthesized there.
        auto mit = eci.methods.find(*md->name->value);
        SharedIdentifier rtype = (mit != eci.methods.end()) ? mit->second.returnType : md->returnType;
        std::string ret = cType(rtype) + placeRetSuffix(md->isRef, md->isConstRef);
        line(md->line);
        _returnIsPlace = md->isRef;
        _returnIsConstPlace = md->isConstRef;
        emitMethodOrCtorBody(eci.name + "__" + *md->name->value, ret.c_str(),
                             md->params, md->body, eci, md->isConst,
                             modHas(md->modifiers, "static") || md->isCtor,   // a `ctor` is static (no `self`)
                             modHas(md->modifiers, "unsafe"), md->name->value->c_str(), md->attributes);
        _returnIsPlace = false;
    }
}

SharedIdentifier CEmitter::intrinsicContract(IntrinsicImplNode* n) const
{
    if (!n || !n->baseTypes || !n->baseTypes->interfaces || n->baseTypes->interfaces->empty())
        return SharedIdentifier();
    return (*n->baseTypes->interfaces)[0];
}

// A primitive's `Serializable`/`Deserializable` conformance is only worth emitting when the program actually
// serializes something — otherwise every binary carries the ~24 prelude monomorphs. Same gate for both
// impl spellings.
bool CEmitter::serdeGatedOff(SharedIdentifier contract) const
{
    return !_usesSerde && contract && contract->value &&
           (*contract->value == "Serializable" || *contract->value == "Deserializable");
}

// The effective member list for ONE target of a `type intrinsic` set: the block's shared bodies, with any
// `<…>` section naming this target overriding them method-for-method. Order is deterministic (shared
// first, in declaration order), which matters because the prototype pass and the body pass must agree.
SharedClassMemberDeclarationList CEmitter::intrinsicMembersFor(IntrinsicImplNode* n, SharedIdentifier target)
{
    auto out = std::make_shared<ClassMemberDeclarationList>();
    if (!n) return out;
    std::string tk = primKey(target);   // NOT cType: a `<char>` section must not also serve `uint32`
    if (n->members) for (auto& m : *n->members) out->push_back(m);
    if (n->sections) for (auto& sec : *n->sections) {
        if (!sec || !sec->targets || !sec->members) continue;
        bool serves = false;
        for (auto& st : *sec->targets) if (primKey(st) == tk) { serves = true; break; }
        if (!serves) continue;
        for (auto& sm : *sec->members) {
            auto* smd = dynamic_cast<ClassMethodDeclarationNode*>(sm.get());
            if (smd && smd->name && smd->name->value) {           // override the shared body, if any
                bool replaced = false;
                for (auto& ex : *out) {
                    auto* emd = dynamic_cast<ClassMethodDeclarationNode*>(ex.get());
                    if (emd && emd->name && emd->name->value && *emd->name->value == *smd->name->value) {
                        ex = sm; replaced = true; break;
                    }
                }
                if (replaced) continue;
            }
            out->push_back(sm);
        }
    }
    return out;
}

// Validate a `type intrinsic` block and inject its methods — once per target in the set. A primitive gets
// NO `_classes` entry (every "is this a user type?" test keys on that map), so the conformance is hung on
// the separate primitive registry, with `this` passed by value.
void CEmitter::applyIntrinsicImpl(IntrinsicImplNode* n)
{
    if (!n->kindWord || *n->kindWord != "intrinsic") {
        unsupported(("`type " + (n->kindWord ? *n->kindWord : std::string("?")) + " <…>` — only "
                     "`type intrinsic` may name primitive types").c_str(), n->line);
        return;
    }
    if (n->baseTypes && n->baseTypes->base)
        unsupported("`type intrinsic` cannot `extends` — a primitive has no base type", n->line);
    SharedIdentifierList ifaces = n->baseTypes ? n->baseTypes->interfaces : SharedIdentifierList();
    if (!ifaces || ifaces->empty()) {
        unsupported("`type intrinsic <…>` must declare a contract — a block with no `implements` gives the "
                    "primitives in it nothing", n->line);
        return;
    }
    {
        bool gated = false;
        for (auto& i : *ifaces) if (i && i->whenParams && !i->whenParams->empty()) gated = true;
        if (auto members = n->members)
            for (auto& m : *members)
                if (auto* md = dynamic_cast<ClassMethodDeclarationNode*>(m.get()))
                    if (md->whenParams && !md->whenParams->empty()) gated = true;
        if (gated)
            unsupported("`type intrinsic <…>` names concrete primitives, so there is no type parameter for "
                        "`when` to condition on — remove the gate", n->line);
    }
    if (ifaces->size() > 1) {
        unsupported("`type intrinsic <…>` declares ONE contract per block — a method's contract has to be "
                    "unambiguous; write a second block for the other one", n->line);
        return;
    }
    if (!n->targets) return;

    for (auto& tgt : *n->targets) {
        // TWO keys, deliberately: `_classes` is C-named (`string` -> kama_string), the conformance registry
        // is kama-named (so `char` and `uint32` don't share `uint32_t`). A prim ClassInfo's `name` stays the
        // C type — it is what `This` resolves to and what the receiver parameter is spelled as.
        std::string ctKey = cType(tgt);
        std::string tkey  = primKey(tgt);
        // `ref This other` is the whole point of the set form, so `This` must be BOUND here — the collect
        // pass runs outside any type, and paramSigsOf/scanTypeForCollections would otherwise reject it.
        // `This` is a C TYPE, so it binds to `ctKey`, not to the registry key.
        ScopedStr  _ts(_thisType, ctKey);
        ScopedThis _tt(_typeSubst, tgt);   // the real kama node: `int32`, not the C spelling `int32_t`
        // The contract resolves PER TARGET, not once for the block: a PINNED contract names a different
        // instance for each type in the set (`Weighable<This>` over `<int8, int16>` is `Weighable_int8`
        // and `Weighable_int16`, two contracts with two vtbls). An unpinned one resolves the same every
        // time, so this costs nothing there.
        std::vector<std::string> names(1, *(*ifaces)[0]->value);
        resolveInterfaceNames(names, ifaces);
        const std::string& contract = names[0];
        // Kind gate, the `intrinsic` arm. This is the ONLY site that can apply it: a primitive's
        // conformance lands in _primConformances, which the `_classes` sweep never sees, and `string`'s
        // lands on the kama_string ClassInfo, which that sweep deliberately skips (a collection has no
        // `kind`) so it is not mistaken for a `value`. Here the ORIGIN is known — it is a `type
        // intrinsic` block — and `n->line` is the only usable line number for one.
        // Inside the per-target loop, so `<int8, int16, …>` names each target, and before
        // injectImplMethods, so the reason arrives ahead of the completeness noise it would cause.
        unsigned allowed = implKindsOf(contract, *(*ifaces)[0]->value);
        if (allowed && !(allowed & IK_Intrinsic))
            unsupported(("`" + *tgt->value + "` is an `intrinsic`, but contract `" + contract
                         + "` is declared `for " + kamaImplKindListText(allowed)
                         + "` — an intrinsic can't implement it").c_str(), n->line);
        ClassInfo* tcip = nullptr;
        auto ti = _classes.find(ctKey);
        if (ti != _classes.end()) tcip = &ti->second;     // `string`, whose kama_string IS a ClassInfo
        else {
            ClassInfo& pci = primConformanceFor(tkey);
            pci.name = ctKey;
            pci.kind = TypeKind::Value;
            pci.isScalarRecv = true;                      // `this` is the scalar itself, not a pointer
            tcip = &pci;
        }
        ClassInfo& tci = *tcip;
        for (auto& ex : tci.interfaces)
            if (ex == contract) {
                unsupported(("`" + *tgt->value + "` already implements `" + contract + "`"
                             + duplicateOriginNote(tkey, contract)).c_str(), n->line);
                break;
            }
        SharedClassMemberDeclarationList members = intrinsicMembersFor(n, tgt);
        // A primitive has no storage of its own to add to, and nothing to destroy.
        for (auto& m : *members) {
            if (dynamic_cast<ClassFieldDeclarationNode*>(m.get()))
                unsupported("`type intrinsic` cannot declare a field — a primitive is its own storage",
                            m->line);
            else if (dynamic_cast<ClassDestructorDeclarationNode*>(m.get()))
                unsupported("`type intrinsic` cannot declare a destructor — a primitive owns nothing",
                            m->line);
        }
        // `isPrimitive` here means "a PRELUDE scalar/`string` conformance whose `Result<…>` return only
        // matters when the program uses serde" — NOT "has no _classes entry". `string` is exactly as
        // eligible as `int32`; keying off `_classes` instead would make `type intrinsic <string>
        // implements Serializable` register monomorphs whose bodies `implEmitsOf` then refuses to emit.
        injectImplMethods(tci, members, contract, tkey, /*isPrimitive=*/tgt->builtInVal != 0);
        checkImplCompleteness(tci, contract, *tgt->value, n->line);
    }
}

// Every (target ClassInfo, member list) this unit's `type intrinsic` blocks contribute — one per target in
// the set. The prototype pass and both body passes walk exactly this, so the three agree by construction
// rather than by three copies staying in step.
std::vector<CEmitter::ImplEmit> CEmitter::implEmitsOf(SharedCompilationUnit u)
{
    std::vector<ImplEmit> out;
    if (!u || !u->codeDeclarationList) return out;
    for (auto& decl : *u->codeDeclarationList) {
        if (auto* ii = dynamic_cast<IntrinsicImplNode*>(decl.get())) {
            SharedIdentifier c = intrinsicContract(ii);
            if (!c || !ii->targets || serdeGatedOff(c)) continue;
            for (auto& tgt : *ii->targets)
                if (ClassInfo* t = implTargetInfo(primKey(tgt)))
                    out.push_back(ImplEmit{t, intrinsicMembersFor(ii, tgt)});
        }
    }
    return out;
}

// The clause a duplicate-conformance message gains when the two claims come from DIFFERENT packages —
// the case neither the user nor either author can fix from one side, and the only one worth the extra
// words. Empty when both claims are in one package, or when either side has no manifest above it (a
// scratch file, the prelude), so the message reads exactly as it always did.
//
// Recorded lazily and resolved here rather than per unit up front: this runs at most once per error.
std::string CEmitter::duplicateOriginNote(const std::string& tkey, const std::string& contract)
{
    if (!_packageResolver) return std::string();
    auto it = _conformanceOrigin.find(std::make_pair(tkey, contract));
    if (it == _conformanceOrigin.end()) return std::string();
    std::string first = _packageResolver(it->second);
    std::string second = _packageResolver(_collectingUnitPath);
    if (first.empty() || second.empty() || first == second) return std::string();
    // Deliberately order-neutral. Which claim the collection pass happens to reach first says nothing
    // about which one is wrong, and phrasing it as "A already declares it, B claims it too" reads as an
    // accusation that lands on whichever package sorted second.
    return " — claimed by package `" + first + "` and by package `" + second +
           "`; only one package may own a (type, contract) pair, so one of them has to drop it";
}

// The C symbol of an impl-injected method. `injectImplMethods` already minted it, so the three emission
// passes read it back instead of each re-deriving `<target>__<method>` — the target's `name` is its C type,
// which is NOT what the symbol is prefixed with once two kama types share one C type (`char`/`uint32`).
std::string CEmitter::implMethodCName(ClassInfo& tci, const std::string& method)
{
    auto it = tci.methods.find(method);
    return it != tci.methods.end() ? it->second.cName : tci.name + "__" + method;
}

// Completeness: the impl must supply every method the contract requires.
// ONE sentence for a missing contract method, whichever pass finds it — the enum/intrinsic conformance check at
// collection or the vtbl emission for every implementer — named by the type as WRITTEN (a generic's template
// name, not one instance). Same file, line and text means the diagnostic dedup reports it once; the vtbl pass
// used to say "class missing contract method" a second time, and was the only thing a class ever said.
std::string CEmitter::missingContractMethod(const ClassInfo& ci, const std::string& contract, const std::string& method)
{
    std::string who = ci.name;
    if (ci.enumNode && ci.enumNode->identifier && ci.enumNode->identifier->value) who = *ci.enumNode->identifier->value;
    else if (ci.node && ci.node->name && ci.node->name->value) who = *ci.node->name->value;
    return "`" + who + "` implements `" + contract + "` but is missing method `" + method + "` required by the contract";
}

void CEmitter::checkImplCompleteness(ClassInfo& tci, const std::string& contract,
                                     const std::string& tkey, int line)
{
    // Phrased over the (type, contract) pair rather than one spelling of the impl, so it reads correctly
    // whether the conformance was declared on the type or supplied by an impl block.
    if (const std::vector<InterfaceMethod>* need = contractMethods(contract))
        for (auto& nm : *need) {
            auto have = tci.methods.find(nm.name);
            if (have == tci.methods.end()) {
                unsupported(("`" + tkey + "` implements `" + contract + "` but is missing method `"
                             + nm.name + "` required by the contract").c_str(), line);
                continue;
            }
            // Constness is part of the promise, not a local detail. A contract that declares `const fn`
            // says its callers may hold the implementer `const` — an implementation that drops the marker
            // makes that false for everyone bound by the contract. The converse is fine: an impl may be
            // MORE const than the contract asks, which only widens where it can be called.
            if (nm.isConst && !have->second.isConst)
                unsupported(("`" + tkey + "` implements `" + contract + "` but its `" + nm.name
                             + "` is not `const fn` — the contract declares it `const fn`, so a caller "
                               "holding a const receiver may call it; declare the implementation "
                               "`const fn` too").c_str(), line);
        }
    // The rest of the promise — return type, parameter types, arity. This is the ONLY path that reaches
    // an enum's or a `type intrinsic` block's conformance: a scalar's lands in `_primConformances` and
    // `string`'s on a collection ClassInfo, neither of which the `_classes` sweep looks at.
    checkConformanceSignature(tci, contract, tkey, line);
}

// a concrete type satisfies a contract BOUND when it has every one of the contract's methods,
// public (structural — this is exactly what makes the monomorphized call resolve to a static
// `Concrete__m(&x)`; nominal `implements` is not required, matching the codegen reality).
// The ClassInfo carrying an impl block's injected methods for `tkey` — a `primKey`, which is the C name for
// anything that has a `_classes` entry and the KAMA name for a scalar primitive. Either a collection's
// `_classes` entry (`kama_string`), or a primitive's `_primConformances` entry (scalar receiver). nullptr
// for a user-type target (which emits through the normal class machinery, not the impl emission path).
ClassInfo* CEmitter::implTargetInfo(const std::string& tkey)
{
    auto ti = _classes.find(tkey);
    // An intrinsic collection (`string` → `kama_string`) emits its injected method bodies through the
    // dedicated impl path (emitModuleContent / the prelude pass), NOT the normal per-class machinery — a
    // `ClassDeclarationNode` class emits via emitClassDefinitions and returns nullptr here.
    //
    // There is no enum arm, because there can be no enum TARGET: `intrinsic_target_list` is a `simple_type`
    // list, and `simple_type` is `primitive_type | class_type` where `class_type` is only `string`. It had
    // one while `implements C for MyEnum` existed.
    if (ti != _classes.end() && ti->second.isIntrinsicColl) return &ti->second;
    if (ClassInfo* pci = primConformance(tkey)) return pci;
    return nullptr;
}

// A `when [P1: B1, …]` gate holds iff EVERY condition holds: the concrete arg bound to each gated param
// satisfies its required contract. A condition naming a param that isn't a type-param of this template
// fails conservatively (as the old single-param gate did — it left the capability off).
// The contract named by a `when [P: B]` gate, resolved the way every OTHER contract name is.
//
// ⚠️ This used to store `*b->value` — the RAW SOURCE SPELLING — while a conformance list stores the
// RESOLVED name, so the two could never match and the gate silently failed. It looked like it worked
// because a PRELUDE contract resolves to its own bare name: `when [T: Hashable]` matched by accident,
// and `when [T: MyContract]` (which resolves to `_Fi1__MyContract`) never held at all. The conditional
// conformance was then dropped from the instance in silence, and the only symptom was an unrelated
// bound check failing much later — "type argument `Queue` does not satisfy bound `MyContract`" on a
// type that declares exactly that conformance.
//
// `default` is NOT a contract — it is the structural default-constructible gate `whenConditionsHold`
// answers itself — so it is passed through untouched. A prelude name resolves to itself, which is why
// the shipped `when [T: Copyable<T>]` clauses are unaffected.
std::string CEmitter::resolveWhenBound(const SharedIdentifier& b)
{
    if (!b || !b->value) return "Copyable";
    if (*b->value == "default") return "default";
    return resolveUserName(*b->value, b->qualifier);
}

// The contract a bound NAMES, exactly. `Source<int32>` is the instance `Source_int32`, and a conformance
// list holds instance names — so reading only the template name (as both gates did) made `when [P:
// Source<int32>]` never hold, and made `<P: Source<string>>` accept a `Source<int32>` (KR-15). The
// arguments are mangled under `bind`, the instance's own type-parameter bindings, so `Source<T>` names the
// instance for THIS `T`.
//
// The bare name comes back for the two cases where it is already the right answer: a PINNED contract,
// whose argument is the bounded type itself (`T: Comparable<T>`) and which `pinnedInstanceName` names per
// type; and an argument still naming an unbound parameter, which cannot be judged until instantiation.
// A type node as its source spelling, arguments included (`Source<int32>`) — for a diagnostic that must name
// what was WRITTEN, where the resolved or mangled name would be an instance nothing registered.
static std::string spellTypeNode(const SharedIdentifier& t)
{
    if (!t || !t->value) return "";
    std::string s = *t->value;
    if (t->genericArgs && !t->genericArgs->empty()) {
        s += "<";
        for (size_t i = 0; i < t->genericArgs->size(); ++i) s += (i ? ", " : "") + spellTypeNode((*t->genericArgs)[i]);
        s += ">";
    }
    return s;
}

std::string CEmitter::exactBoundName(const std::string& base, const SharedIdentifier& b,
                                     const std::map<std::string, SharedIdentifier>& bind)
{
    if (!b || !b->genericArgs || b->genericArgs->empty() || !_genericContracts.count(base)) return base;
    if (pinnedInstanceName(base, "_") != base) return base;
    const std::map<std::string, SharedIdentifier> saved = _typeSubst;
    for (auto& kv : bind) _typeSubst[kv.first] = kv.second;
    bool open = false;
    for (auto& a : *b->genericArgs) if (argCarriesUnboundParam(deepSubstType(a))) open = true;
    std::string m = open ? base : genericTypeMangle(base, b->genericArgs);
    _typeSubst = saved;
    return m;
}

bool CEmitter::whenConditionsHold(const std::vector<std::string>& whenParams,
                                  const std::vector<std::string>& whenBounds,
                                  const std::vector<SharedIdentifier>& whenBoundNodes,
                                  const std::vector<std::string>& params,
                                  const std::vector<SharedIdentifier>& concrete)
{
    std::map<std::string, SharedIdentifier> bind;
    for (size_t i = 0; i < params.size() && i < concrete.size(); ++i) bind[params[i]] = concrete[i];
    for (size_t c = 0; c < whenParams.size() && c < whenBounds.size(); ++c) {
        // Serde gate: a `when [T: Serializable]` / `[T: Deserializable]` conditional (a collection's `serialize`/
        // `deserialize`/`serKey`/… and its `Serializable`/`Deserializable` interface) is treated as UNSATISFIED when
        // the program uses no serde — so none of that machinery is emitted, and it references no primitive
        // serde impl (which is likewise gated off). A program that truly serializes has a Serializer backend
        // or a `@generate` type, which sets `_usesSerde` (see collectProgram) and restores the normal check.
        if (!_usesSerde && (whenBounds[c] == "Serializable" || whenBounds[c] == "Deserializable")) return false;
        bool held = false;
        for (size_t i = 0; i < params.size() && i < concrete.size(); ++i)
            if (params[i] == whenParams[c]) {
                // `when [A: default]` — a STRUCTURAL gate (no nominal `Default` contract): the arg bound to A
                // must itself be default-constructible. Reuse isDefaultFillable (the completeness predicate),
                // so a custom-allocator collection's `empty()`/`withCapacity()` simply don't exist for an `A`
                // without a `default` ctor (closes the M8c zero-allocator hole; killing the force-emit too).
                held = (whenBounds[c] == "default")
                     ? isDefaultFillable(cType(concrete[i]))
                     : satisfiesBound(primKey(concrete[i]),
                                      c < whenBoundNodes.size() ? exactBoundName(whenBounds[c], whenBoundNodes[c], bind)
                                                                : whenBounds[c]);
                break;
            }
        if (!held) return false;
    }
    return true;
}

// Is `ci` deeply immutable, as the `Immutable` BOUND asks?
//
// ⚠️ It reads the QUALIFIER, not only the computed flag, and that is deliberate: `computeDeeplyImmutable`
// runs partway through `collectProgram`, while a bound is checked at every generic instantiation —
// including ones registered before it, where `deeplyImmutable` is still false and a correct
// `<T: Immutable>` would be refused for a reason having nothing to do with the type.
//
// Reading the qualifier is not a weakening, because the two coincide in every program that COMPILES: a
// `type immutable` holding a mutable member is a hard error naming that member (tests/xfail/
// immutable_mutable_field.kama), so `isImmutableQualified && !deeplyImmutable` is exactly the set of
// programs already rejected — and rejected with a better diagnostic than a bound failure would give.
// The qualifier is the declaration; the pass is its verification; the bound may read the declaration.
bool CEmitter::isImmutableType(const ClassInfo& ci) const
{
    return ci.deeplyImmutable || ci.isImmutableQualified;
}

bool CEmitter::classSatisfiesBound(ClassInfo* ci, const std::string& contract)
{
    if (!ci) return false;
    // NOMINAL: the type must DECLARE `implements <contract>` — the keyword is load-bearing for bounds
    // exactly as it is for `foreach`/`when`; a coincidental set of matching public method names is not
    // enough (explicit over implicit). `implementsContractTemplate` matches a plain contract by name AND a
    // generic-contract bound against its TEMPLATE (`Iterator<T>` — no instance needed to constrain a param).
    // `Copyable` keeps its one structural rule: a `value` is bitwise-copyable; a `resource` only by declaring
    // it. (A primitive / impl-block target is handled by the caller before we're reached.)
    if (contract == "Copyable") {
        if (ci->kind == TypeKind::Value) return true;
        return ci->copyable;
    }
    // ...and `Immutable`'s one derived rule, the same shape: answered from the verified deep property
    // rather than from a declaration, because a declaration could lie about it.
    if (contract == "Immutable") return isImmutableType(*ci);
    // ...and `Sendable`'s: nominal for a user type, by nature for an intrinsic (`InlineArray<int32>`, a
    // boxed contract that requires it) — the same predicate `satisfiesBound` consults, so the two halves
    // of the bound check cannot disagree about it.
    if (!_sendableContract.empty() && contract == _sendableContract) return isSendableClass(ci->name);
    // ...and the read half of serde's: a graph comes back as `Shared<X>`, because a cycle cannot be
    // returned by value, so `deserializeJsonBuffer::<Shared<Node>>` needs the bound to hold for the HANDLE.
    // Derived from the pointee rather than declared as a `deserialize` on `Shared`, which would shadow the
    // pointee's through auto-deref — the hazard that keeps the triad method-free. `satisfiesBound` carries
    // the same arm, so the two halves of a bound check cannot disagree about it.
    // The WRITE half of the same rule: a `Shared`/`Weak` on the wire is an id into the object table, so a
    // container of edges (`DynamicArray<Shared<Node>>`) satisfies its own `Serializable when [T: Serializable]`
    // gate with no library change at all. Same reasoning as the read half below, same reason it is derived
    // rather than a method on the handle.
    if (contract == "Serializable") {
        std::string x = sharedPointeeClass(ci->name);
        if (x.empty()) x = ownedPointeeClass(ci->name);      // an `Owned` subtree is written inline
        auto e = x.empty() ? _classes.end() : _classes.find(x);
        if (e != _classes.end() && classSatisfiesBound(&e->second, "Serializable")) return true;
    }
    if (contract.compare(0, 14, "Deserializable") == 0) {
        std::string x = sharedPointeeClass(ci->name);
        if (x.empty()) x = ownedPointeeClass(ci->name);
        auto e = x.empty() ? _classes.end() : _classes.find(x);
        // ⚠️ Asked off the pointee's own bound, NOT off `reachesPointer`/`graphDeserialize`: bounds are
        // judged while a generic instance is registered, during collection, and the graph passes have not
        // run — requiring `reachesPointer` here made every real graph fixture fail its bound. The cost is
        // that `Shared<PointerFreeType>` satisfies this and is refused later, at the ctor lookup, which
        // carries its own diagnostic naming both halves.
        if (e != _classes.end() && (e->second.graphDeserialize
                                    || classSatisfiesBound(&e->second, pinnedInstanceName("Deserializable", x))))
            return true;
    }
    return implementsContractTemplate(ci, contract);
}

bool CEmitter::implementsContractTemplate(ClassInfo* ci, const std::string& tmpl)
{
    if (!ci) return false;
    for (auto& itf : ci->interfaces) {
        if (itf == tmpl) return true;                              // a plain (non-generic) contract
        auto it = _interfaces.find(itf);                          // a specialized generic-contract instance
        if (it != _interfaces.end() && it->second.templateKey == tmpl) return true;
    }
    return false;
}

// If `cls` implements the prelude `Deref<T>` contract, return the pointee class `T` (the auto-deref
// target); "" otherwise. Nominal: keyed on `implements Deref<…>` (the contract is the opt-in gate), not
// on any compiler-blessed smart-pointer list. The pointee is the concrete `ref T` return of the class's
// own `deref()` (resolved under the instance's type-subst for a generic wrapper). Inert (always "") when
// no `Deref` is in scope, so the whole feature is zero-cost when unused.
std::string CEmitter::derefTarget(const std::string& cls)
{
    if (_derefContract.empty() && _derefMutContract.empty()) return "";
    auto it = _classes.find(cls);
    if (it == _classes.end()) return "";
    for (auto& ifn : it->second.interfaces) {
        auto ii = _interfaces.find(ifn);
        if (ii == _interfaces.end() || !ii->second.isGenericInst) continue;
        // Either half names the pointee: `Deref<T>` through `deref()`, `DerefMut<T>` through `derefMut()`.
        const char* member = ii->second.templateKey == _derefContract      ? "deref"
                           : ii->second.templateKey == _derefMutContract   ? "derefMut" : nullptr;
        if (!member) continue;
        ClassInfo* oc = nullptr;
        MethodInfo* mi = findMethod(&it->second, member, &oc);
        if (!mi || !mi->returnType) return "";
        std::string t = cTypeInInstance(cls, mi->returnType);   // resolves `ref T` under a generic wrapper's subst
        return isClass(t) ? t : "";
    }
    return "";
}

// The accessor an auto-deref through `cls` goes through for THIS receiver: `derefMut()` when the type
// implements `DerefMut<T>` and the receiver is not const (a writable place), else `deref()` (the read-only
// place a `const ref Owned<T>` may still hand out). A type implementing only `Deref<T>` forwards reads and
// nothing else — a write or a non-const call through it is refused where the place is used. Null when the
// type has neither.
MethodInfo* CEmitter::derefAccessor(const std::string& cls, SharedExpression recv, bool* isConstPlace)
{
    if (isConstPlace) *isConstPlace = false;
    if (!_classes.count(cls)) return nullptr;
    ClassInfo* dc = nullptr;
    MethodInfo* mut = findMethod(&_classes[cls], "derefMut", &dc);
    if (mut && !(recv && isConstReceiver(recv))) return mut;
    MethodInfo* ro = findMethod(&_classes[cls], "deref", &dc);
    if (ro && isConstPlace) *isConstPlace = true;
    return ro ? ro : mut;
}

// The C function a string-built deref site calls — the handle→pointee bridges that hand a smart pointer's
// pointee to a `ref` parameter, a contract fat pointer or an upcast, which have no receiver EXPRESSION to
// ask about constness, only a need: `wantMut` says the consumer writes (a `ref T` parameter, a contract
// box, a base handle), and a read-only consumer (`const ref T`) takes `deref()`. A type with only one half
// gets that half; the C backstop then judges a `T const*` handed to a writer.
std::string CEmitter::derefFnName(const std::string& cls, bool wantMut)
{
    if (_classes.count(cls)) {
        ClassInfo* dc = nullptr;
        if (wantMut) if (MethodInfo* m = findMethod(&_classes[cls], "derefMut", &dc)) return m->cName;
        if (MethodInfo* m = findMethod(&_classes[cls], "deref", &dc)) return m->cName;
        if (MethodInfo* m = findMethod(&_classes[cls], "derefMut", &dc)) return m->cName;
    }
    return cls + "__deref";
}

// Does this `new` draw from the HEAP? A bare `new` does — it is libc malloc under the box's default
// `GlobalAllocator`. A placement `new(allocator: a)` draws from `a`, and the block it hands back is the
// caller's storage: a `BumpAllocator` over an `InlineArray` the program owns reaches no allocator of the
// system's. The no-heap gate asked neither question and refused the VERB, which made the rule hold in one
// position and not its sibling — `DynamicArray<int32, BumpAllocator>` has always been legal in a `@noheap`
// region (SPEC *No-heap subset*), while `new(allocator: bump) Circle.make()` was not, though both reach
// exactly the same `BumpAllocator::allocate`. Nothing is waved through: the emitted C calls `A__allocate`,
// which is an ordinary edge, so an `A` that does reach the heap is caught by the walk, one hop later and
// with the chain to prove it — the same way a container is.
//
// Answered quietly (no diagnostics): a malformed placement list is diagnosed by placementAllocator itself,
// at emission, and saying it twice helps no one.
bool CEmitter::newDrawsFromHeap(ObjectCreationNode* oc) const
{
    if (!oc || !oc->placement || oc->placement->empty()) return true;
    for (auto& a : *oc->placement)
        if (a && a->name && a->name->value && *a->name->value == "allocator" && a->expression) {
            const std::string ty = const_cast<CEmitter*>(this)->exprClass(a->expression);
            return ty.empty() || ty == "GlobalAllocator";
        }
    return true;
}

// Placement `new(allocator: a) T(...)`: extract the `allocator:` arg's C expression + its allocator class.
// Returns {"",""} for a bare `new` (no placement list). `emit=false` resolves the class only (no emission),
// for the pre-flight target-kind check; `emit=true` materializes the C expression (evaluated once by the
// caller into a temp). Diagnoses a missing `allocator:` slot or a non-class allocator.
std::pair<std::string,std::string> CEmitter::placementAllocator(ObjectCreationNode* oc, int line, bool emit)
{
    if (!oc || !oc->placement || oc->placement->empty()) return {"", ""};
    for (auto& a : *oc->placement) {
        if (a && a->name && a->name->value && *a->name->value == "allocator" && a->expression) {
            std::string ty = exprClass(a->expression);
            if (ty.empty() || !_classes.count(ty))
                unsupported("placement `new(allocator: …)` needs an `Allocator` value", line);
            return {emit ? emitExpression(a->expression) : std::string(), ty};
        }
    }
    unsupported("placement `new(...)` accepts only an `allocator:` argument", line);
    return {"", ""};
}

// The allocator type-arg of an `Owned<T, A>` / `Shared<T, A>` box instance (its `alloc` field type);
// "" if not one. Only the built-in `Owned`/`Shared` boxes (keyed by template) qualify — a user
// HeapOwner isn't gated. Drives the "bare `new` into a stateful-A box leaks" diagnostic; `Weak` is
// never a `new` target so it isn't gated here.
std::string CEmitter::boxAllocatorArg(const std::string& ty)
{
    auto t = _genericTypeInstOf.find(ty);
    if (t == _genericTypeInstOf.end() || (t->second != _ownedTmpl && t->second != _sharedTmpl)) return "";
    auto ci = _classes.find(ty);
    if (ci == _classes.end()) return "";
    for (auto& f : ci->second.fields)                                          // the box's `A alloc` field,
        if (f.name == "alloc" && f.type) return cTypeInInstance(ty, f.type);   // resolved to the concrete A
    return "";
}

// A bare `new`/`try new` takes its block from the global allocator (the funnel), and the box releases it through its
// own `A` — so the two meet only when `A` IS `GlobalAllocator`. Any other `A` is refused and told the placement
// form, stateless or not: a field-less custom allocator used to pass here, and its box freed through `A` a block
// the funnel had allocated (measured: 0 allocations and 2 frees through `A` for one `Shared`), which a declared
// `@globalAllocator` turns from latent into freeing pool memory elsewhere. "" when the bare form is fine.
std::string CEmitter::bareNewRefusal(const std::string& boxAlloc, const std::string& verb, const std::string& what)
{
    if (boxAlloc.empty() || boxAlloc == "GlobalAllocator") return "";
    return "this box releases through its allocator `" + boxAlloc + "`, but a bare `" + verb + "` draws from the global "
           "allocator — construct it with `" + verb + "(allocator: …) " + what + "(...)`";
}

bool CEmitter::ifaceNewAllocator(const std::string& ty, ObjectCreationNode* oc, int line, const char* verb)
{
    const std::string V(verb);   // "new" / "try new" — the advice must name the verb the user wrote
    std::string allocType = _collections.count(ty) ? _collections[ty].allocType : "";
    bool boxStateful = !allocType.empty() && allocType != "GlobalAllocator";
    auto pa = placementAllocator(oc, line, /*emit=*/false);   // resolve the handle type only (no emission)
    bool placed = !pa.second.empty();
    if (placed) {
        // No inference axis: the placement handle's type must equal the box's declared allocator.
        if (allocType != pa.second)
            unsupported((allocType.empty()
                ? "`" + ty + "` has no allocator parameter — a placement `" + V + "(allocator: …)` needs a box "
                  "like `Owned<Contract, A>`/`Shared<Contract, A>`"
                : "the box's allocator type `" + allocType + "` does not match the `" + V + "(allocator: …)` "
                  "handle `" + pa.second + "` — spell the box's allocator explicitly").c_str(), line);
    } else if (boxStateful) {
        unsupported(bareNewRefusal(allocType, verb, "T").c_str(), line);
    }
    return boxStateful;   // a matched, non-Global placement drives the `_ALLOC_` emission path
}

// Is `r` a ctor call spelled on a generic TEMPLATE name — `Box.make(…)`, `SortedMap::withAllocator(…)` —
// or a qualified variant construction (`Optional::Some(…)`)? Such a call has no instance of its own: the
// emitter resolves `Box` -> `Box_int32` from the assignment TARGET (the same channel a local declaration
// uses), so the two assignment paths agree on it through this one predicate — the value-producing path
// claims it, the fresh-rvalue resource path leaves it alone. Both spellings are here because the
// corpus reassigns through both, and a predicate that knew one of them would send the other into a
// standalone emit with no target type to resolve against. A call on a concrete type, or a free
// function returning an instance by value, is not one.
bool CEmitter::isGenericDotCtorCall(ASTNode* r)
{
    auto* iv = dynamic_cast<InvocationNode*>(r);
    if (!iv) return false;
    if (auto* ma = dynamic_cast<MemberAccessNode*>(iv->expression.get())) {
        std::string dt;
        if (isTypeReceiver(ma, dt) && _genericTypeParams.count(dt)) return true;
    }
    SharedStringList qual = iv->identifier ? iv->identifier->qualifier : nullptr;
    if (!qual || qual->empty()) return false;
    auto q = std::make_shared<StringList>();
    for (size_t i = 0; i + 1 < qual->size(); ++i) q->push_back((*qual)[i]);
    std::string en = resolveUserName(*qual->back(), q);
    return (_classes.count(en) && _classes[en].isVariant) || _genericTypeParams.count(en);
}

// If `e` is `this.field[i]` (or `obj.field[i]`) where `field` is a raw `UnsafePtr<T>`, return the element's
// concrete C-type; else "". This is a raw pointer slot (unsafe manual memory) — a container's own buffer —
// distinct from a collection / user operator[].
// ⚠️ The element resolves under the FIELD'S OWNER instance, never under whatever `_typeSubst` is ambient.
// It used to read `cType(f.type->genericArg)`, which answers only when the element's type-param name
// happens to be bound right now — and the caller that matters most, `emitVariantConstruction`, has the
// ENUM's params installed. So `Map<K,V>`'s `UnsafePtr<V>` came back "" (only `Optional`'s `T` was bound),
// `exprClass` said "not a class", and `Optional::Some(value: copy this.vals[i])` silently dropped the copy
// and emitted a bitwise ALIAS of a buffer the map still owns. It survived only when the container spelled
// its parameter `T` — the same letter `Optional<T>` uses — which is why `DynamicArray`/`Deque`/`FixedArray`/
// `ConstView` were correct and `Map`/`SlotMap` needed `cloneVal`/`cloneKey(const ref V)` workarounds.
// This is the M10b fix applied to the branch M10b missed: `indexElemTypeRaw`'s user-`operator[]` arm binds
// the owner instance for exactly this reason, and then falls through to here, which did not.
// See `tests/generic_index_optional_return.kama` (the sibling's regression) and `tests/copy_elem_nonT_param`.
std::string CEmitter::ptrElemType(SharedExpression e)
{
    auto* ea = dynamic_cast<ElementAccessNode*>(e.get());
    if (!ea) return "";
    SharedExpression recv = ea->expression ? ea->expression
                                           : std::static_pointer_cast<ExpressionNode>(ea->identifier);
    auto* ma = dynamic_cast<MemberAccessNode*>(recv.get());
    if (!ma || !ma->identifier || !ma->identifier->value || !_currentClass) return "";
    ClassInfo* owner = findFieldOwner(_currentClass, *ma->identifier->value);
    if (!owner) return "";
    for (auto& f : owner->fields)
        if (f.name == *ma->identifier->value && f.type && f.type->value
            && isRawPtrName(*f.type->value) && f.type->genericArg)
            return cTypeInInstance(owner->name, f.type->genericArg);
    return "";
}

// The POINTEE C type of an expression whose own type is a raw `UnsafePtr<T>` — "" if it is not one.
// `drop(ptr:)`'s whole gate. Two shapes reach it: a pointer NAME (a field like `Owned`'s `p`, a local, a
// parameter), answered by `lvalueCType`; and `addr(of: place)`, whose pointee is the place's own type —
// that one is how a container drops an element sitting in its hand-managed buffer.
// ⚠️ `UnsafeConstPtr<T>` lowers east-const to `T const*`, and a destructor MUTATES what it runs on, so a
// const pointer is deliberately NOT accepted here; the caller is told to use the writable form.
// ⚠️ `addr(of: someLocal)` DOES launder a local back into a pointer, and that is accepted on purpose:
// `addr(of: …)` itself requires an `unsafe fn`, so reaching it means the author has taken responsibility.
// What the pointer form buys is that SAFE code cannot express the double drop at all — not that unsafe
// code is prevented from doing deliberate things.
std::string CEmitter::rawPointeeCType(SharedExpression e)
{
    if (!e) return "";
    if (auto* inv = dynamic_cast<InvocationNode*>(e.get()))
        if (inv->identifier && inv->identifier->value && *inv->identifier->value == "addr"
            && (!inv->identifier->qualifier || inv->identifier->qualifier->empty())
            && inv->args && inv->args->size() == 1) {
            SharedExpression of = (*inv->args)[0]->expression;
            std::string pc = exprClass(of);
            if (pc.empty()) pc = indexElemTypeRaw(of);   // unfiltered: a primitive element answers too
            return pc;                                    // the caller decides whether it is destructible
        }
    std::string ct = lvalueCType(e);
    if (ct.size() < 2 || ct.back() != '*' || ct == "void*") return "";
    ct = ct.substr(0, ct.size() - 1);
    while (!ct.empty() && ct.back() == ' ') ct.pop_back();
    const std::string csuf = " const";
    if (ct.size() > csuf.size() && ct.compare(ct.size() - csuf.size(), csuf.size(), csuf) == 0) return "";
    return ct;
}

// A bare-LOCAL/param `UnsafePtr<T>` element target `buf[i]` (NOT `this.field[i]` — that's ptrElemType above):
// the element C-type, used in the assignment store path for an explicit `give`/`copy` raw-slot move into a
// local pointer, and (0.9.228) to type the RECEIVER of a method call on such an element, which borrows it
// in place. Kept separate from ptrElemType (which also feeds exprClass) so this stays out of exprClass —
// an UNMARKED local store (`nd[i] = od[j]`, the untracked raw-relocate collections rely on) must keep its
// plain-C-store semantics. `UnsafePtr<T>` lowers to `T*`, so strip one trailing `*`; bare `UnsafePtr`
// -> `void*` is not indexable (excluded). Only locals/params live in `_localCTypes`, and a `ref T` param
// lowers to `T` (no `*`), so no false positives.
// Is `recv` (the receiver of a raw-element access) a pointer to `cchar`? The element C type comes from
// the field or local pointer's own type; one `*` is stripped for a nested `pp[i][j]`. `UnsafeConstPtr`
// leaves a trailing ` const`, hence the prefix test.
bool CEmitter::rawElemIsCChar(SharedExpression access)
{
    auto* ea = dynamic_cast<ElementAccessNode*>(access.get());
    if (!ea) return false;
    std::string et = ptrElemType(access);
    if (et.empty()) et = ptrLocalElemType(access);
    if (et.empty() && ea->expression && dynamic_cast<ElementAccessNode*>(ea->expression.get())) {
        // `pp[i][j]`: the outer access names a pointer-to-pointer element; strip one `*` for the inner.
        std::string outer = ptrElemType(ea->expression);
        if (outer.empty()) outer = ptrLocalElemType(ea->expression);
        if (outer.size() > 1 && outer.back() == '*') et = outer.substr(0, outer.size() - 1);
    }
    return et.rfind("kama_cchar", 0) == 0;
}

std::string CEmitter::ptrLocalElemType(SharedExpression e)
{
    auto* ea = dynamic_cast<ElementAccessNode*>(e.get());
    if (!ea) return "";
    SharedExpression recv = ea->expression ? ea->expression
                                           : std::static_pointer_cast<ExpressionNode>(ea->identifier);
    auto* id = dynamic_cast<IdentifierNode*>(recv.get());
    if (!id || !id->value) return "";
    auto it = _localCTypes.find(*id->value);
    if (it == _localCTypes.end()) return "";
    const std::string& ct = it->second;
    if (ct.size() > 1 && ct.back() == '*' && ct != "void*") return ct.substr(0, ct.size() - 1);
    return "";
}

// The class of a hand-off SOURCE — `exprClass`, widened for a bare-local `buf[i]` when the author wrote
// an explicit `give`/`copy`.
//
// `ptrLocalElemType` is deliberately kept out of `exprClass` (see its comment) so an UNMARKED raw store —
// `nd[i] = od[j]`, the relocate idiom the untracked collections rely on — keeps its plain-C-store
// semantics. That reasoning covers the unmarked store and nothing else: a MARKED `copy p[i]` is the
// author naming an element and asking for a deep copy, so the element's class must be known or the marker
// is dropped in silence. It was: measured on a fully CONCRETE element, with no generics anywhere,
// `copy p[0]` on a local/param `UnsafePtr<Box>` aliased in variant-payload, call-argument AND return
// position (a local's initializer was the one form that worked, because it keys on the declared type).
//
// One helper for all three hand-off sites, not three copies — `copyCall`'s own comment records what
// happened when this kind of fact lived at twelve.
std::string CEmitter::handoffSourceClass(SharedExpression e, int handoff)
{
    std::string c = exprClass(e);
    if (!c.empty() || !handoff || !e) return c;
    // `UnsafeConstPtr<T>` lowers east-const (`T const*`), so the stripped element carries a ` const`
    // suffix that is not part of the class name — copying OUT of a read-only buffer is still a copy.
    std::string et = ptrLocalElemType(e);
    const std::string csuf = " const";
    if (et.size() > csuf.size() && et.compare(et.size() - csuf.size(), csuf.size(), csuf) == 0)
        et = et.substr(0, et.size() - csuf.size());
    return isClass(et) ? et : "";
}

// ⚠️ The backstop for the failure mode row 9 cost a session to find: a `give`/`copy` that the author WROTE,
// whose source class did not resolve, handed into a destination that OWNS something. Every branch of every
// hand-off site keys on the source class, so an unresolved one falls through to "plain value" — where a
// marker on a primitive is a documented no-op — and the transfer silently becomes a bitwise copy. For an
// owning destination that is an alias, and the owner and the copy then both free it.
//
// Since `0.9.283`/`0.9.284` every named-lvalue shape has a resolver — local, field, element, a raw-pointer
// element through a field OR a bare local, a place-returning call — so reaching here is a COMPILER bug, not
// a program error, and it says so. A primitive or `value` payload is untouched: its destination owns
// nothing, so it never gets this far.
void CEmitter::rejectUnresolvedHandoff(const std::string& srcCls, const std::string& dstCType,
                                       SharedExpression e, int handoff, const char* what, int line)
{
    if (!handoff || !srcCls.empty() || !e || !isNamedValue(e.get())) return;
    if (!ownsByValue(dstCType) && !isSmartPtrClass(dstCType)) return;
    // ⚠️ Only when nothing has been reported yet. A type that did not resolve because the author has an
    // error ALREADY DIAGNOSED — a missing import is the common one — leaves every downstream class empty,
    // and blaming the compiler for that is worse than saying nothing: it buries the real message under a
    // "please report it" the reader cannot act on. Caught the first time this guard met a real mistake,
    // where one absent `import { std::collections::DynamicArray }` produced both.
    if (!_diagnostics.empty()) return;
    unsupported((std::string(handoff == 1 ? "`give`" : "`copy`") + " of " + what + " cannot be lowered: the "
                 "source's type did not resolve, so the hand-off would silently become a bitwise copy of a `"
                 + dstCType + "` — an alias the owner still frees. This is a COMPILER bug, not a mistake in "
                 "this file; please report it with the snippet").c_str(), line);
}

// Is `base` reachable by walking `derived`'s single-inheritance chain (inclusive)? Used to admit a
// `Derived -> ref Base` upcast while rejecting an unrelated `ref` (e.g. borrowing through a `Weak`).
#if KAMA_INHERITANCE
bool CEmitter::isBaseOf(const std::string& base, const std::string& derived) const
{
    auto it = _classes.find(derived);
    for (const ClassInfo* c = (it != _classes.end() ? &it->second : nullptr); c; c = c->base)
        if (c->name == base) return true;
    return false;
}
#else
bool CEmitter::isBaseOf(const std::string&, const std::string&) const { return false; }
#endif

// If `cls` implements the prelude `HeapOwner<T>` contract, return the owned element `T` (so `new T(args)`
// placement-constructs into `cls` via `cls::adopt(UnsafePtr<T>)`); "" otherwise. The element is the contract
// instance's type arg. Inert (always "") when no `HeapOwner` is in scope.
std::string CEmitter::heapOwnerTarget(const std::string& cls)
{
    if (_heapOwnerContract.empty()) return "";
    auto it = _classes.find(cls);
    if (it == _classes.end()) return "";
    for (auto& ifn : it->second.interfaces) {
        auto ii = _interfaces.find(ifn);
        if (ii == _interfaces.end() || !ii->second.isGenericInst || ii->second.templateKey != _heapOwnerContract)
            continue;
        if (ii->second.typeArgs.empty() || !ii->second.typeArgs[0]) return "";
        // the element is the contract instance's type arg, resolved in its use-site ctx (a user `Point`).
        NsCtx saved = _nsCtx;
        if (_genericContractInstCtx.count(ifn)) _nsCtx = _genericContractInstCtx[ifn];
        std::string t = cType(ii->second.typeArgs[0]);
        _nsCtx = saved;
        return t;
    }
    return "";
}

// A bound names a contract in the scope where the TEMPLATE was written, not where it is called. Checking
// it under the call site's namespace made a bound resolvable only if the caller had also imported the
// contract — so `std::fmt`'s `parse<T: Parseable>` forced every user to `import` a marker contract they
// never name, and the only reason `decode<T: Deserializable>` never showed this is that `Deserializable` lives
// in the always-visible prelude. Restores the caller's context on the way out.
// Only the CONTRACT name moves scope. The concrete type argument still has to resolve at the call site
// (it is the caller's `Point`), which is why this wraps the contract lookup alone and not all of
// checkBounds. Generic functions and generic types keep their home context in different maps.
CEmitter::BoundCtxScope::BoundCtxScope(CEmitter* e, const std::string& templateKey) : _e(e), _saved(e->_nsCtx)
{
    auto it = e->_genericCtx.find(templateKey);
    if (it != e->_genericCtx.end()) { e->_nsCtx = it->second; return; }
    auto tt = e->_genericTypeCtx.find(templateKey);
    if (tt != e->_genericTypeCtx.end()) e->_nsCtx = tt->second;
}
CEmitter::BoundCtxScope::~BoundCtxScope() { _e->_nsCtx = _saved; }

// at each monomorphization, verify the concrete type argument bound to `paramName` satisfies
// every contract on it (`+` = AND); a clean diagnostic instead of a downstream "class missing method".
//
// Returns false when a bound was REFUSED, so the caller can poison the instance and stop the template's
// body being walked with an argument it just rejected — see registerGenericTypeInst. A DEFERRAL (an
// argument that is not concrete yet) is not a refusal and answers true: the per-instantiation re-walk
// runs this again with the real argument, and poisoning on a deferral would silence the whole template.
bool CEmitter::checkBounds(const std::string& paramName, SharedIdentifier concreteArg,
                           SharedIdentifierList bounds, int line, const std::string& templateKey,
                           const std::map<std::string, SharedIdentifier>& bind)
{
    if (!bounds || bounds->empty()) return true;
    // A failed bound is the USE SITE's mistake and carries the use site's line, so it belongs to the file
    // that wrote the type argument — which is what `_nsCtx` names here. All three callers (a generic type,
    // a generic contract, a generic function) reach this from passes where no module is current, so
    // without it a bad type argument named no file at all. Keeps the current value when there is nothing
    // better to say. See diagFile().
    ScopedStr _cu(_collectingUnitPath, _nsCtx.unitPath.empty() ? _collectingUnitPath : _nsCtx.unitPath);

    // The argument may not be concrete yet: one generic function forwarding its own parameters into
    // another (`sortWith::<T, C>` calling `lessAt::<T, C>`) passes `C` itself, and a generic type
    // spelled at a parameter (`Natural<T>`) mentions one. Neither can be looked up — the enclosing
    // template has not been monomorphized, so there is no type to check. Defer instead of rejecting:
    // the per-instantiation re-walk runs this again with the real argument, which is both where the
    // answer exists and where a user wants the diagnostic pointed.
    std::function<bool(const SharedIdentifier&)> mentionsParam = [&](const SharedIdentifier& t) -> bool {
        if (!t || !t->value) return false;
        if (!t->genericArg && isTypeParamName(*t->value)) return true;
        if (t->genericArgs) for (auto& a : *t->genericArgs) if (mentionsParam(a)) return true;
        return false;
    };
    if (mentionsParam(concreteArg)) return true;          // deferred, not refused

    bool ok = true;
    std::string cls = cType(concreteArg);                 // concrete class key (or a primitive C type)
    std::string rkey = primKey(concreteArg);              // the CONFORMANCE key — `cls` still feeds _classes
    // source-level — and a SUBSTITUTED argument (a primitive bound to an enclosing template's `T`) carries no
    // spelling, which made the diagnostic read "type argument `` for …"; its conformance key is its kama name.
    std::string clsName = (concreteArg && concreteArg->value && !concreteArg->value->empty())
                        ? *concreteArg->value : demangleForDisplay(rkey.empty() ? cls : rkey);
    ClassInfo* ci = _classes.count(cls) ? &_classes[cls] : nullptr;
    for (auto& b : *bounds) {
        if (!b || !b->value) continue;
        std::string contract;
        { BoundCtxScope bc(this, templateKey); contract = resolveUserName(*b->value, b->qualifier); }
        if (!contractMethods(contract)) {   // a plain contract OR a generic-contract template (`Iterator<T>`)
            // A bound in a USER declaration was already judged where it is written, once, by
            // `checkDeclaredTypes` — with the import hint, before any instantiation. Repeating it here, at
            // the use site's line, said the same thing twice about two different lines. Only a
            // compiler-owned template can still arrive unjudged, and that is a compiler defect worth naming.
            const std::string tf = declFileOf(templateKey);
            if (tf.empty() || tf[0] == '<')
                unsupported(("unknown contract `" + *b->value + "` in a bound on type parameter `"
                             + paramName + "`").c_str(), line);
            ok = false;                     // an unspellable bound is unsatisfiable — poison it too
            continue;
        }
        // A declared conformance to <bound> also satisfies it. Consult the pre-scan so a bound check that
        // runs during collection (before the methods are injected) still sees it. Matched on the RESOLVED
        // name, which the pre-scan also stores: two same-named contracts in different namespaces are two
        // contracts, and a conformance to one must not satisfy a bound on the other.
        // ...and the bound's type ARGUMENTS are part of what it names: `Source<int32>` is not `Source<string>`.
        // `contractMethods` above wanted the template; every conformance test below wants the instance.
        const std::string tmplName = contract;
        { BoundCtxScope bc(this, templateKey); contract = exactBoundName(contract, b, bind); }
        bool declared = _intrinsicConformances.count(rkey) && _intrinsicConformances[rkey].count(contract);
        // A boxed polymorphic contract handle satisfies the contract bound: `Owned<C>`/`Shared<C>`/
        // `Weak<C>` (and `Owned<X>` where `X` implements `C`) dynamic-dispatches `C`'s methods, so a
        // boxed `Error` IS an `Error` (Model C). This lets `Result<T, Owned<Error>>` — the uniform serde
        // error channel — satisfy the `E: Error` bound without `Owned` itself declaring `implements Error`.
        bool boxed = false;
        if (!declared && isSmartPtrClass(cls)) {
            const std::string& elem = _classes[cls].collElemClass;
            if (elem == contract) boxed = true;
            else if (_classes.count(elem) && classSatisfiesBound(&_classes[elem], contract)) boxed = true;
        }
        // A PRIMITIVE has no `_classes` entry, so `ci` is null and every bound would read as unsatisfied.
        // `satisfiesBound` is the other half of this same question and it answers for one — `Copyable` is
        // structural there (a primitive is bitwise-copyable, as is any `value`) — so consult it rather
        // than let the two disagree. They did: `<T: Copyable<T>>` was unusable as a DECLARED bound while
        // `when [T: Copyable<T>]` worked, because the gate goes through `satisfiesBound` and this did not.
        bool structural = !ci && satisfiesBound(rkey, contract);
        if (!declared && !boxed && !structural && (!ci || !classSatisfiesBound(ci, contract))) {
            // A failed `Sendable` bound says WHY (the field, the mutable pointee, the undeclared type):
            // it is the channel crossing's gate, and "does not satisfy" alone sent the author hunting.
            const std::string why = (!_sendableContract.empty() && contract == _sendableContract)
                                  ? unsendableReason(cls) : std::string();
            if (_silentBounds == 0) {  // a consequence of an already-refused outer instance says nothing (see registerGenericTypeInst)
                // …and a failed bound on a `@generate`d generic INSTANCE says which field lost it the
                // derive, for the same reason: the condition is invisible at the use site.
                const std::string dnote = derivedUnmetNote(cls, *b->value);
                unsupported(("type argument `" + clsName + "` for type parameter `" + paramName
                             + "` does not satisfy bound `" + (contract != tmplName ? spellTypeNode(b) : *b->value) + "`"
                             + (why.empty() ? "" : " — " + why) + dnote).c_str(), line);
            }
            ok = false;
        }
    }
    return ok;
}

// "__base." repeated for each hop from `from` down to ancestor `to` ("" if equal).
#if KAMA_INHERITANCE
std::string CEmitter::basePathTo(ClassInfo* from, ClassInfo* to)
{
    std::string path;
    for (ClassInfo* c = from; c && c != to; c = c->base) path += "__base.";
    return path;
}
#else
std::string CEmitter::basePathTo(ClassInfo*, ClassInfo*) { return ""; }
#endif

#if KAMA_INHERITANCE
std::string CEmitter::vptrPrefix(ClassInfo* ci)
{
    if (!ci || ci->vtableRoot.empty()) return "";
    auto it = _classes.find(ci->vtableRoot);
    return (it != _classes.end()) ? basePathTo(ci, &it->second) : "";
}
#else
std::string CEmitter::vptrPrefix(ClassInfo*) { return ""; }
#endif

// Single definition of the process-global set-once runtime slots (external-linkage in the headers — see
// kama_runtime.h / kama_log.h). Their readers are `static inline` and inlined into every TU, while the
// writer runs only here, so a per-TU `static` would let a slot set in one TU be read as empty in another.
// The entry TU is the one, program-wide place to define them — and a `--shared` module, which has no
// `main`, defines them in its first unit (emitProgram / emit): before that a module with any panic path
// at all failed to LINK, `kama_panic_hook` undefined, which is how `tests/support/expose_shared_check.sh`
// sat broken from 0.9.162 until tools/check-expose-shared.sh started running it. The panic hook and argv
// are hosted-only (the headers declare them under the same guard; on embedded the panic path is the weak
// `kama_panic_handler` and there is no argv); the log sink is declared unconditionally (present on
// embedded too), emitted only when the program imports std::log. The `@onPanic` recovery slot: per
// thread, one definition, declared `extern` in the runtime header under the same KAMA_ONPANIC the TU
// preamble defines — so a program with no region defines nothing.
void CEmitter::emitRuntimeSlotDefinitions()
{
    *_out << "#if defined(KAMA_ONPANIC)\n"
          << "KAMA_ISOLATE_LOCAL kama_recover_t* kama_recover_top = 0;\n"
          << "#endif\n";
    *_out << "#if !defined(KAMA_TARGET_EMBEDDED)\n"
          << "void (*kama_panic_hook)(void) = 0;\n"
          << "int kama_in_panic_hook = 0;\n"
          << "int kama_argc = 0;\n"
          << "char** kama_argv = 0;\n"
          << "#endif\n";
    if (externsHeader("kama_log.h"))
        *_out << "kama_log_sink_fn kama_log_slot = 0;\n";
    // `@globalAllocator`: THE heap — one object for the whole process, so one definition, here. Zero bytes (the
    // module-static no-initializer rule; there is no hook to construct it before `main`), and not hosted-only: an
    // MCU is the first program that wants one. The funnel reaches the pool through these two entries, which are
    // also what the no-heap walk hangs every funnel use on (buildCallGraph). A malformed declaration is refused
    // by checkGlobalAllocator, which runs before any C is compiled — so a missing member emits nothing here.
    if (!_globalAllocator.empty()) {
        const ClassInfo& gci = _classes[_globalAllocator];
        auto a = gci.methods.find("allocate"), d = gci.methods.find("deallocate");
        if (a != gci.methods.end() && d != gci.methods.end())
            *_out << _globalAllocator << " kama_global_allocator = {0};\n"
                  << "void* kama__global_allocate(size_t n, size_t align) {\n"
                  << "    Optional_UnsafePtr o = " << a->second.cName << "(&kama_global_allocator, n, align);\n"
                  << "    return o.tag == Optional_UnsafePtr_Some ? o.u.Some.value : 0;\n"
                  << "}\n"
                  << "void kama__global_deallocate(void* p, size_t n, size_t align) {\n"
                  << "    " << d->second.cName << "(&kama_global_allocator, p, n, align);\n"
                  << "}\n";
    }
    // The detached-child reaper's park (kama_os.h, POSIX branch) — same one-definition rule: its
    // accessors are `static inline`, so a per-TU `static` park would defeat the cross-TU sweep.
    if (externsHeader("kama_os.h"))
        *_out << "#if !defined(_WIN32)\n"
              << "int* kama_reap_pids = 0;\n"
              << "size_t kama_reap_len = 0;\n"
              << "size_t kama_reap_cap = 0;\n"
              << "int kama_reap_lock = 0;\n"
              << "#endif\n";
    *_out << "\n";
}

bool CEmitter::isExtern(FunctionDeclarationNode* fn)
{
    return fn && fn->modifier && fn->modifier->value && *fn->modifier->value == "extern";
}

// `expose fn` — the kama→host boundary. It HAS a body and gets `KAMA_EXPORT` linkage, under the symbol
// `exposedSymbol` names (or its `@linkName`).
bool CEmitter::isExposed(FunctionDeclarationNode* fn)
{
    return fn && fn->modifier && fn->modifier->value && *fn->modifier->value == "expose";
}

// The C symbol a host links an exposed name against: its module path joined with `_`, then the name —
// `twomodname::alpha::tick` is `twomodname_alpha_tick`. C has one flat namespace and kama's modules exist to
// keep names apart, so the module travels into the symbol; a bare `tick` collided across modules and with
// libc (`open`, measured). A loose file is in no module, so its file name stands in, as it does for the
// file-private scope. `_` rather than kama's internal `__`, which C++ reserves; the join is not injective
// (`a_b::c` and `a::b_c`), so collectSignatures refuses two names that meet. `@linkName` overrides it.
std::string CEmitter::exposedSymbol(const std::string& name) const
{
    return hostQualified(_nsCtx.module, _nsCtx.unitPath.empty() ? _collectingUnitPath : _nsCtx.unitPath, name);
}

// The one qualification rule, shared by a symbol and by a type name in the generated host header.
std::string CEmitter::hostQualified(const std::string& module, const std::string& unitPath, const std::string& name)
{
    std::string prefix;
    if (!module.empty()) {
        for (size_t i = 0; i < module.size(); ++i) {
            if (module.compare(i, 2, "::") == 0) { prefix += '_'; ++i; continue; }
            char c = module[i];
            prefix += (std::isalnum((unsigned char)c) || c == '_') ? c : '_';
        }
    } else if (!unitPath.empty()) {
        prefix = privateScopeFor(unitPath).substr(2);
    }
    return prefix.empty() ? name : prefix + "_" + name;
}

// ---- The host header (KR-52) ---------------------------------------------------------------------------
//
// `kama build` writes `<project>.h` beside its output whenever the program exposes a function: the C a host
// includes to call it, generated from the same tables the definitions were emitted from, so the two cannot
// drift. Hand-written prototypes were the alternative, and nothing checked them.
//
// It is a SEPARATE translation of each C type, not the internal header's spelling: the internal header needs
// `kama_runtime.h` and names types the way kama mangles them (`_Fprobe__World`), neither of which a host can
// use. So every type an exposed signature reaches is re-spelled for the host —
//   - a C primitive stays itself, and `kama_cchar` is `char`;
//   - a `type extern value` keeps its C name, and the header includes what its declaring file `extern`s;
//   - a kama type of a module takes the same qualification as a symbol (`geo::Vec2` -> `geo_Vec2`), and is
//     OPAQUE — kama stays free to change it — unless it is a layout kama promises: a `type expose value`
//     (its marker IS the promise), `View`/`ConstView`, or an intrinsic `InlineArray`/`Simd`, each written out
//     from its real fields. The crossing rule already keeps any other type from crossing by value, so opaque
//     only ever meets a pointer. An intrinsic has no module, so it is prefixed `kama_`;
//   - a payload-less enum and a `fnptr` are re-declared in host terms.
// Struct TAGS never reach the linker, which is what makes a different spelling of the same layout sound.
namespace {
bool isHostPrimitiveCType(const std::string& t)
{
    static const std::set<std::string> prims = {
        "void", "bool", "char", "float", "double", "size_t", "ptrdiff_t",
        "int8_t", "int16_t", "int32_t", "int64_t", "uint8_t", "uint16_t", "uint32_t", "uint64_t" };
    return prims.count(t) > 0;
}
}

struct CEmitter::HostHeader {
    std::vector<std::string>           includes;   // as written in `extern "…";`, deduped, in first-use order
    std::ostringstream                 decls;      // typedefs, each after what it names
    std::set<std::string>              declared;   // internal C types already translated
    std::map<std::string, std::string> owner;      // host name -> the internal C type that claimed it
    std::string                        err;
};

std::string CEmitter::hostTypeName(HostHeader& h, const std::string& internal, const std::string& declFile)
{
    std::string module, unit;
    for (auto& kv : _unitCtx) {
        const NsCtx& c = kv.second;
        if (declFile.empty() || c.unitPath != declFile) continue;
        std::string bare;
        for (const std::string* sc : { &c.privScope, &c.scope })
            if (!sc->empty() && internal.compare(0, sc->size() + 2, *sc + "__") == 0) { bare = internal.substr(sc->size() + 2); break; }
        if (!bare.empty()) { module = c.module; unit = c.unitPath; std::string n = hostQualified(module, unit, bare);
            // An instance's suffix spells its arguments with kama's internal `__` (`View_geo__Vec2`), which C++
            // reserves; the host gets `_`, and the collision check below catches the join it makes ambiguous.
            for (size_t at; (at = n.find("__")) != std::string::npos; ) n.erase(at, 1);
            auto claimed = h.owner.emplace(n, internal);
            if (!claimed.second && claimed.first->second != internal && h.err.empty())
                h.err = "`" + demangleForDisplay(internal) + "` and `" + demangleForDisplay(claimed.first->second)
                      + "` would both be `" + n + "` in the host header — rename one";
            return n; }
    }
    std::string n = "kama_" + internal;   // compiler-owned: an intrinsic or a prelude type, in no module
    for (size_t at; (at = n.find("__")) != std::string::npos; ) n.erase(at, 1);
    h.owner.emplace(n, internal);
    return n;
}

std::string CEmitter::hostCType(HostHeader& h, const std::string& ct)
{
    size_t cut = ct.find_first_of(" *");
    const std::string base = ct.substr(0, cut);
    const std::string rest = cut == std::string::npos ? std::string() : ct.substr(cut);
    return hostBaseType(h, base) + rest;
}

std::string CEmitter::hostBaseType(HostHeader& h, const std::string& base)
{
    if (isHostPrimitiveCType(base)) return base;
    if (base == "kama_cchar") return "char";

    auto addIncludes = [&](const std::string& declFile) {
        for (auto& kv : _unitCtx) {
            const CompilationUnit* u = kv.first;
            if (!u || !u->name || *u->name != declFile || !u->codeDeclarationList) continue;
            for (auto& d : *u->codeDeclarationList)
                if (auto* inc = dynamic_cast<IncludeNode*>(d.get()))
                    if (inc->header && std::find(h.includes.begin(), h.includes.end(), *inc->header) == h.includes.end())
                        h.includes.push_back(*inc->header);
        }
    };

    auto sit = _sigs.find(base);
    if (sit != _sigs.end()) {
        const SigInfo si = sit->second;
        const std::string name = hostTypeName(h, base, si.declFile);
        if (h.declared.insert(base).second) {
            std::string line = "typedef " + hostCType(h, si.retCType) + " (*" + name + ")(";
            if (si.params.empty()) line += "void";
            for (size_t i = 0; i < si.params.size(); ++i) {
                const ParamSig& p = si.params[i];
                bool constPtr = p.isConst && !p.className.empty() && p.className.back() == '*' && !isConstRawCType(p.className);
                line += std::string(i ? ", " : "") + (constPtr ? "const " : "") + hostCType(h, p.className)
                      + (p.byRef ? "*" : "") + (p.name.empty() ? "" : " " + p.name);
            }
            h.decls << line << ");\n";
        }
        return name;
    }

    auto eit = _enums.find(base);
    if (eit != _enums.end()) {
        const EnumInfo& ei = eit->second;
        if (ei.isExtern) { addIncludes(ei.declFile); return base; }   // the header's own enum, by its own name
        // A `type expose enum` (the crossing rule admits no other): kama's values, every one spelled, published
        // under the same qualification as a symbol unless `@linkName` fixed the name.
        const std::string name = ei.hostName.empty() ? hostTypeName(h, base, ei.declFile) : ei.hostName;
        if (!ei.hostName.empty()) {
            auto claimed = h.owner.emplace(name, base);
            if (!claimed.second && claimed.first->second != base && h.err.empty())
                h.err = "`" + demangleForDisplay(base) + "` and `" + demangleForDisplay(claimed.first->second)
                      + "` would both be `" + name + "` in the host header — rename one";
        }
        if (h.declared.insert(base).second) {
            h.decls << "typedef " << ei.underlyingCType << " " << name << ";\nenum {";
            for (size_t i = 0; i < ei.members.size(); ++i)
                h.decls << (i ? ", " : " ") << name << "_" << ei.members[i].name << " = " << ei.members[i].folded;
            h.decls << " };\n";
        }
        return name;
    }

    auto cit = _classes.find(base);
    if (cit == _classes.end()) return base;   // a name a C header declares, passed through as `extern` does
    const ClassInfo& ci = cit->second;
    if (ci.isExternStruct) { addIncludes(ci.declFile); return base; }

    if (ci.isExposeStruct) {
        const std::string name = ci.hostName.empty() ? hostTypeName(h, base, ci.declFile) : ci.hostName;
        if (!ci.hostName.empty()) {
            auto claimed = h.owner.emplace(name, base);
            if (!claimed.second && claimed.first->second != base && h.err.empty())
                h.err = "`" + demangleForDisplay(base) + "` and `" + demangleForDisplay(claimed.first->second)
                      + "` would both be `" + name + "` in the host header — rename one";
        }
        if (h.declared.insert(base).second) {
            // Published even when reached through a pointer: the layout is the promise the marker makes.
            std::string body;
            for (const FieldInfo& f : ci.fields) body += " " + hostCType(h, fieldCType(ci.name, f)) + " " + f.name + ";";
            h.decls << "typedef struct " << name << " {" << body << " }" << layoutAttrSuffix(ci) << " " << name << ";\n";
        }
        return name;
    }
    auto gi = _genericTypeInsts.find(base);
    std::string declFile = ci.declFile;
    if (gi != _genericTypeInsts.end()) {   // an instance is named in its TEMPLATE's module: `std_collections_View_int32`
        auto tpl = _genericTypes.find(gi->second.templateKey);
        declFile = tpl != _genericTypes.end() ? tpl->second.declFile : std::string();
    }
    const std::string name = hostTypeName(h, base, declFile);
    if (!h.declared.insert(base).second) return name;
    if (ci.isIntrinsicColl && _collections.count(base)) {
        const CollectionInfo& info = _collections[base];
        if (info.kind == CollKind::Fixed) {
            const std::string elem = hostCType(h, info.elemCType);
            h.decls << "typedef struct " << name << " { " << elem << " v[" << info.constValue << "]; } " << name << ";\n";
            return name;
        }
        if (isValueVectorKind(info.kind)) {
            const std::string elem = hostCType(h, info.elemCType);
            h.decls << "typedef " << elem << " " << name << " __attribute__((vector_size(sizeof(" << elem << ") * "
                    << info.constValue << ")));\n";
            return name;
        }
    }
    const bool isView = gi != _genericTypeInsts.end()
        && (gi->second.templateKey == "std__collections__View" || gi->second.templateKey == "std__collections__ConstView");
    if (isView) {
        // A layout kama promises: written from the struct's own fields, each re-spelled for the host.
        std::string body;
        for (const FieldInfo& f : ci.fields) body += " " + hostCType(h, fieldCType(ci.name, f)) + " " + f.name + ";";
        h.decls << "typedef struct " << name << " {" << body << " } " << name << ";\n";
        return name;
    }
    h.decls << "typedef struct " << name << " " << name << ";\n";   // reached only through a pointer: opaque
    return name;
}

std::string CEmitter::writeHostHeader(std::ostream& out, const std::string& fileName, bool& wrote)
{
    wrote = false;
    HostHeader h;
    std::ostringstream protos;
    std::map<std::string, const FuncSig*> bySymbol;   // one prototype per exported symbol, in symbol order
    for (auto& kv : _funcs)
        if (kv.second.node && isExposed(kv.second.node)) bySymbol[symbolOf(kv.second)] = &kv.second;
    if (bySymbol.empty()) return "";
    for (auto& kv : bySymbol) {
        const FuncSig& s = *kv.second;
        protos << hostCType(h, s.retCType) << " " << kv.first << "(";
        if (s.params.empty()) protos << "void";
        for (size_t i = 0; i < s.params.size(); ++i) {
            const ParamSig& p = s.params[i];
            bool constPtr = p.isConst && !p.className.empty() && p.className.back() == '*' && !isConstRawCType(p.className);
            bool hwPtr    = p.isHardware && !p.className.empty() && p.className.back() == '*';
            protos << (i ? ", " : "") << (constPtr ? "const " : "") << (hwPtr ? "volatile " : "")
                   << hostCType(h, p.className) << (p.byRef ? "*" : "") << (p.name.empty() ? "" : " " + p.name);
        }
        protos << ");\n";
    }
    if (!h.err.empty()) return h.err;

    std::string guard = "KAMA_HOST_";
    for (char c : fileName) guard += std::isalnum((unsigned char)c) ? (char)std::toupper((unsigned char)c) : '_';
    out << "/* " << fileName << " — generated by kama. Do not edit.\n"
        << "   The C interface to this program's `expose fn`s; regenerated by every build. */\n"
        << "#ifndef " << guard << "\n#define " << guard << "\n"
        << "#include <stdbool.h>\n#include <stddef.h>\n#include <stdint.h>\n";
    for (const std::string& inc : h.includes)
        out << "#include " << (inc[0] == '<' ? inc : "\"" + inc + "\"") << "\n";
    out << "\n#ifdef __cplusplus\nextern \"C\" {\n#endif\n\n";
    const std::string d = h.decls.str();
    if (!d.empty()) out << d << "\n";
    out << protos.str() << "\n#ifdef __cplusplus\n}\n#endif\n#endif\n";
    wrote = true;
    return "";
}

// `@linkName("sym")` on an `extern fn` or an `expose fn`: the C symbol, validated — Rust's `#[link_name]`
// and `#[export_name]` in one attribute, named for the concept rather than the backend (the 2.0 bytecode
// VM has no C names). The shape rule is C's identifier, deliberately NOT `kamaIsIdentifier`: that one
// also rejects kama's keywords, and a C symbol spelled like one (`type`, `match`) is precisely what this
// attribute exists to bind. A C keyword is refused because no C symbol can be spelled as one; the
// wrapper that emits the call would not compile. Empty when the attribute is absent or invalid (the
// diagnostic has been emitted); read once, at collection, so an invalid name is reported once.
std::string CEmitter::linkNameOf(FunctionDeclarationNode* fn)
{
    return fn ? linkNameOf(fn->attributes, fn->line) : std::string();
}

std::string CEmitter::linkNameOf(const SharedAttributeList& attrs, int line)
{
    if (!attrs) return "";
    for (auto& at : *attrs) {
        if (!at || !at->name || *at->name != "linkName") continue;
        std::string sym;
        if (at->args && at->args->size() == 1) {
            auto& a = (*at->args)[0];
            if (a && !a->name && a->expression)
                if (auto* s = dynamic_cast<StringNode*>(a->expression.get()))
                    if (s->value) sym = *s->value;
        }
        if (sym.empty()) {
            unsupported("`@linkName(\"...\")` requires exactly one string-literal symbol name", line);
            return "";
        }
        bool shape = isalpha((unsigned char)sym[0]) || sym[0] == '_';
        for (char ch : sym) if (!(isalnum((unsigned char)ch) || ch == '_')) shape = false;
        if (!shape) {
            unsupported(("`@linkName(\"" + sym + "\")` is not a C symbol — a symbol is letters, digits and "
                         "`_`, and does not start with a digit").c_str(), line);
            return "";
        }
        if (cIsReservedWord(sym.c_str())) {
            unsupported(("`@linkName(\"" + sym + "\")` names a C keyword, and no C symbol can be spelled as "
                         "one").c_str(), line);
            return "";
        }
        return sym;
    }
    return "";
}

// Emit `cName(leadArg, <args reordered to declared param order>)`.
//
// NOTE: arguments are emitted in declared (param) order, which can differ from
// source order. With side-effecting args this changes evaluation order; a
// temp-hoisting pass (plan risk #3) is a later refinement.
// The C type of a primitive LITERAL rvalue ("" if not a literal). Used to materialize a bare literal
// into a temp when it's passed to a `ref` parameter (which needs an addressable lvalue).
static std::string litRvalueCType(ASTNode* n)
{
    if (dynamic_cast<Int8Node*>(n))    return "int8_t";
    if (dynamic_cast<Int16Node*>(n))   return "int16_t";
    if (dynamic_cast<Int32Node*>(n))   return "int32_t";
    if (dynamic_cast<Int64Node*>(n))   return "int64_t";
    if (dynamic_cast<UInt8Node*>(n))   return "uint8_t";
    if (dynamic_cast<UInt16Node*>(n))  return "uint16_t";
    if (dynamic_cast<UInt32Node*>(n))  return "uint32_t";
    if (dynamic_cast<UInt64Node*>(n))  return "uint64_t";
    if (dynamic_cast<CharNode*>(n))    return "uint32_t";   // `char` = a uint32-backed codepoint
    if (dynamic_cast<Float32Node*>(n)) return "float";
    if (dynamic_cast<Float64Node*>(n)) return "double";
    if (dynamic_cast<BooleanNode*>(n)) return "bool";
    return "";
}

// Field-wise init of an extern (C-POD) struct from NAMED args, e.g. `c.r = 1.0; c.g = 0.5;`. The
// struct is already `= {0}`, so only provided fields are set (unset -> zero). An unknown field or a
// positional arg is a clean compile error. Returns "" for no args. Extern structs are POD (no
// ctor/dtor) -> no move/drop; the caller emits/hoists the returned string.
// ---- `@generate(of|zero)` bag ctors (construction-model M6) ---------------------------------------------
// A transparent `value` (all public fields — a data bag) may derive `of`/`zero` named ctors instead of
// hand-writing them. Both are infallible static factories returning the value by C-value; registered in
// collectClasses and dispatched through the ordinary dot-on-type ctor path.

bool CEmitter::isTransparentValue(const ClassInfo& ci) const
{
    if (ci.kind != TypeKind::Value) return false;
    for (auto& f : ci.fields) if (f.visibility != Visibility::Public) return false;
    return true;
}

// The shared C signature `V V__of(t1 f1, …)` / `V V__zero(void)` — no `static inline`, no trailing `;`/body.
std::string CEmitter::bagCtorSig(const ClassInfo& ci, const std::string& which)
{
    std::string sig = ci.name + " " + ci.name + "__" + which + "(";
    bool first = true;
    if (which == "of")
        for (auto& f : ci.fields) {
            if (!first) sig += ", ";
            first = false;
            sig += cType(f.type) + " " + f.name;
        }
    if (first) sig += "void";   // `zero()`, or an (edge-case) field-less `of`
    return sig + ")";
}

// `V V__of(…) { return (V){ .f1 = f1, … }; }` / `V V__zero(void) { return (V){0}; }`.
void CEmitter::emitBagCtorBody(ClassInfo& ci, const std::string& which)
{
    *_out << (_emitStaticClass ? "static inline " : "") << bagCtorSig(ci, which) << "\n{\n";
    indent(1);
    if (which == "of" && !ci.fields.empty()) {
        *_out << "return (" << ci.name << "){ ";
        bool first = true;
        for (auto& f : ci.fields) {
            if (!first) *_out << ", ";
            first = false;
            *_out << "." << f.name << " = " << f.name;
        }
        *_out << " };\n";
    } else {
        *_out << "return (" << ci.name << "){0};\n";   // `zero`, or a field-less `of`
    }
    *_out << "}\n\n";
}

// The SOURCE spelling of an inline `Type(...)` call, for a diagnostic — falls back to the mangled name.
static std::string ctorDisp(const InvocationNode* iv, const std::string& fallback)
{
    return (iv && iv->identifier && iv->identifier->value) ? *iv->identifier->value : fallback;
}

std::string CEmitter::emitReorderedCall(const std::string& cName, const std::string& leadArg,
                                        const std::vector<ParamSig>& params,
                                        SharedArgumentList args, int srcLine,
                                        const std::string& trailingArg)
{
    // `cName` is a plain C identifier for a STATICALLY resolved callee, and an expression for the four
    // indirect forms (`(*f)`, a bindable's `((T)x.fn)`, `(r).vtbl->m`, `vptr->m`). The direct ones become
    // call-graph edges because they are in the C (buildCallGraph); the indirect ones are gated at their own
    // sites, where the member being dispatched is still in hand.
    std::map<std::string, ArgumentNode*> byName;
    size_t named = 0;
    if (args)
        for (auto& a : *args)
            if (a->name && a->name->value) { byName[*a->name->value] = a.get(); named++; }

    // Step 5: named arguments ARE kama's calling convention — validate them so a typo or
    // a duplicate can't silently do the wrong thing. (Missing args are caught per-param below.)
    if (named != byName.size())
        unsupported("duplicate named argument in call", srcLine);   // map collapsed a repeat
    {
        std::set<std::string> paramNames;
        for (auto& p : params) paramNames.insert(p.name);
        for (auto& kv : byName)
            if (!paramNames.count(kv.first))
                unsupported(("unknown argument name '" + kv.first + "' in call").c_str(), srcLine);
    }

    // Mutable-borrow uniqueness. Two `ref`/`out` arguments naming overlapping places hand the callee two
    // mutable aliases to one object, so anything it does through one can invalidate what it holds through
    // the other — the classic `merge(dst: xs, src: xs)`. Rust never has to check this because `&mut` is
    // unique by construction; kama's `ref` is not, so the check has to live at the call site. It is the
    // SAME prefix test the view model uses for `borrow`: `f(a: x, b: ref x.lo)` conflicts because `{x}` is
    // a prefix of `{x, lo}`. `out` is `byRef && !isConst`, so a fill overlapping a borrow is caught too.
    std::vector<std::vector<std::string>> mutableArgPlaces;
    auto checkArgOverlap = [&](const std::vector<std::string>& path, const std::string& pname) {
        if (path.empty()) return;                    // not a nameable place — nothing to compare
        for (auto& seen : mutableArgPlaces)
            if (placesConflict(seen, path))
                unsupported(("`" + placeText(path) + "` is passed as two overlapping mutable arguments in "
                             "one call (`" + pname + "` aliases an earlier `ref`/`out` argument) — the "
                             "callee would hold two mutable borrows of the same object; pass distinct "
                             "places, or read one into a local first").c_str(), srcLine);
        mutableArgPlaces.push_back(path);
    };
    // A VIEW argument is a borrow too, and one whose root the test above cannot see: `bad(d: ref d, v:
    // d.view())` passes a by-value parameter, so it never reached `checkArgOverlap`, and `placePath` of an
    // invocation is empty anyway. Rooted through its receiver it becomes an ordinary place and the same
    // prefix test applies — the callee must not be handed a window over a container it may also grow.
    // Compared in BOTH directions so argument order cannot hide it.
    std::vector<std::pair<std::vector<std::string>, std::string>> viewArgRoots;   // root -> param name
    auto viewArgConflict = [&](const std::vector<std::string>& a, const std::string& viewName,
                               const std::string& mutName) {
        unsupported(("`" + placeText(a) + "` is borrowed by the view argument `" + viewName + "` and also "
                     "passed as a mutable `ref`/`out` argument (`" + mutName + "`) in the same call — the "
                     "callee holds a window over storage it may grow, and growing it leaves that window "
                     "dangling. Pass the view alone and let the callee mint what it needs, or copy into an "
                     "owning collection").c_str(), srcLine);
    };
    auto checkViewArgOverlap = [&](const std::vector<std::string>& root, const std::string& pname) {
        if (root.empty()) return;
        for (auto& seen : mutableArgPlaces)
            if (placesConflict(seen, root)) viewArgConflict(root, pname, "an earlier argument");
        viewArgRoots.push_back({ root, pname });
    };

    std::string s = cName + "(";
    bool first = true;
    if (!leadArg.empty()) { s += leadArg; first = false; }
    for (auto& p : params) {
        if (!first) s += ", ";
        first = false;
        auto f = byName.find(p.name);
        if (f == byName.end()) { unsupported("missing argument in call", srcLine); s += "0"; continue; }
        // M6 A2: the label is a REFERENCE to the parameter it just matched, so renaming the parameter
        // rewrites the call sites too. This is the single named-argument matcher for every call form
        // (free fns, methods, virtual dispatch, ctors, bound closures, operators — 29 call sites), so one
        // line covers them all. A no-op in build mode, and free of duplicates: buildPositions dedups by
        // IdentifierNode*, so a generic body re-emitted per instantiation records the same label once.
        recordNodeRef(f->second->name.get(), p.declSite);
        // unwrap a give/copy hand-off marker. The inner value is what we emit;
        // the marker (give=move / copy=retain) only matters for a smart pointer passed
        // BY VALUE (ownership transfer) — it's meaningless on a borrow.
        SharedExpression argExpr = f->second->expression;
        // `out` is a REQUIRED call-site marker, not decoration. `out` and `ref` lower to the same `T*`,
        // so without the marker a reader (and the caller's definite-assignment analysis) cannot tell a
        // borrow from a fill — which is exactly what made `out` a silent alias for `ref` before. The
        // `ref` marker stays optional: a borrow reads AND writes an already-live value, so nothing is
        // riding on it. Marking `out` where the parameter is not one is the mirror error.
        {
            const std::string* am = (f->second->modifier && f->second->modifier->value)
                                  ? f->second->modifier->value.get() : nullptr;
            bool markedOut = am && *am == "out";
            if (p.isOut && !markedOut)
                unsupported(("`" + p.name + "` is an `out` parameter — the call site must say so: `"
                             + p.name + ": out <variable>`" + (am ? " (not `" + *am + "`)" : "")).c_str(), srcLine);
            else if (!p.isOut && markedOut)
                unsupported(("`" + p.name + "` is not an `out` parameter — drop the `out` marker"
                             + std::string(p.byRef ? " (it is a `ref` borrow)" : "")).c_str(), srcLine);
        }
        int handoff = 0;   // 0 none, 1 give, 2 copy
        if (auto* h = dynamic_cast<HandoffNode*>(argExpr.get())) { handoff = h->isGive ? 1 : 2; argExpr = h->value; }
        // A callback crossing to C must state which thread it runs on — see checkForeignCrossing. Here
        // rather than at the extern call sites for the same reason the call EDGE is recorded here: this
        // is the one funnel every resolved call passes through, and a check spread over the sites that
        // reach it fails open the moment one is missed.
        checkForeignCrossing(cName, p, argExpr, srcLine);
        // The kind rule in ARGUMENT position. `className` already IS the C type for every DECLARED
        // parameter (`paramSigsOf` fills it with `cType`, primitives included), so the only signatures
        // it could not answer for were the SYNTHESIZED intrinsics, which name no type at all. Those
        // carry `kindCType` instead — see the ParamSig field, which explains why it cannot be the
        // same field.
        //
        // A CONTRACT param is exempt for the same reason a contract destination is: `hashVia(h: 22)` widens
        // a primitive into a fat pointer, so it accepts every kind by design.
        const std::string& pKindCType = p.kindCType.empty() ? p.className : p.kindCType;
        // A `const UnsafePtr<T>` parameter lowers to `const T*` and so accepts the read-only pointer; a
        // plain `UnsafePtr<T>` one is a writable sink.
        if (!p.isConst) rejectConstPtrWiden(pKindCType, argExpr, ("argument `" + p.name + "`").c_str(), srcLine);
        if (!pKindCType.empty() && !isInterface(pKindCType))
            rejectValueKindMismatch(pKindCType, argExpr,
                                    ("argument `" + p.name + "`").c_str(), srcLine);
        // ...and the check that belongs in the branch the line above skips. A contract param is exempt
        // from the KIND rule because a contract admits every kind — but nothing was put in its place, so
        // the one position that skipped the kind check checked nothing at all, and a non-conforming
        // argument reached clang as `<Concrete>__as_<Contract>: undeclared identifier`.
        else if (!pKindCType.empty())
            rejectContractNonConformance(pKindCType, argExpr,
                                         ("argument `" + p.name + "`").c_str(), srcLine);
        // Mutable-borrow uniqueness — see `checkArgOverlap` above. Read `byRef && !isConst` off the RESOLVED
        // callee signature, never the call-site marker: the `ref` marker is optional (only `out` is
        // mandatory), so the marker would miss the commonest spelling.
        if (p.byRef && !p.isConst) {
            std::vector<std::string> mp = placePath(argExpr);
            checkArgOverlap(mp, p.name);
            if (!mp.empty())
                for (auto& vr : viewArgRoots)     // the other direction: the view argument came first
                    if (placesConflict(vr.first, mp)) viewArgConflict(vr.first, vr.second, p.name);
        } else if (!p.byRef && isViewCType(p.className)) {
            checkViewArgOverlap(viewRootPlace(argExpr), p.name);
        }
        // inline constructor in argument position — `f(x: Counter(start: 5))`. A ctor lowers to
        // `Cls__ctor(&dest, …)`, which needs an lvalue destination, so materialize a HOISTED temp
        // (declared on its own line before this statement — pure ISO C, no `({ … })`) and pass it by
        // value. Only for a by-value param of the exact class in a hoist-enabled statement context;
        // otherwise fall through to the normal path (which rejects an unsupported position cleanly).
        std::string val;
        bool valHoisted = false;   // an earlier branch already materialized `val` into an addressable temp
        // ...and of those, the ones that materialized a TEMPORARY rather than found a real place. The
        // distinction is the whole of the rule below, and `valHoisted` cannot carry it: the element-access
        // arm sets that for `ref a[i]`, which IS a place the callee may legitimately write through.
        bool argIsTemp = false;
        InvocationNode* ctorIv = dynamic_cast<InvocationNode*>(argExpr.get());
        std::string ctorCls;
        if (ctorIv && ctorIv->identifier && ctorIv->identifier->value) {
            std::string rn = resolveUserName(*ctorIv->identifier->value, ctorIv->identifier->qualifier);
            if (isClass(rn) && _classes.count(rn)) ctorCls = rn;
            // `f(b: Box(v: 7))` — the ctor names template `Box`; the target param is instance `Box_int32`.
            else { auto g = _genericTypeInstOf.find(p.className);
                   if (g != _genericTypeInstOf.end() && g->second == rn) ctorCls = p.className; }
        }
        // A dot-on-type ctor call arg (`f(a: Cell.make(…))`) constructs its type just like a nameless inline
        // ctor, so it must materialize the same way (by-value contract upcast, `ref` borrow). But it's a
        // FACTORY returning by value, so it emits a MOVE (`T t = T__make(…)`), not `T__ctor(&t,…)`. #M8d.2
        bool ctorIsFactory = false;
        if (ctorCls.empty()) { std::string dt = dotCtorFactoryClass(argExpr);
            if (!dt.empty()) { ctorCls = dt; ctorIsFactory = true; } }
        // ...and one on a generic TEMPLATE whose instance this parameter names (`take(b: Box.of(v: 4))` at a
        // `Box<int64>`): the parameter IS the destination, exactly as a declaration's type is, so it pins the
        // instance before the ctor's own arguments get a say — `4` is then an `int64`, and `Box.empty()`,
        // which has no argument to infer from, resolves at all (KR-15).
        std::string genericCtorDest;
        if (ctorCls.empty())
            if (auto* div = dynamic_cast<InvocationNode*>(argExpr.get()))
                if (auto* dma = dynamic_cast<MemberAccessNode*>(div->expression.get())) {
                    std::string dt;
                    auto of = _genericTypeInstOf.find(p.className);
                    if (of != _genericTypeInstOf.end() && isTypeReceiver(dma, dt) && of->second == dt
                        && dma->identifier && dma->identifier->value) {
                        CtorInfo* ct = _classes[p.className].ctorByName(*dma->identifier->value);
                        if (ct && !ct->isFallible) { ctorCls = p.className; ctorIsFactory = true; genericCtorDest = p.className; }
                    }
                }
        ScopedStr _gcd(_variantTargetType, genericCtorDest.empty() ? _variantTargetType : genericCtorDest);
        // A value-producing RHS in argument position that needs its type from context: an inline variant
        // construction (`f(o: Optional::Some(…))` / `…::None`) or a value-producing `match` (`f(x: match(…))`).
        // Thread the PARAM's C type as the target so the union instance / match result resolves, exactly as
        // the initializer / assignment / return / arm positions do. (An ordinary arg leaves these unset.)
        bool argIsVariant = false;
        {
            SharedStringList vq;
            if (ctorIv) { if (ctorIv->identifier) vq = ctorIv->identifier->qualifier; }
            else if (auto* id = dynamic_cast<IdentifierNode*>(argExpr.get())) vq = id->qualifier;
            if (vq && !vq->empty()) {
                auto q = std::make_shared<StringList>();
                for (size_t i = 0; i + 1 < vq->size(); ++i) q->push_back((*vq)[i]);
                std::string en = resolveUserName(*vq->back(), q);
                argIsVariant = (_classes.count(en) && _classes[en].isVariant) || _genericTypeParams.count(en);
            }
        }
        bool argIsMatch = needsTargetType(argExpr.get());   // incl. a ternary yielding a match / array literal
        // An inline ctor is a temporary rvalue. To an INTERFACE `ref`/`out` param it can't be a fat pointer
        // inline — reject (bind first). To a concrete-class param (by value OR `ref`) it's materialized into
        // a hoisted temp below, so `f(Point(1, 2))` / `m.get(key: Point(1, 2))` work.
        if (!ctorCls.empty() && !_classes[ctorCls].isIntrinsicColl && p.byRef && isInterface(p.className))
            unsupported("cannot pass an inline constructor to a contract `ref`/`out` parameter — "
                        "bind it to a local first, then pass that", srcLine);
        // A marker on a FRESH inline ctor (`f(x: give Box(…))`) is meaningless — a fresh rvalue is consumed
        // in place. Reject cleanly, matching the init/assignment positions (without this it skips the
        // materialization below and falls to a confusing "unknown function" reject).
        if (handoff != 0 && !ctorCls.empty())
            unsupported("`give`/`copy` apply to a named value — a fresh `new`/constructor/call result needs "
                        "no marker", srcLine);
        // Does the inline ctor's concrete class implement the (by-value) contract param? (A3 — pass it as a
        // fat-pointer borrow of a materialized temp.)
        bool ctorImplementsParam = false;
        if (!ctorCls.empty() && isInterface(p.className))
            for (auto& i : _classes[ctorCls].interfaces) if (i == p.className) { ctorImplementsParam = true; break; }
        if (_hoistOK && handoff == 0 && !ctorCls.empty() && ctorCls == p.className
            && !isInterface(p.className) && !_classes[ctorCls].isIntrinsicColl) {
            std::string t = "__ctorarg" + std::to_string(_tempCounter++);
            if (ctorIsFactory) {
                // A named `ctor` factory returns by value — MOVE it into the temp (`T t = T__make(…)`).
                _hoisted.push_back(ctorCls + " " + t + " = " + emitExpression(argExpr) + ";");
                if (p.byRef && _classes[ctorCls].destructible) recordDestructibleLocal(t, ctorCls);
                val = t;
            } else {
                // A nameless `Type(args)` inline in argument position — no ctor to bind. Reject with the
                // context-aware advice; the degenerate temp keeps the throwaway C well-formed and
                // suppresses the caller's generic follow-on gate.
                rejectNamelessConstruction(_classes[ctorCls], ctorDisp(ctorIv, ctorCls), /*viaNew=*/false, srcLine);
                _hoisted.push_back(ctorCls + " " + t + " = {0};");
                val = t;
            }
            valHoisted = true;
            argIsTemp = true;   // a `__ctorarg` temp — see the temporary rule below
        } else if (_hoistOK && handoff == 0 && ctorImplementsParam && !p.byRef
                   && !_classes[ctorCls].isIntrinsicColl) {
            // A3 — an inline STACK ctor of a concrete that implements a BY-VALUE contract parameter
            // (`useShape(a: Square(3))` where `useShape(Shape a)`). Materialize it into a temp; the by-value
            // contract param is a BORROW (fat pointer {obj, vtbl}), so the CALLER owns the temp and drops it
            // at scope end — a single drop, sound for value and resource concretes alike. The `isInterface`
            // path below wraps `val` as the fat pointer. (`new` into a contract borrow stays a rule — it
            // would leak; `ref`/`out` needs a real interface lvalue to reseat — both handled elsewhere.)
            std::string t = "__ctorarg" + std::to_string(_tempCounter++);
            if (ctorIsFactory) {   // a named `ctor` factory returns by value — MOVE it into the temp
                _hoisted.push_back(ctorCls + " " + t + " = " + emitExpression(argExpr) + ";");
                if (_classes[ctorCls].destructible) recordDestructibleLocal(t, ctorCls);
            } else {   // nameless — no ctor to bind (see the sibling branch above)
                rejectNamelessConstruction(_classes[ctorCls], ctorDisp(ctorIv, ctorCls), /*viaNew=*/false, srcLine);
                _hoisted.push_back(ctorCls + " " + t + " = {0};");
            }
            val = t;
            valHoisted = true;
        } else if (dynamic_cast<ObjectCreationNode*>(argExpr.get())) {
            // an inline `new T(...)` argument — box it into a hoisted temp (malloc + ctor + adopt/vtbl),
            // passed BY VALUE so the callee owns and drops it (a fresh unaliased box, consumed once — not
            // registered destructible here). `give`/`copy` are meaningless on a fresh rvalue; a `ref`/`out`
            // or contract borrow has no stable address to reseat — bind to a local first (the language rule).
            if (handoff != 0)
                unsupported("`give`/`copy` apply to a named value — a fresh `new`/constructor/call result "
                            "needs no marker", srcLine);
            if (p.byRef || isInterface(p.className)) {
                unsupported("cannot pass an inline `new` to a `ref`/`out` or contract-borrow parameter — "
                            "bind it to a local first, then pass that", srcLine);
                val = "0";   // rejected — throwaway (compilation already failed); don't re-diagnose via the gate
            } else {
                std::string t = tryHoistInlineValue(argExpr, p.className, srcLine);
                val = t.empty() ? emitExpression(argExpr) : t;   // "" => not an owning target; emitExpression diagnoses
            }
            valHoisted = true;   // rejected (byRef) or boxed temp — never a bare rvalue for the ref hoist below
        } else if (isTryCast(argExpr.get()) && _hoistOK && !p.byRef) {
            // `f(x: try cast<int8>(v))` — the fallible conversion as an argument. Same treatment as the
            // inline `new` above and for the same reason: a statement form materialized into a hoisted
            // temp, here typed by the PARAMETER. A `ref`/`out` param wants an lvalue to reseat, so it
            // falls through to the ordinary path and gets that rule's diagnostic.
            std::string t = tryHoistInlineValue(argExpr, p.className, srcLine);
            val = t.empty() ? emitExpression(argExpr) : t;   // "" => no Optional param; emitExpression diagnoses
            valHoisted = true;
        } else if (p.byRef && dynamic_cast<ElementAccessNode*>(argExpr.get())) {
            // `ref a[i]` borrows the ELEMENT: emit it as a place (`*NAME__at(...)`) so the `&(...)`
            // below is the bounds-checked `T*` (index evaluated once), not the address of a by-value
            // `__get` rvalue. Folds to `NAME__at(&a, i)`.
            val = emitPlace(argExpr);
            valHoisted = true;   // an addressable place — `&(...)` below is already legal
        } else {
            // An owned-string rvalue argument to a string INTRINSIC (`kama_string__*`) is borrowed by the
            // callee (read-only — none of concat/equals/contains/... store it), so hoist it into a
            // scope-dtor'd temp and free it instead of leaking. Scoped to the borrow-only string
            // intrinsics: a general call may CONSUME a by-value string arg (e.g. `List.add` relocates it),
            // where freeing the caller's temp would double-free — there, bind to a local first.
            std::string st = (cName.rfind("kama_string__", 0) == 0) ? hoistStringTemp(argExpr) : std::string();
            // A `ref string` borrow of a string RVALUE has no address to take: `&(rvalue)` is illegal C
            // ("cannot take the address of an rvalue"). Materialize it into a scope-dtor'd temp so the
            // `&temp` below is legal — makes `f("literal")` / `f(a + b)` work for a `ref string` param.
            // The borrow is read-only and the temp frees at scope end; an addressable lvalue (a named
            // var / field / `this`) keeps its direct `&`. hoistStringTemp handles concat/call rvalues but
            // keeps a bare LITERAL on its normal path, so materialize the literal here too.
            if (st.empty() && p.byRef && _hoistOK && exprIsString(argExpr)) {
                st = hoistStringTemp(argExpr);
                if (st.empty() && dynamic_cast<StringNode*>(argExpr.get())) {
                    st = "__strtmp" + std::to_string(_tempCounter++);
                    _hoisted.push_back("kama_string " + st + " = " + emitExpression(argExpr) + ";");
                    recordDestructibleLocal(st, "kama_string");
                }
            }
            // A bare primitive LITERAL to a `ref`-primitive param (`m.get(key: 5)`) has no address —
            // materialize it into a temp so the `&temp` below is legal. No drop (a primitive owns nothing).
            //
            // The temp is the PARAMETER's storage, so it takes the PARAMETER's type. Typing it from the
            // LITERAL instead — which is what this arm did, and what the comment above it described as if
            // it were the design — was a SILENT WRONG ANSWER: a bare `2` is an `Int32Node`, so
            // `a.contains(item: 2)` on a `DynamicArray<int64>` emitted `int32_t __primtmp0 = 2;` and handed
            // `&__primtmp0` to a callee whose signature said `int64_t*`, which then read four bytes of
            // adjacent stack as the high half and answered false for a value the array held. C reports only
            // `-Wincompatible-pointer-types`, so nothing downstream stopped it.
            //
            // A literal is typed by its DESTINATION — SPEC's *Numeric conversions* (`int8 a = 100;`,
            // `float32 f = 3;`) — and every other position already honours that, which is why the by-value
            // spelling of the same call was fine. `pKindCType` is the destination, and it is the very value
            // `rejectValueKindMismatch` was checked against a screen up, so a literal that reaches here has
            // already been range-checked (`take(x: 300)` at a `const ref int8`) and kind-checked (an
            // integer at a `const ref char`) against it. The two NEIGHBOURING arms target-type the same
            // way: the string arm materializes a `kama_string`, and the variant/match arm sets
            // `_matchTargetCType` to the param's type before emitting.
            //
            // The guard is what `litRvalueCType` itself can produce, plus the two target-width types a
            // parameter can be and a literal cannot (`isize`/`usize` — the case the wasm leg hides, since
            // `ptrdiff_t` is 4 bytes there and the accident holds). Anything else — a contract parameter,
            // an unsubstituted `T` in a generic template — keeps the literal's own type rather than
            // spelling a class name as a temp.
            if (st.empty() && p.byRef && _hoistOK) {
                std::string lct = litRvalueCType(argExpr.get());
                if (!lct.empty()) {
                    if (cNumBits(pKindCType) || cNumTargetWidth(pKindCType) || pKindCType == "bool")
                        lct = pKindCType;
                    st = "__primtmp" + std::to_string(_tempCounter++);
                    _hoisted.push_back(lct + " " + st + " = " + emitExpression(argExpr) + ";");
                }
            }
            if (!st.empty()) argIsTemp = true;   // a `__strtmp`/`__primtmp` temp — see the check below
            if (st.empty() && (argIsVariant || argIsMatch) && !p.className.empty()) {
                // target-type the union instance / match result to the param's type, then emit
                std::string pmt = _matchTargetCType, pvt = _variantTargetType;
                _matchTargetCType = _variantTargetType = p.className;
                val = emitExpression(argExpr);
                _matchTargetCType = pmt; _variantTargetType = pvt;
                valHoisted = true;   // union/match compound literal — keep its existing addressable form
            } else {
                // FAIL CLOSED: an argument that does NOT get a destination threaded must not inherit the
                // one an enclosing position left behind. Leaving it set is what let a `match` reachable
                // from here adopt an ancestor's type and truncate in silence; cleared, the same shape hits
                // the existing "a value-producing `match` must appear in a typed position" error instead.
                // (A generic ctor's destination is the one this PARAMETER supplied, not an ancestor's.)
                std::string pmt = _matchTargetCType, pvt = _variantTargetType;
                _matchTargetCType.clear(); _variantTargetType = genericCtorDest;
                val = st.empty() ? emitExpression(argExpr) : st;
                _matchTargetCType = pmt; _variantTargetType = pvt;
                valHoisted = !st.empty();   // st => a hoisted string/primitive temp; else a bare rvalue
            }
        }
        // THE TEMPORARY RULE. One of the arms above materialized a TEMPORARY — a literal into `__primtmp`,
        // a string rvalue into `__strtmp`, an inline constructor into `__ctorarg` — and a temporary is
        // storage that dies at the end of this statement. Borrowing one READ-ONLY is the whole point of
        // those arms: it is what lets `m.get(key: 5)`, `readFile(path: "x")` and `useShape(a: Square(3))`
        // be written without binding a local first (tests/ref_param_rvalue.kama). WRITING one is a silent
        // no-op, which is exactly what a non-const `ref`/`out` does by definition.
        //
        // The rule and its wording already existed — see the `isClass(argCls)` branch below — and it could
        // reach none of the three, because it is guarded on `!valHoisted` and every arm that materializes
        // sets that. So it fired only for an rvalue that reached the fallthrough path, and the language
        // rejected `bump(p: mk())` while accepting `bump(p: Point.make(1, 2))` and `bump(v: 1)`, which lose
        // the write just as completely. ref_param_rvalue.kama justified the materialization as "the temp is
        // a read-only borrow here" — true of the call it was written about, assumed of every other,
        // enforced nowhere until this check.
        //
        // ⚠️ It is `argIsTemp`, not `valHoisted`. The element-access arm sets the latter for `ref a[i]`,
        // which is a real place (`*NAME__at(...)`) that a callee may legitimately write through — reading
        // "hoisted" as "temporary" would reject the one shape `ref` exists for.
        //
        // The diagnostic names BOTH repairs, because which is right is not the caller's to guess: the
        // callee either genuinely writes (bind a local) or never did and said `ref` out of habit (say
        // `const ref`). The stdlib was the second case in 94 places.
        if (argIsTemp && p.byRef && !p.isConst)
            unsupported(("`" + p.name + "` is a non-const `" + std::string(p.isOut ? "out" : "ref")
                         + "` parameter, so it cannot take a literal or a temporary — the callee writes "
                           "into storage that dies at the end of this statement. Bind it to a local first "
                           "and pass that, or declare the parameter `const ref` if it is only read").c_str(),
                        srcLine);
        if (handoff && (p.byRef || isInterface(p.className)))
            unsupported("`give`/`copy` transfer ownership by value — they don't apply to a `ref`/`out` "
                        "or contract borrow", srcLine);
        if (isInterface(p.className)) {
            std::string c = exprClass(argExpr);
            if (c.empty() && _classes.count(constantTempCType(argExpr))) c = constantTempCType(argExpr);   // `Level::Low` into a contract
            if (p.byRef) {
                // `ref`/`out` interface: the callee may reseat the caller's handle, so the
                // argument must be an actual interface variable (pass its address). A
                // concrete class would need a throwaway temp — reject it; bind first.
                if (!c.empty() && isClass(c))
                    unsupported(("cannot pass '" + c + "' by `ref`/`out` to contract parameter '" + p.name
                                 + "'; bind it to an `" + p.className + "` first "
                                 "(`" + p.className + " s = …; … ref s`)").c_str(), srcLine);
                if (!p.isConst) checkConstWrite(argExpr, srcLine);
                s += "&(" + val + ")";
            } else {
                // by value: wrap a concrete object as an interface fat pointer (the borrow);
                // pass an existing interface value straight through.
                std::string dt = derefTarget(c);   // Owned/Shared<T> pointee via Deref ("" if not, incl. Weak)
                bool dtImpl = false;
                if (!dt.empty()) {
                    auto eit = _classes.find(dt);
                    if (eit != _classes.end())
                        for (auto& i : eit->second.interfaces) if (i == p.className) { dtImpl = true; break; }
                }
                // Both arms below take the argument's ADDRESS, so a call result (`use(g: makeG(k: 4))`) would be
                // `&(rvalue)` — illegal C that `kama check` never saw. Materialize it into a scope-dtor'd temp,
                // the borrow the callee reads, exactly as a `const ref` class rvalue is (the `ref` arm below).
                if ((dtImpl || (isClass(c) && !dynamic_cast<ThisAccessNode*>(argExpr.get())))
                    && !valHoisted && (!isNamedValue(argExpr.get()) || !constantTempCType(argExpr).empty())) {
                    if (_hoistOK) {
                        std::string t = "__ifcarg" + std::to_string(_tempCounter++);
                        _hoisted.push_back(c + " " + t + " = " + val + ";");
                        if (_classes[c].destructible) recordDestructibleLocal(t, c);
                        val = t;
                    } else
                        unsupported(("a temporary cannot be borrowed as contract parameter '" + p.name
                                     + "' here — bind it to a local first, then pass that").c_str(), srcLine);
                }
                if (dtImpl) {
                    // `encode(v: sharedRoot)`: a `Shared`/`Owned<T>` whose pointee `T` implements the contract
                    // — deref to the pointee (`T*`) and wrap THAT as the fat pointer, not the handle struct.
                    s += "(" + p.className + "){ (void*)" + derefFnName(c, true) + "(&(" + val + ")), &"
                       + dt + "__as_" + p.className + " }";
                } else if (!c.empty() && isClass(c)) {
                    // `this` already IS the object pointer (`self`), so wrap it without taking its
                    // address — `&self` would be a `C**` (same reason a by-ref `this` passes `self`).
                    if (dynamic_cast<ThisAccessNode*>(argExpr.get()) && !_classes[c].isScalarRecv)
                        s += "(" + p.className + "){ (void*)(" + val + "), &" + contractVtblOf(c, p.className) + " }";
                    else
                        s += fatPointer(p.className, c, val);
                } else if (!primWidenKey(argExpr, p.className).empty()) {
                    // A PRIMITIVE passed where a contract value is expected — the parameter counterpart of
                    // the local-declaration widening. Same compound literal, same block lifetime; without
                    // this the scalar fell through to `s += val` and emitted a raw int where the callee
                    // reads a fat pointer, which the C compiler caught but kama never explained.
                    std::string pk = primWidenKey(argExpr, p.className);
                    s += "(" + p.className + "){ (void*)&(" + primConformance(pk)->name + "){ " + val
                       + " }, &" + intrinsicContractVtbl(pk, p.className) + " }";
                } else s += val;
            }
        } else if (p.byRef) {
            // Soundness: a non-const `ref`/`out` param can MUTATE its argument, so a
            // const binding (or a const field outside its ctor) may not be passed to one
            // — that would silently launder away const. (A `const ref` borrow is fine.)
            if (!p.isConst) checkConstWrite(argExpr, srcLine);
            // a borrow names the OBJECT (`ref T`). If the argument is a smart pointer
            // holding a T, auto-deref to its T* — `ref p` borrows the heap object, uniformly
            // with `ref stackValue`. (Weak can't be borrowed — it may be dead; tryUpgrade.)
            std::string argCls = exprClass(argExpr);
            std::string dt = derefTarget(argCls);   // library Deref<T> pointee ("" if not a Deref type)
            // A class RVALUE (a factory / call result, not a named lvalue) has no address, so the
            // `&(val)` below would be illegal C (`&(makePoint())`). For a `const ref` borrow, materialize
            // a scope-dtor'd temp (read-only borrow, freed at scope end — sound, mirrors the string /
            // literal hoists). A non-const `ref` would mutate a discarded temp — reject cleanly. Smart-ptr
            // / Deref / `this` keep their dedicated paths below (excluded here).
            if (!valHoisted && isClass(argCls) && !isSmartPtrClass(argCls) && dt.empty()
                && !isNamedValue(argExpr.get()) && !dynamic_cast<ThisAccessNode*>(argExpr.get())) {
                if (!p.isConst)
                    unsupported("a non-const `ref` cannot take a temporary (a call/constructor result) — "
                                "its mutation would be lost; bind it to a local first, then pass that", srcLine);
                else if (_hoistOK) {
                    std::string t = "__refarg" + std::to_string(_tempCounter++);
                    _hoisted.push_back(argCls + " " + t + " = " + val + ";");
                    if (_classes[argCls].destructible) recordDestructibleLocal(t, argCls);
                    val = t;
                }
            }
            if (isSmartPtrClass(argCls) && _classes[argCls].collElemClass == p.className) {
                if (smartKind(argCls) == CollKind::Weak)
                    unsupported(("cannot borrow through a `Weak<" + p.className
                                 + ">` (it may be dead) — `tryUpgrade` to a `Shared` first").c_str(), srcLine);
                s += "(" + val + ").ptr";
            } else if (!dt.empty() && dt == p.className) {
                // a library heap-owner (Owned/Shared) borrows its pointee via the Deref contracts —
                // `derefMut()` (-> T*) for a `ref` parameter, `deref()` (-> T const*) for a `const ref` one —
                // uniformly with `ref stackValue`; no `.ptr` field is assumed.
                s += derefFnName(argCls, !p.isConst) + "(&(" + val + "))";
            } else if (dynamic_cast<ThisAccessNode*>(argExpr.get())) {
                // `this` lowers to `self`, which is ALREADY a `T*` (the receiver pointer). Pass it straight
                // to a `ref T` param — `&(self)` would hand over the address of the param slot (a `T**`), so
                // a whole-`this` borrow (`w.writeString(v: this)` in an impl on `string`) would read the
                // pointer's own bytes, not the value. (Cast for a `ref Base` upcast.)
                s += (isClass(p.className) && argCls != p.className) ? ("(" + p.className + "*)" + val) : val;
            } else {
                // A `ref T` arg must BE a T, a subclass of T (upcast to `ref Base`), or a
                // smart-ptr / Deref<T> owner of T (both handled above). An unrelated class — most
                // notably borrowing through a `Weak<T>` (no Deref) — is a type error, caught here
                // instead of emitting a bad reinterpreting cast.
                if (isClass(p.className) && isClass(argCls) && argCls != p.className
                    && !isBaseOf(p.className, argCls))
                    unsupported(("cannot borrow a `" + argCls + "` as `ref " + p.className
                                 + "` — it is not that object (a `Weak` must `tryUpgrade` to a `Shared` first)").c_str(), srcLine);
                // A `const ref` parameter lowers to a plain `T*` (`const fn` is ABI-neutral — see paramListC),
                // while a READ-ONLY place — a `const` binding, an `UnsafeConstPtr<T>` element, a `const ref T`
                // result such as `cv[i]` — addresses as `T const*`. The front end has already ruled the pass
                // legal (a `const ref` borrow may take a read-only place), so the cast states the ABI, the
                // same way every receiver and `__at` site does. A class param was always cast (the upcast).
                const bool constPlaceToConstRef = p.isConst && !p.className.empty() && isConstReceiver(argExpr);
                if (!constantTempCType(argExpr).empty())   // `Color::Red`, an `extern const`: no address, borrow a temporary
                    s += "(" + constantTempCType(argExpr) + "[]){ " + val + " }";
                else
                s += (isClass(p.className) || constPlaceToConstRef)
                         ? ("(" + p.className + "*)&(" + val + ")")  // upcast for ref Base / the read-only place
                         : ("&(" + val + ")");
            }
        } else {
            // By value. A *named* smart pointer TRANSFERS into the param, which the
            // callee owns and drops at fn-end. The retain (copy) / invalidate (give) is a
            // statement, materialized as a HOISTED temp (pure ISO C).
            std::string argCls = handoffSourceClass(argExpr, handoff);
            rejectUnresolvedHandoff(argCls, p.className, argExpr, handoff, ("argument `" + p.name + "`").c_str(), srcLine);
            if (isSmartPtrClass(argCls) && isNamedValue(argExpr.get())) {
                CollKind k = smartKind(argCls);
                // Default the natural op: Owned -> give (move; copy illegal), Shared/Weak -> copy
                // (retain). A marker overrides (e.g. `give Shared` moves the handle).
                bool doGive = (handoff == 1) || (handoff == 0 && k == CollKind::Owned);
                if (handoff == 2 && k == CollKind::Owned)
                    unsupported("an `Owned` is unique — it can't be `copy`'d; use `give` to move it", srcLine);
                // A give only invalidates the LOCAL copy — a borrowed `match` binding still aliases the
                // subject's box → double free. Reject (this path bypasses moveOnlySource — explicit check).
                if (doGive) giveOfBorrowedBinding(argExpr, srcLine);
                std::string t = "__kama_arg" + std::to_string(_tempCounter++);
                std::string side = doGive ? smartPtrInvalidate("(" + val + ")", k, isInterface(_classes[argCls].collElemClass))
                                          : ("(" + val + ").ctrl->" + (k == CollKind::Weak ? "weak" : "strong") + "++;");
                // Hoist `T t = (x); <retain/invalidate>` as an ordinary statement (ISO C)
                // everywhere a temp can precede its statement (call/init/return/ctor sites). The
                // `({ … })` form is used ONLY for a by-value smart-ptr hand-off inside a loop/branch
                // CONDITION (no preceding-statement slot) — where it is also semantically REQUIRED:
                // hoisting a per-iteration retain out of a `while (...)` would run it once, not each
                // time. No fixture reaches it (the ISO `-pedantic-errors` gate confirms zero GNU
                // extensions across the whole suite).
                if (_hoistOK) {
                    _hoisted.push_back(p.className + " " + t + " = (" + val + "); " + side);
                    s += t;
                } else {
                    s += "({ " + p.className + " " + t + " = (" + val + "); " + side + " " + t + "; })";
                }
            } else if (isSmartPtrClass(argCls)) {
                // A FRESH smart-ptr rvalue (factory/`new` result) — consumed in place, no source.
                if (handoff)
                    unsupported("`give`/`copy` apply to a named value — a fresh `new`/constructor/call "
                                "result needs no marker", srcLine);
                s += val;
            } else if (ownsByValue(p.className) && _classes.count(p.className)
                       && _classes[p.className].isIntrinsicColl && isNamedValue(argExpr.get())) {
                // A collection/`string` passed BY VALUE to an OWNING param transfers ownership: the callee
                // owns it and drops it at fn-end (param-drop registration). `give` MOVES it in (relocate
                // struct + null source + markMoved); `copy` deep-copies (`__copy`); a BARE named arg is an
                // error. Gated on the PARAM's declared type — the `kama_string__*` read-only intrinsics
                // register their string args with `className == ""`, so this is skipped for them and they
                // keep the borrow-hoist above (Phase-3 ergonomics unchanged). A fresh rvalue / literal arg
                // (not isNamedValue) moves in bare via the `else` below.
                if (handoff == 0)
                    unsupported("passing a collection/`string` by value transfers ownership — say `give` "
                                "(move) or `copy` (deep), or pass by `ref` to borrow", srcLine);
                else if (handoff == 2) {                              // copy = deep
                    auto ci = _collections.find(p.className);
                    if (ci != _collections.end() && ci->second.elemDestructible && !ci->second.elemCopyable)
                        unsupported(("`copy` of a `" + p.className + "` needs copyable elements — its elements "
                                     "own resources but aren't `Copyable`; use `give` to move").c_str(), srcLine);
                    s += copyCall(p.className, val);
                } else {                                             // give = move: relocate + null source
                    std::string t = "__kama_carg" + std::to_string(_tempCounter++);
                    std::string blit = p.className + " " + t + " = (" + val + "); " + moveNullStmt(p.className, val);
                    if (_hoistOK) { _hoisted.push_back(blit); s += t; }
                    else          { s += "({ " + blit + " " + t + "; })"; }
                    std::string mv = moveOnlySource(argExpr, srcLine); if (!mv.empty()) markMoved(mv);
                }
            } else if (isMoveOnlyValue(argCls) && isNamedValue(argExpr.get())) {
                // A `resource` VALUE passed by value → the callee owns it and drops it at fn-end. `give`
                // MOVES it in (mark the source moved); `copy` passes a fresh copy (source survives); a
                // BARE arg follows the type's `bare:` default. A non-Copyable resource → move.
                bool cpy = isCopyable(argCls);
                bool doCopy;
                if (handoff == 2) {
                    if (!cpy) unsupported(("`" + argCls + "` has no `copy` method — add `implements "
                                           "Copyable(bare: …)`, or use `give` to move it").c_str(), srcLine);
                    doCopy = cpy;
                } else if (handoff == 1) doCopy = false;
                else doCopy = cpy && _classes[argCls].bareDefault == COPY;
                if (doCopy) s += copyCall(argCls, val);
                else { std::string mv = moveOnlySource(argExpr, srcLine); if (!mv.empty()) markMoved(mv); s += val; }
            } else if (dynamic_cast<ThisAccessNode*>(argExpr.get()) && !p.className.empty()
                       && _classes.count(p.className) && _classes[p.className].kind == TypeKind::Value) {
                // A bare `this` is `self` (a `T*` — the receiver pointer). Passed to a by-value value-type
                // parameter it must be dereferenced: `*self` is the value. (Field args are MemberAccessNodes,
                // never ThisAccessNode, and a primitive param's className is empty — so this only fires for a
                // whole-`this` value arg, e.g. `this.dot(r: this)` in `length()`.)
                s += "*(" + val + ")";
            } else {
                // plain value copy (primitive / value / collection borrow); `give` on a value is just that
                // copy — and a `View<X>` meeting a `ConstView<X>` parameter narrows here.
                s += narrowViewValue(p.className, argExpr, val, srcLine);
            }
        }
    }
    // The graph parameter rides here, after every declared argument — see the header note. `s` ends in
    // `(` only when nothing at all was emitted, which is the one case that must not get a comma.
    if (!trailingArg.empty()) { if (s.back() != '(') s += ", "; s += trailingArg; }
    return s + ")";
}

// does a free function match a FunctionPtr signature? Positional, by C type.
bool CEmitter::sigMatches(const SigInfo& sig, const FuncSig& fn) const
{
    if (sig.retCType != fn.retCType) return false;
    if (sig.params.size() != fn.params.size()) return false;
    for (size_t i = 0; i < sig.params.size(); ++i) {
        if (sig.params[i].className != fn.params[i].className) return false;
        if (sig.params[i].byRef    != fn.params[i].byRef)    return false;
    }
    return true;
}

// Is the ROOT of a member/element chain a by-value call result — a temporary that dies with the statement?
// `f.view()[0]`, `make().field`, `a.slice()[i]` -> true; `b.at(i: 0)` (a place-returning call), `x[i]`,
// `this.f` -> false. `rootBinding` answers "" for a call root, which is not the same question.
bool CEmitter::rootIsTemporary(SharedExpression e) const
{
    ASTNode* n = e.get();
    if (auto* ma = dynamic_cast<MemberAccessNode*>(n)) return ma->expression ? rootIsTemporary(ma->expression) : false;
    if (auto* ea = dynamic_cast<ElementAccessNode*>(n)) return ea->expression ? rootIsTemporary(ea->expression) : false;
    if (auto* inv = dynamic_cast<InvocationNode*>(n)) return !const_cast<CEmitter*>(this)->invocationReturnsPlace(inv);
    return false;
}

// the root identifier a write ultimately targets, for deep-const checks.
// `x` -> "x";  `x.f`, `x[i]`, `x.f.g` -> "x";  `this`/`this.f` -> "this";  else "".
std::string CEmitter::rootBinding(SharedExpression e) const
{
    ASTNode* n = e.get();
    if (dynamic_cast<ThisAccessNode*>(n)) return "this";
    if (auto* id = dynamic_cast<IdentifierNode*>(n))
        return (id->value && (!id->qualifier || id->qualifier->empty())) ? *id->value : "";
    if (auto* ma = dynamic_cast<MemberAccessNode*>(n))
        return ma->expression ? rootBinding(ma->expression) : "";
    if (auto* ea = dynamic_cast<ElementAccessNode*>(n)) {
        if (ea->expression) return rootBinding(ea->expression);
        return (ea->identifier && ea->identifier->value) ? *ea->identifier->value : "";
    }
    return "";
}

// The PLACE an expression designates: the base binding plus its chain of field names.
//   `x` -> {x};  `this` -> {this};  `this.inner.buf` -> {this, inner, buf}
// A bare field name inside a method is normalized to `this.<name>`, because that is what it
// resolves to (see the implicit-field branch of the IdentifierNode arm of `emitExpression`) —
// without this, `borrow this.buf as v { buf.clear(); }` would name the same storage by a path that
// compares unequal.
//
// EMPTY means "not a statically-nameable place", and that is load-bearing rather than a failure
// case: an ELEMENT (`a[i]`) has a runtime index no static rule can pin, and a CALL
// (`this.slot().buf`) or a temporary designates no place at all. Both are rejected as borrow hosts
// on exactly this signal. (Rust is conservative about the index projection too — it is why
// `split_at_mut` has to exist.)
std::vector<std::string> CEmitter::placePath(SharedExpression e)
{
    ASTNode* n = e.get();
    if (!n) return {};
    if (dynamic_cast<ThisAccessNode*>(n)) return { "this" };
    if (auto* id = dynamic_cast<IdentifierNode*>(n)) {
        if (!id->value || (id->qualifier && !id->qualifier->empty())) return {};
        const std::string& nm = *id->value;
        // A bare name that is neither a local nor a param, but IS a field of the enclosing class,
        // is an implicit `this.<nm>`. Mirror that resolution order exactly.
        if (!_localTypes.count(nm) && !_paramNames.count(nm) && _currentClass
            && findFieldOwner(_currentClass, nm))
            return { "this", nm };
        return { nm };
    }
    if (auto* ma = dynamic_cast<MemberAccessNode*>(n)) {
        if (!ma->expression || !ma->identifier || !ma->identifier->value) return {};
        std::vector<std::string> base = placePath(ma->expression);
        if (base.empty()) return {};                 // rooted at a call/element — not a place
        base.push_back(*ma->identifier->value);
        return base;
    }
    return {};   // element access, invocation, temporary, literal — not a place
}

// Two places may overlap in storage iff one is a PREFIX of the other (equality included). If
// neither is, they are provably disjoint: two distinct fields of one object cannot overlap, so
// writing one can never invalidate a view into the other. That is the exact statement of the
// disjointness argument — not an approximation — and it is what lets `borrow this.buf as v` leave
// `this.sink` and `this.failed` fully mutable while still catching `ref this`, whose place `{this}`
// is a prefix of `{this, buf}`.
//
// An empty path never conflicts: "not a place" is handled by rejecting it at the mint, not by
// pretending it aliases everything.
bool CEmitter::placesConflict(const std::vector<std::string>& a, const std::vector<std::string>& b)
{
    if (a.empty() || b.empty()) return false;
    const size_t n = std::min(a.size(), b.size());
    for (size_t i = 0; i < n; ++i)
        if (a[i] != b[i]) return false;
    return true;
}

std::string CEmitter::placeText(const std::vector<std::string>& p)
{
    std::string s;
    for (size_t i = 0; i < p.size(); ++i) { if (i) s += "."; s += p[i]; }
    return s;
}

// The place a VIEW expression ultimately borrows. `placePath` answers "what storage does this designate",
// which is empty for an invocation — correct for a value, and useless for a view, because `d.view()`
// designates no place while borrowing all of `d`. So the two forms that produce a view without being a
// place are unwrapped here:
//
//   `d.view()`, `d.view().slice(…)`   -> {d}   — recurse through the RECEIVER (a chained derive roots
//                                               where its receiver roots)
//   a `borrow` alias `v`              -> the place that window froze
//   a by-value view PARAMETER         -> {}    — the caller's frame already bounds it, and the caller is
//                                               where its aliasing was checked
//   `View.make(…)` (dot-on-type ctor) -> {}    — the mint rule governs it, not aliasing
//
// EMPTY means "nothing here can conflict", the same load-bearing signal `placePath` uses. Forgetting the
// receiver unwrap would make every check downstream silently vacuous — an empty path conflicts with
// nothing — so `xfail/view_arg_aliases_ref` is the guard that this function did anything at all.
std::vector<std::string> CEmitter::viewRootPlace(SharedExpression e)
{
    ASTNode* n = e.get();
    if (!n) return {};
    if (auto* h = dynamic_cast<HandoffNode*>(n)) return viewRootPlace(h->value);
    if (auto* id = dynamic_cast<IdentifierNode*>(n)) {
        if (id->value && (!id->qualifier || id->qualifier->empty())) {
            if (const std::vector<std::string>* r = frozenAliasRoot(*id->value)) return *r;
            if (_viewParams.count(*id->value)) return {};
        }
        return placePath(e);
    }
    if (auto* inv = dynamic_cast<InvocationNode*>(n)) {
        if (inv->expression)
            if (auto* ma = dynamic_cast<MemberAccessNode*>(inv->expression.get())) {
                if (auto* rid = dynamic_cast<IdentifierNode*>(ma->expression.get()))
                    if (rid->value && _viewTypeNames.count(*rid->value)) return {};   // `View.make(…)`
                if (ma->expression) return viewRootPlace(ma->expression);
            }
        return {};
    }
    // A ternary yields one of two views. Either arm may alias, so BOTH are offered to the caller; a
    // single place cannot say "one of these", so the first that roots anywhere is returned and the other
    // is caught on its own if it is the one that conflicts.
    if (auto* t = dynamic_cast<TernaryExpressionNode*>(n)) {
        std::vector<std::string> a = t->LHS ? viewRootPlace(t->LHS) : std::vector<std::string>();
        if (!a.empty()) return a;
        return t->RHS ? viewRootPlace(t->RHS) : std::vector<std::string>();
    }
    return placePath(e);
}

// The window rule. A view borrows storage it does not own, so a view LOCAL is only as good as its root:
// it is legal exactly when that root is already lifetime-bounded, and a container you can still name and
// grow is not. This is the question `viewRootPlace` cannot answer, because "roots nowhere" and "roots at
// something bounded" are the same empty vector there and opposite answers here.
//
// Bounded means one of:
//   * a `borrow` alias — the window IS the bound, and the freeze keeps the storage still
//   * a by-value view PARAMETER — the caller's frame outlives this one, and the caller is where the
//     aliasing was checked (probing showed a rule on the callee would be the wrong place: the caller had
//     borrowed and it still dangled, because the SAME call passed `ref` to the container)
//   * a derive off either — `View<T> mid = whole.slice(…)` roots where `whole` roots
//   * a free function's result, when every view it was handed is bounded — the view-return rule already
//     guarantees the result roots at one of those arguments
//
// NOT bounded: a mint from a nameable container (`d.view()`), which is the shape every one of findings
// ④⑤⑥ rides, and which now has `borrow d.view() as v` as its spelling.
bool CEmitter::viewLocalBounded(SharedExpression init)
{
    ASTNode* n = init.get();
    if (!n) return false;
    if (auto* h = dynamic_cast<HandoffNode*>(n)) return viewLocalBounded(h->value);
    if (auto* id = dynamic_cast<IdentifierNode*>(n)) {
        if (!id->value || (id->qualifier && !id->qualifier->empty())) return false;
        const std::string& nm = *id->value;
        if (frozenAliasRoot(nm) || _viewParams.count(nm)) return true;
        for (int i = (int)_scopes.size() - 1; i >= 0; --i)
            if (_scopes[i].boundedViews.count(nm)) return true;
        return false;
    }
    if (auto* t = dynamic_cast<TernaryExpressionNode*>(n))
        return t->LHS && t->RHS && viewLocalBounded(t->LHS) && viewLocalBounded(t->RHS);
    if (auto* inv = dynamic_cast<InvocationNode*>(n)) {
        if (inv->expression)
            if (auto* ma = dynamic_cast<MemberAccessNode*>(inv->expression.get())) {
                // `View.make(…)` — the dot-on-type view ctor. The mint rule governs it (its ctor is
                // private and `checkViewCtorEscape` checks what it borrows), so it is not this rule's.
                if (auto* rid = dynamic_cast<IdentifierNode*>(ma->expression.get()))
                    if (rid->value && _viewTypeNames.count(*rid->value)) return true;
                return ma->expression && viewLocalBounded(ma->expression);   // a derive roots where its receiver does
            }
        // A free function. Its return already had to root at one of ITS parameters, so the result is
        // bounded exactly when every view handed to it was.
        bool sawView = false;
        if (inv->args)
            for (auto& a : *inv->args) {
                if (!a || !a->expression) continue;
                if (!isViewCType(exprClass(a->expression))) continue;
                sawView = true;
                if (!viewLocalBounded(a->expression)) return false;
            }
        return sawView;
    }
    return false;
}

// --- The window's freeze -------------------------------------------------------------------------------
// `borrow` bounds how long a view is valid by bounding the SCOPE it lives in. That is only half the
// promise: the other half is that the storage does not move under it, which is what these three answer.
// Without them a window was a comment — `borrow a.view() as v { a.add(item: 3); … v[0] }` compiled and
// faulted under ASan, inside the very construct meant to prevent it.
const CEmitter::Scope::FrozenPlace* CEmitter::frozenConflict(const std::vector<std::string>& p) const
{
    if (p.empty()) return nullptr;   // not a nameable place — an element write cannot realloc anyway
    for (int i = (int)_scopes.size() - 1; i >= 0; --i)
        for (auto& f : _scopes[i].frozen)
            if (placesConflict(f.place, p)) return &f;
    return nullptr;
}

const std::vector<std::string>* CEmitter::frozenAliasRoot(const std::string& name) const
{
    if (name.empty()) return nullptr;
    for (int i = (int)_scopes.size() - 1; i >= 0; --i)
        for (auto& f : _scopes[i].frozen)
            if (f.fromBorrow && f.alias == name) return &f.place;
    return nullptr;
}

bool CEmitter::rejectFrozenWrite(SharedExpression target, int line)
{
    std::vector<std::string> p = placePath(target);
    const Scope::FrozenPlace* f = frozenConflict(p);
    if (!f) return false;
    unsupported((f->fromBorrow
        ? ("`" + placeText(p) + "` is frozen by the enclosing `borrow` (opened at line "
           + std::to_string(f->line) + " as `" + f->alias + "`) — a view is live over that storage, so "
           "growing or reseating it would leave `" + f->alias + "` dangling. Mutate it after the window "
           "closes, or narrow the window. A DISJOINT sibling field stays mutable inside it")
        : ("`" + placeText(p) + "` is frozen by the `foreach` at line " + std::to_string(f->line)
           + " that is iterating it — the loop holds a borrowing iterator into that storage, so growing or "
           "reseating it mid-loop would leave the iterator dangling. Collect what you need and apply it "
           "after the loop. Reading it, and writing a DISJOINT sibling field, stay legal")).c_str(), line);
    return true;
}

// The root a view-CONSTRUCTOR's borrowed pointer argument comes from, tracing through the safe
// forms a view is built with: `addr(of: this.data[i])` (pointer offset) and `this.dataPtr()` (a
// place-returning accessor call). Anything else falls back to rootBinding (`this.data` -> "this";
// a local -> the local's name -> rejected). No lifetime analysis — one structural step.
std::string CEmitter::borrowArgRoot(SharedExpression e) const
{
    if (auto* inv = dynamic_cast<InvocationNode*>(e.get())) {
        std::string callee = (inv->identifier && inv->identifier->value) ? *inv->identifier->value : "";
        if (callee == "addr" && inv->args && inv->args->size() == 1)     // addr(of: this.data[i]) -> this
            return borrowArgRoot((*inv->args)[0]->expression);
        if (inv->expression)                                             // this.dataPtr() -> this
            if (auto* ma = dynamic_cast<MemberAccessNode*>(inv->expression.get()))
                if (ma->expression) return rootBinding(ma->expression);
        return "";                                                       // unknown call -> conservatively reject
    }
    return rootBinding(e);                                               // this.data -> "this"; local -> its name
}

bool CEmitter::isSafeViewRoot(const std::string& root) const
{
    return root == "this" || _refParams.count(root) > 0 || _viewParams.count(root) > 0;
}

// The root a view CONSTRUCTOR call borrows, matched BY ARGUMENT NAME against the declared parameters.
//
// Named arguments ARE kama's calling convention — `emitReorderedCall` binds them into declared order
// through a `byName` map and errors on a missing one, so the order a call WRITES them in carries no
// meaning. This used to root at `args[0]` on the convention (its own word) that a view ctor takes its
// borrow first, and writing the length first walked straight past the escape check:
//
//     return View::<int32>.make(len: keep, data: addr(of: local));   // compiled; view over a dead local
//     return View::<int32>.make(data: addr(of: local), len: keep);   // the SAME call, rejected
//
// so ask the signature instead. And ask it about EVERY parameter that can carry a borrow, not just one:
// a multi-borrow ctor (`BitSetIter.make(words:…, modsp: addr(of: this.mods))`) dangles if any single one
// of them does. Returns the first UNSAFE root, so the caller's diagnostic names the real offender;
// otherwise the first borrowed root. "" means "cannot tell", which the caller rejects — the same answer
// every other unresolvable call form here gives.
std::string CEmitter::viewCtorBorrowRoot(IdentifierNode* typeId, const std::string& method,
                                         SharedArgumentList args) const
{
    if (!typeId || !typeId->value) return "";
    auto* self = const_cast<CEmitter*>(this);   // resolveUserName/findMethod are non-const; this query is
    const std::string key = self->resolveUserName(*typeId->value, typeId->qualifier);

    // A concrete `type view` resolves in `_classes`; a GENERIC one (`View<T>`) lives only as a template,
    // and the template is the right place to ask: `paramCanCarryBorrow` keys on the SOURCE spelling of the
    // parameter's type, so it answers correctly even where the monomorph cannot be pinned down.
    SharedParameterList params;
    if (self->_classes.count(key)) {
        ClassInfo* owner = nullptr;
        if (MethodInfo* mi = self->findMethod(&self->_classes[key], method, &owner))
            if (mi->node) params = mi->node->params;
    }
    if (!params) {
        auto gt = _genericTypes.find(key);
        if (gt != _genericTypes.end()) {
            auto mit = gt->second.methods.find(method);
            if (mit != gt->second.methods.end() && mit->second.node) params = mit->second.node->params;
        }
    }
    if (!params) return "";

    std::map<std::string, SharedExpression> byName;
    if (args)
        for (auto& a : *args)
            if (a->name && a->name->value) byName[*a->name->value] = a->expression;

    std::string firstBorrowed;
    for (auto& p : *params) {
        if (!paramCanCarryBorrow(p.get(), std::string())) continue;
        if (!p->identifier || !p->identifier->value) return "";
        auto it = byName.find(*p->identifier->value);
        if (it == byName.end()) return "";                  // a borrow argument we cannot see -> reject
        const std::string r = borrowArgRoot(it->second);
        if (!isSafeViewRoot(r)) return r;                   // name the one that actually dangles
        if (firstBorrowed.empty()) firstBorrowed = r;
    }
    return firstBorrowed;   // "" when no parameter carries a borrow — rejected, exactly as before
}

// The root a RETURNED view ultimately borrows, dispatched on the return form:
//  - a view constructor `View.make(data: <p>, len: <n>)` -> viewCtorBorrowRoot, by argument NAME;
//  - a chained call `recv.slice(...)` returning a view -> wherever the RECEIVER roots, recursively, so a
//    derive off a mint (`this.view().slice(...)`) roots at `this` instead of nowhere;
//  - a bare place (a view local/param) -> rootBinding (a param roots at itself; a local likewise, and a
//    local's borrow provenance is unknown, so it is correctly rejected).
std::string CEmitter::viewReturnRoot(SharedExpression e) const
{
    if (auto* inv = dynamic_cast<InvocationNode*>(e.get())) {
        // (No arm for a bare `View(...)`: nameless construction is rejected upstream — "nameless
        //  construction 'Span(...)' is no longer allowed — use a named constructor".)
        if (inv->expression)                                            // `recv.slice(...)` or `View.make(...)`
            if (auto* ma = dynamic_cast<MemberAccessNode*>(inv->expression.get())) {
                const std::string method = (ma->identifier && ma->identifier->value) ? *ma->identifier->value : "";
                // Dot-on-type view ctor `View.make(...)`: the receiver names a view TYPE, not an instance.
                if (auto* id = dynamic_cast<IdentifierNode*>(ma->expression.get()))
                    if (id->value && _viewTypeNames.count(*id->value))
                        return viewCtorBorrowRoot(id, method, inv->args);
                // Chained: `recv.slice(...)`. RECURSE rather than `rootBinding` — the receiver may itself be
                // a call (`this.view().slice(...)`), and `rootBinding` has no InvocationNode arm, so it
                // answered "" and the derive was rejected as if it borrowed a local. A strict
                // generalization: for any non-invocation receiver `viewReturnRoot` IS `rootBinding`.
                if (ma->expression) return viewReturnRoot(ma->expression);
            }
        return "";                                                      // unknown call form -> reject
    }
    return rootBinding(e);                                              // bare view local/param
}

// is a write/call root `const`? A const local/param, `this` inside a const
// method (recorded as "this" in _constLocals), or — in a const method — a bare field
// of the current class (a write to `f` is really `self->f`).
bool CEmitter::rootIsConst(const std::string& root) const
{
    if (root.empty()) return false;
    if (_constLocals.count(root)) return true;
    if (_constLocals.count("this") && _currentClass && !_localTypes.count(root)
        && const_cast<CEmitter*>(this)->findFieldOwner(_currentClass, root))
        return true;
    return false;
}

// is `target` a write to a `const` data member? (`this.f`, bare `f`, or `obj.f`
// where f is declared const). Used to forbid such writes outside the constructor.
bool CEmitter::isConstFieldWrite(SharedExpression target)
{
    ASTNode* n = target.get();
    if (auto* ma = dynamic_cast<MemberAccessNode*>(n)) {
        std::string field = (ma->identifier && ma->identifier->value) ? *ma->identifier->value : "";
        std::string cls;
        if (ma->expression) {
            cls = dynamic_cast<ThisAccessNode*>(ma->expression.get())
                ? (_currentClass ? _currentClass->name : "")
                : exprClass(ma->expression);
        }
        if (!cls.empty() && isSmartPtrClass(cls)) cls = _classes.at(cls).collElemClass;   // pointee
        auto it = _classes.find(cls);
        return it != _classes.end() && it->second.constFields.count(field);
    }
    if (auto* id = dynamic_cast<IdentifierNode*>(n)) {       // bare field inside a method
        return id->value && (!id->qualifier || id->qualifier->empty()) && _currentClass
            && !_localTypes.count(*id->value) && _currentClass->constFields.count(*id->value);
    }
    return false;
}

// A body-level binder may not take a comptime parameter's name. `emitExpression` resolves a const
// param ahead of every runtime name, so the binder is not shadowing it — it is being silently discarded,
// and the reads inside it quietly become the const. Measured, before this rule: a `foreach (int32 F in
// [1,2,3])` summing `F` gave 48 rather than 6, and a `case A(v: F): F` arm gave 16 rather than the 3 in
// the payload. Both compiled CLEAN.
//
// The parameter and field spellings are rejected earlier, at the declaration (`checkDeclaredTypes`), so
// an uninstantiated generic is covered. A binder lives in a body, and a body is walked per instantiation
// — which is exactly where `_comptimeSubst` is bound, so this is the right and only place for it.
//
// This one stays SEPARATE from the general binder ban below even though both now fire at the same sites: a
// comptime parameter is not a parameter, a local or a field, it lives in `_comptimeSubst`, and its message
// names the thing the author has to rename. (The comment that used to sit here said the general ban did
// not reach these binders and that "the consumer-driven audit answered it (0.9.231): the exemption STAYS".
// That verdict was recorded in a source comment and nowhere else — no row, no SPEC sentence, no fixture —
// and the maintainer's ruling is the opposite: kama does not have shadowing. See `checkBinderShadow`.)
void CEmitter::checkConstParamBinder(const std::string& nm, const char* kind, int srcLine)
{
    if (nm.empty() || !_comptimeSubst.count(nm)) return;
    unsupported((std::string(kind) + " `" + nm + "` shadows a comptime parameter — rename it").c_str(),
                srcLine);
}

// The shadowing ban, at a binder. **kama has no shadowing** — "one name = one binding within any live
// scope", which is what keeps name resolution and move tracking unambiguous — and that rule was only ever
// enforced at a DECLARATION (`emitDeclarator`). The three body-level binders never went through it, so
// `foreach (int32 count in xs)` was accepted inside a method with a field `count`, over a parameter, and
// over an enclosing local, where `int32 count = …` in the same body is refused.
//
// That was never a decision. It was the check not reaching these sites, and it did not even hold together:
// until `0.9.248` a binder shadowing an enclosing local read the OUTER local's type and failed at the first
// use with a bogus type error, and one shadowing a `ref` parameter emitted `(*m)` on a plain int and died
// in clang with no kama diagnostic at all. Those were two shapes of the KB-20 class. `0.9.248` answered
// them by making the shadow WORK, which settled a language question inside a bug fix and in the wrong
// direction; this is that reversal. Sibling-scope reuse is untouched and stays legal — two blocks that
// never coexist are not shadowing, and that half of KB-20 (`0.9.247`) is the real fix.
//
// Same three questions, in the same order, with the same three messages as the declarator's check, so the
// rule reads identically wherever it fires. The `ctor`/static exemptions come along for the same reason
// they exist there: a bare name in a `ctor` body is always a local or a param (the value under
// construction is reached only through `this`), and a static method has no `this` to shadow.
void CEmitter::checkBinderShadow(const std::string& nm, const char* kind, int srcLine)
{
    if (nm.empty() || _probingTemplate) return;
    const std::string what = std::string(kind) + " `" + nm + "` shadows ";
    if (_paramNames.count(nm)) { unsupported((what + "a parameter — rename it").c_str(), srcLine); return; }
    for (auto& sc : _scopes)
        for (auto& dn : sc.declaredNames)
            if (dn == nm) { unsupported((what + "an enclosing-scope local — rename it").c_str(), srcLine); return; }
    if (_currentClass && !_inStaticMethod && !_inNamedCtorBody && _currentClass->fieldNames.count(nm))
        unsupported((what + "a field — rename it").c_str(), srcLine);
}

// writing TO or THROUGH a `const` binding is a hard error (deep const, so
// `c.field = …` / `c[i] = …` are caught too), and a `const` data member may only be
// written in the constructor.
// `const fn ref T m()` is const-laundering in one line, with no `unsafe` anywhere: a place returned out
// of a const method is a writable alias into `this`, so `c.place() = 99;` mutates a `const` binding — deep
// const defeated by the one construct that hands out an address instead of a value.
//
// The form a const method MAY return is `const ref T` — a READ-ONLY place (C#'s `ref readonly`, Rust's
// `&T`), the fourth const-rooted place beside a `const` local, a `const ref` parameter and an element of an
// `UnsafeConstPtr<T>`. It lowers to `T const*`, and every write path — assignment, `give`, a `ref`/`out`
// argument, a non-const call, `addr(of:)` — sees it through `chainThroughConstPlace`. The stdlib's
// two-name split (`getRef`/`getRefMut`, `iterator`/`iterMut`) is the convention for the WRITABLE twin; it
// is no longer the only way to read through a const receiver.
void CEmitter::checkConstPlaceReturn(bool isConst, bool isRef, bool isConstRef, const std::string& m, int line)
{
    if (isConst && isRef && !isConstRef)
        unsupported(("`const fn ref " + m + "` returns a writable place out of a const method, which "
                     "launders const away — a caller can assign through it. Return `const ref` (a "
                     "read-only place), drop `const`, or return by value").c_str(), line);
}

std::string CEmitter::placeRetSuffix(bool isPlace, bool isConstPlace)
{
    return !isPlace ? "" : isConstPlace ? " const*" : "*";
}

std::string CEmitter::placeKamaPrefix(bool isPlace, bool isConstPlace)
{
    return !isPlace ? "" : isConstPlace ? "const ref " : "ref ";
}

// Does this call resolve to a `const ref T` place-returner? Mirrors invocationReturnsPlace's lookup — a free
// function through `_funcs`, a method through its (auto-deref'd) receiver class — plus a CONTRACT receiver,
// whose member lives in `_interfaces`: a read-only slot dispatched through a fat pointer is still read-only.
bool CEmitter::invocationIsConstPlace(InvocationNode* iv)
{
    if (!iv) return false;
    if (iv->identifier && iv->identifier->value) {
        auto fit = _funcs.find(resolveFunc(*iv->identifier->value, iv->identifier->qualifier));
        return fit != _funcs.end() && fit->second.isConstPlace;
    }
    if (auto* ma = dynamic_cast<MemberAccessNode*>(iv->expression.get())) {
        std::string rcls = exprClass(ma->expression);
        if (isSmartPtrClass(rcls)) rcls = _classes[rcls].collElemClass;
        std::string m = (ma->identifier && ma->identifier->value) ? *ma->identifier->value : "";
        if (rcls.empty() || m.empty()) return false;
        if (_classes.count(rcls)) {
            MethodInfo* mi = placeMethodOf(rcls, m);
            return mi && mi->isConstPlace;
        }
        if (isInterface(rcls))
            for (auto& im : _interfaces[rcls].methods)
                if (im.name == m) return im.isConstPlace;
    }
    return false;
}

// Does some step of this place pass through a READ-ONLY place — a `const ref T` call (`m.getRef(k)`,
// `pick(d: d, i: 0)`, `c.place().field`) or a `const ref T operator[]` (`cv[i]`)? A write there, a `give`
// out of it, a `ref`/`out` pass of it or a non-const call on it lands in storage the place only reads. The
// ROOT binding may be perfectly mutable — it is the call that narrows — which is exactly the case
// `rootIsConst` cannot see, and the reason this predicate exists beside it. Same shape as
// chainThroughConstRawPtr, one level up: that one is the raw seam's read-only place, this is the safe one.
bool CEmitter::chainThroughConstPlace(SharedExpression e)
{
    if (!e) return false;
    ASTNode* n = e.get();
    if (auto* h = dynamic_cast<HandoffNode*>(n)) return chainThroughConstPlace(h->value);
    if (auto* inv = dynamic_cast<InvocationNode*>(n)) {
        if (invocationIsConstPlace(inv)) return true;
        // A non-const place call on a read-only receiver is refused by isConstReceiver at the call; here the
        // chain only needs to keep walking so `cv[i].getRefMut(k)` still answers through `cv`.
        if (auto* ma = dynamic_cast<MemberAccessNode*>(inv->expression.get())) return chainThroughConstPlace(ma->expression);
        return false;
    }
    if (auto* ea = dynamic_cast<ElementAccessNode*>(n)) {
        SharedExpression base = ea->expression ? ea->expression
                                               : std::static_pointer_cast<ExpressionNode>(ea->identifier);
        if (MethodInfo* op = userIndexOp(exprClass(base))) if (op->isConstPlace) return true;
        return chainThroughConstPlace(base);
    }
    if (auto* ma = dynamic_cast<MemberAccessNode*>(n)) {
        // A FIELD reached by auto-deref (`w.x` where `x` lives on the pointee) goes through `deref()` — a
        // read-only place — whenever the type has no `derefMut()` or the receiver is const.
        if (ma->identifier && ma->identifier->value) {
            std::string cls = exprClass(ma->expression);
            if (!cls.empty() && _classes.count(cls) && !findFieldOwner(&_classes[cls], *ma->identifier->value)
                && !derefTarget(cls).empty()) {
                bool ro = false;
                if (derefAccessor(cls, ma->expression, &ro) && ro) return true;
            }
        }
        return chainThroughConstPlace(ma->expression);
    }
    return false;
}

void CEmitter::checkConstWrite(SharedExpression target, int srcLine)
{
    if (!target) return;
    // The window's freeze rides this helper for the same reason the const rules do: it is on every write
    // path there is. Independent of the const arms below, so a write that is both gets both sentences.
    rejectFrozenWrite(target, srcLine);
    recordStaticWrite(target);   // the foreign-entry walk's write fact rides the same "every write path" helper
    std::string root = rootBinding(target);
    // A comptime parameter is a compile-time value, not storage — `F = 3` used to emit
    // `((int32_t)16) = 3` and die in clang against generated code. Reported here rather than through
    // `_constLocals` so the message fits an integer binder (the deep-const wording below is about
    // reaching THROUGH a binding, which this one has no inside to reach) — and because this one helper
    // is on every write path there is: assignment, compound assignment, `++`/`--`, and `ref`/`out` args.
    const auto* tid = dynamic_cast<IdentifierNode*>(target.get());
    const bool externConst = tid && tid->value && !_localTypes.count(*tid->value) && !_paramNames.count(*tid->value)
                          && !resolveExternConst(*tid->value, tid->qualifier).empty();
    if (!root.empty() && _comptimeSubst.count(root))
        unsupported(("cannot assign to `" + root + "` — it is a comptime parameter, a compile-time "
                     "value fixed at instantiation").c_str(), srcLine);
    else if (externConst)
        unsupported(("cannot assign to `" + *tid->value + "` — it is an `extern const`, a constant the C header "
                     "defines").c_str(), srcLine);
    else if (rootIsConst(root))
        unsupported(("cannot write to `const " + root + "` (const is deep — neither the "
                     "binding nor anything reached through it may be mutated)").c_str(), srcLine);
    else if (!_inNamedCtorBody && isConstFieldWrite(target))
        unsupported("cannot assign to a `const` field outside the constructor", srcLine);
    // The read-only raw pointer. The root binding may be perfectly mutable — `UnsafeConstPtr<uint8> p`
    // is an ordinary local — and it is the `[i]` step that reaches memory this pointer only reads.
    else if (chainThroughConstRawPtr(target))
        unsupported("cannot store through `UnsafeConstPtr<T>` — it is a read-only pointer. Take the "
                    "mutable form where the pointer was made (`dataPtrMut()`, `viewMut()`), or "
                    "`cast<UnsafePtr<T>>(…)` in an `unsafe fn` to say the launder out loud", srcLine);
    // The read-only PLACE: a `const ref T` call or `operator[]` somewhere in the chain. Like the const raw
    // pointer, the root binding may be mutable — the call is what narrowed it.
    else if (chainThroughConstPlace(target))
        unsupported("cannot write through a `const ref` place — it is read-only. Take the mutable form "
                    "where the place was made (the `…Mut` twin, e.g. `getRefMut`), or return `ref T` from "
                    "a non-const method", srcLine);
}

// a non-const method may not be invoked on a const receiver (it could mutate). A receiver reached
// THROUGH a const raw pointer (`p[i].bump()`) is one too: the method would take `&p[i]` as a writable
// `self` out of memory the pointer only reads.
bool CEmitter::isConstReceiver(SharedExpression receiver)
{
    return receiver && (rootIsConst(rootBinding(receiver)) || chainThroughConstRawPtr(receiver)
                        || chainThroughConstPlace(receiver));
}

// ---- `UnsafeConstPtr<T>` — the read-only raw pointer ----------------------------------------------
// It lowers to `T const*` (see the cType arm, which explains the east-const), which is what makes "is
// this C type a const raw pointer" an exact suffix test — `uint8_t const*` yes, `uint8_t const**` no
// (that is a mutable pointer to const pointers, and storing through it is fine).
bool CEmitter::isRawPtrName(const std::string& v)           { return v == "UnsafePtr" || v == "UnsafeConstPtr"; }
bool CEmitter::isConstRawPtrName(const std::string& v)      { return v == "UnsafeConstPtr"; }
bool CEmitter::isRawPtrName(const SharedIdentifier& t)      { return t && t->value && isRawPtrName(*t->value); }
bool CEmitter::isConstRawPtrName(const SharedIdentifier& t) { return t && t->value && isConstRawPtrName(*t->value); }

bool CEmitter::isConstRawCType(const std::string& ct)
{
    static const std::string suf = " const*";
    return ct.size() > suf.size() && ct.compare(ct.size() - suf.size(), suf.size(), suf) == 0;
}

// A WRITABLE raw pointer: `T*` that is not const, not a view (a view is a struct) and not one of the
// struct pointers the emitter uses for its own plumbing. Mirrors the acquisition gate's test (emitInvocation).
bool CEmitter::isMutRawCType(const std::string& ct)
{
    return ct.size() > 1 && ct.back() == '*' && !isConstRawCType(ct) && !isViewCType(ct)
        && !isClass(ct) && !isInterface(ct);
}

// Does the expression's TYPE say "const raw pointer"? A cast names it, a call answers through the same
// resolver `exprClass` uses (`addr(of:)` included — see callReturnTypeRaw), and anything else is a place,
// typed by `lvalueCType` so a field resolves under its owner instance's type args. A "" from either means
// the rules stay silent and the C backstop (`-Werror=incompatible-pointer-types`, kama.driver.cpp) speaks.
bool CEmitter::exprIsConstRawPtr(SharedExpression e)
{
    if (!e) return false;
    if (auto* h = dynamic_cast<HandoffNode*>(e.get())) return exprIsConstRawPtr(h->value);
    if (auto* c = dynamic_cast<CastNode*>(e.get())) return isConstRawPtrName(c->type);
    if (auto* inv = dynamic_cast<InvocationNode*>(e.get())) return isConstRawCType(callReturnTypeRaw(inv));
    return isConstRawCType(lvalueCType(e));
}

// Does some `[i]` step of this place dereference a const raw pointer? `p[i]`, `p[i].f`, `this.p[i]`,
// `obj.p[i].g[j]` — a write there, or a non-const call on it, lands in memory the pointer only reads.
bool CEmitter::chainThroughConstRawPtr(SharedExpression e)
{
    if (!e) return false;
    if (auto* ea = dynamic_cast<ElementAccessNode*>(e.get())) {
        SharedExpression base = ea->expression ? ea->expression
                                               : std::static_pointer_cast<ExpressionNode>(ea->identifier);
        if (isConstRawCType(lvalueCType(base))) return true;
        return chainThroughConstRawPtr(base);
    }
    if (auto* ma = dynamic_cast<MemberAccessNode*>(e.get())) return chainThroughConstRawPtr(ma->expression);
    return false;
}

// `UnsafeConstPtr<T>` -> `UnsafePtr<T>` is the one raw-pointer conversion kama refuses (the reverse is
// implicit, as in C). Asked at every sink a raw pointer can land in — a local's initializer, an
// assignment, an argument, a `return` — the same list the containment rule enumerates. `dstCType` is the
// DECLARED destination; empty or unknown means stay silent and let the C backstop speak.
void CEmitter::rejectConstPtrWiden(const std::string& dstCType, SharedExpression src, const char* what, int line)
{
    if (dstCType.empty() || !isMutRawCType(dstCType) || !exprIsConstRawPtr(src)) return;
    unsupported((std::string("`UnsafeConstPtr<T>` does not convert to `UnsafePtr<T>` — ") + what
                 + " would make a read-only pointer writable. Take the mutable form where the pointer was "
                   "made (`dataPtrMut()`, `viewMut()`), or `cast<UnsafePtr<T>>(…)` in an `unsafe fn` to "
                   "say the launder out loud").c_str(), line);
}

// ---- `ConstView<T>` — the read-only window ----------------------------------------------------------
// The same seam one level up: `View<T>` is to `ConstView<T>` what `UnsafePtr<T>` is to `UnsafeConstPtr<T>`.
// Both stdlib windows are `type view`s (`isBorrow`), so isViewCType cannot tell them apart; the TEMPLATE
// can, identified structurally (viewTemplateKeyFor), never by a hardcoded path.
bool CEmitter::isConstViewCType(const std::string& ct)
{
    auto gi = _genericTypeInsts.find(ct);
    return gi != _genericTypeInsts.end() && !constViewTemplateKey().empty()
        && gi->second.templateKey == constViewTemplateKey();
}
bool CEmitter::isMutViewCType(const std::string& ct)
{
    auto gi = _genericTypeInsts.find(ct);
    return gi != _genericTypeInsts.end() && !viewTemplateKey().empty()
        && gi->second.templateKey == viewTemplateKey();
}
// `dst` is `ConstView<X>` and `src` is `View<X>` — the one implicit conversion between the two.
bool CEmitter::constViewOf(const std::string& dstCType, const std::string& srcCType)
{
    if (dstCType == srcCType || !isConstViewCType(dstCType) || !isMutViewCType(srcCType)) return false;
    const auto& d = _genericTypeInsts[dstCType].typeArgs;
    const auto& s = _genericTypeInsts[srcCType].typeArgs;
    return d.size() == 1 && s.size() == 1 && d[0] && s[0] && mangleElem(d[0]) == mangleElem(s[0]);
}
// Spell the narrowing at a sink: `View_X__narrow(<emitted>)` — the stdlib's own by-value thunk (view.kama),
// which is why an rvalue source (`f(bytes: v.slice(…))`) is evaluated exactly once and no lvalue is needed.
// Anything else — a source already a `ConstView`, an unrelated value — passes through untouched. Asked at
// every sink a value lands in: an argument, a local's initializer, an assignment, a `return`/`match` arm —
// the list rejectConstPtrWiden rides. The reverse direction is rejectClassIdentityMismatch's.
std::string CEmitter::narrowViewValue(const std::string& dstCType, SharedExpression src,
                                      const std::string& emitted, int line)
{
    if (dstCType.empty() || !src) return emitted;
    const std::string sc = exprClass(src);
    if (sc.empty() || !constViewOf(dstCType, sc)) return emitted;
    MethodInfo* mi = findMethod(&_classes[sc], "narrow", nullptr);
    if (!mi) {   // a `View` without its thunk is not the shipped view.kama — say so rather than emit a bad C cast
        unsupported(("`" + demangleForDisplay(sc) + "` has no `narrow` — the stdlib `View<T>` supplies the "
                     "by-value narrowing this conversion is spelled with").c_str(), line);
        return emitted;
    }
    return mi->cName + "(" + emitted + ")";
}

// --- Never-null definite assignment for `Owned`/`Shared` fields (Stage 1) ------------------------------
// `Owned<T>`/`Shared<T>` are never-null: every such field must be assigned before the constructor returns,
// and must not be read before it is assigned. `Weak<T>` (nullable, `tryUpgrade`) is exempt. v1 tracks
// unconditional (top-level) assignment — the common straight-line ctor; a field assigned only inside a
// branch is conservatively treated as unassigned (path-sensitive analysis is a follow-up).

// If `e` is `this.<field>` or a bare `<field>` (not shadowed by a local) naming a data member of `owner`,
// return the field name; else "".
std::string CEmitter::ctorFieldRef(SharedExpression e, ClassInfo& owner, const std::set<std::string>& locals)
{
    if (!e) return "";
    ASTNode* n = e.get();
    if (auto* ma = dynamic_cast<MemberAccessNode*>(n)) {
        if (ma->expression && dynamic_cast<ThisAccessNode*>(ma->expression.get())
            && ma->identifier && ma->identifier->value && owner.fieldNames.count(*ma->identifier->value))
            return *ma->identifier->value;
    } else if (auto* id = dynamic_cast<IdentifierNode*>(n)) {
        if (id->value && (!id->qualifier || id->qualifier->empty())
            && !locals.count(*id->value) && owner.fieldNames.count(*id->value))
            return *id->value;
    }
    return "";
}

// Recursively record (first hit wins, in `bad`/`badLine`) a READ of an owning field not yet in `assigned`.
void CEmitter::scanOwningReads(SharedExpression e, ClassInfo& owner, const std::set<std::string>& owning,
                               const std::set<std::string>& assigned, const std::set<std::string>& locals,
                               std::string& bad, int& badLine)
{
    if (!e || !bad.empty()) return;
    ASTNode* n = e.get();
    std::string f = ctorFieldRef(e, owner, locals);
    if (!f.empty()) { if (owning.count(f) && !assigned.count(f)) { bad = f; badLine = e->line; } return; }
    auto rec = [&](SharedExpression x){ scanOwningReads(x, owner, owning, assigned, locals, bad, badLine); };
    if (auto* oc = dynamic_cast<ObjectCreationNode*>(n)) {
        if (oc->args) for (auto& a : *oc->args) if (a) rec(a->expression);
    } else if (auto* c = dynamic_cast<CastNode*>(n)) { rec(c->unaryExpression);
    } else if (auto* b = dynamic_cast<BinaryExpressionNode*>(n)) { rec(b->LHS); rec(b->RHS);
    } else if (auto* l = dynamic_cast<LogicalAndOrNode*>(n)) { rec(l->LHS); rec(l->RHS);
    } else if (auto* tn = dynamic_cast<TernaryExpressionNode*>(n)) { rec(tn->condition); rec(tn->LHS); rec(tn->RHS);
    } else if (auto* as = dynamic_cast<AssignmentNode*>(n)) {
        // the LHS of a direct `this.f = …` is a WRITE, not a read — skip it; else scan (write-through reads f)
        if (ctorFieldRef(as->unaryExpression, owner, locals).empty()) rec(as->unaryExpression);
        rec(as->expression);
    } else if (auto* inv = dynamic_cast<InvocationNode*>(n)) {
        rec(inv->expression);
        if (inv->args) for (auto& a : *inv->args) if (a) rec(a->expression);
    } else if (auto* ea = dynamic_cast<ElementAccessNode*>(n)) {
        rec(ea->expression);
        if (ea->expressionlist) for (auto& x : *ea->expressionlist) rec(x);
    } else if (auto* ma = dynamic_cast<MemberAccessNode*>(n)) { rec(ma->expression);
    } else if (auto* pe = dynamic_cast<PreIncrDecrNode*>(n)) { rec(pe->expression);
    } else if (auto* po = dynamic_cast<PostIncrDecrNode*>(n)) { rec(po->expression);
    } else if (auto* su = dynamic_cast<SimpleUnaryExpressionNode*>(n)) { rec(su->expression);
    } else if (auto* al = dynamic_cast<ArrayLiteralNode*>(n)) {
        if (al->elements) for (auto& x : *al->elements) rec(x);
        rec(al->fillValue);
    }
}

// Walk one ctor statement: check its reads against `assigned`, record a top-level `this.f = …`, track locals.
void CEmitter::analyzeCtorStmt(SharedStatement st, ClassInfo& owner, const std::set<std::string>& owning,
                               std::set<std::string>& assigned, std::set<std::string>& locals, bool topLevel)
{
    if (!st) return;
    ASTNode* n = st.get();
    auto checkE = [&](SharedExpression e){
        std::string bad; int line = 0;
        scanOwningReads(e, owner, owning, assigned, locals, bad, line);
        if (!bad.empty())
            unsupported(("'" + bad + "' is used before it is assigned in the constructor "
                         "(`Owned`/`Shared` are never-null)").c_str(), line ? line : st->line);
    };
    if (auto* as = dynamic_cast<AssignmentNode*>(n)) {
        std::string tgt = ctorFieldRef(as->unaryExpression, owner, locals);
        if (tgt.empty()) checkE(as->unaryExpression);   // a write-through LHS may itself read a field
        checkE(as->expression);
        if (!tgt.empty() && topLevel) assigned.insert(tgt);
    } else if (auto* lv = dynamic_cast<LocalVariableDeclaration*>(n)) {
        if (lv->variables) for (auto& v : *lv->variables) if (v) {
            checkE(v->initializer);
            if (v->name && v->name->value) locals.insert(*v->name->value);
        }
    } else if (auto* iff = dynamic_cast<IfNode*>(n)) {
        checkE(iff->booleanExpression);
        analyzeCtorStmt(iff->ifStatement, owner, owning, assigned, locals, false);
        analyzeCtorStmt(iff->elseStatement, owner, owning, assigned, locals, false);
    } else if (auto* wh = dynamic_cast<WhileNode*>(n)) {
        checkE(wh->booleanExpression);
        analyzeCtorStmt(wh->whileStatement, owner, owning, assigned, locals, false);
    } else if (auto* blk = dynamic_cast<BlockNode*>(n)) {
        if (blk->statements) for (auto& s : *blk->statements)
            analyzeCtorStmt(s, owner, owning, assigned, locals, topLevel);
    } else if (dynamic_cast<ExpressionStatementNode*>(n)) {
        checkE(std::dynamic_pointer_cast<ExpressionNode>(st));   // Invocation / incr / etc. — scan its reads
    }
    // (for/foreach/match/early-return: not modeled in v1 — the ctor-end assignment check still holds)
}

// Construction-model M8b: is a field of concrete type `c` DEFAULT-FILLABLE — i.e. may a ctor leave it
// unassigned (the compiler supplies its default) rather than requiring an explicit assignment?
//   - not a user aggregate (primitive, raw `UnsafePtr<T>`, enum): YES — zero is a valid value (deref is `unsafe`).
//   - an intrinsic collection (`List`/`Array`/`String`/`Weak`/…): YES — zero is a valid EMPTY value.
//   - a user type with an explicit `default` ctor: YES — the default designates a valid zero-arg build.
//   - otherwise (a value with no `default`, e.g. a stateful `BumpAllocator`): NO — a zero handle is garbage,
//     so it must be assigned. This is the M7.2 allocator footgun, gated structurally per instantiation.
// Owning pointers (`Owned`/`Shared`) are handled by the caller's never-null set, NOT here.
bool CEmitter::isDefaultFillable(const std::string& c)
{
    auto it = _classes.find(c);
    if (it == _classes.end()) return true;                 // primitive / UnsafePtr / enum-not-in-_classes
    ClassInfo& fc = it->second;
    if (fc.isIntrinsicColl) return true;                   // zero = valid empty collection / null Weak
    // Scan `methods` (NOT `ctors`): the `when [A: default]` gate (registerGenericTypeInst) drops a gated-away
    // `empty()` from `methods` per-monomorph but leaves it in `ctors`, so `methods` is the gate-ACCURATE set.
    // A custom-`A` collection whose `default` ctor was gated off is therefore correctly NOT default-fillable.
    for (auto& kv : fc.methods) if (kv.second.isDefaultCtor) return true;
    return false;
}

// Enforce complete-init on a NAMED ctor (`ctor make(…)`) — a static factory returning the enclosing type
// (or `Result<This,E>`). This is the ONLY ctor shape the language has: a factory builds a value via a
// `slot` local + field assignments, or returns a fresh object by DELEGATION
// (`return Other.make(…)`). The one hole to close: returning a bare zero-inited local whose owning
// (`Owned`/`Shared`) field was never set — that would leak a null owning pointer past construction.
//
// The rule (delegation-aware, sound top-level-only discipline): the returned
// value is COMPLETE unless it is a local that was declared bare (no constructing initializer) and is missing
// an unconditional assignment to some owning field. Any construction / factory call / param is trusted
// complete — it came through something that itself satisfies the guarantee. (There is no back door left:
// a self-returning `static fn` is rejected outright as a disguised constructor, so `ctor` is the only way
// a value of a type comes into being.)
// A derived type's constructor must INSTALL its base: `this.base = Base.<ctor>(…);`, as the very first
// statement. This is the other half of complete initialization — `checkNamedCtorComplete` proves every OWN
// field is assigned and says nothing about inherited ones, which is why a base's invariants were
// unenforceable for its subclasses.
//
// A sibling of that function rather than an extension of it: its machinery is per-FIELD, and it returns
// early when the type has no field that must be assigned — which is most derived types in the corpus, so
// a base obligation seeded into it would simply never be checked.
void CEmitter::checkBaseInstall(ClassInfo& owner, SharedBlock body, int ctorLine)
{
#if KAMA_INHERITANCE
    if (!owner.base || !body) return;
    // An EMPTY body is the case that matters most, not one to skip: `public ctor make() { }` on a derived
    // type is precisely the shape that used to leave a base zero-filled. `statements` is null, not an
    // empty list, when a ctor body is empty.
    const size_t n = body->statements ? body->statements->size() : 0;

    // A ctor that hands off wholesale (`return Other.make(…);`) constructs nothing itself, so it owes no
    // base — the ctor it delegates to owes one. Same doctrine as checkNamedCtorComplete's `classify`.
    if (n == 1 && dynamic_cast<ReturnNode*>(body->statements->front().get()))
        return;

    SharedExpression rhs = n ? baseInstallOf(body->statements->front()) : SharedExpression();

    // Anywhere BUT first is its own mistake, and deserves its own sentence.
    for (size_t i = 1; i < n; ++i) {
        if (!baseInstallOf((*body->statements)[i])) continue;
        if (rhs)
            unsupported(("the base of '" + owner.name + "' is installed exactly once — this second "
                         "`this.base` would discard the '" + owner.baseName + "' already built").c_str(),
                        (*body->statements)[i]->line);
        else
            unsupported(("`this.base` must be the FIRST statement of the constructor — until it runs, "
                         "every inherited member of '" + owner.name + "' reads from a half-built '"
                         + owner.baseName + "'").c_str(), (*body->statements)[i]->line);
        return;
    }

    if (!rhs) {
        if (owner.base->ctors.empty())
            unsupported(("'" + owner.name + "' cannot be constructed: its base '" + owner.baseName
                         + "' has no constructor, so there is nothing to install — give '" + owner.baseName
                         + "' a `ctor`").c_str(), ctorLine);
        else
            unsupported(("the base '" + owner.baseName + "' is never constructed — install it as the first "
                         "statement of this constructor: `this.base = Base.<ctor>(…);`").c_str(), ctorLine);
        return;
    }

    // The right-hand side is a CONSTRUCTOR CALL on the base type, and nothing else. Not a general
    // assignment: a base part is built by its own ctor or not at all, and base fields are private, so
    // there would be nothing to adjust afterwards anyway.
    auto* call = dynamic_cast<InvocationNode*>(rhs.get());
    auto* recv = call ? dynamic_cast<MemberAccessNode*>(call->expression.get()) : nullptr;
    if (!recv) {
        unsupported(("`this.base` takes a constructor call on '" + owner.baseName
                     + "' (`this.base = Base.<ctor>(…);`) — it is not a general assignment").c_str(),
                    rhs->line);
        return;
    }
    std::string recvType;
    if (!isTypeReceiver(recv, recvType) || recvType != owner.baseName) {
        unsupported(("`this.base` in '" + owner.name + "' installs a '" + owner.baseName + "', but this "
                     "builds a '" + (recvType.empty() ? std::string("value of another kind") : recvType)
                     + "'").c_str(), rhs->line);
        return;
    }
    // `this` does not exist yet where the install is emitted — the arguments run before `self` is bound.
    if (call->args) {
        for (auto& a : *call->args)
            if (a && a->expression && exprMentionsThis(a->expression)) {
                unsupported(("the base install runs before `this` exists — `" + owner.baseName
                             + "`'s constructor may read this constructor's parameters, not "
                               "`this.<field>`").c_str(), rhs->line);
                return;
            }
    }
#else
    (void)owner; (void)body; (void)ctorLine;
#endif
}

void CEmitter::checkNamedCtorComplete(ClassInfo& owner, SharedBlock body)
{
    std::set<std::string> owning;       // Owned/Shared fields — never-null (drives the sharper message)
    std::set<std::string> noDefault;    // fields whose TYPE has no `default` — also a sharper message
    std::set<std::string> mustAssign;   // force-explicit-field-init: every field, minus the two escape hatches
    // Force-explicit-field-init: a field must be ASSIGNED unless its type carries a default the compiler
    // actually supplies. Precedent is Rust (all fields required), Swift (definite initialization), Zig,
    // C# structs. The carve-out that goes away is the silent one — a primitive, a raw `UnsafePtr`, or an enum
    // used to ride on the emitted `= {0}`, so `int32 len;` and `UnsafePtr<T> data;` were *implicitly* 0/null and
    // nothing said whether the author meant that. Those must now be spelled.
    //
    // What stays exempt is not a carve-out but a real, checked guarantee:
    //   - an INTRINSIC COLLECTION, whose zero representation IS its valid empty value;
    //   - a user type with a `default` ctor, which the compiler CALLS at the fill site (M8d.1) — and which
    //     a generic field could not spell anyway: there is no expression for "the default `A`", so
    //     requiring `r.alloc = …` in `empty()` would be unsatisfiable, not merely verbose.
    //
    // Two escape hatches, both explicit and both at the DECLARATION rather than hidden in codegen:
    //   - a field initializer (`int32 len = 0;` / `UnsafePtr<T> data = null;`) states the default once, at the
    //     field, and runs in every ctor — so a container spells its empty state instead of inheriting it;
    //   - `@generate(zero)` blesses a whole data bag's zero state (a transparent all-public `value`, which
    //     therefore owns nothing — so this can never skip an `Owned`/`Shared`).
    for (auto& f : owner.fields) {
        std::string fc = cType(f.type);                                       // resolves a field-`T`/`A` per instance
        bool isOwning = !heapOwnerTarget(fc).empty();                         // Owned/Shared (not Weak)
        bool bare     = !_classes.count(fc);                                  // primitive / raw `UnsafePtr` / enum
        if (isOwning)                      owning.insert(f.name);
        else if (!isDefaultFillable(fc))   noDefault.insert(f.name);          // e.g. a stateful `A alloc`
        // declared default / blessed zero bag / a C struct, which a ctor on it zero-fills (KR-53): the header owns
        // the layout and kama may declare only the fields it uses, so "every field" is not kama's to demand.
        if (f.initializer || owner.genZero || owner.isExternStruct) continue;
        if (isOwning || bare || !isDefaultFillable(fc)) mustAssign.insert(f.name);
    }
    if (mustAssign.empty() || !body || !body->statements) return;             // nothing to seal

    std::set<std::string> ownerLocals;                       // locals whose declared type is this owner
    std::set<std::string> completeByInit;                    // ownerLocals declared with a constructing initializer
    std::map<std::string, std::set<std::string>> assigned;   // ownerLocal -> owning fields set (top-level only)

    // `x.f` written as `local.field` — return {local, field} when x is a tracked owner-local; else {"",""}.
    auto localFieldRef = [&](SharedExpression e) -> std::pair<std::string, std::string> {
        auto* ma = dynamic_cast<MemberAccessNode*>(e.get());
        if (!ma || !ma->identifier || !ma->identifier->value) return {"", ""};
        // `this.field = …` — the value under construction has no DECLARATION, so it is keyed by the name
        // it is spelled with. `ownerLocals` holds declared locals; `this` is always in play in a ctor.
        if (dynamic_cast<ThisAccessNode*>(ma->expression.get())) return {"this", *ma->identifier->value};
        auto* id = dynamic_cast<IdentifierNode*>(ma->expression.get());
        if (!id || !id->value || (id->qualifier && !id->qualifier->empty())) return {"", ""};
        if (!ownerLocals.count(*id->value)) return {"", ""};
        return {*id->value, *ma->identifier->value};
    };

    // The first `mustAssign` field this key has not been credited with, in declaration order ("" if none).
    auto missingField = [&](const std::string& key) -> std::string {
        auto& done = assigned[key];
        for (auto& f : owner.fields)
            if (mustAssign.count(f.name) && !done.count(f.name)) return f.name;
        return "";
    };
    auto reportMissing = [&](const std::string& bad, int line) {
        if (owning.count(bad))
            unsupported(("'" + bad + "' must be set before the constructor returns "
                         "(`Owned`/`Shared` are never-null)").c_str(), line);
        else if (noDefault.count(bad))
            unsupported(("'" + bad + "' has no `default` — assign it in the constructor "
                         "(or give its type a `default ctor`)").c_str(), line);
        else
            unsupported(("'" + bad + "' is never assigned — a constructor must initialize every "
                         "field; assign it here, or declare the field's default at the field "
                         "(`T " + bad + " = …;`)").c_str(), line);
    };

    // Classify a RETURNED value expression: report the first missing owning field (via `bad`), or leave empty.
    std::function<void(SharedExpression, std::string&, int&)> classify =
        [&](SharedExpression e, std::string& bad, int& badLine) {
        if (!e || !bad.empty()) return;
        // `return give m` / `return copy m` — collections consume the built local through a HandoffNode.
        // Unwrap to the inner value so the bare-owner-local check below runs (else the gate silently skips
        // every collection factory — the second half of why the gate was inert for generics).
        if (auto* h = dynamic_cast<HandoffNode*>(e.get())) { classify(h->value, bad, badLine); return; }
        // `Result::Ok(value: V)` — check V; `Result::Err(…)` — no object exists, accept.
        if (auto* iv = dynamic_cast<InvocationNode*>(e.get())) {
            if (iv->identifier && iv->identifier->value && iv->identifier->qualifier
                && !iv->identifier->qualifier->empty() && *iv->identifier->qualifier->back() == "Result") {
                const std::string& v = *iv->identifier->value;
                if (v == "Err") return;                                  // failure carries no object
                if (v == "Ok" && iv->args) {
                    SharedExpression inner;
                    for (auto& a : *iv->args) if (a) {
                        if (a->name && a->name->value && *a->name->value == "value") { inner = a->expression; break; }
                        if (!inner) inner = a->expression;               // fallback: first positional arg
                    }
                    classify(inner, bad, badLine);
                    return;
                }
            }
        }
        // `return give this;` — the ctor's EARLY-return form. Same proof as a returned owner-local, on the
        // value the ctor is obliged to complete.
        if (dynamic_cast<ThisAccessNode*>(e.get())) {
            std::string m = missingField("this");
            if (!m.empty()) { bad = m; badLine = e->line; }
            return;
        }
        // A returned bare owner-local: require every owning field assigned (unless complete-by-init).
        if (auto* id = dynamic_cast<IdentifierNode*>(e.get())) {
            if (id->value && (!id->qualifier || id->qualifier->empty()) && ownerLocals.count(*id->value)) {
                if (completeByInit.count(*id->value)) return;
                std::string m = missingField(*id->value);
                if (!m.empty()) { bad = m; badLine = e->line; }
                return;
            }
        }
        // else — a construction / delegating factory call / param: complete by delegation.
    };

    std::function<void(SharedStatement, bool)> walk = [&](SharedStatement st, bool topLevel) {
        if (!st) return;
        ASTNode* n = st.get();
        if (auto* lv = dynamic_cast<LocalVariableDeclaration*>(n)) {
            // Match BOTH forms: a concrete owner via `resolveUserName` (template name == owner.name), AND a
            // GENERIC owner via `cType` — for a monomorph, `owner.name` is the mangled instance
            // (`DynamicArray_int32_BumpAllocator`) but `resolveUserName` yields the bare TEMPLATE, so it never
            // matched → the whole gate was inert for generics (M8c finding). `cType(lv->type)` resolves the
            // local's `DynamicArray<T,A>` under the active instance subst to that same mangled name.
            bool isOwnerTy = lv->type && lv->type->value
                             && (resolveUserName(*lv->type->value, lv->type->qualifier) == owner.name
                                 || cType(lv->type) == owner.name);
            if (isOwnerTy && lv->variables)
                for (auto& v : *lv->variables) if (v && v->name && v->name->value) {
                    ownerLocals.insert(*v->name->value);
                    if (v->initializer) completeByInit.insert(*v->name->value);   // built by delegation at decl
                }
        } else if (auto* as = dynamic_cast<AssignmentNode*>(n)) {
            if (topLevel) {
                std::pair<std::string, std::string> lf = localFieldRef(as->unaryExpression);
                if (!lf.first.empty() && mustAssign.count(lf.second)) assigned[lf.first].insert(lf.second);
            }
        } else if (auto* ret = dynamic_cast<ReturnNode*>(n)) {
            std::string bad; int line = 0;
            classify(ret->expression, bad, line);
            if (!bad.empty()) reportMissing(bad, line ? line : st->line);
        } else if (auto* iff = dynamic_cast<IfNode*>(n)) {
            walk(iff->ifStatement, false);                    // branch bodies don't count as unconditional assigns
            walk(iff->elseStatement, false);
        } else if (auto* wh = dynamic_cast<WhileNode*>(n)) {
            walk(wh->whileStatement, false);
        } else if (auto* blk = dynamic_cast<BlockNode*>(n)) {
            if (blk->statements) for (auto& s : *blk->statements) walk(s, topLevel);
        }
        // (for/foreach/match: not modeled — a returned bare-incomplete local through them stays conservative)
    };
    SharedStatement last;
    for (auto& st : *body->statements) { walk(st, true); last = st; }

    // Falling off the end of a ctor returns the value it built (the implicit `this`), so that value must be
    // complete AT THAT POINT — the same proof a written `return give this;` gets, at the return the author
    // did not write. The condition mirrors the emitter's exactly (kama.cemit.cpp, emitMethodOrCtorBody):
    // wherever it emits `return __self;`, this has proven `__self` complete. A ctor that ends in a `return`
    // was already checked by the ReturnNode arm; one that delegates never credits `this` and would be
    // flagged here, which is correct — a delegating ctor returns, it does not fall off the end.
    if (!(last && stmtIsJump(last))) {
        std::string bad = missingField("this");
        if (!bad.empty()) reportMissing(bad, last ? last->line : body->line);
    }
}

// Option-B view-ctor escape check. A `type view` ctor is a factory: it builds a local view and RETURNS it
// (the M8 construction model). The returned view borrows through its `UnsafePtr`/nested-view fields — each must
// trace to a PARAMETER (a by-value `UnsafePtr`/view param points at caller-owned memory that outlives the call)
// or `this`, never a ctor-LOCAL (whose buffer dies at return -> dangle). Pure structural root-tracing
// (north star 3e — no lifetime analysis): the ctor-body analog of the emit-time fn check at the ReturnNode,
// mirroring checkNamedCtorComplete's top-level-only discipline (a borrow assigned only inside a branch is
// unprovable -> conservatively rejected). Keeps `type view` as a sound second-class borrow through a factory.
void CEmitter::checkViewCtorEscape(ClassInfo& owner, ClassMethodDeclarationNode* mnode)
{
    if (!mnode || !mnode->body || !mnode->body->statements) return;

    std::set<std::string> borrowFields;                      // fields that can dangle: raw `UnsafePtr<T>` or a `type view`
    for (auto& f : owner.fields)
        if (f.type && f.type->value && (isRawPtrName(*f.type->value) || isViewCType(cType(f.type))))
            borrowFields.insert(f.name);
    if (borrowFields.empty()) return;                        // nothing borrowable -> nothing to check

    // This check runs ONLY for a ctor, and a ctor's `this` is the view being built — its storage is the
    // returned value, so a pointer into it dangles just as a pointer into a local does. That leaves the
    // parameters as the only candidate roots, but NOT all of them: a BY-VALUE parameter (`int64 v`) is the
    // callee's own frame, dead the moment the constructor returns, so
    //
    //     public ctor over(int64 v) { this.p = addr(of: v); this.n = 1; }
    //
    // dangles exactly as a local would — and no `return` of the view is needed to observe it, because it is
    // the CONSTRUCTOR's frame that died. This test used to be "is it a parameter?", which accepted that.
    // Only a parameter the view could actually borrow FROM counts: a `ref`/`out` (the caller's storage), a
    // raw `UnsafePtr<T>`, or another view. Same question checkViewContractCtors asks of a contract's ctor slot,
    // so it is the same predicate; the empty `selfParam` is the pinned-contract case, which has no meaning
    // here (a parameter of this view's own type is already matched by `_viewTypeNames`).
    std::set<std::string> params;                            // param names that can carry a borrow
    std::set<std::string> allParams;                         // every param name — only to tell the two failures apart
    if (mnode->params) for (auto& p : *mnode->params)
        if (p->identifier && p->identifier->value) {
            allParams.insert(*p->identifier->value);
            if (paramCanCarryBorrow(p.get(), std::string())) params.insert(*p->identifier->value);
        }
    auto safeRoot = [&](const std::string& r) { return params.count(r) > 0; };

    std::set<std::string> viewLocals;                        // locals of THIS view type (the object being built)
    std::map<std::string, std::map<std::string, std::string>> borrowRoot;   // local -> borrow-field -> root of its RHS

    // `local.field` on a tracked view local -> {local, field}; else {"",""}.
    auto localFieldRef = [&](SharedExpression e) -> std::pair<std::string, std::string> {
        auto* ma = dynamic_cast<MemberAccessNode*>(e.get());
        if (!ma || !ma->identifier || !ma->identifier->value) return {"", ""};
        // `this.field` — the view under construction, which needs no declaration.
        if (dynamic_cast<ThisAccessNode*>(ma->expression.get())) return {"this", *ma->identifier->value};
        auto* id = dynamic_cast<IdentifierNode*>(ma->expression.get());
        if (!id || !id->value || (id->qualifier && !id->qualifier->empty())) return {"", ""};
        if (!viewLocals.count(*id->value)) return {"", ""};
        return {*id->value, *ma->identifier->value};
    };

    // Every borrow field of `key` must trace to a borrowable parameter; an unset one traces nowhere and is
    // rejected. The two ways to fail want DIFFERENT messages: telling an author who borrowed `int64 v` that
    // a constructor "may only borrow its parameters" describes what they already did, and sends them
    // looking in the wrong place.
    auto checkBorrows = [&](const std::string& key, int line) {
        auto& roots = borrowRoot[key];
        for (auto& f : owner.fields) {
            if (!borrowFields.count(f.name)) continue;
            auto it = roots.find(f.name);
            std::string r = it == roots.end() ? "" : it->second;   // an unset borrow field -> "" -> reject
            if (safeRoot(r)) continue;
            if (allParams.count(r))
                unsupported(("a view borrows its buffer, and `" + r + "` is passed BY VALUE — it lives in "
                             "this constructor's own frame and dies when it returns, so the view would "
                             "dangle just as it would over a local. Borrow something that outlives the "
                             "call: a `ref`/`out` parameter, an `UnsafePtr<T>`, or another view").c_str(), line);
            else
                unsupported("a view borrows its buffer, so a view constructor may only borrow its "
                            "parameters — returning a view over a local would dangle", line);
        }
    };

    std::function<void(SharedStatement, bool)> walk = [&](SharedStatement st, bool topLevel) {
        if (!st) return;
        ASTNode* n = st.get();
        if (auto* lv = dynamic_cast<LocalVariableDeclaration*>(n)) {
            bool isViewTy = lv->type && cType(lv->type) == owner.name;    // `View<T> r;` under the active subst
            if (isViewTy && lv->variables)
                for (auto& v : *lv->variables) if (v && v->name && v->name->value)
                    viewLocals.insert(*v->name->value);
        } else if (auto* as = dynamic_cast<AssignmentNode*>(n)) {
            if (topLevel) {
                std::pair<std::string, std::string> lf = localFieldRef(as->unaryExpression);
                if (!lf.first.empty() && borrowFields.count(lf.second))
                    borrowRoot[lf.first][lf.second] = borrowArgRoot(as->expression);
            }
        } else if (auto* ret = dynamic_cast<ReturnNode*>(n)) {
            SharedExpression e = ret->expression;
            if (e) if (auto* h = dynamic_cast<HandoffNode*>(e.get())) e = h->value;   // `return give r`
            if (e && dynamic_cast<ThisAccessNode*>(e.get())) { checkBorrows("this", ret->line); return; }
            auto* id = e ? dynamic_cast<IdentifierNode*>(e.get()) : nullptr;
            if (id && id->value && (!id->qualifier || id->qualifier->empty()) && viewLocals.count(*id->value))
                checkBorrows(*id->value, ret->line);
        } else if (auto* iff = dynamic_cast<IfNode*>(n)) {
            walk(iff->ifStatement, false);                    // branch bodies don't count as unconditional
            walk(iff->elseStatement, false);
        } else if (auto* wh = dynamic_cast<WhileNode*>(n)) {
            walk(wh->whileStatement, false);
        } else if (auto* blk = dynamic_cast<BlockNode*>(n)) {
            if (blk->statements) for (auto& s : *blk->statements) walk(s, topLevel);
        }
    };
    SharedStatement vlast;
    for (auto& st : *mnode->body->statements) { walk(st, true); vlast = st; }
    // Falling off the end returns the view under construction — the same escape, at the return the
    // author did not write. Without this the check simply stopped seeing view ctors once the value
    // they build lost its declaration.
    if (!(vlast && stmtIsJump(vlast))) checkBorrows("this", vlast ? vlast->line : mnode->body->line);
}

// Definite-assignment for LOCALS — the whole-function dual of the use-after-move check. Reading an owning
// (`Owned`/`Shared`) local, or an owning FIELD of a resource local, BEFORE it is assigned is a null-deref in
// safe code (M3 zero-inits a bare destructible local, so an owning pointer starts null). Flag any such READ
// that is not definitely (unconditionally, top-level) assigned at that point. Sound + conservative — a
// branch-body assignment doesn't count (mirrors analyzeCtorStmt/checkNamedCtorComplete's discipline). Params
// are trusted complete (only body-declared locals are tracked). `Weak` and raw `UnsafePtr` are never owning,
// so they are never tracked (box_basic stays legal).
//
// An `unsafe fn` relaxes LOCALS but NOT `out` parameters, and that split is load-bearing. Relaxation exists
// because a raw store is invisible to this walker, so an unsafe body's own initialization dance would
// otherwise read as a use-before-assign. Filling an `out`, by contrast, is a contract with the CALLER — and
// under this model safe code may call an `unsafe fn` freely, so relaxing `out` would hand every caller a
// hole full of uninitialized stack. That was finding 9: a top-level `unsafe { }` used to `unassigned.clear()`
// for the WHOLE function, and `verifyOutsAssigned` returned early, so an unfilled `out` passed `kama check`.
// The bug was that the relaxation's scope (the function) did not match the construct's (the block). Now that
// `unsafe` IS the function, function-wide relaxation of locals is correct BY CONSTRUCTION — and the `out`
// half simply stops being relaxed at all.
void CEmitter::checkDefiniteAssignment(SharedBlock body, SharedParameterList params)
{
    if (!body || !body->statements) return;

    std::set<std::string> bareOwning;                        // local whose OWN type is Owned/Shared
    std::map<std::string, std::set<std::string>> resFields;  // resource local -> its owning field names
    std::set<std::string> unassigned;                        // live keys: "x" (bare) or "x.f" (resource field)
    std::set<std::string> outParams;                         // `out` params — must be assigned by every return
    std::set<std::string> slotDecls;                         // locals declared `slot T x;` (any type)
    // Step 5's three rules. A `slot` names the storage an `out` parameter is about to fill, and nothing
    // else: it must be filled by an `out` argument (rule 1), it must be filled somewhere (rule 2), and the
    // fill must sit on the same unconditional path as the declaration (rule 3), so slot liveness is a
    // compile-time fact at every exit rather than something to test for at runtime.
    std::map<std::string, int> slotDeclLine;                  // slot -> its declaration line (for rule 2)
    std::map<std::string, int> slotDeclDepth;                 // slot -> conditional depth where declared
    std::set<std::string> slotOutFilled;                      // slots an `out` argument has filled
    int condDepth = 0;                                        // +1 inside a branch/loop body a path may skip
    auto slotFillRule = [&](const char* what, int line) { unsupported(what, line); };
    // Class-typed slots. Their storage is VALID-but-empty from the declaration on: the M8d.1 fill loop
    // applies field defaults, calls each field's `default` ctor, and sets the vptr. So handing one to a
    // callee (`collectKeys(dest: acc)` — a `ref` borrow the analysis can't see, since the `ref` marker is
    // optional) or reading a non-owning field of it (`result.alloc`) is safe. A PRIMITIVE slot has no such
    // fill and stays strictly read-before-assign.
    std::set<std::string> slotClassDecls;
    const bool inUnsafe = _inUnsafe;   // the ENCLOSING FUNCTION is `unsafe` (set by the caller)

    // An `out` parameter is the one param that is NOT trusted complete: it arrives as a hole the callee
    // owes a value to. Track it exactly like a bare owning local (reads are flagged) and additionally
    // verify at every return that it was filled.
    if (params) for (auto& p : *params) {
        if (!paramIsOut(p.get()) || !p->identifier || !p->identifier->value) continue;
        const std::string& pn = *p->identifier->value;
        bareOwning.insert(pn); unassigned.insert(pn); outParams.insert(pn);
    }

    // A ctor's `this` is the value under construction: its owning fields start EMPTY and reading one
    // before it is assigned is the same never-null violation as reading through an unassigned local.
    // Tracked under the key "this.f", exactly as a declared local's fields are under "r.f" — which is
    // what that shape was before the value stopped needing a declaration.
    if (_inNamedCtorBody && _currentClass) {
        for (auto& f : _currentClass->fields)
            if (!heapOwnerTarget(cType(f.type)).empty()) {
                resFields["this"].insert(f.name);
                unassigned.insert("this." + f.name);
            }
    }

    // `x.f` where x is a tracked resource local and f one of its owning fields -> key "x.f"; else "".
    auto fieldKey = [&](SharedExpression e) -> std::string {
        auto* ma = dynamic_cast<MemberAccessNode*>(e.get());
        if (!ma || !ma->identifier || !ma->identifier->value) return "";
        if (dynamic_cast<ThisAccessNode*>(ma->expression.get())) {
            auto ti = resFields.find("this");
            return (ti != resFields.end() && ti->second.count(*ma->identifier->value))
                   ? "this." + *ma->identifier->value : "";
        }
        auto* id = dynamic_cast<IdentifierNode*>(ma->expression.get());
        if (!id || !id->value || (id->qualifier && !id->qualifier->empty())) return "";
        auto it = resFields.find(*id->value);
        if (it == resFields.end() || !it->second.count(*ma->identifier->value)) return "";
        return *id->value + "." + *ma->identifier->value;
    };
    // The owning value this LHS assigns (so we don't treat it as a read): "x.f", or a bare owning local "x".
    // A field-write to a bare owning local (`b.p = raw` — how a HeapOwner's own factory builds it) CONSTRUCTS
    // that local, so it counts as assigning "b" (matches box_basic / the Owned::adopt prelude idiom).
    auto writeTargetKey = [&](SharedExpression e) -> std::string {
        std::string fk = fieldKey(e);
        if (!fk.empty()) return fk;
        if (auto* id = dynamic_cast<IdentifierNode*>(e.get()))                     // whole `b = …`
            if (id->value && (!id->qualifier || id->qualifier->empty()) && bareOwning.count(*id->value))
                return *id->value;
        if (auto* ma = dynamic_cast<MemberAccessNode*>(e.get()))                   // field write `b.f = …`
            if (auto* id = dynamic_cast<IdentifierNode*>(ma->expression.get()))
                if (id->value && (!id->qualifier || id->qualifier->empty()) && bareOwning.count(*id->value))
                    return *id->value;
        return "";
    };
    auto flag = [&](const std::string& key, int line) {
        if (inUnsafe) return;                                // the escape hatch owns its invariants
        if (outParams.count(key))
            unsupported(("'" + key + "' is an `out` parameter — it is write-only, so it cannot be read "
                         "before this function assigns it").c_str(), line);
        else if (slotDecls.count(key))
            unsupported(("'" + key + "' is used before it is assigned — a `slot` declares storage with no "
                         "value in it yet").c_str(), line);
        else
            unsupported(("'" + key + "' is used before it is assigned "
                         "(`Owned`/`Shared` are never-null)").c_str(), line);
    };
    // Every `out` parameter must be filled on the path reaching this point (a return, or falling off the
    // end). Reported per-parameter so a two-`out` function names the one actually missing.
    auto verifyOutsAssigned = [&](int line) {
        // NOT exempt in an `unsafe fn` — see the split above. A raw fill still counts: `addr(of: dst)`
        // marks the target assigned, which is how `Atomic.loadInto`'s type-erased C call satisfies this.
        for (auto& o : outParams)
            if (unassigned.count(o))
                unsupported(("`out` parameter '" + o + "' is not assigned on every path before this "
                             "function returns").c_str(), line);
    };
    auto markAssigned = [&](const std::string& nm){
        unassigned.erase(nm);
        auto it = resFields.find(nm);
        if (it != resFields.end()) for (auto& f : it->second) unassigned.erase(nm + "." + f);
    };
    // Stop tracking a name altogether — stronger than markAssigned, which only clears the CURRENT
    // unassigned set and is therefore undone when a skippable body (a loop, a lone `if`) restores it.
    // Used where the evidence is not path-dependent: handing a CLASS slot to a method or a callee says the
    // author is treating it as the live value it already is, and `foreach (…) { parts.add(…) }` — a
    // collection filled in a loop — must not be re-flagged at the read after the loop.
    auto untrack = [&](const std::string& nm){
        unassigned.erase(nm); bareOwning.erase(nm);
        slotDecls.erase(nm); slotClassDecls.erase(nm);
        auto it = resFields.find(nm);
        if (it != resFields.end()) { for (auto& f : it->second) unassigned.erase(nm + "." + f); resFields.erase(it); }
    };
    // `addr(of: x)` on a tracked owning local — the raw slot-init dance (memmove into a zero-init local, then
    // `give`) takes it under manual control; return its name so the caller marks it assigned.
    auto addrOfLocal = [&](InvocationNode* inv) -> std::string {
        if (!inv->identifier || !inv->identifier->value || *inv->identifier->value != "addr") return "";
        if (inv->identifier->qualifier && !inv->identifier->qualifier->empty()) return "";
        if (!inv->args || inv->args->size() != 1 || !(*inv->args)[0] || !(*inv->args)[0]->expression) return "";
        auto* id = dynamic_cast<IdentifierNode*>((*inv->args)[0]->expression.get());
        if (!id || !id->value || (id->qualifier && !id->qualifier->empty())) return "";
        return (bareOwning.count(*id->value) || resFields.count(*id->value)) ? *id->value : "";
    };

    // `f(p: out x)` — the marker says the CALLEE fills `x`, so this argument ASSIGNS it rather than
    // reading it. emitReorderedCall separately proves the marker matches a real `out` parameter, and that
    // callee's own verifyOutsAssigned proves it really is filled — so this is a genuine assignment, not a
    // vouch. Returns the tracked name, or "".
    auto outArgTarget = [&](ArgumentNode* a) -> std::string {
        if (!a || !a->modifier || !a->modifier->value || *a->modifier->value != "out") return "";
        auto* id = dynamic_cast<IdentifierNode*>(a->expression.get());
        if (!id || !id->value || (id->qualifier && !id->qualifier->empty())) return "";
        return (bareOwning.count(*id->value) || resFields.count(*id->value)) ? *id->value : "";
    };

    // Rule 1 — a `slot` is filled by an `out` argument and NOTHING else. Reported at the offending fill,
    // named for the mechanism used, so the message points at the spelling that replaces it.
    auto slotBadFill = [&](const std::string& nm, const char* how, const char* instead, int line) {
        if (!slotDecls.count(nm) || slotOutFilled.count(nm)) return;   // filled already: an ordinary value now
        slotFillRule(("`" + nm + "` is a `slot`, which only an `out` argument may fill — this " + how
                      + ". " + instead).c_str(), line);
        slotDecls.erase(nm);          // reported once; don't re-report the same hole at every later fill
        slotDeclLine.erase(nm);
    };
    // Rule 3 — the fill must sit on the same unconditional path as the declaration. Measured RELATIVE to
    // the declaration, so a slot declared and filled inside the same loop body is fine; what is rejected
    // is a fill a path can skip, which would make slot liveness a runtime question.
    auto slotOutFill = [&](const std::string& nm, int line) {
        if (!slotDecls.count(nm)) return;
        slotOutFilled.insert(nm);
        auto d = slotDeclDepth.find(nm);
        if (d != slotDeclDepth.end() && condDepth != d->second)
            slotFillRule(("`" + nm + "` is a `slot` filled inside a branch or loop the declaration is "
                          "outside of — an `out` fill must be on the same unconditional path, so the "
                          "value's liveness is decided at compile time").c_str(), line);
    };

    std::function<void(SharedExpression)> scan;
    std::function<void(SharedStatement, bool)> walk;

    // Walk a body that control may SKIP (a lone `if`, a loop, a match arm). Its reads must still be
    // checked, but nothing it assigns is definite afterwards — including the marks made by `addr(of: x)`
    // and by an `out` argument, which `scan` applies unconditionally wherever it finds them. Restoring
    // the set is what keeps those two from leaking out of a branch that may never run.
    auto walkSkippable = [&](SharedStatement s) {
        std::set<std::string> before = unassigned;
        ++condDepth;          // a path may skip this body — a slot fill inside it is not unconditional
        walk(s, true);        // INSIDE the branch, sequencing is definite — `q = …; return;` must count…
        --condDepth;
        unassigned = before;  // …but nothing it did survives the join.
    };

    // Recursively flag reads of still-unassigned owning values inside an expression.
    scan = [&](SharedExpression e) {
        if (!e) return;
        ASTNode* n = e.get();
        std::string fk = fieldKey(e);
        if (!fk.empty()) { if (unassigned.count(fk)) flag(fk, e->line); return; }   // don't recurse into base
        if (auto* id = dynamic_cast<IdentifierNode*>(n)) {
            if (id->value && (!id->qualifier || id->qualifier->empty())
                && bareOwning.count(*id->value) && unassigned.count(*id->value))
                flag(*id->value, e->line);
            return;
        }
        auto rec = [&](SharedExpression x){ scan(x); };
        if (auto* oc = dynamic_cast<ObjectCreationNode*>(n)) {
            if (oc->args) for (auto& a : *oc->args) if (a) rec(a->expression);
        } else if (auto* c = dynamic_cast<CastNode*>(n)) { rec(c->unaryExpression);
        } else if (auto* h = dynamic_cast<HandoffNode*>(n)) { rec(h->value);   // give/copy x
        } else if (auto* b = dynamic_cast<BinaryExpressionNode*>(n)) { rec(b->LHS); rec(b->RHS);
        } else if (auto* l = dynamic_cast<LogicalAndOrNode*>(n)) { rec(l->LHS); rec(l->RHS);
        } else if (auto* tn = dynamic_cast<TernaryExpressionNode*>(n)) { rec(tn->condition); rec(tn->LHS); rec(tn->RHS);
        } else if (auto* as = dynamic_cast<AssignmentNode*>(n)) {
            if (writeTargetKey(as->unaryExpression).empty()) rec(as->unaryExpression);
            rec(as->expression);
        } else if (auto* inv = dynamic_cast<InvocationNode*>(n)) {
            std::string ax = addrOfLocal(inv);
            if (!ax.empty()) {                               // addr(of: x) — manual control; x is now managed
                slotBadFill(ax, "vouches for it with `addr(of: …)`",
                            "take an `out` parameter instead — `std::ptr::relocate` is the one for a raw "
                            "move-out", inv->line);
                markAssigned(ax); return;
            }
            // `slot FixedArray<T,A> r; r.allocBuffer(size: size); return give r;` — calling a method ON a
            // slot FILLS it. The receiver is passed by pointer and the method's whole job here is to build
            // the value, so this is a write, not a read; the builder shape is how much of the stdlib
            // constructs. (The declaration's field-default fill already put the storage in a valid state,
            // so the receiver is never garbage.) Marks the slot live without recursing into the receiver.
            if (auto* rma = dynamic_cast<MemberAccessNode*>(inv->expression.get()))
                if (auto* rid = dynamic_cast<IdentifierNode*>(rma->expression.get()))
                    if (rid->value && (!rid->qualifier || rid->qualifier->empty())
                        && slotClassDecls.count(*rid->value)) {   // valid-empty only — NOT an Owned/Shared hole
                        slotBadFill(*rid->value, "fills it with a method call",
                                    "give it a value instead — `T x = T.empty();`", inv->line);
                        untrack(*rid->value);
                        if (inv->args) for (auto& a : *inv->args) if (a) {
                            std::string ot = outArgTarget(a.get());
                            if (!ot.empty()) { slotOutFill(ot, inv->line); markAssigned(ot); }
                            else rec(a->expression);
                        }
                        return;
                    }
            rec(inv->expression);
            if (inv->args) for (auto& a : *inv->args) if (a) {
                std::string ot = outArgTarget(a.get());
                if (!ot.empty()) { slotOutFill(ot, inv->line); markAssigned(ot); continue; }
                // Handing a class slot to a callee fills it — this is the `ref`-destination shape
                // (`this.root.collectKeys(dest: acc)`), and the `ref` marker is optional at call sites so
                // there is nothing syntactic to key off. Safe either way: by-ref the callee builds it, and
                // by-value it copies a valid empty value.
                if (auto* aid = dynamic_cast<IdentifierNode*>(a->expression.get()))
                    if (aid->value && (!aid->qualifier || aid->qualifier->empty())
                        && slotClassDecls.count(*aid->value)) {
                        slotBadFill(*aid->value, "hands it to a callee as a `ref` destination",
                                    "mark the parameter `out` and pass it `out`", a->expression->line);
                        untrack(*aid->value); continue;
                    }
                rec(a->expression);
            }
        } else if (auto* ea = dynamic_cast<ElementAccessNode*>(n)) {
            rec(ea->expression);
            if (ea->expressionlist) for (auto& x : *ea->expressionlist) rec(x);
        } else if (auto* ma = dynamic_cast<MemberAccessNode*>(n)) {
            // A non-owning field of a class slot (`result.alloc`) is fine — the fill loop initialized it.
            // An OWNING field was already caught by the `fieldKey` check at the top of scan, which is what
            // keeps `def_assign_field_read` rejected: an `Owned`/`Shared` field really is null here.
            if (auto* bid = dynamic_cast<IdentifierNode*>(ma->expression.get()))
                if (bid->value && (!bid->qualifier || bid->qualifier->empty())
                    && slotClassDecls.count(*bid->value)) return;
            rec(ma->expression);
        } else if (auto* pe = dynamic_cast<PreIncrDecrNode*>(n)) { rec(pe->expression);
        } else if (auto* po = dynamic_cast<PostIncrDecrNode*>(n)) { rec(po->expression);
        } else if (auto* su = dynamic_cast<SimpleUnaryExpressionNode*>(n)) { rec(su->expression);
        } else if (auto* al = dynamic_cast<ArrayLiteralNode*>(n)) {
            if (al->elements) for (auto& x : *al->elements) rec(x);
            rec(al->fillValue);
        } else if (auto* mt = dynamic_cast<MatchNode*>(n)) {
            rec(mt->subject);
            // A `match` IS a join, exactly like the `if`/`else` case below. It is exhaustive by
            // construction — the emitter rejects a non-exhaustive one, the same assumption `alwaysExits`
            // already makes — so exactly one arm runs, and a key is assigned afterwards iff every arm
            // that REACHES the join assigns it. Treating each arm as independently skippable (which is
            // what this did) rejected the ordinary way to fill a `slot` from a match:
            //     slot int32 e;
            //     match (c) { case Ok: { e = 0; } case _: { e = 99; } };
            //     return e;                        // was: "'e' is used before it is assigned"
            // and there is no other spelling for it — the workaround is to abandon the `slot` and give
            // the local a throwaway initializer, which is exactly the habit `slot` exists to remove.
            if (mt->arms && !mt->arms->empty()) {
                std::set<std::string> before = unassigned, joined;
                bool anyReaches = false;
                for (auto& arm : *mt->arms) {
                    if (!arm) continue;
                    unassigned = before;                       // each arm starts from the pre-match state
                    if (arm->body) rec(arm->body);
                    if (arm->block) walk(std::static_pointer_cast<StatementNode>(arm->block), true);
                    // The same divergence test the emitter uses to merge MOVE state at this very join
                    // (`armDivs`), so the two passes agree about which arms reach it. Under-detecting
                    // divergence only keeps a key unassigned longer, which is the safe direction.
                    if (arm->block && bodyDiverges(std::static_pointer_cast<StatementNode>(arm->block)))
                        continue;                              // never reaches the join; contributes nothing
                    if (!anyReaches) { joined = unassigned; anyReaches = true; }
                    else for (auto& k : unassigned) joined.insert(k);   // union: a hole if ANY arm leaves one
                }
                unassigned = anyReaches ? joined : before;      // no arm reaches the join — state is moot
            }
        }
    };

    // Walk one statement: scan its reads, then record top-level owning-value assignments.
    walk = [&](SharedStatement st, bool topLevel) {
        if (!st) return;
        ASTNode* n = st.get();
        if (auto* lv = dynamic_cast<LocalVariableDeclaration*>(n)) {
            std::string owned = (lv->type && lv->type->value) ? heapOwnerTarget(cType(lv->type)) : "";
            std::string cls   = (lv->type && lv->type->value)
                                ? resolveUserName(*lv->type->value, lv->type->qualifier) : "";
            std::set<std::string> fs;                        // owning fields, if a resource type
            if (owned.empty() && !cls.empty()) {
                auto ci = _classes.find(cls);
                if (ci != _classes.end())
                    // `fieldCType`, not `cType`: this class may be declared in another file, and resolving
                    // its field types HERE judged the declaring file's spelling against this one. See
                    // bakeFieldCTypes.
                    for (auto& f : ci->second.fields)
                        if (!heapOwnerTarget(fieldCType(cls, f)).empty()) fs.insert(f.name);
            }
            if (lv->variables) for (auto& v : *lv->variables) if (v && v->name && v->name->value) {
                const std::string& nm = *v->name->value;
                if (v->initializer) scan(v->initializer);    // RHS read-scan happens before the local is "assigned"
                // A `slot` of ANY type is tracked by its bare name — that is the whole point of the
                // declaration, and it is what widens this check past `Owned`/`Shared` to raw-handle
                // resources, collections and primitives alike.
                if (lv->isSlot || !owned.empty()) {
                    if (lv->isSlot) {
                        slotDecls.insert(nm);
                        slotDeclLine[nm] = n->line;
                        slotDeclDepth[nm] = condDepth;
                        // `owned.empty()` is load-bearing: an `Owned`/`Shared` slot is NOT valid-but-empty.
                        // Its zero value is a NULL pointer, so calling through it derefs null — the very
                        // thing this check exists to catch. Only a plain class, whose field-default fill
                        // leaves a usable value, gets the relaxed treatment.
                        if (owned.empty() && lv->type && lv->type->value && isClass(cType(lv->type)))
                            slotClassDecls.insert(nm);
                    }
                    bareOwning.insert(nm);
                    if (!v->initializer) unassigned.insert(nm);
                }
                if (owned.empty() && !fs.empty()) {           // a resource local with owning fields
                    resFields[nm] = fs;
                    if (!v->initializer) for (auto& f : fs) unassigned.insert(nm + "." + f);
                }
            }
        } else if (auto* as = dynamic_cast<AssignmentNode*>(n)) {
            std::string wk = writeTargetKey(as->unaryExpression);
            if (wk.empty()) scan(as->unaryExpression);       // a write-through LHS may itself read
            scan(as->expression);
            // Rule 1 — an assignment is not a slot fill. `T x = …;` states the same thing with the value
            // in hand, and a branch-initialized one has a stronger spelling still (`match`/ternary build
            // a resource), so nothing is lost by removing the hole.
            {
                std::string an;                                    // the slot this assignment targets
                if (auto* id = dynamic_cast<IdentifierNode*>(as->unaryExpression.get())) {
                    if (id->value && (!id->qualifier || id->qualifier->empty())) an = *id->value;
                } else if (auto* ma = dynamic_cast<MemberAccessNode*>(as->unaryExpression.get())) {
                    if (auto* bid = dynamic_cast<IdentifierNode*>(ma->expression.get()))
                        if (bid->value && (!bid->qualifier || bid->qualifier->empty())) an = *bid->value;
                }
                if (!an.empty())
                    slotBadFill(an, "assigns it",
                                "give the declaration a value instead — a `match` or a ternary builds one "
                                "for a branch", n->line);
            }
            if (topLevel) {
                if (!wk.empty()) unassigned.erase(wk);
                else if (auto* id = dynamic_cast<IdentifierNode*>(as->unaryExpression.get()))  // `h = …` reassigns whole
                    if (id->value && (!id->qualifier || id->qualifier->empty()) && resFields.count(*id->value))
                        for (auto& f : resFields[*id->value]) unassigned.erase(*id->value + "." + f);
            }
        } else if (auto* iff = dynamic_cast<IfNode*>(n)) {
            scan(iff->booleanExpression);
            if (!topLevel || !iff->elseStatement) {
                // A lone `if` (no else) can be skipped entirely, so nothing it assigns is definite; the
                // same goes for anything already off the unconditional path. Stay conservative.
                walkSkippable(iff->ifStatement);             // branch bodies don't count as unconditional assigns
                walkSkippable(iff->elseStatement);
            } else {
                // if/else at the top level IS a join: a key is assigned after it iff every arm that
                // REACHES the join assigns it. An arm ending in return/break/continue never reaches the
                // join, so it contributes nothing (and its own return was already verified below).
                // Without this, `if (c) { q = 1; } else { q = 2; }` — the ordinary way to fill an `out` —
                // would be rejected, which would make the rule unusable.
                std::set<std::string> before = unassigned;
                walk(iff->ifStatement, true);
                std::set<std::string> afterThen = unassigned;
                bool thenDiv = bodyDiverges(iff->ifStatement);
                unassigned = before;
                walk(iff->elseStatement, true);
                std::set<std::string> afterElse = unassigned;
                bool elseDiv = bodyDiverges(iff->elseStatement);
                if (thenDiv && elseDiv)  unassigned = before;      // join is unreachable — state is moot
                else if (thenDiv)        unassigned = afterElse;
                else if (elseDiv)        unassigned = afterThen;
                else {                                            // union: still a hole if EITHER arm left one
                    unassigned = afterThen;
                    for (auto& k : afterElse) unassigned.insert(k);
                }
            }
        } else if (auto* wh = dynamic_cast<WhileNode*>(n)) {
            scan(wh->booleanExpression); walkSkippable(wh->whileStatement);
        } else if (auto* dw = dynamic_cast<DoWhileNode*>(n)) {
            walkSkippable(dw->doWhileStatement); scan(dw->booleanExpression);
        } else if (auto* fr = dynamic_cast<ForNode*>(n)) {
            if (fr->initializerStatements) for (auto& s : *fr->initializerStatements) walkSkippable(s);
            scan(fr->booleanExpression);
            if (fr->iteratorStatements) for (auto& s : *fr->iteratorStatements) walkSkippable(s);
            walkSkippable(fr->body);
        } else if (auto* fe = dynamic_cast<ForEachNode*>(n)) {
            scan(fe->expression); walkSkippable(fe->body);
        } else if (auto* pf = dynamic_cast<ParallelForNode*>(n)) {
            scan(pf->expression); walkSkippable(pf->body);
        } else if (auto* bn = dynamic_cast<BorrowNode*>(n)) {
            // `walk`, not `walkSkippable`: a `borrow` block is UNCONDITIONAL, so an `out` fill inside it
            // is a definite assignment (SPEC's slot rule 3 — "a nested block that always runs"). Pass
            // `topLevel` through, exactly as the plain BlockNode arm does.
            if (bn->bindings) for (auto& b : *bn->bindings) if (b) scan(b->host);
            walk(bn->body, topLevel);
        } else if (auto* ret = dynamic_cast<ReturnNode*>(n)) {
            // `ctor make() { slot Foo r; … return give r; }` — handing a slot OUT of a constructor is
            // governed by checkNamedCtorComplete, which proves every field is assigned (counting field
            // defaults and default-fillable fields). A type whose fields are ALL default-fillable — the
            // primordial `empty()` constructors — assigns nothing at all and is still complete, so slot
            // liveness must not second-guess it here. Outside a ctor there is no such proof, and the
            // ordinary read rule applies.
            // `_inNamedCtorBody`, not an isCtor parameter: a named `ctor` is a static factory, so it is
            // deliberately emitted with isCtor=false (that flag drives the `self->__vptr` store). This is
            // the same flag the const-field-write allowance keys off (#M8d.2).
            bool ctorHandoff = false;
            if (_inNamedCtorBody && ret->expression) {
                // Unwrap the same two shapes checkNamedCtorComplete's `classify` does: a `give`/`copy`
                // hand-off, and a fallible ctor's `Result::Ok(value: …)` wrapper.
                std::function<ExpressionNode*(ExpressionNode*)> unwrap = [&](ExpressionNode* e) {
                    if (!e) return e;
                    if (auto* h = dynamic_cast<HandoffNode*>(e)) return unwrap(h->value.get());
                    if (auto* iv = dynamic_cast<InvocationNode*>(e))
                        if (iv->identifier && iv->identifier->value && iv->identifier->qualifier
                            && !iv->identifier->qualifier->empty()
                            && *iv->identifier->qualifier->back() == "Result"
                            && *iv->identifier->value == "Ok" && iv->args)
                            for (auto& a : *iv->args)
                                if (a && a->name && a->name->value && *a->name->value == "value")
                                    return unwrap(a->expression.get());
                    return e;
                };
                if (auto* rid = dynamic_cast<IdentifierNode*>(unwrap(ret->expression.get())))
                    ctorHandoff = rid->value && (!rid->qualifier || rid->qualifier->empty())
                               && slotDecls.count(*rid->value) > 0;
            }
            if (!ctorHandoff) scan(ret->expression);
            verifyOutsAssigned(ret->line);
        } else if (auto* blk = dynamic_cast<BlockNode*>(n)) {
            if (blk->statements) for (auto& s : *blk->statements) walk(s, topLevel);
        } else if (dynamic_cast<ExpressionStatementNode*>(n)) {
            scan(std::dynamic_pointer_cast<ExpressionNode>(st));   // invocation / match / incr — scan its reads
        }
    };

    for (auto& st : *body->statements) walk(st, true);
    // Rule 2 — a hole nothing ever fills is a dead declaration. Silently eliding its drop was the wrong
    // answer: the storage exists, the reader is told a callee will fill it, and no callee does.
    for (auto& nm : slotDecls)
        if (!slotOutFilled.count(nm)) {
            auto dl = slotDeclLine.find(nm);
            slotFillRule(("`" + nm + "` is a `slot` that no `out` argument ever fills — a hole nothing "
                          "fills is a dead declaration; give it a value, or pass it to a callee that "
                          "takes an `out` parameter").c_str(), dl == slotDeclLine.end() ? body->line : dl->second);
        }
    // Falling off the end is a return too (a `void` function need not spell one). Skip it when the body
    // ends in a jump — that path was already verified at the ReturnNode.
    if (!outParams.empty()
        && !(!body->statements->empty() && stmtIsJump(body->statements->back())))
        verifyOutsAssigned(body->line);
}

// access control --------------------------------------------------------
bool CEmitter::modHas(SharedModifierList mods, const char* name)
{
    if (mods) for (auto& m : *mods) if (m->value && *m->value == name) return true;
    return false;
}

// At most one of public/protected/private; default `dflt` when none is written.
Visibility CEmitter::visibilityOf(SharedModifierList mods, Visibility dflt, int line)
{
    Visibility v = dflt; int count = 0;
    if (mods) for (auto& m : *mods) {
        if (!m->value) continue;
        if      (*m->value == "public")    { v = Visibility::Public;    count++; }
        else if (*m->value == "protected") { v = Visibility::Protected; count++; }
        else if (*m->value == "private")   { v = Visibility::Private;   count++; }
    }
    if (count > 1) unsupported("a member may have at most one of public/protected/private", line);
    return v;
}

// A field's visibility. A `value` picks it per field (default private, `public` allowed, `protected`
// rejected — protected belongs to an extensible resource). A `resource` field is always private
// (ownership encapsulated). An extern struct is public (the FFI struct owns its layout).
Visibility CEmitter::fieldVisibility(const ClassInfo& ci, SharedModifierList mods, int line)
{
    if (ci.isExternStruct) return Visibility::Public;
    // A `view` field is always private — like a `resource` it has an encapsulation invariant (its raw
    // borrowed `UnsafePtr<T>` must not leak into the safe surface, and ptr/len must stay consistent). Expose
    // data through methods (`operator[]`, `length`, `iterator`, …). It codegens as a value but is NOT a
    // transparent data-bag like a plain `value`.
    if (ci.isBorrow) {
        if (modHas(mods, "public") || modHas(mods, "protected") || modHas(mods, "private"))
            unsupported("a `view` field is always private — it borrows a raw pointer that must not leak; "
                        "expose behavior through methods", line);
        return Visibility::Private;
    }
    if (ci.kind == TypeKind::Value) {
        if (modHas(mods, "protected"))
            unsupported("a `value` field can't be `protected` — protected belongs to an extensible `resource`", line);
        return visibilityOf(mods, Visibility::Private, line);
    }
    // A `resource` field is always private — ownership is encapsulated; expose behavior through methods.
    if (modHas(mods, "public") || modHas(mods, "protected") || modHas(mods, "private"))
        unsupported("a `resource` field is always private — expose behavior through methods", line);
    return Visibility::Private;
}

// Is a member (declared on `owner`, visibility `vis`) accessible from the current
// emission context (`_currentClass`; null = external/free function)? Compile error if not.
bool CEmitter::canAccess(ClassInfo* owner, Visibility vis, const std::string& member, int line)
{
    if (vis == Visibility::Public || !owner) return true;
    if (vis == Visibility::Protected) {                 // owner or any subclass of owner
        for (ClassInfo* c = _currentClass; c; c = c->base) if (c == owner) return true;
    } else {                                            // Private — owner itself, or a friend grant
        if (_currentClass == owner) return true;
        // an owner-granted `friend` may touch the named members. The accessing
        // context is the current class (any of its methods) or the current function/method.
        // A grant naming a GENERIC type reaches the CORRESPONDING instance, and only that one: inside
        // `Tree<int32>` the accessing context is `Tree_int32`, which can never equal the template key
        // `Tree` the grant recorded. The correspondence is computed rather than compared — the owner
        // instance's own argument suffix, appended to the accessor's template key — so `Tree<A,B>` may
        // touch `Node<A,B>` while a sibling instance may not. That is the rule plain `private` already
        // follows between sibling instances (`Node<int32>` reading `Node<int64>`'s private field is
        // refused today), and a grant must not be broader than the rule it relaxes. It is also what C++
        // gives for `friend struct Tree<K,V>;`, and kama's bare spelling is the one C++ refuses as
        // ambiguous, so kama reads it as the STRICTER of the two meanings — which keeps an explicit
        // `friend Tree<K,A>[m];` additive if it is ever wanted, rather than a source break.
        std::string ownerArgs;   // "_int32_int32" — "" when the owner is not a generic instance
        if (owner->isGenericInst) {
            auto of = _genericTypeInstOf.find(owner->name);
            if (of != _genericTypeInstOf.end() && owner->name.size() > of->second.size())
                ownerArgs = owner->name.substr(of->second.size());
        }
        for (auto& g : owner->friendGrants) {
            if (!g.members.empty() && !g.members.count(member)) continue;   // empty => all privates
            // The corresponding instance of a generic accessor. With a non-generic owner there is nothing
            // to correspond to, so every instance of the accessor is a friend — ownerArgs is empty, and
            // the current context's own template key is what answers.
            std::string acc = g.accessor;
            if (g.accessorIsTemplate) {
                if (ownerArgs.empty()) {
                    if (!_currentClass) continue;
                    auto cf = _genericTypeInstOf.find(_currentClass->name);
                    if (cf == _genericTypeInstOf.end() || cf->second != g.accessor) continue;
                    acc = _currentClass->name;
                } else {
                    acc += ownerArgs;
                }
                if (!g.accessorMethod.empty()) acc += "__" + g.accessorMethod;   // `Type::method` form
            }
            if (g.accessorIsClass) { if (_currentClass && _currentClass->name == acc) return true; }
            else                   { if (!_currentFunc.empty() && _currentFunc == acc) return true; }
        }
    }
    const char* vs = (vis == Visibility::Private) ? "private" : "protected";
    unsupported(("'" + member + "' is " + vs + " in '" + owner->name + "'").c_str(), line);
    return false;
}

// Field access through a resolved owner (looks up the field's visibility, then checks).
void CEmitter::checkFieldAccess(ClassInfo* owner, const std::string& field, int line)
{
    if (!owner) return;
    for (auto& f : owner->fields)
        if (f.name == field) {
            canAccess(owner, f.visibility, field, line);
            // Containment, on the propagation vector rather than the dereference. DECLARING an
            // `UnsafePtr` field stays legal — every container and every `type extern value` depends on
            // it — but touching one is holding raw memory, and that is what finding 2 exploited: a field
            // plus `addr(of:)` is a general dangling-pointer factory, and `other.p = this.p` moves a raw
            // pointer between objects through a function carrying no marker at all. The deref (`p[0]`)
            // was never the leak; acquisition and propagation were.
            //
            // Hooked HERE, not at the call sites, because every field-resolution path already funnels
            // through this one function — the smart-pointer auto-deref arm, the `Deref<T>` contract arm,
            // and the plain arm each call it, and a gate installed at one of them would silently miss
            // the other two.
            if (namesUnsafePtr(f.type))
                rejectRawOutsideUnsafe(("field `" + field + "`").c_str(), line);
            return;
        }
}

// resolve each class's raw `friend` grants to match keys, once every unit's
// functions/classes are registered. An accessor is a class (matched vs _currentClass),
// a free function, or a `Class::method` (both matched vs _currentFunc's C-name).
// Does the qualifier of a `friend` accessor name a module this program loaded? The qualifier is judged
// WHOLE, never by a prefix: the project root is a namespace too, so a prefix test would call
// `sodium::box::sealInto` present whenever `sodium` is. Three shapes are present: a 1-segment file alias;
// a path that is itself a registered module scope (`mod::func`, `mod::Type`); or a path whose last segment
// names a class inside the registered module the rest spells (`mod::Type::method`). Anything else names a
// module absent from the build — see the inert-grant rule in resolveFriends.
bool CEmitter::friendModulePresent(SharedStringList qual)
{
    if (!qual || qual->empty()) return true;
    if (qual->size() == 1 && _nsCtx.aliases.count(*(*qual)[0])) return true;
    auto dotted = [&](size_t n) { std::string path; for (size_t i = 0; i < n; ++i) path += (path.empty() ? "" : ".") + *(*qual)[i]; return path; };
    if (_namespaces.count(mangleNs(dotted(qual->size())))) return true;
    if (qual->size() >= 2 && _namespaces.count(mangleNs(dotted(qual->size() - 1)))) {
        auto head = std::make_shared<StringList>();
        for (size_t i = 0; i + 1 < qual->size(); ++i) head->push_back((*qual)[i]);
        return _classes.count(resolveUserName(*qual->back(), head)) > 0;
    }
    return false;
}

void CEmitter::resolveFriends()
{
    // A whole-program pass, so no unit is "current": without the owner's file installed as the
    // diagnostic context, every grant error printed `:6:0:` with no file name at all — which is exactly
    // how the first external package's report quoted them. The same rung ScopedContractNs installs.
    const std::string savedDiag = _emitDeclFile;
    // Both tables, because a generic TEMPLATE is never in `_classes` (it lives in `_genericTypes`, see
    // the member's comment) and this pass used to iterate only the first. That one omission was two of
    // the three faces of "`friend` does not work across generics": the grant on a generic owner was
    // captured at collection and then never resolved, so `friendGrants` stayed permanently empty and
    // canAccess fell straight through to "'m' is private in 'Node<int32>'" — a grant that reads correct
    // and grants nothing; and the honesty checks below (a typo'd member, a redundant grant on a public
    // one) never ran for such an owner either, so a mistake in one was silently accepted.
    //
    // Resolving the TEMPLATE is all it takes for every instance to have it: instances are minted later,
    // by collectCollections, and registerGenericTypeInst copies the whole ClassInfo from the template —
    // `friendGrants` included. So there is no second pass to run and nothing in regateGenericInstances
    // to touch. The ORDER is what makes that true (resolveFriends before collectCollections), and it is
    // the order that was already there.
    // The accessor side of the same gap, and the third face: `resolveUserName` DOES answer for a generic
    // type, but every arm below then gated on `_classes.count()`, which a template never satisfies — so
    // `friend Tree[m];` was refused outright as an unknown accessor. Both arms record the template key
    // and say so, and canAccess turns it into the corresponding instance.
    auto asType = [&](const std::string& key, FriendGrant& g) {
        if (_classes.count(key))      { g.accessor = key; g.accessorIsClass = true; return true; }
        if (_genericTypes.count(key)) { g.accessor = key; g.accessorIsClass = true; g.accessorIsTemplate = true; return true; }
        return false;
    };
    auto asMethod = [&](const std::string& ownerKey, const std::string& m, FriendGrant& g) {
        auto cit = _classes.find(ownerKey);
        if (cit != _classes.end() && cit->second.methods.count(m)) {
            g.accessor = cit->second.methods[m].cName; return true;             // a concrete method's C name
        }
        auto git = _genericTypes.find(ownerKey);
        if (git != _genericTypes.end() && git->second.methods.count(m)) {
            // The template's `cName` is not the instance's (registerGenericTypeInst re-mints every method
            // as `Inst__m`), so keep the pieces and let canAccess compose the corresponding one.
            g.accessor = ownerKey; g.accessorIsTemplate = true; g.accessorMethod = m; return true;
        }
        return false;
    };
    std::vector<ClassInfo*> owners;
    for (auto& kv : _classes)      owners.push_back(&kv.second);
    for (auto& kv : _genericTypes) owners.push_back(&kv.second);
    for (ClassInfo* cip : owners) {
        ClassInfo& ci = *cip;
        if (ci.friendGrantsRaw.empty()) continue;
        _nsCtx = NsCtx{}; _nsCtx.scope = ci.scope; _nsCtx.usings = ci.usings; _nsCtx.symbolAliases = ci.symbolAliases; restoreFileRung(_nsCtx, ci.declFile);
        if (!ci.declFile.empty()) _emitDeclFile = ci.declFile;
        for (auto& rg : ci.friendGrantsRaw) {
            FriendGrant g; g.members = rg.members;
            SharedIdentifier acc = rg.accessor;
            std::string     val  = (acc && acc->value) ? *acc->value : "";
            SharedStringList qual = acc ? acc->qualifier : nullptr;
            bool resolved = false;

            if (qual && !qual->empty()) {
                // A qualified accessor, three shapes — tried in this order because each is one segment
                // longer than the last: `mod::Type` (the whole path names a class), `mod::Type::method`
                // (the path minus its last segment names the class, `val` its method — a named `ctor`
                // included, since a ctor is registered in `methods` with its visibility), and `mod::func`
                // (a free function). The first two used to be spelled only bare: `resolveUserName` was
                // handed the LAST qualifier segment with no path, so `fmod::user::Holder[n]` resolved
                // `user` as a class and failed, and an owner had to `import` a module purely to name its
                // friend (the first external package's KAMA_GAPS #1). Fixed in 0.9.230.
                std::string clsName = resolveUserName(val, qual);          // `mod::Type`
                if (asType(clsName, g)) resolved = true;
                if (!resolved) {                                           // `mod::Type::method`
                    auto head = std::make_shared<StringList>();
                    for (size_t i = 0; i + 1 < qual->size(); ++i) head->push_back((*qual)[i]);
                    std::string owner = head->empty() ? resolveUserName(*qual->back(), nullptr)
                                                      : resolveUserName(*qual->back(), head);
                    if (asMethod(owner, val, g)) resolved = true;
                }
                if (!resolved) {                                           // `mod::func`
                    std::string fk = resolveFunc(val, qual);
                    if (_funcs.count(fk)) { g.accessor = _funcs[fk].cName; g.accessorIsClass = false; resolved = true; }
                }
                // A grant into a module that is not part of THIS program is INERT, not an error: the code
                // it names is not being compiled, so it can grant nothing — and an owner must be able to
                // say who its friends are without dragging every one of their modules into every
                // consumer's build (KAMA_GAPS #2: `Nonce.raw()` was `public` "under protest" for exactly
                // this). A typo inside a module that IS present stays a hard error below. "Present" is
                // judged on the longest namespace prefix of the path that names a loaded module, which is
                // what an absent `sodium::box` fails and a present `sodium::aead` passes.
                if (!resolved && !friendModulePresent(qual)) continue;
            } else {
                std::string clsName = resolveUserName(val, nullptr);   // a class
                if (asType(clsName, g)) resolved = true;
                if (!resolved) {                                       // a free function
                    std::string fk = resolveFunc(val, nullptr);
                    if (_funcs.count(fk)) { g.accessor = _funcs[fk].cName; g.accessorIsClass = false; resolved = true; }
                }
            }
            if (!resolved) { unsupported(("unknown `friend` accessor '" + val + "' in '" + ci.name + "'").c_str(), rg.line); continue; }

            // Both sides generic: the grant is between CORRESPONDING instances, so the two argument lists
            // have to be able to correspond at all. Differing arity never can, and the grant would then be
            // one that reads correct and silently never fires — the very class this row existed to end —
            // so it is refused where it is written rather than at some call site it fails to permit.
            if (g.accessorIsTemplate && _genericTypes.count(ci.name)) {
                const size_t np = _genericTypeParams[ci.name].size();
                const size_t na = _genericTypeParams[g.accessor].size();
                if (np != na) {
                    unsupported(("`friend` grant in '" + ci.name + "' names the generic type '" + val
                                 + "', and a grant between generic types is between CORRESPONDING "
                                   "instances — '" + val + "' takes " + std::to_string(na)
                                 + " type parameter(s) where '" + ci.name + "' takes " + std::to_string(np)
                                 + ", so no instance of '" + val + "' could ever correspond").c_str(), rg.line);
                    continue;
                }
            }

            // Granted members must exist and be private (a grant on a public member, or a
            // typo'd name, is a mistake — keep grants honest and greppable).
            for (auto& m : g.members) {
                Visibility v = Visibility::Public; bool found = false;
                for (auto& f : ci.fields) if (f.name == m) { v = f.visibility; found = true; break; }
                if (!found) { auto mit = ci.methods.find(m); if (mit != ci.methods.end()) { v = mit->second.visibility; found = true; } }
                if (!found)
                    unsupported(("`friend` grant names unknown member '" + m + "' in '" + ci.name + "'").c_str(), rg.line);
                else if (v == Visibility::Public)
                    unsupported(("`friend` grant on public member '" + m + "' in '" + ci.name + "' is redundant").c_str(), rg.line);
            }
            ci.friendGrants.push_back(g);
        }
    }
    _emitDeclFile = savedDiag;
}

// Resolve WHAT a `fnptr`-typed destination is being bound to — a free function name, an unbound
// `Type::method`, or another `fnptr` value. Answers only; it emits nothing and reports nothing.
//
// THE one resolver, and that is the point. `emitFnPtrBind` emits from what this finds and
// `checkFnPtrValueBind` judges the same thing, so a bind position cannot be lowered by one path and
// checked by neither. Until this existed the split was real and silent: only a LOCAL INITIALIZER ran
// `sigMatches`, because that is the sole caller of `emitFnPtrBind`. Every other bind position — an
// assignment, a call argument, a return, a field or a module `static` initializer — reached the bare
// function-name arm of `emitExpression` (the `_funcs` lookup that decays a name to its C symbol), which
// checks nothing at all. A shape-mismatched function bound there compiled clean and the call through it
// passed the wrong number of arguments: an indirect call through a mismatched function pointer, the UB
// class UBSan's `function` check would catch and which is disabled suite-wide for an unrelated reason.
bool CEmitter::resolveFnPtrTarget(SharedExpression init, FnPtrTarget& out)
{
    if (auto* id = dynamic_cast<IdentifierNode*>(init.get())) {
        if (id->value) {
            auto fit = _funcs.find(resolveFunc(*id->value, id->qualifier));
            if (fit != _funcs.end()) {
                out.kind    = FnPtrTarget::Function;
                out.cName   = symbolOf(fit->second);   // the C function name decays to a pointer
                out.sig     = fit->second;
                out.display = "function '" + *id->value + "'";
                out.noHeap  = fnHasNoHeap(fit->second.node);
                out.name    = *id->value;
                return true;
            }
            // `Type::method` — an unbound method reference. The method lowers
            // to `Class__method(Class* self, …)`, so it's a function pointer over a
            // signature whose FIRST param is the receiver (`ref Class self`).
            if (id->qualifier && !id->qualifier->empty()) {
                auto prefix = std::make_shared<StringList>();
                for (size_t i = 0; i + 1 < id->qualifier->size(); ++i) prefix->push_back((*id->qualifier)[i]);
                std::string cls = resolveUserName(*id->qualifier->back(), prefix);
                if (_classes.count(cls)) {
                    ClassInfo* owner = nullptr;
                    MethodInfo* mi = findMethod(&_classes[cls], *id->value, &owner);
                    if (mi) {
                        out.kind    = FnPtrTarget::Method;
                        out.cName   = mi->cName;   // the method's C name decays to a fn pointer
                        out.sig.cName    = mi->cName;   // receiver-first signature
                        out.sig.retCType = cType(mi->returnType);
                        out.sig.params.push_back(ParamSig{"self", true, cls});
                        for (auto& p : mi->params) out.sig.params.push_back(p);
                        out.display      = "method '" + cls + "::" + *id->value + "'";
                        out.mismatchNote = " (its first param must be `ref " + cls + "`)";
                        out.noHeap       = mi->noHeap;
                        out.name         = cls + "::" + *id->value;
                        out.id           = id;
                        out.node         = mi->node;
                        return true;
                    }
                }
            }
        }
    }
    if (isSigType(exprClass(init))) {   // copy from another FunctionPtr
        out.kind = FnPtrTarget::SigValue;
        return true;
    }
    return false;
}

// Judge a resolved bind against the signature: the SHAPE, and then the `@noheap` promise.
//
// The promise half is the `fnptr` seam's version of what `checkConformanceSignatures` does for a
// contract member, and deliberately reads the same way: the declaration promises, every implementation
// is checked against it, and the promise is then what lets a no-heap caller cross the slot. One
// direction only — a `@noheap` function may be bound to a plain signature, which constrains only itself.
void CEmitter::checkFnPtrBind(const std::string& sigCName, const FnPtrTarget& t, int line)
{
    if (t.kind == FnPtrTarget::SigValue) return;   // fnptr types are nominal; identity said it already
    auto sit = _sigs.find(sigCName);
    if (sit == _sigs.end()) return;
    if (!sigMatches(sit->second, t.sig)) {
        unsupported((t.display + " does not match the " + (t.kind == FnPtrTarget::Method ? "fnptr" : "FunctionPtr")
                     + " signature" + t.mismatchNote).c_str(), line);
        return;   // a shape mismatch already tells the author to look at this bind; one defect, one message
    }
    if (sit->second.noHeap && !t.noHeap)
        unsupported((t.display + " is bound to `" + demangleForDisplay(sigCName) + "`, which is `@noheap` — "
                     "declare `" + t.name + "` `@noheap` too, so a no-heap caller calling through the "
                     "slot still gets the guarantee").c_str(), line);
    // A kama function landing in a slot C can call through must state which thread it runs on — the same
    // demand `checkForeignCrossing` makes of a callback handed over as an ARGUMENT, made one indirection
    // further out, where the callback rides inside a descriptor struct (WebGPU, CoreAudio, miniaudio all
    // take it that way). Judged HERE because this is the funnel every bind position already reaches, so
    // the construction route cannot matter: a named `ctor` argument, `d.f = cb`, a derived `of`, a local
    // bound first and assigned after, a module `static` initializer.
    //
    // At the BIND and not at the extern struct's field declaration, deliberately. A descriptor a program
    // only ever RECEIVES from C has no kama function in it, so demanding the annotation there would buy
    // nothing and mean something worse — an annotation that drives no check is exactly the inert surface
    // this compiler refuses elsewhere (see `friend` on a contract). It is demanded where it does work.
    auto cv = _cVisibleSigs.find(sigCName);
    if (cv != _cVisibleSigs.end() && !sit->second.foreignEntry && !sit->second.callerThread)
        unsupported((t.display + " is bound to `" + demangleForDisplay(sigCName) + "`, a callback C can "
                     "call through the field `" + cv->second + "` of a C-layout type, and a callback's "
                     "threading contract cannot be inferred — mark the `fnptr` type `@callerThread` if "
                     "the C API calls it on the calling isolate, or `@foreignEntry` if it may run on a "
                     "thread kama did not create (where a module `static` assigned elsewhere is a "
                     "different object)").c_str(), line);
    // A function bound to a `@foreignEntry` signature IS a foreign entry: the signature declared that the
    // C API may call it on a thread kama did not create, and every bind position funnels through here.
    // First root wins, so a body the author also annotated keeps its own line.
    if (sit->second.foreignEntry && !_probingTemplate && !t.cName.empty() && !_foreignEntryFns.count(t.cName))
        _foreignEntryFns[t.cName] = ForeignEntryFn{ demangleForDisplay(t.cName), line, diagFile(),
                                                    demangleForDisplay(sigCName) };
}

// Which `fnptr` types C can see, and the field that made each one visible. A `type extern value` exists
// for one reason — to match a C header's layout — so a callback field declared on one is a slot C calls
// through, and a kama function bound into it has crossed exactly as surely as one handed over as an
// argument. That is the hole the first consumer found: their three WebGPU callbacks all ride inside
// descriptor structs, so `checkForeignCrossing` (per-ARGUMENT, keyed on the parameter's own type) never
// looked at them, and a tree carrying ZERO annotations built clean.
//
// A FLAT walk is enough, and that is worth stating because a transitive one looks necessary and is not:
// nesting is covered because the inner struct declares the sig field itself (`Outer{Inner i}` +
// `Inner{Op f}` records `Op` when the walk reaches `Inner`), and a pointer field is covered for the same
// reason — `UnsafeConstPtr<Desc>` names `Desc`, whose own fields this walk visits on its own account.
//
// Runs after bakeFieldCTypes, which is the ONLY sanctioned way to read a field's type (see fieldCType).
void CEmitter::mapCVisibleSigs()
{
    for (auto& kv : _classes) {
        ClassInfo& ci = kv.second;
        if (!ci.isExternStruct) continue;
        for (auto& f : ci.fields) {
            std::string ft = fieldCType(ci.name, f);
            if (!isSigType(ft) || _cVisibleSigs.count(ft)) continue;   // first field to name it wins
            _cVisibleSigs[ft] = demangleForDisplay(ci.name) + "." + f.name;
        }
    }
}

// A `type expose value` publishes its layout to a host, so every field is part of that promise and must be
// something C can hold and read: a primitive, a pointer (whose pointee the host header names opaquely), a
// `fnptr`, a payload-less enum, another C layout (`extern` or `expose`), or an intrinsic array of those. And
// every field is PUBLIC: the host header shows the whole struct, and C has no `private` — a hidden field in
// a published layout is a claim the language cannot keep.
void CEmitter::checkExposeValues()
{
    for (auto& kv : _classes) {
        const ClassInfo& ci = kv.second;
        if (ci.isExternStruct) {
            // A C struct's enum field is a C enum: a plain kama enum there would read the header's integer
            // with kama's own numbering (KR-55), which is the drift the extern/expose pair exists to prevent.
            ScopedStr _cu(_collectingUnitPath, ci.declFile);
            for (const FieldInfo& f : ci.fields) {
                auto e = _enums.find(fieldCType(ci.name, f));
                if (e == _enums.end() || e->second.isExtern) continue;
                unsupported(("`" + ci.name + "." + f.name + "` is the enum `" + demangleForDisplay(e->first) + "`, but `"
                             + ci.name + "` is a `type extern value` — a C struct's enum field holds a C enum, so bind "
                               "it with `type extern enum` and let the header supply the values").c_str(),
                            f.nameId ? f.nameId->line : ci.node ? ci.node->line : 0);
            }
            continue;
        }
        if (!ci.isExposeStruct) continue;
        ScopedStr _cu(_collectingUnitPath, ci.declFile);
        const std::string shown = demangleForDisplay(ci.name);
        for (const FieldInfo& f : ci.fields) {
            const int ln = f.nameId ? f.nameId->line : ci.node ? ci.node->line : 0;
            if (f.visibility != Visibility::Public)
                unsupported(("`" + shown + "." + f.name + "` is not `public`, but `" + shown + "` is a `type expose "
                             "value` — its host header shows every field, and C has no `private`. Mark the field "
                             "`public`, or keep the value unexposed and pass it by `UnsafePtr`").c_str(), ln);
            std::string ct = fieldCType(ci.name, f);
            for (;;) {   // peel intrinsic arrays down to their element: the element is laid out inline
                auto co = _collections.find(ct);
                if (co == _collections.end() || !(co->second.kind == CollKind::Fixed || isValueVectorKind(co->second.kind))) break;
                ct = co->second.elemCType;
            }
            if (ct.empty() || ct.back() == '*' || isSigType(ct) || ct == "kama_cchar") continue;
            if (_enums.count(ct)) {
                if (_enums[ct].isExtern || _enums[ct].isExpose) continue;
                unsupported(("`" + shown + "." + f.name + "` is the plain enum `" + demangleForDisplay(ct) + "`, whose "
                             "values nothing promises to C — a `type expose value` field's enum is a `type expose "
                             "enum` (kama's values, published) or a `type extern enum` (a C header's)").c_str(), ln);
                continue;
            }
            auto c = _classes.find(ct);
            if (c == _classes.end()) {
                static const std::set<std::string> prims = { "bool", "float", "double", "size_t", "ptrdiff_t",
                    "int8_t", "int16_t", "int32_t", "int64_t", "uint8_t", "uint16_t", "uint32_t", "uint64_t" };
                if (prims.count(ct)) continue;
            } else if (c->second.isExternStruct || c->second.isExposeStruct) {
                continue;
            }
            unsupported(("`" + shown + "." + f.name + "` is `" + (f.type && f.type->value ? *f.type->value : ct)
                         + "`, which has no C layout a host can hold — a `type expose value` field is a primitive, "
                           "a pointer, a `fnptr`, a payload-less enum, a `type extern value` or `type expose value`, "
                           "or an `InlineArray` of those").c_str(), ln);
        }
    }
}

// A `type extern value` emits no struct — the header's is used — so its field list is a claim nothing read:
// `int32 a` over a header's `short a` compiled clean and `a: 70000` truncated silently (measured, KR-52). kama
// does not model C layout (clang does, see `comptime assert`), so the check is handed to the C compiler, and
// it therefore fails at BUILD rather than `kama check`. Order and a subset of the header's fields are fine —
// every read is by name — so what is asserted is exactly what decides how a value is read: its size and class.
void CEmitter::emitExternLayoutChecks()
{
    bool any = false;
    for (auto& kv : _classes) {
        const ClassInfo& ci = kv.second;
        if (!ci.isExternStruct) continue;
        for (const FieldInfo& f : ci.fields) {
            const int ln = f.nameId ? f.nameId->line : ci.node ? ci.node->line : 0;
            const std::string at = ci.declFile + (ln ? ":" + std::to_string(ln) : std::string());
            const std::string ct = fieldCType(ci.name, f);
            if (ct.empty()) continue;
            const std::string field = "((" + ci.name + "*)0)->" + f.name;
            const std::string kamaTy = f.type && f.type->value ? *f.type->value : ct;
            const std::string note = "kama: `" + demangleForDisplay(ci.name) + "." + f.name + "` is declared `" + kamaTy
                + "` (" + at + "), but the C header's field differs in size or in kind (integer, floating, bool) — "
                  "make the kama field match the header";
            *_out << "_Static_assert(sizeof(" << field << ") == sizeof(" << ct << ") && KAMA_C_KIND(" << field
                  << ") == KAMA_C_KIND(*(" << ct << "*)0), \"" << cEscapeStringBody(note) << "\");\n";
            any = true;
        }
    }
    // `extern const T NAME;` (KR-56) — the same claim about a header, about a constant instead of a field. It holds
    // for a `#define` too: `KAMA_C_KIND` and `sizeof` never evaluate their operand, and a macro's literal has a type.
    for (auto& kv : _externConsts) {
        const ExternConst& ec = kv.second;
        const std::string note = "kama: `extern const " + kv.first + "` is declared `" + primKeyOfCType(ec.cType) + "` ("
            + ec.declFile + ":" + std::to_string(ec.line) + "), but the C constant differs in size or in kind (integer, "
              "floating, bool) — state the type the header gives it";
        *_out << "_Static_assert(sizeof(" << ec.symbol << ") == sizeof(" << ec.cType << ") && KAMA_C_KIND(" << ec.symbol
              << ") == KAMA_C_KIND(*(" << ec.cType << "*)0), \"" << cEscapeStringBody(note) << "\");\n";
        any = true;
    }
    if (any) *_out << "\n";
}

// Does this type reach a callback that states no thread, and through which chain of fields? The answer
// `_cVisibleSigs` cannot give, for the two crossings where the type is kama's own rather than a C-layout
// one: a composite handed to an `extern fn`, and an `expose fn`'s return. There the callback sits one or
// more fields down and the bind that put it there was legitimate — an `fnptr` field on an ordinary type
// is a kama callback table and needs no annotation — so it is the CROSSING that has to look.
//
// It sees through a raw pointer, which is not a concession: `UnsafeConstPtr<Desc>` NAMES `Desc`, so the
// pointee is knowable, and a descriptor pointing at sub-descriptors is the shape WebGPU actually uses.
// Cycle-safe on the class set rather than on depth, since a field cycle can only close through a pointer.
bool CEmitter::reachesUnannotatedSig(const std::string& cty, std::string& chainOut,
                                     std::set<std::string>& seen)
{
    // Peel the pointer(s): `UnsafePtr<T>` lowers to `T*` and `UnsafeConstPtr<T>` east-const to `T const*`.
    std::string t = cty;
    while (!t.empty() && t[t.size() - 1] == '*') {
        t.erase(t.size() - 1);
        const std::string cq = " const";
        if (t.size() > cq.size() && t.compare(t.size() - cq.size(), cq.size(), cq) == 0)
            t.erase(t.size() - cq.size());
    }
    auto sit = _sigs.find(t);
    if (sit != _sigs.end()) return !sit->second.foreignEntry && !sit->second.callerThread;
    auto cit = _classes.find(t);
    if (cit == _classes.end() || !seen.insert(t).second) return false;
    for (auto& f : cit->second.fields) {
        std::string sub;
        if (reachesUnannotatedSig(fieldCType(t, f), sub, seen)) {
            chainOut = f.name + (sub.empty() ? "" : "." + sub);
            return true;
        }
    }
    return false;
}

// A `fnptr`-typed destination in any position OTHER than a local initializer — an assignment, a call
// argument, a return, a field or module `static` initializer. Reached from `rejectValueKindMismatch`,
// which is the funnel every one of those already passes through with the destination's C type in hand.
void CEmitter::checkFnPtrValueBind(const std::string& dstCType, SharedExpression value, int line)
{
    if (!value || !isSigType(dstCType)) return;
    FnPtrTarget t;
    if (!resolveFnPtrTarget(value, t)) return;   // not a bindable name — the kind rule below judges it
    checkFnPtrBind(dstCType, t, line);
}

// A kama function crossing to C (ROADMAP row 1). The seam must state the callee's THREADING contract,
// and it is a declaration rather than an inference because the compiler genuinely cannot derive it:
// `kama_run_loop` is `while (tick(state)) { }` and a device callback runs on a thread kama never created,
// and nothing in either signature says which. Get it wrong and the failure is silent — a module `static`
// set up during startup reads back as its declared initialiser inside the callback, because
// KAMA_ISOLATE_LOCAL is `_Thread_local`.
//
// Called per argument from `emitReorderedCall`, the one funnel every resolved call passes through.
void CEmitter::checkForeignCrossing(const std::string& calleeCName, const ParamSig& p,
                                    SharedExpression argExpr, int line)
{
    if (_probingTemplate || !argExpr) return;   // a probe emits nothing, so it teaches nothing
    auto cit = _funcs.find(calleeCName);
    if (cit == _funcs.end() || !isExtern(cit->second.node)) return;

    // The `fnptr` type is where the contract is declared, and it can be seen from either end. The
    // PARAMETER names it when the seam is written in kama (`extern fn void kama_run_loop(TickFn tick,
    // …)`). Where the parameter is a raw header typedef — `CompareFn` from `cb.h`, which
    // `checkDeclaredTypes` deliberately passes through verbatim as the FFI seam working as designed —
    // the kama type is visible only on the ARGUMENT, underneath the cast that bridges to it.
    SharedExpression e = argExpr;
    while (auto* c = dynamic_cast<CastNode*>(e.get())) e = c->unaryExpression;
    std::string sig = isSigType(p.className) ? p.className : std::string();
    if (sig.empty()) { const std::string ec = exprClass(e); if (isSigType(ec)) sig = ec; }

    if (!sig.empty()) {
        auto sit = _sigs.find(sig);
        if (sit == _sigs.end() || sit->second.foreignEntry || sit->second.callerThread) return;
        unsupported(("`" + demangleForDisplay(sig) + "` is handed to the C function `" + calleeCName
                     + "`, and a callback's threading contract cannot be inferred — mark the `fnptr` "
                       "type `@callerThread` if the C API calls it on the calling isolate, or "
                       "`@foreignEntry` if it may run on a thread kama did not create (where a module "
                       "`static` assigned elsewhere is a different object)").c_str(), line);
        return;
    }
    // A COMPOSITE crossing, carrying the callback one or more fields down. A `type extern value` is
    // already answered for at every bind (see `_cVisibleSigs`), so what is left here is an ordinary kama
    // type handed to C — where the bind was legitimate (an `fnptr` field on a kama type is a callback
    // table) and the crossing is the first place the contract can be demanded. Both ends are asked,
    // because either can be the one that names the type: the PARAMETER does when the seam is written in
    // kama, and the ARGUMENT does when the parameter is an opaque `void*` and the kama type is visible
    // only underneath the cast this function already unwrapped.
    {
        std::string chain;
        for (const std::string& cand : { p.className, exprClass(e) }) {
            if (cand.empty()) continue;
            // Behind a pointer too (`UnsafeConstPtr<Holder>` + `addr(of:)`): since KR-45 a plain type cannot
            // cross BY VALUE at all, so the pointer is the one route left, and the filter looked the POINTER
            // type up (`Holder const*`), found no class, and let it through unwalked.
            std::string base = cand;
            while (!base.empty() && base.back() == '*') {
                base.pop_back();
                const std::string cq = " const";
                if (base.size() > cq.size() && base.compare(base.size() - cq.size(), cq.size(), cq) == 0)
                    base.erase(base.size() - cq.size());
            }
            auto cc = _classes.find(base);
            if (cc == _classes.end() || cc->second.isExternStruct) continue;
            std::set<std::string> seen;
            if (!reachesUnannotatedSig(base, chain, seen) || chain.empty()) continue;
            unsupported(("`" + demangleForDisplay(base) + "` is handed to the C function `" + calleeCName
                         + "` carrying a callback in `" + demangleForDisplay(base) + "." + chain + "`, and "
                         "a callback's threading contract cannot be inferred — mark that `fnptr` type "
                         "`@callerThread` if the C API calls it on the calling isolate, or `@foreignEntry` "
                         "if it may run on a thread kama did not create (where a module `static` assigned "
                         "elsewhere is a different object)").c_str(), line);
            return;
        }
    }
    // A bare function name handed straight to C, with no `fnptr` type to carry the contract at all.
    if (auto* id = dynamic_cast<IdentifierNode*>(e.get())) {
        if (!id->value || _localTypes.count(*id->value)) return;
        auto fit = _funcs.find(resolveFunc(*id->value, id->qualifier));
        if (fit == _funcs.end() || isExtern(fit->second.node)) return;
        unsupported(("function `" + *id->value + "` is handed to the C function `" + calleeCName
                     + "` with no `fnptr` type to carry its threading contract — declare one, mark it "
                       "`@callerThread` or `@foreignEntry`, and bind through it").c_str(), line);
    }
}

// bind a value to a FunctionPtr<Sig> local — a free function name (resolve +
// signature-check) or another FunctionPtr (copy). Non-null: `null`/unknown is an error.
std::string CEmitter::emitFnPtrBind(const std::string& sigCName, SharedExpression init, int line)
{
    FnPtrTarget t;
    if (resolveFnPtrTarget(init, t)) {
        if (t.kind == FnPtrTarget::SigValue) return emitExpression(init);
        if (t.id) recordNodeRef(t.id, t.node);   // M6 B3a: `Type::m` as a fn pointer references m
        checkFnPtrBind(sigCName, t, line);
        return t.cName;
    }
    unsupported("a FunctionPtr binds a free function name or another FunctionPtr (and may not be null)", line);
    return "0";
}

// `BindableFunctionPtr.bind(obj: x, method: T::m)` — bind an object + a method, the one intrinsic built by a
// named constructor (dot-on-type), like every kama type. Ownership follows x's pointer type: Owned MOVES in
// (sole owner), Shared RETAINS (shared owner). The receiver is hidden, so Sig excludes it. The type's
// argument comes from the destination (`BindableFunctionPtr<Compare> c = BindableFunctionPtr.bind(…)`), as
// `Channel.bounded(…)` takes its element.
void CEmitter::emitBindableBind(const std::string& nm, const std::string& octy,
                                const SharedArgumentList& args, int ln, int depth)
{
    const std::string& sigCName = _classes[octy].collElemClass;

    SharedExpression objArg, methodArg;
    if (args)
        for (auto& a : *args) {
            if (!a || !a->name || !a->name->value) continue;
            if (*a->name->value == "obj")    objArg = a->expression;
            else if (*a->name->value == "method") methodArg = a->expression;
        }
    if (!objArg || !methodArg) {
        unsupported("BindableFunctionPtr needs obj: <Owned/Shared> and method: <Type::method>", ln); return;
    }

    // The object: a library `Owned`/`Shared` over a CONCRETE type — the method is `Type::method` on that
    // type, so a contract handle (`Owned<I>`) has no method to name. A `Weak` doesn't keep the object alive,
    // so it can't be bound. `retain` = shared ownership (bump the count); else MOVE.
    std::string objCls = exprClass(objArg);
    std::string T      = heapOwnerTarget(objCls);               // library heap-owner pointee ("" otherwise)
    if (T.empty()) {
        unsupported("BindableFunctionPtr obj: must be an Owned<T> or Shared<T> over a concrete type (the "
                    "method is `T::method`)", ln); return;
    }
    bool retain = isCopyable(objCls);
    std::string objE = emitExpression(objArg);

    // The method: a `Type::method` unbound reference.
    auto* mid = dynamic_cast<IdentifierNode*>(methodArg.get());
    if (!mid || !mid->value || !mid->qualifier || mid->qualifier->empty()) {
        unsupported("BindableFunctionPtr method: must be a `Type::method` reference", ln); return;
    }
    auto prefix = std::make_shared<StringList>();
    for (size_t i = 0; i + 1 < mid->qualifier->size(); ++i) prefix->push_back((*mid->qualifier)[i]);
    std::string cls = resolveUserName(*mid->qualifier->back(), prefix);
    ClassInfo* owner = nullptr;
    MethodInfo* mi = _classes.count(cls) ? findMethod(&_classes[cls], *mid->value, &owner) : nullptr;
    if (!mi) { unsupported("unknown method in BindableFunctionPtr method:", ln); return; }
    recordNodeRef(mid, mi->node);   // M6 B3a: `method:` names the method, same as any other call site
    if (cls != T) {
        unsupported("BindableFunctionPtr obj: type does not match the method's class", ln); return;
    }

    // Signature check: the method's params + return (receiver HIDDEN) must equal Sig.
    FuncSig stripped;
    stripped.cName = mi->cName; stripped.retCType = cType(mi->returnType); stripped.params = mi->params;
    if (!sigMatches(_sigs.at(sigCName), stripped))
        unsupported("the method does not match the BindableFunctionPtr signature (the receiver is hidden)", ln);
    // ...and the same `@noheap` promise the bare `fnptr` bind is held to. A bindable is called through
    // the identical blind seam, so a signature that promises must be satisfied here too, or binding an
    // allocating method would launder the guarantee the `fnptr` form refuses to launder.
    else if (_sigs.at(sigCName).noHeap && !mi->noHeap)
        unsupported(("method '" + cls + "::" + *mid->value + "' is bound to `" + demangleForDisplay(sigCName)
                     + "`, which is `@noheap` — declare `" + cls + "::" + *mid->value + "` `@noheap` too, "
                       "so a no-heap caller calling through the slot still gets the guarantee").c_str(), ln);

    // The release: give the object back to the handle it came from. A thunk rebuilds that library owner from
    // (obj, ctrl) and runs ITS destructor, so the bindable never re-derives how the object is dropped (a
    // virtual drop for a base holding a derived), which allocator the block goes back to, or its size. The
    // rebuilt handle's `alloc` is the allocator's DEFAULT value — so a bind needs one: a stateful allocator
    // (an arena's `BumpAllocator`) cannot be recreated from nothing, and would otherwise be released through
    // a zero handle. The same `when [A: default]` rule that gates `Owned.adopt`.
    std::string releaseFn;
    {
        std::string allocInit;
        for (auto& f : _classes[objCls].fields) {
            if (f.name != "alloc") continue;
            std::string act = fieldCType(objCls, f);
            if (!isDefaultFillable(act)) {
                unsupported(("BindableFunctionPtr obj: `" + demangleForDisplay(objCls) + "` draws from `"
                             + demangleForDisplay(act) + "`, which has no `default` ctor — a bindable releases "
                               "its object through a default allocator value, so bind a box whose allocator "
                               "is stateless (`GlobalAllocator`, or a type with a `default ctor`)").c_str(), ln);
                return;
            }
            auto ait = _classes.find(act);
            if (ait != _classes.end())
                for (auto& kv : ait->second.methods)
                    if (kv.second.isDefaultCtor) { allocInit = "    h.alloc = " + kv.second.cName + "();\n"; break; }
        }
        releaseFn = "__kama_bind_release_" + objCls;
        if (_moduleHelperKeys.insert("bind:" + objCls).second) {
            std::ostringstream th;
            th << "static void " << releaseFn << "(void* obj, kama_ctrl* ctrl) {\n"
               << "    " << objCls << " h = {0};\n"
               << "    h.p = (" << T << "*)obj;\n";
            if (retain) th << "    h.c = (void*)ctrl;\n";
            else        th << "    (void)ctrl;\n";
            th << allocInit
               << "    " << objCls << "__dtor(&h);\n"
               << "}\n";
            _fileScopeHelpers.push_back(th.str());
        }
    }
    // The receiver pointer comes from `deref()` (T*); the refcount block is the library `.c`, whose `Ctrl`
    // layout is `kama_ctrl`-compatible (`usize` counts for this).
    indent(depth); *_out << nm << ".obj = (void*)" << derefFnName(objCls, true) << "(&(" << objE << "));\n";
    if (retain) { indent(depth); *_out << nm << ".ctrl = (kama_ctrl*)(" << objE << ").c;\n"; }
    indent(depth); *_out << nm << ".fn = (void (*)(void))" << mi->cName << ";\n";
    indent(depth); *_out << nm << ".release = " << releaseFn << ";\n";
    // Ownership transfer: a shared owner RETAINS (bump strong); a unique owner MOVES — consume the source at
    // COMPILE time so its dtor is skipped (the bindable now owns the pointee and releases it).
    if (retain) { indent(depth); *_out << "if (" << nm << ".ctrl) " << nm << ".ctrl->strong++;\n"; }
    else { std::string mv = moveOnlySource(objArg, ln); if (!mv.empty()) markMoved(mv); }
}

// `BindableFunctionPtr.bind(…)` — the dot-on-type constructor call, or null. The receiver is the bare type
// name (its argument comes from the destination), so no binding of that name may shadow it.
InvocationNode* CEmitter::bindableBindCall(const SharedExpression& e)
{
    auto* call = dynamic_cast<InvocationNode*>(e.get());
    auto* ma = call ? dynamic_cast<MemberAccessNode*>(call->expression.get()) : nullptr;
    auto* rid = ma ? dynamic_cast<IdentifierNode*>(ma->expression.get()) : nullptr;
    if (!rid || !rid->value || *rid->value != "BindableFunctionPtr" || (rid->qualifier && !rid->qualifier->empty()))
        return nullptr;
    if (!ma->identifier || !ma->identifier->value || *ma->identifier->value != "bind") return nullptr;
    return call;
}

// `BindableFunctionPtr<Sig> b = <free fn | another bindable>;` — promote a free
// function (no object) or MOVE another bindable.
void CEmitter::emitBindablePromote(const std::string& nm, const std::string& ty,
                                   SharedExpression init, int depth)
{
    const std::string& sigCName = _classes[ty].collElemClass;

    if (InvocationNode* bind = bindableBindCall(init)) {
        line(init->line);
        emitBindableBind(nm, ty, bind->args, init->line, depth);
        return;
    }
    if (auto* id = dynamic_cast<IdentifierNode*>(init.get())) {
        if (id->value) {
            // Another BindableFunctionPtr lvalue -> move (copy + invalidate the source).
            if (isBindableClass(exprClass(init))) {
                std::string src = emitExpression(init);
                indent(depth); *_out << nm << " = " << src << ";\n";
                indent(depth);
                *_out << "(" << src << ").obj = NULL; (" << src << ").ctrl = NULL; ("
                      << src << ").fn = NULL; (" << src << ").release = NULL;\n";
                return;
            }
            // A free function -> promote (obj = NULL; no RAII).
            auto fit = _funcs.find(resolveFunc(*id->value, id->qualifier));
            if (fit != _funcs.end()) {
                if (!sigMatches(_sigs.at(sigCName), fit->second))
                    unsupported("function does not match the BindableFunctionPtr signature", init->line);
                else if (_sigs.at(sigCName).noHeap && !fnHasNoHeap(fit->second.node))
                    unsupported(("function '" + *id->value + "' is bound to `" + demangleForDisplay(sigCName)
                                 + "`, which is `@noheap` — declare `" + *id->value + "` `@noheap` too, so a "
                                   "no-heap caller calling through the slot still gets the guarantee").c_str(),
                                init->line);
                indent(depth);
                *_out << nm << ".obj = NULL; " << nm << ".ctrl = NULL; " << nm << ".fn = (void (*)(void))"
                      << fit->second.cName << "; " << nm << ".release = NULL;\n";
                return;
            }
            unsupported("a BindableFunctionPtr binds via `BindableFunctionPtr.bind(obj:, method:)`, "
                        "a free function, or another BindableFunctionPtr", init->line);
            return;
        }
    }
    // A bindable-valued rvalue (e.g. a factory call) is already moved out — plain copy.
    std::string src = emitExpression(init);
    indent(depth); *_out << nm << " = " << src << ";\n";
}

// invoke a bindable — branch on obj (bound: pass it first; free: call directly).
// The signature drives the fn-pointer casts and the named-arg reorder.
std::string CEmitter::emitBindableInvoke(const std::string& recv, const std::string& cls,
                                         SharedArgumentList args, int line)
{
    const SigInfo& sig = _sigs.at(_classes[cls].collElemClass);
    // No-heap gate, and the same escape as the bare `fnptr`: a bindable's `Sig` IS an `fnptr` type, so a
    // `@noheap` signature has had every promotion and every `obj:`/`method:` bind checked against the
    // promise, and the call through it is provable.
    if (!sig.noHeap) rejectNoHeapIndirect("through a bound function pointer", line);
    std::string plist;
    for (size_t i = 0; i < sig.params.size(); ++i)
        plist += (i ? ", " : "") + sig.params[i].className + (sig.params[i].byRef ? "*" : "");
    std::string boundT = sig.retCType + " (*)(void*" + (sig.params.empty() ? "" : ", " + plist) + ")";
    std::string freeT  = sig.retCType + " (*)(" + (sig.params.empty() ? std::string("void") : plist) + ")";
    // A `@noheap` signature is proven (every bind was checked), so the type-erased `fn` read carries the
    // marker the call graph reads; unmarked, it is a fact for the calling body like any other slot call.
    auto slot = [&](const std::string& t) {
        const std::string f = "((" + t + ")" + recv + ".fn)";
        return sig.noHeap ? ("KAMA_NOHEAP_SLOT(" + f + ")") : f;
    };
    std::string boundCall = emitReorderedCall(slot(boundT), recv + ".obj", sig.params, args, line);
    std::string freeCall  = emitReorderedCall(slot(freeT), "", sig.params, args, line);
    return "(" + recv + ".obj ? " + boundCall + " : " + freeCall + ")";
}

// Lower a call, reordering named arguments to the callee's declared order.
// the switch body shared by both `match` positions. Borrows the subject (a pointer, never a
// copy — a move-only union must not be shallow-copied), checks exhaustiveness, binds each arm's
// payload into a fresh scope, and either assigns the arm value to `resultTemp` (expression position)
// or emits it as a side-effect statement (statement position). Writes to the current `_out`.
// Materialize `value` into the already-declared lvalue `dst` (of type `dstCType`), honoring an owned
// hand-off: unwrap a give/copy marker, resolve an inline ctor/`new`/bare-generic-ctor from `dstCType`, then
// apply the give/copy matrix (smart-ptr / resource / collection / bindable — move consumes the source, copy
// duplicates). Mirrors the `return`-value hand-off, shared with value-producing `match` arms.
void CEmitter::emitOwnedValueInto(const std::string& dst, const std::string& dstCType,
                                  SharedExpression value, int line, int depth, const char* what, bool kindChecked)
{
    int handoff = 0;   // 0 none, 1 give, 2 copy
    SharedExpression v = value;
    if (v) if (auto* h = dynamic_cast<HandoffNode*>(v.get())) { handoff = h->isGive ? 1 : 2; v = h->value; }
    // The kind rule, one site for both hand-offs this function serves: a `return` value and a
    // value-producing `match` arm. Checked on the UNWRAPPED value, so `return give x;` is judged on `x`.
    // `dstCType` is empty for a void return and for a statement-position `match`, which reads as Unknown
    // and says nothing — the same silence every other unresolved destination gets.
    // A FIELD initializer was judged at its declaration, on its own line (checkDeclaredTypes); judging it again
    // here would repeat it against the ctor that runs it.
    if (!kindChecked) {
        rejectValueKindMismatch(dstCType, v, what, line);
        rejectContractNonConformance(dstCType, v, what, line);     // the branch that rule leaves to a contract
    }
    bool ph = _hoistOK; _hoistOK = true;                       // inline-ctor hoisting
    std::string pmt = _matchTargetCType; _matchTargetCType = dstCType;   // `:= match(…)` / bare generic ctor
    std::string pvt = _variantTargetType; _variantTargetType = dstCType; // `:= Optional::Some(…)`
    std::string rv = tryHoistInlineCtor(v, dstCType, line);    // `:= Point(…)` / `:= List()`
    if (rv.empty()) rv = tryHoistInlineValue(v, dstCType, line); // `:= new T(…)`
    if (rv.empty()) rv = narrowViewValue(dstCType, v, emitExpression(v), line);   // `return v;` into a `ConstView<T>`
    if (ctorThisAsValue(v, dstCType)) rv = "(*" + rv + ")";   // `return give this;` — the early-return form
    _matchTargetCType = pmt; _variantTargetType = pvt; _hoistOK = ph;
    flushHoisted(depth);
    // The value line is where the user's expression IS, and both callers — a `return` and a
    // value-producing `match` arm — declare the destination temp on the line above it. Without a stamp
    // here that declaration consumes the enclosing `#line` and every C-compiler error in the expression is
    // reported one line low. `this->` because the parameter shadows the stamper.
    this->line(line);
    indent(depth); *_out << dst << " = " << rv << ";\n";
    std::string rc = handoffSourceClass(v, handoff);
    rejectUnresolvedHandoff(rc, dstCType, v, handoff, what, line);
    // Smart pointer: give (or a bare dying local) MOVES out (invalidate the source); copy RETAINS.
    if (isSmartPtrClass(rc) && isNamedValue(v.get())) {
        CollKind k = smartKind(rc);
        bool doGive;
        if (handoff == 1)      doGive = true;
        else if (handoff == 2) { if (k == CollKind::Owned)
                                     unsupported("an `Owned` is unique — it can't be `copy`'d; use `give` to move it", line);
                                 doGive = false; }
        else if (isSmartPtrLValue(v)) doGive = true;           // bare local/param dies here: move it out
        else { unsupported("handing out a smart-pointer field/element needs `give` (move it out) or "
                           "`copy` (retain — the source stays valid)", line); doGive = true; }
        indent(depth);
        if (doGive) *_out << smartPtrInvalidate(emitExpression(v), k, isInterface(_classes[rc].collElemClass)) << "\n";
        else        *_out << "(" << emitExpression(v) << ").ctrl->" << (k == CollKind::Weak ? "weak" : "strong") << "++;\n";
    }
    // Destructible `resource` VALUE: give MOVES (mark source moved), copy duplicates via copy().
    else if (isMoveOnlyValue(rc) && isNamedValue(v.get())) {
        bool cpy = isCopyable(rc);
        bool doCopy;
        if (handoff == 2) { if (!cpy) unsupported(("`" + rc + "` has no `copy` method — add `implements "
                                                   "Copyable(bare: …)`, or use `give` to move it").c_str(), line);
                            doCopy = cpy; }
        else if (handoff == 1) doCopy = false;
        else doCopy = cpy && _classes[rc].bareDefault == COPY;
        if (doCopy) { indent(depth); *_out << dst << " = " << copyCall(rc, emitExpression(v)) << ";\n"; }
        else { std::string mv = moveOnlySource(v, line); if (!mv.empty()) markMoved(mv); }
    }
    // Named collection/`string` VALUE (exprClass is "" — key on dstCType): give/bare-dying moves, copy deep-copies.
    else if (ownsByValue(dstCType) && _classes.count(dstCType) && _classes[dstCType].isIntrinsicColl
             && isNamedValue(v.get())) {
        if (handoff == 2) {
            auto ci = _collections.find(dstCType);
            if (ci != _collections.end() && ci->second.elemDestructible && !ci->second.elemCopyable)
                unsupported(("`copy` of a `" + dstCType + "` needs copyable elements — use `give` to move it").c_str(), line);
            else { indent(depth); *_out << dst << " = " << copyCall(dstCType, emitExpression(v)) << ";\n"; }
        } else { std::string mv = moveOnlySource(v, line); if (!mv.empty()) markMoved(mv); }
    }
    // A named BindableFunctionPtr may own its bound object: null the source so its scope-drop no-ops.
    else if (auto* rid = dynamic_cast<IdentifierNode*>(v.get())) {
        if (rid->value && isBindableClass(exprClass(v))) {
            std::string e = emitExpression(v);
            indent(depth);
            *_out << "(" << e << ").obj = NULL; (" << e << ").ctrl = NULL; ("
                  << e << ").fn = NULL; (" << e << ").release = NULL;\n";
        }
    }
}

void CEmitter::emitMatchSwitch(MatchNode* m, const std::string* resultTemp, int depth)
{
    // A1: an inline variant ctor as the SUBJECT pins `_variantTargetType` while the subject is
    // materialized (below) so the same instance is constructed. The recovery itself is shared with the
    // classifier, which needs the identical answer and may not diagnose — see `matchSubjectClassQuiet`.
    bool inlineVariantSubj = false;
    std::string handleCls;   // non-empty: the subject is an `Owned`/`Shared` over the enum, borrowed through
    std::string subjCls = matchSubjectClassQuiet(m, &inlineVariantSubj, &handleCls);
    auto cit = _classes.find(subjCls);
    if (cit == _classes.end() || !cit->second.isVariant) {
        std::string enumTy = exprEnumType(m->subject);
        if (enumTy.empty() && cit != _classes.end() && cit->second.isScalarEnum() && handleCls.empty())
            enumTy = subjCls;
        if (!enumTy.empty()) { emitMatchPlainEnum(m, enumTy, resultTemp, depth); return; }
        // Say which of the two it is. Claiming "requires an enum subject" about a resolvable non-enum
        // named the wrong cause; claiming it about something unresolvable said nothing about the fix.
        // A `Weak` over an enum is the one handle not seen through: it may already be dangling.
        const bool weakEnum = subjCls.rfind("std__memory__Weak", 0) == 0 && _classes.count(subjCls)
                           && [&] { auto g = _genericTypeInsts.find(subjCls);
                                    if (g == _genericTypeInsts.end() || g->second.typeArgs.empty()) return false;
                                    auto pc = _classes.find(cType(g->second.typeArgs[0]));
                                    return pc != _classes.end() && pc->second.isVariant; }();
        if (weakEnum)
            unsupported(("`match` subject is a `" + demangleForDisplay(subjCls) + "`, which may no longer point at "
                         "anything — upgrade it first (`tryUpgrade()` gives an `Optional<Shared<…>>`) and match "
                         "the `Shared`").c_str(), m->line);
        else if (!subjCls.empty())
            unsupported(("`match` subject has type `" + subjCls + "`, which is neither an enum nor a "
                         "tagged union").c_str(), m->line);
        else {
            // A downcast whose TARGET does not resolve is why its type is unknown — name that name, not the
            // shape of the `match`.
            const auto before = _unsupported;
            if (auto* ad = dynamic_cast<AsDowncastNode*>(m->subject.get()))
                checkBodyType(ad->type, "an `.as<T>()` target", ad->type ? ad->type->line : m->line);
            if (_unsupported == before)
                unsupported("`match` subject's type could not be resolved — bind it to a typed local first "
                            "(a nested value-producing `match` or a variant-producing ternary needs one)", m->line);
        }
        return;
    }
    ClassInfo& ci = cit->second;

    // A specialized generic union (Optional_int32) stores its variant payloads in the TEMPLATE's `T`, so
    // every payload type below is resolved in the SUBJECT's instance — `cTypeInInstance` /
    // `deepSubstInInstance`, one scoped binding per resolution.
    //
    // ⚠️ It used to be one binding held open across the WHOLE switch, justified by "arm bodies contain no
    // `T`, so a whole-switch scope is safe". That is false wherever the `match` sits inside a generic
    // scope: the arm body's `T` is the ENCLOSING generic's, and clearing `_typeSubst` for the subject
    // replaced it. `T local = this.item;` in an arm of `Box<A>.run(Optional<B>)` emitted `B local` and
    // `kama check` said OK — clang refused the C. Only these three payload resolutions ever wanted the
    // subject's args; the arm bodies, and the subject expression itself, want the enclosing scope's.

    // Exhaustiveness (compile-time): every variant handled exactly once, unless a `_` wildcard is present.
    bool hasWildcard = false;
    std::set<std::string> covered;
    for (auto& a : *m->arms) {
        if (a->isWildcard()) { hasWildcard = true; continue; }
        std::string vn = a->variantName ? *a->variantName : "";
        bool found = false;
        for (auto& v : ci.variants) if (v.name == vn) { found = true; break; }
        if (found) recordRef(enumMemberKey(subjCls, vn), a->variantId.get());   // LSP: the arm uses the case
        if (!found)          unsupported(("`match` arm names unknown variant '" + vn + "' of '" + subjCls + "'").c_str(), a->line);
        if (covered.count(vn)) unsupported(("duplicate `match` arm for variant '" + vn + "'").c_str(), a->line);
        covered.insert(vn);
    }
    if (!hasWildcard)
        for (auto& v : ci.variants)
            if (!covered.count(v.name))
                unsupported(("`match` on '" + subjCls + "' is not exhaustive: variant '" + v.name
                             + "' is unhandled — add `case " + v.name + ":` or `case _:`").c_str(), m->line);

    // The subject is borrowed by pointer. A plain lvalue is addressed in place; a non-lvalue
    // (a call / construction result) can't be `&`-taken, so materialize an OWNING temp
    // first and drop it after the switch (arm payload bindings borrow it, like a foreach element).
    std::string sp = "__msub" + std::to_string(_tempCounter++);
    // `match (give x)` CONSUMES the subject: it materializes an owning temp (the non-lvalue path below), and
    // an owning payload binding MOVES out of it (destructure-move) rather than borrowing.
    bool subjConsumed = dynamic_cast<HandoffNode*>(m->subject.get()) != nullptr;
    bool subjLvalue = dynamic_cast<IdentifierNode*>(m->subject.get())
                   || dynamic_cast<MemberAccessNode*>(m->subject.get())
                   || dynamic_cast<ThisAccessNode*>(m->subject.get())
                   || dynamic_cast<ElementAccessNode*>(m->subject.get());
    std::string subjOwner;
    size_t subjLocMark = 0;      // where the subject temp sits in the enclosing scope; see the drop below
    // Evaluate the subject FIRST, then flush any temps it hoisted (e.g. a `string` literal materialized for
    // a `ref string` param — `match (map.get("k"))`), so their decls land BEFORE the subject line, not
    // inside the first arm body (which would leave them undeclared at the point of use).
    if (!handleCls.empty()) {
        // `match (h)` through a heap handle: borrow the pointee in place, so payload bindings borrow from the
        // object the handle owns. A lvalue handle is dereffed where it lives; a call result is held in a temp
        // (the handle, dropped after the switch — releasing its share) and dereffed there.
        if (subjConsumed) {
            unsupported(("`match (give …)` on a `" + demangleForDisplay(handleCls) + "` — a handle's enum is "
                         "borrowed through it, not moved out of it; match the handle itself (`match (h)`)").c_str(),
                        m->line);
            return;
        }
        const bool lib = !heapOwnerTarget(handleCls).empty();
        bool ph = _hoistOK; _hoistOK = true;
        std::string hExpr = emitPlace(m->subject);
        _hoistOK = ph;
        flushHoisted(depth);
        std::string place = hExpr;
        if (!subjLvalue) {
            subjLocMark = _scopes.empty() ? 0 : _scopes.back().locals.size();
            subjOwner = "__msubj" + std::to_string(_tempCounter++);
            indent(depth); *_out << handleCls << " " << subjOwner << " = " << hExpr << ";\n";
            recordDestructibleLocal(subjOwner, handleCls);   // see the drop below
            place = subjOwner;
        }
        indent(depth); *_out << subjCls << "* " << sp << " = (" << subjCls << "*)"
                             << (lib ? derefFnName(handleCls, true) + "(&(" + place + "))"
                                     : "(" + place + ").ptr") << ";\n";
    } else if (subjConsumed) {
        // `match (give x)`: the subject is a hand-off. Emit the moved-from source, materialize an owning temp
        // (bitwise handle copy), and mark the source moved (its own scope-drop then no-ops). Payload bindings
        // MOVE out of this temp (destructure-move); the temp's post-switch drop no-ops the defused slots.
        auto* h = dynamic_cast<HandoffNode*>(m->subject.get());
        // No `_hoistOK` here, unlike the sibling branch below: `give` moves a named local, and a call
        // result or an inline ctor is refused outright ("cannot `give` out of a field/element"), so this
        // subject can never carry an argument temp to hoist.
        std::string subjExpr = emitExpression(h->value);
        flushHoisted(depth);
        subjLocMark = _scopes.empty() ? 0 : _scopes.back().locals.size();
        subjOwner = "__msubj" + std::to_string(_tempCounter++);
        indent(depth); *_out << subjCls << " " << subjOwner << " = " << subjExpr << ";\n";
        indent(depth); *_out << subjCls << "* " << sp << " = &" << subjOwner << ";\n";
        recordDestructibleLocal(subjOwner, subjCls);   // see the drop below
        std::string mv = moveOnlySource(h->value, m->line); if (!mv.empty()) markMoved(mv);
    } else {
    // A1: pin the concrete instance so the inline variant ctor constructs `Optional_int32`, not bare `Optional`.
    // A value-producing nested `match`/variant-ternary subject needs the SAME pin: emitMatch requires a
    // non-empty `_matchTargetCType` + a statement slot (`_hoistOK`), and a ternary's inline variant ctors
    // need `_variantTargetType`, so the materialized owning temp is the resolved `subjCls`.
    bool valueSubj = inlineVariantSubj
                  || dynamic_cast<MatchNode*>(m->subject.get())
                  || dynamic_cast<TernaryExpressionNode*>(m->subject.get());
    std::string pvt = _variantTargetType, pmt = _matchTargetCType; bool ph = _hoistOK;
    if (valueSubj) { _variantTargetType = subjCls; _matchTargetCType = subjCls; }
    // `_hoistOK` for EVERY subject, not just a value-producing one. The subject stands in a statement slot
    // and its temps are flushed on the next line, which is the whole precondition hoisting asks for — and
    // the comment above already claimed this worked ("a `string` literal materialized for a `ref string`
    // param"). It did not: the materialization arms in emitReorderedCall are gated on `_hoistOK`, so
    // `match (f(s: "lit"))` on a `const ref string` parameter emitted `&(kama_string_lit(…))` and only
    // clang objected — "cannot take the address of an rvalue" — while `Optional<T> o = f(s: "lit");` one
    // line up compiled. A check/build divergence, and the kind a fixture only finds by being written.
    _hoistOK = true;
    // A PLACE, for the same reason the assignment target one file over is one: `subjLvalue` below already
    // CLAIMS an element access is an lvalue and then takes its address, and `emitExpression` of an
    // intrinsic-collection element is the by-value `Coll__get(…)` — so `match (os[0])` emitted
    // `&(InlineArray…__get(…))` and only clang objected ("cannot take the address of an rvalue"). Same
    // classify-one-way/spell-the-other shape as the element store. `emitPlace` falls through to
    // `emitExpression` for every other subject, so a value-producing subject is untouched.
    std::string subjExpr = emitPlace(m->subject);
    _variantTargetType = pvt; _matchTargetCType = pmt; _hoistOK = ph;
    flushHoisted(depth);
    if (dynamic_cast<ThisAccessNode*>(m->subject.get())) {
        // `this` emits as `self`, which is ALREADY a `subjCls*` (the receiver pointer) — do NOT re-address
        // it (`&self` would point at the parameter slot). Reachable only for `match (this)` in a method on
        // an enum (the only way `this` is a variant subject). (Model C: `type enum … implements Error`.)
        indent(depth); *_out << subjCls << "* " << sp << " = " << subjExpr << ";\n";
    } else if (subjLvalue) {
        indent(depth); *_out << subjCls << "* " << sp << " = &(" << subjExpr << ");\n";
    } else {
        subjLocMark = _scopes.empty() ? 0 : _scopes.back().locals.size();
        subjOwner = "__msubj" + std::to_string(_tempCounter++);
        indent(depth); *_out << subjCls << " " << subjOwner << " = " << subjExpr << ";\n";
        indent(depth); *_out << subjCls << "* " << sp << " = &" << subjOwner << ";\n";
        recordDestructibleLocal(subjOwner, subjCls);   // see the drop below
    }
    }
    indent(depth); *_out << "switch (" << sp << "->tag) {\n";
    auto beforeMove = _moveState;                            // each arm branches from the same pre-match state
    std::vector<std::map<std::string, MoveState>> armEnds;
    std::vector<bool> armDivs;
    for (auto& a : *m->arms) {
        _moveState = beforeMove;
        indent(depth + 1);
        if (a->isWildcard()) *_out << "default: {\n";
        else                 *_out << "case " << subjCls << "_" << *a->variantName << ": {\n";
        // Each arm carries its OWN kama line. Without this the whole switch is attributed to the
        // `match` keyword's line and clang counts forward from there, so an error the C compiler finds in
        // arm 3 is reported several lines below the arm — measured past the end of a short file. An arm is
        // where the user wrote the expression, so it is where a `#line` belongs. It goes AFTER
        // the `case …: {` line, which would otherwise consume the stamp and push the body one line down —
        // naming the NEXT arm, the most misleading answer available.
        line(a->line);

        const VariantCase* vc = nullptr;
        if (!a->isWildcard()) for (auto& v : ci.variants) if (v.name == *a->variantName) { vc = &v; break; }

        // Fresh arm scope; bind the payload fields (borrowed copies — same as a foreach element).
        Scope sc; _scopes.push_back(sc);          // owns the arm's payload bindings — popScope retires them
        std::vector<std::string> borrowedHere;    // owning bindings marked non-giveable for this arm
        bool defusedSubject = false;              // this consumed arm moved an owning payload out of the subject
        if (a->bindings && !a->bindings->empty()) {
            // A pattern binds by FIELD NAME (`case Rect(w: width, h: height)`), never by position. Resolve
            // each label against the variant's payload and report precisely: an unknown label names the
            // fields that do exist, a repeat is caught, and a variant left partially bound is caught — a
            // silent mis-bind is exactly what the named form exists to make impossible.
            std::string arm = a->variantName ? *a->variantName : std::string("_");
            std::vector<size_t> slotOf(a->bindings->size(), SIZE_MAX);
            std::set<size_t> bound;
            for (size_t i = 0; vc && a->labels && i < a->labels->size(); ++i) {
                const std::string& lbl = *(*a->labels)[i];
                size_t f = SIZE_MAX;
                for (size_t k = 0; k < vc->payload.size(); ++k) if (vc->payload[k].name == lbl) { f = k; break; }
                if (f == SIZE_MAX) {
                    std::string have;
                    for (size_t k = 0; k < vc->payload.size(); ++k) have += (k ? ", " : "") + vc->payload[k].name;
                    unsupported(("`match` arm for '" + arm + "' binds unknown field `" + lbl + "` — `" + arm
                                 + "` has " + (have.empty() ? std::string("no fields") : have)).c_str(), a->line);
                } else if (!bound.insert(f).second) {
                    unsupported(("`match` arm for '" + arm + "' binds field `" + lbl + "` twice").c_str(), a->line);
                }
                slotOf[i] = f;
            }
            if (vc && bound.size() != vc->payload.size()) {
                std::string missing;
                for (size_t k = 0; k < vc->payload.size(); ++k)
                    if (!bound.count(k)) missing += (missing.empty() ? "" : ", ") + vc->payload[k].name;
                if (!missing.empty())
                    unsupported(("`match` arm for '" + arm + "' does not bind " + missing
                                 + " — a pattern names every field of its variant").c_str(), a->line);
            }
            for (size_t i = 0; vc && i < a->bindings->size(); ++i) {
                if (slotOf[i] == SIZE_MAX) continue;   // already diagnosed above
                std::string bn = *(*a->bindings)[i];
                // LSP index: the binding's own node (parallel list, same order) carries the span.
                if (a->bindingIds && i < a->bindingIds->size())
                    registerBinding((*a->bindingIds)[i].get(), SymKind::Local);
                int bnLine = (a->bindingIds && i < a->bindingIds->size() && (*a->bindingIds)[i])
                                 ? (*a->bindingIds)[i]->line : a->line;
                checkConstParamBinder(bn, "`match` binding", bnLine);
                checkBinderShadow(bn, "`match` binding", bnLine);
                const FieldInfo& pf = vc->payload[slotOf[i]];
                // Containment, on the position that made a TOKEN-based rule leak. `match (a.allocate(…))
                // { case Some(value: p): … }` binds an `UnsafePtr` and never spells the word — a rule
                // reading the spelled type would let a raw pointer into a function carrying no marker
                // (probed: a double free with zero `unsafe` tokens in the function). The payload's own
                // declared type is right here, so key on that.
                // SUBSTITUTED, unlike the signature rule. `Optional<UnsafePtr>` stores its payload in the
                // template's `T`, so the source spelling here is `T` and reads as safe. That is fine to do
                // at a USE site — the diagnostic lands on the `match` the author actually wrote — whereas
                // substituting in the signature rule would make a declaration's error depend on which
                // instantiation happened to exist.
                if (namesUnsafePtr(deepSubstInInstance(subjCls, pf.type)))
                    rejectRawOutsideUnsafe(("`match` binding `" + *(*a->bindings)[i] + "`").c_str(),
                                           (a->bindingIds && i < a->bindingIds->size() && (*a->bindingIds)[i])
                                               ? (*a->bindingIds)[i]->line : a->line);
                // The LABEL names the variant's field, so it is a reference to that field's declaration —
                // hover, go-to-definition and rename all reach it, the same as any other named use.
                if (a->labelIds && i < a->labelIds->size() && pf.nameId)
                    recordNodeRef((*a->labelIds)[i].get(), pf.nameId.get());
                // The arm scope owns the binding, and whatever the name meant outside is hidden for the
                // arm. FIRST — before the consumed-arm branch below seeds the binding's own move state,
                // which the snapshot must not capture and the hide must not erase.
                noteScopedBinding(bn);
                hideShadowedLocal(bn, /*refBinder=*/false);
                std::string bcty = fieldCType(subjCls, pf);
                std::string slot = std::string(sp) + "->u." + *a->variantName + "." + pf.name;
                indent(depth + 2);
                *_out << bcty << " " << bn << " = " << slot << ";\n";
                // Destructure-MOVE: when the subject is CONSUMED (`match (give x)`) and the payload is owning,
                // the binding takes ownership — defuse the subject slot (so the subject's drop no-ops it) and
                // register the binding as a movable owning local (RAII-dropped if not `give`n out, and giveable).
                // ⚠️ `isSmartPtrClass` as well as `ownsByValue`, and the omission was a latent double free
                // that only the subject temp's missing drop was hiding. `match (give r) { case Err(error:
                // e): return Result::Err(error: give e); }` — `std::serialization::text::json::encode`'s own
                // shape — binds an `Owned<Error>` fat handle, which is not `ownsByValue`, so it took
                // NEITHER branch: not defused (the subject kept owning the box) and not marked borrowed
                // (that arm is for a borrowing match), so `give e` moved an alias out from under a live
                // owner. It survived only because an arm that `return`s jumped over the bare dtor line
                // after the switch; the moment that drop became a real scope drop, the box was freed twice.
                // A consumed subject hands ownership to the binding whatever the payload's shape is.
                if (subjConsumed && (ownsByValue(bcty) || isSmartPtrClass(bcty))) {
                    indent(depth + 2); *_out << slot << " = (" << bcty << "){0};\n";
                    _scopes.back().locals.push_back({bn, bcty});
                    _moveState[bn] = MoveState::NotMoved;
                    defusedSubject = true;
                } else if (!subjConsumed && (ownsByValue(bcty) || isSmartPtrClass(bcty))) {
                    // BORROWING `match (x)`: this owning binding (a collection / move-only value / smart-ptr
                    // handle — incl. the interface-element fat handle `Owned<Error>`) only aliases the box the
                    // subject still owns. `give`ing it out double-frees. Mark it non-giveable for this arm.
                    _borrowedMatchBindings.insert(bn);
                    borrowedHere.push_back(bn);
                }
                _localTypes[bn] = (isClass(bcty) || isInterface(bcty) || isSigType(bcty)) ? bcty : "";
                // …and the TYPE NODE, which `_localTypes` deliberately drops (it keeps classes only, so a
                // primitive payload records ""). Without it the classifier cannot answer for a payload
                // binding, and milestone 6's rule did not hold through one: `int8 n = match (big()) { case
                // Some(value: c): c; … }` truncated an `int64` 300 to 44 in silence.
                //
                // SUBSTITUTED, for the reason the `namesUnsafePtr` check above is: a generic instance
                // stores its payload in the TEMPLATE's `T`, so `Optional<int64>` has `pf.type == T` and the
                // raw node would classify as nothing, so it is resolved in the SUBJECT's instance — a
                // binding scoped to this one resolution, never held open over the arm body.
                _localTypeNodes[bn] = deepSubstInInstance(subjCls, pf.type);
            }
        }

        // Drop-only-if-live (B): a consumed arm that moved an owning payload out of the subject leaves the
        // subject holding a defused ({0}) payload. The post-switch subject drop (a whole-value dtor) would
        // re-drop that zero — a no-op for pointer-shaped payloads but UB for a raw-handle resource (e.g.
        // close(0)). Point the subject tag one past the last variant so the dtor's `switch(tag)` hits
        // `default: break` and drops nothing. Only on consumed arms; borrowing-match subjects are untouched.
        if (defusedSubject) {
            std::string tagTy = ci.tagCType.empty() ? (subjCls + "_Tag") : ci.tagCType;
            indent(depth + 2);
            *_out << sp << "->tag = (" << tagTy << ")" << ci.variants.size() << ";\n";
        }

        // Arm body: a single expression, OR a block. Hoist temps INSIDE the arm braces.
        if (a->block) {
            // block arm — emit its statements in the arm scope. For a value-producing match the
            // block's LAST statement must yield the value (an expression-statement); earlier statements
            // (locals, side effects) run normally, RAII-dropped by the arm's scope cleanup.
            SharedStatementList stmts = a->block->statements;
            size_t nstmt = stmts ? stmts->size() : 0;
            // An EMPTY block arm reaches NEITHER check below, because both live inside the loop — so
            // `int64 x = match (e) { case A(v: v): v; case B: { } };` left the result temp unassigned and
            // emitted C that reads it. The only thing that ever noticed was clang's
            // -Wsometimes-uninitialized, i.e. the diagnostic came from the C compiler, not from kama.
            // A statement-position arm (`resultTemp == nullptr`) yields nothing, so an empty block is
            // legal there and stays legal.
            if (resultTemp && nstmt == 0)
                unsupported("a value-producing `match` arm block must end in `:= <expr>;` or diverge "
                            "(return/break/continue)", a->line);
            for (size_t i = 0; i < nstmt; ++i) {
                SharedStatement st = (*stmts)[i];
                auto armv = std::dynamic_pointer_cast<ArmValueNode>(st);   // `:= expr;` — the arm's value
                if (armv && i + 1 != nstmt) {
                    unsupported("`:=` must be the final statement of a match arm", armv->line);
                    continue;
                }
                if (resultTemp && i + 1 == nstmt) {
                    // A value-producing arm's block states its value with `:= expr;` as the final statement.
                    // The value may be an owned hand-off (`:= give x`) or a bare generic ctor (`:= List()`).
                    // A DIVERGING arm (`return`/`break`/`continue`) yields nothing — it's allowed (the value
                    // comes from the other arms); e.g. `T v = match (r) { case Ok(x): := give x; case Err(e): return … }`.
                    if (armv) emitOwnedValueInto(*resultTemp, _matchTargetCType, armv->value, armv->line, depth + 2, "a `match` arm");
                    else if (stmtIsJump(st)) emitStatement(st, depth + 2);
                    else unsupported("a value-producing `match` arm block must end in `:= <expr>;` or diverge (return/break/continue)", a->line);
                } else {
                    // A NON-FINAL statement of an arm runs in its own typed context, not the match's.
                    // Leaving the target set here let a nested value-producing `match` inside the arm
                    // adopt the OUTER match's result type: an assignment `t = <ternary of matches>` inside
                    // an arm of `int64 x = match …` typed those inner matches `int64` and blitted them into
                    // an `int8` local. At top level the same assignment is REJECTED — the target is "" there,
                    // so "must appear in a typed position" fires — so it is the inherited value alone that
                    // turned the guard into a false pass. Every position that legitimately threads a
                    // destination sets its own, so clearing costs nothing.
                    std::string pmt = _matchTargetCType, pvt = _variantTargetType;
                    _matchTargetCType.clear(); _variantTargetType.clear();
                    emitStatement(st, depth + 2);
                    _matchTargetCType = pmt; _variantTargetType = pvt;
                }
            }
            emitScopeCleanup(_scopes.back(), depth + 2);
        } else if (resultTemp) {
            emitOwnedValueInto(*resultTemp, _matchTargetCType, a->body, a->line, depth + 2, "a `match` arm");   // `case X: give x;`
            emitScopeCleanup(_scopes.back(), depth + 2);   // drop owned sub-expr temps (e.g. concat intermediates)
        } else {
            bool ph = _hoistOK; _hoistOK = true;
            std::string av = emitExpression(a->body);
            _hoistOK = ph;
            flushHoisted(depth + 2);
            indent(depth + 2); *_out << av << ";\n";
            emitScopeCleanup(_scopes.back(), depth + 2);   // drop owned sub-expr temps of a statement-position arm
        }
        indent(depth + 2); *_out << "break;\n";

        for (auto& bn : borrowedHere) _borrowedMatchBindings.erase(bn);
        popScope();   // retires the payload bindings — the state of anything they shadowed comes back with them
        // Captured AFTER the pop, on purpose. A payload binding may shadow an enclosing move-tracked local
        // of the same name; captured before the pop, the merge read the BINDING's state under the outer
        // name and the pop then erased the outer local's state outright. The merge reads only the names
        // live before the match and falls back to their before-state for a key that is missing, so the
        // post-pop map — arm locals gone, shadowed names restored, moves of enclosing locals kept — is exact.
        armEnds.push_back(_moveState);
        armDivs.push_back(a->block ? bodyDiverges(std::static_pointer_cast<StatementNode>(a->block)) : false);
        indent(depth + 1); *_out << "}\n";
    }
    mergeMatchMoveStates(beforeMove, armEnds, armDivs);
    emitMatchDefaultArm(hasWildcard, _classes.count(subjCls) && !_classes[subjCls].tagCType.empty(),
                        subjCls, depth);
    indent(depth); *_out << "}\n";
    // A materialized owning subject (a call/construction result) is dropped once after the switch —
    // bindings only borrowed it, so this releases its owned resource (no leak, no double-free).
    //
    // ⚠️ Through the SCOPE, not as a bare `T__dtor(&temp);` line, and that is the whole fix: an arm that
    // `return`s jumps over anything written after the switch. `match (makeList()) { case Ok(value: l):
    // { return copy l[0]; } … }` therefore leaked the list on every call — measured, 16 bytes per call
    // under LeakSanitizer — while the identical match whose arms fall through was clean. Registering the
    // temp makes `emitUnwindAll` (return) and `emitUnwindToLoop` (break/continue) find it like any other
    // owning local, and `dropCondTemps` performs the fall-through drop and unregisters it so scope exit
    // does not drop it twice. It is the condition-temp pattern, which exists for exactly this reason.
    if (!subjOwner.empty()) dropCondTemps(subjLocMark, depth);
}

// The `default:` arm that closes an exhaustive match's switch, keeping the C switch total.
//
// `break` is right almost everywhere, and wrong in exactly one shape: a match whose tag is a PINNED
// INTEGER (`type enum Color : uint8`). ISO C cannot set an enum's underlying type, so that
// form lowers to `typedef uint8_t Color;` plus an anonymous constant enum (see emitEnum) — and clang
// then sees a switch over 256 possible values with three cases, takes the default in its CFG, and reports
// the result temp as used-uninitialized. `-Werror=uninitialized` (kama.driver.cpp) makes that FATAL, so
// `int32 n = match (c) { … };` over a width-pinned enum simply did not compile.
//
// kama has already PROVEN the match exhaustive (the callers reject a missing variant), so nothing is
// wrong with the program — the C compiler just cannot be told what kama knows. The fix is for the arm to
// DIVERGE, which is what lets clang drop that CFG edge. Zero-initializing the temp instead was rejected:
// it costs every match in every program to serve this one shape.
//
// `kama_panic` rather than `__builtin_unreachable()`, deliberately. Safe kama can no longer mint a tag
// that names no variant (`cast<Color>(n)` is refused; `try cast` is the checked door; `bitcast` was
// always refused), so on a pure-safe path this arm is dead and -O2 folds it away. But an `extern fn` and
// a deserializer both hand back a raw integer that no static rule inspects, and there `unreachable` is UB
// while a panic is a diagnosed abort. It is a cold, noreturn call either way.
//
// The arm is the same in BOTH forms. This used to panic only in the value-producing form, on the claim
// that a statement-form match "has no value to produce, so falling through is correct" — true until every
// arm diverges: `fn int32 pick(Tri t) { match (t) { case A: return 1; … } }` is proven exhaustive by
// kama's own return-path walk (alwaysExits), and the same dead `default: break;` edge is then a
// `-Werror=return-type` error from clang instead of `-Werror=uninitialized`. Same CFG edge, same
// argument, one arm. The first consumer hit exactly this (their KB-12) and rewrote every such function
// to assign in the arms.
//
// A real C enum tag keeps `default: break;` BYTE-FOR-BYTE: clang already treats a switch that names
// every enumerator as total.
void CEmitter::emitMatchDefaultArm(bool hasWildcard, bool pinnedTag, const std::string& what, int depth)
{
    if (hasWildcard) return;
    indent(depth + 1);
    if (!pinnedTag) { *_out << "default: break;\n"; return; }
    // The message a USER reads at runtime, so it goes through the same demangler every diagnostic does —
    // `_Fvm__Color` is an emitter-internal spelling nobody wrote.
    const std::string msg = "match on '" + demangleForDisplay(what) + "': value names no variant";
    *_out << "default: kama_panic(kama_string_lit(\"" << msg << "\", " << msg.size() << "));\n";
}

// a value-producing `match` in expression position. Lifts to a result temp + a switch, hoisted
// before the enclosing statement — strict ISO C11, no GNU statement-expression.
std::string CEmitter::emitMatch(MatchNode* m)
{
    if (!_hoistOK) {
        unsupported("a value-producing `match` here needs a statement slot — bind it to a local first", m->line);
        return "0";
    }
    if (_matchTargetCType.empty()) {
        unsupported("a value-producing `match` must appear in a typed position "
                    "(a local-variable initializer or a `return`)", m->line);
        return "0";
    }
    std::string t  = "__match" + std::to_string(_tempCounter++);
    std::string rt = _matchTargetCType;
    // Build the lowering into a buffer so it can be hoisted as one block; the arms flush their own
    // temps inside their braces (so nested lifting can't escape the arm).
    std::ostringstream buf;
    std::ostream* savedOut = _out; _out = &buf;
    std::vector<std::string> savedHoist; savedHoist.swap(_hoisted);
    *_out << rt << " " << t << ";\n";
    emitMatchSwitch(m, &t, 0);
    savedHoist.swap(_hoisted);
    _out = savedOut;
    _hoisted.push_back(buf.str());
    return t;
}

void CEmitter::emitMatchStatement(MatchNode* m, int depth)
{
    line(m->line);
    emitMatchSwitch(m, nullptr, depth);
}

void CEmitter::mergeMatchMoveStates(const std::map<std::string, MoveState>& before,
                                    const std::vector<std::map<std::string, MoveState>>& armEnds,
                                    const std::vector<bool>& armDivs)
{
    _moveState = before;
    for (auto& kv : before) {
        bool any = false, allMoved = true, allNot = true;
        for (size_t i = 0; i < armEnds.size(); ++i) {
            if (armDivs[i]) continue;                        // a diverging arm never reaches the join
            any = true;
            MoveState s = armEnds[i].count(kv.first) ? armEnds[i].at(kv.first) : kv.second;
            if (s != MoveState::Moved)    allMoved = false;
            if (s != MoveState::NotMoved) allNot   = false;
        }
        if (!any) { _moveState[kv.first] = kv.second; continue; }   // every arm diverges -> join unreachable
        _moveState[kv.first] = allMoved ? MoveState::Moved
                             : (allNot  ? MoveState::NotMoved : MoveState::MaybeMoved);
    }
}

// Resolve the plain (payload-less) enum type of a `match` subject; "" if it is not a plain enum.
// A tagged union resolves through exprClass instead — this only sees bare-integer enums.
std::string CEmitter::exprEnumType(SharedExpression e)
{
    if (!e) return "";
    auto asEnum = [&](const std::string& ty) -> std::string {
        return (!ty.empty() && _enums.count(ty)) ? ty : std::string();
    };
    if (dynamic_cast<ThisAccessNode*>(e.get())) return asEnum(_thisType);   // inside the enum's own method
    if (auto* id = dynamic_cast<IdentifierNode*>(e.get())) {
        if (!id->value) return "";
        // A qualified member of a plain enum, written inline (`match (Level::High)`). The qualifier names
        // the enum, so the subject's type is known without a binding — previously only a local/param/field
        // resolved here, which made a payload-less enum unusable as an inline subject.
        if (id->qualifier && !id->qualifier->empty()) {
            auto tq = std::make_shared<StringList>();
            for (size_t i = 0; i + 1 < id->qualifier->size(); ++i) tq->push_back((*id->qualifier)[i]);
            std::string r = asEnum(resolveUserName(*id->qualifier->back(), tq));
            if (!r.empty()) return r;
        }
        auto it = _localCTypes.find(*id->value);              // a local / param of enum type
        if (it != _localCTypes.end()) { std::string r = asEnum(it->second); if (!r.empty()) return r; }
        if (_currentClass) {                                  // a bare field reference inside a method
            ClassInfo* owner = findFieldOwner(_currentClass, *id->value);
            if (owner)
                for (auto& f : owner->fields)
                    // resolved in the OWNER INSTANCE, like every other field resolution — a `T`-typed
                    // field whose instance binds `T` to a plain enum is a legal `match` subject.
                    if (f.name == *id->value && f.type) { std::string r = asEnum(fieldCType(_currentClass->name, f)); if (!r.empty()) return r; }
        }
        return "";
    }
    if (auto* ma = dynamic_cast<MemberAccessNode*>(e.get())) {   // `obj.field` of enum type
        // A method CALL is an InvocationNode wrapping this MemberAccess, so it is handled below — this
        // arm is a bare field read.
        std::string recv = exprClass(ma->expression);
        if (!recv.empty() && ma->identifier && ma->identifier->value && _classes.count(recv)) {
            ClassInfo* owner = findFieldOwner(&_classes[recv], *ma->identifier->value);
            if (owner)
                for (auto& f : owner->fields)
                    if (f.name == *ma->identifier->value && f.type) { std::string r = asEnum(fieldCType(recv, f)); if (!r.empty()) return r; }
        }
        return "";
    }
    // A CALL returning a plain enum — `match (classify(x: 1))`. The resolution was always there (it is
    // the same one exprClass runs for all five call shapes); it was just filtered through `isClass`,
    // which only knows `_classes`, so a payload-less enum fell out and the subject was rejected with
    // "`match` requires an enum subject" about an expression that plainly was one.
    if (auto* inv = dynamic_cast<InvocationNode*>(e.get()))
        return asEnum(callReturnTypeRaw(inv));
    return "";
}

// Lower a `match` over a plain enum to a C `switch` on the integer value. Same compile-time
// exhaustiveness + `_` wildcard as the tagged-union path, but no payload binding.
void CEmitter::emitMatchPlainEnum(MatchNode* m, const std::string& enumTy, const std::string* resultTemp, int depth)
{
    EnumInfo& ei = _enums[enumTy];

    bool hasWildcard = false;
    std::set<std::string> covered;
    for (auto& a : *m->arms) {
        if (a->isWildcard()) { hasWildcard = true; continue; }
        std::string vn = a->variantName ? *a->variantName : "";
        bool found = false;
        for (auto& mem : ei.members) if (mem.name == vn) { found = true; break; }
        // LSP index: a `case Ok:` arm IS a use of the enum member — without this, renaming a member
        // would rewrite every `Enum::Member` and leave the arms behind, i.e. produce code that no
        // longer compiles. `variantId` is the same name as a node with a span (see MatchArmNode).
        if (found) recordRef(enumMemberKey(enumTy, vn), a->variantId.get());
        if (!found)            unsupported(("`match` arm names unknown case '" + vn + "' of enum '" + enumTy + "'").c_str(), a->line);
        if (a->bindings && !a->bindings->empty())
                               unsupported(("enum case '" + vn + "' carries no payload to bind").c_str(), a->line);
        if (covered.count(vn)) unsupported(("duplicate `match` arm for case '" + vn + "'").c_str(), a->line);
        covered.insert(vn);
    }
    if (!hasWildcard)
        for (auto& mem : ei.members)
            if (!covered.count(mem.name))
                unsupported(("`match` on '" + enumTy + "' is not exhaustive: case '" + mem.name
                             + "' is unhandled — add `case " + mem.name + ":` or `case _:`").c_str(), m->line);

    // Build the subject FIRST: a call subject can hoist (a string argument temp), and those declarations
    // have to land before the `switch` line rather than inside it. Evaluated exactly once either way, so
    // the tagged path's owning `__msubj` temp is not needed here.
    std::string subjExpr = emitExpression(m->subject);
    flushHoisted(depth);
    indent(depth); *_out << "switch (" << subjExpr << ") {\n";
    auto beforeMove = _moveState;
    std::vector<std::map<std::string, MoveState>> armEnds;
    std::vector<bool> armDivs;
    for (auto& a : *m->arms) {
        _moveState = beforeMove;
        indent(depth + 1);
        if (a->isWildcard()) *_out << "default: {\n";
        else                 *_out << "case " << enumTy << "_" << *a->variantName << ": {\n";
        // Each arm carries its OWN kama line. Without this the whole switch is attributed to the
        // `match` keyword's line and clang counts forward from there, so an error the C compiler finds in
        // arm 3 is reported several lines below the arm — measured past the end of a short file. An arm is
        // where the user wrote the expression, so it is where a `#line` belongs. It goes AFTER
        // the `case …: {` line, which would otherwise consume the stamp and push the body one line down —
        // naming the NEXT arm, the most misleading answer available.
        line(a->line);

        Scope sc; _scopes.push_back(sc);
        if (a->block) {
            SharedStatementList stmts = a->block->statements;
            size_t nstmt = stmts ? stmts->size() : 0;
            if (resultTemp && nstmt == 0)   // the same empty-block hole as the tagged-union path above
                unsupported("a value-producing `match` arm block must end in `:= <expr>;` or diverge "
                            "(return/break/continue)", a->line);
            for (size_t i = 0; i < nstmt; ++i) {
                SharedStatement st = (*stmts)[i];
                auto armv = std::dynamic_pointer_cast<ArmValueNode>(st);   // `:= expr;` — the arm's value
                if (armv && i + 1 != nstmt) {
                    unsupported("`:=` must be the final statement of a match arm", armv->line);
                    continue;
                }
                if (resultTemp && i + 1 == nstmt) {
                    // A value-producing arm's block states its value with `:= expr;` as the final statement.
                    // The value may be an owned hand-off (`:= give x`) or a bare generic ctor (`:= List()`).
                    // A DIVERGING arm (`return`/`break`/`continue`) yields nothing — it's allowed (the value
                    // comes from the other arms); e.g. `T v = match (r) { case Ok(x): := give x; case Err(e): return … }`.
                    if (armv) emitOwnedValueInto(*resultTemp, _matchTargetCType, armv->value, armv->line, depth + 2, "a `match` arm");
                    else if (stmtIsJump(st)) emitStatement(st, depth + 2);
                    else unsupported("a value-producing `match` arm block must end in `:= <expr>;` or diverge (return/break/continue)", a->line);
                } else {
                    // A NON-FINAL statement of an arm runs in its own typed context, not the match's.
                    // Leaving the target set here let a nested value-producing `match` inside the arm
                    // adopt the OUTER match's result type: an assignment `t = <ternary of matches>` inside
                    // an arm of `int64 x = match …` typed those inner matches `int64` and blitted them into
                    // an `int8` local. At top level the same assignment is REJECTED — the target is "" there,
                    // so "must appear in a typed position" fires — so it is the inherited value alone that
                    // turned the guard into a false pass. Every position that legitimately threads a
                    // destination sets its own, so clearing costs nothing.
                    std::string pmt = _matchTargetCType, pvt = _variantTargetType;
                    _matchTargetCType.clear(); _variantTargetType.clear();
                    emitStatement(st, depth + 2);
                    _matchTargetCType = pmt; _variantTargetType = pvt;
                }
            }
            emitScopeCleanup(_scopes.back(), depth + 2);
        } else if (resultTemp) {
            emitOwnedValueInto(*resultTemp, _matchTargetCType, a->body, a->line, depth + 2, "a `match` arm");   // `case X: give x;`
            emitScopeCleanup(_scopes.back(), depth + 2);   // drop owned sub-expr temps (e.g. concat intermediates)
        } else {
            bool ph = _hoistOK; _hoistOK = true;
            std::string av = emitExpression(a->body);
            _hoistOK = ph;
            flushHoisted(depth + 2);
            indent(depth + 2); *_out << av << ";\n";
            emitScopeCleanup(_scopes.back(), depth + 2);   // drop owned sub-expr temps of a statement-position arm
        }
        indent(depth + 2); *_out << "break;\n";
        armEnds.push_back(_moveState);
        armDivs.push_back(a->block ? bodyDiverges(std::static_pointer_cast<StatementNode>(a->block)) : false);
        popScope();
        indent(depth + 1); *_out << "}\n";
    }
    mergeMatchMoveStates(beforeMove, armEnds, armDivs);
    emitMatchDefaultArm(hasWildcard, _enums.count(enumTy) && !_enums[enumTy].underlyingCType.empty(),
                        enumTy, depth);
    indent(depth); *_out << "}\n";
}

// an inline constructor `Cls(args)` as a general rvalue (return / variant payload). A ctor
// lowers to `Cls__ctor(&dest, …)` which needs an lvalue destination, so materialize a HOISTED temp
// (declared before the leaf statement — pure ISO C, no `({…})`) and return its name. "" if `e` is not
// an inline ctor for exactly `targetCType`, or no hoist slot. Mirrors the arg-position recognizer.
std::string CEmitter::tryHoistInlineCtor(SharedExpression e, const std::string& targetCType, int srcLine)
{
    if (!_hoistOK || targetCType.empty()) return "";
    auto* iv = dynamic_cast<InvocationNode*>(e.get());
    if (!iv || !iv->identifier || !iv->identifier->value) return "";
    std::string rn = resolveUserName(*iv->identifier->value, iv->identifier->qualifier);
    std::string ctorCls;
    if (isClass(rn) && _classes.count(rn)) ctorCls = rn;
    else { auto g = _genericTypeInstOf.find(targetCType);   // ctor names template `Box`; target is `Box_int32`
           if (g != _genericTypeInstOf.end() && g->second == rn) ctorCls = targetCType; }
    // An extern (C-POD) struct has no ctor to call — `return div_t(quot: 1);` would emit an undefined
    // `div_t__ctor`. Hand it back to the caller to diagnose rather than fabricating a call (the arg-position
    // recognizer aggregate-inits it instead; a value-position extern ctor has no user today).
    if (ctorCls.empty() || ctorCls != targetCType
        || _classes[ctorCls].isIntrinsicColl || _classes[ctorCls].isExternStruct) return "";
    // Nameless — no ctor to bind. Reject with the context-aware advice and hand back a degenerate temp,
    // which suppresses the caller's generic "call to unknown function" follow-on.
    rejectNamelessConstruction(_classes[ctorCls], *iv->identifier->value, /*viaNew=*/false, srcLine);
    std::string t = "__ctorarg" + std::to_string(_tempCounter++);
    _hoisted.push_back(ctorCls + " " + t + " = {0};");
    return t;
}

// an inline `new T(...)` / `try new T(...)` / `try cast<T>(x)` as a general rvalue whose target type the
// CALLER knows — materialize it into a HOISTED temp (declared before the leaf statement, pure ISO C, no
// `({…})`) and return its name. Ownership transfers to the CONSUMER (a callee param, or a return `__ret`
// temp), which is the sole party registered to drop it — the box is NOT recordDestructibleLocal'd here.
// The emitted C mirrors the (ASan-clean) local-init boxing at emitLocalVariableDeclaration; keep in sync.
//   returns "" when not applicable (not one of those forms, or the target isn't an owning pointer / the
//   element plainly mismatches) so the CALLER diagnoses; on a specific semantic error (Weak/abstract/
//   non-impl/no `adopt`) it emits ONE precise diagnostic and returns a declared degenerate temp
//   (compilation already failed, so the throwaway C is never built) — suppressing the caller's gate.
//
// The two `try` verbs are here for the same reason the fallible `new` is: they are STATEMENT forms whose
// result type is read off the DESTINATION, and a value position supplies both — the destination is the
// param/return/payload type instead of a declared local, and the hoist IS the statement slot. Without
// this, `return try new T.make(…)` reported "`new` outside a local-variable initializer", which named
// neither the verb the user wrote nor anything they could act on.
std::string CEmitter::tryHoistInlineValue(SharedExpression e, const std::string& targetCType, int srcLine)
{
    if (!_hoistOK || targetCType.empty()) return "";
    // `try cast<T>(x)` — BEFORE the no-heap gate below, because a conversion allocates nothing: routing it
    // through that gate would make `@noheap` reject the one verb in the language that cannot allocate.
    if (auto* cst = dynamic_cast<CastNode*>(e.get())) {
        if (!cst->isTry || !_classes.count(targetCType)) return "";   // plain cast / no Optional destination
        std::string t = "__trycastv" + std::to_string(_tempCounter++);
        std::string s = emitTryCast(targetCType, t, cst, srcLine);
        _hoisted.push_back(targetCType + " " + t + " = {0};" + (s.empty() ? "" : " " + s));
        return t;
    }
    auto* oc = dynamic_cast<ObjectCreationNode*>(e.get());
    if (!oc) return "";
    checkNamelessNewBanned(oc, srcLine);   // M8 Phase E: no nameless `new Type(...)`
    auto cit = _classes.find(targetCType);
    if (cit == _classes.end()) return "";
    // no-heap gate — value-position `new` (return/arg/payload). `try new` still ALLOCATES (it reports OOM
    // as `None` rather than trapping), so it is gated too — under the name the user wrote.
    if (newDrawsFromHeap(oc)) rejectIfNoHeap(oc->isTry ? "try new" : "new", srcLine);   // see the statement arm
    std::string octy = cType(oc->type);
    { std::string ve = newVariantEnum(oc, heapOwnerTarget(targetCType)); if (!ve.empty()) octy = ve; }
    // one precise diagnostic + a declared degenerate temp (see header) — suppresses the caller's gate.
    auto reject = [&](const std::string& msg) -> std::string {
        unsupported(msg.c_str(), srcLine);
        std::string t = "__newarg" + std::to_string(_tempCounter++);
        _hoisted.push_back(targetCType + " " + t + " = {0};");
        return t;
    };
    // `try new T(...)` in a value position — `targetCType` is the `Optional<Owned<T>>`. Same shape as the
    // fallible box just below (wrap-a-box-in-a-sum-type); `emitTryNewBox` assigns the temp on both branches.
    if (oc->isTry) {
        std::string t = "__newarg" + std::to_string(_tempCounter++);
        std::string s = emitTryNewBox(targetCType, t, oc, srcLine);
        _hoisted.push_back(targetCType + " " + t + " = {0};" + (s.empty() ? "" : " " + s));
        return t;
    }
    // M4b: a fallible `new Type.name(...)` in a value position (return/arg/payload) — `targetCType` is the
    // `Result<Owned<T>,E>`. Hoist the box (factory into a temp, propagate `Err`, box `Ok`) into a fresh temp
    // and hand it back as the value. `emitFallibleNewBox` pushes its arg hand-offs first (ordering preserved).
    if (ctorIsFallible(oc)) {
        std::string t = "__newarg" + std::to_string(_tempCounter++);
        std::string s = emitFallibleNewBox(targetCType, t, oc, srcLine);
        _hoisted.push_back(targetCType + " " + t + " = {0};" + (s.empty() ? "" : " " + s));
        return t;
    }
    // Allocator-aware placement threads a stateful allocator through the concrete-element library boxes
    // (`Owned<T, A>` via `adoptIn` below) AND the type-erased INTERFACE-element intrinsic path (M11d, in the
    // `isInterface(T)` block below — each fat handle carries its own `A alloc` value + `objsize`).

    // ---- LIBRARY HeapOwner, concrete element: `T* hp = malloc; C__ctor(hp,…); box = Owner__adopt(hp)` ----
    // (mirror emitLocalVariableDeclaration ~1265-1300, incl. the derived→base upcast; `adopt` itself
    // allocates the Shared ctrl, so — unlike the intrinsic paths below — we do NOT emit kama_ctrl_new().)
    if (!isSmartPtrClass(targetCType)) {
        std::string T = heapOwnerTarget(targetCType);
        if (T.empty()) return "";                              // not an owning pointer — caller diagnoses
        bool upcastNew = (octy != T) && isClass(octy) && isBaseOf(T, octy);
        std::string C = upcastNew ? octy : T;                  // the concrete actually built
        if (octy != T && !upcastNew)
            return reject("`" + targetCType + "` owns `" + T + "`, but got `new " + octy
                          + "(...)` — name the element type or a derived of it, not the owner");
        if (isClass(C) && _classes[C].isAbstractClass)
            return reject("cannot instantiate abstract class '" + C + "'");
        // Placement `new(allocator: a)` in arg/return/payload position — thread the allocator identically to
        // the local-decl path (draw the block from `a`, adopt through `adoptIn`), else the allocator would be
        // silently dropped and the block leaked. A bare `new` keeps the libc malloc + `adopt` form.
        auto pa = placementAllocator(oc, srcLine, /*emit=*/true);
        bool placed = !pa.second.empty();
        if (!placed) {   // bare `new` into a stateful-allocator box leaks — require the placement form
            const std::string why = bareNewRefusal(boxAllocatorArg(targetCType), "new", "T");
            if (!why.empty()) return reject(why);
        } else {
            std::string boxA = boxAllocatorArg(targetCType);   // declared box allocator must match the handle
            if (!boxA.empty() && boxA != pa.second)
                return reject("the box's allocator type `" + boxA + "` does not match the `new(allocator: …)` "
                              "handle `" + pa.second + "` — spell the box's allocator explicitly");
        }
        const char* adoptName = placed ? "adoptIn" : "adopt";
        ClassInfo* ao = nullptr;
        MethodInfo* adoptM = findMethod(&_classes[targetCType], adoptName, &ao);
        if (placed && !adoptM)
            return reject("allocator-aware `new(allocator: …)` needs an `adoptIn(raw, allocator)` on `" + targetCType + "`");
        if (!adoptM) return reject("`" + targetCType + "` implements HeapOwner but has no `adopt` method");
        std::string hp = "__heap"   + std::to_string(_tempCounter++);
        std::string t  = "__newarg" + std::to_string(_tempCounter++);
        std::string ap = placed ? "__alloc" + std::to_string(_tempCounter++) : "";
        std::string box;
        if (placed) box  = pa.second + " " + ap + " = " + pa.first + "; "
                         + C + "* " + hp + " = (" + C + "*)unwrapPtr(" + pa.second + "__allocate(&" + ap + ", " + layoutOf(C) + "));";
        else        box  = C + "* " + hp + " = (" + C + "*)kama_alloc(" + layoutOf(C) + ");";
        if (newBuildsValue(C, oc)) {
            std::string cc = newFactoryCall(C, oc, srcLine);   // move the factory result into the heap slot
            if (!cc.empty()) box += " *(" + hp + ") = " + cc + ";";
        }
        std::string adoptArg = hp;                             // adopt the base subobject when widening (offset-0)
        if (upcastNew) {
            std::string bp = basePathTo(&_classes[C], &_classes[T]);
            if (!bp.empty()) bp.pop_back();
            adoptArg = "(" + T + "*)&(" + hp + "->" + bp + ")";
        }
        box += " " + targetCType + " " + t + " = " + adoptM->cName + "(" + adoptArg + (placed ? ", " + ap : "") + ");";
        _hoisted.push_back(box);
        return t;
    }

    // ---- INTRINSIC owning pointer (registered fat/thin box) ----
    std::string T = cit->second.collElemClass;
    if (smartKind(targetCType) == CollKind::Weak)              // a Weak is non-owning — it can't own a `new`
        return reject("`new` allocates on the heap — a `Weak` can't own it; wrap it in an `Owned<" + T
                      + ">`/`Shared<" + T + ">` (a `Weak` is a non-owning observer)");

    if (isInterface(T)) {   // `new Concrete` into a Shared/Owned<Interface> — fat box {obj, vtbl[, ctrl]}
        auto oit = _classes.find(octy);                       // (mirror emitLocalVariableDeclaration ~1213-1237)
        bool implementsT = false;
        if (oit != _classes.end())
            for (auto& i : oit->second.interfaces) if (i == T) { implementsT = true; break; }
        if (!implementsT)
            return reject("`new " + octy + "` does not implement `" + T + "` — `" + targetCType
                          + "` owns a class that satisfies the contract");
        if (_classes[octy].isAbstractClass)
            return reject("cannot instantiate abstract class '" + octy + "'");
        // Placement `new(allocator: a)` in arg/return/payload position — thread the allocator identically to
        // the local-decl path (draw the pointee/ctrl from `a`, store `a`+objsize in the fat handle). M11d.
        bool useAlloc = ifaceNewAllocator(targetCType, oc, srcLine);
        std::string aTy = _collections.count(targetCType) ? _collections[targetCType].allocType : "";
        std::string t  = "__newarg" + std::to_string(_tempCounter++);
        std::string ap = useAlloc ? "__alloc" + std::to_string(_tempCounter++) : "";
        std::string box = targetCType + " " + t + " = {0};";
        if (useAlloc) {
            auto pa = placementAllocator(oc, srcLine, /*emit=*/true);
            box += " " + pa.second + " " + ap + " = " + pa.first + "; "
                 + t + ".obj = (void*)unwrapPtr(" + pa.second + "__allocate(&" + ap + ", " + layoutOf(octy) + "));";
        } else {
            box += " " + t + ".obj = kama_alloc(" + layoutOf(octy) + ");";
        }
        if (newBuildsValue(octy, oc)) {
            std::string cc = newFactoryCall(octy, oc, srcLine);
            if (!cc.empty()) box += " *((" + octy + "*)" + t + ".obj) = " + cc + ";";
        }
        box += " " + t + ".vtbl = &" + octy + "__as_" + T + ";";
        if (useAlloc)
            box += " " + t + ".alloc = " + ap + ";";
        if (smartKind(targetCType) == CollKind::Shared)
            box += useAlloc
                 ? " " + t + ".ctrl = (kama_ctrl*)unwrapPtr(" + aTy + "__allocate(&" + ap + ", " + layoutOf("kama_ctrl") + ")); "
                   + t + ".ctrl->strong = 1; " + t + ".ctrl->weak = 0;"
                 : " " + t + ".ctrl = kama_ctrl_new();";
        _hoisted.push_back(box);
        return t;
    }

    return "";   // a smart-pointer class is only ever over a CONTRACT element (registerGenericTypeInst)
}

// resolve the variant type a `::` qualifier names. A non-generic union is in _classes
// directly; a generic union names its bare template (`Optional`, in _genericTypes) — resolve it to
// the target instance set by the enclosing typed position (`_variantTargetType`, e.g. Optional_int32).
// The integer enum a qualifier names: itself, or — for a generic payload-less template (`Side::R`) — the
// instance the target type pins (`Side<bool>`), exactly as resolveVariantType pins a tagged one.
std::string CEmitter::scalarEnumInstanceOf(const std::string& qualResolved)
{
    if (_enums.count(qualResolved) || !_genericTypeParams.count(qualResolved) || _variantTargetType.empty())
        return qualResolved;
    auto of = _genericTypeInstOf.find(_variantTargetType);
    return (of != _genericTypeInstOf.end() && of->second == qualResolved && _enums.count(_variantTargetType))
               ? _variantTargetType : qualResolved;
}

ClassInfo* CEmitter::resolveVariantType(const std::string& qualResolved)
{
    auto direct = _classes.find(qualResolved);
    if (direct != _classes.end() && direct->second.isVariant) return &direct->second;
    if (_genericTypeParams.count(qualResolved) && !_variantTargetType.empty()) {
        auto of = _genericTypeInstOf.find(_variantTargetType);
        if (of != _genericTypeInstOf.end() && of->second == qualResolved) {
            auto inst = _classes.find(_variantTargetType);
            if (inst != _classes.end() && inst->second.isVariant) return &inst->second;
        }
    }
    return nullptr;
}

// `Union::Variant(field: value, …)` -> a C99 compound literal
//   (Shape){ .tag = Shape_Circle, .u.Circle = { .radius = 2.0 } }
// A no-payload variant omits the union member. The compound literal is an rvalue; stored in a local
// it is recorded destructible (if the union owns a resource) and drops via the switch-on-tag dtor.
std::string CEmitter::emitVariantConstruction(ClassInfo& ci, const std::string& variant,
                                              SharedArgumentList args, int srcLine)
{
    const VariantCase* vc = nullptr;
    for (auto& v : ci.variants) if (v.name == variant) { vc = &v; break; }
    if (!vc) { unsupported(("'" + ci.name + "' has no variant '" + variant + "'").c_str(), srcLine); return "0"; }

    // ⚠️ NO ambient type-substitution here. This used to install the enum instance's args
    // (`Optional_int32` -> `{T: int32}`) across the whole payload emission, so that the payload FIELD's C
    // type resolved concretely. That one consumer is gone: the field type is read with
    // `fieldCType(ci.name, f)` below, which takes the baked type or `cTypeInInstance` — both scoped to the
    // owner, neither reading ambient state. What the binding still did was CORRUPT the other four
    // resolutions in this loop, every one of which is about the ARGUMENT and belongs to the CALLER's scope:
    // `rejectValueKindMismatch`, `tryHoistInlineValue`'s `cType` for a `new T(…)` payload, `emitExpression`,
    // and `exprClass`. The last of those is how a raw-buffer element's class went missing (`0.9.283`).
    // `emitMatchSwitch` carries the post-mortem for the identical pattern — one binding held open across a
    // whole construct — and the fix there was the same: delete it, and let each resolution that needs the
    // instance ask for it by name.

    std::map<std::string, ArgumentNode*> byName;
    if (args) for (auto& a : *args) if (a->name && a->name->value) byName[*a->name->value] = a.get();
    size_t argc = args ? args->size() : 0;
    if (argc != vc->payload.size())
        unsupported(("variant '" + ci.name + "::" + variant + "' takes " + std::to_string(vc->payload.size())
                     + " payload field(s), got " + std::to_string(argc)).c_str(), srcLine);

    std::string s = "(" + ci.name + "){ .tag = " + ci.name + "_" + variant;
    if (!vc->payload.empty()) {
        s += ", .u." + variant + " = {";
        bool first = true;
        for (auto& f : vc->payload) {
            auto ai = byName.find(f.name);
            if (ai == byName.end()) {
                unsupported(("missing payload field '" + f.name + "' for '" + ci.name + "::" + variant + "'").c_str(), srcLine);
                continue;
            }
            // M6 B3e: the payload LABEL is a reference to the payload field, exactly as an argument label
            // is to a parameter. This construction does its own named-arg matching rather than going
            // through emitReorderedCall, so A2's one line does not cover it. By node, so a generic union's
            // instances collapse onto the template's declaration.
            recordNodeRef(ai->second->name.get(), f.nameId.get());
            std::string fcls = fieldCType(ci.name, f);   // the payload field's C type (Shared_Probe / int32_t / …)
            SharedExpression argExpr = ai->second->expression;
            int handoff = 0;                             // 0 none, 1 give, 2 copy
            if (auto* h = dynamic_cast<HandoffNode*>(argExpr.get())) { handoff = h->isGive ? 1 : 2; argExpr = h->value; }
            // The kind rule for a payload. This construction does its own named-argument matching instead
            // of going through `emitReorderedCall`, so it is the fourth hand-off site and needs its own
            // call — the same reason the payload LABEL needed its own `recordNodeRef` two lines up.
            // (An `Owned<Error>`/`Shared<Error>` field reads as Unknown, so the enum-boxing path below is
            // untouched.)
            rejectValueKindMismatch(fcls, argExpr,
                                    ("payload field `" + f.name + "`").c_str(), srcLine);
            // an inline construction as the payload (inline `new`, an inline generic-instance ctor,
            // or a nested `Some(Some(…))` / value-producing `match`) materializes against the field type;
            // propagate the target so the nested variant/match resolves.
            std::string pmt = _matchTargetCType, pvt = _variantTargetType;
            _matchTargetCType = _variantTargetType = fcls;
            std::string val = tryHoistInlineValue(argExpr, fcls, srcLine);
            if (val.empty()) val = tryHoistInlineCtor(argExpr, fcls, srcLine);
            if (val.empty()) val = emitExpression(argExpr);
            // `return Result::Ok(value: this);` — a fallible ctor handing back the value it built.
            if (ctorThisAsValue(argExpr, fcls)) val = "(*" + val + ")";
            _matchTargetCType = pmt; _variantTargetType = pvt;
            std::string argCls = handoffSourceClass(argExpr, handoff);
            rejectUnresolvedHandoff(argCls, fcls, argExpr, handoff, ("payload field `" + f.name + "`").c_str(), srcLine);
            std::string field;
            // Model C (P2): an enum value into an `Owned<Error>`/`Shared<Error>` variant field (e.g.
            // `Result::Err(error: IoError::NotFound)`) is BOXED + upcast — heap-copy the enum, attach its
            // `<Enum>__as_Error` vtbl. Checked FIRST (before the move-only branches): if the field is a
            // poly-dispatch-contract handle and the arg is an implementing enum, boxing is always right.
            // `exprClass` is "" for a variant literal, so recover the source enum via variantExprEnumCType.
            auto enumClass = [&](const std::string& c) {
                auto it = _classes.find(c);
                return it != _classes.end() && (it->second.isVariant || it->second.isScalarEnum());
            };
            std::string boxEnum = enumClass(argCls) ? argCls : variantExprEnumCType(argExpr);
            if (boxEnum.empty() && enumClass(typeOfExpr(argExpr))) boxEnum = typeOfExpr(argExpr);   // `E::A` of an integer enum
            if (isSmartPtrClass(fcls) && !boxEnum.empty() && enumClass(boxEnum)
                && isPolyDispatchContract(_classes[fcls].collElemClass)
                && implementsContractTemplate(&_classes[boxEnum], _classes[fcls].collElemClass)) {
                if (!_hoistOK)
                    unsupported("boxing an error into a variant here needs a statement slot — bind the "
                                "constructed value to a local first", srcLine);
                if (isNamedValue(argExpr.get()) && _classes[boxEnum].destructible) {
                    if (handoff != 1)
                        unsupported(("moving `" + boxEnum + "` into an error box transfers ownership — say "
                                     "`give`").c_str(), srcLine);
                    std::string mv = moveOnlySource(argExpr, srcLine); if (!mv.empty()) markMoved(mv);
                }
                field = emitEnumBoxIntoContract(fcls, boxEnum, val, srcLine);
            } else if (isSmartPtrClass(argCls) && isNamedValue(argExpr.get())) {
                // A named smart pointer MOVES/RETAINS into the union (which now owns it, dropped by the
                // switch-on-tag dtor). Same hand-off as a by-value call arg, hoisted (ISO C).
                CollKind k = smartKind(argCls);
                bool doGive = (handoff == 1) || (handoff == 0 && k == CollKind::Owned);
                if (handoff == 2 && k == CollKind::Owned)
                    unsupported("an `Owned` is unique — it can't be `copy`'d; use `give` to move it", srcLine);
                // A give here only invalidates the LOCAL copy — a borrowed `match` binding still aliases the
                // subject's box (which the subject drops too) → double free. Reject it (this path bypasses
                // moveOnlySource, so the check must be explicit).
                if (doGive) giveOfBorrowedBinding(argExpr, srcLine);
                if (!_hoistOK)
                    unsupported("moving a smart pointer into a variant here needs a statement slot — bind the "
                                "constructed value to a local first", srcLine);
                std::string t = "__kama_varg" + std::to_string(_tempCounter++);
                std::string side = doGive ? smartPtrInvalidate("(" + val + ")", k, isInterface(_classes[argCls].collElemClass))
                                          : ("(" + val + ").ctrl->" + (k == CollKind::Weak ? "weak" : "strong") + "++;");
                _hoisted.push_back(fcls + " " + t + " = (" + val + "); " + side);
                field = t;
            } else if (isMoveOnlyValue(argCls) && isNamedValue(argExpr.get())) {
                // A named `resource` value handed into a union field. `give` MOVES it (mark the source
                // moved, dtor suppressed); `copy` deep-copies (source survives); a BARE arg follows the
                // type's `bare:` default. A non-Copyable resource → move.
                bool cpy = isCopyable(argCls);
                bool doCopy;
                if (handoff == 2) {
                    if (!cpy) unsupported(("`" + argCls + "` has no `copy` method — use `give` to move it").c_str(), srcLine);
                    doCopy = cpy;
                } else if (handoff == 1) doCopy = false;
                else doCopy = cpy && _classes[argCls].bareDefault == COPY;
                if (doCopy) field = copyCall(argCls, val);
                else { std::string mv = moveOnlySource(argExpr, srcLine); if (!mv.empty()) markMoved(mv); field = val; }
            } else if (!argCls.empty() && _classes.count(argCls) && _classes[argCls].isIntrinsicColl
                       && !isFixedColl(argCls) && handoff) {
                // Hand a heap collection/`string` into the union: `copy` deep-copies (`__copy`; the union owns
                // the clone, the source survives), `give` transfers the struct (buffer) and nulls the
                // source so its scope-drop is a no-op (the union now owns it, dropped by the tag dtor).
                // (`InlineArray` is excluded — it's a value that owns nothing, so it falls to the plain-value
                // branch below; nulling its non-existent `.data`/`.len` would be wrong.)
                // A give nulls only the LOCAL copy — a borrowed `match` binding still aliases the subject's
                // buffer → double free. Reject (this path bypasses moveOnlySource — explicit check).
                if (handoff == 1) giveOfBorrowedBinding(argExpr, srcLine);
                if (handoff == 2) {                                  // copy = deep copy into the payload
                    auto ci = _collections.find(argCls);
                    if (ci != _collections.end() && ci->second.elemDestructible && !ci->second.elemCopyable)
                        unsupported(("`copy` of a `" + argCls + "` needs copyable elements — use `give` to "
                                     "move it").c_str(), srcLine);
                    else field = copyCall(argCls, val);
                }
                else if (!_hoistOK)
                    unsupported("moving a collection into a variant here needs a statement slot — bind the "
                                "constructed value to a local first", srcLine);
                else {
                    std::string t = "__varg" + std::to_string(_tempCounter++);
                    _hoisted.push_back(fcls + " " + t + " = (" + val + "); " + moveNullStmt(fcls, val));
                    field = t;
                }
            } else if (!argCls.empty() && _classes.count(argCls) && _classes[argCls].isIntrinsicColl
                       && !isFixedColl(argCls) && isNamedValue(argExpr.get())) {
                // A bare NAMED heap collection/`string` into a variant would alias (the union owns it AND the
                // source frees it → double-free / dangle). Ownership transfer must be explicit — `give`
                // (move) or `copy` (deep). A fresh rvalue payload (a call result / literal) needs no marker.
                unsupported("a collection/`string` into a variant transfers ownership — say `give` (move) "
                            "or `copy` (deep)", srcLine);
                field = val;
            } else {
                // Primitive / plain value / fresh smart-ptr rvalue (factory result): consumed in place.
                // A `give`/`copy` on a plain value (primitive or `value` struct) is a no-op — a value is
                // always copied — so only a stray marker on a fell-through resource rvalue is an error.
                bool plainValue = argCls.empty() || isFixedColl(argCls)   // InlineArray: a value that owns nothing
                    || (_classes.count(argCls) && _classes[argCls].kind == TypeKind::Value);
                // A tagged-union (enum) value accepts `give` into the outer variant — the tag+payload copies
                // bitwise (a no-op move for a non-owning enum like `Result::Ok(value: give myEnum)` in
                // `decode<T>`). An owning-payload enum move is a deferred follow-up (it would need the source
                // dtor suppressed here). A plain value's `give` is likewise a no-op copy.
                bool variantVal = !argCls.empty() && _classes.count(argCls) && _classes[argCls].isVariant;
                if (handoff && !plainValue && !variantVal && !isSmartPtrClass(argCls))
                    unsupported("`give`/`copy` apply to a named smart pointer / resource value", srcLine);
                field = val;
            }
            s += (first ? " ." : ", .");
            s += f.name + " = " + field;
            first = false;
        }
        s += " }";
    }
    return s + " }";
}

// a place-returning free/static call lowers to `T*`; deref it so the call is an lvalue EVERYWHERE
// (read copies out; `f(…) = x` writes through; `ref f(…)` / `f(…).field` / nesting all compose) —
// the same treatment a place-returning method call gets. `&(*…)` folds, so chains stay clean ISO C.
static inline std::string placeWrap(const std::string& c, bool isPlace)
{
    return isPlace ? ("(*" + c + ")") : c;
}

std::string CEmitter::emitInvocation(InvocationNode* call)
{
    // Containment, on ACQUISITION-BY-CALL. A call that RETURNS a raw pointer hands one to its caller, and
    // that caller may be unmarked: `kfree(p: make())` never binds the value to a local or a field, so the
    // declaration, local and field rules all miss it, and the pointer is used twice with no marker in
    // sight. Calling an `unsafe fn` stays unrestricted — that is the model — but the RESULT still has to
    // land somewhere allowed to hold it.
    //
    // `callReturnTypeRaw` is the same resolver `exprClass` uses, so a method, a free function and a
    // `Type::factory()` all answer here rather than at three separate sites.
    //
    // `addr(of:)` answers a pointer type there too now (callReturnTypeRaw types it, const or not, for the
    // sinks) — and it has its own arm below with its own message, so it is skipped here or one `addr`
    // outside an `unsafe fn` would be reported twice.
    {
        const bool isAddr = call->identifier && call->identifier->value && *call->identifier->value == "addr"
                         && !call->expression;
        std::string rc = isAddr ? std::string() : callReturnTypeRaw(call);
        if (!rc.empty() && rc.size() > 1 && rc.back() == '*' && !isViewCType(rc)
            && !isClass(rc) && !isInterface(rc))
            rejectRawOutsideUnsafe("this call's result", call->line);
    }

    // Calling a method ON a slot fills it (the receiver goes in by pointer and the method builds the
    // value — the stdlib's builder shape, e.g. `slot FixedArray<T,A> r; r.allocBuffer(size: size);`).
    // So the hole becomes a live value here and its destructor comes back. Mirrors the analysis rule in
    // checkDefiniteAssignment, and must run BEFORE the receiver is emitted.
    if (!_slotLocals.empty() && call->expression)
        if (auto* rma = dynamic_cast<MemberAccessNode*>(call->expression.get()))
            if (auto* rid = dynamic_cast<IdentifierNode*>(rma->expression.get()))
                if (rid->value && (!rid->qualifier || rid->qualifier->empty())
                    && _slotLocals.count(*rid->value)) {
                    _slotLocals.erase(*rid->value);
                    _moveState[*rid->value] = MoveState::NotMoved;
                }

    // `f(dst: out x)` fills a slot as well, and this is the fill `slot` exists for. The callee is
    // separately proven to assign the parameter (verifyOutsAssigned), so `x` holds a live value from here
    // on and its destructor comes back. Without this the value the callee built was never dropped: the
    // three sibling rules above cover assignment, a method call and `addr(of:)`, and the `out` path — the
    // one the analysis has always ACCEPTED as a fill — had no emitter half at all. Runs before the
    // arguments are emitted, like the receiver rule above.
    if (!_slotLocals.empty() && call->args)
        for (auto& a : *call->args)
            if (a && a->modifier && a->modifier->value && *a->modifier->value == "out")
                if (auto* aid = dynamic_cast<IdentifierNode*>(a->expression.get()))
                    if (aid->value && (!aid->qualifier || aid->qualifier->empty())
                        && _slotLocals.count(*aid->value)) {
                        _slotLocals.erase(*aid->value);
                        _moveState[*aid->value] = MoveState::NotMoved;
                    }

    // Expression-form callee (this.method(...), base.method(...), parenthesized).
    if (!call->identifier || !call->identifier->value) {
        if (call->expression) {
            if (auto* ma = dynamic_cast<MemberAccessNode*>(call->expression.get())) {
                // `Type.name(...)` — dot-on-type constructor call: the receiver names a TYPE, not an
                // instance. An in-scope binding wins (instance `.method` first), so this fires only when
                // the receiver is a bare type name with no live binding. Distinct from `Type::staticFn()`
                // (a static fn stays `::`); the strict-ctor gate inside points a static-fn dot at `::`.
                std::string dotType;
                if (isTypeReceiver(ma, dotType)) {
                    // The file rung, for the CONSTRUCTION position. It does not arrive through the
                    // resolve wrappers' gate because `isTypeReceiver` resolves with no site node, and a
                    // node cannot be invented here — recording a reference to the TYPE at the ctor's
                    // position would file the wrong entry in the index. So the predicate is called
                    // directly, which is also the honest shape: this is a distinct source position.
                    auto* rid = dynamic_cast<IdentifierNode*>(ma->expression.get());
                    const std::string spelled = rid && rid->value ? *rid->value : dotType;
                    // ⚠️ A BOUND TYPE PARAMETER is not a reference to anything in this file. `T.make(...)`
                    // inside a generic resolves `T` to the CALLER's concrete type, so judging it here
                    // blamed the template's file for the instantiation site's type — `json.kama` was
                    // reported for a fixture's own `T`. The instantiation site already judged that
                    // argument, where it was written. Same reason the wrappers skip a synthesized node.
                    if (!_typeSubst.count(spelled))
                        checkReach(dotType, spelled, "a construction", call->line, refFilePath(),
                                   rid && rid->qualifier && !rid->qualifier->empty());
                    return emitDotOnTypeCtorCall(call, ma, dotType);
                }
                return emitMethodCall(call, ma);
            }
#if KAMA_INHERITANCE
            if (auto* ba = dynamic_cast<BaseAccessNode*>(call->expression.get())) {
                // base.m(args) -> direct (non-virtual) call into the base.
                if (!_currentClass) {
                    unsupported("`base` is only meaningful inside a method of a derived type", call->line);
                    return "0";
                }
                if (!_currentClass->base) {
                    unsupported(("'" + _currentClass->name + "' has no base class, so `base` names nothing "
                                 "(only a type declared `extends …` has one)").c_str(), call->line);
                    return "0";
                }
                std::string m = (ba->identifier && ba->identifier->value) ? *ba->identifier->value : "";
                ClassInfo* owner = nullptr;
                MethodInfo* mi = findMethod(_currentClass->base, m, &owner);
                if (!mi) {
                    unsupported(("'" + m + "' is not a method of the base class '"
                                 + _currentClass->base->name + "'").c_str(), call->line);
                    return "0";
                }
                // The base path used to skip access control entirely, so a derived type could reach any
                // PRIVATE method of its base just by choosing this spelling — `this.secret()` rejected,
                // `base.secret()` compiled. Apply the existing rule; no new one is needed. `_currentClass`
                // is the derived type here, so canAccess walks its base chain and admits protected while
                // rejecting private, which is exactly right. (The base FIELD path already did this.)
                canAccess(owner, mi->visibility, m, call->line);
                recordNodeRef(ba->identifier.get(), mi->node);   // M6 B3a: `base.m()` references the base's m
                std::string self = "(" + owner->name + "*)&self->__base";
                return emitReorderedCall(mi->cName, self, mi->params, call->args, call->line);
            }
#endif
        }
        unsupported("indirect call", call->line);
        return "0";
    }

    std::string name = *call->identifier->value;

    // A turbofish's type arguments are types written in a body, judged like any other (KR-46) — on the
    // routed path too, where a private qualified argument used to instantiate and run.
    const auto unsupportedBefore = _unsupported;
    forEachTypeArg(call->identifier, [&](const SharedIdentifier& a) {
        checkBodyType(a, "a turbofish type argument", call->line); });
    const bool badTypeArg = _unsupported != unsupportedBefore;

    // a call to a generic function was resolved to a concrete instantiation at discovery.
    // Route it to that specialized C name; reorder named args off the template's param list.
    {
        std::string instKey = callInstOf(call);
        if (!instKey.empty()) {
            const GenericInst& gi = _genericInsts[instKey];
            const FuncSig& tmpl = _funcs[gi.templateKey];
            // M6 B3: the call names the TEMPLATE, not the instantiation it was routed to — the instance's
            // mangled name has no def-site, and two instantiations must not split one declaration's
            // references. This path returns before the resolveFunc that records every other call.
            recordRef(gi.templateKey, call->identifier.get());
            return placeWrap(emitReorderedCall(gi.mangledName, "", instParamSigs(gi), call->args, call->line),
                             tmpl.isPlaceReturn);
        }
    }

    // Turbofish `f::<…>` that didn't resolve to a generic instantiation -> the target isn't a generic
    // function. Reject rather than silently drop the type arguments.
    if (call->identifier->genericArgs) {
        // While PROBING there is no recorded instantiation for a turbofish, because the discovery pass
        // never walks a body nobody instantiates — `_callInst` is populated there, not here. The type
        // arguments ARE resolvable now (the enclosing parameters are bound to opaque types), so do what
        // discovery would have done, on demand. Without this the whole call is skipped, and with it the
        // callee's parameter names, arity and argument types are checked like any other call.
        if (_probingTemplate) {
            const std::string k = resolveFunc(name, call->identifier->qualifier);
            auto git = _generics.find(k);
            if (git != _generics.end()) {
                GenericInst gi;
                if (explicitGenericInst(git->second, k, call->identifier->genericArgs,
                                        call->identifier->nTypeArgs, call->args, nullptr, call->line, gi)) {
                    if (!_genericInsts.count(gi.mangledName)) _genericInsts[gi.mangledName] = gi;
                    const FuncSig& tsig = _funcs[k];
                    recordRef(k, call->identifier.get());   // the reference is to the TEMPLATE, as above
                    ++_probeResolved;
                    return placeWrap(emitReorderedCall(gi.mangledName, "", instParamSigs(gi), call->args,
                                                       call->line), tsig.isPlaceReturn);
                }
            }
        }
        // A turbofish inside an uninstantiated template forwards the enclosing `T` (`sortWith::<T, C>`), so
        // `explicitGenericInst` deferred it and there is no instantiation to route to — absence, not error.
        if (deferUnknownWhileProbing(DK_Turbofish)) return "0";
        // An argument that failed above is why no instantiation resolved; the callee may well be generic.
        if (badTypeArg) return "0";
        // Name the group the reader actually wrote. `genericArgs` now merges both, so a call that only
        // ever carried `#(…)` would otherwise be told about a turbofish it never typed.
        unsupported((call->identifier->nTypeArgs == 0
                         ? "`" + name + "#(…)` — compile-time arguments are only valid on a generic function"
                         : "`" + name + "::<…>` — turbofish type arguments are only valid on a generic function")
                        .c_str(), call->line);
        return "0";
    }

    // FAIL CLOSED: the callee IS a generic template, and no instantiation was ever resolved for this call.
    //
    // Falling through here is what the code used to do, and it is silently wrong: the ordinary function
    // path below emits the TEMPLATE's own mangled C name, which no body ever defines — only instances are
    // emitted. So the compiler wrote a call to a function that does not exist, reported success, and let
    // CLANG find it: `call to undeclared function '_Fd__ident'`. Every discovery hole in this family
    // surfaced that way rather than as a kama diagnostic, which is how they stayed unnoticed.
    //
    // Silent in the two cases that are absence rather than error: while PROBING an uninstantiated template
    // (discovery never walks that body, so `_callInst` is legitimately empty — the turbofish arm above says
    // the same), and when discovery already LOOKED and diagnosed, which would otherwise make one mistake
    // report twice.
    if (!_probingTemplate && !_genericInferFailed.count(call)) {
        const std::string gk = resolveFunc(name, call->identifier->qualifier);
        if (_generics.count(gk)) {
            unsupported(("`" + name + "` is a generic function and no instantiation was resolved for this "
                         "call — pass the type arguments explicitly (`" + name + "::<…>(…)`)").c_str(),
                        call->line, name);
            return "0";
        }
    }

    // FunctionPtr invoke: a bare local whose type is a signature → an indirect
    // call `c(reordered args)` (c IS the function pointer). Named-arg reorder off the sig.
    if ((!call->identifier->qualifier || call->identifier->qualifier->empty())
        && _localTypes.count(name) && isSigType(_localTypes[name])) {
        const SigInfo& sig = _sigs.at(_localTypes[name]);
        // No-heap gate: the target is unresolvable, so the proof crosses only where the SIGNATURE
        // declared it may. A `@noheap fnptr` has had every bind checked against that promise
        // (checkFnPtrBind), so the call is provable and nothing is recorded — the escape hatch this
        // gate existed to make necessary rather than decorative.
        if (!sig.noHeap) rejectNoHeapIndirect("through a `fnptr`", call->line);
        std::string callee = _refParams.count(name) ? ("(*" + name + ")") : name;
        return emitReorderedCall(callee, "", sig.params, call->args, call->line);
    }

    // ...and the same call through a module `static`/`comptime` of signature type. A `fnptr` could be
    // BOUND in a field or a static but never CALLED through one, so the whole install-a-handler-now,
    // invoke-it-later shape was unreachable: `g_h = dbl;` compiled and `g_h(x: 1)` said "call to unknown
    // function", because the arm above only recognises a bare LOCAL and a module name is not one. It
    // resolves the way every other module name does (`resolveModuleVar`), and the C spelling is the
    // symbol itself — a static of function-pointer type IS the pointer, exactly as the local is.
    if (!name.empty()) {
        const std::string ms = resolveModuleVar(name, call->identifier->qualifier);
        auto mit = _moduleStatics.find(ms);
        if (mit != _moduleStatics.end() && mit->second && mit->second->value
            && isSigType(cType(mit->second))) {
            const SigInfo& sig = _sigs.at(cType(mit->second));
            if (!sig.noHeap) rejectNoHeapIndirect("through a `fnptr`", call->line);   // see the local arm
            return emitReorderedCall(ms, "", sig.params, call->args, call->line);
        }
    }

    // BindableFunctionPtr invoke: a bare local of bindable type → branch on the
    // bound object (call the method with it, or the free fn directly).
    if ((!call->identifier->qualifier || call->identifier->qualifier->empty())
        && _localTypes.count(name) && isBindableClass(_localTypes[name])) {
        return emitBindableInvoke(name, _localTypes[name], call->args, call->line);
    }

    // FFI: `addr(x)` is a builtin — the address of a local/value (`&(x)`), for out-params and passing a
    // descriptor by pointer.
    //
    // It used to need no `unsafe`, on the reasoning that it addresses a REAL value. The boundary spike
    // killed that: `addr(of:)` plus an `UnsafePtr` FIELD is a general dangling-pointer factory — take the
    // address of a local, store it, return — which reproduces `stack-use-after-scope` under ASan with no
    // `View` involved and no marker anywhere in the program (finding 2). Addressing a live value is safe;
    // it is the raw pointer that comes BACK, and outlives it, that is not.
    if (name == "addr" && (!call->identifier->qualifier || call->identifier->qualifier->empty())
        && call->args && call->args->size() == 1) {
        rejectRawOutsideUnsafe("`addr(of: …)`", call->line);
        SharedExpression a = (*call->args)[0]->expression;
        // …and it does not launder const. On a const root the pointer that comes back is an
        // `UnsafeConstPtr<T>` (callReturnTypeRaw types it `T const*`), so `addr` is no longer the spelling
        // that skips the assignment-LHS `checkConstWrite` watches: a store through it is refused there, and
        // handing it to an `UnsafePtr<T>` local, argument or return is refused at that sink
        // (rejectConstPtrWiden). It used to be rejected outright, because there was no expression-level
        // const pointer to hand back; now the honest answer is to hand one back. A `mods`-counter iterator
        // factory (`addr(of: this.mods)` into an `UnsafePtr<uint32> modsp`) stays correctly outside the
        // const surface — by the widen rule at its ctor call, not by a refusal here.
        // Taking a SLOT's address is the vouching act for the raw move-out dance (`slot T x;
        // UnsafePtr<T> d = addr(of: x); unsafe { d[0] = …; } return give x;`): the code now initializes that
        // storage by hand, so the hole becomes a live value and its destructor comes back. Restricted to
        // slots so this can't silently resurrect a genuinely moved-from local.
        if (auto* aid = dynamic_cast<IdentifierNode*>(a.get()))
            if (aid->value && (!aid->qualifier || aid->qualifier->empty()) && _slotLocals.count(*aid->value)) {
                _slotLocals.erase(*aid->value);
                _moveState[*aid->value] = MoveState::NotMoved;
            }
        // The operand must be a PLACE — a field, local, or element. A temporary has no address that
        // outlives the expression, and `&(f())` is not even valid C. (This check lived in a second,
        // unreachable `addr` handler below for its whole life — the guard above it was identical and
        // returned first — so it had never once fired, and `emitPlace`'s user-`operator[]` /
        // place-returning-method awareness was bypassed with it.)
        if (!isNamedValue(a.get()))
            unsupported("`addr(of: …)` needs a place — a field, local, or element (not a temporary)",
                        call->line);
        // An element or field IS a place, but not when its ROOT is a temporary: `addr(of: f.view()[0])`
        // indexes a view minted by a call and dropped at the end of the statement, so the pointer would
        // dangle — and until 0.9.231 it escaped the front end and died in clang ("cannot take the address
        // of an rvalue"), which a package author who does not read C could not act on (the first external
        // package's KAMA_GAPS #3). A place-returning call at the root (`b.at(i: 0)`) is storage the callee
        // still owns and stays fine, as it does for `isNamedValue`.
        else if (rootIsTemporary(a))
            unsupported(("`addr(of: …)` on an element of a temporary — `" + unparseExpr(a) + "` is rooted in "
                         "a call result that is dropped at the end of the statement, so the pointer would "
                         "dangle; bind the value to a local first, then take the address through that").c_str(),
                        call->line);
        return "(&(" + emitPlace(a) + "))";
    }

    // `panic(msg:)`, `assert(cond:, msg:)`, `debugAssert(cond:, msg:)` — builtins that trap cleanly (abort
    // with a message + `file:line`), the user-facing form of the runtime bounds trap. Let a user collection
    // bounds-check itself without dropping to FFI `abort()`. `panic` aborts unconditionally; `assert`/
    // `debugAssert` abort iff the condition is false, auto-appending the condition's source text (unparseExpr)
    // to the message. `msg:` is MANDATORY (empty string allowed). `debugAssert` is stripped under `--release`
    // (dev-only checks; `assert` stays always-on). Recoverable errors use `Result<T,E>` — these are for
    // "this is a bug that can't continue".
    bool bareCall = (!call->identifier->qualifier || call->identifier->qualifier->empty());
    if (bareCall && (name == "panic" || name == "assert" || name == "debugAssert")) {
        auto argByName = [&](const char* want) -> SharedExpression {
            if (call->args) for (auto& a : *call->args)
                if (a && a->name && a->name->value && *a->name->value == want) return a->expression;
            return nullptr;
        };
        std::string fileLit = "\"" + cEscapeStringBody(_sourcePath) + "\"";
        std::string lineLit = std::to_string(call->line);

        if (name == "panic") {
            SharedExpression msg = argByName("msg");
            if (!msg) { unsupported("`panic` requires `msg:`", call->line); return "(void)0"; }
            return "kama_panic_at(" + emitExpression(msg) + ", " + fileLit + ", " + lineLit + ")";
        }
        SharedExpression cond = argByName("cond");
        SharedExpression msg  = argByName("msg");
        if (!cond) { unsupported("`assert`/`debugAssert` requires `cond:`", call->line); return "(void)0"; }
        if (!msg)  { unsupported("`assert`/`debugAssert` requires `msg:` (use `msg: \"\"` for none)", call->line); return "(void)0"; }
        if (name == "debugAssert" && _release) return "(void)0";   // stripped in release builds
        std::string condText = unparseExpr(cond);
        return "((" + emitExpression(cond) + ") ? (void)0 : kama_assert_fail(\""
             + cEscapeStringBody(condText) + "\", " + emitExpression(msg) + ", " + fileLit + ", " + lineLit + "))";
    }
    // `sizeof(ptr: p)` / `alignof(ptr: p)` — the layout of the object `p` points at, which is what
    // `Allocator.deallocate` must be given back. For a class with a vtable that is the MOST-DERIVED layout, read
    // through the vptr: a base pointer can hold a derived object, and `sizeof(T)` would hand the allocator a
    // smaller block than it gave out. For anything else the static type is the whole story. Only the grammar
    // builds these calls, always with one argument. Read them BEFORE `drop(ptr:)`, which ends the object's life.
    if ((name == "sizeof" || name == "alignof") && bareCall && call->args && call->args->size() == 1) {
        const bool isSize = name == "sizeof";
        ArgumentNode* a0 = (*call->args)[0].get();
        const std::string label = (a0->name && a0->name->value) ? *a0->name->value : "";
        if (label != "ptr") {
            unsupported(("`" + name + "(" + label + ": …)` — the pointer form is `" + name + "(ptr: p)`, the "
                         + (isSize ? "size" : "alignment") + " of the object `p` points at; the "
                         + (isSize ? "size" : "alignment") + " of a type is `" + name + "(T)`").c_str(), call->line);
            return "0";
        }
        std::string pc = rawPointeeCType(a0->expression);
        if (pc.empty()) {
            unsupported(("`" + name + "(ptr:)` takes an `UnsafePtr<T>` — it measures the POINTEE. The "
                         + std::string(isSize ? "size" : "alignment") + " of a type is `" + name + "(T)`").c_str(),
                        call->line);
            return "0";
        }
#if KAMA_INHERITANCE
        if (_classes.count(pc) && _classes[pc].hasVtable)
            return pc + (isSize ? "__vsize(" : "__valign(") + emitExpression(a0->expression) + ")";
#endif
        return (isSize ? "sizeof(" : "_Alignof(") + pc + ")";
    }
    // `drop(place)` — run the destructor of a place's value (for a library owner over `UnsafePtr<T>` to drop
    // its heap pointee before `free`). A no-op when the value's type isn't destructible. The type is
    // resolved via exprClass (so `drop(this.deref())` reaches the pointee `T` through a `ref T` return).
    if (name == "drop" && bareCall && call->args && call->args->size() == 1) {
        ArgumentNode* a0 = (*call->args)[0].get();
        SharedExpression a = a0->expression;
        const std::string label = (a0 && a0->name && a0->name->value) ? *a0->name->value : "";
        // `drop(ptr: p)` — destroy the POINTEE of a raw pointer. This is what `drop` is FOR: one leg of the
        // manual-memory triad (`allocate` hands out bytes -> a value is placed in them -> `drop` destroys
        // the value -> `deallocate` returns the bytes), reaching a place RAII cannot. Taking the pointer
        // rather than a place is what makes the marker free: an `UnsafePtr` expression already requires an
        // `unsafe fn`, so no separate rule is owed — and a LOCAL is not a pointer, so `drop(local)`, which
        // used to emit a second destructor call on top of the scope's, becomes unspellable.
        if (label == "ptr") {
            std::string pc = rawPointeeCType(a);
            if (pc.empty()) {
                // A destructor MUTATES what it runs on, so an `UnsafeConstPtr<T>` is refused — and named,
                // rather than swept into the generic message, because the author asked for something kama
                // HAS with the wrong half of a pair. (`UnsafeConstPtr<T>` lowers east-const to `T const*`.)
                const std::string ct = lvalueCType(a);
                if (ct.size() > 7 && ct.compare(ct.size() - 7, 7, " const*") == 0)
                    unsupported("cannot `drop` through an `UnsafeConstPtr<T>` — a destructor mutates what it "
                                "runs on. Drop through the writable pointer (`derefMut()`'s owner, "
                                "`addr(of: …)` on a mutable root, or `dataPtrMut()`)", call->line);
                else
                    unsupported("`drop(ptr:)` takes an `UnsafePtr<T>` — it destroys the POINTEE. To end a "
                                "local's life early, give it a scope (`{ T x = …; }`); a local is already "
                                "owned and dropping it again would run its destructor twice", call->line);
                return "(void)0";
            }
            if (_classes.count(pc)) {
                // Polymorphic drops through the vtable: a base pointer owning a derived must run the
                // derived's dtor. The pointer is already a pointer, so no `&(…)` here — that address-of is
                // exactly the round trip the place form had to make.
                if (_classes[pc].hasVtable)   return pc + "__vdrop(" + emitExpression(a) + ")";
                if (_classes[pc].destructible) return pc + "__dtor(" + emitExpression(a) + ")";
            }
            return "(void)0";            // a primitive / non-destructible pointee: nothing to run
        }
        // Any other label — `drop(value: place)`, the old form — is refused. It accepted a place RAII
        // already owned (a local, a by-value parameter), and the scope destructor then ran on the SAME
        // object: two destructor calls, a double free, no diagnostic. It shipped that way in six stdlib
        // sites (`0.9.290`) and crashed `SortedMap.put` on any owning value. The pointer form cannot
        // express it — a local is not a pointer — which is why this is a REMOVAL rather than a check.
        const std::string shown = unparseExpr(a);
        if (label == "value")
            unsupported(("`drop(value:)` is gone — it took a place, and a place RAII already owns got its "
                         "destructor run twice. `drop(ptr:)` takes an `UnsafePtr<T>` and destroys the "
                         "POINTEE: write `drop(ptr: " + shown + ")` if `" + shown + "` is a raw pointer, or "
                         "`drop(ptr: addr(of: " + shown + "))` for an element in a buffer you manage. To end "
                         "a LOCAL's life early, give it a scope: `{ T x = …; }`").c_str(), call->line);
        else
            unsupported(("`drop` takes `ptr:` — `drop(ptr: " + shown + ")`, an `UnsafePtr<T>` whose pointee "
                         "is destroyed").c_str(), call->line);
        return "(void)0";
    }
    // M6.2: `__kama_ctrl_atomic()` — a per-instance COMPILE-TIME constant (0/1) that the prelude
    // `Shared`/`Weak` refcount ops pass to the kama_ctrl.h seam. 1 iff the Shared/Weak instance being
    // emitted is the deeply-immutable (atomic-refcount) flavor (`useAtomicRefcount`); the seam's branch on
    // it folds at compile time, so an ordinary `Rc` keeps the non-atomic counter ops at zero cost while a
    // `Shared<immutable T>` gets the Arc-correct atomics. Read from `_currentClass` (the instance whose
    // method body is being emitted). Not user-facing (leading `__`); only the prelude names it.
    if (name == "__kama_ctrl_atomic" && bareCall && (!call->args || call->args->empty()))
        return (_currentClass && _currentClass->useAtomicRefcount) ? "1" : "0";

    // (A bare function name is a value — its C function pointer — so `FunctionPtr<Sig> c = fn;`
    // and passing `fn` directly bind a callable; there is no separate `funcptr(of: fn)` builtin.)

    // A `::`-qualified callee is **scope resolution**: `Namespace::fn(...)`. The head of a `::`
    // is always a type/namespace — never an object (object
    // access is `.`/member_access) — so the old namespace-vs-object precedence hack
    // is gone. `resolveFunc` handles namespace + `using` + alias resolution.
    SharedStringList qual = call->identifier->qualifier;
    if (qual && !qual->empty()) {
        // `Union::Variant(args)` — construct a discriminated-union value with a payload
        // (`Optional<int32>::Some` resolves via the target-type context).
        auto tq = std::make_shared<StringList>();
        for (size_t i = 0; i + 1 < qual->size(); ++i) tq->push_back((*qual)[i]);
        if (ClassInfo* vt = resolveVariantType(resolveUserName(*qual->back(), tq)))
            for (auto& v : vt->variants)
                if (v.name == name) {
                    // M6 B3e: `Union::Variant(args)` names the variant just as a payload-less
                    // `Union::Variant` read does (the IdentifierNode branch already records that one) —
                    // the CONSTRUCTION form simply returned before reaching any recorder.
                    recordRef(enumMemberKey(vt->name, name), call->identifier.get());
                    return emitVariantConstruction(*vt, name, call->args, call->line);
                }
        // `Type::method(args)` — a static method (no implicit `self`). The qualifier head
        // resolves to a class; the named method must be `static`.
        std::string typeName = resolveUserName(*qual->back(), tq);
        // Same as the construction position above: `Type::staticFn()` and `Union::Variant(...)` resolve
        // their HEAD with no site node, so the wrappers' gate never sees it. And the same exclusion:
        // a bound type parameter's substitution belongs to the instantiation site, not to this file.
        if (!_typeSubst.count(*qual->back()))
            checkReach(typeName, *qual->back(), "a static call", call->line, refFilePath(),
                       qual->size() > 1);
        // `Box::<int32>::tag()` — an EXPLICIT turbofish on the qualifier names the monomorph directly.
        // Mirrors what emitDotOnTypeCtorCall does for the ctor form, and takes precedence over the
        // inference below: the user said which instance, so there is nothing to infer.
        if (call->identifier->qualifierGenericArgs && !call->identifier->qualifierGenericArgs->empty()
            && !_classes.count(typeName) && _genericTypeParams.count(typeName))
            typeName = genericTypeMangle(typeName, call->identifier->qualifierGenericArgs);
        // A generic-type static factory (`Map<int32,int32> m = Map::withCapacity(...)`): the qualifier head
        // names the bare template, so infer the concrete instance from the enclosing typed position — the
        // same `_variantTargetType` channel the bare ctor and `Optional::Some` already consume (mirrors
        // `resolveVariantType`). Nothing to infer from means it falls through to the usual resolution.
        if (!_classes.count(typeName) && !_variantTargetType.empty()) {
            auto of = _genericTypeInstOf.find(_variantTargetType);
            if (of != _genericTypeInstOf.end() && of->second == typeName)
                typeName = _variantTargetType;   // "Map" -> "Map_int32_int32"
        }
        // Fallback: a bound type-parameter head (`T::make` in a generic `fn f<T: C>()`) substitutes to its
        // monomorphized concrete type, so a static contract method on a type-param resolves (e.g.
        // `json::decode<T: Deserializable>` calling `T::deserialize(...)`, or a collection's `T::deserialize`).
        // The concrete type may be a PRIMITIVE whose static conformance lives in `_primConformances`
        // (`int32::deserialize` -> `r.readI32()`), so consider both tables.
        // A bound type-parameter head substitutes to its monomorphized concrete type.
        if (!_classes.count(typeName) && !primConformance(typeName)) {
            auto sit = _typeSubst.find(*qual->back());
            if (sit != _typeSubst.end() && sit->second) {
                std::string concrete = primKey(sit->second);   // the conformance key, not the C type
                if (_classes.count(concrete) || primConformance(concrete)) typeName = concrete;
            }
        }
        // A user type resolves in `_classes`; a primitive/intrinsic-collection static (a `type intrinsic`
        // conformance) resolves via `implTargetInfo` (`_primConformances`).
        ClassInfo* stci = _classes.count(typeName) ? &_classes[typeName] : implTargetInfo(typeName);
        if (stci) {
            ClassInfo* owner = nullptr;
            MethodInfo* mi = findMethod(stci, name, &owner);
            // Construction has exactly ONE spelling: dot-on-type. A `ctor` registers as static (it takes no
            // `self`), so without this it would ALSO answer to `::` — two ways to say the same thing, and the
            // greppability the split exists for would be false: `grep '\.make('` would miss half the call
            // sites. This is the mirror of the `Type.staticFn(...)` rejection in emitDotOnTypeCtorCall; both
            // directions are now closed, so `.` is construction and `::` is scope resolution, always.
            // No exemption for a type-parameter head: `T.deserialize(...)` in `fn f<T: Deserializable>()` is
            // construction too, and dot-on-type resolves through the substitution just as `::` did. One
            // rule, no exceptions — which is the only way `grep '\.make('` finds every construction site.
            if (mi && mi->isCtor) {
                // Diagnose with the SOURCE spelling the user wrote, not the mangled/monomorphized key
                // `typeName` may have become above (`Point`, not `_F<file>__Point`; `Pair`, not `Pair_int32`).
                const std::string& disp = *qual->back();
                unsupported(("`" + disp + "::" + name + "` names a constructor — construct with "
                             "dot-on-type: `" + disp + "." + name + "(...)`. `::` is scope resolution "
                             "(static functions, enum variants, modules)").c_str(), call->line);
                return "0";
            }
            if (mi && mi->isStatic) {
                canAccess(owner, mi->visibility, name, call->line);
                recordNodeRef(call->identifier.get(), mi->node);   // M6 B3a: `Type::m()` references m
                // a place-returning `static fn ref T` returns a `T*` — deref like a free fn (no self)
                return placeWrap(emitReorderedCall(mi->cName, "", mi->params, call->args, call->line),
                                 mi->isPlaceReturn);
            }
            if (mi && !mi->isStatic)
                unsupported(("`" + typeName + "::" + name + "` names a non-static method — call it on an instance (`obj." + name + "(...)`)").c_str(), call->line);
        }
        // const-eval 6b-3: a type-associated `comptime fn` (`Type::table()`) runs only at compile time.
        if (_comptimeMethods.count(typeName + "::" + name)) {
            unsupported(("`" + typeName + "::" + name + "` is a `comptime fn` — it runs only at compile time; "
                         "assign its result to a `comptime` constant and use that").c_str(), call->line);
            return "0";
        }
        auto fit = _funcs.find(resolveFunc(name, qual, call->identifier.get()));
        if (fit != _funcs.end()) {
            gateExternCall(fit->second, name, call->line);
            return placeWrap(emitReorderedCall(symbolOf(fit->second), "", fit->second.params, call->args, call->line),
                             fit->second.isPlaceReturn);
        }
        // The head names a GENERIC template with no turbofish (`Box::tag()`). `typeName` is the bare
        // template, which is in no instance table, so this used to land on the catch-all below — a
        // message that names neither the cause nor the fix. A static has no receiver and its parameters
        // need not mention `T`, so the type arguments cannot be inferred and must be written.
        if (_genericTypeParams.count(typeName) && _genericTypes.count(typeName)
            && _genericTypes[typeName].methods.count(name)) {
            const std::string& disp = *qual->back();
            unsupported(("`" + disp + "` is generic — a static needs its type arguments: `"
                         + disp + "::<...>::" + name + "(...)`").c_str(), call->line);
            return "0";
        }
        // `Natural<T>::compare(...)` — the qualifier names a generic instance that has none yet.
        if (deferUnknownWhileProbing(DK_ScopeQual)) return "0";
        // A one-segment qualifier that is neither a type nor a module in reach is the likelier mistake —
        // name IT, with the import when another file declares it.
        const std::string& head = *qual->back();
        if (qual->size() == 1 && !isNamespace(head) && !isTypeKey(resolveUserNameImpl(head, nullptr))) {
            if (!reportDeclaredElsewhere("type", head, [&](const std::string& k) { return isTypeKey(k); },
                                         "this call", call->line))
                unsupported(("`" + head + "::" + name + "` — `" + head + "` is not a type or module in reach "
                             "here").c_str(), call->line, head);
            return "0";
        }
        unsupported(("`" + head + "::" + name + "` — scope-qualified call resolves to no known "
                     "function").c_str(), call->line);
        return "0";
    }

    // Free-function call — resolve the name through the file's scope + usings.
    auto it = _funcs.find(resolveFunc(name, call->identifier->qualifier, call->identifier.get()));
    if (it == _funcs.end()) {
        // const-eval 6b-3: a `comptime fn` is not a runtime symbol — reject a runtime-position call
        // with a diagnostic that points at the `comptime` constant form.
        std::string ck;
        if (isComptimeFnName(name, call->identifier->qualifier, ck)) {
            unsupported(("`" + name + "` is a `comptime fn` — it runs only at compile time; assign its "
                         "result to a `comptime` constant and use that").c_str(), call->line);
            return "0";
        }
        // The SUBJECT, so an editor can offer the import: a free `fn` is an importable name like any
        // other, and "unknown function" is what a missing import looks like from here.
        if (!call->identifier->qualifier || call->identifier->qualifier->empty()) {
            if (!reportDeclaredElsewhere("function", name, [&](const std::string& k) { return _funcs.count(k) > 0; },
                                         "this call", call->line))
                unsupported(("call to unknown function `" + name + "` — no function of that name is declared or "
                             "imported").c_str(), call->line, name);
        } else
            unsupported("call to unknown function (args kept in source order)", call->line, name);
        std::string s = cFunctionName(name) + "(";
        bool first = true;
        if (call->args) for (auto& a : *call->args) {
            if (!first) s += ", ";
            first = false;
            s += emitExpression(a->expression);
        }
        return s + ")";
    }
    gateExternCall(it->second, name, call->line);
    return placeWrap(emitReorderedCall(symbolOf(it->second), "", it->second.params, call->args, call->line),
                     it->second.isPlaceReturn);
}

bool CEmitter::paramByRef(FunctionParameterNode* p)
{
    return p && p->modifier && p->modifier->value &&
           (*p->modifier->value == "ref" || *p->modifier->value == "out");
}

// `out T x` — the write-only half of the by-pointer pair. Same C lowering as `ref` (a `T*`); the
// difference is the CONTRACT: the callee must assign it on every path and may not read what came in,
// and the call site must spell `out` so the caller knows its variable is being filled, not borrowed.
bool CEmitter::paramIsOut(FunctionParameterNode* p)
{
    return p && p->modifier && p->modifier->value && *p->modifier->value == "out";
}

// C parameter list. ref/out parameters become pointers. When selfType is set,
// a leading `selfType* self` is prepended (for methods/constructors).
std::string CEmitter::paramListC(SharedParameterList params, const char* selfType,
                                 const char* ownerCType, bool selfByValue)
{
    std::string s;
    bool first = true;
    // A conformed PRIMITIVE (`type intrinsic <int32> implements Hashable`) takes `this` (= `self`) as the
    // SCALAR by value — `int32_t self`, not `int32_t* self`. The caller reads that off the target's
    // `isScalarRecv`; `selfType` is a C type and can no longer answer the question by itself.
    if (selfType) { s += std::string(selfType) + (selfByValue ? " self" : "* self"); first = false; }
    if (params) {
        for (auto& p : *params) {
            if (!first) s += ", ";
            first = false;
            std::string nm = (p->identifier && p->identifier->value) ? *p->identifier->value : "";
            // `const UnsafePtr<T>`/`const UnsafePtr` emits `const T*`/`const void*` (FFI const
            // pointers — to match C const callback/API signatures). Only pointer types:
            // a `const ref <class>` stays plain (its methods take a non-const `self`).
            // An `UnsafeConstPtr<T>` already spells its `const` in its C type (`T const*`), so the prefix is
            // for the `const UnsafePtr<T>` form alone — a const BINDING of a mutable pointer, kept lowering
            // to `const T*` as it always has.
            bool constPtr = p->isConst && isRawPtrName(p->type) && !isConstRawPtrName(p->type);
            // `hardware UnsafePtr<T>` emits `volatile T*` — a pointer to an MMIO register (mirrors `const UnsafePtr<T>`).
            // `const hardware UnsafePtr<T>` / `hardware UnsafeConstPtr<T>` → `const volatile T*` (a read-only
            // status register). Raw pointers only.
            bool hwPtr = p->isHardware && isRawPtrName(p->type);
            if (p->isHardware && !hwPtr)
                unsupported("`hardware` applies only to an `UnsafePtr<T>` or `UnsafeConstPtr<T>` parameter (a pointer to an MMIO register)", p->line);
            // a `ref`/`const ref` parameter may not name a smart pointer — you borrow
            // the OBJECT (`ref T`), or transfer ownership by value (`give`/`copy`). Borrowing
            // the handle never makes sense (and would make `ref p` ambiguous). `out` producing
            // a handle (tryUpgrade / factory-out) stays legal.
            std::string pct = cType(p->type);
            std::string libElem = heapOwnerTarget(pct);   // library Owned/Shared pointee ("" otherwise)
            // A SELF-borrow is the exception: `ref This` on the smart pointer's own member borrows the
            // handle it belongs to, which is exactly what `ctor copy(ref This source)` (and any
            // `Equatable`/`Comparable` impl on a handle) needs. The rule is about borrowing SOMEONE
            // ELSE's handle, which is what never makes sense.
            bool selfBorrow = (selfType && pct == selfType) || (ownerCType && pct == ownerCType);
            if (paramByRef(p.get()) && p->modifier && p->modifier->value && *p->modifier->value == "ref"
                && !selfBorrow && (isSmartPtrClass(pct) || !libElem.empty()))
                unsupported(("a `ref` parameter may not name a smart pointer ('" + pct
                             + "') — borrow the object with `ref "
                             + (libElem.empty() ? _classes[pct].collElemClass : libElem)
                             + "`, or transfer ownership by value (`give`/`copy`)").c_str(), p->line);
            s += std::string(constPtr ? "const " : "") + std::string(hwPtr ? "volatile " : "") + cType(p->type)
               + (paramByRef(p.get()) ? "* " : " ") + nm;
        }
    }
    if (s.empty()) s = "void";
    return s;
}

// MCU step 4 — lower `@interrupt` / `@section(".x")` declaration attributes to a C
// `__attribute__((...))` prefix. `fn` is the function node (null for a module static, which only
// accepts `@section`). Emits ONLY where the programmer annotated a declaration — un-annotated code
// is byte-identical to before. Returns "" when there are no attributes.
std::string CEmitter::declAttrPrefix(const SharedAttributeList& attrs, FunctionDeclarationNode* fn, int line,
                                     AttrSite site)
{
    if (!attrs || attrs->empty()) return "";
    const bool onMember = (site == AttrSite::Member);
    std::vector<std::string> parts;
    for (auto& at : *attrs) {
        if (!at || !at->name) continue;
        const std::string& an = *at->name;
        if (an == "interrupt") {
            // `@interrupt` → Cortex-M / RISC-V / classic-ARM ISR calling convention. (AVR's
            // `@interrupt("VECTOR")` → `ISR(VECTOR)` macro is a later step.) `used` keeps it from
            // being dropped by `--gc-sections`; the vector table references it by symbol.
            if (!fn) {
                // A member is rejected for a reason of its own, not for being "not a function": an ISR is
                // reachable only under an exported symbol (the vector table has no other way to name it), and
                // a method's C name is mangled and carries a leading `self` the hardware will not supply.
                unsupported(onMember
                    ? "`@interrupt` applies only to a free function, not to a member — a vector table "
                      "reaches its handler by an exported symbol, and a member's C name is mangled and takes "
                      "a receiver. Make the ISR an `expose fn` that calls the member"
                    : "`@interrupt` applies only to a function, not a `static`", line);
                continue;   // every check below is about the function; `fn` is the null just rejected
            }
            if (at->args && !at->args->empty())
                unsupported("`@interrupt` takes no arguments (AVR `ISR(vector)` is a later step)", line);
            if (cType(fn->returnType) != "void")
                unsupported("`@interrupt` handler must return `void` — an ISR takes no return path", line);
            if (fn->parameters && !fn->parameters->empty())
                unsupported("`@interrupt` handler must take no parameters (an ISR is `void f(void)`)", line);
            if (!isExposed(fn))
                unsupported("`@interrupt` requires `expose` so the vector table can reference the handler by an "
                            "exported symbol (an internal kama function has none) — and `@linkName(\"…\")` when "
                            "the startup code fixes the handler's name", line);
            parts.push_back("interrupt");
            parts.push_back("used");
        } else if (an == "section") {
            // `@section(".name")` — exactly one bare string-literal arg. Valid on functions + statics.
            std::string sec;
            if (at->args && at->args->size() == 1) {
                auto& a = (*at->args)[0];
                if (a && !a->name && a->expression)
                    if (auto* s = dynamic_cast<StringNode*>(a->expression.get()))
                        if (s->value) sec = *s->value;
            }
            if (sec.empty())
                unsupported("`@section(\"...\")` requires exactly one string-literal section name", line);
            parts.push_back("section(\"" + sec + "\")");
        } else if (an == "linkName") {
            // Validated and recorded at collection (`linkNameOf`, `FuncSig::linkName`); here it only has
            // to be on the right kind of declaration. It emits no `__attribute__` — the symbol IS the
            // definition's name (`mangledFunctionName`). An `extern fn` never reaches this emitter.
            if (!fn || !isExposed(fn))
                unsupported((std::string("`@linkName` names the symbol of an `extern fn` or an `expose fn`, and ")
                             + (onMember ? "a member has none to rename — its C name is mangled and takes a receiver"
                                : !fn    ? "a `static` is not a function"
                                         : "an ordinary `fn` has none — its C name is kama's to choose; `expose` it "
                                           "to fix the symbol")).c_str(), line);
        } else if (an == "serializedGraphEdges") {
            // Serde metadata on a MEMBER, in one of two roles told apart by the signature it sits on: an
            // ACCESSOR ("these are the elements carrying my graph edges; rewire them through here", checked
            // by `mutIterOf`) or a DELEGATE ("the element write is handed to me", checked by
            // `graphDelegateNeeded`). Read off `MethodInfo::serdeGraphEdges`. Contributes NO
            // `__attribute__` — a marker, like `@noheap` below. Member-only: `@field` is the peer that marks
            // a FIELD serde walks, and this marks the members the elements are reached through, which are
            // not fields.
            if (!onMember)
                unsupported("`@serializedGraphEdges` marks a METHOD the serde graph routes through — the "
                            "accessor handing out a container's graph-edge elements, or the helper its "
                            "element write is delegated to — not a whole declaration", line);
            // no parts.push_back — emits nothing
        } else if (an == "noheap") {
            // `@noheap` (MCU step 5): a CHECKER flag, not codegen — the body rejects every emitter-visible
            // heap allocation (activated per-body in emitFunction via `_noHeapActive`). Contributes NO
            // `__attribute__`. Function-only, no args. Guarantees this region (an ISR, a game-engine frame
            // tick, a real-time audio callback) allocates nothing.
            if (!fn && !onMember)
                unsupported("`@noheap` applies only to a function, not a `static`", line);
            if (at->args && !at->args->empty())
                unsupported("`@noheap` takes no arguments", line);
            // no parts.push_back — emits nothing
        } else if (an == "foreignEntry" || an == "callerThread") {
            // The threading contract of a callback (ROADMAP row 1). Like `@noheap` these are CHECKER
            // flags and contribute no `__attribute__`: `@foreignEntry` makes this body a region the
            // module-static check walks (a static assigned on the other side of the boundary is a
            // different object there), `@callerThread` says the opposite and turns the check off.
            //
            // On a BODY the pair is not symmetric, which is why they are judged apart here. A region is
            // something a body can BE, so `@foreignEntry` is legal on any body — it is the declared
            // escape for a pointer handed to C by a route the compiler cannot see, the same role
            // `@noheap` on a `fnptr` plays for allocation. `@callerThread` states a promise about a
            // CALLER, so on an ordinary body it would silence nothing (there is nothing to silence) and
            // read as an assertion the compiler never checks; the one body that has a caller it cannot
            // see is an `expose fn`, where a host picks the thread.
            if (!fn && !onMember)
                unsupported(("`@" + an + "` applies only to a function, not a `static`").c_str(), line);
            if (at->args && !at->args->empty())
                unsupported(("`@" + an + "` takes no arguments").c_str(), line);
            if (an == "callerThread" && fn && !isExposed(fn))
                unsupported("`@callerThread` states that a callback runs on the calling isolate, so it "
                            "belongs on the `fnptr` type a C API takes, or on an `expose fn` a host "
                            "calls — on an ordinary function there is no crossing for it to describe", line);
            if (fn && hasAttr(fn->attributes, "foreignEntry") && hasAttr(fn->attributes, "callerThread"))
                unsupported("a function is `@foreignEntry` or `@callerThread`, not both", line);
            // no parts.push_back — emits nothing
        } else if (an == "onPanic") {
            // `@onPanic(recover: <literal>)` (ROADMAP row 2): a CHECKER flag plus a prologue — emits no
            // `__attribute__`. The body becomes a recoverable region: a panic inside it (or inside anything
            // it calls) returns the literal instead of aborting the process. Legal only on a body, and
            // only beside `@noheap`: recovery is a longjmp, which skips every destructor between the fault
            // and the prologue, so the region must own nothing that needs one — no heap (the attribute the
            // author writes here) and no destructible local (checkOnPanicRegions, walked transitively).
            // The region names its own recovery value because no default is right: a `TickFn` returns 1
            // to keep the loop running, so a zero would end the very loop the region was meant to save.
            if (!fn && !onMember)
                unsupported("`@onPanic` applies only to a function body, not a `static`", line);
            if (!hasAttr(attrs, "noheap"))
                unsupported("`@onPanic` needs `@noheap` on the same body — recovery is a longjmp out of "
                            "the fault, which frees nothing, so the region must allocate nothing", line);
            const bool isVoid = fn && (!fn->returnType || (fn->returnType->value && *fn->returnType->value == "void"));
            const size_t nargs = at->args ? at->args->size() : 0;
            if (nargs > 1 || (nargs == 1 && (!(*at->args)[0] || !(*at->args)[0]->name
                                              || !(*at->args)[0]->name->value
                                              || *(*at->args)[0]->name->value != "recover")))
                unsupported("`@onPanic` takes one named argument, the value the region returns after a "
                            "recovered panic: `@onPanic(recover: 1)` — or none on a `void` body", line);
            else if (nargs == 0 && fn && !isVoid)
                unsupported(("`@onPanic` on `" + (fn->name && fn->name->value ? *fn->name->value : std::string("?"))
                             + "` needs `recover:` — the region returns a value, so say which one a "
                               "recovered panic hands back (`@onPanic(recover: 1)`)").c_str(), line);
            else if (nargs == 1 && fn && isVoid)
                unsupported("`@onPanic(recover: …)` on a `void` body — there is nothing to return; write `@onPanic`", line);
            else if (nargs == 1) {
                SharedExpression e = (*at->args)[0]->expression;
                ASTNode* en = e.get();
                if (auto* su = dynamic_cast<SimpleUnaryExpressionNode*>(en)) en = su->expression.get();   // `-1`
                const bool lit = dynamic_cast<Int32Node*>(en) || dynamic_cast<Int64Node*>(en)
                              || dynamic_cast<Float32Node*>(en) || dynamic_cast<Float64Node*>(en)
                              || dynamic_cast<BooleanNode*>(en);
                if (!lit)
                    unsupported("`recover:` takes a literal — the value is returned from a longjmp landing "
                                "pad, before any local exists to compute it from", line);
            }
            // no parts.push_back — emits nothing here; the prologue is emitted at the body's root block
        } else if (an == "compileFor") {
            // `@compileFor(FLAG)` is consumed by the conditional-compilation prune pass
            // (pruneInactiveDecls) and stripped from kept decls before emission — reaching here from a
            // top-level decl means one still carries it (defensive). It is a build-time gate, not a C
            // attribute: no parts.
            //
            // On a MEMBER it is a hard error, and the reason is the one thing a defensive no-op cannot
            // be here: pruneInactiveDecls walks TOP-LEVEL declarations only, so a member's `@compileFor`
            // is never evaluated and never stripped — it would reach this branch on every build and do
            // nothing at all, silently. A gate that silently fails open is the worst shape a conditional
            // can take, and it is exactly what the first external project hit with `@compileFor(NATIVE)`.
            if (onMember) unsupported(kCompileForOnMember, line);
        } else if (an == "align" || an == "packed") {
            // Layout control is a property of a TYPE, not of one declaration — so there is one way to
            // align an object rather than two, which is the call Rust makes as well (`#[repr(align(N))]`
            // is types-only; a static is aligned by wrapping it in an aligned type). Named rather than
            // swept into the catch-all because the user asked for something kama HAS, in the wrong place.
            unsupported(("`@" + an + "` states the layout of a TYPE, not of one declaration. Put it on the "
                         "type and declare this with that type: `@" + an
                         + (an == "align" ? "(N) type value Buf { … }" : " type value Buf { … }")
                         + "` then `static Buf …;`").c_str(), line);
        } else if (onMember && (an == "generate" || an == "viewable")) {
            // Both state something about a whole TYPE — what to synthesize for it, and that it mints a
            // view. Named rather than swept into the catch-all for the same reason `@align` is: the user
            // asked for something kama HAS, one level down from where it belongs.
            unsupported(("`@" + an + "` marks a `type`, not a member of one — put it on the enclosing "
                         "type declaration").c_str(), line);
        // `@deprecated` is deliberately NOT listed here. Its meaning today is serialization metadata on a
        // field, but a general declaration marker (a use-site warning, on a method as readily as a field)
        // is already scheduled — baking "field-only" into a diagnostic we plan to contradict is worse than
        // letting a misplaced one fall to the catch-all unknown-attribute message.
        } else if (an == "heap") {
            unsupported("`@heap` marks an `extern fn` — it says C the compiler cannot read touches the heap. A kama "
                        "body's allocations are seen without it, so on a body it would be a second, unchecked claim "
                        "about the same thing", line);
        } else if (onMember && (an == "field" || an == "skip")) {
            unsupported(("`@" + an + "` marks a FIELD (it is serialization metadata), not a method, `ctor`, "
                         "destructor or operator").c_str(), line);
        } else {
            unsupported(("unknown attribute `@" + an + "` here — expected "
                         + (onMember ? "`@noheap`, `@foreignEntry`, `@serializedGraphEdges` or `@section(\"...\")`"
                                     : "`@interrupt`, `@section(\"...\")`, `@noheap`, `@foreignEntry`, "
                                       "or `@callerThread`")).c_str(), line);
        }
    }
    if (parts.empty()) return "";
    std::string out = "__attribute__((";
    for (size_t i = 0; i < parts.size(); ++i) { if (i) out += ", "; out += parts[i]; }
    out += ")) ";
    return out;
}

// Does this attribute list carry `@noheap`? (Activates the per-body no-heap gate.) Node-free, because a
// METHOD carries the same attribute on a different node — the question is about the list, never about
// which declaration kind happens to hold it.
bool CEmitter::hasAttr(const SharedAttributeList& attrs, const char* name) const
{
    if (!attrs) return false;
    for (auto& at : *attrs)
        if (at && at->name && *at->name == name) return true;
    return false;
}

bool CEmitter::hasNoHeapAttr(const SharedAttributeList& attrs) const
{
    return hasAttr(attrs, "noheap");
}

// Does this function carry `@noheap`? (Activates the per-body no-heap gate.)
bool CEmitter::fnHasNoHeap(FunctionDeclarationNode* fn) const
{
    return fn && hasNoHeapAttr(fn->attributes);
}

// The ONE no-heap gate (MCU step 5): reject an emitter-visible heap allocation under `--no-heap`
// (program-wide) or inside a `@noheap` function body. Every allocation-emitting site funnels through here
// — `new`/`try new`, the parallel_for/isolate/enum boxing, and string interpolation's Formatter buffer —
// so the guarantee is one gate, not a dozen scattered checks. `unsupported()` makes it a hard compile
// error (the driver's error count fails the build). `what` names the construct for the diagnostic.
//
// This gate answers for ONE body. What a `@noheap` region reaches through its CALLEES is answered by
// checkNoHeapTransitive, which is fed from here — see the record below.
//
// (A note stood here saying collection methods "allocate in library C the emitter can't see per-call", so
// a `@noheap` fn could still call a growing collection. It was stale in its reasoning and then wrong in
// its conclusion: the collections have been ordinary kama for some time, and a container reaches the heap
// through its `A: Allocator`, which the emitter can see all the way down to `GlobalAllocator.allocate`.
// That is now the analysis's leaf, so `list.add(x)` inside a `@noheap` region IS rejected — while the same
// call on an arena-backed `DynamicArray<T, BumpAllocator>` is not, because `A` is monomorphized.)
void CEmitter::rejectIfNoHeap(const char* what, int line)
{
    // A PROBE emits nothing. `--no-heap` is a promise about the code a build actually produces, and a
    // template nobody instantiates produces none — so a library type that allocates somewhere in its API
    // must not fail a no-heap program that merely has it in scope. (`SortedMap` allocates in three
    // methods; before this, importing the module was enough.) A real instantiation reaches this gate
    // through the ordinary path, where the allocation is real.
    //
    // Checked BEFORE the record below as well as before the rejection: a probe body must not teach the
    // transitivity analysis that a function allocates, for the same reason it must not fail the build.
    if (_probingTemplate) return;
    // With `@globalAllocator` declared, every site this gate sees draws from the funnel, and the funnel is no longer
    // the system heap: it is the pool. So the site is an EDGE into the pool (buildCallGraph), and the pool's body
    // decides — for `@noheap` as for `--no-heap`, over the same walk. (Starting a thread is not a site here; a
    // borrowed `spawn` records nothing, and a moved one records only its bundle, which the funnel allocates.)
    if (!_globalAllocator.empty()) {
        if (!_currentFunc.empty() && !_funnelCallers.count(_currentFunc)) _funnelCallers[_currentFunc] = line;
        return;
    }
    // RECORD FIRST, GATE SECOND — and note the record is unconditional, taken whether or not this body
    // is `@noheap`. That is the whole point: the function that actually allocates is almost never the
    // annotated one, so the analysis needs the allocation facts for EVERY body, not just the gated ones.
    // First site per function wins; a function that allocates twice is no more allocating than one that
    // allocates once, and the first is the one the diagnostic should point at.
    if (!_currentFunc.empty() && !_allocSites.count(_currentFunc))
        _allocSites[_currentFunc] = AllocSite{ what, line, diagFile(), /*indirect=*/false, /*reported=*/_noHeapActive };
    // ⚠️ `@noheap` REFUSES HERE; `--no-heap` does NOT — the same asymmetry rejectNoHeapIndirect states below, and
    // for the same reason. The attribute proves THIS body; the flag proves the PROGRAM, which is what its entry
    // points reach, so its verdict comes from checkNoHeapTransitive. Refusing here under the flag as well made
    // `import { std::uuid::Uuid };` alone fail a `--no-heap` build four times, at stdlib lines nothing calls.
    if (!_noHeapActive) return;
    unsupported((std::string("heap allocation (") + what + ") is forbidden here — this code is "
                 "`@noheap`; use a stack value, a fixed buffer, or a fixed-capacity arena "
                 "with no dynamic growth").c_str(), line);
}

// The no-heap gate's other half: a call whose target the compiler cannot see. `@noheap` is a PROOF, and a
// proof cannot step over a call it cannot resolve — a `fnptr` slot may be bound to anything, so allowing it
// would silently reduce the guarantee to "allocates nothing, except where we stopped looking". That is the
// exact fail-open shape the transitivity defect had.
//
// Recorded into `_allocSites` like an allocation, which is what makes it transitive for free: a `@noheap`
// fn that calls a helper that dispatches through a callback slot is caught by the same walk, with the same
// chain, and needs no second mechanism. The rendering differs because the defect does.
//
// The escape hatch is `@noheap` ON THE SIGNATURE — a `@noheap fnptr`, whose every bind is checked against
// the promise, so the call through it is provable and never reaches here. This gate is what makes that
// declaration necessary rather than decorative. A contract member and a `virtual` slot have the same pair.
void CEmitter::rejectNoHeapIndirect(const char* what, int line)
{
    if (_probingTemplate) return;
    if (!_currentFunc.empty() && !_allocSites.count(_currentFunc))
        _allocSites[_currentFunc] = AllocSite{ what, line, diagFile(), /*indirect=*/true, /*reported=*/_noHeapActive };
    // ⚠️ `@noheap` REJECTS HERE; `--no-heap` does NOT, and the asymmetry is the point. An attribute says
    // "prove THIS body", so the body is the unit and an unprovable call in it is an error wherever it sits.
    // A BUILD FLAG says "prove the PROGRAM", and a program is what `main` reaches — so the flag's answer
    // comes from the reachability walk above, which reports the same fact with a call chain and reports it
    // only for code that actually runs. Rejecting here as well made the flag mean "no body ANYWHERE in the
    // import closure may dispatch", which is a different and much stronger claim than it advertises: it
    // made `import { std::collections::SlotMap };` alone fail a `--no-heap` build, because `Handle`'s
    // deserialize body exists — never called, never reached, and never able to allocate.
    // The direct-allocation sibling already worked this way, which is why `DynamicArray` under `--no-heap`
    // reports a chain from `main` rather than a bare line inside the stdlib.
    if (!_noHeapActive) return;
    unsupported((std::string("this code is `@noheap`/`--no-heap`, so it may not call ") + what
                 + " — the compiler cannot see the target, so it cannot prove the call allocates nothing. "
                   "Call a named function instead, or move the dispatch outside the no-heap region").c_str(),
                line);
}

// `T__copy(&(x))` — a DEEP copy, and the ONE way the emitter is allowed to spell one. It used to be
// written out at twelve sites; they are all this call now, so the intrinsic copy's allocation FACT below is
// recorded in one place. (A non-intrinsic copy is an ordinary call in the C, and so an ordinary edge.)
std::string CEmitter::copyCall(const std::string& cls, const std::string& lvalue)
{
    // An INTRINSIC owning collection's `__copy` is a runtime C function, not an emitted kama body, so it
    // has no facts of its own and an edge to it would point at nothing. `kama_string__copy` calls
    // `kama_alloc` outright — that is what deep-copying an immutable heap string means — so the fact is
    // recorded here instead. This is the same reason `GlobalAllocator` had to be named: every chain ends
    // in C, and the leaf is wherever the C is known to allocate.
    auto ci = _classes.find(cls);
    if (ci != _classes.end() && ci->second.isIntrinsicColl && ownsByValue(cls)) {
        // Recorded for every body and refused only in a `@noheap` one, like every other site (rejectIfNoHeap).
        // The prelude deep-copies a string in `Template.part` (`return copy this._parts[at]`), and that body is
        // emitted into every build — which is why the flag could never refuse this where it is written.
        rejectIfNoHeap((std::string("a deep `copy` of `") + demangleForDisplay(cls) + "` allocates a new buffer").c_str(),
                       _curLine);
    }
    // `__copy` READS its source, and every copy ctor takes a plain `T*` (`const ref` is ABI-neutral — see
    // paramListC), while a read-only place addresses as `T const*`: `copy this.data[p]` in `ViewIter.next()`
    // walks an `UnsafeConstPtr<T>`, and `copy cv[i]` reads through a `const ref T` place. The cast states
    // the ABI at the one site every deep copy funnels through, as the receiver and `__at` sites do.
    return cls + "__copy((" + cls + "*)&(" + lvalue + "))";
}

// A thread is created ONLY by the compiler's own lowering of `spawn`/`isolate` and `parallel_for` — no library
// source calls the seam's spawn — so this is the precise answer to "does this program need a threaded
// runtime". The driver reads it for wasm, where the answer is a HOSTING MODEL (`-pthread`, PROXY_TO_PTHREAD,
// a SharedArrayBuffer and its COOP/COEP headers), not a link flag: keyed on which seam headers a module
// externs, importing `Atomic` alone made a browser build threaded, because `std::concurrent`'s `Isolate`
// methods are emitted whether or not a program uses them (consumer KB-26).
void CEmitter::noteThreadSpawn()
{
    if (!_probingTemplate) _spawnsThreads = true;   // a probe emits no code
}

// Read the call graph out of the C this build produced (`_emittedC`, see EmitCapture). A function is a
// top-level `…name(…) {`; inside its body, an identifier naming another emitted function is an edge, keyed by
// the first site. Two identifiers are not references: a member (`.x`, `->x`, a field that shares a function's
// name) and a name the body declares — a parameter, or a local — unless it is CALLED, which a C local that
// shadows a function cannot be (KR-57 is the kama rule that would make the shadowing impossible). A call site's
// line is the `#line` above it; a body with no directive (the prelude, which has no file) carries line 0.
//
// What it cannot see is what is not in the text: a function a runtime MACRO defines (`KAMA_OWNED_IFACE_FUNCS`)
// and the runtime's own C. Those are leaf facts recorded by name, as `GlobalAllocator` is.
void CEmitter::buildCallGraph()
{
    const std::string& s = _emittedC;
    const size_t n = s.size();
    const bool pool = !_globalAllocator.empty();   // `@globalAllocator`: the funnel is an edge, not a heap fact
    auto identStart = [](char c) { return isalpha((unsigned char)c) || c == '_'; };
    auto identChar  = [](char c) { return isalnum((unsigned char)c) || c == '_'; };
    // A `#`-directive starts at a line's first non-blank char and runs to an unescaped newline.
    auto skipDirective = [&](size_t i) { while (i < n && s[i] != '\n') { if (s[i] == '\\' && i + 1 < n) ++i; ++i; } return i; };
    auto skipLiteral = [&](size_t i) {   // i at the opening quote; returns one past the closing one
        const char q = s[i++];
        while (i < n && s[i] != q) { if (s[i] == '\\') ++i; ++i; }
        return i + 1;
    };
    auto skipComment = [&](size_t i) {   // i at `/`, which starts `//` or `/*`
        if (s[i + 1] == '/') { while (i < n && s[i] != '\n') ++i; return i; }
        size_t e = s.find("*/", i + 2);
        return e == std::string::npos ? n : e + 2;
    };

    // Pass 1 — the function bodies. At depth 0 the text since the last `;`/`}` is the would-be header, kept
    // free of directives and comments; a `{` after one ending in `)` opens a body named by the identifier
    // before the matching `(`. Anything else (`struct X {`, `= {`) is braces, not a function.
    struct Body { std::string name; size_t open, close; std::string params; };
    std::vector<Body> bodies;
    {
        int depth = 0;
        bool lineStart = true;
        std::string seg;
        Body cur;
        for (size_t i = 0; i < n; ) {
            const char c = s[i];
            if (c == '\n') { lineStart = true; if (depth == 0) seg += ' '; ++i; continue; }
            if (c == ' ' || c == '\t' || c == '\r') { if (depth == 0) seg += ' '; ++i; continue; }
            if (lineStart && c == '#') { i = skipDirective(i); continue; }
            lineStart = false;
            if (c == '/' && i + 1 < n && (s[i + 1] == '/' || s[i + 1] == '*')) { i = skipComment(i); continue; }
            if (c == '"' || c == '\'') { size_t e = skipLiteral(i); if (depth == 0) seg.append(s, i, e - i); i = e; continue; }
            if (c == '{') {
                if (depth == 0) {
                    cur = Body();
                    size_t e = seg.find_last_not_of(' ');
                    if (e != std::string::npos && seg[e] == ')') {
                        int pd = 0; size_t p = e;
                        for (;; --p) { if (seg[p] == ')') ++pd; else if (seg[p] == '(' && --pd == 0) break; if (p == 0) break; }
                        size_t ne = p; while (ne > 0 && seg[ne - 1] == ' ') --ne;
                        size_t nb = ne; while (nb > 0 && identChar(seg[nb - 1])) --nb;
                        if (nb < ne && identStart(seg[nb])) {
                            cur.name = seg.substr(nb, ne - nb);
                            // A program's entry points, as the C says them: the one `main`, and every body the
                            // host can call by symbol (`expose fn`, which `@interrupt`/`@callerThread` require).
                            if (cur.name == "main" || seg.find("KAMA_EXPORT") != std::string::npos)
                                _entryBodies.insert(cur.name);
                            cur.params = seg.substr(p, e - p + 1);
                            cur.open = i;
                        }
                    }
                }
                ++depth; ++i; continue;
            }
            if (c == '}') {
                if (--depth == 0) {
                    if (!cur.name.empty()) { cur.close = i; bodies.push_back(cur); }
                    cur = Body(); seg.clear();
                }
                if (depth < 0) depth = 0;
                ++i; continue;
            }
            if (depth == 0) { if (c == ';') seg.clear(); else seg += c; }
            ++i;
        }
    }
    std::set<std::string> defined;
    for (const Body& b : bodies) defined.insert(b.name);

    static const std::set<std::string> kNotAType = { "return", "case", "goto", "sizeof", "else", "do", "typedef" };
    _callEdges.clear();
    int line = 0;
    std::string file;
    // `#line N "path"` at `d` — the path as `line()` wrote it, with its `\` and `"` escapes undone.
    auto readDirective = [&](size_t d) {
        line = atoi(s.c_str() + d + 6);
        size_t q = s.find('"', d + 6), eol = s.find('\n', d);
        file.clear();
        if (q == std::string::npos || q > eol) return;
        for (size_t k = q + 1; k < eol && s[k] != '"'; ++k) { if (s[k] == '\\' && k + 1 < eol) ++k; file += s[k]; }
    };
    size_t prevClose = 0;
    for (const Body& b : bodies) {
        // The directive in force when the body opens: scan the gap since the previous body for the latest one.
        for (size_t d = s.find("#line ", prevClose); d != std::string::npos && d < b.open; d = s.find("#line ", d + 6))
            readDirective(d);
        prevClose = b.close;
        struct Ref { std::string name; int line; bool call; };
        std::vector<Ref> refs;
        std::set<std::string> declared;
        // A parameter is an identifier followed by `,` `)` or `[` in the header's parameter list.
        for (size_t i = 0; i < b.params.size(); ) {
            if (!identStart(b.params[i])) { ++i; continue; }
            size_t e = i; while (e < b.params.size() && identChar(b.params[e])) ++e;
            size_t f = e; while (f < b.params.size() && b.params[f] == ' ') ++f;
            if (f < b.params.size() && (b.params[f] == ',' || b.params[f] == ')' || b.params[f] == '['))
                declared.insert(b.params.substr(i, e - i));
            i = e;
        }
        std::string prevTok;   // the previous significant token: an identifier, or one punctuation char
        bool lineStart = false;
        // Parenthesis depth, and the depth INSIDE the innermost `KAMA_NOHEAP_SLOT(` still open (0 = none).
        // A slot call is an allocation fact unless the emitter proved it from a declaration and wrapped it
        // in that marker — see kama_runtime.h for why the unmarked case is the one that must be sound.
        int pdepth = 0, provenAt = 0;
        for (size_t i = b.open + 1; i < b.close; ) {
            const char c = s[i];
            if (c == '\n') { lineStart = true; ++i; continue; }
            if (c == ' ' || c == '\t' || c == '\r') { ++i; continue; }
            if (lineStart && c == '#') {
                if (s.compare(i, 6, "#line ") == 0) readDirective(i);
                i = skipDirective(i); continue;
            }
            lineStart = false;
            if (c == '/' && i + 1 < n && (s[i + 1] == '/' || s[i + 1] == '*')) { i = skipComment(i); continue; }
            if (c == '"' || c == '\'') { i = skipLiteral(i); prevTok = "\""; continue; }
            if (!identStart(c)) {
                // `->` is one token for the member test below.
                if (c == '-' && i + 1 < n && s[i + 1] == '>') { prevTok = "->"; i += 2; continue; }
                if (c == '(') ++pdepth;
                if (c == ')') { if (provenAt && pdepth == provenAt) provenAt = 0; if (pdepth) --pdepth; }
                prevTok = std::string(1, c); ++i; continue;
            }
            size_t e = i; while (e < b.close && identChar(s[e])) ++e;
            const std::string id = s.substr(i, e - i);
            size_t f = e; while (f < b.close && (s[f] == ' ' || s[f] == '\t' || s[f] == '\r' || s[f] == '\n')) ++f;
            const char next = f < b.close ? s[f] : '\0';
            const bool member = prevTok == "." || prevTok == "->";
            // A local declaration: `T name =`, `T* name;`, `T name[` — a type token (or `*`) then the name.
            const bool afterType = prevTok == "*" || (!prevTok.empty() && identStart(prevTok[0]) && !kNotAType.count(prevTok));
            if (!member && afterType && (next == '=' || next == ';' || next == ',' || next == '['))
                declared.insert(id);
            if (!member && id != b.name && defined.count(id)) refs.push_back(Ref{ id, line, next == '(' });
            // With `@globalAllocator`, the funnel is the pool: a call to it is an edge into the pool's entry, not an
            // allocation fact (see rejectIfNoHeap for the sites whose C calls a runtime helper instead).
            const bool funnel = id == "kama_alloc" || id == "kama_alloc_zeroed" || id == "kama_free";
            if (pool && !member && next == '(' && funnel) {
                refs.push_back(Ref{ id == "kama_free" ? "kama__global_deallocate" : "kama__global_allocate", line, true });
                prevTok = id; i = e; continue;
            }
            // A call to C marked `@heap` is an allocation fact for this body — the first one, unless emission
            // already recorded one with a better sentence (the gate names the construct; this names the symbol).
            if (!member && next == '(' && _heapSymbols.count(id) && !_allocSites.count(b.name))
                _allocSites[b.name] = AllocSite{ "calls `" + id + "`, which is `@heap`", line, file };
            if (!member && next == '(' && id == "KAMA_NOHEAP_SLOT" && !provenAt) provenAt = pdepth + 1;
            // A CALL THROUGH A MEMBER is a call the compiler cannot see the target of. C has no methods, so
            // `x->m(…)` / `x.m(…)` is always a function pointer read out of a struct: a contract or virtual
            // slot, a `fnptr` field, a vtable's `__dtor`. Read here rather than recorded at the sites that
            // emit one, because the compiler writes slot calls in bodies no source line spells — the
            // synthesized `serialize`/`deserialize`, `__vdrop`, and the smart-pointer drops — and every one
            // of those was missing, so dropping a polymorphic box whose object frees heap memory passed a
            // `@noheap` region (found planning KR-39). A proven slot says so with the marker.
            //
            // `(x->m)(…)` — a member behind parentheses, which is how a bindable's type-erased `fn` is cast
            // before it is called — counts too. A cast `(T)(x)` never has a member before its `)`.
            if (member && !provenAt && !_allocSites.count(b.name)) {
                size_t g = f;
                if (next == ')') { ++g; while (g < b.close && isspace((unsigned char)s[g])) ++g; }
                if ((next == '(' || (next == ')' && g < b.close && s[g] == '(')))
                    _allocSites[b.name] = AllocSite{ id == "__dtor"
                        ? "the destructor of the object behind a contract or base-class handle"
                        : ("`" + id + "` through a dispatch slot"), line, file, /*indirect=*/true };
            }
            prevTok = id;
            i = e;
        }
        auto fc = _funnelCallers.find(b.name);   // a funnel use emission recorded (rejectIfNoHeap)
        if (pool && fc != _funnelCallers.end()) refs.push_back(Ref{ "kama__global_allocate", fc->second, true });
        auto& out = _callEdges[b.name];
        const auto drops = _dropSiteLines.find(b.name);
        for (const Ref& r : refs) {
            if (!r.call && declared.count(r.name)) continue;
            int at = r.line;
            if (drops != _dropSiteLines.end()) { auto d = drops->second.find(r.name); if (d != drops->second.end()) at = d->second; }
            out.emplace(r.name, CallEdge{ at });
        }
        line = 0; file.clear();   // a following body with no directive of its own must not inherit this one's
    }
}

// Is this body one the AUTHOR wrote? Asked only by `--no-heap`, which seeds the transitive walk with
// every user body so the `GlobalAllocator` leaf finally applies program-wide.
//
// It has to exist because the alternative — seeding EVERY body — is wrong twice, and both were already
// recorded facts before this was written. Gating the string copy program-wide once failed a program that
// sorts three integers, because `Template.part` in the PRELUDE does `return copy this._parts[at]`; and
// the leaf itself is deliberately "recorded, never rejected" (see its record in the member emitter) for
// exactly the same reason. Reporting per body would also name `DynamicArray.add` and `growTo` — stdlib
// functions the author did not write and cannot change.
//
// ⚠️ NEITHER HALF OF THE TEST IS SUFFICIENT ALONE, and each covers precisely the other's blind spot:
//
//   * `declFile` names the file a declaration was COLLECTED from, so the `<`-sentinel (`<prelude>`,
//     `<builtin>`, the embedded `std::memory` triad) identifies compiler-owned code — the same test
//     `checkReach` makes. But everything under `lib/std/` is parsed off disk and named by its real path,
//     so the sentinel says nothing about the stdlib proper.
//   * The module path DOES name the stdlib, and it cannot collide: `std` and `core` are RESERVED
//     top-level module segments, refused to user code by the driver. But the prelude has an EMPTY
//     namespace scope (`qualify`), so `GlobalAllocator::allocate` and `Template::part` render BARE and
//     the prefix test would call them user code.
//
// Not `diagFile()` and not `unitOfDecl` — the first falls back to the file being compiled for a prelude
// body emitted in the header pass (which is the trap this whole predicate exists to avoid), and the
// second is filled only under `_analysis`, so it answers nothing during `kama build`.
bool CEmitter::isUserBody(const std::string& declFile, const std::string& display) const
{
    if (declFile.empty() || declFile[0] == '<') return false;   // compiler-owned: prelude, builtin, triad
    return display.compare(0, 5, "std::") != 0 && display.compare(0, 6, "core::") != 0;
}

// `@noheap` is transitive: prove that no function reachable from an annotated body allocates.
//
// Runs after ALL emission on BOTH entry points, which is the ordering that matters — the facts it reads
// are produced by emission itself, so there is nothing to check until every body has been walked. (The
// last campaign shipped a gate that was a silent no-op on exactly one of these two paths because
// `emitIncludes` ran before `collectProgram` on the single-TU path and after it on the other. Two entry
// points, one order, asserted by a guard.)
//
// BOTH gates walk here, and for different reasons. The ATTRIBUTE needs propagation because the annotated
// body is almost never the allocating one. The FLAG proves the PROGRAM, which is what its entry points reach
// (KR-47): every user body is a candidate, and a candidate is judged only if `main`, an `expose fn` or a
// `@foreignEntry` body reaches it. An allocating helper nobody calls is not part of the program, and neither
// is a stdlib body that merely came in with an import.
void CEmitter::checkNoHeapTransitive()
{
    if (_noHeapFns.empty()) return;

    // What the entry points reach — forward, over the same graph. Only the flag asks.
    std::set<std::string> reached;
    if (_noHeapProgram) {
        std::vector<std::string> todo(_entryBodies.begin(), _entryBodies.end());
        for (auto& fe : _foreignEntryFns) todo.push_back(fe.first);   // called by C, by a route no edge shows
        while (!todo.empty()) {
            const std::string f = todo.back(); todo.pop_back();
            if (!reached.insert(f).second) continue;
            auto it = _callEdges.find(f);
            if (it != _callEdges.end()) for (auto& e : it->second) todo.push_back(e.first);
        }
    }

    // Which functions allocate, transitively. Seed with the ones that allocate DIRECTLY and walk the call
    // graph BACKWARDS to every caller — a reverse-reachability fixpoint, the same shape computeDestructible
    // uses over field types, and cheaper than the forward closure because it visits each function once.
    std::map<std::string, std::vector<std::string>> callers;
    for (auto& kv : _callEdges)
        for (auto& e : kv.second) callers[e.first].push_back(kv.first);

    std::set<std::string> allocates;
    std::vector<std::string> work;
    for (auto& kv : _allocSites) { allocates.insert(kv.first); work.push_back(kv.first); }
    while (!work.empty()) {
        const std::string f = work.back(); work.pop_back();
        auto it = callers.find(f);
        if (it == callers.end()) continue;
        for (const std::string& c : it->second)
            if (allocates.insert(c).second) work.push_back(c);
    }

    for (auto& kv : _noHeapFns) {
        const std::string& root = kv.first;
        if (!allocates.count(root)) continue;
        if (kv.second.fromFlag && !reached.count(root)) continue;   // not part of the program
        // A body that allocates DIRECTLY is reported at the allocation, with no chain — the fault is in this
        // body, not one hop away. Unless the gate already said so where it was written (`reported`: only a
        // `@noheap` body refuses eagerly), which names the construct at the same line; a second rendering of
        // one defect is the mistake `unsupported`'s own header warns against.
        auto own = _allocSites.find(root);
        if (own != _allocSites.end()) {
            if (own->second.reported) continue;
            const AllocSite& site = own->second;
            ScopedStr _f(_emitDeclFile, site.file.empty() ? kv.second.file : site.file);
            // The gate's own sentences, with the reason the site is judged in place of "this code is `@noheap`".
            const std::string why = kv.second.fromFlag
                ? ("this build is `--no-heap`, and the program reaches `" + kv.second.display + "`")
                : ("`" + kv.second.display + "` is `@noheap`");
            unsupported((site.indirect
                             ? ("this build is `--no-heap`, but `" + kv.second.display + "` dispatches " + site.what
                                + ", so what it allocates cannot be proven — call a named function instead, or move "
                                  "the dispatch outside the no-heap region")
                             : ("heap allocation (" + site.what + ") is forbidden here — " + why + "; use a stack "
                                "value, a fixed buffer, or a fixed-capacity arena with no dynamic growth")).c_str(),
                        site.line ? site.line : kv.second.line, kv.second.display);
            continue;
        }

        // Breadth-first for the SHORTEST chain. A depth-first walk finds *a* path, and on a call graph
        // that includes the stdlib that path can be absurd — the reader is being asked to follow it, so
        // it should be the shortest one that exists.
        std::map<std::string, std::string> parent;
        std::vector<std::string> queue{ root };
        std::set<std::string> seen{ root };
        std::string hit;
        for (size_t qi = 0; qi < queue.size() && hit.empty(); ++qi) {
            auto it = _callEdges.find(queue[qi]);
            if (it == _callEdges.end()) continue;
            for (auto& e : it->second) {
                if (!allocates.count(e.first) || !seen.insert(e.first).second) continue;
                parent[e.first] = queue[qi];
                if (_allocSites.count(e.first)) { hit = e.first; break; }
                queue.push_back(e.first);
            }
        }
        if (hit.empty()) continue;   // reachable but no path survives — nothing honest to say

        std::vector<std::string> chain;
        for (std::string n = hit; !n.empty(); n = (parent.count(n) ? parent[n] : std::string()))
            chain.push_back(n);

        // ANCHOR AT THE BOUNDARY — a `--no-heap` root reports only when its FIRST HOP leaves user code.
        // Every function on a chain reaches the leaf, so seeding every user body and reporting each one
        // renders the same defect once per frame of the stack: `main`, then `mid`, then `grow`, three
        // messages and three chains for one `l.add(x)`. The innermost user body is also the only one
        // whose message is actionable — it is the frame that contains the call the author can change.
        // If the first hop is itself a seeded root it will report, so this terminates on the last user
        // function before the library, by induction down the chain. A first hop that is NOT a root (an
        // intrinsic, a template probe) reports here instead, because nobody else will.
        //
        // The ATTRIBUTE is untouched: an author who wrote `@noheap` asked about THAT function, and the
        // answer is about that function even when a helper one hop in shares the fault.
        const std::string& firstHop = chain[chain.size() - 2];
        if (kv.second.fromFlag) {
            auto fh = _noHeapFns.find(firstHop);
            if (fh != _noHeapFns.end() && fh->second.fromFlag) continue;
        }

        std::string path;
        for (auto it = chain.rbegin(); it != chain.rend(); ++it)
            path += (path.empty() ? "`" : " -> `") + demangleForDisplay(*it) + "`";

        const AllocSite& site = _allocSites[hit];
        // A position only when there is an honest one to give — see the leaf's record for the case that
        // has none, where the chain's last link already names the culprit.
        const std::string where = site.file.empty() ? std::string()
                                : (" at " + site.file + ":" + std::to_string(site.line));
        // Point at the FIRST HOP's call site: it is inside the annotated body, so it is the line the
        // author can actually act on, and it is in the annotated function's own file.
        const int at = _callEdges[root].count(firstHop) ? _callEdges[root][firstHop].line : kv.second.line;
        ScopedStr _f(_emitDeclFile, kv.second.file);
        // Two defects share the walk, so they share the sentence up to the verb and no further: one says
        // the chain ALLOCATES, the other says the chain stops being provable. Telling a reader their audio
        // callback allocates when what it really does is dispatch through a callback slot would send them
        // hunting for a `new` that is not there.
        const std::string claim = site.indirect
            ? ("dispatches " + site.what + ", so what it allocates cannot be proven")
            : ("reaches heap allocation (" + site.what + ")" + where);
        // The two roots make two different claims and say so. `--no-heap` is a property of the BUILD, and
        // saying a function "is `@noheap`" when the author wrote no attribute sends them looking for one.
        const std::string subject = kv.second.fromFlag
            ? ("this build is `--no-heap`, but `" + kv.second.display + "` ")
            : ("`" + kv.second.display + "` is `@noheap`, but this call ");
        unsupported((subject + claim
                     + " through " + path
                     + (site.indirect ? " — call a named function instead, or move the dispatch outside "
                                        "the no-heap region"
                                      : " — make the callee allocation-free, or move the allocation "
                                        "outside the no-heap region")).c_str(),
                    at, kv.second.display);
    }
}

// ── The foreign-entry static-read walk (ROADMAP row 1) ───────────────────────────────────────────────
// A module `static` is `KAMA_ISOLATE_LOCAL` — one object per thread. A function that runs on a thread
// kama did not create (an audio render callback, a completion port, an ISR) therefore sees the DECLARED
// initialiser in every static, never a value some isolate assigned; the program compiles, runs, and reads
// an empty mixer buffer. `@foreignEntry` names that region so this walk can say, at compile time, "this
// read can only ever see the initialiser". The facts are recorded where every read and every write already
// passes — the identifier arm of emitExpression and checkConstWrite — so detection cannot drift from
// emission, and the region is closed over the same call graph the no-heap proof walks.
void CEmitter::recordStaticRead(const std::string& key, const std::string& name, int line)
{
    if (_probingTemplate || _currentFunc.empty()) return;
    if (key == _staticWriteLhs) { _staticWriteLhs.clear(); return; }   // the store target of a plain `=` — not a read
    if (_constStatics.count(key)) return;                             // `comptime`: a C `static const`, ONE object
    auto& m = _staticReads[_currentFunc];
    if (!m.count(key)) m[key] = StaticRead{ name, line, diagFile() };
}

void CEmitter::recordStaticWrite(SharedExpression target)
{
    if (_probingTemplate || _currentFunc.empty() || !target) return;
    const std::string root = rootBinding(target);
    if (root.empty() || root == "this" || _localTypes.count(root) || _paramNames.count(root)) return;
    if (_currentClass && findFieldOwner(_currentClass, root)) return;   // a bare field name, not a static
    const std::string key = resolveModuleVar(root, nullptr);
    if (!key.empty()) _staticWriters[key].insert(_currentFunc);
}

// The `@onPanic` gate the attribute cannot judge alone: recovery is a longjmp from the fault to the
// region's prologue, which skips every destructor in between — in the root AND in every callee on the
// chain. So no frame the region reaches may own a destructible local or an owning by-value parameter.
// `@noheap` (required beside the attribute) already proves the region allocates nothing, transitively;
// this is the RAII half of the same guarantee, over the same call graph, anchored at the local.
void CEmitter::checkOnPanicRegions()
{
    if (_onPanicFns.empty() || _destructibleOwners.empty()) return;
    for (auto& kv : _onPanicFns) {
        const std::string& root = kv.first;
        std::map<std::string, std::string> parent;
        std::vector<std::string> queue{ root };
        std::set<std::string> region{ root };
        for (size_t qi = 0; qi < queue.size(); ++qi) {
            auto it = _callEdges.find(queue[qi]);
            if (it == _callEdges.end()) continue;
            for (auto& e : it->second)
                if (region.insert(e.first).second) { parent[e.first] = queue[qi]; queue.push_back(e.first); }
        }
        for (const std::string& f : queue) {
            auto d = _destructibleOwners.find(f);
            if (d == _destructibleOwners.end()) continue;
            std::vector<std::string> chain;
            for (std::string n = f; !n.empty(); n = (parent.count(n) ? parent[n] : std::string())) chain.push_back(n);
            std::string path;
            for (auto it = chain.rbegin(); it != chain.rend(); ++it)
                path += (path.empty() ? "`" : " -> `") + demangleForDisplay(*it) + "`";
            ScopedStr _f(_emitDeclFile, d->second.file);
            unsupported(("`" + kv.second.display + "` is `@onPanic`, but " + (chain.size() > 1 ? path + " owns" : "it owns")
                         + " `" + d->second.name + "` (a `" + d->second.className + "`), which has a destructor — "
                         "a recovered panic is a longjmp out of the fault, which would skip it. Keep the region's "
                         "state in the pointer the callback receives, or move the owner outside the region").c_str(),
                        d->second.line);
            break;   // one sentence per region: the nearest frame, shortest chain
        }
    }
}

// Does any unit declare a `@onPanic` body? Asked before the TU's first line is written, because the
// answer decides whether `<setjmp.h>` is included and KAMA_ONPANIC defined — program-wide, since the
// runtime's recovery slot is `extern` in every TU and defined in the entry TU under the same macro.
bool CEmitter::unitsUseOnPanic(const std::vector<SharedCompilationUnit>& units)
{
    for (auto& u : units) {
        if (!u || !u->codeDeclarationList) continue;
        for (auto& decl : *u->codeDeclarationList) {
            if (auto* f = dynamic_cast<FunctionDeclarationNode*>(decl.get())) {
                if (f->attributes && hasAttr(f->attributes, "onPanic")) return true;
            } else if (auto* c = dynamic_cast<ClassDeclarationNode*>(decl.get())) {
                if (!c->members) continue;
                for (auto& m : *c->members)
                    if (m && m->attributes && hasAttr(m->attributes, "onPanic")) return true;
            }
        }
    }
    return false;
}

// Does any unit declare `@globalAllocator`? Asked before the TU's first line is written, like unitsUseOnPanic and
// for the same reason: the answer defines KAMA_GLOBAL_ALLOCATOR ahead of the runtime header, whose funnel then calls
// the pool's entry (`extern` in every TU, defined in the entry TU — emitRuntimeSlotDefinitions).
bool CEmitter::unitsDeclareGlobalAllocator(const std::vector<SharedCompilationUnit>& units)
{
    for (auto& u : units) {
        if (!u || !u->codeDeclarationList) continue;
        for (auto& decl : *u->codeDeclarationList)
            if (auto* c = dynamic_cast<ClassDeclarationNode*>(decl.get()))
                if (c->attributes && hasAttr(c->attributes, "globalAllocator")) return true;
    }
    return false;
}

// `@globalAllocator` — the rules a declaration must meet, whole-program, after emission (fields, conformances and
// ctors are all known by then), and the one defect the no-heap walk cannot see from outside: a pool that reaches the
// funnel is a pool that calls ITSELF. Refused in every build, not only a no-heap one, because it is not a question
// of heap — the first allocation would recurse until the stack runs out.
//
// The instance is `<Pool> kama_global_allocator = {0};` — a C global, with no startup hook to run a constructor
// before `main` (and none an MCU would have), so it begins as zero bytes and nothing else. Hence no ctor and no field
// initializer: either would be a promise the program never keeps. Its fields follow the sharing-seams rule, because
// every isolate calls into the same object: an `Atomic`, a deeply immutable value, raw storage (`UnsafePtr`), or an
// `InlineArray`/`Simd` of scalars.
void CEmitter::checkGlobalAllocator()
{
    std::vector<ClassInfo*> decls;
    for (auto& kv : _classes) if (kv.second.globalAllocator) decls.push_back(&kv.second);
    if (decls.empty()) return;
    auto refuse = [&](ClassInfo* ci, const std::string& why, int line = 0) {
        ScopedStr _cu(_collectingUnitPath, ci->declFile);   // whole-program pass: see diagFile()
        unsupported(("`@globalAllocator` `" + ci->name + "` " + why).c_str(), line ? line : ci->declLine());
    };
    if (decls.size() > 1) {
        refuse(decls[1], "is the program's second global allocator — `" + decls[0]->name + "` is already "
               "declared, and a program has ONE heap");
        return;
    }
    // Must be a `resource` — the heap is one object with identity, and a `value` would be copied — which needs no
    // test of its own: `GlobalHeap` is `for resource`, so the conformance below already refuses any other kind.
    ClassInfo* ci = decls[0];
    bool implements = false;
    for (auto& itf : ci->interfaces) if (itf == "GlobalHeap") { implements = true; break; }
    if (!implements) { refuse(ci, "must declare `implements GlobalHeap` — the contract is what promises the funnel "
                              "its `allocate`/`deallocate`"); return; }
    if (!ci->ctors.empty()) {
        refuse(ci, "declares a constructor, which would never run — the instance is a C global that starts as zero "
               "bytes, before `main` and with no startup hook, so design its state to begin at zero");
        return;
    }
    const NsCtx savedCtx = _nsCtx;
    const std::map<std::string, SharedIdentifier> savedSubst = _typeSubst;
    enterClassCtx(*ci);
    std::string bad;
    int badLine = 0;   // the field's own line: that is where the author acts
    for (auto& f : ci->fields) {
        badLine = f.nameId ? f.nameId->line : 0;
        if (f.initializer) {
            bad = "initializes its field `" + f.name + "`, which would never run — the instance is a C global that "
                  "starts as zero bytes, so design its state to begin at zero";
            break;
        }
        const std::string fc = cType(f.type);
        auto cls = _classes.find(fc);
        bool storage = false;   // `InlineArray`/`Simd` of scalars: raw bytes, whose discipline is the pool's own
        if (cls != _classes.end() && cls->second.isIntrinsicColl
            && (cls->second.collKind == CollKind::Fixed || cls->second.collKind == CollKind::Simd)) {
            auto co = _collections.find(fc);
            const std::string elem = co != _collections.end() ? co->second.elemCType : "";
            storage = !elem.empty() && isScalarPrimKey(primKeyOfCType(elem));
        }
        const bool shareable = storage || isAtomicClass(fc) || (!fc.empty() && fc.back() == '*')
                            || (cls != _classes.end() && !cls->second.isIntrinsicColl && deeplyImmutable(fc));
        if (!shareable) {
            bad = "has a field `" + f.name + "` (of type `" + (f.type && f.type->value ? *f.type->value : fc) + "`) that every isolate would write without "
                  "synchronization — a global allocator's fields are `Atomic`, deeply `immutable`, raw storage "
                  "(`UnsafePtr`), or an `InlineArray`/`Simd` of scalars";
            break;
        }
    }
    _nsCtx = savedCtx; _typeSubst = savedSubst;
    if (!bad.empty()) { refuse(ci, bad, badLine); return; }

    // A pool that reaches the funnel. Breadth-first from its two entries for the shortest chain; with a
    // declaration, every funnel use in the graph is an edge back into these entries (buildCallGraph).
    for (const char* entry : { "kama__global_allocate", "kama__global_deallocate" }) {
        std::map<std::string, std::string> parent;
        std::vector<std::string> queue{ entry };
        std::set<std::string> seen{ entry };
        std::string hit;
        for (size_t qi = 0; qi < queue.size() && hit.empty(); ++qi) {
            auto it = _callEdges.find(queue[qi]);
            if (it == _callEdges.end()) continue;
            for (auto& e : it->second) {
                if (e.first == "kama__global_allocate" || e.first == "kama__global_deallocate") {
                    parent[e.first + "#"] = queue[qi]; hit = e.first + "#"; break;
                }
                if (seen.insert(e.first).second) { parent[e.first] = queue[qi]; queue.push_back(e.first); }
            }
        }
        if (hit.empty()) continue;
        std::vector<std::string> chain;
        for (std::string n = hit; !n.empty(); n = (parent.count(n) ? parent[n] : std::string())) chain.push_back(n);
        chain.front().pop_back();   // the `#` that told the revisit apart from the start
        std::string path;
        for (auto it = chain.rbegin(); it != chain.rend(); ++it)
            path += (path.empty() ? "`" : " -> `") + demangleForDisplay(*it) + "`";
        refuse(ci, "reaches the global allocator it implements, through " + path + " — which is itself, so the "
               "first allocation would recurse without end; a pool draws from storage it owns");
        return;
    }
}

void CEmitter::checkForeignEntryStatics()
{
    if (_foreignEntryFns.empty() || _staticReads.empty()) return;
    for (auto& kv : _foreignEntryFns) {
        const std::string& root = kv.first;
        // The REGION: everything the root reaches, breadth-first so the chain reported is the shortest one.
        std::map<std::string, std::string> parent;
        std::vector<std::string> queue{ root };
        std::set<std::string> region{ root };
        for (size_t qi = 0; qi < queue.size(); ++qi) {
            auto it = _callEdges.find(queue[qi]);
            if (it == _callEdges.end()) continue;
            for (auto& e : it->second)
                if (region.insert(e.first).second) { parent[e.first] = queue[qi]; queue.push_back(e.first); }
        }
        std::set<std::string> reported;   // one sentence per static per root
        for (const std::string& f : queue) {
            auto rit = _staticReads.find(f);
            if (rit == _staticReads.end()) continue;
            for (auto& sr : rit->second) {
                const std::string& key = sr.first;
                if (reported.count(key)) continue;
                auto wit = _staticWriters.find(key);
                if (wit == _staticWriters.end()) continue;
                // Assigned only INSIDE the region is per-thread scratch and fine; the defect is a writer
                // the region cannot reach — that assignment happened on some other isolate's copy.
                std::string outside;
                for (const std::string& w : wit->second) if (!region.count(w)) { outside = w; break; }
                if (outside.empty()) continue;
                reported.insert(key);
                std::vector<std::string> chain;
                for (std::string n = f; !n.empty(); n = (parent.count(n) ? parent[n] : std::string())) chain.push_back(n);
                std::string path;
                for (auto it = chain.rbegin(); it != chain.rend(); ++it)
                    path += (path.empty() ? "`" : " -> `") + demangleForDisplay(*it) + "`";
                ScopedStr _f(_emitDeclFile, sr.second.file);
                unsupported(("`" + kv.second.display + "` is `@foreignEntry`"
                             + (kv.second.via.empty() ? std::string() : " (bound to `" + kv.second.via + "`)")
                             + ", but " + (chain.size() > 1 ? path + " reads" : "it reads") + " module static `"
                             + sr.second.name + "`, which `" + demangleForDisplay(outside) + "` assigns outside "
                             "the region — on a thread kama did not create a static holds only its declared "
                             "initialiser, never that value; carry the state through the pointer the C API "
                             "hands the callback instead").c_str(), sr.second.line);
            }
        }
    }
}

#if !KAMA_INHERITANCE
// The ONE gate for a `KAMA_INHERITANCE=0` compiler. Every surface that would need vtable machinery
// funnels through here (`extends`, a `virtual`/`abstract` class, a `virtual`/`override`/`abstract`
// method), so the rest of the emitter's inheritance code can be compiled out entirely: nothing
// downstream is reachable once these are rejected. `final` does NOT come here — it seals a type, it does
// not extend one, and `final class`/`final fn` is meaningful with no hierarchy at all.
void CEmitter::rejectInheritance(const char* what, int line)
{
    unsupported((std::string(what) + " needs inheritance, and this kama was built without it "
                 "(`KAMA_INHERITANCE=0`); compose the type instead, or declare a `contract` for "
                 "polymorphism").c_str(), line);
}
#endif

void CEmitter::emitFunctionPrototype(FunctionDeclarationNode* fn, const std::string* nameOverride)
{
    bool isEntry = false;
    std::string name = nameOverride ? *nameOverride : mangledFunctionName(fn, isEntry);
    rejectStoredInterface(fn->returnType, "returned from a function", fn->line);
    // a place-returning `fn ref T f(…)` emits `T* f(…)` (the place); its `return e` addresses it.
    const char* linkage = isExposed(fn) ? "KAMA_EXPORT "
                        : _emitStaticInlineFn ? "static inline " : (nameOverride ? "static " : "");
    *_out << linkage << declAttrPrefix(fn->attributes, fn, fn->line)
          << cType(fn->returnType) << placeRetSuffix(fn->isRef, fn->isConstRef) << " " << name
          << "(" << paramListC(fn->parameters, nullptr) << ");\n";
}

void CEmitter::emitFunction(FunctionDeclarationNode* fn, const std::string* nameOverride)
{
    bool isEntry = false;
    std::string name = nameOverride ? *nameOverride : mangledFunctionName(fn, isEntry);

    // `unsafe` marks a CONTAINED region, and `main` is the one function that contains everything: an
    // `unsafe fn main` puts the whole program inside the trusted set from the root, so every containment
    // rule the seam installs (`UnsafePtr` acquisition, `addr(of:)`, the `extern fn` call gate) is off for
    // the entire call-free body of the program at once. That is the same shape as finding 1 — a marker
    // whose scope is so wide it stops marking anything — and it is why the entry point is the one place
    // the qualifier cannot mean what it says. Rejected here rather than at the declaration sweep because
    // `isEntry` is decided by the same mangling that names the function.
    //
    // The fix costs nothing: a kama `unsafe fn` is callable FROM safe code (only an `extern fn` is gated
    // at the call, see gateExternCall), so the raw work moves one frame down into a helper and `main`
    // calls it. The marker then names the region that actually needs it.
    if (isEntry && fn->isUnsafe)
        unsupported("`main` may not be `unsafe` — it encloses the whole program, so the marker would put "
                    "every line in the trusted region. Move the raw work into a helper `unsafe fn` and "
                    "call it from `main` (calling an `unsafe fn` from safe code is allowed)", fn->line);

    // `expose fn` crosses to a host over a raw C ABI — an owned-by-value type (kama `string`,
    // a collection, or an `Owned`/`Shared`/`Weak` smart pointer) carries RAII/refcount state that
    // cannot cross that boundary safely. Gate it here (post-collectClasses, so `_classes` is filled).
    if (isExposed(fn)) {
        auto rejectOwned = [&](const std::string& cty, const char* where) {
            if (isSmartPtrClass(cty) || ownsByValue(cty))
                unsupported(("`expose`: `" + cty + "` cannot cross the C-ABI boundary by value (" + where
                             + ") — pass an `UnsafePtr<T>` or an `extern` struct").c_str(), fn->line);
        };
        rejectOwned(cType(fn->returnType), "return");
        if (fn->parameters)
            for (auto& p : *fn->parameters)
                if (p->type && !paramByRef(p.get())) rejectOwned(cType(p->type), "parameter");
        // The other direction a callback reaches C: HANDED BACK. The host calls this symbol and keeps
        // what it returns, so a kama function returned — bare, or inside a value — crosses exactly as an
        // argument does, and `checkForeignCrossing` never sees it because there is no call for it to
        // watch. The RETURN only: a callback arriving as a PARAMETER is C's own function pointer, and C
        // owes kama no threading contract for it.
        const std::string rty = cType(fn->returnType);
        std::string chain;
        std::set<std::string> seen;
        if (reachesUnannotatedSig(rty, chain, seen))
            unsupported((std::string("`expose`: `") + demangleForDisplay(rty) + "` is handed back to the "
                         "host" + (chain.empty() ? "" : " carrying a callback in `" + chain + "`") + ", and "
                         "a callback's threading contract cannot be inferred — mark that `fnptr` type "
                         "`@callerThread` if the host calls it on the calling isolate, or `@foreignEntry` "
                         "if it may run on a thread kama did not create (where a module `static` assigned "
                         "elsewhere is a different object)").c_str(), fn->line);
    }

    // Track by-ref params (deref on read) and param classes (for member calls).
    _refParams.clear();
    _paramNames.clear();
    _paramDeclKeys.clear();   // LSP index: params are per-function (they outlive every scope)
    // `_localCTypes` belongs on this line and was missing from it — here and at the other three
    // per-body resets (emitDtorDefinition, and emitMethodOrCtorBody's entry and exit). Only the
    // `parallel_for` worker synthesis ever cleared it, so a local's C type outlived its function and
    // leaked into the next one. `lvalueCType` and `receiverScalarCType` consult this map BEFORE the
    // field lookup, so a stale entry shadows a same-named field of a different type in a later body.
    // Latent while nothing read it for a decision; a landmine the moment a type checker does.
    _localTypes.clear(); _localCTypes.clear(); _localTypeNodes.clear();
    _constLocals.clear(); _constLocalVals.clear();
    _moveState.clear();   // per-function move analysis
    _pendingParamDtors.clear();
    _currentClass = nullptr;
    _currentFunc  = name;   // a free function may be a `friend` accessor
    _inUnsafe = fn->isUnsafe;   // `unsafe` is the FUNCTION now — the whole body is the relaxed region
    if (fn->parameters) {
        for (auto& p : *fn->parameters) {
            if (!p->identifier || !p->identifier->value) continue;
            const std::string& pn = *p->identifier->value;
            _paramNames.insert(pn);   // a later local declaration shadowing a param is a compile error
            registerBinding(p->identifier.get(), SymKind::Param);
            if (paramByRef(p.get())) _refParams.insert(pn);
            // An `out` parameter arrives EMPTY — the analysis seeds it as unassigned and the callee is
            // obliged to fill it, so its incoming contents are not a live value. Seed the move state the
            // way a `slot` declaration does, so the first assignment does not emit a dtor for something
            // that was never constructed. (A SECOND assignment still drops: the first one clears this.)
            if (paramIsOut(p.get())) _moveState[pn] = MoveState::Moved;
            if (p->isConst) _constLocals.insert(pn);   // const param is immutable
            std::string pty = p->type ? cType(p->type) : "";
            _localTypes[pn] = (isClass(pty) || isInterface(pty) || isSigType(pty)) ? pty : "";   // record (incl. fnptr params)
            _localCTypes[pn] = pty;                    // full C type (incl. enums/primitives) — e.g. a plain-enum `match` subject
            _localTypeNodes[pn] = p->type;             // kama type node (keeps char vs uint32 for interpolation)
            // a by-value smart-ptr OR owning collection/`string` param is OWNED by the callee — drop it at
            // fn-end (a `ref` param is a borrow — never). The function-root scope is created later
            // (emitBlockScoped); stash it there. Sound because the arg path now forces the caller to
            // `give`/`copy` a named owned collection/string (it can't pass a live-owned one bare).
            if (!paramByRef(p.get()) && (isSmartPtrClass(pty) || ownsByValue(pty))) {
                _pendingParamDtors.push_back({pn, pty});
                if (ownsByValue(pty)) _moveState[pn] = MoveState::NotMoved;   // track move-only / collection / string param
            }
            if (!paramByRef(p.get()) && isViewCType(pty)) _viewParams.insert(pn);   // valid root for a view return
        }
    }

    _currentReturnCType = cType(fn->returnType);
    _tempCounter = 0;
    _scopes.clear();
    _slotLocals.clear(); _slotDeclared.clear();

    line(fn->line);
    // a place-returning `fn ref T f(…)` emits `T* f(…)`; its `return e` addresses the place (the
    // ReturnNode path, gated on `_returnIsPlace`) — same as a `fn ref T` method. The escape check
    // there requires the place to borrow a `ref`/`out` param (a free fn has no `this`), so it can't
    // dangle. `_currentReturnCType` stays the base `T` (the place path never consults it).
    const char* linkage = isExposed(fn) ? "KAMA_EXPORT "
                        : _emitStaticInlineFn ? "static inline " : (nameOverride ? "static " : "");
    *_out << linkage << declAttrPrefix(fn->attributes, fn, fn->line)
          << cType(fn->returnType) << placeRetSuffix(fn->isRef, fn->isConstRef) << " " << name
          << "(" << paramListC(fn->parameters, nullptr) << ")\n";

    _returnIsPlace = fn->isRef;
    _returnIsConstPlace = fn->isConstRef;
    bool prevNoHeap = _noHeapActive;
    if (fnHasNoHeap(fn)) {
        _noHeapActive = true;   // `@noheap`: gate every allocation in this body...
        // ...and register the body, so the transitivity pass can walk out from it once every call edge
        // in the program is known. Registered even when the flag is already on from an enclosing body:
        // the diagnostic should name the function the author actually annotated.
        if (!_probingTemplate) _noHeapFns[name] = NoHeapFn{ demangleForDisplay(name), fn->line, diagFile() };
    } else if (_noHeapProgram && !_probingTemplate) {
        // `--no-heap` seeds the SAME walk with every user body, which is what finally applies the
        // `GlobalAllocator` leaf program-wide. The flag already rejects a direct allocation in any body;
        // what it never reached was the leaf, because that fact is recorded and never rejected, so only
        // the transitive walk can see it — and the walk ran over annotated roots only.
        const std::string disp = demangleForDisplay(name);
        if (isUserBody(declFileOf(name), disp))
            _noHeapFns[name] = NoHeapFn{ disp, fn->line, diagFile(), /*fromFlag=*/true };
    }
    // `@foreignEntry` on the body itself: the declared root for a pointer handed to C by a route no bind
    // can see. Registered like a `@noheap` root; the walk runs once every call edge is known.
    if (!_probingTemplate && hasAttr(fn->attributes, "foreignEntry"))
        _foreignEntryFns[name] = ForeignEntryFn{ demangleForDisplay(name), fn->line, diagFile(), "" };
    // `@onPanic`: a root for the destructor-free walk, and the arming the root block's prologue reads.
    // Restored when this body is done — a nested emission must not inherit the region.
    struct ScopedOnPanic {
        CEmitter& e; bool prevArmed; std::string prevRecover;
        ScopedOnPanic(CEmitter& em) : e(em), prevArmed(em._onPanicArmed), prevRecover(em._onPanicRecover) {}
        ~ScopedOnPanic() { e._onPanicArmed = prevArmed; e._onPanicRecover = prevRecover; }
    } _sop(*this);
    _onPanicArmed = hasAttr(fn->attributes, "onPanic");
    _onPanicRecover.clear();
    if (_onPanicArmed) {
        for (auto& at : *fn->attributes)
            if (at && at->name && *at->name == "onPanic" && at->args && !at->args->empty() && (*at->args)[0])
                _onPanicRecover = emitExpression((*at->args)[0]->expression);
        if (!_probingTemplate) _onPanicFns[name] = OnPanicFn{ demangleForDisplay(name), fn->line, diagFile() };
    }
    if (fn->block) {
        checkDefiniteAssignment(fn->block, fn->parameters);   // owning LOCAL read-before-assign + `out` params (free fn)
        emitBlockScoped(fn->block.get(), 0, /*loopBoundary=*/false, /*functionRoot=*/true);
    } else {
        *_out << "{\n}";
    }
    _noHeapActive = prevNoHeap;
    _returnIsPlace = false;
    *_out << "\n\n";

    _refParams.clear();
    _viewParams.clear();

    if (isEntry) {
        emitRuntimeSlotDefinitions();   // at file scope, before `main`
        // Synthesized portable entry point. Emitted target-agnostically (the emitter has no target
        // knowledge by design): BOTH forms are written behind a preprocessor guard, and the driver's
        // `-DKAMA_TARGET_EMBEDDED` (`--target embedded`) selects the freestanding one — same pattern as
        // KAMA_ISOLATE_LOCAL. Embedded: no argv (there is none on bare metal) and `main` never returns
        // (there's nowhere to return to; a crt0 calls it and expects it to spin). Hosted: argv/argc are
        // stashed via kama_args_init BEFORE kama_main runs, so the prelude floor's args()/program*()/env()
        // can read them (the embedded kama_args_init is a no-op stub — see kama_runtime.h).
        *_out << "#if defined(KAMA_TARGET_EMBEDDED)\n"
             << "int main(void) {\n"
             << "    kama_main();\n"
             << "    for (;;) {}\n"
             << "}\n"
             << "#else\n"
             << "int main(int argc, char** argv) {\n"
             << "    kama_args_init(argc, argv);\n";
        // std::log's `--log` runtime flag: bridge it into the process-global KAMA_LOG env here (main is the one
        // place argv is valid — it is a module-scoped static, not visible to the std::log TU). Only when the
        // program imports std::log (`extern "kama_log.h";`), so non-logging programs stay untouched.
        if (externsHeader("kama_log.h")) {
            *_out << "    kama_log_init_args(argc, argv);\n";
            // The manifest `log` default: seed it into the env AFTER --log (overwrite=0, so flag/env win). M5.
            if (!_logDefault.empty())
                *_out << "    kama_log_set_default(\"" << cEscapeStringBody(_logDefault) << "\");\n";
        }
        *_out << "    return (int)kama_main();\n"
             << "}\n"
             << "#endif\n\n";
    }
}

// ---------------------------------------------------------------------------
// Classes
// ---------------------------------------------------------------------------

void CEmitter::emitStruct(ClassInfo& ci)
{
    if (ci.isScalarEnum()) return;       // a payload-less enum is its integer — `emitEnum` wrote it
    ScopedStr _ts(_thisType, ci.name);   // `This` -> this class while emitting its struct
    // Struct layout is emitted from the HEADER pass, where no module is current and `_sourcePath` is "" in
    // a multi-file build — so a field-level rejection here named no file at all. See diagFile().
    ScopedStr _cu(_collectingUnitPath, ci.declFile);
    // a tagged union — a discriminant tag + a union of per-variant payloads.
    if (ci.isVariant) { emitVariantStruct(ci); return; }
    *_out << "struct " << ci.name << " {\n";
    // Offset-0 invariant: the vptr (root only) or the embedded base comes FIRST.
    bool hasMember = false;
    if (ci.hasVtable && ci.vtableRoot == ci.name) {
        indent(1);
        *_out << "const " << ci.name << "_vtable* __vptr;\n";
        hasMember = true;
    }
    if (ci.base) {
        indent(1);
#if KAMA_INHERITANCE
        *_out << ci.baseName << " __base;\n";
#endif

        hasMember = true;
    }
    for (auto& f : ci.fields) {
        rejectStoredInterface(f.type, "stored in a field", f.type ? f.type->line : (ci.declLine()),
                              /*alsoView=*/true);   // a view can't be a field (would dangle) — but a view's OWN
                                                    // `UnsafePtr<T>`/`int` fields are fine; only view-TYPED fields reject
        indent(1);
        *_out << cType(f.type) << " " << f.name << ";\n";
        hasMember = true;
    }
    if (!hasMember) {
        indent(1);
        *_out << "char __empty; /* C forbids empty structs */\n";
    }
    *_out << "}" << layoutAttrSuffix(ci) << ";\n\n";
}

// `@align(N)` / `@packed` -> the trailing `__attribute__((…))` on a struct definition. Empty when the type
// said nothing, which is every type that does not ask — an un-annotated struct is emitted byte-identically.
//
// A SUFFIX, not the prefix `declAttrPrefix` builds for functions and statics: on a struct definition GCC
// and clang accept the attribute after the closing brace, and putting it before `struct` would attach it
// to the typedef rather than the type on some toolchains.
std::string CEmitter::layoutAttrSuffix(const ClassInfo& ci) const
{
    if (!ci.packed && !ci.alignN) return "";
    std::string s = " __attribute__((";
    if (ci.packed) s += "packed";
    if (ci.alignN) { if (ci.packed) s += ", "; s += "aligned(" + std::to_string(ci.alignN) + ")"; }
    return s + "))";
}

// `struct Name { <tag> tag; union { struct {…} <Variant>; … } u; };` — a discriminated union.
// The tag enum carries symbolic case constants (`Name_Circle`); only payload-carrying variants
// contribute a union member. `: IntType` pins the tag field to a fixed-width integer.
void CEmitter::emitVariantStruct(ClassInfo& ci)
{
    std::string tagTy = ci.tagCType.empty() ? (ci.name + "_Tag") : ci.tagCType;
    // Tag constants: a named `Name_Tag` enum by default, else an anonymous enum (the struct tag
    // field is the pinned integer type, but the constants are still needed for `switch` labels).
    if (ci.tagCType.empty()) *_out << "typedef enum " << ci.name << "_Tag {\n";
    else                     *_out << "enum {\n";
    for (auto& v : ci.variants) { indent(1); *_out << ci.name << "_" << v.name << ",\n"; }
    if (ci.tagCType.empty()) *_out << "} " << ci.name << "_Tag;\n";
    else                     *_out << "};\n";

    *_out << "struct " << ci.name << " {\n";
    indent(1); *_out << tagTy << " tag;\n";
    bool anyPayload = false;
    for (auto& v : ci.variants) if (!v.payload.empty()) { anyPayload = true; break; }
    if (anyPayload) {
        indent(1); *_out << "union {\n";
        for (auto& v : ci.variants) {
            if (v.payload.empty()) continue;
            indent(2); *_out << "struct {\n";
            for (auto& f : v.payload) {
                // A by-value user value/resource payload is legal — the unified struct order
                // lays out the payload type first; a self/mutual by-value cycle is caught (infinite size)
                // by unifiedStructOrder.
                indent(3); *_out << cType(f.type) << " " << f.name << ";\n";
            }
            indent(2); *_out << "} " << v.name << ";\n";
        }
        indent(1); *_out << "} u;\n";
    }
    *_out << "};\n\n";
}

// "(Owner* self, T a, U b)" — the C signature of a vtable slot.
#if KAMA_INHERITANCE
std::string CEmitter::vtableSlotSig(const VSlot& s)
{
    std::string sig = "(" + s.owner + "* self";
    if (s.node && s.node->params) {
        for (auto& p : *s.node->params) {
            std::string nm = (p->identifier && p->identifier->value) ? *p->identifier->value : "";
            sig += ", " + cType(p->type) + (paramByRef(p.get()) ? "* " : " ") + nm;
        }
    }
    return sig + ")";
}
#else
std::string CEmitter::vtableSlotSig(const VSlot&) { return ""; }
#endif

// Vtable struct TYPE — one per root (the class that first introduces a virtual).
// Lists every slot in the hierarchy; fn-ptr self type is pinned to the slot owner.
#if KAMA_INHERITANCE
void CEmitter::emitVtableType(ClassInfo& ci)
{
    auto it = _rootVtables.find(ci.name);
    if (it == _rootVtables.end()) return;
    *_out << "struct " << ci.name << "_vtable {\n";
    for (auto& s : it->second) {
        indent(1);
        *_out << cType(s.node->returnType) << " (*" << s.name << ")" << vtableSlotSig(s) << ";\n";
    }
    // Virtual-destructor slot: destroying a derived through a base handle (`Shared<Base>`
    // owning a `Derived`) dispatches here, so the MOST-DERIVED dtor runs (no slicing). NULL
    // for a non-destructible impl — a base whose derived owns nothing.
    indent(1); *_out << "void (*__dtor)(void*);\n";
    // The most-derived object's LAYOUT, so a base handle returns its block to an allocator with the size and
    // alignment that block was ALLOCATED with — `Allocator.deallocate` promises both. Read by `__vsize`/`__valign`.
    indent(1); *_out << "size_t __size;\n";
    indent(1); *_out << "size_t __align;\n";
    *_out << "};\n\n";
}
#else
void CEmitter::emitVtableType(ClassInfo&) {}
#endif

// The vtable INSTANCE per class with a vtable, filled with the most-derived impl visible to this class
// (designated initializers; missing slots zero). ONE definition, in the class's home module — with
// EXTERNAL linkage, because a generic collection's `_FUNCS` body in the shared header may store this
// address when it moves a polymorphic element by value. Its `extern` declaration is emitted in
// emitHeaderContent, and the two must agree (a `static` definition after a non-static declaration is
// an error), so neither may grow an exclusion the other lacks.
#if KAMA_INHERITANCE
void CEmitter::emitVtableInstance(ClassInfo& ci)
{
    if (!ci.hasVtable) return;
    auto it = _rootVtables.find(ci.vtableRoot);
    if (it == _rootVtables.end()) return;
    *_out << "const " << ci.vtableRoot << "_vtable " << ci.name << "__vtable = {\n";
    for (auto& s : it->second) {
        auto impl = ci.slotImpl.find(s.name);
        if (impl == ci.slotImpl.end()) continue;   // not visible here -> zero
        indent(1);
        // cast the impl (declared with a derived* self) to the slot's owner* signature
        *_out << "." << s.name << " = (" << cType(s.node->returnType) << "(*)"
             << vtableSlotSig(s) << ")&" << impl->second << ",\n";
    }
    // this class's own destructor drives polymorphic drop (`__vdrop`); NULL if it frees nothing.
    if (ci.destructible)
        *_out << "    .__dtor = (void(*)(void*))&" << ci.name << "__dtor,\n";
    *_out << "    .__size = sizeof(" << ci.name << "),\n";
    *_out << "    .__align = _Alignof(" << ci.name << "),\n";
    *_out << "};\n\n";
    // `__vdrop` used to be defined here, in the OWNING MODULE's translation unit, while its `static inline`
    // prototype went into the shared header — so any OTHER unit that dropped a base handle got a static
    // declaration with no definition (`-Wundefined-internal`, and a call to a symbol that cannot exist,
    // since `static` cannot resolve across units). It is now defined in the header next to its prototype;
    // see emitClassPrototypes.
}
#else
void CEmitter::emitVtableInstance(ClassInfo&) {}
#endif

// ---- Interfaces -----------------------------------------------------

// "(void* self, T a, U b)" — an interface slot's C signature (self is type-erased).
std::string CEmitter::ifaceSlotSig(SharedParameterList params)
{
    std::string sig = "(void* self";
    if (params)
        for (auto& p : *params) {
            std::string nm = (p->identifier && p->identifier->value) ? *p->identifier->value : "";
            sig += ", " + cType(p->type) + (paramByRef(p.get()) ? "* " : " ") + nm;
        }
    return sig + ")";
}

// Interface I -> a vtable struct type `I_vtbl` and a fat-pointer value type `I`.
CEmitter::ContractSubst::ContractSubst(CEmitter& e_, const InterfaceInfo& ii)
    : e(e_), savedCtx(e_._nsCtx), savedSubst(e_._typeSubst), active(ii.isGenericInst)
{
    if (!active) return;
    // emit under the USE-SITE ctx (where the instance's type args — e.g. a user `Point` — resolve),
    // falling back to the template's home ctx. Mirrors emitGenericTypeInst's _genericTypeInstCtx.
    e._nsCtx = e._genericContractInstCtx.count(ii.name) ? e._genericContractInstCtx[ii.name]
             : e._genericContractCtx.count(ii.templateKey) ? e._genericContractCtx[ii.templateKey] : e._nsCtx;
    e._typeSubst.clear();
    const std::vector<std::string>& ps = e._genericContractParams[ii.templateKey];
    for (size_t i = 0; i < ps.size() && i < ii.typeArgs.size(); ++i) e._typeSubst[ps[i]] = ii.typeArgs[i];
}
CEmitter::ContractSubst::~ContractSubst()
{
    if (!active) return;
    e._typeSubst = savedSubst;
    e._nsCtx = savedCtx;
}

void CEmitter::emitInterfaceTypes(InterfaceInfo& ii)
{
    // A `@viewable` contract is a MINT PROTOCOL, not a value: it exists so the type being viewed can
    // declare that it is, and a `Viewable<View<T>>` fat pointer is a thing no program can want — boxing
    // one would erase the very type whose identity the grant is about. Emitting nothing is also what keeps
    // the ECS path zero-dispatch: `DynamicArray` gained a conformance, and a conformance that costs a
    // vtable per instantiation would make declaring the relationship expensive enough to avoid.
    if (ii.isViewable) return;
    // No `This` binding here, deliberately: a contract signature can no longer name `This` (it declares a
    // pinned parameter instead), so there is nothing to bind. The binding that used to sit here gave the
    // slot ONE self-type — the contract — while the concrete function behind it had bound the implementing
    // type, and the cast between the two was the unsoundness this campaign removed. Its own comment called
    // the slot "dead for that use but must be valid C"; it is now neither dead nor a cast.
    // The slot TYPES are the contract's own, so render them under the contract's scope — this emission
    // runs in whatever unit first needs the vtbl struct, which is usually not the contract's file and
    // need not import what the contract's signatures name. The site had no reseat at all, so a contract
    // member returning a type declared beside the contract was judged against a THIRD file's imports.
    ScopedContractNs _cns(_nsCtx, _collectingUnitPath, ii);
    ContractSubst _cs(*this, ii);   // bind T->int32 for a generic-contract instance (`Iterator_int32`)
    *_out << "struct " << ii.name << "_vtbl {\n";
    for (auto& m : ii.methods) {
        if (m.isCtor) continue;   // a contract-required `ctor` (HeapOwner::adopt) is not dispatchable — no slot
        indent(1);
        // a place-returning contract method (`fn ref T m()`) is lowered to a `T*`-returning slot
        // (`T const*` for `const ref T`).
        *_out << cType(m.returnType) << placeRetSuffix(m.isPlaceReturn, m.isConstPlace) << " (*" << m.name << ")"
              << ifaceSlotSig(m.params) << ";\n";
    }
    // a virtual-destructor slot so an OWNED interface (`Owned`/`Shared<I>`) can drop its
    // concrete object polymorphically. NULL for a non-destructible impl (drop just frees the obj).
    indent(1); *_out << "void (*__dtor)(void*);\n";
    // The implementer's LAYOUT, so a box releases its object with the size and alignment it was allocated
    // with (`Allocator.deallocate` promises both). A virtual-class implementer may be holding a DERIVED
    // object, so it also points at its `__vsize`/`__valign`, which read the object's own vtable; NULL otherwise.
    indent(1); *_out << "size_t __size;\n";
    indent(1); *_out << "size_t __align;\n";
    indent(1); *_out << "size_t (*__vsize)(void*);\n";
    indent(1); *_out << "size_t (*__valign)(void*);\n";
    // The implementer's C name, for `.as<T>()` — see emitAsDowncast for why a pointer compare alone is wrong.
    if (isPolyDispatchContract(ii.name)) { indent(1); *_out << "const char* __type;\n"; }
    *_out << "};\n";
    *_out << "struct " << ii.name << " { void* obj; const " << ii.name << "_vtbl* vtbl; };\n\n";
}

// For each interface C implements, a static const I_vtbl C__as_I mapping interface
// methods to the class's matching methods (cast to the type-erased slot signature).
void CEmitter::emitClassInterfaceVtables(ClassInfo& ci)
{
    for (auto& ifn : contractsToEmitFor(ci)) {
        // An impl-block conformance dispatches statically (monomorphized) — no fat-pointer vtable.
        // EXCEPTION (Model C): a poly-DISPATCH contract (base `Error`, an enum-implemented contract) DOES
        // get a `<Impl>__as_<C>` vtbl even then, so an enum can be dispatched dynamically + boxed.
        bool staticOnly = contractIsStaticOnlyFor(ci, ifn);
        if (staticOnly && !isPolyDispatchContract(ifn)) continue;
        auto it = _interfaces.find(ifn);
        if (it == _interfaces.end()) { unsupported("unknown contract in implements", ci.declLine()); continue; }
        InterfaceInfo& ii = it->second;
        if (ii.isViewable) continue;   // a mint protocol emits no type, so there is nothing to bind to
        // the slot casts must MATCH the vtbl struct's slot types EXACTLY, so render the contract's method
        // sigs under the CONTRACT's own name-resolution scope (its imports) — not the implementing unit's.
        // A non-generic contract carries that scope in `ii`; a generic-contract instance gets it (with T
        // bound) from ContractSubst below, so only reseat here for the non-generic case.
        ScopedContractNs _cns(_nsCtx, _collectingUnitPath, ii);
        // (No `This` binding — see emitInterfaceTypes. The slot signature and the concrete function now
        //  agree because a pinned parameter substitutes identically on both sides.)
        ContractSubst _cs(*this, ii);   // bind T->int32 so a generic-contract slot's sig matches its vtbl
        if (ci.isScalarRecv) emitScalarSlotThunks(ci, ii, ci.name);   // a payload-less enum's `self` is its integer
        // EXTERNAL linkage (not `static`) + a forward decl in the shared header, so a value can be bound to
        // this contract across module boundaries (e.g. a generic `json::parse<T>`/`toString<T>` in one unit
        // instantiated with a type whose vtable is defined in another). Defined once, in the owning unit.
        // A generic-type INSTANCE (`List<int32>`) is header-inline (`_emitStaticClass`), so ITS vtable is
        // `static` — defined in every TU that includes the header, no extern decl (see the skip above).
        *_out << (_emitStaticClass ? "static const " : "const ")
              << ii.name << "_vtbl " << ci.name << "__as_" << ii.name << " = {\n";
        for (auto& m : ii.methods) {
            ClassInfo* owner = nullptr;
            MethodInfo* mi = findMethod(&ci, m.name, &owner);
            {
            // Every conformance report below is about the IMPLEMENTER — its line comes from `mi->node`
            // or `ci.declLine()`, both of which are in `ci`'s file. `ScopedContractNs` above moved
            // `_collectingUnitPath` to the CONTRACT's file, which is right for rendering the slot
            // signatures under the contract's imports and wrong for these: the pair came out as the
            // contract's file at the implementer's line. Measured on 0.9.180, a contract alone in a
            // 2-line file: "src/proto/shape.kama:5" for a method on line 5 of main.kama.
            // ⚠️ THE RULE: the file must come from whichever declaration the line came from.
            ScopedStr _cu(_collectingUnitPath, ci.declFile);
            if (m.isCtor) {
                // A contract-required `ctor` (M8a, e.g. `HeapOwner::adopt`) is a COMPILE-TIME conformance
                // guarantee, not a runtime slot — construction can't be dispatched on an instance. On a
                // generic monomorph the ctor may be `when`-gated away (Owned's default-alloc `adopt` under a
                // custom `A`) while the TEMPLATE still provides it, so conformance holds. Verify presence
                // (instance OR template) and emit no vtbl slot.
                bool present = mi != nullptr;
                if (!present && _genericTypeInsts.count(ci.name)) {
                    auto ti = _genericTypes.find(_genericTypeInsts[ci.name].templateKey);
                    present = ti != _genericTypes.end() && ti->second.methods.count(m.name);
                }
                if (!present) unsupported(missingContractMethod(ci, ii.name, m.name).c_str(), ci.declLine());
                continue;
            }
            if (!mi) { unsupported(missingContractMethod(ci, ii.name, m.name).c_str(), ci.declLine()); continue; }
            // an interface is a PUBLIC contract — a method that satisfies it must be
            // public too (else it's reachable through the interface but not by name: a leak).
            if (mi->visibility != Visibility::Public)
                unsupported(("method '" + m.name + "' implements contract '" + ii.name
                             + "' and must be declared `public`").c_str(),
                            mi->node ? mi->node->line : ci.declLine());
            // …and constness is part of that public contract. `const fn` on the member promises every
            // caller that a const receiver is enough; dispatch goes through a slot, so the implementation
            // is the only place that promise can be broken. (Only one direction: an impl may be MORE const
            // than the member asks — that widens where it can be called and breaks nothing.)
            if (m.isConst && !mi->isConst)
                unsupported(("method '" + m.name + "' implements contract '" + ii.name
                             + "', which declares it `const fn` — declare it `const fn` here too")
                                .c_str(),
                            mi->node ? mi->node->line : ci.declLine());
            // …and `@noheap` is part of it for exactly the same reason, one the const case only hints at:
            // dispatch goes through a slot, so the implementation is the only place the promise can be
            // broken — and here it is a promise a real-time caller is relying on. Same one direction: an
            // implementation may be `@noheap` when the member does not ask, which constrains only itself.
            if (m.noHeap && !mi->noHeap)
                unsupported(("method '" + m.name + "' implements contract '" + ii.name
                             + "', which declares it `@noheap` — declare it `@noheap` here too, so a "
                               "no-heap caller dispatching through the contract still gets the guarantee")
                                .c_str(),
                            mi->node ? mi->node->line : ci.declLine());
            // Parameter constness is NOT checked here: it is part of the signature, and the signature
            // comparison (`reportSigMismatch`, via checkConformanceSignatures) owns it — in both directions,
            // for every conformance including the static-only ones this vtable path skips, and for
            // overrides. A one-direction copy used to live here and named the contract by its internal
            // instance key; one check, one message.
            }
            indent(1);
            if (ci.isScalarRecv)
                *_out << "." << m.name << " = &" << scalarSlotThunk(ci.name, ii.name, m.name) << ",\n";
            else
                *_out << "." << m.name << " = (" << cType(m.returnType) << placeRetSuffix(m.isPlaceReturn, m.isConstPlace)
                     << "(*)" << ifaceSlotSig(m.params) << ")&" << mi->cName << ",\n";
        }
        // the virtual-destructor slot — the concrete dtor (cast to the erased signature), or NULL when this
        // impl owns nothing to free. A class with a vtable drops through `__vdrop`, and reports its layout through
        // `__vsize`/`__valign`: the box may hold a DERIVED object (upcast from an `Owned<Base>`), whose own
        // destructor must run and whose own size must go back to the allocator.
        indent(1);
#if KAMA_INHERITANCE
        const bool virt = ci.hasVtable;
#else
        const bool virt = false;
#endif
        if (virt)                 *_out << ".__dtor = (void(*)(void*))&" << ci.name << "__vdrop,\n";
        else if (ci.destructible) *_out << ".__dtor = (void(*)(void*))&" << ci.name << "__dtor,\n";
        else                      *_out << ".__dtor = (void(*)(void*))0,\n";
        indent(1); *_out << ".__size = sizeof(" << ci.name << "), .__align = _Alignof(" << ci.name << "),\n";
        if (virt) { indent(1); *_out << ".__vsize = &" << ci.name << "__vsize, .__valign = &" << ci.name << "__valign,\n"; }
        if (isPolyDispatchContract(ii.name)) { indent(1); *_out << ".__type = \"" << ci.name << "\",\n"; }
        *_out << "};\n\n";
    }
}

// (I){ (void*)&(lvalue), &C__as_I } — wrap a concrete class lvalue as interface I.
std::string CEmitter::fatPointer(const std::string& iface, const std::string& concrete, const std::string& lvalue)
{
    return "(" + iface + "){ (void*)&(" + lvalue + "), &" + contractVtblOf(concrete, iface) + " }";
}

// The `C__as_I` symbol for a concrete bound to contract I. A class's is emitted by its own unit's sweep; a
// type-intrinsic target's (`string`) has no unit, so it is demanded here, where it is named.
std::string CEmitter::contractVtblOf(const std::string& concrete, const std::string& iface)
{
    auto it = _classes.find(concrete);
    if (it != _classes.end() && it->second.isIntrinsicColl) return intrinsicContractVtbl(concrete, iface);
    return concrete + "__as_" + iface;
}

// Does a class REACH a contract — declared on itself or on any base? `ci.interfaces` holds only what a
// class declares in its own header, and `emitClassInterfaceVtables` walks the same list, so a derived
// class's vtables come from its own entry while the conformance may have been declared further up.
// Walks `ci->base` for the same reason `findMethod` does.
bool CEmitter::classDeclaresContract(const std::string& cls, const std::string& itf)
{
    auto it = _classes.find(cls);
    if (it == _classes.end()) return false;
    for (ClassInfo* k = &it->second; k; k = k->base)
        for (auto& ifn : k->interfaces) if (ifn == itf) return true;
    return false;
}

// Every contract a class must emit a `C__as_I` vtable for: the ones it declares, PLUS the ones it reaches
// through a base. Both emission sites (the forward decls and the definitions) used to walk `ci.interfaces`
// alone, while the CHECKER accepted a conformance declared further up (that is what `classDeclaresContract`
// is for) — so `Derived d; Contract c = d;` passed analysis and then handed clang a reference to
// `Derived__as_Contract`, which nothing ever defined.
//
// A per-DERIVED vtable rather than reusing the base's, for a reason the layout hides: the `__dtor` slot must
// be the CONCRETE destructor, or dropping the contract handle would slice a derived object. (The methods
// themselves are safe to inherit — a contract member must be `public` and an overridable one must be
// `protected`, so a conformance can never be overridden and the base's implementation is always the right
// one. `__base` sits at offset 0, so the erased `void* self` reaches it unchanged.)
std::vector<std::string> CEmitter::contractsToEmitFor(const ClassInfo& ci) const
{
    std::vector<std::string> out(ci.interfaces.begin(), ci.interfaces.end());
    for (const ClassInfo* k = ci.base; k; k = k->base)
        for (auto& ifn : k->interfaces) {
            bool seen = false;
            for (auto& have : out) if (have == ifn) { seen = true; break; }
            if (!seen) out.push_back(ifn);
        }
    return out;
}

// `staticOnlyInterfaces` is per-class too, so an inherited conformance must be judged against whichever
// class in the chain actually declared it.
bool CEmitter::contractIsStaticOnlyFor(const ClassInfo& ci, const std::string& itf) const
{
    for (const ClassInfo* k = &ci; k; k = k->base) {
        bool declaredHere = false;
        for (auto& ifn : k->interfaces) if (ifn == itf) { declaredHere = true; break; }
        if (!declaredHere) continue;
        for (auto& r : k->staticOnlyInterfaces) if (r == itf) return true;
        return false;
    }
    return false;
}

// Can a value of C type `c` be bound to contract `itf`? This mirrors the four routes the emission
// cascades actually take — a contract value passing through, a class with a vtable, a smart-pointer
// pointee, a widened primitive — and it exists because nothing checked ANY of them.
//
// ⚠️ It answers ONE-SIDED: `false` means "no route, and I am sure", and the callers reject only on that.
// Every uncertainty must read as conforming, because the alternative is rejecting the shapes this
// campaign spent five commits keeping legal — a type parameter, a const-generic binding, an unresolved
// name. That is the same discipline `TKind::Unknown` and `IdFamily::None` keep, for the same reason.
bool CEmitter::valueReachesContract(SharedExpression e, const std::string& c, const std::string& itf)
{
    if (c.empty() || !isInterface(itf)) return true;               // nothing certain to say
    // An existing CONTRACT value passes straight through the cascade. Refinement between two different
    // contracts is a separate, tracked limitation (contract-refinement thunks, ROADMAP §2) — whatever it
    // does today, this rule must not be what newly breaks it.
    if (isInterface(c))                       return true;
    if (classDeclaresContract(c, itf))        return true;
    // `encode(v: sharedRoot)` — a `Shared`/`Owned<T>` whose pointee implements the contract is deref'd
    // and the POINTEE wrapped, so the handle itself never needs the conformance.
    const std::string dt = derefTarget(c);
    if (!dt.empty() && (isInterface(dt) || classDeclaresContract(dt, itf))) return true;
    if (!primWidenKey(e, itf).empty())        return true;         // a primitive that declares it
    // A class the emitter knows nothing about cannot be judged. `isClass` is the test for "this name is a
    // resolved type", so anything failing it is an unresolved spelling and stays silent.
    if (!isClass(c) && !isEnum(c) && primKeyOfCType(c) == c && !cNumBits(c)) return true;
    return false;
}

// A concrete value bound to a contract it does not implement. Until now NOTHING checked this: the
// emitter reached for `<Concrete>__as_<Contract>` and let clang discover that no such vtable exists, or —
// where the value is not a class at all — emitted the raw value into a struct parameter. Both surface as
// a C-level message about a mangled name, on a kama line, which is the shape the 1.0 gate's
// "the diagnostics can be trusted" half exists to remove.
//
// The one diagnostic that DID fire was the local-declaration cascade's fall-through `else`, and it fired
// only for values `exprClass` cannot type — so it caught a plain enum and missed every class. Its wording
// is good and is reused here.
void CEmitter::rejectContractNonConformance(const std::string& itf, SharedExpression value,
                                            const char* what, int line)
{
    if (!value || !isInterface(itf)) return;
    std::string c = exprClass(value);
    if (c.empty()) c = typeOfExpr(value);                          // a plain enum / primitive place
    if (valueReachesContract(value, c, itf)) return;
    const std::string dnote = derivedUnmetNote(c, itf);
    unsupported((std::string(what) + " expects the contract `" + itf + "`, and `" + idTypeName(c)
                 + "` does not implement it"
                 + (dnote.empty() ? std::string(" — a contract value borrows a concrete object that declares "
                                                "the conformance (`implements ") + itf + "`), or a primitive that does"
                                  : dnote)).c_str(), line);
}

// True for a bare C identifier (a local/param) — cheap and side-effect-free to read more than
// once, so it needs no hoisting. Anything with a call/index/member/deref is not "simple".
static bool isSimpleIdent(const std::string& s)
{
    if (s.empty()) return false;
    for (char c : s) if (!(isalnum((unsigned char)c) || c == '_')) return false;
    return true;
}

// s.m(args) where s is an interface value -> (s).vtbl->m((s).obj, <reordered args>).
// A fat-pointer dispatch reads the receiver twice (vtbl + obj), so a non-trivial receiver (a
// bounds-checked index, a call) would run twice — hoist it into one temp (perf + side-effect
// safety). Needs a hoistable statement context; a bare identifier is free to re-read as-is.
std::string CEmitter::emitInterfaceDispatch(const std::string& fatExpr, const std::string& iface,
                                            const std::string& method, SharedArgumentList args, int srcLine,
                                            const std::string& recvCType, const IdentifierNode* site)
{
    auto it = _interfaces.find(iface);
    if (it == _interfaces.end()) { unsupported("dispatch on unknown contract", srcLine); return "0"; }
    std::string recv = fatExpr;
    if (_hoistOK && !isSimpleIdent(fatExpr)) {
        // The receiver's own C type — the plain interface `iface`, or a smart-ptr-of-interface
        // (`Owned/Shared<I>`) when called through a handle; all expose `.obj`/`.vtbl`.
        std::string ty = recvCType.empty() ? iface : recvCType;
        std::string t = "__ifacerecv" + std::to_string(_tempCounter++);
        _hoisted.push_back(ty + " " + t + " = " + fatExpr + ";");
        recv = t;
    }
    for (auto& m : it->second.methods) {
        if (m.name != method) continue;
        recordNodeRef(site, m.nameId.get());   // M6 B3c: a fat-pointer call references the CONTRACT's method
        // The no-heap gate for a contract call. The slot is the blind seam: which implementation runs is a
        // runtime fact, so the proof crosses only where the CONTRACT declared it may. A member that does
        // carry `@noheap` has had every implementation checked against it (see checkConformanceSignatures),
        // so the call is provable and nothing is recorded.
        if (!m.noHeap)
            rejectNoHeapIndirect(("`" + iface + "." + method + "`, a contract member not declared "
                                  "`@noheap`").c_str(), srcLine);
        // A member that IS `@noheap` is proven, so the call carries the marker the call graph reads back
        // out of the C — without it the slot call would be a fact like any other (see buildCallGraph).
        const std::string slot = m.noHeap ? ("KAMA_NOHEAP_SLOT((" + recv + ").vtbl->" + method + ")")
                                          : ("(" + recv + ").vtbl->" + method);
        std::vector<ParamSig> params = paramSigsOf(m.params);
        // A place-returning slot (`fn ref T m()` / `fn const ref T m()`) yields a `T*` / `T const*`; deref it
        // so the call is an lvalue everywhere, exactly as the class and free-function paths do — a contract
        // place call used to come back as a bare pointer, so `x.at(i: 0).value()` fed a `T const*` to a
        // method expecting a `T`.
        return placeWrap(emitReorderedCall(slot, "(" + recv + ").obj",
                                           params, args, srcLine), m.isPlaceReturn);
    }
    unsupported("unknown contract method", srcLine);
    return "0";
}

void CEmitter::emitClassPrototypes(ClassInfo& ci)
{
    if (ci.isIntrinsicColl) return;   // the macro provides these (an extern type's STRUCT is the header's; its members are kama's)
    ScopedStr _ts(_thisType, ci.name);                  // `This` -> this class in method prototypes
    const char* stat = _emitStaticClass ? "static inline " : "";   // specialized instances are header-static inline
    if (ci.destructible)
        *_out << stat << "void " << ci.name << "__dtor(" << ci.name << "* self);\n";
#if KAMA_INHERITANCE
    if (ci.hasVtable) {
        // Virtual drop: read the runtime vtable off the object's vptr and call its `__dtor`. A base handle
        // (`Shared<Base>`) drops through this so a Derived's full chain runs even though the static type is
        // Base. The vptr already names the most-derived vtable (set at construction).
        //
        // DEFINED here, in the shared header, not merely declared. It is reachable from any unit that drops
        // a base handle, and `static inline` without a definition in the calling unit is a dangling
        // reference no linker can satisfy. The body needs only the vtable STRUCT TYPE and the object
        // layout — both complete by this point in the header — and dispatches through the vptr rather
        // than naming the module-local vtable instance, so nothing here is unit-specific.
        // A `@noheap ~T()` is a promise every subclass destructor is held to (checkOverrideSignatures), so
        // the slot is proven and carries the marker the call graph reads; unmarked, dropping a base handle
        // is an allocation fact, because the derived destructor that actually runs may free.
        const bool provenDrop = ci.dtorNode && hasNoHeapAttr(ci.dtorNode->attributes);
        *_out << "static inline void " << ci.name << "__vdrop(" << ci.name << "* self) {\n";
        indent(1); *_out << "const " << ci.vtableRoot << "_vtable* __vt = self->" << vptrPrefix(&ci) << "__vptr;\n";
        indent(1); *_out << "if (__vt && __vt->__dtor) "
                         << (provenDrop ? "KAMA_NOHEAP_SLOT(__vt->__dtor)" : "__vt->__dtor") << "(self);\n";
        *_out << "}\n";
        // `sizeof(ptr: p)` / `alignof(ptr: p)` on a base pointer: the layout of the object it really holds (the
        // vptr names the most-derived vtable). A constructed object's vptr is never null; the fallback covers a
        // zeroed one. They take `void*` so a contract vtable can point at them too (see emitClassInterfaceVtables).
        for (const char* f : {"size", "align"}) {
            const std::string field = f;
            *_out << "static inline size_t " << ci.name << "__v" << field << "(void* obj) {\n";
            indent(1); *_out << "const " << ci.vtableRoot << "_vtable* __vt = ((" << ci.name << "*)obj)->"
                             << vptrPrefix(&ci) << "__vptr;\n";
            indent(1); *_out << "return __vt ? __vt->__" << field << " : "
                             << (field == "size" ? "sizeof(" : "_Alignof(") << ci.name << ");\n";
            *_out << "}\n";
        }
    }
#endif
    const std::string selfC = ci.name + (ci.isScalarRecv ? " self" : "* self");   // a payload-less enum passes its value
    for (auto& kv : ci.methods) {
        MethodInfo& mi = kv.second;
        if (mi.isAbstract) continue;   // pure: no definition, no prototype
        if (mi.isSynthSer) { *_out << stat << cType(mi.returnType) << " " << ci.name << "__serialize(" << selfC << ", Serializer* w);\n"; continue; }   // P4: Result<Unit, Owned<Error>>
        if (mi.isSynthDe)  { *_out << stat << cType(mi.returnType) << " " << ci.name << "__deserialize(Deserializer r);\n"; continue; }   // graph: Shared<T>; by-value: T
        if (mi.isSynthBag) { *_out << stat << bagCtorSig(ci, kv.first) << ";\n"; continue; }   // M6: `V V__of(…)` / `V V__zero(void)`
        if (mi.isSynthFormat) { *_out << stat << "void " << ci.name << "__format(" << selfC << ", Formatter* f);\n"; continue; }   // `@generate(Formattable)`
        if (mi.isSynthCmp) {   // `@generate(Equatable|Hashable)` — keyed by the method name
            if (kv.first == "equals") *_out << stat << "bool " << ci.name << "__equals(" << selfC << ", " << ci.name << "* other);\n";
            else                      *_out << stat << "uint64_t " << ci.name << "__hash(" << selfC << ");\n";
            continue;
        }
        rejectStoredInterface(mi.returnType, "returned from a method",
                              mi.node ? mi.node->line : (ci.declLine()));
        // an operator has no `node`; emit its prototype from `opDecl` (free form: no self).
        SharedParameterList plist = mi.isOperator ? operatorParamList(mi.opDecl->operatorDeclarator.get())
                                                  : mi.node->params;
        // a place-returning `ref T operator[]` returns a `T*` (the place; `T const*` for `const ref T`);
        // everything else by value.
        std::string retC = cType(mi.returnType) + placeRetSuffix(mi.isPlaceReturn, mi.isConstPlace);
        *_out << stat << retC << " " << mi.cName << "("
             << paramListC(plist, mi.isStatic ? nullptr : ci.name.c_str(), ci.name.c_str(),
                           ci.isScalarRecv) << ");\n";   // static/free: no self
    }
    if (ci.isGraphNode)
        emitGraphNodeHelperProtos(ci);   // the node's internal walk helpers (Phase D)
    emitGraphTwinProtos(ci);             // …and a participant's graph-carrying twin
}

// The name of a serde method's own sink parameter — `w` in `serialize(ref Serializer w)`. The call gate
// (`graphSinkIsOurs`) compares against this: a delegate handed THIS sink continues our document, one handed
// any other sink is writing a different one and must not be given our object table.
static std::string serdeSinkParamName(const MethodInfo& mi, bool write)
{
    for (auto& p : mi.params)
        if (p.className == (write ? "Serializer" : "Deserializer")) return p.name;
    return "";
}

// `X__serializeInto` — the graph-carrying twin of a hand-written `serialize`. Declared beside the ordinary
// prototypes so cross-referencing participants link; the 2-arg `X__serialize` keeps its own prototype from
// the loop above, because the `Serializable` vtbl slot casts to that exact shape.
void CEmitter::emitGraphTwinProtos(ClassInfo& ci)
{
    const char* stat = _emitStaticClass ? "static inline " : "";
    if (graphTwinNeeded(ci, /*write=*/true))
        *_out << stat << cType(ci.methods["serialize"].returnType) << " " << ci.name << "__serializeInto("
              << ci.name << "* self, Serializer* w, struct kama_ser_graph* g);\n";
    if (graphTwinNeeded(ci, /*write=*/false)) {
        *_out << stat << cType(ci.methods["deserialize"].returnType) << " " << ci.name << "__deserializeFrom("
              << "Deserializer r, struct kama_de_graph* g);\n";
        if (graphWireElementsNeeded(ci))
            *_out << stat << "void " << ci.name << "__wireParts(" << ci.name
                  << "* self, struct kama_de_graph* g);\n";
        const std::string rootC = graphHandleRootType(ci);
        if (!rootC.empty())
            *_out << stat << rootC << " " << ci.name << "__deserializeRoot(Deserializer r);\n";
    }
    // …and a marked DELEGATE's twin. Unlike `serialize`, whose plain name is taken over by the synthesized
    // root driver, a delegate keeps its OWN 2-arg symbol (a non-graph program calls it) and gains a third
    // parameter in the twin. Declared here so a sibling participant's body can call across.
    for (auto& kv : ci.methods) {
        MethodInfo& mi = kv.second;
        const bool wd = graphDelegateNeeded(ci, mi, /*write=*/true);
        if (!wd && !graphDelegateNeeded(ci, mi, /*write=*/false)) continue;
        *_out << stat << cType(mi.returnType) + placeRetSuffix(mi.isPlaceReturn, mi.isConstPlace) << " "
              << graphDelegateTwinName(mi) << "("
              << paramListC(mi.node->params, mi.isStatic ? nullptr : ci.name.c_str(), ci.name.c_str(),
                            ci.isScalarRecv)
              << (wd ? ", struct kama_ser_graph* g" : ", struct kama_de_graph* g") << ");\n";
    }
}

// void Name__dtor(Name* self): user body first, then destructible fields in
// reverse declaration order. (Early return inside a dtor body is unsupported.)
void CEmitter::emitDtorDefinition(ClassInfo& ci)
{
    line(ci.dtorNode ? ci.dtorNode->line : (ci.declLine()));
    // A destructor is the one member body that does NOT route through emitMethodOrCtorBody, so it needs
    // its own copy of the member-attribute handling — and it is the body that most wants `@noheap`, since
    // a dtor is what runs at the end of a real-time scope. Missing this was invisible: an allocating
    // `@noheap ~R()` simply compiled.
    SharedAttributeList dtorAttrs = ci.dtorNode ? ci.dtorNode->attributes : SharedAttributeList();
    _memberAttrPrefix = declAttrPrefix(dtorAttrs, nullptr,
                                       ci.dtorNode ? ci.dtorNode->line : 0, AttrSite::Member);
    if (hasAttr(dtorAttrs, "onPanic"))
        unsupported("`@onPanic` on a destructor — a drop has no value to recover to; put the region on the "
                    "method that owns and drops the value", ci.dtorNode ? ci.dtorNode->line : 0);
    ScopedNoHeap _nh(_noHeapActive, hasNoHeapAttr(dtorAttrs));
    _currentClass = &ci;
    // A destructor body is a function body, and until the transitivity analysis needed to know WHICH
    // function was being emitted, nothing here had to say so: this path set `_currentClass` and left
    // `_currentFunc` holding the previously-emitted function's name. Harmless for the friend-accessor
    // match it was written for (a dtor is never one), and a silent mis-attribution for anything keyed on
    // it — an allocation in a dtor would have been recorded against whatever body happened to precede it.
    _currentFunc = ci.name + "__dtor";
    if (hasNoHeapAttr(dtorAttrs) && !_probingTemplate)
        _noHeapFns[_currentFunc] = NoHeapFn{ "~" + ci.name, ci.dtorNode ? ci.dtorNode->line : 0, diagFile() };
    else if (_noHeapProgram && !_probingTemplate && isUserBody(ci.declFile, demangleForDisplay(ci.name)))
        _noHeapFns[_currentFunc] = NoHeapFn{ "~" + ci.name, ci.dtorNode ? ci.dtorNode->line : 0,
                                             diagFile(), /*fromFlag=*/true };
    // `unsafe ~Name()` — a raw-handle type frees its buffer in the destructor, so a dtor is markable
    // exactly like any other body.
    _inUnsafe = ci.dtorNode && modHas(ci.dtorNode->modifiers, "unsafe");
    _refParams.clear();
    _paramNames.clear();
    _localTypes.clear(); _localCTypes.clear(); _localTypeNodes.clear();
    _constLocals.clear(); _constLocalVals.clear();
    // Per-BODY analysis state, reset here for the same reason the two paths above reset it: a destructor
    // body is a function body like any other, and inheriting the previously-emitted function's move
    // analysis makes a local's state depend on emission order. It went unnoticed while no destructor
    // happened to reuse a name another body had left moved-from.
    _moveState.clear();
    _slotLocals.clear(); _slotDeclared.clear();
    _currentReturnCType = "void";
    _tempCounter = 0;
    _scopes.clear();
    Scope root; root.isFunctionRoot = true;
    _scopes.push_back(root);

    *_out << (_emitStaticClass ? "static inline " : "") << _memberAttrPrefix
          << "void " << ci.name << "__dtor(" << ci.name << "* self)\n{\n";

    // a discriminated union drops ONLY the active variant's owning payload fields (switch on tag).
    if (ci.isVariant) {
        indent(1); *_out << "switch (self->tag) {\n";
        for (auto& v : ci.variants) {
            bool anyDrop = false;
            for (auto& f : v.payload) {
                auto cit = _classes.find(cType(f.type));
                if (cit != _classes.end() && cit->second.destructible) { anyDrop = true; break; }
            }
            if (!anyDrop) continue;
            indent(2); *_out << "case " << ci.name << "_" << v.name << ":\n";
            for (auto it = v.payload.rbegin(); it != v.payload.rend(); ++it) {   // reverse declaration order
                auto cit = _classes.find(cType(it->type));
                if (cit != _classes.end() && cit->second.destructible) {
                    indent(3);
                    *_out << cit->second.name << "__dtor(&self->u." << v.name << "." << it->name << ");\n";
                }
            }
            indent(3); *_out << "break;\n";
        }
        indent(2); *_out << "default: break;\n";
        indent(1); *_out << "}\n";
        *_out << "}\n\n";
        _scopes.clear();
        _currentClass = nullptr;
        return;
    }

    SharedStatement last;
    if (ci.dtorNode && ci.dtorNode->body && ci.dtorNode->body->statements) {
        for (auto& st : *ci.dtorNode->body->statements) { emitStatement(st, 1); last = st; }
    }
    if (!(last && stmtIsJump(last)))
        emitScopeCleanup(_scopes.back(), 1);

    // Field destructors, reverse declaration order.
    for (auto it = ci.fields.rbegin(); it != ci.fields.rend(); ++it) {
        auto cit = _classes.find(cType(it->type));
        if (cit != _classes.end() && cit->second.destructible) {
            indent(1);
            *_out << cit->second.name << "__dtor(&self->" << it->name << ");\n";
        }
    }
#if KAMA_INHERITANCE
    // Base destructor LAST.
    if (ci.base && ci.base->destructible) {
        indent(1);
        *_out << ci.baseName << "__dtor(&self->__base);\n";
    }
#endif
    *_out << "}\n\n";

    _scopes.clear();
    _currentClass = nullptr;
}

// Emit a method or constructor body with `self`/field/param context set up.
void CEmitter::emitMethodOrCtorBody(const std::string& cName, const char* retType,
                                    SharedParameterList params, SharedBlock body,
                                    ClassInfo& owner, bool isConstMethod, bool isStatic,
                                    bool isUnsafe, const char* memberName, SharedAttributeList attrs)
{
    // `@…` on a member. Validated and lowered HERE, not at each of the five call sites, for the reason
    // the no-heap gate below makes concrete: a check duplicated per site fails OPEN when one site is
    // missed, and a missed `@noheap` reads exactly like a body that legitimately allocates nothing.
    // `_memberAttrPrefix` is consumed by the signature line further down.
    _memberAttrPrefix = declAttrPrefix(attrs, nullptr, body ? body->line : 0, AttrSite::Member);
    // `@noheap` on a method/ctor/dtor/operator, with the same save/set/restore shape emitFunction uses
    // for a free `fn` — the flag is inherited, never cleared, so an inner emission cannot silently
    // escape an enclosing no-heap region.
    ScopedNoHeap _nh(_noHeapActive, hasNoHeapAttr(attrs));
    _currentClass = &owner;
    _currentFunc  = cName;   // a method may be a `Class::method` friend accessor
    // Register an annotated member for the transitivity pass, exactly as emitFunction does for a free fn.
    if (hasNoHeapAttr(attrs) && !_probingTemplate)
        _noHeapFns[cName] = NoHeapFn{ demangleForDisplay(cName), body ? body->line : 0, diagFile() };
    // ...and the `--no-heap` seeding, judged by the OWNER's file. `declFileOf` is keyed by the tables a
    // top-level name lives in, and a method's mangled `Class__method` is in none of them — it would
    // answer "" for every member and quietly seed nothing. The class is what was collected from a file.
    else if (_noHeapProgram && !_probingTemplate && isUserBody(owner.declFile, demangleForDisplay(cName)))
        _noHeapFns[cName] = NoHeapFn{ demangleForDisplay(cName), body ? body->line : 0,
                                      diagFile(), /*fromFlag=*/true };

    if (hasAttr(attrs, "foreignEntry") && !_probingTemplate)   // a `@foreignEntry` member is a root too
        _foreignEntryFns[cName] = ForeignEntryFn{ demangleForDisplay(cName), body ? body->line : 0, diagFile(), "" };
    // `@onPanic` on a method: the same arming emitFunction does (restored when this body is done).
    struct ScopedOnPanic {
        CEmitter& e; bool prevArmed; std::string prevRecover;
        ScopedOnPanic(CEmitter& em) : e(em), prevArmed(em._onPanicArmed), prevRecover(em._onPanicRecover) {}
        ~ScopedOnPanic() { e._onPanicArmed = prevArmed; e._onPanicRecover = prevRecover; }
    } _sop(*this);
    _onPanicArmed = hasAttr(attrs, "onPanic");
    _onPanicRecover.clear();
    if (_onPanicArmed) {
        if (std::string(retType) == owner.name || cName.find("__ctor") != std::string::npos)
            unsupported("`@onPanic` on a constructor — a recovered panic would hand back a half-built "
                        "object; put the region on the method that constructs and calls it", body ? body->line : 0);
        for (auto& at : *attrs)
            if (at && at->name && *at->name == "onPanic" && at->args && !at->args->empty() && (*at->args)[0])
                _onPanicRecover = emitExpression((*at->args)[0]->expression);
        if (!_probingTemplate) _onPanicFns[cName] = OnPanicFn{ demangleForDisplay(cName), body ? body->line : 0, diagFile() };
    }

    // THE ALLOCATION LEAF, and the one piece of by-name knowledge the analysis needs. Every chain ends at
    // an `extern fn`, which has no body and so cannot be analysed — and `GlobalAllocator.allocate` is the
    // one that ends at libc `malloc`. Without this, propagation would prove only that a `@noheap` fn
    // reaches no `new`, and `list.add(x)` in an audio callback — the canonical real-time bug — would keep
    // compiling clean, because a container does not allocate with `new`: it goes through its `A: Allocator`.
    //
    // Naming it here rather than inventing a `@heap` attribute is deliberate on two counts. The compiler
    // already privileges this exact type (it is the default `A` for `Owned<T, A>` and for every container),
    // so this adds no surface a reader has to learn. And it needs no annotation ANYWHERE to be precise:
    // `A` is a type parameter, so `DynamicArray<T, BumpAllocator>.add` is a different monomorph reaching a
    // different `allocate`, and an arena-backed container stays legal inside a `@noheap` region while the
    // heap-backed one does not. That is the idiom real-time code actually uses, and it falls out for free.
    //
    // Recorded, never rejected here. Routing it through `rejectIfNoHeap` would fire while the PRELUDE's own
    // body is being emitted, so every `--no-heap` build would fail pointing at a line in the prelude that
    // the author did not write. The fact belongs to the analysis; the diagnostic belongs at the call.
    //
    // Only while the program declares no `@globalAllocator`. With one, `GlobalAllocator` is a handle onto the pool,
    // and its body's `kama_alloc` call is an edge into it like any other funnel use (buildCallGraph).
    if (!_probingTemplate && _globalAllocator.empty() && owner.name == "GlobalAllocator" && memberName
        && (std::string(memberName) == "allocate" || std::string(memberName) == "deallocate")
        && !_allocSites.count(cName))
        // No file/line, and this is now a CHOICE rather than a defence. It was written when a position
        // taken here would have been a lie — the header pass named no unit, so `diagFile()` fell through
        // to the file being compiled and pointed the reader at an innocent line of their own program.
        // That is fixed (0.9.179: the header pass installs its owner), so an honest `<prelude>` position
        // is available. It is still not taken: this position renders INSIDE the message text, on a
        // sentence whose chain already ends at `GlobalAllocator::allocate`, and a prelude line the author
        // cannot act on adds nothing to it. Keep the behaviour; do not restore the old reason for it.
        _allocSites[cName] = AllocSite{ "a container or box drawing from `GlobalAllocator`, which is the "
                                        "system heap", 0, std::string() };
    _inStaticMethod = isStatic;   // a static body has no `self`/`this`
    _inUnsafe = isUnsafe;         // `unsafe` is the FUNCTION now — the whole body is the relaxed region
    // THE MINT GRANT. A `type view`'s ctor is private (see collectClasses), so the one way an outside type
    // may build one is by declaring that it IS the type being viewed — which it does by implementing a
    // member of a `@viewable` contract. This body may then mint the view it returns, and only that one:
    // the return type self-selects, which is why marking a whole contract cannot over-grant.
    //
    // Computed once here rather than at each mint site, because the question is a property of the ENCLOSING
    // METHOD, and a per-site lookup would have to re-derive the member name from the mangled C name.
    _mintGrant.clear();
    if (retType && memberName && *memberName && isViewCType(retType))
        for (auto& base : owner.interfaces) {
            auto it = _interfaces.find(base);
            if (it == _interfaces.end() || !it->second.isViewable) continue;
            for (auto& m : it->second.methods)
                if (!m.isCtor && m.name == memberName) { _mintGrant = retType; break; }
            if (!_mintGrant.empty()) break;
        }
    // A named `ctor` is emitted as a static factory (no `self` PARAMETER), but it does have a `this`: the
    // value it is building. Storage for it is synthesized below, so `this` must resolve here even though
    // the C signature is static.
    bool ctorBody = _inNamedCtorBody;
    if (ctorBody) _inStaticMethod = false;
    _ctorSelfUsed = false;
    _refParams.clear();
    _paramNames.clear();
    _paramDeclKeys.clear();   // LSP index: params are per-function (they outlive every scope)
    _viewParams.clear();
    _localTypes.clear(); _localCTypes.clear(); _localTypeNodes.clear();
    _constLocals.clear(); _constLocalVals.clear();
    _moveState.clear();   // per-method move analysis
    if (isConstMethod) _constLocals.insert("this");   // `this` is immutable (deep)
    _currentReturnCType = retType;
    _tempCounter = 0;
    _scopes.clear();
    _slotLocals.clear(); _slotDeclared.clear();
    Scope root; root.isFunctionRoot = true;
    _scopes.push_back(root);
    if (params) {
        for (auto& p : *params) {
            if (!p->identifier || !p->identifier->value) continue;
            const std::string& pn = *p->identifier->value;
            _paramNames.insert(pn);   // a later local declaration shadowing a param is a compile error
            registerBinding(p->identifier.get(), SymKind::Param);
            if (paramByRef(p.get())) _refParams.insert(pn);
            // An `out` parameter arrives EMPTY — the analysis seeds it as unassigned and the callee is
            // obliged to fill it, so its incoming contents are not a live value. Seed the move state the
            // way a `slot` declaration does, so the first assignment does not emit a dtor for something
            // that was never constructed. (A SECOND assignment still drops: the first one clears this.)
            if (paramIsOut(p.get())) _moveState[pn] = MoveState::Moved;
            if (p->isConst) _constLocals.insert(pn);   // const param is immutable
            std::string pty = p->type ? cType(p->type) : "";
            _localTypes[pn] = (isClass(pty) || isInterface(pty) || isSigType(pty)) ? pty : "";   // record (incl. fnptr params)
            _localCTypes[pn] = pty;                    // full C type (incl. enums/primitives) — e.g. a plain-enum `match` subject
            _localTypeNodes[pn] = p->type;             // kama type node (keeps char vs uint32 for interpolation)
            // a by-value smart-ptr OR owning collection/`string` param is owned by the callee — drop it at
            // fn-end (a `ref` is a borrow — never). The root scope is already on the stack, so record it
            // directly (dropped last). recordDestructibleLocal also move-tracks an ownsByValue param.
            if (!paramByRef(p.get()) && (isSmartPtrClass(pty) || ownsByValue(pty))) recordDestructibleLocal(pn, pty);
            if (!paramByRef(p.get()) && isViewCType(pty)) _viewParams.insert(pn);   // valid root for a view return
        }
    }

    // The graph parameter, when this is a serde TWIN — see _serGraphArg. It is appended rather than
    // declared because it has no kama parameter to correspond to: the kama signature is the contract's.
    std::string gp;
    if (!_serGraphArg.empty()) gp = ", struct kama_ser_graph* " + _serGraphArg;
    else if (!_deGraphArg.empty()) gp = ", struct kama_de_graph* " + _deGraphArg;
    *_out << (_emitStaticClass ? "static inline " : "") << _memberAttrPrefix << retType << " " << cName
          << "(" << paramListC(params, isStatic ? nullptr : owner.name.c_str(), owner.name.c_str(),
                               owner.isScalarRecv) << gp << ")\n{\n";   // static: no self
    emitOnPanicPrologue(1);   // a `@onPanic` method arms itself first thing (no-op otherwise)

    checkDefiniteAssignment(body, params);   // owning LOCAL read-before-assign + `out` params (any method/ctor)

    // The ctor's implicit `this`. Same lowering as a bare class local — zero-init, field-default fill,
    // vptr store — applied to storage the function synthesizes, with `self` pointing at it so every
    // existing `this` path (`self->field`, `self` as a receiver) works unchanged.
    //
    // Emitted to a buffer BEFORE the body, because the fill SEEDS MOVE STATE (a move-only field is marked
    // Moved so the first `this.f = give …` does not drop the zeroed slot) and the body needs that seeding
    // already in place. It is written out only if the body actually names `this`: the fill can CALL a
    // field's `default` ctor, so emitting it for a ctor that never names `this` would construct a whole
    // object for nothing. During coexistence most ctors still build a `slot` local and want none of it.
    // A derived ctor's FIRST statement installs its base (`this.base = Base.<ctor>(…);`). It is lifted
    // out of the body and into the fill, because that is where it has to happen: before the field
    // defaults, and before the vptr store that must overwrite whatever vtable the base wrote.
    SharedExpression baseInit;
#if KAMA_INHERITANCE
    if (ctorBody && body && body->statements && !body->statements->empty())
        baseInit = baseInstallOf(body->statements->front());
    // At KAMA_INHERITANCE=0 the statement is deliberately NOT consumed here: leaving it in the body lets it
    // reach `rejectBaseMember`, so `this.base` answers with the build's own gate diagnostic like every
    // other inheritance surface, rather than being silently dropped.
#endif

    std::ostringstream ctorPrologue;
    if (ctorBody) {
        std::ostream* sv = _out; _out = &ctorPrologue;
        int ln = body ? body->line : 0;
        indent(1); *_out << owner.name << " __self = {0};\n";
        emitAggregateFill("__self", owner.name, ln, 1, "this", baseInit);
        indent(1); *_out << owner.name << "* self = &__self;\n";
        _out = sv;
        _ctorSelfUsed = false;   // a field initializer naming another field must not count as a use
        // The storage EXISTS the moment a base is installed into it, even if the body never says `this`
        // again — otherwise the prologue (and with it the install) is discarded at the flush below.
        if (baseInit) _ctorSelfUsed = true;
    }

    std::ostringstream ctorStmts;
    std::ostream* savedOut = _out;
    if (ctorBody) _out = &ctorStmts;

    SharedStatement last;
    if (body && body->statements) {
        bool skipFirst = (baseInit != nullptr);   // already emitted, as part of the fill
        for (auto& st : *body->statements) {
            if (skipFirst) { skipFirst = false; last = st; continue; }
            emitStatement(st, 1); last = st;
        }
    }
    bool fellOffEnd = !(last && stmtIsJump(last));
    if (fellOffEnd) {
        emitScopeCleanup(_scopes.back(), 1);
        // Falling off the end of a ctor RETURNS the value it built. A ctor's whole job is to produce that
        // value before it returns, so it need spell no return — exactly as a `void` function need spell
        // none. `return give this;` stays legal as the EARLY-return form, not a second way to say this.
        if (ctorBody) {
            indent(1);
            if (_currentReturnCType == owner.name)
                *_out << "return __self;\n";
            else
                // A fallible ctor is not a special case: it spells its `Err` returns and nothing else, so
                // falling off the end is the `Ok`. Saying so here is what keeps a missing `Ok` from
                // reading as an omission.
                *_out << "return (" << _currentReturnCType << "){ .tag = " << _currentReturnCType
                      << "_Ok, .u.Ok = { .value = __self } };\n";
        }
    }
    if (ctorBody) {
        _out = savedOut;
        // The storage is needed when the body NAMES `this`, and also when the ctor falls off the end —
        // there the value is returned without ever being mentioned (`default ctor empty() { }`, whose
        // every field is default-fillable, is exactly that shape).
        if (_ctorSelfUsed || fellOffEnd) *_out << ctorPrologue.str();
        *_out << ctorStmts.str();
    }
    *_out << "}\n\n";

    _scopes.clear();
    _currentClass = nullptr;
    _refParams.clear();
    _localTypes.clear(); _localCTypes.clear(); _localTypeNodes.clear();
    _constLocals.clear(); _constLocalVals.clear();
    _inStaticMethod = false;
}

void CEmitter::emitClassDefinitions(ClassInfo& ci)
{
    if (ci.isIntrinsicColl) return;   // the macro provides these (an extern type's members are kama's — see emitClassPrototypes)
    ScopedStr _ts(_thisType, ci.name);                  // `This` -> this class in method bodies/sigs
    for (auto& kv : ci.methods) {
        MethodInfo& mi = kv.second;
        if (mi.isAbstract) continue;   // pure: no body to emit
        // Every `@generate` body, through the one fork that knows a variant from a class — which is how a
        // GENERIC ENUM instance gets its per-tag bodies, since its instance comes through here like any
        // other (emitGenericTypeInst phase 2).
        if (mi.isSynthSer || mi.isSynthDe || mi.isSynthBag || mi.isSynthFormat || mi.isSynthCmp) {
            emitSynthBody(ci, kv.first, mi);
            continue;
        }
        // an operator has no `node`; emit its body from `opDecl` (free form: no self).
        if (mi.isOperator) {
            auto* d = mi.opDecl->operatorDeclarator.get();
            line(mi.opDecl->line);
            // a place-returning `ref T operator[]` emits `T* Class__op_index(Class* self, …)`; its
            // `return e` addresses the place (see the ReturnNode path, gated on `_returnIsPlace`).
            std::string ret = cType(mi.returnType) + placeRetSuffix(mi.isPlaceReturn, mi.isConstPlace);
            _returnIsPlace = mi.isPlaceReturn;
            _returnIsConstPlace = mi.isConstPlace;
            emitMethodOrCtorBody(mi.cName, ret.c_str(), operatorParamList(d), mi.opDecl->body, ci, false,
                                 mi.arity == 2, mi.isUnsafe, nullptr, mi.opDecl->attributes);
            _returnIsPlace = false;
            _returnIsConstPlace = false;
            continue;
        }
        line(mi.node->line);
        // a place-returning `fn ref T m(…)` emits `T* Class__m(Class* self, …)`; its `return e`
        // addresses the place (the ReturnNode path, gated on `_returnIsPlace`) — same as `operator[]`.
        std::string ret = cType(mi.returnType) + placeRetSuffix(mi.isPlaceReturn, mi.isConstPlace);
        _returnIsPlace = mi.isPlaceReturn;
        _returnIsConstPlace = mi.isConstPlace;
        // Construction-model M3: a named `ctor` is a static factory — seal it so no returned object leaks a
        // null owning pointer. It is the only ctor shape there is, so this is the only such seal.
        if (mi.isCtor) checkNamedCtorComplete(ci, mi.node->body);
        // ...and, for a derived type, that it installed its base — the inherited half of the same seal.
        if (mi.isCtor) checkBaseInstall(ci, mi.node->body, mi.node->line);
        // ...and a view ctor may only hand back a borrow of its params (not a ctor-local) — see the fn-shaped
        // sibling at the ReturnNode, skipped for a ctor body (which is validated here instead).
        if (mi.isCtor && isViewCType(ret)) checkViewCtorEscape(ci, mi.node);
        // A named `ctor` is a static factory (no `self`), so it can't pass isCtor=true (that emits a
        // `self->__vptr` store). But it DOES construct — its bare local of the return type is the object
        // being built, so const fields written on it (`r.id = id`) must be allowed. Flag it. #M8d.2
        _inNamedCtorBody = mi.isCtor;
        // A participant's hand-written `serialize` becomes the TWIN — the body is emitted once, under the
        // name that carries the graph — and `X__serialize` is then synthesized as the root driver below.
        // Emitting it under its own name as well would leave a second, callable, WRONG symbol: the same
        // body with no graph writes each pointee inline, losing identity and looping on a cycle.
        const bool wtwin = (kv.first == "serialize"   && graphTwinNeeded(ci, /*write=*/true));
        const bool rtwin = (kv.first == "deserialize" && graphTwinNeeded(ci, /*write=*/false));
        {
            ScopedStr _gp(_serGraphArg, wtwin ? "g" : "");
            ScopedStr _gq(_deGraphArg,  rtwin ? "g" : "");
            ScopedStr _gs(_serGraphSink, wtwin ? serdeSinkParamName(mi, true)  : "");
            ScopedStr _gt(_deGraphSink,  rtwin ? serdeSinkParamName(mi, false) : "");
            emitMethodOrCtorBody(wtwin ? ci.name + "__serializeInto"
                                       : rtwin ? ci.name + "__deserializeFrom" : mi.cName,
                                 ret.c_str(), mi.node->params, mi.node->body, ci, mi.isConst, mi.isStatic,
                                 mi.isUnsafe, kv.first.c_str(), mi.node->attributes);
        }
        // A marked DELEGATE gets a SECOND body, under the twin name, with the table live. Both are needed
        // and neither is dead: the plain one is what a non-graph program calls (the same container
        // serialized with no `Shared` in sight), the twin is what a graph copy routes to. `serialize` above
        // is the case that does NOT double up — its plain name is taken over by the synthesized root
        // driver, so emitting the author's body under it too would leave a second, callable, WRONG symbol.
        const bool wdel = graphDelegateNeeded(ci, mi, /*write=*/true);
        const bool rdel = graphDelegateNeeded(ci, mi, /*write=*/false);
        if (wdel || rdel) {
            line(mi.node->line);
            ScopedStr _gp(_serGraphArg, wdel ? "g" : "");
            ScopedStr _gq(_deGraphArg,  rdel ? "g" : "");
            ScopedStr _gs(_serGraphSink, wdel ? serdeSinkParamName(mi, true)  : "");
            ScopedStr _gt(_deGraphSink,  rdel ? serdeSinkParamName(mi, false) : "");
            emitMethodOrCtorBody(graphDelegateTwinName(mi), ret.c_str(), mi.node->params, mi.node->body, ci,
                                 mi.isConst, mi.isStatic, mi.isUnsafe, kv.first.c_str(),
                                 mi.node->attributes);
        }
        _inNamedCtorBody = false;
        _returnIsPlace = false;
    }
    // The root driver over the twin. WHICH driver is decided by identity: a NODE can be pointed at, so it
    // belongs in the table and its `root` slot is an id (and a cycle through it closes); a participant
    // cannot, so its root carries its value inline. Same fork on the way back in.
    if (graphTwinNeeded(ci, /*write=*/true)) {
        if (ci.isGraphNode) emitGraphSerializeDefinition(ci); else emitGraphRootDriver(ci);
    }
    if (graphTwinNeeded(ci, /*write=*/false)) {
        emitGraphWireElements(ci);
        // A hand-written NODE's own `deserialize` keeps the author's by-value signature — it is what fills
        // a shell — so the handle root is a SEPARATE synthesized entry point rather than a retarget of it.
        if (ci.isGraphNode) emitGraphHandleRootReader(ci); else emitGraphReadRootDriver(ci);
    }
    if (ci.destructible)
        emitDtorDefinition(ci);
    if (ci.isGraphNode) {
        emitGraphNodeHelpers(ci);   // visitEdges / writeNode / wireEdges
        emitGraphReadInto(ci);      // `K____readInto`: pass 1, shared by the shell reader and by nesting
    }
}

// ---- By-value (tree) serialization intrinsic (Phase C) --------------------
// Direct C emission of `serialize`/`deserialize` for a `@generate` product (value/tree) type, replacing
// the generated-kama path. Reproduces the exact JSON wire the old synthesis produced. Delegation: a
// scalar/string writes/reads via the Serializer/Deserializer contract directly; a nested struct / enum /
// collection field calls its own `<CType>__serialize`/`__deserialize` (emitted per-instance elsewhere);
// `Optional<E>` is inlined. (`Fixed<T,N>` is unused by any `@generate` type today — deferred.)

// A `kama_string_lit("…", n)` for a wire name (same escaping the StringNode lowering uses).
static std::string kamaStrLit(const std::string& s)
{
    std::ostringstream os;
    os << "kama_string_lit(\"";
    for (char c : s)
        switch (c) {
            case '\\': os << "\\\\"; break;  case '"': os << "\\\""; break;
            case '\n': os << "\\n";  break;  case '\t': os << "\\t"; break;
            case '\r': os << "\\r";  break;  default:  os << c;      break;
        }
    os << "\", " << s.size() << ")";
    return os.str();
}

// The Serializer/Deserializer scalar method suffix for a builtin ("I32"/"U8"/"F64"/"Bool"/"Char"), "" otherwise.
static const char* serScalarSuffix(int builtInVal)
{
    switch (builtInVal) {
        case IDENTIFIER_INT8_VAL:    return "I8";
        case IDENTIFIER_INT16_VAL:   return "I16";
        case IDENTIFIER_INT32_VAL:   return "I32";
        case IDENTIFIER_INT64_VAL:   return "I64";
        case IDENTIFIER_UINT8_VAL:   return "U8";
        case IDENTIFIER_UINT16_VAL:  return "U16";
        case IDENTIFIER_UINT32_VAL:  return "U32";
        case IDENTIFIER_UINT64_VAL:  return "U64";
        case IDENTIFIER_FLOAT32_VAL: return "F32";
        case IDENTIFIER_FLOAT64_VAL: return "F64";
        case IDENTIFIER_BOOL_VAL:    return "Bool";
        case IDENTIFIER_CHAR_VAL:    return "Char";
        default:                     return "";
    }
}

// Emit the write for one field value (`access`) into the Serializer `w` (a `Serializer*`).
// Emit the write of one field to the Serializer `w`. `resultCType` is the enclosing serialize's
// `Result<Unit, Owned<Error>>` C type; on a composite Err it returns the forwarded box (self is borrowed —
// nothing partial to drop, unlike the read side). Empty `resultCType` = graph-node/void context: the sticky
// flag carries the failure to the graph boundary, so just drop the redundant box (leak-clean).
// A PRIMITIVE field with no serde conformance has nothing to call, and the generator used to emit the
// call anyway — `isize__serialize(...)` against a function that is never defined — so `@generate(Serializable)`
// over an `isize` field produced a clean kama build and an implicit-declaration error from the C compiler.
// Zero kama diagnostics for a defect kama can see. Everything non-primitive falls through as before: a
// user type / enum / collection legitimately reaches its own generated `__serialize`.
//
// `isize`/`usize` and C's `long`/`unsigned long` (`clong`/`culong`, 0.9.232) are the only primitives this
// fires for, and deliberately so — see the note above the `Serializable` block in prelude/global.kama. A
// platform-varying width has no wire format, whichever axis it varies on.
// The FIELD a serde diagnostic is about: the one the per-field loop is emitting (`_serdeField`). It used to
// be recovered from the emitted access path, which names a field only in the simplest shape — an `Optional`
// or `Owned` field is read through a temp and written through `.u.Some.value` / a deref call, and an enum
// payload is read into a `__p_` local, so the refusals said `__ov0`, `value`, `boxed)))` and `__p_w` (KR-15).
// The path stays as the fallback for a walk that is not over a field (a container's elements).
std::string CEmitter::serdeFieldName(const std::string& access)
{
    if (!_serdeField.empty()) return _serdeField;
    std::string f = access;
    size_t dot = f.find_last_of(".>");
    if (dot != std::string::npos) f = f.substr(dot + 1);
    while (!f.empty() && (f.back() == ')' || f.back() == ' ')) f.pop_back();
    return f;
}

bool CEmitter::serdeRejectsPrimitive(SharedIdentifier ty, const std::string& access, bool writing, int line)
{
    if (!ty || ty->genericArg) return false;              // a generic instance is composite — not ours
    if (ty->builtInVal == IDENTIFIER_NONE_VAL) return false;   // a user type: it has its own serialize
    if (ty->builtInVal == IDENTIFIER_STRING_VAL) return false; // handled directly by the caller
    if (*serScalarSuffix(ty->builtInVal)) return false;        // has a wire form

    const std::string field = serdeFieldName(access);
    const std::string kt = primKey(ty);
    unsupported(("field `" + field + "` is an `" + kt + "`, which cannot be "
                 + (writing ? "serialized" : "deserialized")
                 + " — `" + kt + "` is a platform-varying width (`" + cType(ty)
                 + (kt == "clong" || kt == "culong" ? "`: 4 bytes on Windows, 8 elsewhere)" : "`: 8 bytes natively, 4 on wasm32)")
                 + ", so it has no wire format and implements neither "
                   "`Serializable` nor `Deserializable`. Give the field a fixed width (`int64`/`uint64`) and "
                   "`cast` at the boundary, or mark it `@skip`").c_str(), line);
    return true;
}

// A COMPOSITE field whose type has no `serialize`/`deserialize` to call. The generator emitted the call
// regardless — `Color__serialize(&(self->c), w)` against a function nothing defines — so a
// `@generate(Serializable)` type with a plain-enum or an un-marked user-type field produced a clean kama
// build and an implicit-declaration error from the C compiler. Zero kama diagnostics for a defect kama can
// see, which is the same hole `serdeRejectsPrimitive` above closed for `isize` and `clong`.
//
// The test is the SYMBOL, not the bound: what the next line emits is `<cType>__serialize`, and that exists
// exactly when the type carries the method. A conditional collection conformance (`when [T: Serializable]`)
// is therefore answered correctly without reasoning about the gate — the instance either got the method or
// it did not. Reached only after the string/scalar/`Optional` arms have had their say.
bool CEmitter::serdeRejectsField(SharedIdentifier ty, const std::string& access, bool writing)
{
    const std::string ct = cType(ty);
    const char* which = writing ? "serialize" : "deserialize";
    auto it = _classes.find(ct);
    if (it != _classes.end() && it->second.methods.count(which)) return false;
    // An opaque type parameter inside a generic body: nothing is known about it here, and a wrong guess
    // would report a defect at a type that is never instantiated. Same silence as the cast rules.
    if (opaqueScalarUnknown(ct)) return false;

    const std::string field = serdeFieldName(access);
    const std::string disp = (ty && ty->value) ? *ty->value : demangleForDisplay(ct);
    const char* contract = writing ? "Serializable" : "Deserializable";
    unsupported(("field `" + field + "` has type `" + disp + "`, which cannot be "
                 + (writing ? "serialized" : "deserialized") + " — a composite field is written through "
                   "its OWN `" + which + "`, and `" + disp + "` has none. Give it `@generate("
                 + contract + ")`, write `implements " + contract + "` for it, or leave the field out of "
                   "the wire form with `@skip`").c_str(), ty ? ty->line : 0);
    return true;
}

// An `Owned<T, A>` on the wire IS a `T`: nothing else can point at a unique pointee, so writing it as an
// id into the object table bought nothing and forced every hierarchy that merely OWNED its children into
// graph mode. It is written inline, byte-identical to a by-value `T` field — which also means a field may
// change between `Owned<T>` and bare `T` and still read data written by the other.
//
// ⚠️ Recognised BY IDENTITY here, and deliberately NOT by a `serialize`/`deserialize` on `Owned` itself
// (which is where it lived at 0.9.268). The triad AUTO-DEREFS, so any domain method on it shadows the
// pointee's: `this.o.serialize(w)` bound `Owned_T__serialize` while `this.s.serialize(w)` bound
// `T__serialize(Shared_T__deref(&self->s))` — two spellings of one line meaning different things, and the
// outputs agreed only by accident. The triad stays method-free; the compiler knows these three types.
//
// The erased `Owned<Contract>` (an intrinsic `{obj, vtbl}`, not a library instance) is deliberately NOT
// covered — the conformance this replaces did not cover it either, so the scope is unchanged.
SharedIdentifier CEmitter::ownedPointeeOf(SharedIdentifier ty)
{
    if (!ty || !ty->genericArg) return nullptr;
    auto g = _genericTypeInstOf.find(cType(ty));
    if (g == _genericTypeInstOf.end() || g->second != _ownedTmpl) return nullptr;
    return ty->genericArg;
}

void CEmitter::emitSerFieldWrite(SharedIdentifier ty, const std::string& access, int depth,
                                 const std::string& resultCType)
{
    // ⚠️ A generic INSTANCE's field node is still the TEMPLATE's `T`, so `ty->builtInVal` reads NONE for
    // what is really an `int32` and every scalar arm below would be skipped — the field would take the
    // composite path and emit a call to `int32_t__serialize`, which nothing defines. `cType` hops
    // `_typeSubst` on its own; the NODE has to be substituted explicitly. Returns `ty` unchanged when
    // nothing is bound, so this costs a non-generic type one map check.
    ty = deepSubstType(ty);
    if (ty && ty->value && *ty->value == "Optional" && ty->genericArg) {   // Some -> inner value, None -> null
        std::string oc = cType(ty);
        indent(depth); *_out << "switch ((" << access << ").tag) {\n";
        indent(depth); *_out << "case " << oc << "_Some: {\n";
        // Mark presence BEFORE the value. A self-describing backend no-ops this (JSON and KBIN recognise a
        // present value by its own bytes); a positional one has nothing to look at, so `Some` and `None`
        // must differ by something the reader can count on.
        indent(depth + 1); *_out << "w->vtbl->writeSome(w->obj);\n";
        emitSerFieldWrite(ty->genericArg, "(" + access + ").u.Some.value", depth + 1, resultCType);
        indent(depth + 1); *_out << "break;\n";
        indent(depth); *_out << "}\n";
        indent(depth); *_out << "case " << oc << "_None: { w->vtbl->writeNull(w->obj); break; }\n";
        indent(depth); *_out << "default: break;\n";
        indent(depth); *_out << "}\n";
        return;
    }
    if (ty && ty->builtInVal == IDENTIFIER_STRING_VAL) {
        indent(depth); *_out << "w->vtbl->writeString(w->obj, &(" << access << "));\n";
        return;
    }
    const char* suf = serScalarSuffix(ty ? ty->builtInVal : 0);
    if (*suf) {
        indent(depth); *_out << "w->vtbl->write" << suf << "(w->obj, " << access << ");\n";
        return;
    }
    // `Owned<T>` — walk THROUGH the handle and write the pointee inline. See ownedPointeeOf.
    if (SharedIdentifier pointee = ownedPointeeOf(ty)) {
        emitSerFieldWrite(pointee, "(*" + derefFnName(cType(ty), /*wantMut=*/true) + "(&(" + access + ")))",
                          depth, resultCType);
        return;
    }
    if (serdeRejectsPrimitive(ty, access, /*writing=*/true, ty ? ty->line : 0)) return;
    if (serdeRejectsField(ty, access, /*writing=*/true)) return;
    // enum / nested struct / collection -> its own FALLIBLE serialize (self by pointer, Serializer* through).
    std::string innerRes = cType(resultUnitOwnedErrorTypeNode());
    std::string t = "__sw" + std::to_string(_tempCounter++);
    indent(depth); *_out << innerRes << " " << t << " = " << cType(ty) << "__serialize(" << selfArg(cType(ty), access) << ", w);\n";
    if (resultCType.empty()) {
        // graph-node/void context: sticky flag carries the failure to the boundary — drop the redundant box.
        indent(depth); *_out << "if (" << t << ".tag == " << innerRes << "_Err) { "
                             << cType(ownedErrorTypeNode()) << "__dtor(&" << t << ".u.Err.error); }\n";
        return;
    }
    // propagate the boxed Err (self is borrowed — no partial to clean up).
    indent(depth); *_out << "if (" << t << ".tag == " << innerRes << "_Err) { return (" << resultCType
                         << "){ .tag = " << resultCType << "_Err, .u.Err = { .error = " << t << ".u.Err.error } }; }\n";
}

uint32_t CEmitter::serWireId(const ClassInfo& ci, const FieldInfo& f) const
{
    if (f.serId >= 0) return (uint32_t)f.serId;
    for (size_t i = 0; i < ci.fields.size(); ++i)
        if (&ci.fields[i] == &f) return (uint32_t)i;
    return 0;   // not one of this class's fields (an enum variant payload) — the caller indexes those itself
}

std::vector<const FieldInfo*> CEmitter::serWireFields(const ClassInfo& ci, bool forWrite) const
{
    std::vector<const FieldInfo*> out;
    for (auto& f : ci.fields) {
        if (f.serSkip) continue;
        if (forWrite && f.serDeprecated) continue;
        out.push_back(&f);
    }
    // Ascending id is what makes ids and positions ONE thing: a positional backend keeps this order and a
    // numbered one keeps the values, so an author who renumbers gets both consistently. Stable, so an
    // all-defaulted type is byte-for-byte what it was before ids existed.
    std::stable_sort(out.begin(), out.end(), [&](const FieldInfo* a, const FieldInfo* b) {
        return serWireId(ci, *a) < serWireId(ci, *b);
    });
    return out;
}

void CEmitter::validateSerFieldKeys(ClassInfo& ci, int line)
{
    // `@deprecated` fields take part on purpose: that participation IS "its name and id stay reserved".
    std::map<std::string, std::string> byName;   // wire name -> the field that owns it
    std::map<uint32_t, std::string>    byId;
    for (auto& f : ci.fields) {
        if (f.serSkip) continue;   // absent from every backend, so it reserves nothing
        const std::string wire = f.serName.empty() ? f.name : f.serName;
        auto n = byName.find(wire);
        if (n != byName.end())
            unsupported(("fields '" + n->second + "' and '" + f.name + "' in '" + ci.name
                         + "' both serialize as \"" + wire + "\" — a wire name addresses one field. A name "
                         "left off defaults to the field's own name, so an explicit `@field(name: \"…\")` "
                         "can collide with one").c_str(),
                        f.nameId ? f.nameId->line : line);
        else byName[wire] = f.name;
        const uint32_t id = serWireId(ci, f);
        auto d = byId.find(id);
        if (d != byId.end())
            unsupported(("fields '" + d->second + "' and '" + f.name + "' in '" + ci.name
                         + "' both have wire id " + std::to_string(id) + " — an id addresses one field. "
                         "An id left off defaults to the field's declaration index, so an explicit "
                         "`@field(id: N)` can collide with one").c_str(),
                        f.nameId ? f.nameId->line : line);
        else byId[id] = f.name;
    }
}

void CEmitter::emitFieldKeySlot(const ClassInfo& ci, const std::vector<const FieldInfo*>& fields, int depth)
{
    indent(depth); *_out << "FieldKey __key = r.vtbl->field(r.obj);\n";
    indent(depth); *_out << "int32_t __slot = -1;\n";
    indent(depth); *_out << "if (__key.tag == FieldKey_Name) {\n";
    bool first = true;
    for (size_t i = 0; i < fields.size(); ++i) {
        const FieldInfo& f = *fields[i];
        const std::string& wire = f.serName.empty() ? f.name : f.serName;
        indent(depth + 1); *_out << (first ? "if" : "else if") << " (kama_string__equals(&__key.u.Name.name, "
                                 << kamaStrLit(wire) << ")) __slot = " << i << ";\n";
        first = false;
    }
    indent(depth); *_out << "} else if (__key.tag == FieldKey_Id) {\n";
    indent(depth + 1); *_out << "switch (__key.u.Id.id) {\n";
    for (size_t i = 0; i < fields.size(); ++i) {
        indent(depth + 2); *_out << "case " << serWireId(ci, *fields[i]) << "u: __slot = " << i << "; break;\n";
    }
    indent(depth + 2); *_out << "default: break;\n";
    indent(depth + 1); *_out << "}\n";
    indent(depth); *_out << "} else {\n";
    // `Position` is already the slot: a positional reader counts fields in the order the derive emits them,
    // which is ascending id, which is this list. It cannot report an id VALUE — it never saw one — and the two
    // cannot share the `Id` switch, since an explicit id may collide numerically with another field's rank.
    indent(depth + 1); *_out << "if (__key.u.Position.rank < " << fields.size() << "u) __slot = (int32_t)__key.u.Position.rank;\n";
    indent(depth); *_out << "}\n";
}

// `self` holds a payload-less enum's `vi`th member. An `if` test and not a `case`: a `type extern enum` may bind
// two C names that share one value, and a `switch` over those is a duplicate-case error in C.
std::string CEmitter::scalarEnumIs(const ClassInfo& ci, size_t vi, const std::string& operand)
{
    return operand + " == " + ci.name + "_" + ci.variants[vi].name;
}

void CEmitter::emitVariantKeySlot(const ClassInfo& ci, int depth)
{
    indent(depth); *_out << "FieldKey __tag = r.vtbl->variant(r.obj);\n";
    indent(depth); *_out << "int32_t __vslot = -1;\n";
    indent(depth); *_out << "if (__tag.tag == FieldKey_Name) {\n";
    for (size_t i = 0; i < ci.variants.size(); ++i) {
        indent(depth + 1); *_out << (i ? "else if" : "if") << " (kama_string__equals(&__tag.u.Name.name, "
                                 << kamaStrLit(ci.variants[i].name) << ")) __vslot = " << i << ";\n";
    }
    indent(depth); *_out << "} else {\n";
    // A variant's index IS its declaration index, so `Id` and `Position` mean the same number here and share
    // one switch — unlike a field, whose id may be an author-chosen sparse value.
    indent(depth + 1); *_out << "uint32_t __vk = (__tag.tag == FieldKey_Id) ? __tag.u.Id.id : __tag.u.Position.rank;\n";
    indent(depth + 1); *_out << "switch (__vk) {\n";
    for (size_t i = 0; i < ci.variants.size(); ++i) {
        indent(depth + 2); *_out << "case " << i << "u: __vslot = " << i << "; break;\n";
    }
    indent(depth + 2); *_out << "default: break;\n";
    indent(depth + 1); *_out << "}\n";
    indent(depth); *_out << "}\n";
}

void CEmitter::emitSerializeDefinition(ClassInfo& ci)
{
    // P4: fallible `Result<Unit, Owned<Error>> This__serialize(...)`. A composite field's Err propagates its
    // box; a scalar failure (a value the format can't represent) surfaces via the final `failed()` check.
    std::string resC = cType(ci.methods["serialize"].returnType);
    *_out << (_emitStaticClass ? "static inline " : "") << resC << " " << ci.name
          << "__serialize(" << ci.name << "* self, Serializer* w)\n{\n";
    std::vector<const FieldInfo*> wf = serWireFields(ci, /*forWrite=*/true);
    indent(1); *_out << "w->vtbl->beginObject(w->obj, " << wf.size() << ");\n";
    for (const FieldInfo* fp : wf) {
        const FieldInfo& f = *fp;
        const std::string& wire = f.serName.empty() ? f.name : f.serName;
        indent(1); *_out << "w->vtbl->field(w->obj, " << kamaStrLit(wire) << ", "
                         << serWireId(ci, f) << "u);\n";
        ScopedStr _sf(_serdeField, f.name);
        emitSerFieldWrite(f.type, "self->" + f.name, 1, resC);
    }
    indent(1); *_out << "w->vtbl->endObject(w->obj);\n";
    // Boundary: a sticky failure (a scalar value the format can't represent) -> Err(boxed).
    indent(1); *_out << "if (w->vtbl->failed(w->obj)) {\n";
    std::string box = emitStickyErrBox(2, "SerError", "w->vtbl->errorCode(w->obj)");
    indent(2); *_out << "return (" << resC << "){ .tag = " << resC << "_Err, .u.Err = { .error = " << box << " } };\n";
    indent(1); *_out << "}\n";
    indent(1); *_out << "return (" << resC << "){ .tag = " << resC << "_Ok, .u.Ok = { .value = Unit_Unit } };\n";
    *_out << "}\n\n";
}

// `@generate(Formattable)` — write a literal chunk of the dump ("Type {", " name: ", ", ", " }") into the caller's
// Formatter. `kama_string_lit` is non-owning (points at static rodata), so the temp needs no dtor — the same
// reason emitInterpolation's literal chunks are dtor-free.
void CEmitter::emitFmtLiteral(const std::string& s)
{
    std::string tmp = "__fl" + std::to_string(_tempCounter++);
    indent(1); *_out << "kama_string " << tmp << " = " << kamaStrLit(s) << "; Formatter__writeStr(f, &" << tmp << ");\n";
}

// `@generate(Formattable)` — write one field of the dump. A scalar/string/char/bool uses the matching Formatter
// fast-path (char is direct via writeChar — it has no Formattable conformance, sharing uint32's cType, exactly as
// emitInterpolation special-cases it); a composite field must itself `implements Formattable` and recurses through
// its own `__format` into the SAME Formatter (one buffer, no per-field allocation).
void CEmitter::emitFmtFieldWrite(SharedIdentifier ty, const std::string& access, int line)
{
    // ⚠️ A generic INSTANCE's field node is still the TEMPLATE's `T`, so `ty->builtInVal` reads NONE for
    // what is really an `int32` and every scalar arm below would be skipped — the field would take the
    // composite path and emit a call to `int32_t__format`, which nothing defines. `cType` hops
    // `_typeSubst` on its own; the NODE has to be substituted explicitly. Returns `ty` unchanged when
    // nothing is bound, so this costs a non-generic type one map check.
    ty = deepSubstType(ty);
    int bv = ty ? ty->builtInVal : 0;
    switch (bv) {
        case IDENTIFIER_STRING_VAL:  indent(1); *_out << "Formatter__writeStr(f, &" << access << ");\n";  return;
        case IDENTIFIER_CHAR_VAL:    indent(1); *_out << "Formatter__writeChar(f, " << access << ");\n";   return;
        case IDENTIFIER_BOOL_VAL:    indent(1); *_out << "Formatter__writeBool(f, " << access << ");\n";   return;
        // The widening cast is what lets the platform-varying pair ride the fixed widths here: on a
        // 64-bit host it is the identity, on wasm32 it widens. Rendering never needs to know the width,
        // which is why these two join in (`Formattable`) where `sizeof` and `bitcast` refuse them.
        case IDENTIFIER_INT8_VAL: case IDENTIFIER_INT16_VAL:
        case IDENTIFIER_INT32_VAL: case IDENTIFIER_INT64_VAL: case IDENTIFIER_ISIZE_VAL: case IDENTIFIER_CLONG_VAL:
            indent(1); *_out << "Formatter__writeI64(f, (int64_t)(" << access << "));\n";  return;
        case IDENTIFIER_UINT8_VAL: case IDENTIFIER_UINT16_VAL:
        case IDENTIFIER_UINT32_VAL: case IDENTIFIER_UINT64_VAL: case IDENTIFIER_USIZE_VAL: case IDENTIFIER_CULONG_VAL:
            indent(1); *_out << "Formatter__writeU64(f, (uint64_t)(" << access << "));\n"; return;
        case IDENTIFIER_FLOAT32_VAL: indent(1); *_out << "Formatter__writeF32(f, " << access << ");\n";    return;
        case IDENTIFIER_FLOAT64_VAL: indent(1); *_out << "Formatter__writeF64(f, " << access << ");\n";    return;
    }
    // Composite field: it must itself implement Formattable. (Optional/collections/enum-typed fields don't today
    // and land here as a clean error — v1 scope, tracked on the ROADMAP.)
    std::string ct = cType(ty);
    // An OPAQUE parameter under the uninstantiated-template probe: nothing is known about `T` here, and
    // the answer would be a defect reported against a type nobody instantiates. Same silence, and the
    // same escape, that serdeRejectsField already takes — see the comment there. (The probe's C goes to
    // a discarded sink, so what this emits for the field never reaches a compiler.)
    if (opaqueScalarUnknown(ct)) return;
    if (!satisfiesBound(ct, "Formattable"))
        unsupported(("`@generate(Formattable)` needs every field to be a primitive/string or a type that "
                     "`implements Formattable`; field type `" + (ty && ty->value ? *ty->value : ct)
                     + "` does not").c_str(), line);
    indent(1); *_out << ct << "__format(" << selfArg(ct, access) << ", f);\n";
}

// A method's `self` argument for the value at `place`: its address, except for a type whose methods take
// `self` by value — a payload-less enum, which is its integer (KR-59).
std::string CEmitter::selfArg(const std::string& ct, const std::string& place)
{
    auto it = _classes.find(ct);
    return (it != _classes.end() && it->second.isScalarEnum()) ? "(" + place + ")" : "&(" + place + ")";
}

// One field's equality test for the derived `equals`. A primitive compares with C `==`; `string` goes
// through the runtime intrinsic; anything else must itself `implements Equatable` and recurses through its
// own `equals` — so a derived comparison is never a bitwise `memcmp` (which would compare padding, and
// would be wrong for any type whose equality is not its representation).
std::string CEmitter::eqFieldTest(SharedIdentifier ty, const std::string& a, const std::string& b, int line)
{
    // ⚠️ A generic INSTANCE's field node is still the TEMPLATE's `T`, so `ty->builtInVal` reads NONE for
    // what is really an `int32` and every scalar arm below would be skipped — the field would take the
    // composite path and emit a call to `int32_t__equals`, which nothing defines. `cType` hops
    // `_typeSubst` on its own; the NODE has to be substituted explicitly. Returns `ty` unchanged when
    // nothing is bound, so this costs a non-generic type one map check.
    ty = deepSubstType(ty);
    if (ty && ty->builtInVal == IDENTIFIER_STRING_VAL)
        return "kama_string__equals(&" + a + ", " + b + ")";
    std::string ct = cType(ty);
    if (!_classes.count(ct))                       // primitive / UnsafePtr / enum-not-in-_classes
        return "(" + a + " == " + b + ")";
    if (opaqueScalarUnknown(ct)) return "(" + a + " == " + b + ")";   // probing an opaque `T` — see emitFmtFieldWrite
    if (!satisfiesBound(ct, "Equatable"))
        unsupported(("`@generate(Equatable)` needs every field to be a primitive/string or a type that "
                     "`implements Equatable`; field type `" + (ty && ty->value ? *ty->value : ct)
                     + "` does not").c_str(), line);
    return ct + "__equals(" + selfArg(ct, a) + ", &" + b + ")";
}

// `@generate(Equatable)` — the synthesized memberwise `equals`. Field order is declaration order, so the
// `&&` short-circuits on the cheapest discriminator the author put first. `@skip` is honored (a skipped
// field is excluded from identity, matching how it is excluded from the wire form).
void CEmitter::emitEqualsDefinition(ClassInfo& ci)
{
    int line = ci.declLine();
    *_out << (_emitStaticClass ? "static inline " : "") << "bool " << ci.name
          << "__equals(" << ci.name << "* self, " << ci.name << "* other)\n{\n";
    std::string cond;
    for (auto& fld : ci.fields) {
        if (fld.serSkip) continue;
        if (!cond.empty()) cond += " && ";
        cond += eqFieldTest(fld.type, "self->" + fld.name, "other->" + fld.name, line);
    }
    // A fieldless (or fully-skipped) bag has exactly one value, so all its instances are equal.
    indent(1); *_out << "return " << (cond.empty() ? "true" : cond) << ";\n";
    *_out << "}\n\n";
}

// One field's contribution to the derived `hash` — the sibling of eqFieldTest, extracted for the same
// reason: a variant's per-tag hash walks payload fields under the identical rule, and one rule is what
// keeps a field hashing the same wherever it is reached from. A field contributes its OWN `hash()` (the
// same cheap content hash the prelude gives every primitive); the caller does the FNV combining.
std::string CEmitter::hashFieldExpr(SharedIdentifier ty, const std::string& access, int line)
{
    // Substituted, for the reason emitSerFieldWrite gives: a generic instance's field node is the
    // template's `T`, and the string arm below reads `builtInVal`.
    ty = deepSubstType(ty);
    std::string ct = cType(ty);
    if (ty && ty->builtInVal == IDENTIFIER_STRING_VAL) return "kama_string__hash(&" + access + ")";
    if (!_classes.count(ct))                       // primitive / UnsafePtr — its own value IS the content hash
        return "(uint64_t)(" + access + ")";
    if (opaqueScalarUnknown(ct)) return "(uint64_t)(" + access + ")";   // probing an opaque `T` — see emitFmtFieldWrite
    if (!satisfiesBound(ct, "Hashable"))
        unsupported(("`@generate(Hashable)` needs every field to be a primitive/string or a type that "
                     "`implements Hashable`; field type `" + (ty && ty->value ? *ty->value : ct)
                     + "` does not").c_str(), line);
    return ct + "__hash(" + selfArg(ct, access) + ")";
}

// `@generate(Hashable)` — the field-walked hash. Each field contributes its OWN `hash()` (the same cheap
// content hash the prelude gives every primitive), FNV-1a-combined in declaration order so field order
// matters and `{1,2}` doesn't collide with `{2,1}`. The avalanche stays where it always was: the Map's
// pluggable `Hasher::finish`. Fields are skipped exactly as in `equals`, which is what keeps the
// hash/equals contract (equal values hash equal) true by construction.
void CEmitter::emitHashDefinition(ClassInfo& ci)
{
    int line = ci.declLine();
    *_out << (_emitStaticClass ? "static inline " : "") << "uint64_t " << ci.name
          << "__hash(" << ci.name << "* self)\n{\n";
    indent(1); *_out << "uint64_t h = 2166136261ULL;\n";
    for (auto& fld : ci.fields) {
        if (fld.serSkip) continue;
        indent(1); *_out << "h = (h ^ " << hashFieldExpr(fld.type, "self->" + fld.name, line)
                         << ") * 16777619ULL;\n";
    }
    indent(1); *_out << "return h;\n";
    *_out << "}\n\n";
}

// `@generate(Formattable)` — the synthesized infallible field dump: `Type { f1: v1, f2: v2 }` (empty => `Type {}`).
// The display analog of emitSerializeDefinition; string fields render raw/unquoted (each field dispatches to
// its own Formattable — no special-case, no escaping runtime). Honors `@skip` via FieldInfo::serSkip.
void CEmitter::emitFormatDefinition(ClassInfo& ci)
{
    int line = ci.declLine();
    // The dump uses the SOURCE type name (`Stat`), not the mangled C name (`_F<file>__Stat`).
    std::string disp = (ci.node && ci.node->name && ci.node->name->value) ? *ci.node->name->value : ci.name;
    *_out << (_emitStaticClass ? "static inline " : "") << "void " << ci.name
          << "__format(" << ci.name << "* self, Formatter* f)\n{\n";
    bool any = false;
    for (auto& fld : ci.fields) {
        if (fld.serSkip) continue;
        emitFmtLiteral((any ? ", " : disp + " { ") + fld.name + ": ");
        emitFmtFieldWrite(fld.type, "self->" + fld.name, line);
        any = true;
    }
    emitFmtLiteral(any ? " }" : disp + " {}");
    *_out << "}\n\n";
}

// The `Deserializer r` read EXPRESSION for a field type (scalar/string direct, else `<CType>__deserialize`).
std::string CEmitter::deReadExpr(SharedIdentifier ty)
{
    if (ty && ty->builtInVal == IDENTIFIER_STRING_VAL) return "r.vtbl->readString(r.obj)";
    const char* suf = serScalarSuffix(ty ? ty->builtInVal : 0);
    if (*suf) return std::string("r.vtbl->read") + suf + "(r.obj)";
    return cType(ty) + "__deserialize(r)";
}

// True for a serde SCALAR/string field: read directly (sticky), no Result/box — surfaced by the enclosing
// deserialize's final `failed()` check. A composite (user type / collection) reads through its fallible
// `deserialize` and its boxed `Err` is propagated.
bool CEmitter::isScalarDeType(SharedIdentifier ty)
{
    if (ty && ty->builtInVal == IDENTIFIER_STRING_VAL) return true;
    return *serScalarSuffix(ty ? ty->builtInVal : 0) != 0;
}

// Emit the read of one field into `dst` from the Deserializer `r`. `resultCType` is the enclosing
// deserialize's `Result<This, Owned<Error>>` C type; on a composite Err the read runs `cleanup` (a raw-C
// stmt prefix, e.g. free the field-name string + drop the partial result) then returns the forwarded box.
void CEmitter::emitDeFieldRead(SharedIdentifier ty, const std::string& dst, int depth,
                               const std::string& resultCType, const std::string& cleanup)
{
    // ⚠️ A generic INSTANCE's field node is still the TEMPLATE's `T`, so `ty->builtInVal` reads NONE for
    // what is really an `int32` and every scalar arm below would be skipped — the field would take the
    // composite path and emit a call to `int32_t__deserialize`, which nothing defines. `cType` hops
    // `_typeSubst` on its own; the NODE has to be substituted explicitly. Returns `ty` unchanged when
    // nothing is bound, so this costs a non-generic type one map check.
    ty = deepSubstType(ty);
    // Optional<T>: null → None; else read the inner value (fallible if composite) and wrap Some.
    if (ty && ty->value && *ty->value == "Optional" && ty->genericArg) {
        std::string oc = cType(ty);
        indent(depth); *_out << "if (r.vtbl->readNull(r.obj)) { " << dst << " = (" << oc << "){ .tag = " << oc << "_None }; }\n";
        indent(depth); *_out << "else {\n";
        if (isScalarDeType(ty->genericArg)) {
            indent(depth+1); *_out << dst << " = (" << oc << "){ .tag = " << oc << "_Some, .u.Some = { .value = "
                                   << deReadExpr(ty->genericArg) << " } };\n";
        } else {
            std::string tmp = "__ov" + std::to_string(_tempCounter++);
            indent(depth+1); *_out << cType(ty->genericArg) << " " << tmp << ";\n";
            emitDeFieldRead(ty->genericArg, tmp, depth+1, resultCType, cleanup);
            indent(depth+1); *_out << dst << " = (" << oc << "){ .tag = " << oc << "_Some, .u.Some = { .value = " << tmp << " } };\n";
        }
        indent(depth); *_out << "}\n";
        return;
    }
    // Scalar/string: bare sticky read (the enclosing `failed()` check wraps a failure into `Err`).
    if (isScalarDeType(ty)) { indent(depth); *_out << dst << " = " << deReadExpr(ty) << ";\n"; return; }
    // `Owned<T>` — the write arm's mirror: read a `T` BY VALUE, then heap-move it into a fresh block and
    // adopt. Reading into a stack temp first (rather than straight into the block) is what keeps a failed
    // read from leaving a half-built pointee on the heap: the `cleanup` path below has nothing to free.
    // malloc pairs with the box's dtor, which deallocates through `GlobalAllocator` — libc `free`; that is
    // the same pairing the bare-`new` path emits.
    if (SharedIdentifier pointee = ownedPointeeOf(ty)) {
        const std::string oc = cType(ty);
        ClassInfo* ao = nullptr;
        MethodInfo* adoptM = _classes.count(oc) ? findMethod(&_classes[oc], "adopt", &ao) : nullptr;
        // `adopt` exists only `when [A: default]`, so a stateful-allocator box has none — and the wire
        // carries no allocator handle to rebuild one from. Say that, rather than letting the composite arm
        // below report a missing `deserialize` and advise `@generate` on a stdlib type.
        if (!adoptM) {
            unsupported(("field of type `" + demangleForDisplay(oc) + "` cannot be deserialized — an "
                         "`Owned<T, A>` with a custom allocator has no `adopt`, and the wire carries no "
                         "allocator handle to rebuild the box from. Use the default allocator, or leave the "
                         "field out of the wire form with `@skip`").c_str(), ty ? ty->line : 0);
            return;
        }
        const std::string pc = cType(pointee);
        std::string v = "__ov" + std::to_string(_tempCounter++);
        std::string b = "__ob" + std::to_string(_tempCounter++);
        indent(depth); *_out << pc << " " << v << ";\n";
        emitDeFieldRead(pointee, v, depth, resultCType, cleanup);
        indent(depth); *_out << pc << "* " << b << " = (" << pc << "*)kama_alloc(" << layoutOf(pc) << ");\n";
        indent(depth); *_out << "if (!" << b << ") kama_panic(kama_string_lit(\"out of memory\", 13));\n";
        indent(depth); *_out << "*" << b << " = " << v << ";\n";
        indent(depth); *_out << dst << " = " << adoptM->cName << "(" << b << ");\n";
        return;
    }
    if (serdeRejectsPrimitive(ty, dst, /*writing=*/false, ty ? ty->line : 0)) return;
    if (serdeRejectsField(ty, dst, /*writing=*/false)) return;
    // Composite (user type / collection): fallible read via its `deserialize`.
    std::string innerRes = cType(resultOwnedErrorTypeNode(ty));
    std::string t = "__dr" + std::to_string(_tempCounter++);
    indent(depth); *_out << innerRes << " " << t << " = " << cType(ty) << "__deserialize(r);\n";
    if (resultCType.empty()) {
        // graph-shell context: no `Result` to return here, and the sticky flag already carries the failure to
        // the graph boundary — so on Err just drop the redundant box (leak-clean), else take the value.
        indent(depth); *_out << "if (" << t << ".tag == " << innerRes << "_Err) { "
                             << cType(ownedErrorTypeNode()) << "__dtor(&" << t << ".u.Err.error); }\n";
        indent(depth); *_out << "else " << dst << " = " << t << ".u.Ok.value;\n";
        return;
    }
    // propagate the boxed `Err` (drop the partial via `cleanup`).
    indent(depth); *_out << "if (" << t << ".tag == " << innerRes << "_Err) { " << cleanup
                         << "return (" << resultCType << "){ .tag = " << resultCType << "_Err, .u.Err = { .error = "
                         << t << ".u.Err.error } }; }\n";
    indent(depth); *_out << dst << " = " << t << ".u.Ok.value;\n";
}

// `Owned<X>.deserialize` — the box read. The mirror of the `Owned` arm in emitDeFieldRead: read the pointee
// BY VALUE into a stack temp, then heap-move it and adopt. Reading into the temp first is what keeps a
// failed read from leaving a half-built pointee on the heap — the Err path below has nothing to free. The
// `malloc` pairs with the box's dtor, which deallocates through `GlobalAllocator` (libc `free`), the same
// pairing bare `new` emits.
void CEmitter::emitOwnedDeserializeDefinition(ClassInfo& ci)
{
    const std::string pc = ownedPointeeClass(ci.name);
    ClassInfo* ao = nullptr;
    MethodInfo* adoptM = findMethod(&ci, "adopt", &ao);   // registerOwnedDeserialize proved it exists
    const std::string resC = cType(ci.methods["deserialize"].returnType);
    // ⚠️ Build the inner `Result<X, Owned<Error>>` from the BOX's own type argument, not by re-`cType`ing the
    // pointee's `deserialize` return node: that node resolves `This` in the POINTEE's scope, and re-resolving
    // it here mangles a file-private pointee to the wrong name (`Result_Leaf_…` for a type whose C name is
    // `_F<unit>__Leaf`). The type argument is the same node `ownedPointeeClass` reads, so it mangles right.
    auto gi = _genericTypeInsts.find(ci.name);
    const std::string innC = cType(resultOwnedErrorTypeNode(gi->second.typeArgs[0]));
    *_out << (_emitStaticClass ? "static inline " : "") << resC << " " << ci.name
          << "__deserialize(Deserializer r)\n{\n";
    indent(1); *_out << innC << " __or = " << pc << "__deserialize(r);\n";
    indent(1); *_out << "if (__or.tag == " << innC << "_Err) return (" << resC << "){ .tag = " << resC
                     << "_Err, .u.Err = { .error = __or.u.Err.error } };\n";
    indent(1); *_out << pc << "* __ob = (" << pc << "*)kama_alloc(" << layoutOf(pc) << ");\n";
    indent(1); *_out << "if (!__ob) kama_panic(kama_string_lit(\"out of memory\", 13));\n";
    indent(1); *_out << "*__ob = __or.u.Ok.value;\n";
    indent(1); *_out << "return (" << resC << "){ .tag = " << resC << "_Ok, .u.Ok = { .value = "
                     << adoptM->cName << "(__ob) } };\n";
    *_out << "}\n\n";
}

void CEmitter::emitDeserializeDefinition(ClassInfo& ci)
{
    // P4: fallible `Result<This, Owned<Error>> This__deserialize(...)`. Bypass assembly (zero-init +
    // field-set) is kept (the M6 `This.of(...)` slot); a composite field's Err propagates its box, a scalar
    // failure surfaces via the final `failed()` check. Either way: `Ok(complete)` or `Err(nothing)`.
    std::string resC = cType(ci.methods["deserialize"].returnType);
    *_out << (_emitStaticClass ? "static inline " : "") << resC << " " << ci.name
          << "__deserialize(Deserializer r)\n{\n";
    indent(1); *_out << ci.name << " result = (" << ci.name << "){0};\n";   // bypass-ctor zero-init
    // Zero-init makes an Optional field `Some(zeroed)` (tag 0) — reset every one to None first.
    for (auto& f : ci.fields) {
        if (f.serSkip) continue;
        if (f.type && f.type->value && *f.type->value == "Optional") {
            std::string oc = cType(f.type);
            indent(1); *_out << "result." << f.name << " = (" << oc << "){ .tag = " << oc << "_None };\n";
        }
    }
    // On an early Err inside the loop: free the current key, then drop the partial result.
    std::string cleanup = std::string("FieldKey__dtor(&__key); ")
                        + (ci.destructible ? (ci.name + "__dtor(&result); ") : "");
    // READ-visible fields: `@deprecated` is still read, so it stays in this list (it is only dropped from
    // the write side). An unknown key falls to `skipValue`, which is what keeps a named stream
    // forward-compatible.
    std::vector<const FieldInfo*> rf = serWireFields(ci, /*forWrite=*/false);
    // ⚠️ The count is the WRITE-visible one. It describes what a writer PUT on the wire, so a
    // `@deprecated` field — read when present, never written — must not be counted, or a positional
    // reader expects one field too many and runs off the end of the record.
    indent(1); *_out << "r.vtbl->beginObject(r.obj, " << serWireFields(ci, /*forWrite=*/true).size() << ");\n";
    indent(1); *_out << "while (r.vtbl->moreFields(r.obj)) {\n";
    emitFieldKeySlot(ci, rf, 2);
    indent(2); *_out << "switch (__slot) {\n";
    for (size_t i = 0; i < rf.size(); ++i) {
        indent(3); *_out << "case " << i << ": {\n";
        { ScopedStr _sf(_serdeField, rf[i]->name); emitDeFieldRead(rf[i]->type, "result." + rf[i]->name, 4, resC, cleanup); }
        indent(3); *_out << "break;\n";
        indent(3); *_out << "}\n";
    }
    indent(3); *_out << "default: r.vtbl->skipValue(r.obj); break;\n";
    indent(2); *_out << "}\n";
    indent(2); *_out << "FieldKey__dtor(&__key);\n";   // the key owns its name string — free each iteration
    indent(1); *_out << "}\n";
    indent(1); *_out << "r.vtbl->endObject(r.obj);\n";
    // Boundary: a sticky failure (a scalar read / an explicit `fail`) → drop the partial + Err(boxed).
    indent(1); *_out << "if (r.vtbl->failed(r.obj)) {\n";
    if (ci.destructible) { indent(2); *_out << ci.name << "__dtor(&result);\n"; }
    std::string box = emitStickyErrBox(2);
    indent(2); *_out << "return (" << resC << "){ .tag = " << resC << "_Err, .u.Err = { .error = " << box << " } };\n";
    indent(1); *_out << "}\n";
    indent(1); *_out << "return (" << resC << "){ .tag = " << resC << "_Ok, .u.Ok = { .value = result } };\n";
    *_out << "}\n\n";
}

// Externally-tagged enum serialize: `{"tag":"V"}` (unit) / `{"tag":"V","value":{fields…}}` (payload).
void CEmitter::emitEnumSerializeDefinition(ClassInfo& ci)
{
    std::string resC = cType(ci.methods["serialize"].returnType);   // Result<Unit, Owned<Error>>
    // The linkage every class-side synth emitter carries, and these two lacked: a body emitted into the
    // HEADER (a prelude enum, a generic enum instance) must match the `static inline` prototype
    // emitClassPrototypes already wrote for it, or each TU gets its own external copy of the same symbol.
    *_out << (_emitStaticClass ? "static inline " : "") << resC << " " << ci.name
          << "__serialize(" << ci.name << (ci.isScalarEnum() ? " self" : "* self") << ", Serializer* w)\n{\n";
    // A PAYLOAD-LESS enum is a NAME, not a record, and it goes on the wire as one: `"Green"`, not
    // `{"tag":"Green"}`. There is no payload for the object to carry, so the object would be a wrapper
    // around nothing — and a bare string is what every other format writes for a fieldless variant
    // (serde_json included). The shape is decided by the TYPE, not per value, so a schema still reads
    // cleanly: a payload-less enum is always a string, a tagged one is always an object.
    // (emitVariantWriteFrame decides which.)
    emitVariantWriteFrame(ci, [&](const FieldInfo& f, const std::string& access, int d) {
        emitSerFieldWrite(f.type, access, d, resC);
    });
    indent(1); *_out << "if (w->vtbl->failed(w->obj)) {\n";
    std::string box = emitStickyErrBox(2, "SerError", "w->vtbl->errorCode(w->obj)");
    indent(2); *_out << "return (" << resC << "){ .tag = " << resC << "_Err, .u.Err = { .error = " << box << " } };\n";
    indent(1); *_out << "}\n";
    indent(1); *_out << "return (" << resC << "){ .tag = " << resC << "_Ok, .u.Ok = { .value = Unit_Unit } };\n";
    *_out << "}\n\n";
}

// The externally-tagged frame (see emitEnumSerializeDefinition), with each payload field handed to
// `writeField`. A payload-less enum is its bare variant name.
void CEmitter::emitVariantWriteFrame(ClassInfo& ci,
                                     const std::function<void(const FieldInfo&, const std::string&, int)>& writeField,
                                     const std::string& scalarSelf)
{
    if (ci.isScalarEnum()) {
        for (size_t vi = 0; vi < ci.variants.size(); ++vi) {
            indent(1); *_out << (vi ? "else if" : "if") << " (" << scalarEnumIs(ci, vi, scalarSelf) << ") "
                             << "w->vtbl->variant(w->obj, " << kamaStrLit(ci.variants[vi].name) << ", " << vi << "u);\n";
        }
        return;
    }
    // The outer frame is `{tag}` or `{tag, value}`, so its field count is VARIANT-dependent — and
    // `beginObject` has to run before the `switch`, since a backend may need the frame open before any key.
    // Compute the count in its own switch rather than moving `beginObject` into the arms: the `default:
    // break` below would then reach `endObject` with no matching begin, and JSON would emit a stray `}`.
    indent(1); *_out << "size_t __n = 1;\n";
    indent(1); *_out << "switch (self->tag) {\n";
    for (auto& v : ci.variants)
        if (!v.payload.empty()) { indent(2); *_out << "case " << ci.name << "_" << v.name << ": __n = 2; break;\n"; }
    indent(2); *_out << "default: break;\n";
    indent(1); *_out << "}\n";
    indent(1); *_out << "w->vtbl->beginObject(w->obj, __n);\n";
    indent(1); *_out << "switch (self->tag) {\n";
    // The externally-tagged framing keys are addressed like any other key: "tag" is id 0 and "value" is
    // id 1. They cannot collide with a payload field's id because a payload is a NESTED object with its
    // own `beginObject`, and its fields are numbered from 0 inside that.
    for (size_t vi = 0; vi < ci.variants.size(); ++vi) {
        auto& v = ci.variants[vi];
        indent(1); *_out << "case " << ci.name << "_" << v.name << ": {\n";
        indent(2); *_out << "w->vtbl->field(w->obj, " << kamaStrLit("tag") << ", 0u);\n";
        // The selector goes through `variant`, not `writeString`: a discriminant is one of `n` known
        // alternatives, so a positional or numbered backend spends one byte on it where a name costs the
        // whole string. A named backend writes the name and its bytes are unchanged. The index is the
        // variant's declaration index, which is also its C tag value.
        indent(2); *_out << "w->vtbl->variant(w->obj, " << kamaStrLit(v.name) << ", " << vi << "u);\n";
        if (!v.payload.empty()) {
            indent(2); *_out << "w->vtbl->field(w->obj, " << kamaStrLit("value") << ", 1u);\n";
            indent(2); *_out << "w->vtbl->beginObject(w->obj, " << v.payload.size() << ");\n";
            for (size_t pi = 0; pi < v.payload.size(); ++pi) {
                auto& f = v.payload[pi];
                // A payload field carries no attributes (the grammar gives a variant payload no slot for
                // one), so its id is positional by construction and can never be reordered.
                indent(2); *_out << "w->vtbl->field(w->obj, " << kamaStrLit(f.name) << ", " << pi << "u);\n";
                ScopedStr _sf(_serdeField, f.name);
                writeField(f, "self->u." + v.name + "." + f.name, 2);
            }
            indent(2); *_out << "w->vtbl->endObject(w->obj);\n";
        }
        indent(2); *_out << "break;\n";
        indent(1); *_out << "}\n";
    }
    indent(1); *_out << "default: break;\n";
    indent(1); *_out << "}\n";
    indent(1); *_out << "w->vtbl->endObject(w->obj);\n";
}

void CEmitter::emitVariantPayloadWalk(ClassInfo& ci,
                                      const std::function<void(const FieldInfo&, const std::string&, int)>& walkField)
{
    indent(1); *_out << "switch (self->tag) {\n";
    for (auto& v : ci.variants) {
        if (v.payload.empty()) continue;
        indent(1); *_out << "case " << ci.name << "_" << v.name << ": {\n";
        for (auto& f : v.payload) {
            ScopedStr _sf(_serdeField, f.name);
            walkField(f, "self->u." + v.name + "." + f.name, 2);
        }
        indent(2); *_out << "break;\n";
        indent(1); *_out << "}\n";
    }
    indent(1); *_out << "default: break;\n";
    indent(1); *_out << "}\n";
}

// Enum deserialize: read `tag`, dispatch, read the `value` object positionally, construct the variant. An
// unknown tag flags the reader (`fail`) and returns a benign payload-less variant (the guaranteed fallback).
void CEmitter::emitEnumDeserializeDefinition(ClassInfo& ci)
{
    std::string resC = cType(ci.methods["deserialize"].returnType);   // Result<This, Owned<Error>>
    std::string dflt;
    for (auto& v : ci.variants) if (v.payload.empty()) { dflt = v.name; break; }
    *_out << (_emitStaticClass ? "static inline " : "") << resC << " " << ci.name
          << "__deserialize(Deserializer r)\n{\n";   // linkage: see emitEnumSerializeDefinition
    indent(1); *_out << ci.name << " __result = " << (ci.isScalarEnum() ? std::string("0") : "(" + ci.name + "){0}") << ";\n";
    // The reader half of the bare-string form — read the name, match it against the variants, and Err on
    // one that names none (there is no "unknown" variant to park on and no payload to skip).
    if (ci.isScalarEnum()) {
        emitVariantKeySlot(ci, 1);
        indent(1); *_out << "switch (__vslot) {\n";
        for (size_t i = 0; i < ci.variants.size(); ++i) {
            indent(2); *_out << "case " << i << ": __result = " << ci.name << "_" << ci.variants[i].name << "; break;\n";
        }
        indent(2); *_out << "default: r.vtbl->fail(r.obj); break;\n";
        indent(1); *_out << "}\n";
        indent(1); *_out << "FieldKey__dtor(&__tag);\n";
        indent(1); *_out << "if (r.vtbl->failed(r.obj)) {\n";
        std::string nbox = emitStickyErrBox(2);
        indent(2); *_out << "return (" << resC << "){ .tag = " << resC << "_Err, .u.Err = { .error = " << nbox << " } };\n";
        indent(1); *_out << "}\n";
        indent(1); *_out << "return (" << resC << "){ .tag = " << resC << "_Ok, .u.Ok = { .value = __result } };\n";
        *_out << "}\n\n";
        return;
    }
    // Closing an object means DRAINING it to the end tag, never a bare `moreFields()` (consumer KG-35).
    // The bare call answered true at a truncated buffer's end (KBIN peeks 0 past the end, which is not
    // the end tag) and consumed nothing, so an object missing its closing bytes decoded as the complete
    // value — the 49- and 50-byte prefixes of a 51-byte `Create(name: "matt")` both came back as it.
    // Draining makes the reader ask `next()` past the end, which IS an error, and skips any unknown
    // trailing field on the way — the same forward-compat rule the struct path above has always had.
    auto closeObj = [&](int d) {
        indent(d); *_out << "while (r.vtbl->moreFields(r.obj)) { FieldKey __sk = r.vtbl->field(r.obj); "
                            "FieldKey__dtor(&__sk); r.vtbl->skipValue(r.obj); }\n";
        indent(d); *_out << "r.vtbl->endObject(r.obj);\n";
    };
    // 0 = "not statically known": which variant follows — and so whether the frame is `{tag}` or
    // `{tag, value}` — is only known once the tag is read, and the tag is INSIDE this object.
    indent(1); *_out << "r.vtbl->beginObject(r.obj, 0);\n";
    indent(1); *_out << "r.vtbl->moreFields(r.obj);\n";
    // The framing keys are read POSITIONALLY and discarded — the shape `{tag, value}` is fixed, so there is
    // nothing to dispatch on. Only the selector and the payload fields carry information.
    indent(1); *_out << "FieldKey __k = r.vtbl->field(r.obj); FieldKey__dtor(&__k);\n";   // the "tag" key
    emitVariantKeySlot(ci, 1);
    bool first = true;
    for (size_t vi = 0; vi < ci.variants.size(); ++vi) {
        auto& v = ci.variants[vi];
        indent(1); *_out << (first ? "if" : "else if") << " (__vslot == " << vi << ") {\n";
        if (!v.payload.empty()) {
            indent(2); *_out << "r.vtbl->moreFields(r.obj);\n";
            indent(2); *_out << "FieldKey __kv = r.vtbl->field(r.obj); FieldKey__dtor(&__kv);\n";   // the "value" key
            indent(2); *_out << "r.vtbl->beginObject(r.obj, " << v.payload.size() << ");\n";
            // an early Err while reading payload field i must free __tag + drop the already-read temps.
            std::string cleanup = "FieldKey__dtor(&__tag); ";
            for (size_t i = 0; i < v.payload.size(); ++i) {
                const FieldInfo& f = v.payload[i];
                std::string idx = std::to_string(i);
                indent(2); *_out << "r.vtbl->moreFields(r.obj);\n";
                indent(2); *_out << "FieldKey __pk" << idx << " = r.vtbl->field(r.obj); FieldKey__dtor(&__pk" << idx << ");\n";
                indent(2); *_out << cType(f.type) << " __p_" << f.name << ";\n";
                { ScopedStr _sf(_serdeField, f.name); emitDeFieldRead(f.type, "__p_" + f.name, 2, resC, cleanup); }
                if (_classes.count(cType(f.type)) && _classes[cType(f.type)].destructible)
                    cleanup += cType(f.type) + "__dtor(&__p_" + f.name + "); ";
            }
            closeObj(2);   // the value object
            closeObj(2);   // the outer object
            indent(2); *_out << "__result = (" << ci.name << "){ .tag = " << ci.name << "_" << v.name << ", .u." << v.name << " = { ";
            for (size_t i = 0; i < v.payload.size(); ++i) { if (i) *_out << ", "; *_out << "." << v.payload[i].name << " = __p_" << v.payload[i].name; }
            *_out << " } };\n";
        } else {
            closeObj(2);   // the outer object
            indent(2); *_out << "__result = (" << ci.name << "){ .tag = " << ci.name << "_" << v.name << " };\n";
        }
        indent(1); *_out << "}\n";
        first = false;
    }
    // An unknown tag. With a unit variant to hand, park the result on it and let the shared `failed()`
    // boundary below do the reporting. WITHOUT one there is no benign value to park on — the old code
    // emitted `(E){ .tag = E_ }` and did not compile, which is why `Deserializable` used to be silently
    // DROPPED from an enum whose every variant carries a payload. Return the Err here instead: nothing
    // has been constructed, so there is no partial to drop and `__result` is never touched.
    if (!dflt.empty()) {
        indent(1); *_out << "else { r.vtbl->fail(r.obj); __result = (" << ci.name << "){ .tag = " << ci.name << "_" << dflt << " }; }\n";
    } else {
        indent(1); *_out << "else {\n";
        indent(2); *_out << "r.vtbl->fail(r.obj);\n";
        indent(2); *_out << "FieldKey__dtor(&__tag);\n";
        std::string ubox = emitStickyErrBox(2);
        indent(2); *_out << "return (" << resC << "){ .tag = " << resC << "_Err, .u.Err = { .error = " << ubox << " } };\n";
        indent(1); *_out << "}\n";
    }
    indent(1); *_out << "FieldKey__dtor(&__tag);\n";
    // Boundary: an unknown tag (`fail`) or a scalar payload failure → drop the partial + Err(boxed); else Ok.
    indent(1); *_out << "if (r.vtbl->failed(r.obj)) {\n";
    if (ci.destructible) { indent(2); *_out << ci.name << "__dtor(&__result);\n"; }
    std::string ebox = emitStickyErrBox(2);
    indent(2); *_out << "return (" << resC << "){ .tag = " << resC << "_Err, .u.Err = { .error = " << ebox << " } };\n";
    indent(1); *_out << "}\n";
    indent(1); *_out << "return (" << resC << "){ .tag = " << resC << "_Ok, .u.Ok = { .value = __result } };\n";
    *_out << "}\n\n";
}

// ---- The derived bodies for an ENUM (a tagged one, and a payload-less one — see `isScalarEnum`) --------
//
// A `value`/`resource` derives by walking `ci.fields`; a variant has none — its data lives per tag, in
// `ci.variants[i].payload`, reached as `self->u.<Variant>.<field>`. So each of the three class-side
// emitters below has a per-tag sibling here, switching on `self->tag`. The PER-FIELD rules are not
// duplicated: these call the very helpers the class side calls (emitFmtFieldWrite / eqFieldTest /
// hashFieldExpr), which is what keeps a field rendering, comparing and hashing identically wherever it
// is reached from — and which is where the `deepSubstType` hop lives that a generic instance depends on.
//
// ⚠️ A payload FieldInfo carries NO `@skip`: buildVariantClassInfo never reads per-field attributes.
// So there is deliberately no `serSkip` check below — a dead one would read as a supported feature.

// `@generate(Formattable)` on an enum: `Circle { r: 2 }` for a payload variant, the bare name (`Nil`)
// for a unit one. The subject is the VARIANT, not the type — which is also why this needs no display
// name: a variant name is written as the author spelled it, never mangled.
void CEmitter::emitEnumFormatDefinition(ClassInfo& ci)
{
    int line = ci.declLine();
    *_out << (_emitStaticClass ? "static inline " : "") << "void " << ci.name
          << "__format(" << ci.name << (ci.isScalarEnum() ? " self" : "* self") << ", Formatter* f)\n{\n";
    if (ci.isScalarEnum()) {
        for (size_t vi = 0; vi < ci.variants.size(); ++vi) {
            indent(1); *_out << (vi ? "else if" : "if") << " (" << scalarEnumIs(ci, vi, "self") << ") {\n";
            emitFmtLiteral(ci.variants[vi].name);
            indent(1); *_out << "}\n";
        }
        *_out << "}\n\n";
        return;
    }
    indent(1); *_out << "switch (self->tag) {\n";
    for (auto& v : ci.variants) {
        indent(1); *_out << "case " << ci.name << "_" << v.name << ": {\n";
        if (v.payload.empty()) emitFmtLiteral(v.name);
        else {
            bool any = false;
            for (auto& f : v.payload) {
                emitFmtLiteral((any ? ", " : v.name + " { ") + f.name + ": ");
                emitFmtFieldWrite(f.type, "self->u." + v.name + "." + f.name, line);
                any = true;
            }
            emitFmtLiteral(" }");
        }
        indent(2); *_out << "break;\n";
        indent(1); *_out << "}\n";
    }
    indent(1); *_out << "default: break;\n";
    indent(1); *_out << "}\n";
    *_out << "}\n\n";
}

// `@generate(Equatable)` on an enum: different tags are never equal; the same tag compares its payload
// field by field, each through its own `equals`. A unit variant is exhausted by the tag test alone.
void CEmitter::emitEnumEqualsDefinition(ClassInfo& ci)
{
    int line = ci.declLine();
    *_out << (_emitStaticClass ? "static inline " : "") << "bool " << ci.name
          << "__equals(" << ci.name << (ci.isScalarEnum() ? " self, " : "* self, ") << ci.name << "* other)\n{\n";
    if (ci.isScalarEnum()) { indent(1); *_out << "return self == *other;\n}\n\n"; return; }
    indent(1); *_out << "if (self->tag != other->tag) { return false; }\n";
    bool anyPayload = false;
    for (auto& v : ci.variants) if (!v.payload.empty()) { anyPayload = true; break; }
    if (anyPayload) {
        indent(1); *_out << "switch (self->tag) {\n";
        for (auto& v : ci.variants) {
            if (v.payload.empty()) continue;   // the tag test above already settled it
            indent(1); *_out << "case " << ci.name << "_" << v.name << ": {\n";
            std::string cond;
            for (auto& f : v.payload) {
                if (!cond.empty()) cond += " && ";
                cond += eqFieldTest(f.type, "self->u." + v.name + "." + f.name,
                                            "other->u." + v.name + "." + f.name, line);
            }
            indent(2); *_out << "return " << cond << ";\n";
            indent(1); *_out << "}\n";
        }
        indent(1); *_out << "default: break;\n";
        indent(1); *_out << "}\n";
    }
    indent(1); *_out << "return true;\n";
    *_out << "}\n\n";
}

// `@generate(Hashable)` on an enum: the tag is the first thing mixed in — it is what distinguishes two
// variants carrying identical payloads — then the live variant's fields, in declaration order. Same
// FNV-1a combine as the class-side walk, so the hash/equals contract holds by the same construction.
void CEmitter::emitEnumHashDefinition(ClassInfo& ci)
{
    int line = ci.declLine();
    *_out << (_emitStaticClass ? "static inline " : "") << "uint64_t " << ci.name
          << "__hash(" << ci.name << (ci.isScalarEnum() ? " self" : "* self") << ")\n{\n";
    indent(1); *_out << "uint64_t h = 2166136261ULL;\n";
    indent(1); *_out << "h = (h ^ (uint64_t)(" << (ci.isScalarEnum() ? "self" : "self->tag") << ")) * 16777619ULL;\n";
    bool anyPayload = false;
    for (auto& v : ci.variants) if (!v.payload.empty()) { anyPayload = true; break; }
    if (anyPayload) {
        indent(1); *_out << "switch (self->tag) {\n";
        for (auto& v : ci.variants) {
            if (v.payload.empty()) continue;
            indent(1); *_out << "case " << ci.name << "_" << v.name << ": {\n";
            for (auto& f : v.payload) {
                indent(2); *_out << "h = (h ^ "
                                 << hashFieldExpr(f.type, "self->u." + v.name + "." + f.name, line)
                                 << ") * 16777619ULL;\n";
            }
            indent(2); *_out << "break;\n";
            indent(1); *_out << "}\n";
        }
        indent(1); *_out << "default: break;\n";
        indent(1); *_out << "}\n";
    }
    indent(1); *_out << "return h;\n";
    *_out << "}\n\n";
}

// The ONE place a synthesized body picks its emitter, so the variant/class fork is written once. Called
// from emitClassDefinitions (which is how a GENERIC enum instance gets its bodies — its instance goes
// through emitGenericTypeInst phase 2 like any other) and, via emitVariantSynthBodies, from the two
// sites that emit a concrete enum's bodies by hand.
void CEmitter::emitSynthBody(ClassInfo& ci, const std::string& name, MethodInfo& mi)
{
    // A graph node's pair IS the walker: `serialize` writes the whole envelope from this root and
    // `deserialize` reads it back as a handle. Everything else is the by-value derive.
    if (mi.isSynthSer) { ci.reachesPointer ? emitGraphSerializeDefinition(ci)
                       : (ci.isVariant || ci.isScalarEnum() ? emitEnumSerializeDefinition(ci) : emitSerializeDefinition(ci)); return; }
    if (mi.isSynthDe)  {
        // An `Owned<X>` box read is neither: it has no fields of its own, it reads its POINTEE by value and
        // adopts the block. See registerOwnedDeserialize.
        if (ci.ownedBoxDe) { emitOwnedDeserializeDefinition(ci); return; }
        ci.graphDeserialize ? emitGraphDeserializeDefinition(ci)
                            : (ci.isVariant || ci.isScalarEnum() ? emitEnumDeserializeDefinition(ci) : emitDeserializeDefinition(ci)); return; }
    const bool isEnumType = ci.isVariant || ci.isScalarEnum();
    if (mi.isSynthFormat) { isEnumType ? emitEnumFormatDefinition(ci) : emitFormatDefinition(ci); return; }
    if (mi.isSynthCmp) {                                              // keyed by the method name
        if (name == "equals") isEnumType ? emitEnumEqualsDefinition(ci) : emitEqualsDefinition(ci);
        else                  isEnumType ? emitEnumHashDefinition(ci)   : emitHashDefinition(ci);
        return;
    }
    emitBagCtorBody(ci, name);   // M6 `@generate(of|zero)` — never a variant (registerDerives refuses it)
}

// Every synthesized body a variant carries. A CONCRETE enum's bodies are emitted from the two hand sites
// rather than from emitClassDefinitions, and that is not an accident to be tidied away: `classOf` casts
// `ClassDeclarationNode` (an enum has none), the preludeStatic loop skips `isVariant`, and the prelude
// enum loop looks names up in `_classes`, where a generic TEMPLATE never lives. Those three guards are
// what keep the two populations disjoint — remove any one and a concrete enum gets its bodies twice.
// Emitted in a FIXED order rather than `ci.methods`' alphabetical one — which would put `deserialize`
// ahead of `serialize` and shuffle every existing enum's generated C for no reason. Nothing depends on
// the order (the prototypes are all in the header), but a refactor that reorders output cannot be
// diffed against the corpus to prove it changed nothing, and that proof is worth more than the shuffle.
void CEmitter::emitVariantSynthBodies(ClassInfo& ci)
{
    static const char* kOrder[] = { "serialize", "deserialize", "format", "equals", "hash" };
    for (const char* name : kOrder) {
        auto it = ci.methods.find(name);
        if (it == ci.methods.end() || it->second.isAbstract) continue;
        MethodInfo& mi = it->second;
        if (mi.isSynthSer || mi.isSynthDe || mi.isSynthFormat || mi.isSynthCmp)
            emitSynthBody(ci, it->first, mi);
    }
}

// ---- Object-graph serialization: the per-type ADAPTERS ------------------------------------------------
// A `@generate` type or enum that reaches a Shared/Weak edge (or is such an edge's pointee) is a GRAPH NODE.
// The walk is emitted C over the runtime's `kama_ser_graph`/`kama_de_graph`: the node's own
// `serialize`/`deserialize` are the drivers (the `{root, objects}` envelope, the id table, the two-pass read),
// and each node gets four helpers — `K__visitEdges`/`K__writeNode` (write) and `K____readInto`/`K__wireEdges`
// (read) — plus, per contract used as an edge, a resolver pair. An enum node's helpers walk the payload of
// whichever variant it holds, inside the same `{tag, value}` frame its by-value derive writes. (An earlier
// design put the algorithm in a library `ObjectGraph<T>` over prelude `Graph*` contracts; it was reverted.)
//
// Edges. A `Shared<X>`/`Weak<X>` field is written as a `u64` id the walker answers (`intern`), read back in
// two passes: pass 1 (`readInto`) reads the id and STASHES it in the handle's own pointer slot with the control
// block NULL — both handle dtors guard on that block, so an aborted read drops cleanly — and pass 2
// (`wireEdges`) turns each stash into a retained handle via `resolve`. A CONTRACT edge (`Shared<Shape>`)
// crosses the concrete/erased line through the per-contract resolvers below. A nested by-value field or an
// `Owned<X>` pointee that is itself a node is walked INLINE by the same passes (its edges are its owner's
// edges); an `Owned<X>` that reaches nothing is an ordinary value field (lib/std/memory/owned.kama).

// One field's graph-pointer classification. kind is "" for a non-edge field (scalar/string/nested/
// collection/`Owned` — those flow through the by-value helpers; an `Owned<X>` is a unique subtree and
// serializes inline through the triad's own conformance), else "Shared"/"Weak" with elemC the pointee's
// C type. `optional` = the edge is wrapped in `Optional<…>` (nullable, e.g. a list tail / cycle bootstrap).
CEmitter::GraphEdge CEmitter::graphEdgeOf(SharedIdentifier ty)
{
    GraphEdge e;
    if (!ty || !ty->value) return e;
    bool opt = (*ty->value == "Optional" && ty->genericArg);
    SharedIdentifier inner = opt ? ty->genericArg : ty;
    std::string ic = cType(inner);
    // Graph deserialize reconstructs a Shared/Weak edge with a ZEROED allocator (it has no handle on the
    // wire), so a STATEFUL-allocator edge would later free through a bogus/zeroed `A` -> leak/UAF. Deserializable
    // is GlobalAllocator-only by design; reject a non-Global edge at the one spot the box type is known.
    auto rejectStatefulEdge = [&](const std::string& a) {
        if (!a.empty() && a != "GlobalAllocator")
            unsupported("graph-mode serialization is GlobalAllocator-only — a Shared/Weak<…, A> edge with "
                        "a stateful allocator can't be reconstructed (deserialize wires a zeroed allocator); use "
                        "the default allocator for @generate graph fields", ty->line);
    };
    // Concrete-element triad instance (`Shared<Leaf>` etc.) — a library generic instance keyed by template.
    auto g = _genericTypeInstOf.find(ic);
    if (g != _genericTypeInstOf.end()) {
        if      (g->second == _sharedTmpl) e.kind = "Shared";
        else if (g->second == _weakTmpl)   e.kind = "Weak";
        if (!e.kind.empty()) { rejectStatefulEdge(boxAllocatorArg(ic)); e.elemC = inner->genericArg ? cType(inner->genericArg) : ""; e.elemIsContract = isInterface(e.elemC); e.optional = opt; return e; }
    }
    // Interface-erased intrinsic smart pointer (`Shared<Contract>` / `Weak<Contract>`). An `Owned<Contract>`
    // is not an edge either — it is the tagged inline form, see emitSerFieldWrite.
    if (isSmartPtrClass(ic)) {
        CollKind k = smartKind(ic);
        if (k == CollKind::Owned) return e;
        e.kind  = (k == CollKind::Shared) ? "Shared" : "Weak";
        rejectStatefulEdge(_collections.count(ic) ? _collections[ic].allocType : "");
        e.elemC = _classes.count(ic) ? _classes[ic].collElemClass : "";
        e.elemIsContract = isInterface(e.elemC);
        e.optional = opt;
    }
    return e;
}

// The wire `__type` tag for a graph node: the SOURCE type name (`Node`), not the mangled C name (`_F<file>__Node`).
// Both the writer (`typeName`) and the reader (the shell chain) must agree, so they share this.
std::string CEmitter::graphWireName(const ClassInfo& ci)
{
    if (ci.node && ci.node->name && ci.node->name->value) return *ci.node->name->value;
    if (ci.enumNode && ci.enumNode->identifier && ci.enumNode->identifier->value) return *ci.enumNode->identifier->value;
    return ci.name;
}

// Synthesize a `Shared<elem>` type node (the graph deserialize return type: `decode::<Shared<T>>` hands back
// the owning root handle). Resolves like the user-written `Shared<Leaf>` field types (empty qualifier + the
// implicit `using std::memory`), so cType mangles it to `Shared_<elem>`.
SharedIdentifier CEmitter::sharedTypeNode(SharedIdentifier elem) { return triadTypeNode("Shared", elem); }

// …and the same for either shared handle: an edge ELEMENT may be a `Weak<X>` as readily as a `Shared<X>`,
// and its read helper has to answer the handle it actually is.
SharedIdentifier CEmitter::triadTypeNode(const char* kind, SharedIdentifier elem)
{
    if (!_synthCtx) _synthCtx = std::make_shared<CodeGenContext>(std::make_shared<std::string>("<synth>"));
    auto node = std::make_shared<IdentifierNode>(*_synthCtx, std::make_shared<std::string>(kind),
                                                 std::make_shared<StringList>(), elem);
    node->synthesized = true;   // emitter-built: not source text (see ASTNode::synthesized)
    node->genericArgs = std::make_shared<IdentifierList>();
    node->genericArgs->push_back(elem);
    return node;
}

// Synthesize an `Owned<elem>` type node — the return of a box read (`Owned<X>.deserialize`). Fully
// qualified for the same reason ownedErrorTypeNode is: a bare `Owned` does not resolve from every context,
// and it must mangle to the SAME canonical instance a user-written `Owned<X>` does, or the `Result`
// monomorph diverges from the one the caller declared.
SharedIdentifier CEmitter::ownedTypeNode(SharedIdentifier elem)
{
    if (!_synthCtx) _synthCtx = std::make_shared<CodeGenContext>(std::make_shared<std::string>("<synth>"));
    auto qual = std::make_shared<StringList>();
    qual->push_back(std::make_shared<std::string>("std"));
    qual->push_back(std::make_shared<std::string>("memory"));
    auto owned = std::make_shared<IdentifierNode>(*_synthCtx, std::make_shared<std::string>("Owned"), qual, elem);
    owned->synthesized = true;   // emitter-built: not source text (see ASTNode::synthesized)
    owned->genericArgs = std::make_shared<IdentifierList>();
    owned->genericArgs->push_back(elem);
    return owned;
}

// Synthesize an `Owned<Error>` type node — the uniform boxed-error payload of a fallible serde Result.
SharedIdentifier CEmitter::ownedErrorTypeNode()
{
    if (!_synthCtx) _synthCtx = std::make_shared<CodeGenContext>(std::make_shared<std::string>("<synth>"));
    auto err   = std::make_shared<IdentifierNode>(*_synthCtx, std::make_shared<std::string>("Error"),
                                                  std::make_shared<StringList>());
    err->synthesized = true;   // emitter-built: not source text (see ASTNode::synthesized)
    // FULLY-QUALIFIED `std::memory::Owned` — bare `Owned` doesn't resolve from every context (e.g. the
    // global prelude), and it must mangle to the SAME canonical `std__memory__Owned_Error_GlobalAllocator`
    // as a user-written `Owned<Error>` (allocator default filled), else the Result monomorph diverges.
    auto qual  = std::make_shared<StringList>();
    qual->push_back(std::make_shared<std::string>("std"));
    qual->push_back(std::make_shared<std::string>("memory"));
    auto owned = std::make_shared<IdentifierNode>(*_synthCtx, std::make_shared<std::string>("Owned"), qual, err);
    owned->synthesized = true;   // emitter-built: not source text (see ASTNode::synthesized)
    owned->genericArgs = std::make_shared<IdentifierList>();
    owned->genericArgs->push_back(err);
    return owned;
}

// Synthesize a `Result<inner, Owned<Error>>` type node — the uniform fallible-deserialize return type.
// Resolves like a user-written type (empty qualifier), so cType mangles it and registers the monomorph.
SharedIdentifier CEmitter::resultOwnedErrorTypeNode(SharedIdentifier inner)
{
    auto res   = std::make_shared<IdentifierNode>(*_synthCtx, std::make_shared<std::string>("Result"),
                                                  std::make_shared<StringList>(), inner);
    res->synthesized = true;   // emitter-built: not source text (see ASTNode::synthesized)
    res->genericArgs = std::make_shared<IdentifierList>();
    res->genericArgs->push_back(inner);
    res->genericArgs->push_back(ownedErrorTypeNode());
    return res;
}

// Synthesize a `Result<Unit, Owned<Error>>` type node — the uniform fallible-serialize return type (a write
// produces nothing, so `Unit`; the read twin returns `Result<This, …>`). Mirrors resultOwnedErrorTypeNode.
SharedIdentifier CEmitter::resultUnitOwnedErrorTypeNode()
{
    if (!_synthCtx) _synthCtx = std::make_shared<CodeGenContext>(std::make_shared<std::string>("<synth>"));
    auto unit = std::make_shared<IdentifierNode>(*_synthCtx, std::make_shared<std::string>("Unit"),
                                                 std::make_shared<StringList>());
    unit->synthesized = true;   // emitter-built: not source text (see ASTNode::synthesized)
    return resultOwnedErrorTypeNode(unit);
}

// Emit (raw C) the boxing of a sticky enum error (`DeError` for read, `SerError` for write) drawn from
// `errExpr` into an `Owned<Error>`; returns the temp holding it. Reuses the P2 boxing
// (emitEnumBoxIntoContract) — flushes its one hoisted statement here since the synth serde bodies are
// hand-emitted C, not the expression/hoist path.
std::string CEmitter::emitStickyErrBox(int depth, const std::string& enumType, const std::string& errExpr)
{
    std::string ownedErr = cType(ownedErrorTypeNode());
    size_t base = _hoisted.size();
    std::string t = emitEnumBoxIntoContract(ownedErr, enumType, errExpr, 0);
    for (size_t i = base; i < _hoisted.size(); ++i) { indent(depth); *_out << _hoisted[i] << "\n"; }
    _hoisted.resize(base);
    return t;
}

// Synthesize an `Optional<elem>` type node (the `.as<T>()` result). Resolves like a user-written
// `Optional<T>` (empty qualifier), so cType mangles it to `Optional_<elem>`.
SharedIdentifier CEmitter::optionalTypeNode(SharedIdentifier elem)
{
    if (!_synthCtx) _synthCtx = std::make_shared<CodeGenContext>(std::make_shared<std::string>("<synth>"));
    auto node = std::make_shared<IdentifierNode>(*_synthCtx, std::make_shared<std::string>("Optional"),
                                                 std::make_shared<StringList>(), elem);
    node->synthesized = true;   // emitter-built: not source text (see ASTNode::synthesized)
    node->genericArgs = std::make_shared<IdentifierList>();
    node->genericArgs->push_back(elem);
    return node;
}


// A nested by-value field, or an `Owned` pointee, whose type is itself a node with edges of its own: it is
// walked INLINE by every pass. A pointee that reaches nothing is an ordinary value (its by-value pair).
bool CEmitter::typeHasGraphAdapters(const std::string& cls) const
{
    auto it = _classes.find(cls);
    return it != _classes.end() && it->second.isGraphNode && it->second.reachesPointer;
}

// The node set (post-computeReachesPointer): a `@generate` type or enum that reaches a Shared/Weak edge — a
// field, or an enum's payload field — and, transitively, every pointee of a node's edge (a contract edge's
// pointees are every nominal `@generate` implementor). Then a node reached only inline loses its synthesized
// by-value `deserialize`, and a root-able one has it retargeted to hand back `Shared<T>`. Records the node
// order, which is each node's wire `typeIndex`.
void CEmitter::computeGraphNodeTypes()
{
    NsCtx saved = _nsCtx;
    std::vector<std::string> work;
    auto seed = [&](const std::string& k) {
        auto it = _classes.find(k);
        if (it == _classes.end() || it->second.isGraphNode) return;
        it->second.isGraphNode = true; work.push_back(k);
    };
    for (auto& kv : _classes) {
        ClassInfo& ci = kv.second;
        // An enum is a node on the same terms as a type: its edges live in variant payloads, which
        // computeReachesPointer already walks. (The prelude's `Optional`/`Result` carry no `@generate`, so the
        // gate keeps them out.)
        if (ci.reachesPointer && (ci.genSerialize || ci.genDeserialize)) seed(kv.first);
    }
    // A PARTICIPANT is not a node — it has no identity, so nothing points at it and it gets no table entry
    // — but its edges are real and their pointees must be nodes. A participant reached as a FIELD is
    // covered by the recursion below; one reached as a ROOT (a bare collection handed to a backend, a
    // hand-written type holding handles) is reached from nowhere, so it is walked here. ⚠️ It is walked
    // WITHOUT being seeded: marking a container `isGraphNode` would make typeHasGraphAdapters answer true
    // for it and the nesting passes would try to walk it as a node.
    std::vector<std::string> roots;
    for (auto& kv : _classes)
        if (graphTwinNeeded(kv.second, true) || graphTwinNeeded(kv.second, false)) roots.push_back(kv.first);

    while (!work.empty() || !roots.empty()) {
        const bool isRoot = work.empty();
        std::string cur = isRoot ? roots.back() : work.back();
        (isRoot ? roots : work).pop_back();
        ClassInfo& ci = _classes[cur];
        _nsCtx = NsCtx{}; _nsCtx.scope = ci.scope; _nsCtx.usings = ci.usings; _nsCtx.symbolAliases = ci.symbolAliases; restoreFileRung(_nsCtx, ci.declFile);
        // Both rejections below are about a FIELD of `ci` and carry that field's line, so they belong to the
        // file that declared `ci`. Whole-program pass — without this they named no file at all. See diagFile().
        ScopedStr _cu(_collectingUnitPath, ci.declFile);
        _typeSubst.clear();
        // The edges of one field. A field is an edge itself (`Shared<Leaf>`), or it CONTAINS them: a
        // participant's edges are its ELEMENTS, which are type arguments rather than fields, so the walk
        // recurses through them. Without that a `DynamicArray<Shared<Leaf>>` field left `Leaf` outside the
        // node set — the owner was a node, the field was walked, and every element was then written inline
        // through the deref because its pointee was not a node.
        std::function<void(SharedIdentifier, const FieldInfo&)> seedField =
            [&](SharedIdentifier ty, const FieldInfo& f) {
            GraphEdge e = graphEdgeOf(ty);
            if (e.kind.empty() || e.elemC.empty()) {
                const std::string fc = cType(ty);
                auto fcit = _classes.find(fc);
                if (fcit == _classes.end() || !fcit->second.reachesPointer) return;
                auto gi = _genericTypeInsts.find(fc);
                if (gi == _genericTypeInsts.end()) return;
                for (auto& a : gi->second.typeArgs) seedField(a, f);
                return;
            }
            if (e.elemIsContract) {   // a `Shared<Contract>` edge: every @generate implementor is a node
                _polyContracts.insert(e.elemC);
                for (auto& kv2 : _classes) {
                    ClassInfo& c2 = kv2.second;
                    if (c2.isGraphNode) continue;
                    // A type that declares `implements Shape` in its own body, not one an impl block supplied —
                    // such a block targets a primitive that can't be a fat-pointer `Shared<Shape>` value.
                    bool impl  = std::find(c2.interfaces.begin(),      c2.interfaces.end(),      e.elemC) != c2.interfaces.end();
                    bool staticOnly = std::find(c2.staticOnlyInterfaces.begin(), c2.staticOnlyInterfaces.end(), e.elemC) != c2.staticOnlyInterfaces.end();
                    if (!impl || staticOnly) continue;
                    if (c2.genSerialize || c2.genDeserialize
                        || graphTwinNeeded(c2, true) || graphTwinNeeded(c2, false)) seed(kv2.first);
                    // A non-@generate implementor has no adapters — at runtime it would flow through the edge
                    // and be SILENTLY dropped from the wire. Reject at the edge field.
                    else unsupported(("`" + kv2.first + "` implements the serialized graph-edge contract `" + e.elemC +
                                      "` but is not `@generate(Serializable/Deserializable)` — it would be silently dropped "
                                      "from the wire; mark it `@generate` or don't route it through a serialized graph "
                                      "edge").c_str(), f.type ? f.type->line : 0);
                }
                return;
            }
            auto it = _classes.find(e.elemC);
            if (it == _classes.end()) return;
            // A pointee is a node if it has a serde half AT ALL — derived or hand-written. `@generate` buys
            // a field walk, which a node needs only if the compiler is the one finding its edges; a
            // hand-written body finds its own, and its four walk helpers are its twin.
            if (it->second.genSerialize || it->second.genDeserialize
                || graphTwinNeeded(it->second, true) || graphTwinNeeded(it->second, false))
                seed(e.elemC);
            else unsupported(("`" + demangleForDisplay(e.elemC) + "` is the pointee of a serialized graph edge (field `" + f.name
                              + "`) but is not `@generate(Serializable/Deserializable)` — a node is written through its own "
                                "adapters; mark it `@generate`, or leave the field out of the wire form with `@skip`").c_str(),
                             f.type ? f.type->line : 0);
        };
        for (auto& f : ci.fields) {
            if (f.serSkip) continue;
            seedField(f.type, f);
        }
        for (auto& v : ci.variants)                         // an enum's edges are its payload fields
            for (auto& f : v.payload) seedField(f.type, f);
        // A participant's own ELEMENTS — its type arguments. A collection's fields are an `UnsafePtr<T>`
        // and bookkeeping, never the element, which is why this has to be asked separately (the same
        // reason computeReachesPointer asks it separately).
        if (isRoot && !ci.fields.empty()) {
            auto gi = _genericTypeInsts.find(cur);
            if (gi != _genericTypeInsts.end())
                for (auto& a : gi->second.typeArgs) seedField(a, ci.fields.front());
        }
    }
    _nsCtx = saved; _typeSubst.clear();
    regateGenericInstances();
    _graphNodeOrder.clear();
    for (auto& kv : _classes) {
        ClassInfo& ci = kv.second;
        if (!ci.isGraphNode) continue;
        ci.graphTypeId = (int)_graphNodeOrder.size();
        _graphNodeOrder.push_back(kv.first);
        // A node keeps the same two members a by-value type has — so `serializeJsonBuffer(v: root)` and
        // `deserializeJsonBuffer::<Shared<Node>>(src: …)` are the ordinary entry points, with no wrapper
        // type and no ceremony. Only the READ's result changes: a graph comes back as a HANDLE, because a
        // cycle cannot be returned by value. `serialize` needs no retarget — writing borrows.
        auto it = ci.methods.find("deserialize");
        if (it == ci.methods.end() || !it->second.returnType
            || !it->second.returnType->genericArgs || it->second.returnType->genericArgs->empty()) continue;
        // A node's read half is the derive's OR a hand-written body's. The two are retargeted differently
        // and that difference is forced, not chosen: a derive's `Result<This, …>` is rewritten in place to
        // `Result<Shared<This>, …>`, and there is no rewriting a body whose `return` constructs a `This`.
        // So a hand-written node keeps its signature — which is what `K____readInto` fills a shell with —
        // and the `Shared<K>` root gets a synthesized entry point of its own.
        const bool synthDe = it->second.isSynthDe;
        const bool handDe  = graphTwinNeeded(ci, /*write=*/false);
        if (!synthDe && !handDe) continue;
        SharedIdentifier inner = it->second.returnType->genericArgs->at(0);   // This — the Result's Ok arm
        SharedIdentifier sh = sharedTypeNode(inner);                          // Shared<This>
        _nsCtx = NsCtx{}; _nsCtx.scope = ci.scope; _nsCtx.usings = ci.usings;
        _nsCtx.symbolAliases = ci.symbolAliases; restoreFileRung(_nsCtx, ci.declFile);
        // ⚠️ A node reached only INLINE — a by-value part, or an `Owned` pointee — has no `Shared<X>`
        // anywhere in the program, so it can never BE a root: there is no spelling that would call its
        // driver. It keeps `K____readInto`, which is how its owner reads it, and loses the synthesized
        // `deserialize` entirely. Leaving the by-value one in place was wrong in a way the C compiler
        // caught rather than kama: its `Shared<Leaf>` field took the composite arm and emitted a call to
        // `Shared_Leaf__deserialize`, which nothing defines (`ser_graph_nested_reach`, measured). Minting
        // the monomorph here instead is too late — the instance would have no bodies emitted.
        if (!_classes.count(cType(sh))) {
            // ⚠️ Only a SYNTHESIZED pair may be taken away — it is the compiler's. A hand-written
            // `deserialize` is the author's code; an inline-only hand-written node simply gets no root
            // entry point, which is exactly right because nothing can spell one.
            if (handDe) { _nsCtx = saved; continue; }
            ci.methods.erase("deserialize");
            ci.ctors.erase("deserialize");
            const std::string d = pinnedInstanceName("Deserializable", ci.name);
            ci.interfaces.erase(std::remove(ci.interfaces.begin(), ci.interfaces.end(), d), ci.interfaces.end());
            _nsCtx = saved;
            continue;
        }
        {
            SharedIdentifier handleRet = resultOwnedErrorTypeNode(sh);   // Result<Shared<This>, Owned<Error>>
            if (synthDe) it->second.returnType = handleRet;              // the derive's, rewritten in place
            scanTypeForCollections(handleRet);
            ci.graphDeserialize = true;
            // `deserializeJsonBuffer::<Shared<Node>>(…)` calls `T.deserialize(r)` on `T = Shared<Node>`, and
            // the function that actually reads a graph is the NODE's. Point `Shared<Node>`'s `deserialize`
            // straight at it rather than special-casing the call site — and mark it abstract, so neither a
            // prototype nor a body is emitted for a name that already exists. (`satisfiesBound` answers the
            // matching bound the same way, by identity; neither is a method ON the handle.)
            ClassInfo& sc = _classes[cType(sh)];
            if (!sc.methods.count("deserialize")) {
                MethodInfo fwd;
                fwd.cName = ci.name + (synthDe ? "__deserialize" : "__deserializeRoot");
                fwd.visibility = Visibility::Public;
                fwd.isStatic = true; fwd.isCtor = true; fwd.isAbstract = true;
                fwd.returnType = handleRet;
                ParamSig r; r.name = "r"; r.byRef = false; r.className = "Deserializer";
                fwd.params.push_back(r);
                sc.methods["deserialize"] = fwd;
                sc.ctors["deserialize"] = CtorInfo{ nullptr, fwd.params, Visibility::Public, true, fwd.returnType };
            }
        }
        _nsCtx = saved;
    }
}

// The READ half of "an `Owned` subtree IS its pointee". The write half needs nothing: emitSerFieldWrite
// walks THROUGH the handle (ownedPointeeOf) and writes the pointee inline, so a container of `Owned<X>`
// already satisfies its own `when [T: Serializable]` gate and writes correct bytes. The read half has
// nowhere to land: a container's `deserialize` calls `T.deserialize(r)`, and with `T = Owned<X>` there is
// nothing to call, because the triad is METHOD-FREE and must stay so — a domain method on a handle shadows
// the pointee's through the deref fallback.
//
// `deserialize` is the one member that can be added without reopening that: it is a STATIC ctor, reached
// only dot-on-TYPE (`emitDotOnTypeCtorCall`), so it has no instance receiver to shadow — unlike `serialize`,
// whose instance form is exactly what `43dd3dd` had to revert.
//
// ⚠️ Registered EAGERLY, before the destructibility fixpoint, and pruned by pruneOwnedDeserialize once the
// node set is known — the same shape the graph adapters use, and for a measured reason: the `Result<Owned<X>,
// Owned<Error>>` this mints must exist BEFORE computeDestructible, or the fixpoint never marks it move-only
// and the container's own `match (give __er)` is refused as "a plain value, copied on assignment". So the
// graph pointee cannot be excluded here (`graphDeserialize` is settled later); it is pruned instead.
void CEmitter::registerOwnedDeserialize()
{
    std::vector<std::string> boxes;                                     // collect first: the loop below writes _classes
    for (auto& kv : _classes) if (!ownedPointeeClass(kv.first).empty()) boxes.push_back(kv.first);
    for (const std::string& oc : boxes) {
        ClassInfo& bc = _classes[oc];
        if (bc.methods.count("deserialize")) continue;                  // hand-written or already registered
        auto p = _classes.find(ownedPointeeClass(oc));
        if (p == _classes.end()) continue;
        if (!p->second.methods.count("deserialize")) continue;          // nothing to box
        // `adopt` is what takes the raw block. It exists only `when [A: default]`, so a stateful-allocator
        // box has none — and the wire carries no allocator handle to rebuild one from. Registering nothing
        // leaves the ordinary "has no constructor `deserialize`" refusal, which is the honest answer.
        ClassInfo* ao = nullptr;
        if (!findMethod(&bc, "adopt", &ao)) continue;
        auto gi = _genericTypeInsts.find(oc);
        if (gi == _genericTypeInsts.end() || gi->second.typeArgs.empty()) continue;
        MethodInfo mi;
        mi.cName = oc + "__deserialize";
        mi.visibility = Visibility::Public;
        mi.isStatic = true; mi.isCtor = true; mi.isSynthDe = true;
        mi.returnType = resultOwnedErrorTypeNode(ownedTypeNode(gi->second.typeArgs[0]));
        scanTypeForCollections(mi.returnType);                          // monomorphize Result<Owned<X>, Owned<Error>>
        ParamSig r; r.name = "r"; r.byRef = false; r.className = "Deserializer";
        mi.params.push_back(r);
        bc.methods["deserialize"] = mi;
        bc.ctors["deserialize"] = CtorInfo{ nullptr, mi.params, Visibility::Public, true, mi.returnType };
        bc.ownedBoxDe = true;   // …and the mark the body fork and the prune below read
    }
}

// The `Result<Shared<X>, Owned<Error>>` a container's element read BINDS — `Result<T, Owned<Error>> __er =
// T.deserialize(r: r)` in every container's own `deserialize`. Nothing mints it during collection: the
// member walk registers signatures, not body locals, and the only other site is computeGraphNodeTypes,
// which runs after the destructibility fixpoint. So the monomorph existed unjudged, `ownsByValue` answered
// false for it, and the container's own `match (give __er)` was refused as "a plain value, copied on
// assignment" — which is why `DynamicArray<Shared<X>>` has never had a read half for ANY `X`, graph or not.
// Minted here, beside the `Owned` box read, for the same reason: before the fixpoint, so it is judged.
void CEmitter::registerEdgeElementResults()
{
    NsCtx saved = _nsCtx;
    std::vector<std::string> insts;
    for (auto& kv : _classes)
        if (kv.second.isGenericInst && kv.second.methods.count("deserialize")) insts.push_back(kv.first);
    for (const std::string& cls : insts) {
        auto gi = _genericTypeInsts.find(cls);
        if (gi == _genericTypeInsts.end()) continue;
        ClassInfo& ci = _classes[cls];
        _nsCtx = _genericTypeInstCtx.count(cls) ? _genericTypeInstCtx[cls]
                                                : _genericTypeCtx[gi->second.templateKey];
        (void)ci;
        for (auto& a : gi->second.typeArgs) {
            auto t = _genericTypeInstOf.find(cType(a));
            if (t == _genericTypeInstOf.end()) continue;
            if (t->second != _sharedTmpl && t->second != _weakTmpl) continue;   // `Owned` has its own pass
            scanTypeForCollections(resultOwnedErrorTypeNode(a));
        }
    }
    _nsCtx = saved;
}

// The late half of the pair above: re-judge the registration against the PRUNED world and take back every
// box the graph pass invalidated. Two ways it can: the pointee became a graph node, whose `deserialize`
// hands back `Result<Shared<X>, …>` and is not an `Owned<X>` at all (such an `Owned` is walked INLINE by the
// graph passes instead — graphNestOf answers {"owned", X}); or the pointee LOST its by-value pair outright,
// which computeGraphNodeTypes does to every node that reaches a pointer. ⚠️ The second is not a corollary of
// the first — measured on `ser_graph_nested_reach`, where a serialize-only node leaves `graphDeserialize`
// false and still has no `deserialize` to call, so a box read emitted a call to a symbol nothing defines.
void CEmitter::pruneOwnedDeserialize()
{
    for (auto& kv : _classes) {
        ClassInfo& bc = kv.second;
        if (!bc.ownedBoxDe) continue;
        auto p = _classes.find(ownedPointeeClass(kv.first));
        if (p != _classes.end() && p->second.methods.count("deserialize") && !p->second.graphDeserialize)
            continue;                    // still a by-value pointee: the box read stands
        bc.methods.erase("deserialize");
        bc.ctors.erase("deserialize");   // both maps, for the reason regateGenericInstances erases both
        bc.ownedBoxDe = false;
    }
}

// After the prune, a generic instance registered DURING collection may hold a conditional member or
// conformance whose bound no longer holds — `Owned<Inner> implements Serializable when [T: Serializable]`,
// where `Inner` turned out to be a graph node and lost its by-value pair — and its body would then call a
// method nothing defines. Re-judge every instance's `when` gates against the pruned world and drop what
// fails. Never add: the prune only ever removes, so a bound that failed at registration still fails.
void CEmitter::regateGenericInstances()
{
    NsCtx saved = _nsCtx;
    std::map<std::string, SharedIdentifier> savedSubst = _typeSubst;
    for (auto& kv : _genericTypeInsts) {
        const GenericTypeInst& gi = kv.second;
        auto ci = _classes.find(gi.mangledName);
        auto ti = _genericTypes.find(gi.templateKey);
        if (ci == _classes.end() || ti == _genericTypes.end()) continue;
        const std::vector<std::string>& params = _genericTypeParams[gi.templateKey];
        const std::vector<SharedIdentifier>& concrete = gi.typeArgs;
        _nsCtx = _genericTypeCtx[gi.templateKey];
        _typeSubst.clear();
        for (size_t i = 0; i < params.size() && i < concrete.size(); ++i) _typeSubst[params[i]] = concrete[i];
        ClassInfo& inst = ci->second;
        for (auto& mkv : ti->second.methods) {
            const MethodInfo& tm = mkv.second;
            if (tm.whenParams.empty() || !inst.methods.count(mkv.first)) continue;
            if (whenConditionsHold(tm.whenParams, tm.whenBounds, tm.whenBoundNodes, params, concrete)) continue;
            inst.methods.erase(mkv.first);
            inst.ctors.erase(mkv.first);
        }
        if (ti->second.baseTypesDecl() && ti->second.baseTypesDecl()->interfaces) {
            ScopedStr  _ts(_thisType, gi.mangledName);
            ScopedThis _tt(_typeSubst, synthId(gi.mangledName));
            for (auto& itf : *ti->second.baseTypesDecl()->interfaces) {
                if (!itf || !itf->value || !itf->whenParams || itf->whenParams->empty()) continue;
                std::vector<std::string> wp, wb;
                std::vector<SharedIdentifier> wn;
                for (size_t c = 0; c < itf->whenParams->size(); ++c) {
                    auto& p = (*itf->whenParams)[c];
                    auto& b = itf->whenBounds ? (*itf->whenBounds)[c] : p;
                    wp.push_back(p && p->value ? *p->value : "");
                    wb.push_back(resolveWhenBound(b));
                    wn.push_back(b);
                }
                if (whenConditionsHold(wp, wb, wn, params, concrete)) continue;
                std::string base = resolveUserName(*itf->value, itf->qualifier);
                if (itf->genericArg && _genericContracts.count(base)) base = genericTypeMangle(base, itf->genericArgs);
                inst.interfaces.erase(std::remove(inst.interfaces.begin(), inst.interfaces.end(), base), inst.interfaces.end());
            }
        }
    }
    _nsCtx = saved; _typeSubst = savedSubst;
}

// ---- prototypes ------------------------------------------------------------------------------------------
// A node's walk helpers, in the shared header so cross-referencing nodes link. These are INTERNAL C
// functions, not members: nothing about them appears on the kama type, and a program that serializes no
// graph gets none of them. They take the substrate structs directly (kama_runtime.h) — the walker is the
// compiler's, so there is no contract in between and nothing to erase through.
void CEmitter::emitGraphNodeHelperProtos(ClassInfo& ci)
{
    const char* stat = _emitStaticClass ? "static inline " : "";
    const std::string& K = ci.name;
    if (graphNodeWrites(ci)) {
        *_out << stat << "void " << K << "__visitEdges(" << K << "* self, struct kama_ser_graph* g);\n";
        *_out << stat << "void " << K << "__writeNode(" << K << "* self, Serializer* w, struct kama_ser_graph* g);\n";
    }
    if (graphNodeReads(ci)) {
        *_out << stat << "void " << K << "__wireEdges(" << K << "* self, struct kama_de_graph* g);\n";
        *_out << stat << "void " << K << "____readInto(" << K << "* self, Deserializer r, struct kama_de_graph* g);\n";
    }
}

// ---- per-contract resolvers + the shell reader chain ----------------------------------------------------
// Emitted once into the shared header, after the class prototypes and the `extern const <K>__as_<C>` decls.
// A contract-typed edge (`Shared<Shape>`) erases its pointee, and both passes need the concrete back. Both
// crossings are a CLOSED-WORLD table keyed on the node type id — the same tag the wire carries — so neither
// needs a contract of its own:
//   `<C>__graphTypeId`  (write): a fat handle's runtime `.vtbl` -> the pointee's node type id, or NO_NODE.
//   `<C>__graphImplVtbl` (read): a shell's node type id -> that concrete's `&<K>__as_<C>`, NULL for a
//                                non-implementor, which is a TypeMismatch on a forged wire.
// Then `__kama_graph_readShell`, the one closed-world dispatch in the program: a wire `type` selector
// (a name, or an index for the index backends) to a freshly allocated, scalar-filled shell of that type.
void CEmitter::emitPolyContractResolvers()
{
    *_out << "#define KAMA_GRAPH_NO_NODE 0xFFFFFFFFu\n";
    for (auto& C : _polyContracts) {
        std::vector<std::string> impls;   // implementors that are graph nodes, in stable _graphNodeOrder
        for (auto& K : _graphNodeOrder) {
            ClassInfo& ci = _classes[K];
            bool impl  = std::find(ci.interfaces.begin(),      ci.interfaces.end(),      C) != ci.interfaces.end();
            bool staticOnly = std::find(ci.staticOnlyInterfaces.begin(), ci.staticOnlyInterfaces.end(), C) != ci.staticOnlyInterfaces.end();
            if (impl && !staticOnly) impls.push_back(K);
        }
        *_out << "static inline uint32_t " << C << "__graphTypeId(const struct " << C << "_vtbl* __vt)\n{\n";
        for (auto& K : impls) if (graphNodeWrites(_classes[K])) { indent(1); *_out << "if (__vt == &" << K << "__as_" << C << ") return " << _classes[K].graphTypeId << "u;\n"; }
        indent(1); *_out << "return KAMA_GRAPH_NO_NODE;\n}\n";
        *_out << "static inline const struct " << C << "_vtbl* " << C << "__graphImplVtbl(uint32_t __tid)\n{\n";
        for (auto& K : impls) if (graphNodeReads(_classes[K])) { indent(1); *_out << "if (__tid == " << _classes[K].graphTypeId << "u) return &" << K << "__as_" << C << ";\n"; }
        indent(1); *_out << "return 0;\n}\n\n";
    }
    bool anyReader = false;
    for (auto& K : _graphNodeOrder) if (graphNodeReads(_classes[K])) { anyReader = true; break; }
    if (!anyReader) return;
    *_out << "static inline kama_de_box* __kama_graph_readShell(FieldKey which, Deserializer r, struct kama_de_graph* g)\n{\n";
    indent(1); *_out << "int32_t __slot = -1;\n";
    indent(1); *_out << "if (which.tag == FieldKey_Name) {\n";
    bool first = true;
    for (auto& K : _graphNodeOrder) {
        if (!graphNodeReads(_classes[K])) continue;
        indent(2); *_out << (first ? "if" : "else if") << " (kama_string__equals(&which.u.Name.name, "
                         << kamaStrLit(graphWireName(_classes[K])) << ")) __slot = " << _classes[K].graphTypeId << ";\n";
        first = false;
    }
    indent(1); *_out << "} else if (which.tag == FieldKey_Id) { __slot = (int32_t)which.u.Id.id; }\n";
    indent(1); *_out << "else { __slot = (int32_t)which.u.Position.rank; }\n";
    indent(1); *_out << "FieldKey__dtor(&which);\n";
    indent(1); *_out << "kama_de_box* __b = 0;\n";
    indent(1); *_out << "switch (__slot) {\n";
    for (auto& K : _graphNodeOrder) {
        if (!graphNodeReads(_classes[K])) continue;
        indent(1); *_out << "case " << _classes[K].graphTypeId << ": {\n";
        indent(2); *_out << K << "* __obj = (" << K << "*)kama_alloc_zeroed(" << layoutOf(K) << ");\n";
        indent(2); *_out << "if (!__obj) kama_panic(kama_string_lit(\"out of memory\", 13));\n";
        indent(2); *_out << K << "____readInto(__obj, r, g);\n";
        indent(2); *_out << "__b = (kama_de_box*)kama_alloc(" << layoutOf("kama_de_box") << ");\n";
        indent(2); *_out << "if (!__b) kama_panic(kama_string_lit(\"out of memory\", 13));\n";
        indent(2); *_out << "__b->ptr = (void*)__obj; __b->ctrl = kama_ctrl_new(); __b->type_id = " << _classes[K].graphTypeId << "u;\n";
        indent(2); *_out << "break;\n";
        indent(1); *_out << "}\n";
    }
    indent(1); *_out << "default: break;\n";
    indent(1); *_out << "}\n";
    indent(1); *_out << "return __b;\n";
    *_out << "}\n\n";
    // Drop one shell's CONSTRUCTION-strong reference and free its box. Every shell gets exactly one of
    // these on the way out, so a node the root reaches survives on the reference the root took and a node
    // nothing reaches — which is what a forged or cyclic-but-unreachable wire produces — is freed here.
    *_out << "static inline void __kama_graph_dropBox(kama_de_box* __b)\n{\n";
    indent(1); *_out << "if (!__b) return;\n";
    indent(1); *_out << "if (__b->ctrl && --__b->ctrl->strong == 0) {\n";
    indent(2); *_out << "if (__b->ptr) {\n";
    // Each node type is freed in its own case: the block goes back with the layout readShell allocated it with.
    indent(3); *_out << "switch (__b->type_id) {\n";
    for (auto& K : _graphNodeOrder) {
        if (!graphNodeReads(_classes[K])) continue;
        indent(3); *_out << "case " << _classes[K].graphTypeId << "u: ";
        if (_classes[K].destructible) *_out << K << "__dtor((" << K << "*)__b->ptr); ";
        *_out << "kama_free(__b->ptr, " << layoutOf(K) << "); break;\n";
    }
    indent(3); *_out << "default: break;\n";
    indent(3); *_out << "}\n";
    indent(2); *_out << "}\n";
    indent(2); *_out << "if (__b->ctrl->weak == 0) kama_free(__b->ctrl, " << layoutOf("kama_ctrl") << ");\n";
    indent(1); *_out << "}\n";
    indent(1); *_out << "kama_free(__b, " << layoutOf("kama_de_box") << ");\n";
    *_out << "}\n\n";
}

// ---- one field, per pass ---------------------------------------------------------------------------------

static bool graphOptional(SharedIdentifier ty) { return ty && ty->value && *ty->value == "Optional" && ty->genericArg; }

// A field that is walked INLINE: "node" (a by-value field whose type is a node with edges) or "owned" (an
// `Owned<X>` whose pointee is), with the pointee's C type; "" for an ordinary value field. A type that
// reaches a pointer without being a node is a defect the author can fix (reported by writeNode/readInto).
std::pair<std::string, std::string> CEmitter::graphNestOf(SharedIdentifier inner)
{
    std::string ic = cType(inner);
    auto g = _genericTypeInstOf.find(ic);
    std::string x = ic;
    bool owned = false;
    if (g != _genericTypeInstOf.end() && g->second == _ownedTmpl) { owned = true; x = inner->genericArg ? cType(inner->genericArg) : ""; }
    auto it = _classes.find(x);
    if (it == _classes.end() || !it->second.reachesPointer) return { "", "" };
    return { owned ? "owned" : "node", x };
}

void CEmitter::emitGraphFieldVisit(SharedIdentifier ty, const std::string& access, int depth)
{
    ty = deepSubstType(ty);
    if (graphOptional(ty)) {
        std::string oc = cType(ty);
        indent(depth); *_out << "if ((" << access << ").tag == " << oc << "_Some) {\n";
        emitGraphFieldVisit(ty->genericArg, "(" + access + ").u.Some.value", depth + 1);
        indent(depth); *_out << "}\n";
        return;
    }
    GraphEdge e = graphEdgeOf(ty);
    if (!e.kind.empty()) { graphInternExpr(e, access, depth); return; }
    // A PARTICIPANT field — a container of edges, or a hand-written type holding them. Its edges are not
    // fields, so there is nothing to walk: run its own body against the discard sink and let the edges
    // intern on the way through. Any error is dropped here; the real write reports it.
    if (emitGraphParticipantCall(ty, access, depth, /*sink=*/true)) return;
    auto nest = graphNestOf(ty);
    if (nest.first.empty()) return;
    if (!typeHasGraphAdapters(nest.second)) return;   // reported once, by writeNode
    indent(depth); *_out << nest.second << "__visitEdges(" << (nest.first == "owned" ? "(" + access + ").p" : "&(" + access + ")") << ", g);\n";
}

// A field whose type carries the graph through its own body: emit that call, against either the discard
// sink (discovery) or the caller's writer (the real write). Answers false when the field is not a
// participant, so both callers fall through to the by-value handling they had. Errors are dropped rather
// than propagated — every caller is a `void` walker helper, and the sink's sticky flag carries a real
// failure out to the driver, which is where the fallible boundary is.
bool CEmitter::emitGraphParticipantCall(SharedIdentifier ty, const std::string& access, int depth, bool sink)
{
    const std::string fc = cType(ty);
    auto it = _classes.find(fc);
    if (it == _classes.end() || !graphTwinNeeded(it->second, /*write=*/true)) return false;
    const std::string resC = cType(resultUnitOwnedErrorTypeNode());
    const std::string t = "__gp" + std::to_string(_tempCounter++);
    indent(depth); *_out << "{\n";
    if (sink) { indent(depth + 1); *_out << "Serializer " << t << "s = __kama_null_serializer();\n"; }
    indent(depth + 1); *_out << resC << " " << t << " = " << fc << "__serializeInto(&(" << access << "), "
                             << (sink ? "&" + t + "s" : "w") << ", g);\n";
    indent(depth + 1); *_out << "if (" << t << ".tag == " << resC << "_Err) { "
                             << cType(ownedErrorTypeNode()) << "__dtor(&" << t << ".u.Err.error); }\n";
    indent(depth); *_out << "}\n";
    return true;
}

// Intern one edge value (a `Shared`/`Weak` struct expression) and answer the temp holding its id — 0 for an
// expired Weak. The handle passed to `intern` is RETAINED (strong++): the walker owns it for the walk.
std::string CEmitter::graphInternExpr(const GraphEdge& e, const std::string& val, int depth)
{
    std::string t = "__gid" + std::to_string(_tempCounter++);
    std::string obj = e.elemIsContract ? "(" + val + ").obj" : "(void*)(" + val + ").p";
    std::string ctl = e.elemIsContract ? "(" + val + ").ctrl" : "(kama_ctrl*)(" + val + ").c";
    std::string tid = e.elemIsContract ? (e.elemC + "__graphTypeId((" + val + ").vtbl)")
                                       : (std::to_string(_classes[e.elemC].graphTypeId) + "u");
    indent(depth); *_out << "uint64_t " << t << " = 0;\n";
    // A null control block is an empty handle; an EXPIRED `Weak` (strong == 0) has a live control block and a
    // dead pointee, so it must not be interned either — it writes 0, which reads back as expired.
    indent(depth); *_out << "if (" << ctl << (e.kind == "Weak" ? " && " + ctl + "->strong > 0" : "") << ") {\n";
    indent(depth + 1); *_out << "uint32_t __tid = " << tid << ";\n";
    // The worklist BORROWS: the caller's root handle keeps the whole graph alive across a read-only write
    // traversal, so nothing is retained here and nothing has to be released on the way out.
    indent(depth + 1); *_out << "if (__tid != KAMA_GRAPH_NO_NODE) " << t
                             << " = kama_ser_graph_intern(g, (uint64_t)(uintptr_t)" << obj << ", __tid);\n";
    indent(depth); *_out << "}\n";
    return t;
}

void CEmitter::emitGraphFieldWrite(SharedIdentifier ty, const std::string& access, int depth)
{
    ty = deepSubstType(ty);
    if (graphOptional(ty)) {
        std::string oc = cType(ty);
        indent(depth); *_out << "switch ((" << access << ").tag) {\n";
        indent(depth); *_out << "case " << oc << "_Some: {\n";
        indent(depth + 1); *_out << "w->vtbl->writeSome(w->obj);\n";
        emitGraphFieldWrite(ty->genericArg, "(" + access + ").u.Some.value", depth + 1);
        indent(depth + 1); *_out << "break;\n";
        indent(depth); *_out << "}\n";
        indent(depth); *_out << "case " << oc << "_None: { w->vtbl->writeNull(w->obj); break; }\n";
        indent(depth); *_out << "default: break;\n";
        indent(depth); *_out << "}\n";
        return;
    }
    GraphEdge e = graphEdgeOf(ty);
    if (!e.kind.empty()) {
        std::string t = graphInternExpr(e, access, depth);
        indent(depth); *_out << "w->vtbl->writeU64(w->obj, " << t << ");\n";
        return;
    }
    // …and the real write of that same participant: its own body, this time against the caller's sink,
    // with every edge element writing the id it interned during discovery.
    if (emitGraphParticipantCall(ty, access, depth, /*sink=*/false)) return;
    auto nest = graphNestOf(ty);
    if (!nest.first.empty()) {
        if (!typeHasGraphAdapters(nest.second)) {
            // ⚠️ A smart pointer is NOT a collection, and this used to call one that: the test below
            // matched any generic instance without a derive, which `Shared<X>` is. The shape that actually
            // lands here is an `Owned` whose POINTEE is itself an edge — a box holding a handle — since a
            // real collection of edges is walked through its own body before this point.
            const bool boxedEdge = isSharedOrWeakClass(nest.second);
            if (boxedEdge)
                unsupported(("field `" + serdeFieldName(access) + "` is an `Owned` whose POINTEE is itself a graph edge "
                             "(`Owned<Shared<X>>`), and a box around a handle has no wire form — the box owns "
                             "uniquely and the handle shares, so the two cannot both be true of one pointee. "
                             "Hold the `Shared<X>` directly, or box the NODE (`Owned<X>`), or leave the field "
                             "out of the wire form with `@skip`").c_str(), ty ? ty->line : 0);
            else unsupported(("`" + demangleForDisplay(nest.second) + "` reaches a `Shared`/`Weak` field, so it is a graph node — but it has no "
                              "`Serializable` half, so its edges cannot be written; give it one with `@generate(Serializable)` or by hand, "
                              "or leave the field out of the wire form with `@skip`").c_str(), ty ? ty->line : 0);
            return;
        }
        indent(depth); *_out << nest.second << "__writeNode(" << (nest.first == "owned" ? "(" + access + ").p" : "&(" + access + ")") << ", w, g);\n";
        return;
    }
    emitSerFieldWrite(ty, access, depth, "");   // an ordinary value field — sticky-only context
}

void CEmitter::emitGraphFieldRead(SharedIdentifier ty, const std::string& dst, int depth)
{
    ty = deepSubstType(ty);
    if (graphOptional(ty)) {
        SharedIdentifier inner = ty->genericArg;
        GraphEdge e = graphEdgeOf(inner);
        auto nest = graphNestOf(inner);
        if (e.kind.empty() && nest.first.empty()) { emitDeFieldRead(ty, dst, depth, "", ""); return; }
        std::string oc = cType(ty);
        indent(depth); *_out << "if (r.vtbl->readNull(r.obj)) { " << dst << " = (" << oc << "){ .tag = " << oc << "_None }; }\n";
        indent(depth); *_out << "else {\n";
        std::string tmp = "__gv" + std::to_string(_tempCounter++);
        indent(depth + 1); *_out << cType(inner) << " " << tmp << " = {0};\n";
        emitGraphFieldRead(inner, tmp, depth + 1);
        indent(depth + 1); *_out << dst << " = (" << oc << "){ .tag = " << oc << "_Some, .u.Some = { .value = " << tmp << " } };\n";
        indent(depth); *_out << "}\n";
        return;
    }
    GraphEdge e = graphEdgeOf(ty);
    if (!e.kind.empty()) {   // pass 1: read the id, STASH it in the pointer slot, control block NULL
        indent(depth); *_out << "{ uint64_t __rid = r.vtbl->readU64(r.obj); ";
        if (e.elemIsContract) *_out << "(" << dst << ").obj = (void*)(uintptr_t)__rid; (" << dst << ").vtbl = NULL; (" << dst << ").ctrl = NULL; }\n";
        else                  *_out << "(" << dst << ").p = (" << e.elemC << "*)(uintptr_t)__rid; (" << dst << ").c = NULL; }\n";
        return;
    }
    // A PARTICIPANT field, read through its own body with the graph threaded — the mirror of the write.
    {
        const std::string fc = cType(ty);
        auto it = _classes.find(fc);
        if (it != _classes.end() && graphTwinNeeded(it->second, /*write=*/false)) {
            const std::string innerRes = cType(resultOwnedErrorTypeNode(ty));
            const std::string t = "__gr" + std::to_string(_tempCounter++);
            indent(depth); *_out << innerRes << " " << t << " = " << fc << "__deserializeFrom(r, g);\n";
            indent(depth); *_out << "if (" << t << ".tag == " << innerRes << "_Ok) " << dst << " = " << t
                                 << ".u.Ok.value;\n";
            indent(depth); *_out << "else { " << cType(ownedErrorTypeNode()) << "__dtor(&" << t
                                 << ".u.Err.error); kama_de_graph_fail(g, DeError_Malformed); }\n";
            return;
        }
    }
    auto nest = graphNestOf(ty);
    if (!nest.first.empty()) {
        if (!typeHasGraphAdapters(nest.second)) {
            // ⚠️ A smart pointer is NOT a collection, and this used to call one that: the test below
            // matched any generic instance without a derive, which `Shared<X>` is. The shape that actually
            // lands here is an `Owned` whose POINTEE is itself an edge — a box holding a handle — since a
            // real collection of edges is walked through its own body before this point.
            const bool boxedEdge = isSharedOrWeakClass(nest.second);
            if (boxedEdge)
                unsupported(("field `" + serdeFieldName(dst) + "` is an `Owned` whose POINTEE is itself a graph edge "
                             "(`Owned<Shared<X>>`), and a box around a handle has no wire form — the box owns "
                             "uniquely and the handle shares, so the two cannot both be true of one pointee. "
                             "Hold the `Shared<X>` directly, or box the NODE (`Owned<X>`), or leave the field "
                             "out of the wire form with `@skip`").c_str(), ty ? ty->line : 0);
            else unsupported(("`" + demangleForDisplay(nest.second) + "` reaches a `Shared`/`Weak` field, so it is a graph node — but it has no "
                              "`Deserializable` half, so its edges cannot be read; give it one with `@generate(Deserializable)` or by hand, "
                              "or leave the field out of the wire form with `@skip`").c_str(), ty ? ty->line : 0);
            return;
        }
        if (nest.first == "owned") {
            indent(depth); *_out << "(" << dst << ").p = (" << nest.second << "*)kama_alloc_zeroed(" << layoutOf(nest.second) << ");\n";
            indent(depth); *_out << nest.second << "____readInto((" << dst << ").p, r, g);\n";
        } else {
            indent(depth); *_out << nest.second << "____readInto(&(" << dst << "), r, g);\n";
        }
        return;
    }
    emitDeFieldRead(ty, dst, depth, "", "");   // an ordinary value field — sticky-only context
}

void CEmitter::emitGraphFieldWire(SharedIdentifier ty, const std::string& dst, int depth)
{
    ty = deepSubstType(ty);
    if (graphOptional(ty)) {
        SharedIdentifier inner = ty->genericArg;
        GraphEdge e = graphEdgeOf(inner);
        auto nest = graphNestOf(inner);
        if (e.kind.empty() && nest.first.empty()) return;
        std::string oc = cType(ty);
        indent(depth); *_out << "if ((" << dst << ").tag == " << oc << "_Some) {\n";
        emitGraphFieldWire(inner, "(" + dst + ").u.Some.value", depth + 1);
        indent(depth); *_out << "}\n";
        return;
    }
    GraphEdge e = graphEdgeOf(ty);
    if (!e.kind.empty()) {   // pass 2: the stash becomes a retained handle
        std::string X = e.elemC;
        std::string slot = e.elemIsContract ? "(" + dst + ").obj" : "(" + dst + ").p";
        const char* cnt = (e.kind == "Weak") ? "weak" : "strong";
        indent(depth); *_out << "{ uint64_t __rid = (uint64_t)(uintptr_t)" << slot << "; " << slot << " = NULL;\n";
        indent(depth + 1); *_out << "if (__rid != 0) {\n";
        indent(depth + 2); *_out << "kama_de_box* __t = kama_de_graph_lookup(g, __rid);\n";
        indent(depth + 2); *_out << "if (!__t) kama_de_graph_fail(g, DeError_UnresolvedReference);\n";
        indent(depth + 2); *_out << "else {\n";
        if (e.elemIsContract) {
            indent(depth + 3); *_out << "const struct " << X << "_vtbl* __vt = " << X << "__graphImplVtbl(__t->type_id);\n";
            indent(depth + 3); *_out << "if (!__vt) kama_de_graph_fail(g, DeError_TypeMismatch);\n";
            indent(depth + 3); *_out << "else { (" << dst << ").obj = __t->ptr; (" << dst << ").vtbl = __vt; (" << dst << ").ctrl = __t->ctrl; __t->ctrl->" << cnt << "++; }\n";
        } else {
            indent(depth + 3); *_out << "if (__t->type_id != " << _classes[X].graphTypeId << "u) kama_de_graph_fail(g, DeError_TypeMismatch);\n";
            indent(depth + 3); *_out << "else { (" << dst << ").p = (" << X << "*)__t->ptr; (" << dst << ").c = (void*)__t->ctrl; __t->ctrl->" << cnt << "++; }\n";
        }
        indent(depth + 2); *_out << "}\n";
        indent(depth + 1); *_out << "}\n";
        // A `Shared` is never null: an id of 0 under one is a forged wire. A `Weak` at 0 is simply expired.
        if (e.kind == "Shared") { indent(depth + 1); *_out << "else kama_de_graph_fail(g, DeError_UnresolvedReference);\n"; }
        indent(depth); *_out << "}\n";
        return;
    }
    // A PARTICIPANT field: its elements are not fields, so pass 2 iterates them. See emitGraphWireElements.
    {
        const std::string fc = cType(ty);
        auto it = _classes.find(fc);
        if (it != _classes.end() && graphWireElementsNeeded(it->second)) {
            indent(depth); *_out << fc << "__wireParts(&(" << dst << "), g);\n";
            return;
        }
    }
    auto nest = graphNestOf(ty);
    if (nest.first.empty() || !typeHasGraphAdapters(nest.second)) return;   // reported by readInto
    indent(depth); *_out << nest.second << "__wireEdges(" << (nest.first == "owned" ? "(" + dst + ").p" : "&(" + dst + ")") << ", g);\n";
}

// ---- bodies ----------------------------------------------------------------------------------------------
// `K____readInto`: pass 1 of the graph read for ONE node — the keyed field loop every by-value derive has,
// with an edge field stashing its id and a nested node read in place. Shared by the shell reader chain (into
// a fresh calloc'd block) and by an owner walking a nested node or `Owned` pointee inline.
void CEmitter::emitGraphReadInto(ClassInfo& ci)
{
    // A hand-written node fills its shell from its own twin: the body reads the `value` object it wrote and
    // hands back a `This` BY VALUE, which is exactly what a freshly calloc'd shell wants assigned into it.
    // The author's declared `Result<This, …>` is therefore usable as-is here — it is only the ROOT spelling
    // that needs a handle, and that gets its own entry point.
    if (graphTwinNeeded(ci, /*write=*/false)) {
        const std::string resC = cType(ci.methods["deserialize"].returnType);
        *_out << (_emitStaticClass ? "static inline " : "") << "void " << ci.name << "____readInto(" << ci.name
              << "* self, Deserializer r, struct kama_de_graph* g)\n{\n";
        indent(1); *_out << resC << " __t = " << ci.name << "__deserializeFrom(r, g);\n";
        indent(1); *_out << "if (__t.tag == " << resC << "_Ok) *self = __t.u.Ok.value;\n";
        indent(1); *_out << "else { " << cType(ownedErrorTypeNode()) << "__dtor(&__t.u.Err.error); "
                            "kama_de_graph_fail(g, DeError_Malformed); }\n";
        *_out << "}\n\n";
        return;
    }
    if (!ci.genDeserialize) return;
    *_out << (_emitStaticClass ? "static inline " : "") << "void " << ci.name << "____readInto(" << ci.name
          << "* self, Deserializer r, struct kama_de_graph* g)\n{\n";
    if (ci.isVariant || ci.isScalarEnum()) { emitGraphReadIntoVariant(ci); return; }
    // The block is zeroed, and zero is `Some(0)` for an Optional — reset every Optional field to None first.
    for (auto& f : ci.fields) {
        if (f.serSkip) continue;
        if (f.type && f.type->value && *f.type->value == "Optional") {
            std::string oc = cType(f.type);
            indent(1); *_out << "self->" << f.name << " = (" << oc << "){ .tag = " << oc << "_None };\n";
        }
    }
    std::vector<const FieldInfo*> rf = serWireFields(ci, /*forWrite=*/false);
    indent(1); *_out << "r.vtbl->beginObject(r.obj, " << serWireFields(ci, /*forWrite=*/true).size() << ");\n";
    indent(1); *_out << "while (r.vtbl->moreFields(r.obj)) {\n";
    emitFieldKeySlot(ci, rf, 2);
    indent(2); *_out << "switch (__slot) {\n";
    for (size_t i = 0; i < rf.size(); ++i) {
        indent(3); *_out << "case " << i << ": {\n";
        { ScopedStr _sf(_serdeField, rf[i]->name); emitGraphFieldRead(rf[i]->type, "self->" + rf[i]->name, 4); }
        indent(3); *_out << "break;\n";
        indent(3); *_out << "}\n";
    }
    indent(3); *_out << "default: r.vtbl->skipValue(r.obj); break;\n";
    indent(2); *_out << "}\n";
    indent(2); *_out << "FieldKey__dtor(&__key);\n";
    indent(1); *_out << "}\n";
    indent(1); *_out << "r.vtbl->endObject(r.obj);\n";
    *_out << "}\n\n";
}

// An enum shell's pass 1: the by-value enum frame (emitEnumDeserializeDefinition), read straight into the
// shell — tag first, then the payload fields in place, so an edge's id is stashed in its own handle and no
// temporary carries it. An unknown tag, or a frame that breaks off, fails the graph read; the shell then holds
// a valid variant (tag set before any payload is read, the rest zeroed), which is all its dtor needs.
void CEmitter::emitGraphReadIntoVariant(ClassInfo& ci)
{
    auto closeObj = [&](int d) {
        indent(d); *_out << "while (r.vtbl->moreFields(r.obj)) { FieldKey __sk = r.vtbl->field(r.obj); "
                            "FieldKey__dtor(&__sk); r.vtbl->skipValue(r.obj); }\n";
        indent(d); *_out << "r.vtbl->endObject(r.obj);\n";
    };
    const bool unit = ci.isScalarEnum();
    if (!unit) {
        indent(1); *_out << "r.vtbl->beginObject(r.obj, 0);\n";
        indent(1); *_out << "r.vtbl->moreFields(r.obj);\n";
        indent(1); *_out << "{ FieldKey __k = r.vtbl->field(r.obj); FieldKey__dtor(&__k); }\n";   // the "tag" key
    }
    emitVariantKeySlot(ci, 1);
    for (size_t vi = 0; vi < ci.variants.size(); ++vi) {
        auto& v = ci.variants[vi];
        indent(1); *_out << (vi ? "else if" : "if") << " (__vslot == " << vi << ") {\n";
        indent(2); *_out << (ci.isScalarEnum() ? "*self = " : "self->tag = ") << ci.name << "_" << v.name << ";\n";
        for (auto& f : v.payload)   // zero is `Some(0)` for an Optional — start every one at None
            if (f.type && f.type->value && *f.type->value == "Optional") {
                std::string oc = cType(f.type);
                indent(2); *_out << "self->u." << v.name << "." << f.name << " = (" << oc << "){ .tag = " << oc << "_None };\n";
            }
        if (!v.payload.empty()) {
            indent(2); *_out << "r.vtbl->moreFields(r.obj);\n";
            indent(2); *_out << "{ FieldKey __kv = r.vtbl->field(r.obj); FieldKey__dtor(&__kv); }\n";   // the "value" key
            indent(2); *_out << "r.vtbl->beginObject(r.obj, " << v.payload.size() << ");\n";
            for (auto& f : v.payload) {
                indent(2); *_out << "r.vtbl->moreFields(r.obj);\n";
                indent(2); *_out << "{ FieldKey __pk = r.vtbl->field(r.obj); FieldKey__dtor(&__pk); }\n";
                ScopedStr _sf(_serdeField, f.name);
                emitGraphFieldRead(f.type, "self->u." + v.name + "." + f.name, 2);
            }
            closeObj(2);   // the value object
        }
        if (!unit) closeObj(2);   // the outer object
        indent(1); *_out << "}\n";
    }
    indent(1); *_out << "else { r.vtbl->fail(r.obj); kama_de_graph_fail(g, DeError_Malformed); }\n";
    indent(1); *_out << "FieldKey__dtor(&__tag);\n";
    *_out << "}\n\n";
}

void CEmitter::emitGraphNodeHelpers(ClassInfo& ci)
{
    const std::string& K = ci.name;
    const char* stat = _emitStaticClass ? "static inline " : "";
    // A HAND-WRITTEN node has no fields to walk — its edges may be anywhere its body puts them — so its
    // four helpers ARE the twin: discovery runs the body against the discard sink, the node's `value`
    // object is the body itself (it does its own framing), and pass 2 is `__wireParts`. Same machinery as
    // a participant; the only difference is that this one is a table entry, because something points at it.
    if (graphTwinNeeded(ci, /*write=*/true)) {
        const std::string resC = cType(ci.methods["serialize"].returnType);
        *_out << stat << "void " << K << "__visitEdges(" << K << "* self, struct kama_ser_graph* g)\n{\n";
        indent(1); *_out << "Serializer __s = __kama_null_serializer();\n";
        indent(1); *_out << resC << " __d = " << K << "__serializeInto(self, &__s, g);\n";
        indent(1); *_out << "if (__d.tag == " << resC << "_Err) { " << cType(ownedErrorTypeNode())
                         << "__dtor(&__d.u.Err.error); }\n";
        *_out << "}\n\n";
        *_out << stat << "void " << K << "__writeNode(" << K << "* self, Serializer* w, struct kama_ser_graph* g)\n{\n";
        indent(1); *_out << resC << " __r = " << K << "__serializeInto(self, w, g);\n";
        indent(1); *_out << "if (__r.tag == " << resC << "_Err) { " << cType(ownedErrorTypeNode())
                         << "__dtor(&__r.u.Err.error); }\n";
        *_out << "}\n\n";
    }
    if (graphTwinNeeded(ci, /*write=*/false)) {
        *_out << stat << "void " << K << "__wireEdges(" << K << "* self, struct kama_de_graph* g)\n{\n";
        if (graphWireElementsNeeded(ci)) { indent(1); *_out << K << "__wireParts(self, g);\n"; }
        else                             { indent(1); *_out << "(void)self; (void)g;\n"; }
        *_out << "}\n\n";
    }
    if (ci.genSerialize) {
        // PASS 1 — discovery. Interning every reachable pointee before a byte is written is what lets the
        // object table be an ARRAY: `beginArray(count)` states its length up front, which is the whole
        // reason a positional backend can carry a graph at all.
        *_out << stat << "void " << K << "__visitEdges(" << K << "* self, struct kama_ser_graph* g)\n{\n";
        if (ci.isVariant)   // an enum's edges are the payload fields of whichever variant it holds
            emitVariantPayloadWalk(ci, [&](const FieldInfo& f, const std::string& a, int d) { emitGraphFieldVisit(f.type, a, d); });
        for (const FieldInfo* fp : serWireFields(ci, /*forWrite=*/true)) {
            ScopedStr _sf(_serdeField, fp->name);
            emitGraphFieldVisit(fp->type, "self->" + fp->name, 1);
        }
        *_out << "}\n\n";
        // PASS 2 — the node's own `value` object: the ordinary keyed field frame, with an edge written as
        // the id discovery already assigned it.
        *_out << stat << "void " << K << "__writeNode(" << K << "* self, Serializer* w, struct kama_ser_graph* g)\n{\n";
        if (ci.isVariant || ci.isScalarEnum()) {   // the by-value enum frame, with an edge written as its id
            emitVariantWriteFrame(ci, [&](const FieldInfo& f, const std::string& a, int d) { emitGraphFieldWrite(f.type, a, d); },
                                  "(*self)");   // a node is reached through its handle, so `self` is a pointer
            *_out << "}\n\n";
        } else {
        std::vector<const FieldInfo*> wf = serWireFields(ci, /*forWrite=*/true);
        indent(1); *_out << "w->vtbl->beginObject(w->obj, " << wf.size() << ");\n";
        for (const FieldInfo* fp : wf) {
            const std::string& wire = fp->serName.empty() ? fp->name : fp->serName;
            indent(1); *_out << "w->vtbl->field(w->obj, " << kamaStrLit(wire) << ", " << serWireId(ci, *fp) << "u);\n";
            ScopedStr _sf(_serdeField, fp->name);
            emitGraphFieldWrite(fp->type, "self->" + fp->name, 1);
        }
        indent(1); *_out << "w->vtbl->endObject(w->obj);\n";
        *_out << "}\n\n";
        }
    }
    if (ci.genDeserialize) {
        // READ PASS 2 — every id the shell stashed becomes a retained handle.
        *_out << stat << "void " << K << "__wireEdges(" << K << "* self, struct kama_de_graph* g)\n{\n";
        if (ci.isVariant)
            emitVariantPayloadWalk(ci, [&](const FieldInfo& f, const std::string& a, int d) { emitGraphFieldWire(f.type, a, d); });
        for (const FieldInfo* fp : serWireFields(ci, /*forWrite=*/false)) {
            ScopedStr _sf(_serdeField, fp->name);
            emitGraphFieldWire(fp->type, "self->" + fp->name, 1);
        }
        *_out << "}\n\n";
    }
}

// ---- the walker ------------------------------------------------------------------------------------------
// The driver, emitted as the node type's OWN `serialize`/`deserialize`. There is no root wrapper type: what
// you hand to a backend IS the root, and a graph comes back as `Shared<T>` because a cycle cannot be
// returned by value.
//
// Every frame below is the ordinary token vocabulary — `{root, objects: [{id, type, value}]}` — so a backend
// that carries values carries graphs, positional and numbered included. The envelope's own frames have a
// FIXED shape, so they are read positionally the way the derive reads a tagged enum's `{tag, value}`; only a
// node's `value` object is keyed.
// A type that must carry the graph through its OWN serde body. Two conditions, and the second is what
// separates this from a `@generate` node: the body is HAND-WRITTEN, so the compiler cannot walk its fields
// to find the edges (a container's edges are its ELEMENTS, which are not fields at all). A node has the
// walker's four helpers instead and needs none of this.
bool CEmitter::graphTwinNeeded(const ClassInfo& ci, bool write) const
{
    if (!ci.reachesPointer || ci.isIntrinsicColl || isSmartPtrClass(ci.name)) return false;
    auto it = ci.methods.find(write ? "serialize" : "deserialize");
    if (it == ci.methods.end()) return false;
    // "Hand-written" is exactly "has an AST body". A derive's has none (isSynthSer/isSynthDe), and neither
    // does a compiler-registered FORWARD — the `Shared<X>.deserialize` computeGraphNodeTypes installs is
    // abstract and points at the node's own driver. Asking for the node rather than the synth flags catches
    // both: the triad must never get a twin, and it was getting one until this said so.
    return it->second.node != nullptr && !it->second.isAbstract;
}

// Does a NODE have a write half / a read half? A derive's is the synthesized field walk; a hand-written
// node's is its twin. Every gate on the node helpers asks one of these two questions, and they used to ask
// `genSerialize`/`genDeserialize` directly — which is the same thing only while `@generate` is the only way
// to be a node. Once a hand-written type can be one, it is not.
bool CEmitter::graphNodeWrites(const ClassInfo& ci) const { return ci.genSerialize   || graphTwinNeeded(ci, true); }
bool CEmitter::graphNodeReads (const ClassInfo& ci) const { return ci.genDeserialize || graphTwinNeeded(ci, false); }

// THE ROLE OF A MARK, off the signature it sits on. Taking the serializer is what makes a method a
// serialization method, so it is also what tells the two roles apart — an edge accessor is nullary and
// hands out an iterator, a delegate is handed the sink. No new attribute: both are "the graph routes
// through this member", and there is nothing for the author to choose between.
CEmitter::GraphMark CEmitter::graphMarkRole(const MethodInfo& mi) const
{
    if (!mi.serdeGraphEdges) return GraphMark::None;
    for (auto& p : mi.params) {
        if (p.className == "Serializer")   return GraphMark::WriteDelegate;
        if (p.className == "Deserializer") return GraphMark::ReadDelegate;
    }
    return GraphMark::EdgeAccessor;   // the nullary-accessor shape; `mutIterOf` validates the rest of it
}

// A DELEGATE the graph table must be threaded into. The gate is deliberately narrow, because the worry it
// answers is run-away: a method qualifies only if it (1) is marked, (2) TAKES the serializer, and (3) sits
// on a type that reaches a `Shared`/`Weak` at all. The stdlib has 8 `ref Serializer`-taking methods outside
// the serde module; 7 are the contract `serialize` and already carry the graph, so this rule adds exactly
// one — `BTreeNode.serializeInto`, which is where a SortedMap's element write actually happens.
bool CEmitter::graphDelegateNeeded(const ClassInfo& ci, const MethodInfo& mi, bool write) const
{
    if (!ci.reachesPointer || ci.isIntrinsicColl || isSmartPtrClass(ci.name)) return false;
    if (graphMarkRole(mi) != (write ? GraphMark::WriteDelegate : GraphMark::ReadDelegate)) return false;
    // Same "hand-written is exactly has an AST body" test graphTwinNeeded uses: there is no body to emit a
    // second copy of otherwise.
    return mi.node != nullptr && !mi.isAbstract;
}

// THE CALL GATE (rule 2 of "the graph table travels with the serializer"). True when the argument bound to
// the callee's sink parameter is exactly the enclosing graph copy's OWN sink, named plainly. Anything else
// — a freshly built `Serializer`, a field, a sink handed in from elsewhere — is a different document, so
// the call routes to the delegate's plain body and writes inline, which is correct for that document.
bool CEmitter::graphSinkIsOurs(const MethodInfo& callee, SharedArgumentList args, bool write) const
{
    const std::string& sink = write ? _serGraphSink : _deGraphSink;
    if (sink.empty() || !args) return false;
    const std::string pname = serdeSinkParamName(callee, write);
    if (pname.empty()) return false;
    for (auto& a : *args) {
        if (!a || !a->name || !a->name->value || *a->name->value != pname) continue;
        auto* id = dynamic_cast<IdentifierNode*>(a->expression.get());
        return id && id->value && *id->value == sink;
    }
    return false;   // not passed by name at all — kama's convention is named, so this is not our sink
}

// Which types need a twin, and which edge handles need a `__serializeEdge`. Runs once, after the node set
// is final — `isGraphNode` is what decides whether a `Shared<X>` is an edge or just a handle to a value.
void CEmitter::planGraphTwins()
{
    for (auto& kv : _classes)
        if (graphTwinNeeded(kv.second, true) || graphTwinNeeded(kv.second, false)) { _anyGraphTwin = true; break; }
    if (!_anyGraphTwin) return;
    for (auto& kv : _classes) {
        const std::string& cls = kv.first;
        // The triad arm of graphEdgeOf, by class rather than by type node — the same two template
        // comparisons, because here the spelling is a monomorph name and there is no field type to ask.
        auto g = _genericTypeInstOf.find(cls);
        if (g == _genericTypeInstOf.end()) continue;
        GraphEdge e;
        if      (g->second == _sharedTmpl) e.kind = "Shared";
        else if (g->second == _weakTmpl)   e.kind = "Weak";
        else continue;
        auto gi = _genericTypeInsts.find(cls);
        if (gi == _genericTypeInsts.end() || gi->second.typeArgs.empty()) continue;
        e.elemC = cType(gi->second.typeArgs[0]);
        e.elemIsContract = isInterface(e.elemC);
        // Only a handle to a NODE is an edge. A `Shared<Config>` over a pointer-free type is an ordinary
        // handle, written by value through the deref, and must keep that behaviour.
        auto ec = _classes.find(e.elemC);
        if (!e.elemIsContract && (ec == _classes.end() || !ec->second.isGraphNode)) continue;
        _graphEdgeHelperFor[cls] = e;
    }
}

// The discard sink. Discovery has to RUN a hand-written body to find its edges (its fields are not the
// edges — a container's elements are), and running it produces tokens nobody wants: the object table is
// not framed yet, and the same body runs again for real. So it writes into this, whose every member is a
// no-op. `failed()` answers false so the body does not bail early, and `errorCode()` is never consulted.
// Emitted once, and only when some type actually needs a twin — a program with no container of edges gets
// none of it.
void CEmitter::emitNullSerializer()
{
    if (!_anyGraphTwin) return;
    // ALWAYS `static inline`: these are DEFINITIONS in the shared header, which every translation unit
    // includes — the resolvers beside them are spelled the same way for the same reason.
    const char* stat = "static inline ";
    *_out << stat << "void __kama_ns_void(void* o) { (void)o; }\n";
    *_out << stat << "void __kama_ns_usize(void* o, size_t n) { (void)o; (void)n; }\n";
    *_out << stat << "void __kama_ns_str(void* o, kama_string* v) { (void)o; (void)v; }\n";
    *_out << stat << "void __kama_ns_field(void* o, kama_string n, uint32_t i) { (void)o; kama_string__dtor(&n); (void)i; }\n";
    *_out << stat << "void __kama_ns_variant(void* o, kama_string n, uint32_t i) { (void)o; kama_string__dtor(&n); (void)i; }\n";
    static const char* kScalars[] = { "I8","int8_t", "I16","int16_t", "I32","int32_t", "I64","int64_t",
                                      "U8","uint8_t", "U16","uint16_t", "U32","uint32_t", "U64","uint64_t",
                                      "F32","float", "F64","double", "Bool","bool", "Char","uint32_t" };
    for (size_t i = 0; i < sizeof(kScalars) / sizeof(*kScalars); i += 2)
        *_out << stat << "void __kama_ns_write" << kScalars[i] << "(void* o, " << kScalars[i + 1]
              << " v) { (void)o; (void)v; }\n";
    *_out << stat << "bool __kama_ns_failed(void* o) { (void)o; return false; }\n";
    // `failed()` is always false, so this is unreachable — but a contract slot must be filled with
    // something of the right type, and `SerError` has a TAGGED repr (a payload-less enum that declares a
    // method), so the tag is not itself a value.
    *_out << stat << "SerError __kama_ns_errorCode(void* o) { (void)o; return SerError_IoError; }\n";
    *_out << "static const Serializer_vtbl __kama_null_ser_vtbl = {\n";   // a table, not a function: no `inline`
    indent(1); *_out << ".beginObject = __kama_ns_usize, .endObject = __kama_ns_void,\n";
    indent(1); *_out << ".field = __kama_ns_field, .variant = __kama_ns_variant,\n";
    indent(1); *_out << ".beginArray = __kama_ns_usize, .endArray = __kama_ns_void,\n";
    indent(1); *_out << ".writeI8 = __kama_ns_writeI8, .writeI16 = __kama_ns_writeI16, "
                        ".writeI32 = __kama_ns_writeI32, .writeI64 = __kama_ns_writeI64,\n";
    indent(1); *_out << ".writeU8 = __kama_ns_writeU8, .writeU16 = __kama_ns_writeU16, "
                        ".writeU32 = __kama_ns_writeU32, .writeU64 = __kama_ns_writeU64,\n";
    indent(1); *_out << ".writeF32 = __kama_ns_writeF32, .writeF64 = __kama_ns_writeF64,\n";
    indent(1); *_out << ".writeBool = __kama_ns_writeBool, .writeChar = __kama_ns_writeChar, "
                        ".writeString = __kama_ns_str,\n";
    indent(1); *_out << ".writeSome = __kama_ns_void, .writeNull = __kama_ns_void,\n";
    indent(1); *_out << ".failed = __kama_ns_failed, .fail = __kama_ns_void, "
                        ".failWith = NULL, .errorCode = __kama_ns_errorCode,\n";
    *_out << "};\n";
    *_out << stat << "Serializer __kama_null_serializer(void) { Serializer s; s.obj = NULL; "
                     "s.vtbl = &__kama_null_ser_vtbl; return s; }\n\n";
}

// Pass 2 has to revisit a participant's ELEMENTS, and they are not fields — so it iterates. `IterableMut<T>`
// is the contract `foreach (ref T x in c)` already requires, which is why this needs no new protocol and a
// third-party container gets it by implementing what it would implement anyway. Answers the iterator's
// class, plus the two protocol methods, or nullptr when the type cannot be iterated mutably.
CEmitter::MutIter CEmitter::mutIterOf(ClassInfo& ci)
{
    MutIter m;
    // The accessor is the one MARKED `@serializedGraphEdges`, never one found by name. Marking is what
    // frees the name: `DynamicArray` marks `iterMut()`, `Map` marks `valuesMut()`, and a third-party
    // container may call its own whatever it likes and implement as many other iterators as it wants
    // without any of them being mistaken for this one. It is also MANDATORY — the same rule `@field`
    // already applies to a `@generate`d product's fields: serde walks what you mark, never what it guesses.
    MethodInfo* iterMi = nullptr;
    std::string iterName;
    // …and only in its ACCESSOR role. The same attribute also marks a write/read DELEGATE (a helper the
    // element write is handed to), which is a different member with a different signature — so "more than
    // one mark" is an error per ROLE, not per class.
    for (auto& kv : ci.methods)                       // `methods` is keyed by kama method name
        if (graphMarkRole(kv.second) == GraphMark::EdgeAccessor) {
            if (iterMi) {
                unsupported(("`" + demangleForDisplay(ci.name) + "` marks more than one method "
                             "`@serializedGraphEdges` — a container has one set of graph-edge elements, so "
                             "exactly one accessor hands them out").c_str(), ci.declLine());
                return m;
            }
            iterMi = &kv.second; iterName = kv.first;
        }
    if (!iterMi) return m;
    // A marked accessor that cannot serve the protocol is an error, not a silent miss: the author said
    // "rewire through here", so failing to is worth a diagnostic naming what is wrong.
    if (!iterMi->params.empty()) {
        unsupported(("`" + iterName + "` is marked `@serializedGraphEdges`, so it is called with no "
                     "arguments to start the rewiring walk — it must take none").c_str(), ci.declLine());
        return m;
    }
    const std::string iterC = cTypeInInstance(ci.name, iterMi->returnType);
    auto it = _classes.find(iterC);
    MethodInfo* hasNextMi = it == _classes.end() ? nullptr : findMethod(&it->second, "hasNext", nullptr);
    MethodInfo* nextMi    = it == _classes.end() ? nullptr : findMethod(&it->second, "next", nullptr);
    if (it == _classes.end() || !hasNextMi || !nextMi || !nextMi->isPlaceReturn
        || !implementsContractTemplate(&it->second, "IteratorMut")) {
        unsupported(("`" + iterName + "` is marked `@serializedGraphEdges`, so it must hand out a "
                     "MUTABLE iterator — one that `implements IteratorMut<T>` (a `bool hasNext()` and a "
                     "place-returning `ref T next()`). Pass 2 writes the live handle back THROUGH that "
                     "place, so a by-value `Iterator<T>` cannot do it").c_str(), ci.declLine());
        return m;
    }
    m.iterC = iterC; m.iter = iterMi; m.hasNext = hasNextMi; m.next = nextMi; m.ic = &it->second;
    return m;
}

// The ELEMENT type a marked accessor hands out — the `T` of the `IteratorMut<T>` its iterator implements,
// as a concrete C type. "" when there is no marked accessor. This is what makes the coverage question
// answerable: a container may carry edges in more than one type argument, and an accessor covers ONE.
std::string CEmitter::graphEdgeElemType(ClassInfo& ci)
{
    MutIter m = mutIterOf(ci);
    if (!m.ic || !m.next) return "";
    return cTypeInInstance(m.iterC, m.next->returnType);
}

// Is this type's parts (`__wireParts`) — does a participant hold anything pass 2 must revisit? A
// participant's edges arrive two ways and BOTH have to be answered: as its own FIELDS (a hand-written type
// holding handles) and as its ELEMENTS (a container, whose elements are type arguments). Answering only the
// second shipped a SIGSEGV in a probe — the write was correct, the read stashed ids into the fields and
// nothing ever turned them back into handles, so the first deref was a wild pointer.
bool CEmitter::graphPartIsEdge(SharedIdentifier ty)
{
    // An absent edge is spelled `Optional<Shared<X>>`, and emitGraphFieldWire unwraps it — so this has to
    // ask the same question about the same thing. It did not, and a hand-written node's `next` field went
    // unwired: the write put the cycle in the table correctly and the read handed back one node with a
    // dangling 0. This predicate must stay the mirror of what that emitter acts on.
    if (graphOptional(ty)) return ty->genericArg && graphPartIsEdge(ty->genericArg);
    const std::string c = cType(ty);
    if (_graphEdgeHelperFor.count(c)) return true;
    auto it = _classes.find(c);
    if (it != _classes.end() && graphWireElementsNeeded(it->second)) return true;
    auto nest = graphNestOf(ty);
    return !nest.first.empty() && typeHasGraphAdapters(nest.second);
}

bool CEmitter::graphWireElementsNeeded(ClassInfo& ci)
{
    if (!graphTwinNeeded(ci, /*write=*/false)) return false;
    if (_wirePartsInProgress.count(ci.name)) return false;   // a self-referential instance: stop the recursion
    _wirePartsInProgress.insert(ci.name);
    bool need = false;
    for (auto& f : ci.fields)
        if (!f.serSkip && graphPartIsEdge(f.type)) { need = true; break; }
    if (!need) {
        auto gi = _genericTypeInsts.find(ci.name);
        if (gi != _genericTypeInsts.end())
            for (auto& a : gi->second.typeArgs)
                if (graphPartIsEdge(a)) { need = true; break; }
    }
    _wirePartsInProgress.erase(ci.name);
    return need;
}

// `X__wireParts` — pass 2 over a participant's FIELDS and then its ELEMENTS. Each stashed id becomes a live handle, with a
// nested participant recursing. ⚠️ This iterates rather than resolving addresses recorded during pass 1,
// and that is not a style choice: `DynamicArray.deserialize` grows via `add`, so the buffer reallocs while
// the elements are being read and any address recorded then dangles. The stash rides IN the element and
// therefore moves with it.
void CEmitter::emitGraphWireElements(ClassInfo& ci)
{
    if (!graphWireElementsNeeded(ci)) return;
    const char* stat = _emitStaticClass ? "static inline " : "";
    *_out << stat << "void " << ci.name << "__wireParts(" << ci.name
          << "* self, struct kama_de_graph* g)\n{\n";
    // FIELDS first — the same walk `K__wireEdges` does for a node. A container's own fields are an
    // `UnsafePtr<T>` and bookkeeping, so this is a no-op for one; a hand-written participant's edges are
    // here and nowhere else.
    for (auto& f : ci.fields)
        if (!f.serSkip) { ScopedStr _sf(_serdeField, f.name); emitGraphFieldWire(f.type, "self->" + f.name, 1); }
    // …then ELEMENTS, which are not fields and so have to be iterated.
    bool wantElems = false;
    auto gi = _genericTypeInsts.find(ci.name);
    if (gi != _genericTypeInsts.end())
        for (auto& a : gi->second.typeArgs) if (graphPartIsEdge(a)) { wantElems = true; break; }
    if (!wantElems) { indent(1); *_out << "(void)self; (void)g;\n}\n\n"; return; }
    MutIter m = mutIterOf(ci);
    if (!m.ic) {   // no mutable iteration: say so where the author can act on it
        indent(1); *_out << "(void)self; (void)g;\n}\n\n";
        unsupported(("`" + demangleForDisplay(ci.name) + "` holds graph edges as ELEMENTS, so reading it back "
                     "needs to revisit them — which means iterating it mutably, and saying WHICH iterator "
                     "does it. Mark the accessor `@serializedGraphEdges`: a nullary method handing out an "
                     "`IteratorMut<T>` (a `bool hasNext()` and a place-returning `ref T next()`). A sequence "
                     "marks its `iterMut()`; a KEYED container marks `valuesMut()`, since its edges live in "
                     "its values and a key cannot be rewired in place. Marking is required even when the type "
                     "has exactly one such iterator — serde walks what you mark, the same way `@field` does").c_str(),
                    ci.declLine());
        return;
    }
    indent(1); *_out << m.iterC << " __it = " << m.iter->cName << "(self);\n";
    indent(1); *_out << "while (" << m.hasNext->cName << "(&__it)) {\n";
    // `next()` is place-returning, so it hands back a pointer INTO the container — writing through it is
    // what wires the element in place.
    indent(2); *_out << cTypeInInstance(m.iterC, m.next->returnType) << "* __e = " << m.next->cName << "(&__it);\n";
    {
        // Resolve the element type in the ITERATOR's instance, the same binding `foreach` uses.
        NsCtx savedCtx = _nsCtx;
        std::map<std::string, SharedIdentifier> savedSubst = _typeSubst;
        auto gi = _genericTypeInsts.find(m.iterC);
        if (gi != _genericTypeInsts.end()) {
            _typeSubst.clear();
            const std::vector<std::string>& ps = _genericTypeParams[gi->second.templateKey];
            for (size_t i = 0; i < ps.size() && i < gi->second.typeArgs.size(); ++i)
                _typeSubst[ps[i]] = gi->second.typeArgs[i];
            _nsCtx = _genericTypeInstCtx.count(m.iterC) ? _genericTypeInstCtx[m.iterC]
                                                        : _genericTypeCtx[gi->second.templateKey];
        }
        emitGraphFieldWire(m.next->returnType, "(*__e)", 2);
        _typeSubst = savedSubst; _nsCtx = savedCtx;
    }
    indent(1); *_out << "}\n";
    *_out << "}\n\n";
}

// One per edge type: interning an edge is a STATEMENT sequence (a temp, a null guard, a type id), but the
// place it has to happen is an EXPRESSION — `this[i].serialize(w: w)` in a container's own body, whose
// value is the fallible `Result`. So the sequence is wrapped in a function and the call site is a call.
// The write is `writeU64(id)`; against the discard sink during discovery it goes nowhere, which is what
// makes one body serve both passes with no mode flag.
void CEmitter::emitGraphEdgeHelpers()
{
    if (!_anyGraphTwin) return;
    const char* stat = "static inline ";   // header-resident definition, as above
    const std::string resC = cType(resultUnitOwnedErrorTypeNode());
    for (auto& kv : _classes) {
        const std::string& cls = kv.first;
        if (!_graphEdgeHelperFor.count(cls)) continue;
        const GraphEdge& e = _graphEdgeHelperFor[cls];
        *_out << stat << resC << " " << cls << "__serializeEdge(" << cls
              << "* self, Serializer* w, struct kama_ser_graph* g)\n{\n";
        indent(1); *_out << "uint64_t __id = 0;\n";
        std::string obj = e.elemIsContract ? "self->obj" : "(void*)self->p";
        std::string ctl = e.elemIsContract ? "self->ctrl" : "(kama_ctrl*)self->c";
        std::string tid = e.elemIsContract ? (e.elemC + "__graphTypeId(self->vtbl)")
                                           : (std::to_string(_classes[e.elemC].graphTypeId) + "u");
        // A null control block is an empty handle; an EXPIRED `Weak` has a live block and a dead pointee,
        // so it must not be interned either — it writes 0, which reads back as expired.
        indent(1); *_out << "if (" << ctl << (e.kind == "Weak" ? " && " + ctl + "->strong > 0" : "") << ") {\n";
        indent(2); *_out << "uint32_t __tid = " << tid << ";\n";
        indent(2); *_out << "if (__tid != KAMA_GRAPH_NO_NODE) __id = kama_ser_graph_intern(g, "
                            "(uint64_t)(uintptr_t)" << obj << ", __tid);\n";
        indent(1); *_out << "}\n";
        indent(1); *_out << "w->vtbl->writeU64(w->obj, __id);\n";
        indent(1); *_out << "return (" << resC << "){ .tag = " << resC << "_Ok, .u.Ok = { .value = Unit_Unit } };\n";
        *_out << "}\n\n";

        // The read twin. Pass 1 takes the id and STASHES it in the handle's own pointer slot with a NULL
        // control block — which is what every graph edge field already does, and what lets the value move
        // with its element when the container reallocs mid-build. `X__wireParts` turns it into a live
        // handle in pass 2. Both handle dtors guard on the null block, so an id never freed as a pointer.
        auto ecIt = _classes.find(e.elemC);
        if (ecIt == _classes.end() || !ecIt->second.methods.count("deserialize")) continue;
        const std::string edgeRes = cType(resultOwnedErrorTypeNode(
            triadTypeNode(e.kind.c_str(), _genericTypeInsts[cls].typeArgs[0])));
        // Only when that `Result` is a real monomorph. It exists exactly when some container of these
        // elements declared it, which is exactly when this helper is called — a program with a
        // `Shared<X>` FIELD and no container of them instantiates the field's edge type but no Result
        // over it, and emitting the helper anyway names a type nothing defines.
        if (!_classes.count(edgeRes)) continue;
        *_out << stat << edgeRes << " " << cls << "__deserializeEdge(Deserializer r, struct kama_de_graph* g)\n{\n";
        indent(1); *_out << "(void)g;\n";
        indent(1); *_out << cls << " __h;\n";
        indent(1); *_out << "uint64_t __rid = r.vtbl->readU64(r.obj);\n";
        if (e.elemIsContract) {
            indent(1); *_out << "__h.obj = (void*)(uintptr_t)__rid; __h.vtbl = NULL; __h.ctrl = NULL;\n";
        } else {
            indent(1); *_out << "__h.p = (" << e.elemC << "*)(uintptr_t)__rid; __h.c = NULL;\n";
        }
        indent(1); *_out << "return (" << edgeRes << "){ .tag = " << edgeRes
                         << "_Ok, .u.Ok = { .value = __h } };\n";
        *_out << "}\n\n";
    }
}

// Discovery. The worklist GROWS under the loop as each node interns its own edges, so `count` is re-read
// every iteration rather than hoisted. Shared by both drivers — a node root seeds it by interning itself,
// a participant root seeds it by running its own body against the discard sink.
void CEmitter::emitGraphWorklistLoop(int depth)
{
    indent(depth); *_out << "for (size_t __i = 0; __i < kama_ser_graph_count(&__g); __i++) {\n";
    indent(depth + 1); *_out << "switch (kama_ser_graph_type(&__g, __i)) {\n";
    for (auto& K : _graphNodeOrder) {
        if (!graphNodeWrites(_classes[K])) continue;
        indent(depth + 1); *_out << "case " << _classes[K].graphTypeId << "u: " << K << "__visitEdges(("
                                 << K << "*)kama_ser_graph_obj(&__g, __i), &__g); break;\n";
    }
    indent(depth + 1); *_out << "default: break;\n";
    indent(depth + 1); *_out << "}\n";
    indent(depth); *_out << "}\n";
}

// `objects: [{id, type, value}]` — the table, in id order. Shared by both drivers.
void CEmitter::emitGraphObjectTable(int depth)
{
    indent(depth); *_out << "w->vtbl->beginArray(w->obj, kama_ser_graph_count(&__g));\n";
    indent(depth); *_out << "for (size_t __i = 0; __i < kama_ser_graph_count(&__g); __i++) {\n";
    indent(depth + 1); *_out << "w->vtbl->beginObject(w->obj, 3);\n";
    indent(depth + 1); *_out << "w->vtbl->field(w->obj, " << kamaStrLit("id") << ", 0u);\n";
    indent(depth + 1); *_out << "w->vtbl->writeU64(w->obj, (uint64_t)(__i + 1));\n";
    indent(depth + 1); *_out << "w->vtbl->field(w->obj, " << kamaStrLit("type") << ", 1u);\n";
    indent(depth + 1); *_out << "switch (kama_ser_graph_type(&__g, __i)) {\n";
    for (auto& K : _graphNodeOrder) {
        if (!graphNodeWrites(_classes[K])) continue;
        indent(depth + 1); *_out << "case " << _classes[K].graphTypeId << "u: {\n";
        // The type tag is a `variant`, not a string: a named backend writes the name unchanged, an index
        // backend writes the index, so the choice costs one byte where a name would cost its length.
        indent(depth + 2); *_out << "w->vtbl->variant(w->obj, " << kamaStrLit(graphWireName(_classes[K])) << ", "
                                 << _classes[K].graphTypeId << "u);\n";
        indent(depth + 2); *_out << "w->vtbl->field(w->obj, " << kamaStrLit("value") << ", 2u);\n";
        indent(depth + 2); *_out << K << "__writeNode((" << K << "*)kama_ser_graph_obj(&__g, __i), w, &__g);\n";
        indent(depth + 2); *_out << "break;\n";
        indent(depth + 1); *_out << "}\n";
    }
    indent(depth + 1); *_out << "default: break;\n";
    indent(depth + 1); *_out << "}\n";
    indent(depth + 1); *_out << "w->vtbl->endObject(w->obj);\n";
    indent(depth); *_out << "}\n";
    indent(depth); *_out << "w->vtbl->endArray(w->obj);\n";
}

// The tail both drivers share: free the worklist and turn the sink's sticky flag into the fallible Result.
void CEmitter::emitGraphDriverTail(const std::string& resC)
{
    indent(1); *_out << "kama_ser_graph_free(&__g);\n";
    indent(1); *_out << "if (w->vtbl->failed(w->obj)) {\n";
    std::string box = emitStickyErrBox(2, "SerError", "w->vtbl->errorCode(w->obj)");
    indent(2); *_out << "return (" << resC << "){ .tag = " << resC << "_Err, .u.Err = { .error = " << box << " } };\n";
    indent(1); *_out << "}\n";
    indent(1); *_out << "return (" << resC << "){ .tag = " << resC << "_Ok, .u.Ok = { .value = Unit_Unit } };\n";
    *_out << "}\n\n";
}

void CEmitter::emitGraphSerializeDefinition(ClassInfo& ci)
{
    std::string resC = cType(ci.methods["serialize"].returnType);
    const char* stat = _emitStaticClass ? "static inline " : "";
    *_out << stat << resC << " " << ci.name << "__serialize(" << ci.name << "* self, Serializer* w)\n{\n";
    indent(1); *_out << "struct kama_ser_graph __g; kama_ser_graph_init(&__g);\n";
    indent(1); *_out << "uint64_t __root = kama_ser_graph_intern(&__g, (uint64_t)(uintptr_t)self, "
                     << ci.graphTypeId << "u);\n";
    emitGraphWorklistLoop(1);
    indent(1); *_out << "w->vtbl->beginObject(w->obj, 2);\n";
    indent(1); *_out << "w->vtbl->field(w->obj, " << kamaStrLit("root") << ", 0u);\n";
    indent(1); *_out << "w->vtbl->writeU64(w->obj, __root);\n";
    indent(1); *_out << "w->vtbl->field(w->obj, " << kamaStrLit("objects") << ", 1u);\n";
    emitGraphObjectTable(1);
    indent(1); *_out << "w->vtbl->endObject(w->obj);\n";
    emitGraphDriverTail(resC);
}

// The same envelope for a participant that is NOT a node — a container of edges, or a hand-written type
// holding them. It has no identity of its own, so there is nothing to intern and the `root` slot carries
// its VALUE inline rather than an id; its elements are ids, and the reader knows which it is reading
// because it knows the type. Existing node wires are untouched.
//
// Discovery is the one place this differs in kind: a derive's edges can be walked field by field, and a
// hand-written body's cannot — so the body is RUN, against a sink that discards every token. The edges
// intern on the way through, which is exactly what the worklist needs, and the count is therefore exact
// before `beginArray` — which the positional and numbered backends have nothing else to bound a read with.
void CEmitter::emitGraphRootDriver(ClassInfo& ci)
{
    const std::string resC = cType(ci.methods["serialize"].returnType);
    const char* stat = _emitStaticClass ? "static inline " : "";
    *_out << stat << resC << " " << ci.name << "__serialize(" << ci.name << "* self, Serializer* w)\n{\n";
    indent(1); *_out << "struct kama_ser_graph __g; kama_ser_graph_init(&__g);\n";
    indent(1); *_out << "Serializer __sink = __kama_null_serializer();\n";
    indent(1); *_out << "{ " << resC << " __d = " << ci.name << "__serializeInto(self, &__sink, &__g);\n";
    indent(1); *_out << "  if (__d.tag == " << resC << "_Err) { " << cType(ownedErrorTypeNode())
                     << "__dtor(&__d.u.Err.error); } }\n";
    emitGraphWorklistLoop(1);
    indent(1); *_out << "w->vtbl->beginObject(w->obj, 2);\n";
    indent(1); *_out << "w->vtbl->field(w->obj, " << kamaStrLit("root") << ", 0u);\n";
    indent(1); *_out << "{ " << resC << " __r = " << ci.name << "__serializeInto(self, w, &__g);\n";
    indent(1); *_out << "  if (__r.tag == " << resC << "_Err) { kama_ser_graph_free(&__g); return __r; } }\n";
    indent(1); *_out << "w->vtbl->field(w->obj, " << kamaStrLit("objects") << ", 1u);\n";
    emitGraphObjectTable(1);
    indent(1); *_out << "w->vtbl->endObject(w->obj);\n";
    emitGraphDriverTail(resC);
}

void CEmitter::emitGraphDeserializeDefinition(ClassInfo& ci)
{
    SharedIdentifier retNode = ci.methods["deserialize"].returnType;     // Result<Shared<T>, Owned<Error>>
    emitGraphNodeReadBody(ci, ci.name + "__deserialize", cType(retNode),
                          cType(retNode->genericArgs->at(0)));           // Shared_T — the Ok arm
}

// A hand-written NODE's handle root. Its own `deserialize` keeps the by-value signature the author wrote —
// that is the one a SHELL wants, and `K____readInto` uses it — so the `Shared<K>` spelling cannot be a
// retarget of it the way a derive's is (computeGraphNodeTypes rewrites a derive's return type; there is no
// rewriting a body whose `return` constructs a `This`). It gets its own entry point over the same walker.
std::string CEmitter::graphHandleRootType(ClassInfo& ci)
{
    if (!ci.isGraphNode || !graphTwinNeeded(ci, /*write=*/false)) return "";
    SharedIdentifier ret = ci.methods.count("deserialize") ? ci.methods["deserialize"].returnType : nullptr;
    if (!ret || !ret->genericArgs || ret->genericArgs->empty()) return "";
    const std::string resC = cType(resultOwnedErrorTypeNode(sharedTypeNode(ret->genericArgs->at(0))));
    return _classes.count(resC) ? resC : "";   // nothing in the program spells `Shared<K>` as a root
}

void CEmitter::emitGraphHandleRootReader(ClassInfo& ci)
{
    // The author's `Result<This, …>` carries a usable `This` node in its Ok arm — the same one
    // computeGraphNodeTypes reads to build a derive's `Shared<This>`.
    const std::string resC = graphHandleRootType(ci);
    if (resC.empty()) return;
    emitGraphNodeReadBody(ci, ci.name + "__deserializeRoot", resC,
                          cType(sharedTypeNode(ci.methods["deserialize"].returnType->genericArgs->at(0))));
}

void CEmitter::emitGraphNodeReadBody(ClassInfo& ci, const std::string& fname,
                                     const std::string& resC, const std::string& sharedT)
{
    std::string T = ci.name;
    const char* stat = _emitStaticClass ? "static inline " : "";
    *_out << stat << resC << " " << fname << "(Deserializer r)\n{\n";
    indent(1); *_out << "struct kama_de_graph __g; kama_de_graph_init(&__g);\n";
    // The envelope is read POSITIONALLY: its shape is fixed, so each key is consumed and discarded and the
    // order is the contract (`type` before `value`, or the reader cannot dispatch).
    indent(1); *_out << "r.vtbl->beginObject(r.obj, 2);\n";
    indent(1); *_out << "r.vtbl->moreFields(r.obj); { FieldKey __k = r.vtbl->field(r.obj); FieldKey__dtor(&__k); }\n";
    indent(1); *_out << "uint64_t __root = r.vtbl->readU64(r.obj);\n";
    indent(1); *_out << "r.vtbl->moreFields(r.obj); { FieldKey __k = r.vtbl->field(r.obj); FieldKey__dtor(&__k); }\n";
    indent(1); *_out << "r.vtbl->beginArray(r.obj);\n";
    // PASS 1 — one shell per entry: allocated, scalars read, every edge id stashed in its own pointer slot.
    indent(1); *_out << "while (r.vtbl->moreElems(r.obj)) {\n";
    indent(2); *_out << "r.vtbl->beginObject(r.obj, 3);\n";
    indent(2); *_out << "r.vtbl->moreFields(r.obj); { FieldKey __k = r.vtbl->field(r.obj); FieldKey__dtor(&__k); }\n";
    indent(2); *_out << "uint64_t __eid = r.vtbl->readU64(r.obj);\n";
    indent(2); *_out << "r.vtbl->moreFields(r.obj); { FieldKey __k = r.vtbl->field(r.obj); FieldKey__dtor(&__k); }\n";
    indent(2); *_out << "FieldKey __ty = r.vtbl->variant(r.obj);\n";
    indent(2); *_out << "r.vtbl->moreFields(r.obj); { FieldKey __k = r.vtbl->field(r.obj); FieldKey__dtor(&__k); }\n";
    indent(2); *_out << "kama_de_box* __b = __kama_graph_readShell(__ty, r, &__g);\n";
    indent(2); *_out << "if (!__b) kama_de_graph_fail(&__g, DeError_TypeMismatch);\n";
    // A table id may appear once, and 0 is never a live id. On refusal the shell just read is dropped.
    indent(2); *_out << "else if (!kama_de_graph_enroll(&__g, __eid, __b, DeError_DuplicateId)) {\n";
    indent(3); *_out << "__kama_graph_dropBox(__b);\n";
    indent(2); *_out << "}\n";
    indent(2); *_out << "r.vtbl->moreFields(r.obj);\n";
    indent(2); *_out << "r.vtbl->endObject(r.obj);\n";
    indent(2); *_out << "if (r.vtbl->failed(r.obj)) break;\n";   // a malformed entry cannot be stepped over
    indent(1); *_out << "}\n";
    indent(1); *_out << "r.vtbl->moreFields(r.obj);\n";
    indent(1); *_out << "r.vtbl->endObject(r.obj);\n";
    // PASS 2 — ids become handles, in read order.
    indent(1); *_out << "for (size_t __i = 0; __i < kama_de_graph_count(&__g); __i++) {\n";
    indent(2); *_out << "kama_de_box* __b = kama_de_graph_at(&__g, __i);\n";
    indent(2); *_out << "switch (__b->type_id) {\n";
    for (auto& K : _graphNodeOrder) {
        if (!graphNodeReads(_classes[K])) continue;
        indent(2); *_out << "case " << _classes[K].graphTypeId << "u: " << K << "__wireEdges(("
                         << K << "*)__b->ptr, &__g); break;\n";
    }
    indent(2); *_out << "default: break;\n";
    indent(2); *_out << "}\n";
    indent(1); *_out << "}\n";
    // ROOT — the walker's construction-strong reference MOVES into the returned handle; a dangling or
    // wrong-typed root is a forged wire.
    indent(1); *_out << sharedT << " __ret = {0};\n";
    indent(1); *_out << "kama_de_box* __rb = kama_de_graph_lookup(&__g, __root);\n";
    indent(1); *_out << "if (!__rb) kama_de_graph_fail(&__g, DeError_UnresolvedReference);\n";
    indent(1); *_out << "else if (__rb->type_id != " << ci.graphTypeId << "u) kama_de_graph_fail(&__g, DeError_TypeMismatch);\n";
    indent(1); *_out << "else { __ret.p = (" << T << "*)__rb->ptr; __ret.c = (void*)__rb->ctrl; __rb->ctrl->strong++; }\n";
    // CLEANUP — drop each shell's construction strong. A node no live edge reaches dies here, so a forged
    // wire cannot leak; one the root reaches survives on the reference just taken.
    indent(1); *_out << "for (size_t __i = 0; __i < kama_de_graph_count(&__g); __i++) __kama_graph_dropBox(kama_de_graph_at(&__g, __i));\n";
    indent(1); *_out << "kama_de_graph_free(&__g);\n";
    // BOUNDARY. The reader's sticky flag and the walker's own are both failures; the walker's carries the
    // sharper code (DuplicateId, UnresolvedReference, TypeMismatch) where the reader would only say
    // Malformed, so it is reported first.
    indent(1); *_out << "if (__g.failed) {\n";
    indent(2); *_out << sharedT << "__dtor(&__ret);\n";
    indent(2); *_out << "r.vtbl->failWith(r.obj, (DeError)__g.code);\n";
    std::string gbox = emitStickyErrBox(2);
    indent(2); *_out << "return (" << resC << "){ .tag = " << resC << "_Err, .u.Err = { .error = " << gbox << " } };\n";
    indent(1); *_out << "}\n";
    indent(1); *_out << "if (r.vtbl->failed(r.obj)) {\n";
    indent(2); *_out << sharedT << "__dtor(&__ret);\n";
    std::string rbox = emitStickyErrBox(2);
    indent(2); *_out << "return (" << resC << "){ .tag = " << resC << "_Err, .u.Err = { .error = " << rbox << " } };\n";
    indent(1); *_out << "}\n";
    indent(1); *_out << "return (" << resC << "){ .tag = " << resC << "_Ok, .u.Ok = { .value = __ret } };\n";
    *_out << "}\n\n";
}

// The read twin of emitGraphRootDriver: the same envelope, read back into a PARTICIPANT. It differs from
// the node reader in exactly the way the writer did — the `root` slot holds the value itself, not an id —
// and in what it hands back: BY VALUE. A node comes back as `Shared<T>` because a cycle has nowhere to
// point if the root is a stack value; a participant has no identity, nothing in the graph can point AT it,
// so there is no cycle to close and no reason to box it.
//
// Order matters and is the reverse of the write: the `objects` table is read FIRST so every shell exists,
// then the root, whose elements can then resolve. The wire is unchanged — `root` is written first — so the
// reader reads root into a temp region... no: the root's elements stash ids exactly as a node's fields do,
// and `X__wireParts` resolves them after the table is enrolled. Same two passes, same order as written.
void CEmitter::emitGraphReadRootDriver(ClassInfo& ci)
{
    const std::string T = ci.name;
    SharedIdentifier retNode = ci.methods["deserialize"].returnType;
    const std::string resC = cType(retNode);
    const char* stat = _emitStaticClass ? "static inline " : "";
    *_out << stat << resC << " " << T << "__deserialize(Deserializer r)\n{\n";
    indent(1); *_out << "struct kama_de_graph __g; kama_de_graph_init(&__g);\n";
    indent(1); *_out << "r.vtbl->beginObject(r.obj, 2);\n";
    indent(1); *_out << "r.vtbl->moreFields(r.obj); { FieldKey __k = r.vtbl->field(r.obj); FieldKey__dtor(&__k); }\n";
    // PASS 1a — the root's own value, with each edge element stashing its id.
    indent(1); *_out << resC << " __rv = " << T << "__deserializeFrom(r, &__g);\n";
    indent(1); *_out << "r.vtbl->moreFields(r.obj); { FieldKey __k = r.vtbl->field(r.obj); FieldKey__dtor(&__k); }\n";
    indent(1); *_out << "r.vtbl->beginArray(r.obj);\n";
    // PASS 1b — the table, exactly as the node reader builds it.
    indent(1); *_out << "while (r.vtbl->moreElems(r.obj)) {\n";
    indent(2); *_out << "r.vtbl->beginObject(r.obj, 3);\n";
    indent(2); *_out << "r.vtbl->moreFields(r.obj); { FieldKey __k = r.vtbl->field(r.obj); FieldKey__dtor(&__k); }\n";
    indent(2); *_out << "uint64_t __eid = r.vtbl->readU64(r.obj);\n";
    indent(2); *_out << "r.vtbl->moreFields(r.obj); { FieldKey __k = r.vtbl->field(r.obj); FieldKey__dtor(&__k); }\n";
    indent(2); *_out << "FieldKey __ty = r.vtbl->variant(r.obj);\n";
    indent(2); *_out << "r.vtbl->moreFields(r.obj); { FieldKey __k = r.vtbl->field(r.obj); FieldKey__dtor(&__k); }\n";
    indent(2); *_out << "kama_de_box* __b = __kama_graph_readShell(__ty, r, &__g);\n";
    indent(2); *_out << "if (!__b) kama_de_graph_fail(&__g, DeError_TypeMismatch);\n";
    indent(2); *_out << "else if (!kama_de_graph_enroll(&__g, __eid, __b, DeError_DuplicateId)) {\n";
    indent(3); *_out << "__kama_graph_dropBox(__b);\n";
    indent(2); *_out << "}\n";
    indent(2); *_out << "r.vtbl->moreFields(r.obj);\n";
    indent(2); *_out << "r.vtbl->endObject(r.obj);\n";
    indent(2); *_out << "if (r.vtbl->failed(r.obj)) break;\n";
    indent(1); *_out << "}\n";
    indent(1); *_out << "r.vtbl->moreFields(r.obj);\n";
    indent(1); *_out << "r.vtbl->endObject(r.obj);\n";
    // PASS 2 — the shells first, then the root's own elements.
    indent(1); *_out << "for (size_t __i = 0; __i < kama_de_graph_count(&__g); __i++) {\n";
    indent(2); *_out << "kama_de_box* __b = kama_de_graph_at(&__g, __i);\n";
    indent(2); *_out << "switch (__b->type_id) {\n";
    for (auto& K : _graphNodeOrder) {
        if (!graphNodeReads(_classes[K])) continue;
        indent(2); *_out << "case " << _classes[K].graphTypeId << "u: " << K << "__wireEdges(("
                         << K << "*)__b->ptr, &__g); break;\n";
    }
    indent(2); *_out << "default: break;\n";
    indent(2); *_out << "}\n";
    indent(1); *_out << "}\n";
    if (graphWireElementsNeeded(ci)) {
        indent(1); *_out << "if (__rv.tag == " << resC << "_Ok) " << T
                         << "__wireParts(&__rv.u.Ok.value, &__g);\n";
    }
    indent(1); *_out << "for (size_t __i = 0; __i < kama_de_graph_count(&__g); __i++) __kama_graph_dropBox(kama_de_graph_at(&__g, __i));\n";
    indent(1); *_out << "kama_de_graph_free(&__g);\n";
    indent(1); *_out << "if (__g.failed) {\n";
    indent(2); *_out << "r.vtbl->failWith(r.obj, (DeError)__g.code);\n";
    std::string gbox = emitStickyErrBox(2);
    indent(2); *_out << "if (__rv.tag == " << resC << "_Ok) " << cType(retNode->genericArgs->at(0))
                     << "__dtor(&__rv.u.Ok.value);\n";
    indent(2); *_out << "else " << cType(ownedErrorTypeNode()) << "__dtor(&__rv.u.Err.error);\n";
    indent(2); *_out << "return (" << resC << "){ .tag = " << resC << "_Err, .u.Err = { .error = " << gbox << " } };\n";
    indent(1); *_out << "}\n";
    indent(1); *_out << "return __rv;\n";
    *_out << "}\n\n";
}

// emit one specialized generic-type instance under its binding. phase 0 = struct typedef+body,
// 1 = ctor/dtor/method prototypes, 2 = bodies. Mirrors emitGenericInst: all specialized class
// functions are header-`static` (every module includes the header), so `_emitStaticClass` is set here.
void CEmitter::emitGenericTypeInst(const GenericTypeInst& gi, int phase)
{
    // A type argument the bound REFUSED is not carried into the template's body. The shape (phase 0) and
    // the prototypes (phase 1) still emit, so every later reference to this instance resolves and the one
    // rejection stays one rejection; the BODIES do not, because walking `Map<K,V>` with a `K` that has no
    // `hash` can only produce consequences of a mistake already reported. See registerGenericTypeInst.
    if (phase == 2 && _boundFailedInsts.count(gi.mangledName)) return;
    auto cit = _classes.find(gi.mangledName);
    if (cit == _classes.end()) return;
    ClassInfo& ci = cit->second;
    // M6 B3: attribute the instance's bodies to the TEMPLATE's unit — see emitGenericInst for why. The
    // template ClassInfo lives in _genericTypes (never in _classes), and its `.node` is the template decl.
    auto tmplIt = _genericTypes.find(gi.templateKey);
    RefUnitScope refScope(this, tmplIt == _genericTypes.end() ? nullptr : unitOfDecl(tmplIt->second.node));
    // A diagnostic raised in this body belongs to the TEMPLATE's file, not to whichever module happens to
    // instantiate it. `declFile` is recorded at collection for exactly this, and unlike `unitOfDecl` it
    // answers for a prelude/std template too — `Shared<T>` and `Weak<T>` are the ones every program hits.
    ScopedStr _edf(_emitDeclFile, tmplIt == _genericTypes.end() ? std::string() : tmplIt->second.declFile);
    ScopedAttrSite _as(*this, gi.mangledName, tmplIt == _genericTypes.end() ? std::string() : tmplIt->second.declFile);
    NsCtx savedCtx = _nsCtx;
    // emit under the USE-SITE ctx (so a prelude template's user-type args resolve); for a
    // same-scope user generic this equals the template's home ctx.
    _nsCtx = _genericTypeInstCtx.count(gi.mangledName) ? _genericTypeInstCtx[gi.mangledName]
                                                       : _genericTypeCtx[gi.templateKey];
    _typeSubst.clear();
    _comptimeSubst.clear();
    const std::vector<std::string>& ps = _genericTypeParams[gi.templateKey];
    for (size_t i = 0; i < ps.size() && i < gi.typeArgs.size(); ++i) _typeSubst[ps[i]] = gi.typeArgs[i];
    bindInstConstParams(gi.templateKey, gi.typeArgs);   // so a member body can READ `const F: int32`
    _emitStaticClass = true;
    // M7: the type's own `comptime assert`s, once per instantiation and with THIS instance's const args
    // bound — so `Fixed<24>` can fail while `Fixed<16>` passes, and the diagnostic names which.
    if (phase == 0 && tmplIt != _genericTypes.end()) emitComptimeAssertsIn(tmplIt->second.node);
    if      (phase == 0) { emitStruct(ci); }   // forward typedef now emitted in the phase-(a) loop
    else if (phase == 1) emitClassPrototypes(ci);
    // Interface vtables BEFORE method bodies: a generic instance's own method may upcast `this` to a contract
    // (`Serializer s = this`), referencing the `static const C__as_I` vtable — which has no forward decl for a
    // header-inline instance, so it must be defined first. Vtable slots reference only method PROTOTYPES
    // (phase 1), so this order is safe. (Free fns emit later, so they never hit the ordering hazard.)
    else { emitClassInterfaceVtables(ci); emitClassDefinitions(ci); }   // `static` C__as_I vtables (e.g. List<int32> as Serializable)
    _emitStaticClass = false;
    _typeSubst.clear();
    _comptimeSubst.clear();
    _nsCtx = savedCtx;
}

// True iff `e` statically has kama type `string` (lowers to `kama_string`): a string literal, a `string`
// local/param or a string-returning call (both surface via `exprClass(e) == "kama_string"`), or a nested
// `+` chain with a string operand. `exprClass`/`operatorResultClass` only class USER operators, so the
// string `+` result is invisible there — recurse here. Keeps string knowledge localized to this predicate
// + the `emitBinaryOperator` string branch, leaving `exprClass`/`operatorResultClass` string-free.
bool CEmitter::exprIsString(SharedExpression e)
{
    if (!e) return false;
    if (dynamic_cast<StringNode*>(e.get())) return true;
    if (auto* be = dynamic_cast<BinaryExpressionNode*>(e.get()))
        if (be->token == PLUS && (exprIsString(be->LHS) || exprIsString(be->RHS))) return true;
    return exprClass(e) == "kama_string";
}

// A `string`-typed RVALUE that isn't a plain lvalue or a borrowed literal — a call/operator result
// (concat, substring, trim, replace, case, find/split pieces...) — may own a heap buffer. Used as an
// operand/receiver it would otherwise be materialized into a throwaway compound-literal and LEAK. Hoist
// it into a named temp registered for RAII drop at scope exit so the buffer is freed. Returns the temp
// name, or "" for a literal / lvalue / non-string (the caller keeps its normal, leak-free path) or when
// there is no statement slot to hoist into (a rare raw `if`/`while` operand — `_hoistOK` false).
// A borrowed result (an empty piece, cap==0) is harmless: kama_string__dtor is a no-op on it.
std::string CEmitter::hoistStringTemp(SharedExpression e)
{
    if (!e || !_hoistOK) return "";                // no statement slot to hoist into (raw operand)
    ASTNode* n = e.get();
    if (dynamic_cast<StringNode*>(n) || dynamic_cast<IdentifierNode*>(n)
        || dynamic_cast<MemberAccessNode*>(n) || dynamic_cast<ThisAccessNode*>(n)) return "";
    // A place-returning invocation (`fn ref string` — e.g. a `ref V value()` accessor, `map.getRef(k)`,
    // `arr[i]` via a place method) is a BORROW, not a fresh owned rvalue. Hoisting it into a scope-dropped
    // temp would free a buffer it doesn't own (double-free with the real owner). Leave it to addrOfOperand,
    // which derefs the returned place as an lvalue and never drops it — mirrors the general-receiver guard.
    if (auto* iv = dynamic_cast<InvocationNode*>(n)) if (invocationReturnsPlace(iv)) return "";
    // `a[i]` is the SAME borrow reached through a different node kind, and it was not on this list.
    // Every form it lowers to hands back an element the container still owns: an intrinsic collection's
    // `__get` is a shallow struct copy sharing the buffer, a `ref T operator[]` is `(*Class__op_index(…))`,
    // a raw `p[i]` reads a pointee owned elsewhere. (A by-value user `operator[]` is not an emission
    // path — emitExpression routes only a place-returning one, and everything else falls to the raw
    // pointer read.) Hoisting one here emitted `kama_string __strtmp = (*…op_index(&a, i)); …;
    // kama_string__dtor(&__strtmp);`, freeing the array's buffer, which the array's own dtor then freed
    // again — a double free that aborts at SCOPE EXIT, not at the comparison, and only when the element
    // is heap-backed: a literal element has nothing to free twice, and the corpus only ever compared
    // against literals or iterated with `foreach (ref string …)`, which is why nothing caught it.
    // Pinned by tests/dynarr_string_index_compare.kama.
    if (dynamic_cast<ElementAccessNode*>(n)) return "";
    if (!exprIsString(e)) return "";
    std::string t = "__strtmp" + std::to_string(_tempCounter++);
    _hoisted.push_back("kama_string " + t + " = " + emitExpression(e) + ";");
    recordDestructibleLocal(t, "kama_string");
    return t;
}

// The static class type of an expression ("" if primitive/unknown).
// The C type of an assignable lvalue (a local/param or a field) — like exprClass, but KEEPS
// collection/string/Fixed types (exprClass drops them via its `isClass` filter, returning ""). Used by the
// assignment handler to detect an `ownsByValue` LHS (a `string`/collection local, param, or `this.`-field).
std::string CEmitter::lvalueCType(SharedExpression e)
{
    if (!e) return "";
    ASTNode* n = e.get();
    if (auto* id = dynamic_cast<IdentifierNode*>(n)) {
        if (!id->value) return "";
        auto it = _localCTypes.find(*id->value);                     // a local / param (incl. kama_string / List_*)
        if (it != _localCTypes.end()) return it->second;
        if (_currentClass) {                                         // a bare or `this.`-qualified field of the current class
            ClassInfo* owner = findFieldOwner(_currentClass, *id->value);
            if (owner)
                for (auto& f : owner->fields)
                    // Under the OWNER INSTANCE's type args, never the ambient _typeSubst — the same rule
                    // `exprClass` and `receiverScalarCType` already follow, and the one this resolver was
                    // never taught. A generic instance's ClassInfo is a COPY OF THE TEMPLATE
                    // (registerGenericTypeInst), so `f.type` is literally `T` and whatever happens to be
                    // bound wins: inside `Box<int64>`'s method, `r.item` on a `Reader<int32>` answered
                    // int64. `typeOfExpr` consults this resolver FIRST, so its wrong answer beat the three
                    // that had it right.
                    if (f.name == *id->value && f.type) return fieldCType(_currentClass->name, f);
        }
        return "";
    }
    if (auto* ma = dynamic_cast<MemberAccessNode*>(n)) {             // `obj.field` — resolve the receiver's field
        std::string recv = exprClass(ma->expression);
        // Auto-deref a smart-pointer / `Deref<T>` receiver to its pointee — but ONLY when the member is
        // not a field of the wrapper itself, the rule `exprClass`'s own member arm already follows and
        // the one this arm was never taught (the identifier arm above got its matching lesson first).
        // Unconditional, `this.alloc` inside `Owned<T, A>` resolved `alloc` on the POINTEE, which is
        // silent until the pointee also spells a field `alloc` with a different type: `BTreeNode<K,V,A>`
        // does, and `SortedMap.withAllocator` deliberately boxes its root as `Owned<BTreeNode<K,V,A>>`
        // (default `A`) — so in that instance's `adoptIn` the field answered the node's `BumpAllocator`
        // while the parameter, correctly, answered the box's own `GlobalAllocator`. `typeOfExpr`
        // consults this resolver FIRST, which is how a wrong answer here blinded the class-identity rule
        // to every generic body until it was found.
        bool memberOnWrapper = !recv.empty() && ma->identifier && ma->identifier->value
                            && _classes.count(recv) && findFieldOwner(&_classes[recv], *ma->identifier->value);
        if (!memberOnWrapper) {
            if (isSmartPtrClass(recv)) recv = _classes[recv].collElemClass;
            else { std::string dt = derefTarget(recv); if (!dt.empty()) recv = dt; }
        }
        if (!recv.empty() && ma->identifier && ma->identifier->value && _classes.count(recv)) {
            ClassInfo* owner = findFieldOwner(&_classes[recv], *ma->identifier->value);
            if (owner)
                for (auto& f : owner->fields)
                    if (f.name == *ma->identifier->value && f.type) return fieldCType(recv, f);
        }
        return "";
    }
    return "";
}

// The resolved return type of a CALL, UNFILTERED — it may name a class, a plain enum, or a primitive.
// Extracted from exprClass so the enum path can reuse it: exprClass keeps only what `isClass` accepts,
// which silently dropped plain enums (they live in `_enums`, not `_classes`) and is why a call could not
// be a `match` subject unless its enum happened to carry a payload. One resolver, two filters.
std::string CEmitter::callReturnTypeRaw(InvocationNode* inv)
{
    // Method call `recv.method(args)` — call->expression is a MemberAccessNode.
    if (auto* ma = inv->expression ? dynamic_cast<MemberAccessNode*>(inv->expression.get()) : nullptr) {
        std::string method = (ma->identifier && ma->identifier->value) ? *ma->identifier->value : "";
        std::string cls = exprClass(ma->expression);
        if (isSmartPtrClass(cls)) {   // an intrinsic (tryUpgrade/valid/…) — returnType is on the smart-ptr
            auto mit = _classes[cls].methods.find(method);
            if (mit != _classes[cls].methods.end() && mit->second.returnType) {
                std::string rc = cType(mit->second.returnType);
                return rc;
            }
            cls = _classes[cls].collElemClass;   // else auto-deref to the pointee's method
        }
        if (!cls.empty() && _classes.count(cls)) {
            ClassInfo* owner = nullptr;
            MethodInfo* mi = findMethod(&_classes[cls], method, &owner);
            // auto-deref via a user Deref<T> contract: the method may live on the pointee T.
            if (!mi) { std::string dt = derefTarget(cls);
                       if (!dt.empty() && _classes.count(dt)) mi = findMethod(&_classes[dt], method, &owner); }
            if (mi && mi->returnType) {
                // A method on a generic INSTANCE returns the template's unbound type
                // (`Weak<T>.tryUpgrade() -> Optional<Shared<T>>`). Bind the owning instance's
                // type args + its ctx so the return mangles concretely (else `match(w.tryUpgrade())`
                // can't find the Optional variant). A non-generic owner is rendered in its own file's
                // scope too, so a `Result<T, E>` naming an `E` the caller never imported still resolves.
                std::string ownerCls = owner ? owner->name : cls;
                // A `This` return type resolves to the method's OWNER — the same binding the operator
                // path makes for `This operator+`. Without it `t.merge(…)` on a named receiver reaches
                // cType with `_thisType` empty and dies as "`This` is only valid inside a type".
                ScopedStr _ts(_thisType, ownerCls);
                return cTypeInInstance(ownerCls, mi->returnType);
            }
        }
        // A CONTRACT (fat-pointer) receiver: the method lives in _interfaces, not _classes, so the
        // resolution above missed it. Resolve the contract method's declared return type — rendered
        // under the CONTRACT's own name-resolution scope (its imports/type-args, like the vtbl slot,
        // so a `Result<usize, IoError>` mangles concretely) — so `match (g.method())` on a contract
        // value is a first-class subject / value site without binding to a typed local first. #§1.2
        if (isInterface(cls)) {
            InterfaceInfo& ii = _interfaces[cls];
            for (auto& m : ii.methods) {
                if (m.name != method || !m.returnType) continue;
                ScopedContractNs _cns(_nsCtx, _collectingUnitPath, ii);
                std::string rc;
                { ContractSubst _cs(*this, ii); rc = cType(m.returnType); }   // binds T for a generic-contract instance
                return rc;
            }
            return "";
        }
        // A dot-on-type ctor call `V.of(x:…)` / `Vec3.make(…)`: the receiver NAMES a type, so `cls`
        // (exprClass of the receiver) is empty and the method-resolution above missed it. Recover the
        // constructed type — an infallible ctor returns the enclosing type by value — so an of/make
        // result is first-class in operand position (operators, ref-arg hoist, arg upcast), exactly like
        // the nameless inline ctor (Q3 below) it replaces. Concrete receiver only (a generic template
        // needs an instance, which operand position lacks — unless a TURBOFISH states it, which is what
        // `dotOnTypeInstance` recovers). #M8d.2
        //
        // The generic case matters because without it a method can never be chained off a generic ctor:
        // `Fixed::<int32, 16>.fromInt(n: 3).toInt()` classed its receiver as "" and died as "method call
        // on unresolved receiver", while the same call on a non-generic type worked. That is a silent
        // regression for any type that becomes generic, which is exactly what `Fixed16_16` just did.
        std::string dotTy;
        if (isTypeReceiver(ma, dotTy)) {
            std::string inst = dotOnTypeInstance(ma, dotTy, inv);
            auto ci = _classes.find(inst);
            if (ci != _classes.end()) {
                auto cit = ci->second.ctors.find(method);
                if (cit != ci->second.ctors.end()) {
                    // Infallible: the ctor yields the enclosing type by value.
                    if (!cit->second.isFallible) return inst;
                    // Fallible (`ctor Result<T, E> open(...)`): yield the DECLARED return type, so the call
                    // is a first-class `match` subject inline — `match (Widget.make(n: 7))`. The `::` bridge
                    // resolved this all along (it reads `mi->returnType`); the dot path returning "" here is
                    // what made an inline fallible ctor unusable as a subject. Now that construction has one
                    // spelling, that gap would leave the pattern unwritable.
                    //
                    // A GENERIC receiver (`G::<int32>.open(…)`) used to bail out to "" right here, on the
                    // grounds that rendering `Result<G<T>, Err>` needs the owning instance's type args bound
                    // and this path does not bind them. `cTypeInInstance` binds exactly those (and the
                    // instance's namespace context with them), and degrades to a plain `cType` for a
                    // non-generic receiver — so one call answers both, and the bail is gone.
                    //
                    // ⚠️ That bail and the discovery hole this commit fixes were IN SERIES, which is why
                    // deleting either one alone changed nothing measurable: with `G<int32>` never
                    // registered, `_classes.find(inst)` missed and control never got here at all.
                    if (cit->second.returnType) return cTypeInInstance(inst, cit->second.returnType);
                }
            }
        }
        return "";
    }
    // Static method call `Class::method(args)` — a qualified identifier with no receiver expression
    // (`File::open(...)`). Resolve the class, find the method, return its (class) return type, so a
    // fallible factory is usable inline as a `match` subject / value site — not only after binding to
    // a typed local. Mirrors the `Type::method` resolution in emitFnPtrBind.
    if (inv->identifier && inv->identifier->value && !inv->expression
        && inv->identifier->qualifier && !inv->identifier->qualifier->empty()) {
        auto prefix = std::make_shared<StringList>();
        for (size_t i = 0; i + 1 < inv->identifier->qualifier->size(); ++i)
            prefix->push_back((*inv->identifier->qualifier)[i]);
        std::string cls = resolveUserName(*inv->identifier->qualifier->back(), prefix);
        // `Union::Variant(field: v)` — a CONSTRUCTION, not a call, and it yields the enum. Read the same
        // way the emitter reads it (resolveVariantType, so a generic instance resolves through the
        // target-type context), and checked BEFORE the static-method arm because a variant and a static
        // method share this spelling. Without it a payload variant literal was typed as nothing, so
        // `x == E::Other(code: 3)` never reached the comparison rule and emitted a raw C `==` between two
        // structs — the same hole the payload-less literal had, one node kind along.
        if (ClassInfo* vt = resolveVariantType(cls))
            for (auto& v : vt->variants)
                if (v.name == *inv->identifier->value) return vt->name;
        if (_classes.count(cls)) {
            ClassInfo* owner = nullptr;
            MethodInfo* mi = findMethod(&_classes[cls], *inv->identifier->value, &owner);
            if (mi && mi->returnType) return cTypeInInstance(owner ? owner->name : cls, mi->returnType);
        }
    }

    // Q3: a bare inline constructor `Vec3(x: …)` — its own class (so an inline ctor works as an
    // operator operand). Checked before _funcs since a class name is never a function.
    if (inv->identifier && inv->identifier->value && !inv->expression
        && (!inv->identifier->qualifier || inv->identifier->qualifier->empty())) {
        std::string rn = resolveUserName(*inv->identifier->value, inv->identifier->qualifier);
        if (isClass(rn) && _classes.count(rn) && !_classes[rn].isIntrinsicColl) return rn;
    }
    // Free / qualified function call — its C return type, if that names a class.
    // `addr(of: place)` — the builtin's result is a pointer to the place's type, and it is READ-ONLY when
    // the place roots in a const binding: that is how `addr(of:)` on `const this` / a `const` local hands
    // back an `UnsafeConstPtr<T>` instead of being refused, and the sinks (rejectConstPtrWiden) are what
    // keep it from becoming a writable one. Typed by `lvalueCType`, so an element place (`addr(of:
    // this.data[i])`) answers "" and stays silent, exactly as it did before this arm existed.
    if (inv->identifier && inv->identifier->value && *inv->identifier->value == "addr" && !inv->expression
        && (!inv->identifier->qualifier || inv->identifier->qualifier->empty())
        && inv->args && inv->args->size() == 1 && (*inv->args)[0] && (*inv->args)[0]->expression) {
        SharedExpression a = (*inv->args)[0]->expression;
        std::string ct = lvalueCType(a);
        bool isConst = rootIsConst(rootBinding(a)) || chainThroughConstPlace(a);
        // A PLACE CALL (`addr(of: b.at(i: 0))`, `addr(of: pick(d: d, i: 0))`) and a user-indexed element
        // (`addr(of: cv[i])`) are places `lvalueCType` does not type. Their element type is what the
        // place-returner / `operator[]` declared; without it the pointer would be untyped, and a
        // `const ref T` place's address would silently bind to an `UnsafePtr<T>`.
        if (ct.empty())
            if (auto* pin = dynamic_cast<InvocationNode*>(a.get()))
                if (invocationReturnsPlace(pin)) ct = callReturnTypeRaw(pin);
        if (ct.empty())
            if (dynamic_cast<ElementAccessNode*>(a.get()) && chainThroughConstPlace(a)) ct = indexElemTypeRaw(a);
        // A module `static` / `comptime` is neither a local nor a field, so `lvalueCType` does not know
        // it. A `comptime` is real `static const` storage (SPEC § Compile-time constants), so its address
        // is read-only — `addr(of: CAP)` into an `UnsafePtr<int32>` was accepted until 0.9.204, and
        // clang's `-Wdiscards-qualifiers` was the only thing that ever saw the launder
        // (tests/mod_export_const.d).
        if (ct.empty())
            if (auto* id = dynamic_cast<IdentifierNode*>(a.get()))
                if (id->value) {
                    const std::string key = resolveModuleVar(*id->value, id->qualifier);
                    auto ms = key.empty() ? _moduleStatics.end() : _moduleStatics.find(key);
                    if (ms != _moduleStatics.end() && ms->second) { ct = cType(ms->second); isConst = _constStatics.count(key) > 0; }
                }
        if (ct.empty()) return "";
        return ct + (isConst ? " const*" : "*");
    }
    if (inv->identifier && inv->identifier->value) {
        auto f = _funcs.find(resolveFunc(*inv->identifier->value, inv->identifier->qualifier));
        if (f != _funcs.end()) return f->second.retCType;
    }
    return "";
}

// The element type of `a[i]`, UNFILTERED — it may name a class or a primitive. Extracted from exprClass
// for the same reason `callReturnTypeRaw` was: exprClass keeps only what `isClass` accepts, so a
// container of primitives answered "" and a type rule could not tell `DynamicArray<int32>`'s element
// from an unresolved receiver. Pure resolution (no emission) — mirrors the front of collectionElemAccess.
std::string CEmitter::indexElemTypeRaw(SharedExpression e)
{
    auto* ea = dynamic_cast<ElementAccessNode*>(e.get());
    if (!ea) return "";
    SharedExpression recv = ea->expression ? ea->expression
                                           : std::static_pointer_cast<ExpressionNode>(ea->identifier);
    std::string cls = exprClass(recv);
    if (!cls.empty() && _classes.count(cls) && _classes[cls].isIntrinsicColl) {
        // An intrinsic collection records its element CLASS, and leaves it empty for a primitive
        // element — the same conflation, one level down. `_collections` carries the C type for both.
        const std::string& ec = _classes[cls].collElemClass;
        if (!ec.empty()) return ec;
        auto ci = _collections.find(cls);
        return ci != _collections.end() ? ci->second.elemCType : "";
    }
    if (cls == "kama_string") return "uint8_t";          // `s[i]` is a byte
    // a user place-`operator[]` element resolves to the operator's element type (its `ref T`), so
    // `m[i][j]` / `m[i].field` chain. Bind `This`/the instance's type args for the return type.
    if (MethodInfo* op = userIndexOp(cls)) {
        ScopedStr _ts(_thisType, cls);
        // Bind the owning generic instance's type args so `operator[]`'s `ref T` resolves concretely
        // (`v[i]` on a `List<Probe>` -> Probe), the same as a method return.
        NsCtx savedCtx = _nsCtx;
        std::map<std::string, SharedIdentifier> savedSubst = _typeSubst;
        auto gi = _genericTypeInsts.find(cls);
        if (gi != _genericTypeInsts.end()) {
            _typeSubst.clear();
            const std::vector<std::string>& ps = _genericTypeParams[gi->second.templateKey];
            for (size_t i = 0; i < ps.size() && i < gi->second.typeArgs.size(); ++i)
                _typeSubst[ps[i]] = gi->second.typeArgs[i];
            _nsCtx = _genericTypeInstCtx.count(cls) ? _genericTypeInstCtx[cls] : _genericTypeCtx[gi->second.templateKey];
        }
        std::string rt = cType(op->returnType);
        _typeSubst = savedSubst; _nsCtx = savedCtx;
        return rt;
    }
    // A raw `UnsafePtr<T>` field index (`this.data[i]` in unsafe container code): resolve to the pointer's
    // element type, so a `drop`/`copy`/variant hand-off of the element knows what it is.
    return ptrElemType(e);
}

std::string CEmitter::exprClass(SharedExpression e)
{
    if (!e) return "";
    ASTNode* n = e.get();

    if (dynamic_cast<StringNode*>(n)) return "kama_string";   // a string literal is the `string` primitive
    if (auto* is = dynamic_cast<InterpolatedStringNode*>(n)) {
        // A tagged string takes the tag function's return type; a plain interpolation lowers to a `string`.
        if (is->tag) {
            std::string key = resolveFunc(*is->tag, nullptr);
            if (_funcs.count(key)) { std::string rc = _funcs[key].retCType; return (isClass(rc) || rc == "kama_string") ? rc : ""; }
        }
        return "kama_string";
    }

    if (auto* ad = dynamic_cast<AsDowncastNode*>(n)) {        // `.as<T>()` -> Optional<T>
        std::string oc = cType(optionalTypeNode(ad->type));
        return isClass(oc) ? oc : "";
    }

    if (dynamic_cast<ThisAccessNode*>(n))
        return _currentClass ? _currentClass->name : "";

    if (auto* id = dynamic_cast<IdentifierNode*>(n)) {
        if (!id->value) return "";
        auto it = _localTypes.find(*id->value);
        if (it != _localTypes.end()) return it->second;
        // A module-level `static` (MCU step 1): resolve its class type (InlineArray / value struct) so
        // element access and method dispatch work — but a local of the same name shadows it (checked first).
        if (!_localTypes.count(*id->value)) {
            auto ms = _moduleStatics.find(qualify(*id->value));
            if (ms != _moduleStatics.end()) { std::string ct = cType(ms->second); if (isClass(ct)) return ct; }
        }
        if (_currentClass) {
            ClassInfo* owner = findFieldOwner(_currentClass, *id->value);
            if (owner)
                for (auto& f : owner->fields)
                    if (f.name == *id->value && f.type) {   // resolve under the OWNER instance's type args
                        std::string ft = fieldCType(_currentClass->name, f);
                        if (isClass(ft)) return ft;
                    }
        }
        return "";
    }

    if (auto* ma = dynamic_cast<MemberAccessNode*>(n)) {
        std::string recv = exprClass(ma->expression);
        // Auto-deref a smart-pointer / `Deref<T>` receiver to its pointee T — but ONLY when the member is
        // not a field of the wrapper itself. A smart pointer's OWN field (e.g. `Owned<T,A>.alloc`, accessed
        // as `this.alloc` inside its dtor) must resolve on the wrapper, not be forwarded to the pointee.
        bool memberOnWrapper = !recv.empty() && ma->identifier && ma->identifier->value
                            && _classes.count(recv) && findFieldOwner(&_classes[recv], *ma->identifier->value);
        if (!memberOnWrapper) {
            if (isSmartPtrClass(recv)) recv = _classes[recv].collElemClass;   // auto-deref: look up on T
            else { std::string dt = derefTarget(recv); if (!dt.empty()) recv = dt; }   // user Deref<T> auto-deref
        }
        if (!recv.empty() && ma->identifier && ma->identifier->value && _classes.count(recv)) {
            ClassInfo* owner = findFieldOwner(&_classes[recv], *ma->identifier->value);
            if (owner)
                for (auto& f : owner->fields)
                    if (f.name == *ma->identifier->value && f.type) {
                        // Resolve the field type under its OWNER INSTANCE's type args — NOT the ambient
                        // _typeSubst, which inside an enum-variant/arg emission may bind only some params
                        // (e.g. `Optional<T>`'s `T`), leaving a nested `DynamicArray<T,A>`'s `A` unbound.
                        std::string ft = fieldCType(recv, f);
                        if (isClass(ft)) return ft;
                    }
        }
        return "";
    }

    // `list[i]` / `a[i]` resolves to the ELEMENT type, so `list[i].m()` finds the method.
    if (dynamic_cast<ElementAccessNode*>(n)) {
        std::string et = indexElemTypeRaw(e);
        return isClass(et) ? et : "";
    }

    // a CALL RESULT's static class (pure resolution — no emission), so a call can be a
    // `match` subject / value site (`match(w.tryUpgrade())`). A class return maps to its name; a
    // primitive/void return stays "".
    if (auto* inv = dynamic_cast<InvocationNode*>(n)) {
        std::string rc = callReturnTypeRaw(inv);
        return isClass(rc) ? rc : "";
    }

    // a user-operator result carries the operator's return type, so a NESTED operator
    // (`a + b + c`, `-a + b`, `(a + b) * s`) resolves and the enclosing operator can be found.
    if (auto* be = dynamic_cast<BinaryExpressionNode*>(n))
        return operatorResultClass(be->token, /*binary*/1, be->LHS, be->RHS);
    if (auto* su = dynamic_cast<SimpleUnaryExpressionNode*>(n))
        return operatorResultClass(su->token, /*unary*/0, su->expression, nullptr);
    if (auto* pr = dynamic_cast<PreIncrDecrNode*>(n))
        return operatorResultClass(pr->token, 0, pr->expression, nullptr);
    if (auto* po = dynamic_cast<PostIncrDecrNode*>(n))
        return operatorResultClass(po->token, 0, po->expression, nullptr);

    // A value-producing `match`/ternary used directly as a value site (notably as another `match`'s
    // SUBJECT, `match (inner_match) { … }` / `match (c ? A(x) : B())`): resolve to the common class of
    // its result branches, so subject inference finds the tagged union without a bind-to-a-local first.
    // Both branches/arms share a type; the first that resolves is representative.
    if (auto* tx = dynamic_cast<TernaryExpressionNode*>(n)) {
        std::string lc = exprClass(tx->LHS);
        return !lc.empty() ? lc : exprClass(tx->RHS);
    }
    if (auto* mx = dynamic_cast<MatchNode*>(n)) {
        if (mx->arms)
            for (auto& a : *mx->arms) {
                SharedExpression v = a->body;                        // single-expression arm
                if (!v && a->block && a->block->statements)          // block arm: its terminal `:= expr;`
                    for (auto& st : *a->block->statements)
                        if (auto* av = dynamic_cast<ArmValueNode*>(st.get())) v = av->value;
                if (!v) continue;                                    // diverging arm (return/break) — no value
                std::string ac = exprClass(v);
                if (!ac.empty()) return ac;
            }
        return "";
    }
    return "";
}

// the class an operator expression evaluates to = the resolved operator's return type
// (a class), else "" (a primitive result like a comparison's `bool`, or no matching operator).
std::string CEmitter::operatorResultClass(int opToken, int arity, SharedExpression lhs, SharedExpression rhs)
{
    std::string lc = exprClass(lhs);
    ClassInfo* owner = nullptr;
    MethodInfo* mi = nullptr;
    if (arity == 0) {   // unary — `op_<sym>` on the operand type
        std::string opName = operatorMangle(opToken, 0);
        if (opName.empty() || !userOperandType(lc, _classes)) return "";
        mi = findMethod(&_classes[lc], opName, &owner);
        if (!(mi && mi->isOperator)) return "";
    } else {            // binary — resolve by operand types (mirrors the dispatch)
        mi = findBinaryOperator(opToken, lc, exprClass(rhs), &owner);
        if (!mi) return "";
    }
    ScopedStr _ts(_thisType, owner ? owner->name : lc);   // a `This` return type resolves to the operator's owner
    std::string rt = cType(mi->returnType);
    return isClass(rt) ? rt : "";
}

// `virtual(maxDepth: N)` — read and validate N. Returns -1 on any error, which the callers read as
// "already diagnosed": 0 has to keep meaning "never annotated", or a bad annotation would also draw the
// "you must state a budget" complaint at an author who just did.
//
// The number exists so a designer meets the depth limit when they OPT IN to extensibility, rather than
// discovering it later when a third level is refused. That is the same doctrine as requiring a deriving
// type to be written `final`: the compiler deliberately does not infer what the author should see.
int CEmitter::readMaxDepth(const SharedModifier& mod, int line)
{
    if (!mod->args || mod->args->size() != 1) {
        unsupported("`virtual`/`abstract` takes exactly one argument, the extension budget "
                    "(`virtual(maxDepth: 1)`)", line);
        return -1;
    }
    auto& a = (*mod->args)[0];
    if (!a || !a->name || !a->name->value || *a->name->value != "maxDepth") {
        unsupported(("the extension budget is spelled `maxDepth:` — `"
                     + std::string(a && a->name && a->name->value ? *a->name->value : "")
                     + ":` is not a modifier argument kama knows").c_str(), line);
        return -1;
    }
    long n = -1;
    if (auto* lit = dynamic_cast<Int32Node*>(a->expression.get())) n = lit->value;
    if (n < 0) {
        unsupported("`maxDepth:` takes a literal whole number — how many levels may be added below this "
                    "type", line);
        return -1;
    }
    // Both bounds are ERRORS, never clamps: a clamp would hide exactly the surprise this annotation
    // exists to prevent.
    if (n == 0) {
        unsupported("`maxDepth: 0` says this type is extensible but that nothing may extend it — to seal "
                    "it, declare it `final` instead (which IS a budget of 0)", line);
        return -1;
    }
    if (n > KAMA_INHERIT_DEPTH) {
        unsupported(("`maxDepth: " + std::to_string(n) + "` exceeds the inheritance depth limit of "
                     + std::to_string(KAMA_INHERIT_DEPTH) + " this kama was built with "
                     "(KAMA_INHERIT_DEPTH)").c_str(), line);
        return -1;
    }
    return (int)n;
}

// Is `e` the expression `this.base`? (`base` is a keyword, so no field can ever be spelled that way.)
bool CEmitter::isThisBase(SharedExpression e)
{
    auto* ma = dynamic_cast<MemberAccessNode*>(e.get());
    return ma && ma->identifier && ma->identifier->value && *ma->identifier->value == "base"
        && dynamic_cast<ThisAccessNode*>(ma->expression.get()) != nullptr;
}

// `this.base = <expr>;` as a whole statement -> the <expr>. Null for anything else, including a
// compound assignment (`this.base += …`), which is not an install.
SharedExpression CEmitter::baseInstallOf(SharedStatement st)
{
    auto* as = dynamic_cast<AssignmentNode*>(st.get());
    if (!as || as->token != EQ || !isThisBase(as->unaryExpression)) return SharedExpression();
    return as->expression;
}

// Does `e` name `this` anywhere inside it? Used to reject `this.base = Base.make(x: this.y)`: the install
// is emitted before `self` is bound, so `this` genuinely does not exist there yet. Only the shapes an
// argument can realistically take are walked — anything unrecognised answers "no", which is safe because
// the emitter would then produce a C error naming `self` rather than accepting bad code.
bool CEmitter::exprMentionsThis(SharedExpression e)
{
    if (!e) return false;
    if (dynamic_cast<ThisAccessNode*>(e.get())) return true;
    if (auto* ma = dynamic_cast<MemberAccessNode*>(e.get()))  return exprMentionsThis(ma->expression);
    if (auto* ea = dynamic_cast<ElementAccessNode*>(e.get())) return exprMentionsThis(ea->expression);
    if (auto* un = dynamic_cast<SimpleUnaryExpressionNode*>(e.get())) return exprMentionsThis(un->expression);
    if (auto* ho = dynamic_cast<HandoffNode*>(e.get()))       return exprMentionsThis(ho->value);
    if (auto* ca = dynamic_cast<CastNode*>(e.get()))          return exprMentionsThis(ca->unaryExpression);
    if (auto* bn = dynamic_cast<BinaryExpressionNode*>(e.get()))
        return exprMentionsThis(bn->LHS) || exprMentionsThis(bn->RHS);
    if (auto* iv = dynamic_cast<InvocationNode*>(e.get())) {
        if (exprMentionsThis(iv->expression)) return true;
        if (iv->args)
            for (auto& a : *iv->args) if (a && exprMentionsThis(a->expression)) return true;
    }
    return false;
}

// `<expr>.base` reached a position where it means nothing. Three distinct answers, because the three
// mistakes are different: the type has no base at all, the receiver is not `this`, or it is a READ of a
// thing that is only ever written. The grammar admits `d.base` deliberately (kama.y `member_access`) so
// that this can be a sentence rather than `syntax error, unexpected BASE`.
void CEmitter::rejectBaseMember(MemberAccessNode* ma)
{
#if !KAMA_INHERITANCE
    rejectInheritance("`this.base`", ma->line);
#else
    bool isThis = dynamic_cast<ThisAccessNode*>(ma->expression.get()) != nullptr;
    if (!_currentClass)
        unsupported("`this.base` is only meaningful inside a constructor of a derived type", ma->line);
    else if (!_currentClass->base)
        unsupported(("'" + _currentClass->name + "' has no base class, so `this.base` names nothing "
                     "(only a type declared `extends …` has one)").c_str(), ma->line);
    else if (!isThis)
        unsupported(("the base part of a '" + _currentClass->name + "' is reachable only from inside it — "
                     "write `this.base = " + _currentClass->baseName + ".<ctor>(…);` as the first statement "
                     "of its constructor").c_str(), ma->line);
    else
        unsupported(("`this.base` may only be ASSIGNED, as the first statement of a constructor "
                     "(`this.base = " + _currentClass->baseName + ".<ctor>(…);`) — to reach an inherited "
                     "member write `base.<member>`").c_str(), ma->line);
#endif
}

// obj.field / this.field — splice the __base. chain to the declaring ancestor.
std::string CEmitter::dotOnTypeAdvice(DotMemberKind k, const std::string& disp, const std::string& typeName,
                                      const std::string& member)
{
    switch (k) {
    case DotMemberKind::Field:
        return "`" + member + "` is a field. Read it from a value (`obj." + member + "`)";
    case DotMemberKind::Const:
        return "`" + member + "` is a `comptime` constant of `" + disp + "` — read it as `" + disp + "::" + member + "`";
    case DotMemberKind::Static:
        // On a GENERIC owner the turbofish is mandatory (a static has nothing to infer from), so
        // `Type::name(...)` would be the one spelling that does not exist — name the real one.
        return _genericTypeParams.count(typeName)
             ? ("`" + member + "` is a static function — call it with `" + disp + "::<...>::" + member + "(...)`")
             : ("`" + member + "` is a static function — call it with `" + disp + "::" + member + "(...)`");
    case DotMemberKind::Ctor:
        return "`" + member + "` is a constructor — call it (`" + disp + "." + member + "(...)`)";
    case DotMemberKind::Method:
        return "`" + member + "` is a method — call it on a value (`obj." + member + "(...)`)";
    }
    return "";
}

bool CEmitter::isValueName(const std::string& nm, SharedStringList qualifier)
{
    const bool q = qualifier && !qualifier->empty();
    if (!q && (_localTypes.count(nm) || _paramNames.count(nm) || _refParams.count(nm) || _comptimeSubst.count(nm)))
        return true;
    if (!q && _currentClass && findFieldOwner(_currentClass, nm)) return true;
    if (!resolveModuleVar(nm, qualifier).empty()) return true;
    if (_funcs.count(resolveFunc(nm, qualifier))) return true;
    return false;
}

bool CEmitter::rejectDotOnTypeRead(MemberAccessNode* ma, IdentifierNode* head, const std::string& field)
{
    const std::string disp = *head->value;
    std::string t = resolveUserName(disp, head->qualifier);
    // A type PARAMETER head reads through what it is bound to — a real type, or the opaque stand-in a probe
    // mints (which rejectUnprovenBound answers for).
    auto ts = _typeSubst.find(disp);
    if (ts != _typeSubst.end() && ts->second) {
        const std::string ct = primKey(ts->second);
        if (_classes.count(ct)) t = ct;
    }
    auto ei = _enums.find(t);
    if (ei != _enums.end()) {
        bool has = false;
        for (auto& m : ei->second.members) if (m.name == field) { has = true; break; }
        if (has)
            unsupported(("`" + disp + "." + field + "` — `.` reads a value's member; a variant is reached through "
                         "its type with `::` (`" + disp + "::" + field + "`)").c_str(), ma->line);
        else
            unsupported(("`" + disp + "` has no variant `" + field + "`").c_str(), ma->line, field);
        return true;
    }
    ClassInfo* ci = nullptr;
    if (_classes.count(t))            ci = &_classes[t];
    else if (_genericTypes.count(t))  ci = &_genericTypes[t];
    if (!ci) {
        if (_interfaces.count(t)) {
            unsupported(("`" + disp + "` is a contract — it has no members to read; reach `" + field
                         + "` through a value that implements it").c_str(), ma->line);
            return true;
        }
        return false;
    }
    if (ci->isVariant) {   // a tagged enum is a class in the emitter; its variants are `::` items too
        bool has = false;
        for (auto& vc : ci->variants) if (vc.name == field) { has = true; break; }
        if (has)
            unsupported(("`" + disp + "." + field + "` — `.` reads a value's member; a variant is reached through "
                         "its type with `::` (`" + disp + "::" + field + "`)").c_str(), ma->line);
        else
            unsupported(("`" + disp + "` has no variant `" + field + "`").c_str(), ma->line, field);
        return true;
    }
    DotMemberKind kind;
    ClassInfo* owner = nullptr;
    MethodInfo* mi = nullptr;
    if (_typeConsts.count(t + "::" + field))         kind = DotMemberKind::Const;
    else if (findFieldOwner(ci, field))               kind = DotMemberKind::Field;
    else if ((mi = findMethod(ci, field, &owner)))    kind = mi->isCtor ? DotMemberKind::Ctor
                                                           : mi->isStatic ? DotMemberKind::Static : DotMemberKind::Method;
    else {
        if (rejectUnprovenBound(t, field, ma->line)) return true;
        unsupported(("`" + disp + "` has no member `" + field + "`").c_str(), ma->line, field);
        return true;
    }
    unsupported(("`" + disp + "." + field + "` — `.` reads a value's member; "
                 + dotOnTypeAdvice(kind, disp, t, field)).c_str(), ma->line);
    return true;
}

std::string CEmitter::emitMemberAccess(MemberAccessNode* ma)
{
    std::string field = (ma->identifier && ma->identifier->value) ? *ma->identifier->value : "";
    if (!ma->expression) {
        unsupported("static member access", ma->line);
        return field;
    }
    // `this.base` is not a member — it is the ONE place a derived constructor installs its base part, and
    // it is consumed before the body is walked (emitMethodOrCtorBody). Reaching here means it was used
    // somewhere it does not belong, so answer with which of the three it was. `base` is a keyword, so no
    // field can ever be named `base` and this can never shadow a real member.
    if (field == "base") { rejectBaseMember(ma); return "0"; }
    // A TYPE as the head of a read (`K.A`, `V.n`, `V.N`): dot-on-type is the constructor spelling and nothing
    // else (SPEC "Scope resolution uses `::`"). The call form has refused this for a long time; the read
    // form used to emit `(K).A` and leave it to the C compiler. A live binding of the same spelling wins.
    if (auto* rid = dynamic_cast<IdentifierNode*>(ma->expression.get()))
        if (rid->value && !rid->synthesized && !isValueName(*rid->value, rid->qualifier)
            && rejectDotOnTypeRead(ma, rid, field))
            return "0";
    std::string cls = exprClass(ma->expression);
    // Auto-deref an Owned/Shared: `n.field` -> `(n).ptr->[base]field` (T*).
    // A Weak can't be dereffed — it must be upgraded with upgrade() first.
    if (isSmartPtrClass(cls)) {
        if (smartKind(cls) == CollKind::Weak) {
            unsupported("cannot access a field through Weak<T>; call .tryUpgrade()", ma->line);
            return field;
        }
        std::string T = _classes[cls].collElemClass;
        std::string basePath;
        ClassInfo* owner = findFieldOwner(&_classes[T], field);
        if (owner) { basePath = basePathTo(&_classes[T], owner); checkFieldAccess(owner, field, ma->line);
                     recordFieldRef(owner, field, ma->identifier.get()); }
        else if (_classes.count(T)) { rejectMissingField(&_classes[T], T, ma, field); return "0"; }
        return "(" + emitExpression(ma->expression) + ").ptr->" + basePath + field;
    }
    std::string basePath;
    if (!cls.empty() && _classes.count(cls)) {
        ClassInfo* owner = findFieldOwner(&_classes[cls], field);
        if (owner) { basePath = basePathTo(&_classes[cls], owner); checkFieldAccess(owner, field, ma->line);
                     recordFieldRef(owner, field, ma->identifier.get()); }
        else {
            // the field is NOT on the wrapper itself — auto-deref via a `Deref<T>` contract to the
            // pointee: `w.field` -> `Cls__deref(&(w))->[base]field` (a T*). (Only when not on `cls`.)
            std::string dtgt = derefTarget(cls);
            ClassInfo* fo = dtgt.empty() || !_classes.count(dtgt) ? nullptr : findFieldOwner(&_classes[dtgt], field);
            // Neither the type nor its `Deref<T>` pointee has the field: kama's error, not the C
            // compiler's "no member named 'zz' in 'struct …'" against a struct name nobody wrote.
            if (!fo) { rejectMissingField(&_classes[cls], cls, ma, field); return "0"; }
            if (fo) {
                // `derefMut()` for a mutable receiver, `deref()` (a read-only place) for a const one or a
                // type that implements only `Deref<T>`; a write through the read-only form is refused by
                // checkConstWrite (chainThroughConstPlace knows this arm).
                MethodInfo* dref = derefAccessor(cls, ma->expression);
                std::string bp = basePathTo(&_classes[dtgt], fo);
                checkFieldAccess(fo, field, ma->line);
                recordFieldRef(fo, field, ma->identifier.get());
                if (dref) return dref->cName + "(&(" + emitExpression(ma->expression) + "))->" + bp + field;
            }
        }
    }
    if (dynamic_cast<ThisAccessNode*>(ma->expression.get())) {
        if (_inStaticMethod) unsupported("a `static` method has no `this`", ma->line);
        _ctorSelfUsed = true;               // in a ctor: the implicit `this` storage is needed
        return "self->" + basePath + field;
    }
    // Emit the receiver as a PLACE: for an indexed-element receiver this is `(*NAME__at(&a,i)).field`
    // (a real lvalue), so `arr[i].field = v` is a valid write — not `(__get(...)).field = v` (assigning
    // to a member of an rvalue). `emitPlace` is identity for a name/`this`/nested member access.
    //
    // No class resolved for the receiver. That is NOT "unknown": `exprClass` is empty for a primitive, a
    // plain-enum value, a raw `UnsafePtr<T>` element (untyped to ownership by design — see
    // ptrLocalElemType) and an opaque parameter alike, so only a POSITIVE answer may reject here. A
    // primitive or a variant value has no fields; everything else falls through as it always has.
    if (cls.empty()) {
        if (_probingTemplate && deferUnknownWhileProbing(classifyDeferredReceiver(ma->expression))) return "0";
        const std::string rct = receiverScalarCType(ma->expression);
        const std::string rk  = rct.empty() ? std::string() : primKeyOfCType(rct);
        // primKeyOfCType echoes what it does not know, so a changed spelling is the positive test — except
        // `bool`, the one primitive whose C spelling IS its kama spelling.
        if (!rk.empty() && (rk != rct || rct == "bool")) {
            unsupported(("`" + rk + "` has no field `" + field + "` — a primitive has no members").c_str(), ma->line, field);
            return "0";
        }
        // A raw pointer has no fields either — its POINTEE does, and kama reaches a pointee by indexing. This
        // fell through to `(p).x`, a C member access on a pointer, and surfaced as clang's "did you mean
        // `->`?" against a struct name nobody wrote.
        if (!rct.empty() && rct.back() == '*') {
            const std::string place = unparseExpr(ma->expression);
            unsupported(("`" + place + "` is a raw pointer, which has no field `" + field + "` — its pointee does; "
                         "read or write it through the pointer as `" + place + "[0]." + field + "`").c_str(),
                        ma->line, field);
            return "0";
        }
        const std::string et = exprEnumType(ma->expression);
        if (!et.empty()) {
            unsupported(("`" + et + "` is a plain enum — a variant value has no field `" + field + "`").c_str(), ma->line, field);
            return "0";
        }
    }
    return "(" + emitPlace(ma->expression) + ")." + basePath + field;
}

// `v.zz` where `v`'s type is KNOWN and has no such field. Says what the name is when it is something
// (a method named without its call), the bound that is missing when the type is an opaque parameter,
// and "no field" only when the type really has none of that name.
void CEmitter::rejectMissingField(ClassInfo* ci, const std::string& cls, MemberAccessNode* ma, const std::string& field)
{
    if (rejectUnprovenBound(cls, field, ma->line)) return;
    ClassInfo* owner = nullptr;
    if (findMethod(ci, field, &owner)) {
        const std::string place = unparseExpr(ma->expression);
        unsupported(("`" + place + "." + field + "` names a method — call it (`" + place + "." + field + "(...)`)").c_str(),
                    ma->line, field);
        return;
    }
    unsupported(("`" + cls + "` has no field `" + field + "`").c_str(), ma->line, field);
}

// Dispatch a method call on a receiver of static class `clsName`.
std::string CEmitter::emitDispatch(const std::string& clsName, const std::string& recvPtr,
                                   const std::string& method, SharedArgumentList args, int srcLine,
                                   const IdentifierNode* site, SharedExpression recvExpr)
{
    if (!_classes.count(clsName)) { unsupported("call on unknown class", srcLine); return "0"; }
    // OBJECT-GRAPH EDGE. Inside a serde twin, `elem.serialize(w)` on a `Shared`/`Weak` to a node writes an
    // ID, not the pointee. It must be decided HERE, before anything else: the triad is method-free, so
    // `serialize` is not on the handle and the auto-deref fallback below would otherwise resolve it on the
    // POINTEE and write the object inline — losing identity, and not terminating on a cycle. That is
    // exactly the silent-wrong write a hand-rolled body produced before this existed.
    if (!_serGraphArg.empty() && method == "serialize" && _graphEdgeHelperFor.count(clsName)) {
        std::vector<ParamSig> ps;
        ParamSig w; w.name = "w"; w.byRef = true; w.className = "Serializer"; ps.push_back(w);
        return emitReorderedCall(clsName + "__serializeEdge", "(" + clsName + "*)" + recvPtr,
                                 ps, args, srcLine, _serGraphArg);
    }
    ClassInfo* owner = nullptr;
    MethodInfo* mi = findMethod(&_classes[clsName], method, &owner);
    // `Atomic<bool>` has no arithmetic: `fetchAdd`/`fetchSub` add the cell's raw bytes, and `true + 1` is
    // the byte 2, which is not a `_Bool` (undefined, and it does not "flip"). A use-site rule rather than a
    // `when` on the method, because no bound spells "an integer" (ROADMAP §2); the flip is `swap`.
    // Judged at the USER's call, not inside `Atomic`'s own body: `fetchAdd` forwards to `fetchAddExplicit`
    // there, and that forwarding is emitted for every instance, `Atomic<bool>` included.
    if (mi && isAtomicClass(clsName) && !(_currentClass && isAtomicClass(_currentClass->name))
        && (method == "fetchAdd" || method == "fetchSub" || method == "fetchAddExplicit" || method == "fetchSubExplicit")) {
        auto gi = _genericTypeInsts.find(clsName);
        const int elv = (gi != _genericTypeInsts.end() && !gi->second.typeArgs.empty() && gi->second.typeArgs[0])
                        ? gi->second.typeArgs[0]->builtInVal : -1;
        if (elv == IDENTIFIER_BOOL_VAL) {
            unsupported(("`" + method + "` needs an integer element — `Atomic<bool>` is a flag: set it with "
                         "`store(value:)`, flip it with `swap(value:)` (which hands back the prior value), or "
                         "`compareExchange`").c_str(), srcLine);
            return "0";
        }
        // A float cell: the same shim would add the two BIT PATTERNS, and no hardware has a lock-free float
        // add anyway — the portable accumulate is a compareExchange loop, which is what the message hands back.
        if (elv == IDENTIFIER_FLOAT32_VAL || elv == IDENTIFIER_FLOAT64_VAL) {
            unsupported(("`" + method + "` needs an integer element — there is no atomic float arithmetic (no "
                         "hardware has a lock-free float add): accumulate with a `compareExchange` loop — "
                         "`seen = c.load(); while (!c.compareExchange(expected: ref seen, desired: seen + d)) {}`").c_str(), srcLine);
            return "0";
        }
    }
    if (!mi) {
        // Auto-deref fallback: `method` is not on `clsName`, but `clsName` implements `Deref<T>` and the
        // method IS on the pointee `T`. Resolve on `T` and call through `clsName__deref(recvPtr)` — a
        // `T*` — as the receiver. Recursive, so `A: Deref<B>, B: Deref<T>` chains transitively.
        std::string tgt = derefTarget(clsName);
        bool roDeref = false;
        MethodInfo* dref = tgt.empty() ? nullptr : derefAccessor(clsName, recvExpr, &roDeref);
        if (dref && _classes.count(tgt)) {
            ClassInfo* towner = nullptr;
            if (MethodInfo* tmi = findMethod(&_classes[tgt], method, &towner)) {
                // Through the READ-ONLY half (`deref()`: the receiver is const, or the type implements only
                // `Deref<T>`), the pointee is a const receiver — only its `const fn`s are reachable. Said here
                // in kama's words; the C backstop (`T const*` into a `T*` self) would otherwise say it.
                if (roDeref && !tmi->isConst && !tmi->isStatic)
                    unsupported(("cannot call non-const method `" + method + "` through `deref()` — a "
                                 "read-only place. Implement `DerefMut<T>` on `" + clsName + "` (the writable "
                                 "half, `derefMut()`), or hold the handle mutably").c_str(), srcLine);
                std::string derefed = dref->cName + "((" + clsName + "*)" + recvPtr + ")";
                return emitDispatch(tgt, derefed, method, args, srcLine, site, nullptr);
            }
        }
        if (rejectUnprovenBound(clsName, method, srcLine)) return "0";   // the BOUND, not the type
        // `view()` on an intrinsic collection is the one method whose absence has a fixable CAUSE rather
        // than being a typo: it is registered only when the program contains `std::collections::View`,
        // and unlike `FixedArray` — which drags View in through its own module — a prelude builtin drags
        // in nothing. Without this the user is told the method does not exist, which is true and useless.
        if ((method == "view" || method == "viewMut") && viewTemplateKey().empty()
            && _classes.count(clsName) && _classes[clsName].isIntrinsicColl) {
            unsupported(("`" + clsName + "` can hand out a view, but this program has no `View<T>` to hand "
                         "out — add `import { std::collections::View };`").c_str(), srcLine);
            return "0";
        }
        // A FIELD of signature type, invoked: `reg.handler(x: 1)`. The other half of the stored-`fnptr`
        // hole — a handler could be installed in a field but never called through one, so a callback
        // REGISTRY (install now, invoke later) had no spelling at all. It reads as a method call and is
        // one syntactically, which is why it landed here and reported the field as a missing method.
        // Checked last, after every real method has failed to resolve, so a field can never shadow one.
        if (_classes.count(clsName)) {
            ClassInfo* fo = findFieldOwner(&_classes[clsName], method);
            if (fo)
                for (auto& f : fo->fields)
                    if (f.name == method && f.type) {
                        const std::string fc = fieldCType(clsName, f);
                        if (isSigType(fc)) {
                            canAccess(fo, f.visibility, method, srcLine);
                            const SigInfo& sig = _sigs.at(fc);
                            if (!sig.noHeap) rejectNoHeapIndirect("through a `fnptr`", srcLine);   // see the local arm
                            return emitReorderedCall(sig.noHeap ? ("KAMA_NOHEAP_SLOT((" + recvPtr + ")->" + method + ")")
                                                                : ("(" + recvPtr + ")->" + method), "", sig.params,
                                                     args, srcLine);
                        }
                        // ...and its bound twin: a `BindableFunctionPtr` FIELD, invoked. The local arm
                        // (`emitBindableInvoke` on a bare local) was the only spelling, so a handler type
                        // holding one — the shape a UI event table is — could store it and never fire it.
                        if (isBindableClass(fc)) {
                            canAccess(fo, f.visibility, method, srcLine);
                            return emitBindableInvoke("(" + recvPtr + ")->" + method, fc, args, srcLine);
                        }
                    }
        }
        unsupported(("`" + clsName + "` has no method `" + method + "`" + whenGateReason(clsName, method)).c_str(),
                    srcLine);
        return "0";
    }
    if (!mi->isIntrinsic) canAccess(owner, mi->visibility, method, srcLine);
    // M6 B3a: the spelling at `site` is a REFERENCE to the method just resolved — the single most common
    // one in the language, and until B3 it reached the index from nowhere, so F2 on a method rewrote the
    // declaration and left every call spelling the old name. One record here covers the virtual, the
    // devirtualized and the direct paths; the auto-deref fallback above passes `site` down and records at
    // the level that actually resolves. Recorded by NODE (mi->node is null for an intrinsic, which drops
    // it) so a generic instance's call collapses onto the template's one declaration.
    recordNodeRef(site, mi->node);
    // ...and the intrinsic half of that same sentence. `string`'s methods are synthesized in
    // registerCollection and have no declaration node, so the record above drops them and `s.length()`
    // indexed as nothing whatever: no hover, no jump, on the most-called methods in the language. They
    // have no AST to point at, but they do have a written place — the same documentation file the
    // receiver type itself resolves to.
    if (mi->isIntrinsic && !mi->node && owner && owner->isIntrinsicColl && owner->collKind == CollKind::String)
        recordBuiltinRef("string." + method, site);

    // `Simd`'s lane-permuting methods cannot go through the ordinary call path, and the reason is the
    // hardware rather than the compiler: `__builtin_shufflevector` requires its lane indices to be
    // INTEGER CONSTANT EXPRESSIONS, because the CPU encodes the permutation in the instruction itself
    // (a constant `wzyx` is `rev64.4s; ext.16b`; the same permutation with a runtime pattern spills the
    // vector to the stack and rebuilds it with four scalar loads). So the pattern is folded HERE, at the
    // call, into literal arguments — the emitter reads the constant the way `[v; N]`'s count and a
    // comptime generic argument are already read, and refuses anything it cannot fold.
    // The no-heap gate for an INTRINSIC method. An intrinsic has no AST body, so it contributes no call
    // edge and no allocation fact — it is invisible to the transitivity walk, and `string` is the one
    // intrinsic family whose methods MINT heap: `concat`, `substring`, `trim*`, `replace`, `toLower`
    // /`toUpper`, `truncate` and `split` each return a NEW owned value and leave the receiver alone
    // (`string` is immutable — the same sentence that motivates them explains why they allocate). So
    // `a + b` inside a `@noheap` region was accepted while `"${a}${b}"` was rejected, which is the same
    // allocation twice with two different answers.
    //
    // Derived from the RETURN TYPE rather than from a list of method names, so a string method added
    // later is covered the day it is added. Scoped to `String` deliberately: the smart-pointer intrinsics
    // also return an owning value (`Shared.downgrade` hands back a `Weak<T>`) and allocate NOTHING — they
    // hand out a handle to memory that already exists, and a `Shared`'s own allocation happens at `new`,
    // which the gate already covers. A bare `ownsByValue(return)` rule would reject those.
    //
    // Recorded against the CALLER, which is the honest attribution: the intrinsic has no body to blame,
    // and the caller is what a `@noheap` region reaches. That also makes it transitive for free.
    if (mi->isIntrinsic && owner && owner->collKind == CollKind::String && mi->returnType
        && ownsByValue(cType(mi->returnType)))
        rejectIfNoHeap((std::string("`string.") + method + "` returns a NEW owned string").c_str(), srcLine);

    if (mi->isIntrinsic && owner && owner->isIntrinsicColl && owner->collKind == CollKind::Simd
        && (method == "shuffle" || method == "blend"))
        return emitSimdShuffle(owner->name, method, recvPtr, args, srcLine);

#if KAMA_INHERITANCE
    if (mi->isVirtual) {
        // Devirtualize when the concrete target is unique for every possible dynamic type: a
        // `final` receiver class (no subclass), a `final` method (unoverridable), or a virtual
        // method no class overrides anywhere in the program (whole-program view — no LTO needed).
        // Then fall through to the direct call below. Otherwise dispatch through the vptr.
        ClassInfo& sc = _classes[clsName];
        bool monomorphic = sc.isFinalClass || mi->isFinal
                         || !_overriddenSlots.count(std::make_pair(sc.vtableRoot, method));
        if (!monomorphic) {
            // The no-heap gate for a virtual call, and note where it sits: AFTER devirtualization. A call
            // the compiler proved has exactly one possible target is a direct call — it fell through to the
            // ordinary path below, where the edge is recorded and the callee analysed like any other. Only
            // a genuinely dynamic slot is a blind seam, so `final`, a `final fn` and a virtual method
            // nobody overrides all stay usable inside a `@noheap` region without an annotation.
            if (!mi->noHeap)
                rejectNoHeapIndirect(("`" + clsName + "." + method + "`, a virtual method not declared "
                                      "`@noheap`").c_str(), srcLine);
            // Dynamic dispatch through the vptr (at offset 0 via the vtable root).
            const std::string& root = sc.vtableRoot;
            std::string slotOwner = owner->name;
            auto rit = _rootVtables.find(root);
            if (rit != _rootVtables.end())
                for (auto& s : rit->second) if (s.name == method) { slotOwner = s.owner; break; }
            std::string self = "(" + slotOwner + "*)" + recvPtr;
            std::string vptr = "((" + root + "*)" + recvPtr + ")->__vptr";
            // A `@noheap` virtual method is proven — every override is checked against it — so the slot
            // call is marked for the call graph, exactly as a `@noheap` contract member's is.
            std::string slot = vptr + "->" + method;
            if (mi->noHeap) slot = "KAMA_NOHEAP_SLOT(" + slot + ")";
            return emitReorderedCall(slot, self, mi->params, args, srcLine);
        }
    }
#endif
    // Static call; upcast self to the declaring class (offset-0 valid). Also the devirtualized path.
    std::string self = owner->isScalarEnum() ? "*(" + recvPtr + ")"       // a payload-less enum is passed by value
                                             : "(" + owner->name + "*)" + recvPtr;
    // A NESTED PARTICIPANT — a container of containers of edges, a node's participant field reached from a
    // twin — needs the same graph its owner is walking. (The EDGE case is answered at the top of this
    // function, before auto-deref can reach the pointee.)
    if (!_serGraphArg.empty() && method == "serialize") {
        auto pc = _classes.find(clsName);
        if (pc != _classes.end() && graphTwinNeeded(pc->second, /*write=*/true))
            return emitReorderedCall(clsName + "__serializeInto", "(" + clsName + "*)" + recvPtr,
                                     mi->params, args, srcLine, _serGraphArg);
    }
    // A marked DELEGATE — a helper the element write is handed to, so the table has to go with it. This is
    // the call that used to end the graph: `SortedMap.serialize` hands its writer to `BTreeNode`, whose
    // body holds the real `this.vals[i].serialize(w: w)`, and with no table there every leaf was written
    // INLINE and duplicated. Rule 1 is `graphDelegateNeeded` (marked + takes the sink); rule 2 is
    // `graphSinkIsOurs` (it is OUR sink); rule 3 — an unmarked callee handed our sink — is refused below.
    const bool inWriteCopy = !_serGraphArg.empty(), inReadCopy = !_deGraphArg.empty();
    if (inWriteCopy || inReadCopy) {
        const bool write = inWriteCopy;
        if (graphDelegateNeeded(*owner, *mi, write) && graphSinkIsOurs(*mi, args, write))
            return emitReorderedCall(graphDelegateTwinName(*mi), self, mi->params, args, srcLine,
                                     write ? _serGraphArg : _deGraphArg);
        // Rule 3: handed our own sink, but nothing carries the table onward. Left alone this is the silent
        // wrong write — inline, duplicated pointees, and a read that fails with "unresolved reference"
        // somewhere else entirely.
        if (graphMarkRole(*mi) == GraphMark::None && graphSinkIsOurs(*mi, args, write)
            && owner->reachesPointer && !owner->isIntrinsicColl && !isSmartPtrClass(owner->name)
            && mi->node != nullptr && !mi->isAbstract)
            unsupported(("`" + demangleForDisplay(clsName) + "." + method + "` is handed this "
                         + std::string(write ? "serializer" : "deserializer") + " from inside a graph "
                         "write, but is not marked `@serializedGraphEdges` — the elements it "
                         + std::string(write ? "writes" : "reads") + " would be "
                         + std::string(write ? "duplicated inline instead of interned as ids"
                                             : "read as values instead of as ids")
                         + ", and the "
                         + std::string(write ? "read would then fail with \"unresolved reference\""
                                             : "graph would come back unshared")
                         + ". Mark it `@serializedGraphEdges`, or "
                         + std::string(write ? "write" : "read")
                         + " the elements in the container's own body the way `Map` does").c_str(), srcLine);
    }
    return emitReorderedCall(mi->cName, self, mi->params, args, srcLine);
}

// obj.method(args) — the member-access callee form (incl. this.method()).
// A "stable" string reference: re-evaluating it is side-effect-free and yields the same bytes+length —
// a variable, a literal, `this`, or a field access rooted in one of those. Gates `.chars()`/`.split()`,
// which read their receiver (and separator) twice and BORROW the bytes for the whole loop; a call/operator
// rvalue (owned or side-effecting) would desync the two reads (OOB) and leak/dangle, so it must be bound
// to a local first.
static bool isStableStringRef(ASTNode* n)
{
    if (!n) return false;
    if (dynamic_cast<IdentifierNode*>(n) || dynamic_cast<StringNode*>(n) || dynamic_cast<ThisAccessNode*>(n))
        return true;
    if (auto* ma = dynamic_cast<MemberAccessNode*>(n)) return isStableStringRef(ma->expression.get());
    return false;
}

// Does an invocation used AS A RECEIVER return a place (a `fn ref T` borrow) rather than a fresh owned
// value? A place receiver must NOT be materialized + dropped (it borrows — dropping a copy would
// double-free); a value receiver (ctor / value-returning method or free fn) must be, else its heap leaks.
// `isPlaceReturn` (on MethodInfo + FuncSig, set for `fn ref T`) is the fresh-value-vs-borrow discriminator.
bool CEmitter::invocationReturnsPlace(InvocationNode* iv)
{
    if (!iv) return false;
    if (iv->identifier && iv->identifier->value) {           // bare call: a free fn (or an inline ctor)
        auto fit = _funcs.find(resolveFunc(*iv->identifier->value, iv->identifier->qualifier));
        return fit != _funcs.end() && fit->second.isPlaceReturn;   // a ctor isn't in _funcs -> false (a value)
    }
    if (auto* ma = dynamic_cast<MemberAccessNode*>(iv->expression.get())) {   // method call `recv.m()`
        std::string rcls = exprClass(ma->expression);
        if (isSmartPtrClass(rcls)) rcls = _classes[rcls].collElemClass;       // a method lives on the pointee
        std::string m = (ma->identifier && ma->identifier->value) ? *ma->identifier->value : "";
        if (rcls.empty() || m.empty()) return false;
        if (isInterface(rcls)) {                    // a contract value: the slot itself is the place-returner
            for (auto& im : _interfaces[rcls].methods)
                if (im.name == m) return im.isPlaceReturn;
            return false;
        }
        if (!_classes.count(rcls)) return false;
        MethodInfo* mi = placeMethodOf(rcls, m);   // follows `Deref<T>` — `this.root.getRef(k)` is a place too
        return mi && mi->isPlaceReturn;
    }
    return false;
}

// `new Type.name(args)` — resolve+validate the named `ctor` and return the factory CALL expression
// (`Type__name(reordered args)`, no `self` lead arg), or "" after emitting a diagnostic. A named `ctor` is
// a FACTORY returning `Type` by value (unlike the legacy in-place `Type__ctor(ptr, args)`), so the caller
// MOVES the result into the freshly-`malloc`'d heap slot. Shared by the local-decl path (emitNewFactoryMove)
// and the hoist path (tryHoistInlineValue). M4a: infallible only — a fallible (`Result`) ctor is rejected
// here (M4b threads `Result<Owned<T>,E>` through the box path).
// `new Geo::Circle(r: 4)` — a VARIANT built on the heap. `new` is kama's heap operator and a variant is how
// an enum is constructed, so this is the one spelling for `Shared<Geo>`/`Owned<Geo>` over an enum, as
// `new Pt.make(…)` is over a type. It had no spelling at all: `new` only ever took a constructor, an enum
// has none, and the bare `Shared<Geo> g = Geo::Circle(r: 4)` reached clang (KR-15 #5).
// The enum a `new` builds, as a C name: `oc` names a variant of a concrete enum, or of the generic enum
// template the handle's element `elem` instantiates. "" when it names no variant.
std::string CEmitter::newVariantEnum(ObjectCreationNode* oc, const std::string& elem)
{
    if (!oc || oc->ctorName || !oc->type || !oc->type->value || !oc->type->qualifier || oc->type->qualifier->empty())
        return "";
    auto q = std::make_shared<StringList>();
    for (size_t i = 0; i + 1 < oc->type->qualifier->size(); ++i) q->push_back((*oc->type->qualifier)[i]);
    std::string en = resolveUserName(*oc->type->qualifier->back(), q);
    if (EnumInfo* ei = _enums.count(en) ? &_enums[en] : nullptr) {       // a payload-less enum's member
        for (auto& mb : ei->members) if (mb.name == *oc->type->value) return en;
        return "";
    }
    if (!_classes.count(en) || !_classes[en].isVariant) {
        auto of = _genericTypeInstOf.find(elem);
        if (!_genericTypes.count(en) || of == _genericTypeInstOf.end() || of->second != en) return "";
        en = elem;
    }
    for (auto& v : _classes[en].variants) if (v.name == *oc->type->value) return en;
    return "";
}

// ...and its value, which the box moves into the heap slot exactly as a factory result is.
std::string CEmitter::newVariantValue(const std::string& enumC, ObjectCreationNode* oc)
{
    ScopedStr _vt(_variantTargetType, enumC);
    if (!oc->args || oc->args->empty()) return emitExpression(oc->type);   // `new Geo::Point()`
    if (!_synthCtx) _synthCtx = std::make_shared<CodeGenContext>(std::make_shared<std::string>("<synth>"));
    auto iv = std::make_shared<InvocationNode>(*_synthCtx, SharedExpression(), oc->args);
    iv->identifier = oc->type;
    iv->line = oc->line;
    return emitExpression(iv);
}

std::string CEmitter::newFactoryCall(const std::string& cls, ObjectCreationNode* oc, int lineNo)
{
    if (!oc->ctorName && ((_classes.count(cls) && _classes[cls].isVariant) || isEnum(cls))) return newVariantValue(cls, oc);
    const std::string cn = (oc->ctorName && oc->ctorName->value) ? *oc->ctorName->value : "";
    // Diagnostics use the SOURCE spelling the user wrote (`Box`), not the mangled `_classes` key.
    std::string disp = (oc->type && oc->type->value) ? *oc->type->value : cls;
    ClassInfo* owner = nullptr;
    MethodInfo* mi = isClass(cls) ? findMethod(&_classes[cls], cn, &owner) : nullptr;
    if (!mi || !mi->isCtor) {
        unsupported(("`new " + disp + "." + cn + "(...)` — `" + cn + "` is not a constructor of `"
                     + disp + "`").c_str(), lineNo);
        return "";
    }
    recordNodeRef(oc->ctorName.get(), mi->node);   // M6 B3a: `new Type.name(...)` references the ctor
    if (mi->returnType && mi->returnType->value && *mi->returnType->value == "Result") {
        // Reached only from an INFALLIBLE box path (a plain `new`, or a `try new` — which reports a failed
        // ALLOCATION, not a failed constructor) — so a fallible ctor here means the declared result type is
        // wrong. A fallible `new` is routed to `emitFallibleNewBox` upstream, for every destination.
        unsupported(("fallible `new " + disp + "." + cn + "(...)` returns `Result` — declare the result "
                     "`Result<Owned<" + disp + ">, E>` (a fallible ctor yields `Err` or an owned value)").c_str(), lineNo);
        return "";
    }
    canAccess(owner, mi->visibility, cn, lineNo);
    return emitReorderedCall(mi->cName, "", mi->params, oc->args, lineNo);
}

// The local-decl form of a named-ctor `new`: emit `*(slotPtr) = Type__name(args);` into `_out`. Written as
// a RAW C assignment (NOT via emitAssignment): the slot is fresh malloc (garbage), so no drop-of-old is
// inserted — that would free a wild pointer (the M3-bonus class of bug). The in-place `__ctor` path already
// writes through the pointer with no drop; we mirror that discipline.
bool CEmitter::newBuildsValue(const std::string& cls, ObjectCreationNode* oc)
{
    if (oc->ctorName || isEnum(cls)) return true;
    auto it = _classes.find(cls);
    return it != _classes.end() && it->second.isVariant;
}

void CEmitter::emitNewFactoryMove(const std::string& cls, const std::string& slotPtr,
                                  ObjectCreationNode* oc, int lineNo, int depth)
{
    line(lineNo);
    bool ph = _hoistOK; _hoistOK = true;               // hoist arg hand-offs, like the in-place ctor path
    std::string cc = newFactoryCall(cls, oc, lineNo);
    _hoistOK = ph; flushHoisted(depth);
    if (cc.empty()) return;                            // rejected (unknown/fallible ctor) — diagnostic emitted
    indent(depth); *_out << "*(" << slotPtr << ") = " << cc << ";\n";
}

// Does `new Type.name(...)` name a FALLIBLE ctor (one returning `Result<T,E>`)? Drives M4b's fallible-`new`
// routing (the box path threads `Result<Owned<T>,E>`) apart from the infallible factory-move.
bool CEmitter::ctorIsFallible(ObjectCreationNode* oc)
{
    if (!oc || !oc->ctorName || !oc->ctorName->value) return false;
    std::string cls = cType(oc->type);
    if (!isClass(cls)) return false;
    ClassInfo* owner = nullptr;
    MethodInfo* mi = findMethod(&_classes[cls], *oc->ctorName->value, &owner);
    return mi && mi->isCtor && mi->returnType && mi->returnType->value && *mi->returnType->value == "Result";
}

// M4b — `new Type.name(args)` over a FALLIBLE ctor (returns `Result<T,E>`) builds `Result<Owned<T>,E>`: call
// the factory into a temp, propagate `Err` with NO allocation (leak-free by construction), else box the `Ok`
// payload into a fresh owning handle (`adopt`) and wrap it in `Ok`. Returns a C statement sequence that
// assigns the (already-declared) `lval`, or "" after emitting a diagnostic. Serves BOTH destinations: the
// type-erased interface-element handle (`Owned<Contract>`, `isSmartPtrClass`) and the concrete
// `Owned`/`Shared` (the `std::memory` library `HeapOwner`), each with the placement `new(allocator: …)`
// form. `emitTryNewBox` is its non-panicking twin and mirrors both branches.
std::string CEmitter::emitFallibleNewBox(const std::string& target, const std::string& lval,
                                         ObjectCreationNode* oc, int srcLine)
{
    const std::string cls = cType(oc->type);
    const std::string cn  = (oc->ctorName && oc->ctorName->value) ? *oc->ctorName->value : "";
    std::string disp = (oc->type && oc->type->value) ? *oc->type->value : cls;
    ClassInfo* owner = nullptr;
    MethodInfo* mi = isClass(cls) ? findMethod(&_classes[cls], cn, &owner) : nullptr;
    if (!mi || !mi->isCtor) {
        unsupported(("`new " + disp + "." + cn + "(...)` — `" + cn + "` is not a constructor of `"
                     + disp + "`").c_str(), srcLine);
        return "";
    }
    canAccess(owner, mi->visibility, cn, srcLine);
    recordNodeRef(oc->ctorName.get(), mi->node);   // M6 B3a: fallible `new Type.name(...)`, same reference

    // The declared result must be `Result<Owned<T>|Shared<T>, E>`. Pull the inner smart-ptr `S` and the
    // error field straight off the monomorphized `Result` ClassInfo — its payload types are substituted-concrete.
    ClassInfo* rc = _classes.count(target) ? &_classes[target] : nullptr;
    VariantCase* okV = nullptr; VariantCase* errV = nullptr;
    if (rc && rc->isVariant)
        for (auto& v : rc->variants) { if (v.name == "Ok") okV = &v; else if (v.name == "Err") errV = &v; }
    if (!okV || !errV || okV->payload.empty() || errV->payload.empty()) {
        unsupported(("fallible `new " + disp + "." + cn + "(...)` needs a `Result<Owned<"
                     + disp + ">, E>` — a fallible ctor yields `Err` or an owned value").c_str(), srcLine);
        return "";
    }
    // Resolve the inner smart-ptr `S` under the `Result` INSTANCE's substitution (not the ambient context) —
    // else a defaulted generic param (`Owned<T>`'s allocator) resolves wrong and `S` misses the registered
    // `…Owned…GlobalAllocator` name. Mirrors emitVariantStruct's own field emission.
    std::string S = fieldCType(target, okV->payload[0]);   // `std__memory__Owned…`/`…Shared…`
    // A concrete `Owned`/`Shared` from `std::memory` is a LIBRARY `HeapOwner` (boxed via `adopt`, NOT the
    // intrinsic `.ptr`/`.ctrl` handle). The intrinsic smart-ptr representation (`isSmartPtrClass`) is the
    // type-erased INTERFACE-element fat handle — its fallible `new` is a follow-on milestone.
    // ---- (1) INTERFACE-ELEMENT: box the concrete `cls` behind the type-erased fat handle `S`. ----
    // Mirror the infallible interface boxing (emitLocalVariableDeclaration ~1321-1402), built as string
    // fragments inside the Ok branch: malloc/allocate `.obj`, MOVE the Ok payload in, set `.vtbl`, and
    // (Shared) the ctrl block. Allocate ONLY on Ok — the Err branch re-wraps with no allocation.
    if (isSmartPtrClass(S)) {
        const std::string Tif = _classes[S].collElemClass;   // the interface the fat handle erases
        if (!isInterface(Tif)) {
            unsupported(("fallible `new` into `" + S + "` — not an interface-element handle").c_str(), srcLine);
            return "";
        }
        bool implementsT = false;
        auto cit = _classes.find(cls);
        if (cit != _classes.end())
            for (auto& i : cit->second.interfaces) if (i == Tif) { implementsT = true; break; }
        if (!implementsT) {
            unsupported(("`new " + disp + "." + cn + "(...)` builds `" + cls + "`, which does not implement `"
                         + Tif + "`").c_str(), srcLine);
            return "";
        }
        if (isClass(cls) && _classes[cls].isAbstractClass) {
            unsupported(("cannot instantiate abstract class '" + cls + "'").c_str(), srcLine);
            return "";
        }
        // Placement `new(allocator: a)` (M11d): draw the pointee AND (Shared) the ctrl from `a`, storing
        // `a`+`objsize` in the fat handle so its dtor frees through it. Default GlobalAllocator keeps the
        // libc malloc + `kama_ctrl_new()` path. `ifaceNewAllocator` validates the box/handle allocator match.
        bool useAlloc = ifaceNewAllocator(S, oc, srcLine);
        std::string RT  = cType(mi->returnType);
        std::string cc  = emitReorderedCall(mi->cName, "", mi->params, oc->args, srcLine);
        std::string tmp = "__fnew"   + std::to_string(_tempCounter++);
        std::string box = "__fbox"   + std::to_string(_tempCounter++);
        std::string ap  = "__falloc" + std::to_string(_tempCounter++);
        const std::string okName  = okV->payload[0].name;
        const std::string errName = errV->payload[0].name;
        std::string s;
        s  = RT + " " + tmp + " = " + cc + "; ";
        s += "if (" + tmp + ".tag == " + RT + "_Err) { ";
        s +=   lval + " = (" + target + "){ .tag = " + target + "_Err, .u.Err = { ." + errName + " = "
                 + tmp + ".u.Err." + errName + " } }; ";
        s += "} else { ";
        s +=   S + " " + box + "; ";
        if (useAlloc) {
            auto pa = placementAllocator(oc, srcLine, /*emit=*/true);
            s += pa.second + " " + ap + " = " + pa.first + "; ";
            s += box + ".obj = (void*)unwrapPtr(" + pa.second + "__allocate(&" + ap + ", " + layoutOf(cls) + ")); ";
        } else {
            s += box + ".obj = kama_alloc(" + layoutOf(cls) + "); ";
        }
        s += "if (!" + box + ".obj) kama_panic(kama_string_lit(\"out of memory\", 13)); ";
        s += "*(" + cls + "*)" + box + ".obj = " + tmp + ".u.Ok." + okName + "; ";
        s += box + ".vtbl = &" + cls + "__as_" + Tif + "; ";
        if (useAlloc) {
            s += box + ".alloc = " + ap + "; ";
        }
        if (smartKind(S) == CollKind::Shared) {
            if (useAlloc)
                s += box + ".ctrl = (kama_ctrl*)unwrapPtr(" + _collections[S].allocType + "__allocate(&" + ap
                   + ", " + layoutOf("kama_ctrl") + ")); " + box + ".ctrl->strong = 1; " + box + ".ctrl->weak = 0; ";
            else
                s += box + ".ctrl = kama_ctrl_new(); ";
        }
        s +=   lval + " = (" + target + "){ .tag = " + target + "_Ok, .u.Ok = { ." + okName + " = "
                 + box + " } }; ";
        s += "}";
        return s;
    }
    std::string T = heapOwnerTarget(S);               // the boxed element (an owning `HeapOwner` element)
    if (T.empty()) {
        unsupported(("fallible `new " + disp + "." + cn + "(...)` needs a `Result<Owned<"
                     + disp + ">, E>` (an owning handle over `" + disp + "`)").c_str(), srcLine);
        return "";
    }
    if (T != cls) {
        unsupported(("`" + S + "` owns `" + T + "`, but `new " + disp + "` builds `" + cls + "`").c_str(), srcLine);
        return "";
    }
    // ---- (2) concrete library `HeapOwner`. Placement `new(allocator: a)` / stateful-allocator box: draw
    // the block from `a` and adopt via `adoptIn` (mirror the infallible path ~1418-1478). A bare `new` keeps
    // libc malloc + `adopt`. A bare `new` into a stateful-A box would leak on a no-op deallocate → require
    // the placement form.
    auto pa = placementAllocator(oc, srcLine, /*emit=*/true);
    bool placed = !pa.second.empty();
    if (!placed) {
        const std::string why = bareNewRefusal(boxAllocatorArg(S), "new", "T");
        if (!why.empty()) { unsupported(why.c_str(), srcLine); return ""; }
    } else {
        std::string boxA = boxAllocatorArg(S);   // no inference axis — the declared box-A must match the handle
        if (!boxA.empty() && boxA != pa.second) {
            unsupported(("the box's allocator type `" + boxA + "` does not match the `new(allocator: …)` "
                         "handle `" + pa.second + "` — spell the box's allocator explicitly").c_str(), srcLine);
            return "";
        }
    }
    const char* adoptName = placed ? "adoptIn" : "adopt";
    ClassInfo* ao = nullptr;
    MethodInfo* adoptM = findMethod(&_classes[S], adoptName, &ao);
    if (placed && !adoptM) {
        unsupported(("allocator-aware `new(allocator: …)` needs an `adoptIn(raw, allocator)` on `" + S + "`").c_str(), srcLine);
        return "";
    }
    if (!adoptM) {
        unsupported(("`" + S + "` implements `HeapOwner` but has no `adopt` — cannot box a fallible `new`").c_str(), srcLine);
        return "";
    }

    std::string RT = cType(mi->returnType);           // the factory's `Result<T, E>`
    std::string cc = emitReorderedCall(mi->cName, "", mi->params, oc->args, srcLine);   // pushes arg hand-offs
    std::string tmp = "__fnew" + std::to_string(_tempCounter++);
    std::string hp  = "__fheap" + std::to_string(_tempCounter++);
    const std::string okName  = okV->payload[0].name;    // "value"
    const std::string errName = errV->payload[0].name;   // "error"

    // Allocate ONLY on the Ok path: allocate the pointee (from `a` when placement, else libc malloc), MOVE
    // the payload in, `adopt`/`adoptIn` it into the owning handle, wrap in `Ok`. The `Err` path allocates
    // nothing (leak-free by construction) and just re-wraps the error. `adopt` itself allocates the `Shared`
    // ctrl block — so, unlike the intrinsic path, no `kama_ctrl_new()` here.
    std::string ap = placed ? "__falloc" + std::to_string(_tempCounter++) : "";
    std::string s;
    s  = RT + " " + tmp + " = " + cc + "; ";
    s += "if (" + tmp + ".tag == " + RT + "_Err) { ";
    s +=   lval + " = (" + target + "){ .tag = " + target + "_Err, .u.Err = { ." + errName + " = "
             + tmp + ".u.Err." + errName + " } }; ";
    s += "} else { ";
    if (placed) {
        s += pa.second + " " + ap + " = " + pa.first + "; ";
        s += T + "* " + hp + " = (" + T + "*)unwrapPtr(" + pa.second + "__allocate(&" + ap + ", " + layoutOf(T) + ")); ";
    } else {
        s += T + "* " + hp + " = (" + T + "*)kama_alloc(" + layoutOf(T) + "); ";
    }
    s +=   "if (!" + hp + ") kama_panic(kama_string_lit(\"out of memory\", 13)); ";
    s +=   "*(" + hp + ") = " + tmp + ".u.Ok." + okName + "; ";
    std::string adoptCall = adoptM->cName + "(" + hp + (placed ? ", " + ap : "") + ")";
    s +=   lval + " = (" + target + "){ .tag = " + target + "_Ok, .u.Ok = { ." + okName + " = "
             + adoptCall + " } }; ";
    s += "}";
    return s;
}

// `try new T(args)` (M-step5): the ONE non-panic construction entry. Mirrors the infallible `new` into a
// library `Owned<T>` (~2033-2110) but yields `Optional<Owned<T>>` — `None` when an allocation fails,
// instead of `kama_panic`. Two destinations, exactly as emitFallibleNewBox has: the type-erased
// INTERFACE-element fat handle (`isSmartPtrClass`) and the concrete library `HeapOwner` (`adopt`). The
// `Some`/`None` compound literal mirrors emitWeakTryUpgrade; the malloc/ctor/adopt mirrors the library-adopt
// path in emitFallibleNewBox. `lval` (declared + RAII-tracked by the caller) is assigned on every branch.
std::string CEmitter::emitTryNewBox(const std::string& target, const std::string& lval,
                                    ObjectCreationNode* oc, int srcLine)
{
    std::string cls = cType(oc->type);
    std::string disp = (oc->type && oc->type->value) ? *oc->type->value : cls;
    // The declared result must be `Optional<Owned<T>>` — read the `Some` payload type off the monomorphized
    // Optional ClassInfo (substituted-concrete), like emitFallibleNewBox reads its `Ok`/`Err`.
    ClassInfo* rc = _classes.count(target) ? &_classes[target] : nullptr;
    VariantCase* someV = nullptr;
    if (rc && rc->isVariant)
        for (auto& v : rc->variants) if (v.name == "Some") { someV = &v; break; }
    if (!someV || someV->payload.empty()) {
        unsupported(("`try new " + disp + "(...)` needs an `Optional<Owned<" + disp
                     + ">>` — it yields the owned value or `None` on OOM").c_str(), srcLine);
        return "";
    }
    std::string S = fieldCType(target, someV->payload[0]);   // the inner Owned/Shared instance
    const std::string someName = someV->payload[0].name;              // "value"
    { std::string ve = newVariantEnum(oc, heapOwnerTarget(S)); if (!ve.empty()) cls = ve; }
    // ---- (1) INTERFACE-ELEMENT: box the concrete `cls` behind the type-erased fat handle `S`. ----
    // Mirrors emitFallibleNewBox's interface branch (malloc `.obj`, construct into it, set `.vtbl`, and —
    // Shared — the ctrl) with ONE deliberate difference, which is this verb's whole reason to exist:
    // ⚠️ every allocation here answers `None`, never `kama_panic`. That also rules out `kama_ctrl_new()`,
    // which does not check its own malloc — the ctrl is allocated inline and tested. Both blocks are taken
    // BEFORE anything is constructed, so a failure has no live object to unwind.
    if (isSmartPtrClass(S)) {
        const std::string Tif = _classes[S].collElemClass;   // the interface the fat handle erases
        if (!isInterface(Tif)) {
            unsupported(("`try new` into `" + S + "` — not an interface-element handle").c_str(), srcLine);
            return "";
        }
        if (smartKind(S) == CollKind::Weak) {
            unsupported("a `Weak` handle owns nothing, so it is not a `try new` destination — build an "
                        "`Optional<Owned<…>>`/`Optional<Shared<…>>` and take a `Weak` from that", srcLine);
            return "";
        }
        bool implementsT = false;
        auto cit = _classes.find(cls);
        if (cit != _classes.end())
            for (auto& i : cit->second.interfaces) if (i == Tif) { implementsT = true; break; }
        if (!implementsT) {
            unsupported(("`try new " + disp + "(...)` builds `" + cls + "`, which does not implement `"
                         + Tif + "`").c_str(), srcLine);
            return "";
        }
        if (isClass(cls) && _classes[cls].isAbstractClass) {
            unsupported(("cannot instantiate abstract class '" + cls + "'").c_str(), srcLine);
            return "";
        }
        // Placement `try new(allocator: a)` (M11d): draw the pointee AND (Shared) the ctrl from `a`, storing
        // `a`+`objsize` in the fat handle so its dtor frees through it. `ifaceNewAllocator` validates the
        // box/handle allocator match and rejects a bare `try new` into a stateful-A box.
        bool useAlloc = ifaceNewAllocator(S, oc, srcLine, "try new");
        std::string ctorStmt;                                // built first: it pushes the arg hand-offs
        std::string obj = "__tobj"  + std::to_string(_tempCounter++);
        std::string box = "__tbox"  + std::to_string(_tempCounter++);
        std::string ctl = "__tctrl" + std::to_string(_tempCounter++);
        std::string ap  = "__talloc" + std::to_string(_tempCounter++);
        if (newBuildsValue(cls, oc)) {
            std::string fc = newFactoryCall(cls, oc, srcLine);   // `T__make(...)`; rejects a fallible/unknown ctor
            if (fc.empty()) return "";                            // diagnostic already emitted
            ctorStmt = "*(" + cls + "*)" + obj + " = " + fc + "; ";
        }
        const bool shared = smartKind(S) == CollKind::Shared;
        const std::string none = lval + " = (" + target + "){ .tag = " + target + "_None }; ";
        // `ptrOrNull`, not `unwrapPtr`: the allocator's `Optional<UnsafePtr>` failure must arrive here as a
        // null pointer to be turned into `None`. `unwrapPtr` would panic, which is the one thing this verb
        // promises not to do — and it is what every INFALLIBLE placement site correctly calls.
        std::string s;
        if (useAlloc) {
            auto pa = placementAllocator(oc, srcLine, /*emit=*/true);
            s  = pa.second + " " + ap + " = " + pa.first + "; ";
            s += "void* " + obj + " = ptrOrNull(" + pa.second + "__allocate(&" + ap + ", " + layoutOf(cls) + ")); ";
        } else {
            s  = "void* " + obj + " = kama_alloc(" + layoutOf(cls) + "); ";
        }
        s += "if (!" + obj + ") { " + none + "} else { ";
        if (shared) {
            const std::string aTy = _collections[S].allocType;   // ctrl from the SAME allocator (validated)
            s += useAlloc
               ? "kama_ctrl* " + ctl + " = (kama_ctrl*)ptrOrNull(" + aTy + "__allocate(&" + ap + ", " + layoutOf("kama_ctrl") + ")); "
               : "kama_ctrl* " + ctl + " = (kama_ctrl*)kama_alloc(" + layoutOf("kama_ctrl") + "); ";
            // The pointee is already taken, so a failed ctrl releases it — through the SAME route it came
            // from, which for an arena is the no-op `deallocate` that keeps the region's own accounting.
            s += "if (!" + ctl + ") { ";
            s += useAlloc ? aTy + "__deallocate(&" + ap + ", " + obj + ", " + layoutOf(cls) + "); "
                          : "kama_free(" + obj + ", " + layoutOf(cls) + "); ";
            s += none + "} else { ";
            s += ctl + "->strong = 1; " + ctl + "->weak = 0; ";
        }
        s += ctorStmt;
        s += S + " " + box + "; " + box + ".obj = " + obj + "; ";
        s += box + ".vtbl = &" + cls + "__as_" + Tif + "; ";
        if (useAlloc) s += box + ".alloc = " + ap + "; ";
        if (shared) s += box + ".ctrl = " + ctl + "; ";
        s += lval + " = (" + target + "){ .tag = " + target + "_Some, .u.Some = { ." + someName + " = "
           + box + " } }; ";
        s += shared ? "} }" : "}";
        return s;
    }
    std::string T = heapOwnerTarget(S);
    if (T.empty() || T != cls) {
        unsupported(("`try new " + disp + "(...)` needs an `Optional<Owned<" + disp
                     + ">>` (an owning handle over `" + disp + "`)").c_str(), srcLine);
        return "";
    }
    if (isClass(cls) && _classes[cls].isAbstractClass) {
        unsupported(("cannot instantiate abstract class '" + cls + "'").c_str(), srcLine);
        return "";
    }
    // ---- (2) concrete library `HeapOwner`. A bare `try new` draws from libc malloc and boxes via `adopt`;
    // a placement `try new(allocator: a)` draws the block from `a` and boxes via `adoptIn`, which stores the
    // handle so the dtor releases through the SAME allocator. A bare `try new` into a stateful-A box would
    // leak on that box's no-op deallocate, so it is refused and told which form to write — the rule the
    // infallible and fallible paths already enforce, said in this verb's own spelling.
    auto pa = placementAllocator(oc, srcLine, /*emit=*/true);
    bool placed = !pa.second.empty();
    std::string boxA = boxAllocatorArg(S);
    if (!placed) {
        const std::string why = bareNewRefusal(boxA, "try new", disp);
        if (!why.empty()) { unsupported(why.c_str(), srcLine); return ""; }
    } else if (!boxA.empty() && boxA != pa.second) {   // no inference axis — the declared box-A must match
        unsupported(("the box's allocator type `" + boxA + "` does not match the `try new(allocator: …)` "
                     "handle `" + pa.second + "` — spell the box's allocator explicitly").c_str(), srcLine);
        return "";
    }
    const char* adoptName = placed ? "adoptIn" : "adopt";
    ClassInfo* ao = nullptr;
    MethodInfo* adoptM = findMethod(&_classes[S], adoptName, &ao);
    if (!adoptM) {
        unsupported((placed
            ? "allocator-aware `try new(allocator: …)` needs an `adoptIn(raw, allocator)` on `" + S + "`"
            : "`" + S + "` implements `HeapOwner` but has no `adopt` — cannot box a `try new`").c_str(), srcLine);
        return "";
    }
    std::string hp = "__theap"  + std::to_string(_tempCounter++);
    std::string ap = "__talloc" + std::to_string(_tempCounter++);
    // Construct the object at `hp`: a named ctor (`try new T.make(...)`, the M8 norm) MOVES a factory result
    // into the slot; a bare positional ctor constructs in place; a ctor-less struct leaves malloc's default.
    std::string ctorStmt;
    if (newBuildsValue(cls, oc)) {
        std::string fc = newFactoryCall(cls, oc, srcLine);   // `T__make(...)`; rejects a fallible/unknown ctor
        if (fc.empty()) return "";                            // diagnostic already emitted
        ctorStmt = "*(" + hp + ") = " + fc + "; ";
    }
    std::string s;
    if (placed) {   // `ptrOrNull`, not `unwrapPtr` — see the interface branch above
        s  = pa.second + " " + ap + " = " + pa.first + "; ";
        s += cls + "* " + hp + " = (" + cls + "*)ptrOrNull(" + pa.second + "__allocate(&" + ap
           + ", " + layoutOf(cls) + ")); ";
    } else {
        s  = cls + "* " + hp + " = (" + cls + "*)kama_alloc(" + layoutOf(cls) + "); ";
    }
    s += "if (!" + hp + ") { " + lval + " = (" + target + "){ .tag = " + target + "_None }; } else { ";
    s += ctorStmt;
    s +=   lval + " = (" + target + "){ .tag = " + target + "_Some, .u.Some = { ." + someName + " = "
             + adoptM->cName + "(" + hp + (placed ? ", " + ap : "") + ") } }; ";
    s += "}";
    return s;
}

// `Optional<T> r = try cast<T>(x);` — the FALLIBLE conversion. Same rule as `try new` above and for the
// same reason: the `Some` payload type is read off the DECLARED destination, so the destination is what
// makes the expression well-typed. `lval` is declared + RAII-tracked by the caller and assigned on both
// branches.
//
// A statement, not an expression, because the operand must be evaluated ONCE and C11 has no statement
// expression: the value goes into a temp, the range test reads the temp, and both arms build their
// compound literal from it. `KAMA_NARROW`'s `_Generic` cannot serve here — it TRAPS, and this is the verb
// that must not.
std::string CEmitter::emitTryCast(const std::string& target, const std::string& lval,
                                  CastNode* cst, int srcLine)
{
    const std::string dst = cType(cst->type);
    const std::string disp = (cst->type && cst->type->value) ? *cst->type->value : dst;
    // A plain enum is the SECOND thing this verb converts into, and the only door from an integer into
    // one — `cast<Color>(…)` is refused (see the CastNode path), so a `Color` that names no variant is
    // unrepresentable in safe kama. It cannot share the numeric path: an enum's valid values are a SET of
    // named constants, not a range, so the test is membership. `None` is where a byte off a wire gets
    // handled, which keeps `match` the one construct that reads an enum.
    const bool enumDst  = isEnum(dst);
    std::string lo, hi;
    if (!enumDst && !cNumRangeText(dst, lo, hi)) {
        unsupported(("`try cast<" + disp + ">(…)` — only a NUMERIC or `enum` conversion can fail, and `"
                     + disp + "` is neither. Use `cast<" + disp + ">(…)`").c_str(), srcLine);
        return "";
    }
    // Read `Some`'s payload off the monomorphized Optional, exactly as emitTryNewBox does.
    ClassInfo* rc = _classes.count(target) ? &_classes[target] : nullptr;
    VariantCase* someV = nullptr;
    if (rc && rc->isVariant)
        for (auto& v : rc->variants) if (v.name == "Some") { someV = &v; break; }
    if (!someV || someV->payload.empty()) {
        unsupported(("`try cast<" + disp + ">(…)` must initialize a declared `Optional<" + disp
                     + ">` — it yields the converted value or `None` where a plain `cast` would "
                       "trap").c_str(), srcLine);
        return "";
    }
    const std::string S = fieldCType(target, someV->payload[0]);
    if (S != dst) {
        unsupported(("`try cast<" + disp + ">(…)` yields `Optional<" + disp + ">`, but this destination "
                     "holds `" + S + "`").c_str(), srcLine);
        return "";
    }
    const std::string someName = someV->payload[0].name;              // "value"
    // The temp is the WIDEST integer of the operand's signedness, so the test sees the true value: a
    // `uint64` above LLONG_MAX must not arrive as a negative, and a negative must not arrive as huge.
    const std::string src = typeOfExpr(cst->unaryExpression);
    // A FLOAT source is refused rather than half-answered. Reaching the range test means converting to an
    // integer first, and an out-of-range float->int conversion TRAPS on the way (float-cast-overflow) — so
    // the `None` this verb promises would never be produced. Testing in `double` instead trades that for a
    // rounding error at a 64-bit boundary (`INT64_MAX` is not representable), which is the same bug wearing
    // a different hat. Clamp in float, then convert.
    if (!src.empty() && cNumFloat(src)) {
        unsupported(("`try cast<" + disp + ">(…)` has no float form — an out-of-range float conversion "
                     "traps before it could answer `None`. Compare the value first, then "
                     "`cast<" + disp + ">(…)`").c_str(), srcLine);
        return "";
    }
    const bool unsignedSrc = !src.empty() && !cNumSigned(src) && !cNumFloat(src);
    const std::string tt = unsignedSrc ? "unsigned long long" : "long long";
    const std::string t = "__trycast" + std::to_string(_tempCounter++);
    std::string test;
    if (enumDst) {
        // Implicit members run 0..N-1, so the common enum tests as a range and reads that way in
        // `--keep-c` output. One explicit `= <expr>` anywhere breaks the run (`{ Ok, Warn = 5, Bad }` is
        // 0,5,6), and then the only honest test is membership, written against the emitted constants so
        // it stays correct whatever the author wrote. clang folds either shape back into a jump table.
        const EnumInfo& ei = _enums[dst];
        std::vector<std::string> names;
        for (auto& m : ei.members) names.push_back(m.name);
        bool contiguous = !names.empty() && !ei.isExtern;   // an extern enum's values are C's: test membership
        for (auto& m : ei.members) if (m.value) { contiguous = false; break; }
        if (contiguous) {
            const std::string top = std::to_string((long long)names.size() - 1);
            test = unsignedSrc ? (t + " > " + top + "ULL")
                               : (t + " < 0 || " + t + " > " + top + "LL");
        } else {
            for (auto& nmm : names) {
                if (!test.empty()) test += " && ";
                test += t + " != (" + tt + ")" + dst + "_" + nmm;
            }
            if (test.empty()) test = "1";        // a memberless enum admits nothing
        }
    } else {
        test = unsignedSrc ? (t + " > (unsigned long long)(" + hi + ")")
                           : (t + " < (long long)(" + lo + ") || (" + t + " >= 0 && "
                              "(unsigned long long)" + t + " > (unsigned long long)(" + hi + "))");
    }
    std::string s;
    s  = tt + " " + t + " = (" + tt + ")(" + emitExpression(cst->unaryExpression) + "); ";
    s += "if (" + test + ") { " + lval + " = (" + target + "){ .tag = " + target + "_None }; } else { ";
    const std::string val = "(" + dst + ")" + t;
    s +=   lval + " = (" + target + "){ .tag = " + target + "_Some, .u.Some = { ." + someName + " = "
             + val + " } }; }";
    return s;
}

// Model C (P2): box an enum VALUE into an `Owned<C>`/`Shared<C>` fat handle (C a poly-dispatch contract).
// Heap-copies the enum in and attaches the `<Enum>__as_<C>` vtbl — mirrors the infallible interface boxing
// (new-into-Owned, ~1350-1377) but the payload is an existing value, not a ctor call. The default
// GlobalAllocator handle is the plain `{obj,vtbl}` (KAMA_OWNED_IFACE_TYPE); a Shared handle also gets a
// fresh ctrl. Pushed as ONE hoisted statement (the caller must have a statement slot); returns the temp.
// `Owned<C>`/`Shared<C>` over a PRIMITIVE — the owning counterpart of the borrow widening. Mirrors
// emitEnumBoxIntoContract exactly (heap-copy the value in, attach the vtbl, a Shared also gets a ctrl);
// the one difference is the vtbl symbol, which is keyed by the CONFORMANCE key (`int32`) and not the C
// type, so `char` and `uint32` do not share one. A primitive owns nothing, so the box's `__dtor` is null
// and dropping the handle just frees the box; a `string` (key `kama_string`) has its own `__dtor` there.
std::string CEmitter::emitPrimBoxIntoContract(const std::string& ownedCType, const std::string& primKey_,
                                              const std::string& valExpr, int srcLine)
{
    rejectIfNoHeap("boxing a primitive into an owning contract handle", srcLine);
    const std::string& contract = _classes[ownedCType].collElemClass;
    ClassInfo* pci = implTargetInfo(primKey_);
    std::string t = "__kama_pbox" + std::to_string(_tempCounter++);
    std::string s = ownedCType + " " + t + " = {0}; ";
    s += t + ".obj = kama_alloc(" + layoutOf(pci->name) + "); ";
    s += "if (!" + t + ".obj) kama_panic(kama_string_lit(\"out of memory\", 13)); ";
    s += "*(" + pci->name + "*)" + t + ".obj = (" + valExpr + "); ";
    s += t + ".vtbl = &" + intrinsicContractVtbl(primKey_, contract) + ";";
    if (smartKind(ownedCType) == CollKind::Shared)
        s += " " + t + ".ctrl = kama_ctrl_new();";
    _hoisted.push_back(s);
    return t;
}

std::string CEmitter::emitEnumBoxIntoContract(const std::string& ownedCType, const std::string& enumCType,
                                              const std::string& enumValExpr, int srcLine)
{
    rejectIfNoHeap("boxing an error into an `Owned<Error>` handle", srcLine);   // no-heap gate
    const std::string& contract = _classes[ownedCType].collElemClass;
    std::string t = "__kama_ebox" + std::to_string(_tempCounter++);
    std::string s = ownedCType + " " + t + " = {0}; ";
    s += t + ".obj = kama_alloc(" + layoutOf(enumCType) + "); ";
    s += "if (!" + t + ".obj) kama_panic(kama_string_lit(\"out of memory\", 13)); ";
    s += "*(" + enumCType + "*)" + t + ".obj = (" + enumValExpr + "); ";
    s += t + ".vtbl = &" + enumCType + "__as_" + contract + ";";
    if (smartKind(ownedCType) == CollKind::Shared)
        s += " " + t + ".ctrl = kama_ctrl_new();";
    _hoisted.push_back(s);
    return t;
}

// Model C (P3): `expr.as<T>()` — runtime downcast of a boxed poly-dispatch error to a concrete enum `T`,
// yielding `Optional<T>`. A vtbl-POINTER compare (`(op).vtbl == &T__as_C`), no type-id table — and then, when
// the pointers differ, the vtbl's `__type` name. The pointer alone is not an identity: a PRELUDE
// enum (`DeError`, `SerError`) has no home module, so its vtbl is `static` in the shared header and every
// unit holds its own copy. A `DeError` boxed in `std::uuid` (or any library's `deserialize`) carried that
// unit's address, and `.as<DeError>()` in the caller's unit answered `None` for exactly the error serde
// returns (tests/as_downcast_cross_unit.d). A C name is unique program-wide, so the name compare is exact;
// the pointer compare stays first because it is the common hit and costs nothing. On a hit it
// COPIES the enum value out (`*(T*)(op).obj`) — a borrow, so `op` stays valid on the `None` branch. `T` must
// be a non-destructible enum implementing the contract (a value copy-out of an owned payload would alias).
std::string CEmitter::emitAsDowncast(AsDowncastNode* ad)
{
    checkBodyType(ad->type, "an `.as<T>()` target", ad->type ? ad->type->line : 0);
    std::string opCls = exprClass(ad->operand);
    std::string contract;
    if (isSmartPtrClass(opCls))   contract = _classes[opCls].collElemClass;   // Owned<Error>/Shared<Error>
    else if (isInterface(opCls))  contract = opCls;                            // a borrowing `Error`
    if (contract.empty() || !isPolyDispatchContract(contract)) {
        unsupported("`.as<T>()` applies to a boxed error (an `Owned<Error>`/`Shared<Error>` or a borrowed "
                    "`Error`) — its static type isn't a poly-dispatch contract", ad->type ? ad->type->line : 0);
        return "0";
    }
    std::string enumC = cType(ad->type);
    std::string tname = (ad->type && ad->type->value) ? *ad->type->value : enumC;
    if (!_classes.count(enumC) || !(_classes[enumC].isVariant || _classes[enumC].isScalarEnum())) {
        unsupported(("`.as<" + tname + ">()` — `" + tname + "` is not an enum").c_str(), ad->type ? ad->type->line : 0);
        return "0";
    }
    if (!implementsContractTemplate(&_classes[enumC], contract)) {
        unsupported(("`.as<" + tname + ">()` — `" + tname + "` does not implement `" + contract + "`").c_str(),
                    ad->type ? ad->type->line : 0);
        return "0";
    }
    if (_classes[enumC].destructible) {
        unsupported(("`.as<" + tname + ">()` recovers `" + tname + "` by copying it out of the box, but `"
                     + tname + "` owns resources (it has an owning payload) — copying would alias them; "
                     "handle it through the boxed `Error`'s methods instead").c_str(),
                    ad->type ? ad->type->line : 0);
        return "0";
    }
    std::string optC = cType(optionalTypeNode(ad->type));
    std::string op = "(" + emitExpression(ad->operand) + ")";   // side-effect-free (a binding / field access)
    return "((" + op + ".vtbl == &" + enumC + "__as_" + contract + " || kama_type_name_eq(" + op
         + ".vtbl->__type, \"" + enumC + "\")) ? "
         + "(" + optC + "){ .tag = " + optC + "_Some, .u.Some = { .value = *(" + enumC + "*)" + op + ".obj } } : "
         + "(" + optC + "){ .tag = " + optC + "_None })";
}

// `bitcast<T>(expr)` — reinterpret the bits of a numeric scalar as an equal-width numeric scalar `T`, with
// NO value conversion (`cast<T>` is the value conversion). Lowers to an ISO-C11 union type-pun (§6.5.2.3)
// inside a compound literal — an rvalue, no UB, no strict-aliasing violation. Source and target must be
// equal-width numeric scalars (`int8..int64`/`uint8..uint64`/`float32`/`float64`); a user type, `bool`/
// `char`, a width mismatch, or an operand whose scalar type can't be resolved (e.g. a bare literal or an
// unresolved generic) is a clean compile error. Endianness / composite reinterpret build on this in library.
std::string CEmitter::emitBitcast(BitcastNode* v)
{
    // (byte width, C scalar type) for a supported numeric-scalar token; width 0 => unsupported.
    // The float rows assume `float`/`double` are 4/8 bytes — if that were false this would approve a pun
    // between differently-sized union members. Not an assumption any more: kama_runtime.h asserts it (with
    // CHAR_BIT == 8, which the integer rows need) for the real target on every build.
    auto scalar = [](int tok) -> std::pair<int, std::string> {
        switch (tok) {
            case IDENTIFIER_INT8_VAL:    return {1, "int8_t"};
            case IDENTIFIER_INT16_VAL:   return {2, "int16_t"};
            case IDENTIFIER_INT32_VAL:   return {4, "int32_t"};
            case IDENTIFIER_INT64_VAL:   return {8, "int64_t"};
            case IDENTIFIER_UINT8_VAL:   return {1, "uint8_t"};
            case IDENTIFIER_UINT16_VAL:  return {2, "uint16_t"};
            case IDENTIFIER_UINT32_VAL:  return {4, "uint32_t"};
            case IDENTIFIER_UINT64_VAL:  return {8, "uint64_t"};
            case IDENTIFIER_FLOAT32_VAL: return {4, "float"};
            case IDENTIFIER_FLOAT64_VAL: return {8, "double"};
            // ⚠️ REFUSED ON PURPOSE (width 0). `bitcast` is an EQUAL-WIDTH reinterpret, and `isize`/`usize`
            // have no width until the target is known — approving one would pun between differently-sized
            // members on some target and not others. Named rather than left to `default:`, like the two
            // width helpers above. `cast`/`truncate` are the conversions that do work on them.
            case IDENTIFIER_ISIZE_VAL:
            case IDENTIFIER_USIZE_VAL:
            case IDENTIFIER_CLONG_VAL:
            case IDENTIFIER_CULONG_VAL:  return {0, ""};   // C `long` is target-width too
            default:                     return {0, ""};
        }
    };
    int toTok = (v->type && !v->type->genericArg) ? v->type->builtInVal : 0;
    auto to   = scalar(toTok);
    auto fr   = scalar(holeBuiltinType(v->unaryExpression));
    std::string tname = (v->type && v->type->value) ? *v->type->value : "T";
    if (to.first == 0) {
        unsupported(("bitcast<" + tname + ">(x) — the target `" + tname + "` must be a numeric scalar "
                     "(`int8..int64`/`uint8..uint64`/`float32`/`float64`)").c_str(), v->line);
        return "0";
    }
    if (fr.first == 0) {
        unsupported(("bitcast<" + tname + ">(x) — the operand's type isn't a resolvable numeric scalar "
                     "(need a variable/field of `int8..int64`/`uint8..uint64`/`float32`/`float64`)").c_str(), v->line);
        return "0";
    }
    if (to.first != fr.first) {
        unsupported(("bitcast<" + tname + ">(x) requires equal width — the operand is " + std::to_string(fr.first)
                     + " bytes but `" + tname + "` is " + std::to_string(to.first)
                     + " (use `cast<" + tname + ">` for a value conversion)").c_str(), v->line);
        return "0";
    }
    // ISO C11 union type-pun via a compound literal: store the source member, read the target member.
    return "(((union { " + fr.second + " __f; " + to.second + " __t; }){ .__f = ("
         + emitExpression(v->unaryExpression) + ") }).__t)";
}

std::string CEmitter::variantExprEnumCType(SharedExpression e)
{
    SharedStringList qual; std::string vname;
    if (auto* id = dynamic_cast<IdentifierNode*>(e.get())) {
        qual = id->qualifier; vname = id->value ? *id->value : "";
    } else if (auto* inv = dynamic_cast<InvocationNode*>(e.get())) {
        if (inv->identifier) { qual = inv->identifier->qualifier; vname = inv->identifier->value ? *inv->identifier->value : ""; }
    }
    if (!qual || qual->empty()) return "";
    auto tq = std::make_shared<StringList>();
    for (size_t i = 0; i + 1 < qual->size(); ++i) tq->push_back((*qual)[i]);
    if (ClassInfo* vt = resolveVariantType(resolveUserName(*qual->back(), tq)))
        for (auto& v : vt->variants) if (v.name == vname) return vt->name;
    return "";
}

// Does a member-access callee name a TYPE (so `X.name(...)` is a dot-on-type ctor call) rather than an
// instance? True only for a bare identifier that resolves to a registered class AND has no live binding —
// an in-scope local/field of the same spelling WINS (instance `.method` first). `outType` gets the
// resolved (namespace-scoped) class name. Enums live in `_enums`, not `_classes`, so this answers false
// for `Enum.Variant` — which is NOT thereby routed anywhere: it used to fall through emitMemberAccess to
// the C compiler, and is now refused by rejectDotOnTypeRead (a variant is a `::` item). This predicate
// feeds CONSTRUCTOR resolution and must not widen to enums, which have none.
bool CEmitter::isTypeReceiver(MemberAccessNode* ma, std::string& outType)
{
    if (!ma) return false;
    if (ma->classType && ma->classType->value) {   // `string.foo` — the `string`-keyword class_type form
        outType = resolveUserName(*ma->classType->value, nullptr);
        return _classes.count(outType) != 0;
    }
    if (auto* id = dynamic_cast<IdentifierNode*>(ma->expression.get())) {
        if (id->value && exprClass(ma->expression).empty()) {   // empty => not a binding/field of a class
            // Pass the receiver's qualifier so a namespace-alias-qualified type (`Gfx::Texture.make(...)`)
            // resolves through the alias — the nameless `bareCtorClass` path already threads it. #M8-PhaseE
            std::string t = resolveUserName(*id->value, id->qualifier);
            // A concrete type is in `_classes`; a GENERIC type's template is in `_genericTypeParams` (its
            // concrete instances live in `_classes` under mangled names). `Pair.make(...)` names the template,
            // so route it here — emitDotOnTypeCtorCall resolves the instance (turbofish or LHS inference). #M7-E2
            if (_classes.count(t) || _genericTypeParams.count(t)) { outType = t; return true; }
            // A generic TYPE PARAMETER bound to a ctor-requiring contract (`fn T fresh<T: Something>() {
            // return T.something(0); }`): during monomorphized emission `T` is substituted to a concrete
            // type, so resolve it through _typeSubst and route the ctor call to the concrete instance. #M8a.2
            if (!_typeSubst.empty()) {
                auto s = _typeSubst.find(*id->value);
                if (s != _typeSubst.end()) {
                    std::string ct = primKey(s->second);   // the conformance key, not the C type
                    // A PRIMITIVE is a legitimate receiver here: conformance puts real `ctor`s on
                    // int32/float64/… (`type intrinsic <int32> implements Deserializable { public ctor … }`),
                    // and they live in `_primConformances`, not `_classes`. The `::` resolver consulted both;
                    // this one only ever needed `_classes` because no other path reached a primitive ctor.
                    if (_classes.count(ct) || primConformance(ct)) { outType = ct; return true; }
                }
            }
        }
    }
    return false;
}

// Which INSTANCE does a dot-on-type receiver name? `isTypeReceiver` answers with the bare template for a
// generic (`Pair`), which is not in `_classes` — its specializations are. Resolve the instance the same two
// ways the `::` static-factory path does: an explicit turbofish (`Pair::<int32>.make()`, or the ctor's own
// `Pair.make::<int32>()`), or inference from the enclosing typed position (`Pair<int32> q = Pair.make(…)`).
// Returns `typeName` unchanged for a concrete type, and for a generic whose instance cannot be pinned down —
// callers distinguish by whether the result is in `_classes`. #M7-E2/E3
std::string CEmitter::dotOnTypeInstance(MemberAccessNode* recv, const std::string& typeName, InvocationNode* call)
{
    if (!recv || _classes.count(typeName) || !_genericTypeParams.count(typeName)) return typeName;
    IdentifierNode* rid = dynamic_cast<IdentifierNode*>(recv->expression.get());
    if (rid && rid->genericArgs)                                 // receiver turbofish `Type::<T>.make` (canonical)
        return genericTypeMangle(typeName, rid->genericArgs);
    if (recv->identifier && recv->identifier->genericArgs)        // method turbofish `Type.make::<T>` (ctor-own generics)
        return genericTypeMangle(typeName, recv->identifier->genericArgs);
    if (!_variantTargetType.empty()) {
        auto of = _genericTypeInstOf.find(_variantTargetType);
        if (of != _genericTypeInstOf.end() && of->second == typeName) return _variantTargetType;
    }
    if (SharedIdentifier inst = inferDotCtorInstance(call, _localTypeNodes)) return cType(inst);
    return typeName;
}

// `Type.name(args)` — a dot-on-type constructor call (the receiver names a TYPE, per `isTypeReceiver`).
// Distinct from `Type::staticFn()` (a static fn stays `::`) and `Enum::Variant` (stays `::`): dot-on-type
// is the constructor spelling, so it resolves ONLY to a registered `ctor`. Reaches the SAME C as the M2
// `Type::name` bridge — a `ctor` is a static factory, so the emitted call is byte-identical (mangled
// `cName`, no `self` lead arg); infallible/fallible is just its return value.
std::string CEmitter::emitDotOnTypeCtorCall(InvocationNode* call, MemberAccessNode* recv, const std::string& typeName)
{
    std::string method = (recv->identifier && recv->identifier->value) ? *recv->identifier->value : "";
    // Diagnostics use the SOURCE spelling the user wrote (`Point`), not the mangled `_classes` key.
    std::string disp = (recv->classType && recv->classType->value) ? *recv->classType->value
                     : (dynamic_cast<IdentifierNode*>(recv->expression.get()) && recv->expression
                        && static_cast<IdentifierNode*>(recv->expression.get())->value)
                        ? *static_cast<IdentifierNode*>(recv->expression.get())->value : typeName;
    // A GENERIC type: `typeName` names the bare template (not in `_classes`; its specialized instances are).
    std::string tn = dotOnTypeInstance(recv, typeName, call);
    // A user type resolves in `_classes`; a `ctor` added to a PRIMITIVE by an impl block
    // (`type intrinsic <int32> implements Deserializable`) resolves through `implTargetInfo` — the same two tables the
    // `::` resolver consults, so both spellings see the same set of constructors.
    ClassInfo* stci = _classes.count(tn) ? &_classes[tn] : implTargetInfo(tn);
    // The head is a GENERIC TEMPLATE whose instance could not be pinned down (no turbofish, nothing to
    // infer from). `Box` is a perfectly known type, so "unknown type" names the wrong problem — say which
    // instance is missing, and for a STATIC say that dot-on-type was never the spelling to begin with.
    if (!stci && _genericTypeParams.count(typeName) && _genericTypes.count(typeName)) {
        auto& gt = _genericTypes[typeName];
        auto mit = gt.methods.find(method);
        if (mit != gt.methods.end() && mit->second.isStatic && !mit->second.isCtor)
            unsupported(("`" + disp + "." + method + "` — dot-on-type calls a constructor; `" + method
                         + "` is a static function — call it with `" + disp + "::<...>::" + method
                         + "(...)`").c_str(), call->line);
        // The sibling branch above stays live under a probe: calling a static through dot-on-type is the
        // wrong spelling whatever `T` turns out to be. THIS one is pure absence — `DynamicArray<T>.new()`
        // has no instance to name until something instantiates the enclosing template.
        else if (_refusedTypeArgSites.count(reportPath(diagFile()) + ":" + std::to_string(call->line)))
            ;   // the target's type argument was refused on this line — that IS the mistake (registerGenericTypeInst)
        else if (!deferUnknownWhileProbing(DK_DotCtor))
            unsupported(("cannot tell which `" + disp + "` to construct — give the type arguments (`"
                         + disp + "::<...>." + method + "(...)`) or annotate the target so they can be "
                         "inferred").c_str(), call->line);
        return "0";
    }
    if (!stci) { unsupported(("unknown type in constructor call `" + disp + "`").c_str(), call->line); return "0"; }
    // M6 B3d: the RECEIVER of `Type.name(...)` is a reference to the type, exactly as the same spelling in
    // an annotation is — it was missing only because this path resolves without passing a site. Record
    // `typeName`, not `tn`: for a generic the latter is the mangled INSTANCE, which has no def-site, while
    // the former is the template key the declaration is registered under. Recorded here rather than in
    // isTypeReceiver, which is a predicate that also runs on non-types.
    recordRef(typeName, dynamic_cast<IdentifierNode*>(recv->expression.get()));
    // Instantiating an abstract class leaves a NULL vtable slot — EXCEPT in a base install, where the
    // value never exists as a standalone instance: it is blitted straight into `__base` and the fill's
    // vptr store stamps the most-derived vtable over it before anything can dispatch. Without this
    // carve-out an abstract base could only ever be derived from if it had a `default` ctor, which would
    // make `abstract` and "carries constructor arguments" mutually exclusive for no reason.
    if (stci->isAbstractClass && !_inBaseInstall) {
        unsupported(("cannot instantiate abstract class '" + disp + "' (it has an unimplemented method)").c_str(), call->line);
        return "0";
    }
    // OBJECT-GRAPH READ RETARGET, the mirror of the write side in emitDispatch. Inside a read twin,
    // `T.deserialize(r)` for an EDGE element takes the id and stashes it (the registered `Shared<X>`
    // forward points at the node's whole-envelope driver, which is emphatically not what an element wants),
    // and a nested PARTICIPANT reads through its own graph-carrying body.
    if (!_deGraphArg.empty() && method == "deserialize") {
        if (_graphEdgeHelperFor.count(tn)) {
            std::vector<ParamSig> ps;
            ParamSig r; r.name = "r"; r.byRef = false; r.className = "Deserializer"; ps.push_back(r);
            return emitReorderedCall(tn + "__deserializeEdge", "", ps, call->args, call->line, _deGraphArg);
        }
        auto pc = _classes.find(tn);
        if (pc != _classes.end() && graphTwinNeeded(pc->second, /*write=*/false)) {
            std::vector<ParamSig> ps;
            ParamSig r; r.name = "r"; r.byRef = false; r.className = "Deserializer"; ps.push_back(r);
            return emitReorderedCall(tn + "__deserializeFrom", "", ps, call->args, call->line, _deGraphArg);
        }
    }
    ClassInfo* owner = nullptr;
    MethodInfo* mi = findMethod(stci, method, &owner);
    // `T.default()` names the ELECTION, not a ctor name: the author marked one zero-arg ctor `default`
    // and may have called it anything (`empty`, `zero`, …). Resolve through the mark. Scanning `methods`
    // (not `ctors`) is deliberate — the `when [A: default]` gate drops a gated-away `empty()` from
    // `methods` per-monomorph but leaves it in `ctors`, so `methods` is the gate-accurate set and a
    // custom-allocator collection correctly has no default here either.
    if (!mi && method == "default") {
        for (auto& kv : stci->methods)
            if (kv.second.isDefaultCtor) { mi = &kv.second; owner = stci; break; }
        if (!mi) {
            unsupported(("`" + disp + "` has no `default` constructor — electing one is the type's own "
                         "choice; mark its canonical zero-arg ctor `default ctor name()`, or call a "
                         "named constructor").c_str(), call->line);
            return "0";
        }
    }
    if (!mi) {
        // A generic type's ctor may be DEFINED on the template but GATED AWAY for this instantiation
        // (`empty() when [A: default]` — dropped when the concrete `A` has no `default` ctor). Say exactly
        // that, naming the unmet bound, rather than the misleading "define one" (the ctor IS defined; it
        // just doesn't apply to these type arguments — use an allocator-taking ctor for a custom `A`).
        auto gt = _genericTypes.find(typeName);
        if (gt != _genericTypes.end()) {
            auto mit = gt->second.methods.find(method);
            if (mit != gt->second.methods.end() && mit->second.isCtor && !mit->second.whenParams.empty()) {
                std::string cond;
                for (size_t i = 0; i < mit->second.whenParams.size(); ++i)
                    cond += (i ? ", " : "") + mit->second.whenParams[i] + ": " + mit->second.whenBounds[i];
                unsupported(("constructor `" + disp + "." + method + "` is not available for this "
                             "instantiation — it requires `when [" + cond + "]` (e.g. a custom allocator "
                             "has no `default`); use an allocator-taking constructor instead").c_str(),
                            call->line);
                return "0";
            }
        }
        // A FIELD of that name: `findMethod` cannot see fields, so without this arm a field is reported
        // as "no constructor `x` — define one", which sends the reader to write a ctor they don't want.
        if (findFieldOwner(stci, method)) {
            unsupported(("`" + disp + "." + method + "` — dot-on-type calls a constructor; "
                         + dotOnTypeAdvice(DotMemberKind::Field, disp, typeName, method)).c_str(), call->line);
            return "0";
        }
        // The receiver is an opaque parameter and its bounds promise no such ctor — the BOUND is what is
        // missing, not the type, and "`T` cannot be constructed" would name the wrong problem and the
        // wrong fix.
        if (rejectUnprovenBound(stci->name, method, call->line)) return "0";
        // No ctor AT ALL is the "not constructible" case, not a misspelled name — route it through the
        // context-aware advice (which offers `of`/`zero` only for a transparent value).
        if (stci->ctors.empty() && rejectNamelessConstruction(*stci, disp, /*viaNew=*/false, call->line))
            return "0";
        // `deserializeJsonBuffer::<Shared<X>>` for a pointer-free `X`. The handle spelling is how a GRAPH
        // comes back — the root arrives behind one because a cycle cannot be returned by value — and a
        // type that reaches no `Shared`/`Weak` is not a graph, so it is read by value with no handle and no
        // envelope. Say that here: the bound holds (`X` really is `Deserializable`), so the only thing the
        // author sees otherwise is a missing ctor reported against stdlib source.
        if (method == "deserialize") {
            const std::string x = sharedPointeeClass(stci->name);
            auto e = x.empty() ? _classes.end() : _classes.find(x);
            if (e != _classes.end())
                unsupported(("`" + demangleForDisplay(x) + "` reaches no `Shared`/`Weak` field, so it is not "
                             "a graph — read it by value (`::<" + demangleForDisplay(x) + ">`), not as `Shared<"
                             + demangleForDisplay(x) + ">`. Only a graph comes back behind a handle").c_str(),
                            call->line);
            if (e != _classes.end()) return "0";
        }
        unsupported(("type `" + disp + "` has no constructor `" + method + "` — define one "
                     "(`ctor " + method + "(...) {…}`)").c_str(), call->line);
        return "0";
    }
    if (!mi->isCtor) {
        // Dot-on-type is for constructors only. The shared preamble teaches the rule; the second clause
        // must then say what the name ACTUALLY is. It used to assert "is a static function" without ever
        // checking, so an INSTANCE method was mislabelled a static and the advice that followed
        // (`Type::name(...)`) sent the reader to a second error telling them the opposite.
        unsupported(("`" + disp + "." + method + "` — dot-on-type calls a constructor; "
                     + dotOnTypeAdvice(mi->isStatic ? DotMemberKind::Static : DotMemberKind::Method, disp, typeName, method)).c_str(),
                    call->line);
        return "0";
    }
    // A GRAPH NODE cannot be read BY VALUE: its `deserialize` returns `Result<Shared<This>, …>`, because a
    // cycle has nowhere to point if the root is a stack value. `deserializeJsonBuffer::<Node>` therefore
    // assigns that into a `Result<Node, …>`, and until this arm existed the mismatch reached CLANG — the
    // bound holds (`Node` really does implement `Deserializable`) and `kama check` passed clean.
    //
    // ⚠️ It cannot be answered at the BOUND, which is where it belongs: bounds are judged while a generic
    // instance is registered, during collection, and `graphDeserialize` is a whole-program fact settled
    // afterwards. So it lands here, at the lowering, which is the first point that knows. The same is true
    // of its mirror image (a handle over a pointer-free type — see the `deserialize` arm above).
    if (method == "deserialize" && stci->graphDeserialize && !_typeSubst.empty()) {
        const std::string n = demangleForDisplay(stci->name);
        unsupported(("`" + n + "` reaches a `Shared`/`Weak` field, so it is a graph and cannot be read by "
                     "value — a cycle has nowhere to point if the root is a stack value. Read it as "
                     "`Shared<" + n + ">`").c_str(), call->line);
        return "0";
    }
    // One-way construction (M8 Phase E): the enclosing type's args ride the TYPE (`Type::<A>.make(...)`),
    // NOT the ctor name. A turbofish on the ctor (`Type.make::<A>`) is reserved for a ctor's OWN generic
    // params — none exist yet — so redirect to the canonical on-type spelling. (`mi` resolved above via the
    // method-turbofish fallback so this can name the exact fix.)
    if (recv->identifier && recv->identifier->genericArgs) {
        unsupported(("type arguments belong on the type — write `" + disp + "::<...>." + method
                     + "(...)`, not `" + disp + "." + method + "::<...>(...)`").c_str(), call->line);
        return "0";
    }
    // THE MINT. A `type view`'s constructor is private, so this is where the two places a view may be born
    // are decided. One of them canAccess already knows — `_currentClass == owner` is the view minting
    // ITSELF, which is what makes `View.slice()` and a future `split`/`chunks`/`first` work with no extra
    // rule. The other is the grant: the type being VIEWED, declared by implementing a member of a
    // `@viewable` contract that returns this view (`_mintGrant`, computed on entry to the body).
    //
    // The diagnostic replaces canAccess's generic "'make' is private in 'View'", which would be true and
    // useless — it names an access-control fact and leaves the reader to rediscover the whole model.
    if (stci->isBorrow && mi->visibility != Visibility::Public && _currentClass != owner
        && _mintGrant != tn) {
        unsupported(("`" + disp + "` is a `view`, so only the type it views may mint one — and `"
                     + (_currentClass ? _currentClass->name : std::string("this function"))
                     + "` has not declared that it does. Implement a `@viewable` contract whose member "
                       "returns `" + disp + "`, and mint it from that member's body").c_str(), call->line);
        return "0";
    }
    if (!stci->isBorrow || _mintGrant != tn)
        canAccess(owner, mi->visibility, method, call->line);
    recordNodeRef(recv->identifier.get(), mi->node);   // M6 B3a: `Type.name(...)` references the ctor
    return emitReorderedCall(mi->cName, "", mi->params, call->args, call->line);
}

// The C scalar type of a receiver whose class is a PRIMITIVE (so `exprClass` is "") — lets the primitive
// method dispatch resolve a conformance on a member/index receiver (`p.x.format(f)`, `arr[i].hash()`,
// `s[i].format(f)`), not just a bare identifier. Powers primitive-typed interpolation holes like `${p.x}`.
// "" if it isn't a resolvable primitive place.
std::string CEmitter::receiverScalarCType(SharedExpression e)
{
    if (!e) return "";
    ASTNode* n = e.get();
    if (auto* id = dynamic_cast<IdentifierNode*>(n)) {
        if (id->value && _localCTypes.count(*id->value)) return _localCTypes[*id->value];
        if (id->value) { auto cs = _comptimeSubst.find(*id->value); if (cs != _comptimeSubst.end()) return cType(primTypeNode(cs->second.kind)); }
        // ...and a MODULE-scope name, which neither of the two lookups above can see: they answer for a
        // local and for a bound `comptime` parameter. A module `static`/`comptime` is reached exactly the
        // way a module function is, so it resolves the same way. Without this a module-scope name was not
        // a valid method receiver AT ALL — reported as `${WIDTH}` failing to interpolate, but interpolation
        // only lowers to a method call on the value, so `WIDTH.toString()` failed identically and so did
        // every module `static`. One missing lookup, three symptoms.
        if (id->value) { auto ms = _moduleStatics.find(resolveModuleVar(*id->value, id->qualifier));
                         if (ms != _moduleStatics.end() && ms->second) return cType(ms->second); }
        if (id->value) { const std::string xk = resolveExternConst(*id->value, id->qualifier);
                         if (!xk.empty()) return cType(_externConsts[xk].type); }
        return "";
    }
    if (auto* ma = dynamic_cast<MemberAccessNode*>(n)) {
        std::string recv = exprClass(ma->expression);
        if (!recv.empty() && ma->identifier && ma->identifier->value && _classes.count(recv)) {
            ClassInfo* owner = findFieldOwner(&_classes[recv], *ma->identifier->value);
            if (owner)
                for (auto& f : owner->fields)
                    if (f.name == *ma->identifier->value && f.type)
                        return fieldCType(recv, f);   // a primitive field -> "int32_t", etc.
        }
        return "";
    }
    if (auto* ea = dynamic_cast<ElementAccessNode*>(n)) {
        std::string cc;   // the container's C type
        if (ea->identifier && ea->identifier->value && _localCTypes.count(*ea->identifier->value))
            cc = _localCTypes[*ea->identifier->value];
        else if (ea->expression) {
            if (auto* tid = dynamic_cast<IdentifierNode*>(ea->expression.get()))
                if (tid->value && _localCTypes.count(*tid->value)) cc = _localCTypes[*tid->value];
            if (cc.empty()) cc = exprClass(ea->expression);
        }
        if (cc == "kama_string") return "uint8_t";                        // a string byte index
        if (!cc.empty() && _collections.count(cc)) return _collections[cc].elemCType;
        // ...and a LIBRARY container, whose element type is its `operator[]`'s `ref T` with the instance's
        // type args bound. `indexElemTypeRaw` already answers that for a CLASS element (it is what makes
        // `xs[0].m()` work); the scalar half was missing, so `xs[i]` was not a nameable receiver when the
        // element was a primitive. That is why every container hops through a `const ref T` helper to call
        // an element's method — and why the hop then collides with the rule that a `ref` parameter may not
        // name a smart pointer, gating serde for `DynamicArray<Owned<X>>`/`<Shared<X>>`.
        std::string et = indexElemTypeRaw(e);
        return isClass(et) ? std::string() : et;   // a class element is exprClass's job, not this one
    }
    return "";
}

// The exact KAMA type node behind a place expression — an identifier (local/param/foreach binding) or a
// field reached through an instance. This is the only channel that keeps `char` distinct from `uint32`,
// which share the C type `uint32_t`: `_localCTypes` and `receiverScalarCType` have already erased it.
// Null when the expression is neither shape, or when nothing recorded a type node for it.
SharedIdentifier CEmitter::receiverTypeNode(SharedExpression e)
{
    if (!e) return SharedIdentifier();
    ASTNode* n = e.get();
    if (auto* id = dynamic_cast<IdentifierNode*>(n)) {
        if (id->value) { auto it = _localTypeNodes.find(*id->value); if (it != _localTypeNodes.end()) return it->second; }
        if (id->value) { auto cs = _comptimeSubst.find(*id->value); if (cs != _comptimeSubst.end()) return primTypeNode(cs->second.kind); }
        if (id->value) { auto ms = _moduleStatics.find(resolveModuleVar(*id->value, id->qualifier));   // module `static`/`comptime`
                         if (ms != _moduleStatics.end() && ms->second) return ms->second; }
        if (id->value) { const std::string xk = resolveExternConst(*id->value, id->qualifier);          // `extern const`
                         if (!xk.empty()) return _externConsts[xk].type; }
    } else if (auto* ma = dynamic_cast<MemberAccessNode*>(n)) {
        std::string recv = exprClass(ma->expression);
        if (!recv.empty() && ma->identifier && ma->identifier->value && _classes.count(recv)) {
            ClassInfo* owner = findFieldOwner(&_classes[recv], *ma->identifier->value);
            if (owner) for (auto& f : owner->fields)
                if (f.name == *ma->identifier->value) return f.type;
        }
    }
    return SharedIdentifier();
}

// True iff `e`'s kama type is `char` — a char literal, an identifier/param/foreach binding, or a struct field.
// Consults the KAMA type node so an interpolation hole `${c}` renders its CHARACTER (via `writeChar`) rather
// than going through the numeric formatting path.
bool CEmitter::exprIsChar(SharedExpression e)
{
    if (!e) return false;
    if (dynamic_cast<CharNode*>(e.get())) return true;
    SharedIdentifier ty = receiverTypeNode(e);
    return ty && !ty->genericArg && ty->builtInVal == IDENTIFIER_CHAR_VAL;
}

// The IDENTIFIER_*_VAL builtin kind of an interpolation hole's numeric type — for the `${x:spec}` fast-path.
// Resolves the exact kama type node for an identifier (local/param/foreach) or a struct field (so `char`
// stays distinct from `uint32`), then falls back to the C scalar type of a place (`arr[i]`, `s[i]`, a field
// through an instance) mapped back to a kind. Returns 0 for a user type or anything it can't classify.
int CEmitter::holeBuiltinType(SharedExpression e)
{
    if (!e) return 0;
    SharedIdentifier ty = receiverTypeNode(e);
    if (ty && !ty->genericArg && ty->builtInVal) return ty->builtInVal;
    std::string ct = receiverScalarCType(e);
    if (ct == "int8_t")   return IDENTIFIER_INT8_VAL;
    if (ct == "int16_t")  return IDENTIFIER_INT16_VAL;
    if (ct == "int32_t")  return IDENTIFIER_INT32_VAL;
    if (ct == "int64_t")  return IDENTIFIER_INT64_VAL;
    if (ct == "uint8_t")  return IDENTIFIER_UINT8_VAL;
    if (ct == "uint16_t") return IDENTIFIER_UINT16_VAL;
    if (ct == "uint32_t") return IDENTIFIER_UINT32_VAL;
    if (ct == "uint64_t") return IDENTIFIER_UINT64_VAL;
    if (ct == "float")    return IDENTIFIER_FLOAT32_VAL;
    if (ct == "double")   return IDENTIFIER_FLOAT64_VAL;
    return 0;
}

// Emit a format-specifier hole `${x:spec}` as a Formatter fast-path (the Formattable contract stays spec-less).
// `spec` is the raw text after the `:`. Forms:
//   base (M1)      — `x`/`0x`/`0X`/`o`/`0o`/`b`/`0b`  (integer holes; the leading `0` is echoed as a prefix)
//   width (M2)     — `W` (space-pad) / `0W` (zero-pad) on decimal integers, and `W.N` / `0W.N` on floats
//   precision      — `.N` on floats (a width of 0)
//   flags (M3)     — a leading `+` (force sign) and/or `-` (left-align) on any decimal int/float form
// Grammar (parsed here, not in the lexer — future specifiers add no AST churn):
//   spec := [ '+' | '-' ]*  [ '0'? digits ]  [ '.' digits ]  | base
// A base spec doesn't combine with width/flags/precision yet, and a float width needs a precision. A wrong
// hole kind / unrecognized spec is a hard error. Flag bits mirror kama_runtime.h: 1=zero, 2=left, 4=plus.
void CEmitter::emitHoleSpec(const std::string& fv, SharedExpression hole, const std::string& spec)
{
    int bt = holeBuiltinType(hole);
    bool isFloat  = (bt == IDENTIFIER_FLOAT32_VAL || bt == IDENTIFIER_FLOAT64_VAL);
    bool isInt    = (bt >= IDENTIFIER_INT8_VAL && bt <= IDENTIFIER_UINT64_VAL);   // INT8..UINT64 (not bool/char)
    bool isSigned = (bt >= IDENTIFIER_INT8_VAL && bt <= IDENTIFIER_INT64_VAL);
    int bits = 32;                                                                // declared bit width (base masking)
    switch (bt) {
        case IDENTIFIER_INT8_VAL:  case IDENTIFIER_UINT8_VAL:  bits = 8;  break;
        case IDENTIFIER_INT16_VAL: case IDENTIFIER_UINT16_VAL: bits = 16; break;
        case IDENTIFIER_INT64_VAL: case IDENTIFIER_UINT64_VAL: bits = 64; break;
        default: bits = 32; break;
    }
    std::string val = emitExpression(hole);
    auto isBaseLetter = [](char c) { return c=='x'||c=='X'||c=='o'||c=='O'||c=='b'||c=='B'; };

    // ---- Split off a trailing base marker (always last): `x`/`0x`/... A `0` before the letter that is the
    //      whole remaining head is the echoed prefix; otherwise the base is bare and any `0` is a pad flag. ----
    std::string head = spec;
    bool hasBase = false; int base = 0, upper = 0, prefix = 0;
    if (!spec.empty() && isBaseLetter(spec.back())) {
        char c = spec.back(); hasBase = true;
        base = (c=='x'||c=='X') ? 16 : (c=='o'||c=='O') ? 8 : 2;
        upper = (c=='X') ? 1 : 0;
        head = spec.substr(0, spec.size() - 1);
        if (head == "0") { prefix = 1; head.clear(); }
    }

    // ---- Parse the head: [flags] [`0`? width] [`.` prec]. ----
    size_t pos = 0; bool plus = false, left = false, zero = false, hasWidth = false, hasPrec = false;
    int width = 0, prec = 0;
    while (pos < head.size() && (head[pos] == '+' || head[pos] == '-')) { if (head[pos] == '+') plus = true; else left = true; ++pos; }
    if (pos + 1 < head.size() && head[pos] == '0' && isdigit((unsigned char)head[pos+1])) { zero = true; ++pos; }
    while (pos < head.size() && isdigit((unsigned char)head[pos])) { width = width*10 + (head[pos]-'0'); hasWidth = true; ++pos; }
    if (pos < head.size() && head[pos] == '.') {
        ++pos; hasPrec = true; size_t d0 = pos;
        while (pos < head.size() && isdigit((unsigned char)head[pos])) { prec = prec*10 + (head[pos]-'0'); ++pos; }
        if (pos == d0) { unsupported(("precision specifier `:" + spec + "` needs digits (e.g. `.2`)").c_str(), hole->line); return; }
    }
    if (pos != head.size()) { unsupported(("unrecognized format specifier `:" + spec + "`").c_str(), hole->line); return; }
    bool hasFlag = plus || left || zero;
    int flags = (zero ? 1 : 0) | (left ? 2 : 0) | (plus ? 4 : 0);

    // ---- Base spec: integer only. Width and the `0`/`-` flags compose with it (`${n:08x}` is the zero
    //      flag + width 8, NO prefix — the prefix is only ever the lone `0` directly before the letter, so
    //      `:0x` and `:08x` mean different things, as `%#x` and `%08x` do). Precision has no meaning on an
    //      integer and `+` none on a bit pattern, so both stay refused. The combination was refused
    //      wholesale as "not yet" until the consumer-driven audit (0.9.228). ----
    if (hasBase) {
        if (!isInt) { unsupported(("base specifier `:" + spec + "` applies only to an integer hole").c_str(), hole->line); return; }
        if (hasPrec) { unsupported(("a precision (`.N`) does not apply to a base specifier — `:" + spec + "` (an integer has no fraction)").c_str(), hole->line); return; }
        if (plus)    { unsupported(("`+` does not apply to a base specifier — `:" + spec + "` shows an unsigned bit pattern, which has no sign").c_str(), hole->line); return; }
        _hoisted.push_back("Formatter__writeU64Radix(&" + fv + ", (uint64_t)(" + val + "), "
                           + std::to_string(base) + ", " + std::to_string(bits) + ", "
                           + std::to_string(upper) + ", " + std::to_string(prefix) + ", "
                           + std::to_string(width) + ", " + std::to_string(flags) + ");");
        return;
    }

    if (!hasWidth && !hasPrec && !hasFlag) { unsupported(("unrecognized format specifier `:" + spec + "`").c_str(), hole->line); return; }

    // ---- Precision (with optional width/flags) — float only. ----
    if (hasPrec) {
        if (!isFloat) { unsupported(("precision specifier `:" + spec + "` applies only to a float hole").c_str(), hole->line); return; }
        _hoisted.push_back("Formatter__writeF64Prec(&" + fv + ", (double)(" + val + "), "
                           + std::to_string(prec) + ", " + std::to_string(width) + ", " + std::to_string(flags) + ");");
        return;
    }
    // ---- Width/flags only — decimal integer (a float width needs a precision to be well-defined). ----
    if (isFloat) { unsupported(("a float width needs a precision (e.g. `:" + std::to_string(width) + ".2`)").c_str(), hole->line); return; }
    if (!isInt) { unsupported(("format specifier `:" + spec + "` applies only to a numeric hole").c_str(), hole->line); return; }
    if (isSigned)
        _hoisted.push_back("Formatter__writeI64Width(&" + fv + ", (int64_t)(" + val + "), "
                           + std::to_string(width) + ", " + std::to_string(flags) + ");");
    else
        _hoisted.push_back("Formatter__writeU64Width(&" + fv + ", (uint64_t)(" + val + "), "
                           + std::to_string(width) + ", " + std::to_string(flags) + ");");
}

std::string CEmitter::emitMethodCall(InvocationNode* call, MemberAccessNode* recv)
{
    std::string method = (recv->identifier && recv->identifier->value) ? *recv->identifier->value : "";
    SharedExpression receiver = recv->expression;
    // A method takes NO turbofish. There is exactly one way to name a type argument on a call, and it is
    // on the callee: a free fn (`decode::<T>(…)`) or a type (`Type::<Arg>.ctor(…)`). `r.deserialize::<T>()`
    // used to be an exception, lowered through a `__kamaDeserialize<T>` trampoline; it was pure sugar for
    // `T.deserialize(r: r)`, which the stdlib's own `decode<T>` already writes.
    if (recv->identifier && recv->identifier->genericArgs) {
        unsupported(("`." + method + "::<…>` — a method takes no type arguments; name them on the callee "
                     "instead (`T." + method + "(…)`, or `T::<Arg>." + method + "(…)` for a generic type)").c_str(),
                    call->line);
        return "0";
    }
    // `BindableFunctionPtr.bind(…)` takes its signature from the DESTINATION, and the one destination that
    // names it is a local's declared type — emitBindablePromote builds it there. Anywhere else (a return, an
    // argument, an assignment) the receiver would otherwise read as an unknown name.
    if (auto* rid = dynamic_cast<IdentifierNode*>(receiver.get()))
        if (rid->value && *rid->value == "BindableFunctionPtr" && method == "bind") {
            unsupported("`BindableFunctionPtr.bind(…)` takes its signature from the local it initializes — "
                        "bind one first (`BindableFunctionPtr<Sig> b = BindableFunctionPtr.bind(obj: …, "
                        "method: …);`) and hand that on with `give`", call->line);
            return "0";
        }
    std::string cls = exprClass(receiver);
    // `p[0].m()` on a LOCAL raw `UnsafePtr<T>`: `exprClass` deliberately does not type a local raw element
    // (a store through one — `nd[i] = od[i]` in the collections — must stay a bitwise relocate, and
    // exprClass feeds the store path; widening it was measured to break 45 fixtures). A CALL is not a
    // store: the receiver is borrowed in place, `&(p[0])`, exactly as a FIELD element (`this.buf[i].m()`,
    // which ptrElemType has always typed) is. So the RECEIVER alone is typed here, at the one site that
    // builds a receiver pointer, and every store keeps its plain-C semantics. Until 0.9.228 this was
    // refused as "untyped to ownership" with the borrow/own spellings (the first consumer's KB-14).
    if (cls.empty()) {
        const std::string et = ptrLocalElemType(receiver);
        if (!et.empty() && _classes.count(et)) cls = et;
    }
    // A `string` receiver that `exprClass` can't name — a bare literal (`"x".trim()`) or a `+` chain
    // (`(a + b).length()`) — still classes as the `string` primitive. Localizes string knowledge to
    // `exprIsString`; the rvalue is made addressable below (addrOfOperand), like `.concat()` composes.
    if (cls.empty() && exprIsString(receiver)) cls = "kama_string";
    // (An iterator-invalidation guard stood here, keyed on `method == "add" && isIntrinsicColl`. It
    // could never fire: `isIntrinsicColl` is set only for String/Owned/Shared/Weak/Bindable/Fixed, and
    // none of those has an `add` — every growable collection is an ordinary library type. It is
    // replaced by the view model's place rule, which makes the container unnameable for the extent of
    // the `foreach` and so needs no method-name list to stay honest.)
    // a non-const method may not be called on a const receiver (deep const).
    // The method lives on the pointee for a smart-pointer receiver (auto-deref).
    if (isConstReceiver(receiver)) {
        std::string mcls = isSmartPtrClass(cls) ? _classes[cls].collElemClass : cls;
        ClassInfo* owner = nullptr;
        MethodInfo* mi = _classes.count(mcls) ? findMethod(&_classes[mcls], method, &owner) : nullptr;
        if (mi && !mi->isConst)
            unsupported(("cannot call non-const method `" + method + "` on a const receiver "
                         "(declare it `const fn` if it does not mutate)").c_str(), call->line);
        // A CONTRACT-typed receiver resolves in `_interfaces`, not `_classes`, so the lookup above comes
        // back null and the call sails through. The contract member is the only thing visible here — the
        // concrete implementation is behind a vtable slot — which is exactly why the member carries
        // `isConst` (see InterfaceMethod) and why conformance now enforces it.
        if (!mi && isInterface(mcls))
            if (const std::vector<InterfaceMethod>* need = contractMethods(mcls))
                for (auto& nm : *need)
                    if (nm.name == method && !nm.isConst)
                        unsupported(("cannot call non-const contract method `" + method + "` on a const "
                                     "receiver (declare it `const fn` on `" + mcls
                                     + "` if it does not mutate)").c_str(), call->line);
    }
    // Mutable-borrow uniqueness, RECEIVER side. `emitReorderedCall` compares the `ref`/`out` arguments
    // against each other, but it only ever sees the receiver as an already-emitted C string, so
    // `p.absorb(other: p)` and `p.take(n: p.hi)` slipped through it. A non-`const fn` method borrows its
    // receiver mutably, so it participates in exactly the same prefix test — checked here, where the
    // receiver EXPRESSION is still in hand, rather than by threading it through `emitDispatch`.
    if (!cls.empty()) {
        std::string mcls = isSmartPtrClass(cls) ? _classes[cls].collElemClass : cls;
        ClassInfo* rowner = nullptr;
        MethodInfo* rmi = _classes.count(mcls) ? findMethod(&_classes[mcls], method, &rowner) : nullptr;
        std::vector<std::string> recvPlace = placePath(receiver);
        // A non-`const fn` borrows its receiver MUTABLY, so calling one on frozen storage is the shape
        // finding ⑤ rides — `a.add(item: 3)` can realloc, and the window's alias would be left pointing
        // at the freed buffer. `const fn` is what makes this precise rather than "any method call": the
        // stdlib marks 247 of them, so a read inside a window stays free.
        if (rmi && !rmi->isConst && !recvPlace.empty()) rejectFrozenWrite(receiver, call->line);
        if (rmi && !rmi->isConst && !recvPlace.empty() && call->args) {
            for (auto& a : *call->args) {
                if (!a || !a->name || !a->name->value) continue;
                const ParamSig* ps = nullptr;
                for (auto& p : rmi->params) if (p.name == *a->name->value) { ps = &p; break; }
                // A by-value VIEW argument over the receiver's own storage: `b.eat(v: b.view())`. The
                // receiver is borrowed mutably by a non-`const fn`, so this is the argument-list aliasing
                // rule with the receiver as the mutable side — and the receiver never reaches that rule,
                // which only ever compares arguments with each other.
                if (ps && !ps->byRef && isViewCType(ps->className)) {
                    std::vector<std::string> vr = viewRootPlace(a->expression);
                    if (!vr.empty() && placesConflict(recvPlace, vr))
                        unsupported(("`" + placeText(vr) + "` is borrowed by the view argument `" + ps->name
                                     + "` while `" + placeText(recvPlace) + "` is the receiver of non-`const "
                                     "fn` `" + method + "` — the method may grow the very storage that "
                                     "window views, leaving it dangling. Mint the view inside `" + method
                                     + "`, or declare it a `const fn` if it does not mutate").c_str(),
                                    call->line);
                    continue;
                }
                if (!ps || !ps->byRef || ps->isConst) continue;
                SharedExpression ax = a->expression;
                if (auto* h = dynamic_cast<HandoffNode*>(ax.get())) ax = h->value;
                std::vector<std::string> ap = placePath(ax);
                if (!ap.empty() && placesConflict(recvPlace, ap))
                    unsupported(("`" + placeText(ap) + "` is passed as a mutable argument to `" + method
                                 + "` while `" + placeText(recvPlace) + "` is its receiver — a non-`const "
                                 "fn` borrows its receiver mutably, so this hands the method two mutable "
                                 "borrows of the same object; pass a distinct place, read it into a local "
                                 "first, or declare `" + method + "` a `const fn` if it does not mutate")
                                    .c_str(), call->line);
            }
        }
    }
    // Smart-pointer receiver: an intrinsic (lock/expired/valid) or auto-deref to T.
    if (isSmartPtrClass(cls))
        return emitSmartPtrCall(cls, emitExpression(receiver), method, call->args, call->line,
                                recv->identifier.get());
    if (isInterface(cls))
        return emitInterfaceDispatch(emitExpression(receiver), cls, method, call->args, call->line, "",
                                     recv->identifier.get());
    // A PRIMITIVE receiver with a conformance (`type intrinsic <int32> implements Hashable`): the method's
    // `this` is the SCALAR itself, passed BY VALUE. `exprClass` is "" for a primitive, so recover the
    // receiver's type separately. Resolve on `_primConformances`; the call is a plain free function
    // `int32__hash(k)` (no pointer, no vtable).
    {
        std::string primTy = cls;
        bool viaTypeParam = false;
        if (primTy.empty()) {
            // Prefer the KAMA type node — the only channel that tells `char` from `uint32`, which share the
            // C type `uint32_t`. A place with no recorded node (a collection element, an index into an
            // array) falls back to its C type, which answers `uint32` for both.
            SharedIdentifier tn = receiverTypeNode(receiver);
            // THE GATE'S DISCRIMINATOR, and it has to be read BEFORE primKey: primKey substitutes first,
            // and that substitution is exactly what turns `K` into `int32`. A receiver whose recorded node
            // still spells a bound type PARAMETER is generic dispatch — the pervasive, zero-cost idiom —
            // and must stay legal. One that spells `int32` is a concrete receiver.
            // A NULL node means "cannot tell" (a collection element, an array index): permissive, because
            // treating it as concrete would fire the gate on library code.
            viaTypeParam = !tn || (tn->value && _typeSubst.count(*tn->value) != 0);
            std::string k = tn ? primKey(tn) : std::string();
            primTy = isScalarPrimKey(k) ? k : primKeyOfCType(receiverScalarCType(receiver));
        }
        if (ClassInfo* pci = primConformance(primTy)) {
            // A contract decorates a primitive WITHIN THE SCOPE OF THAT CONTRACT — the method is not part
            // of the primitive's own API. Otherwise any package declaring `type intrinsic <int32>
            // implements Weighable` would put `.weight()` on every `int32` in the program.
            if (!viaTypeParam && !_inSynthDispatch)
                unsupported(("`" + method + "` is not `" + primTy + "`'s own method — it comes from a "
                             "contract, so reach it through one: a bound (`fn f<T: C<T>>(T x)`) or a "
                             "contract value (`C c = x;`)").c_str(), call->line);
            ClassInfo* powner = nullptr;
            MethodInfo* pmi = findMethod(pci, method, &powner);
            if (!pmi) { unsupported(("unknown method `" + method + "` on `" + primTy + "`").c_str(), call->line); return "0"; }
            return emitReorderedCall(pmi->cName, emitExpression(receiver), pmi->params, call->args, call->line);
        }
    }
    if (cls.empty() || !_classes.count(cls)) {
        // `d.length()` on a `DynamicArray<T>` — see the header. The bucket is read off the RECEIVER's
        // declared type node, because that is what says whether a compiler change or a source change is
        // what closes this site.
        if (deferUnknownWhileProbing(classifyDeferredReceiver(receiver))) return "0";
        // NAME the receiver. This message used to be four words with no subject, and it was reached by a
        // module `static`/`comptime` used as one — so a `"${WIDTH}"` five lines down reported "method call
        // on unresolved receiver" against the CONSTANT's declaration line, naming neither the constant nor
        // the interpolation that lowered to the call. That cost the reporter ~40 minutes of bisection for
        // a one-lookup bug. A diagnostic about a name that cannot be resolved must at minimum say which.
        std::string who;
        if (auto* rid = dynamic_cast<IdentifierNode*>(receiver.get())) if (rid->value) who = *rid->value;
        // ⚠️ TWO different failures reach this line, and saying the wrong one is worse than saying
        // nothing. The receiver may be an unknown NAME, or a perfectly good value of a primitive type
        // that simply has no conformance carrying this method — which is what an `isize` hits, since
        // `isize`/`usize` are absent from every `type intrinsic <…> implements …` list in the prelude.
        // Telling someone that `n` is "not in reach" when `n` is the local on the line above sends them
        // hunting for a scope bug that is not there.
        // (A THIRD used to be handled here: an element of a LOCAL raw `UnsafePtr<T>` — `p[0].m()` —
        // refused as "untyped to ownership" with the borrow/own spellings, the first consumer's KB-14.
        // Since 0.9.228 the receiver is typed at the top of this function — a call borrows the element in
        // place, as the field form always did — so a class-typed local element never reaches this line;
        // the relocate-store reason that kept it out of exprClass is unchanged and lives there.)
        const std::string rct = receiverScalarCType(receiver);
        const std::string rk  = rct.empty() ? std::string() : primKeyOfCType(rct);
        if (rk.empty() && !who.empty()
            && reportDeclaredElsewhere("type", who, [&](const std::string& k) { return isTypeKey(k); },
                                       "this call", call->line))
            return "0";
        if (!rk.empty())
            unsupported(("`" + rk + "` has no method `" + method + "` — no contract that declares it is "
                         "implemented for `" + rk + "` (an interpolation hole needs `Formattable`, a `Map` key "
                         "needs `Hashable`, `sort` needs `Comparable`)").c_str(), call->line, rk);
        else
            unsupported((who.empty()
                         ? ("cannot resolve the receiver of `" + method + "` — its type is not known here")
                         : ("cannot resolve `" + who + "`, the receiver of `" + method + "` — no local, "
                            "parameter, module `static`/`comptime` or type of that name is in reach here")).c_str(),
                        call->line, who);
        return "0";
    }
    // The other side of that tally: a receiver the probe DID resolve, so this call site is fully checked.
    // Deferred-vs-resolved is what makes `--probe-templates` answer "how much of a template body can a
    // walk with no type binding actually see", rather than just "how much did it give up on".
    if (_probingTemplate) ++_probeResolved;
    // `.chars()`/`.split()` build a BORROWING iterator (Chars/Split) as a compound literal that reads each
    // operand TWICE (.data/.len) and borrows its bytes for the WHOLE loop. An owned/side-effecting rvalue
    // operand (`s.trim()`, `a + b`) is materialized ONCE into a scope-dtor'd temp (stable + read-once,
    // dropped after the loop — the A2 receiver-drop pattern), so it neither desyncs the two reads nor
    // dangles; a stable var/literal/field/`this` keeps the zero-copy path. Handled BEFORE `recvPtr` so an
    // owned receiver isn't ALSO hoisted by the general string path below (which would double-evaluate it).
    if (cls == "kama_string" && (method == "chars" || method == "split")) {
        auto stableBorrow = [&](SharedExpression e, const char* what) -> std::string {
            std::string t = hoistStringTemp(e);      // owned rvalue -> scope-dtor'd temp; "" if stable OR no slot
            if (!t.empty()) return t;
            if (!isStableStringRef(e.get())) {
                unsupported((std::string("`.") + method + "()` borrows and re-reads its " + what + " across "
                             "the whole loop, so it must be a stable reference (a variable, literal, field, "
                             "or `this`) — bind an expression like `s.trim()` or `a + b` to a local first").c_str(),
                            call->line);
                return "";                            // failure sentinel (a valid ref never emits "")
            }
            return emitExpression(e);                 // stable ref -> direct (zero-copy, unchanged)
        };
        if (!_synthCtx) _synthCtx = std::make_shared<CodeGenContext>(std::make_shared<std::string>("<generic>"));
        if (method == "chars") {
            std::string sv = stableBorrow(receiver, "receiver");
            if (sv.empty()) return "0";
            // A real constructor, not a positional compound literal. `{ data, len, 0 }` had to match the
            // field order in `prelude/global.kama` and nothing checked that it did, so reordering a field
            // there miscompiled every string iteration in silence. Now the C compiler checks it.
            std::string charsC = cType(synthId("Chars"));
            return "(" + charsC + "__over((uint8_t*)(" + sv + ").data, (int32_t)(" + sv + ").len))";
        }
        // split — borrows the receiver AND the separator; materialize each independently.
        SharedExpression sepExpr = (call->args && call->args->size() == 1) ? (*call->args)[0]->expression
                                                                          : SharedExpression();
        std::string sv = stableBorrow(receiver, "receiver");
        if (sv.empty()) return "0";
        std::string sep = sepExpr ? stableBorrow(sepExpr, "separator") : std::string("kama_string_lit(\"\", 0)");
        if (sep.empty()) return "0";
        std::string splitC = cType(synthId("Split"));
        return "(" + splitC + "__over((uint8_t*)(" + sv + ").data, (int32_t)(" + sv + ").len, (uint8_t*)("
             + sep + ").data, (int32_t)(" + sep + ").len))";
    }
    std::string recvPtr;
    if (auto* ea = dynamic_cast<ElementAccessNode*>(receiver.get())) {
        // `list[i].m()` — borrow the element IN PLACE via the bounds-checked `__at`
        // (a T* into the buffer). No copy, no temp; a plain nested call, strictly ISO C.
        std::string coll, recvExpr, idx;
        if (collectionElemAccess(ea, coll, recvExpr, idx))
            recvPtr = coll + "__at((" + coll + "*)&(" + recvExpr + "), " + idx + ")";
        else
            recvPtr = "&(" + emitExpression(receiver) + ")";
    } else if (cls == "kama_string") {
        // A string receiver may be an rvalue — a chained `s.trim().toLower()`, a `"lit".method()`, or an
        // `(a + b).length()`. An OWNED rvalue is hoisted into a scope-dtor'd temp (so its buffer is freed,
        // not leaked); a literal/lvalue keeps the addressable compound-literal / `&(x)` path.
        std::string t = hoistStringTemp(receiver);
        recvPtr = t.empty() ? addrOfOperand(receiver, "kama_string", call->line) : ("&" + t);
    } else {
        // An OWNED rvalue receiver — an operator result (`(a - b).m()`) or a by-value call/ctor result
        // (`make().m()`, `R().m()`, a method chain `builder.make().use()`) — owns a heap buffer that
        // addrOfOperand's throwaway compound-literal receiver would LEAK. Materialize it into a scope-dtor'd
        // temp so RAII frees it (the general-class analogue of the string-receiver hoist above). Gated to a
        // fresh BY-VALUE rvalue: an operator result, or ANY call (free fn OR method) that returns a fresh
        // owned value. A `fn ref T` place return (a borrow — a `ref` method result, `a[i]`, or a place-
        // returning free fn) is left to addrOfOperand and NEVER dropped, so this can't double-free.
        // `invocationReturnsPlace` (via isPlaceReturn) is the discriminator — it covers method chains
        // (previously excluded → leak) and correctly excludes a `fn ref T` free fn (previously included →
        // would double-free). Pure RAII scope-drop; no lifetime analysis.
        InvocationNode* riv = dynamic_cast<InvocationNode*>(receiver.get());
        bool byValueRvalue = dynamic_cast<BinaryExpressionNode*>(receiver.get())
                             || (riv && !invocationReturnsPlace(riv));
        if (_hoistOK && byValueRvalue && _classes.count(cls) && _classes[cls].destructible) {
            std::string t = "__recv" + std::to_string(_tempCounter++);
            std::string ct = hoistCtorIfInline(receiver);                 // inline ctor -> its own temp init
            if (!ct.empty()) { recordDestructibleLocal(ct, cls); recvPtr = "&" + ct; }
            else {
                _hoisted.push_back(cls + " " + t + " = " + emitExpression(receiver) + ";");
                recordDestructibleLocal(t, cls);
                recvPtr = "&" + t;
            }
        } else {
            recvPtr = addrOfOperand(receiver, cls, call->line);
        }
    }
    // The contract-scope gate, class path. `string` has a real `_classes` entry, so its INJECTED
    // `compareTo`/`hash` never reach the primitive branch above — and they sit on the same ClassInfo as its
    // NATIVE `equals`/`length`. `fromContract` is exactly what tells them apart: it is non-empty only for a
    // method supplied from outside the type's own body (a `type intrinsic` block), which is
    // the property the rule wants. A type that declares `implements C` in its own body is untouched.
    {
        ClassInfo* gowner = nullptr;
        MethodInfo* gmi = _classes.count(cls) ? findMethod(&_classes[cls], method, &gowner) : nullptr;
        if (gmi && !gmi->fromContract.empty() && !_inSynthDispatch) {
            // Same discriminator as the primitive branch: a receiver still spelling a bound type parameter
            // is generic dispatch and stays legal. A null node means "cannot tell" — permissive.
            SharedIdentifier tn = receiverTypeNode(receiver);
            bool viaTypeParam = !tn || (tn->value && _typeSubst.count(*tn->value) != 0);
            if (!viaTypeParam)
                unsupported(("`" + method + "` is not `" + cls + "`'s own method — it comes from the "
                             "contract `" + gmi->fromContract + "`, so reach it through one: a bound "
                             "(`fn f<T: " + gmi->fromContract + "<T>>(T x)`) or a contract value").c_str(),
                            call->line);
        }
    }
    std::string callStr = emitDispatch(cls, recvPtr, method, call->args, call->line, recv->identifier.get(), receiver);
    // a place-returning `fn ref T m(…)` returns a `T*`; deref it so the call is an lvalue EVERYWHERE
    // (read copies out; `m(…) = x` writes through; `m(…).f` / `ref m(…)` / nesting all compose via the
    // existing lvalue paths). `&(*…)` folds, so a chained `a.at(i).at(j)` stays clean ISO C.
    // Resolved the way emitDispatch resolved it — through `Deref<T>` when the method lives on the pointee
    // (`this.root.getRef(k)` on an `Owned<Node>`): the deref arm used to be skipped here, so a place call
    // reached through a smart pointer came back as a bare `T*` while the same call on a direct receiver
    // was `(*…)`, and the `return &(place)` path could not serve both.
    MethodInfo* pmi = placeMethodOf(cls, method);
    return (pmi && pmi->isPlaceReturn) ? ("(*" + callStr + ")") : callStr;
}

// The method `recv.m()` resolves to, following `Deref<T>` auto-deref transitively when `m` is not on the
// receiver's own class — the same walk emitDispatch's deref arm makes. Null when nothing resolves.
MethodInfo* CEmitter::placeMethodOf(const std::string& cls, const std::string& method)
{
    std::string c = cls;
    for (int hops = 0; hops < 8 && !c.empty() && _classes.count(c); ++hops) {
        ClassInfo* owner = nullptr;
        if (MethodInfo* mi = findMethod(&_classes[c], method, &owner)) return mi;
        c = derefTarget(c);
    }
    return nullptr;
}

// Nothing is constructible by default (SPEC § Construction). A nameless `Type(...)` / `new Type(...)` names
// no constructor, so it has nothing to call: it would SILENTLY drop any arguments and leave the object
// uninitialized — and for a type with NO ctor at all it used to slip through entirely, emitting a bare
// `T v;` that reads uninitialized stack (an escape hatch around `slot`, invisible to -Wuninitialized
// because the local is struct-typed). So it is rejected for every user type, at every construction form.
//
// The advice is CONTEXT-AWARE, as SPEC promises: `of`/`zero` are offered only for a TRANSPARENT value (all
// fields public — a data bag can bless its own memberwise/zero state), never for a `resource` or a value
// with private fields, which must state a real `ctor`.
//
// One exemption: an intrinsic collection has no kama ctor to point at (and `BindableFunctionPtr`, the one
// that took this spelling, is now built by `BindableFunctionPtr.bind`). A `type extern value` used to be the
// second — `div_t(quot: 3, rem: 2)` was by-name aggregate init — until KR-53 gave it constructors.
// Returns true when it rejected, so a caller can suppress its own follow-on diagnostic.
bool CEmitter::rejectNamelessConstruction(const ClassInfo& ci, const std::string& disp, bool viaNew, int srcLine)
{
    if (ci.isIntrinsicColl) return false;

    if (!ci.ctors.empty()) {
        // Named ctors exist — point at them by their real names rather than a guessed `make`.
        std::string names;
        for (auto& c : ci.ctors) {
            if (!names.empty()) names += "` / `";
            names += disp + "." + c.first + "(...)";
        }
        unsupported((viaNew
                     ? "nameless `new " + disp + "(...)` is no longer allowed — construct through a named "
                       "constructor (`new " + names + "`)"
                     : "nameless construction `" + disp + "(...)` is no longer allowed — use a named "
                       "constructor (`" + names + "`)").c_str(), srcLine);
        return true;
    }

    std::string how = isTransparentValue(ci)
        ? "add one (`ctor make(...)`), or opt in to a bag constructor with `@generate(of)` / `@generate(zero)` "
          "and call `" + disp + ".of(...)` / `" + disp + ".zero()`"
        : "add one (`ctor make(...)` returning `give`)";
    unsupported(("`" + disp + "` cannot be constructed — it has no `ctor`; " + how).c_str(), srcLine);
    return true;
}

// The `new` entry point into the rule above — covers every `new` form, because both call sites (the
// local-declaration arm and the value-position hoist) run this BEFORE dispatching to the plain / `try` /
// fallible / placement boxing.
void CEmitter::checkNamelessNewBanned(ObjectCreationNode* oc, int line)
{
    if (!oc || oc->ctorName || !oc->type || !oc->type->value) return;
    std::string cls = resolveUserName(*oc->type->value, oc->type->qualifier);
    if (!isClass(cls)) return;
    rejectNamelessConstruction(_classes[cls], *oc->type->value, /*viaNew=*/true, line);
}

// ---------------------------------------------------------------------------
// Translation unit
// ---------------------------------------------------------------------------

// Whole-program symbol table: run the collect passes for every unit (they append
// to the shared maps), then resolve inheritance/vtables/destructibility once.
// ---------------------------------------------------------------------------
// `@compileFor(FLAG)` conditional compilation — the "structure" axis (decl-level keep/drop)
// ---------------------------------------------------------------------------

// Evaluate a decl's `@compileFor(...)` gate against the active build-flag set. Returns true (KEEP)
// when there is no `@compileFor`, or when every gate arg holds. Args are ANDed: a bare `FLAG` holds
// iff FLAG is active; a negated `!FLAG` holds iff FLAG is inactive. Membership + `!` + comma-AND is
// v1's deliberately-small logic (full `&&`/`||`/parens are a later comptime-bool fold, out of scope).
// Names the BUILD CONFIGURATION owns, as opposed to a project's own `flags`. Purely lexical, so an
// inactive-but-legitimate gate (`@compileFor(OS_FREEBSD)` in a linux build) is not mistaken for a typo.
// The driver shares this predicate — it is also what `flags` may not redeclare — so the rule has exactly
// one definition. Built-in TARGET names are deliberately NOT here: they are CLI shortcuts for a triple
// family and never become flags, so `@compileFor(MACOS)` should indeed be rejected in favour of
// `@compileFor(OS_MACOS)`, which is the fact rather than the spelling.
// The contract `for` clause's kind words. One table, read both directions (see kama.cemit.h), so the
// set of legal words and the order a clause renders in cannot drift apart.
namespace {
struct KindWord { const char* word; unsigned bit; };
static const KindWord kKindWords[] = {
    { "value", IK_Value }, { "resource", IK_Resource }, { "view", IK_View },
    { "enum",  IK_Enum  }, { "intrinsic", IK_Intrinsic },
};
}

unsigned kamaImplKindBit(const std::string& word)
{
    for (auto& kw : kKindWords) if (word == kw.word) return kw.bit;
    return 0;
}

std::string kamaImplKindListText(unsigned mask)
{
    std::string out;
    for (auto& kw : kKindWords)
        if (mask & kw.bit) { if (!out.empty()) out += ", "; out += kw.word; }
    return out;
}

bool kamaIsBuildConfigFlag(const std::string& n)
{
    // SIMD128 joins these rather than the namespaced prefixes: it is derived from the triple like an
    // ARCH_ flag, but it is a CAPABILITY rather than a triple component, so it has no namespace to sit in.
    if (n == "DEBUG" || n == "RELEASE" || n == "HOSTED" || n == "NOHEAP" || n == "SIMD128") return true;
    return n.compare(0, 3, "OS_")   == 0
        || n.compare(0, 5, "ARCH_") == 0
        || n.compare(0, 4, "ABI_")  == 0;
}

// Under strict mode (a `kama.json` manifest was loaded) every referenced flag must be a build-config
// name or declared in `flags`/`select` — a typo like `@compileFor(WINODWS)` is then rejected rather than
// silently dropping the decl.
//
// A FREE function, and `report` is a callback, because the rule has TWO callers with different
// diagnostic channels: the emitter's `unsupported()` for a declaration gate, and the driver's stderr for
// a FILE gate (`file @compileFor(FLAG);`), which is read before any emitter exists. One definition, so a
// file gate and a decl gate can never come to disagree about what `!FLAG` means.
// One literal of a gate: is `name` (negated when `neg`) satisfied by `active`? Validates the name under
// strict mode first. The single definition every gate goes through — a `@compileFor` attribute below, and
// a `csources`/`cincludes` entry's `compileFor` in the manifest (kama.driver.cpp) — so the two spellings of
// one gate can never come to disagree.
bool kamaGateLitActive(const std::string& name, bool neg,
                       const std::set<std::string>& active,
                       const std::set<std::string>& declared,
                       bool strict,
                       const std::function<void(const std::string&)>& report)
{
    if (strict && !kamaIsBuildConfigFlag(name) && !declared.count(name))
        report("`@compileFor` references undeclared flag `" + name +
               "` (add it to the `flags` object in kama.json)");
    return active.count(name) ? !neg : neg;
}

bool kamaCompileForActive(const SharedAttributeList& attrs,
                          const std::set<std::string>& active,
                          const std::set<std::string>& declared,
                          bool strict,
                          const std::function<void(const std::string&)>& report)
{
    if (!attrs) return true;
    for (auto& at : *attrs) {
        if (!at || !at->name || *at->name != "compileFor") continue;
        if (!at->args || at->args->empty()) {
            report("`@compileFor(...)` requires at least one flag name");
            continue;
        }
        for (auto& arg : *at->args) {
            if (!arg) continue;
            // bare `FLAG` — an identifier name with no value expression.
            if (arg->name && arg->name->value && !arg->expression) {
                if (!kamaGateLitActive(*arg->name->value, false, active, declared, strict, report)) return false;
                continue;
            }
            // negated `!FLAG` — a unary-not (EXCLAMATION) over an identifier (see kama.y attr_arg).
            if (arg->expression) {
                auto* su = dynamic_cast<SimpleUnaryExpressionNode*>(arg->expression.get());
                if (su && su->token == EXCLAMATION && su->expression) {
                    if (auto* id = dynamic_cast<IdentifierNode*>(su->expression.get()))
                        if (id->value) {
                            if (!kamaGateLitActive(*id->value, true, active, declared, strict, report)) return false;
                            continue;
                        }
                }
            }
            report("`@compileFor(...)` takes bare flag names or `!FLAG` (e.g. "
                   "`@compileFor(DEBUG)`, `@compileFor(!RELEASE)`)");
        }
    }
    return true;
}

bool CEmitter::compileForActive(const SharedAttributeList& attrs, int line)
{
    return kamaCompileForActive(attrs, _activeFlags, _declaredFlags, _strictFlags,
                                [&](const std::string& m) { unsupported(m.c_str(), line); });
}

// Drop every top-level decl whose `@compileFor` gate is inactive (as if never written), and strip
// the `@compileFor` attribute from each KEPT decl so no downstream pass (declAttrPrefix, the collect
// passes, emit) ever encounters it. This single seam runs before all collection, so nothing else
// needs per-pass gate guarding. v1 covers the top-level decl kinds that carry an `attributes` list;
// class members / `implements` blocks are a later stage.
void CEmitter::pruneInactiveDecls(SharedCompilationUnit unit)
{
    if (!unit || !unit->codeDeclarationList) return;

    // A unit already pruned by an EARLIER emitter (a cached unit reused across analyses) has nothing left
    // to drop, so this pass would record nothing — inherit what that pass dropped instead. Sound
    // because pruning is idempotent under a fixed build-flag set, and the parse cache is keyed by that
    // set (kama.driver.cpp, parseFile).
    _prunedNames.insert(unit->prunedNames.begin(), unit->prunedNames.end());

    // The `attributes` member lives on each concrete top-level decl kind; return a pointer so the
    // gate can be read and `@compileFor` stripped in place from a kept decl.
    // A pruned decl's NAME is remembered so the export-manifest check below can tell "dropped by this
    // build's flags" from "typo" — a module lists its full surface in one `export`, and gating a
    // declaration must not force the author to gate the export line too. Unqualified, so in principle a
    // name pruned in one module could suppress a genuine "no such declaration" in another; that only ever
    // loses a diagnostic, never accepts bad code, and qualifying is not possible here (pruning runs before
    // any namespace context is established).
    auto nameOf = [](ASTNode* d) -> std::string {
        if (auto* f = dynamic_cast<FunctionDeclarationNode*>(d))
            return (f->name && f->name->value) ? *f->name->value : std::string();
        if (auto* c = dynamic_cast<ClassDeclarationNode*>(d))
            return (c->name && c->name->value) ? *c->name->value : std::string();
        if (auto* e = dynamic_cast<EnumDeclarationNode*>(d))
            return (e->identifier && e->identifier->value) ? *e->identifier->value : std::string();
        if (auto* x = dynamic_cast<ExternConstNode*>(d))
            return (x->name && x->name->value) ? *x->name->value : std::string();
        return std::string();
    };

    auto attrsOf = [](ASTNode* d) -> SharedAttributeList* {
        if (auto* f = dynamic_cast<FunctionDeclarationNode*>(d))   return &f->attributes;
        if (auto* c = dynamic_cast<ClassDeclarationNode*>(d))      return &c->attributes;
        if (auto* e = dynamic_cast<EnumDeclarationNode*>(d))       return &e->attributes;
        if (auto* m = dynamic_cast<ModuleVariableDeclaration*>(d)) return &m->attributes;
        // `extern "<h>";` — an FFI include. Unlike every entry above it names no symbol, so `nameOf`
        // stays silent for one: there is nothing for the export-manifest check to reconcile. Dropping the
        // node here is the WHOLE mechanism — emitIncludes re-derives the `#include` set by walking this
        // very list, so a gated-out header emits no directive and contributes no driver link hint.
        if (auto* i = dynamic_cast<IncludeNode*>(d))               return &i->attributes;
        if (auto* x = dynamic_cast<ExternConstNode*>(d))           return &x->attributes;
        return nullptr;
    };

    StatementList kept;
    kept.reserve(unit->codeDeclarationList->size());
    for (auto& decl : *unit->codeDeclarationList) {
        SharedAttributeList* ap = decl ? attrsOf(decl.get()) : nullptr;
        if (!ap || !*ap) { kept.push_back(decl); continue; }
        // A gate that can never be active gates DEAD code — no configuration compiles it — so it is a
        // mistake, and it is one under every verb: the refusal lives here, where every gate passes.
        if (_gateContradiction) {
            std::string why = _gateContradiction(*ap);      // the whole sentence: the driver owns the groups
            if (!why.empty()) unsupported(why.c_str(), decl->line);
        }
        if (!compileForActive(*ap, decl->line)) {           // gate inactive -> decl never exists
            std::string n = nameOf(decl.get());
            if (!n.empty()) { _prunedNames.insert(n); unit->prunedNames.insert(n); }
            continue;
        }
        // KEEP: rebuild the attribute list without any `@compileFor` entry.
        SharedAttributeList filtered;
        for (auto& at : **ap) {
            if (at && at->name && *at->name == "compileFor") continue;
            if (!filtered) filtered = std::make_shared<AttributeList>();
            filtered->push_back(at);
        }
        *ap = filtered;   // null when `@compileFor` was the only attribute (declAttrPrefix tolerates null)
        // A BODYLESS declaration — `extern "<h>";`, `extern fn`, `fnptr` — accepts `@compileFor` and
        // nothing else, and this is the only pass that sees one: `declAttrPrefix` runs from the two
        // function EMITTERS, and none of these three reaches either (an extern emits no prototype at
        // all, a fnptr becomes a `_sigs` typedef). Without the check here a stray `@noheap extern "h";`
        // is accepted in silence. The rule is not a list of banned names but a property: `@interrupt`
        // and `@section` attach to EMITTED CODE, and a form with no body has none — so naming the
        // reason is more useful than naming the attribute.
        //
        // `@noheap` on a `fnptr` is THE exception, and it is the property talking rather than a special
        // case: `@noheap` does not attach to emitted code, it states a promise, and a `fnptr` is the one
        // bodyless form that declares a TYPE for something else's body to satisfy. The signature carries
        // the promise, every bind is checked against it (emitFnPtrBind / rejectFnPtrBindNoHeap), and a
        // call through the slot is then provable — which is what makes the fnptr gate in
        // rejectNoHeapIndirect a rule with an escape hatch rather than a dead end. It stays rejected on
        // an `extern fn` and an `extern "<h>";`, whose bodies are C and cannot be checked at all.
        if (filtered) {
            const char* what = nullptr;
            bool isFnPtr = false;
            if (dynamic_cast<IncludeNode*>(decl.get())) what = "`extern \"<header>\";`";
            else if (dynamic_cast<ExternConstNode*>(decl.get())) what = "an `extern const`";   // a symbol: `@linkName` fits
            else if (auto* f = dynamic_cast<FunctionDeclarationNode*>(decl.get()))
                if (!f->block) { isFnPtr = !isExtern(f); what = isFnPtr ? "a `fnptr`" : "an `extern fn`"; }
            for (auto& at : *filtered) {
                if (!at || !at->name) continue;
                if (*at->name == "linkName") {
                    // Names a SYMBOL, not a body, so the property above admits it on the one bodyless
                    // form that HAS one: an `extern fn`. A `fnptr` is a type and an `extern "<h>";` an
                    // include — neither is a symbol to rename. Validated at collection (`linkNameOf`);
                    // a bodied declaration is judged by `declAttrPrefix`.
                    if (!what || (!isFnPtr && !dynamic_cast<IncludeNode*>(decl.get()))) continue;
                    unsupported(("`@linkName` names the symbol of an `extern fn`, an `extern const` or an `expose fn`, and "
                                 + std::string(what) + " has no symbol to rename").c_str(), decl->line);
                    continue;
                }
                if (*at->name == "heap") {
                    // States that the C behind a symbol touches the heap — so it belongs on the one bodyless
                    // form that HAS a symbol and C behind it, and nowhere else (KR-47).
                    if (at->args && !at->args->empty())
                        unsupported("`@heap` takes no arguments", decl->line);
                    if (what && (isFnPtr || dynamic_cast<IncludeNode*>(decl.get())))
                        unsupported(("`@heap` marks an `extern fn` — it says C the compiler cannot read touches "
                                     "the heap — and " + std::string(what) + " has no C of its own").c_str(), decl->line);
                    continue;
                }
                if (isFnPtr && (*at->name == "noheap" || *at->name == "foreignEntry"
                                                      || *at->name == "callerThread")) {
                    // Same exception, same reason: none of the three attaches to emitted code, each
                    // states a promise, and a `fnptr` is the one bodyless form that declares a TYPE for
                    // somebody else's body to satisfy. `@foreignEntry`/`@callerThread` name the C API's
                    // threading contract (ROADMAP row 1) — the knowledge the compiler cannot derive,
                    // since `kama_run_loop` calls back on the caller's thread and a device callback does
                    // not, and neither signature says which.
                    if (at->args && !at->args->empty())
                        unsupported((std::string("`@") + *at->name + "` takes no arguments").c_str(), decl->line);
                    continue;
                }
                if (what)
                    unsupported((std::string("`@") + *at->name + "` needs a body to apply to, and "
                                 + what + " has none — `@compileFor(FLAG)` is the only attribute a "
                                 "declaration without a body accepts").c_str(), decl->line);
            }
        }
        kept.push_back(decl);
    }
    unit->codeDeclarationList->swap(kept);
}

// The kind a `_classes` entry implements AS, as a `for`-clause bit. 0 means "no `type <kind>` word
// produced this" — an intrinsic collection (INCLUDING `kama_string`, whose ClassInfo comes from the
// collection registrar and never gets a `kind`), a smart pointer. Those are not user-declared kinds and
// have nothing to gate; a primitive's conformances come from `type intrinsic` and are judged there,
// which is the only site that knows their origin and the only one with a line number for them.
static unsigned implementerKind(const ClassInfo& ci)
{
    // isBorrow BEFORE the Value test, and this ordering is the whole design: a `type view` is registered
    // as TypeKind::Value on purpose (collectClasses), because it genuinely copies like one and that
    // mapping governs the layout/copy/pass path. Only the conformance gate has to tell them apart, so
    // it keys on the flag and :4914 stays exactly as it is.
    if (ci.isBorrow)                   return IK_View;
    if (ci.isVariant || ci.isScalarEnum()) return IK_Enum;   // a `type enum` with members
    if (ci.kind == TypeKind::Value)    return IK_Value;
    if (ci.kind == TypeKind::Resource) return IK_Resource;
    return 0;
}

void CEmitter::collectProgram(const std::vector<SharedCompilationUnit>& userUnits)
{
    // the prelude (Optional/Result) is collected FIRST, in the global namespace (empty scope),
    // so its generic templates register under bare names resolvable unqualified from every file.
    std::vector<SharedCompilationUnit> units;
    if (_preludeUnit) units.push_back(_preludeUnit);
    // The namespaced built-in modules (the smart-ptr triad, std::memory) collect right after the prelude
    // and before user code. Unlike _preludeUnit they are NOT global: ctxOf reads their `namespace`/`export`
    // (below), so they register under `std__memory` and satisfy an explicit `import std::memory` — while an
    // implicit `using std::memory` (added in ctxOf) also makes their names resolve unqualified everywhere.
    for (auto& m : _preludeModuleUnits) if (m) units.push_back(m);
    for (auto& u : userUnits) units.push_back(u);

    // `@compileFor(FLAG)` conditional compilation: prune inactive top-level decls (and strip the gate
    // attribute from kept ones) BEFORE any name pre-registration or collection — so a dropped decl's
    // symbol never exists and no downstream pass needs to know the feature exists. Prelude/built-in
    // units carry no `@compileFor`, so pruning them is a harmless no-op.
    for (auto& u : units) pruneInactiveDecls(u);

    // Decl -> owning unit, needed DURING emission (M6 B3): a generic instance's body is emitted from the
    // header pass, and its use-sites belong to the TEMPLATE's unit, which only unitOfDecl can name. Must
    // come after pruning, which rewrites the decl lists in place. buildDefSites rebuilds this later anyway.
    //
    // ⚠️ In EVERY mode, not only analysis. It was analysis-only ("so a build pays nothing"), and the same map
    // is what names the file a generic body's reference is written in (`_refUnit`, `checkReach`) — so under
    // `kama build` every name inside a generic instance or an uncalled template went unjudged, and a private
    // `Optional<geo::HidErr>` in a generic body was refused by `kama check` and COMPILED by `kama build`.
    buildDeclUnits(userUnits);

    // Assign each file its namespace context (public module scope, or a `_F<file>` file-private one)
    // and register public namespaces, before any name resolution.
    std::map<std::string, std::string> privateScopeOwner;   // scope -> the unit that minted it
    for (size_t i = 0; i < units.size(); ++i) {
        if (!units[i]) continue;
        NsCtx ctx;
        if (units[i] == _preludeUnit) { ctx.isPublic = true; }   // empty scope = global (bare names)
        else                          ctx = ctxOf(units[i]);
        _unitCtx[units[i].get()] = ctx;
        if (ctx.isPublic && !ctx.scope.empty()) _namespaces.insert(ctx.scope);
        if (!ctx.scope.empty() && !ctx.module.empty()) _moduleNames[ctx.scope] = ctx.module;
        // A file-private scope is derived from the file's NAME (§2e.26), so two units can only share one by
        // sharing a name — and then their file-private symbols would collide in the emitted C, silently,
        // since neither is importable and nothing else would notice. Two files in one directory cannot have
        // the same name, but two module-less files reached from different directories can, and a name that
        // is not a legal C identifier folds (`my-prog` and `my_prog` both give `_Fmy_prog`).
        if (!ctx.isPublic && !ctx.scope.empty()) {
            auto claimed = privateScopeOwner.emplace(ctx.scope, ctx.unitPath);
            if (!claimed.second && claimed.first->second != ctx.unitPath)
                unsupported(("'" + claimed.first->second + "' and '" + ctx.unitPath + "' are both in no "
                             "module, and their names give them the same file-private scope — their "
                             "private symbols would collide in the emitted C. Rename one, or move it into "
                             "a subdirectory, which makes it a module").c_str(), 0);
            _privateScopes.insert(ctx.scope);
        }
        // The same rule one level down: a module file's PRIVATE scope is also derived from its name, and a
        // module may span subfolders (a folder with no manifest entry belongs to the module above it), so
        // `geo/a.kama` and `geo/impl/a.kama` would mint one private scope between them. Rare, and already
        // impossible in practice — their per-unit `.c` stems collide too — but refused by name here rather
        // than discovered as a C redefinition.
        if (!ctx.privScope.empty()) {
            auto claimed = privateScopeOwner.emplace(ctx.privScope, ctx.unitPath);
            if (!claimed.second && claimed.first->second != ctx.unitPath)
                unsupported(("'" + claimed.first->second + "' and '" + ctx.unitPath + "' are two files of "
                             "module `" + ctx.module + "` with the same name — their file-private symbols "
                             "would share one scope and collide in the emitted C. Rename one").c_str(), 0);
            _privateFileScopes[ctx.privScope] = ctx.scope;   // demangleForDisplay drops the file segment, keeps the module
        }
    }
    // Record each module's PUBLIC SURFACE from its top-of-file `export { … };` manifest. Everything
    // unlisted is module-private and cannot be pulled in by another module's per-symbol `import`
    // (enforced below). A listed name is validated against real declarations after collect.
    for (auto& u : units) {
        if (!u || u == _preludeUnit || !u->exportList) continue;
        _nsCtx = _unitCtx[u.get()];
        for (auto& name : *u->exportList) {
            if (!name) continue;
            // ⚠️ BEFORE `qualify`, which maps `main` to `kama_main` — an export list naming `main` was
            // accepted silently and then validated fine, because `kama_main` really is in `_funcs`. The
            // import side builds `m__main`, which is in no export set, so the only symptom was a consumer
            // being told the module "does not export `main`" when the module plainly listed it.
            if (*name == "main") {
                const size_t which = (size_t)(&name - &(*u->exportList)[0]);
                unsupported("`main` may not be exported — it is the program's entry point, not part of any "
                            "module's surface, and no importer could name it",
                            which < u->exportListPos.size() ? u->exportListPos[which].line : 0);
            }
            _exported.insert(qualify(*name));
        }
    }
    _exportedReady = true;   // the file rung can be answered from here on — see `checkReach`
    // Pre-register every type's mangled NAME so references resolve regardless of
    // file/declaration order (a class method param may reference a type declared
    // later, or in another file). The full collect below overwrites these.
    //
    // ...and it is the ONE place a duplicate type is visible: `collectClasses` writes `_classes[n] = ci`
    // over whatever is there, so two declarations of one key were a silent last-wins until 0.9.207 —
    // a's own `T` resolved to b's and was refused as "not exported by b.kama". A private name is keyed
    // by its file now, so what remains to collide is two declarations in one file, or two EXPORTED ones
    // in one module, and both are named here the way `collectSignatures` names a duplicate function.
    // `extern` structs are exempt for the reason externs always are: re-declared per file by design.
    std::map<std::string, std::string> firstTypeAt;   // key -> "file:line" of its first declaration
    auto claimType = [&](const std::string& n, const std::string& spelled, int line) {
        std::string here = _nsCtx.unitPath + ":" + std::to_string(line);
        auto it = firstTypeAt.emplace(n, here);
        if (!it.second)
            unsupported(("duplicate type '" + spelled + "' — a name may be declared only once in its module "
                         "(first declared at " + it.first->second + ")").c_str(), line);
    };
    for (auto& u : units) {
        if (!u || !u->codeDeclarationList) continue;
        _nsCtx = _unitCtx[u.get()];
        for (auto& decl : *u->codeDeclarationList) {
            ASTNode* d = decl.get();
            if (auto* cd = dynamic_cast<ClassDeclarationNode*>(d)) {
                if (cd->name && cd->name->value) {
                    // `type contract` pre-registers as an interface name, not a class. A GENERIC
                    // contract pre-registers in _genericContracts (like a generic type below), so an
                    // early `cType(Iterator<int32>)` (collectSignatures runs first) mangles to the
                    // instance name rather than resolving the bare template stub.
                    if (cd->typeKind && *cd->typeKind == "contract") {
                        std::string n = qualify(*cd->name->value);
                        claimType(n, *cd->name->value, cd->line);
                        if (cd->typeParams && !cd->typeParams->empty()) {
                            _genericContracts[n].name = n;
                            // Record params/defaults/ctx NOW (not just in collectInterfaces), so
                            // genericTypeMangle can fill a defaulted type-arg during the earlier
                            // collectSignatures pass — see the generic-TYPE note below.
                            std::vector<std::string> ps;
                            for (auto& p : *cd->typeParams) if (p) ps.push_back(*p);
                            _genericContractParams[n] = ps;
                            if (cd->typeDefaults) _genericContractDefaults[n] = *cd->typeDefaults;
                            _genericContractCtx[n] = _nsCtx;
                        } else _interfaces[n].name = n;
                    } else if (cd->typeParams && !cd->typeParams->empty()) {
                        // a generic TYPE template pre-registers in _genericTypes, NOT _classes
                        // (an empty _classes entry would be emitted as a bogus struct). collectClasses fills it.
                        std::string n = qualify(*cd->name->value); _genericTypes[n].name = n;
                        claimType(n, *cd->name->value, cd->line);
                        // Also record params/defaults/ctx here (ahead of collectClasses), so a DEFAULTED
                        // type-arg mangles to its filled instance name (`DynamicArray<int32>` ->
                        // `DynamicArray_int32_GlobalAllocator`) even in collectSignatures — which runs
                        // BEFORE collectClasses and BEFORE this template's own unit (the CLI/main unit is
                        // collected first, its imports appended after). Without this, a free function
                        // returning `DynamicArray<int32>` cached an unfilled `DynamicArray_int32` retCType
                        // that named no registered class (breaking e.g. `make().length()`). Idempotent —
                        // collectClasses re-records the same values.
                        std::vector<std::string> ps;
                        for (auto& p : *cd->typeParams) if (p) ps.push_back(*p);
                        _genericTypeParams[n] = ps;
                        if (cd->typeDefaults) _genericTypeDefaults[n] = *cd->typeDefaults;
                        _genericTypeCtx[n] = _nsCtx;
                    } else {
                        bool ext = false;
                        if (cd->modifiers) for (auto& mod : *cd->modifiers)
                            if (mod->value && *mod->value == "extern") ext = true;
                        std::string n = ext ? *cd->name->value : qualify(*cd->name->value);
                        if (!ext) claimType(n, *cd->name->value, cd->line);
                        _classes[n].name = n;
                        if (ext) { _classes[n].isExternStruct = true; _externNames.insert(n); }
                    }
                }
            } else if (auto* ed = dynamic_cast<EnumDeclarationNode*>(d)) {
                if (ed->identifier && ed->identifier->value) {
                    std::string n = qualify(*ed->identifier->value);
                    if (!enumHasModifier(ed, "extern")) claimType(n, *ed->identifier->value, ed->line);
                    // pre-register a tagged/generic enum where its real home is (a class-like
                    // type / a generic template), NOT _enums — else emitEnum would emit a bogus enum.
                    if (ed->typeParams && !ed->typeParams->empty()) {
                        _genericTypes[n].name = n;
                        // Record params/defaults/ctx now (like the generic-type branch above) so a
                        // defaulted enum type-arg mangles filled during collectSignatures.
                        std::vector<std::string> ps;
                        for (auto& p : *ed->typeParams) if (p) ps.push_back(*p);
                        _genericTypeParams[n] = ps;
                        if (ed->typeDefaults) _genericTypeDefaults[n] = *ed->typeDefaults;
                        _genericTypeCtx[n] = _nsCtx;
                    }
                    else if (enumIsTagged(ed))                      _classes[n].name = n;
                    else if (enumHasModifier(ed, "extern")) {       // a C enum's name is global and literal
                        const std::string& lit = *ed->identifier->value;
                        _enums[lit].name = lit;
                        _externNames.insert(lit);
                    }
                    else                                            _enums[n].name = n;
                }
            }
        }
    }
    // PERF: does the program use serde at all? A `@generate(Serializable|Deserializable)` type or a
    // `Serializer`/`Deserializer` BACKEND implementer (JsonWriter/JsonReader) is the ONLY way to serialize or
    // deserialize anything — you cannot even call a collection's `serialize` without a `Serializer` sink. When
    // NEITHER is present we emit NONE of the serde machinery: not the prelude's primitive Serializable/Deserializable
    // conformances, and not the conditional serde a collection would carry (the `when [T: Serializable]` bound is
    // treated as unsatisfied under `!_usesSerde` in whenConditionsHold, so `serialize`/`serKey`/… all drop).
    // Compile-time only (all of it is static-inline / dead-strippable). Computed HERE — before collectClasses,
    // so every downstream decision (collection specialization included) sees the final flag. Both signals are
    // TOP-LEVEL declarations, fully present in the AST now.
    auto attrHasSerde = [](auto& attrs) {
        if (attrs) for (auto& at : *attrs)
            if (at && at->name && *at->name == "generate" && at->args)
                for (auto& a : *at->args)
                    if (a && a->name && a->name->value && !a->expression &&
                        (*a->name->value == "Serializable" || *a->name->value == "Deserializable")) return true;
        return false;
    };
    for (auto& u : units) {
        if (_usesSerde || !u || !u->codeDeclarationList) break;
        for (auto& decl : *u->codeDeclarationList) {
            if (auto* cd = dynamic_cast<ClassDeclarationNode*>(decl.get())) {
                if (attrHasSerde(cd->attributes)) { _usesSerde = true; break; }
                if (cd->baseTypes && cd->baseTypes->interfaces)
                    for (auto& itf : *cd->baseTypes->interfaces)
                        if (itf && itf->value && (*itf->value == "Serializer" || *itf->value == "Deserializer")) _usesSerde = true;
            } else if (auto* ed = dynamic_cast<EnumDeclarationNode*>(decl.get())) {
                if (attrHasSerde(ed->attributes)) _usesSerde = true;
            } else if (auto* ii = dynamic_cast<IntrinsicImplNode*>(decl.get())) {
                SharedIdentifier c = intrinsicContract(ii);
                if (c && c->value && (*c->value == "Serializer" || *c->value == "Deserializer")) _usesSerde = true;
            }
            if (_usesSerde) break;
        }
    }

    for (auto& u : units) {
        if (!u || !u->codeDeclarationList) continue;
        _nsCtx = _unitCtx[u.get()];
        ScopedStr _cu(_collectingUnitPath, u->name ? *u->name : std::string());
        collectModuleVars(u);
    }
    foldModuleConsts();
    for (auto& u : units) {
        if (!u || !u->codeDeclarationList) continue;
        _nsCtx = _unitCtx[u.get()];
        // Every diagnostic these four raise is ABOUT a declaration in `u`, and in a multi-file build
        // `_sourcePath` is still "" here — so without this they report no file at all. See diagFile().
        ScopedStr _cu(_collectingUnitPath, u->name ? *u->name : std::string());
        collectSignatures(u);
        collectEnums(u);
        collectInterfaces(u);
        collectClasses(u);
    }
    linkBases();
    linkContracts();    // merge refined-parent methods into each contract before vtables are built
    // `type enum E implements C` — after linkContracts (completeness needs the merged contract methods),
    // before buildVtables, so an enum's conformance is in place when vtables are built.
    collectEnumConformances(units);
    checkDerivedPublicSurface();   // decision A: a derived type may not widen the public interface
    buildVtables();
    resolveFriends();   // after all classes/functions are registered
    // Pre-scan `type intrinsic` blocks into _intrinsicConformances (target primKey -> contracts) BEFORE
    // collectCollections. A `Map<string, V>` local drives a generic-type-arg bound check DURING collection,
    // which is earlier than the methods are injected; without this the check would falsely reject
    // `string: Hashable`. The real methods + coherence are still handled below.
    //
    // The contract is stored RESOLVED, under the declaring file's namespace — a bare name would conflate
    // two same-named contracts in different namespaces, so a bound on one would be satisfied by a
    // conformance to the other and the mistake would surface much later, as an unknown method inside the
    // callee's body. The bound check resolves its side the same way.
    for (auto& u : units) {
        if (!u || !u->codeDeclarationList) continue;
        _nsCtx = _unitCtx[u.get()];
        for (auto& decl : *u->codeDeclarationList) {
            auto* ii = dynamic_cast<IntrinsicImplNode*>(decl.get());
            if (ii && ii->targets) {
                SharedIdentifier c = intrinsicContract(ii);
                if (c && c->value) {
                    std::string contract = resolveUserName(*c->value, c->qualifier);
                    // ...and as the exact INSTANCE too (`Source<int64>`), which is what a bound with
                    // arguments asks for; the bare template stays for a bound written bare.
                    std::string exact = exactBoundName(contract, c, {});
                    for (auto& tgt : *ii->targets) {
                        _intrinsicConformances[primKey(tgt)].insert(contract);
                        _intrinsicConformances[primKey(tgt)].insert(exact);
                    }
                }
            }
        }
    }
    // Every module constant, then every enum member, BEFORE the first reader of a const-generic size below.
    // Both used to run after collectCollections and generic discovery, so a `comptime fn`-derived constant
    // could size nothing those passes registered: `InlineArray<isize>#(MAX_CREW)` with `MAX_CREW = crew()`
    // degraded to a raw pointer in ANY build. Enum members after the constants, which an initializer may read.
    // What both need is settled by here: every comptime fn, type constant, class and enum is collected.
    evalComptimeConsts();
    foldEnumMembers();
    // register collections BEFORE the destructibility fixpoint, so a class whose only
    // owning member is a collection field (`List<T>` etc., no explicit `~dtor`) is correctly seen
    // as a resource (destructible + move-only). computeDestructible then re-derives each
    // collection's elemDestructible from the final class destructibility.
    for (auto& u : units)
        if (u && u->codeDeclarationList) { _nsCtx = _unitCtx[u.get()]; collectCollections(u); }
    // `type intrinsic <…> implements C { … }` — inject each block's methods into every target's conformance
    // registry. Runs AFTER collectCollections so a collection target (`string` → `kama_string`) already has
    // its ClassInfo. Coherence lives in applyIntrinsicImpl: one claim per (type, contract), and no method
    // clobbering one the type already has.
    for (auto& u : units) {
        if (!u || !u->codeDeclarationList) continue;
        _nsCtx = _unitCtx[u.get()];
        // Which file is claiming these conformances — resolved to a package only if one turns out to be a
        // duplicate (see duplicateOriginNote).
        ScopedStr _cu(_collectingUnitPath, u->name ? *u->name : std::string());
        for (auto& decl : *u->codeDeclarationList)
            if (auto* ii = dynamic_cast<IntrinsicImplNode*>(decl.get())) applyIntrinsicImpl(ii);
    }
    // Every unit is collected by here, so whether the program HAS a `std::collections::View` is settled —
    // and generic-instantiation discovery is still AHEAD, which is the other half of the constraint:
    // `View<T>.swap` calls the generic `relocate`, and a View instance minted after registerInstGenerics
    // never gets the per-instantiation walk that resolves it (the symptom is an unresolved `relocate`
    // reported inside the stdlib's own view.kama).
    registerFixedViews();

    // discover generic-function instantiations after collections (a specialization may use
    // one) and before the destructibility fixpoint. Runs with _typeSubst empty (concrete mangles).
    for (auto& u : units)
        if (u && u->codeDeclarationList) { _nsCtx = _unitCtx[u.get()]; collectGenericInsts(u); }
    registerInstGenerics();   // the same walk over a generic TYPE's members, once per instantiation with
                              // _typeSubst bound — before registerInstColls, which reads _genericInsts.
    registerInstColls();   // MCU 6b-1: register const-param-derived collection sizes (`InlineArray<T,(N+1)>`)
                           // now that every instantiation is known — before the collection typedefs emit.
    registerFixedViews();  // ...and the same for any InlineArray this pass just minted. Idempotent (it skips
                           // one that already has `view`), so this only does work for a const-param-derived
                           // size whose ELEMENT type no other InlineArray in the program already used.
    refreshStaleParamTypes();  // a const-generic param mangled before its comptime constant was known
    registerOwnedDeserialize();   // the `Owned<X>` box read — BEFORE the fixpoint, which must see the
                                  // `Result<Owned<X>, Owned<Error>>` it mints to mark it move-only
    registerEdgeElementResults();  // …and the `Result<Shared<X>, …>` a container's element read binds
    bakeFieldCTypes();     // ...and resolve every field's type in its OWN class's scope, before any body
                           // walk can resolve it in a reader's. computeDestructible installs the same
                           // context immediately below; this is that answer, kept.
    checkExposeValues();   // KR-52 — reads baked field C types, so after bakeFieldCTypes like the next line
    mapCVisibleSigs();     // ...which is what lets this read a callback field's type: every `fnptr` a
                           // C-layout struct exposes, for the crossing check at each bind.
    computeDestructible();
    // A `type view` borrows and owns nothing, so it must not be destructible — a destructible view means
    // it has an owning/resource field (a `DynamicArray`, `Owned`/`Shared`, `string`, …) that its (absent)
    // dtor would have to free. Reject with guidance toward a raw `UnsafePtr<T>` (a non-owning field). Runs after
    // the fixpoint so a transitively-owning field is caught. (A view in an enum PAYLOAD is caught earlier,
    // at registerGenericTypeInst, where the payload type is substituted concrete.)
    for (auto& kv : _classes) {
        ClassInfo& ci = kv.second;
        if (ci.isBorrow && ci.destructible) {
            ScopedStr _cu(_collectingUnitPath, ci.declFile);   // whole-program pass: see diagFile()
            unsupported(("a `view` (`" + ci.name + "`) borrows and owns nothing — it may not have an owning "
                         "or resource field (hold a non-owning `UnsafePtr<T>` instead)").c_str(),
                        ci.declLine());
        }
    }
    computeReachesPointer();   // serialization mode gate (by-value vs. graph)
    computeDeeplyImmutable();     // M6.2: mark deeply-immutable types (feeds the sendability seed below)
    computeAtomicRefcount();      // M6.2: a `Shared`/`Weak` over a deeply-immutable T takes the atomic flavor
    computeGraphNodeTypes();   // graph node closure + Shared<T> deserialize return types (Phase D)
    pruneOwnedDeserialize();   // …now that a boxed VALUE can be told from a boxed graph NODE
    planGraphTwins();          // …and who carries the graph through a hand-written serde body

    // Contract kind-gate enforcement: a type may `implements` a contract only if its kind is named by
    // that contract's `for` clause. Covers the kinds that own a `_classes` entry.
    for (auto& kv : _classes) {
        ClassInfo& ci = kv.second;
        unsigned k = implementerKind(ci);
        if (!k) continue;
        // A whole-program check has no unit context of its own, so borrow the one collection recorded —
        // otherwise every rejection here reports an empty file in a multi-file build. See diagFile().
        ScopedStr _cu(_collectingUnitPath, ci.declFile);
        const std::string kw  = kamaImplKindListText(k);
        const std::string art = (k == IK_Enum || k == IK_Intrinsic) ? "an " : "a ";
        for (auto& base : ci.interfaces) {
            unsigned allowed = implKindsOf(base);
            if (!allowed || (allowed & k)) continue;   // 0 = a base class, unresolved, or already diagnosed
            // Name the TEMPLATE, not the mangled instance (`Windowed`, not `Windowed_F<file>_Span`): it is
            // what the author wrote and it is stable across instantiations. checkViewContractCtors made
            // the same call for the same reason.
            auto bi = _interfaces.find(base);
            const std::string& shown = (bi != _interfaces.end() && !bi->second.templateKey.empty())
                                       ? bi->second.templateKey : base;
            unsupported(("`" + kv.first + "` is " + art + "`" + kw + "`, but contract `" + shown
                         + "` is declared `for " + kamaImplKindListText(allowed) + "` — " + art
                         + kw + " can't implement it").c_str(), ci.declLine());
        }
        // A contract that REQUIRES `Sendable` (`type contract Job implements Sendable`) is satisfied only
        // by a type that declares it too — the declaration is then verified like any other. Asked here,
        // beside the kind gate, because it is the same question: may this type implement that contract.
        for (auto& base : ci.interfaces) {
            if (!contractRequiresSendable(base)) continue;
            bool declares = false;
            for (auto& itf : ci.interfaces) if (itf == _sendableContract) { declares = true; break; }
            if (declares) continue;
            auto bi = _interfaces.find(base);
            const std::string& shown = (bi != _interfaces.end() && !bi->second.templateKey.empty())
                                       ? bi->second.templateKey : base;
            unsupported(("`" + kv.first + "` implements `" + shown + "`, which requires `Sendable` of every "
                         "implementor (`type contract " + shown + " implements Sendable`), but does not "
                         "declare `implements Sendable`").c_str(), ci.declLine());
            break;
        }
    }

    // …and the signatures it promised. After the kind gate for the same reason: a type that may not
    // implement the contract at all should hear THAT, not a list of its members' disagreements.
    checkConformanceSignatures();
#if KAMA_INHERITANCE
    checkOverrideSignatures();
#endif

    // A `view` may not promise a contract that requires it to be CONSTRUCTED out of nothing borrowable.
    // After the kind gate, so a view failing a `for resource` clause hears that first — it is the more
    // fundamental problem, and the two would otherwise both fire on one declaration.
    checkViewContractCtors();
    checkViewableContracts();
    checkViewRefParams();

    // Validate export manifests: a name in `export { … };` must be a real top-level declaration in
    // that same file (catches typos + enforces per-file surfaces for directory-modules).
    for (auto& u : units) {
        if (!u || u == _preludeUnit || !u->exportList) continue;
        _nsCtx = _unitCtx[u.get()];
        ScopedStr _cu(_collectingUnitPath, u->name ? *u->name : std::string());   // see diagFile()
        for (auto& name : *u->exportList) {
            if (!name) continue;
            std::string q = qualify(*name);
            bool exists = _classes.count(q) || _enums.count(q) || _interfaces.count(q) || _funcs.count(q)
                       || _genericTypes.count(q) || _genericContracts.count(q) || _sigs.count(q)
                       || _constStatics.count(q);   // a module `comptime` — SPEC: "subject to the module
                                                    // `export { }` surface". It is a named constant, so it
                                                    // publishes like a function; see emitHeaderContent.
            // An extern this file declares is exported under its literal key, recorded per exporting FILE
            // (many files may declare one C symbol; only the ones that export it offer it).
            if (!exists) {
                auto ds = _externDeclSites.find(*name);
                if (ds != _externDeclSites.end() && ds->second.count(_nsCtx.unitPath)) {
                    exists = true;
                    _externExportedBy[*name].insert(_nsCtx.unitPath);
                }
            }
            // A MUTABLE module `static` is a different answer, and it deserves its own sentence rather
            // than the phantom "there is no such top-level declaration" — the declaration is right there.
            if (!exists && _moduleStatics.count(q)) {
                size_t which = (size_t)(&name - &(*u->exportList)[0]);
                unsupported(("a module `static` is not exportable — `" + *name + "` has internal C linkage "
                             "and per-isolate storage, so no other file can name it. Make it `comptime` if "
                             "it is a constant, or expose it through a function").c_str(),
                            which < u->exportListPos.size() ? u->exportListPos[which].line : 0);
                continue;
            }
            if (!exists && !_prunedNames.count(*name)) {
                // The location used to be the `namespace` declaration's line, which is gone. The export
                // list's own span is the better answer anyway: it points at the block being validated.
                size_t which = (size_t)(&name - &(*u->exportList)[0]);
                unsupported(("export list names `" + *name + "` but there is no such top-level declaration in this module").c_str(),
                            which < u->exportListPos.size() ? u->exportListPos[which].line : 0);
            }
        }
    }

    // Enforce the file rung at the IMPORT: a per-symbol `import a::b::{X}` may bind only an `export`ed X
    // (an unmarked or missing symbol is not importable — "does not export"). The same-module form
    // `import { X };` is checked here too, against this file's own scope — a sibling's `export` is an
    // offer and the import is the acceptance, so importing what a sibling kept private is the same
    // mistake spelled a shorter way.
    for (auto& u : units) {
        if (!u || !u->importDeclarationList) continue;
        ScopedStr _cu(_collectingUnitPath, u->name ? *u->name : std::string());   // see diagFile()
        for (auto& imp : *u->importDeclarationList) {
            if (!imp || !imp->symbols || !imp->modulePath) continue;
            std::string path;
            for (auto& s : *imp->modulePath) path += (path.empty() ? "" : ".") + *s;
            const bool sameModule = imp->modulePath->empty();
            _nsCtx = _unitCtx[u.get()];
            std::string mod = sameModule ? _nsCtx.scope : mangleNs(path);
            // §2c AT THE IMPORT. `visibility` governs reach BEYOND a module; the file rung below has its
            // own say. A same-module entry is always allowed — a module's own files see each other
            // unconditionally, which is what "its own files" means in all four forms.
            //
            // ⚠️ THIS CANNOT LIVE IN `ctxOf`. The driver's module-name index is filled as each unit is
            // ATTRIBUTED, which happens through the resolver callback `ctxOf` itself makes — so asking
            // there consults a half-built index and the answer depends on which unit came first. It read
            // as "internal is enforced, a list is not"; both were really coin-flips on unit order.
            if (!sameModule && _moduleVisible) {
                std::string target;                        // the entry's module, unmangled
                for (auto& sg : *imp->modulePath) target += (target.empty() ? "" : "::") + *sg;
                if (!_moduleVisible(_nsCtx.module, target))
                    unsupported(("module `" + target + "` is not visible from "
                                 + (_nsCtx.module.empty() ? std::string("a file in no module")
                                                          : "`" + _nsCtx.module + "`")
                                 + " — its `visibility` in `kama.json` does not name this module. Widen it, "
                                   "or import from a module it does name").c_str(), imp->line);
            }
            // M6 B3g: an `import`'s symbol list NAMES the things it imports, so renaming one of them has
            // to rewrite the import too — otherwise the rename leaves a module importing a symbol that no
            // longer exists, which is the B3a failure again, across files. `_refUnit` is null throughout
            // collectProgram, so point it at the importing unit for this loop.
            RefUnitScope refScope(this, u.get());
            for (auto& sym : *imp->symbols) {
                if (!sym || !sym->identifier || !sym->identifier->value) continue;
                // A name this build DROPPED is not a typo, and it is still in the module's export list, so
                // the plain "does not export" check below would wave it through and leave the reader with a
                // bare "call to unknown function" at the use site. Name the real reason instead.
                const std::string q = mod + "__" + *sym->identifier->value;
                auto anyTable = [&](const std::string& k) {
                    return _funcs.count(k) || _classes.count(k) || _enums.count(k) || _interfaces.count(k)
                        || _genericTypes.count(k) || _genericContracts.count(k) || _sigs.count(k)
                        || _constStatics.count(k);   // a module `comptime` is importable by name
                };
                // `live` under the MODULE key, or under some sibling file's PRIVATE key: a name declared
                // in this module and never exported now lives under its file's scope, and case 2 below
                // must still find it to say so.
                bool live = anyTable(q) || (sameModule && !siblingPrivateKey(*sym->identifier->value, anyTable).empty());
                if (externExportedFrom(*sym->identifier->value, mod)) {   // an exported extern: literal key
                    recordRef(*sym->identifier->value, sym->identifier.get());
                    continue;
                }
                if (!live && _prunedNames.count(*sym->identifier->value))
                    unsupported(("`" + *sym->identifier->value + "` is not available in this build configuration"
                                 " — a `@compileFor` gate on its declaration excludes it").c_str(), imp->line);
                else if (!_exported.count(q)) {
                    const std::string& n = *sym->identifier->value;
                    // ONE TEST, THREE MISTAKES. `!_exported.count(q)` is a single negative set lookup, and
                    // three unrelated situations fail it. Saying "no file in this module exports X" for all
                    // three blamed a rule that had not fired — the exact shape the module campaign existed
                    // to remove, which survived it. Both discriminators were already computed and in scope.
                    //
                    // 1. THE LOOSE ROOT, where the sentence is FLATLY FALSE. A file the build was handed in
                    //    its own root belongs to no module, so it gets a file-private `_F<file>` scope: the
                    //    sibling's `export { X };` is recorded as `_Fb__X` while this file asks for
                    //    `_Fmain__X`, and no pair of files in a loose root can ever match. The sibling
                    //    demonstrably DOES export it — moving either file one directory down makes the
                    //    identical import succeed — so the export list is the one thing that is not wrong.
                    if (sameModule && _nsCtx.module.empty()) {
                        std::string owner;   // the file that exports it, if some loose sibling does
                        for (auto& kv : _unitCtx)
                            if (_exported.count(kv.second.scope + "__" + n)) { owner = kv.second.unitPath; break; }
                        unsupported((owner.empty()
                                     ? "`" + n + "` cannot be imported: this file sits in the build's own "
                                       "ROOT, which is not a module — a loose root's symbols are file-private "
                                       "and it has no siblings to import from. Move these files into a "
                                       "directory, or give the project a `kama.json`"
                                     : "`" + n + "` IS exported by `" + owner + "`, but neither file is in a "
                                       "module: a file in the build's own ROOT keeps its symbols file-private, "
                                       "so there is nothing to import FROM. Move both files into a directory, "
                                       "or give the project a `kama.json` — the `export` is already right")
                                        .c_str(), imp->line);
                    }
                    // 2. IT IS HERE AND PRIVATE — the only case the old wording was right about. `live` says
                    //    a declaration of that name exists under this module's scope; it just never left its
                    //    file. This is the offer/acceptance rule doing its job.
                    else if (sameModule && live)
                        unsupported(("`" + n + "` is declared in this module but no file `export`s it — "
                                     "visibility is per file, so the sibling that declares it must say "
                                     "`export { " + n + " };` before this file can import it").c_str(), imp->line);
                    // 3. IT WAS NEVER LOADED. Nothing of that name is in the compilation at all, so an
                    //    `export` list is the wrong thing to go and edit: either the name is misspelled, or
                    //    the file that declares it was never handed to the build. §2i — a loose build
                    //    compiles its operands and does not go looking on disk — makes the second common.
                    else if (sameModule)
                        unsupported(("nothing named `" + n + "` was loaded — no file of this module declares "
                                     "it. Check the spelling; and if a sibling declares it, pass that file "
                                     "too, because a loose build compiles only the files it is given").c_str(),
                                    imp->line);
                    else
                        unsupported(("module `" + path + "` does not export `" + n + "`").c_str(), imp->line);
                }
                // The module-qualified name the export check just built IS the resolved key the symbol's
                // def-site is registered under; an alias (`X as Y`) still refers to X, which is what
                // `identifier` holds.
                recordRef(mod + "__" + *sym->identifier->value, sym->identifier.get());
            }
        }
    }

    // Every DECLARED type name resolves (params / returns / fields / variant payloads). Must be LAST: the
    // check consults `_sigs`, which `collectSignatures` fills in FILE order, so a parameter typed by a
    // `sig` declared in a later file is not yet registered mid-collect; enum conformance collection has
    // finished giving enums their member ClassInfos; and `pruneInactiveDecls` has already rewritten the decl
    // lists, so `@compileFor`-dropped declarations are simply absent here rather than needing a guard.
    // Running inside `collectProgram` (rather than at emit) is also what makes `kama build`, `kama check`
    // and the language server agree — all three take this path, which is the whole point of the check.
    checkDeclaredTypes(units);
}

// All DECLARATIONS (the shared header): typedefs, enums, struct/vtable types,
// interface types, collection/smart-pointer macros, and every prototype.
void CEmitter::emitHeaderContent(const std::vector<SharedCompilationUnit>& units)
{
    std::vector<ClassInfo*> classes = topoOrderClasses();       // base before derived (no generic instances)
    std::vector<ClassInfo*> ordered = unifiedStructOrder();     // all struct bodies, by-value-dep order

    // Forward typedefs so bodies can reference each other and any struct (incl. generic instances).
    for (ClassInfo* ci : ordered) {
        if (ci->isExternStruct) continue;
        if (ci->isIntrinsicColl) {
            // A `Fixed<T,N>` gets its full `KAMA_FIXED_TYPE` later (by-value struct order); forward-
            // declare it HERE so a pointer-storing collection (`List<Fixed<...>>`, emitted in the early
            // types pass) can name it. The later full typedef is a legal C11 redeclaration. Other
            // collections already emit a full `_TYPE` typedef in that early pass.
            if (ci->collKind == CollKind::Fixed)
                *_out << "typedef struct " << ci->name << " " << ci->name << ";\n";
            continue;
        }
        *_out << "typedef struct " << ci->name << " " << ci->name << ";\n";
#if KAMA_INHERITANCE
        if (ci->hasVtable && ci->vtableRoot == ci->name)
            *_out << "typedef struct " << ci->name << "_vtable " << ci->name << "_vtable;\n";
#endif
    }
    for (auto& kv : _interfaces) {
        if (kv.second.isViewable) continue;   // a mint protocol has no C type at all — see emitInterfaceTypes
        *_out << "typedef struct " << kv.first << "_vtbl " << kv.first << "_vtbl;\n";
        *_out << "typedef struct " << kv.first << " " << kv.first << ";\n";
    }
    if (!ordered.empty() || !_interfaces.empty()) *_out << "\n";

    // Function-pointer signature typedefs: `typedef ret (*Name)(params);`.
    // After the class forward-typedefs so a signature may take/return a class.
    for (auto& kv : _sigs) {
        SigInfo& si = kv.second;
        *_out << "typedef " << si.retCType << " (*" << si.cName << ")(";
        if (si.params.empty()) *_out << "void";
        for (size_t i = 0; i < si.params.size(); ++i) {
            const ParamSig& p = si.params[i];
            // const pointer params -> `const T*` (FFI). className already ends
            // in `*` for an UnsafePtr<T>/UnsafePtr; a const-ref class param keeps its self mutable.
            bool constPtr = p.isConst && !p.className.empty() && p.className.back() == '*' && !isConstRawCType(p.className);
            bool hwPtr    = p.isHardware && !p.className.empty() && p.className.back() == '*';
            *_out << (i ? ", " : "") << (constPtr ? "const " : "") << (hwPtr ? "volatile " : "") << p.className << (p.byRef ? "*" : "");
        }
        *_out << ");\n";
    }
    if (!_sigs.empty()) *_out << "\n";

    // Set the name-resolution scope from the type/file being emitted. `aliases` carries the
    // declaring file's per-symbol imports (a field/base typed with an imported generic needs them).
    auto scopeOf = [&](const std::string& declFile, const std::string& scope, const std::vector<std::string>& usings,
                       const std::map<std::string, std::string>& aliases = std::map<std::string, std::string>()) {
        _nsCtx = NsCtx{}; _nsCtx.scope = scope; _nsCtx.usings = usings; _nsCtx.symbolAliases = aliases;
        restoreFileRung(_nsCtx, declFile);   // the file rung too — or a private type's prototype resolves `This` to a sibling's
    };

    for (auto& kv : _enums) { scopeOf(kv.second.declFile, kv.second.scope, kv.second.usings); emitEnum(kv.second); }

    // Collection/smart-pointer STRUCT typedefs (the `_TYPE` half) — before class struct
    // bodies, so a class may hold a collection/smart-pointer BY VALUE as a field. They
    // store only `T*`, so the element being forward-declared (above) is enough.
    emitCollectionDefs(/*typesOnly=*/true);

    // struct bodies (normal classes + generic instances + tagged unions) in ONE by-value-
    // dependency order — so any struct may hold another user struct BY VALUE (`Box<Rock>`, a union
    // carrying a `Vec2`, a class holding a class). A generic instance routes through emitGenericTypeInst
    // (which binds its _typeSubst/_nsCtx for its `T`-typed fields); a normal class/variant through
    // emitStruct. The emission ORDER places every by-value dependency before its holder.
    for (ClassInfo* ci : ordered) {
        if (ci->isExternStruct) continue;
        if (ci->isIntrinsicColl) {
            // A `Fixed<T,N>` embeds its element BY VALUE, so — unlike the pointer-storing collections
            // (whose `_TYPE` went out above) — its struct typedef must land HERE, after the element's
            // struct body (this loop is the by-value-dependency order). Other collections are skipped.
            if (ci->collKind == CollKind::Fixed) {
                CollectionInfo& info = _collections[ci->name];
                *_out << "KAMA_FIXED_TYPE(" << info.elemCType << ", " << info.constValue
                     << ", " << info.cName << ")\n";
            } else if (_collections.count(ci->name) && isIfaceAllocColl(_collections[ci->name])) {
                emitIfaceAllocType(_collections[ci->name]);   // fat handle embeds `A` by value (after A's struct)
            }
            continue;   // macro / header provides it
        }
        if (ci->isGenericInst) {
            emitGenericTypeInst(_genericTypeInsts[ci->name], /*phase=*/0);   // body-only (forward split out)
        } else {
            scopeOf(ci->declFile, ci->scope, ci->usings, ci->symbolAliases);
#if KAMA_INHERITANCE
            if (ci->hasVtable && ci->vtableRoot == ci->name) emitVtableType(*ci);
#endif

            emitStruct(*ci);   // dispatches to emitVariantStruct for a union
        }
    }
    for (auto& kv : _interfaces) { scopeOf(kv.second.declFile, kv.second.scope, kv.second.usings, kv.second.symbolAliases); emitInterfaceTypes(kv.second); }
    emitExternLayoutChecks();   // after every body: a field may hold an `InlineArray` or a kama value by value

    // Forward-declare each class-interface vtable (`C__as_I`) — the definitions have external linkage (see
    // emitClassInterfaceVtables) so binding a concrete to a contract works across module boundaries.
    for (ClassInfo* ci : classes) {
        if (ci->isIntrinsicColl || ci->isExternStruct) continue;
        if (ci->isGenericInst) continue;   // a generic instance's vtables are emitted `static` inline (below), no extern decl
        if (_preludeEnums.count(ci->name)) continue;   // a prelude enum's vtbl is header-static (emitted below), no extern
        for (auto& ifn : contractsToEmitFor(*ci)) {
            bool staticOnly = contractIsStaticOnlyFor(*ci, ifn);
            if (staticOnly && !isPolyDispatchContract(ifn)) continue;   // Model C: enum→poly-dispatch vtbl HAS a def
            auto it = _interfaces.find(ifn);
            if (it == _interfaces.end()) continue;
            if (it->second.isViewable) continue;   // a mint protocol has no vtbl TYPE, so this decl would not compile
            *_out << "extern const " << it->second.name << "_vtbl " << ci->name << "__as_" << it->second.name << ";\n";
        }
    }

#if KAMA_INHERITANCE
    // Forward-declare each CLASS vtable instance, for the same reason as the `C__as_I` block above and
    // one order-of-emission step further: a generic collection's `_FUNCS` body (emitted just below, from
    // `emitCollectionDefs`) stores `&C__vtable` when it moves a polymorphic element BY VALUE — but the
    // instance itself is defined per-module by emitVtableInstance, i.e. AFTER this header. The instance
    // therefore carries external linkage (one definition, in its home module) and is declared here.
    // Without this, `DynamicArray<SomeVirtualResource>` fails at the C level with "use of undeclared
    // identifier 'C__vtable'" — the inheritance x generics seam (docs/design/inheritance.md, hole 4).
    for (ClassInfo* ci : classes) {
        if (ci->isIntrinsicColl || ci->isExternStruct || ci->isGenericInst) continue;
        if (!ci->hasVtable || !_rootVtables.count(ci->vtableRoot)) continue;   // mirrors emitVtableInstance
        *_out << "extern const " << ci->vtableRoot << "_vtable " << ci->name << "__vtable;\n";
    }
#endif

    // Element destructor prototypes the collection/smart-pointer macros call, then the
    // macros themselves, then class prototypes — so a method (or any class member)
    // can pass a collection/smart-pointer wrapper BY VALUE in its signature, the wrapper
    // type being complete by then. The dtor protos are re-declared (identically, harmless)
    // by emitClassPrototypes. Free-function prototypes follow (they may use a wrapper too).
    for (ClassInfo* ci : classes)
        if (!ci->isIntrinsicColl && !ci->isExternStruct && ci->destructible)
            // A prelude type's dtor is defined `static inline` at the end pass, so its early proto must match
            // (else "static declaration follows non-static") — same reasoning as the preludeStatic branch below.
            *_out << (ci->preludeStatic ? "static inline " : "") << "void " << ci->name << "__dtor(" << ci->name << "* self);\n";
    // a collection of `Copyable` elements deep-copies via the element's `copy()`, so its
    // prototype must precede the `_FUNCS` macro that calls it (re-declared identically by
    // emitClassPrototypes). The C signature is `Elem Elem__copy(Elem* self)` (nullary; paramListC).
    for (ClassInfo* ci : classes)
        if (!ci->isIntrinsicColl && !ci->isExternStruct && ci->copyable)
            *_out << ci->name << " " << ci->name << "__copy(" << ci->name << "* self);\n";
    emitCollectionDefs(/*typesOnly=*/false);   // the `_FUNCS` half (ctor/dtor/methods)
    for (ClassInfo* ci : classes) {
        if (ci->preludeStatic) {
            // A non-generic prelude type's BODIES are emitted static-inline at the very end (below), but its
            // PROTOTYPES must come out here — a generic container monomorph emitted before that end pass may
            // call them (e.g. `DynamicArray<T, GlobalAllocator>` calling `GlobalAllocator__allocate`). Emit
            // them `static` so the later static-inline definitions don't follow a non-static implicit decl.
            scopeOf(ci->declFile, ci->scope, ci->usings, ci->symbolAliases);
            _emitStaticClass = true; emitClassPrototypes(*ci); _emitStaticClass = false;
            continue;
        }
        scopeOf(ci->declFile, ci->scope, ci->usings, ci->symbolAliases); emitClassPrototypes(*ci);
    }
    // Allocator-aware INTERFACE smart-ptr FUNCS (M11d): deferred to HERE so the `A__deallocate` the dtor calls
    // is already prototyped (above). Registration order (inner-first) so a Weak partner's Shared is complete.
    for (const std::string& cName : _collectionOrder)
        if (_collections.count(cName) && isIfaceAllocColl(_collections[cName]))
            emitIfaceAllocFuncs(_collections[cName]);
    emitPolyContractResolvers();   // Phase E: per-contract graph-edge dispatch (after node-helper protos + extern vtbl decls)
    // The discard sink and the per-edge helpers, in the shared header beside the resolvers: a twin's body
    // may live in any unit and both are called from it, so they must be visible everywhere the twin is.
    emitNullSerializer();
    emitGraphEdgeHelpers();
    // `type intrinsic` impl methods for a COLLECTION/primitive target (`string` → `kama_string`):
    // the normal per-class emitters early-out for a collection, so emit a non-static PROTOTYPE here — BEFORE
    // the generic-function instances below, which may call it (e.g. a `<K: Hashable>` body calling
    // `k.hash()` monomorphized for `string`). The body lands once in the impl's module `.c`
    // (emitModuleContent). A USER-type target emits through the normal machinery (skipped here).
    // User-unit impl blocks: non-static prototype here; body lands in that unit's `.c` (below). The PRELUDE's
    // blocks (collect-only, no home module) are emitted `static inline` in a dedicated pass just after.
    // Skip an ungated serde block: the prelude's primitive `Serializable`/`Deserializable` conformances are
    // emitted only when `_usesSerde` (see the collect-time gate). All other blocks always emit.
    auto emitImplProtos = [&](const std::vector<SharedCompilationUnit>& us, const char* stat) {
        for (auto& u : us) {
            if (!u || !u->codeDeclarationList) continue;
            _nsCtx = _unitCtx[u.get()];
            for (auto& e : implEmitsOf(u)) {
                ScopedStr _ts(_thisType, e.target->name);
                for (auto& m : *e.members) {
                    auto* md = dynamic_cast<ClassMethodDeclarationNode*>(m.get());
                    if (!md || !md->name || !md->name->value) continue;
                    std::string ret = cType(md->returnType) + placeRetSuffix(md->isRef, md->isConstRef);
                    // a `static` impl method (or a `ctor` — always static) has no implicit `self` receiver
                    const char* recv = (modHas(md->modifiers, "static") || md->isCtor) ? nullptr
                                                                                       : e.target->name.c_str();
                    *_out << stat << ret << " " << implMethodCName(*e.target, *md->name->value) << "("
                          << paramListC(md->params, recv, nullptr, e.target->isScalarRecv) << ");\n";
                }
            }
        }
    };
    emitImplProtos(units, "");                                     // user units (`units` excludes the prelude)
    if (_preludeUnit) emitImplProtos({_preludeUnit}, "static inline ");

    // Everything below can emit a kama BODY, and a body may bind a primitive or a `string` to a contract,
    // naming a vtbl that is defined only on demand (intrinsicContractVtbl). Buffer the region so those
    // vtbls are written AHEAD of it — after the impl prototypes just above, which is all their slots need.
    std::ostringstream headerBodies;
    std::ostream* headerOut = _out; _out = &headerBodies;
    // specialized generic-type instance prototypes (ctor/dtor/method), `static`.
    for (const std::string& m : _genericTypeInstOrder)
        emitGenericTypeInst(_genericTypeInsts[m], /*phase=*/1);
    // Prototypes for kama's OWN free functions. kama never emits prototypes for
    // `extern` C functions: an `extern` decl is purely kama's call signature
    // (name + named params, for lowering) — the C prototype comes from the header
    // you `extern "<…>";` (or one the runtime already includes). This keeps the
    // FFI rule a single explicit sentence and makes redeclaration conflicts
    // impossible (kama can't always spell a C type exactly, e.g. const char*).
    bool any = false;
    for (auto& u : units) {
        if (!u || !u->codeDeclarationList) continue;
        if (u == _preludeUnit) continue;   // global-prelude free fns are header-static-inline (emitted just below)
        _nsCtx = _unitCtx[u.get()];
        for (auto& decl : *u->codeDeclarationList)
            if (auto* fn = dynamic_cast<FunctionDeclarationNode*>(decl.get())) {
                if (isExtern(fn) || !fn->block || fn->isComptime) continue;   // skip extern + signature types + comptime-only fns
                if (fn->typeParams && !fn->typeParams->empty()) continue;   // template — instantiated below
                emitFunctionPrototype(fn);
                any = true;
            }
    }
    if (any) *_out << "\n";

    // Module-scope `comptime` constants, DEFINED here rather than in the declaring unit's body.
    //
    // ⚠️ This is what makes a module constant reachable at all beyond its own file. A build emits one C
    // translation unit per module, and a `comptime` lowers to `static const` — so defining it in the
    // declaring unit's `.c` left every other TU with nothing, and a perfectly ordinary sibling-file
    // reference failed as a clang "use of undeclared identifier". `kama check` saw none of it (it folds to
    // one unit), so the corpus could not catch it either. A function does not have this problem because
    // it is prototyped here — that is the shape being matched.
    //
    // `static const` in a header gives every TU its own copy, which is exactly right for an immutable
    // compile-time value: it stays addressable (SPEC promises `@section`-placeable storage) and there is
    // no one-definition rule to violate. A MUTABLE `static` must not be COPIED — per-TU copies of mutable
    // state would be a silent correctness bug, not a fix — so it is DECLARED here (`extern`, the
    // function-prototype shape exactly) and defined once, in its unit, and it is still rejected at the
    // export list. The declaration is what a GENERIC type's bodies need: they are emitted `static inline`
    // in this header, before every unit, so a generic dtor counting into a module static was a clang
    // "use of undeclared identifier" while its non-generic twin built — see emitModuleStaticDecl.
    // Only an EXPORTED constant comes here. A constant its own file keeps private is reachable from
    // nowhere else (the file rung sees to that), so it stays in its unit — which matters for a
    // `comptime fn` table: a 256-byte `.rodata` aggregate has no business being copied into every
    // translation unit of an MCU build to serve one file.
    bool anyConst = false;
    for (auto& u : units) {
        if (!u || !u->codeDeclarationList || u == _preludeUnit) continue;
        _nsCtx = _unitCtx[u.get()];
        ScopedStr _edf(_emitDeclFile, u->name ? *u->name : std::string());   // diagnostics land on the DECLARING file
        for (auto& decl : *u->codeDeclarationList)
            if (auto* mv = dynamic_cast<ModuleVariableDeclaration*>(decl.get())) {
                if (mv->isComptime && moduleVarExported(mv)) { emitModuleStaticDecl(mv); anyConst = true; }
                else if (!mv->isComptime) { emitModuleStaticDecl(mv, /*declOnly=*/true); anyConst = true; }
            }
    }
    if (anyConst) *_out << "\n";

    // Non-generic global-prelude free functions (e.g. `unwrapPtr`): the prelude is collect-only, so — like
    // its types/impl blocks below — no module emits their bodies. Emit prototype + definition `static inline`
    // in the header HERE (before the generic-fn/collection instances that call them), so a helper the
    // collections rely on (unwrap a fallible `Optional<UnsafePtr>` → panic-on-OOM) resolves everywhere. Generic
    // prelude free fns ride `emitGenericInst`; extern/signature-only ones carry no body.
    if (_preludeUnit && _preludeUnit->codeDeclarationList) {
        _nsCtx = _unitCtx[_preludeUnit.get()];
        // Say WHOSE code this is. Header content belongs to no module, so a diagnostic raised in one of
        // these bodies fell through diagFile()'s last rung to `_sourcePath` — the file being compiled —
        // and was stamped with the USER's path at the PRELUDE's line. Measured on 0.9.177: a 4-line
        // program, built with `--strict-numeric`, produced 26 rows naming that program and not one of
        // them at a line it has; the highest claimed line 531. `emitStruct` already installs this for the
        // same reason one layer up. See diagFile().
        ScopedStr _cu(_collectingUnitPath, _preludeUnit->name ? *_preludeUnit->name : std::string());
        _emitStaticInlineFn = true;
        for (auto& decl : *_preludeUnit->codeDeclarationList)
            if (auto* fn = dynamic_cast<FunctionDeclarationNode*>(decl.get())) {
                if (isExtern(fn) || !fn->block) continue;
                if (fn->typeParams && !fn->typeParams->empty()) continue;   // template — instantiated below
                emitFunctionPrototype(fn);
            }
        for (auto& decl : *_preludeUnit->codeDeclarationList)
            if (auto* fn = dynamic_cast<FunctionDeclarationNode*>(decl.get())) {
                if (isExtern(fn) || !fn->block) continue;
                if (fn->typeParams && !fn->typeParams->empty()) continue;
                emitFunction(fn);
            }
        _emitStaticInlineFn = false;
        *_out << "\n";
    }

    // 6b-2: type-associated `comptime` constants (`Type::NAME`) — one `static const` global each, emitted
    // once in the header before any body reads them. A folded value bakes to a literal (no C init-order
    // dependency); a non-integer literal const falls back to its constant initializer.
    if (!_typeConsts.empty()) {
        for (auto& kv : _typeConsts) {
            TypeConstInfo& tc = kv.second;
            auto oc = _classes.find(tc.owner);
            // ...and this one is USER code emitted from the header pass, where `_sourcePath` is "" in a
            // multi-file build — so its rejection below named no file at all. See diagFile().
            ScopedStr _cu(_collectingUnitPath, oc != _classes.end() ? oc->second.declFile : std::string());
            if (oc != _classes.end()) scopeOf(oc->second.declFile, oc->second.scope, oc->second.usings, oc->second.symbolAliases);
            *_out << "static const " << cType(tc.type) << " " << tc.cName << " = ";
            if (tc.hasValue) *_out << tc.value;
            else if (tc.initializer && isConstInitExpr(tc.initializer.get())) *_out << emitExpression(tc.initializer);
            else { unsupported(("a `comptime` constant must be a compile-time constant (a literal, `sizeof`, "
                               "`alignof`, or const arithmetic) — `" + kv.first + "`").c_str(), tc.line); *_out << "{0}"; }
            *_out << ";\n";
        }
        *_out << "\n";
    }

    // A PRELUDE ENUM's `<Enum>__as_<C>` VTABLE, ahead of every generic instantiation below.
    // The vtables used to go out with the rest of the prelude-enum block further down, which is after the
    // generic bodies — and a generic instance that serializes boxes a `SerError` into `Owned<Error>`
    // through `&SerError__as_Error`, so it referenced a `static const` that C had not seen yet. It never
    // surfaced before `@generate` reached generic types, because a plain type's synth serde body is
    // emitted in its HOME MODULE, long after this header.
    //
    // Only the vtables move: they reference method PROTOTYPES, which went out much earlier, so they have
    // nothing to wait for. The member bodies and the enum's own synth serde stay where they were, below
    // the prelude class bodies they may call into.
    if (_preludeUnit) {
        _emitStaticClass = true;
        for (const std::string& name : _preludeEnums) {
            auto it = _classes.find(name);
            if (it == _classes.end() || !(it->second.isVariant || it->second.isScalarEnum())) continue;
            ClassInfo& eci = it->second;
            scopeOf(eci.declFile, eci.scope, eci.usings, eci.symbolAliases);
            ScopedStr _cu(_collectingUnitPath, eci.declFile);
            emitClassInterfaceVtables(eci);
        }
        _emitStaticClass = false;
    }

    // generic-function instantiations — one `static` C function per (template, type-args),
    // in the header so every module can call them (like the collection macros). Forward-declare
    // all, then define, so a generic that calls another (or recurses) resolves.
    if (!_genericInsts.empty()) {
        for (auto& kv : _genericInsts) emitGenericInst(kv.second, /*prototypeOnly=*/true);
        *_out << "\n";
        for (auto& kv : _genericInsts) emitGenericInst(kv.second, /*prototypeOnly=*/false);
    }

    // specialized generic-type instance BODIES (ctor/method/dtor), `static`, in the header.
    for (const std::string& m : _genericTypeInstOrder)
        emitGenericTypeInst(_genericTypeInsts[m], /*phase=*/2);

    // Non-generic prelude types (e.g. Chars): the prelude is collect-only, so no module emits their
    // bodies — emit prototype + definition static-inline here (struct went out above with the others).
    for (auto& kv : _classes) {
        if (!kv.second.preludeStatic || kv.second.methods.empty()) continue;
        // A prelude ENUM with members is `preludeStatic` too — for the PROTOTYPE linkage, which must match its
        // static-inline bodies — but its definitions are class-shaped here (ctors, fields, a vtbl loop) and
        // an enum has none of that. The dedicated block just below emits its bodies instead.
        if (kv.second.isVariant || kv.second.isScalarEnum()) continue;
        scopeOf(kv.second.declFile, kv.second.scope, kv.second.usings, kv.second.symbolAliases);
        ScopedStr _cu(_collectingUnitPath, kv.second.declFile);   // whose code this is — see diagFile()
        _emitStaticClass = true;
        emitClassPrototypes(kv.second);
        emitClassDefinitions(kv.second);
        _emitStaticClass = false;
    }

    // A PRELUDE ENUM with members (e.g. `DeError implements Error`) has no home module, so — like the prelude
    // types/impl blocks — emit its `<Enum>__as_C` vtbl (+ dtor / synth serde) `static inline` in the header
    // (the module-content enum pass only covers user units; its `extern` decl is skipped above). Placed
    // BEFORE the impl bodies below, which reference the vtbl when boxing an error into `Owned<Error>`.
    if (_preludeUnit) {
        _emitStaticClass = true;
        for (const std::string& name : _preludeEnums) {
            auto it = _classes.find(name);
            if (it == _classes.end() || !(it->second.isVariant || it->second.isScalarEnum())) continue;   // only an enum with members reaches _classes
            ClassInfo& eci = it->second;
            scopeOf(eci.declFile, eci.scope, eci.usings, eci.symbolAliases);
            ScopedStr _cu(_collectingUnitPath, eci.declFile);   // whose code this is — see diagFile()
            if (eci.destructible) emitDtorDefinition(eci);
            // (its vtables went out ahead of the generic instantiations above — see there for why)
            emitEnumMemberBodies(eci, eci.enumNode);   // a prelude `type enum`'s own methods
            emitVariantSynthBodies(eci);               // whatever `@generate` synthesized for it
            if (eci.isGraphNode) { emitGraphNodeHelpers(eci); emitGraphReadInto(eci); }
        }
        _emitStaticClass = false;
    }

    // Prelude impl BODIES (e.g. `type intrinsic <int32> implements Hashable`): the prelude is collect-only,
    // so — like the prelude types above — emit their method bodies `static inline` in the header (prototype
    // already emitted above). This makes the primitive conformances UNIVERSAL: a `<T: Equatable>` bound,
    // `List<int32>.contains`, or an int-keyed `Map` resolves without importing `std::collections`.
    if (_preludeUnit && _preludeUnit->codeDeclarationList) {
        _nsCtx = _unitCtx[_preludeUnit.get()];
        ScopedStr _cu(_collectingUnitPath, _preludeUnit->name ? *_preludeUnit->name : std::string());
        _emitStaticClass = true;
        for (auto& e : implEmitsOf(_preludeUnit)) {
            ScopedStr _ts(_thisType, e.target->name);
            for (auto& m : *e.members) {
                auto* md = dynamic_cast<ClassMethodDeclarationNode*>(m.get());
                if (!md || !md->name || !md->name->value) continue;
                std::string ret = cType(md->returnType) + placeRetSuffix(md->isRef, md->isConstRef);
                line(md->line);
                _returnIsPlace = md->isRef;
                _returnIsConstPlace = md->isConstRef;
                emitMethodOrCtorBody(implMethodCName(*e.target, *md->name->value), ret.c_str(),
                                     md->params, md->body, *e.target, md->isConst,
                                     modHas(md->modifiers, "static") || md->isCtor,   // a `ctor` is static (no `self`)
                                     modHas(md->modifiers, "unsafe"), md->name->value->c_str(), md->attributes);
                _returnIsPlace = false;
            }
        }
        _emitStaticClass = false;
    }
    _out = headerOut;
    *_out << _intrinsicVtblsHeaderText;
    *_out << headerBodies.str();
}

// This file's DEFINITIONS: its classes' vtable instances + interface vtables +
// method/ctor/dtor bodies, then its free-function bodies. Prototypes for anything
// referenced across files live in the shared header.
// MCU step 1: a module `static` initializer must be a C constant expression (deterministic reset-time init,
// no synthesized startup hook). Structural check — no const-eval engine exists. Allow literals, `sizeof`, and
// unary/binary/cast/logical combinations thereof; reject everything runtime (calls, `new`, `spawn`, refs,
// aggregates). An aggregate (InlineArray / value struct) is served by omitting the initializer (zero-init).
static bool isConstInitExpr(ExpressionNode* e)
{
    if (!e) return false;
    if (dynamic_cast<Int8Node*>(e)  || dynamic_cast<Int16Node*>(e)  || dynamic_cast<Int32Node*>(e)
     || dynamic_cast<Int64Node*>(e) || dynamic_cast<UInt8Node*>(e)  || dynamic_cast<UInt16Node*>(e)
     || dynamic_cast<UInt32Node*>(e)|| dynamic_cast<UInt64Node*>(e) || dynamic_cast<CharNode*>(e)
     || dynamic_cast<Float32Node*>(e)|| dynamic_cast<Float64Node*>(e)|| dynamic_cast<BooleanNode*>(e)
     || dynamic_cast<NullNode*>(e)  || dynamic_cast<SizeofNode*>(e))
        return true;
    if (auto* u = dynamic_cast<SimpleUnaryExpressionNode*>(e)) return isConstInitExpr(u->expression.get());
    if (auto* c = dynamic_cast<CastNode*>(e))                  return isConstInitExpr(c->unaryExpression.get());
    if (auto* b = dynamic_cast<BinaryExpressionNode*>(e))
        return isConstInitExpr(b->LHS.get()) && isConstInitExpr(b->RHS.get());
    if (auto* l = dynamic_cast<LogicalAndOrNode*>(e))
        return isConstInitExpr(l->LHS.get()) && isConstInitExpr(l->RHS.get());
    return false;
}

// MCU step 1: emit a module-level `static T name …`. Per-isolate by construction — the KAMA_ISOLATE_LOCAL
// macro (kama_runtime.h) is `_Thread_local` on native, empty on wasm/embedded. Value/UnsafePtr/InlineArray only;
// no RAII/move tracking (contrast the local-decl path).
//
// A MUTABLE static is DECLARED in the shared header (`declOnly`: `extern KAMA_ISOLATE_LOCAL T name;`) and
// DEFINED in its unit, with external linkage — the shape every non-generic function already has. It used
// to be C-`static` in its unit and nowhere else, which a body in that unit reaches by order alone; but a
// GENERIC type's bodies are emitted `static inline` in the header, ahead of every unit, so `~Box() {
// drops = drops + 1; }` passed `kama check` and failed clang with `use of undeclared identifier` while the
// non-generic twin built. In a multi-file program it was worse than order: a header-inline body in any
// OTHER unit could not reach a file-private symbol at all. Nothing is copied — one definition, in the
// declaring unit — so the rule against per-TU copies of mutable state (see emitHeaderContent) holds; the
// C name is already file-mangled (`_Fgds__drops`), so two files' private `drops` cannot collide. A
// `comptime` constant stays `static const` in its unit: an unexported one is folded to a literal
// wherever it is read, and an exported one is defined in the header (emitHeaderContent).
//
// The gates run in both passes; only the definition pass REPORTS, so a refused static is diagnosed once.
void CEmitter::emitModuleStaticDecl(ModuleVariableDeclaration* mv, bool declOnly)
{
    if (!mv || !mv->type || !mv->variables) return;
    if (declOnly && mv->isComptime) return;
    std::string ty = cType(mv->type);
    bool isPtr = isRawPtrName(mv->type);
    // `hardware` (MMIO/ISR) is valid on a scalar value (`volatile T`) or an `UnsafePtr<T>` handle (`volatile T*`).
    // An InlineArray/collection static with `hardware` has murky element-volatility — reject it in v1.
    if (mv->isHardware && !isPtr && _classes.count(ty) && _classes[ty].isIntrinsicColl) {
        if (!declOnly)
            unsupported("`hardware` applies only to a scalar value or an `UnsafePtr<T>` static (an MMIO register or ISR flag)",
                        mv->line);
        return;
    }
    std::string hw = mv->isHardware ? "volatile " : "";
    // Type gate: value / UnsafePtr / InlineArray / Simd only. Reject anything that owns memory or needs
    // teardown (v1 has no static-dtor seam). `InlineArray`/`FixedArray` are `isIntrinsicColl` but own no
    // heap (collKind Fixed, a value array), and a `Simd<T,N>` owns even less — it is a `vector_size`
    // typedef over a primitive, so there is no struct, no element dtor and nothing to tear down. Allow
    // both; reject heap collections, smart pointers, destructible and move-only values.
    bool isValueArray = _classes.count(ty)
                     && (_classes[ty].collKind == CollKind::Fixed || isValueVectorKind(_classes[ty].collKind));
    if (!isPtr && !isValueArray && _classes.count(ty)
        && (_classes[ty].destructible || _classes[ty].isIntrinsicColl
            || isSmartPtrClass(ty) || isMoveOnlyValue(ty))) {
        // The message states the STANCE, not a promise: this used to end "(no destructible resources yet)",
        // which read as a queue entry. It is not one — a `static` is the MCU shape (per-isolate,
        // const-initialised, no teardown seam), and persistence of a resource is answered by ownership at the
        // foreign boundary instead: `Owned<T>` holds it, `release()` hands it to the host's userdata slot to
        // outlive a frame, `adopt` takes it back to destroy. GOALS §3a/§3e; the design for a destructible
        // static is kept in ROADMAP_DETAIL §2 should an isolate/MCU case ever pull it.
        if (!declOnly)
            unsupported(("a module `static` must be a value, UnsafePtr, `InlineArray` or `Simd` — `" + ty
                         + "` owns memory. A `static` is the MCU shape, not a home for a resource: persistence is "
                         "ownership, so keep it in an `Owned<" + ty + ">`, and `release()` it to a foreign API's "
                         "userdata slot when it must outlive a frame").c_str(), mv->line);
        return;
    }
    if (declOnly) {
        // The declaration carries no section attribute and no initializer — both belong to the one
        // definition, and C attaches an attribute given on any declaration to the object anyway.
        for (auto& d : *mv->variables)
            if (d && d->name && d->name->value)
                *_out << "extern KAMA_ISOLATE_LOCAL " << hw << ty << " " << qualify(*d->name->value) << ";\n";
        return;
    }
    // `@section(".x")` places the static in a named linker section (flash const table, DMA RAM bank,
    // ISR vector table). `@interrupt` on a static is rejected here (function-only).
    std::string secAttr = declAttrPrefix(mv->attributes, nullptr, mv->line);
    for (auto& d : *mv->variables) {
        if (!d || !d->name || !d->name->value) continue;
        std::string cname = qualify(*d->name->value);
        line(mv->line);
        // 6b-2: a `comptime NAME` is an immutable, compile-time-folded named constant. Emit plain
        // `static const` — NOT KAMA_ISOLATE_LOCAL: an immutable value is race-free to share across isolates,
        // so it needs no per-isolate copy. A mutable `static` keeps the isolate-local storage class, with
        // external linkage — its `extern` declaration went out in the header (see above).
        if (mv->isComptime)
            *_out << "static const " << secAttr << hw << ty << " " << cname;
        else
            *_out << secAttr << "KAMA_ISOLATE_LOCAL " << hw << ty << " " << cname;
        if (mv->isComptime) {
            if (!d->initializer) {
                unsupported(("a `comptime` constant must be initialized — `" + *d->name->value
                             + "`").c_str(), mv->line);
                *_out << " = {0}";
            } else {
                int64_t cv;
                auto ctv = _comptimeConstVals.find(cname);
                if (ctv != _comptimeConstVals.end())
                    *_out << " = " << ctRender(ctv->second);   // 6b-3: a `comptime fn`-computed scalar, baked
                else if (constValue(d->initializer, cv))
                    *_out << " = " << cv;   // baked literal: folds cross-const refs (`B = A + 1`) and sidesteps
                                            // C's "initializer element is not constant" for a const-referencing-const
                else if (isConstInitExpr(d->initializer.get()))
                    *_out << " = " << emitExpression(d->initializer);   // non-integer literal const (float/bool/char)
                else if (_ctErroredConsts.count(cname))
                    *_out << " = {0}";   // 6b-3: interpreter eval already reported a precise error — no duplicate
                else {
                    unsupported(("a `comptime` initializer must be a compile-time constant (a literal, an array "
                                 "literal, `sizeof`, const arithmetic, or a `comptime fn` call) — `" + *d->name->value + "`").c_str(), mv->line);
                    *_out << " = {0}";
                }
            }
        } else if (d->initializer) {
            if (!isConstInitExpr(d->initializer.get())) {
                unsupported(("a module `static` initializer must be a compile-time constant (a literal, "
                             "`sizeof`, or const arithmetic) — `" + *d->name->value
                             + "` has a runtime initializer; omit it to zero-init").c_str(), mv->line);
                *_out << " = {0}";
            } else {
                *_out << " = " << emitExpression(d->initializer);
            }
        } else {
            *_out << " = {0}";   // deterministic reset-time zero init
        }
        *_out << ";\n";
    }
}

void CEmitter::emitModuleContent(SharedCompilationUnit unit)
{
    _nsCtx = _unitCtx[unit.get()];   // resolve this file's body references in its scope
    // M3: attribute every body use-site recorded below to this unit. Outside a scope like this one
    // recordRef sees nullptr and drops the record — header/prelude type refs are covered by
    // buildPositions' own walk, and a generic instance sets its own (the TEMPLATE's unit; M6 B3).
    RefUnitScope refScope(this, unit.get());
    auto classOf = [&](ASTNode* d) -> ClassInfo* {
        auto* cd = dynamic_cast<ClassDeclarationNode*>(d);
        if (cd && cd->name && cd->name->value) {
            std::string mangled = qualify(*cd->name->value);
            if (_classes.count(mangled)) return &_classes[mangled];
            // An extern type keeps its literal key, and many files may declare it: its members' bodies are
            // emitted from the ONE declaration that carries them (the collect-time merge points `node` there).
            auto ext = _classes.find(*cd->name->value);
            if (ext != _classes.end() && ext->second.isExternStruct && ext->second.node == cd) return &ext->second;
        }
        return nullptr;
    };
    // Emit this module's bodies into a buffer so any `isolate` trampolines they generate can be flushed
    // to _out FIRST — a body takes the address of its trampoline, which C requires defined earlier in the TU.
    std::ostringstream moduleBody;
    std::ostream* savedModuleOut = _out; _out = &moduleBody;
    _intrinsicVtblsModule.clear();   // a module's intrinsic vtbls are its own `static`s (intrinsicContractVtbl)
    // MCU step 1: module-level `static`s into their own buffer — flushed to _out BEFORE bodies, since C
    // requires a file-scope definition to precede its use.
    std::ostringstream moduleStatics;
    {
        std::ostream* svd = _out; _out = &moduleStatics;
        for (auto& decl : *unit->codeDeclarationList)
            if (auto* mv = dynamic_cast<ModuleVariableDeclaration*>(decl.get()))
                if (!mv->isComptime || !moduleVarExported(mv)) emitModuleStaticDecl(mv);
                    // an EXPORTED `comptime` is defined in the shared header instead, so that other
                    // translation units can see it at all — see emitHeaderContent
        _out = svd;
    }
    // vtable instances + interface vtables first (referenced by ctor bodies).
#if KAMA_INHERITANCE
    for (auto& decl : *unit->codeDeclarationList)
        if (ClassInfo* ci = classOf(decl.get())) emitVtableInstance(*ci);
#endif

    for (auto& decl : *unit->codeDeclarationList)
        if (ClassInfo* ci = classOf(decl.get())) emitClassInterfaceVtables(*ci);
    // M7 `comptime assert` at module scope, and in the body of a NON-generic type. A generic type's are
    // checked per instantiation instead (emitGenericTypeInst), since that is where its const arguments are
    // bound. Neither emits runtime code — a false one is a diagnostic, a layout one a `_Static_assert`
    // queued into _fileScopeHelpers, which is flushed below before any body that could reference it.
    for (auto& decl : *unit->codeDeclarationList) {
        if (auto* ca = dynamic_cast<ComptimeAssertNode*>(decl.get())) { emitComptimeAssert(ca); continue; }
        auto* cd = dynamic_cast<ClassDeclarationNode*>(decl.get());
        if (cd && !(cd->typeParams && !cd->typeParams->empty())) {
            ScopedStr _ts(_thisType, qualify(cd->name && cd->name->value ? *cd->name->value : std::string()));
            emitComptimeAssertsIn(cd);
        }
    }
    // class definitions, then free-function definitions.
    for (auto& decl : *unit->codeDeclarationList)
        if (ClassInfo* ci = classOf(decl.get())) emitClassDefinitions(*ci);
    // Impl-block method BODIES for a collection/primitive target (`string` → `kama_string`): the
    // normal class machinery early-outs for a collection, so the body lands here, non-static (its prototype
    // is in the shared header). A user-type target already emitted through emitClassDefinitions above.
    for (auto& e : implEmitsOf(unit)) {
        ScopedStr _ts(_thisType, e.target->name);
        for (auto& m : *e.members) {
            auto* md = dynamic_cast<ClassMethodDeclarationNode*>(m.get());
            if (!md || !md->name || !md->name->value) continue;
            std::string ret = cType(md->returnType) + placeRetSuffix(md->isRef, md->isConstRef);
            line(md->line);
            _returnIsPlace = md->isRef;
            _returnIsConstPlace = md->isConstRef;
            emitMethodOrCtorBody(implMethodCName(*e.target, *md->name->value), ret.c_str(),
                                 md->params, md->body, *e.target, md->isConst,
                                 modHas(md->modifiers, "static") || md->isCtor,   // a `ctor` is static (no `self`)
                                 modHas(md->modifiers, "unsafe"), md->name->value->c_str(), md->attributes);
            _returnIsPlace = false;
        }
    }
    for (auto& decl : *unit->codeDeclarationList) {
        if (auto* fn = dynamic_cast<FunctionDeclarationNode*>(decl.get())) {
            if (fn->typeParams && !fn->typeParams->empty()) continue;   // template — instantiations live in the header
            if (fn->isComptime) continue;   // 6b-3: a comptime fn is compile-time-only — never emitted as C
            if (!isExtern(fn) && fn->block) emitFunction(fn);   // skip signature types (no body)
        } else if (dynamic_cast<ClassDeclarationNode*>(decl.get())) {
            // emitted above
        } else if (auto* ed = dynamic_cast<EnumDeclarationNode*>(decl.get())) {
            // a non-generic tagged union's dtor DEFINITION lives in its home module (its struct +
            // prototype are in the header). Generic-enum instances are emitted static-inline in the header.
            if (ed->identifier && ed->identifier->value) {
                auto it = _classes.find(enumKey(ed));
                if (it != _classes.end() && (it->second.isVariant || it->second.isScalarEnum())) {
                    ClassInfo& eci = it->second;
                    if (eci.destructible) emitDtorDefinition(eci);
                    // Model C: emit the `<Enum>__as_<C>` vtbl DEFINITION for any poly-dispatch contract the
                    // enum implements (classOf skips enums, so the class-vtbl loop above missed it). The
                    // header carries the matching `extern` decl. Enables dynamic dispatch + (P2) boxing.
                    emitClassInterfaceVtables(eci);
                    // The bodies of the methods this enum declares in its own body (`type enum E
                    // implements C { A, B; … }`). Same reason as the serde bodies below: classOf skips
                    // enums, so the per-class definition loop never reaches them.
                    emitEnumMemberBodies(eci, ed);
                    // The `@generate` bodies — bodies land in the home module (protos are in the header via
                    // emitClassPrototypes; classOf skips enums, so emit here alongside the dtor). The unit's
                    // scope is already active (_nsCtx = _unitCtx above), so payload types resolve.
                    emitVariantSynthBodies(eci);
                    // ...and a graph node's walk helpers, which emitClassDefinitions gives a type.
                    if (eci.isGraphNode) { emitGraphNodeHelpers(eci); emitGraphReadInto(eci); }
                }
            }
        } else if (dynamic_cast<IncludeNode*>(decl.get()) || dynamic_cast<ExternConstNode*>(decl.get())) {
            // FFI #include — emitted in the header by emitIncludes; an `extern const` emits nothing (the header
            // defines it; its size/kind check is emitExternLayoutChecks')
        } else if (dynamic_cast<IntrinsicImplNode*>(decl.get())) {
            // `type intrinsic <…> implements C { … }` — its methods were injected into each target's
            // conformance registry and their bodies emitted just above; nothing at this top-level site.
        } else if (dynamic_cast<ModuleVariableDeclaration*>(decl.get())) {
            // MCU step 1: module-level `static` — already emitted into `moduleStatics` (flushed before bodies).
        } else if (dynamic_cast<ComptimeAssertNode*>(decl.get())) {
            // M7: checked in the `comptime assert` loop above; it produces a diagnostic or a queued
            // `_Static_assert`, never a top-level definition.
        } else if (decl) {
            unsupported("top-level declaration", decl->line);
            *_out << "\n";
        }
    }
    // Restore the real stream, emit any `isolate` trampolines this module produced (they must precede the
    // bodies that reference them), then the buffered bodies.
    _out = savedModuleOut;
    *_out << moduleStatics.str();   // file-scope statics precede the bodies that reference them
    for (auto& h : _fileScopeHelpers) *_out << h;
    _fileScopeHelpers.clear();
    _moduleHelperKeys.clear();   // every helper is `static`: the next module's TU needs its own definitions
    *_out << moduleBody.str();
}

// FFI: emit a C `#include` per `extern "<header>";` directive, deduped.
void CEmitter::emitIncludes(const std::vector<SharedCompilationUnit>& units)
{
    std::set<std::string> seen;
    for (auto& u : units) {
        if (!u || !u->codeDeclarationList) continue;
        for (auto& decl : *u->codeDeclarationList)
            if (auto* inc = dynamic_cast<IncludeNode*>(decl.get())) {
                std::string h = inc->header ? *inc->header : "";
                if (h.empty()) continue;
                _externedHeaders.insert(h);   // record for the driver's link hints (e.g. <math.h> -> -lm)
                if (seen.count(h)) continue;
                seen.insert(h);
                if (h[0] == '<') *_out << "#include " << h << "\n";       // <stdlib.h>
                else             *_out << "#include \"" << h << "\"\n";    // "my.h"
            }
    }
    *_out << "\n";
}

// Single self-contained TU (transpile / single-file build): header content +
// module definitions in one stream.
int CEmitter::emit(SharedCompilationUnit unit)
{
    // Everything written from here on is the TU this build keeps — see EmitCapture. Restored on every return,
    // so `_out` never outlives the capture that wraps it.
    EmitCapture capture(*_out, _emittedC, _lines);
    std::ostream captured(&capture);
    std::ostream* const finalOut = _out;
    _out = &captured;
    struct RestoreOut { std::ostream*& o; std::ostream* v; ~RestoreOut() { o = v; } } _ro{ _out, finalOut };
    *_out << "/* Generated by kama. Do not edit. */\n";
    // A program with a `@onPanic` region defines KAMA_ONPANIC BEFORE the runtime header, which builds its
    // recovery path on that macro and includes `<setjmp.h>` itself. ⚠️ NOT here: a standard header read before
    // kama_runtime.h latches glibc's feature set ahead of its `_DEFAULT_SOURCE`, and kama_os.h then loses
    // `lstat`/`getaddrinfo` in the same translation unit — eleven errors naming kama's header (consumer KB-25).
    if (unit && unit->codeDeclarationList && unitsUseOnPanic({unit}))
        *_out << "#define KAMA_ONPANIC 1\n";
    if (unit && unit->codeDeclarationList && unitsDeclareGlobalAllocator({unit}))
        *_out << "#define KAMA_GLOBAL_ALLOCATOR 1\n";   // the funnel calls the declared pool — kama_runtime.h
    *_out << "#include \"kama_runtime.h\"\n";
    if (!unit || !unit->codeDeclarationList)
        return _unsupported;
    // collectProgram FIRST: it runs pruneInactiveDecls, and emitIncludes re-derives the `#include` set by
    // walking the decl list, so a `@compileFor`-gated `extern "<h>";` is only dropped if the prune has
    // already removed the node. This used to be the other way round, which made the gate a silent no-op on
    // exactly this path — `kama transpile` and every single-file build — while emitProgram (multi-file)
    // had it right. Nothing in collectProgram reads `_externedHeaders`, which is what emitIncludes
    // populates, so the swap is safe; the six `externsHeader(...)` call sites all run later still.
    collectProgram({unit});
    emitIncludes({unit});           // FFI #include directives
    _discoveryClosed = true;
    { ScopedFlag _hp(_inHeaderPass); emitHeaderContent({unit}); }
    emitModuleContent(unit);
    if (_sharedModule && !_funcs.count("kama_main")) emitRuntimeSlotDefinitions();   // no entry TU — see the definition
    checkUninstantiatedTemplates();   // LAST — see the header; both entry points call it, so check == build
    buildCallGraph();                 // every body is written: read the graph the three walks below share
    checkNoHeapTransitive();          // ...and this after it: the probe pass records nothing, but it must
                                      // not run against a half-built call graph either.
    checkGlobalAllocator();           // the declared pool's rules, and a pool reaching itself through the funnel
    checkForeignEntryStatics();       // the foreign-entry static-read walk, over the same finished call graph
    checkOnPanicRegions();            // ...and the `@onPanic` destructor-free walk, over the same graph
    checkSendableDeclarations();      // every `implements Sendable` verified over its fields (a lie is caught here)
    checkSpawnBundleSendability();    // ...and the bundle crossing requires one (an omission is caught here)
                                      // runs at collect time — a `spawn` lives in a BODY, so its facts
                                      // exist only once every body has been emitted.
    return _unsupported;
}

// Multi-file program: a guarded shared header of all declarations, then one .c of
// definitions per source file (each #include-ing the header).
int CEmitter::emitProgram(const std::vector<SharedCompilationUnit>& units,
                          const std::string& headerName, std::ostream& header,
                          const std::vector<std::ostream*>& moduleStreams,
                          const std::vector<std::string>& sourcePaths)
{
    collectProgram(units);

    // Every stream this build keeps is captured — see EmitCapture. Scoped to this call, like emit()'s.
    EmitCapture headerCapture(header, _emittedC, _lines);
    std::ostream capturedHeader(&headerCapture);
    std::vector<std::unique_ptr<EmitCapture>>  moduleCaptures;
    std::vector<std::unique_ptr<std::ostream>> capturedModules;
    for (std::ostream* m : moduleStreams) {
        moduleCaptures.emplace_back(new EmitCapture(*m, _emittedC, _lines));
        capturedModules.emplace_back(new std::ostream(moduleCaptures.back().get()));
    }

    std::string guard = "KAMA_GEN_";
    for (char c : headerName) guard += (isalnum((unsigned char)c) ? (char)toupper(c) : '_');

    _out = &capturedHeader;
    *_out << "/* Generated by kama. Do not edit. */\n";
    *_out << "#ifndef " << guard << "\n#define " << guard << "\n";
    if (unitsUseOnPanic(units))   // see emit(): program-wide, since every TU includes this header
        *_out << "#define KAMA_ONPANIC 1\n";   // a macro only — kama_runtime.h includes <setjmp.h> (KB-25)
    if (unitsDeclareGlobalAllocator(units))   // ...and the same for the funnel's implementation
        *_out << "#define KAMA_GLOBAL_ALLOCATOR 1\n";
    *_out << "#include \"kama_runtime.h\"\n";
    emitIncludes(units);        // FFI #include directives (before any type decls)
    // ...and the prelude's static-inline BODIES, which the comment here used to deny. They emitted 389
    // `#line` directives with an EMPTY file name, because the emitter is constructed with no path.
    _discoveryClosed = true;
    { ScopedFlag _hp(_inHeaderPass); emitHeaderContent(units); }
    *_out << "#endif /* " << guard << " */\n";

    for (size_t i = 0; i < units.size(); ++i) {
        _out = capturedModules[i].get();
        _sourcePath = sourcePaths[i];   // #line in this module points to its own source
        *_out << "/* Generated by kama. Do not edit. */\n";
        *_out << "#include \"" << headerName << "\"\n\n";
        emitModuleContent(units[i]);
        if (i == 0 && _sharedModule && !_funcs.count("kama_main")) emitRuntimeSlotDefinitions();   // no entry TU
    }
    checkUninstantiatedTemplates();   // LAST — see the header; both entry points call it, so check == build
    buildCallGraph();                 // every body is written: read the graph the three walks below share
    checkNoHeapTransitive();          // ...and this after it: the probe pass records nothing, but it must
                                      // not run against a half-built call graph either.
    checkGlobalAllocator();           // the declared pool's rules, and a pool reaching itself through the funnel
    checkForeignEntryStatics();       // the foreign-entry static-read walk, over the same finished call graph
    checkOnPanicRegions();            // ...and the `@onPanic` destructor-free walk, over the same graph
    checkSendableDeclarations();      // every `implements Sendable` verified over its fields (a lie is caught here)
    checkSpawnBundleSendability();    // ...and the bundle crossing requires one (an omission is caught here)
                                      // runs at collect time — a `spawn` lives in a BODY, so its facts
                                      // exist only once every body has been emitted.
    _out = moduleStreams.empty() ? &header : moduleStreams.back();   // the captures die with this call
    return _unsupported;
}
